/**
 * RMFOOD 应用根组件
 * 路由配置、认证守卫、QueryProvider
 *
 * 使用 react-router-dom v7 的 createBrowserRouter + RouterProvider
 *
 * 🔒 P3-1: lazyWithPreload 懒加载策略：
 * - 首屏关键页面（登录、仪表盘）同步加载
 * - 其他页面使用懒加载 + 空闲预加载
 * - 大体积模块（图表/导出）延迟加载
 */
import { createBrowserRouter, RouterProvider, Navigate } from 'react-router-dom';
