// 🔒 P3-1: 可预加载懒加载（空闲时预加载）
import { lazyWithPreload } from '@/components/LazyLoad.tsx';

// 🔒 P3-1: 关键页面直接导入，确保首屏加载速度
// 这些文件体积小，同步加载无影响首屏性能
