     （曾因 MainLayout 根容器在暗色下仍是浅底而出现 2.45:1 的「加载中…」）。 */
  <div className="flex items-center justify-center h-screen" style={{ backgroundColor: 'var(--bg-canvas)' }}>
    <div className="text-center">
      <div
        className="inline-block rounded-full h-8 w-8 border-t-2 border-b-2 animate-spin mb-4"
        style={{
          borderColor: 'var(--color-primary-600, var(--color-primary, var(--color-primary-400)))',
          borderTopColor: 'var(--color-primary, var(--color-primary-400))',
        }}
      ></div>
      <p className="text-neutral-600 dark:text-neutral-400">加载中...</p>
    </div>
  </div>
);

/**
 * 白名单申请页预加载：登录页挂载时提前加载该页面资源，
 * 用户点击「申请准入」跳转时无需等待网络加载。
 */
function WhitelistPreload() {
  useEffect(() => {
    WhitelistApplyPage.preload();
  }, []);
  return null;
}

/**
 * 根路径组件 — 未登录展示着陆页，已登录跳转仪表盘
 */
