  enableCache: import.meta.env?.VITE_ENABLE_CACHE !== 'false',
  cacheTTL: parseInt(import.meta.env?.VITE_CACHE_TTL || '300000', 10),
  maxRetries: parseInt(import.meta.env?.VITE_MAX_RETRIES || '3', 10),
