// ═══════════════════════════════════════════
// 2. 标准化响应类型
// ═══════════════════════════════════════════

/** 标准 API 响应结构 */
export interface ApiResponse<T = any> {
  /** 响应码 */
  code: number
  /** 响应消息 */
  message: string
  /** 响应数据 */
  data: T
  /** 时间戳 */
