  return response.data;
}

/**
 * 食品原料流式搜索 (SSE)
 * POST /databases/search/food-materials/stream
 */
export function searchFoodMaterialsStream(
  request: FoodMaterialSearchRequest,
  onEvent: (event: string, data: unknown) => void,
  onComplete?: () => void,
): EventSource | null {
  // SSE 使用 fetch + ReadableStream 实现
  const controller = new AbortController();

  fetch('/databases/search/food-materials/stream', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(request),
    signal: controller.signal,
  })
    .then(async (response) => {
      const reader = response.body?.getReader();
      if (!reader) return;

      const decoder = new TextDecoder();
      let buffer = '';

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\n');
        buffer = lines.pop() || '';

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            const eventData = line.slice(6);
            try {
              const data = JSON.parse(eventData);
              // 从 event 行获取事件类型
              onEvent('data', data);
            } catch {
              // 忽略非 JSON 行
            }
          }
        }
      }

      onComplete?.();
    })
    .catch((err) => {
      if (err.name !== 'AbortError') {
        logger.error('[FoodMaterialStream] SSE 错误:', err);
      }
    });

  return null; // 返回 controller 供取消使用
}

