/**
 * 文档预览组件 - 实时渲染Markdown内容，支持专业学术排版
 * 包含页码、页眉页脚系统
 */
import React, { useMemo, useState, useEffect } from 'react';
import { FileText, Eye, Printer } from 'lucide-react';
import type { ReportDocument } from '@/types/academicReport';
import { CitationService } from '@/services/citationService';

interface DocumentPreviewProps {
  document: ReportDocument | null;
}

export function DocumentPreview({ document }: DocumentPreviewProps) {
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);

  const service = useMemo(() => {
    return new CitationService(document?.citations || []);
  }, [document?.citations]);

  const references = useMemo(() => {
    if (!document) return [];
    return service.generateReferences(document.citationStyle);
  }, [document, service]);

  // 计算总页数
  useEffect(() => {
    if (!document) return;

    let pages = 0;

    // 封面
    pages += 1;

    // 摘要（中英文各占一页）
    if (document.abstractChinese || document.abstractEnglish) {
      pages += 1;
    }

    // 目录
    pages += 1;

    // 章节内容（每章至少一页）
    const contentChapters = document.chapters.filter(
      ch => ch.type !== 'cover' && ch.type !== 'abstract' && ch.type !== 'toc',
    );
    pages += contentChapters.length;

    // 参考文献
    if (references.length > 0) {
      pages += Math.ceil(references.length / 15); // 每页约15条参考文献
    }

    setTotalPages(pages);
  }, [document, references]);

  const handlePrint = () => {
    window.print();
  };

  if (!document) {
    return (
      <div className="h-full flex items-center justify-center bg-neutral-50 dark:bg-neutral-900">
        <div className="text-center text-neutral-500 dark:text-neutral-400">
          <FileText className="w-16 h-16 mx-auto mb-4 opacity-50" />
          <p>暂无文档</p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full bg-neutral-100 dark:bg-neutral-900">
      {/* 工具栏 */}
      <div className="flex items-center justify-between p-3 border-b border-neutral-200 dark:border-neutral-700 bg-neutral-50 dark:bg-neutral-800">
        <div className="flex items-center gap-2">
          <Eye className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
          <span className="text-sm font-medium text-neutral-700 dark:text-neutral-300">预览</span>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={handlePrint}
            className="flex items-center gap-1 px-3 py-1.5 text-sm bg-neutral-200 dark:bg-neutral-700 rounded-lg hover:bg-neutral-300 dark:hover:bg-neutral-600 transition-colors"
          >
