/**
 * 渲染Markdown内容为React组件
 */
function renderContent(content: string): React.ReactNode {
  if (!content.trim()) return null;

  const lines = content.split('\n');
  const elements: React.ReactNode[] = [];
  let currentParagraph: string[] = [];
  let inCodeBlock = false;
  let codeBlockContent: string[] = [];

  const flushParagraph = () => {
    if (currentParagraph.length > 0) {
      const text = currentParagraph.join('\n');
      elements.push(
        <p key={elements.length} className="text-neutral-700 dark:text-neutral-300 leading-relaxed mb-4 text-justify">
          {renderInlineFormatting(text)}
        </p>,
      );
      currentParagraph = [];
    }
  };

  const renderInlineFormatting = (text: string): React.ReactNode => {
    // 处理加粗
    const parts = text.split(/(\*\*[^*]+\*\*)/g);
    return parts.map((part, i) => {
      if (part.startsWith('**') && part.endsWith('**')) {
        return <strong key={i}>{part.slice(2, -2)}</strong>;
      }
      // 处理斜体
      const italicParts = part.split(/(_[^_]+_)/g);
      return italicParts.map((ip, j) => {
        if (ip.startsWith('_') && ip.endsWith('_')) {
          return <em key={`${i}-${j}`}>{ip.slice(1, -1)}</em>;
        }
        return ip;
      });
    });
  };

  lines.forEach((line, _index) => {
    // 代码块
    if (line.startsWith('```')) {
      if (inCodeBlock) {
        elements.push(
          <pre key={elements.length} className="bg-neutral-100 dark:bg-neutral-800 p-4 rounded-lg overflow-x-auto mb-4">
            <code className="text-sm text-neutral-800 dark:text-neutral-200 font-mono">
              {codeBlockContent.join('\n')}
            </code>
          </pre>,
        );
        codeBlockContent = [];
        inCodeBlock = false;
      } else {
        flushParagraph();
        inCodeBlock = true;
      }
      return;
    }

    if (inCodeBlock) {
      codeBlockContent.push(line);
      return;
    }

    // 标题
    if (line.startsWith('#### ')) {
      flushParagraph();
      elements.push(
        <h4 key={elements.length} className="text-base font-semibold text-neutral-900 dark:text-neutral-100 mt-6 mb-2">
          {line.slice(5)}
        </h4>,
      );
      return;
    }
    if (line.startsWith('### ')) {
      flushParagraph();
      elements.push(
        <h3 key={elements.length} className="text-lg font-semibold text-neutral-900 dark:text-neutral-100 mt-6 mb-2">
          {line.slice(4)}
        </h3>,
      );
      return;
    }
    if (line.startsWith('## ')) {
      flushParagraph();
      elements.push(
        <h2 key={elements.length} className="text-xl font-bold text-neutral-900 dark:text-neutral-100 mt-8 mb-3">
          {line.slice(3)}
        </h2>,
      );
      return;
    }
    if (line.startsWith('# ')) {
      flushParagraph();
      elements.push(
        <h1 key={elements.length} className="text-2xl font-bold text-neutral-900 dark:text-neutral-100 mt-10 mb-4">
          {line.slice(2)}
        </h1>,
      );
      return;
    }

    // 无序列表
    if (line.startsWith('- ')) {
      flushParagraph();
      const items = lines.filter(l => l.startsWith('- ')).map(l => l.slice(2));
      elements.push(
        <ul key={elements.length} className="list-disc list-inside space-y-1 mb-4 text-neutral-700 dark:text-neutral-300">
          {items.map((item, i) => <li key={i}>{renderInlineFormatting(item)}</li>)}
        </ul>,
      );
      return;
    }

    // 有序列表
    if (/^\d+\.\s/.exec(line)) {
      flushParagraph();
      const items = lines.filter(l => /^\d+\.\s/.exec(l)).map(l => l.replace(/^\d+\.\s/, ''));
      elements.push(
        <ol key={elements.length} className="list-decimal list-inside space-y-1 mb-4 text-neutral-700 dark:text-neutral-300">
          {items.map((item, i) => <li key={i}>{renderInlineFormatting(item)}</li>)}
        </ol>,
      );
      return;
    }

    // 引用
    if (line.startsWith('> ')) {
      flushParagraph();
      elements.push(
        <blockquote key={elements.length} className="border-l-4 border-secondary-500 pl-4 italic text-neutral-600 dark:text-neutral-400 my-4">
          {line.slice(2)}
        </blockquote>,
      );
      return;
    }

    // 表格
    if (line.includes('|') && line.trim().startsWith('|')) {
      flushParagraph();
      const tableLines = lines.filter(l => l.includes('|') && l.trim().startsWith('|'));
      if (tableLines.length > 0) {
        const headers = tableLines[0].split('|').map(h => h.trim()).filter(h => h);
        const bodyRows = tableLines.slice(2).map(row =>
          row.split('|').map(c => c.trim()).filter(c => c),
        );
        elements.push(
          <table key={elements.length} className="w-full border-collapse my-4">
            <thead>
              <tr className="bg-neutral-100 dark:bg-neutral-800">
                {headers.map((header, i) => (
                  <th key={i} className="border border-neutral-300 dark:border-neutral-600 px-4 py-2 text-left font-medium text-neutral-700 dark:text-neutral-300">
                    {header}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {bodyRows.map((row, i) => (
                <tr key={i} className="hover:bg-neutral-50 dark:hover:bg-neutral-800">
                  {row.map((cell, j) => (
                    <td key={j} className="border border-neutral-300 dark:border-neutral-600 px-4 py-2 text-neutral-700 dark:text-neutral-300">
                      {cell}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>,
        );
      }
      return;
    }

    // 普通段落
    if (line.trim()) {
      currentParagraph.push(line);
    } else if (currentParagraph.length > 0) {
      flushParagraph();
    }
  });

  flushParagraph();
  return elements;
}

import { useEffect, useState } from 'react';
import { useCollaborationStore } from '@/stores/collaborationStore';
import type { CollaborationRole } from '@/utils/rbac';
import {
  Users,
  Wifi,
  WifiOff,
  AlertTriangle,
  Check,
  RefreshCw,
  Edit3,
  Trash2,
  UserPlus,
  UserMinus,
  Settings,
  Download,
  Crown,
  Eye,
  EyeOff,
} from 'lucide-react';

interface ParticipantDisplay {
  userId: string;
  name: string;
  color: string;
  joinedAt: string;
  role: CollaborationRole;
  isOnline: boolean;
  isCurrentUser?: boolean;
}

interface PermissionBadgeProps {
  permission: string;
  hasPermission: boolean;
}

function PermissionBadge({ permission, hasPermission }: PermissionBadgeProps) {
  const icons: Record<string, typeof Edit3> = {
    canEdit: Edit3,
    canDelete: Trash2,
    canInvite: UserPlus,
    canRemove: UserMinus,
    canChangeRole: Settings,
    canExport: Download,
  };

  const labels: Record<string, string> = {
    canEdit: '编辑',
    canDelete: '删除',
    canInvite: '邀请',
    canRemove: '移除',
    canChangeRole: '改角色',
    canExport: '导出',
  };

  const Icon = icons[permission];
  const label = labels[permission];

  if (!Icon || !label) return null;

  return (
    <div
      className={`flex items-center gap-1 px-2 py-0.5 rounded text-xs ${
        hasPermission
          ? 'bg-success-100 text-success-700 dark:bg-success-300/25 dark:text-success-600'
          : 'bg-neutral-100 text-neutral-400 dark:bg-neutral-700 dark:text-neutral-400'
      }`}
    >
      <Icon size={12} />
      <span>{label}</span>
    </div>
  );
}

function RoleBadge({ role }: { role: CollaborationRole }) {
  const config: Record<CollaborationRole, { icon: typeof Crown; label: string; className: string }> = {
    owner: { icon: Crown, label: '所有者', className: 'bg-accent-100 text-accent-700 dark:bg-accent-300/25 dark:text-accent-700' },
    editor: { icon: Edit3, label: '编辑者', className: 'bg-secondary-100 text-secondary-700 dark:bg-secondary-300/25 dark:text-secondary-700' },
    reviewer: { icon: Eye, label: '审阅者', className: 'bg-warning-100 text-warning-700 dark:bg-warning-300/25 dark:text-warning-700' },
    viewer: { icon: EyeOff, label: '查看者', className: 'bg-neutral-100 text-neutral-600 dark:bg-neutral-700 dark:text-neutral-400' },
  };

  const { icon: Icon, label, className } = config[role];

  return (
    <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs font-medium ${className}`}>
      <Icon size={12} />
      {label}
    </span>
  );
}

function ConflictWarning({ conflicts, onResolve }: { conflicts: any[]; onResolve: (id: string, resolution: string) => void }) {
  if (conflicts.length === 0) return null;

  return (
    <div className="p-3 bg-warning-50 dark:bg-warning-300/20 border border-warning-200 dark:border-warning-800 rounded-lg">
      <div className="flex items-center gap-2 mb-2">
        <AlertTriangle className="w-4 h-4 text-warning-600" />
        <span className="text-sm font-medium text-warning-800 dark:text-warning-200">
          检测到 {conflicts.length} 个冲突
        </span>
      </div>
      <div className="space-y-2">
        {conflicts.slice(0, 3).map((conflict) => (
          <div key={conflict.id} className="text-xs bg-white dark:bg-warning-300/25 p-2 rounded">
            <div className="flex items-center justify-between">
              <span className="text-warning-700 dark:text-warning-700">
                冲突类型: {conflict.type}
              </span>
              <div className="flex gap-1">
                <button
                  onClick={() => onResolve(conflict.id, 'keep-local')}
                  className="px-2 py-0.5 bg-secondary-100 text-secondary-700 rounded hover:bg-secondary-200"
                >
                  保留本地
                </button>
                <button
                  onClick={() => onResolve(conflict.id, 'keep-remote')}
                  className="px-2 py-0.5 bg-success-100 text-success-700 rounded hover:bg-success-200"
                >
                  保留远程
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function SyncStatusIndicator({ status }: { status: { isSyncing: boolean; hasConflict: boolean; pendingOperations: number; lastSyncedAt: Date | null } }) {
  return (
    <div className="flex items-center gap-2 text-xs">
      {status.isSyncing ? (
        <div className="flex items-center gap-1 text-secondary-600">
          <RefreshCw className="w-3 h-3 animate-spin" />
          <span>同步中...</span>
        </div>
      ) : status.hasConflict ? (
        <div className="flex items-center gap-1 text-warning-600">
          <AlertTriangle className="w-3 h-3" />
          <span>存在冲突</span>
        </div>
      ) : status.pendingOperations > 0 ? (
        <div className="flex items-center gap-1 text-warning-600">
          <RefreshCw className="w-3 h-3" />
          <span>{status.pendingOperations} 个待同步</span>
        </div>
      ) : (
        <div className="flex items-center gap-1 text-success-600">
          <Check className="w-3 h-3" />
          <span>
            {status.lastSyncedAt
              ? `已同步 ${new Date(status.lastSyncedAt).toLocaleTimeString()}`
              : '已同步'}
          </span>
        </div>
      )}
    </div>
  );
}

export function CollaborationPanel() {
  const {
    session,
    participants,
    isConnected,
    isConnecting,
    connect,
    disconnect,
    getActiveParticipants,
    syncStatus,
    conflicts,
    resolveConflict,
    getCurrentUserRole,
    getCurrentUserPermissions,
  } = useCollaborationStore();

  const [activeUsers, setActiveUsers] = useState<ParticipantDisplay[]>([]);
  const [showPermissions, setShowPermissions] = useState(false);

  const currentRole = getCurrentUserRole();
  const currentPermissions = getCurrentUserPermissions();

  useEffect(() => {
    const active = getActiveParticipants();
    setActiveUsers(active.map(p => ({
      userId: p.user.id,
      name: p.user.name,
      color: p.user.id === 'user-1' ? '#FF3B30' : 'var(--color-secondary-500)',
      joinedAt: typeof p.joinedAt === 'string' ? p.joinedAt : p.joinedAt.toISOString(),
      role: p.role,
      isOnline: p.isOnline ?? true,
    })));
  }, [participants, getActiveParticipants]);

  const handleConnect = async () => {
    await connect('current-document');
  };

  const handleResolveConflict = (conflictId: string, resolution: string) => {
    resolveConflict(conflictId, resolution as 'keep-local' | 'keep-remote' | 'merge' | 'manual');
  };

  const pendingConflicts = conflicts.filter(c => c.status === 'pending');

  return (
    <div className="border rounded-lg p-4 bg-white dark:bg-neutral-800">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <Users className="w-5 h-5 text-primary-500" />
          <h3 className="font-semibold">实时协作</h3>
        </div>
        {isConnecting ? (
          <span className="px-2 py-1 text-xs bg-secondary-100 text-secondary-700 rounded-full dark:bg-secondary-300/25 dark:text-secondary-700">连接中...</span>
        ) : isConnected ? (
          <span className="px-2 py-1 text-xs bg-success-100 text-success-700 rounded-full dark:bg-success-300/25 dark:text-success-600">已连接</span>
        ) : (
          <span className="px-2 py-1 text-xs bg-neutral-100 text-neutral-700 rounded-full dark:bg-neutral-700 dark:text-neutral-300">未连接</span>
        )}
