      <div className="mt-4 space-y-4">
        <div className="space-y-1.5">
          <label className="text-sm font-semibold text-[var(--text-secondary)] block">模型类型</label>
          <Select value={modelType} onChange={(v) => onModelChange(v as ModelType)}>
