                  <Slider
                    value={params[key as keyof typeof params] as number}
                    min={min} max={max} step={step}
                    onChange={(value) => handleParamChange(key, value)}
                    className="w-full"
                  />
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </Card>
  )
}

