                  <Badge key={tag} variant="info" size="sm">
                    <Tag size={10} className="mr-0.5" />
                    {tag}
                  </Badge>
                ))}
                {template.tags.length > 3 && (
                  <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">+{template.tags.length - 3}</span>
                )}
              </div>
            )}

