/**
 * Bot 对话服务（DS Bot 移植）
 *
 * 复用后端成熟对话链路：POST /ai/chat 与 /ai/chat/stream（SSE），
 * 请求体携带 bot_id，后端以 Bot 的人设+记忆+模型覆盖应答（评审 M2/R7）。
 */
import api from '@/api/client';
import { envConfig } from '@/config/env';

export interface BotChatResponse {
  content: string;
  role?: string;
  model?: string | null;
  formulas?: unknown[];
  thinking_steps?: Array<{ step: string; content: string; status: string; detail?: string }>;
  success?: boolean;
}

export interface BotChatHistoryItem {
  role: string;
  content: string;
}

export interface BotChatStreamHandlers {
  onMeta?: (model: string) => void;
  onContent: (chunk: string) => void;
  onDone: () => void;
  onError: (error: Error) => void;
}

/** 非流式 Bot 对话 */
export async function botChat(
  botId: number,
  question: string,
  history: BotChatHistoryItem[] = [],
): Promise<BotChatResponse> {
  const res = await api.post<BotChatResponse>('/ai/chat', {
    question,
    history,
    stream: false,
    bot_id: botId,
  });
  return res.data;
}

/** 流式 Bot 对话（SSE），返回 abort 函数 */
export function botChatStream(
  botId: number,
  question: string,
  history: BotChatHistoryItem[] = [],
  handlers: BotChatStreamHandlers,
): () => void {
  const controller = new AbortController();

  const request = async () => {
    try {
      const res = await fetch(`${envConfig.api.baseUrl}/ai/chat/stream`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          question,
          history,
          stream: true,
          bot_id: botId,
        }),
        credentials: 'include',
        signal: controller.signal,
      });
      if (!res.ok) {
        const text = await res.text().catch(() => '');
        throw new Error(`Bot 对话失败 (${res.status}): ${text.slice(0, 200)}`);
      }
      const reader = res.body?.getReader();
      if (!reader) throw new Error('无响应流');

      const decoder = new TextDecoder();
      let buffer = '';
      let accumulated = '';
      let currentEvent = '';

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\n');
        buffer = lines.pop() ?? '';

        for (const line of lines) {
          // SSE event 名与 data 分离：`event: meta` + `data: {...}`
          if (line.startsWith('event: ')) {
            currentEvent = line.slice(7).trim();
            continue;
          }
          if (!line.startsWith('data: ')) continue;
          const dataStr = line.slice(6).trim();
          if (!dataStr || dataStr === '[DONE]') continue;
          try {
            const parsed = JSON.parse(dataStr);
            if (currentEvent === 'meta' && parsed.model) {
              handlers.onMeta?.(parsed.model);
            } else if (currentEvent === 'content' && typeof parsed.content === 'string') {
              accumulated += parsed.content;
              handlers.onContent(parsed.content);
            }
          } catch {
            // 忽略无法解析的行
          }
        }
      }
      handlers.onDone();
    } catch (err) {
      if ((err as Error).name === 'AbortError') return;
      handlers.onError(err instanceof Error ? err : new Error(String(err)));
    }
  };

  void request();
  return () => controller.abort();
}

import { useMemo } from 'react'
import {
  LineChart, Line, BarChart, Bar, PieChart, Pie, Cell,
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
} from 'recharts'
import { CHART_TYPOGRAPHY } from '../../../utils/typography'
import { getChartThemeColors } from '../../../utils/chartTheme'
import { useIsDarkMode } from '@/theme'

export interface ChartComponentProps {
  type: 'line' | 'bar' | 'pie'
  data: any[]
  options: {
    title?: string
    xAxisKey?: string
    yAxisKey?: string
    valueKey?: string
    source?: string
  }
  theme?: 'light' | 'dark'
}

export function ChartComponent({ type, data, options }: ChartComponentProps) {
  // D-43 修复：原为 useMemo(..., []) 空依赖 —— getChartThemeColors() 读取 DOM 上的
  // 当前模式（.dark / data-mode），空依赖会使**切主题后图表颜色永不更新**。
  const isDark = useIsDarkMode()
  const colors = useMemo(() => getChartThemeColors(), [isDark])

  const tooltipStyle = {
    backgroundColor: colors.tooltipBg,
    border: `1px solid ${colors.tooltipBorder}`,
    borderRadius: '8px',
    color: colors.tooltipText,
    fontSize: CHART_TYPOGRAPHY.tooltipContent.fontSize + 'px',
  }

  const axisTickStyle = {
    fontSize: CHART_TYPOGRAPHY.axisLabel.fontSize,
    fill: colors.axis,
  }

  switch (type) {
    case 'line':
      return (
        <div className="my-4 p-4 bg-white dark:bg-neutral-800 rounded-lg border border-neutral-200 dark:border-neutral-700">
          <h4 className="text-sm font-medium mb-3">{options.title || '折线图'}</h4>
          <ResponsiveContainer width="100%" height={300}>
            <LineChart data={data}>
              <CartesianGrid strokeDasharray="3 3" stroke={colors.grid} />
              <XAxis dataKey={options.xAxisKey || 'name'} tick={axisTickStyle} />
              <YAxis tick={axisTickStyle} />
              <Tooltip contentStyle={tooltipStyle} />
              <Line type="monotone" dataKey={options.yAxisKey || 'value'} stroke={colors.line} strokeWidth={2} dot={{ r: 3, fill: colors.line }} />
            </LineChart>
          </ResponsiveContainer>
          {options.source && (
            <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-2 text-right">数据来源: {options.source}</p>
          )}
        </div>
      )
    case 'bar':
      return (
        <div className="my-4 p-4 bg-white dark:bg-neutral-800 rounded-lg border border-neutral-200 dark:border-neutral-700">
          <h4 className="text-sm font-medium mb-3">{options.title || '柱状图'}</h4>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={data}>
              <CartesianGrid strokeDasharray="3 3" stroke={colors.grid} />
              <XAxis dataKey={options.xAxisKey || 'name'} tick={axisTickStyle} />
              <YAxis tick={axisTickStyle} />
              <Tooltip contentStyle={tooltipStyle} />
              <Bar dataKey={options.yAxisKey || 'value'} fill={colors.bar} />
            </BarChart>
          </ResponsiveContainer>
          {options.source && (
            <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-2 text-right">数据来源: {options.source}</p>
          )}
        </div>
      )
    case 'pie':
      return (
        <div className="my-4 p-4 bg-white dark:bg-neutral-800 rounded-lg border border-neutral-200 dark:border-neutral-700">
          <h4 className="text-sm font-medium mb-3">{options.title || '饼图'}</h4>
          <ResponsiveContainer width="100%" height={300}>
            <PieChart>
              <Pie rootTabIndex={-1}
                data={data}
                cx="50%"
                cy="50%"
                labelLine={false}
                outerRadius={100}
                fill="#8884d8"
                dataKey={options.valueKey || 'value'}
                label={({ name, percent }) => `${name}: ${(percent * 100).toFixed(0)}%`}
              >
                {data.map((_entry: any, index: number) => (
                  <Cell key={`cell-${index}`} fill={colors.pie[index % colors.pie.length]} />
                ))}
              </Pie>
              <Tooltip contentStyle={tooltipStyle} />
            </PieChart>
          </ResponsiveContainer>
          {options.source && (
            <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-2 text-right">数据来源: {options.source}</p>
          )}
        </div>
      )
    default:
      return null
  }
}

import React, { useState, useCallback } from 'react';
import type {
  FieldEditorConfig,
} from '../../../types/editing.types';

interface BatchEditDialogProps {
  isOpen: boolean;
  columnLabel: string;
  config: FieldEditorConfig;
  selectedCount: number;
  onApply: (value: any) => void;
  onCancel: () => void;
}

const BatchEditDialog: React.FC<BatchEditDialogProps> = ({
  isOpen,
  columnLabel,
  config,
  selectedCount,
  onApply,
  onCancel,
}) => {
  const [value, setValue] = useState<any>('');
  const [previewData, setPreviewData] = useState<any[]>([]);

  const handleValueChange = useCallback((newValue: any) => {
    setValue(newValue);

    if (config.editorType === 'select' && config.options) {
      const option = config.options.find(opt => opt.value === newValue);
      setPreviewData([{
        field: columnLabel,
        newValue: option?.label || newValue,
        affectedRows: selectedCount,
      }]);
    } else {
      setPreviewData([{
        field: columnLabel,
        newValue,
        affectedRows: selectedCount,
      }]);
    }
  }, [columnLabel, config.editorType, config.options, selectedCount]);

  const handleApply = useCallback(() => {
    onApply(value);
    setValue('');
    setPreviewData([]);
  }, [value, onApply]);

  const handleCancel = useCallback(() => {
    onCancel();
    setValue('');
    setPreviewData([]);
  }, [onCancel]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50">
      <div className="bg-white dark:bg-neutral-900 rounded-lg shadow-xl w-full max-w-md mx-4">
        <div className="px-6 py-4 border-b border-neutral-200 dark:border-neutral-700">
          <h3 className="text-lg font-semibold text-neutral-900 dark:text-neutral-100">批量编辑</h3>
          <p className="mt-1 text-sm text-neutral-600">
            将修改 {selectedCount} 行数据的「{columnLabel}」字段
          </p>
        </div>

        <div className="px-6 py-4 space-y-4">
          <div>
            <label className="block text-sm font-medium text-neutral-700 mb-2">
              新值
            </label>
            {renderBatchInput(config, value, handleValueChange)}
          </div>

          {previewData.length > 0 && (
            <div className="p-3 bg-secondary-50 rounded-lg">
              <h4 className="text-sm font-medium text-secondary-800 mb-2">预览</h4>
              <div className="space-y-1">
                {previewData.map((preview, index) => (
                  <div key={index} className="flex justify-between text-sm">
                    <span className="text-secondary-700">{preview.field}</span>
                    <span className="font-medium text-secondary-900">{String(preview.newValue)}</span>
                  </div>
                ))}
              </div>
              <p className="mt-2 text-xs text-secondary-600">
                将影响 {selectedCount} 行数据
              </p>
            </div>
          )}
        </div>

        <div className="px-6 py-4 bg-neutral-50 dark:bg-neutral-800 rounded-b-lg flex justify-end space-x-3">
          <button
            onClick={handleCancel}
            className="px-4 py-2 text-sm font-medium text-neutral-700 bg-white dark:bg-neutral-800 border border-neutral-300 dark:border-neutral-700 rounded-md hover:bg-neutral-50 dark:bg-neutral-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-secondary-500"
          >
            取消
          </button>
          <button
            onClick={handleApply}
            disabled={!value && value !== false}
            className="px-4 py-2 text-sm font-medium text-secondary-main bg-secondary-container border border-transparent rounded-md hover:bg-secondary-container focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-secondary-500 disabled:bg-neutral-300 disabled:cursor-not-allowed"
          >
            应用更改
          </button>
        </div>
      </div>
    </div>
  );
};

function renderBatchInput(
  config: FieldEditorConfig,
  value: any,
  onChange: (value: any) => void,
): React.ReactNode {
  const baseClasses = "w-full px-3 py-2 border border-neutral-300 dark:border-neutral-700 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-secondary-500 focus:border-secondary-500";

  switch (config.editorType) {
    case 'select':
      return (
        <select
          value={value ?? ''}
          onChange={(e) => onChange(e.target.value)}
          className={`${baseClasses} bg-white dark:bg-neutral-900`}
        >
          <option value="">请选择...</option>
          {config.options?.map((option) => (
            <option key={option.value} value={option.value}>
              {option.label}
            </option>
          ))}
        </select>
      );

    case 'number':
      return (
        <input
          type="number"
          value={value ?? ''}
          onChange={(e) => onChange(e.target.value ? Number(e.target.value) : '')}
          className={baseClasses}
          step={config.step || 'any'}
          min={config.min}
          max={config.max}
          placeholder={`输入数字${config.min !== undefined ? ` (最小: ${config.min})` : ''}`}
        />
      );

    case 'date':
      return (
        <input
          type="date"
          value={value ? new Date(value).toISOString().split('T')[0] : ''}
          onChange={(e) => onChange(e.target.value)}
          className={baseClasses}
          aria-label={config.label}
        />
      );

    case 'toggle':
      return (
        <div className="flex items-center space-x-2">
          <input
            type="checkbox"
            checked={Boolean(value)}
            onChange={(e) => onChange(e.target.checked)}
            className="w-4 h-4 text-secondary-600 rounded focus:ring-2 focus:ring-secondary-500"
          />
          <span className="text-sm text-neutral-700">
            {value ? '是' : '否'}
          </span>
        </div>
      );

    case 'textarea':
      return (
        <textarea
          value={value ?? ''}
          onChange={(e) => onChange(e.target.value)}
          className={`${baseClasses} resize-none`}
          rows={3}
          placeholder={config.placeholder || '输入内容...'}
        />
      );

    default:
      return (
        <input
          type="text"
          value={value ?? ''}
          onChange={(e) => onChange(e.target.value)}
          className={baseClasses}
          placeholder={config.placeholder || '输入新值...'}
        />
      );
  }
}

