// ==================== 评分算法 ====================

const EFFICACY_TAG_WEIGHTS: Partial<Record<EfficacyTag, number>> = {
  '补气养血': 9,
  '抗氧化': 8.5,
  '降血压': 8,
  '降血糖': 8,
