      { range: '70-84', level: '良好', color: 'var(--color-secondary-500)' },
      { range: '55-69', level: '一般', color: '#D97706' },
      { range: '0-54', level: '需改进', color: '#FF3B30' },
    ],
    mechanism:
      '评估抗氧化保护、光热稳定性、货架期延长等物理化学稳定性指标。',
    optimizationTips: [
      '添加天然抗氧化剂（如维生素C/E、多酚类）',
      '优化包装材料和储存条件',
      '采用微胶囊化技术隔离敏感成分',
