    ));
  }, []);

  // 处理列顺序变更
  const handleOrderChange = useCallback((newColumns: ColumnConfig[]) => {
    setEditingColumns(newColumns);
  }, []);

  // 处理列宽调整
  const handleWidthChange = useCallback((key: string, width: number | null) => {
    setEditingColumns(prev => prev.map(col =>
      col.key === key ? { ...col, width } : col,
    ));
  }, []);

  // 全选/取消全选
  const handleSelectAll = useCallback((visible: boolean) => {
    setEditingColumns(prev => prev.map(col => ({ ...col, visible })));
  }, []);

  // 应用当前编辑结果到视图
  const handleApply = useCallback(() => {
    onViewChange({
      ...currentView,
      columns: editingColumns,
      updatedAt: Date.now(),
    });
  }, [currentView, editingColumns, onViewChange]);

  // 保存为新视图
  const handleSaveAsNew = useCallback(() => {
    if (!viewName.trim()) {
      toastError('请输入视图名称');
      return;
    }

    if (onSaveView) {
      onSaveView({
        id: `new-${Date.now()}`,
        name: viewName.trim(),
        description: viewDesc.trim() || undefined,
        columns: editingColumns,
        isDefault: false,
        createdAt: Date.now(),
      });

      setViewName('');
      setViewDesc('');
    }
  }, [viewName, viewDesc, editingColumns, onSaveView]);

  // 导出当前视图
  const handleExport = useCallback(() => {
    const data = {
      version: 1,
      exportTime: new Date().toISOString(),
      view: {
        name: currentView.name,
        columns: editingColumns,
      },
    };

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${currentView.name.replace(/\s+/g, '_')}_view.json`;
    a.click();
    URL.revokeObjectURL(url);
  }, [currentView.name, editingColumns]);

  // 重置为初始状态
  const handleReset = useCallback(() => {
    setEditingColumns(currentView.columns.map(col => ({ ...col })));
  }, [currentView]);

  // 统计信息
  const stats = useMemo(() => {
    const total = editingColumns.length;
    const visible = editingColumns.filter(c => c.visible).length;
    return { total, visible, hidden: total - visible };
  }, [editingColumns]);

  return (
    <div className={`bg-white dark:bg-neutral-800 rounded-lg shadow-lg border border-neutral-200 dark:border-neutral-700 ${className}`}>
      {/* 头部 */}
      <div className="flex items-center justify-between px-5 py-4 border-b border-neutral-200 dark:border-neutral-700">
        <h3 className="text-base font-semibold text-neutral-800 dark:text-neutral-200">
          📊 列视图管理
        </h3>

        <button
          onClick={() => {} /* 关闭由父组件处理 */}
          className="p-1.5 text-neutral-400 hover:text-neutral-600 hover:bg-neutral-100 dark:hover:bg-neutral-700 rounded-full transition-colors"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
          </svg>
        </button>
      </div>

      {/* 标签页切换 */}
      <div className="flex border-b border-neutral-200 dark:border-neutral-700 px-5">
        <button
          onClick={() => setActiveTab('edit')}
          className={`px-4 py-2.5 text-sm font-medium border-b-2 transition-colors ${
            activeTab === 'edit'
              ? 'border-secondary-500 text-secondary-600 dark:text-secondary-700'
              : 'border-transparent text-neutral-500 hover:text-neutral-700 dark:hover:text-neutral-300'
          }`}
        >
          ✏️ 编辑视图
        </button>
        <button
          onClick={() => setActiveTab('saved')}
          className={`px-4 py-2.5 text-sm font-medium border-b-2 transition-colors relative ${
            activeTab === 'saved'
              ? 'border-secondary-500 text-secondary-600 dark:text-secondary-700'
              : 'border-transparent text-neutral-500 hover:text-neutral-700 dark:hover:text-neutral-300'
          }`}
        >
          💾 已保存 ({savedViews.length})
          {savedViews.length > 0 && (
            <span className="absolute -top-1 -right-2 w-4 h-4 bg-secondary-container text-secondary-main text-xs rounded-full flex items-center justify-center">
              {savedViews.length}
            </span>
          )}
        </button>
      </div>

      {/* 内容区域 */}
      <div className="p-5 max-h-[60vh] overflow-y-auto">
        {activeTab === 'edit' ? (
          /* ====== 编辑标签页 ====== */
          <div className="space-y-5">
            {/* 快速操作栏 */}
            <div className="flex items-center justify-between flex-wrap gap-2">
              <div className="flex items-center gap-2">
                <button
                  onClick={() => handleSelectAll(true)}
                  className="px-3 py-1.5 text-xs font-medium text-success-600 bg-success-50 hover:bg-success-100 rounded-md transition-colors"
                >
                  全部显示
                </button>
                <button
                  onClick={() => handleSelectAll(false)}
                  className="px-3 py-1.5 text-xs font-medium text-error-600 bg-error-50 hover:bg-error-100 rounded-md transition-colors"
                >
                  全部隐藏
                </button>
                <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                  显示 {stats.visible}/{stats.total} 列
                </span>
              </div>

              <button
                onClick={handleReset}
                className="px-3 py-1.5 text-xs font-medium text-neutral-600 bg-neutral-100 hover:bg-neutral-200 dark:bg-neutral-700 dark:hover:bg-neutral-600 rounded-md transition-colors"
              >
                ↺ 重置
              </button>
            </div>

            {/* 列可见性列表 */}
            <div className="space-y-1">
              {availableColumns.map(col => {
                const editingCol = editingColumns.find(c => c.key === col.key);
                const isVisible = editingCol?.visible ?? true;

                return (
                  <div
                    key={col.key}
                    className={`flex items-center gap-3 px-3 py-2.5 rounded-lg border transition-colors ${
                      isVisible
                        ? 'bg-secondary-50/30 dark:bg-secondary-300/15 border-secondary-200 dark:border-secondary-800'
                        : 'bg-neutral-50 dark:bg-neutral-750 border-neutral-200 dark:border-neutral-600 opacity-60'
                    }`}
                  >
                    {/* Checkbox */}
                    <input
                      type="checkbox"
                      checked={isVisible}
                      onChange={() => handleVisibilityToggle(col.key)}
                      className="w-4 h-4 text-secondary-600 rounded focus:ring-secondary-500"
                    />

                    {/* 列名 */}
                    <span className={`flex-1 text-sm font-medium ${
                      isVisible ? 'text-neutral-800 dark:text-neutral-200' : 'text-neutral-400 line-through'
                    }`}>
                      {col.label}
                    </span>

                    {/* 列宽输入 */}
                    <div className="flex items-center gap-1">
                      <input
                        type="number"
                        value={editingCol?.width || ''}
                        onChange={(e) => handleWidthChange(
                          col.key,
                          e.target.value ? parseInt(e.target.value) : null,
                        )}
                        placeholder="自动"
                        min={col.minWidth || 40}
                        max={col.maxWidth || 1000}
                        className="w-20 px-2 py-1 text-xs border border-neutral-300 dark:border-neutral-600 rounded bg-white dark:bg-neutral-700"
                      />
                      <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">px</span>
                    </div>
                  </div>
                );
              })}
            </div>

            {/* 拖拽排序预览区 */}
            <div className="mt-4 p-4 bg-neutral-50 dark:bg-neutral-750 rounded-lg border border-dashed border-neutral-300 dark:border-neutral-600">
              <div className="flex items-center justify-between mb-3">
                <span className="text-xs font-medium text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] uppercase tracking-wider">
                  列顺序 (拖拽调整)
                </span>
                <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                  提示：上下拖拽行来调整列的显示顺序
                </span>
              </div>

              <SortableList
                items={editingColumns.sort((a, b) => a.order - b.order)}
                onChange={handleOrderChange}
              />
            </div>

            {/* 保存新视图表单 */}
            <div className="pt-4 border-t border-neutral-200 dark:border-neutral-700">
              <div className="flex gap-3 mb-3">
                <input
                  type="text"
                  placeholder="新视图名称..."
                  value={viewName}
                  onChange={(e) => setViewName(e.target.value)}
                  className="flex-1 px-3 py-2 text-sm border border-neutral-300 dark:border-neutral-600 rounded-lg bg-white dark:bg-neutral-700 focus:ring-2 focus:ring-secondary-500"
                />
                <input
                  type="text"
                  placeholder="描述 (可选)"
                  value={viewDesc}
                  onChange={(e) => setViewDesc(e.target.value)}
                  className="flex-1 px-3 py-2 text-sm border border-neutral-300 dark:border-neutral-600 rounded-lg bg-white dark:bg-neutral-700"
                />
              </div>
            </div>
          </div>
        ) : (
          /* ====== 已保存标签页 ====== */
          <div className="space-y-2">
            {savedViews.length === 0 ? (
              <div className="text-center py-8 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                <svg className="w-12 h-12 mx-auto mb-2 opacity-50" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
                </svg>
                <p className="text-sm">暂无已保存的视图</p>
                <p className="text-xs mt-1">在"编辑视图"中配置并保存自定义视图</p>
              </div>
            ) : (
              savedViews.map(view => (
                <div
                  key={view.id}
                  className={`flex items-center justify-between p-3 rounded-lg border transition-colors group ${
                    view.id === currentView.id
                      ? 'bg-secondary-50 dark:bg-secondary-300/20 border-secondary-300 dark:border-secondary-700'
                      : 'bg-white dark:bg-neutral-750 border-neutral-200 dark:border-neutral-600 hover:border-neutral-300'
                  }`}
                >
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2">
                      <span className="font-medium text-sm text-neutral-800 dark:text-neutral-200 truncate">
                        📋 {view.name}
                      </span>

                      {view.isDefault && (
                        <span className="px-1.5 py-0.5 text-xs bg-warning-100 text-warning-700 dark:bg-warning-300/25 dark:text-warning-700 rounded">
                          默认
                        </span>
                      )}

                      {view.id === currentView.id && (
                        <span className="px-1.5 py-0.5 text-xs bg-success-100 text-success-700 dark:bg-success-300/25 dark:text-success-600 rounded">
                          当前
                        </span>
                      )}
                    </div>

                    {view.description && (
                      <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-0.5 truncate">{view.description}</p>
                    )}

                    <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">
                      {view.columns.filter(c => c.visible).length}/{view.columns.length} 列 ·
                      更新于 {new Date(view.updatedAt || view.createdAt).toLocaleDateString()}
                    </p>
                  </div>

                  <div className="flex items-center gap-1 ml-3">
                    <button
                      onClick={() => onViewChange(view)}
                      className="px-2.5 py-1.5 text-xs font-medium text-secondary-600 bg-secondary-50 hover:bg-secondary-100 dark:bg-secondary-300/20 dark:hover:bg-secondary-900/40 rounded-md transition-colors"
                    >
                      加载
                    </button>

                    {!view.isSystem && onSetAsDefault && (
                      <button
                        onClick={() => onSetAsDefault(view.id)}
                        className="px-2 py-1.5 text-xs text-neutral-600 hover:bg-neutral-100 dark:hover:bg-neutral-700 rounded-md transition-colors"
                        title="设为默认视图"
                      >
                        ⭐
                      </button>
                    )}

                    {!view.isSystem && onDeleteView && (
                      <button
                        onClick={() => onDeleteView(view.id)}
                        className="opacity-0 group-hover:opacity-100 p-1.5 text-neutral-400 hover:text-error-600 hover:bg-error-50 dark:hover:bg-error-900/20 rounded-md transition-all"
                        title="删除此视图"
                      >
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                        </svg>
                      </button>
                    )}
                  </div>
                </div>
              ))
            )}
          </div>
        )}
      </div>

      {/* 底部操作栏 */}
      <div className="flex items-center justify-end gap-3 px-5 py-4 bg-neutral-50 dark:bg-neutral-750/50 border-t border-neutral-200 dark:border-neutral-700 rounded-b-lg">
        <button
          onClick={handleExport}
          className="px-4 py-2 text-sm font-medium text-neutral-600 bg-white hover:bg-neutral-100 dark:bg-neutral-700 dark:hover:bg-neutral-600 border border-neutral-300 dark:border-neutral-600 rounded-lg transition-colors"
        >
          📤 导出JSON
        </button>

        <button
          onClick={handleApply}
          className="px-5 py-2 text-sm font-medium text-secondary-main bg-secondary-container hover:bg-secondary-container rounded-lg shadow-sm transition-colors"
        >
          ✓ 应用更改
        </button>

        {activeTab === 'edit' && viewName.trim() && (
          <button
            onClick={handleSaveAsNew}
            className="px-4 py-2 text-sm font-medium text-success-600 bg-success-50 hover:bg-success-100 dark:bg-success-300/20 dark:hover:bg-success-900/40 rounded-lg transition-colors"
          >
            💾 另存为新视图
          </button>
        )}
      </div>
    </div>
  );
}

export default ViewManager;

/**
 * ChatStateProvider - AI 对话状态容器 (ADR-029 P1-1)
 *
 * 所有业务逻辑在此初始化，通过 Context 提供给子组件。
 * ChatTab 组件只负责渲染布局，不包含任何状态逻辑。
 *
 * @version 1.0.0
 * @created 2026-09-21
 */

import React, { useState, useEffect, useRef, useCallback, useMemo, ReactNode } from 'react'
import { useQuery } from '@tanstack/react-query'
import { ModelClient } from '@/api/modelClient'
import { logger } from '@/utils/safeLogger'
import { useScenarioStore } from '@/stores/scenarioStore'

// ===== Hooks =====
import { useChatTabOrchestrator } from './hooks/useChatTabOrchestrator'
import { useChatSendMessage } from './hooks/useChatSendMessage'
import { useChatCallbacks } from './hooks/useChatCallbacks'
import { useRAGContext } from '@/hooks/useRAGContext'
import { useFormulaActions } from './hooks/useFormulaActions'
import { useMessageEditing } from './hooks/useMessageEditing'
import { useChatHandlers } from './hooks/useChatHandlers'
import { useChatMessages } from './hooks/useChatMessages'
import { useFormulaManager } from './hooks/useFormulaManager'
import { useReportGenerator } from './hooks/useReportGenerator'
import { useKeyboardShortcuts } from './hooks/useKeyboardShortcuts'

// ===== Services =====
import { sessionCapability } from './capabilities/session/SessionCapability'
import type { HistorySession } from './components/pro'
import type { BackendThinkingStep } from './hooks/useThinkingProcessV3'

// ===== Context =====
import { ChatStateContext } from './ChatStateContext'

interface ChatStateProviderProps {
  children: ReactNode
  onBatchExport?: (ids: string[], format: 'json' | 'csv' | 'excel' | 'pdf') => void
  onBatchDelete?: (ids: string[]) => void
  onBatchTag?: (ids: string[], tags: string[]) => void
  onSelectAll?: () => void
  onToggleSelect?: (id: string, sel?: boolean) => void
  onImport?: (data: unknown[]) => void
}

export function ChatStateProvider({ children, ...props }: ChatStateProviderProps) {
  // ===== 2. 核心消息状态 =====
  const chatMessages = useChatMessages()
  const {
    messages, input, setInput, isStreaming, setIsStreaming,
    chatError, setChatError, clearMessages, addMessage, updateMessage,
    retryLastMessage, clearError, isPaused, pauseStreaming, resumeStreaming,
    setActiveSessionId, checkCompaction,
  } = chatMessages

  // ===== 3. 引擎编排 =====
  const orchestrator = useChatTabOrchestrator()
  orchestrator.scenarioSwitcher.setAutoSwitch(false)

  // 后端 thinking_steps → 前端思维可视化同步
  const lastProcessedMsgCountRef = useRef(0)
  useEffect(() => {
    const currentCount = messages.length
    if (currentCount <= lastProcessedMsgCountRef.current) return
    lastProcessedMsgCountRef.current = currentCount
    const recentMsgs = messages.slice(-10)
    const lastAssistant = [...recentMsgs].reverse().find((m) => m.role === 'assistant' && !m.isLoading)
    if (lastAssistant) {
      const msg = lastAssistant as { role: string; content: string; isLoading?: boolean; thinking_steps?: BackendThinkingStep[] }
      if (msg.thinking_steps && Array.isArray(msg.thinking_steps) && msg.thinking_steps.length > 0) {
        orchestrator.thinkingProcessV3.loadExternalSteps(msg.thinking_steps, msg.content)
      }
    }
  }, [messages, orchestrator.thinkingProcessV3])

  // ===== 4. 模型状态 =====
  const { data: modelStatus } = useQuery({
    queryKey: ['ai-model-status'],
    queryFn: ModelClient.getModelStatus,
    refetchOnMount: true, gcTime: 0, staleTime: 0, retry: 1,
  })
  const llmAvailable = modelStatus?.llm?.status === 'active'
  const llmModel = modelStatus?.llm?.model ?? ''

  // ===== 5. 会话统计 =====
  const assistantCount = messages.filter(m => m.role === 'assistant').length
  const firstMsgTime = messages.length > 0 ? messages[0].timestamp : 0
  const [elapsedSeconds, setElapsedSeconds] = useState(0)
  useEffect(() => {
    if (messages.length === 0) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setElapsedSeconds(0); return
    }
    const timer = setInterval(() => setElapsedSeconds(Math.floor((Date.now() - firstMsgTime) / 1000)), 1000)
    return () => clearInterval(timer)
  }, [firstMsgTime, messages.length])

  // ===== 6. RAG 上下文 =====
  const rag = useRAGContext()

  // ===== 7. 场景模式 =====
  const scenarioMode = useScenarioStore(s => s.mode)

  // ===== 8. 消息发送 =====
  const chatHook = useChatSendMessage(chatMessages, {
    orchestrator, ragAugment: rag.augment, llmAvailable, scenarioMode,
  })

  // ===== 9. 导出管理 =====

  // ===== 10. 配方管理 =====
  const {
    formulas, formulaIndex, formulaCount, expandedIds, selectedIds,
    selectedForDetail, isDetailModalOpen, toggleExpand, selectFormula,
    selectAll, showDetailTable,
    closeDetailTable, importFormulas, exportFormulas: handleExportFormulas,
    clearAllFormulas,
  } = useFormulaManager()

  // ===== 11. 报告生成 =====
  const {
    handleGenerateReport, reportData, isGeneratingReport,
    showReportModal, setShowModal: setShowReportModal,
  } = useReportGenerator(formulaIndex)

  // ===== 12. 会话管理 =====
  const [historySessions, setHistorySessions] = useState<HistorySession[]>([])
  const [activeSessionId, setActiveSessionIdState] = useState<string | null>(null)
  const [historyVisible, setHistoryVisible] = useState(false)
  const initializedRef = useRef(false)

  useEffect(() => {
    if (initializedRef.current) return
    initializedRef.current = true
    sessionCapability.listSessions()
      .then(sessions => {
        const mapped: HistorySession[] = sessions.map(s => ({
          id: s.id, title: s.title, messageCount: s.messageCount, lastMessage: '', timestamp: s.updatedAt,
        }))
        setHistorySessions(mapped)
        if (mapped.length > 0) setActiveSessionIdState(mapped[0].id)
      })
      .catch(err => logger.warn('[ChatStateProvider] 加载会话列表失败:', err))
  }, [])

  // 同步会话 ID 到持久化层
  useEffect(() => {
    setActiveSessionId(activeSessionId)
  }, [activeSessionId, setActiveSessionId])

  const handleForkMessage = useCallback(async (messageId: string) => {
    if (!activeSessionId) return
    try {
      const childId = await sessionCapability.fork(activeSessionId, {
        boundaryMessageId: messageId,
        title: `分支 @${messageId.slice(-6)}`,
      })
      setActiveSessionIdState(childId)
      const refreshed = await sessionCapability.listSessions()
      setHistorySessions(refreshed.map(s => ({
        id: s.id, title: s.title, messageCount: s.messageCount, lastMessage: '', timestamp: s.updatedAt,
      })))
      logger.info(`[ChatStateProvider] 已分支至新会话: ${childId}`)
    } catch (e) {
      logger.error('[ChatStateProvider] 分支失败:', e)
    }
  }, [activeSessionId])

  // ===== 15. 附件管理 =====
  const [attachments, setAttachments] = useState<Array<{ id: string; file: File; previewUrl: string }>>([])
  const handleAddAttachment = useCallback((file: File) => {
    const id = `att-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`
    const previewUrl = URL.createObjectURL(file)
    setAttachments(prev => [...prev, { id, file, previewUrl }])
  }, [])
  const handleRemoveAttachment = useCallback((id: string) => {
    setAttachments(prev => prev.filter(a => a.id !== id))
  }, [])

  // ===== 16. Details 面板 =====
  const [detailsCall] = useState<{ id: string; name: string; args: Record<string, unknown>; result?: string; status: 'running' | 'completed' | 'error'; durationMs?: number } | null>(null)
  const [detailsOpen] = useState(false)
  const [showKBPanel] = useState(false)

  // ===== 17. 回调管理 =====
  const callbacks = useChatCallbacks({
    historySessions, setHistorySessions, setActiveSessionId: setActiveSessionIdState,
    historyVisible, setHistoryVisible, clearMessages, clearAllFormulas,
    clearWorkingMemory: () => {},
    clearMultiTurnDialogue: orchestrator.multiTurnDialogue.clearDialogue,
    clearShortTermMemory: () => {},
    messages, setMessages: chatMessages.replaceMessages, activeSessionId,
  })

  // ===== 18. 键盘快捷键 =====
  useKeyboardShortcuts({ disabled: isStreaming })

  // ===== 19. 消息编辑 =====
  const messageEditing = useMessageEditing({
    messages, editMessage: chatMessages.editMessage,
    removeMessage: chatMessages.removeMessage,
    retractMessage: chatMessages.retractMessage,
    sendMessage: async (content: string) => {
      await chatHook.handleSendMessage(content)
      if (activeSessionId) {
        callbacks.updateSessionMetadata(activeSessionId, messages)
      }
    },
  })

  // ===== 20. UI 状态 =====
  const [showFormulaList, setShowFormulaList] = useState(false)
  const [searchQuery] = useState('')
  const [highlightedMessageId] = useState<string | null>(null)

  // ===== 21. 聊天处理器 =====
  const chatHandlers = useChatHandlers({
    input, isStreaming, activeSessionId, chatError, setChatError, clearError,
    retryLastMessage, handleSendMessage: chatHook.handleSendMessage,
    updateSessionMetadata: callbacks.updateSessionMetadata, messages,
    showReportModal, setShowReportModal,
    isDetailModalOpen, closeDetailTable,
    showFormulaList, setShowFormulaList,
    checkCompaction,
  })

  // ===== 22. 配方操作 =====
  const formulaActions = useFormulaActions({
    formulas, selectedIds, selectedForDetail, expandedIds, formulaCount,
    isDetailModalOpen,
    onToggleExpand: toggleExpand, onShowDetail: showDetailTable, onCloseDetail: closeDetailTable,
    onGenerateReport: handleGenerateReport, onExport: handleExportFormulas,
    onClearStorage: clearAllFormulas,
    onBatchExport: props.onBatchExport ?? (() => {}),
    onBatchDelete: props.onBatchDelete ?? (() => {}),
    onBatchTag: props.onBatchTag ?? (() => {}),
    onSelectAll: selectAll,
    onToggleSelect: (id, sel) => selectFormula(id, sel ?? false),
    onImport: importFormulas,
  })

  // ===== 23. 构建 Context Value =====
  const contextValue = useMemo<Parameters<typeof ChatStateContext.Provider>[0]['value']>(() => ({
    // 消息
    messages, input, setInput, isStreaming, setIsStreaming,
    chatError, setChatError, clearMessages, addMessage, updateMessage,
    retryLastMessage, clearError, isPaused, pauseStreaming, resumeStreaming,
    editMessage: messageEditing.handleEditMessage,
    retractMessage: messageEditing.handleRetractMessage,
    setActiveSessionId, checkCompaction,

    // 会话
    historySessions, setHistorySessions,
    activeSessionId, setActiveSessionIdCtx: setActiveSessionIdState,
    historyVisible, setHistoryVisible,

    // UI
    isDetailModalOpen, selectedForDetail,
    showFormulaList, searchQuery, highlightedMessageId,
    attachments, detailsCall, detailsOpen, showKBPanel,

    // 引擎
    llmAvailable, llmModel, scenarioMode,
    assistantCount, elapsedSeconds,

    // 配方
    formulaCount, expandedIds, selectedIds, formulas,

    // 报告
    showReportModal, setShowReportModal, reportData, isGeneratingReport,

    // 方法
    handleSendMessage: chatHook.handleSendMessage,
    handleNewSession: callbacks.handleNewSession,
    handleSelectSession: callbacks.handleSelectSession,
    handleDeleteSession: callbacks.handleDeleteSession,
    handleRenameSession: callbacks.handleRenameSession,
    handleClearChat: callbacks.handleClearChat,
    handleRetry: chatHandlers.handleRetry,
    handleSend: chatHandlers.handleSend,
    handleForkMessage,
    handleAddAttachment, handleRemoveAttachment,
    toggleHistory: callbacks.toggleHistory,
    syncSessionsFromServer: callbacks.syncSessionsFromServer,
    handleGenerateReport,
  }), [
    messages, input, isStreaming, chatError, assistantCount, elapsedSeconds,
    historySessions, activeSessionId, historyVisible,
    llmAvailable, llmModel, scenarioMode,
    formulaCount, expandedIds, selectedIds, formulas,
    showReportModal, setShowReportModal, reportData, isGeneratingReport,
    handleGenerateReport,
    showFormulaList, searchQuery, highlightedMessageId,
    attachments, detailsCall, detailsOpen, showKBPanel, isDetailModalOpen, selectedForDetail,
    chatHook, callbacks, chatHandlers, messageEditing, formulaActions,
    handleForkMessage, handleAddAttachment, handleRemoveAttachment,
    props,
  ])

  return (
    <ChatStateContext.Provider value={contextValue}>
      {children}
    </ChatStateContext.Provider>
  )
}

export default ChatStateProvider

/**
 * ChatTab - 智能对话布局组件 (v13.0 ADR-029)
 *
 * v13.0 重构 (2026-09-21):
 * ✅ 所有业务逻辑提取至 ChatStateProvider
 * ✅ 纯布局组件，无 useState/useEffect
 * ✅ 通过 useChatContext() 获取所有状态和方法
 *
 * 核心职责：
 * - 提供 ChatStateProvider 包裹所有子组件
 * - 渲染 JSX 布局结构
 * - 委托事件处理给 Context 提供的回调
 *
 * @version 13.0.0
 * @lastUpdated 2026-09-21
 */

import React from 'react'
import { useChatContext } from './ChatStateContext'
import { logger } from '@/utils/safeLogger'

// ===== Pro 组件 =====
import { ChatMessages, ChatInputPro, ChatHistory } from './components/pro'
import { TopBar, EmptyStateCard } from './components/pro'
import ComposerStatusBar from './components/pro/ComposerStatusBar'
import DetailsPanel from './components/pro/DetailsPanel'
import FollowUpSuggestionsBar from './components/pro/FollowUpSuggestionsBar'
import type { DraftAttachment } from './components/pro/ChatInput'

// ===== 视觉设计系统 =====
import { scenarioSwitcher } from './services/scenarioSwitcher'
import { sessionCapability } from './capabilities/session/SessionCapability'

// ===== UI 组件 =====
import { Button } from '@/components/ui'

// ===== 专业内容组件 =====
import { ProfessionalReport as ProfessionalReportModal, type ProfessionalReportProps as ProfessionalReportModalProps } from '@/components/ai/components/ProfessionalReport'

// ===== 新功能组件 =====
import { UserProfileSettingsPanel } from './components/UserProfileSettingsPanel'
import { FormulaShareModal } from './components/FormulaShareModal'
import { ChatSearchOverlay } from './components/ChatSearchOverlay'
import { detectStructuredContent } from './components/structured/utils'
import * as formulaExtractorService from './services/formulaExtractorService'
import { createFormula } from '@/api/formula'
import { FormulaStatus } from '@/types'
import type { FormulaCreatePayload } from '@/types/formula'

// ===== 图标库 =====
import { AlertTriangle, Pause, Leaf } from 'lucide-react'

// ===== 配置 =====
import { QUICK_QUESTIONS } from '@/config/ai'

// ===== RAG / UI =====
import { RAGKnowledgePanel } from './components/RAGKnowledgePanel'

interface ChatTabProps {
  onBatchExport?: (ids: string[], format: 'json' | 'csv' | 'excel' | 'pdf') => void
  onBatchDelete?: (ids: string[]) => void
  onBatchTag?: (ids: string[], tags: string[]) => void
  onSelectAll?: () => void
  onToggleSelect?: (id: string, sel?: boolean) => void
  onImport?: (data: unknown[]) => void
}

/**
 * ChatTab - 纯布局组装组件 (v13.0)
 * 所有业务逻辑已提取至 ChatStateProvider
 */
// eslint-disable-next-line @typescript-eslint/no-unused-vars -- 兼容既有 Props 契约，当前实现未使用这些 props
export function ChatTab(_props: ChatTabProps) {
  // ===== 从 Context 获取所有状态 =====
  const ctx = useChatContext()
  const {
    // 消息
    messages, input, setInput, isStreaming,
    chatError, clearError, pauseStreaming,
    editMessage, retractMessage,
    // 会话
    historySessions, activeSessionId, historyVisible,
    // UI
    highlightedMessageId,
    attachments, detailsCall, detailsOpen, showKBPanel,
    // 引擎
    llmAvailable, llmModel, scenarioMode,
    assistantCount, elapsedSeconds,
    // 配方
    formulaCount,
    // 报告
    showReportModal, setShowReportModal, reportData, isGeneratingReport,
    // 方法
    handleNewSession, handleSelectSession, handleDeleteSession,
    handleRenameSession, handleClearChat, handleRetry, handleSend, handleForkMessage,
    handleGenerateReport,
    handleAddAttachment, handleRemoveAttachment, toggleHistory,
  } = ctx

  // ===== 本地 UI 状态 =====
  const [detailsCallLocal, setDetailsCall] = React.useState<typeof detailsCall>(null)
  const [detailsOpenLocal, setDetailsOpen] = React.useState(false)
  const [showKBPanelLocal, setShowKBPanelLocal] = React.useState(false)

  // ===== 新功能：设置/分享/搜索 =====
  const [showUserProfileSettings, setShowUserProfileSettings] = React.useState(false)
  const [shareModalContent, setShareModalContent] = React.useState<{ messageId: string; content: string } | null>(null)
  const [searchOpen, setSearchOpen] = React.useState(false)
  // 轻量提示条：后端未提供端点的按钮点下去必须给出明确反馈，不能静默无响应
  const [notice, setNotice] = React.useState<{ kind: 'success' | 'warning' | 'error'; text: string } | null>(null)
  const noticeTimer = React.useRef<ReturnType<typeof setTimeout> | null>(null)
  const showNotice = React.useCallback((kind: 'success' | 'warning' | 'error', text: string) => {
    setNotice({ kind, text })
    if (noticeTimer.current) clearTimeout(noticeTimer.current)
    noticeTimer.current = setTimeout(() => setNotice(null), 4000)
  }, [])
  React.useEffect(() => () => { if (noticeTimer.current) clearTimeout(noticeTimer.current) }, [])

  // ── 同步 Context 状态到本地（用于回调）──
  React.useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- 镜像 Context 状态到本地，保持现有同步逻辑不变
    if (detailsCall !== detailsCallLocal) setDetailsCall(detailsCall)
  }, [detailsCall])
  React.useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- 镜像 Context 状态到本地，保持现有同步逻辑不变
    if (detailsOpen !== detailsOpenLocal) setDetailsOpen(detailsOpen)
  }, [detailsOpen])
  React.useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- 镜像 Context 状态到本地，保持现有同步逻辑不变
    if (showKBPanel !== showKBPanelLocal) setShowKBPanelLocal(showKBPanel)
  }, [showKBPanel])

  // ── 从结构化内容提取配方并真正保存到后端 /formulas ──
  // 此前只生成本地 id 就弹"✓ 配方已保存到配方库"，实际没有落库。
  const handleStructureSave = React.useCallback(async (messageId: string, content: string) => {
    const structured = detectStructuredContent(content)
    if (!structured) {
      logger.warn('[ChatTab] 消息内容不是结构化格式，无法保存:', messageId)
      showNotice('warning', '该消息不是结构化配方，无法保存')
      return
    }
    const extracted = formulaExtractorService.extractFormulaFromContent(structured)
    if (!extracted) {
      logger.warn('[ChatTab] 未能从结构化内容中提取配方:', messageId)
      showNotice('warning', '未能从消息中提取到配方成分表')
      return
    }

    // 剂量字符串 -> 数值（"10g" / "10-15g" / "约15克"）。区间取上限。
    const parseDosage = (raw: string): number => {
      const range = /(\d+(?:\.\d+)?)\s*[-–~至]\s*(\d+(?:\.\d+)?)/.exec(raw)
      const val = range ? Number(range[2]) : Number((/^[\s约]*([\d.]+)/.exec(raw) || [0, '0'])[1])
      return Number.isFinite(val) ? val : 0
    }
    const totalAmount = extracted.ingredients.reduce((s, i) => s + parseDosage(i.dosage), 0)
    const ingredients = extracted.ingredients.map((i) => {
      const amount = parseDosage(i.dosage)
      return {
        name: i.name,
        amount,
        unit: /斤/.test(i.dosage) ? 'kg' : 'g',
        percentage: totalAmount > 0 ? Number(((amount / totalAmount) * 100).toFixed(2)) : 0,
        role: i.role,
      }
    })

    const payload: FormulaCreatePayload = {
      name: extracted.name,
      description: [extracted.description, extracted.rationale && `【配伍思路】${extracted.rationale}`]
        .filter(Boolean)
        .join('\n\n'),
      status: FormulaStatus.DRAFT,
      ingredients,
      effects: extracted.expectedEffects ?? [],
      target_effects: extracted.expectedEffects ?? [],
      dosage: extracted.dosageAdvice,
      processing_method: extracted.productionSteps?.length ? extracted.productionSteps.join('；') : undefined,
      notes: extracted.precautions?.length ? `【注意事项】${extracted.precautions.join('；')}` : undefined,
      composition: extracted.scores,
      version_notes: '由 AI 对话结构化内容导入',
    }

    try {
      const created = await createFormula(payload)
      showNotice('success', `配方「${created.name ?? extracted.name}」已保存到配方库`)
      logger.info('[ChatTab] 配方已保存到配方库:', {
        formulaId: created.id,
        name: created.name,
        ingredients: ingredients.length,
      })
    } catch (e) {
      logger.error('[ChatTab] 配方保存失败:', e)
      showNotice('error', '配方保存失败：' + (e instanceof Error ? e.message : '服务端未接受请求'))
    }
  }, [showNotice])

  const handleStructureShare = React.useCallback((messageId: string, content: string) => {
    setShareModalContent({ messageId, content })
  }, [])

  return (
    <div className={`flex h-full relative chat-unified chat-area`}>
      {/* 对话历史侧栏 */}
      <ChatHistory
        sessions={historySessions}
        activeSessionId={activeSessionId}
        onNewChat={handleNewSession}
        onSelectSession={handleSelectSession}
        onDeleteSession={handleDeleteSession}
        onRenameSession={handleRenameSession}
        onForkSession={async (sessionId, title) => {
          try {
            const newId = await sessionCapability.fork(sessionId, {
              title: title || `分支-${sessionId.slice(-6)}`,
            })
            handleSelectSession(newId)
            return newId
          } catch (e) {
            logger.warn('[ChatTab] Fork failed:', e)
            return ''
          }
        }}
        isVisible={historyVisible}
        onToggle={toggleHistory}
      />

      {/* 主内容区 */}
      <div className="flex flex-col flex-1 min-h-0 min-w-0">
        {/* ① 顶栏 */}
        <TopBar
          llmAvailable={llmAvailable}
          llmModel={llmModel}
          onModelChange={(model) => {
            // 后端没有"按对话切换模型"的端点，聊天始终走 /models/status 的默认模型。
            // 此前这里只打日志，用户以为切换生效了。
            logger.debug('[ChatTab] Model changed:', model)
            showNotice('warning', '模型切换暂不可用：后端未提供按对话指定模型的接口，当前仍使用默认模型')
          }}
          scenarioMode={scenarioMode}
          onScenarioSwitch={(mode) => scenarioSwitcher.switchTo(mode, 'user_selected')}
          historyVisible={historyVisible}
          historySessions={historySessions}
          onToggleHistory={toggleHistory}
          ragEnabled={false}
          ragIsSeeded={false}
          ragIsSeeding={false}
          onToggleRAG={() =>
            showNotice('warning', '知识库检索暂不可用：后端未提供 RAG 索引与检索端点')
          }
          onTriggerSeed={() =>
            showNotice('warning', '知识库初始化暂不可用：后端未提供 RAG 端点')
          }
          formulaCount={formulaCount}
          onShowFormulaList={() => setShowKBPanelLocal(true)}
          messageCount={messages.length}
          onClearChat={handleClearChat}
          onOpenKBPanel={() => setShowKBPanelLocal(true)}
          onOpenUserProfile={() => setShowUserProfileSettings(true)}
          onToggleSearch={() => setSearchOpen(v => !v)}
          searchOpen={searchOpen}
          // 此前是 t={() => ''}，把 TopBar 标题清空了
          t={(_key, fallback) => fallback ?? _key}
        />

        {/* ② 消息滚动区 */}
        <div className="flex-1 overflow-y-auto min-h-0">
          <div className="px-4 py-5 space-y-5">
            {/* 错误提示 */}
            {chatError && (
              <div className="p-3 bg-error-50 dark:bg-error-300/15 border border-error-200 dark:border-error-800/30 rounded-xl">
                <div className="flex items-start gap-2.5">
                  <AlertTriangle className="w-4 h-4 text-error-500 shrink-0 mt-0.5" />
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium text-error-800 dark:text-error-700">对话出错</p>
                    <p className="text-xs text-error-600 dark:text-error-700 mt-0.5 truncate">
                      {chatError instanceof Error ? chatError.message : String(chatError)}
                    </p>
                    <div className="flex gap-2 mt-2">
                      <Button variant="outline" size="sm" onClick={handleRetry}>重试</Button>
                      <Button variant="ghost" size="sm" onClick={clearError}>关闭</Button>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* 空状态 */}
            {messages.length === 0 && (
              <EmptyStateCard
                welcomeTitle="欢迎使用智能配方助手"
                welcomeSubtitle="选择下方问题快速开始，或直接输入您的配方需求"
                questions={QUICK_QUESTIONS}
                onAsk={handleSend}
              />
            )}

            {/* 消息列表 */}
            <ChatMessages
              messages={messages}
              isStreaming={isStreaming}
              chatError={chatError}
              onRetry={handleRetry}
              onGenerateReport={() => {
                if (isGeneratingReport) {
                  showNotice('warning', '报告正在生成中，请稍候')
                  return
                }
                if (formulaCount === 0) {
                  showNotice('warning', '还没有配方数据，请先在对话中描述配方需求或导入配方')
                  return
                }
                showNotice('success', '开始生成配方报告…')
                // 汇总当前会话识别出的全部配方；useReportGenerator 内部会做缓存与版本记录
                handleGenerateReport().catch((err) => {
                  const msg = err instanceof Error ? err.message : String(err ?? '未知错误')
                  showNotice('error', `报告生成失败：${msg}`)
                })
              }}
              showReportButton={formulaCount > 0}
              highlightedMessageId={highlightedMessageId}
              selectedMessageIds={[]}
              onReferenceMessage={(msg) => {
                const text = typeof msg.content === 'string' ? msg.content : String(msg.content ?? '')
                const snippet = text.length > 160 ? text.slice(0, 160) + '…' : text
                if (!snippet.trim()) return
                // 把被引用的消息作为上下文插入输入框，供下一轮提问引用
                setInput(`> ${snippet}\n${input}`)
              }}
              onEditMessage={editMessage}
              onRetractMessage={retractMessage}
              onForkMessage={handleForkMessage}
              onDetailsMessage={(call) => { setDetailsCall(call); setDetailsOpen(true) }}
              thinkingSteps={[]}
              onStructureSave={handleStructureSave}
              onStructureShare={handleStructureShare}
            />

            {/* 追问建议栏 */}
            {!isStreaming && messages.length > 0 && (
              <FollowUpSuggestionsBar
                onSendSuggestion={(question) => {
                  setInput(question)
                  handleSend()
                }}
                messages={messages}
                isVisible={!isStreaming && messages.length > 0}
              />
            )}

            {/* 生成中占位 */}
            {isStreaming && (
              <div className="flex items-start gap-3">
                <div className="w-7 h-7 rounded-full bg-gradient-to-br from-success-400 to-success-600 flex items-center justify-center flex-shrink-0">
                  <Leaf className="w-3.5 h-3.5 text-white" />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-1.5 py-2.5">
                    <span className="w-1.5 h-1.5 rounded-full bg-success-400 animate-bounce" style={{ animationDelay: '0ms' }} />
                    <span className="w-1.5 h-1.5 rounded-full bg-success-400 animate-bounce" style={{ animationDelay: '150ms' }} />
                    <span className="w-1.5 h-1.5 rounded-full bg-success-400 animate-bounce" style={{ animationDelay: '300ms' }} />
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* ③ 输入区 */}
        <div className="border-t border-neutral-200 dark:border-neutral-800 bg-white dark:bg-neutral-950 flex-shrink-0">
          {/* 暂停条 */}
          {isStreaming && (
            <div className="flex items-center justify-between px-4 py-1.5 bg-neutral-50/50 dark:bg-neutral-900/50">
              <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] flex items-center gap-1.5">
                <span className="w-1.5 h-1.5 rounded-full bg-success-500 animate-pulse" />
                生成中
              </span>
              <button onClick={pauseStreaming}
                className="flex items-center gap-1 px-2 py-0.5 rounded text-xs font-medium bg-neutral-200 dark:bg-neutral-800 text-neutral-500 hover:text-neutral-700 dark:hover:text-neutral-300 transition-colors">
                <Pause className="w-2.5 h-2.5" />
                暂停
              </button>
            </div>
          )}
          <ChatInputPro
            value={input}
            onChange={setInput}
            onSend={() => handleSend()}
            onStop={() => pauseStreaming()}
            isStreaming={isStreaming}
            maxLength={2000}
            placeholder="描述您的配方需求..."
            modelName={llmModel || 'deepseek-chat'}
            modelColor="text-success-500"
            attachments={attachments as DraftAttachment[]}
            onAddAttachment={handleAddAttachment}
            onRemoveAttachment={handleRemoveAttachment}
            onSlashSelect={(cmd) => {
              setInput('/' + cmd + ' ')
              handleSend()
            }}
          />
          <ComposerStatusBar
            messageCount={messages.length}
            assistantCount={assistantCount}
            elapsedSeconds={elapsedSeconds}
            modelName={llmModel || undefined}
            ragStatus={null}
          />
        </div>

        {/* Details 面板 — 移动端为全屏抽屉，sm+ 恢复为右侧内嵌列 */}
        {detailsOpenLocal && detailsCallLocal && (
          <div className="fixed inset-y-0 right-0 z-50 w-full max-w-[320px] flex-shrink-0 border-l border-neutral-200 dark:border-neutral-800 overflow-hidden sm:static sm:z-auto sm:w-[320px] sm:max-w-none">
            <DetailsPanel
              selectedCall={{ ...detailsCallLocal, arguments: detailsCallLocal.args } as any}
              onClose={() => setDetailsOpen(false)}
              title="工具调用详情"
            />
          </div>
        )}

        {/* RAG 知识库管理面板 */}
        {showKBPanelLocal && (
          <RAGKnowledgePanel
            onClose={() => setShowKBPanelLocal(false)}
            onSeedComplete={() => setShowKBPanelLocal(false)}
          />
        )}

        {/* 健康画像设置面板 */}
        {showUserProfileSettings && (
          <UserProfileSettingsPanel
            onClose={() => setShowUserProfileSettings(false)}
          />
        )}

        {/* 配方分享模态框 */}
        {shareModalContent && (
          <FormulaShareModal
            content={detectStructuredContent(shareModalContent.content) ?? { blocks: [], responseType: 'general' as any}}
            onClose={() => setShareModalContent(null)}
          />
        )}

        {/* 聊天消息搜索浮层 */}
        {searchOpen && (
          <ChatSearchOverlay
            messages={messages}
            onGoToMessage={(id) => {
              setSearchOpen(false)
              // 滚动到对应消息
              const el = document.querySelector(`[data-message-id="${id}"]`)
              el?.scrollIntoView({ behavior: 'smooth', block: 'center' })
            }}
            onClose={() => setSearchOpen(false)}
          />
        )}

        {/* 专业配方报告模态框
            注意：ProfessionalReport 内部 report.sections / report.title 无空值守卫，
            所以必须同时要求 reportData 存在才渲染，不能只看 showReportModal。 */}
        {showReportModal && !!reportData && (
          <ProfessionalReportModal
            report={reportData as ProfessionalReportModalProps['report']}
            isLoading={isGeneratingReport}
            onClose={() => setShowReportModal(false)}
          />
        )}

        {/* 操作反馈提示：成功 / 后端未提供端点 / 失败 */}
        {notice && (
          <div
            role="status"
            className={`fixed bottom-20 left-1/2 -translate-x-1/2 z-50 px-4 py-2 rounded-full
              text-xs font-medium shadow-lg animate-fade-in text-white ${
                notice.kind === 'success'
                  ? 'bg-success-500'
                  : notice.kind === 'error'
                    ? 'bg-error-500'
                    : 'bg-warning-500'
              }`}
          >
            {notice.kind === 'success' ? '✓ ' : '⚠ '}
            {notice.text}
          </div>
        )}
      </div>
    </div>
  )
}

export default ChatTab

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Button } from '@/components/ui';
import { Input } from '@/components/ui';
import { Alert, AlertTitle } from '@/components/ui';
import { LoadingSpinner } from '@/components/ui';
import { EmptyState } from '@/components/ui';
import { Tooltip } from '@/components/ui';
import {
  Plus,
  Trash2,
  LayoutTemplate,
  RefreshCw,
  Save,
  Calculator,
  CheckCircle2,
  AlertCircle,
} from 'lucide-react';
import { IngredientRow } from './IngredientRow';
import { IngredientSelector } from './IngredientSelector';
import { TemplateSelector } from './TemplateSelector';
import type { FormulaIngredient, FormulaTemplate, ValidationError, RatioUnit } from './types';
import {
  validateForm,
  calculateDosages,
  saveToLocalStorage,
  loadFromLocalStorage,
  createNewIngredient,
  duplicateIngredient,
  formatForNSGAII,
} from './utils';

interface FormulaIngredientInputProps {
  onSubmit: (data: ReturnType<typeof formatForNSGAII>) => void;
  disabled?: boolean;
  ingredients?: FormulaIngredient[];
  setIngredients?: React.Dispatch<React.SetStateAction<FormulaIngredient[]>>;
  totalWeight?: number;
  setTotalWeight?: React.Dispatch<React.SetStateAction<number>>;
}

export const FormulaIngredientInput: React.FC<FormulaIngredientInputProps> = ({
  onSubmit,
  disabled = false,
  ingredients: externalIngredients,
  setIngredients: externalSetIngredients,
  totalWeight: externalTotalWeight,
  setTotalWeight: externalSetTotalWeight,
}) => {
  const [internalIngredients, setInternalIngredients] = useState<FormulaIngredient[]>([]);
  const [internalTotalWeight, setInternalTotalWeight] = useState(100);

  const ingredients = externalIngredients !== undefined ? externalIngredients : internalIngredients;
  const setIngredients = externalSetIngredients !== undefined 
    ? externalSetIngredients 
    : setInternalIngredients;
  const totalWeight = externalTotalWeight !== undefined ? externalTotalWeight : internalTotalWeight;
  const setTotalWeight = externalSetTotalWeight !== undefined 
    ? externalSetTotalWeight 
    : setInternalTotalWeight;
  const [ratioUnit, setRatioUnit] = useState<RatioUnit>('percentage');
  const [errors, setErrors] = useState<ValidationError[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [showSelector, setShowSelector] = useState(false);
  const [showTemplateSelector, setShowTemplateSelector] = useState(false);
  const [expandedRowId, setExpandedRowId] = useState<string | null>(null);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);
  const [isAutoSaving, setIsAutoSaving] = useState(false);

  const saveTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    const savedData = loadFromLocalStorage();
    if (savedData) {
      setIngredients(savedData.ingredients);
      setTotalWeight(savedData.totalWeight);
    }
  }, []);

  useEffect(() => {
    const calculated = calculateDosages(ingredients, totalWeight);
    setIngredients(calculated);
  }, [totalWeight]);

  useEffect(() => {
    if (saveTimeoutRef.current) {
      clearTimeout(saveTimeoutRef.current);
    }

    saveTimeoutRef.current = setTimeout(() => {
      setIsAutoSaving(true);
      saveToLocalStorage({ ingredients, totalWeight });
      setLastSaved(new Date());
      setIsAutoSaving(false);
    }, 30000);

    return () => {
      if (saveTimeoutRef.current) {
        clearTimeout(saveTimeoutRef.current);
      }
    };
  }, [ingredients, totalWeight]);

  const handleSaveNow = useCallback(() => {
    saveToLocalStorage({ ingredients, totalWeight });
    setLastSaved(new Date());
  }, [ingredients, totalWeight]);

  const handleAddIngredient = () => {
    setShowSelector(true);
  };

  const handleQuickAddIngredient = () => {
    const newIng = createNewIngredient();
    setIngredients([...ingredients, newIng]);
    setExpandedRowId(newIng.id);
  };

  const handleSelectIngredient = (ingredient: FormulaIngredient) => {
    setIngredients([...ingredients, ingredient]);
    setExpandedRowId(ingredient.id);
  };

  const handleUpdateIngredient = (id: string, updates: Partial<FormulaIngredient>) => {
    setIngredients((prev) =>
      prev.map((ing) => (ing.id === id ? { ...ing, ...updates } : ing))
    );
  };

  const handleDeleteIngredient = (id: string) => {
    setIngredients((prev) => prev.filter((ing) => ing.id !== id));
    if (expandedRowId === id) {
      setExpandedRowId(null);
    }
  };

  const handleDuplicateIngredient = (ingredient: FormulaIngredient) => {
    const duplicated = duplicateIngredient(ingredient);
    setIngredients([...ingredients, duplicated]);
    setExpandedRowId(duplicated.id);
  };

  const handleLoadTemplate = (template: FormulaTemplate) => {
    const newIngredients = template.ingredients.map((ing) => ({
      ...ing,
      id: `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      parameters: ing.parameters.map((p) => ({ ...p, id: `${Date.now()}-${Math.random().toString(36).substr(2, 9)}` })),
    }));
    setIngredients(calculateDosages(newIngredients, template.totalWeight));
    setTotalWeight(template.totalWeight);
    setErrors([]);
  };

  const handleClearAll = () => {
    setIngredients([]);
    setTotalWeight(100);
    setErrors([]);
  };

  const handleSubmit = async () => {
    const validationErrors = validateForm(ingredients);

    if (validationErrors.length > 0) {
      setErrors(validationErrors);
      return;
    }

    setIsLoading(true);
    setErrors([]);

    try {
      const data = formatForNSGAII(ingredients, totalWeight);
      onSubmit(data);
    } finally {
      setIsLoading(false);
    }
  };

  const totalRatio = ingredients.reduce((sum, ing) => sum + ing.ratio, 0);
  const isValidRatio = Math.abs(totalRatio - 100) <= 0.01;

  return (
    <div className="formula-ingredient-input">
      <div className="input-header">
        <h2 className="input-title">配方成分输入</h2>
        <div className="header-actions">
          <Tooltip content={lastSaved ? `上次保存: ${lastSaved.toLocaleTimeString()}` : '未保存'}>
            <Button
              icon={isAutoSaving ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
              onClick={handleSaveNow}
              size="sm"
              disabled={disabled}
              variant="secondary"
            >
              {isAutoSaving ? '保存中...' : '保存'}
            </Button>
          </Tooltip>
          <Button
            icon={<LayoutTemplate className="w-4 h-4" />}
            onClick={() => setShowTemplateSelector(true)}
            size="sm"
            disabled={disabled}
            variant="secondary"
          >
            模板
          </Button>
        </div>
      </div>

      <div className="total-weight-section">
        <label className="total-weight-label">
          <Calculator className="w-4 h-4 mr-2" /> 成品总克数
        </label>
        <div className="total-weight-input-wrapper">
          <Input
            type="number"
            min={1}
            max={10000}
            step={1}
            value={totalWeight || ''}
            onChange={(e) => setTotalWeight(parseFloat(e.target.value) || 100)}
            className="total-weight-input"
            disabled={disabled}
          />
          <span className="total-weight-unit">g</span>
        </div>
        <div className="total-ratio-status">
          <span className="ratio-label">比例总和:</span>
          <span className={`ratio-value ${isValidRatio ? 'valid' : 'invalid'}`}>
            {totalRatio.toFixed(2)}%
          </span>
          {isValidRatio ? (
            <CheckCircle2 className="ratio-icon valid w-5 h-5" />
          ) : (
            <AlertCircle className="ratio-icon invalid w-5 h-5" />
          )}
        </div>
      </div>

      <div className="unit-switch-section">
        <span className="unit-label">比例单位:</span>
        <div className="unit-switch">
          <button
            type="button"
            className={`unit-btn ${ratioUnit === 'percentage' ? 'active' : ''}`}
            onClick={() => setRatioUnit('percentage')}
            disabled={disabled}
          >
            百分比 (%)
          </button>
          <button
            type="button"
            className={`unit-btn ${ratioUnit === 'mass' ? 'active' : ''}`}
            onClick={() => setRatioUnit('mass')}
            disabled={disabled}
          >
            质量分数
          </button>
        </div>
      </div>

      {errors.length > 0 && (
        <Alert variant="destructive">
          <AlertTitle>输入验证失败</AlertTitle>
          <ul className="error-list">
            {errors.map((error, index) => (
              <li key={index}>
                <span className="error-message">{error.message}</span>
                <span className="error-suggestion">({error.suggestion})</span>
              </li>
            ))}
          </ul>
        </Alert>
      )}

      <div className="ingredients-section">
        <div className="ingredients-header">
          <span className="ingredients-count">{ingredients.length} 种成分</span>
          <div className="ingredients-actions">
            <Button
              icon={<Plus className="w-4 h-4" />}
              onClick={handleAddIngredient}
              size="sm"
              variant="primary"
              disabled={disabled}
            >
              从数据库添加
            </Button>
            <Button
              icon={<Plus className="w-4 h-4" />}
              onClick={handleQuickAddIngredient}
              size="sm"
              disabled={disabled}
              variant="secondary"
            >
              快速添加
            </Button>
            {ingredients.length > 0 && (
              <Button
                icon={<Trash2 className="w-4 h-4" />}
                onClick={handleClearAll}
                size="sm"
                variant="danger"
                disabled={disabled}
              >
                清空全部
              </Button>
            )}
          </div>
        </div>

        <div className="ingredients-list">
          {isLoading ? (
            <div className="loading-container">
              <LoadingSpinner size="lg" />
            </div>
          ) : ingredients.length === 0 ? (
            <EmptyState title="暂无成分" description="请添加配方成分" />
          ) : (
            ingredients.map((ingredient) => (
              <IngredientRow
                key={ingredient.id}
                ingredient={ingredient}
                onUpdate={handleUpdateIngredient}
                onDelete={handleDeleteIngredient}
                onDuplicate={handleDuplicateIngredient}
                onSelectIngredient={() => setShowSelector(true)}
                expanded={expandedRowId === ingredient.id}
                onToggleExpand={() =>
                  setExpandedRowId(
                    expandedRowId === ingredient.id ? null : ingredient.id
                  )
                }
              />
            ))
          )}
        </div>
      </div>

      <div className="submit-section">
        <Button
          variant="primary"
          size="lg"
          onClick={handleSubmit}
          disabled={disabled || ingredients.length === 0 || isLoading}
          loading={isLoading}
        >
          提交优化
        </Button>
        <span className="submit-hint">
          请确保比例总和为100%，所有必填参数已填写
        </span>
      </div>

      <IngredientSelector
        isOpen={showSelector}
        onClose={() => setShowSelector(false)}
        onSelect={handleSelectIngredient}
      />

      <TemplateSelector
        isOpen={showTemplateSelector}
        onClose={() => setShowTemplateSelector(false)}
        onLoadTemplate={handleLoadTemplate}
      />
    </div>
  );
};

