          {currentStep > 0 && (
            <button
              onClick={handlePrev}
              className="flex items-center gap-2 px-4 py-2 text-sm font-medium text-neutral-600 dark:text-neutral-400 hover:text-neutral-900 dark:hover:text-white hover:bg-neutral-100 dark:hover:bg-neutral-700 rounded-lg transition-colors"
            >
              <ChevronLeft className="w-4 h-4" />
              上一步
            </button>
          )}

          {currentStep < steps.length - 1 && (
            <button
              onClick={handleSkip}
              className="text-sm text-neutral-500 hover:text-neutral-700 dark:hover:text-neutral-300 underline"
            >
              跳过此步
            </button>
          )}
        </div>

        <div className="flex items-center gap-3">
          {onCancel && (
            <button
              onClick={onCancel}
              className="px-4 py-2 text-sm font-medium text-neutral-600 dark:text-neutral-400 hover:text-neutral-900 dark:hover:text-white hover:bg-neutral-100 dark:hover:bg-neutral-700 rounded-lg transition-colors"
            >
              取消
            </button>
          )}

          <motion.button
            whileHover={{ scale: 1.02 }}
            whileTap={{ scale: 0.98 }}
            onClick={handleNext}
            disabled={!canProceed && currentStep < steps.length - 1}
            className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-sm font-semibold text-white shadow-lg transition-all ${
              canProceed || currentStep === steps.length - 1
                ? 'bg-gradient-to-r from-success-500 to-success-500 hover:from-success-600 hover:to-success-600'
                : 'bg-neutral-300 dark:bg-neutral-600 cursor-not-allowed'
            }`}
          >
            {currentStep === steps.length - 1 ? (
              <>
                <Check className="w-4 h-4" />
                完成配置
              </>
            ) : (
              <>
                下一步
                <ChevronRight className="w-4 h-4" />
              </>
            )}
          </motion.button>
        </div>
      </div>
    </div>
  );
}

function ConfigPreview({ data, currentStep }: { data: any; currentStep: number }) {
  return (
    <div className="space-y-4 text-sm">
      {currentStep >= 0 && data.selectedEfficacies?.length > 0 && (
        <div>
          <h5 className="text-xs font-semibold text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] uppercase tracking-wider mb-2">目标功效</h5>
          <div className="space-y-1.5">
            {data.selectedEfficacies.slice(0, 5).map((e: any) => (
              <div key={e.id} className="flex items-center justify-between">
                <span className="text-neutral-700 dark:text-neutral-300">{e.label}</span>
                <span className="text-primary-700 font-medium">{e.weight}%</span>
              </div>
            ))}
            {data.selectedEfficacies.length > 5 && (
              <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">+{data.selectedEfficacies.length - 5} 更多...</div>
            )}
          </div>
        </div>
      )}

      {currentStep >= 1 && (
        <div>
          <h5 className="text-xs font-semibold text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] uppercase tracking-wider mb-2">约束条件</h5>
          <div className="space-y-1 text-neutral-600 dark:text-neutral-400">
            <div>
              pH: {data.constraints?.phRange?.[0]}-{data.constraints?.phRange?.[1]}
            </div>
            <div>
              温度:{' '}
              {{ room: '常温', heated: '加热', refrigerated: '冷藏' }[data.constraints?.temperature as string] ?? '-'}
            </div>
            <div>
              粘度:{' '}
              {{ watery: '水状', lotion: '乳液', cream: '膏体', solid: '固体' }[
                data.constraints?.viscosity as string
              ] ?? '-'}
            </div>
            {data.constraints?.maxCostPerKg && <div>成本上限: ¥{data.constraints.maxCostPerKg}/kg</div>}
          </div>
        </div>
      )}

      {currentStep >= 2 && (
        <div>
          <h5 className="text-xs font-semibold text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] uppercase tracking-wider mb-2">高级选项</h5>
          <div className="space-y-1 text-neutral-600 dark:text-neutral-400">
            {data.advanced?.sourcePreference?.length > 0 && (
              <div>原料: {data.advanced.sourcePreference.join(', ')}</div>
            )}
            {data.advanced?.certifications?.length > 0 && <div>认证: {data.advanced.certifications.join(', ')}</div>}
            {data.advanced?.targetMarket?.length > 0 && <div>市场: {data.advanced.targetMarket.join(', ')}</div>}
          </div>
        </div>
      )}
    </div>
  );
}

function PresetManager({
  presets,
  onSave,
  onDelete,
  onClose,
}: {
  presets: PresetData[];
  onSave: (name: string) => void;
  onDelete: (id: string) => void;
  onClose: () => void;
}) {
  const [newPresetName, setNewPresetName] = useState('');

  return (
    <div className="p-4 bg-neutral-50 dark:bg-neutral-800 rounded-xl space-y-3">
      <div className="flex items-center justify-between">
        <h4 className="text-sm font-semibold text-neutral-700 dark:text-neutral-300">管理自定义预设</h4>
        <button onClick={onClose} className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-neutral-600 text-sm">
          ✕
        </button>
      </div>

      <div className="flex gap-2">
        <input
          type="text"
          value={newPresetName}
          onChange={(e) => setNewPresetName(e.target.value)}
          placeholder="输入预设名称..."
          className="flex-1 px-3 py-1.5 text-sm border border-neutral-300 dark:border-neutral-600 rounded-lg bg-white dark:bg-neutral-700 focus:outline-none focus:ring-2 focus:ring-success-500"
        />
        <button
          onClick={() => {
            if (newPresetName.trim()) {
              onSave(newPresetName.trim());
              setNewPresetName('');
            }
          }}
          disabled={!newPresetName.trim()}
          aria-label="保存预设"
          className="px-3 py-1.5 bg-primary-container text-primary-main text-sm rounded-lg hover:bg-primary-container disabled:opacity-50"
        >
          <Save className="w-4 h-4" />
        </button>
      </div>

      {presets.length === 0 ? (
        <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] text-center py-2">暂无自定义预设</p>
      ) : (
        <div className="space-y-2 max-h-40 overflow-y-auto">
          {presets.map((preset) => (
            <div key={preset.id} className="flex items-center justify-between p-2 bg-white dark:bg-neutral-700 rounded-lg">
              <div>
                <div className="text-sm font-medium text-neutral-700 dark:text-neutral-300">{preset.name}</div>
                <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{preset.description}</div>
              </div>
              <button
                onClick={() => onDelete(preset.id)}
                className="p-1 text-error-500 hover:bg-error-50 dark:hover:bg-error-900/20 rounded"
              >
                <Trash2 className="w-4 h-4" />
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

