import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest'
import { renderHook, act } from '@testing-library/react'
import { useFormulaTemplates, type FormulaTemplate } from '../useFormulaTemplates'

describe('useFormulaTemplates', () => {
  const mockTemplate = {
    name: '测试模板',
    description: '测试描述',
    targetEffects: ['免疫调节', '抗疲劳'],
    constraints: { maxIngredients: 5 },
  }

  beforeEach(() => {
    localStorage.clear()
    vi.clearAllMocks()
  })

  afterEach(() => {
    localStorage.clear()
  })

  it('should initialize with empty templates when no storage', () => {
    const { result } = renderHook(() => useFormulaTemplates())
    expect(result.current.templates).toEqual([])
  })

  it('should load templates from localStorage', () => {
    const storedTemplates: FormulaTemplate[] = [
      {
        id: 'test_id',
        name: '存储的模板',
        description: '描述',
        targetEffects: ['免疫调节'],
        createdAt: Date.now(),
        updatedAt: Date.now(),
        usageCount: 0,
      },
    ]
    localStorage.setItem('rmfood_formula_templates', JSON.stringify(storedTemplates))

    const { result } = renderHook(() => useFormulaTemplates())
    expect(result.current.templates).toEqual(storedTemplates)
  })

  it('should create a new template', () => {
    const { result } = renderHook(() => useFormulaTemplates())

    act(() => {
      result.current.createTemplate(mockTemplate)
    })

    expect(result.current.templates.length).toBe(1)
    expect(result.current.templates[0].name).toBe(mockTemplate.name)
    expect(result.current.templates[0].id).toBeDefined()
    expect(result.current.templates[0].createdAt).toBeDefined()
    expect(result.current.templates[0].usageCount).toBe(0)
  })

  it('should persist templates to localStorage', () => {
    const { result } = renderHook(() => useFormulaTemplates())

    act(() => {
      result.current.createTemplate(mockTemplate)
    })

    const stored = localStorage.getItem('rmfood_formula_templates')
    expect(stored).toBeTruthy()
    const parsed = JSON.parse(stored!)
    expect(parsed.length).toBe(1)
    expect(parsed[0].name).toBe(mockTemplate.name)
  })

  it('should update a template', () => {
    const { result } = renderHook(() => useFormulaTemplates())

    act(() => {
      result.current.createTemplate(mockTemplate)
    })

    const templateId = result.current.templates[0].id

    act(() => {
      result.current.updateTemplate(templateId, {
        name: '更新后的名称',
        description: '更新后的描述',
      })
    })

    const updated = result.current.getTemplateById(templateId)
    expect(updated?.name).toBe('更新后的名称')
    expect(updated?.description).toBe('更新后的描述')
    expect(updated?.updatedAt).toBeGreaterThan(updated?.createdAt!)
  })

  it('should delete a template', () => {
    const { result } = renderHook(() => useFormulaTemplates())

    act(() => {
      result.current.createTemplate(mockTemplate)
    })

    const templateId = result.current.templates[0].id
    expect(result.current.templates.length).toBe(1)

    act(() => {
      result.current.deleteTemplate(templateId)
    })

    expect(result.current.templates.length).toBe(0)
  })

  it('should get template by id', () => {
    const { result } = renderHook(() => useFormulaTemplates())

    act(() => {
      result.current.createTemplate(mockTemplate)
    })

    const templateId = result.current.templates[0].id
    const found = result.current.getTemplateById(templateId)

    expect(found).toBeDefined()
    expect(found?.id).toBe(templateId)
    expect(found?.name).toBe(mockTemplate.name)
  })

  it('should increment usage count', () => {
    const { result } = renderHook(() => useFormulaTemplates())

    act(() => {
      result.current.createTemplate(mockTemplate)
    })

    const templateId = result.current.templates[0].id
    expect(result.current.templates[0].usageCount).toBe(0)

    act(() => {
      result.current.incrementUsage(templateId)
    })

    expect(result.current.templates[0].usageCount).toBe(1)

    act(() => {
      result.current.incrementUsage(templateId)
    })

    expect(result.current.templates[0].usageCount).toBe(2)
  })

  it('should return default templates', () => {
    const { result } = renderHook(() => useFormulaTemplates())
    const defaults = result.current.getDefaultTemplates()

    expect(defaults.length).toBe(3)
    expect(defaults[0].name).toBe('免疫调节配方')
    expect(defaults[1].name).toBe('抗疲劳配方')
    expect(defaults[2].name).toBe('综合调理配方')
  })
})

/**
 * useAlgorithmConfig - 算法配置管理 Hook
 * 
 * @description 管理遗传算法参数配置，支持预设场景和自定义参数
 * @version 1.0.0
 */
import { useState, useCallback, useMemo } from 'react'
import { usePersistentState } from '@/hooks/usePersistentState'
import { STORAGE_KEYS } from '@/config'
import { logger } from '@/utils/safeLogger'

export type AlgorithmStrategy = 'ga' | 'nsga2' | 'hybrid' | 'auto'
export type PresetMode = 'balanced' | 'cost_first' | 'efficacy_first' | 'safety_first' | 'synergy_focused' | null
export type TastePreference = 'balanced' | 'sweet_enhanced' | 'bitter_reduced' | 'custom'

export interface AlgorithmConfig {
  strategy: AlgorithmStrategy
  preset: PresetMode
  populationSize: number
  generations: number
  mutationRate: number
  crossoverRate: number
  eliteRatio: number
  tournamentSize: number
  tastePreference: TastePreference
  customTasteRatios?: Record<string, number>
}

export interface ConstraintConfig {
  ageGroup: 'children' | 'adult' | 'elderly' | 'pregnant'
  gender?: 'male' | 'female'
  weight?: number  // kg
  height?: number  // cm
  allergies: string[]
  contraindications: string[]
  dietaryRestrictions: string[]
  conditions: string[]
  currentMedications: string[]
  cookingMethod: 'decoction' | 'tea' | 'soup' | 'paste' | 'powder'
  cookingTime?: number
}

// 默认配置
const DEFAULT_ALGORITHM_CONFIG: AlgorithmConfig = {
  strategy: 'auto',
  preset: 'balanced',
  populationSize: 50,
  generations: 40,
  mutationRate: 0.15,
  crossoverRate: 0.85,
  eliteRatio: 0.15,
  tournamentSize: 5,
  tastePreference: 'balanced',
}

const DEFAULT_CONSTRAINT_CONFIG: ConstraintConfig = {
  ageGroup: 'adult',
  allergies: [],
  contraindications: [],
  dietaryRestrictions: [],
  conditions: [],
  currentMedications: [],
  cookingMethod: 'decoction',
}

// 预设场景参数映射
const PRESET_PARAMS: Record<string, Partial<AlgorithmConfig>> = {
  balanced: {
    populationSize: 50,
    generations: 40,
    eliteRatio: 0.15,
  },
  cost_first: {
    populationSize: 60,
    generations: 50,
    eliteRatio: 0.2,
  },
  efficacy_first: {
    populationSize: 80,
    generations: 60,
    eliteRatio: 0.1,
  },
  safety_first: {
    populationSize: 60,
    generations: 50,
    eliteRatio: 0.25,
  },
  synergy_focused: {
    populationSize: 70,
    generations: 55,
    eliteRatio: 0.15,
  },
}

export function useAlgorithmConfig() {
  const [config, setConfig] = usePersistentState<AlgorithmConfig>(
    'rmfood:generate:algorithmConfig',
    DEFAULT_ALGORITHM_CONFIG,
  )

  const [constraints, setConstraints] = usePersistentState<ConstraintConfig>(
    'rmfood:generate:constraints',
    DEFAULT_CONSTRAINT_CONFIG,
  )

  const applyPreset = useCallback((preset: PresetMode) => {
    if (!preset) return

    const presetParams = PRESET_PARAMS[preset]
    if (presetParams) {
      setConfig(prev => ({ ...prev, preset, ...presetParams }))
      logger.info('应用预设场景', { preset })
    }
  }, [setConfig])

  const updateConfig = useCallback((updates: Partial<AlgorithmConfig>) => {
    setConfig(prev => ({ ...prev, ...updates }))
  }, [setConfig])

  const updateConstraints = useCallback((updates: Partial<ConstraintConfig>) => {
    setConstraints(prev => ({ ...prev, ...updates }))
  }, [setConstraints])

  const resetConfig = useCallback(() => {
    setConfig(DEFAULT_ALGORITHM_CONFIG)
    setConstraints(DEFAULT_CONSTRAINT_CONFIG)
    logger.info('重置算法配置')
  }, [setConfig, setConstraints])

  // 构建 API 请求参数
  const toApiParams = useMemo(() => {
    return {
      // 算法参数
      population_size: config.populationSize,
      generations: config.generations,
      mutation_rate: config.mutationRate,
      crossover_rate: config.crossoverRate,
      elite_ratio: config.eliteRatio,
      tournament_size: config.tournamentSize,
      strategy: config.strategy,

      // 约束条件
      constraints: {
        age_group: constraints.ageGroup,
        allergies: constraints.allergies,
        contraindications: constraints.contraindications,
        conditions: constraints.conditions,
        cooking_method: constraints.cookingMethod,
        taste_preference: config.tastePreference,
      },
    }
  }, [config, constraints])

  return {
    config,
    constraints,
    setConfig,
    setConstraints,
    applyPreset,
    updateConfig,
    updateConstraints,
    resetConfig,
    toApiParams,
  }
}

// 导出存储键常量
export const ALGORITHM_STORAGE_KEYS = {
  ALGORITHM_CONFIG: 'rmfood:generate:algorithmConfig',
  ALGORITHM_CONSTRAINTS: 'rmfood:generate:constraints',
} as const

/**
 * 配方导出功能 Hook
 *
 * @description 提供配方数据导出功能，支持 JSON、CSV 等格式
 * @version 1.0.0
 */

import { useCallback } from 'react'
import { logger } from '@/utils/safeLogger'
import { useOperationFeedback } from '@/hooks/useOperationFeedback'
import type { AICandidate } from '@/api/ai'

export interface ExportOptions {
  format: 'json' | 'csv' | 'pdf'
  includePatentScores?: boolean
  includeDetailedInfo?: boolean
}

export function useExportFormula(generateResult: AICandidate[] | null) {
  const feedback = useOperationFeedback()

  const exportData = useCallback((options: ExportOptions) => {
    if (!generateResult || generateResult.length === 0) {
      feedback.showError('导出失败', '没有可导出的配方数据')
      return
    }

    try {
      const { format } = options

      const exportItems = generateResult.map((candidate, index) => {
        // 兼容后端字段：herb_combination 项可能含 dosage_g / dosage / dose_g 与 role
        const herbCombo = (candidate.herb_combination || [])
          .map((h: any) => {
            const dose = h.dosage_g ?? h.dosage ?? h.dose_g
            const role = h.role ? `[${h.role}]` : ''
            return `${role}${h.name}${typeof dose !== 'undefined' ? ` ${dose}g` : ''}`
          })
          .join(', ')
        const baseData = {
          序号: index + 1,
          配方名称: candidate.formula_name || candidate.name || '未知配方',
          药材组合: herbCombo,
          功效: (candidate.effects || []).join('、'),
          综合评分: candidate.overall_score ?? candidate.synergy_score ?? 0,
          协同评分: candidate.synergy_score || 0,
          口感评分: candidate.taste_score || '',
          稳定性评分: candidate.stability_score || '',
          安全性: candidate.safety_passed ? '通过' : '未通过',
          生成方式: candidate.generated_by || '遗传算法',
          创建时间: candidate.generated_at || '',
        }

        if (options.includePatentScores && candidate.patent_synergy_scores) {
          return {
            ...baseData,
            专利协同指数: candidate.patent_synergy_scores.overall_si || 0,
            加权综合分: candidate.patent_synergy_scores.weighted_score || 0,
            主导机制: candidate.patent_synergy_scores.dominant_mechanism || '',
            质量等级: candidate.patent_synergy_scores.quality_level || '',
            置信度: candidate.patent_synergy_scores.confidence || 0,
          }
        }

        return baseData
      })

      if (format === 'json') {
        exportToJSON(exportItems)
      } else if (format === 'csv') {
        exportToCSV(exportItems)
      } else if (format === 'pdf') {
        handlePDFExport(feedback)
      }

      feedback.showSuccess('导出成功', `已成功导出 ${generateResult.length} 条配方数据`)
    } catch (error) {
      logger.error('导出失败', { error, options })
      feedback.showError('导出失败', '导出过程出错')
    }
  }, [generateResult, feedback])

  const exportToJSON = (data: any[]) => {
    const dataStr = JSON.stringify(data, null, 2)
    const blob = new Blob([dataStr], { type: 'application/json;charset=utf-8;' })
    downloadBlob(blob, `RMFOOD_配方数据_${getCurrentDate()}.json`)
  }

  const exportToCSV = (data: any[]) => {
    const headers = Object.keys(data[0] || {})
    const csvContent = [
      headers.join(','),
      ...data.map(row =>
        headers.map(header => `"${String(row[header as keyof typeof row] || '').replace(/"/g, '""')}"`).join(','),
      ),
    ].join('\n')
    const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' })
    downloadBlob(blob, `RMFOOD_配方数据_${getCurrentDate()}.csv`)
  }

  const handlePDFExport = async (feedback: ReturnType<typeof useOperationFeedback>) => {
    try {
      const printWindow = window.open('', '_blank')
      if (!printWindow) {
        feedback.showError('PDF 导出失败', '请允许弹出窗口以生成 PDF')
        return
      }

      const html = `
        <!DOCTYPE html>
        <html><head><title>RMFOOD 配方数据导出</title>
        <style>
          body { font-family: 'Microsoft YaHei', sans-serif; padding: 40px; }
          table { width: 100%; border-collapse: collapse; margin-top: 20px; }
          th, td { border: 1px solid #ddd; padding: 8px 12px; text-align: left; }
          th { background: #f5f5f5; }
          h1 { color: #333; }
        </style></head>
        <body>
          <h1>RMFOOD 配方数据导出</h1>
          <p>导出时间: ${new Date().toLocaleString('zh-CN')}</p>
          <table>
            <thead><tr>${Object.keys(feedback).map(k => `<th>${k}</th>`).join('')}</tr></thead>
            <tbody>${(generateResult as unknown as Record<string, unknown>[]).map((row: Record<string, unknown>) =>
              `<tr>${Object.values(row).map(v => `<td>${v}</td>`).join('')}</tr>`
            ).join('')}</tbody>
          </table>
        </body></html>
      `

      printWindow.document.write(html)
      printWindow.document.close()
      printWindow.focus()

      setTimeout(() => {
        printWindow.print()
        printWindow.close()
        feedback.showSuccess('PDF 导出成功', '请在打印对话框中选择"另存为 PDF"')
      }, 500)
    } catch (error) {
      logger.error('PDF 导出失败', { error })
      feedback.showError('PDF 导出失败', '导出过程出错')
    }
  }

  const downloadBlob = (blob: Blob, filename: string) => {
    const link = document.createElement('a')
    link.href = URL.createObjectURL(blob)
    link.download = filename
    link.click()
    URL.revokeObjectURL(link.href)
  }

  const getCurrentDate = () => {
    return new Date().toISOString().slice(0, 10)
  }

  return {
    exportData,
    hasData: !!generateResult && generateResult.length > 0,
  }
}

import { useState, useRef, useCallback } from 'react'
import { DEFAULTS, VALIDATION } from '@/config'
import { HERB_ROLES } from '../config/generateTabConfig'
import { logger } from '@/utils/safeLogger'
import type { AICandidate } from '@/api/ai'

interface FormulaVersionData {
  id: string
  versionNumber: number
  formulaName: string
  effects: string[]
  ingredients: { name: string; dosage: string; role: string }[]
  scores: { synergy: number; taste: number; stability: number; overall: number }
  createdAt: number
  remark: string
}

export function useFormulaVersions() {
  const [formulaVersions, setFormulaVersions] = useState<FormulaVersionData[]>([])
  const versionCounterRef = useRef(0)

  const addVersion = useCallback((candidates: AICandidate[], effects: string[]) => {
    if (candidates.length === 0) return

    const topCandidate = candidates[0]
    versionCounterRef.current += 1

    const newVersion: FormulaVersionData = {
      id: `version_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`,
      versionNumber: versionCounterRef.current,
      formulaName: typeof topCandidate.formula_name === 'string'
        ? topCandidate.formula_name
        : DEFAULTS.PLACEHOLDER_TEXTS.UNKNOWN_FORMULA,
      effects,
      ingredients: (topCandidate.herb_combination || []).map((h: any, i: number) => ({
        name: typeof h.name === 'string' ? h.name : DEFAULTS.PLACEHOLDER_TEXTS.UNKNOWN_INGREDIENT,
        dosage: h.dosage || DEFAULTS.PLACEHOLDER_TEXTS.DEFAULT_DOSAGE_RANGE,
        role: HERB_ROLES[i % HERB_ROLES.length] || '君药',
      })),
      scores: {
        synergy: topCandidate.synergy_score || 0,
        taste: ((topCandidate as unknown) as Record<string, unknown>).taste_score as number || DEFAULTS.DEFAULT_TASTE_SCORE,
        stability: ((topCandidate as unknown) as Record<string, unknown>).stability_score as number || DEFAULTS.DEFAULT_STABILITY_SCORE,
        overall: ((topCandidate as unknown) as Record<string, unknown>).overall_score as number || (topCandidate.synergy_score || 0),
      },
      createdAt: Date.now(),
      remark: `${DEFAULTS.PLACEHOLDER_TEXTS.VERSION_REMARK_PREFIX} [${effects.join(', ')}] ${DEFAULTS.PLACEHOLDER_TEXTS.VERSION_REMARK_SUFFIX}`,
    }

    setFormulaVersions(prev =>
      [newVersion, ...prev].slice(0, VALIDATION.maxFormulaVersions),
    )

    logger.info('添加新配方版本', {
      versionNumber: newVersion.versionNumber,
      formulaName: newVersion.formulaName,
    })
  }, [])

  return {
    formulaVersions,
    setFormulaVersions,
    addVersion,
    versionCount: formulaVersions.length,
  }
}

/**
 * useGenerationCache - 配方生成缓存Hook
 * 
 * @description 缓存配方生成结果，提升重复操作性能
 * @version 1.0.0
 */
import { useState, useCallback, useEffect } from 'react'
import { logger } from '@/utils/safeLogger'

interface CacheEntry<T> {
  data: T
  timestamp: number
  ttl: number
}

interface GenerationCache {
  [key: string]: CacheEntry<any>
}

const CACHE_TTL = 5 * 60 * 1000 // 5分钟
const MAX_CACHE_SIZE = 50

class LRUCache {
  private cache: GenerationCache = {}
  private order: string[] = []

  get(key: string): any {
    if (!this.cache[key]) return undefined

    const entry = this.cache[key]
    if (Date.now() - entry.timestamp > CACHE_TTL) {
      this.delete(key)
      return undefined
    }

    // 更新顺序
    this.order = this.order.filter(k => k !== key)
    this.order.push(key)

    return entry.data
  }

  set(key: string, data: any) {
    // 如果已存在，先删除
    if (this.cache[key]) {
      this.order = this.order.filter(k => k !== key)
    }

    // 如果超出大小限制，删除最旧的
    if (this.order.length >= MAX_CACHE_SIZE) {
      const oldest = this.order.shift()
      if (oldest) {
        delete this.cache[oldest]
      }
    }

    this.cache[key] = {
      data,
      timestamp: Date.now(),
      ttl: CACHE_TTL,
    }
    this.order.push(key)

    logger.debug('Cache set', { key, size: this.order.length })
  }

  delete(key: string) {
    delete this.cache[key]
    this.order = this.order.filter(k => k !== key)
  }

  clear() {
    this.cache = {}
    this.order = []
    logger.info('Cache cleared')
  }

  get size() {
    return this.order.length
  }

  getStats() {
    return {
      size: this.order.length,
      maxSize: MAX_CACHE_SIZE,
      ttl: CACHE_TTL,
    }
  }
}

const cache = new LRUCache()

export function useGenerationCache() {
  const [cacheStats, setCacheStats] = useState(cache.getStats())

  useEffect(() => {
    const interval = setInterval(() => {
      setCacheStats(cache.getStats())
    }, 5000)
    return () => clearInterval(interval)
  }, [])

  const getCachedResult = useCallback((key: string) => {
    const result = cache.get(key)
    if (result) {
      logger.info('Cache hit', { key })
    }
    return result
  }, [])

  const setCachedResult = useCallback((key: string, data: any) => {
    cache.set(key, data)
    setCacheStats(cache.getStats())
  }, [])

  const clearCache = useCallback(() => {
    cache.clear()
    setCacheStats(cache.getStats())
  }, [])

  return {
    getCachedResult,
    setCachedResult,
    clearCache,
    stats: cacheStats,
  }
}

/**
 * 生成缓存键
 */
export function generateCacheKey(effects: string[], options?: Record<string, any>): string {
  const sortedEffects = [...effects].sort().join(',')
  const optionsStr = options ? JSON.stringify(options) : ''
  return `generate_${sortedEffects}_${optionsStr}`
}

import { useState, useRef, useCallback } from 'react'
import { DEFAULTS, TIMEOUTS } from '@/config'
import { logger } from '@/utils/safeLogger'
import type { AICandidate } from '@/api/ai'

interface SavedFormulaState {
  formulaId: number
  savedAt: number
}

export function useSavedFormulas() {
  const [savedFormulas, setSavedFormulas] = useState<Map<string, SavedFormulaState>>(new Map())
  const [saveSuccess, setSaveSuccess] = useState<{ formulaId: number; formulaName: string } | null>(null)
  const candidateIdCache = useRef<Map<string, string>>(new Map())

  const getCandidateId = useCallback((candidate: AICandidate, index: number): string => {
    const cacheKey = `${index}_${candidate.id || candidate.name || 'unknown'}`

    const cached = candidateIdCache.current.get(cacheKey)
    if (cached) return cached

    const safeName = typeof candidate.formula_name === 'string'
      ? candidate.formula_name.replace(/\s+/g, '_').toLowerCase()
      : (typeof candidate.name === 'string' ? candidate.name.replace(/\s+/g, '_').toLowerCase() : 'unknown')

    const newId = `candidate_${index}_${safeName}`
    candidateIdCache.current.set(cacheKey, newId)

    return newId
  }, [])

  const handleSaveSuccess = useCallback((
    formulaId: number,
    candidateId: string,
    generateResult: AICandidate[] | null,
  ) => {
    setSavedFormulas(prev => new Map(prev).set(candidateId, {
      formulaId,
      savedAt: Date.now(),
    }))

    const savedCandidate = generateResult?.find((c, i) => getCandidateId(c, i) === candidateId)

    if (savedCandidate) {
      const formulaName = typeof savedCandidate.formula_name === 'string'
        ? savedCandidate.formula_name
        : DEFAULTS.PLACEHOLDER_TEXTS.UNKNOWN_FORMULA

      setSaveSuccess({ formulaId, formulaName })

      setTimeout(() => {
        setSaveSuccess(null)
      }, TIMEOUTS.saveSuccessDisplay)
    }
  }, [getCandidateId])

  const resetSavedFormulas = useCallback(() => {
    setSavedFormulas(new Map())
    setSaveSuccess(null)
  }, [])

  return {
    savedFormulas,
    saveSuccess,
    setSaveSuccess,
    getCandidateId,
    handleSaveSuccess,
    resetSavedFormulas,
  }
}

import { logger } from '@/utils/safeLogger'
import React, { useState, useCallback, useEffect, useRef, useMemo } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import {
  Pause,
  Play,
  Square,
  ChevronDown,
  ChevronUp,
  Copy,
  Clock,
  CheckCircle2,
  Loader2,
  AlertCircle,
  XCircle,
} from 'lucide-react'

export type ProgressStage = 'idle' | 'preparing' | 'generating' | 'scoring' | 'optimizing' | 'sorting' | 'finalizing' | 'completed' | 'failed' | 'cancelled' | 'paused'

export type SubTaskStatus = 'pending' | 'running' | 'completed' | 'failed'

export interface SubTask {
  id: string
  name: string
  status: SubTaskStatus
  progress: number
  current?: number
  total?: number
}

export interface LogEntry {
  timestamp: string
  level: 'INFO' | 'WARN' | 'ERROR'
  message: string
}

export interface GenerationProgressState {
  stage: ProgressStage
  overallProgress: number
  currentStageName: string
  subTasks: SubTask[]
  logs: LogEntry[]
  startTime: number | null
  estimatedRemainingTime: number | null
  canPause: boolean
  canCancel: boolean
}

interface GenerationProgressProps {
  progress: Partial<GenerationProgressState>
  onPause?: () => void
  onResume?: () => void
  onCancel?: () => void
  onRetry?: () => void
  className?: string
  compact?: boolean
}

const STAGE_CONFIG: Record<ProgressStage, { label: string; color: string; icon: React.ReactNode }> = {
  idle: { label: '就绪', color: 'gray', icon: <Clock className="w-4 h-4" /> },
  preparing: { label: '准备中', color: 'blue', icon: <Loader2 className="w-4 h-4 animate-spin" /> },
  generating: { label: '候选生成', color: 'purple', icon: <Loader2 className="w-4 h-4 animate-spin" /> },
  scoring: { label: '评分计算', color: 'cyan', icon: <Loader2 className="w-4 h-4 animate-spin" /> },
  optimizing: { label: '排序优化', color: 'amber', icon: <Loader2 className="w-4 h-4 animate-spin" /> },
  sorting: { label: '结果整理', color: 'emerald', icon: <Loader2 className="w-4 h-4 animate-spin" /> },
  finalizing: { label: '最终处理', color: 'teal', icon: <Loader2 className="w-4 h-4 animate-spin" /> },
  completed: { label: '完成', color: 'green', icon: <CheckCircle2 className="w-4 h-4" /> },
  failed: { label: '失败', color: 'red', icon: <XCircle className="w-4 h-4" /> },
  cancelled: { label: '已取消', color: 'gray', icon: <XCircle className="w-4 h-4" /> },
  paused: { label: '已暂停', color: 'amber', icon: <Pause className="w-4 h-4" /> },
}

const STATUS_ICONS: Record<SubTaskStatus, React.ReactNode> = {
  pending: <div className="w-3 h-3 rounded-full border-2 border-neutral-300 dark:border-neutral-600" />,
  running: <Loader2 className="w-3 h-3 text-secondary-500 animate-spin" />,
  completed: <CheckCircle2 className="w-3 h-3 text-success-500" />,
  failed: <XCircle className="w-3 h-3 text-error-500" />,
}

const COLOR_MAP: Record<string, string> = {
  gray: 'bg-neutral-400',
  blue: 'bg-secondary-500',
  purple: 'bg-accent-500',
  cyan: 'bg-info-500',
  amber: 'bg-warning-500',
  emerald: 'bg-primary-500',
  teal: 'bg-success-500',
  green: 'bg-success-500',
  red: 'bg-error-500',
}

function formatTime(seconds: number): string {
  if (seconds < 60) return `${Math.round(seconds)}s`
  const mins = Math.floor(seconds / 60)
  const secs = Math.round(seconds % 60)
  return `${mins}m ${secs}s`
}

function formatTimestamp(date: Date): string {
  return date.toLocaleTimeString('zh-CN', {
    hour12: false,
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
  })
}

export function GenerationProgress({
  progress,
  onPause,
  onResume,
  onCancel,
  onRetry,
  className = '',
  compact = false,
}: GenerationProgressProps) {
  const [showLogs, setShowLogs] = useState(false)
  const logsEndRef = useRef<HTMLDivElement>(null)
  const stageInfo = STAGE_CONFIG[progress.stage || 'idle']

  useEffect(() => {
    if (showLogs && logsEndRef.current) {
      logsEndRef.current.scrollIntoView({ behavior: 'smooth' })
    }
  }, [progress.logs, showLogs])

  const elapsedTime = useMemo(() => {
    if (!progress.startTime) return 0
    return (Date.now() - progress.startTime) / 1000
  }, [progress.startTime, progress.stage])

  const handleCopyLogs = useCallback(() => {
    if (!progress.logs?.length) return

    const logText = progress.logs
      .map(log => `[${log.timestamp}] [${log.level}] ${log.message}`)
      .join('\n')

    navigator.clipboard.writeText(logText).then(() => {
      logger.log('日志已复制到剪贴板')
    })
  }, [progress.logs])

  if (compact && (progress.stage === 'idle' || !progress.stage)) {
    return null
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      className={`rounded-xl border bg-white dark:bg-neutral-900 overflow-hidden ${className}`}
      style={{ borderColor: `var(--tw-${stageInfo.color}-200, rgb(229, 231, 235))` }}
    >
      {/* 主进度条区域 */}
      <div className="p-5 space-y-4">
        {/* 进度头部信息 */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <span className={`${COLOR_MAP[stageInfo.color] || 'bg-neutral-400'} text-white p-1.5 rounded-lg`}>
              {stageInfo.icon}
            </span>
            <div>
              <h4 className="text-sm font-semibold text-neutral-900 dark:text-white">
                {progress.currentStageName || stageInfo.label}
              </h4>
              {(progress.stage !== 'idle' && progress.stage !== 'completed' && progress.stage !== 'failed' && progress.stage !== 'cancelled') && (
                <p className="text-xs text-neutral-500 dark:text-neutral-400">
                  已用时 {formatTime(elapsedTime)}
                  {progress.estimatedRemainingTime != null && (
                    <span className="ml-2">预计剩余 ~{formatTime(progress.estimatedRemainingTime)}</span>
                  )}
                </p>
              )}
            </div>
          </div>

          {/* 百分比显示 */}
          <motion.div
            key={progress.overallProgress || 0}
            initial={{ scale: 1.1 }}
            animate={{ scale: 1 }}
            className="text-right"
          >
            <span className="text-2xl font-bold text-neutral-900 dark:text-white">
              {Math.round(progress.overallProgress || 0)}%
            </span>
          </motion.div>
        </div>

        {/* 总进度条 */}
        <div className="relative h-3 bg-neutral-100 dark:bg-neutral-800 rounded-full overflow-hidden">
          <motion.div
            className="absolute inset-y-0 left-0 rounded-full"
            style={{
              backgroundColor:
                progress.stage === 'failed'
                  ? 'rgb(239, 68, 68)'
                  : progress.stage === 'cancelled'
                  ? 'rgb(156, 163, 175)'
                  : `linear-gradient(90deg, rgb(16, 185, 129), rgb(20, 184, 166))`,
              width: `${Math.max(0, Math.min(100, progress.overallProgress || 0))}%`,
            }}
            transition={{ duration: 0.3, ease: 'easeOut' }}
          />
          {/* 动画光效 */}
          {(progress.stage !== 'idle' &&
            progress.stage !== 'completed' &&
            progress.stage !== 'failed' &&
            progress.stage !== 'cancelled') && (
            <motion.div
              className="absolute inset-y-0 w-20 bg-gradient-to-r from-transparent via-white/30 to-transparent"
              animate={{ left: ['-20%', '120%'] }}
              transition={{ duration: 1.5, repeat: Infinity, ease: 'easeInOut' }}
            />
          )}
        </div>

        {/* 子任务列表 */}
        {!compact && progress.subTasks && progress.subTasks.length > 0 && (
          <div className="space-y-2">
            {progress.subTasks.map((task) => (
              <div key={task.id} className="flex items-center gap-3 text-sm">
                <span>{STATUS_ICONS[task.status]}</span>
                <span className={`flex-1 ${task.status === 'failed' ? 'text-error-600 dark:text-error-600' : task.status === 'completed' ? 'text-neutral-500 dark:text-neutral-400 line-through' : 'text-neutral-700 dark:text-neutral-300'}`}>
                  {task.name}
                </span>
                {task.status === 'running' && task.total != null && (
                  <span className="text-xs text-secondary-600 dark:text-secondary-700 font-medium">
                    ({task.current || 0}/{task.total})
                  </span>
                )}
                {task.status === 'running' && (
                  <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{task.progress}%</span>
                )}
              </div>
            ))}
          </div>
        )}

        {/* 控制按钮组 */}
        <div className="flex items-center justify-between pt-2 border-t border-neutral-100 dark:border-neutral-800">
          <div className="flex gap-2">
            {progress.canPause && progress.stage !== 'paused' && onPause && (
              <button
                onClick={onPause}
                className="flex items-center gap-1.5 px-3 py-1.5 text-sm font-medium text-warning-700 bg-warning-50 dark:bg-warning-300/20 hover:bg-warning-100 dark:hover:bg-warning-900/30 rounded-lg transition-colors"
              >
                <Pause className="w-3.5 h-3.5" />
                暂停
              </button>
            )}

            {progress.stage === 'paused' && onResume && (
              <button
                onClick={onResume}
                className="flex items-center gap-1.5 px-3 py-1.5 text-sm font-medium text-primary-700 bg-primary-50 dark:bg-primary-300/20 hover:bg-primary-100 dark:hover:bg-primary-900/30 rounded-lg transition-colors"
              >
                <Play className="w-3.5 h-3.5" />
                继续
              </button>
            )}

            {progress.canCancel && onCancel && (
              <button
                onClick={() => {
                  if (window.confirm('确定要取消生成吗？当前中间结果将被保留。')) {
                    onCancel()
                  }
                }}
                className="flex items-center gap-1.5 px-3 py-1.5 text-sm font-medium text-error-700 bg-error-50 dark:bg-error-300/20 hover:bg-error-100 dark:hover:bg-error-900/30 rounded-lg transition-colors"
              >
                <Square className="w-3.5 h-3.5" />
                取消
              </button>
            )}

            {progress.stage === 'failed' && onRetry && (
              <button
                onClick={onRetry}
                className="flex items-center gap-1.5 px-3 py-1.5 text-sm font-medium text-secondary-700 bg-secondary-50 dark:bg-secondary-300/20 hover:bg-secondary-100 dark:hover:bg-secondary-900/30 rounded-lg transition-colors"
              >
                <Loader2 className="w-3.5 h-3.5" />
                重试
              </button>
            )}
          </div>

          {/* 日志面板切换 */}
          {!compact && progress.logs && progress.logs.length > 0 && (
            <button
              onClick={() => setShowLogs(!showLogs)}
              className="flex items-center gap-1.5 px-3 py-1.5 text-sm font-medium text-neutral-600 dark:text-neutral-400 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg transition-colors"
            >
              {showLogs ? <ChevronUp className="w-3.5 h-3.5" /> : <ChevronDown className="w-3.5 h-3.5" />}
              日志 ({progress.logs.length})
            </button>
          )}
        </div>

        {/* 日志面板 */}
        <AnimatePresence>
          {showLogs && progress.logs && progress.logs.length > 0 && (
            <motion.div
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: 'auto', opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              className="overflow-hidden"
            >
              <div className="mt-3 p-3 bg-neutral-900 dark:bg-black rounded-lg font-mono text-xs max-h-48 overflow-y-auto">
                <div className="flex items-center justify-between mb-2 pb-2 border-b border-neutral-700">
                  <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">实时日志</span>
                  <button
                    onClick={handleCopyLogs}
                    className="flex items-center gap-1 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-white transition-colors"
                  >
                    <Copy className="w-3 h-3" />
                    复制
                  </button>
                </div>
                <div className="space-y-1">
                  {progress.logs.map((log, index) => (
                    <div
                      key={index}
                      className={`${
                        log.level === 'ERROR'
                          ? 'text-error-400'
                          : log.level === 'WARN'
                          ? 'text-warning-400'
                          : 'text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]'
                      }`}
                    >
                      <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">[{log.timestamp}]</span>{' '}
                      <span
                        className={
                          log.level === 'ERROR'
                            ? 'text-error-500'
                            : log.level === 'WARN'
                            ? 'text-warning-500'
                            : 'text-info-400'
                        }
                      >
                        [{log.level}]
                      </span>{' '}
                      {log.message}
                    </div>
                  ))}
                  <div ref={logsEndRef} />
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </motion.div>
  )
}

export function useGenerationProgressState() {
  const [state, setState] = useState<GenerationProgressState>({
    stage: 'idle',
    overallProgress: 0,
    currentStageName: '',
    subTasks: [],
    logs: [],
    startTime: null,
    estimatedRemainingTime: null,
    canPause: true,
    canCancel: true,
  })

  const addLog = useCallback((level: LogEntry['level'], message: string) => {
    setState(prev => ({
      ...prev,
      logs: [
        ...prev.logs,
        {
          timestamp: formatTimestamp(new Date()),
          level,
          message,
        },
      ],
    }))
  }, [])

  const updateSubTask = useCallback((taskId: string, updates: Partial<SubTask>) => {
    setState(prev => ({
      ...prev,
      subTasks: prev.subTasks.map(task =>
        task.id === taskId ? { ...task, ...updates } : task,
      ),
    }))
  }, [])

  const startGeneration = useCallback(() => {
    const now = Date.now()
    setState({
      stage: 'preparing',
      overallProgress: 0,
      currentStageName: '正在准备...',
      subTasks: [
        { id: 'generate', name: '候选生成', status: 'pending', progress: 0, total: 50 },
        { id: 'score', name: '评分计算', status: 'pending', progress: 0, total: 50 },
        { id: 'optimize', name: '排序优化', status: 'pending', progress: 0 },
        { id: 'finalize', name: '结果整理', status: 'pending', progress: 0 },
      ],
      logs: [],
      startTime: now,
      estimatedRemainingTime: null,
      canPause: true,
      canCancel: true,
    })
    addLog('INFO', '配方生成任务启动')
  }, [addLog])

  const completeGeneration = useCallback((success = true) => {
    setState(prev => ({
      ...prev,
      stage: success ? 'completed' : 'failed',
      overallProgress: 100,
      canPause: false,
      canCancel: false,
    }))
    addLog(success ? 'INFO' : 'ERROR', success ? '配方生成完成' : '配方生成失败')
  }, [addLog])

  const pauseGeneration = useCallback(() => {
    setState(prev => ({ ...prev, stage: 'paused', canPause: false }))
    addLog('WARN', '生成任务已暂停')
  }, [addLog])

  const resumeGeneration = useCallback(() => {
    setState(prev => ({ ...prev, stage: prev.subTasks.some(t => t.status === 'running') ? 'generating' : 'preparing', canPause: true }))
    addLog('INFO', '生成任务已恢复')
  }, [addLog])

  const cancelGeneration = useCallback(() => {
    setState(prev => ({
      ...prev,
      stage: 'cancelled',
      canPause: false,
      canCancel: false,
    }))
    addLog('WARN', '生成任务已取消，保留中间结果')
  }, [addLog])

  return {
    state,
    setState,
    addLog,
    updateSubTask,
    startGeneration,
    completeGeneration,
    pauseGeneration,
    resumeGeneration,
    cancelGeneration,
  }
}

