/**
 * 创建可控制的 Mock 函数（记录调用历史）
 */
export function createTrackedMock<T extends (...args: any[]) => any>(fn: T): T & { callHistory: any[][] } {
  const history: any[][] = []

  const trackedFn = ((...args: any[]) => {
    history.push(args)
    return fn(...args)
  }) as T & { callHistory: any[][] }

  trackedFn.callHistory = history

  return trackedFn
}

