  STORAGE_KEY: 'test-chat-storage',
  SESSION_KEY: 'test-session-storage',
  MOCK_DELAY: 100,
  ERROR_MESSAGE: '测试错误消息',
};

export interface MockMessage {
  id: string;
  role: 'user' | 'assistant' | 'system';
  content: string;
  timestamp: number;
  formulaIds?: string[];
  metadata?: Record<string, any>;
}

export interface MockAIResponse {
  id: string;
  content: string;
  reasoning?: string;
  formulaIds?: string[];
  metadata?: Record<string, any>;
}

export function createMockMessage(overrides?: Partial<MockMessage>): MockMessage {
  return {
    id: overrides?.id || `${TEST_CONSTANTS.DEFAULT_MESSAGE_ID}-${Date.now()}`,
    role: overrides?.role || 'user',
    content: overrides?.content || '测试消息内容',
    timestamp: overrides?.timestamp || Date.now(),
    formulaIds: overrides?.formulaIds,
    metadata: overrides?.metadata,
  };
}

export function createMockAIResponse(overrides?: Partial<MockAIResponse>): MockAIResponse {
  return {
    id: `resp-${Date.now()}`,
    content: overrides?.content || 'AI 响应内容',
    reasoning: overrides?.reasoning,
    formulaIds: overrides?.formulaIds,
    metadata: overrides?.metadata,
  };
}

export function createMockMessagesArray(count: number, role: 'user' | 'assistant' = 'user'): MockMessage[] {
  return Array.from({ length: count }, (_, i) =>
    createMockMessage({
      id: `msg-${i + 1}`,
      role,
      content: `测试消息 ${i + 1}`,
      timestamp: Date.now() - (count - i) * 1000,
    })
  );
}

export function createMockError(message: string = TEST_CONSTANTS.ERROR_MESSAGE): Error {
  return new Error(message);
}

export function createMockSession(
  id: string = TEST_CONSTANTS.DEFAULT_SESSION_ID,
  messageCount: number = 5
) {
  return {
    id,
    title: `测试会话 ${id}`,
    messages: createMockMessagesArray(messageCount),
    createdAt: Date.now() - 86400000,
    updatedAt: Date.now(),
    metadata: {},
  };
}

export function createMockFormula(id: string = 'formula-1') {
  return {
    id,
    name: `测试配方 ${id}`,
    ingredients: [
      { name: '人参', dosage: '10g', role: '君药' },
      { name: '黄芪', dosage: '15g', role: '臣药' },
    ],
    effects: ['补气', '增强免疫力'],
    safetyLevel: 'low',
    scores: {
      synergy: 0.85,
      taste: 0.72,
      stability: 0.90,
      overall: 0.82,
    },
  };
}

export function createMockStorageData<T>(data: T, expiresInMs?: number) {
  return {
    data,
    version: 8,
    timestamp: Date.now(),
    expiresAt: expiresInMs ? Date.now() + expiresInMs : undefined,
  };
}

export function wait(ms: number = TEST_CONSTANTS.MOCK_DELAY): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}

export function mockConsoleLog() {
  return jest.spyOn(console, 'log').mockImplementation(() => {});
}

export function mockConsoleError() {
  return jest.spyOn(console, 'error').mockImplementation(() => {});
}

export function cleanupMocks(...mocks: jest.SpyInstance[]) {
  mocks.forEach(mock => mock.mockRestore());
}

import { renderHook, act } from '@testing-library/react'
import '@testing-library/jest-dom'
import { describe, it, expect, beforeEach, vi, Mock } from 'vitest'
import { useChatMessages } from '../../../hooks/useChatMessages'
import { chatService } from '../../../services/chatService'
import { storageService } from '../../../services/storageService'
import { eventBus } from '../../../services/eventBus'

// 当前 useChatMessages 以模块单例方式依赖各服务
vi.mock('../../../services/chatService', () => ({
  chatService: {
    sendMessage: vi.fn().mockResolvedValue({ content: '非流式回复', role: 'assistant', formulas: [], timestamp: 0 }),
    sendMessageStream: vi.fn(),
    clearAuthToken: vi.fn(),
    closeAllPendingRequests: vi.fn(),
    retryLastMessage: vi.fn().mockResolvedValue({ content: '重试回复', role: 'assistant', formulas: [], timestamp: 0 }),
  },
}))

vi.mock('../../../services/storageService', () => ({
  storageService: {
    get: vi.fn(() => null),
    set: vi.fn(),
    remove: vi.fn(),
  },
}))

vi.mock('../../../services/eventBus', () => ({
  eventBus: {
    emit: vi.fn(),
    subscribe: vi.fn(() => vi.fn()),
  },
}))

vi.mock('../../../capabilities/storage/ChatStorageService', () => ({
  chatStorageService: {
    saveMessages: vi.fn().mockResolvedValue(undefined),
    deleteMessages: vi.fn().mockResolvedValue(undefined),
  },
}))

function makeMessage(id: string, role: 'user' | 'assistant', content: string) {
  return { id, role, content, timestamp: Date.now() }
}

describe('useChatMessages', () => {
  beforeEach(() => {
    vi.clearAllMocks()
  })

  it('应初始化为空状态', () => {
    const { result } = renderHook(() => useChatMessages())

    expect(result.current.messages).toEqual([])
    expect(result.current.input).toBe('')
    expect(result.current.isStreaming).toBe(false)
    expect(result.current.chatError).toBeNull()
    expect(result.current.isPaused).toBe(false)
  })

  it('setInput 应更新输入内容', () => {
    const { result } = renderHook(() => useChatMessages())

    act(() => {
      result.current.setInput('你好')
    })

    expect(result.current.input).toBe('你好')
  })

  it('addMessage / updateMessage / removeMessage / clearMessages 应正确维护消息列表', () => {
    const { result } = renderHook(() => useChatMessages())

    const userMsg = makeMessage('u1', 'user', '你好')

    act(() => {
      result.current.addMessage(userMsg)
    })
    expect(result.current.messages).toHaveLength(1)

    act(() => {
      result.current.updateMessage('u1', { content: '你好呀' })
    })
    expect(result.current.messages[0].content).toBe('你好呀')

    act(() => {
      result.current.addMessage(makeMessage('a1', 'assistant', '回复'))
    })
    expect(result.current.messages).toHaveLength(2)

    act(() => {
      result.current.removeMessage('u1')
    })
    expect(result.current.messages).toHaveLength(1)
    expect(result.current.messages[0].id).toBe('a1')

    act(() => {
      result.current.clearMessages()
    })
    expect(result.current.messages).toHaveLength(0)
  })

  it('sendMessage 应通过流式接口累加回复', async () => {
    ;(chatService.sendMessageStream as Mock).mockImplementation(async function* () {
      yield { done: false, content: '流式' }
      yield { done: false, content: '回复' }
      yield { done: true, content: '' }
    })

    const { result } = renderHook(() => useChatMessages())

    await act(async () => {
      await result.current.sendMessage('你好')
    })

    expect(result.current.messages.length).toBeGreaterThanOrEqual(2)
    const assistantMessages = result.current.messages.filter((m) => m.role === 'assistant')
    expect(assistantMessages.length).toBeGreaterThan(0)
    expect(assistantMessages[assistantMessages.length - 1].content).toContain('流式回复')
    expect(result.current.isStreaming).toBe(false)
  })

  it('sendMessage 流式失败时应回退到非流式接口', async () => {
    ;(chatService.sendMessageStream as Mock).mockImplementation(async function* () {
      throw new Error('Network error')
    })
    ;(chatService.sendMessage as Mock).mockResolvedValue({
      content: '回退回复',
      role: 'assistant',
      formulas: [],
      timestamp: 0,
    })

    const { result } = renderHook(() => useChatMessages())

    await act(async () => {
      await result.current.sendMessage('你好')
    })

    const assistantMessages = result.current.messages.filter((m) => m.role === 'assistant')
    expect(assistantMessages.length).toBeGreaterThan(0)
    expect(assistantMessages[assistantMessages.length - 1].content).toContain('回退回复')
  })

  it('setChatError / clearError 应维护错误状态', () => {
    const { result } = renderHook(() => useChatMessages())

    act(() => {
      result.current.setChatError(new Error('测试错误'))
    })
    expect(result.current.chatError?.message).toBe('测试错误')

    act(() => {
      result.current.clearError()
    })
    expect(result.current.chatError).toBeNull()
  })

  it('setActiveSessionId 应更新会话 ID', () => {
    const { result } = renderHook(() => useChatMessages())

    act(() => {
      result.current.setActiveSessionId('session-1')
    })

    expect(result.current.messages).toEqual([])
    // setActiveSessionId 更新内部引用，不直接暴露；此处仅验证可调用不抛错
    expect(typeof result.current.setActiveSessionId).toBe('function')
  })

  it('retryLastMessage 应调用 chatService 重试', async () => {
    ;(chatService.sendMessageStream as Mock).mockImplementation(async function* () {
      yield { done: true, content: '' }
    })
    ;(chatService.sendMessage as Mock).mockResolvedValue({
      content: '重试结果',
      role: 'assistant',
      formulas: [],
      timestamp: 0,
    })

    const { result } = renderHook(() => useChatMessages())

    await act(async () => {
      await result.current.sendMessage('第一条')
    })

    await act(async () => {
      await result.current.retryLastMessage()
    })

    // 重试会再次产生一条 assistant 消息
    const assistantMessages = result.current.messages.filter((m) => m.role === 'assistant')
    expect(assistantMessages.length).toBeGreaterThan(0)
  })

  it('eventBus 的 auth:required 订阅应被注册', () => {
    renderHook(() => useChatMessages())

    expect(eventBus.subscribe).toHaveBeenCalledWith(
      'auth:required',
      expect.any(Function),
    )
  })
})

/**
 * useChatSessions 单元测试
 *
 * 测试覆盖：
 * - 会话 CRUD 操作（创建/切换/删除/重命名）
 * - 会话置顶功能
 * - 会话搜索和过滤
 * - 会话导出/导入数据完整性
 * - 边界条件处理
 *
 * @version 1.0.0
 */

import { renderHook, act, waitFor } from '@testing-library/react'
import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest'
import { useChatSessions } from '../../../hooks/useChatSessions'

describe('useChatSessions', () => {
  let consoleWarnSpy: ReturnType<typeof vi.spyOn>
  let consoleErrorSpy: ReturnType<typeof vi.spyOn>

  beforeEach(() => {
    localStorage.clear()
    consoleWarnSpy = vi.spyOn(console, 'warn').mockImplementation(() => {})
    consoleErrorSpy = vi.spyOn(console, 'error').mockImplementation(() => {})
  })

  afterEach(() => {
    consoleWarnSpy.mockRestore()
    consoleErrorSpy.mockRestore()
  })

  describe('初始化', () => {
    it('应正确初始化为空状态', () => {
      const { result } = renderHook(() => useChatSessions())

      expect(result.current.sessions).toEqual([])
      expect(result.current.activeSessionId).toBeNull()
      expect(result.current.getStats()).toEqual({
        totalSessions: 0,
        totalMessages: 0,
        pinnedCount: 0,
      })
    })

    it('应从 localStorage 恢复已保存的会话', async () => {
      const savedSessions = [
        {
          id: 'session_1',
          title: '测试会话',
          createdAt: Date.now() - 1000,
          updatedAt: Date.now(),
          messageCount: 5,
          tags: ['test'],
          pinned: false,
        },
      ]

      localStorage.setItem(
        'rmfood_chat_sessions_v1',
        JSON.stringify(savedSessions)
      )

      const { result } = renderHook(() => useChatSessions())
      expect(result.current.sessions.length).toBe(1)
      expect(result.current.sessions[0].title).toBe('测试会话')
    })
  })

  describe('会话 CRUD 操作', () => {
    describe('createSession', () => {
      it('应成功创建新会话并返回 ID', () => {
        const { result } = renderHook(() => useChatSessions())

        let sessionId: string

        act(() => {
          sessionId = result.current.createSession('新对话')
        })

        expect(result.current.sessions.length).toBe(1)
        expect(result.current.activeSessionId).toBe(sessionId)
        expect(result.current.sessions[0].title).toBe('新对话')
        expect(result.current.sessions[0].messageCount).toBe(0)
        expect(result.current.sessions[0].pinned).toBe(false)
        expect(result.current.sessions[0].tags).toEqual([])
      })

      it('不传标题时应使用默认标题', () => {
        const { result } = renderHook(() => useChatSessions())

        act(() => {
          result.current.createSession()
        })

        expect(result.current.sessions[0].title).toBe('新对话')
      })

      it('新创建的会话应添加到列表开头', () => {
        const { result } = renderHook(() => useChatSessions())

        act(() => {
          result.current.createSession('第一个')
          result.current.createSession('第二个')
        })

        expect(result.current.sessions.length).toBe(2)
        expect(result.current.sessions[0].title).toBe('第二个')
        expect(result.current.sessions[1].title).toBe('第一个')
      })

      it('超过最大限制时应抛出错误', () => {
        const { result } = renderHook(() => useChatSessions())

        expect(() => {
          for (let i = 0; i <= 101; i++) {
            act(() => {
              try {
                result.current.createSession(`会话 ${i}`)
              } catch (e) {
                if (i === 100) throw e
              }
            })
          }
        }).toThrow()

        expect(consoleWarnSpy).toHaveBeenCalled()
      })
    })

    describe('switchSession', () => {
      it('应成功切换活跃会话', () => {
        const { result } = renderHook(() => useChatSessions())

        let id1: string, id2: string

        act(() => {
          id1 = result.current.createSession('会话1')
          id2 = result.current.createSession('会话2')
        })

        act(() => {
          result.current.switchSession(id1!)
        })

        expect(result.current.activeSessionId).toBe(id1)

        act(() => {
          result.current.switchSession(id2!)
        })

        expect(result.current.activeSessionId).toBe(id2)
      })

      it('切换到不存在的会话时应警告', () => {
        const { result } = renderHook(() => useChatSessions())

        act(() => {
          result.current.switchSession('non_existent_id')
        })

        expect(consoleWarnSpy).toHaveBeenCalledWith(
          expect.stringContaining('目标会话不存在')
        )
      })
    })

    describe('deleteSession', () => {
      it('应成功删除指定会话', () => {
        const { result } = renderHook(() => useChatSessions())

        let sessionId: string

        act(() => {
          sessionId = result.current.createSession('待删除')
          result.current.createSession('保留')
        })

        expect(result.current.sessions.length).toBe(2)

        act(() => {
          result.current.deleteSession(sessionId!)
        })

        expect(result.current.sessions.length).toBe(1)
        expect(result.current.sessions[0].title).toBe('保留')
      })

      it('删除当前活跃会话时应自动切换', () => {
        const { result } = renderHook(() => useChatSessions())

        let id1: string, id2: string

        act(() => {
          id1 = result.current.createSession('会话1')
          id2 = result.current.createSession('会话2')
        })

        act(() => {
          result.current.deleteSession(id2!)
        })

        expect(result.current.activeSessionId).toBe(id1)
      })

      it('删除唯一会话时 activeSessionId 应为 null', () => {
        const { result } = renderHook(() => useChatSessions())

        let sessionId: string

        act(() => {
          sessionId = result.current.createSession('唯一会话')
        })

        act(() => {
          result.current.deleteSession(sessionId!)
        })

        expect(result.current.activeSessionId).toBeNull()
        expect(result.current.sessions.length).toBe(0)
      })
    })

    describe('renameSession', () => {
      it('应成功重命名会话', () => {
        const { result } = renderHook(() => useChatSessions())

        let sessionId: string

        act(() => {
          sessionId = result.current.createSession('原始名称')
        })

        act(() => {
          result.current.renameSession(sessionId!, '新名称')
        })

        expect(result.current.sessions[0].title).toBe('新名称')
      })

      it('标题过长时应自动截断', () => {
        const { result } = renderHook(() => useChatSessions())

        let sessionId: string

        act(() => {
          sessionId = result.current.createSession('短名称')
        })

        const longTitle = 'A'.repeat(60)

        act(() => {
          result.current.renameSession(sessionId!, longTitle)
        })

        expect(result.current.sessions[0].title.length).toBe(50)
      })

      it('空标题时应拒绝重命名', () => {
        const { result } = renderHook(() => useChatSessions())

        let sessionId: string

        act(() => {
          sessionId = result.current.createSession('原始')
        })

        act(() => {
          result.current.renameSession(sessionId!, '')
        })

        expect(result.current.sessions[0].title).toBe('原始')
        expect(consoleWarnSpy).toHaveBeenCalled()
      })
    })
  })

  describe('置顶功能', () => {
    it('应切换会话的置顶状态', () => {
      const { result } = renderHook(() => useChatSessions())

      let sessionId: string

      act(() => {
        sessionId = result.current.createSession('置顶测试')
      })

      expect(result.current.sessions[0].pinned).toBe(false)

      act(() => {
        result.current.pinSession(sessionId!)
      })

      expect(result.current.sessions[0].pinned).toBe(true)

      act(() => {
        result.current.pinSession(sessionId!)
      })

      expect(result.current.sessions[0].pinned).toBe(false)
    })

    it('置顶会话应在排序中优先显示', () => {
      const { result } = renderHook(() => useChatSessions())

      let id1: string, id2: string

      act(() => {
        id1 = result.current.createSession('普通会话')
        id2 = result.current.createSession('置顶会话')
        result.current.pinSession(id2!)
      })

      expect(result.current.sessions[0].id).toBe(id2)
      expect(result.current.sessions[0].pinned).toBe(true)
      expect(result.current.sessions[1].id).toBe(id1)
      expect(result.current.sessions[1].pinned).toBe(false)
    })

    it('getStats 应正确统计置顶数量', () => {
      const { result } = renderHook(() => useChatSessions())

      let id1: string, id3: string

      act(() => {
        id1 = result.current.createSession('会话1')
        result.current.createSession('会话2')
        id3 = result.current.createSession('会话3')

        result.current.pinSession(id1!)
        result.current.pinSession(id3!)
      })

      const stats = result.current.getStats()
      expect(stats.pinnedCount).toBe(2)
      expect(stats.totalSessions).toBe(3)
    })
  })

  describe('搜索和过滤', () => {
    it('应根据关键词搜索会话', () => {
      const { result } = renderHook(() => useChatSessions())

      act(() => {
        result.current.createSession('配方开发咨询')
        result.current.createSession('营养成分分析')
        result.current.createSession('工艺优化建议')
      })

      const results = result.current.searchSessions('配方')
      expect(results.length).toBe(1)
      expect(results[0].title).toContain('配方')
    })

    it('空查询时应返回所有会话', () => {
      const { result } = renderHook(() => useChatSessions())

      act(() => {
        result.current.createSession('会话A')
        result.current.createSession('会话B')
      })

      const results = result.current.searchSessions('')
      expect(results.length).toBe(2)
    })

    it('搜索结果应按置顶和时间排序', () => {
      const { result } = renderHook(() => useChatSessions())

      let id1: string

      act(() => {
        id1 = result.current.createSession('Alpha')
        result.current.createSession('Beta')
        result.current.createSession('Alpha Beta')

        result.current.pinSession(id1!)
      })

      const results = result.current.searchSessions('Alpha')
      expect(results[0].id).toBe(id1)
      expect(results[0].pinned).toBe(true)
    })
  })

  describe('标签管理', () => {
    it('应设置会话标签', () => {
      const { result } = renderHook(() => useChatSessions())

      let sessionId: string

      act(() => {
        sessionId = result.current.createSession('带标签的会话')
        result.current.setSessionTags(sessionId!, ['重要', '工作'])
      })

      expect(result.current.sessions[0].tags).toEqual(['重要', '工作'])
    })

    it('搜索应支持基于标签的匹配', () => {
      const { result } = renderHook(() => useChatSessions())

      let sessionId: string

      act(() => {
        sessionId = result.current.createSession('某会话')
        result.current.setSessionTags(sessionId!, ['紧急'])
      })

      const results = result.current.searchSessions('紧急')
      expect(results.length).toBe(1)
    })
  })

  describe('导出和导入', () => {
    describe('exportSession', () => {
      it('应以 JSON 格式导出会话', async () => {
        const { result } = renderHook(() => useChatSessions())

        let sessionId: string

        act(() => {
          sessionId = result.current.createSession('导出测试')
        })

        const blob = await result.current.exportSession(sessionId!, 'json')
        const text = await new Promise<string>((resolve) => {
          const reader = new FileReader()
          reader.onload = () => resolve(reader.result as string)
          reader.readAsText(blob)
        })
        const parsed = JSON.parse(text)

        expect(parsed.title).toBe('导出测试')
        expect(parsed.id).toBeDefined()
        expect(parsed.createdAt).toBeDefined()
      })

      it('应以 Markdown 格式导出会话', async () => {
        const { result } = renderHook(() => useChatSessions())

        let sessionId: string

        act(() => {
          sessionId = result.current.createSession('Markdown 导出')
        })

        const blob = await result.current.exportSession(sessionId!, 'markdown')
        const text = await new Promise<string>((resolve) => {
          const reader = new FileReader()
          reader.onload = () => resolve(reader.result as string)
          reader.readAsText(blob)
        })

        expect(text).toContain('# Markdown 导出')
        expect(text).toContain('- **消息数量**:')
      })

      it('导出不存在的会话时应抛出错误', async () => {
        const { result } = renderHook(() => useChatSessions())

        await expect(
          result.current.exportSession('non_existent', 'json')
        ).rejects.toThrow('会话不存在')
      })
    })

    describe('importSession', () => {
      it('应从 JSON 数据导入会话', async () => {
        const { result } = renderHook(() => useChatSessions())

        const exportData = {
          id: 'original_session',
          title: '导入测试',
          createdAt: Date.now() - 86400000,
          updatedAt: Date.now() - 3600000,
          messageCount: 10,
          tags: ['测试'],
          pinned: false,
        }

        const newSessionId = await result.current.importSession(
          JSON.stringify(exportData)
        )

        await waitFor(() => {
          expect(result.current.sessions.length).toBe(1)
          expect(result.current.activeSessionId).toBe(newSessionId)
          expect(result.current.sessions[0].title).toContain('导入测试')
          expect(result.current.sessions[0].title).toContain('(已导入)')
        })
      })

