import { renderHook, act } from '@testing-library/react'
import '@testing-library/jest-dom'
import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest'
import { useStreamingText } from '../../../hooks/useStreamingText'
import { TEST_CONSTANTS } from '../../helpers/testFactories'

/**
 * useStreamingText 单元测试（对齐 v7.1 当前 API）
 * 当前返回值：displayedText / formattedHtml / isComplete / progress /
 * appendChunk / reset / interrupt / resume / getFormattingStats / reformat / getFormattingMode
 */
describe('useStreamingText', () => {
  beforeEach(() => {
    vi.useFakeTimers()
  })

  afterEach(() => {
    vi.useRealTimers()
  })

  /** 推进打字机动画帧，使缓冲文本刷新到 displayedText */
  const flush = () => {
    act(() => {
      vi.advanceTimersByTime(3000)
    })
  }

  describe('打字机效果', () => {
    it('应逐步显示流式文本内容', () => {
      const { result } = renderHook(() => useStreamingText())

      const chunks = ['Hello', ', ', 'World', '!']
      chunks.forEach(chunk => {
        act(() => {
          result.current.appendChunk(chunk)
        })
      })
      flush()

      expect(result.current.displayedText).toBe('Hello, World!')
      expect(result.current.isComplete).toBe(true)
    })

    it('应实时更新当前显示的文本', () => {
      const { result } = renderHook(() => useStreamingText())

      act(() => {
        result.current.appendChunk('第一部分')
      })
      flush()
      expect(result.current.displayedText).toBe('第一部分')

      act(() => {
        result.current.appendChunk(' 第二部分')
      })
      flush()
      expect(result.current.displayedText).toBe('第一部分 第二部分')
    })

    it('应处理空 chunk', () => {
      const { result } = renderHook(() => useStreamingText())

      act(() => {
        result.current.appendChunk('')
      })
      flush()

      expect(result.current.displayedText).toBe('')
    })
  })

  describe('流式状态管理', () => {
    it('应在完成后标记 isComplete', () => {
      const { result } = renderHook(() => useStreamingText())

      act(() => {
        result.current.appendChunk('完整文本')
      })
      flush()

      expect(result.current.isComplete).toBe(true)
      expect(result.current.displayedText).toBe('完整文本')
    })

    it('appendChunk 后应推进文本显示', () => {
      const { result } = renderHook(() => useStreamingText())

      act(() => {
        result.current.appendChunk('一段文本')
      })
      flush()

      expect(result.current.displayedText).toBe('一段文本')
      expect(result.current.isComplete).toBe(true)
    })
  })

  describe('中断与恢复', () => {
    it('应支持中断当前的流式传输', () => {
      const { result } = renderHook(() => useStreamingText())

      act(() => {
        result.current.appendChunk('部分内容')
        // 在动画尚未 flush 前立即中断
        result.current.interrupt()
      })
      flush()

      // 中断后缓冲不再输出
      expect(result.current.displayedText).not.toBe('部分内容')
      expect(result.current.isComplete).toBe(false)
    })

    it('应从中断点恢复流式传输', () => {
      const { result } = renderHook(() => useStreamingText())

      act(() => {
        result.current.appendChunk('中断前 ')
      })
      flush()
      act(() => {
        result.current.interrupt()
      })
      act(() => {
        result.current.resume()
        result.current.appendChunk('恢复后')
      })
      flush()

      expect(result.current.displayedText).toBe('中断前 恢复后')
      expect(result.current.isComplete).toBe(true)
    })
  })

  describe('重置功能', () => {
    it('应完全重置所有状态', () => {
      const { result } = renderHook(() => useStreamingText())

      act(() => {
        result.current.appendChunk('要清除的文本')
      })
      flush()
      act(() => {
        result.current.interrupt()
        result.current.reset()
      })

      expect(result.current.displayedText).toBe('')
      expect(result.current.isComplete).toBe(false)
      expect(result.current.progress).toBe(0)
    })
  })

  describe('性能优化', () => {
    it('应高效处理大量 chunk（1000+）', () => {
      const { result } = renderHook(() => useStreamingText())

      const startTime = performance.now()

      act(() => {
        for (let i = 0; i < 1000; i++) {
          result.current.appendChunk(`chunk${i} `)
        }
      })
      flush()

      const endTime = performance.now()

      expect(result.current.displayedText.length).toBeGreaterThan(0)
      expect(endTime - startTime).toBeLessThan(5000)
    })

    it('不应因无关操作引起不必要的重置', () => {
      const { result } = renderHook(() => useStreamingText())

      act(() => {
        result.current.appendChunk('test')
      })
      flush()

      expect(result.current.displayedText).toBe('test')
    })
  })

  describe('Markdown 实时渲染', () => {
    it('应生成可渲染的 Markdown HTML', () => {
      const { result } = renderHook(() => useStreamingText({ formattingMode: 'markdown' }))

      act(() => {
        result.current.appendChunk('# 标题\n\n')
        result.current.appendChunk('这是**加粗**文本')
      })
      flush()

      expect(result.current.formattedHtml).toContain('h1')
      expect(result.current.formattedHtml).toContain('strong')
    })

    it('应处理不完整的 Markdown 标记而不崩溃', () => {
      const { result } = renderHook(() => useStreamingText({ formattingMode: 'markdown' }))

      act(() => {
        result.current.appendChunk('未完成的**加粗')
      })
      flush()

      expect(result.current.formattedHtml.length).toBeGreaterThan(0)
    })
  })

  describe('格式化统计', () => {
    it('应返回格式统计信息', () => {
      const { result } = renderHook(() => useStreamingText())

      act(() => {
        result.current.appendChunk('文本')
      })
      flush()

      const stats = result.current.getFormattingStats()
      expect(stats).toBeDefined()
      expect(stats.totalCharacters).toBeGreaterThan(0)
    })

    it('reformat 不应抛出异常', () => {
      const { result } = renderHook(() => useStreamingText({ formattingMode: 'markdown' }))

      act(() => {
        result.current.appendChunk('# 标题')
      })
      flush()

      expect(() => {
        act(() => {
          result.current.reformat()
        })
      }).not.toThrow()
    })
  })
})

/**
 * Verifies the ChatState context plumbing added for the report generator:
 * ChatTab's "生成报告" button was previously a stub that only showed a
 * "not available" notice, because handleGenerateReport / setShowReportModal
 * were never exposed through ChatStateContext even though useReportGenerator
 * provides a fully working client-side report generator.
 */
import '@testing-library/jest-dom'
import { describe, it, expect, beforeEach, vi } from 'vitest'
import * as React from 'react'
import { render } from '@testing-library/react'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { ChatStateProvider } from '../../ChatStateProvider'
import { useChatState } from '../../ChatStateContext'
import type { ChatState } from '../../ChatStateContext'

/** Reads the live context shape and stamps it onto the container element. */
function Probe({ _ }: { _?: never }) {
  const ctx = useChatState() as Partial<ChatState>
  return React.createElement('div', {
    'data-testid': 'probe',
    'data-gen': typeof ctx.handleGenerateReport,
    'data-set-modal': typeof ctx.setShowReportModal,
    'data-report-modal': String(Boolean(ctx.showReportModal)),
    'data-generating': String(Boolean(ctx.isGeneratingReport)),
    'data-formula-count': String(ctx.formulaCount ?? 'missing'),
  })
}

function renderWithProviders() {
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } })
  return render(
    React.createElement(
      QueryClientProvider,
      { client },
      React.createElement(ChatStateProvider, null,
        React.createElement(Probe as React.ComponentType<object>)),
    ),
  )
}

describe('ChatStateContext report plumbing', () => {
  beforeEach(() => {
    // 静默掉 provider 内部的 react-query 网络调用
    vi.spyOn(globalThis, 'fetch').mockResolvedValue(new Response('{}', { status: 200 }))
  })

  it('exposes handleGenerateReport as a callable function', () => {
    const { container } = renderWithProviders()
    const probe = container.querySelector('[data-testid="probe"]')!
    expect(probe.getAttribute('data-gen')).toBe('function')
  })

  it('exposes setShowReportModal so the report modal can be closed', () => {
    const { container } = renderWithProviders()
    const probe = container.querySelector('[data-testid="probe"]')!
    expect(probe.getAttribute('data-set-modal')).toBe('function')
  })

  it('starts with the report modal closed and not generating', () => {
    const { container } = renderWithProviders()
    const probe = container.querySelector('[data-testid="probe"]')!
    expect(probe.getAttribute('data-report-modal')).toBe('false')
    expect(probe.getAttribute('data-generating')).toBe('false')
  })
})

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest'
import { ChatHistoryStorage } from '../../../services/chatHistoryStorage'
import { ChatSession, ChatTopic, MAX_TAGS_PER_SESSION } from '../../../types/chatHistory.types'

const TEST_DB_NAME = 'RMFOOD_ChatHistory_Test'
const TEST_LOCALSTORAGE_KEY = 'rmfood_chat_history_test'

describe('ChatHistoryStorage', () => {
  let storage: ChatHistoryStorage

  beforeEach(async () => {
    storage = new ChatHistoryStorage({
      indexedDBName: TEST_DB_NAME,
      localStorageKey: TEST_LOCALSTORAGE_KEY,
      maxSessions: 100
    })
    await storage.clearAll()
  })

  afterEach(async () => {
    await storage.clearAll()
  })

  function createTestSession(index: number, topic: ChatTopic = ChatTopic.KNOWLEDGE_QUERY): ChatSession {
    const now = Date.now()
    return {
      id: `session-${index}`,
      title: `测试会话 ${index}`,
      messages: [
        {
          id: `msg-${index}-1`,
          role: 'user',
          content: `用户消息 ${index}`,
          timestamp: now - 1000
        },
        {
          id: `msg-${index}-2`,
          role: 'assistant',
          content: `助手回复 ${index}`,
          timestamp: now
        }
      ],
      metadata: {
        topic,
        tags: [`tag-${index % 5}`, `tag-${(index + 1) % 5}`].slice(0, Math.min(index % 3 + 1, MAX_TAGS_PER_SESSION)),
        createdAt: now - 1000,
        updatedAt: now,
        messageCount: 2
      }
    }
  }

  describe('基本CRUD操作', () => {
    it('应保存和读取单个会话', async () => {
      const session = createTestSession(1, ChatTopic.FORMULA_DESIGN)
      await storage.saveSession(session)

      const retrieved = await storage.getSession(session.id)
      expect(retrieved).not.toBeNull()
      expect(retrieved?.id).toBe(session.id)
      expect(retrieved?.title).toBe(session.title)
      expect(retrieved?.metadata.topic).toBe(ChatTopic.FORMULA_DESIGN)
    })

    it('应返回null当会话不存在时', async () => {
      const retrieved = await storage.getSession('non-existent-id')
      expect(retrieved).toBeNull()
    })

    it('应删除指定会话', async () => {
      const session = createTestSession(1)
      await storage.saveSession(session)

      await storage.deleteSession(session.id)
      const retrieved = await storage.getSession(session.id)
      expect(retrieved).toBeNull()
    })

    it('应清除所有会话', async () => {
      for (let i = 0; i < 5; i++) {
        await storage.saveSession(createTestSession(i))
      }

      await storage.clearAll()
      const sessions = await storage.getAllSessions()
      expect(sessions).toHaveLength(0)
    })
  })

  describe('主题分类', () => {
    it('应支持所有8个预设主题', async () => {
      const topics = Object.values(ChatTopic)
      expect(topics).toHaveLength(8)

      for (let i = 0; i < topics.length; i++) {
        const session = createTestSession(i, topics[i])
        await storage.saveSession(session)
      }

      const sessions = await storage.getAllSessions()
      expect(sessions).toHaveLength(8)

      const sessionByTopic = await storage.getAllSessions({ topic: ChatTopic.FORMULA_DESIGN })
      expect(sessionByTopic).toHaveLength(1)
      expect(sessionByTopic[0].metadata.topic).toBe(ChatTopic.FORMULA_DESIGN)
    })
  })

  describe('标签管理', () => {
    it('应支持最多5个标签', async () => {
      const session: ChatSession = {
        id: 'test-tags',
        title: '标签测试',
        messages: [],
        metadata: {
          topic: ChatTopic.KNOWLEDGE_QUERY,
          tags: ['tag1', 'tag2', 'tag3', 'tag4', 'tag5'],
          createdAt: Date.now(),
          updatedAt: Date.now(),
          messageCount: 0
        }
      }
      await storage.saveSession(session)

      const retrieved = await storage.getSession('test-tags')
      expect(retrieved?.metadata.tags).toHaveLength(5)
    })

    it('应拒绝超过5个标签', async () => {
      const session: ChatSession = {
        id: 'test-tags-exceed',
        title: '标签超限测试',
        messages: [],
        metadata: {
          topic: ChatTopic.KNOWLEDGE_QUERY,
          tags: ['tag1', 'tag2', 'tag3', 'tag4', 'tag5', 'tag6'],
          createdAt: Date.now(),
          updatedAt: Date.now(),
          messageCount: 0
        }
      }

      await expect(storage.saveSession(session)).rejects.toThrow(
        `最多支持 ${MAX_TAGS_PER_SESSION} 个标签`
      )
    })
  })

  describe('100条记录存储测试', () => {
    it('应成功存储100条会话记录', async () => {
      const sessions: ChatSession[] = []
      const topics = Object.values(ChatTopic)

      for (let i = 0; i < 100; i++) {
        const topic = topics[i % topics.length]
        sessions.push(createTestSession(i, topic))
      }

      const startTime = Date.now()
      for (const session of sessions) {
        await storage.saveSession(session)
      }
      const saveTime = Date.now() - startTime

      console.log(`保存100条会话耗时: ${saveTime}ms`)

      const retrieved = await storage.getAllSessions()
      expect(retrieved).toHaveLength(100)
    })

    it('应正确加载100条会话记录', async () => {
      for (let i = 0; i < 100; i++) {
        await storage.saveSession(createTestSession(i))
      }

      const startTime = Date.now()
      const sessions = await storage.getAllSessions()
      const loadTime = Date.now() - startTime

      console.log(`加载100条会话耗时: ${loadTime}ms`)

      expect(sessions).toHaveLength(100)

      const sessionIds = sessions.map(s => s.id)
      expect(sessionIds).toContain('session-0')
      expect(sessionIds).toContain('session-99')

      for (let i = 0; i < sessions.length - 1; i++) {
        expect(sessions[i].metadata.updatedAt).toBeGreaterThanOrEqual(sessions[i + 1].metadata.updatedAt)
      }
    })

    it('100条记录应包含所有主题分布', async () => {
      const topics = Object.values(ChatTopic)
      for (let i = 0; i < 100; i++) {
        const topic = topics[i % topics.length]
        await storage.saveSession(createTestSession(i, topic))
      }

      const stats = await storage.getStatistics()
      expect(stats.totalSessions).toBe(100)
      expect(stats.totalMessages).toBe(200)

      const topicsWithSessions = Object.values(stats.sessionsByTopic).filter(count => count > 0)
      expect(topicsWithSessions).toHaveLength(8)
    })
  })

  describe('搜索与过滤', () => {
    beforeEach(async () => {
      for (let i = 0; i < 20; i++) {
        const topic = i % 2 === 0 ? ChatTopic.FORMULA_DESIGN : ChatTopic.INGREDIENT_ANALYSIS
        await storage.saveSession(createTestSession(i, topic))
      }
    })

    it('应按主题过滤', async () => {
      const sessions = await storage.getAllSessions({ topic: ChatTopic.FORMULA_DESIGN })
      expect(sessions).toHaveLength(10)
      sessions.forEach(session => {
        expect(session.metadata.topic).toBe(ChatTopic.FORMULA_DESIGN)
      })
    })

    it('应按关键词搜索', async () => {
      const sessions = await storage.getAllSessions({ keyword: '测试会话 5' })
      expect(sessions).toHaveLength(1)
      expect(sessions[0].id).toBe('session-5')
    })

    it('应按标签过滤', async () => {
      const sessions = await storage.getAllSessions({ tags: ['tag-0'] })
      expect(sessions.length).toBeGreaterThan(0)
    })

    it('应按日期范围过滤', async () => {
      const now = Date.now()
      const sessions = await storage.getAllSessions({
        dateFrom: now - 10000,
        dateTo: now + 10000
      })
      expect(sessions).toHaveLength(20)
    })
  })

  describe('统计信息', () => {
    it('应返回正确的统计信息', async () => {
      for (let i = 0; i < 10; i++) {
        await storage.saveSession(createTestSession(i))
      }

      const stats = await storage.getStatistics()
      expect(stats.totalSessions).toBe(10)
      expect(stats.totalMessages).toBe(20)
      expect(stats.sessionsLastWeek).toBe(10)
      expect(stats.sessionsLastMonth).toBe(10)
    })

    it('应统计热门标签', async () => {
      for (let i = 0; i < 20; i++) {
        const session = createTestSession(i)
        session.metadata.tags = [`common-tag`, `tag-${i % 3}`]
        await storage.saveSession(session)
      }

      const stats = await storage.getStatistics()
      expect(stats.topTags.length).toBeGreaterThan(0)
      expect(stats.topTags[0].tag).toBe('common-tag')
      expect(stats.topTags[0].count).toBe(20)
    })
  })

  describe('存储限制', () => {
    it('应限制最多100条会话', async () => {
      for (let i = 0; i < 105; i++) {
        await storage.saveSession(createTestSession(i))
      }

      const sessions = await storage.getAllSessions()
      expect(sessions).toHaveLength(100)
    })
  })
})

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest'
import { ChatService } from '../../../services/chatService'
import api from '@/api/client'

// 非流式 sendMessage 走 axios api.post（@/api/client），而非 global.fetch
vi.mock('@/api/client', () => ({
  default: {
    post: vi.fn(),
    get: vi.fn(),
    put: vi.fn(),
    delete: vi.fn(),
  },
}))

// 服务流式路径依赖登录态
vi.mock('@/stores/auth', () => ({
  useAuthStore: {
    getState: () => ({ isAuthenticated: true }),
  },
}))

/** 创建测试服务实例；默认关闭重试，避免定时器交互导致超时 */
function createService(overrides: Record<string, unknown> = {}) {
  const svc = new ChatService({ timeout: 60_000, maxRetries: 0, debounceMs: 0, ...overrides })
  vi.spyOn(svc as any, 'isAuthenticated').mockReturnValue(true)
  return svc
}

describe('ChatService', () => {
  let chatService: ChatService
  const apiPost = api.post as unknown as Mock

  const TEST_TOKEN = 'test-auth-token'

  beforeEach(() => {
    document.cookie = 'csrf_token=test-csrf-token'
    vi.clearAllMocks()
    chatService = createService()
  })

  afterEach(() => {
    vi.restoreAllMocks()
  })

  describe('认证管理', () => {
    it('应正确设置认证令牌', () => {
      chatService.setAuthToken(TEST_TOKEN)
      expect(chatService['authToken']).toBe(TEST_TOKEN)
    })

    it('应正确清除认证令牌', () => {
      chatService.setAuthToken(TEST_TOKEN)
      chatService.clearAuthToken()
      expect(chatService['authToken']).toBeNull()
    })

    it('应在请求头中包含认证令牌', async () => {
      apiPost.mockResolvedValue({ data: { id: '1', content: 'ok', senderId: 'assistant', timestamp: 0, formulas: [] } })
      chatService.setAuthToken(TEST_TOKEN)
      await chatService.sendMessage('test')
      expect(apiPost).toHaveBeenCalled()
    })
  })

  describe('发送消息', () => {
    it('应成功发送消息并返回响应', async () => {
      const mockResponse = { id: 'resp-1', content: '这是AI的回答', senderId: 'assistant', timestamp: 0, formulas: [] }
      apiPost.mockResolvedValue({ data: mockResponse })
      const result = await chatService.sendMessage('你好')
      expect(result.content).toBe(mockResponse.content)
      expect(apiPost).toHaveBeenCalled()
    })

    it('应处理网络超时错误', async () => {
      apiPost.mockRejectedValue(new Error('Network timeout'))
      await expect(chatService.sendMessage('test')).rejects.toThrow()
      expect(chatService.getLastError()).not.toBeNull()
    })

    it('应处理 HTTP 错误状态码', async () => {
      for (const status of [401, 403, 404, 500]) {
        apiPost.mockRejectedValueOnce({ response: { status, data: { detail: `err-${status}` } } })
        await expect(chatService.sendMessage('test')).rejects.toThrow()
      }
    })
  })

  describe('流式消息', () => {
    it('应正确处理流式响应', async () => {
      const sseLines = [
        'event: content',
        'data: {"type":"content","content":"chunk1"}',
        '',
        'event: content',
        'data: {"type":"content","content":"chunk2"}',
        '',
        'event: content',
        'data: {"type":"content","content":"chunk3"}',
        '',
        'data: [DONE]',
        '',
      ]
      let lineIndex = 0
      const encoder = new TextEncoder()
      const mockFetch = vi.fn().mockImplementationOnce(async () => ({
        ok: true,
        body: {
          getReader: () => ({
            read: () => {
              if (lineIndex < sseLines.length) {
                return Promise.resolve({ done: false, value: encoder.encode(sseLines[lineIndex++] + '\n') })
              }
              return Promise.resolve({ done: true, value: null })
            },
            releaseLock: vi.fn(),
          }),
        },
      }))
      global.fetch = mockFetch as any

      const receivedChunks: string[] = []
      const gen = chatService.sendMessageStream('stream test', undefined, { signal: null as any })
      for await (const chunk of gen) {
        if (chunk && chunk.content) receivedChunks.push(chunk.content)
      }

      expect(receivedChunks).toContain('chunk1')
      expect(receivedChunks).toContain('chunk2')
      expect(receivedChunks).toContain('chunk3')
    })
  })

  describe('重试机制', () => {
    it('应自动重试失败的消息发送', async () => {
      vi.useFakeTimers()
      const retryService = createService({ maxRetries: 2 })
      apiPost
        .mockRejectedValueOnce(new Error('Network error'))
        .mockResolvedValueOnce({ data: { id: 'retry-1', content: 'retry response', senderId: 'assistant', timestamp: 0, formulas: [] } })

      // 首次发送内部会重试：第一次网络错误 → 第二次成功
      const p = retryService.sendMessage('重试测试')
      p.catch(() => {}) // 吸收未处理 rejection，避免 Node unhandled 警告
      await vi.advanceTimersByTimeAsync(10_000)
      const result = await p
      expect(result.content).toBe('retry response')
      expect(apiPost.mock.calls.length).toBeGreaterThanOrEqual(2)
      vi.useRealTimers()
    })

    it('应在达到最大重试次数后抛出错误', async () => {
      vi.useFakeTimers()
      const retryService = createService({ maxRetries: 2 })
      apiPost.mockRejectedValue(new Error('Persistent error'))
      const first = retryService.sendMessage('x')
      first.catch(() => {}) // 吸收未处理 rejection
      await vi.advanceTimersByTimeAsync(10_000)
      await expect(first).rejects.toThrow()

      const p = retryService.retryLastMessage()
      p.catch(() => {}) // 吸收未处理 rejection
      await vi.advanceTimersByTimeAsync(10_000)
      await expect(p).rejects.toThrow()
      vi.useRealTimers()
    })
  })

  describe('限流处理', () => {
    it('应正确解析限流状态', async () => {
      apiPost.mockRejectedValueOnce({ response: { status: 429, data: { detail: 'Rate limit exceeded' } } })
      await expect(chatService.sendMessage('rate limit test')).rejects.toThrow()
      expect(chatService.getRateLimitStatus()).toBeDefined()
    })

    it('应在限流时阻止新请求', async () => {
      apiPost.mockRejectedValueOnce({ response: { status: 429, data: { detail: 'Rate limited' } } })
      await expect(chatService.sendMessage('test')).rejects.toThrow()
      expect(chatService.getRateLimitStatus()).toBeDefined()
    })
  })

  describe('错误追踪', () => {
    it('应记录最后一次错误', async () => {
      apiPost.mockRejectedValueOnce(new Error('Test error'))
      await expect(chatService.sendMessage('error test')).rejects.toThrow()
      expect(chatService.getLastError()).not.toBeNull()
    })

    it('成功请求后应清除错误状态', async () => {
      apiPost
        .mockRejectedValueOnce(new Error('First error'))
        .mockResolvedValueOnce({ data: { id: '1', content: 'success', senderId: 'assistant', timestamp: 0, formulas: [] } })

      await expect(chatService.sendMessage('fail')).rejects.toThrow()
      expect(chatService.getLastError()).not.toBeNull()

      await chatService.sendMessage('success')
      expect(chatService.getLastError()).toBeNull()
    })
  })

  describe('请求去重 (Debounce)', () => {
    it('应在短时间内防止重复请求', async () => {
      vi.useFakeTimers()
      const debounceService = createService({ debounceMs: 300, maxRetries: 0 })
      apiPost.mockResolvedValue({ data: { id: '1', content: 'response', senderId: 'assistant', timestamp: 0, formulas: [] } })

      const promises = [
        debounceService.sendMessage('msg1'),
        debounceService.sendMessage('msg2'),
        debounceService.sendMessage('msg3'),
      ]
      await vi.advanceTimersByTimeAsync(1000)
      const results = await Promise.all(promises)
      expect(results[0].content).toBe('response')
      vi.useRealTimers()
    })
  })
})

import { describe, it, expect, beforeEach, vi, Mock } from 'vitest'
import { eventBus } from '../../../services/eventBus'

describe('EventBus', () => {
  beforeEach(() => {
    eventBus.clear()
  })

  afterEach(() => {
    eventBus.clear()
  })

  describe('基础功能', () => {
    it('应提供 EventBus 单例', () => {
      expect(eventBus).toBeDefined()
      expect(typeof eventBus.emit).toBe('function')
      expect(typeof eventBus.subscribe).toBe('function')
      expect(typeof eventBus.once).toBe('function')
      expect(typeof eventBus.clear).toBe('function')
      expect(typeof eventBus.getSubscriberCount).toBe('function')
    })

    it('应正确发布和订阅事件', () => {
      const mockCallback = vi.fn()
      const testData = { content: 'test', timestamp: 123 }

      eventBus.subscribe('message:sending', mockCallback)
      eventBus.emit('message:sending', testData)

      expect(mockCallback).toHaveBeenCalledTimes(1)
      expect(mockCallback).toHaveBeenCalledWith(testData)
    })

    it('应支持多个订阅者监听同一事件', () => {
      const mock1 = vi.fn()
      const mock2 = vi.fn()
      const mock3 = vi.fn()

      eventBus.subscribe('message:received', mock1)
      eventBus.subscribe('message:received', mock2)
      eventBus.subscribe('message:received', mock3)

      eventBus.emit('message:received', { content: 'test', senderId: 's1', timestamp: 1 })

      expect(mock1).toHaveBeenCalledTimes(1)
      expect(mock2).toHaveBeenCalledTimes(1)
      expect(mock3).toHaveBeenCalledTimes(1)
    })

    it('应返回取消订阅函数', () => {
      const mockCallback = vi.fn()

      const unsubscribe = eventBus.subscribe('message:error', mockCallback)
      expect(typeof unsubscribe).toBe('function')

      unsubscribe()
      eventBus.emit('message:error', { error: new Error('test') })

      expect(mockCallback).not.toHaveBeenCalled()
    })
  })

  describe('一次性订阅 (once)', () => {
    it('应只触发一次回调', () => {
      const mockCallback = vi.fn()

      eventBus.once('search:started', mockCallback)

      eventBus.emit('search:started', { query: 'q', timestamp: 1 })
      eventBus.emit('search:started', { query: 'q', timestamp: 2 })
      eventBus.emit('search:started', { query: 'q', timestamp: 3 })

      expect(mockCallback).toHaveBeenCalledTimes(1)
    })

    it('应在触发后自动取消订阅', () => {
      const mockCallback = vi.fn()

      eventBus.once('formulas:detected', mockCallback)
      eventBus.emit('formulas:detected', { formulas: [] })

      expect(eventBus.getSubscriberCount('formulas:detected')).toBe(0)
    })
  })

  describe('清理功能', () => {
    it('应清除指定事件的所有订阅者', () => {
      const mock1 = vi.fn()
      const mock2 = vi.fn()

      eventBus.subscribe('state:changed', mock1)
      eventBus.subscribe('state:changed', mock2)
      eventBus.subscribe('language:changed', vi.fn())

      eventBus.clearEvent('state:changed')

      eventBus.emit('state:changed', { newState: 'x' })
      eventBus.emit('language:changed', { language: 'zh' })

      expect(mock1).not.toHaveBeenCalled()
      expect(mock2).not.toHaveBeenCalled()
    })

    it('应清除所有事件的订阅者', () => {
      const mock1 = vi.fn()
      const mock2 = vi.fn()

      eventBus.subscribe('report:generated', mock1)
      eventBus.subscribe('search:completed', mock2)

      eventBus.clear()

      eventBus.emit('report:generated', { reportUrl: '', reportType: 'x' })
      eventBus.emit('search:completed', { query: 'q', results: 0, timeTaken: 0, timestamp: 0 })

      expect(mock1).not.toHaveBeenCalled()
      expect(mock2).not.toHaveBeenCalled()
    })
  })

  describe('订阅者计数', () => {
    it('应正确返回指定事件的订阅者数量', () => {
      expect(eventBus.getSubscriberCount('message:sending')).toBe(0)

      eventBus.subscribe('message:sending', vi.fn())
      expect(eventBus.getSubscriberCount('message:sending')).toBe(1)

      eventBus.subscribe('message:sending', vi.fn())
      expect(eventBus.getSubscriberCount('message:sending')).toBe(2)
    })

    it('取消订阅后应减少计数', () => {
      const unsub1 = eventBus.subscribe('message:error', vi.fn())
      const unsub2 = eventBus.subscribe('message:error', vi.fn())

      expect(eventBus.getSubscriberCount('message:error')).toBe(2)

      unsub1()
      expect(eventBus.getSubscriberCount('message:error')).toBe(1)

      unsub2()
      expect(eventBus.getSubscriberCount('message:error')).toBe(0)
    })
  })

  describe('事件数据传递', () => {
    it('应正确传递复杂数据对象', () => {
      const mockCallback = vi.fn()
      const complexData = {
        step: 'analysis',
        question: '测试问题',
        timestamp: 123,
      }

      eventBus.subscribe('thinking:step', mockCallback)
      eventBus.emit('thinking:step', complexData)

      expect(mockCallback).toHaveBeenCalledWith(complexData)
      expect(mockCallback.mock.calls[0][0]).toEqual(complexData)
    })
  })

  describe('错误处理', () => {
    it('应捕获并处理订阅者回调中的错误', () => {
      const errorCallback = vi.fn(() => {
        throw new Error('Subscriber error')
      })
      const successCallback = vi.fn()

      console.error = vi.fn()

      eventBus.subscribe('message:sending', errorCallback)
      eventBus.subscribe('message:sending', successCallback)

      expect(() => {
        eventBus.emit('message:sending', { content: 'x', timestamp: 1 })
      }).not.toThrow()

      expect(errorCallback).toHaveBeenCalled()
      expect(successCallback).toHaveBeenCalled()
      expect(console.error).toHaveBeenCalled()
    })
  })

  describe('性能测试', () => {
    it('应高效处理大量事件发布（1000 次）', () => {
      const mockCallback = vi.fn()
      eventBus.subscribe('message:sending', mockCallback)

      const startTime = performance.now()

      for (let i = 0; i < 1000; i++) {
        eventBus.emit('message:sending', { content: `c${i}`, timestamp: i })
      }

      const endTime = performance.now()

      expect(mockCallback).toHaveBeenCalledTimes(1000)
      expect(endTime - startTime).toBeLessThan(500)
    })
  })
})

import { describe, it, expect, beforeEach, afterEach } from 'vitest'
import { StorageService, QuotaExceededError } from '../../../services/storageService'

describe('StorageService', () => {
  let storageService: StorageService
  const testKey = 'test_storage_key'

  beforeEach(() => {
    localStorage.clear()
    storageService = new StorageService(localStorage)
  })

  afterEach(() => {
    localStorage.clear()
  })

  describe('基础 CRUD 操作', () => {
    it('应设置和获取值', () => {
      const testValue = { name: 'test', value: 123 }

      storageService.set(testKey, testValue)
      const result = storageService.get<typeof testValue>(testKey)

      expect(result).toEqual(testValue)
    })

    it('应返回 null 当键不存在', () => {
      const result = storageService.get(testKey)
      expect(result).toBeNull()
    })

    it('应删除指定键', () => {
      storageService.set(testKey, 'test-value')
      expect(storageService.exists(testKey)).toBe(true)

      storageService.remove(testKey)
      expect(storageService.exists(testKey)).toBe(false)
    })

    it('应检查键是否存在', () => {
      expect(storageService.exists(testKey)).toBe(false)

      storageService.set(testKey, 'value')
      expect(storageService.exists(testKey)).toBe(true)
    })
  })

  describe('过期数据处理', () => {
    it('应自动清理过期数据', () => {
      const expiredData = {
        data: 'expired',
        version: 8,
        timestamp: Date.now(),
        expiresAt: Date.now() - 1000, // 已过期
      }
      localStorage.setItem(testKey, JSON.stringify(expiredData))

      const result = storageService.get(testKey)
      expect(result).toBeNull()
      expect(storageService.exists(testKey)).toBe(false)
    })

    it('应保留未过期数据', () => {
      storageService.set(testKey, 'valid', { expiresInMs: 3600000 })

      const result = storageService.get(testKey)
      expect(result).toBe('valid')
    })
  })

  describe('键管理', () => {
    it('应获取所有键', () => {
      storageService.set('prefix_key1', 'value1')
      storageService.set('prefix_key2', 'value2')
      storageService.set('other_key', 'value3')

      const allKeys = storageService.keys()
      expect(allKeys).toHaveLength(3)
    })

    it('应获取匹配前缀的键', () => {
      storageService.set('prefix_key1', 'value1')
      storageService.set('prefix_key2', 'value2')
      storageService.set('other_key', 'value3')

      const prefixKeys = storageService.keys('prefix')
      expect(prefixKeys).toHaveLength(2)
      expect(prefixKeys).toContain('prefix_key1')
      expect(prefixKeys).toContain('prefix_key2')
    })

    it('应清除匹配前缀的键', () => {
      storageService.set('prefix_key1', 'value1')
      storageService.set('prefix_key2', 'value2')
      storageService.set('other_key', 'value3')

      storageService.clearByPrefix('prefix')

      expect(storageService.keys('prefix')).toHaveLength(0)
      expect(storageService.exists('other_key')).toBe(true)
    })
  })

  describe('配额管理', () => {
    it('应在配额超限时抛出 QuotaExceededError', () => {
      // Mock localStorage 抛出配额错误
      const mockStorage = {
        getItem: () => null,
        setItem: () => {
          throw new DOMException('Quota exceeded', 'QuotaExceededError')
        },
        removeItem: () => {},
        key: () => null,
        length: 0,
        clear: () => {},
      }

      const service = new StorageService(mockStorage as unknown as Storage)

      expect(() => {
        service.set('large_data', 'x'.repeat(1000000))
      }).toThrow(QuotaExceededError)
    })
  })

  describe('统计信息', () => {
    it('应返回正确的统计信息', () => {
      storageService.set('key1', 'value1')
      storageService.set('key2', { nested: 'object' })

      const stats = storageService.getStats()

      expect(stats.itemCount).toBe(2)
      expect(stats.used).toBeGreaterThan(0)
      expect(stats.total).toBe(5 * 1024 * 1024)
    })

    it('应处理空存储', () => {
      const stats = storageService.getStats()

      expect(stats.itemCount).toBe(0)
      expect(stats.used).toBe(0)
    })
  })

  describe('清理过期数据', () => {
    it('应清理所有过期数据', () => {
      const expiredData = {
        data: 'expired',
        version: 8,
        timestamp: Date.now(),
        expiresAt: Date.now() - 1000,
      }
      const validData = {
        data: 'valid',
        version: 8,
        timestamp: Date.now(),
        expiresAt: Date.now() + 3600000,
      }

      localStorage.setItem('expired_key', JSON.stringify(expiredData))
      localStorage.setItem('valid_key', JSON.stringify(validData))

      storageService.cleanExpiredData()

      expect(storageService.exists('expired_key')).toBe(false)
      expect(storageService.exists('valid_key')).toBe(true)
    })
  })

  describe('数据版本管理', () => {
    it('应存储版本号和时间戳', () => {
      storageService.set(testKey, 'test_value')

      const raw = localStorage.getItem(testKey)
      const parsed = JSON.parse(raw!)

      expect(parsed.version).toBe(8)
      expect(parsed.timestamp).toBeDefined()
      expect(parsed.data).toBe('test_value')
    })
  })

  describe('错误处理', () => {
    it('应处理无效的 JSON 数据', () => {
      localStorage.setItem(testKey, 'invalid json {{{')

      const result = storageService.get(testKey)
      expect(result).toBeNull()
    })

    it('应处理 null 值', () => {
      storageService.set(testKey, null)
      const result = storageService.get(testKey)
      expect(result).toEqual({ version: 8, timestamp: expect.any(Number), data: null })
    })

    it('应处理 undefined 值', () => {
      storageService.set(testKey, undefined as any)
      const result = storageService.get(testKey)
      expect(result).toEqual({ version: 8, timestamp: expect.any(Number) })
    })
  })

  describe('LRU 缓存', () => {
    it('应限制 LRU 缓存大小', () => {
      // 设置超过 MAX_HISTORY_SIZE 的键
      for (let i = 0; i < 1100; i++) {
        storageService.set(`key_${i}`, `value_${i}`)
      }

      // LRU 缓存应被限制在 1000 以内
      const keys = storageService.keys()
      expect(keys.length).toBe(1100) // localStorage 不受影响
    })
  })

  describe('复杂数据类型', () => {
    it('应支持存储数组', () => {
      const arrayData = [1, 2, 3, { nested: 'object' }]
      storageService.set(testKey, arrayData)

      const result = storageService.get(testKey)
      expect(result).toEqual(arrayData)
    })

    it('应支持存储嵌套对象', () => {
      const nestedData = {
        level1: {
          level2: {
            level3: 'deep',
            array: [1, 2, 3],
          },
        },
      }
      storageService.set(testKey, nestedData)

      const result = storageService.get(testKey)
      expect(result).toEqual(nestedData)
    })

    it('应支持存储 Date 对象（序列化后）', () => {
      const date = new Date('2024-01-01')
      storageService.set(testKey, date.toISOString())

      const result = storageService.get(testKey)
      expect(result).toBe('2024-01-01T00:00:00.000Z')
    })
  })
})

/**
 * SubagentDelegation — 子智能体委托能力
 *
 * 参照 DeepSeek Harness Delegation 设计：
 * - 当用户请求涉及多步骤/多主题时，自动拆解为子任务
 * - 每个子任务可独立发送到后端 API 并行处理
 * - 结果聚合后合并输出
 *
 * @version 1.0.0
 */

import { logger } from '@/utils/safeLogger'
import type { ChatMessage } from '../../types'
import { chatService } from '../../services/chatService'

export interface SubTask {
  /** 唯一 ID */
  id: string
  /** 子任务描述 */
  description: string
  /** 任务类型 */
  type: 'analyze' | 'design' | 'evaluate' | 'compare' | 'summary'
  /** 状态 */
  status: 'pending' | 'running' | 'completed' | 'failed'
  /** 输入提示词 */
  prompt: string
  /** 输出结果 */
  result?: string
  /** 错误信息 */
  error?: string
}

export interface DelegationResult {
  taskId: string
  subtasks: SubTask[]
  finalOutput: string
  /** 是否成功并行完成 */
  parallelDone: boolean
}

export class SubagentDelegationService {
  private runningTasks: Map<string, AbortController> = new Map()

  /**
   * 判断是否需要启动子任务委托
   * 策略：请求包含多个不同主题关键词时触发
   */
  shouldDelegate(input: string, messages: ChatMessage[]): boolean {
    if (messages.length > 30) return false // 长对话不触发（已在压缩中）

    const keywords = input.toLowerCase()
    const topicSignals = [
      /分析|检测|验证|检查/i,
      /设计|配方|方案|制备/i,
      /评估|对比|比较|优劣/i,
      /总结|概括|汇总|整理/i,
    ]

    const matchedCount = topicSignals.filter(pattern => pattern.test(keywords)).length
    return matchedCount >= 2
  }

  /**
   * 拆解任务为子任务列表
   */
  decompose(input: string, messages: ChatMessage[]): SubTask[] {
    const lastMessages = messages.slice(-6)
    const context = lastMessages.map(m => `${m.role}: ${m.content}`).join('\n')

    const subtasks: SubTask[] = []
    const keywords = input.toLowerCase()

    if (/分析|检测|验证|检查/.test(keywords)) {
      subtasks.push({
        id: `task-analyze-${Date.now()}`,
        description: '成分与功效分析',
        type: 'analyze',
        status: 'pending',
        prompt: `基于以下上下文，分析核心食材的功效成分与作用机理：\n${context}\n\n请输出结构化的分析结果。`,
      })
    }

    if (/设计|配方|方案|制备/.test(keywords)) {
      subtasks.push({
        id: `task-design-${Date.now()}`,
        description: '配方方案设计',
        type: 'design',
        status: 'pending',
        prompt: `基于以下上下文，设计一个精确到克的药食同源配方：\n${context}\n\n输出格式：君臣佐使结构 + 克重配比 + 制备SOP。`,
      })
    }

    if (/评估|对比|比较|优劣/.test(keywords)) {
      subtasks.push({
        id: `task-evaluate-${Date.now()}`,
        description: '方案评估对比',
        type: 'evaluate',
        status: 'pending',
        prompt: `基于以下上下文，对现有方案进行安全性与有效性评估：\n${context}\n\n从配伍禁忌、剂量安全、适口性三个维度评估。`,
      })
    }

    // 确保至少有一个子任务
    if (subtasks.length === 0) {
      subtasks.push({
        id: `task-summary-${Date.now()}`,
        description: '综合处理',
        type: 'summary',
        status: 'pending',
        prompt: `请完整回答以下问题：\n${input}`,
      })
    }

    logger.info(`[SubagentDelegation] 任务拆解完成: ${subtasks.length} 个子任务`)
    return subtasks
  }

  /**
   * 执行子任务委托（串行 fallback，后续可扩展为并行）
   */
  async execute(
    input: string,
    messages: ChatMessage[],
    onProgress?: (task: SubTask) => void,
  ): Promise<DelegationResult> {
    const subtasks = this.decompose(input, messages)
    const taskId = `delegation-${Date.now()}`
    const abortController = new AbortController()
    this.runningTasks.set(taskId, abortController)

    logger.info(`[SubagentDelegation] 开始执行 ${subtasks.length} 个子任务: ${taskId}`)

    const results: SubTask[] = []
    let finalOutput = ''

    for (const task of subtasks) {
      if (abortController.signal.aborted) {
        logger.warn('[SubagentDelegation] 任务已取消')
        break
      }

      task.status = 'running'
      onProgress?.(task)

      try {
        const result = await this.runTask(task, abortController.signal)
        task.result = result
        task.status = 'completed'
        finalOutput += result + '\n\n'
        logger.info(`[SubagentDelegation] 子任务完成: ${task.id}`)
      } catch (error) {
        task.status = 'failed'
        task.error = error instanceof Error ? error.message : String(error)
        logger.error(`[SubagentDelegation] 子任务失败: ${task.id}`, error)
      }

      results.push(task)
      onProgress?.(task)
    }

    this.runningTasks.delete(taskId)

    const result: DelegationResult = {
      taskId,
      subtasks: results,
      finalOutput: finalOutput.trim(),
      parallelDone: subtasks.length === 1,
    }

    logger.info(`[SubagentDelegation] 委托完成: ${taskId}`)
    return result
  }

  /**
   * 运行单个子任务
   */
  private async runTask(task: SubTask, signal: AbortSignal): Promise<string> {
    const response = await chatService.sendMessage(task.prompt)
    return response.content || '（无输出）'
  }

  /**
   * 取消正在执行的委托
   */
  cancel(taskId: string): void {
    const controller = this.runningTasks.get(taskId)
    if (controller) {
      controller.abort()
      this.runningTasks.delete(taskId)
      logger.info(`[SubagentDelegation] 任务已取消: ${taskId}`)
    }
  }

  /**
   * 获取正在运行的任务数
   */
  get activeCount(): number {
    return this.runningTasks.size
  }
}

export const subagentDelegation = new SubagentDelegationService()
export default SubagentDelegationService

/**
 * SessionCapability — 会话管理能力
 *
 * 参照 DeepSeek Harness Session fork/resume 设计：
 * - fork: 在指定位置创建会话分支
 * - resumeTo: 恢复到历史节点
 * - 完整的会话生命周期管理
 *
 * @version 1.0.0
 */

import type { ChatMessage } from '../../types'
import { chatStorageService } from '../storage/ChatStorageService'
import { logger } from '@/utils/safeLogger'

export interface SessionForkOptions {
  /** 从哪条消息开始分叉（不传则从最后一条消息之后） */
  boundaryMessageId?: string
  /** 子会话 ID（不传则自动生成） */
  childSessionId?: string
  /** 子会话标题 */
  title?: string
}

export interface SessionResumeResult {
  sessionId: string
  messages: ChatMessage[]
  boundarySeq: number
}

export class SessionCapability {
  /**
   * 在当前会话指定位置创建分支
   * 参照 DSH: session.fork(source, boundary)
   */
  async fork(parentSessionId: string, options: SessionForkOptions = {}): Promise<string> {
    const messages = (await chatStorageService.loadMessages(parentSessionId)) as ChatMessage[]

    // 确定分叉边界
    let boundaryIndex = messages.length
    if (options.boundaryMessageId) {
      const idx = messages.findIndex((m: ChatMessage) => m.id === options.boundaryMessageId)
      if (idx !== -1) {
        boundaryIndex = idx + 1
      }
    }

    // 生成子会话 ID
    const childId = options.childSessionId ??
      `session-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`

    // 保存分支消息
    const branchMessages = messages.slice(0, boundaryIndex)
    await chatStorageService.saveMessages(childId, branchMessages)

    // 更新元数据
    await chatStorageService.saveSessionMeta(childId, {
      title: options.title || `分支-${childId.slice(-6)}`,
      tags: [],
      createdAt: Date.now(),
      updatedAt: Date.now(),
      messageCount: branchMessages.length,
    })

    logger.info(`[SessionCapability] 会话分支已创建: ${parentSessionId} → ${childId} (${boundaryIndex}条消息)`)
    return childId
  }

  /**
   * 恢复到指定历史节点
   * 参照 DSH: session.resume(sessionId)
   */
  async resumeTo(sessionId: string, targetMessageId: string): Promise<SessionResumeResult | null> {
    const messages = (await chatStorageService.loadMessages(sessionId)) as ChatMessage[]
    const targetIndex = messages.findIndex((m: ChatMessage) => m.id === targetMessageId)

    if (targetIndex === -1) {
      logger.warn('[SessionCapability] resumeTo: 目标消息未找到', { targetMessageId })
      return null
    }

    // 返回目标节点及之前的所有消息
    const history = messages.slice(0, targetIndex + 1)

    logger.info(`[SessionCapability] 会话已恢复到: ${sessionId}@${targetMessageId} (${history.length}条消息)`)
    return {
      sessionId,
      messages: history,
      boundarySeq: targetIndex,
    }
  }

  /**
   * 创建新会话
   */
  async createSession(title?: string): Promise<string> {
    const sessionId = `session-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`
    await chatStorageService.saveSessionMeta(sessionId, {
      title: title || '新对话',
      tags: [],
      createdAt: Date.now(),
      updatedAt: Date.now(),
      messageCount: 0,
    })
    logger.info(`[SessionCapability] 新会话已创建: ${sessionId}`)
    return sessionId
  }

  /**
   * 删除会话
   */
  async deleteSession(sessionId: string): Promise<void> {
    await chatStorageService.deleteMessages(sessionId)
    logger.info(`[SessionCapability] 会话已删除: ${sessionId}`)
  }

  /**
   * 获取会话摘要列表
   */
  async listSessions(): Promise<Array<{ id: string; title: string; messageCount: number; updatedAt: number }>> {
    const summaries = await chatStorageService.listSessions()
    return summaries.map((s: any) => ({
      id: s.id,
      title: s.meta.title,
      messageCount: s.messageCount,
      updatedAt: s.meta.updatedAt,
    }))
  }

  /**
   * 重命名会话
   */
  async renameSession(sessionId: string, title: string): Promise<void> {
    const meta = await chatStorageService.loadSessionMeta(sessionId)
    if (meta) {
      await chatStorageService.saveSessionMeta(sessionId, {
        ...meta,
        title,
        updatedAt: Date.now(),
      })
    }
  }
}

export const sessionCapability = new SessionCapability()
export default SessionCapability

/**
 * ChatStorageCapability — 统一存储能力
 *
 * 参照 DeepSeek Harness Session 持久化设计：
 * - IndexedDB 作为主存储（大容量、结构化查询）
 * - localStorage 作为性能缓存（快速读取，带版本号校验）
 * - 后端 API 作为跨设备同步层
 *
 * 统一接口替代现有的散乱存储逻辑
 *
 * @version 1.0.0
 */

import { logger } from '@/utils/safeLogger'
import type { ChatMessage } from '../../types'
import { chatHistoryStorage } from '../../services/chatHistoryStorage'
import { storageService } from '../../services/storageService'
import { ChatTopic } from '../../types/chatHistory.types'

export interface ChatStorageCapability {
  /** 保存指定会话的所有消息 */
  saveMessages(sessionId: string, messages: ChatMessage[]): Promise<void>

  /** 加载指定会话的所有消息 */
  loadMessages(sessionId: string): Promise<ChatMessage[]>

  /** 删除指定会话的消息 */
  deleteMessages(sessionId: string): Promise<void>

  /** 更新单条消息 */
  updateMessage(sessionId: string, messageId: string, updates: Partial<ChatMessage>): Promise<void>

  /** 删除单条消息 */
  deleteMessage(sessionId: string, messageId: string): Promise<void>

  /** 保存会话元数据 */
  saveSessionMeta(sessionId: string, meta: SessionMeta): Promise<void>

  /** 加载会话元数据 */
  loadSessionMeta(sessionId: string): Promise<SessionMeta | null>

  /** 列出所有会话摘要 */
  listSessions(): Promise<SessionSummary[]>

  /** 同步到后端 */
  syncToServer(sessionId: string): Promise<void>

  /** 从后端加载 */
  fetchFromServer(sessionId: string): Promise<ChatMessage[]>

  /** 从云端恢复全部会话快照（跨设备） */
  restoreFromServer(): Promise<number>
}

export interface SessionMeta {
  title: string
  topic?: string
  tags: string[]
  createdAt: number
  updatedAt: number
  messageCount: number
}

export interface SessionSummary {
  id: string
  meta: SessionMeta
  messageCount: number
}

const CACHE_TTL_MS = 5 * 60 * 1000 // 5分钟缓存有效期

export class ChatStorageService implements ChatStorageCapability {
  private cache = new Map<string, { messages: ChatMessage[]; timestamp: number }>()

  async saveMessages(sessionId: string, messages: ChatMessage[]): Promise<void> {
    try {
      // 1. 保存到 IndexedDB（主存储）
      await chatHistoryStorage.saveSession({
        id: sessionId,
        title: `会话 ${sessionId.slice(-8)}`,
        messages,
        metadata: {
          topic: ChatTopic.KNOWLEDGE_QUERY,
          tags: [],
          createdAt: messages[0]?.timestamp || Date.now(),
          updatedAt: Date.now(),
          messageCount: messages.length,
        },
      })

      // 2. 更新 localStorage 缓存
      this.cache.set(sessionId, {
        messages,
        timestamp: Date.now(),
      })

      // 3. 更新会话列表
      await this.updateSessionList(sessionId, messages)

      logger.info(`[ChatStorage] 消息已保存: ${sessionId} (${messages.length}条)`)
    } catch (error) {
      logger.error('[ChatStorage] 保存消息失败:', error)
      throw error
    }
  }

  async loadMessages(sessionId: string): Promise<ChatMessage[]> {
    try {
      // 1. 尝试从缓存加载
      const cached = this.cache.get(sessionId)
      if (cached && Date.now() - cached.timestamp < CACHE_TTL_MS) {
        return cached.messages
      }

      // 2. 尝试从 IndexedDB 加载
      const session = await chatHistoryStorage.getSession(sessionId)
      if (session?.messages && session.messages.length > 0) {
        this.cache.set(sessionId, {
          messages: session.messages as unknown as ChatMessage[],
          timestamp: Date.now(),
        })
        return session.messages as unknown as ChatMessage[]
      }

      // 3. 降级：尝试从 localStorage 加载（兼容旧数据）
      const legacyMessages = this.loadFromLocalStorage(sessionId)
      if (legacyMessages.length > 0) {
        await this.saveMessages(sessionId, legacyMessages)
        return legacyMessages
      }

      return []
    } catch (error) {
      logger.error('[ChatStorage] 加载消息失败:', error)
      return []
    }
  }

  async deleteMessages(sessionId: string): Promise<void> {
    try {
      await chatHistoryStorage.deleteSession(sessionId)
      this.cache.delete(sessionId)
      await this.removeFromSessionList(sessionId)
      logger.info(`[ChatStorage] 消息已删除: ${sessionId}`)
    } catch (error) {
      logger.error('[ChatStorage] 删除消息失败:', error)
    }
  }

  async updateMessage(sessionId: string, messageId: string, updates: Partial<ChatMessage>): Promise<void> {
    const messages = await this.loadMessages(sessionId)
    const updated = messages.map(m =>
      m.id === messageId ? { ...m, ...updates } : m
    )
    await this.saveMessages(sessionId, updated)
  }

  async deleteMessage(sessionId: string, messageId: string): Promise<void> {
    const messages = await this.loadMessages(sessionId)
    const filtered = messages.filter(m => m.id !== messageId)
    await this.saveMessages(sessionId, filtered)
  }

  async saveSessionMeta(sessionId: string, meta: SessionMeta): Promise<void> {
    try {
      // 重新保存整个 session 以更新元数据
      const existing = await chatHistoryStorage.getSession(sessionId)
      if (existing) {
        await chatHistoryStorage.saveSession({
          ...existing,
          title: meta.title,
          metadata: {
            ...existing.metadata,
            topic: (meta.topic || ChatTopic.KNOWLEDGE_QUERY) as ChatTopic,
            tags: meta.tags,
            updatedAt: meta.updatedAt,
            messageCount: meta.messageCount,
          },
        })
      } else {
        // 新建 session
        await chatHistoryStorage.saveSession({
          id: sessionId,
          title: meta.title,
          messages: [],
          metadata: {
            topic: (meta.topic || ChatTopic.KNOWLEDGE_QUERY) as ChatTopic,
            tags: meta.tags,
            createdAt: meta.createdAt,
            updatedAt: meta.updatedAt,
            messageCount: meta.messageCount,
          },
        })
      }
      logger.info(`[ChatStorage] 会话元数据已保存: ${sessionId}`)
    } catch (error) {
      logger.error('[ChatStorage] 保存会话元数据失败:', error)
    }
  }

  async loadSessionMeta(sessionId: string): Promise<SessionMeta | null> {
    try {
      const session = await chatHistoryStorage.getSession(sessionId)
      if (!session) return null
      return {
        title: session.title,
        topic: session.metadata?.topic,
        tags: session.metadata?.tags || [],
        createdAt: session.metadata?.createdAt || 0,
        updatedAt: session.metadata?.updatedAt || 0,
        messageCount: session.metadata?.messageCount || session.messages?.length || 0,
      }
    } catch {
      return null
    }
  }

  async listSessions(): Promise<SessionSummary[]> {
    try {
      const sessions = await chatHistoryStorage.getAllSessions()
      return sessions.map(s => ({
        id: s.id,
        meta: {
          title: s.title,
          topic: s.metadata?.topic,
          tags: s.metadata?.tags || [],
          createdAt: s.metadata?.createdAt || 0,
          updatedAt: s.metadata?.updatedAt || 0,
          messageCount: s.metadata?.messageCount || s.messages?.length || 0,
        },
        messageCount: s.metadata?.messageCount || s.messages?.length || 0,
      }))
    } catch (error) {
      logger.error('[ChatStorage] 列出会话失败:', error)
      return []
    }
  }

  async syncToServer(sessionId: string): Promise<void> {
    try {
      const messages = await this.loadMessages(sessionId)
      if (messages.length === 0) return

      // 2026-10-12：后端已新增 POST /api/v1/chat/sync，将本地会话快照持久化到
      // SystemConfig（chat_sync_<user_id>，按 session id 去重，最多 200 个）。
      // 注意：这是快照级备份；后端会话表主键仍是 int，与本地字符串 ID 是两套
      // ID 空间，完整的跨设备恢复需 client_id 关联（结构性改造）。
      const sessionData = {
        id: sessionId,
        title: this.loadSessionList().find(s => s.id === sessionId)?.title || `会话 ${sessionId.slice(-8)}`,
        messages: messages.map(m => ({
          id: m.id,
          role: m.role,
          content: m.content,
          timestamp: m.timestamp,
          sendStatus: m.sendStatus,
          retryCount: m.retryCount,
        })),
        createdAt: messages[0]?.timestamp || Date.now(),
        updatedAt: Date.now(),
      }

      const token = localStorage.getItem('auth_token') || ''
      const response = await fetch('/api/v1/chat/sync', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ sessions: [sessionData] }),
      })

      if (!response.ok) throw new Error(`同步失败: ${response.status}`)
      logger.info(`[ChatStorage] 会话已同步到后端: ${sessionId} (${messages.length}条)`)
    } catch (error) {
      logger.error('[ChatStorage] 同步到后端失败:', error)
    }
  }

  async fetchFromServer(sessionId: string): Promise<ChatMessage[]> {
    try {
      const token = localStorage.getItem('auth_token') || ''
      // 后端路由是 /chat/sessions/{id}（复数）。此前写的是 /chat/session/{id}，
      // 必然 404，"从后端加载会话"永远拿不到数据。
      //
      // 注意：即使路由名修正后仍不会成功——后端 session_id 是 int（自增主键），
      // 而前端的 sessionId 是 `session-${Date.now()}-xxxx` 字符串
      // （见 SessionCapability.ts:97 / sessionManager.ts:32），会返回 422。
      // 后端会话表与前端会话层目前是两套互不相通的 ID 空间，
      // 本地 IndexedDB/localStorage 才是真正的主存储。这条路径要在
      // ID 空间统一后才能真正生效，届时可改为按 title 匹配或加 client_id 列。
      const response = await fetch(`/api/v1/chat/sessions/${encodeURIComponent(sessionId)}`, {
        headers: { Authorization: `Bearer ${token}` },
      })

      if (response.status === 422) {
        logger.warn(`[ChatStorage] 后端会话 ID 为整数，无法用本地字符串 ID "${sessionId}" 查询（422）`)
        return []
      }
      if (!response.ok) return []
      const data = await response.json() as { messages?: Array<{ id: string; role: string; content: string; timestamp: number }> }
      if (!data.messages?.length) return []

      const messages: ChatMessage[] = data.messages.map(m => ({
        id: m.id,
        role: m.role as 'user' | 'assistant',
        content: m.content,
        timestamp: m.timestamp,
      }))

      await this.saveMessages(sessionId, messages)
      logger.info(`[ChatStorage] 从后端加载 ${messages.length} 条消息: ${sessionId}`)
      return messages
    } catch (error) {
      logger.error('[ChatStorage] 从后端加载失败:', error)
      return []
    }
  }

  /** 从云端恢复全部会话快照（跨设备）：拉取 POST /sync 上传过的快照并写回本地 */
  async restoreFromServer(): Promise<number> {
    try {
      const token = localStorage.getItem('auth_token') || ''
      const response = await fetch('/api/v1/chat/sync/restore', {
        headers: { Authorization: `Bearer ${token}` },
      })
      if (!response.ok) {
        logger.warn(`[ChatStorage] 云端恢复失败: HTTP ${response.status}`)
        return 0
      }
      const data = await response.json() as {
        success?: boolean
        sessions?: Array<{
          id: string
          title?: string
          messages?: Array<{ id: string; role: string; content: string; timestamp: number }>
          createdAt?: number
          updatedAt?: number
        }>
      }
      const sessions = data.sessions || []
      let restored = 0
      for (const s of sessions) {
        if (!s.id) continue
        const msgs: ChatMessage[] = (s.messages || []).map((m) => ({
          id: m.id,
          role: m.role as 'user' | 'assistant',
          content: m.content,
          timestamp: m.timestamp,
        }))
        if (msgs.length > 0) {
          await this.saveMessages(s.id, msgs)
          restored += 1
        }
      }
      logger.info(`[ChatStorage] 云端恢复 ${restored} 个会话`)
      return restored
    } catch (error) {
      logger.error('[ChatStorage] 云端恢复失败:', error)
      return 0
    }
  }

  // ===== 私有方法 =====

  private async updateSessionList(sessionId: string, messages: ChatMessage[]): Promise<void> {
    try {
      const sessions = this.loadSessionList()
      const existingIndex = sessions.findIndex(s => s.id === sessionId)

      const sessionData = {
        id: sessionId,
        title: messages[0]?.content?.slice(0, 30) || '新对话',
        messageCount: messages.length,
        lastMessage: messages[messages.length - 1]?.content?.slice(0, 50) || '',
        timestamp: messages[messages.length - 1]?.timestamp || Date.now(),
      }

      if (existingIndex >= 0) {
        sessions[existingIndex] = sessionData
      } else {
        sessions.unshift(sessionData)
      }

      // 限制最多100个会话
      if (sessions.length > 100) {
        sessions.splice(100)
      }

      storageService.set('rmfood_chat_sessions_v2', sessions)
    } catch (error) {
      logger.warn('[ChatStorage] 更新会话列表失败:', error)
    }
  }

  private async removeFromSessionList(sessionId: string): Promise<void> {
    try {
      const sessions = this.loadSessionList()
      const filtered = sessions.filter(s => s.id !== sessionId)
      storageService.set('rmfood_chat_sessions_v2', filtered)
    } catch (error) {
      logger.warn('[ChatStorage] 从会话列表移除失败:', error)
    }
  }

  private loadSessionList(): Array<{
    id: string
    title: string
    messageCount: number
    lastMessage: string
    timestamp: number
  }> {
    try {
      const data = storageService.get<Array<any>>('rmfood_chat_sessions_v2')
      return data || []
    } catch {
      return []
    }
  }

  private loadFromLocalStorage(sessionId: string): ChatMessage[] {
    try {
      // 兼容旧版存储键格式
      const key = `chat_session_msgs_${sessionId}`
      const data = storageService.get<ChatMessage[]>(key)
      return data || []
    } catch {
      return []
    }
  }
}

export const chatStorageService = new ChatStorageService()
export default chatStorageService

﻿/**
 * ContextCompaction — 上下文压缩引擎
 *
 * 参照 DeepSeek Harness Compaction 算法：
 * - 当 token 接近上限时，用摘要替换旧消息
 * - 保留关键信息（首次问题、核心配方数据）
 * - 压缩后日志完整可追溯
 *
 * @version 1.0.0
 */

import type { ChatMessage } from '../../types'
import { logger } from '@/utils/safeLogger'

export interface CompactionResult {
  /** 压缩后的消息列表 */
  messages: ChatMessage[]
  /** 被压缩的消息数量 */
  compressedCount: number
  /** 生成的摘要文本 */
  summary: string
  /** 触发原因 */
  trigger: 'pressure' | 'overflow'
}

export class ContextCompactionEngine {
  /** 压缩触发阈值：token 使用率超过此值时触发 */
  private readonly TRIGGER_THRESHOLD = 0.85
  /** 压缩后保留的最大 token 数 */
  private readonly TARGET_TOKENS = 3000
  /** 始终保留的首条用户消息（对话起点） */
  private readonly KEEP_FIRST_USER = true
  /** 始终保留的最后 N 条完整消息 */
  private readonly KEEP_LAST_N = 6

  /**
   * 检测是否需要压缩
   */
  shouldCompact(messages: ChatMessage[], estimatedTokens: number): boolean {
    if (messages.length < 20) return false
    return estimatedTokens > this.TARGET_TOKENS * this.TRIGGER_THRESHOLD
  }

  /**
   * 执行压缩
   *
   * 策略（参照 DSH Compaction flow）：
   * 1. 选择可压缩范围（早期消息）
   * 2. 调用 LLM 生成摘要
   * 3. 将摘要作为新消息插入，替换被压缩的范围
   */
  async compact(
    messages: ChatMessage[],
    onProgress?: (step: string) => void
  ): Promise<CompactionResult> {
    const validMessages = messages.filter(
      m => !m.error && m.content && (m.role === 'user' || m.role === 'assistant')
    )

    if (validMessages.length < 20) {
      return {
        messages,
        compressedCount: 0,
        summary: '',
        trigger: 'pressure',
      }
    }

    onProgress?.('开始上下文压缩...')

    // 1. 确定压缩范围（早期消息，保留最近 N 条）
    const keepFromEnd = Math.min(this.KEEP_LAST_N, Math.floor(validMessages.length * 0.3))
    const compressUpTo = validMessages.length - keepFromEnd

    if (compressUpTo <= 2) {
      logger.warn('[ContextCompaction] 可压缩消息不足，跳过压缩')
      return {
        messages,
        compressedCount: 0,
        summary: '',
        trigger: 'pressure',
      }
    }

    const messagesToCompress = validMessages.slice(0, compressUpTo)
    const messagesToKeep = validMessages.slice(compressUpTo)

    // 2. 构建压缩提示
    const compressionPrompt = this.buildCompressionPrompt(messagesToCompress)

    onProgress?.('正在生成摘要...')

    // 3. 纯规则摘要（不依赖 LLM，避免递归调用）
    let summary = this.buildRuleSummary(messagesToCompress)

    // 4. 构建压缩后的消息列表
    const summaryMessage: ChatMessage = {
      id: `compacted-summary-${Date.now()}`,
      role: 'system' as const,
      content: `【对话摘要】${summary}`,
      timestamp: Date.now(),
    }

    // 5. 保留首条用户消息（如果不在 keep 范围内）
    const result: ChatMessage[] = []
    if (this.KEEP_FIRST_USER && messagesToCompress.length > 0) {
      result.push(messagesToCompress[0])
    }
    result.push(summaryMessage)
    result.push(...messagesToKeep)

    logger.info(`[ContextCompaction] 压缩完成: ${messagesToCompress.length}条 → 保留${result.length}条`)

    return {
      messages: result,
      compressedCount: messagesToCompress.length - (this.KEEP_FIRST_USER ? 1 : 0),
      summary,
      trigger: 'pressure',
    }
  }

  /**
   * 构建压缩提示词
   */
  private buildCompressionPrompt(messages: ChatMessage[]): string {
    const conversation = messages
      .map(m => `${m.role === 'user' ? '用户' : '助手'}: ${m.content}`)
      .join('\n\n')

    return `请为以下对话生成精炼摘要，保留关键信息和上下文：

${conversation}

要求：
1. 摘要不超过200字
2. 保留关键配方数据、成分名称、剂量等核心信息
3. 用中文输出
4. 直接输出摘要，不需要额外解释`
  }

  /**
   * 简单的摘要生成（LLM 不可用时的降级方案）
   */
  private buildRuleSummary(messages: ChatMessage[]): string {
    const userMessages = messages.filter(m => m.role === 'user')
    const assistantMessages = messages.filter(m => m.role === 'assistant')

    const keyPoints: string[] = []

    // 提取用户问题要点
    userMessages.slice(-3).forEach(m => {
      const preview = m.content.slice(0, 50)
      if (preview) keyPoints.push(`用户: ${preview}...`)
    })

    // 提取助手回复要点
    assistantMessages.slice(-2).forEach(m => {
      const preview = m.content.slice(0, 80)
      if (preview) keyPoints.push(`助手: ${preview}...`)
    })

    return `本次对话包含 ${messages.length} 条消息，主要涉及：${keyPoints.slice(0, 3).join('、')}`
  }
}

export const contextCompactionEngine = new ContextCompactionEngine()
export default ContextCompactionEngine

/**
 * AdvancedFilter - 高级多条件组合筛选器组件 (v1.0)
 *
 * 提供专业的多维度配方筛选UI，支持：
 * - 质量等级筛选（A/B/C/D/F 多选）
 * - 置信度范围筛选（双滑块 0-100%）
 * - 时间范围筛选（今天/本周/本月/自定义）
 * - 成分数量范围筛选
 * - 标签多选筛选（动态从数据提取）
 *
 * @version 1.0.0
 * @lastUpdated 2026-05-20
 * @author RMFOOD Team
 */

import React, { useState, useCallback, useMemo } from 'react';
import type { AIRecognizedFormula, FormulaFilters } from '@/types/ai.types';
import { Button } from '@/components/ui';

import { Filter, RotateCcw, Check, Calendar, Tag, Star, TrendingUp, Hash } from 'lucide-react';

interface AdvancedFilterProps {
  /** 当前筛选条件 */
  filters: FormulaFilters;
  /** 筛选条件变更回调 */
  onFiltersChange: (filters: FormulaFilters) => void;
  /** 重置筛选条件 */
  onReset: () => void;
  /** 所有配方数据（用于动态提取标签等） */
  allFormulas: AIRecognizedFormula[];
}

/** 质量等级选项 */
const QUALITY_GRADE_OPTIONS = [
  { value: 'A', label: 'A级', color: 'text-success-600 bg-success-100 dark:bg-success-300/25' },
  { value: 'B', label: 'B级', color: 'text-secondary-600 bg-secondary-100 dark:bg-secondary-300/25' },
  { value: 'C', label: 'C级', color: 'text-warning-600 bg-warning-100 dark:bg-warning-300/25' },
  { value: 'D', label: 'D级', color: 'text-warning-600 bg-warning-100 dark:bg-warning-300/25' },
  { value: 'F', label: 'F级', color: 'text-error-600 bg-error-100 dark:bg-error-300/25' },
];

/** 时间范围选项 */
const DATE_RANGE_OPTIONS = [
  { value: 'today', label: '今天' },
  { value: 'week', label: '本周' },
  { value: 'month', label: '本月' },
  { value: 'custom', label: '自定义' },
];

/**
 * AdvancedFilter 组件
 */
const AdvancedFilter: React.FC<AdvancedFilterProps> = ({ filters, onFiltersChange, onReset, allFormulas }) => {
  const [localFilters, setLocalFilters] = useState<FormulaFilters>(filters);

  const availableTags = useMemo(() => {
    const tagSet = new Set<string>();
    allFormulas.forEach((formula) => {
      formula.tags?.forEach((tag) => tagSet.add(tag));
    });
    return Array.from(tagSet).sort();
  }, [allFormulas]);

  const updateFilter = useCallback(<K extends keyof FormulaFilters>(key: K, value: FormulaFilters[K]) => {
    setLocalFilters((prev) => ({
      ...prev,
      [key]: value,
    }));
  }, []);

  const handleQualityGradeToggle = useCallback(
    (grade: string) => {
      const currentGrades = localFilters.qualityGrades || [];
      const typedGrade = grade as "A" | "D" | "B" | "C" | "F";
      const newGrades = currentGrades.includes(typedGrade)
        ? currentGrades.filter((g) => g !== grade)
        : [...currentGrades, typedGrade];

      updateFilter('qualityGrades', newGrades);
      onFiltersChange({
        ...localFilters,
        qualityGrades: newGrades,
      });
    },
    [localFilters, updateFilter, onFiltersChange],
  );

  const handleConfidenceRangeChange = useCallback(
    (min: number, max: number) => {
      const newFilters = {
        ...localFilters,
        confidenceRange: { min, max },
      };
      setLocalFilters(newFilters);
      onFiltersChange(newFilters);
    },
    [localFilters, onFiltersChange],
  );

  const handleDateRangeChange = useCallback(
    (type: string, start?: number, end?: number) => {
      let dateRange: FormulaFilters['dateRange'] | undefined;

      if (type === 'today') {
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        const tomorrow = new Date(today);
        tomorrow.setDate(tomorrow.getDate() + 1);
        dateRange = {
          start: today.getTime(),
          end: tomorrow.getTime(),
        };
      } else if (type === 'week') {
        const now = new Date();
        const weekAgo = new Date(now);
        weekAgo.setDate(weekAgo.getDate() - 7);
        dateRange = {
          start: weekAgo.getTime(),
          end: now.getTime(),
        };
      } else if (type === 'month') {
        const now = new Date();
        const monthAgo = new Date(now);
        monthAgo.setMonth(monthAgo.getMonth() - 1);
        dateRange = {
          start: monthAgo.getTime(),
          end: now.getTime(),
        };
      } else if (type === 'custom' && start && end) {
        dateRange = { start, end };
      }

      const newFilters = {
        ...localFilters,
        dateRange,
      };
      setLocalFilters(newFilters);
      onFiltersChange(newFilters);
    },
    [localFilters, onFiltersChange],
  );

  const handleIngredientCountChange = useCallback(
    (min: number, max: number) => {
      const newFilters = {
        ...localFilters,
        ingredientCountRange: { min, max },
      };
      setLocalFilters(newFilters);
      onFiltersChange(newFilters);
    },
    [localFilters, onFiltersChange],
  );

  const handleTagToggle = useCallback(
    (tag: string) => {
      const currentTags = localFilters.tags || [];
      const newTags = currentTags.includes(tag) ? currentTags.filter((t) => t !== tag) : [...currentTags, tag];

      const newFilters = {
        ...localFilters,
        tags: newTags,
      };
      setLocalFilters(newFilters);
      onFiltersChange(newFilters);
    },
    [localFilters, onFiltersChange],
  );

  const hasActiveFilters = useMemo(() => {
    return !!(
      (localFilters.qualityGrades && localFilters.qualityGrades.length > 0) ||
      localFilters.confidenceRange ||
      localFilters.dateRange ||
      localFilters.ingredientCountRange ||
      (localFilters.tags && localFilters.tags.length > 0)
    );
  }, [localFilters]);

  return (
    <div className="px-6 py-4">
      {/* 筛选器头部 */}
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2 text-sm font-semibold text-neutral-700 dark:text-neutral-300">
          <Filter size={16} />
          高级筛选
        </div>

        <div className="flex items-center gap-2">
          {hasActiveFilters && (
            <Button variant="ghost" size="sm" onClick={onReset} icon={<RotateCcw size={14} />}>
              重置
            </Button>
          )}
        </div>
      </div>

      {/* 筛选条件网格 */}
      <div className="space-y-4">
        {/* ===== 质量等级筛选 ===== */}
        <div className="space-y-2">
          <div className="flex items-center gap-2 text-xs font-medium text-neutral-600 dark:text-neutral-400">
            <Star size={14} />
            质量等级
          </div>

          <div className="flex flex-wrap gap-2">
            {QUALITY_GRADE_OPTIONS.map((option) => {
              const isSelected =
                localFilters.qualityGrades?.includes(option.value as 'A' | 'B' | 'C' | 'D' | 'F') ?? false;
              return (
                <button
                  key={option.value}
                  onClick={() => handleQualityGradeToggle(option.value)}
                  className={`px-3 py-1.5 rounded-md text-sm font-medium border transition-all ${
                    isSelected
                      ? `${option.color} border-current`
                      : 'border-neutral-300 dark:border-neutral-600 text-neutral-600 dark:text-neutral-400 hover:border-neutral-400'
                  }`}
                >
                  <span className="mr-1">{isSelected ? '✓' : ''}</span>
                  {option.label}
                </button>
              );
            })}
          </div>
        </div>

        {/* ===== 置信度范围筛选 ===== */}
        <div className="space-y-2">
          <div className="flex items-center justify-between text-xs font-medium text-neutral-600 dark:text-neutral-400">
            <div className="flex items-center gap-2">
              <TrendingUp size={14} />
              置信度范围
            </div>
            {localFilters.confidenceRange && (
              <span className="text-secondary-600 dark:text-secondary-700">
                {localFilters.confidenceRange.min}% - {localFilters.confidenceRange.max}%
              </span>
            )}
          </div>

          <div className="flex items-center gap-3">
            <input
              type="range"
              min="0"
              max="100"
              value={localFilters.confidenceRange?.min ?? 0}
              onChange={(e) => {
                const min = parseInt(e.target.value);
                const max = localFilters.confidenceRange?.max ?? 100;
                handleConfidenceRangeChange(Math.min(min, max), max);
              }}
              className="flex-1 h-2 bg-neutral-200 rounded-lg appearance-none cursor-pointer accent-secondary-500"
              aria-label="置信度下限"
            />
            <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] w-10 text-right">{localFilters.confidenceRange?.min ?? 0}%</span>
          </div>

          <div className="flex items-center gap-3">
            <input
              type="range"
              min="0"
              max="100"
              value={localFilters.confidenceRange?.max ?? 100}
              onChange={(e) => {
                const max = parseInt(e.target.value);
                const min = localFilters.confidenceRange?.min ?? 0;
                handleConfidenceRangeChange(min, Math.max(min, max));
              }}
              className="flex-1 h-2 bg-neutral-200 rounded-lg appearance-none cursor-pointer accent-secondary-500"
              aria-label="置信度上限"
            />
            <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] w-10 text-right">{localFilters.confidenceRange?.max ?? 100}%</span>
          </div>
        </div>

        {/* ===== 时间范围筛选 ===== */}
        <div className="space-y-2">
          <div className="flex items-center gap-2 text-xs font-medium text-neutral-600 dark:text-neutral-400">
            <Calendar size={14} />
            时间范围
          </div>

          <div className="flex flex-wrap gap-2">
            {DATE_RANGE_OPTIONS.map((option) => (
              <button
                key={option.value}
                onClick={() => handleDateRangeChange(option.value)}
                className={`px-3 py-1.5 rounded-md text-sm border transition-all ${
                  (option.value === 'custom' && localFilters.dateRange) ||
                  (option.value !== 'custom' && localFilters.dateRange)
                    ? 'border-secondary-500 bg-secondary-50 text-secondary-700 dark:bg-secondary-300/20 dark:text-secondary-700'
                    : 'border-neutral-300 dark:border-neutral-600 text-neutral-600 dark:text-neutral-400 hover:border-neutral-400'
                }`}
              >
                {option.label}
              </button>
            ))}
          </div>

          {localFilters.dateRange && (
            <div className="flex items-center gap-2 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">
              <span>{new Date(localFilters.dateRange.start).toLocaleDateString('zh-CN')}</span>
              <span>-</span>
              <span>{new Date(localFilters.dateRange.end).toLocaleDateString('zh-CN')}</span>
            </div>
          )}
        </div>

        {/* ===== 成分数量范围筛选 ===== */}
        <div className="space-y-2">
          <div className="flex items-center justify-between text-xs font-medium text-neutral-600 dark:text-neutral-400">
            <div className="flex items-center gap-2">
              <Hash size={14} />
              成分数量
            </div>
            {localFilters.ingredientCountRange && (
              <span className="text-secondary-600 dark:text-secondary-700">
                {localFilters.ingredientCountRange.min} - {localFilters.ingredientCountRange.max} 种
              </span>
            )}
          </div>

          <div className="flex items-center gap-3">
            <div className="flex items-center gap-2 flex-1">
              <input
                type="number"
                min="0"
                max="50"
                value={localFilters.ingredientCountRange?.min ?? ''}
                onChange={(e) => {
                  const min = parseInt(e.target.value) || 0;
                  const max = localFilters.ingredientCountRange?.max ?? 50;
                  handleIngredientCountChange(min, Math.max(min, max));
                }}
                placeholder="最少"
                className="w-20 px-2 py-1 border border-neutral-300 dark:border-neutral-600 rounded text-sm bg-white dark:bg-neutral-700 outline-none focus:ring-2 focus:ring-secondary-500"
              />
              <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">-</span>
              <input
                type="number"
                min="0"
                max="50"
                value={localFilters.ingredientCountRange?.max ?? ''}
                onChange={(e) => {
                  const max = parseInt(e.target.value) || 50;
                  const min = localFilters.ingredientCountRange?.min ?? 0;
                  handleIngredientCountChange(Math.min(min, max), max);
                }}
                placeholder="最多"
                className="w-20 px-2 py-1 border border-neutral-300 dark:border-neutral-600 rounded text-sm bg-white dark:bg-neutral-700 outline-none focus:ring-2 focus:ring-secondary-500"
              />
              <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">种</span>
            </div>
          </div>
        </div>

        {/* ===== 标签筛选 ===== */}
        {availableTags.length > 0 && (
          <div className="space-y-2">
            <div className="flex items-center gap-2 text-xs font-medium text-neutral-600 dark:text-neutral-400">
              <Tag size={14} />
              标签
              <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] normal-font">({availableTags.length} 个可用)</span>
            </div>

            <div className="flex flex-wrap gap-2 max-h-32 overflow-y-auto">
              {availableTags.slice(0, 20).map((tag) => {
                const isSelected = localFilters.tags?.includes(tag);
                return (
                  <button
                    key={tag}
                    onClick={() => handleTagToggle(tag)}
                    className={`px-2.5 py-1 rounded-full text-xs font-medium transition-all ${
                      isSelected
                        ? 'bg-primary-100 text-primary-700 dark:bg-primary-300/25 dark:text-primary-700 ring-2 ring-primary-500'
                        : 'bg-neutral-100 text-neutral-600 dark:bg-neutral-700 dark:text-neutral-400 hover:bg-neutral-200 dark:hover:bg-neutral-600'
                    }`}
                  >
                    <span className="mr-1">{isSelected ? '✓' : ''}</span>
                    {tag}
                  </button>
                );
              })}
            </div>

            {availableTags.length > 20 && (
              <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] italic">还有 {availableTags.length - 20} 个标签未显示...</div>
            )}
          </div>
        )}

        {/* 无可用标签提示 */}
        {availableTags.length === 0 && (
          <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] italic py-2 text-center">暂无可用标签（配方数据中未包含标签信息）</div>
        )}
      </div>

      {/* 底部操作栏 */}
      <div className="mt-4 pt-4 border-t border-neutral-200 dark:border-neutral-700 flex items-center justify-between">
        <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
          {hasActiveFilters ? (
            <span>
              已启用 <strong>{Object.values(localFilters).filter(Boolean).length}</strong> 个筛选条件
            </span>
          ) : (
            <span>未启用任何筛选条件</span>
          )}
        </div>

        <Button size="sm" onClick={() => onFiltersChange(localFilters)} disabled={!hasActiveFilters}>
          应用筛选
        </Button>
      </div>
    </div>
  );
};

AdvancedFilter.displayName = 'AdvancedFilter';

export { AdvancedFilter };
export default AdvancedFilter;

