            <div className="flex items-center justify-between">
              <div>
                <h4 className="text-sm font-medium text-neutral-900 dark:text-white">最大高度</h4>
                <p className="text-xs text-neutral-500 dark:text-neutral-400 mt-0.5">输入框最大高度（像素）</p>
