                </div>
              );
            })}
          </div>

          <p className="mt-4 text-xs text-neutral-500 dark:text-neutral-400">
            💡 提示：点击录制按钮后，直接按下想要设置的快捷键组合即可自动记录
          </p>
        </div>

        {/* 底部操作按钮 */}
        <div className="flex items-center justify-between pt-4 border-t border-neutral-200 dark:border-neutral-700">
          <button
