            </div>
            <div>
              <h3 id="share-panel-title" className="text-base font-semibold text-neutral-900 dark:text-white">
                分享内容
              </h3>
              <p className="text-xs text-neutral-500 dark:text-neutral-400 mt-0.5">{shareData.title || '分享 AI 对话内容'}</p>
            </div>
          </div>

          <button
            onClick={onClose}
