        </div>

        {/* Tab 切换器 */}
        <div className="px-5 pt-4">
          <TabSwitcher activeTab={activeTab} onTabChange={setActiveTab} />
        </div>

        {/* 内容区域 */}
        <div className="px-5 py-4 max-h-[400px] overflow-y-auto">
          {/* 错误提示 */}
          {error && (
