/**
 * ErrorRecoveryDialog - 智能错误恢复对话框 (v7.0)
 *
 * 功能特性：
 * 1. 根据错误类型显示差异化的恢复策略和 UI
 * 2. 支持自动重试机制（可配置重试次数）
 * 3. 提供用户友好的错误提示和操作建议
 * 4. 支持倒计时器（限流错误）
 * 5. 可折叠的技术详情面板
 *
 * 错误类型支持：
 * - NetworkTimeout: 网络超时，自动重试3次
 * - Unauthorized: 401未授权，跳转登录
 * - RateLimited: 429限流，倒计时+禁用发送
 * - ServerError: 500服务器错误，指数退避重试
 * - StreamInterrupted: 流式中断，重连选项
 * - Unknown: 未知错误，通用恢复策略
 *
 * @version 7.0.0
 * @lastUpdated 2026-05-11
 */

import React, { useState, useEffect, useCallback, useMemo } from 'react'
import {
  AlertTriangle,
  WifiOff,
  Lock,
  Timer,
  ServerCrash,
  Unplug,
  RefreshCw,
  X,
  LogIn,
  Bug,
  Lightbulb,
} from 'lucide-react'
import { Button } from '@/components/ui'
import { logger } from '@/utils/safeLogger'

export enum ErrorType {
  NetworkTimeout = 'network_timeout',
  NetworkUnreachable = 'network_unreachable',
  Unauthorized = 'unauthorized',
  Forbidden = 'forbidden',
  RateLimited = 'rate_limited',
  ServerError = 'server_error',
  StreamInterrupted = 'stream_interrupted',
  Unknown = 'unknown',
}

interface ClassifiedError {
  type: ErrorType
  originalError: Error
  userMessage: string
  suggestion: string
  canAutoRecover: boolean
  retryAfter?: number
  countdown?: number
}

export interface ErrorRecoveryDialogProps {
  error: Error | null
  errorType?: ErrorType
  onRetry?: () => Promise<void>
  onDismiss?: () => void
  onLogin?: () => void
  autoRetryCount?: number
  showDetails?: boolean
  className?: string
}

const ERROR_CONFIG: Record<ErrorType, {
  icon: React.ElementType
  title: string
  colorClass: string
  bgClass: string
}> = {
  [ErrorType.NetworkTimeout]: {
    icon: WifiOff,
    title: '连接超时',
    colorClass: 'text-warning-600 dark:text-warning-700',
    bgClass: 'bg-warning-100 dark:bg-warning-300/25',
  },
  [ErrorType.NetworkUnreachable]: {
    icon: WifiOff,
    title: '无法连接服务',
    colorClass: 'text-error-600 dark:text-error-600',
    bgClass: 'bg-error-100 dark:bg-error-300/25',
  },
  [ErrorType.Unauthorized]: {
    icon: Lock,
    title: '会话已过期',
    colorClass: 'text-error-600 dark:text-error-600',
    bgClass: 'bg-error-100 dark:bg-error-300/25',
  },
  [ErrorType.Forbidden]: {
    icon: Lock,
    title: '权限不足',
    colorClass: 'text-error-600 dark:text-error-600',
    bgClass: 'bg-error-100 dark:bg-error-300/25',
  },
  [ErrorType.RateLimited]: {
    icon: Timer,
    title: '请求过于频繁',
    colorClass: 'text-warning-600 dark:text-warning-700',
    bgClass: 'bg-warning-100 dark:bg-warning-300/25',
  },
  [ErrorType.ServerError]: {
    icon: ServerCrash,
    title: '服务器繁忙',
    colorClass: 'text-accent-600 dark:text-accent-700',
    bgClass: 'bg-accent-100 dark:bg-accent-300/25',
  },
  [ErrorType.StreamInterrupted]: {
    icon: Unplug,
    title: '响应中断',
    colorClass: 'text-secondary-600 dark:text-secondary-700',
    bgClass: 'bg-secondary-100 dark:bg-secondary-300/25',
  },
  [ErrorType.Unknown]: {
    icon: AlertTriangle,
    title: '发生错误',
    colorClass: 'text-neutral-600 dark:text-neutral-400',
    bgClass: 'bg-neutral-100 dark:bg-neutral-900/30',
  },
}

const SUGGESTIONS: Record<ErrorType, string> = {
  [ErrorType.NetworkTimeout]: '请检查您的网络连接后重试',
  [ErrorType.NetworkUnreachable]: 'AI 服务暂时不可用，请确认后端服务已启动 (端口 8000)',
  [ErrorType.Unauthorized]: '请重新登录以继续使用',
  [ErrorType.Forbidden]: '您的账号没有访问 AI 服务的权限，请联系管理员',
  [ErrorType.RateLimited]: '请稍等片刻后再发送消息',
  [ErrorType.ServerError]: '我们正在努力修复，请稍后重试',
  [ErrorType.StreamInterrupted]: '网络连接不稳定，是否重新生成响应？',
  [ErrorType.Unknown]: '请稍后重试或联系客服获取帮助',
}

function classifyError(error: Error): ClassifiedError {
  const errorMessage = error.message.toLowerCase()
  const errorName = error.name

  // ── 网络不可达：后端未启动 / 代理连接失败 / fetch 本身失败 ──
  const isNetworkUnreachable =
    errorMessage.includes('failed to fetch') ||
    errorMessage.includes('err_aborted') ||
    errorMessage.includes('aborted') ||
    errorMessage.includes('networkerror') ||
    (errorName === 'TypeError' && (errorMessage.includes('fetch') || errorMessage.includes('network')))

  if (isNetworkUnreachable) {
    return {
      type: ErrorType.NetworkUnreachable,
      originalError: error,
      userMessage: '无法连接到 AI 服务，请检查后端服务是否已启动',
      suggestion: SUGGESTIONS[ErrorType.NetworkUnreachable],
      canAutoRecover: true,
      retryAfter: 3000,
    }
  }

  if (errorName === 'TimeoutError' || errorMessage.includes('timeout')) {
    return {
      type: ErrorType.NetworkTimeout,
      originalError: error,
      userMessage: '网络连接超时，正在尝试重新连接...',
      suggestion: SUGGESTIONS[ErrorType.NetworkTimeout],
      canAutoRecover: true,
      retryAfter: 1000,
    }
  }

  if (
    errorMessage.includes('401') ||
    errorMessage.includes('unauthorized') ||
    errorMessage.includes('认证失败')
  ) {
    return {
      type: ErrorType.Unauthorized,
      originalError: error,
      userMessage: '您的登录会话已过期',
      suggestion: SUGGESTIONS[ErrorType.Unauthorized],
      canAutoRecover: false,
    }
  }

  if (errorMessage.includes('429') || errorMessage.includes('请求过于频繁') || errorMessage.includes('rate limit')) {
    const countdownMatch = /剩余\s*(\d+)/.exec(error.message)
    const countdown = countdownMatch ? parseInt(countdownMatch[1]) : 60

    return {
      type: ErrorType.RateLimited,
      originalError: error,
      userMessage: `请求过于频繁，请等待 ${countdown}s`,
      suggestion: SUGGESTIONS[ErrorType.RateLimited],
      canAutoRecover: false,
      countdown,
    }
  }

  if (
    errorMessage.includes('500') ||
    errorMessage.includes('服务器错误') ||
    errorMessage.includes('server error')
  ) {
    return {
      type: ErrorType.ServerError,
      originalError: error,
      userMessage: '服务器暂时无法处理请求',
      suggestion: SUGGESTIONS[ErrorType.ServerError],
      canAutoRecover: true,
      retryAfter: 2000,
    }
  }

  // 403 权限不足
  if (errorMessage.includes('403') || errorMessage.includes('forbidden') || errorMessage.includes('权限')) {
    return {
      type: ErrorType.Forbidden,
      originalError: error,
      userMessage: '权限不足，请重新登录后重试',
      suggestion: SUGGESTIONS[ErrorType.Forbidden],
      canAutoRecover: false,
    }
  }

  if (
    errorMessage.includes('流式') ||
    errorMessage.includes('stream') ||
    errorMessage.includes('中断')
  ) {
    return {
      type: ErrorType.StreamInterrupted,
      originalError: error,
      userMessage: 'AI 响应在传输过程中被中断',
      suggestion: SUGGESTIONS[ErrorType.StreamInterrupted],
      canAutoRecover: true,
      retryAfter: 500,
    }
  }

  return {
    type: ErrorType.Unknown,
    originalError: error,
    userMessage: '发生了未知错误',
    suggestion: SUGGESTIONS[ErrorType.Unknown],
    canAutoRecover: true,
    retryAfter: 2000,
  }
}

export function ErrorRecoveryDialog({
  error,
  errorType: propErrorType,
  onRetry,
  onDismiss,
  onLogin,
  autoRetryCount = 3,
  showDetails = false,
  className = '',
}: ErrorRecoveryDialogProps) {
  const [retryCount, setRetryCount] = useState(0)
  const [isRetrying, setIsRetrying] = useState(false)
  const [countdown, setCountdown] = useState(0)
  const [autoRetryExhausted, setAutoRetryExhausted] = useState(false)

  const classifiedError = useMemo(() => {
    if (!error) return null
    const classified = classifyError(error)
    return propErrorType ? { ...classified, type: propErrorType } : classified
  }, [error, propErrorType])

  useEffect(() => {
    if (classifiedError?.type !== ErrorType.RateLimited || !classifiedError.countdown) {
      return
    }

    setCountdown(classifiedError.countdown)
    const timer = setInterval(() => {
      setCountdown(prev => {
        if (prev <= 1) {
          clearInterval(timer)
          return 0
        }
        return prev - 1
      })
    }, 1000)

    return () => clearInterval(timer)
  }, [classifiedError])

  useEffect(() => {
    if (!classifiedError || !classifiedError.canAutoRecover || !onRetry || autoRetryExhausted) {
      return
    }

    const attemptAutoRetry = async () => {
      for (let i = 0; i < autoRetryCount; i++) {
        if (!classifiedError?.canAutoRecover) break

        await new Promise(resolve => setTimeout(resolve, classifiedError.retryAfter || 1000))

        try {
          setIsRetrying(true)
          setRetryCount(prev => prev + 1)
          logger.info(`[ErrorRecoveryDialog] 自动重试第 ${i + 1}/${autoRetryCount} 次`)
          await onRetry()
          logger.info('[ErrorRecoveryDialog] 自动重试成功')
          return
        } catch (retryError) {
          logger.warn(`[ErrorRecoveryDialog] 自动重试第 ${i + 1} 次失败:`, retryError)
          if (i === autoRetryCount - 1) {
            setAutoRetryExhausted(true)
          }
        } finally {
          setIsRetrying(false)
        }
      }
    }

    attemptAutoRetry()
  }, [classifiedError, onRetry, autoRetryCount, autoRetryExhausted])

  const handleRetry = useCallback(async () => {
    if (!onRetry || isRetrying) return

    try {
      setIsRetrying(true)
      setRetryCount(prev => prev + 1)
      logger.info('[ErrorRecoveryDialog] 用户手动重试')
      await onRetry()
    } catch (retryError) {
      logger.error('[ErrorRecoveryDialog] 手动重试失败:', retryError)
    } finally {
      setIsRetrying(false)
    }
  }, [onRetry, isRetrying])

  const handleLogin = useCallback(() => {
    logger.info('[ErrorRecoveryDialog] 用户点击登录')
    onLogin?.()
  }, [onLogin])

  const handleDismiss = useCallback(() => {
    logger.info('[ErrorRecoveryDialog] 用户关闭错误提示')
    onDismiss?.()
  }, [onDismiss])

  if (!error || !classifiedError) {
    return null
  }

  const config = ERROR_CONFIG[classifiedError.type]
  const IconComponent = config.icon
  const canShowRetry =
    classifiedError.canAutoRecover &&
    (autoRetryExhausted || retryCount >= autoRetryCount)

  return (
    <div className={`error-recovery-dialog rounded-lg border p-6 shadow-lg ${className}`}>
      <div className="flex items-start gap-4">
        <div className={`flex-shrink-0 w-12 h-12 rounded-full ${config.bgClass} flex items-center justify-center`}>
          <IconComponent className={`w-6 h-6 ${config.colorClass}`} />
        </div>

        <div className="flex-1 min-w-0">
          <div className="flex items-start justify-between mb-2">
            <h3 className="text-lg font-semibold text-neutral-900 dark:text-white">
              {config.title}
            </h3>
            <button
              onClick={handleDismiss}
              className="flex-shrink-0 ml-2 text-neutral-400 hover:text-neutral-600 dark:hover:text-neutral-300"
              aria-label="关闭"
            >
              <X className="w-5 h-5" />
            </button>
          </div>

          <p className="text-sm text-neutral-700 dark:text-neutral-300 mb-3">
            {classifiedError.userMessage}
          </p>

          <div className="flex items-start gap-2 mb-4 text-sm text-neutral-600 dark:text-neutral-400">
            <Lightbulb className="w-4 h-4 mt-0.5 flex-shrink-0" />
            <span>{classifiedError.suggestion}</span>
          </div>

          <div className="flex flex-wrap items-center gap-3">
            {(classifiedError.type === ErrorType.Unauthorized || classifiedError.type === ErrorType.Forbidden) && onLogin && (
              <Button
                variant="primary"
                size="sm"
                onClick={handleLogin}
                className="inline-flex items-center gap-2"
              >
                <LogIn className="w-4 h-4" />
                重新登录
              </Button>
            )}

            {classifiedError.type === ErrorType.RateLimited && countdown > 0 && (
              <Button variant="outline" size="sm" disabled className="inline-flex items-center gap-2">
                <Timer className="w-4 h-4" />
                等待 {countdown}s
              </Button>
            )}

            {canShowRetry && (
              <Button
                variant="outline"
                size="sm"
                onClick={handleRetry}
                disabled={isRetrying}
                className="inline-flex items-center gap-2"
              >
                <RefreshCw className={`w-4 h-4 ${isRetrying ? 'animate-spin' : ''}`} />
                {isRetrying ? '重试中...' : `重试 (${retryCount}/${autoRetryCount})`}
              </Button>
            )}

            <Button
              variant="ghost"
              size="sm"
              onClick={handleDismiss}
              className="inline-flex items-center gap-2"
            >
              关闭
            </Button>
          </div>

          {showDetails && (
            <details className="mt-4 text-left">
              <summary className="cursor-pointer text-xs font-medium text-neutral-500 dark:text-neutral-400 hover:text-neutral-700 dark:hover:text-neutral-300 inline-flex items-center gap-1">
                <Bug className="w-3 h-3" />
                技术详情
              </summary>
              <pre className="mt-2 p-3 bg-neutral-50 dark:bg-neutral-800 rounded-lg text-xs text-error-600 dark:text-error-600 overflow-auto max-h-40 whitespace-pre-wrap">
                {classifiedError.originalError.message}
                {'\n\n'}
                {classifiedError.originalError.stack}
              </pre>
            </details>
          )}
        </div>
      </div>
    </div>
  )
}

export default ErrorRecoveryDialog

/**
 * FlavorWheel3D - 3D 风味雷达图组件 (v1.0)
 *
 * 使用 CSS 3D transform 实现可交互的 3D 风味轮盘。
 * 支持六大味道维度（酸/甜/苦/辣/鲜/涩）的可视化展示。
 *
 * 技术选型理由：
 * - 选择 CSS 3D transform 而非 Three.js 是为了：
 *   1. 包体积更小（0KB vs ~500KB）
 *   2. 更容易与 React 集成
 *   3. 性能更好（GPU 加速，无需 WebGL 上下文）
 *   4. 移动端兼容性更好
 *
 * 功能特性：
 * - 可旋转/缩放交互（鼠标拖拽/滚轮）
 * - 六大味道维度标注清晰
 * - 触摸手势支持（移动端适配）
 * - 数据点悬停显示详情
 * - 动画过渡效果流畅
 *
 * @version 1.0.0
 * @lastUpdated 2026-05-12
 */

import React, { useRef, useState, useCallback, useEffect, memo } from 'react'
import { RotateCcw, ZoomIn, ZoomOut, Maximize2 } from 'lucide-react'
import { Tooltip } from '@/components/ui'
import { logger } from '@/utils/safeLogger'

// ===== 类型定义 =====

export interface FlavorDimension {
  id: string
  label: string
  value: number // 0-100
  color: string
  description?: string
}

interface FlavorData {
  name: string
  dimensions: FlavorDimension[]
  timestamp?: number
}

interface FlavorWheel3DProps {
  data: FlavorData[]
  width?: number
  height?: number
  showControls?: boolean
  interactive?: boolean
  onDimensionClick?: (dimension: FlavorDimension) => void
  className?: string
}

// ===== 常量配置 =====

const DEFAULT_DIMENSIONS: Omit<FlavorDimension, 'value'>[] = [
  { id: 'sour', label: '酸', color: 'var(--color-warning-400, #F59E0B)' },
  { id: 'sweet', label: '甜', color: 'var(--color-danger-500, #D946EF)' },
  { id: 'bitter', label: '苦', color: 'var(--color-amber-600, #d97706)' },
  { id: 'spicy', label: '辣', color: 'var(--color-error, #FF3B30)' },
  { id: 'umami', label: '鲜', color: 'var(--color-primary, var(--color-primary-400))' },
  { id: 'astringent', label: '涩', color: 'var(--color-primary-500, #10b981)' },
]

const ROTATION_SPEED = 0.5
const ZOOM_SPEED = 0.1
const MIN_ZOOM = 0.5
const MAX_ZOOM = 2.0

// ===== 主组件实现 =====

const FlavorWheel3D = memo(({
  data,
  width = 500,
  height = 500,
  showControls = true,
  interactive = true,
  onDimensionClick,
  className = '',
}: FlavorWheel3DProps) => {
  const containerRef = useRef<HTMLDivElement>(null)
  const [rotation, setRotation] = useState({ x: -20, y: 30 })
  const [zoom, setZoom] = useState(1)
  const [isDragging, setIsDragging] = useState(false)
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 })
  const [hoveredDimension, setHoveredDimension] = useState<FlavorDimension | null>(null)

  /**
   * 鼠标/触摸事件处理
   */
  const handlePointerDown = useCallback((e: React.PointerEvent) => {
    if (!interactive) return
    setIsDragging(true)
    setDragStart({ x: e.clientX, y: e.clientY })
    ;(e.target as HTMLElement).setPointerCapture(e.pointerId)
  }, [interactive])

  const handlePointerMove = useCallback((e: React.PointerEvent) => {
    if (!isDragging || !interactive) return

    const deltaX = e.clientX - dragStart.x
    const deltaY = e.clientY - dragStart.y

    setRotation(prev => ({
      x: Math.max(-90, Math.min(90, prev.x + deltaY * ROTATION_SPEED)),
      y: prev.y + deltaX * ROTATION_SPEED,
    }))

    setDragStart({ x: e.clientX, y: e.clientY })
  }, [isDragging, dragStart, interactive])

  const handlePointerUp = useCallback(() => {
    setIsDragging(false)
  }, [])

  /**
   * 滚轮缩放处理
   */
  const handleWheel = useCallback((e: React.WheelEvent) => {
    if (!interactive) return
    e.preventDefault()

    setZoom(prev => {
      const delta = e.deltaY > 0 ? -ZOOM_SPEED : ZOOM_SPEED
      return Math.max(MIN_ZOOM, Math.min(MAX_ZOOM, prev + delta))
    })
  }, [interactive])

  /**
   * 触摸手势处理（双指缩放）
   */
  const [touchDistance, setTouchDistance] = useState<number | null>(null)

  const handleTouchMove = useCallback((e: React.TouchEvent) => {
    if (!interactive || e.touches.length !== 2) return

    const touch1 = e.touches[0]
    const touch2 = e.touches[1]
    const distance = Math.hypot(
      touch2.clientX - touch1.clientX,
      touch2.clientY - touch1.clientY,
    )

    if (touchDistance !== null) {
      const scale = distance / touchDistance
      setZoom(prev => Math.max(MIN_ZOOM, Math.min(MAX_ZOOM, prev * scale)))
    }

    setTouchDistance(distance)
  }, [interactive, touchDistance])

  useEffect(() => {
    if (touchDistance === null && isDragging) {
      // 单指拖拽已在 handlePointerMove 中处理
    }
  }, [touchDistance, isDragging])

  /**
   * 控制按钮操作
   */
  const handleReset = useCallback(() => {
    setRotation({ x: -20, y: 30 })
    setZoom(1)
  }, [])

  const handleZoomIn = useCallback(() => {
    setZoom(prev => Math.min(MAX_ZOOM, prev + 0.2))
  }, [])

  const handleZoomOut = useCallback(() => {
    setZoom(prev => Math.max(MIN_ZOOM, prev - 0.2))
  }, [])

  /**
   * 计算多边形顶点坐标
   */
  const calculatePolygonPoints = useCallback((
    dimensions: FlavorDimension[],
    centerX: number,
    centerY: number,
    radius: number,
  ): string => {
    const angleStep = (Math.PI * 2) / dimensions.length
    return dimensions
      .map((dim, i) => {
        const angle = angleStep * i - Math.PI / 2
        const r = radius * (dim.value / 100)
        const x = centerX + r * Math.cos(angle)
        const y = centerY + r * Math.sin(angle)
        return `${x},${y}`
      })
      .join(' ')
  }, [])

  /**
   * 渲染单个数据集的雷达图
   */
  const renderRadarChart = useCallback(
    (flavorData: FlavorData, index: number) => {
      const cx = width / 2
      const cy = height / 2
      const maxRadius = Math.min(width, height) * 0.35

      return (
        <g key={flavorData.name} className="radar-chart">
          {/* 背景网格 */}
          {[0.25, 0.5, 0.75, 1].map((level) => (
            <polygon
              key={level}
              points={DEFAULT_DIMENSIONS.map((_, i) => {
                const angleStep = (Math.PI * 2) / DEFAULT_DIMENSIONS.length
                const angle = angleStep * i - Math.PI / 2
                const r = maxRadius * level
                return `${cx + r * Math.cos(angle)},${cy + r * Math.sin(angle)}`
              }).join(' ')}
              fill={index === 0 ? 'rgba(99, 102, 241, 0.05)' : 'none'}
              stroke="rgba(156, 163, 175, 0.3)"
              strokeWidth={0.5}
            />
          ))}

          {/* 轴线 */}
          {DEFAULT_DIMENSIONS.map((dim, i) => {
            const angleStep = (Math.PI * 2) / DEFAULT_DIMENSIONS.length
            const angle = angleStep * i - Math.PI / 2
            return (
              <line
                key={dim.id}
                x1={cx}
                y1={cy}
                x2={cx + maxRadius * Math.cos(angle)}
                y2={cy + maxRadius * Math.sin(angle)}
                stroke="rgba(156, 163, 175, 0.3)"
                strokeWidth={0.5}
              />
            )
          })}

          {/* 数据多边形 */}
          <polygon
            points={calculatePolygonPoints(
              flavorData.dimensions.map(d => ({
                ...d,
                ...DEFAULT_DIMENSIONS.find(def => def.id === d.id)!,
              })),
              cx,
              cy,
              maxRadius,
            )}
            fill={`hsla(${index * 60}, 70%, 60%, ${data.length > 1 ? 0.3 : 0.4})`}
            stroke={`hsl(${index * 60}, 70%, 50%)`}
            strokeWidth={2}
            style={{ transition: 'all 0.3s ease-out' }}
          />

          {/* 数据点和标签 */}
          {flavorData.dimensions.map((dim, i) => {
            const dimDef = DEFAULT_DIMENSIONS.find(d => d.id === dim.id)!
            const angleStep = (Math.PI * 2) / DEFAULT_DIMENSIONS.length
            const angle = angleStep * i - Math.PI / 2
            const r = maxRadius * (dim.value / 100)
            const x = cx + r * Math.cos(angle)
            const y = cy + r * Math.sin(angle)
            const labelX = cx + (maxRadius + 25) * Math.cos(angle)
            const labelY = cy + (maxRadius + 25) * Math.sin(angle)

            return (
              <g key={dim.id}>
                {/* 数据点 */}
                <circle
                  cx={x}
                  cy={y}
                  r={hoveredDimension?.id === dim.id ? 7 : 5}
                  fill={dimDef.color}
                  stroke="#fff"
                  strokeWidth={2}
                  style={{ cursor: 'pointer', transition: 'all 0.2s' }}
                  onMouseEnter={() => setHoveredDimension(dim)}
                  onMouseLeave={() => setHoveredDimension(null)}
                  onClick={() => onDimensionClick?.(dim)}
                />
                {/* 维度标签 */}
                <text
                  x={labelX}
                  y={labelY}
                  textAnchor="middle"
                  dominantBaseline="middle"
                  fontSize={12}
                  fontWeight={600}
                  fill={dimDef.color}
                >
                  {dimDef.label}
                </text>
                {/* 数值标签 */}
                <text
                  x={x}
                  y={y - 12}
                  textAnchor="middle"
                  fontSize={10}
                  fill="var(--color-gray-700, #374151)"
                >
                  {dim.value.toFixed(0)}
                </text>
              </g>
            )
          })}
        </g>
      )
    },
    [width, height, hoveredDimension, data.length, onDimensionClick, calculatePolygonPoints],
  )

  return (
    <div className={`relative ${className}`}>
      {/* 控制按钮 */}
      {showControls && (
        <div className="absolute top-4 right-4 z-10 flex flex-col gap-2">
          <button
            onClick={handleZoomIn}
            className="p-2 bg-white dark:bg-neutral-800 rounded-lg shadow-md hover:bg-neutral-50 dark:hover:bg-neutral-700 transition-colors"
            title="放大"
          >
            <ZoomIn className="w-4 h-4 text-neutral-600 dark:text-neutral-300" />
          </button>
          <button
            onClick={handleZoomOut}
            className="p-2 bg-white dark:bg-neutral-800 rounded-lg shadow-md hover:bg-neutral-50 dark:hover:bg-neutral-700 transition-colors"
            title="缩小"
          >
            <ZoomOut className="w-4 h-4 text-neutral-600 dark:text-neutral-300" />
          </button>
          <button
            onClick={handleReset}
            className="p-2 bg-white dark:bg-neutral-800 rounded-lg shadow-md hover:bg-neutral-50 dark:hover:bg-neutral-700 transition-colors"
            title="重置视图"
          >
            <RotateCcw className="w-4 h-4 text-neutral-600 dark:text-neutral-300" />
          </button>
          <div className="text-xs text-center text-neutral-500 dark:text-neutral-400 mt-1">
            {(zoom * 100).toFixed(0)}%
          </div>
        </div>
      )}

      {/* 3D 容器 */}
      <div
        ref={containerRef}
        className="relative overflow-hidden rounded-xl border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-900"
        style={{
          perspective: '1000px',
          width: `${width}px`,
          height: `${height}px`,
          maxWidth: '100%',
          margin: '0 auto',
        }}
        onWheel={handleWheel}
        onTouchMove={handleTouchMove}
      >
        {/* SVG 图表层 */}
        <svg
          width={width}
          height={height}
          viewBox={`0 0 ${width} ${height}`}
          style={{
            transform: `rotateX(${rotation.x}deg) rotateY(${rotation.y}deg) scale(${zoom})`,
            transformStyle: 'preserve-3d',
            transition: isDragging ? 'none' : 'transform 0.3s ease-out',
            cursor: interactive ? (isDragging ? 'grabbing' : 'grab') : 'default',
          }}
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={handlePointerUp}
          onPointerLeave={handlePointerUp}
        >
          {/* 渲染所有数据集 */}
          {data.map(renderRadarChart)}

          {/* 中心标题 */}
          {data.length === 1 && (
            <text
              x={width / 2}
              y={height / 2}
              textAnchor="middle"
              dominantBaseline="middle"
              fontSize={14}
              fontWeight={700}
              fill="var(--color-gray-700, #374151)"
            >
              {data[0].name}
            </text>
          )}

          {/* 多数据集图例 */}
          {data.length > 1 && (
            <g transform={`translate(${width - 80}, 10)`}>
              {data.map((d, i) => (
                <g key={i} transform={`translate(0, ${i * 18})`}>
                  <rect width={12} height={12} fill={`hsl(${i * 60}, 70%, 50%)`} rx={2} />
                  <text x={16} y={10} fontSize={10} fill="var(--color-gray-700, #374151)">{d.name}</text>
                </g>
              ))}
            </g>
          )}
        </svg>

        {/* 交互提示 */}
        {interactive && !isDragging && (
          <div className="absolute bottom-3 left-1/2 transform -translate-x-1/2 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] pointer-events-none select-none">
            拖拽旋转 · 滚轮缩放 · 点击查看详情
          </div>
        )}
      </div>

      {/* 悬停 Tooltip */}
      {hoveredDimension && (
        <Tooltip content={
          <div className="space-y-1">
            <div className="font-semibold" style={{ color: hoveredDimension.color }}>
              {hoveredDimension.label}
            </div>
            <div className="text-sm">强度值: {hoveredDimension.value.toFixed(1)}</div>
            {hoveredDimension.description && (
              <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{hoveredDimension.description}</div>
            )}
          </div>
        }>
          <div className="sr-only">维度信息</div>
        </Tooltip>
      )}
    </div>
  )
})

FlavorWheel3D.displayName = 'FlavorWheel3D'

