              style={{ width: `${metrics.healthScore}%` }}
            />
          </div>
        </div>

        {/* 详细指标 */}
        <div className="grid grid-cols-2 gap-2 text-xs">
          <div className="flex justify-between">
            <span className="text-neutral-500 dark:text-neutral-400">帧时间:</span>
