                            </button>
                          )}
                        </div>
                      </div>
                    ) : (
                      /* 完成后的操作栏 */
                      <div className="flex items-center gap-2 flex-wrap">
                        <span className="text-xs text-success-600 dark:text-success-600 font-medium flex items-center gap-1">
