 */

import React, { useState, useCallback, useRef, useEffect } from 'react'
import { Star, TrendingUp, Download, RefreshCw, BarChart3 } from 'lucide-react'
import { Button, Badge } from '@/components/ui'
import { logger } from '@/utils/safeLogger'

// ===== 类型定义 =====

export interface PreferenceRating {
  dimensionId: string
  dimensionLabel: string
  rating: number // 1-5
  timestamp: number
}

export interface PreferenceProfile {
  id: string
  userId?: string
  ratings: PreferenceRating[]
  createdAt: number
  updatedAt: number
}

interface RecommendedProduct {
  id: string
  name: string
  category: string
  similarityScore: number
  matchDimensions: string[]
  imageUrl?: string
  description?: string
}

interface PreferenceLearnerProps {
  dimensions: { id: string; label: string; icon?: React.ReactNode }[]
  initialRatings?: PreferenceRating[]
  onPreferenceChange?: (profile: PreferenceProfile) => void
  showRecommendations?: boolean
  maxHistoryItems?: number
  className?: string
}

// ===== 常量配置 =====

const DIMENSION_CONFIG = [
  { id: 'sour', label: '酸度', emoji: '🍋' },
  { id: 'sweet', label: '甜度', emoji: '🍯' },
  { id: 'bitter', label: '苦味', emoji: '☕' },
  { id: 'spicy', label: '辣度', emoji: '🌶️' },
  { id: 'umami', label: '鲜味', emoji: '🍲' },
  { id: 'astringent', label: '涩感', emoji: '🫒' },
]

// ===== 主组件实现 =====

function PreferenceLearner({
  dimensions = DIMENSION_CONFIG,
  initialRatings = [],
  onPreferenceChange,
  showRecommendations = true,
  maxHistoryItems = 10,
  className = '',
}: PreferenceLearnerProps) {
  const [ratings, setRatings] = useState<PreferenceRating[]>(
    initialRatings.length > 0
      ? initialRatings
      : dimensions.map(dim => ({
          dimensionId: dim.id,
          dimensionLabel: dim.label,
          rating: 3, // 默认中等偏好
          // eslint-disable-next-line react-hooks/purity
          timestamp: Date.now(),
        })),
  )
  const [history, setHistory] = useState<PreferenceProfile[]>([])
  const [recommendations, setRecommendations] = useState<RecommendedProduct[]>([])

  const svgRef = useRef<SVGSVGElement>(null)

  /**
   * 评分变更处理
   */
  const handleRatingChange = useCallback((dimensionId: string, newRating: number) => {
    setRatings(prev =>
      prev.map(r =>
        r.dimensionId === dimensionId
          ? { ...r, rating: newRating, timestamp: Date.now() }
          : r,
      ),
    )
  }, [])

  /**
   * 保存当前偏好到历史
   */
  const handleSaveToHistory = useCallback(() => {
    const profile: PreferenceProfile = {
      id: `pref_${Date.now()}`,
      ratings: [...ratings],
      createdAt: Date.now(),
      updatedAt: Date.now(),
    }

    setHistory(prev => [profile, ...prev].slice(0, maxHistoryItems))
    onPreferenceChange?.(profile)
    logger.info(`[PreferenceLearner] 偏好已保存到历史 (${ratings.length} 个维度)`)
  }, [ratings, maxHistoryItems, onPreferenceChange])

  /**
   * 生成推荐产品（模拟）
   */
  const generateRecommendations = useCallback(() => {
    const mockProducts: RecommendedProduct[] = [
      {
        id: 'prod_001',
        name: '清爽柠檬茶配方',
        category: '饮料',
        similarityScore: 92,
        matchDimensions: ['甜度', '酸度'],
        description: '酸甜平衡，清爽可口，适合夏季饮用。',
      },
      {
        id: 'prod_002',
        name: '麻辣火锅底料',
        category: '调味品',
        similarityScore: 87,
        matchDimensions: ['辣度', '鲜味'],
        description: '醇厚麻辣，鲜香浓郁，层次丰富。',
      },
      {
        id: 'prod_003',
        name: '抹茶拿铁奶盖',
        category: '饮品',
        similarityScore: 83,
        matchDimensions: ['苦味', '甜度'],
        description: '微苦回甘，奶香浓郁，口感丝滑。',
      },
      {
        id: 'prod_004',
        name: '陈皮梅子酱',
        category: '果酱',
        similarityScore: 78,
        matchDimensions: ['酸度', '涩感', '甜度'],
        description: '酸甜适中，陈香悠长，开胃消食。',
      },
    ]

    // 根据用户评分排序
    const sorted = mockProducts
      .map(p => ({
        ...p,
        similarityScore: p.similarityScore + (Math.random() * 10 - 5),
      }))
      .sort((a, b) => b.similarityScore - a.similarityScore)

    setRecommendations(sorted.slice(0, 3))
    logger.info('[PreferenceLearner] 已生成推荐列表')
  }, [ratings])

  /**
   * 绘制偏好曲线图表
   */
  useEffect(() => {
    if (!svgRef.current || ratings.length === 0) return

    const svg = window.d3?.select(svgRef.current)
    if (!svg) return

    // 简化的 D3 绑定逻辑（实际项目应使用完整 d3 库）
    // 这里仅作示例，实际应引入 d3-shape 等模块
  }, [ratings])

  /**
   * 导出偏好数据
   */
  const handleExport = useCallback(() => {
    const data = {
      exportedAt: new Date().toISOString(),
      currentRatings: ratings,
      historyCount: history.length,
    }

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `preference_profile_${Date.now()}.json`
    a.click()
    URL.revokeObjectURL(url)

    logger.info('[PreferenceLearner] 偏好数据已导出')
  }, [ratings, history.length])

  /**
   * 重置为默认评分
   */
  const handleReset = useCallback(() => {
    setRatings(
      dimensions.map(dim => ({
        dimensionId: dim.id,
        dimensionLabel: dim.label,
        rating: 3,
        timestamp: Date.now(),
      })),
    )
  }, [dimensions])

  // 自动生成推荐
  useEffect(() => {
    if (showRecommendations) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      generateRecommendations()
    }
  }, [ratings, showRecommendations, generateRecommendations])

  return (
    <div className={`bg-white dark:bg-neutral-800 rounded-xl border border-neutral-200 dark:border-neutral-700 shadow-sm p-6 space-y-6 ${className}`}>
      {/* 头部 */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-semibold text-neutral-900 dark:text-neutral-100 flex items-center gap-2">
            <Star className="w-5 h-5 text-warning-500" />
            口味偏好设置
          </h3>
          <p className="text-sm text-neutral-500 dark:text-neutral-400 mt-1">
            调整各维度的偏好强度，系统将为您推荐匹配的产品
          </p>
        </div>

        <div className="flex gap-2">
          <Button variant="outline" size="sm" icon={<RefreshCw className="w-4 h-4" />} onClick={handleReset}>
            重置
          </Button>
          <Button variant="outline" size="sm" icon={<Download className="w-4 h-4" />} onClick={handleExport}>
            导出
          </Button>
          <Button size="sm" icon={<TrendingUp className="w-4 h-4" />} onClick={handleSaveToHistory}>
            保存偏好
          </Button>
        </div>
      </div>

      {/* 评分滑块区域 */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {dimensions.map(dim => {
          const rating = ratings.find(r => r.dimensionId === dim.id)?.rating ?? 3
          const config = DIMENSION_CONFIG.find(c => c.id === dim.id)

          return (
            <div
              key={dim.id}
              className="bg-neutral-50 dark:bg-neutral-700/50 rounded-lg p-4 space-y-3"
            >
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <span className="text-2xl">{config?.emoji || '🎯'}</span>
                  <span className="font-medium text-neutral-900 dark:text-neutral-100">
                    {dim.label}
                  </span>
                </div>
                <Badge
                  variant={
                    rating <= 2 ? 'danger' : rating <= 3 ? 'warning' : rating <= 4 ? 'info' : 'success'
                  }
                >
                  {rating.toFixed(1)} 分
                </Badge>
              </div>

              {/* 滑块 */}
              <input
                type="range"
                min={1}
                max={5}
                step={0.1}
                value={rating}
                onChange={e => handleRatingChange(dim.id, Number(e.target.value))}
                className="w-full h-2 bg-neutral-200 dark:bg-neutral-600 rounded-lg appearance-none cursor-pointer accent-primary-600" aria-label="滑块" />

              {/* 星级显示 */}
              <div className="flex gap-1">
                {[1, 2, 3, 4, 5].map(star => (
                  <Star
                    key={star}
                    className={`w-5 h-5 ${
                      star <= Math.round(rating)
                        ? 'fill-warning-400 text-warning-400'
                        : 'text-neutral-300 dark:text-neutral-400'
                    }`}
                  />
                ))}
              </div>

              {/* 描述文字 */}
              <p className="text-xs text-neutral-500 dark:text-neutral-400 text-center">
                {rating <= 1.5
                  ? '极低偏好'
                  : rating <= 2.5
                  ? '较低偏好'
                  : rating <= 3.5
                  ? '中等偏好'
                  : rating <= 4.5
                  ? '较高偏好'
                  : '极高偏好'}
              </p>
            </div>
          )
        })}
      </div>

      {/* 偏好曲线可视化（简化版） */}
      <div className="border-t border-neutral-200 dark:border-neutral-700 pt-6">
        <h4 className="text-base font-semibold text-neutral-900 dark:text-neutral-100 mb-4 flex items-center gap-2">
          <BarChart3 className="w-5 h-5 text-primary-500" />
          偏好分布图
        </h4>
        <div className="relative h-48 bg-neutral-50 dark:bg-neutral-700/30 rounded-lg p-4">
          <svg ref={svgRef} width="100%" height="100%" viewBox="0 0 600 150">
            {/* 简单柱状图 */}
            {ratings.map((r, i) => {
              const barWidth = 60
              const barHeight = (r.rating / 5) * 120
              const x = i * (barWidth + 20) + 40
              const y = 140 - barHeight
              const colors = ['#F59E0B', '#EF4444', '#10b981', '#F97316', '#059669', '#0d9488']

              return (
                <g key={r.dimensionId}>
                  <rect
                    x={x}
                    y={y}
                    width={barWidth}
                    height={barHeight}
                    fill={colors[i]}
                    opacity={0.8}
                    rx={4}
                    style={{ transition: 'all 0.3s ease-out' }}
                  />
                  <text
                    x={x + barWidth / 2}
                    y={135}
                    textAnchor="middle"
                    fontSize={12}
                    fill="#6b7280"
                  >
                    {r.dimensionLabel}
                  </text>
                  <text
                    x={x + barWidth / 2}
                    y={y - 5}
                    textAnchor="middle"
                    fontSize={12}
                    fontWeight={600}
                    fill={colors[i]}
                  >
                    {r.rating.toFixed(1)}
                  </text>
                </g>
              )
            })}
          </svg>
        </div>
      </div>

      {/* 推荐产品列表 */}
      {showRecommendations && recommendations.length > 0 && (
        <div className="border-t border-neutral-200 dark:border-neutral-700 pt-6">
          <h4 className="text-base font-semibold text-neutral-900 dark:text-neutral-100 mb-4">
            为您推荐的产品
          </h4>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {recommendations.map(product => (
              <div
                key={product.id}
                className="bg-gradient-to-br from-primary-50 to-secondary-50 dark:from-primary-900/20 dark:to-secondary-900/20 rounded-lg p-4 border border-primary-200 dark:border-primary-800 hover:shadow-md transition-shadow"
              >
                <div className="flex items-start justify-between mb-2">
                  <h5 className="font-semibold text-neutral-900 dark:text-neutral-100 text-sm">
                    {product.name}
                  </h5>
                  <Badge variant="success">{product.similarityScore.toFixed(0)}% 匹配</Badge>
                </div>

                <p className="text-xs text-neutral-500 dark:text-neutral-400 mb-2">{product.category}</p>

                {product.description && (
                  <p className="text-xs text-neutral-600 dark:text-neutral-400 line-clamp-2 mb-3">
                    {product.description}
                  </p>
                )}

                <div className="flex flex-wrap gap-1">
                  {product.matchDimensions.map(dim => (
                    <span
                      key={dim}
                      className="px-2 py-0.5 text-xs font-medium bg-white dark:bg-neutral-700 rounded-full text-neutral-700 dark:text-neutral-300 border border-neutral-200 dark:border-neutral-600"
                    >
                      {dim}
                    </span>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 历史记录 */}
      {history.length > 0 && (
        <div className="border-t border-neutral-200 dark:border-neutral-700 pt-4">
          <details className="group">
            <summary className="cursor-pointer text-sm font-medium text-neutral-600 dark:text-neutral-400 hover:text-neutral-900 dark:hover:text-neutral-100 list-none flex items-center gap-2">
              <span>历史记录 ({history.length})</span>
              <span className="transition-transform group-open:rotate-180">▼</span>
            </summary>
            <div className="mt-3 space-y-2 max-h-48 overflow-y-auto">
              {history.map((profile, idx) => (
                <div
                  key={profile.id}
                  className="flex items-center justify-between px-3 py-2 bg-neutral-50 dark:bg-neutral-700/50 rounded-lg text-sm"
                >
                  <span className="text-neutral-600 dark:text-neutral-400">
                    #{idx + 1} · {new Date(profile.createdAt).toLocaleString('zh-CN')}
                  </span>
                  <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                    {profile.ratings.length} 维度评分
                  </span>
                </div>
              ))}
            </div>
          </details>
        </div>
      )}
    </div>
  )
}

export { PreferenceLearner }
export default PreferenceLearner

/**
 * PromptLibrary - 企业级提示词库UI组件
 *
 * 功能特性：
 * ✅ 多级分类导航（面包屑 + 树形结构）
 * ✅ 智能搜索与过滤
 * ✅ 模板卡片展示（含使用统计、收藏状态）
 * ✅ 一键插入与变量填充
 * ✅ 智能推荐区域
 * ✅ 响应式布局（桌面端/平板端/移动端）
 * ✅ 无障碍访问支持（ARIA、键盘导航）
 * ✅ 深色模式适配
 *
 * @version 2.0.0
 * @lastUpdated 2026-05-20
 */

import React, { useState, useCallback, useMemo } from 'react'
import { usePromptManager } from '../hooks/usePromptManager'
import {
  PromptTemplate,
  PromptCategory,
  PromptRecommendation,
} from '../hooks/types/prompt'
import { cn } from '@/lib/utils'
import { useToast } from '@/components/ui'
import {
  Search,
  Star,
  Heart,
  Copy,
  Edit3,
  Trash2,
  ChevronRight,
  ChevronDown,
  TrendingUp,
  Clock,
  Zap,
  X,
  Plus,
  Download,
  Upload,
  FileText,
  Tag,
  BookOpen,
  Sparkles,
  AlertCircle,
} from 'lucide-react'

interface PromptLibraryProps {
  /** 选择提示词回调 */
  onSelectPrompt: (prompt: PromptTemplate, renderedContent?: string) => void
  /** 关闭回调 */
  onClose?: () => void
  /** 自定义类名 */
  className?: string
  /** 是否显示 */
  visible?: boolean
}

export const PromptLibrary: React.FC<PromptLibraryProps> = ({
  onSelectPrompt,
  onClose,
  className,
  visible = true,
}) => {
  const promptManager = usePromptManager()
  const { error: toastError, warning: toastWarning, success: toastSuccess } = useToast()

  const [showEditor, setShowEditor] = useState(false)
  const [editingTemplate, setEditingTemplate] = useState<PromptTemplate | null>(null)
  const [variableValues, setVariableValues] = useState<Record<string, string>>({})
  const [activeTab, setActiveTab] = useState<'library' | 'recommendations' | 'favorites'>('library')
  const [showImportExport, setShowImportExport] = useState(false)
  const [expandedCategories, setExpandedCategories] = useState<Set<string>>(new Set(['cat_formula', 'cat_nutrition']))

  // ===== 分类导航 =====

  const toggleCategoryExpand = useCallback((categoryId: string) => {
    setExpandedCategories(prev => {
      const newSet = new Set(prev)
      if (newSet.has(categoryId)) {
        newSet.delete(categoryId)
      } else {
        newSet.add(categoryId)
      }
      return newSet
    })
  }, [])

  const renderCategoryTree = useCallback(
    (categories: PromptCategory[], level = 0) => {
      return categories.map(category => {
        const hasChildren = category.children && category.children.length > 0
        const isExpanded = expandedCategories.has(category.id)
        const isSelected = promptManager.selectedCategory === category.id

        return (
          <div key={category.id}>
            <button
              onClick={() => {
                if (hasChildren) {
                  toggleCategoryExpand(category.id)
                }
                promptManager.selectCategory(category.id)
              }}
              className={cn(
                'w-full flex items-center gap-2 px-3 py-2 text-sm rounded-lg transition-all duration-150',
                'hover:bg-neutral-100 dark:hover:bg-neutral-700/50',
                isSelected
                  ? 'bg-primary-50 dark:bg-primary-300/20 text-primary-700 dark:text-primary-700 font-medium'
                  : 'text-neutral-700 dark:text-neutral-300',
              )}
              style={{ paddingLeft: `${level * 16 + 12}px` }}
            >
              {hasChildren ? (
                isExpanded ? (
                  <ChevronDown className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
                ) : (
                  <ChevronRight className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
                )
              ) : (
                <div className="w-4" />
              )}
              <BookOpen className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
              <span className="flex-1 text-left">{category.name}</span>
              {category.children && (
                <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{category.children.length}</span>
              )}
            </button>

            {hasChildren && isExpanded && (
              <div className="ml-2">
                {/* eslint-disable-next-line react-hooks/immutability */}
                {renderCategoryTree(category.children || [], level + 1)}
              </div>
            )}
          </div>
        )
      })
    },
    [promptManager.selectedCategory, expandedCategories, toggleCategoryExpand],
  )

  // ===== 模板操作 =====

  const handleSelectPrompt = useCallback(
    (template: PromptTemplate) => {
      if (template.variables.length > 0) {
        setEditingTemplate(template)
        setVariableValues({})
        setShowEditor(true)
      } else {
        const renderedContent = promptManager.renderTemplate(template.id, {})
        promptManager.incrementUsage(template.id)
        onSelectPrompt(template, renderedContent)
      }
    },
    [onSelectPrompt, promptManager],
  )

  const handleInsertWithVariables = useCallback(() => {
    if (!editingTemplate) return

    const validation = promptManager.validateVariables(editingTemplate.id, variableValues)

    if (!validation.isValid) {
      toastError('请填写所有必填项')
      return
    }

    const renderedContent = promptManager.renderTemplate(editingTemplate.id, variableValues)
    promptManager.incrementUsage(editingTemplate.id)
    onSelectPrompt(editingTemplate, renderedContent)
    setShowEditor(false)
    setEditingTemplate(null)
  }, [editingTemplate, variableValues, onSelectPrompt, promptManager])

  // ===== 推荐列表 =====

  const recommendations = useMemo(
    () => promptManager.getRecommendations(8),
    [promptManager],
  )

  // ===== 导入/导出处理 =====

  const handleExport = useCallback(() => {
    const data = promptManager.exportPrompts()
    const blob = new Blob([data], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `rmfood-prompts-${new Date().toISOString().split('T')[0]}.json`
    a.click()
    URL.revokeObjectURL(url)
    setShowImportExport(false)
  }, [promptManager])

  const handleImport = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0]
      if (!file) return

      const reader = new FileReader()
      reader.onload = (event) => {
        const content = event.target?.result as string
        const result = promptManager.importPrompts(content)

        if (result.success) {
          toastSuccess(`成功导入 ${result.count} 个模板`)
        } else {
          toastWarning(`导入完成：${result.count} 成功，${result.errors.length} 失败`)
        }

        setShowImportExport(false)
      }
      reader.readAsText(file)
    },
    [promptManager],
  )

  if (!visible) return null

  return (
    <div
      className={cn(
        'fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm',
        'animate-[fadeIn_0.2s_ease-out]',
      )}
      onClick={(e) => { if (e.target === e.currentTarget) onClose?.() }}
      role="dialog"
      aria-modal="true"
      aria-label="提示词库"
    >
      <div
        className={cn(
          'relative w-full max-w-6xl max-h-[85vh] m-4',
          'bg-white dark:bg-neutral-900 rounded-2xl shadow-2xl',
          'border border-neutral-200 dark:border-neutral-700',
          'flex overflow-hidden',
          className,
        )}
      >
        {/* ===== 头部栏 ===== */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-neutral-200 dark:border-neutral-700 bg-gradient-to-r from-neutral-50 to-white dark:from-neutral-800 dark:to-neutral-900">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-primary-500 to-accent-500 flex items-center justify-center shadow-lg">
              <Sparkles className="w-5 h-5 text-white" />
            </div>
            <div>
              <h2 className="text-xl font-bold text-neutral-900 dark:text-white">智能提示词库</h2>
              <p className="text-xs text-neutral-500 dark:text-neutral-400">
                共 {promptManager.templates.length} 个模板 · {promptManager.filteredTemplates.length} 个可见
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <button
              onClick={() => setShowImportExport(!showImportExport)}
              className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg transition-colors"
              title="导入/导出"
            >
              <Download className="w-5 h-5 text-neutral-600 dark:text-neutral-400" />
            </button>

            <button
              onClick={() => {
                setEditingTemplate(null)
                setShowEditor(true)
              }}
              className="flex items-center gap-2 px-4 py-2 bg-primary-container hover:bg-primary-container text-primary-main rounded-lg transition-colors font-medium text-sm"
            >
              <Plus className="w-4 h-4" />
              新建模板
            </button>

            <button
              onClick={onClose}
              className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg transition-colors"
              title="关闭"
            >
              <X className="w-5 h-5 text-neutral-600 dark:text-neutral-400" />
            </button>
          </div>
        </div>

        {/* ===== 主体内容区 ===== */}
        <div className="flex flex-1 overflow-hidden">
          {/* 左侧：分类导航 */}
          <aside className="w-64 border-r border-neutral-200 dark:border-neutral-700 overflow-y-auto p-4 bg-neutral-50/50 dark:bg-neutral-800/30">
            <h3 className="text-xs font-semibold text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] uppercase tracking-wider mb-3 px-3">
              分类导航
            </h3>

            <button
              onClick={() => promptManager.selectCategory(null)}
              className={cn(
                'w-full flex items-center gap-2 px-3 py-2 text-sm rounded-lg mb-1 transition-all duration-150',
                !promptManager.selectedCategory
                  ? 'bg-primary-50 dark:bg-primary-300/20 text-primary-700 dark:text-primary-700 font-medium'
                  : 'text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-700/50',
              )}
            >
              <BookOpen className="w-4 h-4" />
              全部模板
            </button>

            <div className="mt-2 space-y-1">{renderCategoryTree(promptManager.getCategoryTree())}</div>

            {/* 统计信息 */}
            <div className="mt-6 pt-4 border-t border-neutral-200 dark:border-neutral-700">
              <div className="px-3 space-y-2">
                <div className="flex items-center justify-between text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                  <span>收藏</span>
                  <span className="font-medium text-neutral-700 dark:text-neutral-300">
                    {promptManager.templates.filter(t => t.isFavorite).length}
                  </span>
                </div>
                <div className="flex items-center justify-between text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                  <span>自定义</span>
                  <span className="font-medium text-neutral-700 dark:text-neutral-300">
                    {promptManager.templates.filter(t => !t.isBuiltin).length}
                  </span>
                </div>
              </div>
            </div>
          </aside>

          {/* 中间：主内容区 */}
          <main className="flex-1 flex flex-col overflow-hidden">
            {/* Tab切换 */}
            <div className="flex items-center gap-1 px-6 py-3 border-b border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-900">
              <button
                onClick={() => setActiveTab('library')}
                className={cn(
                  'px-4 py-2 text-sm font-medium rounded-lg transition-colors',
                  activeTab === 'library'
                    ? 'bg-primary-100 dark:bg-primary-300/25 text-primary-700 dark:text-primary-700'
                    : 'text-neutral-600 dark:text-neutral-400 hover:bg-neutral-100 dark:hover:bg-neutral-800',
                )}
              >
                <FileText className="w-4 h-4 inline mr-2" />
                提示词库
              </button>
              <button
                onClick={() => setActiveTab('recommendations')}
                className={cn(
                  'px-4 py-2 text-sm font-medium rounded-lg transition-colors relative',
                  activeTab === 'recommendations'
                    ? 'bg-primary-100 dark:bg-primary-300/25 text-primary-700 dark:text-primary-700'
                    : 'text-neutral-600 dark:text-neutral-400 hover:bg-neutral-100 dark:hover:bg-neutral-800',
                )}
              >
                <TrendingUp className="w-4 h-4 inline mr-2" />
                智能推荐
                {recommendations.length > 0 && (
                  <span className="absolute -top-1 -right-1 w-5 h-5 bg-error-500 text-white text-xs rounded-full flex items-center justify-center">
                    {recommendations.length}
                  </span>
                )}
              </button>
              <button
                onClick={() => setActiveTab('favorites')}
                className={cn(
                  'px-4 py-2 text-sm font-medium rounded-lg transition-colors',
                  activeTab === 'favorites'
                    ? 'bg-primary-100 dark:bg-primary-300/25 text-primary-700 dark:text-primary-700'
                    : 'text-neutral-600 dark:text-neutral-400 hover:bg-neutral-100 dark:hover:bg-neutral-800',
                )}
              >
                <Heart className="w-4 h-4 inline mr-2" />
                收藏夹
              </button>
            </div>

            {/* 搜索栏 */}
            <div className="px-6 py-4 border-b border-neutral-100 dark:border-neutral-800">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
                <input
                  type="text"
                  placeholder="搜索提示词（标题、描述、标签）..."
                  value={promptManager.searchQuery}
                  onChange={(e) => promptManager.searchTemplates(e.target.value)}
                  className="w-full pl-10 pr-4 py-2.5 bg-neutral-50 dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/50 focus:border-primary-400 transition-all"
                />
                {promptManager.searchQuery && (
                  <button
                    onClick={() => promptManager.searchTemplates('')}
                    className="absolute right-3 top-1/2 -translate-y-1/2 p-1 hover:bg-neutral-200 dark:hover:bg-neutral-700 rounded"
                  >
                    <X className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
                  </button>
                )}
              </div>
            </div>

            {/* 内容列表 */}
            <div className="flex-1 overflow-y-auto p-6">
              {activeTab === 'library' && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {promptManager.filteredTemplates.map((template) => (
                    <PromptCard
                      key={template.id}
                      template={template}
                      onSelect={() => handleSelectPrompt(template)}
                      onToggleFavorite={() => promptManager.toggleFavorite(template.id)}
                      onEdit={() => {
                        setEditingTemplate(template)
                        setShowEditor(true)
                      }}
                      onDelete={() => {
                        if (confirm('确定要删除此模板吗？')) {
                          promptManager.deleteTemplate(template.id)
                        }
                      }}
                      onDuplicate={() => promptManager.duplicateTemplate(template.id)}
                    />
                  ))}

                  {promptManager.filteredTemplates.length === 0 && (
                    <div className="col-span-full flex flex-col items-center justify-center py-16 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                      <AlertCircle className="w-16 h-16 mb-4 opacity-50" />
                      <p className="text-lg font-medium">未找到匹配的提示词</p>
                      <p className="text-sm mt-2">尝试调整搜索条件或选择其他分类</p>
                    </div>
                  )}
                </div>
              )}

              {activeTab === 'recommendations' && (
                <div className="space-y-3">
                  {recommendations.map((rec, index) => (
                    <RecommendationCard
                      key={rec.prompt.id}
                      recommendation={rec}
                      rank={index + 1}
                      onSelect={() => handleSelectPrompt(rec.prompt)}
                    />
                  ))}

                  {recommendations.length === 0 && (
                    <div className="flex flex-col items-center justify-center py-16 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                      <Zap className="w-16 h-16 mb-4 opacity-50" />
                      <p className="text-lg font-medium">暂无推荐</p>
                      <p className="text-sm mt-2">使用更多提示词后，系统将为您智能推荐</p>
                    </div>
                  )}
                </div>
              )}

              {activeTab === 'favorites' && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {promptManager.templates
                    .filter(t => t.isFavorite)
                    .map((template) => (
                      <PromptCard
                        key={template.id}
                        template={template}
                        onSelect={() => handleSelectPrompt(template)}
                        onToggleFavorite={() => promptManager.toggleFavorite(template.id)}
                        onEdit={() => {
                          setEditingTemplate(template)
                          setShowEditor(true)
                        }}
                        onDelete={() => {
                          if (confirm('确定要删除此模板吗？')) {
                            promptManager.deleteTemplate(template.id)
                          }
                        }}
                        onDuplicate={() => promptManager.duplicateTemplate(template.id)}
                      />
                    ))}

                  {promptManager.templates.filter(t => t.isFavorite).length === 0 && (
                    <div className="col-span-full flex flex-col items-center justify-center py-16 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                      <Heart className="w-16 h-16 mb-4 opacity-50" />
                      <p className="text-lg font-medium">暂无收藏</p>
                      <p className="text-sm mt-2">点击提示词卡片的星标图标即可收藏</p>
                    </div>
                  )}
                </div>
              )}
            </div>
          </main>
        </div>

        {/* ===== 变量编辑器（模态框） ===== */}
        {showEditor && editingTemplate && (
          <VariableEditorModal
            template={editingTemplate}
            values={variableValues}
            onChange={setVariableValues}
            onConfirm={handleInsertWithVariables}
            onCancel={() => {
              setShowEditor(false)
              setEditingTemplate(null)
            }}
          />
        )}

        {!showEditor && !editingTemplate && showEditor && (
          <VariableEditorModal
            template={{
              id: '',
              title: '',
              content: '',
              categoryId: '',
              tags: [],
              variables: [],
              isBuiltin: false,
              isFavorite: false,
              visibility: 'public',
              version: '1.0.0',
              // eslint-disable-next-line react-hooks/purity
              createdAt: Date.now(),
              // eslint-disable-next-line react-hooks/purity
              updatedAt: Date.now(),
              usageCount: 0,
            }}
            values={{}}
            onChange={setVariableValues}
            onConfirm={() => {}}
            onCancel={() => setShowEditor(false)}
          />
        )}

        {/* ===== 导入/导出面板 ===== */}
        {showImportExport && (
          <div className="absolute bottom-4 right-4 bg-white dark:bg-neutral-800 rounded-xl shadow-xl border border-neutral-200 dark:border-neutral-700 p-4 animate-in slide-in-from-bottom-2 fade-in duration-200">
            <div className="flex items-center gap-3">
              <button
                onClick={handleExport}
                className="flex items-center gap-2 px-4 py-2 bg-success-600 hover:bg-success-700 text-white rounded-lg text-sm font-medium transition-colors"
              >
                <Download className="w-4 h-4" />
                导出全部
              </button>

              <label className="flex items-center gap-2 px-4 py-2 bg-secondary-container hover:bg-secondary-container text-secondary-main rounded-lg text-sm font-medium cursor-pointer transition-colors">
                <Upload className="w-4 h-4" />
                导入文件
                <input type="file" accept=".json" onChange={handleImport} className="hidden" aria-hidden="true" tabIndex={-1} />
              </label>

              <button
                onClick={() => setShowImportExport(false)}
                className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-700 rounded-lg"
              >
                <X className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

// ============================================
// 子组件：提示词卡片
// ============================================

interface PromptCardProps {
  template: PromptTemplate
  onSelect: () => void
  onToggleFavorite: () => void
  onEdit: () => void
  onDelete: () => void
  onDuplicate: () => void
}

const PromptCard: React.FC<PromptCardProps> = ({
  template,
  onSelect,
  onToggleFavorite,
  onEdit,
  onDelete,
  onDuplicate,
}) => {
  const [showActions, setShowActions] = useState(false)

  return (
    <article
      className={cn(
        'group relative p-5 rounded-xl border transition-all duration-200 cursor-pointer',
        'bg-white dark:bg-neutral-800/50',
        'border-neutral-200 dark:border-neutral-700',
        'hover:border-primary-300 dark:hover:border-primary-600',
        'hover:shadow-lg hover:shadow-primary-500/10',
        template.isFavorite && 'ring-2 ring-warning-400/30 dark:ring-warning-500/20',
      )}
      onMouseEnter={() => setShowActions(true)}
      onMouseLeave={() => setShowActions(false)}
      onClick={onSelect}
      role="button"
      tabIndex={0}
      onKeyDown={e => (e.key === 'Enter' || e.key === ' ') && onSelect()}
    >
      {/* 头部：标题 + 收藏按钮 */}
      <div className="flex items-start justify-between mb-3">
        <h3 className="text-base font-semibold text-neutral-900 dark:text-white line-clamp-1 flex-1 mr-2">
          {template.title}
        </h3>

        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
          <button
            onClick={(e) => {
              e.stopPropagation()
              onToggleFavorite()
            }}
            className="p-1.5 hover:bg-neutral-100 dark:hover:bg-neutral-700 rounded-lg transition-colors"
            title={template.isFavorite ? '取消收藏' : '收藏'}
          >
            <Heart
              className={cn(
                'w-4 h-4',
                template.isFavorite
                  ? 'fill-warning-400 text-warning-400'
                  : 'text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-warning-400',
              )}
            />
          </button>
        </div>
      </div>

      {/* 描述 */}
      {template.description && (
        <p className="text-sm text-neutral-600 dark:text-neutral-400 line-clamp-2 mb-3">
          {template.description}
        </p>
      )}

      {/* 变量标签 */}
      {template.variables.length > 0 && (
        <div className="flex flex-wrap gap-1.5 mb-3">
          {template.variables.map(v => (
            <span
              key={v.name}
              className="inline-flex items-center px-2 py-0.5 bg-secondary-50 dark:bg-secondary-300/20 text-secondary-700 dark:text-secondary-700 text-xs font-mono rounded-md"
            >
              {'{{'}{v.label}{'}}'}
            </span>
          ))}
        </div>
      )}

      {/* 标签 */}
      <div className="flex flex-wrap gap-1.5 mb-3">
        {template.tags.slice(0, 3).map(tag => (
          <span
            key={tag}
            className="inline-flex items-center px-2 py-0.5 bg-neutral-100 dark:bg-neutral-700 text-neutral-600 dark:text-neutral-400 text-xs rounded-full"
          >
            <Tag className="w-3 h-3 mr-1" />
            {tag}
          </span>
        ))}
        {template.tags.length > 3 && (
          <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">+{template.tags.length - 3}</span>
        )}
      </div>

      {/* 底部：统计信息 + 操作按钮 */}
      <div className="flex items-center justify-between pt-3 border-t border-neutral-100 dark:border-neutral-700/50">
        <div className="flex items-center gap-3 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
          <span className="flex items-center gap-1">
            <Clock className="w-3.5 h-3.5" />
            使用 {template.usageCount} 次
          </span>
          {template.isBuiltin && (
            <span className="px-1.5 py-0.5 bg-accent-100 dark:bg-accent-300/25 text-accent-700 dark:text-accent-700 rounded text-xs font-medium">
              内置
            </span>
          )}
        </div>

        <div
          className={cn(
            'flex items-center gap-1 transition-opacity',
            showActions ? 'opacity-100' : 'opacity-0',
          )}
        >
          <button
            onClick={(e) => {
              e.stopPropagation()
              onEdit()
            }}
            className="p-1.5 hover:bg-neutral-100 dark:hover:bg-neutral-700 rounded-lg transition-colors"
            title="编辑"
          >
            <Edit3 className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
          </button>
          <button
            onClick={(e) => {
              e.stopPropagation()
              onDuplicate()
            }}
            className="p-1.5 hover:bg-neutral-100 dark:hover:bg-neutral-700 rounded-lg transition-colors"
            title="复制"
          >
            <Copy className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
          </button>
          {!template.isBuiltin && (
            <button
              onClick={(e) => {
                e.stopPropagation()
                onDelete()
              }}
              className="p-1.5 hover:bg-error-50 dark:hover:bg-error-900/20 rounded-lg transition-colors"
              title="删除"
            >
              <Trash2 className="w-4 h-4 text-error-400" />
            </button>
          )}
        </div>
      </div>
    </article>
  )
}

// ============================================
// 子组件：推荐卡片
// ============================================

interface RecommendationCardProps {
  recommendation: PromptRecommendation
  rank: number
  onSelect: () => void
}

const RecommendationCard: React.FC<RecommendationCardProps> = ({
  recommendation,
  rank,
  onSelect,
}) => {
  const reasonLabels: Record<string, { label: string; color: string; icon: React.ReactNode }> = {
    frequently_used: {
      label: '高频使用',
      color: 'bg-secondary-100 text-secondary-700 dark:bg-secondary-300/25 dark:text-secondary-700',
      icon: <TrendingUp className="w-3.5 h-3.5" />,
    },
    context_match: {
      label: '最近活跃',
      color: 'bg-success-100 text-success-700 dark:bg-success-300/25 dark:text-success-600',
      icon: <Clock className="w-3.5 h-3.5" />,
    },
    trending: {
      label: '上升趋势',
      color: 'bg-warning-100 text-warning-700 dark:bg-warning-300/25 dark:text-warning-700',
      icon: <Zap className="w-3.5 h-3.5" />,
    },
    similar_to_history: {
      label: '上下文匹配',
      color: 'bg-accent-100 text-accent-700 dark:bg-accent-300/25 dark:text-accent-700',
      icon: <Sparkles className="w-3.5 h-3.5" />,
    },
    new_and_relevant: {
      label: '新模板',
      color: 'bg-success-100 text-success-700 dark:bg-success-300/25 dark:text-success-700',
      icon: <Star className="w-3.5 h-3.5" />,
    },
  }

  const reasonInfo = reasonLabels[recommendation.reason] || reasonLabels.frequently_used

  return (
    <button
      onClick={onSelect}
      className="w-full flex items-center gap-4 p-4 rounded-xl border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-800/50 hover:border-primary-300 dark:hover:border-primary-600 hover:shadow-md transition-all text-left group"
    >
      {/* 排名 */}
      <div
        className={cn(
          'w-8 h-8 rounded-lg flex items-center justify-center text-sm font-bold',
          rank <= 3
            ? 'bg-gradient-to-br from-primary-500 to-accent-500 text-white shadow-lg'
            : 'bg-neutral-100 dark:bg-neutral-700 text-neutral-600 dark:text-neutral-400',
        )}
      >
        {rank}
      </div>

      {/* 信息区 */}
      <div className="flex-1 min-w-0">
        <h4 className="font-semibold text-neutral-900 dark:text-white truncate">
          {recommendation.prompt.title}
        </h4>
        <p className="text-sm text-neutral-500 dark:text-neutral-400 truncate mt-0.5">
          {recommendation.prompt.description || recommendation.prompt.content.slice(0, 80)}...
        </p>
      </div>

      {/* 推荐原因标签 */}
      <div className={cn('inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium shrink-0', reasonInfo.color)}>
        {reasonInfo.icon}
        {reasonInfo.label}
      </div>

      {/* 分数 */}
      <div className="text-right shrink-0">
        <div className="text-lg font-bold text-primary-700 dark:text-primary-700">
          {recommendation.score}
        </div>
        <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">分</div>
      </div>
    </button>
  )
}

// ============================================
// 子组件：变量编辑器模态框
// ============================================

interface VariableEditorModalProps {
  template: PromptTemplate
  values: Record<string, string>
  onChange: (values: Record<string, string>) => void
  onConfirm: () => void
  onCancel: () => void
}

const VariableEditorModal: React.FC<VariableEditorModalProps> = ({
  template,
  values,
  onChange,
  onConfirm,
  onCancel,
}) => {
  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/60 backdrop-blur-sm animate-[fadeIn_0.2s_ease-out]">
      <div className="w-full max-w-lg mx-4 bg-white dark:bg-neutral-900 rounded-2xl shadow-2xl border border-neutral-200 dark:border-neutral-700 overflow-hidden">
        {/* 头部 */}
        <div className="px-6 py-4 border-b border-neutral-200 dark:border-neutral-700 bg-gradient-to-r from-primary-50 to-white dark:from-primary-900/20 dark:to-neutral-900">
          <h3 className="text-lg font-bold text-neutral-900 dark:text-white">
            填写模板变量
          </h3>
          <p className="text-sm text-neutral-500 dark:text-neutral-400 mt-1">
            "{template.title}" 需要以下信息：
          </p>
        </div>

        {/* 表单内容 */}
        <div className="p-6 space-y-4 max-h-[60vh] overflow-y-auto">
          {template.variables.map(variable => (
            <div key={variable.name}>
              <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-1.5">
                {variable.label}
                {variable.required && <span className="text-error-500 ml-1">*</span>}
              </label>

              {variable.type === 'select' ? (
                <select
                  value={values[variable.name] || ''}
                  onChange={e =>
                    onChange({ ...values, [variable.name]: e.target.value })
                  }
                  className="w-full px-3 py-2.5 bg-white dark:bg-neutral-800 border border-neutral-300 dark:border-neutral-600 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/50"
                >
                  <option value="">请选择...</option>
                  {variable.options?.map(opt => (
                    <option key={opt.value} value={opt.value}>
                      {opt.label}
                    </option>
                  ))}
                </select>
              ) : variable.type === 'multiline' ? (
                <textarea
                  placeholder={variable.placeholder || `请输入${variable.label}`}
                  value={values[variable.name] || ''}
                  onChange={e =>
                    onChange({ ...values, [variable.name]: e.target.value })
                  }
                  rows={3}
                  className="w-full px-3 py-2.5 bg-white dark:bg-neutral-800 border border-neutral-300 dark:border-neutral-600 rounded-lg text-sm resize-none focus:outline-none focus:ring-2 focus:ring-primary-500/50"
                />
              ) : (
                <input
                  type={variable.type === 'number' ? 'number' : 'text'}
                  placeholder={variable.placeholder || `请输入${variable.label}`}
                  value={values[variable.name] || ''}
                  onChange={e =>
                    onChange({ ...values, [variable.name]: e.target.value })
                  }
                  className="w-full px-3 py-2.5 bg-white dark:bg-neutral-800 border border-neutral-300 dark:border-neutral-600 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary-500/50"
                />
              )}

              {variable.placeholder && variable.type !== 'multiline' && variable.type !== 'select' && (
                <p className="mt-1 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{variable.placeholder}</p>
              )}
            </div>
          ))}
        </div>

        {/* 操作按钮 */}
        <div className="flex items-center justify-end gap-3 px-6 py-4 border-t border-neutral-200 dark:border-neutral-700 bg-neutral-50/50 dark:bg-neutral-800/30">
          <button
            onClick={onCancel}
            className="px-4 py-2 text-sm font-medium text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-700 rounded-lg transition-colors"
          >
            取消
          </button>
          <button
            onClick={onConfirm}
            className="px-6 py-2 text-sm font-medium text-primary-main bg-primary-container hover:bg-primary-container rounded-lg transition-colors shadow-md hover:shadow-lg"
          >
            确认插入
          </button>
        </div>
      </div>
    </div>
  )
}

export default PromptLibrary

/**
 * RAG 知识库管理面板
 *
 *展示知识库状态、文档列表、统计信息，
 *支持一键初始化种子数据和上传自定义文档。
 */
import React, { useState, useEffect, useCallback } from 'react'
import {
  Database, Plus, Trash2, RefreshCw, CheckCircle, AlertCircle,
  FileText, ChevronDown, ChevronUp, X, Upload, Search, Loader2,
} from 'lucide-react'
import {
  getSeedStatus, seedKnowledgeBase, listDocuments, deleteDocument,
  uploadDocument, getRAGStats, type RAGStats,
} from '@/api/rag'
import { Card } from '@/components/ui'
import { logger } from '@/utils/safeLogger'

interface KBPanelProps {
  onClose: () => void
  onSeedComplete?: (chunks: number, files: string[]) => void
}

interface KBDoc {
  filename: string
  chunks: number
  created_at: string
}

export function RAGKnowledgePanel({ onClose, onSeedComplete }: KBPanelProps) {
  const [isSeeded, setIsSeeded] = useState(false)
  const [totalChunks, setTotalChunks] = useState(0)
  const [isSeeding, setIsSeeding] = useState(false)
  const [seedingProgress, setSeedingProgress] = useState(0)
  const [docs, setDocs] = useState<KBDoc[]>([])
  const [stats, setStats] = useState<RAGStats | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [uploading, setUploading] = useState(false)
  const [uploadProgress, setUploadProgress] = useState(0)
  const [expandedDocs, setExpandedDocs] = useState<Set<string>>(new Set())
  const [searchQuery, setSearchQuery] = useState('')

  const loadStatus = useCallback(async () => {
    try {
      setIsLoading(true)
      const [status, docList, ragStats] = await Promise.all([
        getSeedStatus(),
        listDocuments().catch(() => []),
        getRAGStats().catch(() => null),
      ])
      setIsSeeded(status.is_seeded)
      setTotalChunks(status.total_chunks ?? 0)
      setStats(ragStats)
      setError(null)
    } catch (e) {
      logger.warn('[RAGKnowledgePanel] 加载状态失败:', e)
      setError('无法连接知识库服务')
    } finally {
      setIsLoading(false)
    }
  }, [])

  useEffect(() => { loadStatus() }, [loadStatus])

  const handleSeed = async () => {
    setIsSeeding(true)
    setSeedingProgress(0)
    try {
      const result = await seedKnowledgeBase()
      setIsSeeded(result.seeded || totalChunks > 0)
      setTotalChunks(result.total_chunks ?? totalChunks)
      setSeedingProgress(100)
      // 从 documents 字段获取文件名列表
      const files = (result as unknown as { files?: string[] }).files || []
      if (files.length || result.seeded) {
        onSeedComplete?.(result.total_chunks, files)
      }
      await loadStatus()
    } catch (e) {
      logger.error('[RAGKnowledgePanel] 种子注入失败:', e)
      setError('种子注入失败，请检查后端日志')
    } finally {
      setIsSeeding(false)
    }
  }

  const handleUpload = async (file: File) => {
    setUploading(true)
    setUploadProgress(0)
    try {
      const info = await uploadDocument(file, (p) => setUploadProgress(p))
      setDocs(prev => [...prev, {
        filename: info.filename,
        chunks: info.chunk_count,
        created_at: info.created_at,
      }])
      setTotalChunks(prev => prev + info.chunk_count)
      setIsSeeded(true)
      setUploadProgress(100)
    } catch (e) {
      logger.error('[RAGKnowledgePanel] 上传失败:', e)
      setError('文档上传失败')
    } finally {
      setUploading(false)
      setUploadProgress(0)
    }
  }

  const handleDelete = async (filename: string) => {
    try {
      await deleteDocument(filename)
      setDocs(prev => prev.filter(d => d.filename !== filename))
      await loadStatus()
    } catch (e) {
      logger.error('[RAGKnowledgePanel] 删除失败:', e)
    }
  }

  const toggleDocExpand = (filename: string) => {
    setExpandedDocs(prev => {
      const next = new Set(prev)
      if (next.has(filename)) next.delete(filename)
      else next.add(filename)
      return next
    })
  }

  const filteredDocs = docs.filter(d =>
    d.filename.toLowerCase().includes(searchQuery.toLowerCase())
  )

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm">
      <Card className="w-full max-w-lg mx-4 max-h-[85vh] overflow-hidden flex flex-col bg-white dark:bg-neutral-900 border-neutral-200 dark:border-neutral-800">
        {/* 头部 */}
        <div className="flex items-center justify-between px-5 py-4 border-b border-neutral-200 dark:border-neutral-800">
          <div className="flex items-center gap-2.5">
            <div className={`w-8 h-8 rounded-lg flex items-center justify-center ${isSeeded ? 'bg-success-100 dark:bg-success-300/25' : 'bg-neutral-100 dark:bg-neutral-800'}`}>
              <Database className={`w-4 h-4 ${isSeeded ? 'text-success-700 dark:text-success-600' : 'text-neutral-500'}`} />
            </div>
            <div>
              <h2 className="font-semibold text-sm text-neutral-900 dark:text-white">知识库管理</h2>
              <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">RAG 向量检索 · 药食同源知识引擎</p>
            </div>
          </div>
          <button onClick={onClose} className="p-1.5 rounded-md hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors">
            <X className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
          </button>
        </div>

        {/* 内容区 */}
        <div className="flex-1 overflow-y-auto px-5 py-4 space-y-4">
          {/* 状态卡片 */}
          <div className={`rounded-xl border p-4 ${
            isSeeded
              ? 'bg-success-50 dark:bg-success-300/15 border-success-200 dark:border-success-900/30'
              : 'bg-warning-50 dark:bg-warning-300/15 border-warning-200 dark:border-warning-900/30'
          }`}>
            <div className="flex items-center gap-3">
              {isSeeded ? (
                <CheckCircle className="w-5 h-5 text-success-500 flex-shrink-0" />
              ) : isLoading ? (
                <RefreshCw className="w-5 h-5 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] animate-spin flex-shrink-0" />
              ) : (
                <AlertCircle className="w-5 h-5 text-warning-500 flex-shrink-0" />
              )}
              <div className="flex-1 min-w-0">
                <p className="font-medium text-sm {isSeeded ? 'text-success-800 dark:text-success-700' : 'text-warning-800 dark:text-warning-700'}">
                  {isLoading ? '加载中…' : isSeeded ? '知识库已就绪' : '知识库未初始化'}
                </p>
                <p className="text-xs text-neutral-500 dark:text-neutral-400 mt-0.5">
                  {isSeeded
                    ? `共 ${totalChunks.toLocaleString()} 个知识片段，{stats?.document_count ?? '?'} 篇文档`
                    : '内置药材库、药食同源目录、食品安全法规尚未注入'}
                </p>
              </div>
              <button
                onClick={handleSeed}
                disabled={isSeeding || isSeeded}
                className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${
                  isSeeded
                    ? 'bg-success-100 dark:bg-success-300/25 text-success-700 dark:text-success-700 cursor-default'
                    : isSeeding
                      ? 'bg-warning-100 dark:bg-warning-300/25 text-warning-700 dark:text-warning-700 cursor-wait'
                      : 'bg-success-500 text-white hover:bg-success-600 active:scale-95 shadow-sm'
                }`}
              >
                {isSeeding ? (
                  <>
                    <Loader2 className="w-3.5 h-3.5 animate-spin" />
                    {seedingProgress > 0 ? `${seedingProgress}%` : '初始化中…'}
                  </>
                ) : isSeeded ? (
                  <>
                    <CheckCircle className="w-3.5 h-3.5" />
                    已就绪
                  </>
                ) : (
                  <>
                    <Plus className="w-3.5 h-3.5" />
                    初始化
                  </>
                )}
              </button>
            </div>

            {/* 进度条 */}
            {isSeeding && seedingProgress > 0 && (
              <div className="mt-3 h-1.5 bg-warning-200 dark:bg-warning-300/25 rounded-full overflow-hidden">
                <div
                  className="h-full bg-success-500 rounded-full transition-all duration-500"
                  style={{ width: `${seedingProgress}%` }}
                />
              </div>
            )}
          </div>

          {/* 错误提示 */}
          {error && (
            <div className="flex items-center gap-2 px-3 py-2 bg-error-50 dark:bg-error-300/15 border border-error-200 dark:border-error-900/30 rounded-lg text-xs text-error-600 dark:text-error-700">
              <AlertCircle className="w-3.5 h-3.5 flex-shrink-0" />
              <span className="flex-1">{error}</span>
              <button onClick={() => setError(null)} className="flex-shrink-0"><X className="w-3 h-3" /></button>
            </div>
          )}

          {/* 操作栏 */}
          <div className="flex items-center gap-2">
            {/* 搜索 */}
            <div className="relative flex-1">
              <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
              <input
                value={searchQuery}
                onChange={e => setSearchQuery(e.target.value)}
                placeholder="搜索文档…"
                className="w-full pl-8 pr-3 py-1.5 text-xs bg-neutral-50 dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-lg focus:outline-none focus:ring-1 focus:ring-success-400 placeholder:text-neutral-400"
              />
            </div>
            {/* 刷新 */}
            <button onClick={loadStatus} className="p-1.5 rounded-lg bg-neutral-100 dark:bg-neutral-800 hover:bg-neutral-200 dark:hover:bg-neutral-700 transition-colors" title="刷新">
              <RefreshCw className="w-3.5 h-3.5 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
            </button>
          </div>

          {/* 文档列表 */}
          <div className="space-y-1.5">
            <div className="flex items-center justify-between px-1">
              <span className="text-xs font-medium text-neutral-500 dark:text-neutral-400">
                文档列表 ({filteredDocs.length})
              </span>
              {/* 上传按钮 */}
              <label className="flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-xs font-medium bg-neutral-100 dark:bg-neutral-800 text-neutral-600 dark:text-neutral-400 hover:bg-success-50 hover:text-success-600 dark:hover:bg-success-900/20 dark:hover:text-success-400 transition-colors cursor-pointer">
                <Upload className="w-3 h-3" />
                上传文档
                <input
                  type="file"
                  accept=".txt,.md,.pdf,.csv,.html"
                  className="hidden"
                  disabled={uploading}
                  onChange={e => {
                    const file = e.target.files?.[0]
                    if (file) handleUpload(file)
                    e.target.value = ''
                  }} aria-hidden="true" tabIndex={-1} />
              </label>
            </div>

            {filteredDocs.length === 0 && !isLoading ? (
              <div className="text-center py-8 text-xs text-neutral-400 dark:text-neutral-400">
                {isSeeded ? '暂无文档' : '点击"初始化"加载内置知识库'}
              </div>
            ) : (
              filteredDocs.map(doc => {
                const expanded = expandedDocs.has(doc.filename)
                return (
                  <div key={doc.filename} className="rounded-lg border border-neutral-100 dark:border-neutral-800 overflow-hidden">
                    <button
                      onClick={() => toggleDocExpand(doc.filename)}
                      className="w-full flex items-center gap-2.5 px-3 py-2.5 text-left hover:bg-neutral-50 dark:hover:bg-neutral-800/50 transition-colors"
                    >
                      <FileText className="w-4 h-4 text-success-500 flex-shrink-0" />
                      <div className="flex-1 min-w-0">
                        <p className="text-xs font-medium text-neutral-700 dark:text-neutral-300 truncate">{doc.filename}</p>
                        <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{doc.chunks} 个片段</p>
                      </div>
                      <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] flex-shrink-0">{new Date(doc.created_at).toLocaleDateString('zh-CN')}</span>
                      {expanded ? <ChevronUp className="w-3.5 h-3.5 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] flex-shrink-0" /> : <ChevronDown className="w-3.5 h-3.5 text-neutral-400 flex-shrink-0" />}
                    </button>
                    {expanded && (
                      <div className="border-t border-neutral-100 dark:border-neutral-800 px-3 py-2 flex items-center justify-end gap-2">
                        <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] flex-1">点击删除将永久移除该文档的所有知识片段</span>
                        <button
                          onClick={() => handleDelete(doc.filename)}
                          className="flex items-center gap-1 px-2 py-1 rounded text-xs text-error-500 hover:bg-error-50 dark:hover:bg-error-900/20 transition-colors"
                        >
                          <Trash2 className="w-3 h-3" />
                          删除
                        </button>
                      </div>
                    )}
                  </div>
                )
              })
            )}
          </div>

          {/* 上传进度 */}
          {uploading && (
            <div className="space-y-1.5">
              <div className="flex items-center gap-2 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                <Loader2 className="w-3.5 h-3.5 animate-spin" />
                <span>上传中… {uploadProgress}%</span>
              </div>
              <div className="h-1.5 bg-neutral-100 dark:bg-neutral-800 rounded-full overflow-hidden">
                <div className="h-full bg-success-500 rounded-full transition-all" style={{ width: `${uploadProgress}%` }} />
              </div>
            </div>
          )}
        </div>

        {/* 底部 */}
        <div className="flex items-center justify-end gap-2 px-5 py-3 border-t border-neutral-200 dark:border-neutral-800 bg-neutral-50 dark:bg-neutral-900/50">
          <button onClick={onClose} className="px-3 py-1.5 text-xs font-medium text-neutral-600 dark:text-neutral-400 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg transition-colors">
            关闭
          </button>
        </div>
      </Card>
    </div>
  )
}

/**
 * RecommendationPanel - 推荐参数调节面板 (v1.0)
 *
 * 提供算法选择、权重调节、推荐结果实时预览等功能。
 * 用于协同作用分析的参数调优和结果解释。
 *
 * 功能特性：
 * - 算法选择下拉框（至少 3 种算法）
 * - 权重滑块实时更新推荐结果（debounce 200ms）
 * - 推荐解释文本生成
 * - 参数预设保存/加载
 * - 响应式设计 + Dark Mode 支持
 *
 * @version 1.0.0
 * @lastUpdated 2026-05-12
 */

import React, { useState, useCallback, useMemo, useEffect } from 'react'
import {
  Sliders,
  Sparkles,
  RefreshCw,
  Save,
  FolderOpen,
  ChevronDown,
  ChevronUp,
  Info,
  Zap,
  Lightbulb,
} from 'lucide-react'
import { Button, Badge, Tooltip } from '@/components/ui'
import { logger } from '@/utils/safeLogger'

// ===== 类型定义 =====

export interface AlgorithmOption {
  id: string
  name: string
  description: string
  icon?: React.ReactNode
  parameters?: AlgorithmParameter[]
}

export interface AlgorithmParameter {
  id: string
  name: string
  label: string
  type: 'slider' | 'toggle' | 'select'
  min?: number
  max?: number
  step?: number
  default: number | boolean | string
  options?: { value: string; label: string }[]
  unit?: string
  description?: string
}

export interface RecommendationResult {
  id: string
  score: number
  confidence: number
  explanation: string
  data: Record<string, unknown>
  timestamp: number
}

interface RecommendationPanelProps {
  algorithms: AlgorithmOption[]
  onRecommendationChange?: (result: RecommendationResult) => void
  onParameterChange?: (algorithmId: string, params: Record<string, unknown>) => void
  defaultAlgorithmId?: string
  showPresets?: boolean
  className?: string
}

// ===== 常量配置 =====

const DEBOUNCE_MS = 200

// ===== 主组件实现 =====

function RecommendationPanel({
  algorithms,
  onRecommendationChange,
  onParameterChange,
  defaultAlgorithmId,
  showPresets = true,
  className = '',
}: RecommendationPanelProps) {
  const [selectedAlgorithmId, setSelectedAlgorithmId] = useState(
    defaultAlgorithmId || algorithms[0]?.id || '',
  )
  const [parameters, setParameters] = useState<Record<string, unknown>>({})
  const [result, setResult] = useState<RecommendationResult | null>(null)
  const [isCalculating, setIsCalculating] = useState(false)
  const [isExpanded, setIsExpanded] = useState(true)
  const [presets, setPresets] = useState<{
    name: string
    algorithmId: string
    parameters: Record<string, unknown>
  }[]>([])

  const selectedAlgorithm = useMemo(
    () => algorithms.find(a => a.id === selectedAlgorithmId),
    [algorithms, selectedAlgorithmId],
  )

  /**
   * 初始化默认参数
   */
  useEffect(() => {
    if (selectedAlgorithm?.parameters) {
      const defaults: Record<string, unknown> = {}
      selectedAlgorithm.parameters.forEach(param => {
        defaults[param.id] = param.default
      })
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setParameters(defaults)
    }
  }, [selectedAlgorithm])

  /**
   * 参数变更处理（带 debounce）
   */
  useEffect(() => {
    const timer = setTimeout(() => {
      // eslint-disable-next-line react-hooks/immutability
      calculateRecommendation()
    }, DEBOUNCE_MS)

    return () => clearTimeout(timer)
  }, [parameters, selectedAlgorithmId])

  /**
   * 计算推荐结果（模拟）
   */
  const calculateRecommendation = useCallback(async () => {
    if (!selectedAlgorithm) return

    setIsCalculating(true)

    try {
      await new Promise(resolve => setTimeout(resolve, 150))

      const score = Math.random() * 40 + 60
      const confidence = Math.random() * 20 + 80

      // eslint-disable-next-line react-hooks/immutability
      const explanation = generateExplanation(selectedAlgorithm.name, parameters, score)

      const newResult: RecommendationResult = {
        id: `rec_${Date.now()}`,
        score,
        confidence,
        explanation,
        data: {
          algorithm: selectedAlgorithm.name,
          parameters: { ...parameters },
          metrics: {
            precision: (Math.random() * 10 + 90).toFixed(1),
            recall: (Math.random() * 10 + 85).toFixed(1),
            f1Score: ((score + confidence) / 2).toFixed(1),
          },
        },
        timestamp: Date.now(),
      }

      setResult(newResult)
      onRecommendationChange?.(newResult)
      logger.info(`[RecommendationPanel] 推荐计算完成: score=${score.toFixed(1)}, algorithm=${selectedAlgorithm.name}`)
    } catch (error) {
      logger.error('[RecommendationPanel] 推荐计算失败:', error)
    } finally {
      setIsCalculating(false)
    }
  }, [selectedAlgorithm, parameters, onRecommendationChange])

  /**
   * 生成推荐解释文本
   */
  const generateExplanation = useCallback((
    algorithmName: string,
    params: Record<string, unknown>,
    score: number,
  ): string => {
    const paramEntries = Object.entries(params)
      .filter(([, v]) => typeof v === 'number')
      .map(([k, v]) => `${k}=${Number(v).toFixed(2)}`)

    const templates = [
      `基于 ${algorithmName} 算法分析，当前参数组合 (${paramEntries.join(', ')}) 的综合评分为 ${score.toFixed(1)} 分。`,
      `通过调整关键参数权重，系统识别出最优协同作用模式。当前配置在${score >= 80 ? '高效' : score >= 60 ? '中等' : '待优化'}区间运行。`,
      `算法 ${algorithmName} 根据多维特征空间映射，给出置信度 ${(score * 0.9 + 10).toFixed(1)}% 的推荐方案。`,
    ]

    return templates[Math.floor(Math.random() * templates.length)]
  }, [])

  /**
   * 参数值更新
   */
  const handleParameterChange = useCallback((paramId: string, value: unknown) => {
    setParameters(prev => ({ ...prev, [paramId]: value }))
    onParameterChange?.(selectedAlgorithmId, { ...parameters, [paramId]: value })
  }, [selectedAlgorithmId, parameters, onParameterChange])

  /**
   * 保存预设
   */
  const handleSavePreset = useCallback(() => {
    const presetName = prompt('请输入预设名称：')
    if (!presetName) return

    const newPreset = {
      name: presetName,
      algorithmId: selectedAlgorithmId,
      parameters: { ...parameters },
    }

    setPresets(prev => [...prev, newPreset])
    logger.info(`[RecommendationPanel] 预设已保存: ${presetName}`)
  }, [selectedAlgorithmId, parameters])

  /**
   * 加载预设
   */
  const handleLoadPreset = useCallback((preset: typeof presets[0]) => {
    setSelectedAlgorithmId(preset.algorithmId)
    setParameters(preset.parameters)
    logger.info(`[RecommendationPanel] 预设已加载: ${preset.name}`)
  }, [])

  /**
   * 重置为默认参数
   */
  const handleReset = useCallback(() => {
    if (selectedAlgorithm?.parameters) {
      const defaults: Record<string, unknown> = {}
      selectedAlgorithm.parameters.forEach(param => {
        defaults[param.id] = param.default
      })
      setParameters(defaults)
    }
  }, [selectedAlgorithm])

  return (
    <div className={`bg-white dark:bg-neutral-800 rounded-xl border border-neutral-200 dark:border-neutral-700 shadow-sm overflow-hidden ${className}`}>
      <div
        className="flex items-center justify-between p-4 cursor-pointer hover:bg-neutral-50 dark:bg-neutral-800 dark:hover:bg-neutral-700/50 transition-colors"
         role="button" tabIndex={0} onClick={() => setIsExpanded(!isExpanded)}
      >
        <div className="flex items-center gap-3">
          <div className="p-2 bg-primary-100 dark:bg-primary-300/25 rounded-lg">
            <Sliders className="w-5 h-5 text-primary-700 dark:text-primary-700" />
          </div>
          <div>
