              <div className="absolute left-4 top-0 bottom-0 w-0.5 bg-gradient-to-b from-accent-300 via-accent-300 to-danger-300 dark:from-accent-700 dark:via-accent-700 dark:to-danger-700" />
              <div className="space-y-1">
