  describe('Message Rendering', () => {
    const mockMessages = [
      {
        id: '1',
        role: 'user' as const,
        content: 'Hello, how are you?',
        timestamp: Date.now(),
      },
      {
        id: '2',
        role: 'assistant' as const,
        content: 'I am doing well, thank you!',
        timestamp: Date.now() + 1000,
      },
