  describe('Message Reference', () => {
    const mockMessages = [
      {
        id: '1',
        role: 'user' as const,
        content: 'Original message',
        timestamp: Date.now(),
      },
    ]

    it('should call onReferenceMessage when reference action is triggered', () => {
