/**
 * ChartBlock — 可视化图表区块
 *
 * 根据 chartType 分派到现有图表组件：
 * - radar → RadarChart
 * - bar → BarChart
 * - score-cards → ScoreCards
 *
 * 统一的卡片容器 + 标题栏
 */
import React from 'react'
import { BarChart3, Loader2 } from 'lucide-react'
import { RadarChart } from '@/components/ai/charts/RadarChart'
import { BarChart } from '@/components/ai/charts/BarChart'
import { ScoreCards } from '@/components/ai/charts/ScoreCards'
import type { ChartData } from '../types'

interface ChartBlockProps {
  data: ChartData
}

function ChartBlock({ data }: ChartBlockProps) {
  const { chartType, title, data: chartData } = data

  if (!chartData || Object.keys(chartData).length === 0) {
    return null
  }

  const renderChart = () => {
    switch (chartType) {
      case 'radar':
        // RadarChart 接受 { synergy, taste, stability, safety }
        return <RadarChart data={chartData as { synergy: number; taste: number; stability: number; safety: number }} />

      case 'bar':
        // BarChart 接受 IngredientContribution[]
        return <BarChart data={chartData as unknown as Array<{ name: string; contribution: number; category: 'synergy' | 'safety' | 'taste' | 'stability' }>} />

      case 'score-cards':
        // ScoreCards 接受 { synergyScore, tasteScore, stabilityScore, overallScore }
        const sc = chartData as unknown as Record<string, number | null | undefined>
        return (
          <ScoreCards
            synergyScore={sc.synergyScore ?? null}
            tasteScore={sc.tasteScore ?? null}
            stabilityScore={sc.stabilityScore ?? null}
            overallScore={sc.overallScore ?? null}
          />
        )

      default:
        return (
          <div className="text-center py-4">
            <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">暂不支持的图表类型: {chartType}</p>
          </div>
        )
    }
  }

  return (
    <div className="mb-3 last:mb-0">
      {/* 卡片容器 */}
      <div className="rounded-xl border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-900 overflow-hidden">
        {/* 标题栏 */}
        {title && (
          <div className="flex items-center gap-1.5 px-4 py-2.5 border-b border-neutral-100 dark:border-neutral-800
            bg-gradient-to-r from-secondary-50/60 to-transparent dark:from-secondary-950/20 dark:to-transparent">
            <BarChart3 className="w-3.5 h-3.5 text-secondary-500" />
            <span className="text-xs font-semibold text-neutral-700 dark:text-neutral-300">{title}</span>
          </div>
        )}

        {/* 图表内容 */}
        <div className="p-3">
          {renderChart()}
        </div>
      </div>
    </div>
  )
}

export default ChartBlock

/**
 * ListBlock — 分析列表区块
 *
 * 四种变体：
 * - bullet: 圆点列表（通用）
 * - number: 编号列表（步骤/排序）
 * - analysis: 带状态图标的分析列表（🟢🟡🔴）
 * - checklist: 勾选清单
 *
 * 每种变体有独立的视觉风格
 */
import React from 'react'
import { CheckCircle2, Circle, ChevronRight, HelpCircle } from 'lucide-react'
import type { ListData } from '../types'

interface ListBlockProps {
  data: ListData
}

const STATUS_ICONS = {
  positive: CheckCircle2,
  negative: HelpCircle,
  neutral: Circle,
  info: ChevronRight,
} as const

const STATUS_COLORS = {
  positive: 'text-primary-500 dark:text-primary-700',
  negative: 'text-error-500 dark:text-error-600',
  neutral: 'text-neutral-400 dark:text-neutral-400',
  info: 'text-secondary-500 dark:text-secondary-700',
} as const

const BULLET_COLORS = [
  'text-primary-500',
  'text-secondary-500',
  'text-primary-500',
  'text-warning-500',
  'text-accent-500',
]

function ListBlock({ data }: ListBlockProps) {
  // 兼容 LLM 常见变体：自动推断 variant，归一化 items
  const rawItems = data.items || []
  const normalizedItems = rawItems.map((item: any) => {
    if (typeof item === 'string') return { label: item }
    return item
  })
  const inferredVariant: 'bullet' | 'number' | 'analysis' | 'checklist' =
    data.variant || (normalizedItems.some((i: any) => i.description) ? 'analysis' : 'bullet')

  const normalizedData: ListData = {
    ...data,
    variant: inferredVariant,
    items: normalizedItems,
  }

  const { title, variant, items = normalizedItems } = normalizedData

  if (items.length === 0) {
    return (
      <div className="py-3 text-center text-xs text-neutral-300 dark:text-neutral-400">
        暂无列表数据
      </div>
    )
  }

  return (
    <div className="mb-3 last:mb-0">
      {/* 标题 */}
      {title && (
        <div className="text-xs font-semibold text-neutral-700 dark:text-neutral-300 mb-2">
          {title}
        </div>
      )}

      {/* 列表内容 */}
      <div className="space-y-1.5">
        {items.map((item, i) => {
          // — bullet 变体 —
          if (variant === 'bullet') {
            const color = BULLET_COLORS[i % BULLET_COLORS.length]
            return (
              <div key={i} className="flex items-start gap-2">
                <span className={`flex-shrink-0 mt-0.5 w-1.5 h-1.5 rounded-full ${color} bg-current`} />
                <div className="min-w-0 flex-1">
                  <span className="text-xs text-neutral-700 dark:text-neutral-300 leading-relaxed">
                    {item.label}
                  </span>
                  {item.description && (
                    <p className="text-xs text-neutral-400 dark:text-neutral-400 mt-0.5 leading-relaxed">
                      {item.description}
                    </p>
                  )}
                </div>
                {item.value && (
                  <span className="flex-shrink-0 text-xs font-mono text-neutral-400 dark:text-neutral-400">
                    {item.value}
                  </span>
                )}
              </div>
            )
          }

          // — number 变体 —
          if (variant === 'number') {
            return (
              <div key={i} className="flex items-start gap-2.5">
                <span className="flex-shrink-0 w-5 h-5 rounded-md bg-neutral-100 dark:bg-neutral-800
                  flex items-center justify-center text-xs font-bold text-neutral-500 dark:text-neutral-400">
                  {i + 1}
                </span>
                <div className="min-w-0 flex-1 pt-0.5">
                  <span className="text-xs text-neutral-700 dark:text-neutral-300 leading-relaxed">
                    {item.label}
                  </span>
                  {item.description && (
                    <p className="text-xs text-neutral-400 dark:text-neutral-400 mt-0.5 leading-relaxed">
                      {item.description}
                    </p>
                  )}
                </div>
              </div>
            )
          }

          // — analysis 变体 —
          if (variant === 'analysis') {
            const status = (item.status || 'neutral') as keyof typeof STATUS_ICONS
            const StatusIcon = STATUS_ICONS[status] ?? Circle
            const statusColor = STATUS_COLORS[status] ?? STATUS_COLORS.neutral
            return (
              <div key={i} className="flex items-start gap-2 px-2.5 py-2 rounded-lg
                bg-neutral-50 dark:bg-neutral-800/40 border border-neutral-100 dark:border-neutral-700/50">
                <StatusIcon className={`flex-shrink-0 w-3.5 h-3.5 mt-0.5 ${statusColor}`} />
                <div className="min-w-0 flex-1">
                  <div className="flex items-baseline justify-between gap-2">
                    <span className="text-xs font-medium text-neutral-800 dark:text-neutral-200">
                      {item.label}
                    </span>
                    {item.value && (
                      <span className="flex-shrink-0 text-xs font-mono text-neutral-400 dark:text-neutral-400">
                        {item.value}
                      </span>
                    )}
                  </div>
                  {item.description && (
                    <p className="text-xs text-neutral-400 dark:text-neutral-400 mt-0.5 leading-relaxed">
                      {item.description}
                    </p>
                  )}
                </div>
              </div>
            )
          }

          // — checklist 变体 —
          if (variant === 'checklist') {
            const isPositive = item.status === 'positive'
            return (
              <div key={i} className="flex items-start gap-2">
                <CheckCircle2 className={`flex-shrink-0 w-3.5 h-3.5 mt-0.5 ${
                  isPositive
                    ? 'text-primary-500 dark:text-primary-700'
                    : 'text-neutral-300 dark:text-neutral-400'
                }`} />
                <span className={`text-xs leading-relaxed ${
                  isPositive
                    ? 'text-neutral-700 dark:text-neutral-300'
                    : 'text-neutral-400 dark:text-neutral-400 line-through'
                }`}>
                  {item.label}
                </span>
              </div>
            )
          }

          return null
        })}
      </div>
    </div>
  )
}

export default ListBlock

/**
 * SynergyChartBlock — 配伍关系图
 *
 * 展示君臣佐使层级关系或成分协同网络
 * 支持两种模式：hierarchy（层级树）/ network（关系图）
 */
import React, { useState } from 'react'
import { Network, GitBranch, TrendingUp } from 'lucide-react'
import type { SynergyChartData, SynergyNode, SynergyEdge } from '../types'

interface SynergyChartBlockProps {
  data: SynergyChartData
}

function SynergyChartBlock({ data }: SynergyChartBlockProps) {
  const { type = 'hierarchy', title, nodes = [], edges = [] } = data
  const [selectedNode, setSelectedNode] = useState<string | null>(null)

  const roleColors: Record<string, string> = {
    '君': 'text-primary-700 dark:text-primary-700 bg-primary-100 dark:bg-primary-300/25 border-primary-300 dark:border-primary-700',
    '臣': 'text-secondary-600 dark:text-secondary-700 bg-secondary-100 dark:bg-secondary-300/25 border-secondary-300 dark:border-secondary-700',
    '佐': 'text-accent-600 dark:text-accent-700 bg-accent-100 dark:bg-accent-300/25 border-accent-300 dark:border-accent-700',
    '使': 'text-warning-600 dark:text-warning-700 bg-warning-100 dark:bg-warning-300/25 border-warning-300 dark:border-warning-700',
    '其他': 'text-neutral-600 dark:text-neutral-400 bg-neutral-100 dark:bg-neutral-800 border-neutral-300 dark:border-neutral-700',
  }

  const roleLabels: Record<string, string> = {
    '君': '君',
    '臣': '臣',
    '佐': '佐',
    '使': '使',
    '其他': '其他',
  }

  // 按层级分组节点
  const levelGroups: Record<number, SynergyNode[]> = {}
  nodes.forEach(node => {
    const level = node.level ?? 0
    if (!levelGroups[level]) levelGroups[level] = []
    levelGroups[level].push(node)
  })

  const sortedLevels = Object.keys(levelGroups)
    .map(Number)
    .sort((a, b) => a - b)

  if (nodes.length === 0) {
    return (
      <div className="mb-3 last:mb-0 rounded-lg border border-neutral-200 dark:border-neutral-700 p-6 text-center">
        <Network className="w-8 h-8 mx-auto text-neutral-300 dark:text-neutral-400 mb-2" />
        <p className="text-xs text-neutral-400 dark:text-neutral-400">暂无配伍数据</p>
      </div>
    )
  }

  return (
    <div className="mb-3 last:mb-0 rounded-xl border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-900 overflow-hidden">
      {/* 标题栏 */}
      <div className="flex items-center justify-between px-4 py-2.5 bg-neutral-50 dark:bg-neutral-800/50 border-b border-neutral-200 dark:border-neutral-700">
        <div className="flex items-center gap-2">
          <GitBranch className="w-4 h-4 text-primary-500" />
          <span className="text-xs font-semibold text-neutral-700 dark:text-neutral-300">
            {title || '配伍关系'}
          </span>
        </div>
        <div className="flex items-center gap-1.5">
          {type === 'hierarchy' ? (
            <span className="text-xs px-2 py-0.5 rounded-full bg-primary-100 dark:bg-primary-300/25 text-primary-700 dark:text-primary-700">
              层级模式
            </span>
          ) : (
            <span className="text-xs px-2 py-0.5 rounded-full bg-accent-100 dark:bg-accent-300/25 text-accent-600 dark:text-accent-700">
              网络模式
            </span>
          )}
        </div>
      </div>

      {/* 图表内容 */}
      <div className="p-4">
        {type === 'hierarchy' ? (
          <div className="space-y-3">
            {sortedLevels.map((level) => {
              const levelNodes = levelGroups[level]
              return (
                <div key={level} className="flex justify-center gap-3 flex-wrap">
                  {levelNodes.map((node) => {
                    const isSelected = selectedNode === node.id
                    return (
                      <button
                        key={node.id}
                        onClick={() => setSelectedNode(isSelected ? null : node.id)}
                        className={`px-3 py-2 rounded-lg border text-center transition-all duration-200 ${
                          isSelected
                            ? 'ring-2 ring-primary-500 ring-offset-2 dark:ring-offset-neutral-900 scale-105'
                            : 'hover:shadow-md'
                        } ${roleColors[node.role] || roleColors['其他']}`}
                      >
                        <div className="text-xs font-bold">{node.label}</div>
                        <div className="text-xs opacity-75 mt-0.5">{roleLabels[node.role] || node.role}</div>
                      </button>
                    )
                  })}
                </div>
              )
            })}

            {/* 连接说明 */}
            {edges.length > 0 && (
              <div className="mt-4 pt-3 border-t border-neutral-100 dark:border-neutral-800">
                <div className="text-xs text-neutral-500 dark:text-neutral-400 mb-2">配伍关系</div>
                <div className="space-y-1">
                  {edges.slice(0, 5).map((edge, i) => (
                    <div key={i} className="flex items-center gap-2 text-xs text-neutral-600 dark:text-neutral-400">
                      <span className="font-medium">{edge.from}</span>
                      <TrendingUp className="w-3 h-3 text-primary-400" />
                      <span className="font-medium">{edge.to}</span>
                      {edge.type && (
                        <span className="ml-auto px-1.5 py-0.5 rounded bg-neutral-100 dark:bg-neutral-800 text-neutral-500">
                          {edge.type}
                        </span>
                      )}
                    </div>
                  ))}
                  {edges.length > 5 && (
                    <div className="text-xs text-neutral-400 dark:text-neutral-400 italic">
                      ... 还有 {edges.length - 5} 条关系
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>
        ) : (
          /* Network 模式简化展示 */
          <div className="space-y-2">
            {nodes.map((node) => (
              <div key={node.id} className="flex items-center gap-3 p-2 rounded-lg hover:bg-neutral-50 dark:hover:bg-neutral-800/50 transition-colors">
                <span className={`px-2 py-1 rounded text-xs font-bold ${roleColors[node.role] || roleColors['其他']}`}>
                  {roleLabels[node.role]}
                </span>
                <span className="text-xs font-medium text-neutral-700 dark:text-neutral-300 flex-1">
                  {node.label}
                </span>
                {edges.filter(e => e.from === node.id || e.to === node.id).length > 0 && (
                  <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                    {edges.filter(e => e.from === node.id || e.to === node.id).length} 条关系
                  </span>
                )}
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

export default SynergyChartBlock

/**
 * TimelineBlock — 服用周期时间线
 *
 * 展示多阶段服药方案的时间轴
 * 每个阶段包含：天数、阶段名、说明、剂量、注意事项
 */
import React, { useState } from 'react'
import { Clock, Calendar, Pill, AlertCircle, CheckCircle2 } from 'lucide-react'
import type { TimelineData, TimelinePhase, TimelineItem } from '../types'

interface TimelineBlockProps {
  data: TimelineData
}

const PHASE_COLORS: Record<TimelinePhase, {
  bg: string
  border: string
  text: string
  dot: string
}> = {
  '初期': {
    bg: 'bg-secondary-50 dark:bg-secondary-300/20',
    border: 'border-secondary-200 dark:border-secondary-800',
    text: 'text-secondary-700 dark:text-secondary-700',
    dot: 'bg-secondary-500',
  },
  '中期': {
    bg: 'bg-primary-50 dark:bg-success-300/20',
    border: 'border-success-200 dark:border-success-800',
    text: 'text-success-700 dark:text-success-700',
    dot: 'bg-success-500',
  },
  '后期': {
    bg: 'bg-warning-50 dark:bg-warning-300/20',
    border: 'border-warning-200 dark:border-warning-800',
    text: 'text-warning-700 dark:text-warning-700',
    dot: 'bg-warning-500',
  },
  '巩固': {
    bg: 'bg-accent-50 dark:bg-accent-300/20',
    border: 'border-accent-200 dark:border-accent-800',
    text: 'text-accent-700 dark:text-accent-700',
    dot: 'bg-accent-500',
  },
}

function TimelineBlock({ data }: TimelineBlockProps) {
  const { title, duration_days, phases = [], items = [] } = data
  const [expandedDay, setExpandedDay] = useState<number | null>(null)

  // 按天数排序
  const sortedItems = [...items].sort((a, b) => a.day - b.day)

  // 计算总天数覆盖范围
  const maxDay = Math.max(...sortedItems.map(i => i.day), duration_days)

  if (items.length === 0) {
    return (
      <div className="mb-3 last:mb-0 rounded-lg border border-neutral-200 dark:border-neutral-700 p-6 text-center">
        <Calendar className="w-8 h-8 mx-auto text-neutral-300 dark:text-neutral-400 mb-2" />
        <p className="text-xs text-neutral-400 dark:text-neutral-400">暂无疗程数据</p>
      </div>
    )
  }

  return (
    <div className="mb-3 last:mb-0 rounded-xl border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-900 overflow-hidden">
      {/* 标题栏 */}
      <div className="flex items-center justify-between px-4 py-3 bg-gradient-to-r from-primary-50/50 to-transparent dark:from-primary-900/10 border-b border-neutral-100 dark:border-neutral-800">
        <div className="flex items-center gap-2">
          <Clock className="w-4 h-4 text-primary-500" />
          <span className="text-sm font-semibold text-neutral-800 dark:text-neutral-200">
            {title || '服用周期'}
          </span>
        </div>
        <span className="text-xs px-2 py-1 rounded-full bg-primary-100 dark:bg-primary-300/25 text-primary-700 dark:text-primary-700 font-medium">
          {duration_days} 天
        </span>
      </div>

      {/* 阶段概览 */}
      {phases.length > 0 && (
        <div className="px-4 py-3 border-b border-neutral-100 dark:border-neutral-800">
          <div className="flex flex-wrap gap-2">
            {phases.map((phase) => {
              const colors = PHASE_COLORS[phase.key as TimelinePhase] || PHASE_COLORS['初期']
              return (
                <div
                  key={phase.key}
                  className={`flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium border ${colors.bg} ${colors.border} ${colors.text}`}
                >
                  <span className={`w-1.5 h-1.5 rounded-full ${colors.dot}`} />
                  {phase.label}
                  <span className="opacity-75">({phase.days.length}天)</span>
                </div>
              )
            })}
          </div>
        </div>
      )}

      {/* 时间线 */}
      <div className="p-4">
        <div className="relative">
          {/* 垂直线 */}
          <div className="absolute left-3.5 top-0 bottom-0 w-0.5 bg-neutral-200 dark:bg-neutral-700" />

          <div className="space-y-2">
            {sortedItems.map((item) => {
              const phaseColors = PHASE_COLORS[item.phase] || PHASE_COLORS['初期']
              const isExpanded = expandedDay === item.day
              return (
                <div key={item.day} className="relative pl-8">
                  {/* 时间点 */}
                  <div
                    className={`absolute left-1.5 top-1.5 w-4 h-4 rounded-full border-2 border-white dark:border-neutral-900 ${phaseColors.dot} shadow-sm`}
                  >
                    {item.day === duration_days && (
                      <CheckCircle2 className="w-3 h-3 text-white absolute inset-0 m-auto" />
                    )}
                  </div>

                  {/* 日期标签 */}
                  <div className="flex items-center gap-2 mb-1">
                    <span className={`text-xs font-bold px-1.5 py-0.5 rounded ${phaseColors.bg} ${phaseColors.text}`}>
                      第 {item.day} 天
                    </span>
                    <span className={`text-xs px-1.5 py-0.5 rounded-full border ${phaseColors.bg} ${phaseColors.border} ${phaseColors.text}`}>
                      {item.phase}
                    </span>
                  </div>

                  {/* 标题 */}
                  <button
                    onClick={() => setExpandedDay(isExpanded ? null : item.day)}
                    className="w-full text-left"
                  >
                    <div className="flex items-center gap-2 p-2 rounded-lg hover:bg-neutral-50 dark:hover:bg-neutral-800/50 transition-colors">
                      <Pill className="w-3.5 h-3.5 text-primary-500 flex-shrink-0" />
                      <span className="text-xs font-medium text-neutral-700 dark:text-neutral-300">
                        {item.title}
                      </span>
                    </div>
                  </button>

                  {/* 展开详情 */}
                  {isExpanded && (
                    <div className="mt-1 ml-1 p-3 rounded-lg bg-neutral-50 dark:bg-neutral-800/30 border border-neutral-100 dark:border-neutral-700 space-y-2">
                      {item.description && (
                        <p className="text-xs text-neutral-600 dark:text-neutral-400 leading-relaxed">
                          {item.description}
                        </p>
                      )}
                      {item.dosage && (
                        <div className="flex items-center gap-1.5 text-xs">
                          <Pill className="w-3 h-3 text-primary-500" />
                          <span className="text-neutral-600 dark:text-neutral-400">剂量：</span>
                          <span className="font-medium text-neutral-800 dark:text-neutral-200">{item.dosage}</span>
                        </div>
                      )}
                      {item.notes && (
                        <div className="flex items-start gap-1.5 text-xs">
                          <AlertCircle className="w-3 h-3 text-warning-500 flex-shrink-0 mt-0.5" />
                          <span className="text-warning-600 dark:text-warning-700">{item.notes}</span>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              )
            })}
          </div>
        </div>

        {/* 结束标记 */}
        <div className="mt-4 pt-3 border-t border-neutral-100 dark:border-neutral-800 text-center">
          <div className="inline-flex items-center gap-1.5 text-xs text-neutral-400 dark:text-neutral-400">
            <CheckCircle2 className="w-3.5 h-3.5 text-success-500" />
            <span>疗程结束 · 建议复查指标</span>
          </div>
        </div>
      </div>
    </div>
  )
}

export default TimelineBlock

/**
 * Structured Content Block Renderer — 工具函数
 */
import type { StructuredContent, BlockType } from './types'

/**
 * 规范化 CalloutData：兼容 style（LLM 常用）→ variant（类型定义）字段映射
 */
function normalizeCallout(block: { type: string; data: unknown }): { type: string; data: unknown } {
  const data = (block.data as Record<string, unknown>) || {}
  if (block.type === 'callout') {
    // LLM 可能输出 style 而非 variant
    if (data.style && !data.variant) {
      data.variant = data.style as string
    }
    // 确保 style 字段也保留（渲染层读取）
    if (data.variant && !data.style) {
      data.style = data.variant as string
    }
    return { ...block, data }
  }
  return block
}

/**
 * 规范化 ListItem：兼容平铺字符串数组 → 结构化 ListItem 对象
 */
function normalizeList(block: { type: string; data: unknown }): { type: string; data: unknown } {
  const data = (block.data as Record<string, unknown>) || {}
  if (block.type === 'list') {
    // LLM 可能直接输出字符串数组而非 ListItem[]
    if (Array.isArray(data.items) && data.items.length > 0 && typeof data.items[0] === 'string') {
      data.items = (data.items as string[]).map(text => ({ label: text }))
    }
    // 若无 variant，根据内容推断
    if (!data.variant) {
      const items = data.items as Array<{ label?: string; description?: string } | string>
      const hasDescriptions = items.some(item => {
        if (typeof item === 'string') return false
        return !!item.description
      })
      data.variant = hasDescriptions ? 'analysis' : 'bullet'
    }
    return { ...block, data }
  }
  return block
}

/**
 * 检测消息内容是否为结构化JSON
 *
 * 支持两种格式：
 * 1. 纯JSON：以 { 开头的内容
 * 2. Markdown代码块中的JSON：```json ... ```
 *
 * 在解析后对 block 数据做归一化处理，兼容 LLM 常见变体。
 *
 * @param content 消息内容字符串
 * @returns 解析成功返回 StructuredContent, 失败返回 null
 */
export function detectStructuredContent(content: string): StructuredContent | null {
  if (!content) {
    console.warn('[detectStructured] empty content')
    return null
  }
  const trimmed = content.trim()
  console.log(`[detectStructured] content length=${trimmed.length}, starts="${trimmed[0]}", ends="${trimmed[trimmed.length-1]}"`)

  // 快速短路 — 纯文本消息不尝试解析
  if (trimmed.length < 10) {
    console.log('[detectStructured] too short, returning null')
    return null
  }

  let jsonStr: string | null = null
  let strategy = 'none'

  // ── 策略1: 从 ```json ... ``` 代码块中提取（处理嵌套大括号）──
  const codeBlockMatch = trimmed.match(/```(?:json)?\s*\n([\s\S]*?)\n?\s*```/)
  if (codeBlockMatch) {
    const candidate = codeBlockMatch[1].trim()
    const lastBrace = candidate.lastIndexOf('}')
    if (lastBrace >= 0 && candidate.startsWith('{') && candidate[lastBrace] === '}') {
      jsonStr = candidate.slice(0, lastBrace + 1)
      strategy = 'code-block'
    }
  }

  // ── 策略2: 内容以 { 开头 → 找最后一个匹配的 } ──
  if (!jsonStr && trimmed[0] === '{') {
    const lastBrace = trimmed.lastIndexOf('}')
    if (lastBrace > 0) {
      jsonStr = trimmed.slice(0, lastBrace + 1)
      strategy = 'starts-brace'
    }
  }

  // ── 策略3: 全文就是一段JSON（无代码块包裹）──
  if (!jsonStr && trimmed.startsWith('{') && trimmed.endsWith('}')) {
    jsonStr = trimmed
    strategy = 'full-text'
  }

  // ── 策略4: 扫描内容中第一个 { 到最后一个 } 的区间 ──
  if (!jsonStr) {
    const firstBrace = trimmed.indexOf('{')
    const lastBrace = trimmed.lastIndexOf('}')
    if (firstBrace >= 0 && lastBrace > firstBrace) {
      jsonStr = trimmed.slice(firstBrace, lastBrace + 1)
      strategy = 'scan-braces'
    }
  }

  console.log(`[detectStructured] strategy=${strategy}, jsonStr.length=${jsonStr ? jsonStr.length : 0}, first100="${jsonStr ? jsonStr.substring(0, 100) : 'null'}"`)

  if (!jsonStr) {
    console.warn('[detectStructured] no json found, returning null')
    return null
  }

  try {
    const parsed = JSON.parse(jsonStr) as Record<string, unknown>
    console.log(`[detectStructured] JSON parse OK, keys=${Object.keys(parsed).join(',')}, blocks=${Array.isArray(parsed.blocks) ? parsed.blocks.length : 'N/A'}`)

    // 验证核心结构
    if (!parsed || typeof parsed !== 'object') return null
    if (!Array.isArray(parsed.blocks)) return null

    // 验证每个 block 都有 type 字段
    const validTypes = new Set<BlockType>([
      'header', 'data-table', 'chart', 'list',
      'callout', 'metrics', 'divider',
      'ingredient-detail', 'synergy-chart', 'timeline',
    ])

    for (const block of parsed.blocks) {
      if (!block || typeof block !== 'object') return null
      if (!block.type || typeof block.type !== 'string') return null
      if (!validTypes.has(block.type as BlockType)) return null
    }

    // ── 归一化：兼容 LLM 常见字段变体 ──
    const normalizedBlocks = parsed.blocks.map((block: { type: string; data: unknown }) => {
      const n = normalizeCallout(block)
      return normalizeList(n)
    })

    // 兼容 LLM 未输出 responseType 的情况，自动补全默认值
    const structured: StructuredContent = {
      responseType: (parsed.responseType as StructuredContent['responseType']) ?? 'general',
      title: (parsed.title as string) || undefined,
      blocks: normalizedBlocks as any,
    }
    return structured
  } catch {
    // JSON 解析失败 → 不是结构化内容
    return null
  }
}

/**
 * 安全获取 block 数据，避免空指针
 */
export function safeBlockData<T>(data: T | undefined | null, fallback: T): T {
  return data ?? fallback
}

/**
 * 格式化数值为百分比字符串
 */
export function formatPercent(value: number, decimals = 0): string {
  return (value * 100).toFixed(decimals) + '%'
}

/**
 * Agent 智能路由 Hook
 *
 * 根据用户输入自动判断应该使用哪种模式：
 * - "工作流模式"：涉及配方设计、合规检查、实验方案等结构化任务
 * - "对话模式"：开放式问题、多轮对话、查询类问题
 *
 * 使用方式：
 * const { mode, setMode, isAutoMode } = useAgentSmartRouter();
 */
import { useState, useCallback, useMemo } from 'react';

export type AgentMode = 'workflow' | 'chat' | 'auto';

export interface AgentRouteResult {
  mode: AgentMode;
  workflowType?: string;
  confidence: number;
  reason: string;
}

// 工作流关键词映射
const WORKFLOW_KEYWORDS: Record<string, string[]> = {
  formula_design: ['配方', '设计配方', '生成配方', '研发配方'],
  compliance_check: ['合规', '检查', '安全性', '禁忌', '配伍'],
  experiment_plan: ['实验', '方案', '测试', '验证'],
  ingredient_lookup: ['查询', '功效', '用量', '是什么', '有什么用'],
  full_pipeline: ['全流程', '完整流程', '一站式'],
};

// 对话关键词
const CHAT_KEYWORDS = [
  '你好', '帮助', '介绍', '怎么', '如何', '为什么',
  '告诉我', '解释', '说明', '什么是',
];

/**
 * 根据用户输入判断应该使用的模式
 */
export function useAgentSmartRouter() {
  const [userMode, setUserMode] = useState<AgentMode>('auto');

  /**
   * 智能路由：根据输入自动判断模式
   */
  const route = useCallback(
    (input: string): AgentRouteResult => {
      if (userMode !== 'auto') {
        return {
          mode: userMode,
          workflowType: userMode === 'workflow' ? 'formula_design' : undefined,
          confidence: 1.0,
          reason: userMode === 'workflow' ? '用户选择工作流模式' : '用户选择对话模式',
        };
      }

      const lowerInput = input.toLowerCase();

      // 检查是否匹配工作流关键词
      for (const [type, keywords] of Object.entries(WORKFLOW_KEYWORDS)) {
        const matchCount = keywords.filter((kw) => lowerInput.includes(kw)).length;
        if (matchCount > 0) {
          return {
            mode: 'workflow',
            workflowType: type as keyof typeof WORKFLOW_KEYWORDS,
            confidence: Math.min(0.95, 0.6 + matchCount * 0.1),
            reason: `匹配到工作流关键词: ${keywords.find((kw) => lowerInput.includes(kw))}`,
          };
        }
      }

      // 检查是否匹配对话关键词
      const chatMatch = CHAT_KEYWORDS.some((kw) => lowerInput.includes(kw));
      if (chatMatch) {
        return {
          mode: 'chat',
          confidence: 0.8,
          reason: '匹配到对话关键词',
        };
      }

      // 默认使用工作流模式（更符合 RMFOOD 场景）
      return {
        mode: 'workflow',
        workflowType: 'formula_design',
        confidence: 0.5,
        reason: '默认工作流模式',
      };
    },
    [userMode]
  );

  /**
   * 预检输入模式（用于输入框 placeholder 提示）
   */
  const previewMode = useCallback(
    (input: string): AgentMode => {
      if (!input.trim()) return 'auto';
      return route(input).mode;
    },
    [route]
  );

  return {
    mode: userMode,
    setMode: setUserMode,
    route,
    previewMode,
    isAutoMode: userMode === 'auto',
  };
}

/**
 * useChatCallbacks - ChatTab 回调管理 Hook (v3.0)
 *
 * v3.0 更新 (2026-08-23):
 * ✅ 统一存储层：使用 ChatStorageService 替代散乱 localStorage
 * ✅ 后端回退：本地无数据时尝试从后端加载
 * ✅ 会话隔离：每个会话独立存储，切换安全
 *
 * @version 3.0.0
 */

import { useCallback, useEffect } from 'react'
import type { Dispatch, SetStateAction } from 'react'
import type { HistorySession } from '../components/pro'
import { logger } from '@/utils/safeLogger'
import type { ChatMessage } from '../types'
import { chatApi } from '@/api/chat'
import type { ChatSession as BackendSession } from '@/api/chat'
import { chatStorageService } from '../capabilities/storage/ChatStorageService'

export interface UseChatCallbacksOptions {
  historySessions: HistorySession[]
  setHistorySessions: Dispatch<SetStateAction<HistorySession[]>>
  setActiveSessionId: Dispatch<SetStateAction<string | null>>
  historyVisible: boolean
  setHistoryVisible: Dispatch<SetStateAction<boolean>>
  clearMessages: () => void
  clearAllFormulas: () => void
  clearWorkingMemory: () => void
  clearMultiTurnDialogue: () => void
  clearShortTermMemory: () => void
  /** 当前消息列表（用于会话切换时保存/恢复） */
  messages: ChatMessage[]
  /** 替换当前消息列表（用于从目标会话恢复） */
  setMessages: (messages: ChatMessage[]) => void
  /** 当前活跃会话ID */
  activeSessionId: string | null
}

export interface UseChatCallbacksReturn {
  handleClearChat: () => void
  handleNewSession: () => void
  handleSelectSession: (id: string) => void
  handleDeleteSession: (id: string) => void
  handleRenameSession: (id: string, title: string) => void
  toggleHistory: () => void
  updateSessionMetadata: (sessionId: string, msgs: ChatMessage[]) => void
  syncSessionsFromServer: () => Promise<void>
}

export function useChatCallbacks(options: UseChatCallbacksOptions): UseChatCallbacksReturn {
  const {
    historySessions, setHistorySessions, setActiveSessionId,
    clearMessages, clearAllFormulas,
    clearWorkingMemory, clearMultiTurnDialogue, clearShortTermMemory,
    messages, setMessages, activeSessionId,
  } = options

  const handleClearChat = useCallback(() => {
    clearMessages()
    clearAllFormulas()
    clearWorkingMemory()
    clearMultiTurnDialogue()
    clearShortTermMemory()
  }, [clearMessages, clearAllFormulas, clearWorkingMemory, clearMultiTurnDialogue, clearShortTermMemory])

  /** 更新指定会话的元数据（消息数、最后消息） */
  const updateSessionMetadata = useCallback(async (sessionId: string, msgs: ChatMessage[]) => {
    const userMsgs = msgs.filter(m => m.role === 'user')
    const lastUserMsg = userMsgs[userMsgs.length - 1]
    setHistorySessions(prev => prev.map(s =>
      s.id === sessionId
        ? { ...s, messageCount: msgs.length, lastMessage: lastUserMsg?.content?.slice(0, 50) || '', timestamp: Date.now() }
        : s
    ))
    // 统一保存到 IndexedDB
    try {
      await chatStorageService.saveMessages(sessionId, msgs)
    } catch (e) {
      logger.warn('[useChatCallbacks] 保存会话消息失败:', e)
    }
  }, [setHistorySessions])

  const handleNewSession = useCallback(async () => {
    // 保存当前会话的消息（如果有活跃会话）
    if (activeSessionId && messages.length > 0) {
      try {
        await chatStorageService.saveMessages(activeSessionId, messages)
      } catch (e) {
        logger.warn('[useChatCallbacks] 保存当前会话失败:', e)
      }
      await updateSessionMetadata(activeSessionId, messages)
    }

    const newSession: HistorySession = {
      id: `session-${Date.now()}`,
      title: '新对话',
      messageCount: 0,
      lastMessage: '',
      timestamp: Date.now(),
    }
    const updated = [newSession, ...historySessions]
    setHistorySessions(updated)
    setActiveSessionId(newSession.id)
    // 同步写入 IndexedDB 元数据，保证新会话在侧栏立即可见
    chatStorageService.saveSessionMeta(newSession.id, {
      title: newSession.title,
      tags: [],
      createdAt: newSession.timestamp,
      updatedAt: newSession.timestamp,
      messageCount: 0,
    }).catch(e => logger.warn('[useChatCallbacks] 保存新会话元数据失败:', e))
    handleClearChat()
  }, [historySessions, setHistorySessions, setActiveSessionId, handleClearChat, activeSessionId, messages, updateSessionMetadata])

  const handleSelectSession = useCallback(async (id: string) => {
    if (id === activeSessionId) return

    // 1. 保存当前会话的消息
    if (activeSessionId && messages.length > 0) {
      try {
        await chatStorageService.saveMessages(activeSessionId, messages)
      } catch (e) {
        logger.warn('[useChatCallbacks] 保存当前会话失败:', e)
      }
      await updateSessionMetadata(activeSessionId, messages)
    }

    // 2. 切换到目标会话
    setActiveSessionId(id)

    // 3. 从统一存储恢复消息（先本地，后后端）
    try {
      const restoredMessages = await chatStorageService.loadMessages(id)
      if (restoredMessages.length > 0) {
        logger.info(`[useChatCallbacks] 恢复会话 ${id} 的 ${restoredMessages.length} 条消息`)
        setMessages(restoredMessages)
        return
      }
    } catch (e) {
      logger.warn('[useChatCallbacks] 本地加载失败，尝试后端:', e)
    }

    // 4. 降级：从后端加载
    try {
      const serverMessages = await chatStorageService.fetchFromServer(id)
      if (serverMessages.length > 0) {
        setMessages(serverMessages)
        await chatStorageService.saveMessages(id, serverMessages)
        return
      }
    } catch (e) {
      logger.warn('[useChatCallbacks] 后端加载失败:', e)
    }

    // 5. 最终降级：清空
    handleClearChat()
  }, [setActiveSessionId, activeSessionId, messages, handleClearChat, setMessages, updateSessionMetadata])

  const handleDeleteSession = useCallback(async (id: string) => {
    const updated = historySessions.filter(s => s.id !== id)
    setHistorySessions(updated)
    // 清理被删除会话的消息存储（IndexedDB）
    try {
      await chatStorageService.deleteMessages(id)
    } catch {}
    // 如果删除的是当前活跃会话，清空消息
    if (id === activeSessionId) {
      handleClearChat()
    }
  }, [historySessions, setHistorySessions, activeSessionId, handleClearChat])

  const handleRenameSession = useCallback(async (id: string, title: string) => {
    const updated = historySessions.map(s => s.id === id ? { ...s, title } : s)
    setHistorySessions(updated)
    // 同步更新 IndexedDB 元数据
    try {
      await chatStorageService.saveSessionMeta(id, {
        title,
        tags: [],
        createdAt: Date.now(),
        updatedAt: Date.now(),
        messageCount: updated.find(s => s.id === id)?.messageCount ?? 0,
      })
    } catch (e) {
      logger.warn('[useChatCallbacks] 重命名会话元数据保存失败:', e)
    }
  }, [historySessions, setHistorySessions])

  const toggleHistory = useCallback(() => {
    options.setHistoryVisible(v => !v)
  }, [options.setHistoryVisible])

  const syncSessionsFromServer = useCallback(async () => {
    try {
      const data = await chatApi.getSessions({ page_size: 50 })
      const backendSessions = data.items.map((s: BackendSession) => ({
        id: String(s.id),
        title: s.title,
        messageCount: s.message_count,
        lastMessage: '',
        timestamp: new Date(s.updated_at).getTime(),
      }))
      const existingIds = new Set(historySessions.map(s => s.id))
      const toMerge = backendSessions.filter((s: any) => !existingIds.has(s.id))
      if (toMerge.length > 0) {
        const merged = [...historySessions, ...toMerge]
        setHistorySessions(merged)
        // 同步写入 IndexedDB，废弃 localStorage
        try {
          for (const s of toMerge) {
            await chatStorageService.saveSessionMeta(s.id, {
              title: s.title,
              tags: [],
              createdAt: s.timestamp,
              updatedAt: s.timestamp,
              messageCount: s.messageCount,
            })
          }
        } catch (e) {
          logger.warn('[useChatCallbacks] 服务端会话写入 IndexedDB 失败:', e)
        }
        logger.info(`[useChatCallbacks] 手动同步新增 ${toMerge.length} 个会话`)
      }
    } catch (err) {
      logger.warn('[useChatCallbacks] 手动同步失败:', err)
    }
  }, [historySessions, setHistorySessions])

  return {
    handleClearChat,
    handleNewSession,
    handleSelectSession,
    handleDeleteSession,
    handleRenameSession,
    toggleHistory,
    updateSessionMetadata,
    syncSessionsFromServer,
  }
}

/**
 * useChatCompaction 增强 Hook
 *
 * 在消息发送前检查 token 使用量，自动触发压缩
 * 集成到 ChatTab 的消息发送流程
 */

import { useCallback } from 'react';
import { useCompaction, type CompactionResult } from './useCompaction';
import { logger } from '@/utils/safeLogger';
import type { AgentMessage } from '@/components/ai/shared/types';

export interface UseChatCompactionOptions {
  /** 压缩触发时的回调 */
  onCompact?: (result: CompactionResult) => void;
  /** 最大消息数后强制压缩 (默认 100) */
  forceCompactAfter?: number;
}

export interface UseChatCompactionReturn {
  /** 检查并执行压缩，返回是否触发了压缩 */
  checkAndCompact: (messages: AgentMessage[]) => Promise<CompactionResult>;
  /** 当前 token 使用统计 */
  tokenUsage: { used: number; ratio: number };
  /** 压缩配置 */
  config: ReturnType<typeof useCompaction>['config'];
}

export function useChatCompaction(options: UseChatCompactionOptions = {}): UseChatCompactionReturn {
  const { onCompact, forceCompactAfter = 100 } = options;
  const { checkCompact, compact, getTokenUsage, config } = useCompaction();

  /**
   * 发送前检查并执行压缩
   */
  const checkAndCompact = useCallback(
    async (messages: AgentMessage[]): Promise<CompactionResult> => {
      const trigger = checkCompact(messages);

      if (!trigger) {
        // 检查是否达到强制压缩阈值
        if (messages.length >= forceCompactAfter) {
          logger.info(`[ChatCompaction] Force compact: ${messages.length} messages exceeds limit`);
        } else {
          return { triggered: false, beforeCount: messages.length, afterCount: messages.length, tokensSaved: 0 };
        }
      }

      const result = await compact(messages, (updated) => {
        // 更新消息列表（由调用方处理）
        logger.info(`[ChatCompaction] Compact applied: ${trigger}, before=${messages.length}, after=${updated.length}`);
        onCompact?.({ triggered: true, trigger: trigger ?? undefined, beforeCount: messages.length, afterCount: updated.length, tokensSaved: 0 });
      });

      return result;
    },
    [checkCompact, compact, forceCompactAfter, onCompact],
  );

  return {
    checkAndCompact,
    tokenUsage: { used: 0, ratio: 0 }, // 实际使用时由调用方传入消息列表计算
    config,
  };
}

import { useState, useCallback, useEffect, useMemo } from 'react'
import { logger } from '@/utils/safeLogger'
import { chatHistoryStorage } from '../services/chatHistoryStorage'
import type {
  ChatSession,
  ChatMessage,
  HistorySearchFilters,
  HistoryStatistics,
} from '../types/chatHistory.types'
import { ChatTopic, MAX_TAGS_PER_SESSION } from '../types/chatHistory.types'

interface UseChatHistoryManagerReturn {
  sessions: ChatSession[]
  currentSession: ChatSession | null
  isLoading: boolean
  isSaving: boolean
  statistics: HistoryStatistics | null
  filters: HistorySearchFilters

  createSession: (title?: string, topic?: ChatTopic) => ChatSession
  saveSession: (session: ChatSession) => Promise<void>
  deleteSession: (id: string) => Promise<void>
  clearAll: () => Promise<void>
  selectSession: (id: string) => void
  addMessage: (sessionId: string, message: ChatMessage) => Promise<void>
  updateSessionTopic: (sessionId: string, topic: ChatTopic) => Promise<void>
  addTagToSession: (sessionId: string, tag: string) => Promise<void>
  removeTagFromSession: (sessionId: string, tag: string) => Promise<void>
  searchSessions: (filters: HistorySearchFilters) => Promise<void>
  refreshStatistics: () => Promise<void>
  getSessionById: (id: string) => ChatSession | null
  getSessionsByTopic: (topic: ChatTopic) => ChatSession[]
  getSessionsByTag: (tag: string) => ChatSession[]
}

export function useChatHistoryManager(): UseChatHistoryManagerReturn {
  const [sessions, setSessions] = useState<ChatSession[]>([])
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const [isSaving, setIsSaving] = useState(false)
  const [statistics, setStatistics] = useState<HistoryStatistics | null>(null)
  const [filters, setFilters] = useState<HistorySearchFilters>({})

  useEffect(() => {
    loadSessions()
  }, [])

  const loadSessions = useCallback(async () => {
    setIsLoading(true)
    try {
      const loaded = await chatHistoryStorage.getAllSessions(filters)
      setSessions(loaded)
      if (loaded.length > 0 && !currentSessionId) {
        setCurrentSessionId(loaded[0].id)
      }
      await refreshStatistics()
      logger.info(`[useChatHistoryManager] 加载了 ${loaded.length} 条会话`)
    } catch (error) {
      logger.error('[useChatHistoryManager] 加载会话失败:', error)
    } finally {
      setIsLoading(false)
    }
  }, [filters, currentSessionId])

  const refreshStatistics = useCallback(async () => {
    try {
      const stats = await chatHistoryStorage.getStatistics()
      setStatistics(stats)
    } catch (error) {
      logger.error('[useChatHistoryManager] 获取统计信息失败:', error)
    }
  }, [])

  const createSession = useCallback((title?: string, topic: ChatTopic = ChatTopic.KNOWLEDGE_QUERY): ChatSession => {
    const now = Date.now()
    const newSession: ChatSession = {
      id: crypto.randomUUID(),
      title: title || `对话 ${new Date(now).toLocaleString('zh-CN')}`,
      messages: [],
      metadata: {
        topic,
        tags: [],
        createdAt: now,
        updatedAt: now,
        messageCount: 0,
      },
    }
    return newSession
  }, [])

  const saveSession = useCallback(async (session: ChatSession) => {
    setIsSaving(true)
    try {
      await chatHistoryStorage.saveSession(session)
      setSessions(prev => {
        const index = prev.findIndex(s => s.id === session.id)
        if (index >= 0) {
          const updated = [...prev]
          updated[index] = session
          return updated
        }
        return [session, ...prev]
      })
      if (!currentSessionId) {
        setCurrentSessionId(session.id)
      }
      await refreshStatistics()
      logger.info(`[useChatHistoryManager] 保存会话成功: ${session.id}`)
    } catch (error) {
      logger.error('[useChatHistoryManager] 保存会话失败:', error)
      throw error
    } finally {
      setIsSaving(false)
    }
  }, [currentSessionId, refreshStatistics])

  const deleteSession = useCallback(async (id: string) => {
    try {
      await chatHistoryStorage.deleteSession(id)
      setSessions(prev => prev.filter((s: any) => s.id !== id))
      if (currentSessionId === id) {
        setCurrentSessionId(sessions.filter((s: any) => s.id !== id)[0]?.id || null)
      }
      await refreshStatistics()
      logger.info(`[useChatHistoryManager] 删除会话成功: ${id}`)
    } catch (error) {
      logger.error('[useChatHistoryManager] 删除会话失败:', error)
      throw error
    }
  }, [currentSessionId, refreshStatistics])

  const clearAll = useCallback(async () => {
    try {
      await chatHistoryStorage.clearAll()
      setSessions([])
      setCurrentSessionId(null)
      setStatistics(null)
      logger.info('[useChatHistoryManager] 清除所有会话')
    } catch (error) {
      logger.error('[useChatHistoryManager] 清除会话失败:', error)
      throw error
    }
  }, [])

  const selectSession = useCallback((id: string) => {
    setCurrentSessionId(id)
    logger.info(`[useChatHistoryManager] 选择会话: ${id}`)
  }, [])

  const addMessage = useCallback(async (sessionId: string, message: ChatMessage) => {
    const session = sessions.find(s => s.id === sessionId)
    if (!session) {
      throw new Error(`会话不存在: ${sessionId}`)
    }

    const updatedSession: ChatSession = {
      ...session,
      messages: [...session.messages, message],
      metadata: {
        ...session.metadata,
        updatedAt: Date.now(),
        messageCount: session.metadata.messageCount + 1,
      },
    }

    await saveSession(updatedSession)
  }, [sessions, saveSession])

  const updateSessionTopic = useCallback(async (sessionId: string, topic: ChatTopic) => {
    const session = sessions.find(s => s.id === sessionId)
    if (!session) {
      throw new Error(`会话不存在: ${sessionId}`)
    }

    const updatedSession: ChatSession = {
      ...session,
      metadata: {
        ...session.metadata,
        topic,
        updatedAt: Date.now(),
      },
    }

    await saveSession(updatedSession)
  }, [sessions, saveSession])

  const addTagToSession = useCallback(async (sessionId: string, tag: string) => {
    const session = sessions.find(s => s.id === sessionId)
    if (!session) {
      throw new Error(`会话不存在: ${sessionId}`)
    }

    if (session.metadata.tags.length >= MAX_TAGS_PER_SESSION) {
      throw new Error(`最多支持 ${MAX_TAGS_PER_SESSION} 个标签`)
    }

    if (session.metadata.tags.includes(tag)) {
      return
    }

    const updatedSession: ChatSession = {
      ...session,
      metadata: {
        ...session.metadata,
        tags: [...session.metadata.tags, tag],
        updatedAt: Date.now(),
      },
    }

    await saveSession(updatedSession)
  }, [sessions, saveSession])

  const removeTagFromSession = useCallback(async (sessionId: string, tag: string) => {
    const session = sessions.find(s => s.id === sessionId)
    if (!session) {
      throw new Error(`会话不存在: ${sessionId}`)
    }

    const updatedSession: ChatSession = {
      ...session,
      metadata: {
        ...session.metadata,
        tags: session.metadata.tags.filter(t => t !== tag),
        updatedAt: Date.now(),
      },
    }

    await saveSession(updatedSession)
  }, [sessions, saveSession])

  const searchSessions = useCallback(async (newFilters: HistorySearchFilters) => {
    setFilters(newFilters)
  }, [])

  useEffect(() => {
    loadSessions()
  }, [filters])

  const getSessionById = useCallback((id: string): ChatSession | null => {
    return sessions.find(s => s.id === id) || null
  }, [sessions])

  const getSessionsByTopic = useCallback((topic: ChatTopic): ChatSession[] => {
    return sessions.filter(s => s.metadata.topic === topic)
  }, [sessions])

  const getSessionsByTag = useCallback((tag: string): ChatSession[] => {
    return sessions.filter(s => s.metadata.tags.includes(tag))
  }, [sessions])

  const currentSession = useMemo(() => {
    if (!currentSessionId) return null
    return sessions.find(s => s.id === currentSessionId) || null
  }, [sessions, currentSessionId])

  return {
    sessions,
    currentSession,
    isLoading,
    isSaving,
    statistics,
    filters,
    createSession,
    saveSession,
    deleteSession,
    clearAll,
    selectSession,
    addMessage,
    updateSessionTopic,
    addTagToSession,
    removeTagFromSession,
    searchSessions,
    refreshStatistics,
    getSessionById,
    getSessionsByTopic,
    getSessionsByTag,
  }
}

export default useChatHistoryManager

/**
 * useChatInputAttachments - 文件附件管理 Hook (v1.0)
 *
 * 职责：
 * - 文件粘贴处理（图片/文件）
 * - 拖拽上传处理
 * - 附件列表管理（添加/移除/清空）
 * - 文件类型和大小校验
 *
 * @version 1.0.0
 * @author RMFOOD Team
 */

import { useCallback, useRef, useEffect, useState } from 'react'
import { logger } from '@/utils/safeLogger'

export interface Attachment {
  id: string
  name: string
  type: string
  size: number
  dataUrl?: string
  preview?: string
}

export interface AttachmentOptions {
  maxSize?: number       // 默认 10MB
  maxFiles?: number      // 默认 5
  accept?: string[]      // 默认所有
}

const DEFAULT_OPTIONS: AttachmentOptions = {
  maxSize: 10 * 1024 * 1024,
  maxFiles: 5,
  accept: ['image/*', '.pdf', '.doc', '.docx', '.xls', '.xlsx', '.txt', '.md'],
}

export interface UseChatInputAttachmentsReturn {
  attachments: Attachment[]
  isDragging: boolean
  showAttachments: boolean
  setShowAttachments: (v: boolean) => void
  addAttachments: (files: Attachment[]) => void
  removeAttachment: (id: string) => void
  clearAttachments: () => void
  handleFileSelect: (e: React.ChangeEvent<HTMLInputElement>) => Promise<void>
  setupEventListeners: () => () => void
}

export function useChatInputAttachments(
  fileInputRef: React.RefObject<HTMLInputElement | null>,
  options: AttachmentOptions = DEFAULT_OPTIONS,
): UseChatInputAttachmentsReturn {
  const [attachments, setAttachments] = useState<Attachment[]>([])
  const [isDragging, setIsDragging] = useState(false)
  const [showAttachments, setShowAttachments] = useState(false)

  const addAttachments = useCallback((newAttachments: Attachment[]) => {
    setAttachments(prev => {
      const combined = [...prev, ...newAttachments]
      if (combined.length > options.maxFiles!) {
        logger.warn(`[useChatInputAttachments] 超过最大文件数 ${options.maxFiles}`)
        return prev.concat(combined.slice(combined.length - options.maxFiles!))
      }
      return combined
    })
    setShowAttachments(true)
  }, [options.maxFiles])

  const removeAttachment = useCallback((id: string) => {
    setAttachments(prev => {
      const filtered = prev.filter(a => a.id !== id)
      if (filtered.length === 0) setShowAttachments(false)
      return filtered
    })
  }, [])

  const clearAttachments = useCallback(() => {
    setAttachments([])
    setShowAttachments(false)
  }, [])

  const handleFileSelect = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files
    if (!files || files.length === 0) return

    const fileArray = Array.from(files)
    const newAttachments: Attachment[] = []

    for (const file of fileArray) {
      // 大小校验
      if (file.size > (options.maxSize ?? 10 * 1024 * 1024)) {
        logger.warn(`[useChatInputAttachments] 文件过大: ${file.name}`)
        continue
      }
      // 类型校验
      if (options.accept && options.accept.length > 0) {
        const ext = '.' + file.name.split('.').pop()?.toLowerCase()
        const isImage = file.type.startsWith('image/')
        const typeOk = isImage || options.accept.some(a => a === '*' || file.type.includes(a.replace('.', '')) || ext === a)
        if (!typeOk) {
          logger.warn(`[useChatInputAttachments] 不支持的文件类型: ${file.name}`)
          continue
        }
      }

      // 读取为 data URL（仅图片用于预览）
      let dataUrl: string | undefined
      let preview: string | undefined
      if (file.type.startsWith('image/')) {
        dataUrl = await new Promise((resolve) => {
          const reader = new FileReader()
          reader.onload = (ev) => resolve(ev.target?.result as string)
          reader.readAsDataURL(file)
        })
        preview = dataUrl
      }

      newAttachments.push({
        id: `attach-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        name: file.name,
        type: file.type,
        size: file.size,
        dataUrl,
        preview,
      })
    }

    if (newAttachments.length > 0) {
      addAttachments(newAttachments)
    }

    // 重置 input
    if (fileInputRef.current) fileInputRef.current.value = ''
  }, [fileInputRef, options, addAttachments])

  // 拖拽事件
  const setupEventListeners = useCallback(() => {
    const container = document.getElementById('chat-input-container')
    if (!container) return () => {}

    const handleDragOver = (e: DragEvent) => { e.preventDefault(); setIsDragging(true) }
    const handleDragLeave = () => setIsDragging(false)
    const handleDrop = (e: DragEvent) => {
      e.preventDefault()
      setIsDragging(false)
      if (e.dataTransfer?.files?.length) {
        const dt = new DataTransfer()
        Array.from(e.dataTransfer.files).forEach(f => dt.items.add(f))
        if (fileInputRef.current) {
          fileInputRef.current.files = dt.files
          fileInputRef.current.dispatchEvent(new Event('change', { bubbles: true }))
        }
      }
    }

    container.addEventListener('dragover', handleDragOver)
    container.addEventListener('dragleave', handleDragLeave)
    container.addEventListener('drop', handleDrop)

    return () => {
      container.removeEventListener('dragover', handleDragOver)
      container.removeEventListener('dragleave', handleDragLeave)
      container.removeEventListener('drop', handleDrop)
    }
  }, [fileInputRef])

  return {
    attachments, isDragging, showAttachments, setShowAttachments,
    addAttachments, removeAttachment, clearAttachments,
    handleFileSelect, setupEventListeners,
  }
}

/**
 * useChatInputValidation - 输入校验 Hook (v1.0)
 *
 * 职责：
 * - 字符计数与长度限制
 * - 发送按钮可用性判断
 * - 空内容/流式输出中禁止发送
 *
 * @version 1.0.0
 * @author RMFOOD Team
 */

import { useCallback, useMemo } from 'react'

export interface UseChatInputValidationOptions {
  maxLength?: number
  value: string
  isStreaming: boolean
  isDisabled: boolean
  showFormatError: boolean
}

export interface UseChatInputValidationReturn {
  charCount: number
  isOverLimit: boolean
  isExceeded: boolean
  canSend: boolean
  errorMessage: string
}

export function useChatInputValidation(opts: UseChatInputValidationOptions): UseChatInputValidationReturn {
  const { maxLength, value, isStreaming, isDisabled, showFormatError } = opts

  const charCount = useMemo(() => value.length, [value])
  const isOverLimit = useMemo(
    () => !!(maxLength && charCount > maxLength * 0.9),
    [maxLength, charCount],
  )
  const isExceeded = useMemo(
    () => !!(maxLength && charCount > maxLength),
    [maxLength, charCount],
  )

  const canSend = useMemo(() => {
    return !isDisabled && !isStreaming && value.trim().length > 0 && !showFormatError
  }, [isDisabled, isStreaming, value, showFormatError])

  return { charCount, isOverLimit, isExceeded, canSend, errorMessage: '' }
}

import { useState, useCallback, useRef, useEffect } from 'react'
import { chatService } from '../services/chatService'
import { storageService } from '../services/storageService'
import { eventBus } from '../services/eventBus'
import { logger } from '@/utils/safeLogger'
import { sanitizeChatMessages } from '../utils/sanitizeChatMessages'
import { toFriendlyErrorMessage } from '../utils/friendlyError'
import type { ChatMessage } from '../types'
import { tokenBudgetManager } from '../capabilities/streaming/TokenBudgetManager'
import { contextCompactionEngine } from '../capabilities/streaming/ContextCompaction'
import { chatEventLog } from '../capabilities/storage/ChatEventLog'
import { chatStorageService } from '../capabilities/storage/ChatStorageService'
import { offlineManager } from '../utils/offlineManager'
import { userPreferencesService } from '../services/userPreferencesService'
export type { ChatMessage } from '../types'

interface UseChatMessagesReturn {
  messages: ChatMessage[]
  input: string
  setInput: (value: string) => void
  isStreaming: boolean
  setIsStreaming: (streaming: boolean) => void
  chatError: Error | null
  setChatError: (error: Error | null) => void
  addMessage: (message: ChatMessage) => void
  updateMessage: (id: string, updates: Partial<ChatMessage>) => void
  removeMessage: (id: string) => void
  clearMessages: () => void
  /** 替换所有消息（用于会话切换恢复） */
  replaceMessages: (messages: ChatMessage[]) => void
  sendMessage: (content: string, displayContent?: string, scenarioMode?: string) => Promise<void>
  retryLastMessage: () => Promise<void>
  /** 对指定失败消息重新发送（最大重试3次） */
  retryMessage: (messageId: string) => Promise<void>
  clearError: () => void
  /** 暂停流式输出 */
  isPaused: boolean
  pauseStreaming: () => void
  resumeStreaming: () => void
  editMessage: (id: string, newContent: string) => void
  retractMessage: (id: string) => void
  /** 设置当前会话 ID（用于持久化到 IndexedDB） */
  setActiveSessionId: (id: string | null) => void
  /** 检查并执行上下文压缩（当 token 超限时自动触发） */
  checkCompaction: () => Promise<void>
}

const STORAGE_KEY = 'chat_messages'
const MAX_MESSAGES = 100
const MAX_RETRY = 3 // 最大重试次数

export function useChatMessages(): UseChatMessagesReturn {
  const [messages, setMessages] = useState<ChatMessage[]>(() => {
    try {
      const stored = storageService.get<ChatMessage[]>(STORAGE_KEY)
      if (!stored) return []

      // 一次性清理 v12 精简前遗留的脚手架污染消息（系统提示词/意图分析/报错气泡等）
      const { messages: cleaned, removedCount } = sanitizeChatMessages(stored)
      if (removedCount > 0) {
        logger.info(`[useChatMessages] 已清理 ${removedCount} 条历史污染消息`)
        try {
          if (cleaned.length > 0) {
            storageService.set(STORAGE_KEY, cleaned)
          } else {
            storageService.remove(STORAGE_KEY)
          }
        } catch (writeError) {
          logger.warn('[useChatMessages] 清理后写回存储失败:', writeError)
        }
      }
      // Normalize content: detect and preserve structured JSON blocks
      const normalized = cleaned.map(msg => {
        if (msg.role === 'assistant' && msg.content) {
          const trimmed = msg.content.trim()
          if (trimmed.startsWith('{') && trimmed.includes('"blocks"') && !trimmed.includes('```json')) {
            return { ...msg, content: '```json\n' + trimmed + '\n```' }
          }
        }
        return msg
      })

      const hasChanges = normalized.some((m: any, i: number) => m.content !== cleaned[i].content)
      if (hasChanges) {
        try { storageService.set(STORAGE_KEY, normalized) } catch { /* 忽略写回失败 */ }
      }

      return normalized
    } catch (error) {
      logger.warn('[useChatMessages] Failed to load messages from storage:', error)
      return []
    }
  })

  const [input, setInput] = useState('')
  const [isStreaming, setIsStreaming] = useState(false)
  const [chatError, setChatError] = useState<Error | null>(null)
  const [isPaused, setIsPaused] = useState(false)
  const messagesRef = useRef(messages)
  const lastQuestionRef = useRef<string>('')
  const activeSessionIdRef = useRef<string | null>(null)

  // ── 监听认证失效事件，清除过期 Token ──
  useEffect(() => {
    const unsub = eventBus.subscribe('auth:required', () => {
      logger.warn('[useChatMessages] 收到 auth:required 事件，清除过期 Token')
      storageService.remove('access_token')
      storageService.remove('refresh_token')
      localStorage.removeItem('access_token')
      localStorage.removeItem('refresh_token')
      chatService.clearAuthToken()
    })
    return unsub
  }, [])

  // ── 组件 unmount 时清理所有 pending SSE 请求 ──
  useEffect(() => {
    return () => {
      logger.info('[useChatMessages] Unmount cleanup: aborting all pending SSE requests')
      chatService.closeAllPendingRequests()
    }
  }, [])

  // ADR-029 P1-3: 统一存储策略 - IndexedDB 作为主存储，localStorage 仅作降级兜底
  const saveToStorage = useCallback((newMessages: ChatMessage[]) => {
    try {
      if (newMessages.length > MAX_MESSAGES) {
        newMessages = newMessages.slice(-MAX_MESSAGES)
      }

      // 优先写入 IndexedDB（支持大容量会话）
      if (activeSessionIdRef.current && newMessages.length > 0) {
        chatStorageService.saveMessages(activeSessionIdRef.current, newMessages)
          .catch(e => logger.warn('[useChatMessages] IndexedDB save failed:', e))
      }

      // localStorage 降级：仅当 IndexedDB 失败时使用
      // 注意：localStorage 有 ~5MB 限制，不适合大会话
      const isIndexedDBSupported = typeof indexedDB !== 'undefined'
      if (!isIndexedDBSupported) {
        storageService.set(STORAGE_KEY + '_fallback', newMessages)
        logger.warn('[useChatMessages] IndexedDB 不可用，降级到 localStorage')
      }
    } catch (storageError) {
      logger.warn('[useChatMessages] Failed to save messages to storage:', storageError)
    }
  }, [])

  // ── ChatEventLog 集成：所有消息变更写入事件日志 ──
  useEffect(() => {
    return chatEventLog.onChange(() => {
      // EventLog 变更时同步到 IndexedDB
      const currentMessages = chatEventLog.deriveMessages()
      if (currentMessages.length > 0 && activeSessionIdRef.current) {
        chatStorageService.saveMessages(activeSessionIdRef.current, currentMessages).catch(e =>
          logger.warn('[useChatMessages] EventLog sync failed:', e)
        )
      }
    })
  }, [])

  const updateMessages = useCallback((updater: (prev: ChatMessage[]) => ChatMessage[]) => {
    setMessages(prev => {
      const newMessages = updater(prev)
      messagesRef.current = newMessages
      saveToStorage(newMessages)
      return newMessages
    })
  }, [saveToStorage])

  const addMessage = useCallback((message: ChatMessage) => {
    updateMessages(prev => [...prev, message])
  }, [updateMessages])

  const updateMessage = useCallback((id: string, updates: Partial<ChatMessage>) => {
    updateMessages(prev =>
      prev.map(msg => (msg.id === id ? { ...msg, ...updates } : msg)),
    )
  }, [updateMessages])

  const clearMessages = useCallback(async () => {
    setMessages([])
    messagesRef.current = []
    storageService.remove(STORAGE_KEY)
    // 同步清理 IndexedDB，防止切换回该会话时恢复已清除的消息
    if (activeSessionIdRef.current) {
      try { await chatStorageService.deleteMessages(activeSessionIdRef.current) }
      catch (e) { logger.warn('[useChatMessages] IndexedDB 清理失败:', e) }
    }
    logger.info('[useChatMessages] Messages cleared')
  }, [])

  const removeMessage = useCallback((id: string) => {
    updateMessages(prev => prev.filter(m => m.id !== id))
  }, [updateMessages])

  /** 替换所有消息（会话切换时从隔离存储恢复） */
  const replaceMessages = useCallback((newMessages: ChatMessage[]) => {
    setMessages(newMessages)
    messagesRef.current = newMessages
    saveToStorage(newMessages)
    logger.info(`[useChatMessages] Messages replaced (${newMessages.length} items)`)
  }, [saveToStorage])

  const clearError = useCallback(() => {
    setChatError(null)
  }, [])

  const sendMessage = useCallback(async (content: string, displayContent?: string, scenarioMode?: string) => {
    void scenarioMode;
    if (!content?.trim()) {
      logger.warn('[useChatMessages] ⚠️ Empty message content, ignoring send request')
      return
    }

    if (isPaused) {
      logger.warn('[useChatMessages] ⚠️ Streaming is paused, ignoring send request')
      return
    }

    lastQuestionRef.current = content.trim()
    const userDisplayContent = (displayContent || content).trim()

    logger.info('[useChatMessages] 🚀 Starting message send:', {
      contentLength: content.trim().length,
      contentPreview: content.trim().substring(0, 50) + (content.trim().length > 50 ? '...' : ''),
      timestamp: Date.now(),
    })

    setChatError(null)
    setIsStreaming(true)

    const userMessage: ChatMessage = {
      id: `user-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`,
      role: 'user',
      content: userDisplayContent,
      timestamp: Date.now(),
      sendStatus: 'sending', // 先标记为发送中
      retryCount: 0,
    }

    addMessage(userMessage)
    logger.info('[useChatMessages] ✅ User message added to UI (status=sending):', { messageId: userMessage.id })

    try {
      logger.info('[useChatMessages] 📡 Calling chatService (streaming mode)...')
      // 使用 TokenBudgetManager 选择完整上下文，不再硬截断 1000 字
      const history = tokenBudgetManager.selectHistory(messagesRef.current)

      // 先创建空的 AI 消息占位（用于流式渐进更新）
      const assistantMessageId = `assistant-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`
      const assistantMessage: ChatMessage = {
        id: assistantMessageId,
        role: 'assistant',
        content: '',
        timestamp: Date.now(),
        isLoading: true,
      }
      addMessage(assistantMessage)

      // 使用流式 SSE API 获取响应（失败时自动降级为非流式）
      let fullContent = ''
      let streamModel = ''  // 回复来源（后端 meta 事件），用于展示来源徽标
      let streamDialectics: ChatMessage['dialectics'] = undefined
      const accumulatedFormulas: any[] = []
      let hasError = false
      let errorMessage = ''

      // ── 尝试 1: 流式 SSE ──
      try {
        for await (const chunk of chatService.sendMessageStream(content.trim(), history)) {
          if (chunk.done) break
          // 思考步骤事件不追加到对话内容（仅转发到侧栏）
          if (!chunk.step) {
            fullContent += chunk.content
          }

          // 累积配方数据（后端通过 type=formula 事件发送）
          if (chunk.formula) {
            accumulatedFormulas.push(chunk.formula)
          }

          // 转发思考步骤到 ChatSidebar（通过 eventBus）
          if (chunk.step) {
            eventBus.emit('thinking:step', { step: chunk.step.step, content: chunk.step.content, status: chunk.step.status, timestamp: Date.now() })
          }

          // 回复来源标识（后端通过 type=meta 事件发送，通常为首个事件）
          if (chunk.model) {
            streamModel = chunk.model
          }

          // 辨证分析（后端通过 type=dialectics 事件发送）
          if (chunk.dialectics) {
            streamDialectics = chunk.dialectics
          }

          updateMessage(assistantMessageId, {
            content: fullContent,
            formulas: accumulatedFormulas.length > 0 ? [...accumulatedFormulas] : undefined,
            model: streamModel || undefined,
            dialectics: streamDialectics || undefined,
          })
        }
      } catch (streamError) {
        const streamErrMsg = streamError instanceof Error ? streamError.message : String(streamError)

        // ── 如果是认证错误，跳过降级（非流式也会遇到同样的认证问题）──
        const isStreamAuthError = streamErrMsg.includes('401') || streamErrMsg.includes('认证') || streamErrMsg.includes('Token') || streamErrMsg.includes('未授权')
        if (isStreamAuthError) {
          logger.warn('[useChatMessages] Stream failed with auth error, skipping fallback (would also fail)')
          updateMessage(userMessage.id, { sendStatus: 'failed' })
          removeMessage(assistantMessageId)
          return // auth:required 事件已在 ChatService 中触发
        }

        // ── 尝试 2: 非流式降级（非认证类错误才降级）──
        // 保留流式已收到的内容，追加而非替换
        logger.warn('[useChatMessages] Stream failed, falling back to non-streaming:', streamErrMsg)
        try {
          const response = await chatService.sendMessage(content.trim(), history)
          // 追加到已收到的流式内容后面
          fullContent = fullContent + (fullContent ? '\n\n' : '') + response.content
          updateMessage(assistantMessageId, {
            content: fullContent,
            formulas: response.formulas || accumulatedFormulas.length > 0 ? [...accumulatedFormulas] : undefined,
            isLoading: false,
            // 传递回复来源，供 MessageBubble 展示「大模型 / 规则引擎降级」徽标
            model: response.model,
          })
        } catch (fallbackError) {
          // 流式和非流式均失败
          const errMsg = fallbackError instanceof Error ? fallbackError.message : String(fallbackError)
          logger.error('[useChatMessages] Both streaming and fallback failed:', errMsg)

          // 认证错误不显示气泡（auth:required 事件已在 ChatService 中触发重新登录）
          const isAuthError = errMsg.includes('401') || errMsg.includes('认证') || errMsg.includes('Token') || errMsg.includes('未授权')
          if (!isAuthError) {
            hasError = true
            errorMessage = errMsg
          } else {
            // 认证失败：清理占位消息，标记用户消息为失败，但不设 chatError（避免显示多余错误提示）
            updateMessage(userMessage.id, { sendStatus: 'failed' })
            removeMessage(assistantMessageId)
            return // 由 auth:required 事件处理重新登录
          }
        }
      }

      // 统一处理结果
      if (!hasError) {
        updateMessage(assistantMessageId, {
          isLoading: false,
          formulas: accumulatedFormulas.length > 0 ? accumulatedFormulas : undefined,
        })
        updateMessage(userMessage.id, { sendStatus: 'sent' })

        // ── 写入 EventLog（append-only） ──
        chatEventLog.append('user/message', userMessage)
        chatEventLog.append('assistant/message', { ...assistantMessage, id: assistantMessageId, content: fullContent, formulas: accumulatedFormulas.length > 0 ? accumulatedFormulas : undefined })

        // ── 自动提取对话偏好并更新用户画像 ──
        try {
          userPreferencesService.extractAndSavePreferencesFromContent(fullContent)
        } catch (e) {
          logger.warn('[useChatMessages] 偏好提取失败:', e)
        }

        // ── 自动触发上下文压缩检查 ──
        if (messagesRef.current.length >= 20) {
          const tokens = tokenBudgetManager.estimateHistory(messagesRef.current)
          if (tokenBudgetManager.shouldCompact(messagesRef.current, tokens)) {
            logger.info('[useChatMessages] Auto-compaction triggered:', { tokens, msgCount: messagesRef.current.length })
            try {
              const result = await contextCompactionEngine.compact(messagesRef.current)
              if (result.compressedCount > 0) {
                setMessages(result.messages)
                logger.info(`[useChatMessages] Compaction done: ${result.compressedCount} msgs → ${result.messages.length}`)
              }
            } catch (e) {
              logger.warn('[useChatMessages] Compaction failed:', e)
            }
          }
        }
      } else {
        // 双重失败：清理占位消息，标记用户消息为失败状态
        updateMessage(userMessage.id, { sendStatus: 'failed' })
        const friendly = toFriendlyErrorMessage(errorMessage)
        const errorMsg: ChatMessage = {
          id: `error-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`,
          role: 'assistant',
          content: '',
          timestamp: Date.now(),
          error: friendly,
        }
        addMessage(errorMsg)
        setChatError(new Error(friendly))
      }
    } catch (err) {
      const error = err instanceof Error ? err : new Error(String(err))
      logger.error('[useChatMessages] ❌ Send message failed:', {
        errorMessage: error.message,
        errorName: error.name,
        errorStack: error.stack?.substring(0, 500),
      })

      // 用户消息发送失败，更新状态
      updateMessage(userMessage.id, { sendStatus: 'failed' })
      logger.warn('[useChatMessages] ⚠️ User message status updated to failed:', { messageId: userMessage.id })

      const friendly = toFriendlyErrorMessage(error)
      const errorMessage: ChatMessage = {
        id: `error-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`,
        role: 'assistant',
        content: '',
        timestamp: Date.now(),
        error: friendly,
      }

      addMessage(errorMessage)
      setChatError(new Error(friendly))
      logger.error('[useChatMessages] 💥 Error state updated, UI should show error message')

      // ── Task 5: 失败消息入离线队列（网络恢复后自动补发） ──
      try {
        const isOnline = typeof navigator !== 'undefined' && navigator.onLine
        if (!isOnline || chatError) {
          offlineManager.enqueue('message', {
            id: userMessage.id,
            payload: { content: userMessage.content, history: tokenBudgetManager.selectHistory(messagesRef.current) },
            timestamp: Date.now(),
            retryCount: (userMessage.retryCount ?? 0) + 1,
          })
          logger.info('[useChatMessages] 消息已加入离线队列')
        }
      } catch { /* 静默降级 */ }
    } finally {
      setIsStreaming(false)
      logger.debug('[useChatMessages] 🔄 Streaming state reset to false')
    }
  }, [addMessage, isPaused])

  const pauseStreaming = useCallback(() => {
    setIsPaused(true)
    setIsStreaming(false)
    logger.info('[useChatMessages] ⏸️ Streaming paused')
  }, [])

  const resumeStreaming = useCallback(() => {
    if (!isPaused) return
    setIsPaused(false)
    const lastQuestion = lastQuestionRef.current
    if (lastQuestion) {
      logger.info('[useChatMessages] ▶️ Resuming streaming with last question:', { lastQuestionPreview: lastQuestion.substring(0, 50) })
      sendMessage(lastQuestion)
    } else {
      logger.warn('[useChatMessages] ⚠️ No last question to resume')
    }
  }, [isPaused, sendMessage])

  const retryLastMessage = useCallback(async () => {
    const lastUserMessage = [...messagesRef.current].reverse().find(m => m.role === 'user')

    if (!lastUserMessage) {
      logger.warn('[useChatMessages] No user message to retry')
      return
    }

    await sendMessage(lastUserMessage.content)
  }, [sendMessage])

  /** 对指定失败消息重新发送（最大重试3次） */
  const retryMessage = useCallback(async (messageId: string) => {
    const targetMsg = messagesRef.current.find(m => m.id === messageId)

    if (!targetMsg) {
      logger.warn('[useChatMessages] retryMessage: 消息未找到:', { messageId })
      return
    }

    if (targetMsg.sendStatus !== 'failed') {
      logger.warn('[useChatMessages] retryMessage: 消息状态非 failed，跳过重试:', {
        messageId,
        sendStatus: targetMsg.sendStatus,
      })
      return
    }

    // 检查重试次数是否已达上限
    const currentRetryCount = targetMsg.retryCount ?? 0
    if (currentRetryCount >= MAX_RETRY) {
      logger.warn('[useChatMessages] retryMessage: 已达最大重试次数，不再重试:', {
        messageId,
        retryCount: currentRetryCount,
        maxRetry: MAX_RETRY,
      })
      return
    }

    logger.info('[useChatMessages] 🔄 开始重试消息:', {
      messageId,
      currentRetry: currentRetryCount + 1,
      maxRetry: MAX_RETRY,
    })

    // 更新消息状态为 sending，重试次数+1
    updateMessage(messageId, {
      sendStatus: 'sending',
      retryCount: currentRetryCount + 1,
    })

    try {
      const response = await chatService.sendMessage(targetMsg.content)
      logger.info('[useChatMessages] ✅ 重试发送成功:', { messageId, retryCount: currentRetryCount + 1 })

      updateMessage(messageId, { sendStatus: 'sent' })

      // 重试成功后添加 AI 回复
      const assistantMessage: ChatMessage = {
        id: `assistant-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`,
        role: 'assistant',
        content: response.content,
        timestamp: response.timestamp || Date.now(),
        formulas: response.formulas,
      }
      addMessage(assistantMessage)
      setChatError(null)
    } catch (err) {
      const error = err instanceof Error ? err : new Error(String(err))
      logger.error('[useChatMessages] ❌ 重试发送失败:', {
        messageId,
        errorMessage: error.message,
        retryCount: currentRetryCount + 1,
      })

      updateMessage(messageId, { sendStatus: 'failed' })
      setChatError(error)
    }
  }, [updateMessage, addMessage])

  const editMessage = useCallback((id: string, newContent: string) => {
    updateMessages(prev =>
      prev.map(msg => {
        if (msg.id !== id) return msg
        return {
          ...msg,
          content: newContent,
          isEdited: true,
          originalContent: msg.originalContent ?? msg.content,
        }
      }),
    )
  }, [updateMessages])

  const retractMessage = useCallback((id: string) => {
    updateMessages(prev =>
      prev.map(msg => {
        if (msg.id !== id) return msg
        return {
          ...msg,
          content: '消息已撤回',
          isRetracted: true,
          retractedAt: Date.now(),
        }
      }),
    )
  }, [updateMessages])

  return {
    messages,
    input,
    setInput,
    isStreaming,
    setIsStreaming,
    chatError,
    setChatError,
    addMessage,
    updateMessage,
    removeMessage,
    clearMessages,
    replaceMessages,
    sendMessage,
    retryLastMessage,
    retryMessage,
    clearError,
    isPaused,
    pauseStreaming,
    resumeStreaming,
    editMessage,
    retractMessage,
    /** 设置当前会话 ID（用于持久化） */
    setActiveSessionId: (id: string | null) => { activeSessionIdRef.current = id },
    /** 检查并执行上下文压缩 */
    checkCompaction: async () => {
      const tokens = tokenBudgetManager.estimateHistory(messagesRef.current)
      if (tokenBudgetManager.shouldCompact(messagesRef.current, tokens)) {
        logger.info('[useChatMessages] Compaction triggered:', { tokens, messageCount: messagesRef.current.length })
        const result = await contextCompactionEngine.compact(messagesRef.current, (step) => {
          logger.debug('[useChatMessages] Compaction step:', step)
        })
        if (result.compressedCount > 0 && activeSessionIdRef.current) {
          await chatStorageService.saveMessages(activeSessionIdRef.current, result.messages)
          setMessages(result.messages)
          logger.info(`[useChatMessages] Compaction complete: ${result.compressedCount} messages compressed`)
        }
      }
    },
  }
}

export type { UseChatMessagesReturn }

﻿/**
 * useChatSendMessage - 消息发送处理 Hook (v12.0 精简版)
 *
 * 精简说明 (2026-06-26):
 * - 移除工作记忆写入（纯内存操作，无持久化）
 * - 移除短期记忆兴趣画像更新（纯副作用，无反馈闭环）
 * - 移除 buildEnhancedPrompt 中的系统元数据注入（[记忆摘要]、[意图分析] 等）
 *   → 这些是系统层面关注点，不应作为用户输入发送给 LLM
 * - 保留：多轮对话指代消解、RAG 增强、配方意图检测
 * - 场景 System Prompt 改由后端注入（role="system"），不再前端拼接
 *
 * @version 12.0.0
 * @lastUpdated 2026-06-26
 */

import { useCallback, useRef } from 'react';
import { useChatMessages } from './useChatMessages';
import type { ChatTabOrchestratorReturn } from './useChatTabOrchestrator';
import { formulaIntelligenceService } from '../services/formulaIntelligenceService';
import { logger } from '@/utils/safeLogger';
import type { IntentDetectionResult } from '../services/hybridNLPEngineV2';

export interface MultiTurnProcessResult {
  resolvedInput: string;
  topicUpdate?: {
    type: 'switch' | 'return' | 'continue';
    topic?: { id: string; title: string };
  };
}

export interface UseChatSendMessageOptions {
  orchestrator: ChatTabOrchestratorReturn;
  ragAugment?: (question: string) => Promise<string>;
  /** LLM 是否可用（用于降级路径优化：不可用时跳过无效预处理） */
  llmAvailable?: boolean;
  /** 当前场景模式，用于后端注入对应 system prompt */
  scenarioMode?: string;
}

export interface UseChatSendMessageReturn {
  handleSendMessage: (content: string) => Promise<void>;
  isSending: boolean;
}

export function useChatSendMessage(
  chatMessages: ReturnType<typeof useChatMessages>,
  options: UseChatSendMessageOptions,
): UseChatSendMessageReturn {
  const { orchestrator, ragAugment, llmAvailable = true, scenarioMode } = options;
  const { messages, sendMessage: chatServiceSendMessage, setInput } = chatMessages;
  const {
    nlpEngine,
    multiTurnDialogue,
    thinkingProcessV3,
  } = orchestrator;

  const isSendingRef = useRef(false);
  const messagesRef = useRef(messages);
  messagesRef.current = messages;

  const handleSendMessage = useCallback(
    async (contentToSend: string) => {
      const trimmed = contentToSend.trim();
      if (!trimmed || isSendingRef.current) return;
      isSendingRef.current = true;

      const { startThinking: startThinkingV3, stopThinking: stopThinkingV3 } = thinkingProcessV3;
      startThinkingV3(trimmed);

      try {
        // ── 降级路径优化：LLM 不可用时跳过所有无效预处理──
        // 原因：thinking_engine 是规则匹配，NLP/RAG/配方意图检测的输出对它无用，
        // 反而会污染 prompt（如注入 JSON 格式指令会让 thinking_engine 困惑）
        let finalContent = trimmed;

        if (llmAvailable) {
          // LLM 可用：执行完整预处理管线

          // Step 1: NLP 意图识别（仅用于后续逻辑分支，不注入用户 Prompt）
          let intentResult: IntentDetectionResult | null = null;
          try {
            intentResult = await nlpEngine.detectIntent(trimmed, {
              context: messages.slice(-5).map((m) => m.content),
              history: messages.slice(-10).map((m) => `${m.role}: ${m.content.length > 200 ? m.content.slice(0, 200) + '…' : m.content}`),
            });
          } catch (e) {
            logger.warn('[handleSendMessage] Intent detection failed:', e);
          }

          // Step 2: 多轮对话处理（指代消解 + 话题追踪）
          let multiTurnResult: MultiTurnProcessResult | null = null;
          try {
            multiTurnResult = await multiTurnDialogue.processUserInput(
              trimmed,
              messages as Parameters<typeof multiTurnDialogue.processUserInput>[1],
              async (text: string) => {
                // 复用已计算的 intentResult，避免重复调用 NLP 引擎
                if (intentResult && text === trimmed) {
                  return { intent: intentResult.primaryIntent, confidence: intentResult.confidence };
                }
                const result = await nlpEngine.detectIntent(text);
                return { intent: result.primaryIntent, confidence: result.confidence };
              },
            );
          } catch (e) {
            logger.warn('[handleSendMessage] Multi-turn processing failed:', e);
          }

          // Step 3: RAG 知识库增强（可选）
          if (ragAugment) {
            try {
              const augmented = await ragAugment(trimmed);
              if (augmented !== trimmed) {
                finalContent = augmented + '\n\n---\n' + trimmed;
                logger.info('[handleSendMessage] RAG context injected');
              }
            } catch (e) {
              logger.warn('[handleSendMessage] RAG augmentation failed:', e);
            }
          }

          // Step 4: 配方意图检测 → 注入结构化输出指令
          const formulaIntent = formulaIntelligenceService.detectIntent(trimmed);
          if (formulaIntent !== 'general_chat') {
            finalContent =
              finalContent +
              `

【结构化输出要求】
请以下面格式输出配方方案，使用 JSON 代码块包裹：
\`\`\`json
{
  "blocks": [
    {"type":"header","data":{"title":"配方名称","description":"一句话描述","level":1}},
    {"type":"metrics","data":{"title":"多维评分","items":[{"label":"功效","value":85,"unit":"分"},{"label":"安全性","value":90,"unit":"分"}]}},
    {"type":"data-table","data":{"title":"配方组成","columns":[{"key":"name","label":"成分"},{"key":"dosage","label":"用量(g)"}],"rows":[{"name":"成分A","dosage":10}]}},
    {"type":"callout","data":{"variant":"info","title":"配伍思路","content":"文字说明"}},
    {"type":"callout","data":{"variant":"warning","title":"注意事项","content":"禁忌说明"}},
    {"type":"list","data":{"variant":"bullet","title":"生产工艺","items":["要点一","要点二"]}}
  ]
}
\`\`\`

重要字段命名规范：
- callout 区块必须用 "variant" 而非 "style"，取值：info / success / warning / summary
- list 区块必须有 "variant" 字段，取值：bullet / number / analysis / checklist
- list 的 items 可以是字符串数组（自动转换）或 [{label, description}] 对象数组`;
          }
        }
        // llmAvailable=false: finalContent = trimmed（原始输入，不做任何污染）

        // Step 5: 发送消息
        await chatServiceSendMessage(finalContent, trimmed, scenarioMode);
        setInput('');

        // Step 6: 同步更新多轮对话（不再用 setTimeout）
        try {
          const currentMessages = messagesRef.current;
          const latestMsgs = currentMessages.filter((m) => m.role === 'assistant');
          if (latestMsgs.length > 0) {
            const last = latestMsgs[latestMsgs.length - 1];
            multiTurnDialogue.addConversationTurn(
              { id: `mt-${Date.now()}`, role: 'user', content: trimmed, timestamp: Date.now() },
              { id: `mt-ai-${Date.now()}`, role: 'assistant', content: last.content, timestamp: Date.now() },
            );
          }
        } catch (e) {
          logger.warn('[handleSendMessage] Post-processing failed:', e);
        }
      } catch (error) {
        logger.error('[handleSendMessage] Send failed:', error);
        throw error;
      } finally {
        stopThinkingV3();
        isSendingRef.current = false;
      }
    },
    [
      messages,
      chatServiceSendMessage,
      setInput,
      nlpEngine,
      multiTurnDialogue,
      thinkingProcessV3,
      ragAugment,
      llmAvailable,
    ],
  );

  return {
    handleSendMessage,
    get isSending() {
      return isSendingRef.current;
    },
  };
}

