/**
 * Context Compaction Hook
 *
 * 基于 DeepSeek Harness 的 compaction 算法实现：
 * - 基于 token 计数的压力检测
 * - 自动摘要压缩历史消息
 * - 保留关键上下文
 */

import { useCallback, useRef } from 'react';
import { logger } from '@/utils/safeLogger';
import { tokenEstimator, type CompactionTrigger, type EventSourcedSession } from '../utils/eventSourcing';
import type { AgentMessage } from '@/components/ai/shared/types';

export interface CompactionOptions {
  /** 压力阈值 (默认 80%) */
  pressureThreshold?: number;
  /** 溢出阈值 (默认 95%) */
  overflowThreshold?: number;
  /** 最大消息数 (触发压力压缩) */
  maxMessageCount?: number;
  /** 最大 token 数 (默认 128000) */
  maxTokens?: number;
  /** 压缩后保留的最小消息数 */
  minMessagesToKeep?: number;
}

export interface CompactionResult {
  /** 是否触发了压缩 */
  triggered: boolean;
  /** 触发原因 */
  trigger?: CompactionTrigger;
  /** 压缩前的消息数 */
  beforeCount: number;
  /** 压缩后的消息数 */
  afterCount: number;
  /** 估算节省的 token 数 */
  tokensSaved: number;
}

/**
 * 计算当前 token 使用量和比例
 */
function calculateTokenUsage(
  messages: AgentMessage[],
  maxTokens: number,
): { used: number; ratio: number } {
  const used = tokenEstimator.estimate(messages);
  return { used, ratio: used / maxTokens };
}

/**
 * 判断是否需要触发压缩
 */
function shouldCompact(
  messages: AgentMessage[],
  options: Required<CompactionOptions>,
): CompactionTrigger | null {
  const { used, ratio } = calculateTokenUsage(messages, options.maxTokens);

  if (ratio >= options.overflowThreshold) {
    return 'context-overflow';
  }

  if (
    ratio >= options.pressureThreshold &&
    messages.length >= options.maxMessageCount
  ) {
    return 'pressure';
  }

  return null;
}

/**
 * 生成压缩摘要 (实际项目中应调用 LLM)
 */
async function generateCompressionSummary(
  messages: AgentMessage[],
  keepCount: number,
): Promise<{ summary: string; remaining: AgentMessage[] }> {
  // 保留最近的消息
  const remaining = messages.slice(-keepCount);
  const toCompress = messages.slice(0, -keepCount);

  // 生成摘要
  const summary = `[上下文摘要] 已压缩 ${toCompress.length} 条历史消息 (约 ${tokenEstimator.estimate(toCompress)} tokens)，保留最近 ${remaining.length} 条关键对话。`;

  // 将摘要注入第一条消息
  if (remaining.length > 0) {
    remaining[0] = {
      ...remaining[0],
      content: summary + (remaining[0].content ?? ''),
    };
  }

  return { summary, remaining };
}

export function useCompaction(options: CompactionOptions = {}) {
  const {
    pressureThreshold = 0.8,
    overflowThreshold = 0.95,
    maxMessageCount = 100,
    maxTokens = 128000,
    minMessagesToKeep = 10,
  } = { ...options };

  const sessionRef = useRef<EventSourcedSession | null>(null);

  /**
   * 检查当前消息是否需要压缩
   */
  const checkCompact = useCallback(
    (messages: AgentMessage[]): CompactionTrigger | null => {
      return shouldCompact(messages, {
        pressureThreshold,
        overflowThreshold,
        maxMessageCount,
        maxTokens,
        minMessagesToKeep,
      });
    },
    [pressureThreshold, overflowThreshold, maxMessageCount, maxTokens, minMessagesToKeep],
  );

  /**
   * 执行压缩操作
   */
  const compact = useCallback(
    async (
      messages: AgentMessage[],
      onMessagesUpdate: (updated: AgentMessage[]) => void,
    ): Promise<CompactionResult> => {
      const trigger = shouldCompact(messages, {
        pressureThreshold,
        overflowThreshold,
        maxMessageCount,
        maxTokens,
        minMessagesToKeep,
      });

      if (!trigger) {
        return {
          triggered: false,
          beforeCount: messages.length,
          afterCount: messages.length,
          tokensSaved: 0,
        };
      }

      logger.info(`[Compaction] Triggered: ${trigger}`);

      // 计算保留数量
      const keepCount = Math.max(minMessagesToKeep, Math.floor(messages.length * 0.2));

      // 计算节省的 token
      const beforeTokens = tokenEstimator.estimate(messages);
      const { remaining } = await generateCompressionSummary(messages, keepCount);
      const afterTokens = tokenEstimator.estimate(remaining);

      // 更新消息
      onMessagesUpdate(remaining);

      return {
        triggered: true,
        trigger,
        beforeCount: messages.length,
        afterCount: remaining.length,
        tokensSaved: beforeTokens - afterTokens,
      };
    },
    [pressureThreshold, overflowThreshold, maxMessageCount, maxTokens, minMessagesToKeep],
  );

  /**
   * 获取当前 token 使用量
   */
  const getTokenUsage = useCallback(
    (messages: AgentMessage[]) => {
      return calculateTokenUsage(messages, maxTokens);
    },
    [maxTokens],
  );

  /**
   * 获取压缩配置
   */
  const config = {
    pressureThreshold,
    overflowThreshold,
    maxMessageCount,
    maxTokens,
    minMessagesToKeep,
  };

  return {
    checkCompact,
    compact,
    getTokenUsage,
    config,
  };
}

/**
 * useExportManager - 导出管理器 Hook (v7.0)
 *
 * 职责：管理聊天消息的导出功能，包括格式选择、
 * 进度跟踪、事件通知等。
 *
 * @version 7.0.0
 * @lastUpdated 2026-05-11
 */

import { useState, useCallback, useRef } from 'react'
import { logger } from '@/utils/safeLogger'
import type { ExportFormat } from '../services/exportService'
import { exportService } from '../services/exportService'
import type { UnsubscribeFn } from '../services/eventBus'
import { eventBus } from '../services/eventBus'
import type { ChatMessage } from '../types'
import { chatApi } from '@/api/chat'

/** 导出消息格式（内部使用，扩展自 ChatMessage 核心字段） */
export interface ExportChatMessage {
  id: string
  role: 'user' | 'assistant' | 'system'
  content: string
  timestamp: number
  isEdited?: boolean
  editedAt?: number
  originalContent?: string
  isWithdrawn?: boolean
  withdrawnAt?: number
  withdrawReason?: string
  replyTo?: string
  quoteContent?: string
  rating?: 'up' | 'down' | null
  feedback?: string
  isBookmarked?: boolean
  bookmarkNote?: string
  tags?: string[]
  metadata?: Record<string, unknown>
}

export interface ExportOptions {
  includeMetadata?: boolean
  exportSource?: 'local' | 'api'
}

export interface UseExportManagerReturn {
  /** 当前选中的导出格式 */
  exportFormat: ExportFormat
  /** 设置导出格式的方法 */
  setExportFormat: React.Dispatch<React.SetStateAction<ExportFormat>>
  /** 是否正在导出 */
  isExporting: boolean
  /** 导出进度 (0-100) */
  exportProgress: number
  /** 是否显示导出对话框 */
  showExportDialog: boolean
  /** 设置导出对话框显示状态的方法 */
  setShowExportDialog: React.Dispatch<React.SetStateAction<boolean>>
  /** 是否包含元数据 */
  includeMetadata: boolean
  /** 设置是否包含元数据 */
  setIncludeMetadata: React.Dispatch<React.SetStateAction<boolean>>
  /** 当前会话ID（用于API导出） */
  currentSessionId: string | null
  /** 设置当前会话ID */
  setCurrentSessionId: React.Dispatch<React.SetStateAction<string | null>>
  /** 执行导出操作的方法 */
  exportMessages: (messages: ChatMessage[], options?: ExportOptions) => Promise<void>
  /** 通过API导出当前会话 */
  exportSession: (sessionId: number, format: ExportFormat, includeMetadata?: boolean) => Promise<void>
  /** 取消正在进行的导出操作 */
  cancelExport: () => void
  /** 验证导出格式 */
  validateFormat: (format: ExportFormat) => { valid: boolean; message?: string }
  /** 订阅导出进度事件 */
  onExportProgress: (handler: (progress: { format: string; processed: number; total: number; percentage: number }) => void) => UnsubscribeFn
  /** 订阅导出完成事件 */
  onExportComplete: (handler: (result: { filePath: string; success: boolean }) => void) => UnsubscribeFn
}

/**
 * 导出管理器 Hook
 *
 * 提供完整的导出功能管理，包括：
 * - 格式选择（JSON/CSV/TXT/HTML/Markdown）
 * - 异步导出支持（大数据量优化）
 * - 实时进度追踪
 * - 事件驱动通知
 * - 取消操作支持
 *
 * @returns UseExportManagerReturn 导出管理器的状态和方法
 *
 * @example
 * ```tsx
 * const {
 *   exportFormat,
 *   setExportFormat,
 *   isExporting,
 *   exportProgress,
 *   showExportDialog,
 *   setShowExportDialog,
 *   exportMessages,
 *   cancelExport
 * } = useExportManager()
 *
 * // 触发导出
 * await exportMessages(messages)
 * ```
 */
export function useExportManager(): UseExportManagerReturn {
  const [exportFormat, setExportFormat] = useState<ExportFormat>('json')
  const [isExporting, setIsExporting] = useState<boolean>(false)
  const [exportProgress, setExportProgress] = useState<number>(0)
  const [showExportDialog, setShowExportDialog] = useState<boolean>(false)
  const [includeMetadata, setIncludeMetadata] = useState<boolean>(true)
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null)

  const abortControllerRef = useRef<AbortController | null>(null)

  /**
   * 将内部 ChatMessage 格式转换为 exportService 需要的格式（包含所有元数据）
   */
  const convertMessages = useCallback((messages: ChatMessage[], includeMeta: boolean): ExportChatMessage[] => {
    return messages.map(msg => {
      const base: ExportChatMessage = {
        id: msg.id,
        role: msg.role,
        content: msg.content,
        timestamp: msg.timestamp,
      }

      if (includeMeta) {
        return {
          ...base,
          isEdited: msg.isEdited,
          editedAt: msg.editedAt,
          originalContent: msg.originalContent,
          isWithdrawn: msg.isWithdrawn,
          withdrawnAt: msg.withdrawnAt,
          withdrawReason: msg.withdrawReason,
          replyTo: msg.replyTo,
          quoteContent: msg.quoteContent,
          rating: msg.rating,
          feedback: msg.feedback,
          isBookmarked: msg.isBookmarked,
          bookmarkNote: msg.bookmarkNote,
          tags: msg.tags,
          metadata: msg.metadata,
        }
      }

      return base
    })
  }, [])

  /**
   * 验证导出格式
   */
  const validateFormat = useCallback((format: ExportFormat): { valid: boolean; message?: string } => {
    const validFormats: ExportFormat[] = ['json', 'csv', 'txt', 'html', 'markdown']

    if (!validFormats.includes(format)) {
      return { valid: false, message: `无效的导出格式: ${format}` }
    }

    switch (format) {
      case 'json':
        return { valid: true }
      case 'csv':
        return { valid: true }
      case 'txt':
        return { valid: true }
      case 'html':
        return { valid: true }
      case 'markdown':
        return { valid: true }
      default:
        return { valid: false, message: `未知的导出格式: ${format}` }
    }
  }, [])

  /**
   * 执行导出操作
   *
   * 异步导出消息到指定格式，自动触发文件下载。
   * 支持大数据量分块处理，通过 eventBus 发布进度事件。
   *
   * @param messages - 要导出的消息数组
   * @param options - 导出选项（包含元数据、导出源）
   * @throws {Error} 当导出被取消时抛出错误
   */
  const exportMessages = useCallback(async (messages: ChatMessage[], options?: ExportOptions): Promise<void> => {
    if (!messages || messages.length === 0) {
      logger.warn('没有可导出的消息')
      return
    }

    const useMetadata = options?.includeMetadata ?? includeMetadata
    const exportSource = options?.exportSource ?? 'local'

    setIsExporting(true)
    setExportProgress(0)

    abortControllerRef.current = new AbortController()

    try {
      // 验证格式
      const validation = validateFormat(exportFormat)
      if (!validation.valid) {
        throw new Error(validation.message || '无效的导出格式')
      }

      // API导出模式
      if (exportSource === 'api' && currentSessionId) {
        logger.info(`通过API导出会话 ${currentSessionId}，格式：${exportFormat}`)

        let blob: Blob
        if (exportFormat === 'json') {
          blob = await chatApi.exportSessionJson(parseInt(currentSessionId), { include_metadata: useMetadata })
        } else if (exportFormat === 'csv') {
          blob = await chatApi.exportSessionCsv(parseInt(currentSessionId), { include_metadata: useMetadata })
        } else {
          throw new Error(`API导出不支持 ${exportFormat} 格式`)
        }

        const filename = `chat_session_${currentSessionId}_${new Date().toISOString().slice(0, 19).replace(/[:T]/g, '_')}.${exportFormat}`
        downloadBlob(blob, filename, exportFormat)

        setExportProgress(100)
        eventBus.emit('export:completed', { filePath: filename, success: true })
        logger.info(`API导出完成：${filename}`)
        return
      }

      // 本地导出模式
      const convertedMessages = convertMessages(messages, useMetadata)
      const filename = exportService.generateFilename(exportFormat)

      eventBus.emit('export:started', {
        format: exportFormat,
        itemCount: messages.length,
      })

      logger.info(`开始导出 ${messages.length} 条消息，格式：${exportFormat}，包含元数据：${useMetadata}`)

      const content = await exportService.exportAsync(
        convertedMessages,
        exportFormat,
        (progress) => {
          setExportProgress(progress.percentage)
          logger.debug(`导出进度：${progress.percentage}% (${progress.processed}/${progress.total})`)
        },
      )

      if (abortControllerRef.current?.signal.aborted) {
        throw new Error('导出操作已取消')
      }

      downloadFile(content, filename, exportFormat)

      setExportProgress(100)

      eventBus.emit('export:completed', { filePath: filename, success: true })

      logger.info(`导出完成：${filename}`)
    } catch (error) {
      if ((error as Error).message === '导出操作已取消') {
        logger.info('用户取消了导出操作')
        setExportProgress(0)
      } else {
        logger.error('导出失败:', error)
        eventBus.emit('export:completed', {
          filePath: '',
          success: false,
        })
        throw error
      }
    } finally {
      setIsExporting(false)
      abortControllerRef.current = null
    }
  }, [exportFormat, convertMessages, includeMetadata, currentSessionId, validateFormat])

  /**
   * 通过API导出当前会话
   *
   * @param sessionId - 会话ID
   * @param format - 导出格式
   * @param includeMetadata - 是否包含元数据
   */
  const exportSession = useCallback(async (sessionId: number, format: ExportFormat, includeMeta = true): Promise<void> => {
    setIsExporting(true)
    setExportProgress(0)

    try {
      // 验证格式
      const validation = validateFormat(format)
      if (!validation.valid) {
        throw new Error(validation.message || '无效的导出格式')
      }

      logger.info(`通过API导出会话 ${sessionId}，格式：${format}，包含元数据：${includeMeta}`)

      let blob: Blob
      if (format === 'json') {
        blob = await chatApi.exportSessionJson(sessionId, { include_metadata: includeMeta })
      } else if (format === 'csv') {
        blob = await chatApi.exportSessionCsv(sessionId, { include_metadata: includeMeta })
      } else {
        throw new Error(`API导出不支持 ${format} 格式`)
      }

      const filename = `chat_session_${sessionId}_${new Date().toISOString().slice(0, 19).replace(/[:T]/g, '_')}.${format}`
      downloadBlob(blob, filename, format)

      setExportProgress(100)
      eventBus.emit('export:completed', { filePath: filename, success: true })
      logger.info(`API导出完成：${filename}`)
    } catch (error) {
      logger.error('API导出失败:', error)
      eventBus.emit('export:completed', { filePath: '', success: false })
      throw error
    } finally {
      setIsExporting(false)
    }
  }, [validateFormat])

  /**
   * 取消正在进行的导出操作
   */
  const cancelExport = useCallback((): void => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort()
      exportService.cancelExport()
      logger.info('已请求取消导出操作')
    }
  }, [])

  /**
   * 订阅导出进度事件
   *
   * @param handler - 进度事件处理函数
   * @returns 取消订阅的函数
   */
  const onExportProgress = useCallback((
    handler: (progress: { format: string; processed: number; total: number; percentage: number }) => void,
  ): UnsubscribeFn => {
    return eventBus.subscribe('export:started', (payload: { format: string; itemCount: number }) => {
      handler({
        format: payload.format || exportFormat,
        processed: payload.itemCount || 0,
        total: payload.itemCount || 0,
        percentage: payload.itemCount ? Math.round((payload.itemCount / payload.itemCount) * 100) : 0,
      })
    })
  }, [exportFormat])

  /**
   * 订阅导出完成事件
   *
   * @param handler - 完成事件处理函数
   * @returns 取消订阅的函数
   */
  const onExportComplete = useCallback((
    handler: (result: { filePath: string; success: boolean }) => void,
  ): UnsubscribeFn => {
    return eventBus.subscribe('export:completed', (payload) => {
      handler({
        filePath: payload.filePath,
        success: payload.success,
      })
    })
  }, [])

  return {
    exportFormat,
    setExportFormat,
    isExporting,
    exportProgress,
    showExportDialog,
    setShowExportDialog,
    includeMetadata,
    setIncludeMetadata,
    currentSessionId,
    setCurrentSessionId,
    exportMessages,
    exportSession,
    cancelExport,
    validateFormat,
    onExportProgress,
    onExportComplete,
  }
}

/**
 * 触发浏览器下载文件
 *
 * @private
 * @param content - 文件内容
 * @param filename - 文件名
 * @param format - 文件格式
 */
function downloadFile(content: string, filename: string, format: ExportFormat): void {
  const mimeTypeMap: Record<ExportFormat, string> = {
    json: 'application/json',
    csv: 'text/csv',
    txt: 'text/plain',
    html: 'text/html',
    markdown: 'text/markdown',
  }

  const blob = new Blob([content], { type: mimeTypeMap[format] + ';charset=utf-8' })
  downloadBlob(blob, filename, format)
}

/**
 * 触发浏览器下载Blob文件
 *
 * @private
 * @param blob - Blob对象
 * @param filename - 文件名
 * @param format - 文件格式
 */
function downloadBlob(blob: Blob, filename: string, _format: ExportFormat): void {
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  link.download = filename
  document.body.appendChild(link)
  link.click()
  document.body.removeChild(link)
  URL.revokeObjectURL(url)
}

export default useExportManager

/**
 * useFocusTrap - 焦点陷阱 Hook (v1.0)
 *
 * 用于模态框、对话框等组件的键盘焦点管理。
 * 确保 Tab 键在指定容器内循环，符合 WCAG 2.1 AA 标准。
 *
 * 功能特性：
 * - 自动捕获 Tab/Shift+Tab 键
 * - 支持初始聚焦元素配置
 * - 支持 Escape 键关闭回调
 * - 支持延迟激活（动画完成后）
 * - 可恢复之前的焦点位置
 * - ARIA 属性自动管理（aria-modal）
 *
 * @version 1.0.0
 * @lastUpdated 2026-05-12
 */

import { useRef, useEffect, useCallback } from 'react'

interface UseFocusTrapOptions {
  /** 是否激活焦点陷阱 */
  active?: boolean
  /** 初始聚焦元素选择器或 ref */
  initialFocus?: string | HTMLElement | null
  /** Escape 键按下时的回调 */
  onEscape?: () => void
  /** 是否恢复之前的焦点 */
  restoreFocus?: boolean
  /** 延迟激活时间 (ms)，用于等待动画完成 */
  delay?: number
}

interface UseFocusTrapReturn {
  /** 容器 ref，需要绑定到模态框根元素 */
  containerRef: React.RefObject<HTMLDivElement | null>
}

/**
 * 焦点陷阱 Hook
 *
 * @example
 * ```tsx
 * function Modal({ isOpen, onClose }) {
 *   const { containerRef } = useFocusTrap({
 *     active: isOpen,
 *     onEscape: onClose,
 *     initialFocus: '[data-autofocus]',
 *   })
 *
 *   return (
 *     <div ref={containerRef} role="dialog" aria-modal="true">
 *       data-autofocus 是纯技术性的焦点落点，不是给用户的控件 ——
 *       必须配 aria-hidden + tabIndex={-1}，否则会出现一个没有名字的可聚焦元素
 *       <input data-autofocus aria-hidden="true" tabIndex={-1} />
 *       <button onClick={onClose}>关闭</button>
 *     </div>
 *   )
 * }
 * ```
 */
export function useFocusTrap(options: UseFocusTrapOptions = {}): UseFocusTrapReturn {
  const {
    active = true,
    initialFocus = null,
    onEscape,
    restoreFocus = true,
    delay = 0,
  } = options

  const containerRef = useRef<HTMLDivElement>(null)
  const previousActiveElement = useRef<HTMLElement | null>(null)

  /**
   * 获取容器内所有可聚焦元素
   */
  const getFocusableElements = useCallback((): HTMLElement[] => {
    const container = containerRef.current
    if (!container) return []

    const selector = [
      'a[href]',
      'button:not([disabled])',
      'input:not([disabled])',
      'select:not([disabled])',
      'textarea:not([disabled])',
      '[tabindex]:not([tabindex="-1"])',
      '[contenteditable="true"]',
    ].join(', ')

    return Array.from(container.querySelectorAll<HTMLElement>(selector))
  }, [])

  /**
   * 获取第一个可聚焦元素
   */
  const getFirstFocusable = useCallback((): HTMLElement | null => {
    const elements = getFocusableElements()
    return elements[0] || null
  }, [getFocusableElements])

  /**
   * 获取最后一个可聚焦元素
   */
  const getLastFocusable = useCallback((): HTMLElement | null => {
    const elements = getFocusableElements()
    return elements[elements.length - 1] || null
  }, [getFocusableElements])

  /**
   * 处理键盘事件
   */
  const handleKeyDown = useCallback(
    (event: KeyboardEvent) => {
      // Escape 键处理
      if (event.key === 'Escape') {
        event.preventDefault()
        event.stopPropagation()
        onEscape?.()
        return
      }

      // Tab 键处理
      if (event.key === 'Tab') {
        const focusableElements = getFocusableElements()

        if (focusableElements.length === 0) {
          event.preventDefault()
          return
        }

        const firstElement = focusableElements[0]
        const lastElement = focusableElements[focusableElements.length - 1]

        if (event.shiftKey) {
          // Shift + Tab: 向后循环
          if (document.activeElement === firstElement) {
            event.preventDefault()
            lastElement.focus()
          }
        } else {
          // Tab: 向前循环
          if (document.activeElement === lastElement) {
            event.preventDefault()
            firstElement.focus()
          }
        }
      }
    },
    [getFocusableElements, onEscape],
  )

  /**
   * 设置初始焦点
   */
  const setInitialFocus = useCallback(() => {
    const container = containerRef.current
    if (!container) return

    let targetElement: HTMLElement | null = null

    if (typeof initialFocus === 'string') {
      targetElement = container.querySelector<HTMLElement>(initialFocus)
    } else if (initialFocus instanceof HTMLElement) {
      targetElement = initialFocus
    } else {
      targetElement = getFirstFocusable()
    }

    if (targetElement) {
      // 使用 requestAnimationFrame 确保 DOM 已更新
      requestAnimationFrame(() => {
        targetElement?.focus({ preventScroll: false })
      })
    }
  }, [initialFocus, getFirstFocusable])

  useEffect(() => {
    if (!active || !containerRef.current) return

    const container = containerRef.current

    // 保存当前焦点
    if (restoreFocus && document.activeElement instanceof HTMLElement) {
      previousActiveElement.current = document.activeElement
    }

    // 设置 ARIA 属性
    container.setAttribute('aria-modal', 'true')

    // 延迟设置初始焦点
    const timer = setTimeout(() => {
      setInitialFocus()
    }, delay)

    // 添加键盘监听
    container.addEventListener('keydown', handleKeyDown)

    return () => {
      clearTimeout(timer)

      // 移除监听器
      container.removeEventListener('keydown', handleKeyDown)

      // 移除 ARIA 属性
      container.removeAttribute('aria-modal')

      // 恢复之前的焦点
      if (restoreFocus && previousActiveElement.current) {
        previousActiveElement.current.focus({ preventScroll: true })
        previousActiveElement.current = null
      }
    }
  }, [active, delay, handleKeyDown, setInitialFocus, restoreFocus])

  return { containerRef }
}

export default useFocusTrap

/**
 * useFormulaManager - 企业级配方管理 Hook (v8.0)
 *
 * 职责：集中处理配方的增删改查、展开收起、搜索过滤、数据表格显示、导入导出等功能。
 *
 * 架构说明（v8.0 内部分区）：
 * ┌─────────────────────────────────────────────────────┐
 * │ [A] 类型定义区    (L56-L110)  接口/常量/类型别名     │
