    if (!Array.isArray(ids) || ids.length === 0) {
      logger.warn('[useFormulaManager] ⚠️ 批量重命名：无效的ID列表')
      return
    }

    setIsLoading(true)
    ids.forEach(id => {
      renameFormula(id)
    })
