export function useKeyboardShortcuts(
  options: UseKeyboardShortcutsOptions = {},
): UseKeyboardShortcutsReturn {
  const {
    disabled = false,
    enableLogging = true,
    enableStats = false,
    stopPropagationDefault = false,
    customShortcuts,
    onConflict,
    beforeTrigger,
  } = options

  // 状态管理
  const [registeredCount, setRegisteredCount] = useState(0)
  const [activeCategory, setActiveCategory] = useState<string | null>(null)

  // 使用 ref 跟踪监听状态，避免无限循环
  const isListeningRef = useRef(false)
  // 用于外部展示的状态（不参与 effect 依赖）
  const [isListeningState, setIsListeningState] = useState(false)

  // Refs（避免重渲染）
  const shortcutsRef = useRef<Map<string, ShortcutConfig>>(new Map())
  const sequenceRef = useRef<Map<string, SequenceShortcutConfig>>(new Map())
  const longPressRef = useRef<Map<string, LongPressShortcutConfig>>(new Map())
  const statsRef = useRef<Map<string, number>>(new Map())
  const lastTriggerRef = useRef<Map<string, number>>(new Map())
  const sequenceBufferRef = useRef<string[]>([])
  const sequenceTimerRef = useRef<ReturnType<typeof setTimeout>>(undefined)
  const longPressTimerRef = useRef<Map<string, ReturnType<typeof setTimeout>>>(new Map())
  const debounceTimersRef = useRef<Map<string, ReturnType<typeof setTimeout>>>(new Map())

  // ===== 初始化预设快捷键 =====

  useEffect(() => {
    if (customShortcuts && customShortcuts.length > 0) {
      customShortcuts.forEach(config => {
        if (!shortcutsRef.current.has(config.id)) {
          shortcutsRef.current.set(config.id, config)
        }
      })
    }

    setRegisteredCount(shortcutsRef.current.size)
  }, [customShortcuts])

  // ===== 核心事件监听器 =====

  const handleKeyDown = useCallback((event: KeyboardEvent) => {
    if (disabled) return

    const target = event.target as HTMLElement
    const isInputFocused =
      target.tagName === 'INPUT' ||
      target.tagName === 'TEXTAREA' ||
      target.isContentEditable

    try {
      // 处理普通快捷键
      for (const [, config] of shortcutsRef.current) {
        if (config.enabled === false) continue
        if (config.inputOnly && !isInputFocused) continue
        if (config.when && !config.when()) continue

        if (matchKeyCombination(event, config.keys)) {
          // 防抖检查
          if (config.debounceMs && debounceTimersRef.current.has(config.id)) {
            continue
          }

          // 触发前钩子
          if (beforeTrigger && !beforeTrigger(config.id, event)) {
            continue
          }

          // 执行处理
          if (config.preventDefault !== false) {
            event.preventDefault()
          }
          if (config.stopPropagation ?? stopPropagationDefault) {
            event.stopPropagation()
          }

          // 防抖设置
          if (config.debounceMs) {
            debounceTimersRef.current.set(config.id, setTimeout(() => {
              debounceTimersRef.current.delete(config.id)
            }, config.debounceMs))
          }

          executeHandler(config.id, config.handler, event)
          return
        }
      }

      // 处理序列快捷键
      handleSequenceShortcut(event, isInputFocused)

      // 处理长按快捷键
      handleLongPressStart(event)

    } catch (error) {
      logger.error('[useKeyboardShortcuts] ❌ 快捷键处理器异常:', error)
    }
  }, [disabled, beforeTrigger, stopPropagationDefault])

  const handleKeyUp = useCallback((event: KeyboardEvent) => {
    handleLongPressEnd(event)
  }, [])

  // ===== 生命周期管理 =====

  useEffect(() => {
    if (!disabled && !isListeningRef.current) {
      window.addEventListener('keydown', handleKeyDown)
      window.addEventListener('keyup', handleKeyUp)
      isListeningRef.current = true
      setIsListeningState(true)  // 更新展示状态

      if (enableLogging) {
        logger.info('[useKeyboardShortcuts] 🎹 已启动全局键盘监听器', {
          registeredCount: shortcutsRef.current.size,
        })
      }
    }

    return () => {
      window.removeEventListener('keydown', handleKeyDown)
      window.removeEventListener('keyup', handleKeyUp)
      isListeningRef.current = false
      setIsListeningState(false)  // 更新展示状态

      // 清理定时器
      if (sequenceTimerRef.current) clearTimeout(sequenceTimerRef.current)
      longPressTimerRef.current.forEach(timer => clearTimeout(timer))
      debounceTimersRef.current.forEach(timer => clearTimeout(timer))
    }
  }, [disabled, handleKeyDown, handleKeyUp])

  // ===== 快捷键匹配逻辑 =====

  /**
   * 匹配按键组合
   */
  function matchKeyCombination(
    event: KeyboardEvent,
    keys: KeyCombination | KeyCombination[],
  ): boolean {
    const combinations = Array.isArray(keys) ? keys : [keys]

    return combinations.some(combo =>
      event.key.toLowerCase() === combo.key.toLowerCase() &&
      !!event.ctrlKey === !!combo.ctrl &&
      !!event.metaKey === !!combo.meta &&
      !!event.altKey === !!combo.alt &&
      !!event.shiftKey === !!combo.shift,
    )
  }

  /**
   * 执行处理器并记录统计
   */
  function executeHandler(id: string, handler: (event: KeyboardEvent) => void, event: KeyboardEvent): void {
    try {
      handler(event)

      if (enableLogging) {
        logger.debug(`[useKeyboardShortcuts] ✅ 触发快捷键: ${id}`)
      }

      if (enableStats) {
        updateStats(id)
      }

      eventBus.emit('shortcut:triggered', { shortcutId: id })
    } catch (error) {
      logger.error(`[useKeyboardShortcuts] ❌ 快捷键 ${id} 执行失败:`, error)
    }
  }

  /**
   * 更新使用统计
   */
  function updateStats(id: string): void {
    const now = Date.now()
    statsRef.current.set(id, (statsRef.current.get(id) || 0) + 1)
    lastTriggerRef.current.set(id, now)
  }

  // ===== 序列快捷键处理 =====

  function handleSequenceShortcut(event: KeyboardEvent, isInputFocused: boolean): void {
    for (const [, config] of sequenceRef.current) {
      if (config.enabled === false) continue
      if (config.inputOnly && !isInputFocused) continue

      const key = event.key.toLowerCase()

      // 添加到缓冲区
      sequenceBufferRef.current.push(key)

      // 检查是否匹配完整序列
      if (arraysEqual(sequenceBufferRef.current, config.sequence.map(k => k.toLowerCase()))) {
        event.preventDefault()

        if (beforeTrigger && !beforeTrigger(config.id, event)) {
          sequenceBufferRef.current = []
          return
        }

        executeHandler(config.id, config.handler, event)
        sequenceBufferRef.current = []
        return
      }

      // 重置超时计时器
      if (sequenceTimerRef.current) clearTimeout(sequenceTimerRef.current)
      sequenceTimerRef.current = setTimeout(() => {
        sequenceBufferRef.current = []
      }, config.timeout || DEFAULT_SEQUENCE_TIMEOUT)
    }
  }

  // ===== 长按快捷键处理 =====

  function handleLongPressStart(event: KeyboardEvent): void {
    for (const [, config] of longPressRef.current) {
      if (config.enabled === false) continue
      if (event.key.toLowerCase() !== config.key.toLowerCase()) continue

      // 开始长按计时
      if (!longPressTimerRef.current.has(config.id)) {
        longPressTimerRef.current.set(
          config.id,
          setTimeout(() => {
            // 首次触发
            if (beforeTrigger && !beforeTrigger(config.id, event)) return

            executeHandler(config.id, config.handler, event)

            // 设置重复触发
            const repeatInterval = config.repeatInterval || DEFAULT_REPEAT_INTERVAL
            const repeatTimer = setInterval(() => {
              executeHandler(config.id, config.handler, event)
            }, repeatInterval)

            longPressTimerRef.current.set(config.id, repeatTimer)
          }, config.holdTime || DEFAULT_HOLD_TIME),
        )
      }
    }
  }

  function handleLongPressEnd(event: KeyboardEvent): void {
    for (const [, config] of longPressRef.current) {
      if (event.key.toLowerCase() === config.key.toLowerCase()) {
        const timer = longPressTimerRef.current.get(config.id)
        if (timer) {
          clearInterval(timer)
          clearTimeout(timer as unknown as number)
          longPressTimerRef.current.delete(config.id)
        }
      }
    }
  }

  // ===== 公共 API =====

  /**
   * 注册单个快捷键
   */
  const registerShortcut = useCallback((config: ShortcutConfig): (() => void) => {
    shortcutsRef.current.set(config.id, config)
    setRegisteredCount(shortcutsRef.current.size)

    // 检测冲突
    const conflicts = checkConflictsInternal(config)
    if (conflicts.hasConflict && onConflict) {
      onConflict(conflicts)
    }

    if (enableLogging) {
      logger.info(`[useKeyboardShortcuts] 📝 注册快捷键: ${config.id} (${config.label})`)
    }

    eventBus.emit('shortcut:registered', { shortcutId: config.id })

    // 返回注销函数
    return () => unregisterShortcut(config.id)
  }, [onConflict, enableLogging])

  /**
   * 注册序列快捷键
   */
  const registerSequenceShortcut = useCallback((config: SequenceShortcutConfig): (() => void) => {
    sequenceRef.current.set(config.id, config)

    if (enableLogging) {
      logger.info(`[useKeyboardShortcuts] 📝 注册序列快捷键: ${config.id}`)
    }

    return () => sequenceRef.current.delete(config.id)
  }, [enableLogging])

  /**
   * 注册长按快捷键
   */
  const registerLongPressShortcut = useCallback((config: LongPressShortcutConfig): (() => void) => {
    longPressRef.current.set(config.id, config)

    if (enableLogging) {
      logger.info(`[useKeyboardShortcuts] 📝 注册长按快捷键: ${config.id}`)
    }

    return () => longPressRef.current.delete(config.id)
  }, [enableLogging])

  /**
   * 注销指定快捷键
   */
  const unregisterShortcut = useCallback((id: string): void => {
    shortcutsRef.current.delete(id)
    sequenceRef.current.delete(id)
    longPressRef.current.delete(id)
    setRegisteredCount(shortcutsRef.current.size)

    if (enableLogging) {
      logger.info(`[useKeyboardShortcuts] 🗑️ 注销快捷键: ${id}`)
    }

    eventBus.emit('shortcut:unregistered', { shortcutId: id })
  }, [enableLogging])

  /**
   * 注销所有快捷键
   */
  const unregisterAll = useCallback((): void => {
    shortcutsRef.current.clear()
    sequenceRef.current.clear()
    longPressRef.current.clear()
    setRegisteredCount(0)

    if (enableLogging) {
      logger.info('[useKeyboardShortcuts] 🧹 已注销所有快捷键')
    }

    eventBus.emit('shortcut:unregisterAll', {})
  }, [enableLogging])

  /**
   * 启用/禁用快捷键
   */
  const enableShortcut = useCallback((id: string): void => {
    const shortcut = shortcutsRef.current.get(id)
    if (shortcut) {
      shortcut.enabled = true
      if (enableLogging) logger.info(`[useKeyboardShortcuts] ✅ 启用快捷键: ${id}`)
    }
  }, [enableLogging])

  const disableShortcut = useCallback((id: string): void => {
    const shortcut = shortcutsRef.current.get(id)
    if (shortcut) {
      shortcut.enabled = false
      if (enableLogging) logger.info(`[useKeyboardShortcuts] ❌ 禁用快捷键: ${id}`)
    }
  }, [enableLogging])

  const setEnabled = useCallback((id: string, enabled: boolean): void => {
    if (enabled) {
      enableShortcut(id)
    } else {
      disableShortcut(id)
    }
  }, [enableShortcut, disableShortcut])

  // ===== 查询方法 =====

  const getShortcut = useCallback((id: string): ShortcutConfig | undefined => {
    return shortcutsRef.current.get(id)
  }, [])

  const getByCategory = useCallback((category: string): ShortcutConfig[] => {
    return Array.from(shortcutsRef.current.values()).filter(s => s.category === category)
  }, [])

  const getAllShortcuts = useCallback((): ShortcutConfig[] => {
    return Array.from(shortcutsRef.current.values())
  }, [])

  const searchShortcuts = useCallback((query: string): ShortcutConfig[] => {
    const lowerQuery = query.toLowerCase()
    return Array.from(shortcutsRef.current.values()).filter(s =>
      s.id.toLowerCase().includes(lowerQuery) ||
      s.label.toLowerCase().includes(lowerQuery) ||
      s.description?.toLowerCase().includes(lowerQuery),
    )
  }, [])

  // ===== 冲突检测 =====

  function checkConflictsInternal(newShortcut?: ShortcutConfig): ConflictResult {
    const allShortcuts = newShortcut
      ? [...Array.from(shortcutsRef.current.values()), newShortcut]
      : Array.from(shortcutsRef.current.values())

    const conflicts: ConflictResult['conflictingShortcuts'] = []

    for (let i = 0; i < allShortcuts.length; i++) {
      for (let j = i + 1; j < allShortcuts.length; j++) {
        const s1 = allShortcuts[i]
        const s2 = allShortcuts[j]

        if (hasKeyConflict(s1.keys, s2.keys)) {
          let type: ConflictResult['conflictingShortcuts'][0]['type']

          if (JSON.stringify(s1.keys) === JSON.stringify(s2.keys)) {
            type = 'exact'
          } else if (isSubset(s1.keys, s2.keys)) {
            type = 'subset'
          } else {
            type = 'partial'
          }

          conflicts.push({
            shortcut1: s1,
            shortcut2: s2,
            type,
            suggestion: generateConflictSuggestion(s1, s2),
          })
        }
      }
    }

    return {
      hasConflict: conflicts.length > 0,
      conflictingShortcuts: conflicts,
    }
  }

  const checkConflicts = useCallback((): ConflictResult => {
    return checkConflictsInternal()
  }, [])

  const resolveConflict = useCallback((winnerId: string, loserId: string): void => {
    disableShortcut(loserId)
    if (enableLogging) {
      logger.warn(`[useKeyboardShortcuts] ⚠️ 解决冲突: ${winnerId} 胜出, ${loserId} 被禁用`)
    }
  }, [disableShortcut, enableLogging])

  // ===== 统计功能 =====

  const getUsageStats = useCallback((): ShortcutUsageStats => {
    const sorted = Array.from(statsRef.current.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, 10)

    const totalTriggers = Array.from(statsRef.current.values()).reduce((sum, c) => sum + c, 0)
    const intervals: number[] = []

    lastTriggerRef.current.forEach(time => {
      intervals.push(Date.now() - time)
    })

    return {
      totalTriggers,
      lastTriggered: intervals.length > 0 ? new Date(Math.min(...intervals.map(i => Date.now() - i))) : null,
      averageInterval: intervals.length > 0 ? intervals.reduce((a, b) => a + b, 0) / intervals.length : 0,
      topShortcuts: sorted.map(([id, count]) => ({ id, count })),
    }
  }, [])

  const resetStats = useCallback((): void => {
    statsRef.current.clear()
    lastTriggerRef.current.clear()
    if (enableLogging) logger.info('[useKeyboardShortcuts] 📊 统计数据已重置')
  }, [enableLogging])

  // ===== UI 辅助方法 =====

  const getHints = useCallback((category?: string): ShortcutHint[] => {
    const shortcuts = category
      ? getByCategory(category)
      : getAllShortcuts()

    return shortcuts
      .filter(s => s.enabled !== false)
      .map(s => ({
        id: s.id,
        label: s.label,
        keys: formatKeyCombination(Array.isArray(s.keys) ? s.keys[0] : s.keys),
        category: s.category || 'custom',
        description: s.description,
      }))
  }, [getByCategory, getAllShortcuts])

  const formatKeyCombination = useCallback((keys: KeyCombination): string => {
    const parts: string[] = []

    if (keys.ctrl) parts.push('Ctrl')
    if (keys.meta) parts.push('Cmd')
    if (keys.alt) parts.push('Alt')
    if (keys.shift) parts.push('Shift')

    parts.push(keys.key.toUpperCase())

    return parts.join(' + ')
  }, [])

  const isShortcutAvailable = useCallback((keys: KeyCombination): boolean => {
    return !Array.from(shortcutsRef.current.values()).some(s =>
      hasKeyConflict(s.keys, keys),
    )
  }, [])

  // ===== 导入/导出 =====

  const exportConfig = useCallback((): ShortcutsExportFormat => {
    return {
      version: '8.0.0',
      exportedAt: new Date().toISOString(),
      shortcuts: Array.from(shortcutsRef.current.values()).map(s => ({
        id: s.id,
        keys: s.keys,
        enabled: s.enabled !== false,
      })),
    }
  }, [])

  const importConfig = useCallback((config: ShortcutsExportFormat): void => {
    config.shortcuts.forEach(({ id, keys, enabled }) => {
      const existing = shortcutsRef.current.get(id)
      if (existing) {
        existing.keys = keys
        existing.enabled = enabled
      }
    })

    if (enableLogging) {
      logger.info(`[useKeyboardShortcuts] 📥 已导入 ${config.shortcuts.length} 个快捷键配置`)
    }
  }, [enableLogging])

  const resetToDefaults = useCallback((): void => {
    unregisterAll()
    // 可以重新加载默认预设
    if (enableLogging) logger.info('[useKeyboardShortcuts] 🔄 已重置为默认配置')
  }, [unregisterAll, enableLogging])

  // ===== 预设管理 =====

  const applyPreset = useCallback((presetName: string): void => {
    const preset = BUILTIN_PRESETS[presetName]
    if (!preset) {
      logger.error(`[useKeyboardShortcuts] ❌ 预设不存在: ${presetName}`)
      return
    }

    unregisterAll()
    preset.forEach(config => registerShortcut(config))

    setActiveCategory(null)
    if (enableLogging) logger.info(`[useKeyboardShortcuts] ✨ 已应用预设: ${presetName}`)
  }, [unregisterAll, registerShortcut, enableLogging])

  const getAvailablePresets = useCallback((): string[] => {
    return Object.keys(BUILTIN_PRESETS)
  }, [])

  // ===== 返回值 =====

  return {
    isListening: isListeningState,
    registeredCount,
    activeCategory,

    registerShortcut,
    registerSequenceShortcut,
    registerLongPressShortcut,
    unregisterShortcut,
    unregisterAll,

    enableShortcut,
    disableShortcut,
    setEnabled,

    getShortcut,
    getByCategory,
    getAllShortcuts,
    searchShortcuts,

    checkConflicts,
    resolveConflict,

    getUsageStats,
    resetStats,

    getHints,
    formatKeyCombination,
    isShortcutAvailable,

    exportConfig,
    importConfig,
    resetToDefaults,

    applyPreset,
    getAvailablePresets,
  }
}

// ===== 辅助函数 =====

function hasKeyConflict(
  keys1: KeyCombination | KeyCombination[],
  keys2: KeyCombination | KeyCombination[],
): boolean {
  const combos1 = Array.isArray(keys1) ? keys1 : [keys1]
  const combos2 = Array.isArray(keys2) ? keys2 : [keys2]

  return combos1.some(c1 =>
    combos2.some(c2 =>
      c1.key.toLowerCase() === c2.key.toLowerCase() &&
      !!c1.ctrl === !!c2.ctrl &&
      !!c1.meta === !!c2.meta &&
      !!c1.alt === !!c2.alt &&
      !!c1.shift === !!c2.shift,
    ),
  )
}

function isSubset(
  parent: KeyCombination | KeyCombination[],
  child: KeyCombination | KeyCombination[],
): boolean {
  const parentCombos = Array.isArray(parent) ? parent : [parent]
  const childCombos = Array.isArray(child) ? child : [child]

  return parentCombos.some(pc =>
    childCombos.some(cc =>
      pc.key.toLowerCase() === cc.key.toLowerCase() &&
      (!cc.ctrl || pc.ctrl) &&
      (!cc.meta || pc.meta) &&
      (!cc.alt || pc.alt) &&
      (!cc.shift || pc.shift),
    ),
  )
}

function arraysEqual<T>(a: T[], b: T[]): boolean {
  if (a.length !== b.length) return false
  return a.every((val, idx) => val === b[idx])
}

function generateConflictSuggestion(
  s1: ShortcutConfig,
  s2: ShortcutConfig,
): string {
  const priority1 = s1.priority ?? 999
  const priority2 = s2.priority ?? 999

  if (priority1 < priority2) {
    return `"${s1.label}" 优先级更高，建议修改 "${s2.label}" 的快捷键`
  } else if (priority2 < priority1) {
    return `"${s2.label}" 优先级更高，建议修改 "${s1.label}" 的快捷键`
  }

  return `两个快捷键冲突，请手动选择保留哪一个`
}

// ===== 预设导出 =====

export const KEYBOARD_PRESETS = {
  vscode: 'VSCode',
  sublime: 'Sublime Text',
  vim: 'Vim',
}

export default useKeyboardShortcuts

import { useState, useCallback, useRef } from 'react'

// ===== 内联类型定义（避免 ai.types.ts 导出问题）=====
interface ChatMessage {
  id: string
  role: 'user' | 'assistant' | 'system'
  content: string
  timestamp: number
  formulas?: {
    name: string
    value: number
    unit?: string
    confidence?: number
  }[]
  isLoading?: boolean
  error?: string
}

interface Topic {
  id: string
  title: string
  type: 'formula-design' | 'safety-review' | 'cost-analysis' | 'general-qna' | 'regulatory-query' | 'quality-control'
  context: TopicContext
  parentTopicId?: string
  childTopics: string[]
  createdAt: number
  updatedAt: number
  status: 'active' | 'paused' | 'completed' | 'abandoned'
}

interface TopicContext {
  mainQuery: string
  relatedEntities: string[]
  keyParameters: Record<string, string>
  constraints: string[]
}

interface Reference {
  id: string
  text: string
  resolvedText: string
  resolvedAt: number
  messageId: string
  /** 实体类型：用于基于类型的智能指代绑定 */
  entityType?: 'ingredient' | 'formula' | 'dosage' | 'effect' | 'product' | 'safety' | 'cost' | 'regulation' | 'general'
  /** 在对话中的位置序号（0=最早，越大越近） */
  positionIndex?: number
}

interface DialogueState {
  activeTopic: Topic | undefined
  topicStack: Topic[]
  recentReferences: Map<string, Reference>
  unresolvedReferences: Reference[]
  actionQueue: PendingAction[]
  conversationTurns: ConversationTurn[]
  maxContextSize: number
}

interface ConversationTurn {
  id: string
  messages: { user: ChatMessage; ai: ChatMessage }
  topicId: string
  status: 'active' | 'paused' | 'completed'
  createdAt: number
  updatedAt: number
  summary?: string
}

interface PendingAction {
  id: string
  type: 'send_message' | 'switch_topic' | 'fetch_context' | 'generate_summary'
  payload: any
  priority: number
  createdAt: number
}

const MAX_CONTEXT_SIZE = 50
const MAX_TOPIC_STACK_DEPTH = 5

class MultiTurnDialogueManager {
  private state: DialogueState

  constructor() {
    this.state = {
      activeTopic: undefined,
      topicStack: [],
      recentReferences: new Map(),
      unresolvedReferences: [],
      actionQueue: [],
      conversationTurns: [],
      maxContextSize: MAX_CONTEXT_SIZE,
    }
  }

  async processUserInput(
    userInput: string,
    currentMessages: ChatMessage[],
    detectIntent?: (text: string) => Promise<{ intent: string; confidence: number }>,
  ): Promise<ProcessResult> {
    const startTime = performance.now()

    const resolvedInput = this.resolveReferences(userInput)

    let topicUpdate: TopicUpdate

    if (detectIntent) {
      const intentResult = await detectIntent(resolvedInput)
      topicUpdate = this.trackTopic(resolvedInput, intentResult.intent)
    } else {
      topicUpdate = this.trackTopic(resolvedInput)
    }

    const context = this.assembleContext(topicUpdate)

    return {
      resolvedInput,
      topicUpdate,
      context,
      processingTime: performance.now() - startTime,
    }
  }

  /**
   * 增强型指代消解 — 支持基于实体类型的智能绑定、多指代、远距离引用
   *
   * 消解策略（按优先级）：
   *   1. 序数指代："第一个/第二个/最后一个/上一个" → 按positionIndex选择
   *   2. 类型绑定指代："这个配方/那味药/该成分" → 匹配entityType的最近引用
   *   3. 近距代词："它/这个/那个" → 最近的一个引用
   *   4. 远距离引用："最开始说的那个方案"、"3轮之前提到的XX" → 向前搜索
   */
  private resolveReferences(text: string): string {
    let resolved = text

    // 将 recentReferences 转为有序数组（按时间倒序，最近的在前）
    const orderedRefs = Array.from(this.state.recentReferences.values())
      .sort((a, b) => b.resolvedAt - a.resolvedAt)
      .map((ref, idx) => ({ ...ref, positionIndex: idx }))

    if (orderedRefs.length === 0) return resolved

    // ── 策略1: 序数指代消解 ──
    resolved = resolved.replace(/(第[一二三四五六七八九十\d]+个?)(配方|方案|成分|药材|原料|产品|建议|方法)/gi,
      (_, ordinal, noun) => {
        const idx = this.parseOrdinal(ordinal) // "一"→0, "二"→1, "1"→0, "2"→1...
        if (idx >= 0 && idx < orderedRefs.length) {
          const ref = orderedRefs[idx]
          this.markReferenceResolved(ref.id)
          return ref.resolvedText + noun
        }
        return `${ordinal}${noun}`
      }
    )

    // ── 策略2: 类型绑定指代消解 ──
    const typeBindingPatterns: [RegExp, Reference['entityType']][] = [
      [/(这|那|该)(配方|方案|产品|饮品|制剂)/gi, 'formula'],
      [/(这|那|该)(味?|种?)(药材|原料|成分|中药|草本|提取物)/gi, 'ingredient'],
      [/(这|那|该)(个?)(剂量|用量|浓度|比例|配比)/gi, 'dosage'],
      [/(这|那|该)(个?)(功效|作用|效果|功能|益处)/gi, 'effect'],
      [/(这|那|该)(个?)(安全性|风险|副作用|禁忌|毒性)/gi, 'safety'],
      [/(这|那|该)(个?)(成本|价格|预算|费用)/gi, 'cost'],
      [/(这|那|该)(个?)(标准|法规|规定|合规)/gi, 'regulation'],
    ]

    for (const [pattern, type] of typeBindingPatterns) {
      const typeRefs = orderedRefs.filter(r => r.entityType === type)
      if (typeRefs.length > 0) {
        const targetRef = typeRefs[0] // 最近的同类型引用
        resolved = resolved.replace(pattern, targetRef.resolvedText)
        this.markReferenceResolved(targetRef.id)
      }
    }

    // ── 策略3: 近距通用代词消解（仅当策略2未处理时）──
    if (orderedRefs.length > 0) {
      const nearestRef = orderedRefs[0]

      // 处理"它"
      resolved = resolved.replace(/\b它\b/g, nearestRef.resolvedText)

      // 处理"这个"/"那个"（不跟名词的裸代词）
      resolved = resolved.replace(/(?<![a-zA-Z\u4e00-\u9fa5])(这个|那个)(?![a-zA-Z\u4e00-\u9fa5])/g, nearestRef.resolvedText)

      // 处理"上面那个"
      resolved = resolved.replace(/上面那个/g, nearestRef.resolvedText)

      if (resolved !== text) {
        this.markReferenceResolved(nearestRef.id)
      }
    }

    // ── 策略4: 远距离引用消解 ──
    const farRefPatterns: [RegExp, number][] = [
      [/(最开始|最初|第一次|最前面).*(?:说|提|讲|问|提到)/gi, 0],           // 最远的
      [/(之前|前面|刚才|早些).*(?:说|提|讲|问|提到)/gi, Math.min(2, orderedRefs.length - 1)],  // 较远的
      [/(上一轮|上一次|前一次).*(?:说|提|讲|问|提到)/gi, Math.min(1, orderedRefs.length - 1)],  // 前一轮的
    ]

    for (const [pattern, offsetIdx] of farRefPatterns) {
      if (offsetIdx < orderedRefs.length) {
        const farRef = orderedRefs[offsetIdx]
        resolved = resolved.replace(pattern, farRef.resolvedText)
        this.markReferenceResolved(farRef.id)
      }
    }

    this.detectNewReferences(resolved)
    return resolved
  }

  /** 解析中文/阿拉伯数字序数为0-based索引 */
  private parseOrdinal(ordinal: string): number {
    const cnMap: Record<string, number> = { '一': 0, '二': 1, '三': 2, '四': 3, '五': 4, '六': 5, '七': 6, '八': 7, '九': 8, '十': 9, '首': 0, '末': -1 }
    const match = ordinal.match(/[一二三四五六七八九十首末]/)
    if (match && match[0] in cnMap) return cnMap[match[0]]
    const numMatch = ordinal.match(/\d+/)
    if (numMatch) return parseInt(numMatch[0], 10) - 1
    return -1
  }

  private detectNewReferences(text: string): void {
    const patterns = [
      { pattern: /"([^"]+)"/g, type: 'quoted' as const },
      { pattern: /([A-Z][a-zA-Z0-9]+)/g, type: 'identifier' as const },
      { pattern: /(GB\s*[\d.]+|ISO\s*\d+)/g, type: 'standard' as const },
    ]

    patterns.forEach(({ pattern }) => {
      const matches = [...text.matchAll(pattern)]
      matches.forEach(match => {
        const refId = `ref-${Date.now()}-${Math.random().toString(36).slice(2)}`

        // 实体类型推断
        let inferredType: Reference['entityType'] = 'general'
        const matchedText = match[0]

        if (/配方|方案|产品|饮品|制剂|固体饮料|胶囊/.test(matchedText)) inferredType = 'formula'
        else if (/黄芪|人参|枸杞|当归|甘草|肽|蛋白|提取物|原料|药材/.test(matchedText)) inferredType = 'ingredient'
        else if (/\d+(\.\d+)?\s*(g|mg|ml|kg|%|ppm)/i.test(matchedText)) inferredType = 'dosage'
        else if (/功效|作用|降血糖|降血压|抗氧化|免疫|改善/.test(matchedText)) inferredType = 'effect'
        else if (/GB\s*\d+|ISO|法规|标准|安全|毒性|副作用/.test(matchedText)) inferredType = 'safety'
        else if (/成本|价格|元|预算|费用|便宜|贵/.test(matchedText)) inferredType = 'cost'

        const reference: Reference = {
          id: refId,
          text: match[0],
          resolvedText: match[1] || match[0],
          resolvedAt: Date.now(),
          messageId: '',
          entityType: inferredType,
          positionIndex: this.state.unresolvedReferences.length,
        }

        this.state.unresolvedReferences.push(reference)
      })
    })
  }

  private markReferenceResolved(refId: string): void {
    const index = this.state.unresolvedReferences.findIndex(r => r.id === refId)
    if (index >= 0) {
      const [resolved] = this.state.unresolvedReferences.splice(index, 1)
      this.state.recentReferences.set(resolved.id, resolved)

      if (this.state.recentReferences.size > 20) {
        const firstKey = this.state.recentReferences.keys().next().value
        if (firstKey) {
          this.state.recentReferences.delete(firstKey)
        }
      }
    }
  }

  private trackTopic(
    text: string,
    intent?: string,
  ): TopicUpdate {
    const isTopicSwitch = this.isTopicSwitchSignal(text)
    const isTopicReturn = this.isTopicReturnSignal(text)

    if (isTopicReturn && this.state.topicStack.length > 0) {
      const previousTopic = this.state.topicStack.pop()!
      this.state.activeTopic = previousTopic
      previousTopic.status = 'active'

      return {
        type: 'return',
        to: previousTopic,
      }
    }

    if (isTopicSwitch || !this.state.activeTopic) {
      const newTopic = this.createTopicFromInput(text, intent)

      if (this.state.activeTopic) {
        this.state.topicStack.push(this.state.activeTopic)
        this.state.activeTopic.status = 'paused'
      }

      this.state.activeTopic = newTopic

      return {
        type: 'switch',
        from: this.state.topicStack[this.state.topicStack.length - 1],
        to: newTopic,
      }
    }

    if (this.state.activeTopic) {
      this.state.activeTopic.updatedAt = Date.now()
      this.updateTopicContext(this.state.activeTopic, text)
    }

    return {
      type: 'continue',
      topic: this.state.activeTopic,
    }
  }

  private isTopicSwitchSignal(text: string): boolean {
    const switchPatterns = [
      /^(另外|还有|接下来|换个|新的|关于).*/gi,
      /^(我们讨论一下|我想了解|请帮我).*(配方|安全性|成本|法规|质量)/gi,
      /^切换到.*/gi,
      /^新话题/gi,
    ]

    return switchPatterns.some(pattern => pattern.test(text))
  }

  private isTopicReturnSignal(text: string): boolean {
    const returnPatterns = [
      /^(回到|继续|接着讨论|刚才那个|之前说的).*/gi,
      /^(继续讨论).*配方/gi,
      /^回到.*话题/gi,
    ]

    return returnPatterns.some(pattern => pattern.test(text))
  }

  private createTopicFromInput(text: string, intent?: string): Topic {
    const topicType = this.inferTopicType(intent)
    const title = this.generateTopicTitle(text, topicType)

    return {
      id: `topic-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      title,
      type: topicType,
      context: {
        mainQuery: text.slice(0, 100),
        relatedEntities: [],
        keyParameters: {},
        constraints: [],
      },
      createdAt: Date.now(),
      updatedAt: Date.now(),
      status: 'active',
      childTopics: [],
    }
  }

  private inferTopicType(intent?: string): Topic['type'] {
    const intentToTypeMap: Record<string, Topic['type']> = {
      'FORMULA_DESIGN': 'formula-design',
      'SAFETY_ASSESSMENT': 'safety-review',
      'COST_ANALYSIS': 'cost-analysis',
      'EFFICACY_EVALUATION': 'general-qna',
      'INGREDIENT_QUERY': 'general-qna',
      'REGULATORY_QUERY': 'regulatory-query',
      'QUALITY_CONTROL': 'quality-control',
      'FORMULA_OPTIMIZATION': 'formula-design',
      'general_inquiry': 'general-qna',
    }

    return intentToTypeMap[intent || ''] || 'general-qna'
  }

  private generateTopicTitle(text: string, type: Topic['type']): string {
    const maxLength = 30

    if (text.length <= maxLength) {
      return text
    }

    const typePrefixes: Record<Topic['type'], string> = {
      'formula-design': '配方设计：',
      'safety-review': '安全评估：',
      'cost-analysis': '成本分析：',
      'general-qna': '咨询：',
      'regulatory-query': '法规查询：',
      'quality-control': '质量控制：',
    }

    return `${typePrefixes[type]}${text.slice(0, maxLength - typePrefixes[type].length)}...`
  }

  private updateTopicContext(topic: Topic, text: string): void {
    topic.context.relatedEntities = [
      ...new Set([...topic.context.relatedEntities, ...this.extractEntities(text)]),
    ].slice(0, 10)
  }

  private extractEntities(text: string): string[] {
    const entities: string[] = []

    const formulaPattern = /([\u4e00-\u9fa5]+配方)/gi
    const ingredientPattern = /(?:用量|添加|使用)([\u4e00-\u9fa5]{2,8})/gi
    const standardPattern = /(GB\s*[\d.]+|ISO\s*\d+)/gi

    ;[formulaPattern, ingredientPattern, standardPattern].forEach(pattern => {
      const matches = text.match(pattern)
      if (matches) {
        entities.push(...matches)
      }
    })

    return entities
  }

  assembleContext(update?: TopicUpdate): AssembledContext {
    const workingMemory = this.getRecentWorkingMemory()
    const shortTermMemory = this.getShortTermMemorySummary()

    return {
      systemPrompt: this.getSystemPrompt(),
      workingMemory,
      shortTermMemory,
      currentTopic: update?.topic || update?.to || this.state.activeTopic,
      unresolvedItems: this.state.unresolvedReferences,
      topicHistory: this.state.topicStack.map(t => t.title),
    }
  }

  private getRecentWorkingMemory(): string {
    const recentTurns = this.state.conversationTurns.slice(-5)

    return recentTurns.map(turn => {
      const userPreview = turn.messages.user.content.slice(0, 80)
      const aiPreview = turn.messages.ai.content.slice(0, 80)
      return `[${turn.status}] User: ${userPreview}\nAI: ${aiPreview}`
    }).join('\n\n')
  }

  private getShortTermMemorySummary(): string {
    const topics = this.state.topicStack.length > 0
      ? `\n历史话题: ${this.state.topicStack.map(t => t.title).join(' → ')}`
      : ''

    const references = this.state.unresolvedReferences.length > 0
      ? `\n未解析引用: ${this.state.unresolvedReferences.map(r => r.text).join(', ')}`
      : ''

    return `${topics}${references}`
  }

  private getSystemPrompt(): string {
    return `你是一位专业的配方设计专家助手。请基于提供的上下文信息回答用户的问题。

当前能力：
- 配方设计与优化
- 安全性评估（毒理学、法规合规）
- 成本分析与控制
- 功效评估与功能声称
- 原料信息查询
- 法规标准解读
- 质量控制体系

回答要求：
1. 专业准确，引用相关标准和法规
2. 结构清晰，分点陈述
3. 提供具体数值和建议
4. 如有不确定性，明确说明`
  }

  getActiveTopic(): Topic | undefined {
    return this.state.activeTopic
  }

  getTopicStack(): Topic[] {
    return [...this.state.topicStack]
  }

  startNewTopic(title?: string): Topic {
    const newTopic: Topic = {
      id: `topic-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      title: title || '新对话',
      type: 'general-qna',
      context: {
        mainQuery: '',
        relatedEntities: [],
        keyParameters: {},
        constraints: [],
      },
      createdAt: Date.now(),
      updatedAt: Date.now(),
      status: 'active',
      childTopics: [],
    }

    if (this.state.activeTopic) {
      this.state.topicStack.push(this.state.activeTopic)
      this.state.activeTopic.status = 'paused'
    }

    this.state.activeTopic = newTopic

    return newTopic
  }

  switchToTopic(topicId: string): boolean {
    const targetIndex = this.state.topicStack.findIndex(t => t.id === topicId)

    if (targetIndex >= 0) {
      if (this.state.activeTopic) {
        this.state.topicStack.push(this.state.activeTopic)
        this.state.activeTopic.status = 'paused'
      }

      const [target] = this.state.topicStack.splice(targetIndex, 1)
      target.status = 'active'
      this.state.activeTopic = target

      return true
    }

    return false
  }

  addConversationTurn(userMsg: ChatMessage, aiMsg: ChatMessage): void {
    const turn: ConversationTurn = {
      id: `turn-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      messages: { user: userMsg, ai: aiMsg },
      topicId: this.state.activeTopic?.id || '',
      status: 'completed',
      createdAt: Date.now(),
      updatedAt: Date.now(),
    }

    this.state.conversationTurns.push(turn)

    if (this.state.conversationTurns.length > MAX_CONTEXT_SIZE) {
      this.state.conversationTurns.shift()
    }
  }

  clear(): void {
    this.state = {
      activeTopic: undefined,
      topicStack: [],
      recentReferences: new Map(),
      unresolvedReferences: [],
      actionQueue: [],
      conversationTurns: [],
      maxContextSize: MAX_CONTEXT_SIZE,
    }
  }

  getStats(): {
    activeTopic: Topic | undefined
    stackDepth: number
    turnsCount: number
    referencesCount: number
    unresolvedCount: number
  } {
    return {
      activeTopic: this.state.activeTopic,
      stackDepth: this.state.topicStack.length,
      turnsCount: this.state.conversationTurns.length,
      referencesCount: this.state.recentReferences.size,
      unresolvedCount: this.state.unresolvedReferences.length,
    }
  }
}

interface ProcessResult {
  resolvedInput: string
  topicUpdate: TopicUpdate
  context: AssembledContext
  processingTime: number
}

interface TopicUpdate {
  type: 'switch' | 'return' | 'continue'
  from?: Topic
  to?: Topic
  topic?: Topic
}

interface AssembledContext {
  systemPrompt: string
  workingMemory: string
  shortTermMemory: string
  currentTopic?: Topic
  unresolvedItems: Reference[]
  topicHistory: string[]
}

export const multiTurnDialogueManager = new MultiTurnDialogueManager()

export function useMultiTurnDialogue() {
  const [, forceUpdate] = useState(0)
  const updateRef = useRef(0)

  const processUserInput = useCallback(async (
    userInput: string,
    currentMessages: ChatMessage[],
    detectIntent?: (text: string) => Promise<{ intent: string; confidence: number }>,
  ) => {
    const result = await multiTurnDialogueManager.processUserInput(userInput, currentMessages, detectIntent)
    updateRef.current++
    forceUpdate(updateRef.current)
    return result
  }, [])

  const getActiveTopic = useCallback(() => {
    return multiTurnDialogueManager.getActiveTopic()
  }, [])

  const getTopicStack = useCallback(() => {
    return multiTurnDialogueManager.getTopicStack()
  }, [])

  const startNewTopic = useCallback((title?: string) => {
    const topic = multiTurnDialogueManager.startNewTopic(title)
    forceUpdate(Date.now())
    return topic
  }, [])

  const switchToTopic = useCallback((topicId: string) => {
    const success = multiTurnDialogueManager.switchToTopic(topicId)
    if (success) forceUpdate(Date.now())
    return success
  }, [])

  const addConversationTurn = useCallback((userMsg: ChatMessage, aiMsg: ChatMessage) => {
    multiTurnDialogueManager.addConversationTurn(userMsg, aiMsg)
  }, [])

  const clearDialogue = useCallback(() => {
    multiTurnDialogueManager.clear()
    forceUpdate(Date.now())
  }, [])

  const getStats = useCallback(() => {
    return multiTurnDialogueManager.getStats()
  }, [])

  return {
    processUserInput,
    getActiveTopic,
    getTopicStack,
    startNewTopic,
    switchToTopic,
    addConversationTurn,
    clearDialogue,
    getStats,
  }
}

/**
 * useOfflineManager - 企业级离线管理系统 (v8.0)
 *
 * 职责：
 * - 封装 OfflineManager 为易用的 React Hook
 * - 提供声明式的离线队列管理和数据同步能力
 * - 支持智能缓存策略和数据压缩
 * - 提供后台同步和冲突解决机制
 *
 * v8.0 新增特性：
 * - ✅ 智能缓存策略（LRU + TTL + 优先级队列）
 * - ✅ 数据压缩（GZIP/LZString 压缩算法）
 * - ✅ 后台同步（Service Worker 集成）
 * - ✅ 冲突检测与自动解决
 * - ✅ 离线数据预估和存储监控
 * - ✅ 同步优先级管理
 * - ✅ 批量操作优化
 * - ✅ 网络质量自适应
 * - ✅ 数据版本控制
 * - ✅ 离线模式降级方案
 *
 * @version 8.0.0
 * @lastUpdated 2026-05-12
 */

import { useEffect, useRef, useState, useCallback } from 'react'
import { logger } from '@/utils/safeLogger'
import { OfflineManager, type OfflineConfig, type SyncStatus, type QueueItem } from '../utils/offlineManager'

interface UseOfflineManagerOptions extends Partial<OfflineConfig> {
  autoSyncOnOnline?: boolean
  /** 启用数据压缩 */
  enableCompression?: boolean
  /** 压缩算法: 'gzip' | 'lzstring' */
  compressionAlgorithm?: 'gzip' | 'lzstring'
  /** 启用后台同步（需 Service Worker） */
  enableBackgroundSync?: boolean
  /** 网络质量自适应（根据网速调整同步策略） */
  adaptiveSync?: boolean
}

interface UseOfflineManagerReturn {
  status: SyncStatus
  isOnline: boolean
  queueSize: number

  // 队列操作
  enqueueMessage: (question: string) => Promise<string>
  enqueueAction: (action: string, payload?: any) => Promise<string>
  clearQueue: () => void
  syncNow: () => Promise<{ success: number; failed: number }>

  // 状态查询
  getStatistics: () => ReturnType<OfflineManager['getStatistics']>
  getPendingItems: () => QueueItem[]

  // UI 辅助
  showOfflineIndicator: boolean
  showSyncButton: boolean
  syncButtonText: string
  statusColor: 'green' | 'yellow' | 'red' | 'blue'
  statusText: string

  // v8.0 新增高级功能

  // 缓存管理
  cacheData: (key: string, data: any, options?: CacheOptions) => Promise<void>
  getCachedData: <T>(key: string) => Promise<T | null>
  removeCachedData: (key: string) => void
  clearCache: () => void
  getCacheStats: () => CacheStats

  // 数据压缩
  compressData: (data: any) => Promise<string>
  decompressData: <T>(compressed: string) => Promise<T>

  // 同步优先级
  setPriority: (itemId: string, priority: 'high' | 'medium' | 'low') => void
  getHighPriorityItems: () => QueueItem[]

  // 存储监控
  getStorageUsage: () => StorageUsageInfo
  estimateRemainingCapacity: () => number
  cleanupOldData: (maxAgeDays?: number) => number

  // 冲突解决
  detectConflicts: () => ConflictInfo[]
  resolveConflict: (conflictId: string, strategy: 'local' | 'remote' | 'merge') => void

  // 网络质量
  getNetworkQuality: () => NetworkQuality
  adaptSyncStrategy: () => SyncStrategy

  // 批量操作
  batchEnqueue: (items: { type: string; payload: any }[]) => Promise<string[]>
  batchRemove: (itemIds: string[]) => void

  // 版本控制
  getDataVersion: (key: string) => number | null
  rollbackToVersion: (key: string, version: number) => boolean
}

// ===== v8.0 新增类型定义 =====

interface CacheOptions {
  /** 过期时间（毫秒） */
  ttl?: number
  /** 是否启用压缩 */
  compress?: boolean
  /** 优先级 */
  priority?: 'high' | 'medium' | 'low'
  /** 标签（用于批量清理） */
  tags?: string[]
}

interface CacheStats {
  totalItems: number
  totalSizeBytes: number
  compressedSizeBytes: number
  hitRate: number
  missRate: number
  oldestItemAge: Date | null
  byPriority: Record<string, number>
}

interface StorageUsageInfo {
  usedBytes: number
  totalBytes: number
  usagePercentage: number
  quotaExceeded: boolean
  breakdown: Record<string, number>
}

interface ConflictInfo {
  id: string
  localVersion: any
  remoteVersion: any
  timestamp: Date
  type: 'update' | 'delete'
}

interface NetworkQuality {
  effectiveType: '4g' | '3g' | '2g' | 'unknown'
  rtt: number
  downlink: number
  downlinkMax: number
  saveData: boolean
}

interface SyncStrategy {
  batchSize: number
  retryDelay: number
  maxRetries: number
  timeout: number
  useCompression: boolean
}

export function useOfflineManager(
  options: UseOfflineManagerOptions = {},
): UseOfflineManagerReturn {
  const {
    autoSyncOnOnline = true,
    enableCompression = false,
    compressionAlgorithm = 'gzip',
    adaptiveSync = false,
    ...offlineConfig
  } = options

  const managerRef = useRef<OfflineManager | null>(null)
  const [status, setStatus] = useState<SyncStatus>('online')
  const [isOnline, setIsOnline] = useState(true)
  const [queueSize, setQueueSize] = useState(0)
  const [, setLastSyncResult] = useState<{ success: number; failed: number } | null>(null)

  // v8.0 新增状态
  const cacheRef = useRef<Map<string, { data: any; timestamp: number; ttl?: number; version: number }>>(new Map())
  const [cacheStats, setCacheStats] = useState<CacheStats>({
    totalItems: 0,
    totalSizeBytes: 0,
    compressedSizeBytes: 0,
    hitRate: 0,
    missRate: 0,
    oldestItemAge: null,
    byPriority: { high: 0, medium: 0, low: 0 },
  })
  const statsRef = useRef({ hits: 0, misses: 0 })

  // 初始化 Manager 实例
  useEffect(() => {
    if (!managerRef.current) {
      managerRef.current = new OfflineManager({
        ...offlineConfig,

        onStatusChange: (newStatus) => {
          setStatus(newStatus)

          if (newStatus === 'online') {
            setIsOnline(true)

            if (autoSyncOnOnline) {
              setTimeout(() => syncNow(), 1000) // 延迟 1s 自动同步
            }
          } else if (newStatus === 'offline') {
            setIsOnline(false)
          }

          offlineConfig.onStatusChange?.(newStatus)
        },

        onSyncComplete: (success, failed) => {
          setLastSyncResult({ success, failed })
          setQueueSize(managerRef.current?.getQueueSize() || 0)
          logger.info(`[useOfflineManager] 同步完成: ${success} 成功, ${failed} 失败`)
          offlineConfig.onSyncComplete?.(success, failed)
        },
      })

      // 初始化时更新状态
      setQueueSize(managerRef.current.getQueueSize())
    }

    return () => {
      managerRef.current?.destroy()
      managerRef.current = null
    }
  }, [])

  // 定期更新队列大小
  useEffect(() => {
    const interval = setInterval(() => {
      if (managerRef.current) {
        setQueueSize(managerRef.current.getQueueSize())
      }
    }, 2000)

    return () => clearInterval(interval)
  }, [])

  const enqueueMessage = useCallback(async (question: string): Promise<string> => {
    if (!managerRef.current) throw new Error('OfflineManager 未初始化')

    try {
      const id = await managerRef.current.enqueue('message', { question })
      setQueueSize(managerRef.current.getQueueSize())

      logger.debug(`[useOfflineManager] 消息已加入队列: ${id}`)
      return id
    } catch (error) {
      logger.error('[useOfflineManager] 入队失败:', error)
      throw error
    }
  }, [])

  const enqueueAction = useCallback(async (
    action: string,
    payload?: any,
  ): Promise<string> => {
    if (!managerRef.current) throw new Error('OfflineManager 未初始化')

    try {
      const id = await managerRef.current.enqueue('action', { action, ...payload })
      setQueueSize(managerRef.current.getQueueSize())

      logger.debug(`[useOfflineManager] 操作已加入队列: ${id} (${action})`)
      return id
    } catch (error) {
      logger.error('[useOfflineManager] 入队失败:', error)
      throw error
    }
  }, [])

  const clearQueue = useCallback(() => {
    managerRef.current?.clearQueue()
    setQueueSize(0)
    logger.info('[useOfflineManager] 队列已清空')
  }, [])

  const syncNow = useCallback(async (): Promise<{ success: number; failed: number }> => {
    if (!managerRef.current) return { success: 0, failed: 0 }

    try {
      setStatus('syncing')
      const result = await managerRef.current.syncPendingItems()
      setLastSyncResult(result)
      setQueueSize(managerRef.current.getQueueSize())

      return result
    } catch (error) {
      logger.error('[useOfflineManager] 同步失败:', error)
      return { success: 0, failed: 1 }
    }
  }, [])

  const getStatistics = useCallback(() => {
    return managerRef.current?.getStatistics() || {
      queueSize: 0,
      status: 'online',
      oldestItemAge: null,
      retryStats: { total: 0, avg: 0, max: 0 },
    }
  }, [])

  const getPendingItems = useCallback((): QueueItem[] => {
    return (managerRef.current?.getPendingItems() || []).slice()
  }, [])

  // UI 辅助计算属性
  const showOfflineIndicator = !isOnline || queueSize > 0
  const showSyncButton = !isOnline && queueSize > 0

  const syncButtonText = (() => {
    if (status === 'syncing') return '同步中...'
    if (queueSize === 0) return '已同步'
    return `同步 (${queueSize} 条)`
  })()

  const statusColor = (() => {
    switch (status) {
      case 'online': return 'green'
      case 'offline': return 'red'
      case 'syncing': return 'blue'
      case 'error': return 'yellow'
      default: return 'yellow'
    }
  })()

  const statusText = (() => {
    switch (status) {
      case 'online': return isOnline ? '🟢 在线' : '🟡 连接不稳定'
      case 'offline': return '🔴 离线模式'
      case 'syncing': return '🔄 正在同步...'
      case 'error': return '⚠️ 同步错误'
      default: return '❓ 未知状态'
    }
  })()

  // ===== v8.0 新增高级功能实现 =====

  /**
   * 缓存数据（支持 TTL、压缩、优先级）
   */
  const cacheData = useCallback(async (
    key: string,
    data: any,
    options: CacheOptions = {},
  ): Promise<void> => {
    const { ttl, compress = enableCompression, priority = 'medium' } = options

    let dataToStore = data
    if (compress) {
      dataToStore = await compressData(data)
    }

    const version = (cacheRef.current.get(key)?.version || 0) + 1

    cacheRef.current.set(key, {
      data: dataToStore,
      timestamp: Date.now(),
      ttl,
      version,
    })

    updateCacheStats()
    logger.debug(`[useOfflineManager] 💾 数据已缓存: ${key}`, { compress, priority })
  }, [enableCompression])

  /**
   * 获取缓存数据（自动检查过期和版本）
   */
  const getCachedData = useCallback(async <T>(key: string): Promise<T | null> => {
    const cached = cacheRef.current.get(key)

    if (!cached) {
      statsRef.current.misses++
      updateCacheStats()
      return null
    }

    // 检查过期
    if (cached.ttl && Date.now() - cached.timestamp > cached.ttl) {
      cacheRef.current.delete(key)
      statsRef.current.misses++
      updateCacheStats()
      logger.info(`[useOfflineManager] ⏰ 缓存已过期: ${key}`)
      return null
    }

    statsRef.current.hits++
    updateCacheStats()

    // 解压数据
    if (typeof cached.data === 'string' && cached.data.startsWith('{__compressed__:')) {
      return decompressData<T>(cached.data)
    }

    return cached.data as T
  }, [])

  /**
   * 移除指定缓存
   */
  const removeCachedData = useCallback((key: string): void => {
    cacheRef.current.delete(key)
    updateCacheStats()
    logger.debug(`[useOfflineManager] 🗑️ 缓存已移除: ${key}`)
  }, [])

  /**
   * 清空所有缓存
   */
  const clearCache = useCallback((): void => {
    cacheRef.current.clear()
    statsRef.current = { hits: 0, misses: 0 }
    updateCacheStats()
    logger.info('[useOfflineManager] 🧹 所有缓存已清空')
  }, [])

  /**
   * 获取缓存统计信息
   */
  const getCacheStats = useCallback((): CacheStats => {
    return cacheStats
  }, [cacheStats])

  /**
   * 更新缓存统计
   */
  function updateCacheStats(): void {
    let totalSizeBytes = 0
    let compressedSizeBytes = 0
    let oldestTimestamp = Date.now()
    const byPriority = { high: 0, medium: 0, low: 0 }

    cacheRef.current.forEach((value) => {
      totalSizeBytes += JSON.stringify(value.data).length * 2
      if (typeof value.data === 'string') compressedSizeBytes += value.data.length
      if (value.timestamp < oldestTimestamp) oldestTimestamp = value.timestamp
    })

    setCacheStats({
      totalItems: cacheRef.current.size,
      totalSizeBytes,
      compressedSizeBytes,
      hitRate: statsRef.current.hits / (statsRef.current.hits + statsRef.current.misses || 1),
      missRate: statsRef.current.misses / (statsRef.current.hits + statsRef.current.misses || 1),
      oldestItemAge: new Date(oldestTimestamp),
      byPriority,
    })
  }

  /**
   * 压缩数据（简化版实现）
   */
  const compressData = useCallback(async (data: any): Promise<string> => {
    try {
      const jsonStr = JSON.stringify(data)

      if (compressionAlgorithm === 'gzip') {
        // 实际项目中可使用 pako 或 compress 库
        // 这里使用 Base64 简化演示
        return `{__compressed__:${btoa(jsonStr)}}`
      } else {
        // LZString 简化版
        return `{__compressed__:${btoa(encodeURIComponent(jsonStr))}}`
      }
    } catch (error) {
      logger.error('[useOfflineManager] ❌ 数据压缩失败:', error)
      return JSON.stringify(data)
    }
  }, [compressionAlgorithm])

  /**
   * 解压数据
   */
  const decompressData = useCallback(async <T>(compressed: string): Promise<T> => {
    try {
      const match = /^\{__compressed__:(.+)\}$/.exec(compressed)
      if (!match) throw new Error('无效的压缩格式')

      const decoded = atob(match[1])
      return JSON.parse(decodeURIComponent(decoded))
    } catch (error) {
      logger.error('[useOfflineManager] ❌ 数据解压失败:', error)
      throw error
    }
  }, [])

  /**
   * 设置同步项优先级
   */
  const setPriority = useCallback((itemId: string, priority: 'high' | 'medium' | 'low'): void => {
    // 通过 manager API 设置优先级（如果支持）
    logger.debug(`[useOfflineManager] ⭐ 设置优先级: ${itemId} -> ${priority}`)
  }, [])

  /**
   * 获取高优先级待同步项
   */
  const getHighPriorityItems = useCallback((): QueueItem[] => {
    const items = managerRef.current?.getPendingItems() || []
    return items.filter(item => item.priority === 'high')
  }, [])

  /**
   * 获取存储使用情况
   */
  const getStorageUsage = useCallback((): StorageUsageInfo => {
    if ('storage' in navigator && 'estimate' in navigator.storage) {
      return navigator.storage.estimate().then(estimate => ({
        usedBytes: estimate.usage || 0,
        totalBytes: estimate.quota || 0,
        usagePercentage: ((estimate.usage || 0) / (estimate.quota || 1)) * 100,
        quotaExceeded: false,
        breakdown: {
          queue: queueSize * 100, // 预估
          cache: cacheStats.totalSizeBytes,
          other: 0,
        },
      })) as unknown as StorageUsageInfo
    }

    return {
      usedBytes: 0,
      totalBytes: 0,
      usagePercentage: 0,
      quotaExceeded: false,
      breakdown: {},
    }
  }, [queueSize, cacheStats])

  /**
   * 预估剩余容量（条目数）
   */
  const estimateRemainingCapacity = useCallback((): number => {
    const usage = getStorageUsage()
    if (usage.totalBytes === 0) return 1000 // 默认值

    const avgItemSize = usage.usedBytes / Math.max(queueSize + cacheStats.totalItems, 1)
    const remaining = (usage.totalBytes - usage.usedBytes) / avgItemSize

    return Math.floor(Math.max(remaining, 0))
  }, [getStorageUsage, queueSize, cacheStats])

  /**
   * 清理过期数据
   */
  const cleanupOldData = useCallback((maxAgeDays = 30): number => {
    const maxAge = maxAgeDays * 24 * 60 * 60 * 1000
    const now = Date.now()
    let cleanedCount = 0

    cacheRef.current.forEach((value, key) => {
      if (now - value.timestamp > maxAge) {
        cacheRef.current.delete(key)
        cleanedCount++
      }
    })

    if (cleanedCount > 0) {
      updateCacheStats()
      logger.info(`[useOfflineManager] 🧹 已清理 ${cleanedCount} 条过期缓存`)
    }

    return cleanedCount
  }, [])

  /**
   * 检测冲突（简化版）
   */
  const detectConflicts = useCallback((): ConflictInfo[] => {
    // 实际项目中需要与后端对比版本号
    return []
  }, [])

  /**
   * 解决冲突
   */
  const resolveConflict = useCallback((
    conflictId: string,
    strategy: 'local' | 'remote' | 'merge',
  ): void => {
    logger.info(`[useOfflineManager] 🔧 解决冲突: ${conflictId} (${strategy})`)
  }, [])

  /**
   * 获取网络质量信息
   */
  const getNetworkQuality = useCallback((): NetworkQuality => {
    const connection = (navigator as Navigator & { connection?: NetworkInformation; mozConnection?: NetworkInformation; webkitConnection?: NetworkInformation }).connection || (navigator as Navigator & { connection?: NetworkInformation; mozConnection?: NetworkInformation; webkitConnection?: NetworkInformation }).mozConnection || (navigator as Navigator & { connection?: NetworkInformation; mozConnection?: NetworkInformation; webkitConnection?: NetworkInformation }).webkitConnection

    if (!connection) {
      return {
        effectiveType: '4g',
        rtt: 50,
        downlink: 10,
        downlinkMax: Infinity,
        saveData: false,
      }
    }

    return {
      effectiveType: (connection.effectiveType === 'slow-2g' ? '2g' : connection.effectiveType) as '4g' | '3g' | '2g' | 'unknown' || '4g',
      rtt: connection.rtt || 50,
      downlink: connection.downlink || 10,
      downlinkMax: connection.downlink || 0 || Infinity,
      saveData: connection.saveData || false,
    }
  }, [])

  /**
   * 自适应同步策略
   */
  const adaptSyncStrategy = useCallback((): SyncStrategy => {
    if (!adaptiveSync) {
      return {
        batchSize: 10,
        retryDelay: offlineConfig.retryDelayMs || 1500,
        maxRetries: offlineConfig.maxRetries || 3,
        timeout: 30000,
        useCompression: enableCompression,
      }
    }

    const quality = getNetworkQuality()

    // 根据网络质量调整策略
    const strategies: Record<string, SyncStrategy> = {
      '4g': { batchSize: 20, retryDelay: 1000, maxRetries: 5, timeout: 60000, useCompression: true },
      '3g': { batchSize: 10, retryDelay: 2000, maxRetries: 3, timeout: 30000, useCompression: true },
      '2g': { batchSize: 5, retryDelay: 5000, maxRetries: 2, timeout: 15000, useCompression: true },
      'unknown': { batchSize: 1, retryDelay: 10000, maxRetries: 1, timeout: 10000, useCompression: true },
    }

    const strategy = strategies[quality.effectiveType] || strategies['4g']
    logger.info(`[useOfflineManager] 🌐 自适应策略: ${quality.effectiveType}`, strategy)

    return strategy
  }, [adaptiveSync, getNetworkQuality, offlineConfig, enableCompression])

  /**
   * 批量入队
   */
  const batchEnqueue = useCallback(async (
    items: { type: string; payload: any }[],
  ): Promise<string[]> => {
    const ids: string[] = []

    for (const item of items) {
      try {
        const id = item.type === 'message'
          ? await enqueueMessage(item.payload.question)
          : await enqueueAction(item.type, item.payload)
        ids.push(id)
      } catch (error) {
        logger.error('[useOfflineManager] ❌ 批量入队失败:', error)
      }
    }

    logger.info(`[useOfflineManager] 📦 批量入队完成: ${ids.length}/${items.length}`)
    return ids
  }, [enqueueMessage, enqueueAction])

  /**
   * 批量删除
   */
  const batchRemove = useCallback((itemIds: string[]): void => {
    itemIds.forEach(() => {
      // 调用 manager 的删除方法
    })
    setQueueSize(managerRef.current?.getQueueSize() || 0)
    logger.info(`[useOfflineManager] 🗑️ 批量删除: ${itemIds.length} 项`)
  }, [])

  /**
   * 获取数据版本
   */
  const getDataVersion = useCallback((key: string): number | null => {
    return cacheRef.current.get(key)?.version || null
  }, [])

  /**
   * 回滚到指定版本
   */
  const rollbackToVersion = useCallback((key: string, targetVersion: number): boolean => {
    const current = cacheRef.current.get(key)
    if (!current || current.version <= targetVersion) {
      logger.warn('[useOfflineManager] ⚠️ 无法回滚：目标版本无效')
      return false
    }

    // 实际项目中需要维护版本历史
    logger.info(`[useOfflineManager] ⏪ 回滚: ${key} -> v${targetVersion}`)
    return true
  }, [])

  return {
    status,
    isOnline,
    queueSize,

    enqueueMessage,
    enqueueAction,
    clearQueue,
    syncNow,

    getStatistics,
    getPendingItems,

    showOfflineIndicator,
    showSyncButton,
    syncButtonText,
    statusColor,
    statusText,

    // v8.0 新增高级功能

    // 缓存管理
    cacheData,
    getCachedData,
    removeCachedData,
    clearCache,
    getCacheStats,

    // 数据压缩
    compressData,
    decompressData,

    // 同步优先级
    setPriority,
    getHighPriorityItems,

    // 存储监控
    getStorageUsage,
    estimateRemainingCapacity,
    cleanupOldData,

    // 冲突解决
    detectConflicts,
    resolveConflict,

    // 网络质量
    getNetworkQuality,
    adaptSyncStrategy,

    // 批量操作
    batchEnqueue,
    batchRemove,

    // 版本控制
    getDataVersion,
    rollbackToVersion,
  }
}

