export function useUnifiedAgent(options: UseUnifiedAgentOptions = {}): UseUnifiedAgentReturn {
  const {
    initialWorkflowType = 'formula_design',
    onComplete,
    onError,
  } = options;

  // ── 核心状态 ─────────────────────────────────────────────
  const [messages, setMessages] = useState<AgentMessage[]>([]);
  const [tools, setTools] = useState<ToolCall[]>([]);
  const [stages, setStages] = useState<ExecutionStage[]>([]);
  const [isRunning, setIsRunning] = useState(false);
  const [executedCount, setExecutedCount] = useState(0);
  const [workflowType, setWorkflowType] = useState(initialWorkflowType);
  const [availableTools, setAvailableTools] = useState<AgentTool[]>([]);
  const [workflowTemplates, setWorkflowTemplates] = useState<import('@/api/deep_dev').WorkflowTemplate[]>(DEFAULT_WORKFLOW_TEMPLATES);
  const [currentTurn, setCurrentTurn] = useState<TurnState | null>(null);
  const [turnHistory, setTurnHistory] = useState<TurnState[]>([]);
  const [tokenCount, setTokenCount] = useState(0);

  // ── 引用 ──────────────────────────────────────────────────
  const sessionRef = useRef<EventSourcedSession | null>(null);
  const emitterRef = useRef<ReturnType<typeof getWaterfallEmitter> | null>(null);
  const turnIdRef = useRef<string>('');

  // ── 初始化 ────────────────────────────────────────────────
  useEffect(() => {
    const session = new EventSourcedSession();
    session.open().catch((err) => logger.error('[useUnifiedAgent] Failed to open session:', err));
    sessionRef.current = session;

    const emitter = getWaterfallEmitter();
    emitterRef.current = emitter;

    // 注册 pre-step 监听器 (输入验证)
    const offPreStep = emitter.on('agent/pre-step', async (data, next) => {
      const { input } = data as { input: string; turnId: string };

      // 输入验证
      if (!input || input.trim().length === 0) {
        logger.warn('[useUnifiedAgent] Empty input, rejecting turn');
        return; // 不调用 next()，turn 以空 step 关闭
      }

      // 输入长度检查
      if (input.length > MAX_INPUT_LENGTH) {
        data.input = input.slice(0, MAX_INPUT_LENGTH) + '...[truncated]';
        logger.warn('[useUnifiedAgent] Input truncated to max length');
      }

      // 敏感信息过滤
      data.input = filterSensitiveData(input);

      // Compaction 检查
      const session = sessionRef.current;
      if (session) {
        const decision = checkCompactionTrigger(session, COMPACTION_MAX_TOKENS);
        if (decision.trigger && decision.canCompact) {
          logger.info(`[useUnifiedAgent] Pre-step compaction check: ${decision.trigger}`);
        }
      }

      next();
    });

    // 注册 request-error 监听器 (增强版)
    const offRequestError = emitter.on('agent/request-error', async (data, next) => {
      const { error, turnId, stepId } = data as {
        error: unknown;
        turnId: string;
        stepId: string;
      };

      const normalized = normalizeError(error);
      logger.warn(`[useUnifiedAgent] Request error in turn ${turnId}:`, normalized);

      switch (normalized.code) {
        case 'EMPTY_RESPONSE':
          logger.info('[useUnifiedAgent] Empty response, will retry');
          await sleep(1000);
          // 重试逻辑由调用方处理
          return;

        case 'CONTEXT_WINDOW_EXCEEDED':
          logger.info('[useUnifiedAgent] Context window exceeded, triggering compaction');
          try {
            await doCompaction();
            // 压缩后重试
            await executeStep(turnId, stepId);
            return;
          } catch (compactionErr) {
            logger.error('[useUnifiedAgent] Compaction failed:', compactionErr);
            next();
            return;
          }

        case 'RATE_LIMITED':
          logger.info('[useUnifiedAgent] Rate limited, waiting');
          await sleep(5000);
          await executeStep(turnId, stepId);
          return;

        case 'INVALID_AUTH':
          logger.error('[useUnifiedAgent] Invalid auth, aborting');
          next();
          return;

        default:
          next();
      }
    });

    // 注册 turn-stopping 监听器
    const offTurnStopping = emitter.onSerial('agent/turn-stopping', (data) => {
      logger.info(`[useUnifiedAgent] Turn stopping: ${data.turnId}, reason=${data.reason}`);
    });

    return () => {
      offPreStep();
      offRequestError();
      offTurnStopping();
      session.close();
      emitter.setEnabled(false);
    };
  }, []);

  // ── 工具函数 ──────────────────────────────────────────────
  const sleep = (ms: number): Promise<void> => {
    return new Promise(resolve => setTimeout(resolve, ms));
  };

  const normalizeError = (error: unknown) => {
    if (error instanceof Error) {
      const msg = error.message.toLowerCase();
      if (msg.includes('context') || msg.includes('too long') || msg.includes('maximum')) {
        return { message: error.message, code: 'CONTEXT_WINDOW_EXCEEDED', retryable: false };
      }
      if (msg.includes('empty') || msg.includes('no response') || msg.includes('invalid')) {
        return { message: error.message, code: 'EMPTY_RESPONSE', retryable: true };
      }
      if (msg.includes('timeout')) {
        return { message: error.message, code: 'TIMEOUT', retryable: true };
      }
      if (msg.includes('429') || msg.includes('rate limit')) {
        return { message: error.message, code: 'RATE_LIMITED', retryable: true };
      }
      if (msg.includes('401') || msg.includes('auth') || msg.includes('unauthorized')) {
        return { message: error.message, code: 'INVALID_AUTH', retryable: false };
      }
      if (msg.includes('network') || msg.includes('fetch') || msg.includes('failed')) {
        return { message: error.message, code: 'NETWORK_ERROR', retryable: true };
      }
    }
    return { message: String(error), code: 'UNKNOWN_ERROR', retryable: false };
  };

  const filterSensitiveData = (input: string): string => {
    // 简单的敏感信息过滤
    return input
      .replace(/(\d{4})\s*(\d{4})\s*(\d{4})\s*(\d{4})/g, '$1**** **** $4')
      .replace(/\b\d{17,19}\b/g, '***')
      .replace(/[\u4e00-\u9fa5]{2,4}(?:身份证|护照|银行卡)\s*[:：]?\s*\S+/g, '$1***');
  };

  // ── 加载工具列表 ─────────────────────────────────────────
  const loadTools = useCallback(async () => {
    try {
      const res = await agentApi.listTools();
      setAvailableTools(res.tools || []);
    } catch (err) {
      logger.warn('[useUnifiedAgent] Failed to load tools, using defaults:', err);
    }
  }, []);

  // ── 加载工作流模板 ───────────────────────────────────────
  const reloadTemplates = useCallback(async () => {
    try {
      const res = await workflowApi.listTemplates();
      setWorkflowTemplates(
        (res.items || []).map((t) => ({
          template_id: t.template_id,
          id: t.id,
          name: t.name,
          label: t.name,
          description: t.description ?? undefined,
          category: t.category ?? '',
          icon: t.icon ?? undefined,
          node_count: t.node_count ?? undefined,
          estimated_duration: t.estimated_duration ?? undefined,
          nodes: t.nodes ?? [],
          edges: t.edges ?? [],
          preset_config: t.preset_config ?? {},
        }))
      );
    } catch (err) {
      logger.warn('[useUnifiedAgent] Failed to load templates from API:', err);
    }
  }, []);

  useEffect(() => {
    loadTools();
    reloadTemplates();
  }, [loadTools, reloadTemplates]);

  // ── 添加消息 ─────────────────────────────────────────────
  const addMessage = useCallback(
    (role: AgentMessage['role'], content: string, metadata?: Record<string, unknown>) => {
      const msg: AgentMessage = {
        id: `msg-${Date.now()}-${Math.random().toString(36).slice(2)}`,
        role,
        content,
        timestamp: new Date(),
        ...metadata,
      };
      setMessages((prev) => [...prev, msg]);

      const session = sessionRef.current;
      if (session) {
        session.append(
          role === 'user' ? 'user/message' : 'assistant/message',
          { content, id: msg.id, metadata }
        ).catch((err) => logger.error('[useUnifiedAgent] Failed to persist message:', err));
      }

      return msg;
    },
    []
  );

  // ── 更新最后一条助手消息 ─────────────────────────────────
  const updateLastAssistantMessage = useCallback(
    (content: string, metadata?: Record<string, unknown>) => {
      setMessages((prev) => {
        const newMsgs = [...prev];
        const lastIdx = newMsgs.length - 1;
        if (lastIdx >= 0 && newMsgs[lastIdx].role === 'assistant') {
          newMsgs[lastIdx] = { ...newMsgs[lastIdx], content, ...metadata };
        }
        return newMsgs;
      });
    },
    []
  );

  // ── 开始新 Turn ──────────────────────────────────────────
  const startTurn = useCallback((input: string, wfType: string): string => {
    const turnId = `turn-${Date.now()}`;
    turnIdRef.current = turnId;
    const turnState: TurnState = {
      turnId,
      status: 'running',
      steps: [],
      startedAt: Date.now(),
      input,
    };
    setCurrentTurn(turnState);

    const session = sessionRef.current;
    if (session) {
      session.append('turn/start', createTurnStartEvent(turnId, input, wfType))
        .catch((err) => logger.error('[useUnifiedAgent] 持久化 turn/start 失败:', err));
    }

    const emitter = emitterRef.current;
    if (emitter) {
      emitter.emit('agent/pre-step', { input, turnId })
        .catch((err) => logger.error('[useUnifiedAgent] 发送 pre-step 事件失败:', err));
    }

    return turnId;
  }, []);

  // ── 添加 Step (前置声明以避免循环依赖) ──────────────────────
  const addStep = useCallback((stepType: StepState['type'], toolName?: string) => {
    const stepId = `step-${Date.now()}-${Math.random().toString(36).slice(2)}`;
    const stepState: StepState = {
      stepId,
      type: stepType,
      status: 'running',
      latencyMs: 0,
      toolName,
      startedAt: Date.now(),
    };
    setCurrentTurn((prev) => {
      if (!prev) return prev;
      return { ...prev, steps: [...prev.steps, stepState] };
    });

    const session = sessionRef.current;
    if (session) {
      session.append('step/start', createStepStartEvent(stepId, stepType, toolName))
        .catch((err) => logger.error('[useUnifiedAgent] 持久化 step/start 失败:', err));
    }

    return stepId;
  }, []);

  // ── 完成 Step (前置声明以避免循环依赖) ──────────────────────
  const completeStep = useCallback(
    (stepId: string, success: boolean, error?: string, result?: unknown) => {
      const latencyMs = Date.now() - (currentTurn?.steps.find((s) => s.stepId === stepId)?.startedAt ?? Date.now());
      setCurrentTurn((prev) => {
        if (!prev) return prev;
        return {
          ...prev,
          steps: prev.steps.map((s) =>
            s.stepId === stepId
              ? { ...s, status: success ? 'success' : 'failed', latencyMs, error, result, completedAt: Date.now() }
              : s
          ),
        };
      });

      const session = sessionRef.current;
      if (session) {
        const stepType = currentTurn?.steps.find((s) => s.stepId === stepId)?.type ?? 'llm_request';
        session.append('step/end', createStepEndEvent(stepId, stepType, latencyMs, success, error))
          .catch((err) => logger.error('[useUnifiedAgent] 持久化 step/end 失败:', err));
      }
    },
    [currentTurn]
  );

  // ── 执行 Step ────────────────────────────────────────────
  const executeStep = useCallback(async (
    turnId: string,
    stepId?: string,
    query?: string
  ): Promise<AgentExecution | null> => {
    const emitter = emitterRef.current;
    const stepId_ = stepId ?? `step-${Date.now()}`;
    // 优先使用传入的 query，回退到 currentTurn.input（React 闭包安全）
    const effectiveQuery = query || currentTurn?.input || '';

    if (!effectiveQuery) {
      logger.warn('[executeStep] Empty query, skipping');
      completeStep(stepId_, true);
      return null;
    }

    // 触发 request 事件
    await emitter?.emit('agent/request', { turnId, model: 'deepseek-chat' }).catch(() => {});

    // 执行 Step (使用真实 LLM Adapter)
    try {
      const res = await agentApi.execute({ query: effectiveQuery, mode: 'smart', max_steps: 8 });
      const execution = res.data;
      // 保存执行结果，供 UI 展示工具调用详情
      completeStep(stepId_, true, undefined, execution);
      return execution;
    } catch (err) {
      logger.error('[executeStep] Execution error:', err);
      completeStep(stepId_, false, err instanceof Error ? err.message : String(err));
      return null;
    }
  }, [completeStep, currentTurn]);

  // ── 结束 Turn ────────────────────────────────────────────
  const endTurn = useCallback(
    (turnId: string, reason: 'completed' | 'cancelled' | 'timeout' = 'completed') => {
      const durationMs = Date.now() - (currentTurn?.startedAt ?? Date.now());
      setCurrentTurn(null);

      const session = sessionRef.current;
      if (session) {
        session.append('turn/end', createTurnEndEvent(turnId, durationMs, reason))
          .catch((err) => logger.error('[useUnifiedAgent] 持久化 turn/end 失败:', err));
      }

      const emitter = emitterRef.current;
      if (emitter) {
        emitter.emitSerial('agent/turn-stopping', { turnId, reason })
          .catch((err) => logger.error('[useUnifiedAgent] 发送 turn-stopping 事件失败:', err));
      }

      if (currentTurn) {
        setTurnHistory((prev) => [...prev, { ...currentTurn, completedAt: Date.now() }]);
      }
    },
    [currentTurn]
  );

  // ── 执行工具调用 (有界并行) ────────────────────────────────
  const executeToolCalls = useCallback(
    async (calls: ToolCall[]): Promise<ToolCall[]> => {
      const emitter = emitterRef.current;

      await emitter?.emit('tools/pre-execute', { toolCalls: calls });

      const results = await scheduleToolCalls(calls, MAX_PARALLEL_TOOLS);

      const updatedCalls: ToolCall[] = calls.map((call, idx) => {
        const result = results[idx];
        return {
          ...call,
          status: result?.error ? 'failed' : 'success',
          latencyMs: result?.latencyMs ?? call.latencyMs,
          output: result?.result as Record<string, unknown>,
          error: result?.error,
        };
      });

      await emitter?.emit('tools/post-execute', { results });

      setTools(updatedCalls);
      return updatedCalls;
    },
    []
  );

  // ── Compaction ───────────────────────────────────────────
  const doCompaction = useCallback(async (): Promise<boolean> => {
    const session = sessionRef.current;
    if (!session) return false;

    const decision = checkCompactionTrigger(session, COMPACTION_MAX_TOKENS);
    if (!decision.trigger) return false;

    const lock = await tryAcquireCompactionLock(null);
    if (!lock) {
      logger.warn('[useUnifiedAgent] Could not acquire compaction lock');
      return false;
    }

    try {
      logger.info(`[useUnifiedAgent] Compaction triggered: ${decision.trigger}`);

      const allMessages = session.deriveMessages();
      const keepCount = Math.max(10, Math.floor(allMessages.length * 0.2));
      const remaining = allMessages.slice(-keepCount);

      const summary: AgentMessage = {
        id: `msg-compact-${Date.now()}`,
        role: 'assistant',
        content: `[上下文已压缩] 保留最近 ${remaining.length} 条消息，压缩了 ${allMessages.length - remaining.length} 条历史消息。`,
        timestamp: new Date(),
      };

      setMessages([summary, ...remaining]);
      setTokenCount(tokenEstimator.estimate([summary, ...remaining]));

      if (session.seq > keepCount + 5) {
        const toReplaceFrom = Math.max(0, session.seq - keepCount - 10);
        const replacementEvents: any[] = [{
          seq: 0,
          type: 'assistant/message',
          data: { content: summary.content, id: summary.id },
          timestamp: Date.now(),
        }];
        for (const msg of remaining) {
          replacementEvents.push({
            seq: replacementEvents.length,
            type: msg.role === 'user' ? 'user/message' : 'assistant/message',
            data: { content: msg.content, id: msg.id },
            timestamp: msg.timestamp.getTime(),
          });
        }
        await session.replaceEvents(toReplaceFrom, session.seq, replacementEvents);
      }

      // 使消息缓存失效
      session.invalidateMessageCache();

      return true;
    } finally {
      releaseCompactionLock(lock.compactionId, 'completed');
    }
  }, []);

  // ── 核心执行方法 ─────────────────────────────────────────
  const execute = useCallback(
    async (query: string, workflowTypeParam?: string): Promise<void> => {
      if (!query.trim() || isRunning) return;

      const wfType = workflowTypeParam || workflowType;
      setIsRunning(true);
      setTools([]);
      setStages([]);

      addMessage('user', query);

      const session = sessionRef.current;
      if (session) {
        const decision = checkCompactionTrigger(session, COMPACTION_MAX_TOKENS);
        if (decision.trigger) {
          await doCompaction();
        }
        setTokenCount(session.estimateTokenCount());
      }

      const turnId = startTurn(query, wfType);
      addMessage('assistant', '', { executionId: turnId, workflowType: wfType });

      try {
        const emitter = emitterRef.current;
        await emitter?.emit('agent/request', { turnId, model: 'deepseek-chat' }).catch(() => {});

        // 尝试工作流执行（优先路径）
        let result: AgentExecution | WorkflowExecution | null = null;
        let workflowSucceeded = false;

        try {
          const wfRes = await workflowApi.execute(wfType, { query, max_steps: 8 });
          result = wfRes.data;
          workflowSucceeded = true;

          if ('stages' in result) {
            setStages(result.stages.map((s) => ({
              stage: s.stage,
              success: s.success,
              latencyMs: s.latency_ms,
              error: s.error,
            })));
          }
        } catch (wfErr) {
          logger.info('Workflow execution failed, fallback to smart mode:', wfErr);
        }

        // 工作流失败时使用 smart 模式（含 LLM 调用）
        if (!workflowSucceeded) {
          const stepId = addStep('llm_request');
          const exec = await executeStep(turnId, stepId, query);

          // 将 smart 模式的工具调用结果呈现给 UI，避免详情丢失
          if (exec && 'steps' in exec && exec.steps.length > 0) {
            result = exec;
            const toolCalls: ToolCall[] = exec.steps.map((s) => ({
              tool: s.tool,
              status: (s.status === 'success' ? 'success' : s.status === 'failed' ? 'failed' : 'running') as ToolCall['status'],
              latencyMs: s.latency_ms || 0,
              error: s.error,
              isConcurrencySafe: true,
            }));
 await executeToolCalls(toolCalls);
          }
        } else {
          // 工作流成功时补全 final-response step
          addStep('final_response');
        }

        // 若工作流成功但未获取到 result（异常），降级到 smart 模式
        if (!result) {
          const smartRes = await agentApi.execute({ query, mode: 'smart', max_steps: 5 });
          result = smartRes.data;

          if ('steps' in result) {
            const toolCalls: ToolCall[] = result.steps.map((s) => ({
              tool: s.tool,
              status: (s.status === 'success' ? 'success' : s.status === 'failed' ? 'failed' : 'running') as ToolCall['status'],
              latencyMs: s.latency_ms || 0,
              error: s.error,
              isConcurrencySafe: true,
            }));
            await executeToolCalls(toolCalls);
          }
        }

        const finalContent = ('final_response' in result && result.final_response
          ? result.final_response
          : ('final_response_preview' in result
            ? result.final_response_preview
            : '')) || '执行完成';

        updateLastAssistantMessage(finalContent, { executionId: turnId });
        completeStep('final-response', true, undefined, finalContent);

        setExecutedCount((c) => c + 1);
        onComplete?.(undefined);

        if (session) setTokenCount(session.estimateTokenCount());

        endTurn(turnId, 'completed');
      } catch (err) {
        logger.error('[useUnifiedAgent] Execution failed:', err);
        const errorMsg = err instanceof Error ? err.message : String(err);
        updateLastAssistantMessage(`执行失败：${errorMsg}`);
        completeStep('final-response', false, errorMsg);
        onError?.(err instanceof Error ? err : new Error(String(err)));
        endTurn(turnId, 'cancelled');
      } finally {
        setIsRunning(false);
      }
    },
    [
      isRunning, workflowType, addMessage, updateLastAssistantMessage,
      startTurn, endTurn, completeStep, executeToolCalls, doCompaction,
      onComplete, onError, addStep, executeStep,
    ]
  );

  const sendMessage = useCallback(async (content: string): Promise<void> => {
    await execute(content);
  }, [execute]);

  const clearMessages = useCallback(async () => {
    setMessages([]);
    setTools([]);
    setStages([]);
    setExecutedCount(0);
    setCurrentTurn(null);
    setTurnHistory([]);
    setTokenCount(0);

    const session = sessionRef.current;
    if (session) await session.clear();
  }, []);

  return {
    messages,
    tools,
    stages,
    isRunning,
    executedCount,
    workflowType,
    availableTools,
    workflowTemplates,
    currentTurn,
    turnHistory,
    tokenCount,
    setWorkflowType,
    sendMessage,
    clearMessages,
    reloadTemplates,
    execute,
  };
}

/**
 * EventBusV2 — 可拦截的水落式事件总线
 *
 * 参照 DeepSeek Harness Waterfall Events 设计：
 * - pipe() 注册拦截管道（handler → next()）
 * - emit() 执行所有拦截器后分发
 * - 保持与旧版 eventBus 的向后兼容
 *
 * @version 2.0.0
 */

import { logger } from '@/utils/safeLogger'
import type { EventType, EventPayloadMap, EventHandler, UnsubscribeFn } from './eventBus'

export type PipeHandler<T> = (payload: T, next: () => Promise<void>) => Promise<void> | void

export class EventBusV2<TEvents extends Record<string, any>> {
  private subscribers = new Map<keyof TEvents, EventHandler<any>[]>
  private pipes = new Map<keyof TEvents, PipeHandler<any>[]>
  private emitHistory: Array<{ event: string; timestamp: number; payload: unknown }> = []
  private readonly MAX_HISTORY_SIZE = 100

  /**
   * 发射事件（执行所有拦截管道后，再分发到订阅者）
   */
  async emit<K extends keyof TEvents>(event: K, payload: TEvents[K]): Promise<void> {
    // 1. 执行所有 pipe 拦截器
    const handlers = this.pipes.get(event)
    if (handlers && handlers.length > 0) {
      let index = 0
      const executeNext = async (): Promise<void> => {
        if (index >= handlers.length) return
        const handler = handlers[index++]
        await handler(payload as Record<string, unknown>, executeNext)
      }
      await executeNext()
    }

    // 2. 执行原有 subscribe 逻辑（向后兼容）
    this.simpleEmit(event as string, payload)

    // 3. 记录历史
    this.recordEmit(event as string, payload)
  }

  /**
   * 注册拦截管道（水落式拦截）
   * @param event 事件名
   * @param handlers 拦截处理器（按注册顺序执行）
   */
  pipe<K extends keyof TEvents>(event: K, ...handlers: PipeHandler<TEvents[K]>[]): void {
    const key = event as string
    if (!this.pipes.has(key)) {
      this.pipes.set(key, [])
    }
    this.pipes.get(key)!.push(...handlers as PipeHandler<any>[])
    logger.debug(`[EventBusV2] pipe 注册: ${key} (${handlers.length} 个处理器)`)
  }

  /**
   * 订阅事件（向后兼容）
   */
  subscribe<K extends keyof TEvents>(event: K, handler: EventHandler<TEvents[K]>): UnsubscribeFn {
    const key = event as string
    if (!this.subscribers.has(key)) {
      this.subscribers.set(key, [])
    }
    this.subscribers.get(key)!.push(handler as EventHandler<any>)

    logger.debug(`[EventBusV2] subscribe: ${key}`)
    return () => this.unsubscribe(key, handler)
  }

  /**
   * 一次性订阅
   */
  once<K extends keyof TEvents>(event: K, handler: EventHandler<TEvents[K]>): UnsubscribeFn {
    const key = event as string
    const wrapper: EventHandler<TEvents[K]> = (payload) => {
      handler(payload)
      this.unsubscribe(key, wrapper)
    }
    return this.subscribe(event, wrapper)
  }

  /**
   * 清除所有订阅和管道
   */
  clear(): void {
    const totalSubs = this.getTotalSubscriberCount()
    this.subscribers.clear()
    this.pipes.clear()
    this.emitHistory = []
    logger.info(`[EventBusV2] 清理所有订阅和管道 (共移除 ${totalSubs} 个订阅者)`)
  }

  /**
   * 清除指定事件的订阅
   */
  clearEvent<K extends keyof TEvents>(event: K): void {
    const key = event as string
    const count = this.subscribers.get(key)?.length ?? 0
    this.subscribers.delete(key)
    this.pipes.delete(key)
    logger.info(`[EventBusV2] 清理事件 "${key}" 的订阅 (共移除 ${count} 个)`)
  }

  /**
   * 获取订阅者数量
   */
  getSubscriberCount(event?: keyof TEvents): number {
    if (event) {
      return this.subscribers.get(event as string)?.length ?? 0
    }
    let count = 0
    this.subscribers.forEach(entries => { count += entries.length })
    return count
  }

  /**
   * 检查是否有订阅者
   */
  hasSubscribers<K extends keyof TEvents>(event: K): boolean {
    return !!this.subscribers.get(event as string)?.length
  }

  /**
   * 获取事件历史
   */
  getEmitHistory(): Array<{ event: string; timestamp: number; payload: unknown }> {
    return [...this.emitHistory]
  }

  // ===== 私有方法 =====

  private simpleEmit(event: string, payload: unknown): void {
    const entries = this.subscribers.get(event)
    if (!entries || entries.length === 0) {
      logger.debug(`[EventBusV2] 事件 "${event}" 无订阅者`)
      return
    }

    entries.forEach((handler, index) => {
      try {
        handler(payload)
      } catch (error) {
        logger.error(`[EventBusV2] 订阅者执行异常 [事件: ${event}, 索引: ${index}]:`, error)
      }
    })
  }

  private unsubscribe(event: string, handler: EventHandler<any>): void {
    const entries = this.subscribers.get(event)
    if (!entries) return
    const index = entries.indexOf(handler)
    if (index > -1) entries.splice(index, 1)
    if (entries.length === 0) this.subscribers.delete(event)
  }

  private getTotalSubscriberCount(): number {
    let count = 0
    this.subscribers.forEach(entries => { count += entries.length })
    return count
  }

  private recordEmit(event: string, payload: unknown): void {
    this.emitHistory.push({ event, timestamp: Date.now(), payload })
    if (this.emitHistory.length > this.MAX_HISTORY_SIZE) {
      this.emitHistory.shift()
    }
  }
}

// 类型化的全局实例
export const eventBusV2 = new EventBusV2<EventPayloadMap>()

// 导出旧的 eventBus 作为兼容层（基于新实现）
export const eventBus = {
  emit: <K extends keyof EventPayloadMap>(event: K, payload: EventPayloadMap[K]) =>
    eventBusV2.emit(event, payload),
  subscribe: <K extends keyof EventPayloadMap>(
    event: K,
    handler: EventHandler<EventPayloadMap[K]>
  ) => eventBusV2.subscribe(event, handler),
  once: <K extends keyof EventPayloadMap>(
    event: K,
    handler: EventHandler<EventPayloadMap[K]>
  ) => eventBusV2.once(event, handler),
  clear: () => eventBusV2.clear(),
  clearEvent: <K extends keyof EventPayloadMap>(event: K) => eventBusV2.clearEvent(event),
  getSubscriberCount: (event?: keyof EventPayloadMap) =>
    eventBusV2.getSubscriberCount(event),
  hasSubscribers: <K extends keyof EventPayloadMap>(event: K) =>
    eventBusV2.hasSubscribers(event),
} as const

export default eventBusV2

/**
 * WaterfallInterceptor — Waterfall 消息拦截链
 *
 * 参照 DeepSeek Harness Waterfall Events 设计：
 * - message:sending 管道：认证检查 → 输入校验 → 自动保存
 * - message:received 管道：自动持久化 → 上下文压缩检查
 * - 每个拦截器可拒绝后续处理器（通过 throw）
 *
 * @version 1.0.0
 */

import { logger } from '@/utils/safeLogger'
import { eventBusV2, type PipeHandler } from './EventBusV2'
import type { EventType, EventPayloadMap } from './eventBus'
import { chatStorageService } from '../capabilities/storage/ChatStorageService'
import { userProfileManager } from './userProfileService'

export interface InterceptorPayload {
  content: string
  timestamp: number
  sessionId?: string
  messageId?: string
}

export interface InterceptorConfig {
  onAuthCheck?: (payload: EventPayloadMap['message:sending']) => boolean | Promise<boolean>
  onValidate?: (payload: EventPayloadMap['message:sending']) => string | null
  onPersistReceived?: (payload: EventPayloadMap['message:received'], sessionId: string) => void
  onAutoSave?: (messages: import('../types').ChatMessage[]) => void
}

let currentSessionId: string | null = null

/**
 * 注册所有 Waterfall 拦截器
 * 应在应用启动时调用一次
 */
export function registerWaterfallInterceptors(config: InterceptorConfig = {}): void {
  logger.info('[WaterfallInterceptor] 注册消息拦截链')

  // ── message:sending 管道 ──
  eventBusV2.pipe('message:sending' as EventType,
    // 1. 认证检查
    async (payload, next) => {
      const hasToken = localStorage.getItem('access_token') || document.cookie.includes('token=')
      if (!hasToken && config.onAuthCheck) {
        const result = await config.onAuthCheck(payload as InterceptorPayload)
        if (!result) {
          logger.warn('[Waterfall] 认证检查失败，中止发送')
          eventBusV2.emit('auth:required' as EventType, {})
          return // 不调用 next()，中断管道
        }
      }
      await next()
    },
    // 2. 输入校验
    async (payload, next) => {
      const violation = config.onValidate?.(payload as InterceptorPayload)
      if (violation) {
        logger.warn(`[Waterfall] 输入校验失败: ${violation}`)
        eventBusV2.emit('message:error' as EventType, { error: new Error(violation), messageId: '' })
        return // 不调用 next()
      }
      await next()
    },
    // 3. 自动保存草稿
    async (payload, next) => {
      if (currentSessionId) {
        try {
          // 保存用户发送内容到草稿（轻量级，不阻塞发送）
          const draftKey = `draft_${currentSessionId}`
          localStorage.setItem(draftKey, JSON.stringify({
            content: (payload as InterceptorPayload).content,
            timestamp: (payload as InterceptorPayload).timestamp,
          }))
          logger.debug('[Waterfall] 草稿已保存:', draftKey)
        } catch (e) {
          logger.warn('[Waterfall] 草稿保存失败:', e)
        }
      }
      await next()
    },
  )

  // ── message:received 管道 ──
  eventBusV2.pipe('message:received' as EventType,
    // 1. 自动持久化到 IndexedDB
    async (payload, next) => {
      if (currentSessionId) {
        try {
          await chatStorageService.saveMessages(currentSessionId, [])
          logger.debug('[Waterfall] AI 回复已持久化:', currentSessionId)
        } catch (e) {
          logger.warn('[Waterfall] 持久化失败:', e)
        }
      }
      config.onPersistReceived?.(payload as EventPayloadMap['message:received'], currentSessionId ?? '')
      await next()
    },
    // 2. 上下文压缩检查
    async (payload, next) => {
      await next()
      // 压缩检查由 useChatMessages 在执行后触发，此处仅做日志
      logger.debug('[Waterfall] 消息已接收，压缩检查将在下次发送时执行')
    },
  )
}

/**
 * 设置当前会话 ID（由 ChatTab 在切换会话时调用）
 */
export function setWaterfallSessionId(sessionId: string | null): void {
  currentSessionId = sessionId
  logger.debug(`[WaterfallInterceptor] 会话 ID 已更新: ${sessionId ?? 'null'}`)
}

/**
 * 获取当前会话 ID
 */
export function getWaterfallSessionId(): string | null {
  return currentSessionId
}

/**
 * 注入用户画像到消息上下文中（在发送前调用）
 */
export function injectUserProfileIntoBody(body: Record<string, unknown>): void {
  const profileSummary = userProfileManager.generatePromptSummary()
  body['user_profile_context'] = profileSummary
  logger.debug('[WaterfallInterceptor] 用户画像已注入请求体')
}

/**
 * 获取拦截器状态
 */
export function getInterceptorStatus(): {
  sendingHandlers: number
  receivedHandlers: number
  currentSessionId: string | null
} {
  return {
    sendingHandlers: eventBusV2.getSubscriberCount('message:sending' as EventType) +
      (eventBusV2 as any).getPipes?.().get('message:sending')?.length || 0,
    receivedHandlers: eventBusV2.getSubscriberCount('message:received' as EventType) +
      (eventBusV2 as any).getPipes?.().get('message:received')?.length || 0,
    currentSessionId,
  }
}

