import { logger } from '@/utils/safeLogger'
import {
  FileSecurityError,
  sanitizeFileName,
  validateMimeType,
  hasDangerousExtension,
  generateSecureId,
  validateDataUrlSize,
  formatFileSize,
} from '@/utils/fileSecurity'

export type AttachmentType = 'image' | 'document' | 'text' | 'unknown'

export interface Attachment {
  id: string
  name: string
  originalName?: string
  type: AttachmentType
  file?: File
  dataUrl?: string
  text?: string
  mimeType: string
  detectedMimeType?: string
  size: number
  thumbnail?: string
  createdAt: number
  securityValidated: boolean
}

export interface DropZoneOptions {
  accept?: string[]
  maxSize?: number
  maxFiles?: number
  enableSecurityValidation?: boolean
}

export interface PasteHandlerOptions {
  handleImages?: boolean
  handleFiles?: boolean
  handleText?: boolean
  enableSecurityValidation?: boolean
}

const DEFAULT_MAX_SIZE = 10 * 1024 * 1024
const DEFAULT_MAX_FILES = 10
const DATA_URL_MAX_SIZE = 5 * 1024 * 1024

const IMAGE_MIME_TYPES = ['image/jpeg', 'image/png', 'image/gif', 'image/webp', 'image/bmp']
const DOCUMENT_MIME_TYPES = [
  'application/pdf',
  'application/msword',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/vnd.ms-excel',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  'application/vnd.ms-powerpoint',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  'text/plain',
  'text/csv',
  'text/markdown',
]

export class UnsupportedFileTypeError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'UnsupportedFileTypeError'
  }
}

export class FileTooLargeError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'FileTooLargeError'
  }
}

export class TooManyFilesError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'TooManyFilesError'
  }
}

export class ClipboardAttachmentService {
  private listeners = new Map<string, Set<(data: any) => void>>()

  constructor() {
    logger.debug('[ClipboardAttachmentService] 初始化（安全增强版）')
  }

  getAttachmentType(mimeType: string): AttachmentType {
    if (IMAGE_MIME_TYPES.includes(mimeType)) return 'image'
    if (DOCUMENT_MIME_TYPES.includes(mimeType)) return 'document'
    if (mimeType.startsWith('text/')) return 'text'
    return 'unknown'
  }

  generateId(): string {
    return generateSecureId()
  }

  private async performSecurityValidation(file: File): Promise<{
    sanitizedName: string
    detectedMimeType: string
  }> {
    logger.debug('[ClipboardAttachmentService] 执行安全验证', { fileName: file.name })

    const originalName = file.name

    try {
      const sanitizedName = sanitizeFileName(originalName)

      if (hasDangerousExtension(sanitizedName)) {
        throw new FileSecurityError(
          'DANGEROUS_EXTENSION',
          `检测到危险文件扩展名: ${sanitizedName}`,
          `不允许上传 .${sanitizedName.split('.').pop()} 类型的文件`,
        )
      }

      const detectedMimeType = await validateMimeType(file)

      logger.info('[ClipboardAttachmentService] 安全验证通过', {
        originalName,
        sanitizedName,
        declaredType: file.type,
        detectedType: detectedMimeType,
      })

      return { sanitizedName, detectedMimeType }
    } catch (error) {
      if (error instanceof FileSecurityError) {
        logger.error('[ClipboardAttachmentService] 安全验证失败', {
          code: error.code,
          message: error.message,
          fileName: file.name,
        })
        throw error
      }

      throw new FileSecurityError(
        'VALIDATION_ERROR',
        `安全验证异常: ${error instanceof Error ? error.message : '未知错误'}`,
        '文件安全检查失败，请确认文件完整性后重试',
      )
    }
  }

  async fileToAttachment(file: File, enableSecurityValidation = true): Promise<Attachment> {
    let sanitizedName = file.name
    let detectedMimeType: string | undefined
    let securityValidated = false

    if (enableSecurityValidation) {
      try {
        const validation = await this.performSecurityValidation(file)
        sanitizedName = validation.sanitizedName
        detectedMimeType = validation.detectedMimeType
        securityValidated = true
      } catch (error) {
        if (error instanceof FileSecurityError) {
          throw error
        }

        logger.warn('[ClipboardAttachmentService] 安全验证失败，使用基本模式', {
          error: error instanceof Error ? error.message : '未知错误',
        })
      }
    }

    const effectiveMimeType = detectedMimeType || file.type
    const type = this.getAttachmentType(effectiveMimeType)

    const attachment: Attachment = {
      id: this.generateId(),
      name: sanitizedName,
      originalName: file.name !== sanitizedName ? file.name : undefined,
      type,
      file,
      mimeType: effectiveMimeType,
      detectedMimeType,
      size: file.size,
      createdAt: Date.now(),
      securityValidated,
    }

    if (type === 'image') {
      attachment.dataUrl = await this.fileToDataUrlWithLimit(file)
      attachment.thumbnail = await this.generateThumbnail(file)
    }

    return attachment
  }

  async textToAttachment(text: string): Promise<Attachment> {
    return {
      id: this.generateId(),
      name: '剪贴板文本',
      type: 'text',
      text,
      mimeType: 'text/plain',
      size: new Blob([text]).size,
      createdAt: Date.now(),
      securityValidated: true,
    }
  }

  async fileToDataUrl(file: File): Promise<string> {
    return new Promise((resolve, reject) => {
      const reader = new FileReader()
      reader.onload = () => resolve(reader.result as string)
      reader.onerror = reject
      reader.readAsDataURL(file)
    })
  }

  private async fileToDataUrlWithLimit(file: File): Promise<string> {
    const dataUrl = await this.fileToDataUrl(file)

    try {
      validateDataUrlSize(dataUrl)
    } catch (error) {
      if (error instanceof FileSecurityError) {
        throw new FileTooLargeError(error.userMessage || `图片大小超过限制 (${formatFileSize(DATA_URL_MAX_SIZE)})`)
      }
      throw error
    }

    return dataUrl
  }

  async generateThumbnail(file: File, maxWidth = 200, maxHeight = 200): Promise<string> {
    return new Promise((resolve, reject) => {
      const img = new Image()
      const url = URL.createObjectURL(file)

      img.onload = () => {
        const canvas = document.createElement('canvas')
        let width = img.width
        let height = img.height

        if (width > maxWidth || height > maxHeight) {
          const ratio = Math.min(maxWidth / width, maxHeight / height)
          width = Math.round(width * ratio)
          height = Math.round(height * ratio)
        }

        canvas.width = width
        canvas.height = height

        const ctx = canvas.getContext('2d')
        if (ctx) {
          ctx.drawImage(img, 0, 0, width, height)
          const thumbnail = canvas.toDataURL('image/png')
          URL.revokeObjectURL(url)
          resolve(thumbnail)
        } else {
          URL.revokeObjectURL(url)
          reject(new Error('无法获取 canvas 上下文'))
        }
      }

      img.onerror = () => {
        URL.revokeObjectURL(url)
        reject(new Error('图片加载失败'))
      }

      img.src = url
    })
  }

  validateFile(file: File, options: DropZoneOptions = {}): void {
    const maxSize = options.maxSize ?? DEFAULT_MAX_SIZE
    const accept = options.accept
    const enableSecurityValidation = options.enableSecurityValidation ?? true

    if (file.size > maxSize) {
      throw new FileTooLargeError(`文件 ${file.name} 超过大小限制 (${formatFileSize(maxSize)})`)
    }

    if (enableSecurityValidation) {
      const sanitizedName = sanitizeFileName(file.name)

      if (hasDangerousExtension(sanitizedName)) {
        throw new FileSecurityError(
          'DANGEROUS_EXTENSION',
          `检测到危险文件扩展名: ${sanitizedName}`,
          `不允许上传此类型的文件 (.${sanitizedName.split('.').pop()})`,
        )
      }
    }

    if (accept && accept.length > 0) {
      const sanitizedFile = new File([file], sanitizeFileName(file.name), { type: file.type })
      const fileExtension = `.${sanitizeFileName(file.name).split('.').pop()?.toLowerCase()}`
      const mimeTypeMatch = accept.some(type =>
        sanitizedFile.type.includes(type) || fileExtension === type,
      )

      if (!mimeTypeMatch) {
        throw new UnsupportedFileTypeError(`不支持的文件类型: ${file.type}`)
      }
    }
  }

  async handleFiles(files: FileList, options: DropZoneOptions = {}): Promise<Attachment[]> {
    const maxFiles = options.maxFiles ?? DEFAULT_MAX_FILES
    const fileArray = Array.from(files)
    const enableSecurityValidation = options.enableSecurityValidation ?? true

    if (fileArray.length > maxFiles) {
      throw new TooManyFilesError(`最多只能上传 ${maxFiles} 个文件`)
    }

    const attachments: Attachment[] = []

    for (const file of fileArray) {
      this.validateFile(file, options)
      const attachment = await this.fileToAttachment(file, enableSecurityValidation)
      attachments.push(attachment)
    }

    logger.debug('[ClipboardAttachmentService] 处理文件完成', {
      count: attachments.length,
      securityEnabled: enableSecurityValidation,
    })
    return attachments
  }

  async handlePaste(event: ClipboardEvent, options: PasteHandlerOptions = {}): Promise<Attachment[]> {
    const {
      handleImages = true,
      handleFiles = true,
      handleText = true,
      enableSecurityValidation = true,
    } = options

    const attachments: Attachment[] = []

    logger.debug('[ClipboardAttachmentService] 处理粘贴事件', {
      hasFiles: !!event.clipboardData?.files.length,
      hasItems: !!event.clipboardData?.items?.length,
      securityEnabled: enableSecurityValidation,
    })

    if (handleFiles && event.clipboardData?.files.length) {
      const fileAttachments = await this.handleFiles(
        event.clipboardData.files,
        { ...options, enableSecurityValidation },
      )
      attachments.push(...fileAttachments)
    }

    if (handleImages && event.clipboardData?.items) {
      for (const item of event.clipboardData.items) {
        if (item.type.startsWith('image/')) {
          const file = item.getAsFile()
          if (file) {
            const attachment = await this.fileToAttachment(file, enableSecurityValidation)
            attachments.push(attachment)
          }
        }
      }
    }

    if (handleText && attachments.length === 0) {
      const text = event.clipboardData?.getData('text')
      if (text?.trim()) {
        const textAttachment = await this.textToAttachment(text)
        attachments.push(textAttachment)
      }
    }

    if (attachments.length > 0) {
      this.emit('paste', attachments)
    }

    return attachments
  }

  setupDropZone(element: HTMLElement, options: DropZoneOptions = {}): () => void {
    const handleDragOver = (e: DragEvent) => {
      e.preventDefault()
      e.stopPropagation()
      element.classList.add('dragover')
    }

    const handleDragLeave = (e: DragEvent) => {
      e.preventDefault()
      e.stopPropagation()
      element.classList.remove('dragover')
    }

    const handleDrop = async (e: DragEvent) => {
      e.preventDefault()
      e.stopPropagation()
      element.classList.remove('dragover')

      if (e.dataTransfer?.files.length) {
        try {
          const attachments = await this.handleFiles(e.dataTransfer.files, options)
          this.emit('drop', attachments)
        } catch (error) {
          logger.error('[ClipboardAttachmentService] 拖放处理失败', error)
          this.emit('error', error)
        }
      }
    }

    element.addEventListener('dragover', handleDragOver)
    element.addEventListener('dragleave', handleDragLeave)
    element.addEventListener('drop', handleDrop)

    logger.debug('[ClipboardAttachmentService] 拖放区已设置', {
      securityEnabled: options.enableSecurityValidation ?? true,
    })

    return () => {
      element.removeEventListener('dragover', handleDragOver)
      element.removeEventListener('dragleave', handleDragLeave)
      element.removeEventListener('drop', handleDrop)
      element.classList.remove('dragover')
      logger.debug('[ClipboardAttachmentService] 拖放区已清理')
    }
  }

  setupPasteHandler(element: HTMLElement, options: PasteHandlerOptions = {}): () => void {
    const handlePaste = async (e: ClipboardEvent) => {
      try {
        const attachments = await this.handlePaste(e, options)
        if (attachments.length > 0) {
          e.preventDefault()
        }
      } catch (error) {
        logger.error('[ClipboardAttachmentService] 粘贴处理失败', error)
        this.emit('error', error)
      }
    }

    element.addEventListener('paste', handlePaste as unknown as EventListener)
    logger.debug('[ClipboardAttachmentService] 粘贴处理器已设置', {
      securityEnabled: options.enableSecurityValidation ?? true,
    })

    return () => {
      element.removeEventListener('paste', handlePaste as unknown as EventListener)
      logger.debug('[ClipboardAttachmentService] 粘贴处理器已清理')
    }
  }

  on(event: string, callback: (data: any) => void): void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set())
    }
    this.listeners.get(event)!.add(callback)
  }

  off(event: string, callback: (data: any) => void): void {
    this.listeners.get(event)?.delete(callback)
  }

  private emit(event: string, data: any): void {
    this.listeners.get(event)?.forEach(callback => callback(data))
  }
}

export const clipboardAttachmentService = new ClipboardAttachmentService()
export default clipboardAttachmentService

/**
 * ContextManager - 高级上下文管理服务
 *
 * 提供增强的上下文理解能力，支持多轮对话连贯性。
 *
 * 核心功能：
 * - 上下文窗口管理：智能维护对话历史滑动窗口
 * - 意图追踪：追踪用户意图的连贯性
 * - 实体记忆：记住对话中提到的关键实体
 * - 话题管理：检测话题变化和相关性
 * - 引用解析：处理代词指代关系
 *
 * @version 2.0.0
 * @lastUpdated 2026-05-22
 */

import { logger } from '@/utils/safeLogger';
import { eventBus } from './eventBus';

export interface ContextEntity {
  id: string;
  name: string;
  type: 'ingredient' | 'formula' | 'symptom' | 'disease' | 'product' | 'other';
  confidence: number;
  occurrences: number;
  lastMentioned: number;
  attributes?: Record<string, string | number>;
}

export interface IntentInfo {
  intent: string;
  confidence: number;
  slots: Record<string, string>;
  isFollowUp: boolean;
  relatedIntents: string[];
}

export interface TopicInfo {
  topic: string;
  confidence: number;
  keywords: string[];
  similarity: number;
}

export interface ContextState {
  entities: ContextEntity[];
  intents: IntentInfo[];
  topics: TopicInfo[];
  history: ContextMessage[];
  contextWindow: string[];
  isMaintainingContext: boolean;
  topicContinuity: number;
}

export interface ContextMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: number;
  entities: ContextEntity[];
  intent?: IntentInfo;
}

export interface ContextManagerConfig {
  maxWindowSize?: number;
  maxEntities?: number;
  entityConfidenceThreshold?: number;
  topicSimilarityThreshold?: number;
}

const DEFAULT_CONFIG: Required<ContextManagerConfig> = {
  maxWindowSize: 10,
  maxEntities: 20,
  entityConfidenceThreshold: 0.6,
  topicSimilarityThreshold: 0.7,
};

// 领域实体词典
const DOMAIN_ENTITIES: Record<string, { type: ContextEntity['type']; keywords: string[] }> = {
  ingredients: {
    type: 'ingredient',
    keywords: ['黄芪', '当归', '枸杞', '人参', '鹿茸', '虫草', '灵芝', '丹参', '山楂', '决明子'],
  },
  formulas: {
    type: 'formula',
    keywords: ['配方', '复方', '制剂', '方剂', '组方', '药方'],
  },
  symptoms: {
    type: 'symptom',
    keywords: ['高血糖', '高血压', '高血脂', '失眠', '疲劳', '头晕', '乏力', '记忆力减退'],
  },
  diseases: {
    type: 'disease',
    keywords: ['糖尿病', '高血压', '高血脂', '心血管疾病', '骨质疏松', '免疫力低下'],
  },
  products: {
    type: 'product',
    keywords: ['口服液', '胶囊', '片剂', '颗粒', '饮料', '食品', '保健品', '多肽'],
  },
};

export class ContextManager {
  private config: Required<ContextManagerConfig>;
  private entities: ContextEntity[] = [];
  private intents: IntentInfo[] = [];
  private topics: TopicInfo[] = [];
  private history: ContextMessage[] = [];
  private contextWindow: string[] = [];
  private currentTopic = '';
  private topicContinuity = 0;

  constructor(config: ContextManagerConfig = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.initializeEventListeners();
    logger.info('[ContextManager] 上下文管理器已初始化', { config: this.config });
  }

  private initializeEventListeners(): void {
    eventBus.subscribe('message:sending', (data) => {
      this.processUserMessage((data as { content: string }).content);
    });

    eventBus.subscribe('message:received', (data) => {
      this.processAssistantMessage((data as { content: string }).content);
    });

    eventBus.subscribe('state:changed', (data) => {
      const payload = data as { newState: string };
      if (payload.newState === 'Idle') {
        this.topicContinuity = 0;
      }
    });
  }

  private extractEntities(text: string): ContextEntity[] {
    const entities: ContextEntity[] = [];

    for (const [category, info] of Object.entries(DOMAIN_ENTITIES)) {
      for (const keyword of info.keywords) {
        const regex = new RegExp(keyword, 'gi');
        const matches = text.match(regex);

        if (matches) {
          const existingEntity = this.entities.find((e) => e.name === keyword);
          const confidence = Math.min(0.95, 0.7 + matches.length * 0.05);

          entities.push({
            id: `entity-${keyword}-${Date.now()}`,
            name: keyword,
            type: info.type,
            confidence,
            occurrences: existingEntity ? existingEntity.occurrences + 1 : 1,
            lastMentioned: Date.now(),
          });
        }
      }
    }

    return entities.filter((e) => e.confidence >= this.config.entityConfidenceThreshold);
  }

  private analyzeIntent(text: string): IntentInfo {
    const intentPatterns = [
      { intent: 'ask_question', pattern: /什么|如何|怎么|为什么|是否|能否|可以/i, slots: {} },
      { intent: 'request_formula', pattern: /配方|组方|制剂|药方|设计/i, slots: {} },
      { intent: 'request_analysis', pattern: /分析|评估|评价|效果|功效/i, slots: {} },
      { intent: 'request_recommendation', pattern: /推荐|建议|推荐一下|介绍/i, slots: {} },
      { intent: 'confirm', pattern: /对吗|是不是|正确|确认/i, slots: {} },
      { intent: 'follow_up', pattern: /还有|另外|再|继续/i, slots: {} },
    ];

    let matchedIntent: IntentInfo = {
      intent: 'unknown',
      confidence: 0.5,
      slots: {},
      isFollowUp: false,
      relatedIntents: [],
    };

    for (const pattern of intentPatterns) {
      if (pattern.pattern.test(text)) {
        const confidence = 0.7 + Math.random() * 0.3;
        if (confidence > matchedIntent.confidence) {
          matchedIntent = {
            intent: pattern.intent,
            confidence,
            slots: pattern.slots,
            isFollowUp: pattern.intent === 'follow_up',
            relatedIntents: this.findRelatedIntents(pattern.intent),
          };
        }
      }
    }

    return matchedIntent;
  }

  private findRelatedIntents(intent: string): string[] {
    const intentRelations: Record<string, string[]> = {
      ask_question: ['request_analysis', 'request_recommendation'],
      request_formula: ['request_analysis', 'request_recommendation'],
      request_analysis: ['ask_question', 'request_recommendation'],
      request_recommendation: ['ask_question', 'request_formula'],
      confirm: ['ask_question', 'request_analysis'],
      follow_up: ['ask_question', 'request_formula', 'request_analysis'],
    };
    return intentRelations[intent] || [];
  }

  private analyzeTopic(text: string): TopicInfo {
    const topicKeywords: Record<string, string[]> = {
      配方设计: ['配方', '设计', '组方', '制剂', '药方'],
      成分分析: ['成分', '分析', '功效', '作用', '活性'],
      健康问题: ['高血糖', '高血压', '高血脂', '失眠', '疲劳'],
      产品开发: ['产品', '开发', '研制', '研发', '生产'],
      学术研究: ['研究', '论文', '文献', '学术', '报告'],
    };

    let bestTopic: TopicInfo = {
      topic: '其他',
      confidence: 0.5,
      keywords: [],
      similarity: 0,
    };

    for (const [topic, keywords] of Object.entries(topicKeywords)) {
      let matchCount = 0;
      for (const keyword of keywords) {
        if (text.includes(keyword)) {
          matchCount++;
        }
      }

      const confidence = matchCount / keywords.length;
      const similarity = this.calculateTopicSimilarity(topic, text);

      if (confidence > bestTopic.confidence && similarity > this.config.topicSimilarityThreshold) {
        bestTopic = {
          topic,
          confidence: Math.min(0.95, confidence),
          keywords: keywords.filter((k) => text.includes(k)),
          similarity,
        };
      }
    }

    return bestTopic;
  }

  private calculateTopicSimilarity(topic: string, text: string): number {
    const topicWords = topic.split('');
    const textWords = text.split('');

    let matches = 0;
    for (const word of topicWords) {
      if (textWords.includes(word)) {
        matches++;
      }
    }

    return matches / topicWords.length;
  }

  private updateContextWindow(content: string): void {
    this.contextWindow.push(content);

    if (this.contextWindow.length > this.config.maxWindowSize) {
      this.contextWindow.shift();
    }
  }

  private updateTopicContinuity(newTopic: string): void {
    if (newTopic === this.currentTopic) {
      this.topicContinuity = Math.min(100, this.topicContinuity + 10);
    } else {
      this.topicContinuity = Math.max(0, this.topicContinuity - 20);
      this.currentTopic = newTopic;
    }
  }

  processUserMessage(content: string): void {
    logger.debug('[ContextManager] 处理用户消息:', { content: content.substring(0, 50) });

    const entities = this.extractEntities(content);
    const intent = this.analyzeIntent(content);
    const topic = this.analyzeTopic(content);

    // 更新实体记忆
    for (const entity of entities) {
      const existingIndex = this.entities.findIndex((e) => e.name === entity.name);
      if (existingIndex >= 0) {
        this.entities[existingIndex].occurrences++;
        this.entities[existingIndex].lastMentioned = Date.now();
        this.entities[existingIndex].confidence = Math.min(0.99, this.entities[existingIndex].confidence + 0.02);
      } else {
        this.entities.push(entity);
      }
    }

    // 保持实体数量限制
    this.entities = this.entities.sort((a, b) => b.lastMentioned - a.lastMentioned).slice(0, this.config.maxEntities);

    // 更新意图历史
    this.intents.push(intent);
    if (this.intents.length > 5) {
      this.intents.shift();
    }

    // 更新话题
    this.topics.push(topic);
    if (this.topics.length > 5) {
      this.topics.shift();
    }

    // 更新上下文窗口
    this.updateContextWindow(content);

    // 更新话题连续性
    this.updateTopicContinuity(topic.topic);

    // 添加到历史记录
    this.history.push({
      id: `msg-${Date.now()}`,
      role: 'user',
      content,
      timestamp: Date.now(),
      entities,
      intent,
    });

    if (this.history.length > this.config.maxWindowSize) {
      this.history.shift();
    }

    eventBus.emit('context:updated', this.getState() as unknown as Record<string, unknown>);
  }

  processAssistantMessage(content: string): void {
    logger.debug('[ContextManager] 处理助手消息:', { content: content.substring(0, 50) });

    const entities = this.extractEntities(content);

    this.history.push({
      id: `msg-${Date.now()}`,
      role: 'assistant',
      content,
      timestamp: Date.now(),
      entities,
    });

    if (this.history.length > this.config.maxWindowSize) {
      this.history.shift();
    }

    eventBus.emit('context:updated', this.getState() as unknown as Record<string, unknown>);
  }

  getState(): ContextState {
    return {
      entities: [...this.entities],
      intents: [...this.intents],
      topics: [...this.topics],
      history: [...this.history],
      contextWindow: [...this.contextWindow],
      isMaintainingContext: this.topicContinuity > 50,
      topicContinuity: this.topicContinuity,
    };
  }

  getActiveEntities(): ContextEntity[] {
    const recentThreshold = Date.now() - 5 * 60 * 1000; // 5分钟内
    return this.entities.filter((e) => e.lastMentioned > recentThreshold).sort((a, b) => b.occurrences - a.occurrences);
  }

  getCurrentTopic(): TopicInfo | null {
    return this.topics[this.topics.length - 1] || null;
  }

  getContextSummary(): string {
    const activeEntities = this.getActiveEntities();
    const currentTopic = this.getCurrentTopic();
    const recentIntents = this.intents.slice(-3);

    const parts: string[] = [];

    if (activeEntities.length > 0) {
      parts.push(`涉及实体: ${activeEntities.map((e) => e.name).join('、')}`);
    }

    if (currentTopic) {
      parts.push(`当前话题: ${currentTopic.topic}`);
    }

    if (recentIntents.length > 0) {
      const intentNames = recentIntents.map((i) => i.intent).join('、');
      parts.push(`用户意图: ${intentNames}`);
    }

    return parts.join('；') || '暂无上下文信息';
  }

  clearContext(): void {
    this.entities = [];
    this.intents = [];
    this.topics = [];
    this.history = [];
    this.contextWindow = [];
    this.currentTopic = '';
    this.topicContinuity = 0;

    logger.info('[ContextManager] 上下文已清空');
    eventBus.emit('context:cleared', {});
  }

  getContextPrompt(): string {
    const state = this.getState();

    if (state.contextWindow.length === 0) {
      return '';
    }

    const messagesSummary = state.contextWindow
      .map((msg, i) => {
        const prefix = i % 2 === 0 ? '用户: ' : '助手: ';
        return `${prefix}${msg}`;
      })
      .join('\n');

    const entitiesSummary =
      state.entities.length > 0 ? `\n\n相关实体: ${state.entities.map((e) => e.name).join('、')}` : '';

    const topicSummary =
      state.topicContinuity > 50 && state.topics.length > 0
        ? `\n\n当前话题: ${state.topics[state.topics.length - 1].topic}`
        : '';

    return `以下是对话历史上下文，请基于此进行回复：\n${messagesSummary}${entitiesSummary}${topicSummary}`;
  }

  isFollowUpQuestion(content: string): boolean {
    const followUpPatterns = [
      /还有|另外|再|继续|接着|进一步|更详细/i,
      /这个|那个|它|他们|这些|那些/i,
      /之前|刚才|之前说的/i,
      /然后呢|之后呢|接下来呢/i,
    ];

    return followUpPatterns.some((pattern) => pattern.test(content));
  }
}

export const contextManager = new ContextManager();

export default ContextManager;

/**
 * DeepThinkingService V2 - 增强型深度思考服务
 *
 * 多维度分析能力升级：
 * - 语义分析：实体识别、关键词提取、意图分类、情感分析
 * - 领域分析：食品配方领域专业知识注入（原料、功效、工艺、法规）
 * - 上下文理解：多轮对话连贯性、指代消解、话题追踪
 * - 逻辑推理：多步骤推理、假设验证、证据链构建
 * - 复杂度评估：问题复杂度量化、子任务拆解建议
 *
 * @version 2.0.0
 */

import { API_ENDPOINTS } from '@/config/apiEndpoints';
import { logger } from '@/utils/safeLogger';
import { eventBus } from './eventBus';

export interface SemanticAnalysis {
  entities: {
    name: string;
    type: 'ingredient' | 'formula' | 'symptom' | 'disease' | 'dosage_form' | 'process' | 'regulation' | 'other';
    confidence: number;
    category?: string;
  }[];
  keywords: string[];
  sentiment: 'positive' | 'negative' | 'neutral';
  sentimentScore: number;
  intent:
    | 'question'
    | 'request'
    | 'statement'
    | 'complaint'
    | 'suggestion'
    | 'comparison'
    | 'how_to'
    | 'definition'
    | 'unknown';
  intentConfidence: number;
  complexity: number;
}

export interface DomainAnalysis {
  productType: string | null;
  targetEfficacy: string[];
  keyIngredients: { name: string; type: string; confidence: number }[];
  dosageForm: string | null;
  regulatoryContext: string | null;
  processKeywords: string[];
  safetyConcerns: string[];
  domainConfidence: number;
}

export interface ContextAnalysis {
  references: {
    text: string;
    type: 'pronoun' | 'entity' | 'topic';
    target?: string;
  }[];
  contextWindow: string[];
  topicContinuity: number;
  isFollowUp: boolean;
  relatedQuestions: string[];
}

export interface LogicalReasoning {
  steps: {
    step: number;
    description: string;
    dimension: string;
    confidence: number;
  }[];
  conclusion: string;
  supportingEvidence: string[];
  confidence: number;
  alternativeSolutions?: string[];
  assumptions?: string[];
}

export interface MultiDimensionResult {
  semanticAnalysis: SemanticAnalysis;
  domainAnalysis: DomainAnalysis;
  contextAnalysis: ContextAnalysis;
  logicalReasoning: LogicalReasoning;
  enhancedPrompt: string;
  analysisDimensions: {
    name: string;
    score: number;
    findings: string[];
  }[];
}

export interface DeepThinkingServiceConfig {
  timeout?: number;
}

const DOMAIN_ENTITY_PATTERNS: {
  regex: RegExp;
  type: SemanticAnalysis['entities'][number]['type'];
  category?: string;
}[] = [
  {
    regex: /[\u4e00-\u9fa5]+(?:提取物|精华|粉|肽|多糖|黄酮|皂苷|生物碱|甾醇|花青素)/,
    type: 'ingredient',
    category: '活性成分',
  },
  { regex: /(?:大豆|胶原|鱼|玉米|卵白|乳清|大米|海洋|小麦|玉米)肽/, type: 'ingredient', category: '多肽类' },
  {
    regex: /(?:黄芪|人参|灵芝|枸杞|当归|党参|山药|茯苓|甘草|山楂|苦瓜|桑叶|红曲|银杏|绞股蓝)/,
    type: 'ingredient',
    category: '药食同源',
  },
  { regex: /(?:益生菌|益生元|乳酸菌|双歧杆菌|酵母菌)/, type: 'ingredient', category: '微生物' },
  { regex: /(?:固体饮料|片剂|胶囊|软糖|粉剂|口服液|冲剂|丸剂|膏方|滴丸)/, type: 'dosage_form', category: '剂型' },
  { regex: /(?:酶解|发酵|提取|纯化|干燥|造粒|压片|包衣|灭菌|均质|乳化|微囊化)/, type: 'process', category: '工艺' },
  {
    regex: /(?:GB|ISO|HACCP|GMP|SC|保健食品|特医食品|新资源食品|药食同源|备案|申报|注册)/,
    type: 'regulation',
    category: '法规标准',
  },
  { regex: /配方|配方表|配比|成分表|复配/, type: 'formula', category: '配方' },
  {
    regex: /(?:降|调节|改善|控制|辅助).{0,6}(?:血压|血糖|血脂|三高|胆固醇|尿酸|体重|免疫|睡眠|记忆|抗氧化)/,
    type: 'symptom',
    category: '功效目标',
  },
  {
    regex: /(?:安全|毒性|副作用|禁忌|不良反应|过敏|重金属|农残|微生物|菌落|霉菌)/,
    type: 'symptom',
    category: '安全关注',
  },
];

const EFFICACY_MAPPING: Record<string, string> = {
  降三高: '代谢调节(三高)',
  降压: '血压调节',
  降血糖: '血糖调节',
  降血脂: '血脂调节',
  减肥: '体重管理',
  免疫: '免疫调节',
  睡眠: '睡眠改善',
  美容: '美容抗衰',
  肠道: '肠道健康',
  抗氧化: '抗氧化',
  抗疲劳: '抗疲劳',
  护肝: '肝脏保护',
  关节: '关节健康',
  骨骼: '骨骼健康',
  心血管: '心血管保护',
};

class DeepThinkingServiceV2 {
  private readonly timeout: number;

  constructor(config: DeepThinkingServiceConfig = {}) {
    this.timeout = config.timeout ?? 30000;
  }

  async analyze(question: string, context?: string[]): Promise<MultiDimensionResult> {
    logger.debug('[DeepThinkingServiceV2] 开始多维度深度分析:', { question, contextLength: context?.length });

    eventBus.emit('thinking:step', { question, timestamp: Date.now() });

    try {
      const response = await fetch(API_ENDPOINTS.AI.CHAT as string, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ question, context }),
        signal: AbortSignal.timeout(this.timeout),
      });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(`深度思考分析失败 (${response.status}): ${errorText}`);
      }

      const result = await response.json();

      eventBus.emit('thinking:step', {
        question,
        result,
        timestamp: Date.now(),
      });

      logger.debug('[DeepThinkingServiceV2] 深度分析完成');
      return this.enrichWithDomainAnalysis(result as MultiDimensionResult, question);
    } catch (error) {
      eventBus.emit('thinking:step', {
        error: error instanceof Error ? error.message : 'Unknown error',
        timestamp: Date.now(),
      });

      logger.error('[DeepThinkingServiceV2] 深度分析失败，使用增强版降级分析:', error);
      return this.enhancedFallbackAnalysis(question, context);
    }
  }

  async *analyzeStream(question: string, context?: string[]): AsyncGenerator<Partial<MultiDimensionResult>> {
    logger.debug('[DeepThinkingServiceV2] 开始流式深度分析:', { question });

    try {
      const response = await fetch(API_ENDPOINTS.AI.CHAT as string, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ question, context }),
        signal: AbortSignal.timeout(this.timeout),
      });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(`流式分析失败 (${response.status}): ${errorText}`);
      }

      const reader = response.body?.getReader();
      if (!reader) throw new Error('无法获取响应流');

      const decoder = new TextDecoder();
      let buffer = '';

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\n');
        buffer = lines.pop() || '';

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            const data = line.slice(6).trim();
            if (data === '[DONE]') return;
            try {
              yield JSON.parse(data) as Partial<MultiDimensionResult>;
            } catch {
              logger.warn('[DeepThinkingServiceV2] 解析流式数据失败:', data);
            }
          }
        }
      }
    } catch (error) {
      logger.error('[DeepThinkingServiceV2] 流式分析失败:', error);
      yield this.enhancedFallbackAnalysis(question, context);
    }
  }

  private enrichWithDomainAnalysis(base: MultiDimensionResult, _question: string): MultiDimensionResult {
    return {
      ...base,
      domainAnalysis: base.domainAnalysis || this.analyzeDomain(_question),
      analysisDimensions: base.analysisDimensions || this.buildAnalysisDimensions(base),
    };
  }

  private enhancedFallbackAnalysis(question: string, context?: string[]): MultiDimensionResult {
    logger.warn('[DeepThinkingServiceV2] 使用增强版多维度降级分析');

    const semantic = this.performSemanticAnalysis(question);
    const domain = this.analyzeDomain(question);

    return {
      semanticAnalysis: semantic,
      domainAnalysis: domain,
      contextAnalysis: {
        references: [],
        contextWindow: context || [],
        topicContinuity: (context?.length ?? 0) ? 0.8 : 0.5,
        isFollowUp: (context?.length ?? 0) > 0,
        relatedQuestions: this.generateRelatedQuestions(question, domain),
      },
      logicalReasoning: {
        steps: this.buildReasoningSteps(question, domain),
        conclusion: this.generateConclusion(question, domain),
        supportingEvidence: this.buildEvidenceChain(question, domain),
        confidence: Math.min(semantic.complexity * 0.8 + domain.domainConfidence * 0.2, 0.95),
        alternativeSolutions: this.generateAlternatives(domain),
        assumptions: this.identifyAssumptions(question, domain),
      },
      enhancedPrompt: this.buildEnhancedPrompt(question, context, semantic, domain),
      analysisDimensions: this.buildAnalysisDimensionsFromScratch(semantic, domain),
    };
  }

  private performSemanticAnalysis(question: string): SemanticAnalysis {
    const entities = this.extractEntitiesEnhanced(question);
    const keywords = this.extractKeywords(question);
    const sentiment = this.analyzeSentiment(question);
    const intent = this.detectIntentEnhanced(question);
    const complexity = this.calculateComplexity(entities, keywords, question.length);

    return {
      entities,
      keywords,
      sentiment,
      sentimentScore: sentiment === 'positive' ? 0.75 : sentiment === 'negative' ? -0.5 : 0,
      intent: intent.type,
      intentConfidence: intent.confidence,
      complexity,
    };
  }

  private extractEntitiesEnhanced(question: string): SemanticAnalysis['entities'] {
    const entities: SemanticAnalysis['entities'] = [];

    for (const { regex, type, category } of DOMAIN_ENTITY_PATTERNS) {
      const matches = question.match(regex);
      if (matches) {
        entities.push({
          name: matches[0],
          type,
          confidence: type === 'ingredient' ? 0.88 : type === 'dosage_form' ? 0.92 : 0.78,
          category,
        });
      }
    }

    return entities;
  }

  private extractKeywords(question: string): string[] {
    const stopWords = [
      '的',
      '是',
      '在',
      '有',
      '和',
      '了',
      '我',
      '你',
      '他',
      '她',
      '它',
      '这',
      '那',
      '一个',
      '一种',
      '如何',
      '什么',
    ];
    const words = question
      .replace(/[，。！？、；：""''（）【】《》]/g, ' ')
      .split(/\s+/)
      .filter((word) => word.length > 1 && !stopWords.includes(word));

    return [...new Set(words)].slice(0, 12);
  }

  private calculateComplexity(
    entities: SemanticAnalysis['entities'],
    _keywords: string[],
    questionLength: number,
  ): number {
    let score = 0.3;

    const entityTypes = new Set(entities.map((e) => e.type));
    score += Math.min(entityTypes.size * 0.1, 0.3);

    if (entities.some((e) => e.type === 'ingredient')) score += 0.12;
    if (entities.some((e) => e.type === 'dosage_form')) score += 0.08;
    if (entities.some((e) => e.type === 'regulation')) score += 0.1;
    if (entities.some((e) => e.type === 'process')) score += 0.1;

    if (questionLength > 30) score += 0.08;
    if (questionLength > 50) score += 0.07;

    return Math.min(score, 1.0);
  }

  private analyzeDomain(question: string): DomainAnalysis {
    const entities = this.extractEntitiesEnhanced(question);

    const productTypeMatch = /(?:设计|开发|研制|研发|创建).{0,10}(?:配方|产品|制剂|饮料|片剂|胶囊)/.exec(question);
    const dosageFormMatch = entities.find((e) => e.type === 'dosage_form');
    const regulationMatch = entities.find((e) => e.type === 'regulation');
    const processMatches = entities.filter((e) => e.type === 'process').map((e) => e.name);
    const efficacyMatches = entities.filter((e) => e.category === '功效目标').map((e) => e.name);
    const safetyMatches = entities.filter((e) => e.category === '安全关注').map((e) => e.name);

    const targetEfficacy: string[] = [];
    for (const [key, value] of Object.entries(EFFICACY_MAPPING)) {
      if (question.includes(key)) targetEfficacy.push(value);
    }

    const ingredients = entities
      .filter((e) => e.type === 'ingredient')
      .map((e) => ({
        name: e.name,
        type: e.category || '未知',
        confidence: e.confidence,
      }));

    const domainConfidence = Math.min(
      0.4 +
        ingredients.length * 0.08 +
        (targetEfficacy.length > 0 ? 0.15 : 0) +
        (dosageFormMatch ? 0.12 : 0) +
        (regulationMatch ? 0.1 : 0) +
        (processMatches.length > 0 ? 0.08 : 0),
      0.95,
    );

    return {
      productType: productTypeMatch ? productTypeMatch[0].replace(/^(设计|开发|研制|研发|创建)/, '').trim() : null,
      targetEfficacy,
      keyIngredients: ingredients,
      dosageForm: dosageFormMatch?.name || null,
      regulatoryContext: regulationMatch?.name || null,
      processKeywords: processMatches,
      safetyConcerns: safetyMatches,
      domainConfidence,
    };
  }

  private detectIntentEnhanced(question: string): { type: SemanticAnalysis['intent']; confidence: number } {
    if (/？|\?|吗$|什么|怎么|如何|为什么|哪/.test(question)) return { type: 'question', confidence: 0.9 };
    if (/请|帮我|需要|希望|想要|能否/.test(question)) return { type: 'request', confidence: 0.85 };
    if (/建议|应该|可以|推荐|最好/.test(question)) return { type: 'suggestion', confidence: 0.8 };
    if (/比较|对比|区别|差异|优缺点|VS|vs/.test(question)) return { type: 'comparison', confidence: 0.88 };
    if (/如何|怎么.*做|步骤|流程|方法|方案/.test(question)) return { type: 'how_to', confidence: 0.86 };
    if (/什么是|定义|解释|含义/.test(question)) return { type: 'definition', confidence: 0.87 };
    if (/问题|错误|不行|失败|麻烦|投诉/.test(question)) return { type: 'complaint', confidence: 0.78 };
    return { type: 'statement', confidence: 0.65 };
  }

  private analyzeSentiment(question: string): SemanticAnalysis['sentiment'] {
    const positiveWords = ['好', '棒', '优秀', '完美', '喜欢', '满意', '推荐', '优化', '提升', '增强'];
    const negativeWords = ['差', '糟糕', '不好', '问题', '错误', '失败', '麻烦', '缺陷', '风险', '毒性'];

    let posCount = 0;
    let negCount = 0;
    for (const word of positiveWords) {
      if (question.includes(word)) posCount++;
    }
    for (const word of negativeWords) {
      if (question.includes(word)) negCount++;
    }

    if (posCount > negCount) return 'positive';
    if (negCount > posCount) return 'negative';
    return 'neutral';
  }

  private buildReasoningSteps(question: string, domain: DomainAnalysis): LogicalReasoning['steps'] {
    const steps: LogicalReasoning['steps'] = [
      { step: 1, description: `语义解析：${question.slice(0, 25)}...`, dimension: '语义理解', confidence: 0.92 },
      {
        step: 2,
        description: `领域识别：检测到 ${domain.keyIngredients.length} 个核心原料 + ${domain.targetEfficacy.length} 个功效目标`,
        dimension: '领域知识',
        confidence: 0.87,
      },
    ];

    if (domain.dosageForm) {
      steps.push({
        step: steps.length + 1,
        description: `剂型适配：${domain.dosageForm} 的工艺约束与质量标准`,
        dimension: '工艺路线',
        confidence: 0.83,
      });
    }
    if (domain.regulatoryContext) {
      steps.push({
        step: steps.length + 1,
        description: `合规检查：${domain.regulatoryContext} 相关法规要求梳理`,
        dimension: '法规合规',
        confidence: 0.89,
      });
    }
    if (domain.safetyConcerns.length > 0) {
      steps.push({
        step: steps.length + 1,
        description: `风险评估：关注 ${domain.safetyConcerns.join('、')} 等安全问题`,
        dimension: '安全评估',
        confidence: 0.85,
      });
    }

    steps.push(
      {
        step: steps.length + 1,
        description: '综合决策：基于多维度分析生成最优建议',
        dimension: '综合决策',
        confidence: 0.8,
      },
      { step: steps.length + 1, description: '内容组织：结构化输出专业回复', dimension: '内容生成', confidence: 0.9 },
    );

    return steps;
  }

  private generateConclusion(question: string, domain: DomainAnalysis): string {
    const parts: string[] = [];
    if (domain.keyIngredients.length > 0) parts.push(`涉及${domain.keyIngredients.map((i) => i.name).join('、')}`);
    if (domain.targetEfficacy.length > 0) parts.push(`针对${domain.targetEfficacy.join('/')}需求`);
    if (domain.dosageForm) parts.push(`${domain.dosageForm}剂型`);
    return `此问题属于${parts.length > 0 ? parts.join('的') : '通用'}专业咨询，需从技术、法规、安全等多维度综合分析`;
  }

  private buildEvidenceChain(question: string, domain: DomainAnalysis): string[] {
    const evidence: string[] = [`用户原始问题: "${question.slice(0, 60)}"`];
    if (domain.keyIngredients.length > 0) evidence.push(`原料依据: 已识别${domain.keyIngredients.length}种关键成分`);
    if (domain.targetEfficacy.length > 0) evidence.push(`功效依据: 目标方向为${domain.targetEfficacy.join('、')}`);
    if (domain.regulatoryContext) evidence.push(`法规依据: 需符合${domain.regulatoryContext}相关要求`);
    return evidence;
  }

  private generateAlternatives(_domain: DomainAnalysis): string[] {
    return ['从成本效益角度简化方案', '考虑替代性原料组合', '分阶段实施策略（MVP → 完整版）'];
  }

  private identifyAssumptions(question: string, domain: DomainAnalysis): string[] {
    const assumptions: string[] = [];
    if (domain.keyIngredients.length === 0) assumptions.push('假设用户可接受推荐的候选原料');
    if (!domain.dosageForm) assumptions.push('假设以最常用的固体饮料作为默认剂型');
    if (domain.targetEfficacy.length === 0) assumptions.push('假设用户关注基础营养补充功能');
    if (question.length < 15) assumptions.push('用户输入信息有限，部分推断基于行业常见场景');
    return assumptions;
  }

  private generateRelatedQuestions(question: string, domain: DomainAnalysis): string[] {
    const questions: string[] = [];
    if (domain.targetEfficacy.length > 0) questions.push(`${domain.targetEfficacy[0]}的作用机制是什么？`);
    if (domain.keyIngredients.length > 0) questions.push(`${domain.keyIngredients[0].name}的最佳用量范围？`);
    if (domain.dosageForm) questions.push(`${domain.dosageForm}的关键质量控制点有哪些？`);
    questions.push(`${question.slice(0, 20)} 的成本估算和开发周期？`);
    return questions.slice(0, 4);
  }

  private buildEnhancedPrompt(
    question: string,
    context: string[] | undefined,
    semantic: SemanticAnalysis,
    domain: DomainAnalysis,
  ): string {
    const contextStr = context?.join('\n') || '无历史上下文';
    const ingredientStr = domain.keyIngredients.map((i) => `- ${i.name} (${i.type})`).join('\n') || '- 待识别';
    const efficacyStr = domain.targetEfficacy.join('、') || '待明确';

    return `
## 用户请求分析报告

### 基本信息
- **原始问题**: ${question}
- **问题复杂度**: ${(semantic.complexity * 100).toFixed(0)}%
- **用户意图**: ${semantic.intent} (置信度: ${(semantic.intentConfidence * 100).toFixed(0)}%)
- **情感倾向**: ${semantic.sentiment}

### 领域特征
- **产品类型**: ${domain.productType || '未指定'}
- **目标功效**: ${efficacyStr}
- **核心原料**:
${ingredientStr}
- **剂型**: ${domain.dosageForm || '未指定'}
- **法规上下文**: ${domain.regulatoryContext || '无特殊法规要求'}
- **安全关注**: ${domain.safetyConcerns.length > 0 ? domain.safetyConcerns.join('、') : '无明显安全关注点'}

### 对话上下文
${contextStr}

---
请基于以上多维分析结果，提供：
1. 结构化的专业回答
2. 数据支撑的关键论断
3. 可执行的建议步骤
4. 潜在风险提示
5. 后续深入探讨的方向
`.trim();
  }

  private buildAnalysisDimensions(result: MultiDimensionResult): MultiDimensionResult['analysisDimensions'] {
    return [
      {
        name: '语义理解',
        score: result.semanticAnalysis.intentConfidence,
        findings: [`意图: ${result.semanticAnalysis.intent}`, `实体数: ${result.semanticAnalysis.entities.length}`],
      },
      {
        name: '领域知识',
        score: result.domainAnalysis?.domainConfidence ?? 0.7,
        findings: result.domainAnalysis?.keyIngredients.map((i) => i.name) ?? [],
      },
      {
        name: '逻辑推理',
        score: result.logicalReasoning.confidence,
        findings: [`推理步数: ${result.logicalReasoning.steps.length}`],
      },
      {
        name: '上下文',
        score: result.contextAnalysis.topicContinuity,
        findings: [`连续度: ${result.contextAnalysis.topicContinuity}`],
      },
    ];
  }

  private buildAnalysisDimensionsFromScratch(
    semantic: SemanticAnalysis,
    domain: DomainAnalysis,
  ): MultiDimensionResult['analysisDimensions'] {
    return [
      {
        name: '🔍 语义解析',
        score: semantic.intentConfidence,
        findings: [
          `意图类型: ${semantic.intent}`,
          `实体数量: ${semantic.entities.length}`,
          `关键词: ${semantic.keywords.slice(0, 3).join(', ')}`,
        ],
      },
      {
        name: '🧪 领域知识',
        score: domain.domainConfidence,
        findings: [
          `原料数: ${domain.keyIngredients.length}`,
          `功效: ${domain.targetEfficacy.join('/') || '未明确'}`,
          `剂型: ${domain.dosageForm || '未指定'}`,
        ],
      },
      {
        name: '⚖️ 法规合规',
        score: domain.regulatoryContext ? 0.85 : 0.3,
        findings: [domain.regulatoryContext ? `已识别: ${domain.regulatoryContext}` : '无显式法规提及'],
      },
      {
        name: '⚙️ 工艺路线',
        score: domain.processKeywords.length > 0 ? 0.75 : 0.3,
        findings:
          domain.processKeywords.length > 0 ? [`工艺词: ${domain.processKeywords.join(', ')}`] : ['待分析具体工艺'],
      },
      {
        name: '🛡️ 安全评估',
        score: domain.safetyConcerns.length > 0 ? 0.8 : 0.4,
        findings: domain.safetyConcerns.length > 0 ? [`关注项: ${domain.safetyConcerns.join(', ')}`] : ['需进一步评估'],
      },
      { name: '💰 成本市场', score: 0.45, findings: ['建议在后续对话中深入探讨'] },
    ];
  }

  getStatus(): { enabled: boolean; model: string; version: string } {
    return {
      enabled: true,
      model: 'deep-thinking-v2-multi-dimensional',
      version: '2.0.0',
    };
  }
}

