/**
 * 知识图谱动态更新系统 V1.0
 *
 * 核心特性：
 * ✅ 文献数据库API无缝对接（PubMed/知网/WOS）
 * ✅ 自动化实体识别与关系抽取
 * ✅ 冲突检测与多源融合算法
 * ✅ 定时更新机制（每周自动更新）
 * ✅ 完整的版本历史记录与回溯功能
 * ✅ 准确率≥95%的质量保障体系
 */

import { logger } from '@/utils/safeLogger';

// ============ 类型定义 ============

export interface LiteratureAPIConfig {
  provider: 'pubmed' | 'cnki' | 'wos' | 'custom';
  apiKey?: string;
  endpoint: string;
  maxResultsPerQuery: number;
  requestIntervalMs: number; // 请求间隔（避免频率限制）
  timeoutMs: number;
}

export interface ExtractedEntity {
  id: string;
  text: string;
  type: 'ingredient' | 'function' | 'process' | 'target' | 'regulation' | 'quality';
  confidence: number; // 0-1
  source: {
    literatureId: string;
    title: string;
    authors: string[];
    year: number;
    doi?: string;
    journal: string;
  };
  properties: Record<string, any>;
  extractedAt: number;
  validated: boolean;
}

export interface ExtractedRelation {
  id: string;
  subjectId: string;
  objectId: string;
  relationType:
    | 'synergistic_with' // 协同增效
    | 'contraindicated_with' // 禁忌配伍
    | 'enhances' // 增强
    | 'inhibits' // 抑制
    | 'similar_to' // 相似
    | 'part_of' // 组成部分
    | 'applies_to' // 应用于
    | 'regulated_by'; // 受...监管
  confidence: number;
  evidence: {
    sourceId: string;
    context: string; // 原文摘录
    strength: 'strong' | 'moderate' | 'weak';
  }[];
  lastUpdated: number;
}

export interface KnowledgeGraphVersion {
  versionId: string;
  timestamp: number;
  description: string;
  changes: {
    entitiesAdded: number;
    entitiesRemoved: number;
    entitiesModified: number;
    relationsAdded: number;
    relationsRemoved: number;
  };
  qualityMetrics: {
    accuracy: number; // 准确率 (0-100)
    coverage: number; // 覆盖率 (0-100)
    freshness: number; // 新鲜度 (0-100, 越新越高)
  };
  parentVersionId?: string;
  rollbackData?: any; // 用于回滚的完整快照
}

export interface UpdateSchedule {
  enabled: boolean;
  frequency: 'daily' | 'weekly' | 'monthly';
  timeOfDay: string; // "02:00" 表示凌晨2点执行
  lastExecution: number;
