import { logger } from '@/utils/safeLogger'
/**
 * 三级缓存与预计算架构 V4.0
 *
 * 核心特性：
 * - L1: 内存LRU缓存 (最快, 容量最小)
 * - L2: 预计算结果缓存 (热门查询)
 * - L3: 持久化存储缓存 (跨会话)
 * - 智能预计算引擎 (基于用户行为模式)
 * - 目标响应时间 ≤80ms
 */

// ============ 缓存接口定义 ============

export interface CacheEntry<T> {
  data: T
  timestamp: number
  ttl: number // 毫秒
  accessCount: number
  lastAccessTime: number
  sizeBytes: number // 估算内存占用
}

export interface CacheStats {
  level: 'L1' | 'L2' | 'L3'
  hits: number
  misses: number
  hitRate: number
  avgAccessTimeMs: number
  memoryUsageMB: number
  evictionCount: number
}

export interface PrecomputeTask {
  id: string
  query: string
  priority: number // 1-10 (10最高)
  frequency: number // 出现频率
  lastRequested: number
  status: 'pending' | 'computing' | 'completed' | 'failed'
  result?: any
  error?: string
  computeTime?: number
}

export interface PrecomputeConfig {
  maxQueueSize: number
  computeIntervalMs: number
  minFrequencyThreshold: number
  maxConcurrentComputes: number
  enablePredictivePrecomputation: boolean
}

export interface ThreeLevelCacheStats {
  l1Hits: number
  l1Misses: number
  l2Hits: number
  l2Misses: number
  l3Hits: number
  l3Misses: number
  totalRequests: number
  hitRate: number
  avgResponseTimeMs: number
  memoryUsageMB: number
}

// ============ L1 内存缓存 (LRU) ============

export class L1MemoryCache<T> {
  private cache: Map<string, CacheEntry<T>>
  private maxSize: number
  private defaultTTL: number
  private stats: { hits: number; misses: number }

  constructor(maxSize = 500, defaultTTL = 5 * 60 * 1000) {
    this.cache = new Map()
    this.maxSize = maxSize
    this.defaultTTL = defaultTTL
    this.stats = { hits: 0, misses: 0 }
  }

  get(key: string): T | null {
    const entry = this.cache.get(key)

    if (!entry) {
      this.stats.misses++
      return null
    }

    if (this.isExpired(entry)) {
      this.cache.delete(key)
      this.stats.misses++
      return null
    }

    entry.accessCount++
    entry.lastAccessTime = Date.now()
    this.stats.hits++

    // LRU: 移动到末尾(最近访问)
    this.cache.delete(key)
    this.cache.set(key, entry)

    return entry.data
  }

  set(key: string, data: T, ttl?: number): void {
    if (this.cache.size >= this.maxSize) {
      this.evictLRU()
    }

    const entry: CacheEntry<T> = {
      data,
      timestamp: Date.now(),
      ttl: ttl || this.defaultTTL,
      accessCount: 1,
      lastAccessTime: Date.now(),
      sizeBytes: this.estimateSize(data),
    }

    this.cache.set(key, entry)
  }

  has(key: string): boolean {
    const entry = this.cache.get(key)
    return !!entry && !this.isExpired(entry)
  }

  delete(key: string): boolean {
    return this.cache.delete(key)
  }

  clear(): void {
    this.cache.clear()
    this.stats = { hits: 0, misses: 0 }
  }

  getStats(): CacheStats {
    const total = this.stats.hits + this.stats.misses
    return {
      level: 'L1',
      hits: this.stats.hits,
      misses: this.stats.misses,
      hitRate: total > 0 ? this.stats.hits / total : 0,
      avgAccessTimeMs: 0.01, // L1 极快(<0.1ms)
      memoryUsageMB: this.calculateMemoryUsage(),
      evictionCount: 0,
    }
  }

  private isExpired(entry: CacheEntry<T>): boolean {
    return Date.now() - entry.timestamp > entry.ttl
  }

  private evictLRU(): void {
    // Map保持插入顺序，第一个元素是最久未访问的
    const firstKey = this.cache.keys().next().value
    if (firstKey) {
      this.cache.delete(firstKey)
    }
  }

  private estimateSize(data: T): number {
    try {
      const serialized = JSON.stringify(data)
      return new Blob([serialized]).size
    } catch {
      return 1024 // 默认估算1KB
    }
  }

  private calculateMemoryUsage(): number {
    let totalSize = 0
    this.cache.forEach(entry => {
      totalSize += entry.sizeBytes
    })
    return totalSize / (1024 * 1024) // 转换为MB
  }
}

// ============ L2 预计算缓存 ============

export class L2PrecomputeCache<T> {
  private cache: Map<string, CacheEntry<T>>
  private precomputeQueue: PrecomputeTask[]
  private config: PrecomputeConfig
  private computeFunction: (query: string) => Promise<T>
  private intervalId: NodeJS.Timeout | null
  private stats: { hits: number; misses: number; computes: number }

  constructor(
    computeFunction: (query: string) => Promise<T>,
    config?: Partial<PrecomputeConfig>,
  ) {
    this.cache = new Map()
    this.precomputeQueue = []
    this.computeFunction = computeFunction
    this.config = {
      maxQueueSize: 100,
      computeIntervalMs: 60000, // 每分钟检查一次
      minFrequencyThreshold: 3,
      maxConcurrentComputes: 3,
      enablePredictivePrecomputation: true,
      ...config,
    }
    this.intervalId = null
    this.stats = { hits: 0, misses: 0, computes: 0 }

    this.startPrecomputeWorker()
  }

  async get(query: string): Promise<T | null> {
    const cacheKey = this.generateKey(query)
    const entry = this.cache.get(cacheKey)

    if (entry && !this.isExpired(entry)) {
      entry.accessCount++
      this.stats.hits++
      return entry.data
    }

    this.stats.misses++

    // 记录查询以供预计算
    this.recordQuery(query)

    return null
  }

  async set(query: string, data: T, ttl = 30 * 60 * 1000): Promise<void> {
    const cacheKey = this.generateKey(query)

    this.cache.set(cacheKey, {
      data,
      timestamp: Date.now(),
      ttl,
      accessCount: 1,
      lastAccessTime: Date.now(),
      sizeBytes: this.estimateSize(data),
    })
  }

  private recordQuery(query: string): void {
    const existingTask = this.precomputeQueue.find(t => t.query === query)

    if (existingTask) {
      existingTask.frequency++
      existingTask.lastRequested = Date.now()

      // 动态提升优先级
      if (existingTask.frequency >= this.config.minFrequencyThreshold) {
        existingTask.priority = Math.min(10, existingTask.priority + 1)
      }
    } else if (this.precomputeQueue.length < this.config.maxQueueSize) {
      this.precomputeQueue.push({
        id: `pre-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`,
        query,
        priority: 1,
        frequency: 1,
        lastRequested: Date.now(),
        status: 'pending',
      })
    }
  }

  private startPrecomputeWorker(): void {
    if (this.intervalId) return

    this.intervalId = setInterval(async () => {
      await this.processPrecomputeQueue()
    }, this.config.computeIntervalMs)
  }

  private async processPrecomputeQueue(): Promise<void> {
    if (!this.config.enablePredictivePrecomputation) return

    // 按优先级和频率排序
    this.precomputeQueue.sort((a, b) => {
      if (b.priority !== a.priority) return b.priority - a.priority
      return b.frequency - a.frequency
    })

    let concurrentComputes = 0

    for (const task of this.precomputeQueue) {
      if (task.status !== 'pending') continue
      if (task.frequency < this.config.minFrequencyThreshold) continue
      if (concurrentComputes >= this.config.maxConcurrentComputes) break

      task.status = 'computing'
      concurrentComputes++

      this.computeWithTimeout(task).catch(error => {
        logger.warn(`[L2Cache] 预计算失败: ${task.query}`, error.message)
        task.status = 'failed'
        task.error = error.message
      })
    }
  }

  private async computeWithTimeout(task: PrecomputeTask): Promise<void> {
    const startTime = performance.now()

    try {
      const result = await Promise.race([
        this.computeFunction(task.query),
        new Promise<never>((_, reject) =>
          setTimeout(() => reject(new Error('预计算超时')), 30000),
        ),
      ])

      task.status = 'completed'
      task.result = result
      task.computeTime = performance.now() - startTime

      await this.set(task.query, result)
      this.stats.computes++

      logger.log(`[L2Cache] ✅ 预计算完成 (${task.computeTime?.toFixed(0)}ms):`, task.query.substring(0, 50))

    } catch (error) {
      task.status = 'failed'
      task.error = error instanceof Error ? error.message : String(error)
    }
  }

  getStats(): CacheStats {
    const total = this.stats.hits + this.stats.misses
    return {
      level: 'L2',
      hits: this.stats.hits,
      misses: this.stats.misses,
      hitRate: total > 0 ? this.stats.hits / total : 0,
      avgAccessTimeMs: 5, // L2 较快(1-10ms)
      memoryUsageMB: this.calculateMemoryUsage(),
      evictionCount: 0,
    }
  }

  stop(): void {
    if (this.intervalId) {
      clearInterval(this.intervalId)
      this.intervalId = null
    }
  }

  private generateKey(query: string): string {
    return `l2-${query.substring(0, 100).toLowerCase().replace(/\s+/g, '_')}`
  }

  private isExpired(entry: CacheEntry<any>): boolean {
    return Date.now() - entry.timestamp > entry.ttl
  }

  private estimateSize(data: any): number {
    try {
      return new Blob([JSON.stringify(data)]).size
    } catch {
      return 2048
    }
  }

  private calculateMemoryUsage(): number {
    let totalSize = 0
    this.cache.forEach(entry => {
      totalSize += entry.sizeBytes
    })
    return totalSize / (1024 * 1024)
  }
}

// ============ L3 持久化缓存 (LocalStorage) ============

export class L3PersistentCache<T> {
  private prefix: string
  private defaultTTL: number
  private maxSize: number
  private stats: { hits: number; misses: number }

  constructor(prefix = 'pie_v4', maxSize = 50, defaultTTL = 24 * 60 * 60 * 1000) {
    this.prefix = prefix
    this.maxSize = maxSize
    this.defaultTTL = defaultTTL
    this.stats = { hits: 0, misses: 0 }
  }

  async get(key: string): Promise<T | null> {
    try {
      const fullKey = `${this.prefix}_${key}`
      const item = localStorage.getItem(fullKey)

      if (!item) {
        this.stats.misses++
        return null
      }

      const entry: CacheEntry<T> & { key: string } = JSON.parse(item)

      if (this.isExpired(entry)) {
        localStorage.removeItem(fullKey)
        this.stats.misses++
        return null
      }

      entry.accessCount++
      entry.lastAccessTime = Date.now()
      localStorage.setItem(fullKey, JSON.stringify(entry))

      this.stats.hits++
      return entry.data

    } catch (error) {
      logger.warn('[L3Cache] 读取失败:', error)
      this.stats.misses++
      return null
    }
  }

  async set(key: string, data: T, ttl?: number): Promise<void> {
    try {
      this.ensureCapacity()

      const fullKey = `${this.prefix}_${key}`
      const entry: CacheEntry<T> & { key: string } = {
        key,
        data,
        timestamp: Date.now(),
        ttl: ttl || this.defaultTTL,
        accessCount: 1,
        lastAccessTime: Date.now(),
        sizeBytes: this.estimateSize(data),
      }

      localStorage.setItem(fullKey, JSON.stringify(entry))

    } catch (error) {
      logger.warn('[L3Cache] 写入失败:', error)
    }
  }

  getStats(): CacheStats {
    const total = this.stats.hits + this.stats.misses
    return {
      level: 'L3',
      hits: this.stats.hits,
      misses: this.stats.misses,
      hitRate: total > 0 ? this.stats.hits / total : 0,
      avgAccessTimeMs: 20, // L3 最慢(10-30ms, IO操作)
      memoryUsageMB: this.calculateLocalStorageUsage(),
      evictionCount: 0,
    }
  }

  clear(): void {
    const keysToRemove: string[] = []

    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i)
      if (key?.startsWith(this.prefix)) {
        keysToRemove.push(key)
      }
    }

    keysToRemove.forEach(key => localStorage.removeItem(key))
    this.stats = { hits: 0, misses: 0 }
  }

  private isExpired(entry: CacheEntry<any>): boolean {
    return Date.now() - entry.timestamp > entry.ttl
  }

  private ensureCapacity(): void {
    const currentCount = this.getPrefixedItemCount()

    if (currentCount >= this.maxSize) {
      this.evictLRUItems(Math.ceil(this.maxSize * 0.2)) // 清理20%空间
    }
  }

  private getPrefixedItemCount(): number {
    let count = 0
    for (let i = 0; i < localStorage.length; i++) {
      if (localStorage.key(i)?.startsWith(this.prefix)) {
        count++
      }
    }
    return count
  }

  private evictLRUItems(count: number): void {
    const items: { key: string; lastAccessTime: number }[] = []

    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i)
      if (key?.startsWith(this.prefix)) {
        try {
          const item = JSON.parse(localStorage.getItem(key) || '{}')
          items.push({ key, lastAccessTime: item.lastAccessTime || 0 })
        } catch { /* 忽略解析错误 */ }
      }
    }

    items.sort((a, b) => a.lastAccessTime - b.lastAccessTime)
    items.slice(0, count).forEach(item => {
      localStorage.removeItem(item.key)
    })
  }

  private estimateSize(data: T): number {
    try {
      return new Blob([JSON.stringify(data)]).size
    } catch {
      return 4096
    }
  }

  private calculateLocalStorageUsage(): number {
    let totalSize = 0
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i)
      if (key?.startsWith(this.prefix)) {
        totalSize += (localStorage.getItem(key) || '').length * 2 // UTF-16编码
      }
    }
    return totalSize / (1024 * 1024)
  }
}

// ============ 三级缓存管理器 ============

export class ThreeLevelCacheManager<T> {
  private l1Cache: L1MemoryCache<T>
  private l2Cache: L2PrecomputeCache<T> | null
  private l3Cache: L3PersistentCache<T>
  private globalStats: ThreeLevelCacheStats

  constructor(
    computeFunction?: (query: string) => Promise<T>,
    options?: {
      l1MaxSize?: number
      l1DefaultTTL?: number
      enableL2Precompute?: boolean
      l3MaxSize?: number
      l3DefaultTTL?: number
    },
  ) {
    this.l1Cache = new L1MemoryCache<T>(
      options?.l1MaxSize || 500,
      options?.l1DefaultTTL || 5 * 60 * 1000,
    )

    this.l2Cache = options?.enableL2Precompute && computeFunction
      ? new L2PrecomputeCache<T>(computeFunction)
      : null

    this.l3Cache = new L3PersistentCache<T>(
      undefined,
      options?.l3MaxSize || 50,
      options?.l3DefaultTTL || 24 * 60 * 60 * 1000,
    )

    this.globalStats = {
      l1Hits: 0,
      l1Misses: 0,
      l2Hits: 0,
      l2Misses: 0,
      l3Hits: 0,
      l3Misses: 0,
      totalRequests: 0,
      hitRate: 0,
      avgResponseTimeMs: 0,
      memoryUsageMB: 0,
    }
  }

  async get(query: string): Promise<{ data: T | null; source: 'L1' | 'L2' | 'L3' | 'miss'; timeMs: number }> {
    const startTime = performance.now()
    this.globalStats.totalRequests++

    // Level 1: 内存缓存 (最快)
    const l1Result = this.l1Cache.get(query)
    if (l1Result) {
      this.globalStats.l1Hits++
      this.updateGlobalStats(performance.now() - startTime, 'L1')
      return { data: l1Result, source: 'L1', timeMs: performance.now() - startTime }
    }
    this.globalStats.l1Misses++

    // Level 2: 预计算缓存
    if (this.l2Cache) {
      const l2Result = await this.l2Cache.get(query)
      if (l2Result) {
        this.globalStats.l2Hits++
        // 回填L1缓存
        this.l1Cache.set(query, l2Result)
        this.updateGlobalStats(performance.now() - startTime, 'L2')
        return { data: l2Result, source: 'L2', timeMs: performance.now() - startTime }
      }
      this.globalStats.l2Misses++
    }

    // Level 3: 持久化缓存
    const l3Result = await this.l3Cache.get(query)
    if (l3Result) {
      this.globalStats.l3Hits++
      // 回填L1和L2缓存
      this.l1Cache.set(query, l3Result)
      if (this.l2Cache) await this.l2Cache.set(query, l3Result)
      this.updateGlobalStats(performance.now() - startTime, 'L3')
      return { data: l3Result, source: 'L3', timeMs: performance.now() - startTime }
    }
    this.globalStats.l3Misses++

    this.updateGlobalStats(performance.now() - startTime, 'miss')
    return { data: null, source: 'miss', timeMs: performance.now() - startTime }
  }

  async set(query: string, data: T, options?: { l1TTL?: number; l2TTL?: number; l3TTL?: number }): Promise<void> {
    this.l1Cache.set(query, data, options?.l1TTL)
    if (this.l2Cache) await this.l2Cache.set(query, data, options?.l2TTL)
    await this.l3Cache.set(query, data, options?.l3TTL)
  }

  getFullStats(): { l1: CacheStats; l2: CacheStats | null; l3: CacheStats; global: ThreeLevelCacheStats } {
    return {
      l1: this.l1Cache.getStats(),
      l2: this.l2Cache?.getStats() || null,
      l3: this.l3Cache.getStats(),
      global: this.globalStats,
    }
  }

  clearAll(): void {
    this.l1Cache.clear()
    this.l2Cache?.stop()
    this.l3Cache.clear()
    this.globalStats = {
      l1Hits: 0, l1Misses: 0, l2Hits: 0, l2Misses: 0,
      l3Hits: 0, l3Misses: 0, totalRequests: 0,
      hitRate: 0, avgResponseTimeMs: 0, memoryUsageMB: 0,
    }
  }

  private updateGlobalStats(timeMs: number, _source: 'L1' | 'L2' | 'L3' | 'miss'): void {
    const alpha = 0.3 // 指数移动平均系数
    this.globalStats.avgResponseTimeMs = this.globalStats.avgResponseTimeMs === 0
      ? timeMs
      : alpha * timeMs + (1 - alpha) * this.globalStats.avgResponseTimeMs

    const totalHits = this.globalStats.l1Hits + this.globalStats.l2Hits + this.globalStats.l3Hits
    const totalRequests = this.globalStats.totalRequests
    this.globalStats.hitRate = totalRequests > 0 ? totalHits / totalRequests : 0

    this.globalStats.memoryUsageMB =
      this.l1Cache.getStats().memoryUsageMB +
      (this.l2Cache?.getStats().memoryUsageMB || 0) +
      this.l3Cache.getStats().memoryUsageMB
  }
}

import { logger } from '@/utils/safeLogger'
import { storageService } from './storageService'

export type HotkeyAction =
  | 'sendMessage'
  | 'newLine'
  | 'toggleDeepThinking'
  | 'toggleSmartSearch'
  | 'clearInput'

export interface HotkeyConfig {
  key: string
  ctrl?: boolean
  shift?: boolean
  alt?: boolean
  meta?: boolean
}

export interface InputBehaviorConfig {
  autoFocus: boolean
  autoResize: boolean
  minHeight: number
  maxHeight: number
  enterToSend: boolean
  showCharCount: boolean
  showSuggestions: boolean
}

/**
 * 用户健康画像相关类型
 */
export type HealthGoal =
  | 'blood_sugar_control'    // 控血糖
  | 'blood_pressure_control' // 控血压
  | 'weight_management'      // 体重管理
  | 'sleep_improvement'      // 改善睡眠
  | 'immune_boost'           // 增强免疫
  | 'antioxidant'            // 抗氧化
  | 'liver_protection'       // 护肝
  | 'digestive_health'       // 消化健康
  | 'anti_fatigue'           // 抗疲劳
  | 'other'

export type AllergenType =
  | 'peanuts'
  | 'shellfish'
  | 'dairy'
  | 'gluten'
  | 'soy'
  | 'eggs'
  | 'tree_nuts'
  | 'sesame'
  | 'mugwort'        // 菊科植物（苦瓜、桑叶过敏源）
  | 'other'

export type DietRestriction =
  | 'vegetarian'
  | 'vegan'
  | 'halal'
  | 'kosher'
  | 'low_sugar'
  | 'low_fat'
  | 'low_sodium'
  | 'no_alcohol'

export interface UserProfileContext {
  /** 健康目标列表 */
  healthGoals?: HealthGoal[]
  /** 过敏原列表 */
  allergens?: AllergenType[]
  /** 饮食限制 */
  dietRestrictions?: DietRestriction[]
  /** 年龄范围 */
  ageRange?: 'under_18' | '18_30' | '31_50' | '51_70' | 'over_70'
  /** 体质倾向（中医体质） */
  constitutionType?: string
  /** 特殊健康状况备注 */
  healthNotes?: string
  /** 最近一次对话提取的偏好摘要 */
  recentPreferences?: {
    targetedCondition?: string
    preferredIngredients?: string[]
    avoidedIngredients?: string[]
    dosagePreference?: string
    extractedAt: number
  }
}

export interface UserPreferences {
  hotkeys: Partial<Record<HotkeyAction, HotkeyConfig>>
  inputBehavior: InputBehaviorConfig
  theme?: 'light' | 'dark' | 'system'
  /** 用户健康画像上下文 */
  userProfile?: UserProfileContext
}

const STORAGE_KEY = 'user-preferences'
const CURRENT_VERSION = 1

const DEFAULT_HOTKEYS: Partial<Record<HotkeyAction, HotkeyConfig>> = {
  sendMessage: { key: 'Enter' },
  newLine: { key: 'Enter', shift: true },
  toggleDeepThinking: { key: 'D', ctrl: true },
  toggleSmartSearch: { key: 'S', ctrl: true },
  clearInput: { key: 'Escape' },
}

const DEFAULT_INPUT_BEHAVIOR: InputBehaviorConfig = {
  autoFocus: true,
  autoResize: true,
  minHeight: 40,
  maxHeight: 160,
  enterToSend: true,
  showCharCount: true,
  showSuggestions: true,
}

const DEFAULT_PREFERENCES: UserPreferences = {
  hotkeys: DEFAULT_HOTKEYS,
  inputBehavior: DEFAULT_INPUT_BEHAVIOR,
  theme: 'system',
}

export class UserPreferencesError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'UserPreferencesError'
  }
}

export class UserPreferencesService {
  private preferences: UserPreferences | null = null
  private listeners: ((preferences: UserPreferences) => void)[] = []

  constructor() {
    this.loadPreferences()
  }

  private loadPreferences(): void {
    try {
      const stored = storageService.get<UserPreferences>(STORAGE_KEY)
      if (stored) {
        this.preferences = this.mergeWithDefaults(stored)
        logger.info('[UserPreferencesService] 从存储加载偏好设置成功')
      } else {
        this.preferences = { ...DEFAULT_PREFERENCES }
        logger.info('[UserPreferencesService] 使用默认偏好设置')
      }
    } catch (error) {
      logger.error('[UserPreferencesService] 加载偏好设置失败，使用默认值:', error)
      this.preferences = { ...DEFAULT_PREFERENCES }
    }
  }

  private mergeWithDefaults(partial: Partial<UserPreferences>): UserPreferences {
    return {
      ...DEFAULT_PREFERENCES,
      ...partial,
      hotkeys: { ...DEFAULT_PREFERENCES.hotkeys, ...partial.hotkeys },
      inputBehavior: { ...DEFAULT_PREFERENCES.inputBehavior, ...partial.inputBehavior },
      userProfile: partial.userProfile
        ? { ...((DEFAULT_PREFERENCES.userProfile ?? {} as UserProfileContext)), ...partial.userProfile }
        : this.preferences?.userProfile ?? undefined,
    }
  }

  private savePreferences(): void {
    if (!this.preferences) {
      throw new UserPreferencesError('偏好设置未初始化')
    }

    try {
      storageService.set(STORAGE_KEY, this.preferences)
      logger.info('[UserPreferencesService] 偏好设置保存成功')
      this.notifyListeners()
    } catch (error) {
      logger.error('[UserPreferencesService] 保存偏好设置失败:', error)
      throw new UserPreferencesError('保存偏好设置失败')
    }
  }

  private notifyListeners(): void {
    if (!this.preferences) return
    this.listeners.forEach(listener => {
      try {
        listener(this.preferences!)
      } catch (error) {
        logger.error('[UserPreferencesService] 通知监听器失败:', error)
      }
    })
  }

  getPreferences(): UserPreferences {
    if (!this.preferences) {
      this.preferences = { ...DEFAULT_PREFERENCES }
    }
    return { ...this.preferences }
  }

  setHotkey(action: HotkeyAction, config: HotkeyConfig): void {
    if (!this.preferences) {
      this.preferences = { ...DEFAULT_PREFERENCES }
    }
    this.preferences.hotkeys[action] = { ...config }
    this.savePreferences()
  }

  getHotkey(action: HotkeyAction): HotkeyConfig | undefined {
    if (!this.preferences) {
      this.preferences = { ...DEFAULT_PREFERENCES }
    }
    const config = this.preferences.hotkeys[action]
    return config ? { ...config } : undefined
  }

  resetHotkey(action: HotkeyAction): void {
    if (!this.preferences) {
      this.preferences = { ...DEFAULT_PREFERENCES }
    }
    this.preferences.hotkeys[action] = DEFAULT_PREFERENCES.hotkeys[action]
    this.savePreferences()
  }

  resetAllHotkeys(): void {
    if (!this.preferences) {
      this.preferences = { ...DEFAULT_PREFERENCES }
    }
    this.preferences.hotkeys = { ...DEFAULT_HOTKEYS }
    this.savePreferences()
  }

  setInputBehavior(config: Partial<InputBehaviorConfig>): void {
    if (!this.preferences) {
      this.preferences = { ...DEFAULT_PREFERENCES }
    }
    this.preferences.inputBehavior = { ...this.preferences.inputBehavior, ...config }
    this.savePreferences()
  }

  getInputBehavior(): InputBehaviorConfig {
    if (!this.preferences) {
      this.preferences = { ...DEFAULT_PREFERENCES }
    }
    return { ...this.preferences.inputBehavior }
  }

  setTheme(theme: 'light' | 'dark' | 'system'): void {
    if (!this.preferences) {
      this.preferences = { ...DEFAULT_PREFERENCES }
    }
    this.preferences.theme = theme
    this.savePreferences()
  }

  getTheme(): 'light' | 'dark' | 'system' {
    if (!this.preferences) {
      this.preferences = { ...DEFAULT_PREFERENCES }
    }
    return this.preferences.theme || 'system'
  }

  resetAll(): void {
    this.preferences = { ...DEFAULT_PREFERENCES }
    this.savePreferences()
    logger.info('[UserPreferencesService] 所有偏好设置已重置为默认值')
  }

  subscribe(listener: (preferences: UserPreferences) => void): () => void {
    this.listeners.push(listener)
    if (this.preferences) {
      try {
        listener(this.preferences)
      } catch (error) {
        logger.error('[UserPreferencesService] 初始通知监听器失败:', error)
      }
    }

    return () => {
      const index = this.listeners.indexOf(listener)
      if (index > -1) {
        this.listeners.splice(index, 1)
      }
    }
  }

  exportPreferences(): string {
    if (!this.preferences) {
      this.preferences = { ...DEFAULT_PREFERENCES }
    }
    return JSON.stringify(this.preferences, null, 2)
  }

  importPreferences(jsonString: string): void {
    try {
      const imported = JSON.parse(jsonString)
      this.preferences = this.mergeWithDefaults(imported)
      this.savePreferences()
      logger.info('[UserPreferencesService] 偏好设置导入成功')
    } catch (error) {
      logger.error('[UserPreferencesService] 导入偏好设置失败:', error)
      throw new UserPreferencesError('导入的偏好设置格式无效')
    }
  }

  validateHotkey(config: HotkeyConfig): boolean {
    if (!config.key || config.key.trim().length === 0) {
      return false
    }
    return true
  }

  /**
   * 获取用户健康画像上下文
   */
  getUserProfile(): UserProfileContext | undefined {
    return this.preferences?.userProfile
  }

  /**
   * 设置健康目标
   */
  setHealthGoals(goals: HealthGoal[]): void {
    if (!this.preferences) {
      this.preferences = { ...DEFAULT_PREFERENCES }
    }
    if (!this.preferences.userProfile) {
      this.preferences.userProfile = {} as UserProfileContext
    }
    this.preferences.userProfile.healthGoals = goals
    this.savePreferences()
  }

  /**
   * 设置过敏原
   */
  setAllergens(allergens: AllergenType[]): void {
    if (!this.preferences) {
      this.preferences = { ...DEFAULT_PREFERENCES }
    }
    if (!this.preferences.userProfile) {
      this.preferences.userProfile = {} as UserProfileContext
    }
    this.preferences.userProfile.allergens = allergens
    this.savePreferences()
  }

  /**
   * 设置饮食限制
   */
  setDietRestrictions(restrictions: DietRestriction[]): void {
    if (!this.preferences) {
      this.preferences = { ...DEFAULT_PREFERENCES }
    }
    if (!this.preferences.userProfile) {
      this.preferences.userProfile = {} as UserProfileContext
    }
    this.preferences.userProfile.dietRestrictions = restrictions
    this.savePreferences()
  }

  /**
   * 设置体质倾向与健康备注
   */
  setConstitution(constitutionType: string, healthNotes?: string): void {
    if (!this.preferences) {
      this.preferences = { ...DEFAULT_PREFERENCES }
    }
    if (!this.preferences.userProfile) {
      this.preferences.userProfile = {} as UserProfileContext
    }
    this.preferences.userProfile.constitutionType = constitutionType
    if (healthNotes !== undefined) {
      this.preferences.userProfile.healthNotes = healthNotes
    }
    this.savePreferences()
  }

  /**
   * 从对话内容中自动提取偏好并更新画像
   */
  extractAndSavePreferencesFromContent(content: string): void {
    if (!this.preferences) {
      this.preferences = { ...DEFAULT_PREFERENCES }
    }
    if (!this.preferences.userProfile) {
      this.preferences.userProfile = {} as UserProfileContext
    }

    // 提取健康目标
    const goalMappings: Array<{ pattern: RegExp; goal: HealthGoal }> = [
      { pattern: /血糖|高血糖|糖尿病/i, goal: 'blood_sugar_control' },
      { pattern: /血压|高血压/i, goal: 'blood_pressure_control' },
      { pattern: /减肥|体重|瘦身/i, goal: 'weight_management' },
      { pattern: /睡眠|失眠|助眠/i, goal: 'sleep_improvement' },
      { pattern: /免疫|增强免疫/i, goal: 'immune_boost' },
      { pattern: /抗氧化|抗衰老/i, goal: 'antioxidant' },
      { pattern: /护肝|肝脏/i, goal: 'liver_protection' },
      { pattern: /消化|肠胃/i, goal: 'digestive_health' },
      { pattern: /疲劳|精力/i, goal: 'anti_fatigue' },
    ]

    const detectedGoals: HealthGoal[] = []
    for (const { pattern, goal } of goalMappings) {
      if (pattern.test(content)) {
        detectedGoals.push(goal)
      }
    }
    if (detectedGoals.length > 0) {
      this.preferences.userProfile.healthGoals = [...new Set([...(this.preferences.userProfile.healthGoals ?? []), ...detectedGoals])]
    }

    // 提取过敏相关信息
    const allergenMappings: Array<{ pattern: RegExp; allergen: AllergenType }> = [
      { pattern: /菊科|苦瓜|桑叶过敏/i, allergen: 'mugwort' },
      { pattern: /花生过敏/i, allergen: 'peanuts' },
      { pattern: /海鲜|虾蟹/i, allergen: 'shellfish' },
      { pattern: /乳糖|牛奶/i, allergen: 'dairy' },
    ]

    const detectedAllergens: AllergenType[] = []
    for (const { pattern, allergen } of allergenMappings) {
      if (pattern.test(content)) {
        detectedAllergens.push(allergen)
      }
    }
    if (detectedAllergens.length > 0) {
      this.preferences.userProfile.allergens = [...new Set([...(this.preferences.userProfile.allergens ?? []), ...detectedAllergens])]
    }

    // 记录最近偏好摘要
    this.preferences.userProfile.recentPreferences = {
      targetedCondition: detectedGoals[0] ?? 'other',
      preferredIngredients: [],
      avoidedIngredients: detectedAllergens,
      dosagePreference: 'standard',
      extractedAt: Date.now(),
    }

    this.savePreferences()
    logger.info('[UserPreferencesService] 从对话内容提取并保存偏好:', {
      goals: detectedGoals,
      allergens: detectedAllergens,
    })
  }

  /**
   * 生成用于AI请求的偏好摘要文本
   */
  generatePromptSummary(): string {
    const profile = this.preferences?.userProfile
    if (!profile) return ''

    const parts: string[] = []

    if (profile.healthGoals && profile.healthGoals.length > 0) {
      const goalLabels: Record<HealthGoal, string> = {
        blood_sugar_control: '高血糖/血糖管理',
        blood_pressure_control: '高血压/血压管理',
        weight_management: '体重管理',
        sleep_improvement: '改善睡眠',
        immune_boost: '增强免疫',
        antioxidant: '抗氧化/抗衰老',
        liver_protection: '肝脏养护',
        digestive_health: '消化健康',
        anti_fatigue: '抗疲劳/提升精力',
        other: '其他健康目标',
      }
      parts.push(`健康目标: ${profile.healthGoals.map(g => goalLabels[g]).join('、')}`)
    }

    if (profile.allergens && profile.allergens.length > 0) {
      const allergenLabels: Record<AllergenType, string> = {
        peanuts: '花生',
        shellfish: '海鲜/甲壳类',
        dairy: '乳制品',
        gluten: '麸质',
        soy: '大豆',
        eggs: '鸡蛋',
        tree_nuts: '坚果',
        sesame: '芝麻',
        mugwort: '菊科植物（苦瓜、桑叶等）',
        other: '其他',
      }
      parts.push(`过敏禁忌: ${profile.allergens.map(a => allergenLabels[a]).join('、')}`)
    }

    if (profile.dietRestrictions && profile.dietRestrictions.length > 0) {
      const restrictionLabels: Record<DietRestriction, string> = {
        vegetarian: '素食',
        vegan: '纯素',
        halal: '清真',
        kosher: '洁食',
        low_sugar: '低糖',
        low_fat: '低脂',
        low_sodium: '低盐',
        no_alcohol: '禁酒',
      }
      parts.push(`饮食限制: ${profile.dietRestrictions.map(r => restrictionLabels[r]).join('、')}`)
    }

    if (profile.constitutionType) {
      parts.push(`体质倾向: ${profile.constitutionType}`)
    }

    if (profile.healthNotes) {
      parts.push(`健康状况备注: ${profile.healthNotes}`)
    }

    return parts.join('；')
  }
}

export const userPreferencesService = new UserPreferencesService()
export default userPreferencesService

/**
 * 统一用户画像服务 (Unified User Profile Service)
 *
 * 合并 6 个碎片化偏好系统为单一真相源：
 * ┌─────────────────────────────────────────────────────┐
 * │                  UnifiedUserProfile                 │
 * │  ┌──────────┐  ┌──────────┐  ┌──────────────────┐  │
 * │  │ UI 偏好   │  │ 领域偏好  │  │ 行为推断画像     │  │
 * │  │ ·主题     │  │ ·回复风格 │  │ ·专业度自评      │  │
 * │  │ ·快捷键   │  │ ·技术深度 │  │ ·兴趣领域       │  │
 * │  │ ·输入行为 │  │ ·对话模式 │  │ ·交互习惯       │  │
 * │  └────┬─────┘  └────┬─────┘  └───────┬──────────┘  │
 * │        │              │                │             │
 * │  ←─ userPrefsSvc   ←─ WorkingMemory  ←─ 自动推断    │
 * │       (委托)          (合并)           (新增)        │
 * └─────────────────────────────────────────────────────┘
 *
 * 设计原则：
 * 1. 单一真相源 — 所有组件通过此服务访问用户偏好
 * 2. 向后兼容 — 内部委托给现有 userPreferencesService（UI层）
 * 3. 渐进增强 — 支持从用户行为自动推断隐式偏好
 * 4. 版本化持久化 — localStorage 存储带版本号，支持迁移
 */

import { logger } from '@/utils/safeLogger';
import { userPreferencesService } from './userPreferencesService';
// ===== 类型定义 =====

/** UI 层偏好（委托给 userPreferencesService） */
export interface UIPreferences {
  theme: 'light' | 'dark' | 'system'
  enterToSend: boolean
  showCharCount: boolean
  showSuggestions: boolean
  autoFocus: boolean
}

/** 领域/对话层偏好（原 WorkingMemory.userPreferences 扩展） */
export interface DomainPreferences {
  /** 回复风格：简洁 / 详细 / 学术 */
  responseStyle: 'concise' | 'detailed' | 'academic'
  /** 技术深度：基础 / 中级 / 高级 */
  technicalDepth: 'basic' | 'intermediate' | 'advanced'
  /** 对话模式：标准 / 教学式 / 探索式 */
  dialogMode: 'standard' | 'tutorial' | 'exploratory'
  /** 是否启用共情回应 */
  empathyEnabled: boolean
  /** 是否显示思考过程 */
  showThinkingProcess: boolean
  /** 语言偏好：中文 / 英文 / 自动 */
  languagePreference: 'zh-CN' | 'en' | 'auto'
}

/** 行为推断画像（自动从交互历史中学习） */
export interface InferredProfile {
  /** 自评专业度（0-100，从提问复杂度和术语使用推断） */
  estimatedExpertise: number
  /** 主要兴趣领域标签 */
  primaryInterests: string[]
  /** 平均提问长度（字符） */
  avgQueryLength: number
  /** 偏好的回复长度偏好（从用户对长/短回复的反应推断） */
  preferredResponseLength: 'short' | 'medium' | 'long' | 'unknown'
  /** 是否喜欢结构化输出（列表/表格/分步） */
  prefersStructuredOutput: boolean
  /** 活跃时段（小时，0-23） */
  activeHours: number[]
  /** 总对话轮次 */
  totalTurns: number
  /** 上次活跃时间戳 */
  lastActiveAt: number
}

/** 完整用户画像 */
export interface UserProfile {
  ui: UIPreferences
  domain: DomainPreferences
  inferred: InferredProfile
  /** 配置置创建/更新时间 */
  updatedAt: number
}

/** 用户行为事件（用于自动推断） */
export interface BehaviorEvent {
  type: 'query_sent' | 'response_liked' | 'response_disliked' | 'query_refined'
    | 'long_query' | 'short_query' | 'technical_term_used' | 'follow_up_asked'
    | 'topic_switched' | 'session_long'
  timestamp: number
  metadata?: Record<string, unknown>
}

const STORAGE_KEY = 'unified-user-profile'
const PROFILE_VERSION = 1

const DEFAULT_UI: UIPreferences = {
  theme: 'system',
  enterToSend: true,
  showCharCount: true,
  showSuggestions: true,
  autoFocus: true,
}

const DEFAULT_DOMAIN: DomainPreferences = {
  responseStyle: 'detailed',
  technicalDepth: 'intermediate',
  dialogMode: 'standard',
  empathyEnabled: true,
  showThinkingProcess: true,
  languagePreference: 'zh-CN',
}

const DEFAULT_INFERRED: InferredProfile = {
  estimatedExpertise: 50,
  primaryInterests: [],
  avgQueryLength: 0,
  preferredResponseLength: 'unknown',
  prefersStructuredOutput: false,
  activeHours: [],
  totalTurns: 0,
  lastActiveAt: 0,
}

const DEFAULT_PROFILE: UserProfile = {
  ui: { ...DEFAULT_UI },
  domain: { ...DEFAULT_DOMAIN },
  inferred: { ...DEFAULT_INFERRED },
  updatedAt: Date.now(),
}

// ===== 核心实现 =====

class UnifiedUserProfileManager {
  private profile: UserProfile
  private listeners: ((profile: UserProfile) => void)[] = []
  /** 行为事件缓冲区（用于批量推断） */
  private behaviorBuffer: BehaviorEvent[] = []
  /** 最大缓冲区大小 */
  static readonly MAX_BEHAVIOR_BUFFER = 200
  /** 活跃时段内部 Set（O(1) 查找，替代数组的 O(n) includes） */
  private activeHoursSet = new Set<number>()

  constructor() {
    this.profile = this.loadFromStorage()
  }

  // ===== 核心访问 =====

  /** 获取完整用户画像（只读副本） */
  getProfile(): UserProfile {
    return { ...this.profile }
  }

  /** 获取 UI 偏好 */
  getUI(): UIPreferences {
    return { ...this.profile.ui }
  }

  /** 获取领域偏好 */
  getDomain(): DomainPreferences {
    return { ...this.profile.domain }
  }

  /** 获取推断画像 */
  getInferred(): InferredProfile {
    return { ...this.profile.inferred }
  }

  // ===== UI 偏好操作（延迟同步到原有 userPreferencesService）=====

  /** 延迟加载的 userPreferencesService 引用（避免 ESM 中 require()） */
  private legacyPrefsService: any = null

  /** 异步初始化遗留服务引用 */
  private async initLegacyService(): Promise<void> {
    try {
      const mod = await import('../services/userPreferencesService')
      this.legacyPrefsService = mod.userPreferencesService || mod.default
    } catch {
      this.legacyPrefsService = null
    }
  }

  setUI(partial: Partial<UIPreferences>): void {
    this.profile.ui = { ...this.profile.ui, ...partial }
    this.saveAndNotify()

    // 异步同步到原有 userPreferencesService（不阻塞主流程）
    if (!this.legacyPrefsService) {
      this.initLegacyService().then(() => {
        if (this.legacyPrefsService?.setTheme && partial.theme !== undefined) {
          this.legacyPrefsService.setTheme(partial.theme)
        }
      })
    } else if (partial.theme !== undefined) {
      try { this.legacyPrefsService.setTheme(partial.theme) } catch { /* ignore */ }
    }
  }

  // ===== 领域偏好操作 =====

  setDomain(partial: Partial<DomainPreferences>): void {
    this.profile.domain = { ...this.profile.domain, ...partial }
    this.saveAndNotify()
  }

  /**
   * 快捷设置：一键切换回复风格（单次调用，避免双重通知）
   */
  setResponseStyle(style: DomainPreferences['responseStyle']): void {
    const depthMap: Record<DomainPreferences['responseStyle'], DomainPreferences['technicalDepth']> = {
      concise: 'basic',
      detailed: 'intermediate',
      academic: 'advanced',
    }
    // 单次调用同时设置风格和联动深度，避免两次 saveAndNotify
    this.setDomain({ responseStyle: style, technicalDepth: depthMap[style] || 'intermediate' })
  }

  /**
   * 快捷设置：切换共情开关
   */
  toggleEmpathy(): void {
    this.setDomain({ empathyEnabled: !this.profile.domain.empathyEnabled })
  }

  // ===== 行为推断接口 =====

  /**
   * 记录用户行为事件（供各 hook 在交互时调用）
   */
  recordBehavior(event: BehaviorEvent): void {
    this.behaviorBuffer.push(event)

    // 缓冲区溢出时裁剪
    if (this.behaviorBuffer.length > UnifiedUserProfileManager.MAX_BEHAVIOR_BUFFER) {
      this.behaviorBuffer = this.behaviorBuffer.slice(-100)
    }

    // 每10个事件触发一次批量推断
    if (this.behaviorBuffer.length % 10 === 0) {
      this.runInference()
    }

    // 实时更新基础计数
    if (event.type === 'query_sent') {
      this.profile.inferred.totalTurns++
      this.profile.inferred.lastActiveAt = event.timestamp
      // 更新活跃时段（O(1) Set 操作替代 O(n) includes + O(n log n) sort）
      const hour = new Date(event.timestamp).getHours()
      if (!this.activeHoursSet.has(hour)) {
        this.activeHoursSet.add(hour)
        this.profile.inferred.activeHours = Array.from(this.activeHoursSet).sort((a, b) => a - b)
      }
    }
  }

  /**
   * 手动触发推断（如会话结束时）
   */
  runInference(): void {
    if (this.behaviorBuffer.length < 3) return

    const events = [...this.behaviorBuffer]
    this.updateExpertiseEstimate(events)
    this.updateInterestProfile(events)
    this.updateQueryPattern(events)
    this.updateResponseLengthPreference(events)

    this.profile.updatedAt = Date.now()
    this.saveToStorage()
  }

  // ===== 推断算法 =====

  /**
   * 从行为事件推断专业度评分
   *
   * 算法：
   * - 基础分 50
   * - 使用专业术语 +5/次（上限+20）
   * - 提出追问/跟进 +3/次（上限+15）
   * - 发送长查询(>50字) +2/次（上限+10）
   * - 短查询(<10字)频繁 -1/次（下限-15）
   * - 需要 refine（重新表述）-2/次（下限-10）
   */
  private updateExpertiseEstimate(events: BehaviorEvent[]): void {
    let score = 50
    let termCount = 0
    let followUpCount = 0
    let longQueryCount = 0
    let shortQueryCount = 0
    let refineCount = 0

    for (const e of events) {
      switch (e.type) {
        case 'technical_term_used': termCount++; break
        case 'follow_up_asked': followUpCount++; break
        case 'long_query': longQueryCount++; break
        case 'short_query': shortQueryCount++; break
        case 'query_refined': refineCount++; break
      }
    }

    score += Math.min(termCount * 5, 20)
    score += Math.min(followUpCount * 3, 15)
    score += Math.min(longQueryCount * 2, 10)
    score -= Math.min(shortQueryCount * 1, 15)
    score -= Math.min(refineCount * 2, 10)

    // 平滑更新（指数移动平均，α=0.3）
    const prevScore = this.profile.inferred.estimatedExpertise
    this.profile.inferred.estimatedExpertise = Math.round(prevScore * 0.7 + score * 0.3)
    this.profile.inferred.estimatedExpertise = Math.max(0, Math.min(100, this.profile.inferred.estimatedExpertise))
  }

  /**
   * 更新兴趣领域画像
   */
  private updateInterestProfile(events: BehaviorEvent[]): void {
    // 从 topic_switched 事件的 metadata 中提取兴趣标签
    const topicEvents = events.filter(e => e.type === 'topic_switched' && e.metadata?.topic)
    const newTopics = topicEvents
      .map(e => {
        const t = e.metadata?.topic
        return (typeof t === 'string' && t.length > 0 && t.length <= 50) ? t : null
      })
      .filter((t): t is string => t !== null)

    // 合并到现有兴趣列表（带频次加权）
    const merged = [...this.profile.inferred.primaryInterests]
    for (const topic of newTopics) {
      if (!merged.includes(topic)) {
        merged.push(topic)
      }
    }

    // 只保留 top-8 兴趣
    this.profile.inferred.primaryInterests = merged.slice(0, 8)
  }

  /**
   * 更新查询模式（平均长度等）
   */
  private updateQueryPattern(events: BehaviorEvent[]): void {
    const queryEvents = events.filter(e =>
      e.type === 'query_sent' || e.type === 'long_query' || e.type === 'short_query',
    )

    if (queryEvents.length === 0) return

    // 计算平均查询长度（需要原始文本，这里用事件类型估算）
    let totalEstimate = 0
    for (const e of queryEvents) {
      if (e.type === 'long_query') totalEstimate += 60
      else if (e.type === 'short_query') totalEstimate += 8
      else totalEstimate += 25 // average estimate
    }

    const newAvg = totalEstimate / queryEvents.length
    // 平滑更新
    const prevAvg = this.profile.inferred.avgQueryLength
    this.profile.inferred.avgQueryLength = Math.round(prevAvg * 0.6 + newAvg * 0.4)
  }

  /**
   * 更新偏好的回复长度
   */
  private updateResponseLengthPreference(events: BehaviorEvent[]): void {
    const likes = events.filter(e => e.type === 'response_liked').length
    const dislikes = events.filter(e => e.type === 'response_disliked').length

    if (likes + dislikes < 2) return // 数据不足

    const likeRatio = likes / (likes + dislikes)

    if (likeRatio > 0.7) {
      // 用户喜欢当前回复风格 → 保持
      // 可以进一步细化：如果 liked 的回复是长的 → long
      this.profile.inferred.preferredResponseLength =
        this.profile.inferred.avgQueryLength > 30 ? 'long' : 'medium'
    } else if (likeRatio < 0.3) {
      // 用户不喜欢 → 切换
      this.profile.inferred.preferredResponseLength =
        this.profile.inferred.preferredResponseLength === 'long' ? 'medium' : 'short'
    }
  }

  // ===== Prompt 注入 =====

  /**
   * 生成用于 System Prompt 的用户画像摘要
   * 供后端 chat_engine 使用以个性化回复
   */
  generatePromptSummary(): string {
    const { domain, inferred } = this.profile
    const parts: string[] = []

    // 回复风格
    const styleDesc: Record<string, string> = {
      concise: '简洁明了，直击要点',
      detailed: '详尽全面，配有例子和解释',
      academic: '学术严谨，引用标准和文献',
    }
    parts.push(`回复风格：${styleDesc[domain.responseStyle] || '标准'}`)

    // 技术深度
    const depthDesc: Record<string, string> = {
      basic: '入门级，避免过多专业术语',
      intermediate: '中级，适度使用术语并解释',
      advanced: '高级，可深入讨论机制和原理',
    }
    parts.push(`技术深度：${depthDesc[domain.technicalDepth] || '中级'}`)

    // 专业度自适应
    if (inferred.estimatedExpertise > 70) {
      parts.push('用户表现出较高专业水平，可直接使用行业术语')
    } else if (inferred.estimatedExpertise < 30) {
      parts.push('用户可能是新手，请用通俗语言解释概念')
    }

    // 兴趣领域（净化后注入，防止 Prompt 注入）
    if (inferred.primaryInterests.length > 0) {
      const safeTopics = inferred.primaryInterests
        .map(t => t.replace(/[\n\r\t]/g, ' ').slice(0, 30).trim())
        .filter(t => t.length > 0)
      parts.push(`关注领域：${safeTopics.join('、')}`)
    }

    // 共情开关
    if (!domain.empathyEnabled) {
      parts.push('用户已关闭共情回应模式，保持纯专业语调')
    }

    // ── 健康安全约束（来自设置面板 / 自动提取）──
    // 这是安全关键信息，缺失会导致 AI 忽略用户过敏原与饮食禁忌。
    const health = this.buildHealthConstraints()
    if (health.length > 0) {
      parts.push(...health)
    }

    return `【用户画像】\n${parts.map(p => `- ${p}`).join('\n')}`
  }

  /**
   * 构建健康安全约束条目。
   *
   * 数据源：userPreferencesService（设置面板手动填写 + 对话自动提取）。
   * 与「交互偏好」不同，这些字段属于安全约束，必须注入 Prompt。
   */
  private buildHealthConstraints(): string[] {
    const items: string[] = []
    try {
      const hp = userPreferencesService.getUserProfile()
      if (!hp) return items

      const goalLabels: Record<string, string> = {
        blood_sugar_control: '血糖管理',
        blood_pressure_control: '血压管理',
        weight_management: '体重管理',
        sleep_improvement: '改善睡眠',
        immune_boost: '增强免疫',
        antioxidant: '抗氧化/抗衰老',
        liver_protection: '肝脏养护',
        digestive_health: '消化健康',
        anti_fatigue: '抗疲劳/提升精力',
        other: '其他健康目标',
      }
      const allergenLabels: Record<string, string> = {
        peanuts: '花生',
        shellfish: '海鲜/甲壳类',
        dairy: '乳制品',
        gluten: '麸质',
        soy: '大豆',
        eggs: '鸡蛋',
        tree_nuts: '坚果',
        sesame: '芝麻',
        mugwort: '菊科植物（苦瓜、桑叶等）',
        other: '其他',
      }
      const dietLabels: Record<string, string> = {
        vegetarian: '素食',
        vegan: '纯素',
        halal: '清真',
        kosher: '洁食',
        low_sugar: '低糖',
        low_fat: '低脂',
        low_sodium: '低盐',
        no_alcohol: '禁酒',
      }

      const goals = (hp.healthGoals ?? [])
        .map(g => goalLabels[g] ?? String(g))
        .filter(Boolean)
      if (goals.length > 0) items.push(`健康目标: ${goals.join('、')}`)

      const allergens = (hp.allergens ?? [])
        .map(a => allergenLabels[a] ?? String(a))
        .filter(Boolean)
      if (allergens.length > 0) {
        items.push(`⚠️ 过敏禁忌（严禁使用）: ${allergens.join('、')}`)
      }

      const diets = (hp.dietRestrictions ?? [])
        .map(d => dietLabels[d] ?? String(d))
        .filter(Boolean)
      if (diets.length > 0) {
        items.push(`饮食限制: ${diets.join('、')}`)
      }

      if (hp.constitutionType) {
        items.push(`体质倾向: ${hp.constitutionType}`)
      }
      if (hp.healthNotes) {
        items.push(`健康状况备注: ${hp.healthNotes}`)
      }
    } catch (error) {
      logger.warn('[UnifiedUserProfile] 读取健康约束失败，已跳过:', error)
    }
    return items
  }

  // ===== 持久化 =====

  private saveAndNotify(): void {
    this.profile.updatedAt = Date.now()
    this.saveToStorage()
    this.notifyListeners()
  }

  private saveToStorage(): void {
    try {
      const data = {
        version: PROFILE_VERSION,
        profile: this.profile,
      }
      localStorage.setItem(STORAGE_KEY, JSON.stringify(data))
    } catch (error) {
      logger.warn('[UnifiedUserProfile] 持久化失败:', error)
    }
  }

  private loadFromStorage(): UserProfile {
    try {
      const raw = localStorage.getItem(STORAGE_KEY)
      if (!raw) return { ...DEFAULT_PROFILE }

      const data = JSON.parse(raw)
      if (data.version !== PROFILE_VERSION) {
        logger.warn(`[UserProfile] 版本不匹配(${data.version} vs ${PROFILE_VERSION})，使用默认值`)
        return { ...DEFAULT_PROFILE }
      }

      // 深度合并默认值（确保新增字段有值）
      return {
        ui: { ...DEFAULT_UI, ...(data.profile?.ui || {}) },
        domain: { ...DEFAULT_DOMAIN, ...(data.profile?.domain || {}) },
        inferred: { ...DEFAULT_INFERRED, ...(data.profile?.inferred || {}) },
        updatedAt: data.profile?.updatedAt || Date.now(),
      }
    } catch {
      return { ...DEFAULT_PROFILE }
    }
  }

  // ===== 监听器 =====

  subscribe(listener: (profile: UserProfile) => void): () => void {
    this.listeners.push(listener)
    // 立即通知一次当前状态
    try {
      listener(this.getProfile())
    } catch {
      // 忽略监听器错误
    }
    return () => {
      const idx = this.listeners.indexOf(listener)
      if (idx >= 0) this.listeners.splice(idx, 1)
    }
  }

  private notifyListeners(): void {
    const profile = this.getProfile()
    for (const fn of this.listeners) {
      try {
        fn(profile)
      } catch {
        // 忽略监听器错误
      }
    }
  }

  // ===== 重置 =====

  reset(): void {
    this.profile = { ...DEFAULT_PROFILE }
    this.behaviorBuffer = []
    this.saveAndNotify()
  }

  /** 仅重置推断数据（保留显式偏好设置） */
  resetInferred(): void {
    this.profile.inferred = { ...DEFAULT_INFERRED }
    this.behaviorBuffer = []
    this.saveAndNotify()
  }

  // ===== 调试 =====

  getDebugInfo(): object {
    return {
      profileVersion: PROFILE_VERSION,
      behaviorBufferSize: this.behaviorBuffer.length,
      profile: this.getProfile(),
    }
  }
}

