    })

    it('应处理混合文本', () => {
      const text = '🎂 生日蛋糕 🎉🎊🎁'
      expect(countEmojis(text)).toBe(4)
    })
  })

  describe('normalizeText', () => {
    it('应压缩多余空格', () => {
