// ===== 类型定义 =====

export interface TimeFormatOptions {
  /** 显示相对时间（如"3分钟前"） */
  relative?: boolean
  /** 显示日期 */
  showDate?: boolean
  /** 显示时间 */
  showTime?: boolean
  /** 自定义格式字符串 */
  format?: string
  /** 是否使用12小时制 */
  use12Hour?: boolean
}

export interface TextSummaryOptions {
  /** 最大长度 */
  maxLength?: number
  /** 是否保留完整句子 */
  preserveSentences?: boolean
  /** 关键词权重（可选，用于优化摘要） */
  keywords?: string[]
}

export interface MessageSimilarityResult {
  similarity: number        // 相似度 (0-1)
  isDuplicate: boolean     // 是否判定为重复
  commonWords: string[]    // 共同词汇
  diffRatio: number        // 差异比例
}

export interface ParsedUrl {
  original: string
  protocol: string
  host: string
  path: string
  query: Record<string, string>
  hash: string
  isValid: boolean
}

/**
 * 格式化时间戳为可读字符串
 */
export function formatTimestamp(timestamp: number | string): string {
  let date: Date

  if (typeof timestamp === 'string') {
    date = new Date(timestamp)
  } else if (typeof timestamp === 'number') {
    date = new Date(timestamp)
  } else {
    return ''
  }

  if (isNaN(date.getTime())) {
    return ''
  }

  // 简单的格式化实现
  const now = new Date()
  const diff = now.getTime() - date.getTime()

  // 小于1分钟
  if (diff < 60000) {
    return '刚刚'
  }

  // 小于1小时
  if (diff < 3600000) {
    const minutes = Math.floor(diff / 60000)
    return `${minutes}分钟前`
  }

  // 小于24小时
  if (diff < 86400000) {
    const hours = Math.floor(diff / 3600000)
    return `${hours}小时前`
  }

  // 其他情况显示日期
  return date.toLocaleDateString('zh-CN', {
    month: 'numeric',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  })
}

/**
 * 截断过长文本并添加省略号
 */
export function truncateText(text: string, maxLength = 100): string {
  if (!text || text.length <= maxLength) {
    return text || ''
  }

  return text.substring(0, maxLength).trim() + '...'
}

/**
 * 根据内容自动检测消息类型
 */
export function detectMessageType(content: string): string {
  if (!content) return 'text'

  // 检测是否包含公式相关关键词
  const formulaKeywords = ['配方', '成分', '营养', '成本']
  if (formulaKeywords.some(keyword => content.includes(keyword))) {
    return 'formula'
  }

  // 检测是否是问题
  if (content.includes('?') || content.includes('？')) {
    return 'question'
  }

  // 默认返回普通文本类型
  return 'text'
}

/**
 * 高亮匹配的关键词
 */
export function highlightKeywords(text: string, keywords: string[]): string {
  if (!keywords || keywords.length === 0) return text

  let result = text
  keywords.forEach(keyword => {
    if (keyword && keyword.trim()) {
      const regex = new RegExp(`(${keyword})`, 'gi')
      result = result.replace(regex, '<mark>$1</mark>')
    }
  })

  return result
}

/**
 * 生成唯一消息ID
 */
export function generateMessageId(): string {
  return `msg_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`
}

/**
 * 计算文本的预估token数量（粗略估算）
 */
export function estimateTokenCount(text: string): number {
  if (!text) return 0

  // 中文字符约1-2个token，英文单词约1个token
  const chineseChars = (text.match(/[\u4e00-\u9fa5]/g) || []).length
  const englishWords = (text.match(/[a-zA-Z]+/g) || []).length

  return Math.ceil(chineseChars * 1.5 + englishWords)
}

// ===== v7.0 新增高级功能 =====

/**
 * 高级时间格式化（支持多种模式）
 */
export function formatTimestampAdvanced(
  timestamp: number | string | Date,
  options: TimeFormatOptions = {},
): string {
  const {
    relative = true,
    showDate = true,
    showTime = true,
    format,
    use12Hour = false,
  } = options

  let date: Date

  if (timestamp instanceof Date) {
    date = timestamp
  } else if (typeof timestamp === 'string') {
    date = new Date(timestamp)
  } else if (typeof timestamp === 'number') {
    date = new Date(timestamp)
  } else {
    return ''
  }

  if (isNaN(date.getTime())) return ''

  // 自定义格式
  if (format) {
    return formatDateWithPattern(date, format, use12Hour)
  }

  // 相对时间模式
  if (relative) {
    const now = new Date()
    const diff = now.getTime() - date.getTime()

    if (diff < 5000) return '刚刚'
    if (diff < 60000) return `${Math.floor(diff / 1000)}秒前`
    if (diff < 3600000) return `${Math.floor(diff / 60000)}分钟前`
    if (diff < 86400000) return `${Math.floor(diff / 3600000)}小时前`
    if (diff < 604800000) return `${Math.floor(diff / 86400000)}天前`

    // 超过7天显示具体日期
    return formatAbsoluteDate(date, showDate, showTime, use12Hour)
  }

  // 绝对时间模式
  return formatAbsoluteDate(date, showDate, showTime, use12Hour)
}

/**
 * 使用自定义格式字符串格式化日期
 */
function formatDateWithPattern(date: Date, pattern: string, use12Hour: boolean): string {
  const tokens: Record<string, string> = {
    'YYYY': date.getFullYear().toString(),
    'YY': date.getFullYear().toString().slice(-2),
    'MM': String(date.getMonth() + 1).padStart(2, '0'),
    'M': String(date.getMonth() + 1),
    'DD': String(date.getDate()).padStart(2, '0'),
    'D': String(date.getDate()),
    'HH': String(date.getHours()).padStart(2, '0'),
    'H': String(date.getHours()),
    'hh': use12Hour
      ? String(date.getHours() % 12 || 12).padStart(2, '0')
      : String(date.getHours()).padStart(2, '0'),
    'mm': String(date.getMinutes()).padStart(2, '0'),
    'ss': String(date.getSeconds()).padStart(2, '0'),
    'A': date.getHours() >= 12 ? 'PM' : 'AM',
    'a': date.getHours() >= 12 ? 'pm' : 'am',
  }

  let result = pattern
  Object.entries(tokens).forEach(([token, value]) => {
    result = result.replace(new RegExp(token, 'g'), value)
  })

  return result
}

/**
 * 格式化绝对日期时间
 */
function formatAbsoluteDate(
  date: Date,
  showDate: boolean,
  showTime: boolean,
  use12Hour: boolean,
): string {
  const parts: string[] = []

  if (showDate) {
    parts.push(date.toLocaleDateString('zh-CN', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    }))
  }

  if (showTime) {
    parts.push(date.toLocaleTimeString('zh-CN', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: use12Hour,
    }))
  }

  return parts.join(' ')
}

/**
 * 生成文本摘要（智能截断）
 */
export function generateTextSummary(
  text: string,
  options: TextSummaryOptions = {},
): string {
  const { maxLength = 200, preserveSentences = true, keywords: _keywords = [] } = options

  if (!text || text.length <= maxLength) return text || ''

  if (preserveSentences) {
    // 尝试在句子边界处截断
    let summary = text.slice(0, maxLength)

    // 查找最后一个句子结束符
    const lastSentenceEnd = Math.max(
      summary.lastIndexOf('。'),
      summary.lastIndexOf('！'),
      summary.lastIndexOf('？'),
      summary.lastIndexOf('.'),
      summary.lastIndexOf('!'),
      summary.lastIndexOf('?'),
      summary.lastIndexOf('\n'),
    )

    if (lastSentenceEnd > maxLength * 0.5) {
      summary = summary.slice(0, lastSentenceEnd + 1)
    }

    return summary.trim() + '...'
  } else {
    return truncateText(text, maxLength)
  }
}

/**
 * 提取文本中的关键词（基于词频统计）
 */
export function extractKeywords(text: string, topN = 10): { word: string; count: number }[] {
  if (!text) return []

  // 简单的分词（中文按字符，英文按单词）
  const words = text.toLowerCase()
    .replace(/[^\u4e00-\u9fa5a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(word => word.length > 1)

  // 统计词频
  const wordCount = new Map<string, number>()
  words.forEach(word => {
    wordCount.set(word, (wordCount.get(word) || 0) + 1)
  })

  // 排序并返回前 N 个
  return Array.from(wordCount.entries())
    .map(([word, count]) => ({ word, count }))
    .sort((a, b) => b.count - a.count)
    .slice(0, topN)
}

/**
 * 计算两条消息的相似度（用于去重检测）
 */
export function calculateMessageSimilarity(
  msg1: string,
  msg2: string,
  threshold = 0.8,
): MessageSimilarityResult {
  if (!msg1 || !msg2) {
    return { similarity: 0, isDuplicate: false, commonWords: [], diffRatio: 1 }
  }

  // 分词
  const words1 = new Set(msg1.toLowerCase().split(/\s+/).filter(w => w.length > 0))
  const words2 = new Set(msg2.toLowerCase().split(/\s+/).filter(w => w.length > 0))

  // 计算交集
  const commonWords = [...words1].filter(w => words2.has(w))

  // Jaccard 相似度
  const unionSize = new Set([...words1, ...words2]).size
  const similarity = unionSize > 0 ? commonWords.length / unionSize : 0

  // 计算差异比例（基于编辑距离的简化版本）
  const diffRatio = calculateDiffRatio(msg1, msg2)

  return {
    similarity: Math.round(similarity * 100) / 100,
    isDuplicate: similarity >= threshold,
    commonWords,
    diffRatio: Math.round(diffRatio * 100) / 100,
  }
}

/**
 * 计算文本差异比例（简化版编辑距离）
 */
function calculateDiffRatio(text1: string, text2: string): number {
  const len1 = text1.length
  const len2 = text2.length
  const maxLen = Math.max(len1, len2)

  if (maxLen === 0) return 0

  // 计算不同字符的数量
  let diffs = 0
  const minLen = Math.min(len1, len2)

  for (let i = 0; i < minLen; i++) {
    if (text1[i] !== text2[i]) diffs++
  }

  diffs += Math.abs(len1 - len2)

  return diffs / maxLen
}

/**
 * 解析 URL 并提取各部分信息
 */
export function parseUrl(urlString: string): ParsedUrl {
  try {
    const url = new URL(urlString)

    const query: Record<string, string> = {}
    url.searchParams.forEach((value, key) => {
      query[key] = value
    })

    return {
      original: urlString,
      protocol: url.protocol.replace(':', ''),
      host: url.host,
      path: url.pathname,
      query,
      hash: url.hash.replace('#', ''),
      isValid: true,
    }
  } catch {
    return {
      original: urlString,
      protocol: '',
      host: '',
      path: '',
      query: {},
      hash: '',
      isValid: false,
    }
  }
}

/**
 * 检测并转换文本中的 URL 为可点击链接
 */
export function linkifyText(text: string): string {
  const urlRegex = /(https?:\/\/[^\s<]+)/g

  return text.replace(urlRegex, '<a href="$1" target="_blank" rel="noopener noreferrer">$1</a>')
}

/**
 * 检测文本中的表情符号数量
 */
export function countEmojis(text: string): number {
  const emojiRegex = /[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/gu
  return (text.match(emojiRegex) || []).length
}

/**
 * 清理和规范化文本（去除多余空格、特殊字符等）
 */
export function normalizeText(text: string): string {
  if (!text) return ''

  return text
    .replace(/\r\n/g, '\n')          // 统一换行符
    .replace(/\n{3,}/g, '\n\n')     // 压缩多余换行
    .replace(/[ \t]+/g, ' ')        // 压缩空格
    .trim()                         // 去除首尾空格
}

/**
 * 检测文本语言（简化版：中/英/混合）
 */
export function detectLanguage(text: string): 'zh' | 'en' | 'mixed' | 'unknown' {
  if (!text) return 'unknown'

  const chineseChars = (text.match(/[\u4e00-\u9fa5]/g) || []).length
  const englishChars = (text.match(/[a-zA-Z]/g) || []).length
  const totalChars = text.replace(/\s/g, '').length

  if (totalChars === 0) return 'unknown'

  const zhRatio = chineseChars / totalChars
  const enRatio = englishChars / totalChars

  if (zhRatio > 0.6) return 'zh'
  if (enRatio > 0.6) return 'en'
  if (zhRatio > 0.2 && enRatio > 0.2) return 'mixed'
  return enRatio > zhRatio ? 'en' : 'zh'
}

/**
 * 格式化文件大小为可读字符串
 */
export function formatFileSize(bytes: number): string {
  if (bytes === 0) return '0 B'

  const units = ['B', 'KB', 'MB', 'GB', 'TB']
  const k = 1024
  const i = Math.floor(Math.log(bytes) / Math.log(k))
  const size = bytes / Math.pow(k, i)

  return `${size.toFixed(i > 0 ? 1 : 0)} ${units[i]}`
}

/**
 * 防抖函数（用于搜索输入等场景）
 */
export function debounce<T extends (...args: any[]) => any>(
  func: T,
  wait: number,
): (...args: Parameters<T>) => void {
  let timeoutId: ReturnType<typeof setTimeout>

  return function (...args: Parameters<T>) {
    clearTimeout(timeoutId)
    timeoutId = setTimeout(() => func(...args), wait)
  }
}

/**
 * 节流函数（用于滚动事件等高频场景）
 */
export function throttle<T extends (...args: any[]) => any>(
  func: T,
  limit: number,
): (...args: Parameters<T>) => void {
  let inThrottle: boolean

  return function (...args: Parameters<T>) {
    if (!inThrottle) {
      func(...args)
      inThrottle = true
      setTimeout(() => (inThrottle = false), limit)
    }
  }
}

import { logger } from '@/utils/safeLogger';
export enum ChatState {
  Idle = 'idle',
  Validating = 'validating',
  Sending = 'sending',
  Streaming = 'streaming',
  Success = 'success',
  Error = 'error',
  RateLimited = 'rate_limited',

  Thinking = 'thinking',
  Formatting = 'formatting',
  Processing = 'processing',
  Paused = 'paused',
  Retrying = 'retrying',
}

const VALID_TRANSITIONS: Record<ChatState, ChatState[]> = {
  [ChatState.Idle]: [ChatState.Validating, ChatState.Thinking],
  [ChatState.Validating]: [ChatState.Sending, ChatState.Error, ChatState.Idle],
  [ChatState.Sending]: [ChatState.Streaming, ChatState.Thinking, ChatState.Error, ChatState.Success],
  [ChatState.Streaming]: [ChatState.Success, ChatState.Error, ChatState.Paused],
  [ChatState.Success]: [ChatState.Idle],
  [ChatState.Error]: [ChatState.Idle, ChatState.Retrying],
  [ChatState.RateLimited]: [ChatState.Idle],
  [ChatState.Thinking]: [ChatState.Sending, ChatState.Idle],
  [ChatState.Formatting]: [ChatState.Success, ChatState.Error],
  [ChatState.Processing]: [ChatState.Streaming, ChatState.Success, ChatState.Error],
  [ChatState.Paused]: [ChatState.Streaming, ChatState.Idle],
  [ChatState.Retrying]: [ChatState.Sending, ChatState.Error],
};

Object.keys(VALID_TRANSITIONS).forEach(state => {
  if (!VALID_TRANSITIONS[state as ChatState].includes(ChatState.RateLimited)) {
    VALID_TRANSITIONS[state as ChatState].push(ChatState.RateLimited);
  }
});

export interface StateMachineConfig {
  throwOnError?: boolean;
  enableDebug?: boolean;
  autoResetOnSuccess?: boolean;
  maxContextWindow?: number;
  contextCompressionThreshold?: number;
  minRelevanceScore?: number;
}

export interface IStateMachine<T> {
  readonly state: T;
  readonly previousState: T;
  readonly transitionHistory: { from: T; to: T; timestamp: number }[];

  canTransition(to: T): boolean;
  transition(to: T): boolean;
  reset(): void;
  isInState(...states: T[]): boolean;

  onStateChange?: (from: T, to: T) => void;
  onTransitionError?: (from: T, to: T, error: Error) => void;
}

export interface TransitionResult {
  success: boolean;
  from?: ChatState;
  to?: ChatState;
  error?: string;
}

export interface Message {
  id: string;
  role: 'user' | 'assistant' | 'system';
  content: string;
  timestamp: number;
  tokens: number;
  relevanceScore?: number;
  importanceTags?: string[];
  summary?: string;
}

export interface CompressedContext {
  messages: Message[];
  originalMessageCount: number;
  compressedMessageCount: number;
  compressionRatio: number;
  totalRelevanceScore: number;
  averageRelevanceScore: number;
}

export interface ContextStats {
  totalMessages: number;
  totalTokens: number;
  userMessages: number;
  assistantMessages: number;
  systemMessages: number;
  averageRelevance: number;
  contextSize: number;
}

const STOP_WORDS = new Set([
  'the', 'a', 'an', 'is', 'are', 'was', 'were', 'be', 'been', 'being',
  'have', 'has', 'had', 'do', 'does', 'did', 'will', 'would', 'could', 'should',
  'may', 'might', 'must', 'shall', 'can', 'need', 'dare', 'ought', 'used',
  'to', 'of', 'in', 'for', 'on', 'with', 'at', 'by', 'from', 'as', 'into',
  'through', 'during', 'before', 'after', 'above', 'below', 'between', 'under',
  'again', 'further', 'then', 'once', 'here', 'there', 'when', 'where', 'why',
  'how', 'all', 'each', 'few', 'more', 'most', 'other', 'some', 'such', 'no',
  'nor', 'not', 'only', 'own', 'same', 'so', 'than', 'too', 'very', 'just', 'or',
  'and', 'but', 'if', 'because', 'while', 'although', 'though', 'that', 'which',
  'who', 'whom', 'this', 'these', 'those', 'i', 'you', 'he', 'she', 'it', 'we', 'they',
]);

function createHash(text: string): string {
  let hash = 0;
  for (let i = 0; i < text.length; i++) {
    const char = text.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  return Math.abs(hash).toString(36);
}

function extractKeywords(text: string): string[] {
  const words = text.toLowerCase().split(/[^a-zA-Z0-9\u4e00-\u9fa5]+/).filter(w => w.length > 1 && !STOP_WORDS.has(w));
  const keywordMap = new Map<string, number>();

  words.forEach(word => {
    keywordMap.set(word, (keywordMap.get(word) || 0) + 1);
  });

  return Array.from(keywordMap.entries())
    .sort((a, b) => b[1] - a[1])
    .slice(0, 20)
    .map(entry => entry[0]);
}

function calculateSemanticSimilarity(text1: string, text2: string): number {
  const keywords1 = new Set(extractKeywords(text1));
  const keywords2 = new Set(extractKeywords(text2));

  if (keywords1.size === 0 || keywords2.size === 0) return 0;

  let intersection = 0;
  keywords1.forEach(k => {
    if (keywords2.has(k)) intersection++;
  });

  const union = keywords1.size + keywords2.size - intersection;
  return union > 0 ? intersection / union : 0;
}

export class RelevanceScorer {
  private static instance: RelevanceScorer;
  private keywordCache = new Map<string, string[]>();
  private similarityCache = new Map<string, number>();

  private constructor() {}

  static getInstance(): RelevanceScorer {
    if (!RelevanceScorer.instance) {
      RelevanceScorer.instance = new RelevanceScorer();
    }
    return RelevanceScorer.instance;
  }

  scoreMessage(message: Message, contextMessages: Message[], currentQuery?: string): number {
    if (!message.content.trim()) return 0;

    const cacheKey = `${message.id}_${currentQuery ? createHash(currentQuery) : 'none'}`;
    if (this.similarityCache.has(cacheKey)) {
      return this.similarityCache.get(cacheKey)!;
    }

    let totalScore = 0;
    let scoreCount = 0;

    if (currentQuery) {
      const querySimilarity = calculateSemanticSimilarity(message.content, currentQuery);
      totalScore += querySimilarity * 50;
      scoreCount++;
    }

    contextMessages.forEach(ctxMsg => {
      if (ctxMsg.id !== message.id) {
        const similarity = calculateSemanticSimilarity(message.content, ctxMsg.content);
        totalScore += similarity * 25;
        scoreCount++;
      }
    });

    const recencyScore = Math.max(0, 1 - (Date.now() - message.timestamp) / (24 * 60 * 60 * 1000));
    totalScore += recencyScore * 25;
    scoreCount++;

    const finalScore = scoreCount > 0 ? Math.round((totalScore / scoreCount) * 100) : 0;

    this.similarityCache.set(cacheKey, finalScore);

    if (this.similarityCache.size > 1000) {
      const keys = Array.from(this.similarityCache.keys());
      for (let i = 0; i < 200; i++) {
        this.similarityCache.delete(keys[i]);
      }
    }

    return finalScore;
  }

  batchScore(messages: Message[], currentQuery?: string): Message[] {
    const scoredMessages = messages.map(msg => ({
      ...msg,
      relevanceScore: this.scoreMessage(msg, messages, currentQuery),
    }));
    return scoredMessages;
  }

  clearCache(): void {
    this.keywordCache.clear();
    this.similarityCache.clear();
  }
}

export class ContextCompressor {
  private scorer: RelevanceScorer;

  constructor() {
    this.scorer = RelevanceScorer.getInstance();
  }

  compress(
    messages: Message[],
    maxWindowSize = 50,
    _minRelevance = 30,
    currentQuery?: string,
  ): CompressedContext {
    const originalCount = messages.length;

    if (originalCount <= maxWindowSize) {
      const scoredMessages = this.scorer.batchScore(messages, currentQuery);
      return {
        messages: scoredMessages,
        originalMessageCount: originalCount,
        compressedMessageCount: originalCount,
        compressionRatio: 0,
        totalRelevanceScore: scoredMessages.reduce((sum, m) => sum + (m.relevanceScore || 0), 0),
        averageRelevanceScore: scoredMessages.reduce((sum, m) => sum + (m.relevanceScore || 0), 0) / originalCount,
      };
    }

    let scoredMessages = this.scorer.batchScore(messages, currentQuery);

    scoredMessages = scoredMessages.sort((a, b) => (b.relevanceScore || 0) - (a.relevanceScore || 0));

    const topMessages = scoredMessages.slice(0, Math.floor(maxWindowSize * 0.7));

    const remainingMessages = scoredMessages.slice(Math.floor(maxWindowSize * 0.7));
    const recentMessages = remainingMessages
      .sort((a, b) => b.timestamp - a.timestamp)
      .slice(0, Math.floor(maxWindowSize * 0.3));

    const compressed = [...topMessages, ...recentMessages]
      .sort((a, b) => a.timestamp - b.timestamp);

    const totalRelevance = compressed.reduce((sum, m) => sum + (m.relevanceScore || 0), 0);

    return {
      messages: compressed,
      originalMessageCount: originalCount,
      compressedMessageCount: compressed.length,
      compressionRatio: ((originalCount - compressed.length) / originalCount) * 100,
      totalRelevanceScore: totalRelevance,
      averageRelevanceScore: compressed.length > 0 ? totalRelevance / compressed.length : 0,
    };
  }

  generateSummary(messages: Message[]): string {
    const systemMessages = messages.filter(m => m.role === 'system');
    const userMessages = messages.filter(m => m.role === 'user');

    const keyPoints: string[] = [];

    if (systemMessages.length > 0) {
      keyPoints.push(`系统指令: ${systemMessages[0].content.slice(0, 100)}...`);
    }

    if (userMessages.length > 0) {
      const recentUser = userMessages[userMessages.length - 1];
				keyPoints.push(`最新用户提问: ${recentUser.content.slice(0, 150)}...`);
    }

    const highRelevanceMessages = messages
      .filter(m => m.relevanceScore && m.relevanceScore >= 70)
      .slice(0, 3);

    highRelevanceMessages.forEach(msg => {
      keyPoints.push(`${msg.role === 'user' ? '用户' : '助手'}: ${msg.content.slice(0, 100)}... (相关度: ${msg.relevanceScore}%)`);
    });

    return keyPoints.join(' | ');
  }
}

export class ChatStateMachine implements IStateMachine<ChatState> {
  private _state: ChatState;
  private _previousState: ChatState;
  private _transitionHistory: { from: ChatState; to: ChatState; timestamp: number }[];
  private _context: Message[];
  private config: StateMachineConfig;
  private transitionLock = false;
  private contextCompressor: ContextCompressor;
  private relevanceScorer: RelevanceScorer;
  private _stats: ContextStats;
  private statsUpdateTime = 0;

  public onStateChange?: (from: ChatState, to: ChatState) => void;
  public onTransitionError?: (from: ChatState, to: ChatState, error: Error) => void;
  public onContextUpdate?: (stats: ContextStats) => void;
  public onContextCompressed?: (result: CompressedContext) => void;

  constructor(initialState: ChatState = ChatState.Idle, config: StateMachineConfig = {}) {
    this._state = initialState;
    this._previousState = initialState;
    this._transitionHistory = [];
    this._context = [];
    this._stats = this.createEmptyStats();

    this.config = {
      throwOnError: false,
      enableDebug: false,
      autoResetOnSuccess: true,
      maxContextWindow: 50,
      contextCompressionThreshold: 60,
      minRelevanceScore: 30,
      ...config,
    };

    this.contextCompressor = new ContextCompressor();
    this.relevanceScorer = RelevanceScorer.getInstance();
  }

  private createEmptyStats(): ContextStats {
    return {
      totalMessages: 0,
      totalTokens: 0,
      userMessages: 0,
      assistantMessages: 0,
      systemMessages: 0,
      averageRelevance: 0,
      contextSize: 0,
    };
  }

  private updateStats(): void {
    const now = Date.now();
    if (now - this.statsUpdateTime < 100) return;

    const stats = {
      totalMessages: this._context.length,
      totalTokens: this._context.reduce((sum, m) => sum + m.tokens, 0),
      userMessages: this._context.filter(m => m.role === 'user').length,
      assistantMessages: this._context.filter(m => m.role === 'assistant').length,
      systemMessages: this._context.filter(m => m.role === 'system').length,
      averageRelevance: this._context.length > 0
        ? this._context.reduce((sum, m) => sum + (m.relevanceScore || 0), 0) / this._context.length
        : 0,
      contextSize: JSON.stringify(this._context).length,
    };

    this._stats = stats;
    this.statsUpdateTime = now;

    this.onContextUpdate?.(stats);
  }

  get state(): ChatState {
    return this._state;
  }

  get previousState(): ChatState {
    return this._previousState;
  }

  get transitionHistory(): { from: ChatState; to: ChatState; timestamp: number }[] {
    return [...this._transitionHistory];
  }

  get context(): Message[] {
    return [...this._context];
  }

  get stats(): ContextStats {
    this.updateStats();
    return { ...this._stats };
  }

  canTransition(to: ChatState): boolean {
    if (this.transitionLock) {
      if (this.config.enableDebug) {
        logger.debug('[ChatStateMachine] 状态转换被锁定: 当前状态 %s', this._state);
      }
      return false;
    }

    const allowedTransitions = VALID_TRANSITIONS[this._state] || [];
    return allowedTransitions.includes(to);
  }

  transition(to: ChatState): boolean {
    if (!this.canTransition(to)) {
      const errorMessage = `无效的状态转换: '${this._state}' -> '${to}'. 允许的转换: ${VALID_TRANSITIONS[this._state]?.join(', ') || '无'}`;

      if (this.config.throwOnError) {
        const error = new Error(errorMessage);
        this.onTransitionError?.(this._state, to, error);
        throw error;
      }

      if (this.config.enableDebug) {
        logger.warn(`[ChatStateMachine] ${errorMessage}`);
      }
      this.onTransitionError?.(this._state, to, new Error(errorMessage));
      return false;
    }

    const previousState = this._state;
    this._previousState = previousState;
    this._state = to;

    this._transitionHistory.push({
      from: previousState,
      to,
      timestamp: Date.now(),
    });

    if (this._transitionHistory.length > 500) {
      this._transitionHistory = this._transitionHistory.slice(-500);
    }

    if (this.config.enableDebug) {
      logger.debug('[ChatStateMachine] 状态转换: %s -> %s', previousState, to);
    }

    if (this.onStateChange) {
      try {
        this.onStateChange(previousState, to);
      } catch (callbackError) {
        logger.error(`[ChatStateMachine] onStateChange 回调执行失败:`, callbackError);
      }
    }

    if (this.config.autoResetOnSuccess && to === ChatState.Success) {
      setTimeout(() => {
        if (this._state === ChatState.Success) {
          this.transition(ChatState.Idle);
        }
      }, 2000);
    }

    return true;
  }

  reset(): void {
    this._state = ChatState.Idle;
    this._previousState = ChatState.Idle;
    this._transitionHistory = [];
    this._context = [];
    this._stats = this.createEmptyStats();
    if (this.config.enableDebug) {
      logger.debug('[ChatStateMachine] 已重置状态');
    }
  }

  isInState(...states: ChatState[]): boolean {
    return states.includes(this._state);
  }

  setTransitionLock(locked: boolean): void {
    this.transitionLock = locked;
    if (this.config.enableDebug) {
      logger.debug('[ChatStateMachine] 转换锁 %s', locked ? '已锁定' : '已解锁');
    }
  }

  getStateDuration(): number {
    const lastTransition = this._transitionHistory[this._transitionHistory.length - 1];
    if (!lastTransition) return 0;
    return Date.now() - lastTransition.timestamp;
  }

  getTransitionCount(from?: ChatState, to?: ChatState): number {
    return this._transitionHistory.filter(t => {
      const fromMatch = !from || t.from === from;
      const toMatch = !to || t.to === to;
      return fromMatch && toMatch;
    }).length;
  }

  addMessage(message: Omit<Message, 'id' | 'timestamp' | 'relevanceScore'>): Message {
    const newMessage: Message = {
      ...message,
      id: `${message.role}_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`,
      timestamp: Date.now(),
      relevanceScore: undefined,
    };

    this._context.push(newMessage);

    if (this._context.length > this.config.maxContextWindow!) {
      const result = this.compressContext();
      if (this.config.enableDebug) {
        logger.debug('[ChatStateMachine] 上下文已压缩', {
          originalMessageCount: result.originalMessageCount,
          compressedMessageCount: result.compressedMessageCount,
        });
      }
    }

    this.updateStats();

    return newMessage;
  }

  addMessages(messages: Omit<Message, 'id' | 'timestamp' | 'relevanceScore'>[]): Message[] {
    const addedMessages: Message[] = [];

    messages.forEach(msg => {
      addedMessages.push(this.addMessage(msg));
    });

    return addedMessages;
  }

  removeMessage(messageId: string): boolean {
    const index = this._context.findIndex(m => m.id === messageId);
    if (index !== -1) {
      this._context.splice(index, 1);
      this.updateStats();
      return true;
    }
    return false;
  }

  clearContext(): void {
    this._context = [];
    this.updateStats();
  }

  compressContext(currentQuery?: string): CompressedContext {
    const result = this.contextCompressor.compress(
      this._context,
      this.config.maxContextWindow,
      this.config.minRelevanceScore,
      currentQuery,
    );

    this._context = result.messages;
    this.updateStats();

    this.onContextCompressed?.(result);

    return result;
  }

  scoreContextRelevance(currentQuery?: string): number {
    const scored = this.relevanceScorer.batchScore(this._context, currentQuery);
    const avgScore = scored.reduce((sum, m) => sum + (m.relevanceScore || 0), 0) / scored.length;
    return Math.round(avgScore);
  }

  getContextSummary(): string {
    return this.contextCompressor.generateSummary(this._context);
  }

  getMessagesByRole(role: Message['role']): Message[] {
    return this._context.filter(m => m.role === role);
  }

  getHighRelevanceMessages(minScore = 70): Message[] {
    return this._context
      .filter(m => m.relevanceScore && m.relevanceScore >= minScore)
      .sort((a, b) => (b.relevanceScore || 0) - (a.relevanceScore || 0));
  }

  static getValidTransitions(): Record<ChatState, ChatState[]> {
    return { ...VALID_TRANSITIONS };
  }

  static getAllStates(): ChatState[] {
    return Object.values(ChatState);
  }

  static getInitialStates(): ChatState[] {
    return [ChatState.Idle];
  }

  static getTerminalStates(): ChatState[] {
    return [ChatState.Success, ChatState.Error, ChatState.RateLimited];
  }

  static getActiveStates(): ChatState[] {
    return [ChatState.Validating, ChatState.Sending, ChatState.Streaming,
            ChatState.Thinking, ChatState.Formatting, ChatState.Processing,
            ChatState.Retrying];
  }
}

export function createChatStateMachine(
  initialState?: ChatState,
  config?: StateMachineConfig,
): ChatStateMachine {
  return new ChatStateMachine(initialState, config);
}

export interface TransitionRule {
  from: ChatState;
  to: ChatState;
  isValid: boolean;
}

export function getTransitionRules(): TransitionRule[] {
  const rules: TransitionRule[] = [];
  const states = ChatStateMachine.getAllStates();

  for (const from of states) {
    const validTargets = VALID_TRANSITIONS[from] || [];

    for (const to of states) {
      rules.push({
        from,
        to,
        isValid: validTargets.includes(to),
      });
    }
  }

  return rules;
}

export function validateTransitionSequence(states: ChatState[]): boolean {
  for (let i = 0; i < states.length - 1; i++) {
    const from = states[i];
    const to = states[i + 1];
    if (!VALID_TRANSITIONS[from]?.includes(to)) {
      return false;
    }
  }
  return true;
}

type WorkerMessageType =
  | 'export:start'
  | 'export:progress'
  | 'export:complete'
  | 'export:error'
  | 'process:text'
  | 'process:complete'
  | 'error';

interface WorkerMessage<T = any> {
  type: WorkerMessageType;
  payload: T;
  id?: string;
}

interface ExportTask {
  data: any[];
  format: 'json' | 'csv' | 'txt' | 'html' | 'markdown';
  options?: {
    includeHeaders?: boolean;
    delimiter?: string;
    prettyPrint?: boolean;
  };
}

interface ProcessTextTask {
  content: string;
  operation: 'markdown-to-html' | 'sanitize' | 'truncate' | 'extract-keywords';
  options?: Record<string, any>;
}

class ChatWorkerManager {
  private worker: Worker | null = null;
  // eslint-disable-next-line @typescript-eslint/no-unsafe-function-type
  private taskQueue = new Map<string, { resolve: Function; reject: Function }>();
  private isInitialized = false;

  async init(): Promise<void> {
    if (this.isInitialized) return;

    // eslint-disable-next-line no-useless-catch
    try {
      const workerCode = this.getWorkerCode();
      const blob = new Blob([workerCode], { type: 'application/javascript' });
      const workerUrl = URL.createObjectURL(blob);

      this.worker = new Worker(workerUrl);
      this.worker.onmessage = this.handleMessage.bind(this);
      this.worker.onerror = this.handleError.bind(this);

      this.isInitialized = true;
    } catch (error) {
      throw error;
    }
  }

  async exportData(task: ExportTask): Promise<string> {
    await this.init();

    return new Promise((resolve, reject) => {
      const taskId = crypto.randomUUID();
      this.taskQueue.set(taskId, { resolve, reject });

      this.worker!.postMessage({
        type: 'export:start',
        payload: task,
        id: taskId,
      });
    });
  }

  async processText(task: ProcessTextTask): Promise<string> {
    await this.init();

    return new Promise((resolve, reject) => {
      const taskId = crypto.randomUUID();
      this.taskQueue.set(taskId, { resolve, reject });

      this.worker!.postMessage({
        type: 'process:text',
        payload: task,
        id: taskId,
      });
    });
  }

  cancelTask(taskId?: string): void {
    if (!this.worker) return;
    if (taskId) {
      this.taskQueue.delete(taskId);
    } else {
      this.taskQueue.clear();
    }
  }

  terminate(): void {
    if (this.worker) {
      this.worker.terminate();
      this.worker = null;
      this.isInitialized = false;
      this.taskQueue.clear();
    }
  }

  private handleMessage(event: MessageEvent<WorkerMessage>): void {
    const { type, payload, id } = event.data;

    switch (type) {
      case 'export:complete':
      case 'process:complete': {
        const resolver = this.taskQueue.get(id!);
        if (resolver) {
          resolver.resolve(payload as string);
          this.taskQueue.delete(id!);
        }
        break;
      }
      case 'export:error':
      case 'error': {
        const rejecter = this.taskQueue.get(id!);
        if (rejecter) {
          rejecter.reject(new Error(payload as string));
          this.taskQueue.delete(id!);
        }
        break;
      }
    }
  }

  private handleError(error: ErrorEvent): void {
    this.taskQueue.forEach(({ reject }) => {
      reject(new Error('Worker error: ' + error.message));
    });
    this.taskQueue.clear();
  }

  private getWorkerCode(): string {
    return `
      self.onmessage = function(event) {
        var data = event.data;
        var type = data.type;
        var payload = data.payload;
        var id = data.id;

        switch (type) {
          case 'export:start':
            handleExport(payload, id);
            break;
          case 'process:text':
            handleProcessText(payload, id);
            break;
        }
      };

      function handleExport(task, taskId) {
        try {
          var data = task.data;
          var format = task.format;
          var options = task.options || {};
          var result = '';

          switch (format) {
            case 'json':
              result = JSON.stringify(data, null, options.prettyPrint ? 2 : void 0);
              break;
            case 'csv':
              result = convertToCSV(data, options.delimiter || ',');
              break;
            case 'txt':
              result = convertToTXT(data);
              break;
            case 'html':
              result = convertToHTML(data, options.includeHeaders !== false);
              break;
            case 'markdown':
              result = convertToMarkdown(data);
              break;
          }

          for (var i = 0; i <= 10; i++) {
            setTimeout(function(idx, res) {
              return function() {
                self.postMessage({
                  type: 'export:progress',
                  payload: { percentage: idx * 10 },
                  id: taskId
                });

                if (idx === 10) {
                  self.postMessage({
                    type: 'export:complete',
                    payload: res,
                    id: taskId
                  });
                }
              };
            }(i, result), i * 50);
          }
        } catch (error) {
          self.postMessage({
            type: 'export:error',
            payload: error.message,
            id: taskId
          });
        }
      }

      function handleProcessText(task, taskId) {
        try {
          var content = task.content;
          var operation = task.operation;
          var options = task.options || {};
          var result = '';

          switch (operation) {
            case 'markdown-to-html':
              result = simpleMarkdownToHTML(content);
              break;
            case 'sanitize':
              result = sanitizeHTML(content);
              break;
            case 'truncate':
              var maxLength = options.maxLength || 200;
              result = content.length > maxLength ? content.slice(0, maxLength) + '...' : content;
              break;
            case 'extract-keywords':
              result = extractKeywords(content, options.count || 5);
              break;
          }

          self.postMessage({
            type: 'process:complete',
            payload: result,
            id: taskId
          });
        } catch (error) {
          self.postMessage({
            type: 'error',
            payload: error.message,
            id: taskId
          });
        }
      }

      function convertToCSV(data, delimiter) {
        if (!data.length) return '';
        var headers = Object.keys(data[0]);
        var csvRows = [headers.join(delimiter)];

        for (var i = 0; i < data.length; i++) {
          var row = data[i];
          var values = [];
          for (var j = 0; j < headers.length; j++) {
            var header = headers[j];
            var value = row[header];
            var stringValue = String(value !== void 0 && value !== null ? value : '');
            if (stringValue.indexOf(delimiter) !== -1 || stringValue.indexOf('"') !== -1) {
              values.push('"' + stringValue.replace(/"/g, '""') + '"');
            } else {
              values.push(stringValue);
            }
          }
          csvRows.push(values.join(delimiter));
        }

        return csvRows.join('\\n');
      }

      function convertToTXT(data) {
        var lines = [];
        for (var i = 0; i < data.length; i++) {
          lines.push(JSON.stringify(data[i]));
        }
        return lines.join('\\n');
      }

      function convertToHTML(data, includeHeaders) {
        var html = '<table>\\n';

        if (includeHeaders && data.length > 0) {
          html += '  <tr>\\n';
          var headers = Object.keys(data[0]);
          for (var i = 0; i < headers.length; i++) {
            html += '    <th>' + headers[i] + '</th>\\n';
          }
          html += '  </tr>\\n';
        }

        for (var j = 0; j < data.length; j++) {
          html += '  <tr>\\n';
          var row = data[j];
          var values = Object.values(row);
          for (var k = 0; k < values.length; k++) {
            html += '    <td>' + (values[k] !== void 0 && values[k] !== null ? values[k] : '') + '</td>\\n';
          }
          html += '  </tr>\\n';
        }

        html += '</table>';
        return html;
      }

      function convertToMarkdown(data) {
        if (!data.length) return '';
        var headers = Object.keys(data[0]);
        var md = '| ' + headers.join(' | ') + ' |\\n';
        var separators = [];
        for (var i = 0; i < headers.length; i++) {
          separators.push('---');
        }
        md += '| ' + separators.join(' | ') + ' |\\n';

        for (var j = 0; j < data.length; j++) {
          var row = data[j];
          var values = [];
          for (var k = 0; k < headers.length; k++) {
            var val = row[headers[k]];
            values.push(val !== void 0 && val !== null ? val : '');
          }
          md += '| ' + values.join(' | ') + ' |\\n';
        }

        return md;
      }

      function simpleMarkdownToHTML(markdown) {
        return markdown
          .replace(/^### (.+)$/gm, '<h3>$1</h3>')
          .replace(/^## (.+)$/gm, '<h2>$1</h2>')
          .replace(/^# (.+)$/gm, '<h1>$1</h1>')
          .replace(/\\*\\*(.+?)\\*\\*/g, '<strong>$1</strong>')
          .replace(/\\*(.+?)\\*/g, '<em>$1</em>')
          .replace(/\\n/g, '<br>');
      }

      function sanitizeHTML(html) {
        var div = document.createElement('div');
        div.textContent = html;
        return div.innerHTML;
      }

      function extractKeywords(text, count) {
        var words = text.toLowerCase().match(/\\b[a-z\\u4e00-\\u9fa5]+\\b/g) || [];
        var frequency = {};

        for (var i = 0; i < words.length; i++) {
          var word = words[i];
          frequency[word] = (frequency[word] || 0) + 1;
        }

        var entries = Object.entries(frequency);
        entries.sort(function(a, b) { return b[1] - a[1]; });
        var topWords = entries.slice(0, count);
        var result = [];
        for (var j = 0; j < topWords.length; j++) {
          result.push(topWords[j][0]);
        }
        return result.join(', ');
      }
    `;
  }
}

import { useEffect, useRef, useState, useCallback } from 'react';

interface UseWorkerOptions {
  autoInit?: boolean;
}

interface UseWorkerReturn {
  isReady: boolean;
  isProcessing: boolean;

  exportData: (task: ExportTask) => Promise<string>;
  processText: (task: ProcessTextTask) => Promise<string>;
  cancelCurrentTask: () => void;
  terminate: () => void;
}

export function useChatWorker(options: UseWorkerOptions = {}): UseWorkerReturn {
  const { autoInit = true } = options;

  const workerRef = useRef<ChatWorkerManager | null>(null);
  const [isReady, setIsReady] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);

  useEffect(() => {
    if (autoInit) {
      initWorker();
    }

    return () => {
      workerRef.current?.terminate();
    };
  }, [autoInit]);

  const initWorker = useCallback(async () => {
    try {
      workerRef.current = new ChatWorkerManager();
      await workerRef.current.init();
      setIsReady(true);
    } catch {
      setIsReady(false);
    }
  }, []);

  const exportData = useCallback(async (task: ExportTask): Promise<string> => {
    if (!workerRef.current) throw new Error('Worker not initialized');
    setIsProcessing(true);
    try {
      return await workerRef.current.exportData(task);
    } finally {
      setIsProcessing(false);
    }
  }, []);

  const processText = useCallback(async (task: ProcessTextTask): Promise<string> => {
    if (!workerRef.current) throw new Error('Worker not initialized');
    setIsProcessing(true);
    try {
      return await workerRef.current.processText(task);
    } finally {
      setIsProcessing(false);
    }
  }, []);

  const cancelCurrentTask = useCallback(() => {
    workerRef.current?.cancelTask();
    setIsProcessing(false);
  }, []);

  const terminate = useCallback(() => {
    workerRef.current?.terminate();
    setIsReady(false);
    setIsProcessing(false);
  }, []);

  return {
    isReady,
    isProcessing,
    exportData,
    processText,
    cancelCurrentTask,
    terminate,
  };
}

export { ChatWorkerManager, type ExportTask, type ProcessTextTask };
export default ChatWorkerManager;

/**
 * CompactionLock - 压缩锁机制
 *
 * 基于 DeepSeek Harness 的 CompactionLock 实现：
 * - 防止并发压缩导致数据不一致
 * - 未匹配的 start 阻止所有入口点
 * - 自动超时释放
 */

import { logger } from '@/utils/safeLogger';

export type CompactionId = string;
export type TurnId = string;

export interface CompactionLock {
  /** 压缩操作唯一 ID */
  compactionId: CompactionId;
  /** 触发的 turn ID (自动压缩为数字, 手动为 null) */
  turn: TurnId | null;
  /** 锁定开始时间 */
  startedAt: number;
  /** 是否已释放 */
  released: boolean;
}

export interface CompactionLockOptions {
  /** 锁超时时间 (默认 30 秒) */
  timeoutMs?: number;
  /** 锁所有者标识 */
  owner?: string;
}

const DEFAULT_TIMEOUT_MS = 30_000;
const LOCK_SUFFIX = '-lock';

let _activeLock: CompactionLock | null = null;
let _lockCounter = 0;

/**
 * 生成唯一的压缩锁 ID
 */
function generateLockId(): CompactionId {
  _lockCounter++;
  return `compaction-lock-${Date.now()}-${_lockCounter}`;
}

/**
 * 获取当前活动的压缩锁
 */
export function getActiveCompactionLock(): CompactionLock | null {
  // 检查锁是否已超时
  if (_activeLock && _activeLock.released) {
    _activeLock = null;
  }
  if (_activeLock && Date.now() - _activeLock.startedAt > DEFAULT_TIMEOUT_MS) {
    logger.warn('[CompactionLock] Lock timed out, releasing');
    _activeLock = null;
  }
  return _activeLock;
}

/**
 * 尝试获取压缩锁
 * @returns 锁对象或 null (已被占用)
 */
export async function tryAcquireCompactionLock(
  turnId: TurnId | null = null,
  options: CompactionLockOptions = {},
): Promise<CompactionLock | null> {
  const { timeoutMs = DEFAULT_TIMEOUT_MS, owner = 'unknown' } = options;

  // 检查是否已有锁 —— 已被占用则直接返回 null（非阻塞，避免调用方无意义等待）
  const existingLock = getActiveCompactionLock();
  if (existingLock && !existingLock.released) {
    logger.warn(`[CompactionLock] Lock already held by ${existingLock.compactionId}, returning null`);
    return null;
  }

  // 创建新锁
  const lock: CompactionLock = {
    compactionId: generateLockId(),
    turn: turnId,
    startedAt: Date.now(),
    released: false,
  };

  _activeLock = lock;
  logger.info(`[CompactionLock] Acquired lock: ${lock.compactionId}, owner=${owner}`);

  // 启动超时释放
  setTimeout(() => {
    if (!lock.released) {
      logger.warn(`[CompactionLock] Auto-releasing lock due to timeout: ${lock.compactionId}`);
      releaseCompactionLock(lock.compactionId, 'timeout');
    }
  }, timeoutMs);

  return lock;
}

/**
 * 释放压缩锁
 */
export function releaseCompactionLock(
  compactionId: CompactionId,
  reason: 'completed' | 'failed' | 'timeout' | 'cancelled',
): void {
  if (_activeLock?.compactionId === compactionId) {
    _activeLock.released = true;
    logger.info(`[CompactionLock] Released lock: ${compactionId}, reason=${reason}`);
    _activeLock = null;
  } else {
    logger.warn(`[CompactionLock] Attempted to release non-active lock: ${compactionId}`);
  }
}

/**
 * 检查是否可以执行压缩
 */
export function canCompact(): boolean {
  return getActiveCompactionLock() === null;
}

/**
 * 获取锁状态信息
 */
export function getLockStatus(): {
  hasLock: boolean;
  lockId?: CompactionId;
  turnId?: TurnId;
  elapsedMs?: number;
  isExpired: boolean;
} {
  const lock = getActiveCompactionLock();
  if (!lock) {
    return { hasLock: false, isExpired: false };
  }

  const elapsed = Date.now() - lock.startedAt;
  const isExpired = elapsed > DEFAULT_TIMEOUT_MS;

  return {
    hasLock: true,
    lockId: lock.compactionId,
    turnId: lock.turn ?? undefined,
    elapsedMs: elapsed,
    isExpired,
  };
}

/**
 * 清除所有锁 (用于测试)
 */
export function clearAllCompactionLocks(): void {
  _activeLock = null;
  _lockCounter = 0;
  logger.info('[CompactionLock] All locks cleared');
}

