// ===== 版本控制辅助 =====

/**
 * 计算两个配方的差异
 */
export function compareFormulas(v1: NormalizedFormula, v2: NormalizedFormula): {
  addedIngredients: string[]
  removedIngredients: string[]
  modifiedIngredients: { name: string; changes: string[] }[]
  metadataChanges: string[]
} {
  const v1Names = new Set(v1.ingredients.map(i => i.name))
  const v2Names = new Set(v2.ingredients.map(i => i.name))

  const added = v2.ingredients.filter(i => !v1Names.has(i.name)).map(i => i.name)
  const removed = v1.ingredients.filter(i => !v2Names.has(i.name)).map(i => i.name)

  const modified: { name: string; changes: string[] }[] = []
  v2.ingredients.forEach(i2 => {
    const i1 = v1.ingredients.find(i => i.name === i2.name)
    if (i1 && i1.percentage !== i2.percentage) {
      modified.push({
        name: i2.name,
        changes: [`百分比变更: ${i1.percentage}% → ${i2.percentage}%`],
      })
    }
  })

  const metaChanges: string[] = []
  if (v1.name !== v2.name) metaChanges.push(`名称变更: ${v1.name} → ${v2.name}`)
  if (v1.version !== v2.version) metaChanges.push(`版本变更: ${v1.version} → ${v2.version}`)

  return {
    addedIngredients: added,
    removedIngredients: removed,
    modifiedIngredients: modified,
    metadataChanges: metaChanges,
  }
}

/**
 * networkAwareness — 网络状态感知工具
 *
 * 功能：
 * - 检测在线/离线状态（navigator.onLine + online/offline 事件）
 * - 连接质量评估（NetworkInformation API：effectiveType / rtt / downlink）
 * - 所有网络 API 做特性检测，fallback 到 navigator.onLine
 */
import { logger } from '@/utils/safeLogger'

export interface NetworkStatus {
  isOnline: boolean
  effectiveType?: 'slow-2g' | '2g' | '3g' | '4g'
  rtt?: number          // 往返时间 ms
  downlink?: number     // 下行速度 Mbps
  saveData?: boolean    // 是否开启省流模式
  isSlowConnection: boolean // <3g 或 rtt > 300ms
}

type NetworkChangeListener = (status: NetworkStatus) => void

/** 网络类型排序（用于判断慢速连接） */
const SLOW_TYPES = new Set(['slow-2g', '2g'])
const RTT_SLOW_THRESHOLD = 300 // ms

/**
 * 获取当前网络连接信息（特性检测 + fallback）
 */
function getConnectionInfo(): Partial<NetworkStatus> {
  if (typeof navigator === 'undefined') {
    return { isOnline: true, isSlowConnection: false }
  }

  const nav = navigator

  // 尝试获取 NetworkInformation API
  const connection = nav.connection || nav.mozConnection || nav.webkitConnection

  if (!connection) {
    // fallback：仅使用 onLine
    return {
      isOnline: navigator.onLine ?? true,
      isSlowConnection: false,
    }
  }

  const effectiveType = connection.effectiveType as NetworkStatus['effectiveType'] | undefined
  const rtt = typeof connection.rtt === 'number' ? connection.rtt : undefined
  const downlink = typeof connection.downlink === 'number' ? connection.downlink : undefined
  const saveData = !!connection.saveData

  const isSlowConnection =
    (effectiveType !== undefined && SLOW_TYPES.has(effectiveType)) ||
    (rtt !== undefined && rtt > RTT_SLOW_THRESHOLD)

  return {
    isOnline: navigator.onLine ?? true,
    effectiveType,
    rtt,
    downlink,
    saveData,
    isSlowConnection,
  }
}

class NetworkAwareness {
  private listeners: Set<NetworkChangeListener> = new Set()
  private currentStatus: NetworkStatus
  private boundOnlineHandler: () => void
  private boundOfflineHandler: () => void
  private boundChangeHandler: () => void
  private connectionEventListener: EventListener | null = null

  constructor() {
    this.currentStatus = this.buildStatus()
    this.boundOnlineHandler = this.handleOnline.bind(this)
    this.boundOfflineHandler = this.handleOffline.bind(this)
    this.boundChangeHandler = this.handleChange.bind(this)

    if (typeof window !== 'undefined') {
      this.setupListeners()
    }
  }

  private buildStatus(): NetworkStatus {
    const info = getConnectionInfo()
    return info as NetworkStatus
  }

  private setupListeners(): void {
    window.addEventListener('online', this.boundOnlineHandler)
    window.addEventListener('offline', this.boundOfflineHandler)

    // 监听 NetworkInformation 变化
    const nav = navigator
    const connection = nav.connection || nav.mozConnection || nav.webkitConnection

    if (connection) {
      this.connectionEventListener = this.boundChangeHandler
      connection.addEventListener('change', this.connectionEventListener)
      logger.debug('[NetworkAwareness] NetworkInformation API 已监听')
    }
  }

  private handleOnline(): void {
    logger.info('[NetworkAwareness] 网络已恢复在线')
    this.updateStatus()
  }

  private handleOffline(): void {
    logger.warn('[NetworkAwareness] 网络已断开离线')
    this.updateStatus()
  }

  private handleChange(): void {
    logger.debug('[NetworkAwareness] 网络连接质量变化')
    this.updateStatus()
  }

  private updateStatus(): void {
    this.currentStatus = this.buildStatus()
    this.notifyListeners()
  }

  private notifyListeners(): void {
    for (const listener of this.listeners) {
      try {
        listener(this.currentStatus)
      } catch (error) {
        logger.error('[NetworkAwareness] 监听器回调异常:', error)
      }
    }
  }

  /** 获取当前网络状态快照 */
  getStatus(): NetworkStatus {
    return { ...this.currentStatus }
  }

  /** 订阅网络状态变化 */
  subscribe(listener: NetworkChangeListener): () => void {
    this.listeners.add(listener)

    // 立即推送一次当前状态
    try {
      listener(this.currentStatus)
    } catch (_error) {
      // 忽略首次调用异常
    }

    // 返回取消订阅函数
    return () => {
      this.listeners.delete(listener)
    }
  }

  /** 销毁实例，清理所有监听器 */
  destroy(): void {
    if (typeof window !== 'undefined') {
      window.removeEventListener('online', this.boundOnlineHandler)
      window.removeEventListener('offline', this.boundOfflineHandler)

      const nav = navigator
      const connection = nav.connection || nav.mozConnection || nav.webkitConnection
      if (connection && this.connectionEventListener) {
        connection.removeEventListener('change', this.connectionEventListener)
      }
    }

    this.listeners.clear()
    logger.debug('[NetworkAwareness] 实例已销毁')
  }
}

// ===== 单例模式 =====
let instance: NetworkAwareness | null = null

export function getNetworkAwareness(): NetworkAwareness {
  if (!instance) {
    instance = new NetworkAwareness()
  }
  return instance
}

export { NetworkAwareness }
export default getNetworkAwareness

import { logger } from '@/utils/safeLogger'
import { eventBus, IEventBus } from '../services/eventBus'
import { chatService } from '../services/chatService'

type SyncStatus = 'online' | 'offline' | 'syncing' | 'error'
interface QueueItem {
  id: string
  type: 'message' | 'action'
  payload: any
  timestamp: number
  retryCount: number
  priority?: 'high' | 'medium' | 'low'
}

interface OfflineConfig {
  enabled: boolean
  maxQueueSize: number
  maxRetries: number
  retryDelayMs: number
  syncOnResume: boolean
  storageKey: string
  onStatusChange?: (status: SyncStatus) => void
  onSyncComplete?: (successCount: number, failCount: number) => void
}

class OfflineManager {
  private config: OfflineConfig
  private status: SyncStatus = 'online'
  private pendingQueue: QueueItem[] = []
  private isOnline = true
  private syncInProgress = false
  private eventBus: IEventBus

  constructor(config: Partial<OfflineConfig> = {}) {
    this.config = {
      enabled: true,
      maxQueueSize: 100,
      maxRetries: 3,
      retryDelayMs: 1000,
      syncOnResume: true,
      storageKey: 'rmfood_offline_queue',
      ...config,
    }

    this.eventBus = eventBus

    if (typeof window !== 'undefined') {
      this.initialize()
    }
  }

  private initialize(): void {
    if (!this.config.enabled) return

    this.loadQueueFromStorage()
    this.setupNetworkListeners()

    if (!navigator.onLine) {
      this.setStatus('offline')
    }

    logger.info('[OfflineManager] 初始化离线管理', {
      queueSize: this.pendingQueue.length,
      isOnline: navigator.onLine,
    })
  }

  private setupNetworkListeners(): void {
    // 存储绑定后的处理器引用，确保 destroy() 能正确移除
    this._onlineHandler = this.handleOnline.bind(this)
    this._offlineHandler = this.handleOffline.bind(this)
    this._visibilityHandler = () => {
      if (document.visibilityState === 'visible' && navigator.onLine) {
        this.syncPendingItems()
      }
    }
    window.addEventListener('online', this._onlineHandler)
    window.addEventListener('offline', this._offlineHandler)
    document.addEventListener('visibilitychange', this._visibilityHandler)
  }

  /** 绑定后的事件处理器引用（用于 destroy 时正确移除） */
  private _onlineHandler: (() => void) | null = null
  private _offlineHandler: (() => void) | null = null
  private _visibilityHandler: (() => void) | null = null

  private handleOnline(): void {
    logger.info('[OfflineManager] 网络已恢复')
    this.isOnline = true

    if (this.config.syncOnResume) {
      this.syncPendingItems()
    }
  }

  private handleOffline(): void {
    logger.warn('[OfflineManager] 网络连接断开')
    this.isOnline = false
    this.setStatus('offline')
  }

  setStatus(status: SyncStatus): void {
    const previousStatus = this.status
    this.status = status

    logger.info(`[OfflineManager] 状态变更: ${previousStatus} → ${status}`)

    this.eventBus.emit('state:changed', {
      newState: `offline_${status}`,
      previousState: `offline_${previousStatus}`,
    })

    this.config.onStatusChange?.(status)
  }

  getStatus(): SyncStatus {
    return this.status
  }

  isOnlineStatus(): boolean {
    return this.isOnline
  }

  async enqueue<T>(type: 'message' | 'action', payload: T): Promise<string> {
    if (!this.config.enabled) {
      throw new Error('离线模式未启用')
    }

    const item: QueueItem = {
      id: crypto.randomUUID(),
      type,
      payload,
      timestamp: Date.now(),
      retryCount: 0,
    }

    if (this.pendingQueue.length >= this.config.maxQueueSize) {
      const removed = this.pendingQueue.shift()
      logger.warn(`[OfflineManager] 队列已满，移除最旧项: ${removed?.id}`)
    }

    this.pendingQueue.push(item)
    await this.persistQueue()

    this.eventBus.emit('export:started', {
      format: 'offline-queue',
      itemCount: this.pendingQueue.length,
    })

    logger.debug(`[OfflineManager] 新增队列项 [${type}]: ${item.id}`, {
      queueLength: this.pendingQueue.length,
    })

    if (this.isOnline && !this.syncInProgress) {
      this.syncPendingItems()
    }

    return item.id
  }

  removeItem(id: string): boolean {
    const index = this.pendingQueue.findIndex(item => item.id === id)
    if (index > -1) {
      this.pendingQueue.splice(index, 1)
      this.persistQueue()
      return true
    }
    return false
  }

  clearQueue(): void {
    const count = this.pendingQueue.length
    this.pendingQueue = []
    localStorage.removeItem(this.config.storageKey)
    logger.info(`[OfflineManager] 队列已清空 (${count} 项)`)
  }

  getQueueSize(): number {
    return this.pendingQueue.length
  }

  getPendingItems(): readonly QueueItem[] {
    return [...this.pendingQueue]
  }

  async syncPendingItems(): Promise<{ success: number; failed: number }> {
    if (this.syncInProgress || this.pendingQueue.length === 0) {
      return { success: 0, failed: 0 }
    }

    this.syncInProgress = true
    this.setStatus('syncing')

    let successCount = 0
    let failedCount = 0
    const failedItems: QueueItem[] = []

    logger.info(`[OfflineManager] 开始同步队列 (${this.pendingQueue.length} 项)`)

    for (const item of [...this.pendingQueue]) {
      try {
        await this.processItem(item)

        const index = this.pendingQueue.findIndex(i => i.id === item.id)
        if (index > -1) {
          this.pendingQueue.splice(index, 1)
        }

        successCount++
        logger.debug(`[OfflineManager] 同步成功: ${item.id}`)
      } catch (error) {
        item.retryCount++

        if (item.retryCount < this.config.maxRetries) {
          failedItems.push(item)
          logger.warn(
            `[OfflineManager] 同步失败，将重试 [${item.id}, 第${item.retryCount}次]:`,
            error,
          )

          await this.delay(this.config.retryDelayMs * item.retryCount)
        } else {
          failedCount++
          logger.error(
            `[OfflineManager] 同步最终失败 [${item.id}, 已重试${item.retryCount}次]:`,
            error,
          )

          this.eventBus.emit('message:error', {
            error: error as Error,
            messageId: item.id,
          })
        }
      }
    }

    this.pendingQueue = failedItems
    await this.persistQueue()

    this.syncInProgress = false

    if (!this.isOnline) {
      this.setStatus('offline')
    } else {
      this.setStatus('online')
    }

    logger.info(`[OfflineManager] 同步完成 (成功: ${successCount}, 失败: ${failedCount})`)

    this.eventBus.emit('export:completed', {
      filePath: '',
      success: failedCount === 0,
    })

    this.config.onSyncComplete?.(successCount, failedCount)

    return { success: successCount, failed: failedCount }
  }

  private async processItem(item: QueueItem): Promise<void> {
    switch (item.type) {
      case 'message':
        await this.syncMessage(item.payload)
        break
      case 'action':
        await this.syncAction(item.payload)
        break
      default:
        throw new Error(`未知队列项类型: ${item.type}`)
    }
  }

  private async syncMessage(payload: any): Promise<void> {
    // 复用 chatService.sendMessage：统一走 axios 认证拦截器（cookie 自动携带 + 401 自动刷新），
    // 并获得去重、重试、CSRF、状态机、事件总线等能力，避免裸 fetch 在 401 时认证链路断裂
    const response = await chatService.sendMessage(payload.question)
    this.eventBus.emit('message:received', {
      content: response.content,
      senderId: 'assistant',
      timestamp: Date.now(),
      ...(response.formulas && { formulas: response.formulas }),
    })
  }

  private async syncAction(payload: any): Promise<void> {
    switch (payload.action) {
      case 'export':
        logger.info(`[OfflineManager] 同步导出操作:`, payload.format)
        break
      case 'clear_history':
        logger.info('[OfflineManager] 同步清空历史操作')
        break
      default:
        logger.warn(`[OfflineManager] 未知操作类型: ${payload.action}`)
    }
  }

  private async persistQueue(): Promise<void> {
    try {
      localStorage.setItem(
        this.config.storageKey,
        JSON.stringify({
          version: '1.0',
          timestamp: Date.now(),
          items: this.pendingQueue,
        }),
      )
    } catch (error) {
      logger.error('[OfflineManager] 持久化队列失败:', error instanceof Error ? error : new Error(String(error)))

      if ((error as DOMException).name === 'QuotaExceededError') {
        this.handleQuotaExceeded()
      }
    }
  }

  private loadQueueFromStorage(): void {
    try {
      const stored = localStorage.getItem(this.config.storageKey)
      if (!stored) return

      const parsed = JSON.parse(stored)
      if (parsed.items && Array.isArray(parsed.items)) {
        this.pendingQueue = parsed.items

        logger.info(`[OfflineManager] 从存储恢复队列 (${this.pendingQueue.length} 项)`)

        if (parsed.timestamp) {
          const ageMinutes = (Date.now() - parsed.timestamp) / (1000 * 60)
          if (ageMinutes > 60) {
            logger.warn(`[OfflineManager] 队列数据较旧 (${ageMinutes.toFixed(0)} 分钟前)`)
          }
        }
      }
    } catch (error) {
      logger.error('[OfflineManager] 加载队列失败:', error)
      this.pendingQueue = []
    }
  }

  private handleQuotaExceeded(): void {
    logger.warn('[OfflineManager] 存储配额不足，清理旧数据')

    const sortedByTime = [...this.pendingQueue].sort((a, b) => a.timestamp - b.timestamp)
    const toRemove = Math.ceil(sortedByTime.length * 0.3)

    this.pendingQueue = sortedByTime.slice(toRemove)

    this.persistQueue().catch(err => {
      logger.error('[OfflineManager] 清理后持久化仍失败:', err)
    })
  }

  private delay(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms))
  }

  getStatistics(): {
    queueSize: number
    status: SyncStatus
    oldestItemAge: number | null
    retryStats: { total: number; avg: number; max: number }
  } {
    const now = Date.now()
    const retries = this.pendingQueue.map(item => item.retryCount)

    return {
      queueSize: this.pendingQueue.length,
      status: this.status,
      oldestItemAge: this.pendingQueue.length > 0
        ? now - Math.min(...this.pendingQueue.map(item => item.timestamp))
        : null,
      retryStats: {
        total: retries.reduce((sum, r) => sum + r, 0),
        avg: retries.length > 0 ? retries.reduce((a, b) => a + b, 0) / retries.length : 0,
        max: retries.length > 0 ? Math.max(...retries) : 0,
      },
    }
  }

  destroy(): void {
    // 使用存储的绑定引用正确移除监听器（避免 bind() 创建新引用的问题）
    if (this._onlineHandler) {
      window.removeEventListener('online', this._onlineHandler)
      this._onlineHandler = null
    }
    if (this._offlineHandler) {
      window.removeEventListener('offline', this._offlineHandler)
      this._offlineHandler = null
    }
    if (this._visibilityHandler) {
      document.removeEventListener('visibilitychange', this._visibilityHandler)
      this._visibilityHandler = null
    }

    if (this.syncInProgress) {
      this.syncInProgress = false
    }

    this.clearQueue()
    logger.info('[OfflineManager] 实例已销毁')
  }
}

export { OfflineManager, type OfflineConfig, type SyncStatus, type QueueItem }

// 单例实例
export const offlineManager = new OfflineManager()
export default OfflineManager

/**
 * 投影缓存优化
 *
 * 基于 DeepSeek Harness 的 SessionProjection 实现：
 * - 缓存派生消息，避免重复计算
 * - 基于内容 hash 失效
 */

import { useRef, useMemo, useCallback } from 'react';
import type { AgentMessage } from '@/components/ai/shared/types';

// ── Hash 计算 ──────────────────────────────────────────────

function simpleHash(str: string): string {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash; // Convert to 32bit integer
  }
  return Math.abs(hash).toString(36);
}

function messageHash(msg: AgentMessage): string {
  return simpleHash(`${msg.id}-${msg.content}-${msg.timestamp.getTime()}`);
}

// ── 缓存结构 ───────────────────────────────────────────────

interface CacheEntry {
  hash: string;
  messages: AgentMessage[];
  tokenEstimate: number;
  updatedAt: number;
}

// ── 单例缓存 ───────────────────────────────────────────────

const cache = new Map<string, CacheEntry>();
const MAX_CACHE_SIZE = 100;

function evictOldest(): void {
  if (cache.size >= MAX_CACHE_SIZE) {
    const oldestKey = Array.from(cache.entries())
      .sort((a, b) => a[1].updatedAt - b[1].updatedAt)[0]?.[0];
    if (oldestKey) cache.delete(oldestKey);
  }
}

// ── 投影缓存 Hook ──────────────────────────────────────────

export function useProjectionCache() {
  const invalidateRef = useRef<(() => void)[]>([]);

  /**
   * 获取或计算派生消息 (带缓存)
   */
  const getProjectedMessages = useMemo(() => {
    return (messages: AgentMessage[]): AgentMessage[] => {
      // 生成缓存 key
      const key = messages.map(messageHash).join('|');

      // 检查缓存
      const cached = cache.get(key);
      if (cached && Date.now() - cached.updatedAt < 5000) {
        return cached.messages;
      }

      // 未命中，计算并缓存
      evictOldest();
      const entry: CacheEntry = {
        hash: key,
        messages,
        tokenEstimate: estimateTokens(messages),
        updatedAt: Date.now(),
      };
      cache.set(key, entry);

      return messages;
    };
  }, []);

  /**
   * 清除缓存
   */
  const clearCache = useCallback(() => {
    cache.clear();
  }, []);

  /**
   * 获取缓存统计
   */
  const stats = useMemo(() => ({
    size: cache.size,
    maxEntries: MAX_CACHE_SIZE,
  }), [cache.size]);

  return { getProjectedMessages, clearCache, stats };
}

/**
 * 估算 token 数量
 */
function estimateTokens(messages: AgentMessage[]): number {
  let total = 0;
  for (const msg of messages) {
    // 简单估算：中文字符 1.5 字符/token，ASCII 4 字符/token
    let chinese = 0;
    let ascii = 0;
    for (const char of msg.content) {
      if (/[\u4e00-\u9fa5]/.test(char)) chinese++;
      else ascii++;
    }
    total += Math.ceil(chinese / 1.5 + ascii / 4);
  }
  return total;
}

/**
 * Ralph Loop - 面向目标的 Fresh-Agent 迭代工作流
 *
 * 基于 DeepSeek Harness 的 Ralph 循环模式：
 * - 每轮创建 fresh child session
 * - Handoff 结构化传递状态
 * - 直到目标完成或达到预算
 */

import { logger } from '@/utils/safeLogger';
import type { SessionId, ContentBlock } from '@/components/ai/shared/types';

// ── 类型定义 ────────────────────────────────────────────────

export type RalphStatus = 'in_progress' | 'blocked' | 'completed';

export interface RalphHandoff {
  status: RalphStatus;
  summary: string;
  evidence: ContentBlock[];
  nextSteps: string[];
  blocker?: string;
  round?: number;
}

export interface RalphBudget {
  maxRounds: number;
  timeoutMs?: number;
}

export interface RalphResult {
  success: boolean;
  rounds: number;
  finalHandoff: RalphHandoff;
  error?: string;
}

// ── Ralph Handoff 解析器 ────────────────────────────────────

export function parseHandoffFromText(text: string): RalphHandoff {
  const handoff: RalphHandoff = {
    status: 'in_progress',
    summary: '',
    evidence: [],
    nextSteps: [],
  };

  // 解析 JSON 格式
  try {
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      return {
        status: parsed.status ?? 'in_progress',
        summary: parsed.summary ?? '',
        evidence: parsed.evidence ?? [],
        nextSteps: parsed.nextSteps ?? [],
        blocker: parsed.blocker,
        round: parsed.round,
      };
    }
  } catch {
    // 降级到文本解析
  }

  // 文本解析
  const summaryMatch = text.match(/summary[:\s]+([^\n]+)/i);
  if (summaryMatch) handoff.summary = summaryMatch[1].trim();

  const statusMatch = text.match(/status[:\s]+(\w+)/i);
  if (statusMatch) {
    handoff.status = statusMatch[1].toLowerCase() as RalphStatus;
  }

  const nextStepsMatch = text.match(/next steps[:\s]+([^\n]+)/i);
  if (nextStepsMatch) {
    handoff.nextSteps = nextStepsMatch[1].split(',').map(s => s.trim());
  }

  return handoff;
}

export function formatHandoffForInput(handoff: RalphHandoff): string {
  return JSON.stringify({
    status: handoff.status,
    summary: handoff.summary,
    evidence: handoff.evidence,
    nextSteps: handoff.nextSteps,
    blocker: handoff.blocker,
    round: handoff.round ?? 0,
  }, null, 2);
}

// ── Ralph Loop 引擎 ────────────────────────────────────────

export class RalphLoopEngine {
  private readonly MAX_DEFAULT_ROUNDS = 10;
  private readonly TIMEOUT_MS = 60_000;

  /**
   * 执行 Ralph 循环
   * @param objective 不可变目标
   * @param budget 预算限制
   * @param agentFactory 创建 fresh agent 的工厂函数
   */
  async execute(
    objective: string,
    budget: RalphBudget = { maxRounds: this.MAX_DEFAULT_ROUNDS },
    agentFactory: (handoff: RalphHandoff, round: number) => Promise<RalphHandoff>,
  ): Promise<RalphResult> {
    let handoff: RalphHandoff = {
      status: 'in_progress',
      summary: `Ralph 循环开始: ${objective}`,
      evidence: [],
      nextSteps: [objective],
      round: 0,
    };

    const startTime = Date.now();
    let round = 0;

    logger.info(`[RalphLoop] Starting loop for objective: ${objective}`);

    for (round = 1; round <= budget.maxRounds; round++) {
      // 检查超时
      if (budget.timeoutMs && Date.now() - startTime > budget.timeoutMs) {
        logger.warn('[RalphLoop] Timeout exceeded');
        return {
          success: false,
          rounds: round,
          finalHandoff: { ...handoff, status: 'blocked', blocker: 'timeout' },
          error: 'Timeout exceeded',
        };
      }

      // 执行当前轮次
      handoff.round = round;
      logger.info(`[RalphLoop] Round ${round}/${budget.maxRounds}`);

      try {
        const result = await agentFactory(handoff, round);
        handoff = result;

        // 检查是否完成
        if (handoff.status === 'completed') {
          logger.info('[RalphLoop] Objective completed');
          return {
            success: true,
            rounds: round,
            finalHandoff: handoff,
          };
        }

        // 检查是否阻塞
        if (handoff.status === 'blocked' && handoff.blocker) {
          logger.warn(`[RalphLoop] Blocked: ${handoff.blocker}`);
          return {
            success: false,
            rounds: round,
            finalHandoff: handoff,
            error: handoff.blocker,
          };
        }

      } catch (err) {
        logger.error('[RalphLoop] Round execution failed:', err);
        handoff.status = 'blocked';
        handoff.blocker = err instanceof Error ? err.message : 'Unknown error';
        return {
          success: false,
          rounds: round,
          finalHandoff: handoff,
          error: handoff.blocker,
        };
      }
    }

    // 达到预算上限
    logger.warn('[RalphLoop] Budget exceeded');
    return {
      success: false,
      rounds: round,
      finalHandoff: { ...handoff, status: 'blocked', blocker: 'budget_exceeded' },
      error: 'Budget exceeded',
    };
  }

  /**
   * 创建 Ralph Handoff 初始值
   */
  static createInitialHandoff(objective: string): RalphHandoff {
    return {
      status: 'in_progress',
      summary: `初始目标: ${objective}`,
      evidence: [],
      nextSteps: [objective],
      round: 0,
    };
  }
}

// ── 便捷函数 ────────────────────────────────────────────────

/**
 * 简化的 Ralph 循环执行
 */
export async function runRalphLoop(
  objective: string,
  handler: (handoff: RalphHandoff, round: number) => Promise<RalphHandoff>,
  maxRounds: number = 5,
): Promise<RalphResult> {
  const engine = new RalphLoopEngine();
  return engine.execute(objective, { maxRounds }, handler);
}

import type { ProfessionalReport, AIRecognizedFormula, ReportSection, ReportMetadata } from '@/types/ai.types'

export function generateReportId(): string {
  const timestamp = Date.now().toString(36)
  const randomPart = Math.random().toString(36).substring(2, 10)
  return `RPT-${timestamp}-${randomPart}`.toUpperCase()
}

export function generateContentHash(content: string): string {
  let hash = 0
  for (let i = 0; i < content.length; i++) {
    const char = content.charCodeAt(i)
    hash = ((hash << 5) - hash) + char
    hash = hash & hash
  }
  return Math.abs(hash).toString(36)
}

export function generateSingleFormulaReport(formula: AIRecognizedFormula): ProfessionalReport {
  const now = new Date()
  const reportId = `rpt_${now.getTime()}_${formula.id.slice(0, 8)}`

  const ingredients = formula.ingredients || []
  const totalIngredients = ingredients.length

  const allEfficacyTags = ingredients
    .map(ing => ing.efficacy)
    .filter((tag): tag is string => !!tag && tag.trim().length > 0)

  const uniqueEfficacyTags = [...new Set(allEfficacyTags)]
  const mainEfficacies = uniqueEfficacyTags.slice(0, 3)

  const applicableScenarios: string[] = []
  if (uniqueEfficacyTags.some(tag => tag.includes('免疫') || tag.includes('抗氧化'))) {
    applicableScenarios.push('日常保健')
  }
  if (uniqueEfficacyTags.some(tag => tag.includes('睡眠') || tag.includes('安神'))) {
    applicableScenarios.push('改善睡眠质量')
  }
  if (uniqueEfficacyTags.some(tag => tag.includes('美容') || tag.includes('抗衰老'))) {
    applicableScenarios.push('美容养颜')
  }
  if (applicableScenarios.length === 0) {
    applicableScenarios.push('功能性食品研发', '健康调理方案')
  }

  const sections: ReportSection[] = [
    {
      id: 'cover',
      type: 'cover',
      title: '封面',
      content: {
        title: formula.name,
        subtitle: '专业配方分析报告',
        generatedAt: now.toLocaleString('zh-CN'),
        version: '1.0.0',
        confidence: formula.confidence,
        ingredientCount: totalIngredients,
      },
      order: 0,
    },
    {
      id: 'executive-summary',
      type: 'executive-summary',
      title: '执行摘要',
      content: {
        summary: `本报告针对"${formula.name}"进行专业分析，该配方包含${totalIngredients}种成分，识别置信度为${(formula.confidence * 100).toFixed(1)}%。${mainEfficacies.length > 0 ? `主要功效包括：${mainEfficacies.join('、')}。` : ''}`,
        keyPoints: [
          `成分总数: ${totalIngredients}种`,
          `识别置信度: ${(formula.confidence * 100).toFixed(1)}%`,
          mainEfficacies.length > 0 ? `核心功效: ${mainEfficacies.join('、')}` : '功效待进一步分析',
          `适用场景: ${applicableScenarios.slice(0, 2).join('、')}`,
          `分析时间: ${now.toLocaleString('zh-CN')}`,
        ],
        overallScore: Math.round(formula.confidence * 100),
        recommendation: formula.confidence >= 0.8 ? '推荐使用' : formula.confidence >= 0.6 ? '建议优化后使用' : '需重新评估',
      },
      order: 1,
    },
    {
      id: 'formula-details',
      type: 'formula-details',
      title: '配方详情',
      content: {
        formulaName: formula.name,
        formulaId: formula.id,
        parsedAt: formula.parsedAt.toLocaleString('zh-CN'),
        sourceMessageId: formula.sourceMessageId,
        confidence: formula.confidence,
        ingredientTable: {
          headers: ['序号', '成分名称', '用量', '单位', '功效说明'],
          rows: ingredients.map((ing, idx) => [
            (idx + 1).toString(),
            ing.name,
            ing.dosage || '-',
            ing.unit || '-',
            ing.efficacy || '-',
          ]),
        },
        rawData: formula.rawData,
      },
      order: 2,
    },
    {
      id: 'ingredient-analysis',
      type: 'ingredient-analysis',
      title: '成分分析',
      content: {
        totalIngredients,
        ingredientDetails: ingredients.map((ing, idx) => ({
          index: idx + 1,
          name: ing.name,
          dosage: ing.dosage,
          unit: ing.unit,
