    if (!query.trim()) return;
    setIsTesting(true);
    try {
      const data = await searchChunks(query, 5);
      setResults(data);
      setExpanded(true);
    } catch {
      setResults([]);
    } finally {
      setIsTesting(false);
    }
  }, [query]);

  if (!expanded) {
    return (
      <Card className="p-4 space-y-3">
