// ─── 类型定义 ───
export interface Dimension {
  key: string
  label: string
  type: 'categorical' | 'numerical' | 'temporal'
  values?: string[]
}

export interface Measure {
  key: string
  label: string
  aggregation: 'sum' | 'avg' | 'count' | 'min' | 'max' | 'median' | 'distinct_count'
  format?: (value: number) => string
  unit?: string
}

export interface AnalysisConfig {
  dimensions: Dimension[]
  measures: Measure[]
  rows: string[]       // 行维度
  columns: string[]    // 列维度
  values: string[]     // 度量值
  filters?: {
    dimension: string
    operator: 'eq' | 'neq' | 'in' | 'not_in' | 'gt' | 'lt' | 'gte' | 'lte' | 'contains'
    value: any
  }[]
  sortBy?: string
  sortOrder?: 'asc' | 'desc'
  limit?: number
  drillDownLevel?: number
}

interface PivotCell {
  rowKey: string[]
  colKey: string[]
  value: number | null
  formattedValue: string
  rowLabel: string
  colLabel: string
  isTotal?: boolean
  isSubtotal?: boolean
}

// ─── 预定义的维度和度量 ───
export const PREDEFINED_DIMENSIONS: Dimension[] = [
  { key: 'category', label: '产品类别', type: 'categorical', values: ['功能性食品', '保健品', '营养补充剂', '药食同源'] },
  { key: 'status', label: '状态', type: 'categorical', values: ['草稿', '审核中', '已发布', '已归档'] },
  { key: 'user', label: '负责人', type: 'categorical', values: ['张研发', '李实验', '王配方', '赵测试'] },
  { key: 'time_period', label: '时间周期', type: 'temporal' },
  { key: 'priority', label: '优先级', type: 'categorical', values: ['高', '中', '低'] },
  { key: 'department', label: '部门', type: 'categorical', values: ['研发部', '质量部', '市场部', '运营部'] },
]

export const PREDEFINED_MEASURES: Measure[] = [
  { key: 'formula_count', label: '配方数量', aggregation: 'count', unit: '个' },
  { key: 'experiment_count', label: '实验次数', aggregation: 'sum', unit: '次' },
  { key: 'success_rate', label: '成功率', aggregation: 'avg', format: (v) => `${(v * 100).toFixed(1)}%`, unit: '%' },
  { key: 'avg_duration', label: '平均耗时', aggregation: 'avg', format: (v) => `${v.toFixed(1)}s`, unit: 's' },
  { key: 'total_cost', label: '总成本', aggregation: 'sum', format: (v) => `¥${v.toLocaleString()}`, unit: '元' },
  { key: 'user_activity', label: '用户活跃度', aggregation: 'distinct_count', unit: '人' },
]

// ─── 主组件 ───
export const MultiDimensionalAnalyzer: React.FC<{
  initialConfig?: Partial<AnalysisConfig>
  onDataAnalyzed?: (data: PivotCell[], config: AnalysisConfig) => void
}> = ({ initialConfig }) => {
  const [config, setConfig] = useState<AnalysisConfig>({
    dimensions: PREDEFINED_DIMENSIONS,
    measures: PREDEFINED_MEASURES,
    rows: initialConfig?.rows || ['category'],
    columns: initialConfig?.columns || ['status'],
    values: initialConfig?.values || ['formula_count'],
    filters: initialConfig?.filters,
    limit: initialConfig?.limit || 100,
    ...initialConfig,
  })

  const [showConfigPanel, setShowConfigPanel] = useState(false)
  const [selectedCells, setSelectedCells] = useState<Set<string>>(new Set())
  const [drillDownPath, setDrillDownPath] = useState<string[]>([])

  // 获取分析数据 — 优先使用后端 /analytics/aggregate 接口，失败时降级到模拟
  const { data: rawData, isLoading, error, refetch } = useQuery({
    queryKey: ['multi-dimension-analysis', config],
    queryFn: async () => {
      // 尝试调用后端聚合接口
      try {
        const entity = config.rows[0] || 'formulas'
        const groupBy = config.columns[0] || 'status'
        const res = await api.post('/analytics/aggregate', {
          entity,
          operations: [{ operation: 'count', field: 'id', alias: 'total' }],
          group_by: groupBy,
          filters: {},
        })
        const items = (res.data.items ?? []) as Array<{ label: string; total: number }>
        return items.map(item => ({
          rowKey: [item.label],
          colKey: ['合计'],
          value: item.total,
          formattedValue: item.total.toLocaleString(),
          rowLabel: item.label,
          colLabel: '合计',
          isTotal: false,
          isSubtotal: false,
        }))
      } catch {
        // 降级：使用模拟数据
        return generatePivotData(config)
      }
    },
    staleTime: 30_000,
  })

  // 计算透视表数据
  const pivotData = useMemo(() => {
    if (!rawData) return []

    return rawData.map((cell: PivotCell) => ({
      ...cell,
      isSelected: selectedCells.has(`${cell.rowKey.join('|')}-${cell.colKey.join('|')}`),
    }))
  }, [rawData, selectedCells])

  // 添加行维度
  const addRowDimension = useCallback((dimensionKey: string) => {
    setConfig(prev => ({
      ...prev,
      rows: [...prev.rows, dimensionKey],
    }))
  }, [])

  // 移除行维度
  const removeRowDimension = useCallback((dimensionKey: string) => {
    setConfig(prev => ({
      ...prev,
      rows: prev.rows.filter(r => r !== dimensionKey),
    }))
  }, [])

  // 添加列维度
  const addColumnDimension = useCallback((dimensionKey: string) => {
    setConfig(prev => ({
      ...prev,
      columns: [...prev.columns, dimensionKey],
    }))
  }, [])

  // 移除列维度
  const removeColumnDimension = useCallback((dimensionKey: string) => {
    setConfig(prev => ({
      ...prev,
      columns: prev.columns.filter(c => c !== dimensionKey),
    }))
  }, [])

  // 切换单元格选中状态
  const toggleCellSelection = useCallback((cell: PivotCell) => {
    const cellId = `${cell.rowKey.join('|')}-${cell.colKey.join('|')}`
    setSelectedCells(prev => {
      const next = new Set(prev)
      if (next.has(cellId)) {
        next.delete(cellId)
      } else {
        next.add(cellId)
      }
      return next
    })
  }, [])

  // 数据钻取
  const drillDown = useCallback((rowKey: string[]) => {
    setDrillDownPath([...drillDownPath, rowKey.join(' > ')])
  }, [drillDownPath])

  // 返回上一级
  const drillUp = useCallback(() => {
    setDrillDownPath(drillDownPath.slice(0, -1))
  }, [drillDownPath])

  // 重置配置
  const resetConfig = useCallback(() => {
    setConfig({
      dimensions: PREDEFINED_DIMENSIONS,
      measures: PREDEFINED_MEASURES,
      rows: ['category'],
      columns: ['status'],
      values: ['formula_count'],
      limit: 100,
    })
    setSelectedCells(new Set())
    setDrillDownPath([])
  }, [])

  // 导出分析结果
  const exportAnalysis = useCallback(async () => {
    if (!pivotData.length) return

    try {
      const csvContent = [
        // 表头
        [...config.rows, ...config.columns, ...config.values].join(','),
        // 数据行
        ...pivotData.map(row =>
          [...row.rowKey, ...row.colKey, row.formattedValue].join(','),
        ),
      ].join('\n')

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' })
      const link = document.createElement('a')
      link.href = URL.createObjectURL(blob)
      link.download = `multi-dimensional-analysis-${new Date().toISOString().slice(0,10)}.csv`
      link.click()
    } catch (error) {
      logger.error('[MultiDimensionalAnalyzer] Export failed:', error)
    }
  }, [pivotData, config])

  return (
    <div className="w-full space-y-4">
      {/* 工具栏 */}
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div className="flex items-center gap-3">
          {/* 配置面板切换按钮 */}
          <button
            onClick={() => setShowConfigPanel(!showConfigPanel)}
            className={`px-3 py-1.5 text-sm rounded-lg border transition-all flex items-center gap-2 ${
              showConfigPanel
                ? 'bg-primary-50 dark:bg-primary-940/40 border-primary-300 text-primary-700 dark:text-primary-700'
                : 'bg-white dark:bg-neutral-900 border-neutral-200 dark:border-neutral-700 text-text-primary hover:bg-neutral-50 dark:hover:bg-neutral-800'
            }`}
          >
            <Layers className="w-4 h-4" />
            维度配置
          </button>

          {/* 钻取路径显示 */}
          {drillDownPath.length > 0 && (
            <div className="flex items-center gap-2 text-sm">
              <span className="text-text-muted">钻取路径:</span>
              <div className="flex items-center gap-1 bg-neutral-100 dark:bg-neutral-800 px-3 py-1 rounded-lg">
                {drillDownPath.map((path, index) => (
                  <React.Fragment key={index}>
                    {index > 0 && <ChevronRight className="w-3 h-3 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />}
                    <button
                      onClick={() => setDrillDownPath(drillDownPath.slice(0, index + 1))}
                      className="text-primary-700 hover:text-primary-700 font-medium"
                    >
                      {path}
                    </button>
                  </React.Fragment>
                ))}
                <button
                  onClick={drillUp}
                  className="ml-2 text-xs px-2 py-0.5 bg-white dark:bg-neutral-700 border border-neutral-200 dark:border-neutral-600 rounded hover:bg-neutral-50"
                >
                  返回
                </button>
              </div>
            </div>
          )}
        </div>

        <div className="flex items-center gap-2">
          {/* 刷新按钮 */}
          <button
            onClick={() => refetch()}
            disabled={isLoading}
            className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-lg transition-colors"
          >
            <RefreshCw className={`w-4 h-4 ${isLoading ? 'animate-spin' : ''}`} />
          </button>

          {/* 导出按钮 */}
          <button
            onClick={exportAnalysis}
            disabled={!pivotData.length}
            className="px-3 py-1.5 text-sm bg-primary-container hover:bg-primary-container text-primary-main rounded-lg transition-colors flex items-center gap-2 disabled:opacity-50"
          >
            <Download className="w-4 h-4" />
            导出CSV
          </button>

          {/* 重置按钮 */}
          <button
            onClick={resetConfig}
            className="px-3 py-1.5 text-sm text-neutral-600 dark:text-neutral-400 hover:text-neutral-900 dark:hover:text-neutral-200 transition-colors flex items-center gap-2"
          >
            <RotateCcw className="w-4 h-4" />
            重置
          </button>
        </div>
      </div>

      {/* 维度配置面板 */}
      {showConfigPanel && (
        <div className="bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-700 rounded-xl p-6 animate-micro-in">
          <h3 className="font-bold text-base mb-4">多维度分析配置</h3>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {/* 行维度选择 */}
            <div>
              <label className="block text-sm font-semibold mb-2 flex items-center gap-2">
                <ChevronRight className="w-4 h-4 rotate-0" /> 行维度
              </label>
              <div className="space-y-2 min-h-[120px] p-3 bg-neutral-50 dark:bg-neutral-800/50 rounded-lg border border-neutral-200 dark:border-neutral-700">
                {config.rows.map(dim => (
                  <div key={dim} className="flex items-center justify-between py-1.5 px-2 bg-white dark:bg-neutral-700 rounded text-sm group">
                    <span>{config.dimensions.find(d => d.key === dim)?.label || dim}</span>
                    <button
                      onClick={() => removeRowDimension(dim)}
                      className="opacity-0 group-hover:opacity-100 text-error-500 hover:text-error-600 transition-opacity"
                    >
                      <Minus className="w-3.5 h-3.5" />
                    </button>
                  </div>
                ))}

                {/* 添加维度下拉 */}
                <select
                  onChange={(e) => e.target.value && addRowDimension(e.target.value)}
                  value=""
                  className="mt-2 w-full px-2 py-1.5 text-sm input"
                >
                  <option value="">添加维度...</option>
                  {config.dimensions
                    .filter(d => !config.rows.includes(d.key) && !config.columns.includes(d.key))
                    .map(d => (
                      <option key={d.key} value={d.key}>{d.label}</option>
                    ))
                  }
                </select>
              </div>
            </div>

            {/* 列维度选择 */}
            <div>
              <label className="block text-sm font-semibold mb-2 flex items-center gap-2">
                <ChevronDown className="w-4 h-4" /> 列维度
              </label>
              <div className="space-y-2 min-h-[120px] p-3 bg-neutral-50 dark:bg-neutral-800/50 rounded-lg border border-neutral-200 dark:border-neutral-700">
                {config.columns.map(dim => (
                  <div key={dim} className="flex items-center justify-between py-1.5 px-2 bg-white dark:bg-neutral-700 rounded text-sm group">
                    <span>{config.dimensions.find(d => d.key === dim)?.label || dim}</span>
                    <button
                      onClick={() => removeColumnDimension(dim)}
                      className="opacity-0 group-hover:opacity-100 text-error-500 hover:text-error-600 transition-opacity"
                    >
                      <Minus className="w-3.5 h-3.5" />
                    </button>
                  </div>
                ))}

                <select
                  onChange={(e) => e.target.value && addColumnDimension(e.target.value)}
                  value=""
                  className="mt-2 w-full px-2 py-1.5 text-sm input"
                >
                  <option value="">添加维度...</option>
                  {config.dimensions
                    .filter(d => !config.rows.includes(d.key) && !config.columns.includes(d.key))
                    .map(d => (
                      <option key={d.key} value={d.key}>{d.label}</option>
                    ))
                  }
                </select>
              </div>
            </div>

            {/* 度量值选择 */}
            <div>
              <label className="block text-sm font-semibold mb-2 flex items-center gap-2">
                <BarChart3 className="w-4 h-4" /> 度量值
              </label>
              <div className="space-y-2 min-h-[120px] p-3 bg-neutral-50 dark:bg-neutral-800/50 rounded-lg border border-neutral-200 dark:border-neutral-700">
                {config.values.map(measure => (
                  <div key={measure} className="flex items-center justify-between py-1.5 px-2 bg-white dark:bg-neutral-700 rounded text-sm group">
                    <span>{config.measures.find(m => m.key === measure)?.label || measure}</span>
                    <button
                      onClick={() => setConfig(p => ({ ...p, values: p.values.filter(v => v !== measure) }))}
                      className="opacity-0 group-hover:opacity-100 text-error-500 hover:text-error-600 transition-opacity"
                    >
                      <Minus className="w-3.5 h-3.5" />
                    </button>
                  </div>
                ))}

                <select
                  onChange={(e) => e.target.value && setConfig(p => ({ ...p, values: [...p.values, e.target.value] }))}
                  value=""
                  className="mt-2 w-full px-2 py-1.5 text-sm input"
                >
                  <option value="">添加度量...</option>
                  {config.measures
                    .filter(m => !config.values.includes(m.key))
                    .map(m => (
                      <option key={m.key} value={m.key}>{m.label} ({m.unit})</option>
                    ))
                  }
                </select>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 透视表格展示区 */}
      <div className="bg-white dark:bg-neutral-900 rounded-xl border border-neutral-200 dark:border-neutral-700 overflow-hidden">
        {isLoading ? (
          <div className="flex items-center justify-center h-96">
            <RefreshCw className="w-8 h-8 animate-spin text-primary-500" />
          </div>
        ) : error ? (
          <div className="flex items-center justify-center h-96 text-error-500">
            分析失败，请重试
          </div>
        ) : pivotData.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-96 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
            <Table2 className="w-16 h-16 mb-3 opacity-50" />
            <p>请配置维度和度量以开始分析</p>
          </div>
        ) : (
          <div className="overflow-auto max-h-[600px]">
            <table className="w-full text-sm">
              <thead className="bg-neutral-50 dark:bg-neutral-800 sticky top-0 z-10">
                <tr>
                  <th className="px-4 py-3 text-left font-semibold text-text-muted border-b border-r border-neutral-200 dark:border-neutral-700">
                    {config.rows.map(r => config.dimensions.find(d => d.key === r)?.label).join(' / ')}
                  </th>
                  {Array.from(new Set(pivotData.map(d => d.colLabel))).map(col => (
                    <th
                      key={col}
                      className="px-4 py-3 text-right font-semibold text-text-muted border-b border-r border-neutral-200 dark:border-neutral-700 whitespace-nowrap"
                    >
                      {col}
                    </th>
                  ))}
                  <th className="px-4 py-3 text-right font-semibold text-text-muted border-b border-neutral-200 dark:border-neutral-700">
                    合计
                  </th>
                </tr>
              </thead>
              <tbody>
                {pivotData.reduce((acc: string[], cell) => {
                  if (!acc.includes(cell.rowLabel)) acc.push(cell.rowLabel)
                  return acc
                }, []).map(rowLabel => (
                  <tr
                    key={rowLabel}
                    className="hover:bg-neutral-50 dark:hover:bg-neutral-800/50 transition-colors"
                  >
                    <td className="px-4 py-3 font-medium text-text-primary border-r border-neutral-200 dark:border-neutral-700">
                      <button
                        onClick={() => drillDown([rowLabel])}
                        className="hover:text-primary-700 transition-colors flex items-center gap-1"
                      >
                        <ChevronRight className="w-3.5 h-3.5" />
                        {rowLabel}
                      </button>
                    </td>

                    {Array.from(new Set(pivotData.map(d => d.colLabel))).map(colLabel => {
                      const cell = pivotData.find(
                        d => d.rowLabel === rowLabel && d.colLabel === colLabel,
                      )
                      return (
                        <td
                          key={`${rowLabel}-${colLabel}`}
                          className={`px-4 py-3 text-right border-r border-neutral-200 dark:border-neutral-700 cursor-pointer transition-all ${
                            cell?.isSelected ? 'bg-primary-50 dark:bg-primary-940/30 font-bold' : ''
                          }`}
                          onClick={() => cell && toggleCellSelection(cell)}
                        >
                          {cell?.formattedValue ?? '-'}
                        </td>
                      )
                    })}

                    {/* 行合计 */}
                    <td className="px-4 py-3 text-right font-bold text-text-primary border-t border-neutral-200 dark:border-neutral-700">
                      {pivotData
                        .filter(d => d.rowLabel === rowLabel)
                        .reduce((sum, d) => sum + (d.value || 0), 0)
                        .toLocaleString()
                      }
                    </td>
                  </tr>
                ))}
              </tbody>
              <tfoot className="bg-neutral-50 dark:bg-neutral-800">
                <tr>
                  <td className="px-4 py-3 font-bold text-text-primary border-t border-r border-neutral-200 dark:border-neutral-700">
                    总计
                  </td>
                  {Array.from(new Set(pivotData.map(d => d.colLabel))).map(colLabel => (
                    <td
                      key={colLabel}
                      className="px-4 py-3 text-right font-bold text-text-primary border-t border-r border-neutral-200 dark:border-neutral-700"
                    >
                      {pivotData
                        .filter(d => d.colLabel === colLabel)
                        .reduce((sum, d) => sum + (d.value || 0), 0)
                        .toLocaleString()
                      }
                    </td>
                  ))}
                  <td className="px-4 py-3 text-right font-bold text-primary-700 border-t border-neutral-200 dark:border-neutral-700">
                    {pivotData.reduce((sum, d) => sum + (d.value || 0), 0).toLocaleString()}
                  </td>
                </tr>
              </tfoot>
            </table>
          </div>
        )}

        {/* 统计信息栏 */}
        {pivotData.length > 0 && (
          <div className="px-4 py-3 bg-neutral-50 dark:bg-neutral-800/50 border-t border-neutral-200 dark:border-neutral-700 flex items-center justify-between text-xs text-text-muted">
            <span>
              共 {pivotData.length} 个数据点 · {new Set(pivotData.map(d => d.rowLabel)).size} 行 × {new Set(pivotData.map(d => d.colLabel)).size} 列
            </span>
            <span>
              已选中 {selectedCells.size} 个单元格
            </span>
          </div>
        )}
      </div>
    </div>
  )
}

// ─── 辅助函数：生成模拟透视数据 ───
function generatePivotData(config: AnalysisConfig): Promise<PivotCell[]> {
  return new Promise(resolve => {
    setTimeout(() => {
      const data: PivotCell[] = []

      const rowValues = getDimensionValues(config.dimensions, [config.rows[0]])
      const colValues = getDimensionValues(config.dimensions, [config.columns[0]])

      let rowIdx = 0
      for (const rowVal of rowValues) {
        let colIdx = 0
        for (const colVal of colValues) {
          const baseValue = Math.floor(Math.random() * 1000) + 100

          data.push({
            rowKey: [rowVal],
            colKey: [colVal],
            value: baseValue,
            formattedValue: baseValue.toLocaleString(),
            rowLabel: rowVal,
            colLabel: colVal,
            ...(rowIdx === rowValues.length - 1 && { isSubtotal: true }),
            ...(colIdx === colValues.length - 1 && { isTotal: true }),
          })
          colIdx++
        }
        rowIdx++
      }

      resolve(data)
    }, 500) // 模拟网络延迟
  })
}

function getDimensionValues(dimensions: Dimension[], keys: string[]): string[] {
  if (!keys.length) return ['全部']

  const dim = dimensions.find(d => d.key === keys[0])
  return dim?.values || Array.from({ length: 5 }, (_, i) => `类别${i + 1}`)
}

export default MultiDimensionalAnalyzer

/**
 * PerformanceOptimizer - 性能优化工具集
 * 提供虚拟滚动、数据分页、内存管理、懒加载等性能优化功能
 */
import React, { useState, useMemo, useCallback, useRef, useEffect } from 'react'
import { useVirtualizer } from '@tanstack/react-virtual'
import { ChevronLeft, ChevronRight, Loader2, Database, Zap, MemoryStick } from 'lucide-react'

// ─── 类型定义 ───
export interface PaginationConfig {
  currentPage: number
  pageSize: number
  totalItems: number
  totalPages: number
  onPageChange: (page: number) => void
  onPageSizeChange?: (size: number) => void
}

interface VirtualScrollProps<T> {
  items: T[]
  itemHeight: number | ((index: number) => number)
  overscan?: number
  renderItem: (item: T, index: number) => React.ReactNode
  className?: string
  estimateSize?: () => number
}

// ─── 虚拟滚动组件 ───
export function VirtualizedList<T>({
  items,
  itemHeight,
  overscan = 5,
  renderItem,
  className = '',
}: VirtualScrollProps<T>) {
  const parentRef = useRef<HTMLDivElement>(null)

  const virtualizer = useVirtualizer({
    count: items.length,
    getScrollElement: () => parentRef.current,
    estimateSize: (index) => typeof itemHeight === 'function' ? itemHeight(index) : itemHeight,
    overscan,
  })

  return (
    <div
      ref={parentRef}
      className={`overflow-auto ${className}`}
      style={{ height: '600px' }}
    >
      <div
        style={{
          height: `${virtualizer.getTotalSize()}px`,
          width: '100%',
          position: 'relative',
        }}
      >
        {virtualizer.getVirtualItems().map((virtualItem) => {
          const isLoaderRow = virtualItem.index >= items.length

          return (
            <div
              key={virtualItem.key}
              data-index={virtualItem.index}
              ref={virtualizer.measureElement}
              style={{
                position: 'absolute',
                top: 0,
                left: 0,
                width: '100%',
                transform: `translateY(${virtualItem.start}px)`,
              }}
            >
              {isLoaderRow ? (
                <div className="flex items-center justify-center py-8">
                  <Loader2 className="w-6 h-6 animate-spin text-primary-500" />
                  <span className="ml-2 text-sm text-text-muted">加载更多数据...</span>
                </div>
              ) : (
                renderItem(items[virtualItem.index], virtualItem.index)
              )}
            </div>
          )
        })}
      </div>
    </div>
  )
}

// ─── 分页组件 ───
export function Pagination({
  currentPage,
  pageSize,
  totalItems,
  totalPages,
  onPageChange,
  onPageSizeChange,
}: PaginationConfig) {
  const [inputPage, setInputPage] = useState(currentPage)

  // 计算显示的页码范围
  const pageNumbers = useMemo(() => {
    const delta = 2 // 当前页前后显示的页数
    const range = []
    const rangeWithDots: (number | string)[] = []

    for (
      let i = Math.max(2, currentPage - delta);
      i <= Math.min(totalPages - 1, currentPage + delta);
      i++
    ) {
      range.push(i)
    }

    if (currentPage - delta > 2) {
      rangeWithDots.push(1, '...')
    } else {
      rangeWithDots.push(1)
    }

    rangeWithDots.push(...range)

    if (currentPage + delta < totalPages - 1) {
      rangeWithDots.push('...', totalPages)
    } else if (totalPages > 1) {
      rangeWithDots.push(totalPages)
    }

    return rangeWithDots
  }, [currentPage, totalPages])

  // 处理输入跳转
  const handleJumpToPage = useCallback(() => {
    const page = parseInt(inputPage.toString())
    if (page >= 1 && page <= totalPages) {
      onPageChange(page)
    }
    setInputPage(currentPage)
  }, [inputPage, currentPage, totalPages, onPageChange])

  return (
    <div className="flex items-center justify-between px-4 py-3 bg-white dark:bg-neutral-900 border-t border-neutral-200 dark:border-neutral-700">
      {/* 左侧：信息 */}
      <div className="flex items-center gap-4 text-sm text-text-muted">
        <span>共 {totalItems.toLocaleString()} 条记录</span>

        {/* 每页条数选择器 */}
        {onPageSizeChange && (
          <select
            value={pageSize}
            onChange={(e) => onPageSizeChange(Number(e.target.value))}
            className="px-2 py-1 input text-xs"
          >
            {[10, 20, 50, 100, 200].map(size => (
              <option key={size} value={size}>{size} 条/页</option>
            ))}
          </select>
        )}
      </div>

      {/* 中间：页码导航 */}
      <div className="flex items-center gap-1">
        {/* 上一页按钮 */}
        <button
          onClick={() => onPageChange(currentPage - 1)}
          disabled={currentPage <= 1}
          className="p-1.5 rounded hover:bg-neutral-100 dark:hover:bg-neutral-800 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
        >
          <ChevronLeft className="w-4 h-4" />
        </button>

        {/* 页码按钮 */}
        {pageNumbers.map((pageNum, index) =>
          pageNum === '...' ? (
            <span key={`dots-${index}`} className="px-2 py-1 text-text-muted">...</span>
          ) : (
            <button
              key={pageNum}
              onClick={() => onPageChange(pageNum as number)}
              className={`px-3 py-1.5 rounded text-sm transition-colors ${
                currentPage === pageNum
                  ? 'bg-primary-container text-primary-main font-medium'
                  : 'hover:bg-neutral-100 dark:hover:bg-neutral-800 text-text-primary'
              }`}
            >
              {pageNum}
            </button>
          ),
        )}

        {/* 下一页按钮 */}
        <button
          onClick={() => onPageChange(currentPage + 1)}
          disabled={currentPage >= totalPages}
          className="p-1.5 rounded hover:bg-neutral-100 dark:hover:bg-neutral-800 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
        >
          <ChevronRight className="w-4 h-4" />
        </button>
      </div>

      {/* 右侧：跳转输入框 */}
      <div className="flex items-center gap-2 text-sm">
        <span className="text-text-muted">跳转到</span>
        <input
          type="number"
          min={1}
          max={totalPages}
          value={inputPage}
          onChange={(e) => setInputPage(Number(e.target.value))}
          onKeyDown={(e) => e.key === 'Enter' && handleJumpToPage()}
          className="w-16 px-2 py-1 input text-center"
        aria-label="跳转页码"
      />
        <button
          onClick={handleJumpToPage}
          className="px-3 py-1 bg-neutral-100 dark:bg-neutral-800 rounded text-text-primary hover:bg-neutral-200 dark:hover:bg-neutral-700 transition-colors"
        >
          Go
        </button>
      </div>
    </div>
  )
}

// ─── 数据缓存管理器 ───
class DataCacheManager {
  private cache = new Map<string, { data: any; timestamp: number; ttl: number; size: number }>()
  private maxSize: number
  private currentSize: number

  constructor(maxSizeMB = 50) {
    this.maxSize = maxSizeMB * 1024 * 1024 // 转换为字节
    this.currentSize = 0
  }

  set(key: string, data: any, ttl = 30_000): void {
    // 计算数据大小（简化版）
    const size = new TextEncoder().encode(JSON.stringify(data)).length

    // 如果超出容量，清理旧缓存
    if (this.currentSize + size > this.maxSize) {
      this.evictLRU()
    }

    this.cache.set(key, { data, timestamp: Date.now(), ttl, size })
    this.currentSize += size
  }

  get(key: string): any | null {
    const item = this.cache.get(key)

    if (!item) return null

    // 检查是否过期
    if (Date.now() - item.timestamp > item.ttl) {
      this.delete(key)
      return null
    }

    // 更新访问时间（LRU）
    this.cache.set(key, { ...item, timestamp: Date.now() })

    return item.data
  }

  delete(key: string): boolean {
    const item = this.cache.get(key)
    if (item) {
      this.currentSize -= item.size
      return this.cache.delete(key)
    }
    return false
  }

  clear(): void {
    this.cache.clear()
    this.currentSize = 0
  }

  has(key: string): boolean {
    return this.cache.has(key)
  }

  keys(): string[] {
    return Array.from(this.cache.keys())
  }

  stats(): {
    size: number
    count: number
    memoryUsageMB: number
    hitRate: number
  } {
    return {
      size: this.currentSize,
      count: this.cache.size,
      memoryUsageMB: Math.round(this.currentSize / (1024 * 1024) * 100) / 100,
      hitRate: 0, // 实际应用中需要统计命中率
    }
  }

  private evictLRU(): void {
    // 找到最久未使用的项并删除
    let oldestKey: string | null = null
    let oldestTime = Infinity

    for (const [key, value] of this.cache.entries()) {
      if (value.timestamp < oldestTime) {
        oldestTime = value.timestamp
        oldestKey = key
      }
    }

    if (oldestKey) {
      this.delete(oldestKey)
    }
  }
}

export const globalCacheManager = new DataCacheManager()

// ─── 内存监控组件 ───
export function MemoryMonitor() {
  const [memoryStats, setMemoryStats] = useState<{
    usedJSHeapSize: number
    totalJSHeapSize: number
    jsHeapSizeLimit: number
  } | null>(null)

  useEffect(() => {
    const interval = setInterval(() => {
      if ('memory' in performance) {
        const perfWithMemory = performance as { memory?: PerformanceMemory } | undefined;
        setMemoryStats({
          usedJSHeapSize: perfWithMemory?.memory?.usedJSHeapSize ?? 0,
          totalJSHeapSize: perfWithMemory?.memory?.totalJSHeapSize ?? 0,
          jsHeapSizeLimit: perfWithMemory?.memory?.jsHeapSizeLimit ?? 0,
        })
      }
    }, 5000)

    return () => clearInterval(interval)
  }, [])

  if (!memoryStats) return null

  const usagePercent = (memoryStats.usedJSHeapSize / memoryStats.jsHeapSizeLimit) * 100
  const isWarning = usagePercent > 80
  const isCritical = usagePercent > 95

  return (
    <div className={`fixed bottom-4 right-4 p-3 rounded-lg shadow-lg border z-50 transition-all ${
      isCritical ? 'bg-error-50 dark:bg-error-300/20 border-error-200 dark:border-error-800' :
      isWarning ? 'bg-warning-50 dark:bg-warning-300/20 border-warning-200 dark:border-warning-800' :
      'bg-white dark:bg-neutral-900 border-neutral-200 dark:border-neutral-700'
    }`}>
      <div className="flex items-center gap-2 mb-2">
        <MemoryStick className={`w-4 h-4 ${isCritical ? 'text-error-500' : isWarning ? 'text-warning-500' : 'text-success-500'}`} />
        <span className="text-xs font-semibold">内存使用</span>
      </div>

      <div className="space-y-1 text-xs">
        <div className="flex justify-between">
          <span className="text-text-muted">已用:</span>
          <span>{(memoryStats.usedJSHeapSize / 1024 / 1024).toFixed(1)} MB</span>
        </div>

        <div className="w-full h-2 bg-neutral-200 dark:bg-neutral-700 rounded-full overflow-hidden">
          <div
            className={`h-full transition-all ${
              isCritical ? 'bg-error-500' : isWarning ? 'bg-warning-500' : 'bg-success-500'
            }`}
            style={{ width: `${Math.min(usagePercent, 100)}%` }}
          />
        </div>

        <div className="text-right text-text-muted">
          {(usagePercent).toFixed(1)}%
        </div>
      </div>

      {isCritical && (
        <p className="text-xs text-error-600 mt-2 font-medium">
          ⚠️ 内存使用过高，建议刷新页面或关闭部分标签页
        </p>
      )}
    </div>
  )
}

// ─── 数据预取 Hook ───
export function useDataPrefetch<T>(
  queryKey: string[],
  fetcher: () => Promise<T>,
  options?: {
    prefetchOnHover?: boolean
    prefetchDelay?: number
    staleTime?: number
  },
): {
  data: T | undefined
  isLoading: boolean
  error: Error | null
  prefetch: () => void
} {
  const [data, setData] = useState<T | undefined>()
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<Error | null>(null)
  const timerRef = useRef<NodeJS.Timeout | undefined>(undefined)

  const fetchData = useCallback(async () => {
    try {
      setIsLoading(true)
      setError(null)
      const result = await fetcher()
      setData(result)
    } catch (err) {
      setError(err as Error)
    } finally {
      setIsLoading(false)
    }
  }, [fetcher])

  const prefetch = useCallback(() => {
    if (timerRef.current) clearTimeout(timerRef.current)

    timerRef.current = setTimeout(() => {
      fetchData()
    }, options?.prefetchDelay || 200)
  }, [fetchData, options?.prefetchDelay])

  return { data, isLoading, error, prefetch }
}

// ─── 导出工具函数 ───

/**
 * 防抖函数
 */
export function debounce<T extends (...args: any[]) => any>(
  func: T,
  wait: number,
): (...args: Parameters<T>) => void {
  let timeoutId: NodeJS.Timeout

  return (...args: Parameters<T>) => {
    clearTimeout(timeoutId)
    timeoutId = setTimeout(() => func(...args), wait)
  }
}

/**
 * 节流函数
 */
export function throttle<T extends (...args: any[]) => any>(
  func: T,
  limit: number,
): (...args: Parameters<T>) => void {
  let inThrottle: boolean

  return (...args: Parameters<T>) => {
    if (!inThrottle) {
      func(...args)
      inThrottle = true
      setTimeout(() => inThrottle = false, limit)
    }
  }
}

/**
 * 格式化数字（添加千位分隔符）
 */
export function formatNumber(num: number, locale = 'zh-CN'): string {
  return num.toLocaleString(locale)
}

/**
 * 格式化文件大小
 */
export function formatFileSize(bytes: number): string {
  if (bytes === 0) return '0 B'

  const k = 1024
  const sizes = ['B', 'KB', 'MB', 'GB', 'TB']
  const i = Math.floor(Math.log(bytes) / Math.log(k))

  return `${parseFloat((bytes / Math.pow(k, i)).toFixed(2))} ${sizes[i]}`
}

/**
 * 深度克隆对象
 */
export function deepClone<T>(obj: T): T {
  return JSON.parse(JSON.stringify(obj))
}

