/**
 * RealTimeDataUpdater - 实时数据更新组件
 * 集成WebSocket实现数据实时推送、自动刷新、状态监控
 */
import React, { useState, useEffect, useCallback, useRef } from 'react'
import { useQueryClient } from '@tanstack/react-query'
import { logger } from '@/utils/safeLogger'
import {
  Wifi, WifiOff, Activity, RefreshCw, AlertCircle,
  Clock, TrendingUp, Zap,
} from 'lucide-react'

// ─── 类型定义 ───
export interface RealtimeConfig {
  endpoint: string
  updateInterval?: number        // 轮询间隔（毫秒），默认30秒
  enableWebSocket?: boolean      // 是否启用WebSocket，默认true
  reconnectAttempts?: number     // 最大重连次数，默认5次
  heartbeatInterval?: number     // 心跳检测间隔，默认15秒
  dataBufferMaxSize?: number     // 数据缓冲区最大容量，默认1000条
  onMessage?: (data: any) => void
  onError?: (error: Error) => void
  onReconnect?: (attempt: number) => void
}

interface ConnectionStatus {
  connected: boolean
  mode: 'websocket' | 'polling' | 'offline'
  lastUpdate: Date | null
  latency: number              // 延迟（毫秒）
  messagesReceived: number
  errorsCount: number
}

interface DataPoint {
  id: string
  timestamp: Date
  type: string
  data: any
  processed: boolean
}

// ─── WebSocket Hook ───
function useWebSocket(config: RealtimeConfig) {
  const [status, setStatus] = useState<ConnectionStatus>({
    connected: false,
    mode: 'offline',
    lastUpdate: null,
    latency: 0,
    messagesReceived: 0,
    errorsCount: 0,
  })

  const wsRef = useRef<WebSocket | null>(null)
  const reconnectTimerRef = useRef<NodeJS.Timeout | undefined>(undefined)
	const heartbeatTimerRef = useRef<NodeJS.Timeout | undefined>(undefined)
  const [reconnectAttempt, setReconnectAttempt] = useState(0)
  const queryClient = useQueryClient()

  // 数据缓冲区
  const [dataBuffer, setDataBuffer] = useState<DataPoint[]>([])

  // 连接WebSocket
  const connect = useCallback(() => {
    if (!config.enableWebSocket) {
      setStatus(prev => ({ ...prev, mode: 'polling' }))
      return
    }

    try {
      const wsUrl = config.endpoint.startsWith('ws')
        ? config.endpoint
        : `ws://${window.location.host}${config.endpoint}`

      wsRef.current = new WebSocket(wsUrl)

      wsRef.current.onopen = () => {
        logger.info('[RealTimeDataUpdater] WebSocket connected')
        setStatus({
          connected: true,
          mode: 'websocket',
          lastUpdate: new Date(),
          latency: 0,
          messagesReceived: status.messagesReceived,
          errorsCount: status.errorsCount,
        })
        setReconnectAttempt(0)

        // 启动心跳检测
        // eslint-disable-next-line react-hooks/immutability
        startHeartbeat()

        config.onReconnect?.(reconnectAttempt)
      }

      wsRef.current.onmessage = (event) => {
        try {
          const message = JSON.parse(event.data)
          const startTime = performance.now()

          // 处理消息
          // eslint-disable-next-line react-hooks/immutability
          handleMessage(message)

          // 更新状态
          setStatus(prev => ({
            ...prev,
            lastUpdate: new Date(),
            latency: Math.round(performance.now() - startTime),
            messagesReceived: prev.messagesReceived + 1,
          }))

          // 触发回调
          config.onMessage?.(message)

          // 使相关查询失效以触发重新获取
          // eslint-disable-next-line react-hooks/immutability
          invalidateRelatedQueries(message.type)

        } catch (error) {
          logger.error('[RealTimeDataUpdater] Failed to parse message:', error)
          // eslint-disable-next-line react-hooks/immutability
          handleConnectionError(error as Error)
        }
      }

      wsRef.current.onerror = (error) => {
        logger.error('[RealTimeDataUpdater] WebSocket error:', error)
        handleConnectionError(new Error('WebSocket connection error'))
      }

      wsRef.current.onclose = () => {
        logger.info('[RealTimeDataUpdater] WebSocket disconnected')
        setStatus(prev => ({ ...prev, connected: false }))
        // eslint-disable-next-line react-hooks/immutability
        stopHeartbeat()
        // eslint-disable-next-line react-hooks/immutability
        scheduleReconnect()
      }

    } catch (error) {
      logger.error('[RealTimeDataUpdater] Connection failed:', error)
      handleConnectionError(error as Error)
    }
  }, [config.endpoint, config.enableWebSocket])

  // 处理接收到的消息
  const handleMessage = useCallback((data: any) => {
    const newDataPoint: DataPoint = {
      id: `${Date.now()}-${Math.random().toString(36).substring(2, 11)}`,
      timestamp: new Date(),
      type: data.type || 'unknown',
      data,
      processed: false,
    }

    // 添加到缓冲区
    setDataBuffer(prev => {
      const updated = [...prev, newDataPoint]
      // 保持缓冲区大小在限制内
      return updated.slice(-(config.dataBufferMaxSize ?? 1000))
    })

    // 标记为已处理
    setTimeout(() => {
      setDataBuffer(prev =>
        prev.map(p => p.id === newDataPoint.id ? { ...p, processed: true } : p),
      )
    }, 100)
  }, [config.dataBufferMaxSize])

  // 处理连接错误
  const handleConnectionError = useCallback((error: Error) => {
    setStatus(prev => ({
      ...prev,
      errorsCount: prev.errorsCount + 1,
    }))
    config.onError?.(error)
  }, [config.onError])

  // 计划重连
  const scheduleReconnect = useCallback(() => {
    const maxAttempts = config.reconnectAttempts || 5

    if (reconnectAttempt >= maxAttempts) {
      logger.warn(`[RealTimeDataUpdater] Max reconnect attempts (${maxAttempts}) reached`)
      setStatus(prev => ({ ...prev, mode: 'polling' })) // 降级为轮询模式
      return
    }

    const delay = Math.min(1000 * Math.pow(2, reconnectAttempt), 30000)

    reconnectTimerRef.current = setTimeout(() => {
      setReconnectAttempt(prev => prev + 1)
      connect()
    }, delay)
  }, [reconnectAttempt, config.reconnectAttempts, connect])

  // 启动心跳检测
  const startHeartbeat = useCallback(() => {
    const interval = config.heartbeatInterval || 15000

    heartbeatTimerRef.current = setInterval(() => {
      if (wsRef.current?.readyState === WebSocket.OPEN) {
        const pingStart = performance.now()

        wsRef.current.send(JSON.stringify({ type: 'ping', timestamp: Date.now() }))

        // 测量延迟（简化版）
        setTimeout(() => {
          setStatus(prev => ({
            ...prev,
            latency: Math.round(performance.now() - pingStart),
          }))
        }, 50)
      }
    }, interval)
  }, [config.heartbeatInterval])

  // 停止心跳
  // eslint-disable-next-line react-hooks/preserve-manual-memoization
  const stopHeartbeat = useCallback(() => {
    if (heartbeatTimerRef.current) {
      clearInterval(heartbeatTimerRef.current)
    }
  }, [])

  // 使相关查询失效
  const invalidateRelatedQueries = useCallback((dataType: string) => {
    // 根据消息类型使相关查询失效
    const queryKeysToInvalidate: string[][] = []

    switch (dataType) {
      case 'kpi_update':
        queryKeysToInvalidate.push(['analytics', 'kpis'])
        break
      case 'chart_update':
        queryKeysToInvalidate.push(['analytics', 'charts'])
        break
      case 'activity':
        queryKeysToInvalidate.push(['analytics', 'activity'])
        break
      default:
        queryKeysToInvalidate.push(['analytics'])
    }

    queryKeysToInvalidate.forEach(key => {
      queryClient.invalidateQueries({ queryKey: key })
    })
  }, [queryClient])

  // 断开连接
  const disconnect = useCallback(() => {
    stopHeartbeat()

    if (reconnectTimerRef.current) {
      clearTimeout(reconnectTimerRef.current)
    }

    if (wsRef.current) {
      wsRef.current.close()
      wsRef.current = null
    }

    setStatus({
      connected: false,
      mode: 'offline',
      lastUpdate: null,
      latency: 0,
      messagesReceived: 0,
      errorsCount: 0,
    })
  }, [stopHeartbeat])

  // 初始化和清理
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    connect()

    return () => {
      disconnect()
    }
  }, [connect, disconnect])

  // 如果WebSocket不可用，使用轮询模式
  useEffect(() => {
    if (!config.enableWebSocket || status.mode === 'polling') {
      const interval = setInterval(() => {
        // 通过使查询失效来触发数据刷新
        queryClient.invalidateQueries({ queryKey: ['analytics'] })
        setStatus(prev => ({
          ...prev,
          lastUpdate: new Date(),
          mode: 'polling',
        }))
      }, config.updateInterval || 30000)

      return () => clearInterval(interval)
    }
    return undefined
  }, [config.enableWebSocket, status.mode, config.updateInterval, queryClient])

  return {
    status,
    dataBuffer,
    connect,
    disconnect,
    reconnect: connect,
  }
}

// ─── 主组件 ───
export const RealTimeDataUpdater: React.FC<{
  config: RealtimeConfig
  children?: React.ReactNode
}> = ({ config, children }) => {
  const { status, dataBuffer, reconnect } = useWebSocket(config)

  // 格式化最后更新时间
  const formatLastUpdate = useCallback((date: Date | null) => {
    if (!date) return '从未'

    const now = new Date()
    const diff = now.getTime() - date.getTime()
    const seconds = Math.floor(diff / 1000)

    if (seconds < 60) return `${seconds}秒前`
    if (seconds < 3600) return `${Math.floor(seconds / 60)}分钟前`
    if (seconds < 86400) return `${Math.floor(seconds / 3600)}小时前`
    return date.toLocaleString()
  }, [])

  // 状态指示器颜色
  const getStatusColor = (mode: string, connected: boolean) => {
    if (connected && mode === 'websocket') return 'text-success-500 bg-success-50 dark:bg-success-300/20'
    if (mode === 'polling') return 'text-secondary-500 bg-secondary-50 dark:bg-secondary-300/20'
    return 'text-error-500 bg-error-50 dark:bg-error-300/20'
  }

  return (
    <div className="relative">
      {/* 实时状态指示器 */}
      <div className="absolute top-4 right-4 z-10">
        <div className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-medium border ${
          getStatusColor(status.mode, status.connected)
        }`}>
          {status.connected && status.mode === 'websocket' ? (
            <>
              <Wifi className="w-3.5 h-3.5" />
              <span>实时</span>
              <span className="opacity-70">{formatLastUpdate(status.lastUpdate)}</span>
            </>
          ) : status.mode === 'polling' ? (
            <>
              <RefreshCw className="w-3.5 h-3.5 animate-spin" />
              <span>轮询</span>
              <span className="opacity-70">每{Math.round((config.updateInterval || 30000) / 1000)}s</span>
            </>
          ) : (
            <>
              <WifiOff className="w-3.5 h-3.5" />
              <span>离线</span>
              <button
                onClick={reconnect}
                className="ml-1 underline hover:no-underline"
              >
                重连
              </button>
            </>
          )}
        </div>
      </div>

      {/* 子内容 */}
      {children}

      {/* 数据流统计面板（可折叠） */}
      <div className="mt-4 p-4 bg-neutral-50 dark:bg-neutral-800/50 rounded-lg border border-neutral-200 dark:border-neutral-700">
        <h4 className="text-xs font-semibold text-text-muted uppercase tracking-wider mb-3 flex items-center gap-2">
          <Activity className="w-4 h-4" />
          数据流状态
        </h4>

        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
          <div className="flex items-center gap-2">
            <Clock className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
            <div>
              <div className="font-medium text-text-primary">最后更新</div>
              <div className="text-text-muted text-xs">{formatLastUpdate(status.lastUpdate)}</div>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <TrendingUp className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
            <div>
              <div className="font-medium text-text-primary">接收消息</div>
              <div className="text-text-muted text-xs">{status.messagesReceived.toLocaleString()} 条</div>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <Zap className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
            <div>
              <div className="font-medium text-text-primary">网络延迟</div>
              <div className="text-text-muted text-xs">{status.latency} ms</div>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <AlertCircle className={`w-4 h-4 ${status.errorsCount > 0 ? 'text-error-500' : 'text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]'}`} />
            <div>
              <div className="font-medium text-text-primary">错误次数</div>
              <div className={`text-xs ${status.errorsCount > 0 ? 'text-error-500' : 'text-text-muted'}`}>
                {status.errorsCount}
              </div>
            </div>
          </div>
        </div>

        {/* 数据缓冲区大小 */}
        <div className="mt-3 pt-3 border-t border-neutral-200 dark:border-neutral-700 flex items-center justify-between text-xs text-text-muted">
          <span>缓冲区容量: {dataBuffer.length}/{config.dataBufferMaxSize || 1000}</span>
          <span>连接模式: {status.mode.toUpperCase()}</span>
        </div>
      </div>
    </div>
  )
}

// ─── 模拟数据生成器（用于演示） ───
export function generateRealtimeMockData(): any[] {
  const types = ['kpi_update', 'chart_update', 'activity', 'alert', 'metric_change']

  return Array.from({ length: 10 }, (_, i) => ({
    type: types[Math.floor(Math.random() * types.length)],
    timestamp: new Date(Date.now() - i * 5000).toISOString(),
    data: {
      value: Math.floor(Math.random() * 1000),
      change: (Math.random() - 0.5) * 20,
      metadata: {
        source: `source-${i}`,
        category: ['formulas', 'experiments', 'users'][Math.floor(Math.random() * 3)],
      },
    },
  }))
}

// ─── 导出配置工具 ───
export function createDefaultRealtimeConfig(endpoint: string): RealtimeConfig {
  return {
    endpoint,
    updateInterval: 30000,
    enableWebSocket: true,
    reconnectAttempts: 5,
    heartbeatInterval: 15000,
    dataBufferMaxSize: 1000,
    onMessage: (data) => {
      logger.info('[RealTime] Received:', data.type)
    },
    onError: (error) => {
      logger.error('[RealTime] Error:', error.message)
    },
    onReconnect: (attempt) => {
      logger.info(`[RealTime] Reconnecting... Attempt ${attempt}`)
    },
  }
}

export default RealTimeDataUpdater

/**
 * AdvancedChartEngine - 企业级数据可视化引擎
 * 基于 Recharts 构建，提供统一的图表接口和丰富的交互功能
 */
import React, { useMemo, useState, useCallback } from 'react';
import {
  LineChart,
  Line,
  BarChart,
  Bar,
  PieChart,
  Pie,
  Cell,
  AreaChart,
  Area,
  RadarChart,
  Radar,
  PolarGrid,
  PolarAngleAxis,
  PolarRadiusAxis,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ScatterChart,
  Scatter,
} from 'recharts';
// D-40：原 import { useTheme } from '@/hooks/useTheme'（遗留兼容层）。
// 该文件仅需 isDark，改用 @/theme 的现代 hook，消除同名 useTheme 歧义。
import { useIsDarkMode } from '@/theme';

// ─── 类型定义 ───
export type ChartType =
  | 'line'
  | 'multi-line'
  | 'bar'
  | 'stacked-bar'
  | 'horizontal-bar'
  | 'pie'
  | 'donut'
  | 'area'
  | 'stacked-area'
  | 'radar'
  | 'scatter';

export type ChartDataPoint = Record<string, string | number>;

export interface ChartSeries {
  dataKey: string;
  name: string;
  color?: string;
  type?: 'monotone' | 'linear' | 'step' | 'basis' | 'natural';
  strokeWidth?: number;
  dot?: boolean | { r?: number; fill?: string; stroke?: string };
  stackId?: string;
}

export interface ChartConfig {
  id: string;
  type: ChartType;
  title?: string;
  subtitle?: string;
  data: ChartDataPoint[];
  series: ChartSeries[];
  xAxis?: {
    dataKey?: string;
    label?: string;
    tickFormatter?: (value: any) => string;
    angle?: number;
  };
  yAxis?: {
    label?: string;
    tickFormatter?: (value: any) => string;
    unit?: string;
  };
  legend?: {
    show?: boolean;
    position?: 'top' | 'bottom' | 'left' | 'right';
  };
  tooltip?: {
    enabled?: boolean;
    formatter?: (value: any, name: string) => [string, string];
  };
  grid?: boolean;
  animation?: boolean;
  height?: number;
  responsive?: boolean;
  onChartClick?: (data: any) => void;
  onDataPointClick?: (data: any, index: number) => void;
  customTooltip?: React.ReactNode;
  loading?: boolean;
  emptyState?: string;
  error?: string;
}

// ─── 常量定义 ───
const CHART_COLORS = [
  'var(--color-primary, var(--color-primary-400))', // primary green
  'var(--color-secondary, #0A84FF)', // blue
  'var(--color-tertiary, var(--color-accent-500))', // violet
  'var(--color-warning, #FF9F0A)', // amber
  'var(--color-error, #FF3B30)', // red
  'var(--color-info, var(--color-secondary-500))', // cyan
  'var(--color-danger-500, #D946EF)', // pink
  'var(--color-success, var(--color-primary-400))', // lime
];

const DARK_CHART_COLORS = [
  'var(--color-success-400, #4ADE80)', // lighter green
  'var(--color-blue-400, #6ECAFF)', // lighter blue
  'var(--color-accent-400, #C090FF)', // lighter violet
  'var(--color-warning-400, #F59E0B)', // lighter amber
  'var(--color-danger-400, #EF4444)', // lighter red
  'var(--color-info-400, #67E8F9)', // lighter cyan
  'var(--color-danger-400, #EC4899)', // lighter pink
  'var(--color-success-400, #A3E635)', // lighter lime
];

interface CustomTooltipProps {
  active?: boolean;
  payload?: { name: string; value: number; color: string }[];
  label?: string;
  dark?: boolean;
}

function CustomTooltip({ active, payload, label, dark }: CustomTooltipProps) {
  if (!active || !payload) return null;

  return (
    <div
      className={`px-4 py-3 rounded-lg shadow-lg border ${
        dark ? 'bg-neutral-800 border-neutral-700' : 'bg-white dark:bg-neutral-900 border-neutral-200'
      }`}
    >
      {label && <p className={`text-sm font-semibold mb-2 ${dark ? 'text-neutral-200' : 'text-neutral-900'}`}>{label}</p>}
      {payload.map((entry, index) => (
        <div key={index} className="flex items-center gap-2 text-sm">
          <span className="w-2 h-2 rounded-full" style={{ backgroundColor: entry.color }} />
          <span className={dark ? 'text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]' : 'text-neutral-700'}>{entry.name}:</span>
          <span className={`font-semibold ${dark ? 'text-white' : 'text-neutral-900'}`}>
            {typeof entry.value === 'number' ? entry.value.toLocaleString() : entry.value}
          </span>
        </div>
      ))}
    </div>
  );
}

// ─── 主组件 ───
export const AdvancedChartEngine: React.FC<ChartConfig> = ({
  type,
  title,
  subtitle,
  data,
  series,
  xAxis,
  yAxis,
  legend = { show: true, position: 'top' },
  tooltip = { enabled: true },
  grid = true,
  animation = true,
  height = 400,
  responsive = true,
  onChartClick,
  onDataPointClick,
  loading = false,
  emptyState,
  error,
}) => {
  const isDark = useIsDarkMode();
  const [activeIndex, setActiveIndex] = useState(-1);

  const colors = useMemo(() => (isDark ? DARK_CHART_COLORS : CHART_COLORS), [isDark]);

  const seriesWithColors = useMemo(
    () =>
      series.map((s, i) => ({
        ...s,
        color: s.color || colors[i % colors.length],
      })),
    [series, colors],
  );

  const handleDataPointClick = useCallback(
    (data: any, index: number) => {
      setActiveIndex(index);
      onDataPointClick?.(data, index);
    },
    [onDataPointClick],
  );

  // Loading 状态
  if (loading) {
    return (
      <div className="flex items-center justify-center h-full min-h-[200px] bg-neutral-50 dark:bg-neutral-800 rounded-lg">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600 mx-auto mb-4"></div>
          <p className="text-text-muted">加载中...</p>
        </div>
      </div>
    );
  }

  // Error 状态
  if (error) {
    return (
      <div className="flex items-center justify-center h-full min-h-[200px] bg-error-50 dark:bg-error-300/20 rounded-lg">
        <p className="text-error-600 dark:text-error-600">{error}</p>
      </div>
    );
  }

  // Empty 状态
  if (!data || data.length === 0) {
    return (
      <div className="flex items-center justify-center h-full min-h-[200px] bg-neutral-50 dark:bg-neutral-800 rounded-lg">
        <p className="text-text-muted">{emptyState || '暂无数据'}</p>
      </div>
    );
  }

  // 渲染图表内容
  const renderChartContent = () => {
    switch (type) {
      case 'line':
      case 'multi-line':
        return (
          <ResponsiveContainer width={responsive ? '100%' : undefined} height={height}>
            <LineChart data={data} onClick={onChartClick}>
              {grid && <CartesianGrid strokeDasharray="3 3" stroke={isDark ? 'var(--text-secondary, #6E6E73)' : 'var(--border-subtle, rgba(0,0,0,0.06))'} />}
              <XAxis
                dataKey={xAxis?.dataKey}
                tick={{ fontSize: 12, fill: isDark ? 'var(--text-muted, #9A9A9F)' : 'var(--text-secondary, #6E6E73)' }}
                angle={xAxis?.angle}
              />
              <YAxis
                tick={{ fontSize: 12, fill: isDark ? 'var(--text-muted, #9A9A9F)' : 'var(--text-secondary, #6E6E73)' }}
                tickFormatter={yAxis?.tickFormatter}
                unit={yAxis?.unit}
              />
              {tooltip.enabled && <Tooltip content={<CustomTooltip dark={isDark} />} />}
              {legend.show && <Legend {...legend} />}
              {seriesWithColors.map((s) => (
                <Line
                  key={s.dataKey}
                  type={s.type || 'monotone'}
                  dataKey={s.dataKey}
                  name={s.name}
                  stroke={s.color}
                  strokeWidth={s.strokeWidth || 2}
                  dot={s.dot === true ? { r: 4, fill: s.color, stroke: s.color } : s.dot}
                  activeDot={{ r: 6 }}
                  animationDuration={animation ? 500 : 0}
                />
              ))}
            </LineChart>
          </ResponsiveContainer>
        );

      case 'bar':
      case 'stacked-bar':
        return (
          <ResponsiveContainer width={responsive ? '100%' : undefined} height={height}>
            <BarChart data={data} onClick={onChartClick}>
              {grid && <CartesianGrid strokeDasharray="3 3" stroke={isDark ? 'var(--text-secondary, #6E6E73)' : 'var(--border-subtle, rgba(0,0,0,0.06))'} />}
              <XAxis dataKey={xAxis?.dataKey} tick={{ fontSize: 12, fill: isDark ? 'var(--text-muted, #9A9A9F)' : 'var(--text-secondary, #6E6E73)' }} />
              <YAxis
                tick={{ fontSize: 12, fill: isDark ? 'var(--text-muted, #9A9A9F)' : 'var(--text-secondary, #6E6E73)' }}
                tickFormatter={yAxis?.tickFormatter}
                unit={yAxis?.unit}
              />
              {tooltip.enabled && <Tooltip content={<CustomTooltip dark={isDark} />} />}
              {legend.show && <Legend {...legend} />}
              {seriesWithColors.map((s) => (
                <Bar
                  key={s.dataKey}
                  dataKey={s.dataKey}
                  name={s.name}
                  fill={s.color}
                  stackId={type === 'stacked-bar' ? 'stack' : s.stackId}
                  radius={[4, 4, 0, 0]}
                  animationDuration={animation ? 500 : 0}
                  onClick={(data: any, idx: number) => handleDataPointClick(data, idx)}
                />
              ))}
            </BarChart>
          </ResponsiveContainer>
        );

      case 'pie':
      case 'donut':
        return (
          <ResponsiveContainer width={responsive ? '100%' : undefined} height={height}>
            <PieChart>
              {tooltip.enabled && <Tooltip content={<CustomTooltip dark={isDark} />} />}
              <Pie rootTabIndex={-1}
                data={series.map((s) => ({
                  name: s.name,
                  value: data.reduce((sum, row) => sum + (Number(row[s.dataKey]) || 0), 0),
                  color: s.color,
                }))}
                cx="50%"
                cy="50%"
                outerRadius={type === 'donut' ? 80 : 100}
                innerRadius={type === 'donut' ? 60 : 0}
                paddingAngle={2}
                dataKey="value"
                nameKey="name"
                animationDuration={animation ? 500 : 0}
                onClick={(data, idx) => handleDataPointClick(data, idx)}
              >
                {seriesWithColors.map((s, index) => (
                  <Cell key={`cell-${index}`} fill={s.color} />
                ))}
              </Pie>
              {legend.show && <Legend {...legend} />}
            </PieChart>
          </ResponsiveContainer>
        );

      case 'area':
      case 'stacked-area':
        return (
          <ResponsiveContainer width={responsive ? '100%' : undefined} height={height}>
            <AreaChart data={data} onClick={onChartClick}>
              {grid && <CartesianGrid strokeDasharray="3 3" stroke={isDark ? 'var(--text-secondary, #6E6E73)' : 'var(--border-subtle, rgba(0,0,0,0.06))'} />}
              <XAxis dataKey={xAxis?.dataKey} tick={{ fontSize: 12, fill: isDark ? 'var(--text-muted, #9A9A9F)' : 'var(--text-secondary, #6E6E73)' }} />
              <YAxis tick={{ fontSize: 12, fill: isDark ? 'var(--text-muted, #9A9A9F)' : 'var(--text-secondary, #6E6E73)' }} unit={yAxis?.unit} />
              {tooltip.enabled && <Tooltip content={<CustomTooltip dark={isDark} />} />}
              {legend.show && <Legend {...legend} />}
              {seriesWithColors.map((s) => (
                <Area
                  key={s.dataKey}
                  type={s.type || 'monotone'}
                  dataKey={s.dataKey}
                  name={s.name}
                  stroke={s.color}
                  fill={s.color}
                  fillOpacity={type === 'stacked-area' ? 0.6 : 0.3}
                  stackId={type === 'stacked-area' ? 'stack' : s.stackId}
                  animationDuration={animation ? 500 : 0}
                />
              ))}
            </AreaChart>
          </ResponsiveContainer>
        );

      case 'radar':
        return (
          <ResponsiveContainer width={responsive ? '100%' : undefined} height={height}>
            <RadarChart data={data}>
              <PolarGrid stroke={isDark ? 'var(--text-secondary, #6E6E73)' : 'var(--border-subtle, rgba(0,0,0,0.06))'} />
              <PolarAngleAxis
                dataKey={xAxis?.dataKey || 'name'}
                tick={{ fontSize: 12, fill: isDark ? 'var(--text-muted, #9A9A9F)' : 'var(--text-secondary, #6E6E73)' }}
              />
              <PolarRadiusAxis tick={{ fontSize: 12, fill: isDark ? 'var(--text-muted, #9A9A9F)' : 'var(--text-secondary, #6E6E73)' }} />
              {tooltip.enabled && <Tooltip content={<CustomTooltip dark={isDark} />} />}
              {legend.show && <Legend {...legend} />}
              {seriesWithColors.map((s) => (
                <Radar
                  key={s.dataKey}
                  name={s.name}
                  dataKey={s.dataKey}
                  stroke={s.color}
                  fill={s.color}
                  fillOpacity={0.3}
                  animationDuration={animation ? 500 : 0}
                />
              ))}
            </RadarChart>
          </ResponsiveContainer>
        );

      case 'scatter':
        return (
          <ResponsiveContainer width={responsive ? '100%' : undefined} height={height}>
            <ScatterChart>
              {grid && <CartesianGrid strokeDasharray="3 3" stroke={isDark ? 'var(--text-secondary, #6E6E73)' : 'var(--border-subtle, rgba(0,0,0,0.06))'} />}
              <XAxis dataKey={xAxis?.dataKey || 'x'} name={xAxis?.label || 'X'} tick={{ fontSize: 12 }} />
              <YAxis dataKey={series[0]?.dataKey || 'y'} name={yAxis?.label || 'Y'} tick={{ fontSize: 12 }} />
              {tooltip.enabled && <Tooltip content={<CustomTooltip dark={isDark} />} />}
              {legend.show && <Legend {...legend} />}
              {seriesWithColors.map((s) => (
                <Scatter
                  key={s.dataKey}
                  name={s.name}
                  dataKey={s.dataKey}
                  fill={s.color}
                  animationDuration={animation ? 500 : 0}
                />
              ))}
            </ScatterChart>
          </ResponsiveContainer>
        );

      default:
        return (
          <div className="flex items-center justify-center h-full min-h-[200px] bg-neutral-50 dark:bg-neutral-800 rounded-lg">
            <p className="text-text-muted">不支持的图表类型: {type}</p>
          </div>
        );
    }
  };

  return (
    <div style={{ width: '100%' }}>
      {/* 图表标题区 */}
      {(title || subtitle) && (
        <div style={{ marginBottom: '16px' }}>
          {title && (
            <h3
              style={{
                fontSize: '16px',
                fontWeight: 'bold',
                color: isDark ? 'var(--card-bg-solid, #FFFFFF)' : 'var(--bg-canvas, #000000)',
                marginBottom: '4px',
              }}
            >
              {title}
            </h3>
          )}
          {subtitle && (
            <p
              style={{
                fontSize: '14px',
                color: isDark ? 'var(--text-muted, #9A9A9F)' : 'var(--text-secondary, #6E6E73)',
                marginTop: '4px',
              }}
            >
              {subtitle}
            </p>
          )}
        </div>
      )}

      {/* 图表主体 */}
      <div
        style={{
          backgroundColor: isDark ? 'var(--bg-canvas, #000000)' : 'var(--card-bg-solid, #FFFFFF)',
          borderRadius: '12px',
          padding: '16px',
          border: `1px solid ${isDark ? 'var(--bg-secondary, var(--bg-surface-container))' : 'var(--border-subtle, rgba(0,0,0,0.06))'}`,
          transition: 'box-shadow 0.2s',
        }}
        onMouseEnter={(e) => {
          (e.currentTarget as HTMLElement).style.boxShadow = isDark
            ? '0 10px 25px rgba(0, 0, 0, 0.3)'
            : '0 10px 25px rgba(0, 0, 0, 0.1)';
        }}
        onMouseLeave={(e) => {
          (e.currentTarget as HTMLElement).style.boxShadow = 'none';
        }}
      >
        {renderChartContent()}
      </div>
    </div>
  );
};

export default AdvancedChartEngine;

/**
 * Enhanced Area Chart Component
 *
 * Features:
 * - Full Material Design 3 theme support (light/dark)
 * - Smooth animations with easing
 * - Interactive tooltips
 * - Responsive design
 * - Gradient fill effects
 * - Grid lines with subtle styling
 * - Legend support
 * - Accessibility compliant
 */
import React, { useMemo } from 'react'
import {
  AreaChart as RechartsAreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Legend,
} from 'recharts'

interface ChartData {
  chart_type: string
  title: string
  subtitle?: string
  labels: string[]
  datasets: {
    data: number[]
    label?: string
    borderColor?: string
    backgroundColor?: string | string[]
    fill?: boolean
    tension?: number
    pointRadius?: number
    pointHoverRadius?: number
  }[]
}

interface ThemeColors {
  primary: string
  secondary: string
  tertiary: string
  textPrimary: string
  textSecondary: string
  textMuted: string
  surfaceVariant: string
  outline: string
  background: string
  surface: string
  success: string
  warning: string
  error: string
  info: string
}

interface EnhancedAreaChartProps {
  data: ChartData
  themeColors: ThemeColors
  height?: number
  showLegend?: boolean
  showGrid?: boolean
  animate?: boolean
}

export function EnhancedAreaChart({
  data,
  themeColors,
  height = 320,
  showLegend = true,
  showGrid = true,
  animate = true,
}: EnhancedAreaChartProps) {

  const chartData = useMemo(() => {
    const labels = data.labels || []
    const datasets = data.datasets || []

    return labels.map((label, index) => {
      const point: Record<string, any> = { name: label }

      datasets.forEach((dataset, datasetIndex) => {
        point[dataset.label || `series_${datasetIndex}`] = dataset.data[index] ?? 0
      })

      return point
    })
  }, [data])

  const defaultColors = [
    themeColors.primary,
    themeColors.secondary,
    themeColors.tertiary,
    themeColors.success,
    themeColors.warning,
    themeColors.info,
  ]

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload?.length) {
      return (
        <div
          className="rounded-lg p-4 shadow-xl border backdrop-blur-sm"
          style={{
            backgroundColor: `${themeColors.surface}F2`,
            borderColor: themeColors.outline,
          }}
        >
          <p className="font-semibold mb-3 text-sm" style={{ color: themeColors.textPrimary }}>
            {label}
          </p>
          {payload.map((entry: any, index: number) => (
            <div key={index} className="flex items-center justify-between gap-4 mb-1.5 last:mb-0">
              <div className="flex items-center gap-2">
                <div
                  className="w-2.5 h-2.5 rounded-full"
                  style={{ backgroundColor: entry.color }}
                />
                <span className="text-xs font-medium" style={{ color: themeColors.textSecondary }}>
                  {entry.name}
                </span>
              </div>
              <span className="text-sm font-bold tabular-nums" style={{ color: themeColors.textPrimary }}>
                {typeof entry.value === 'number' ? entry.value.toLocaleString('zh-CN') : entry.value}
              </span>
            </div>
          ))}
        </div>
      )
    }
    return null
  }

  const CustomLegend = ({ payload }: any) => {
    if (!showLegend || !payload) return null

    return (
      <div className="flex flex-wrap justify-center gap-4 mt-4 pt-4" style={{ borderTop: `1px solid ${themeColors.outline}20` }}>
        {payload.map((entry: any, index: number) => (
          <div key={index} className="flex items-center gap-2 cursor-pointer group">
            <div
              className="w-3 h-3 rounded-full transition-transform group-hover:scale-125"
              style={{ backgroundColor: entry.color }}
            />
            <span
              className="text-xs font-medium transition-colors group-hover:text-primary"
              style={{ color: themeColors.textSecondary }}
            >
              {entry.value}
            </span>
          </div>
        ))}
      </div>
    )
  }

  return (
    <ResponsiveContainer width="100%" height={height}>
      <RechartsAreaChart
        data={chartData}
        margin={{ top: 10, right: 30, left: 0, bottom: 0 }}
      >
        {showGrid && (
          <CartesianGrid
            strokeDasharray="3 3"
            stroke={themeColors.surfaceVariant}
            vertical={false}
            opacity={0.5}
          />
        )}

        <XAxis
          dataKey="name"
          axisLine={false}
          tickLine={false}
          tick={{
            fill: themeColors.textMuted,
            fontSize: 12,
            fontFamily: 'inherit',
          }}
          tickMargin={10}
        />

        <YAxis
          axisLine={false}
          tickLine={false}
          tick={{
            fill: themeColors.textMuted,
            fontSize: 12,
            fontFamily: 'inherit',
          }}
          tickFormatter={(value: number) => (value >= 1000 ? `${(value / 1000).toFixed(1)}K` : String(value))}
          width={60}
        />

        <Tooltip content={<CustomTooltip />} animationDuration={200} />
        <Legend content={<CustomLegend />} />

        {(data.datasets || []).map((dataset, index) => {
          const color = defaultColors[index % defaultColors.length]

          return (
            <Area
              key={index}
              type="monotone"
              dataKey={dataset.label || `series_${index}`}
              stroke={color}
              strokeWidth={2.5}
              fill={`url(#gradient_${index})`}
              fillOpacity={0.6}
              dot={false}
              activeDot={{
                r: 6,
                fill: color,
                stroke: themeColors.background,
                strokeWidth: 2,
                filter: 'drop-shadow(0 2px 4px rgba(0,0,0,0.15))',
              }}
              isAnimationActive={animate}
              animationBegin={0}
              animationDuration={1200}
              animationEasing="ease-in-out"
              name={dataset.label}
            />
          )
        })}

        {/* Gradient Definitions */}
        <defs>
          {(data.datasets || []).map((_, index) => {
            const color = defaultColors[index % defaultColors.length]

            return (
              <linearGradient key={index} id={`gradient_${index}`} x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor={color} stopOpacity={0.35} />
                <stop offset="95%" stopColor={color} stopOpacity={0.02} />
              </linearGradient>
            )
          })}
        </defs>
      </RechartsAreaChart>
    </ResponsiveContainer>
  )
}

export default EnhancedAreaChart

/**
 * Enhanced Bar Chart Component
 *
 * Features:
 * - Grouped/stacked bar support
 * - Animated bars with entrance effects
 * - Theme-aware colors
 * - Interactive hover states
 * - Gradient fills option
 */
import React, { useMemo } from 'react'
import {
  BarChart as RechartsBarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Legend,
  Cell,
} from 'recharts'

interface ChartData {
  chart_type: string
  title: string
  labels: string[]
  datasets: {
    data: number[]
    label?: string
    backgroundColor?: string | string[]
    borderRadius?: number
  }[]
}

interface ThemeColors {
  primary: string
  secondary: string
  tertiary: string
  textPrimary: string
  textSecondary: string
  textMuted: string
  surfaceVariant: string
  outline: string
  background: string
  success: string
  warning: string
  surface: string
  outlineVariant: string
}

interface EnhancedBarChartProps {
  data: ChartData
  themeColors: ThemeColors
  height?: number
  horizontal?: boolean
  stacked?: boolean
  showGrid?: boolean
}

export function EnhancedBarChart({
  data,
  themeColors,
  height = 320,
  horizontal = false,
  stacked = false,
  showGrid = true,
}: EnhancedBarChartProps) {

  const chartData = useMemo(() => {
    const labels = data.labels || []

    return labels.map((label, index) => {
      const point: Record<string, any> = { name: label }

      ;(data.datasets || []).forEach((dataset: { data: number[]; label?: string }, datasetIndex: number) => {
        point[dataset.label || `series_${datasetIndex}`] = dataset.data[index] ?? 0
      })

      return point
    })
  }, [data])

  const defaultColors = [
    themeColors.primary,
    themeColors.secondary,
    themeColors.success,
    themeColors.warning,
    'var(--color-tertiary, var(--color-accent-500))',
  ]

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload?.length) {
      return (
        <div
          className="rounded-lg p-4 shadow-xl border min-w-[160px]"
          style={{
            backgroundColor: `${themeColors.surface}F5`,
            borderColor: themeColors.outline,
          }}
        >
          <p className="font-semibold mb-2 text-sm" style={{ color: themeColors.textPrimary }}>
            {label}
          </p>
          {payload.map((entry: any, index: number) => (
            <div key={index} className="flex items-center justify-between gap-4 mb-1.5 last:mb-0">
              <div className="flex items-center gap-2">
                <div
                  className="w-3 h-3 rounded-sm"
                  style={{ backgroundColor: entry.color }}
                />
                <span className="text-xs font-medium" style={{ color: themeColors.textSecondary }}>
                  {entry.name}
                </span>
              </div>
              <span className="text-sm font-bold tabular-nums" style={{ color: themeColors.textPrimary }}>
                {entry.value?.toLocaleString('zh-CN')}
              </span>
            </div>
          ))}

          {/* Total for stacked */}
          {stacked && (
            <div
              className="mt-3 pt-3 border-t flex justify-between items-center"
              style={{ borderColor: themeColors.outlineVariant }}
            >
              <span className="text-xs font-bold" style={{ color: themeColors.textSecondary }}>总计</span>
              <span className="text-sm font-bold tabular-nums" style={{ color: themeColors.primary }}>
                {payload.reduce((sum: number, item: any) => sum + (item.value || 0), 0).toLocaleString()}
              </span>
            </div>
          )}
        </div>
      )
    }
    return null
  }

  if (horizontal) {
    return (
      <ResponsiveContainer width="100%" height={height}>
        <RechartsBarChart
          data={chartData}
          layout="vertical"
          margin={{ top: 10, right: 30, left: 80, bottom: 0 }}
        >
          {showGrid && <CartesianGrid strokeDasharray="3 3" stroke={themeColors.surfaceVariant} opacity={0.3} horizontal={false} />}

          <XAxis type="number" axisLine={false} tickLine={false} tick={{ fill: themeColors.textMuted, fontSize: 12 }} />
          <YAxis
            type="category"
            dataKey="name"
            axisLine={false}
            tickLine={false}
            tick={{ fill: themeColors.textSecondary, fontSize: 12 }}
            width={75}
          />

          <Tooltip content={<CustomTooltip />} animationDuration={200} cursor={{ fill: `${themeColors.primary}08` }} />

          {(data.datasets || []).map((dataset, index) => (
            <Bar
              key={index}
              dataKey={dataset.label || `series_${index}`}
              fill={defaultColors[index % defaultColors.length]}
              radius={[0, 4, 4, 0]}
              stackId={stacked ? "stack" : undefined}
              isAnimationActive={true}
              animationDuration={800}
              animationEasing="ease-out"
              maxBarSize={24}
            >
              {chartData.map((_, cellIndex) => (
                <Cell
                  key={`cell-${cellIndex}`}
                  fill={Array.isArray(dataset.backgroundColor)
                    ? (dataset.backgroundColor[cellIndex % dataset.backgroundColor.length] || defaultColors[index])
                    : (dataset.backgroundColor || defaultColors[index % defaultColors.length])
                  }
                />
              ))}
            </Bar>
          ))}
        </RechartsBarChart>
      </ResponsiveContainer>
    )
  }

  return (
    <ResponsiveContainer width="100%" height={height}>
      <RechartsBarChart
        data={chartData}
        margin={{ top: 10, right: 30, left: 0, bottom: 0 }}
      >
        {showGrid && <CartesianGrid strokeDasharray="3 3" stroke={themeColors.surfaceVariant} opacity={0.3} vertical={false} />}

        <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: themeColors.textMuted, fontSize: 12 }} />
        <YAxis axisLine={false} tickLine={false} tick={{ fill: themeColors.textMuted, fontSize: 12 }} width={55} />

        <Tooltip content={<CustomTooltip />} animationDuration={200} cursor={{ fill: `${themeColors.primary}08` }} />

        {(data.datasets || []).map((dataset, index) => (
          <Bar
            key={index}
            dataKey={dataset.label || `series_${index}`}
            fill={defaultColors[index % defaultColors.length]}
            radius={[4, 4, 0, 0]}
            stackId={stacked ? "stack" : undefined}
            isAnimationActive={true}
            animationDuration={800}
            animationEasing="ease-out"
            maxBarSize={40}
          >
            {chartData.map((_, cellIndex) => (
              <Cell
                key={`cell-${cellIndex}`}
                fill={Array.isArray(dataset.backgroundColor)
                  ? (dataset.backgroundColor[cellIndex % dataset.backgroundColor.length] || defaultColors[index])
                  : (dataset.backgroundColor || defaultColors[index % defaultColors.length])
                }
              />
            ))}
          </Bar>
        ))}
      </RechartsBarChart>
    </ResponsiveContainer>
  )
}

export default EnhancedBarChart

