import {
  LineChart as RechartsLineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Legend,
  Brush,
} from 'recharts';

interface ChartData {
  chart_type: string;
  title: string;
  labels: string[];
  datasets: {
    data: number[];
    label?: string;
    borderColor?: string;
    backgroundColor?: string | string[];
    tension?: number;
    pointRadius?: number;
    pointHoverRadius?: number;
  }[];
}

interface ThemeColors {
  primary: string;
  secondary: string;
  tertiary: string;
  textPrimary: string;
  textSecondary: string;
  textMuted: string;
  surfaceVariant: string;
