              </tr>
            </thead>
            <tbody>
              {categoryItems.map((item, idx) => (
                <tr key={item.id ?? idx} className={idx % 2 === 0 ? 'bg-white dark:bg-neutral-900' : 'bg-neutral-50 dark:bg-neutral-800'}>
