/**
 * 仪表板模板管理组件
 * - 导入/导出仪表板模板
 * - 管理保存的模板
 * - 应用模板到仪表板
 */
import { useState, useRef, useEffect } from 'react'
import { Download, Upload, Save, Trash2, CheckCircle2, FileText, Share2 } from 'lucide-react'
import { Card, CardHeader, CardTitle, CardContent, Button, Input, Badge } from '@/components/ui'
import type { DashboardLayout } from '@/config/dashboard'
import DashboardConfigManager from '@/config/dashboard'
import { logger } from '@/utils/safeLogger';


interface TemplateManagerProps {
  currentLayout: DashboardLayout
  onUpdate: (layout: DashboardLayout) => void
  className?: string
}

interface DashboardTemplate {
  id: string
  name: string
  description: string
  layout: DashboardLayout
  createdAt: string
  updatedAt: string
}

export function TemplateManager({ currentLayout, onUpdate, className }: TemplateManagerProps) {
  const [templates, setTemplates] = useState<DashboardTemplate[]>([])
  const [isImportDialogOpen, setIsImportDialogOpen] = useState(false)
  const [isExportDialogOpen, setIsExportDialogOpen] = useState(false)
  const [isSaveDialogOpen, setIsSaveDialogOpen] = useState(false)
  const [templateName, setTemplateName] = useState('')
  const [templateDescription, setTemplateDescription] = useState('')
  const [importError, setImportError] = useState('')
  const fileInputRef = useRef<HTMLInputElement>(null)

  // 挂载时从 localStorage 加载已保存的模板
  useEffect(() => {
    const savedTemplates = localStorage.getItem('rmfood_dashboard_templates')
    if (savedTemplates) {
      try {
        setTemplates(JSON.parse(savedTemplates))
      } catch (error) {
        logger.error('Error loading templates:', error)
      }
    }
  }, [])

  const saveTemplates = (newTemplates: DashboardTemplate[]) => {
    setTemplates(newTemplates)
    localStorage.setItem('rmfood_dashboard_templates', JSON.stringify(newTemplates))
  }

  const handleSaveTemplate = () => {
    if (!templateName.trim()) return

    const newTemplate: DashboardTemplate = {
      id: `template_${Date.now()}`,
      name: templateName.trim(),
      description: templateDescription.trim(),
      layout: currentLayout,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    }

    const updatedTemplates = [...templates, newTemplate]
    saveTemplates(updatedTemplates)
    setIsSaveDialogOpen(false)
    setTemplateName('')
    setTemplateDescription('')
  }

  const handleApplyTemplate = (template: DashboardTemplate) => {
    const newLayout = {
      ...template.layout,
      id: currentLayout.id,
      name: currentLayout.name,
      isDefault: currentLayout.isDefault,
    }
    onUpdate(newLayout)
    DashboardConfigManager.saveLayout(newLayout)
  }

  const handleDeleteTemplate = (templateId: string) => {
    const updatedTemplates = templates.filter(t => t.id !== templateId)
    saveTemplates(updatedTemplates)
  }

  const handleExportTemplate = (template: DashboardTemplate) => {
    const templateData = {
      version: '1.0',
      exportedAt: new Date().toISOString(),
      template,
    }

    const blob = new Blob([JSON.stringify(templateData, null, 2)], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `${template.name}_template.json`
    a.click()
    URL.revokeObjectURL(url)
  }

  const handleExportCurrent = () => {
    const templateData = {
      version: '1.0',
      exportedAt: new Date().toISOString(),
      template: {
        id: `template_${Date.now()}`,
        name: currentLayout.name,
        description: 'Exported dashboard layout',
        layout: currentLayout,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      },
    }

    const blob = new Blob([JSON.stringify(templateData, null, 2)], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `${currentLayout.name}_template.json`
    a.click()
    URL.revokeObjectURL(url)
    setIsExportDialogOpen(false)
  }

  const handleImportTemplate = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0]
    if (!file) return

    const reader = new FileReader()
    reader.onload = (e) => {
      try {
        const content = e.target?.result as string
        const data = JSON.parse(content)

        if (!data.template?.layout) {
          setImportError('无效的模板文件格式')
          return
        }

        const importedTemplate: DashboardTemplate = {
          id: `template_${Date.now()}`,
          name: data.template.name,
          description: data.template.description || 'Imported template',
          layout: data.template.layout,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
        }

        const updatedTemplates = [...templates, importedTemplate]
        saveTemplates(updatedTemplates)
        setImportError('')
        setIsImportDialogOpen(false)

        // 重置文件输入
        if (fileInputRef.current) {
          fileInputRef.current.value = ''
        }
      } catch (error) {
        setImportError('导入失败：文件格式错误')
        logger.error('Error importing template:', error)
      }
    }
    reader.readAsText(file)
  }

  return (
    <Card className={className}>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <FileText size={20} className="text-secondary-600 dark:text-secondary-700" />
            <CardTitle as="h2" className="text-sm font-semibold">模板管理</CardTitle>
          </div>
          <Badge size="sm">{templates.length}</Badge>
        </div>
      </CardHeader>
      <CardContent>
        {/* 操作按钮 */}
        <div className="flex flex-wrap gap-2 mb-4">
          <Button
            variant="primary"
            size="sm"
            icon={<Save size={16} />}
            onClick={() => setIsSaveDialogOpen(true)}
          >
            保存为模板
          </Button>
          <Button
            variant="secondary"
            size="sm"
            icon={<Upload size={16} />}
            onClick={() => setIsImportDialogOpen(true)}
          >
            导入模板
          </Button>
          <Button
            variant="secondary"
            size="sm"
            icon={<Download size={16} />}
            onClick={() => setIsExportDialogOpen(true)}
          >
            导出当前布局
          </Button>
        </div>

        {/* 模板列表 */}
        <div className="mt-4 border rounded-lg">
          {templates.length === 0 ? (
            <div className="py-4">
              <p className="text-sm text-neutral-500 dark:text-neutral-400 text-center">
                暂无保存的模板
              </p>
            </div>
          ) : (
            templates.map((template) => (
              <div key={template.id} className="py-3 px-4 border-b last:border-b-0 flex items-center justify-between">
                <div className="flex-1 min-w-0">
                  <div className="flex items-center justify-between">
                    <p className="text-sm font-medium text-neutral-900 dark:text-white truncate">
                      {template.name}
                    </p>
                    <Badge size="sm">
                      {new Date(template.updatedAt).toLocaleDateString()}
                    </Badge>
                  </div>
                  {template.description && (
                    <p className="text-xs text-neutral-500 dark:text-neutral-400 mt-1">
                      {template.description}
                    </p>
                  )}
                  <div className="flex items-center gap-2 mt-2">
                    <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                      卡片数量: {template.layout.cards.length}
                    </span>
                    <span className="text-xs text-neutral-300 dark:text-neutral-400">·</span>
                    <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                      最后更新: {new Date(template.updatedAt).toLocaleTimeString()}
                    </span>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <Button
                    variant="primary"
                    size="sm"
                    icon={<CheckCircle2 size={14} />}
                    onClick={() => handleApplyTemplate(template)}
                  >
                    应用
                  </Button>
                  <Button
                    variant="secondary"
                    size="sm"
                    icon={<Download size={14} />}
                    onClick={() => handleExportTemplate(template)}
                  >
                    导出
                  </Button>
                  <Button
                    variant="danger"
                    size="sm"
                    icon={<Trash2 size={14} />}
                    onClick={() => handleDeleteTemplate(template.id)}
                  >
                    删除
                  </Button>
                </div>
              </div>
            ))
          )}
        </div>

        {/* 导入模板对话框 */}
        {isImportDialogOpen && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
            <div className="bg-white dark:bg-neutral-800 rounded-lg p-6 max-w-md w-full">
              <h3 className="text-lg font-medium mb-4">导入模板</h3>
              {importError && (
                <div className="p-3 rounded-lg bg-error-50 dark:bg-error-300/15 border border-error-200 dark:border-error-800/30 mb-4">
                  <h4 className="text-sm font-medium text-error-800 dark:text-error-600 mb-1">导入失败</h4>
                  <p className="text-xs text-error-600 dark:text-error-600">{importError}</p>
                </div>
              )}
              <div className="space-y-4">
                <p className="text-sm text-neutral-600 dark:text-neutral-400">
                  选择JSON格式的模板文件进行导入
                </p>
                <input
                  ref={fileInputRef}
                  type="file"
                  accept=".json"
                  onChange={handleImportTemplate}
                  className="w-full p-3 border border-neutral-200 dark:border-neutral-700 rounded-lg" aria-label="选择文件" />
              </div>
              <div className="flex gap-2 mt-6 justify-end">
                <Button variant="secondary" onClick={() => setIsImportDialogOpen(false)}>
                  取消
                </Button>
              </div>
            </div>
          </div>
        )}

        {/* 导出当前布局对话框 */}
        {isExportDialogOpen && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
            <div className="bg-white dark:bg-neutral-800 rounded-lg p-6 max-w-md w-full">
              <h3 className="text-lg font-medium mb-4">导出当前布局</h3>
              <div className="space-y-4">
                <p className="text-sm text-neutral-600 dark:text-neutral-400">
                  将当前仪表板布局导出为JSON模板文件
                </p>
                <div className="p-4 rounded-lg bg-neutral-50 dark:bg-neutral-800/50 border border-neutral-200 dark:border-neutral-700">
                  <div className="flex items-center gap-3">
                    <FileText size={24} className="text-secondary-600 dark:text-secondary-700" />
                    <div>
                      <p className="text-sm font-medium text-neutral-900 dark:text-white">
                        {currentLayout.name}
                      </p>
                      <p className="text-xs text-neutral-500 dark:text-neutral-400">
                        包含 {currentLayout.cards.length} 个卡片
                      </p>
                    </div>
                  </div>
                </div>
              </div>
              <div className="flex gap-2 mt-6 justify-end">
                <Button variant="secondary" onClick={() => setIsExportDialogOpen(false)}>
                  取消
                </Button>
                <Button variant="primary" onClick={handleExportCurrent}>
                  导出
                </Button>
              </div>
            </div>
          </div>
        )}

        {/* 保存为模板对话框 */}
        {isSaveDialogOpen && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
            <div className="bg-white dark:bg-neutral-800 rounded-lg p-6 max-w-md w-full">
              <h3 className="text-lg font-medium mb-4">保存为模板</h3>
              <div className="space-y-4">
                <div>
                  <label className="text-sm font-medium mb-1 block">模板名称</label>
                  <Input
                    placeholder="输入模板名称"
                    value={templateName}
                    onChange={(e) => setTemplateName(e.target.value)}
                  />
                </div>
                <div>
                  <label className="text-sm font-medium mb-1 block">描述（可选）</label>
                  <Input
                    placeholder="输入模板描述"
                    value={templateDescription}
                    onChange={(e) => setTemplateDescription(e.target.value)}
                  />
                </div>
                <div className="p-4 rounded-lg bg-neutral-50 dark:bg-neutral-800/50 border border-neutral-200 dark:border-neutral-700">
                  <div className="flex items-center gap-3">
                    <Share2 size={24} className="text-secondary-600 dark:text-secondary-700" />
                    <div>
                      <p className="text-sm font-medium text-neutral-900 dark:text-white">
                        当前布局
                      </p>
                      <p className="text-xs text-neutral-500 dark:text-neutral-400">
                        包含 {currentLayout.cards.length} 个卡片
                      </p>
                    </div>
                  </div>
                </div>
              </div>
              <div className="flex gap-2 mt-6 justify-end">
                <Button variant="secondary" onClick={() => setIsSaveDialogOpen(false)}>
                  取消
                </Button>
                <Button
                  variant="primary"
                  onClick={handleSaveTemplate}
                  disabled={!templateName.trim()}
                >
                  保存
                </Button>
              </div>
            </div>
          </div>
        )}

        {/* 使用提示 */}
        <div className="mt-4 p-3 rounded-lg bg-secondary-50 dark:bg-secondary-300/15 border border-secondary-100 dark:border-secondary-800/30">
          <div className="flex items-start gap-3">
            <FileText size={18} className="text-secondary-600 dark:text-secondary-700 flex-shrink-0 mt-0.5" />
            <div>
              <h4 className="text-sm font-medium text-secondary-800 dark:text-secondary-700 mb-1">模板管理提示</h4>
              <ul className="text-xs text-secondary-600 dark:text-secondary-700 space-y-1">
                <li>• 保存当前布局为模板，方便后续快速应用</li>
                <li>• 导入/导出模板，实现布局的备份和分享</li>
                <li>• 应用模板会覆盖当前仪表板布局</li>
                <li>• 模板文件为JSON格式，可手动编辑调整</li>
              </ul>
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  )
}

/**
 * 快捷操作卡片 — 支持用户自定义 + 角色适配
 */
import type { FC } from 'react'
import { useState, useEffect } from 'react'
import { Link } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { Plus, TestTubes, Clock, Brain, Database, ArrowRight, Pencil, Trash2, Check, X } from 'lucide-react'
import { Card, CardHeader, CardTitle, CardContent, Button, Modal, Input } from '@/components/ui'

const STORAGE_KEY = 'rmfood_quick_actions'

interface Action {
  to: string
  icon: React.ComponentType<{ size?: number; className?: string }>
  title: string
  desc: string
  /** 可选翻译 key（默认快捷项用；用户自定义项为空则显示原 title） */
  titleKey?: string
  descKey?: string
  iconBg: string
  iconColor: string
}

const DEFAULT_ACTIONS: Action[] = [
  {
    to: '/formulas/new',
    icon: Plus,
    title: '新建配方',
    titleKey: 'pages.dashboard.cards.newFormula',
    desc: '药食同源配方',
    descKey: 'pages.dashboard.cards.formulaDesc',
    iconBg: 'bg-primary-100 dark:bg-primary-300/25',
    iconColor: 'text-primary-700 dark:text-primary-700',
  },
  {
    to: '/experiments',
    icon: TestTubes,
    title: '实验管理',
    titleKey: 'pages.dashboard.cards.experimentManagement',
    desc: '查看所有实验',
    descKey: 'pages.dashboard.cards.viewAllExperiments',
    iconBg: 'bg-secondary-100 dark:bg-secondary-300/25',
    iconColor: 'text-secondary-600 dark:text-secondary-700',
  },
  {
    to: '/formulas?status=pending_review',
    icon: Clock,
    title: '待审核配方',
    titleKey: 'pages.dashboard.cards.pendingReview',
    desc: '审核配方方案',
    descKey: 'pages.dashboard.cards.reviewFormulaPlan',
    iconBg: 'bg-warning-100 dark:bg-warning-300/25',
    iconColor: 'text-warning-600 dark:text-warning-700',
  },
  {
    to: '/ai',
    icon: Brain,
    title: 'AI智能助手',
    titleKey: 'pages.dashboard.cards.aiAssistant',
    desc: '配方生成/分析',
    descKey: 'pages.dashboard.cards.formulaGenAnalysis',
    iconBg: 'bg-accent-100 dark:bg-accent-300/25',
    iconColor: 'text-accent-600 dark:text-accent-700',
  },
  {
    to: '/databases',
    icon: Database,
    title: '数据库检索',
    titleKey: 'pages.dashboard.cards.databaseSearch',
    desc: 'TCMSP / DFBP',
    iconBg: 'bg-info-100 dark:bg-info-300/25',
    iconColor: 'text-info-600 dark:text-info-600',
  },
]

interface StoredAction {
  to: string
  icon: string
  title: string
  desc: string
}

const ICON_MAP: Record<string, React.ComponentType<{ size?: number; className?: string }>> = {
  Plus,
  TestTubes,
  Clock,
  Brain,
  Database,
  ArrowRight,
}

export const QuickActions: FC = () => {
  const { t } = useTranslation()
  const [actions, setActions] = useState<Action[]>([])
  const [editMode, setEditMode] = useState(false)
  // C-04: 自定义入口 Modal 表单（替代 4 次 prompt()）
  const [showAddModal, setShowAddModal] = useState(false)
  const [draft, setDraft] = useState({ to: '', title: '', desc: '', iconKey: 'Plus' })

  useEffect(() => {
    const stored = localStorage.getItem(STORAGE_KEY)
    if (stored) {
      try {
        const parsed: StoredAction[] = JSON.parse(stored)
        const mapped: Action[] = parsed.map(a => ({
          to: a.to,
          icon: ICON_MAP[a.icon] || Plus,
          title: a.title,
          desc: a.desc,
          iconBg: 'bg-primary-100 dark:bg-primary-300/25',
          iconColor: 'text-primary-700 dark:text-primary-700',
        }))
        setActions(mapped)
      } catch {
        setActions(DEFAULT_ACTIONS)
      }
    } else {
      setActions(DEFAULT_ACTIONS)
    }
  }, [])

  const saveActions = (newActions: Action[]) => {
    const stored: StoredAction[] = newActions.map(a => ({
      to: a.to,
      icon: Object.keys(ICON_MAP).find(k => ICON_MAP[k] === a.icon) || 'Plus',
      title: a.title,
      desc: a.desc,
    }))
    localStorage.setItem(STORAGE_KEY, JSON.stringify(stored))
    setActions(newActions)
  }

  const handleAddCustom = () => {
    setDraft({ to: '', title: '', desc: '', iconKey: 'Plus' })
    setShowAddModal(true)
  }

  const handleConfirmAdd = () => {
    const to = draft.to.trim()
    if (!to) return
    const icon = ICON_MAP[draft.iconKey] || Plus
    const newAction: Action = {
      to,
      icon,
      title: draft.title.trim() || t('pages.dashboard.cards.customEntry'),
      desc: draft.desc.trim(),
      iconBg: 'bg-accent-100 dark:bg-accent-300/25',
      iconColor: 'text-accent-600 dark:text-accent-700',
    }
    saveActions([...actions, newAction])
    setShowAddModal(false)
  }

  const handleDelete = (index: number) => {
    saveActions(actions.filter((_, i) => i !== index))
  }

  const actionTitle = (a: Action) => (a.titleKey ? t(a.titleKey) : a.title)
  const actionDesc = (a: Action) => (a.descKey ? t(a.descKey) : a.desc)

  return (
    <Card>
      <CardHeader className="px-6 pt-6 pb-4">
        <div className="flex items-center justify-between">
          <CardTitle as="h2" className="text-sm font-semibold text-neutral-900 dark:text-neutral-100">{t('pages.dashboard.cards.quickActions')}</CardTitle>
          {/* A-10：原 min-h-[24px] 实测命中区仅 48×24，低于 WCAG 2.5.5 的 44×44。
              抬到 44px 高，用 -my-3.5 / -mx-2 的负外边距抵消，保持视觉位置不变。 */}
          <button
            onClick={() => setEditMode(!editMode)}
            className="text-xs text-neutral-600 dark:text-neutral-400 hover:text-primary-700 dark:hover:text-primary-600 transition-colors flex items-center gap-1 min-h-[44px] px-2 -mx-2 -my-3.5"
            aria-label={editMode ? t('pages.dashboard.cards.editQuickActions') : t('pages.dashboard.cards.editQuickActions')}
          >
            {editMode ? <Check size={12} /> : <Pencil size={12} />}
            {editMode ? t('pages.dashboard.cards.finish') : t('pages.dashboard.cards.edit')}
          </button>
        </div>
      </CardHeader>
      <CardContent className="px-6 pb-6 pt-0">
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
          {actions.map((action, idx) => (
            <div key={action.to} className="relative group">
              <Link
                to={action.to}
                className="flex items-center gap-3 p-3 rounded-lg border border-neutral-100 dark:border-neutral-800 hover:border-neutral-200 dark:hover:border-neutral-700 hover:bg-neutral-50 dark:hover:bg-neutral-800/50 transition-colors duration-200 cursor-pointer"
              >
                <div className={`w-9 h-9 rounded-lg ${action.iconBg} flex items-center justify-center shrink-0`}>
                  <action.icon size={16} className={action.iconColor} />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="font-medium text-neutral-900 dark:text-white text-sm truncate">{actionTitle(action)}</p>
                  <p className="text-xs text-neutral-500 dark:text-neutral-400 mt-0.5">{actionDesc(action)}</p>
                </div>
                <ArrowRight size={14} className="text-neutral-600 dark:text-neutral-400 group-hover:text-primary-700 dark:group-hover:text-primary-400 transition-colors" />
              </Link>
              {editMode && (
                <button
                  onClick={(e) => { e.preventDefault(); handleDelete(idx) }}
                  className="absolute top-1 right-1 p-1 rounded bg-error-100 dark:bg-error-300/30 text-error-600 dark:text-error-600 opacity-0 group-hover:opacity-100 transition-opacity"
                  title={t('pages.dashboard.cards.delete')}
                >
                  <Trash2 size={12} />
                </button>
              )}
            </div>
          ))}
          {editMode && (
            <button
              onClick={handleAddCustom}
              className="flex items-center gap-2 p-3 rounded-lg border border-dashed border-neutral-300 dark:border-neutral-600 text-neutral-500 dark:text-neutral-400 hover:border-primary-400 hover:text-primary-700 dark:hover:border-primary-500 dark:hover:text-primary-600 transition-colors text-sm"
            >
              <Plus size={14} />
              {t('pages.dashboard.cards.addQuickEntry')}
            </button>
          )}
        </div>
      </CardContent>

      {/* C-04：自定义入口 Modal 表单 */}
      <Modal
        open={showAddModal}
        onClose={() => setShowAddModal(false)}
        title={t('pages.dashboard.cards.addQuickEntry')}
        maxWidth="max-w-md"
      >
        <div className="space-y-3">
          <div className="space-y-1">
            <label className="text-xs font-medium text-neutral-600 dark:text-neutral-400">{t('pages.dashboard.cards.jumpPath')}</label>
            <Input
              value={draft.to}
              onChange={(e) => setDraft((d) => ({ ...d, to: e.target.value }))}
              placeholder={t('pages.dashboard.cards.pathPlaceholder')}
            />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-medium text-neutral-600 dark:text-neutral-400">{t('pages.dashboard.cards.title')}</label>
            <Input
              value={draft.title}
              onChange={(e) => setDraft((d) => ({ ...d, title: e.target.value }))}
              placeholder={t('pages.dashboard.cards.customEntry')}
            />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-medium text-neutral-600 dark:text-neutral-400">{t('pages.dashboard.cards.desc')}</label>
            <Input
              value={draft.desc}
              onChange={(e) => setDraft((d) => ({ ...d, desc: e.target.value }))}
              placeholder={t('pages.dashboard.cards.optional')}
            />
          </div>
          <div className="space-y-1">
            <label className="text-xs font-medium text-neutral-600 dark:text-neutral-400">{t('pages.dashboard.cards.icon')}</label>
            <select
              value={draft.iconKey}
              onChange={(e) => setDraft((d) => ({ ...d, iconKey: e.target.value }))}
              className="w-full h-9 px-3 rounded-lg border border-neutral-200 dark:border-neutral-700 bg-white dark:bg-neutral-800 text-sm text-neutral-900 dark:text-neutral-100"
            >
              {Object.keys(ICON_MAP).map((k) => (
                <option key={k} value={k}>{k}</option>
              ))}
            </select>
          </div>
          <div className="flex justify-end gap-2 pt-2">
            <Button variant="secondary" size="sm" onClick={() => setShowAddModal(false)}>{t('common.cancel')}</Button>
            <Button
              size="sm"
              disabled={!draft.to.trim()}
              onClick={handleConfirmAdd}
            >
              {t('pages.dashboard.cards.add')}
            </Button>
          </div>
        </div>
      </Modal>
    </Card>
  )
}

/**
 * 团队活动卡 — 由原「即将上线」占位升级为真实数据聚合
 * 数据源：
 *   - 在线协作者：TeamOnlineStatus 的 user_status 事件（WS 启用时）
 *   - 最近动态：/dashboard/activity（已有 query）
 * 无数据时展示「暂无团队活动」而非虚假占位文案
 */
import type { FC } from 'react'
import { useState, useEffect, useCallback } from 'react'
import { useTranslation } from 'react-i18next'
import { Users, Activity as ActivityIcon, WifiOff } from 'lucide-react'
import { Card, CardHeader, CardTitle, CardContent, CardSkeleton, Badge } from '@/components/ui'
import { wsService, isWebSocketEnabled } from '@/services/websocket'

interface TeamActivityProps {
  timeline: { type: string; id: number | string; event: string; title: string; created_at: string; status: string }[]
  timelineLoading?: boolean
}

export const TeamActivity: FC<TeamActivityProps> = ({ timeline, timelineLoading }) => {
  const { t } = useTranslation()
  const [onlineUsers, setOnlineUsers] = useState<{ userId: string; userName: string; status: string }[]>([])

  // R-06 风格：WS 启用时订阅 user_status（载荷为扁平用户对象，与 TeamOnlineStatus 一致）；未启用时不伪造
  const upsertUser = useCallback((data: any) => {
    if (!data?.userId) return
    setOnlineUsers(prev => {
      const next = prev.filter(u => u.userId !== data.userId)
      next.push({ userId: data.userId, userName: data.userName ?? data.userId, status: data.status ?? 'online' })
      return next.filter((u: { status: string }) => u.status !== 'offline')
    })
  }, [])

  useEffect(() => {
    if (!isWebSocketEnabled) return
    const unsubscribe = wsService.on('user_status', upsertUser)
    return unsubscribe
  }, [upsertUser])

  const onlineCount = onlineUsers.filter(u => u.status === 'online').length

  if (timelineLoading) {
    return <CardSkeleton count={1} className="h-full" />
  }

  const hasContent = onlineUsers.length > 0 || timeline.length > 0

  return (
    <Card className="overflow-hidden">
      <CardHeader className="px-6 pt-6 pb-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Users size={18} className="text-secondary-600 dark:text-secondary-700" />
            <CardTitle as="h2" className="text-sm font-semibold" style={{ color: 'var(--text-primary)' }}>{t('pages.dashboard.cards.teamActivity')}</CardTitle>
          </div>
          {isWebSocketEnabled ? (
            <Badge variant="primary" size="sm">{t('pages.dashboard.cards.onlineCount', { count: onlineCount })}</Badge>
          ) : (
            <Badge variant="secondary" size="sm">{t('pages.dashboard.cards.realtimeNotEnabled')}</Badge>
          )}
        </div>
      </CardHeader>
      <CardContent className="px-6 pb-6 pt-0">
        {!hasContent ? (
          <div className="py-8 flex flex-col items-center gap-2 text-center">
            {isWebSocketEnabled ? (
              <>
                <Users size={28} className="text-neutral-600 dark:text-neutral-400" />
                <p className="text-sm text-neutral-500 dark:text-neutral-400">{t('pages.dashboard.cards.noTeamActivity')}</p>
                <p className="text-xs text-neutral-600 dark:text-neutral-400">
                  {t('pages.dashboard.cards.teamActivityDesc')}
                </p>
              </>
            ) : (
              <>
                <WifiOff size={28} className="text-neutral-600 dark:text-neutral-400" />
                <p className="text-sm text-neutral-500 dark:text-neutral-400">{t('pages.dashboard.cards.realtimeNotEnabled')}</p>
                <p className="text-xs text-neutral-600 dark:text-neutral-400">
                  {t('pages.dashboard.cards.staticOnlyDesc')}
                </p>
              </>
            )}
          </div>
        ) : (
          <div className="space-y-4">
            {/* 在线协作者 */}
            {onlineUsers.length > 0 && (
              <div>
                <h4 className="text-xs font-semibold text-neutral-500 dark:text-neutral-400 mb-2">{t('pages.dashboard.cards.currentlyOnline')}</h4>
                <div className="flex flex-wrap gap-2">
                  {onlineUsers.map(u => (
                    <div key={u.userId} className="flex items-center gap-1.5 px-2 py-1 rounded-full bg-secondary-50 dark:bg-secondary-300/20 text-xs">
                      <span className={`w-2 h-2 rounded-full ${u.status === 'online' ? 'bg-success-500' : 'bg-warning-500'}`} />
                      <span className="text-neutral-700 dark:text-neutral-400">{u.userName}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* 最近动态摘要 */}
            {timeline.length > 0 && (
              <div>
                <h4 className="text-xs font-semibold text-neutral-500 dark:text-neutral-400 mb-2 flex items-center gap-1">
                  <ActivityIcon size={12} /> {t('pages.dashboard.cards.recentActivityShort')}
                </h4>
                <div className="space-y-2">
                  {timeline.slice(0, 5).map(e => (
                    <div key={`${e.type}-${e.id}`} className="flex items-center justify-between text-xs">
                      <span className="text-neutral-700 dark:text-neutral-400 truncate flex-1">{e.title}</span>
                      <span className="text-neutral-600 dark:text-neutral-400 ml-2 shrink-0">
                        {new Date(e.created_at).toLocaleDateString('zh-CN', { month: 'short', day: 'numeric' })}
                      </span>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
      </CardContent>
    </Card>
  )
}

/**
 * 实验数据对比弹窗
 */
import { useState } from 'react'
import { X, BarChart3 } from 'lucide-react'
import { Button, CardContent } from '@/components/ui'
import { StatusBadge } from '@/components/ui/Common'
import { cn } from '@/lib/utils'
import type { Experiment } from '@/types'

interface Props {
  experiments: Experiment[]
  onClose: () => void
}

const COLORS = ['#8b5cf6', '#06b6d4', '#f59e0b', '#ef4444', '#10b981', '#ec4899']

export default function ExperimentCompareModal({ experiments, onClose }: Props) {
  const [activeTab, setActiveTab] = useState<'params' | 'data'>('params')

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/50 backdrop-blur-sm"  role="button" tabIndex={0} onClick={onClose} />
      <div className="relative w-full max-w-4xl max-h-[90vh] overflow-auto bg-white dark:bg-neutral-900 rounded-2xl shadow-2xl">
        {/* Header */}
        <div className="sticky top-0 z-10 flex items-center justify-between px-6 py-4 bg-white dark:bg-neutral-900 border-b border-neutral-200 dark:border-neutral-800">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-lg bg-accent-50 dark:bg-accent-300/20 flex items-center justify-center">
              <BarChart3 size={16} className="text-accent-500" />
            </div>
            <div>
              <h2 className="text-lg font-semibold text-neutral-900 dark:text-white">实验数据对比</h2>
              <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{experiments.length} 个实验</p>
            </div>
          </div>
          <Button variant="ghost" size="sm" icon={<X size={14} />} onClick={onClose}>关闭</Button>
        </div>

        {/* Tab switcher */}
        <div className="flex gap-1 px-6 py-3 bg-neutral-50 dark:bg-neutral-800/50 border-b border-neutral-200 dark:border-neutral-800">
          <button
            onClick={() => setActiveTab('params')}
            className={cn(
              'px-4 py-1.5 rounded-lg text-sm font-medium transition-colors',
              activeTab === 'params'
                ? 'bg-white dark:bg-neutral-700 text-neutral-900 dark:text-white shadow-sm'
                : 'text-neutral-500 hover:text-neutral-700 dark:hover:text-neutral-300',
            )}
          >
            参数对比
          </button>
          <button
            onClick={() => setActiveTab('data')}
            className={cn(
              'px-4 py-1.5 rounded-lg text-sm font-medium transition-colors',
              activeTab === 'data'
                ? 'bg-white dark:bg-neutral-700 text-neutral-900 dark:text-white shadow-sm'
                : 'text-neutral-500 hover:text-neutral-700 dark:hover:text-neutral-300',
            )}
          >
            数据趋势
          </button>
        </div>

        <CardContent className="p-6">
          {activeTab === 'params' ? (
            <ParamComparison experiments={experiments} />
          ) : (
            <DataComparison experiments={experiments} />
          )}
        </CardContent>
      </div>
    </div>
  )
}

function ParamComparison({ experiments }: { experiments: Experiment[] }) {
  // Collect all unique parameter keys
  const allParams = new Set<string>()
  for (const exp of experiments) {
    const params = exp.parameters || {}
    if (typeof params === 'object') {
      Object.keys(params).forEach(k => allParams.add(k))
    }
  }

  if (allParams.size === 0) {
    return <div className="text-center py-8 text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">暂无参数数据可对比</div>
  }

  const paramLabels: Record<string, string> = {
    temperature: '温度',
    humidity: '湿度',
    ph: 'pH值',
    time: '时间',
    concentration: '浓度',
    sample_size: '样本量',
    duration: '周期',
  }

  return (
    <div className="overflow-x-auto">
      <table className="w-full text-sm">
        <thead>
          <tr className="border-b border-neutral-200 dark:border-neutral-700">
            <th className="text-left py-3 px-4 text-xs font-semibold text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] w-32">参数</th>
            {experiments.map((exp, i) => (
              <th key={exp.id} className="text-left py-3 px-4 text-xs font-semibold text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                <div className="flex items-center gap-2">
                  <span className="w-2 h-2 rounded-full" style={{ backgroundColor: COLORS[i % COLORS.length] }} />
                  <span className="max-w-[150px] truncate">{exp.title}</span>
                </div>
                <StatusBadge status={exp.status} />
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {Array.from(allParams).map((param) => (
            <tr key={param} className="border-b border-neutral-100 dark:border-neutral-800 hover:bg-neutral-50 dark:hover:bg-neutral-800/30">
              <td className="py-3 px-4 font-medium text-neutral-700 dark:text-neutral-300">
                {paramLabels[param] || param}
              </td>
              {experiments.map((exp) => {
                const params = exp.parameters || {}
                const value = (params as Record<string, unknown>)[param] as string | number | undefined
                return (
                  <td key={exp.id} className="py-3 px-4 text-neutral-600 dark:text-neutral-400 font-mono">
                    {value ?? '-'}
                  </td>
                )
              })}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

function DataComparison({ experiments }: { experiments: Experiment[] }) {
  // Collect all data points
  const allDataPoints: Record<number, any[]> = {}
  const allParams = new Set<string>()

  for (const exp of experiments) {
    const data = (exp as { data_points?: unknown[] }).data_points || []
    allDataPoints[exp.id] = data
    data.forEach((d: any) => {
      if (d.parameter) allParams.add(d.parameter)
    })
  }

  if (allParams.size === 0) {
    return <div className="text-center py-8 text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">暂无数据点可对比</div>
  }

  return (
    <div className="space-y-6">
      {/* Parameter selector */}
      <div className="flex flex-wrap gap-2">
        {Array.from(allParams).map((param) => (
          <span key={param} className="px-2 py-1 rounded-md bg-neutral-100 dark:bg-neutral-800 text-xs text-neutral-600 dark:text-neutral-400">
            {param}
          </span>
        ))}
      </div>

      {/* Data table */}
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b border-neutral-200 dark:border-neutral-700">
              <th className="text-left py-2 px-3 text-xs font-semibold text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">参数</th>
              {experiments.map((exp, i) => (
                <th key={exp.id} className="text-left py-2 px-3 text-xs font-semibold text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                  <div className="flex items-center gap-1.5">
                    <span className="w-2 h-2 rounded-full" style={{ backgroundColor: COLORS[i % COLORS.length] }} />
                    {exp.code}
                  </div>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {Array.from(allParams).map((param) => (
              <tr key={param} className="border-b border-neutral-100 dark:border-neutral-800">
                <td className="py-2 px-3 font-medium text-neutral-700 dark:text-neutral-300">{param}</td>
                {experiments.map((exp) => {
                  const dps = allDataPoints[exp.id] || []
                  const matching = dps.filter((d: any) => d.parameter === param)
                  return (
                    <td key={exp.id} className="py-2 px-3 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] font-mono text-xs">
                      {matching.map((d: any, idx: number) => (
                        <div key={idx}>{d.value ?? '-'} {d.unit ?? ''}</div>
                      )) || '-'}
                    </td>
                  )
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  )
}

