// 文件交付组件
import React, { useState, useEffect } from 'react'
import { Card, Button, Progress, Alert, Badge, Modal } from '@/components/ui'
import type { TaskStatus as TaskStatusType } from '@/types/fileGenerator'
import { FileFormat } from '@/types/fileGenerator'
import { fileGeneratorApi } from '@/api/fileGenerator'
import { Download, Eye, RefreshCw, X, Clock, Check, AlertCircle, FileText, Table, File } from 'lucide-react'
import { logger } from '@/utils/safeLogger';


interface FileDeliveryProps {
  taskId: string
  filename: string
  format: FileFormat
  onClose: () => void
}

export function FileDelivery({ taskId, filename, format, onClose }: FileDeliveryProps) {
  const [status, setStatus] = useState<TaskStatusType | null>(null)
  const [, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [showPreview, setShowPreview] = useState(false)
  const [previewUrl, setPreviewUrl] = useState<string | null>(null)
  const [isDownloading, setIsDownloading] = useState(false)

  const formatIcon = {
    [FileFormat.PDF]: <File className="w-4 h-4" />,
    [FileFormat.DOCX]: <FileText className="w-4 h-4" />,
    [FileFormat.XLSX]: <Table className="w-4 h-4" />,
    [FileFormat.MARKDOWN]: <FileText className="w-4 h-4" />,
  }

  const formatName = {
    [FileFormat.PDF]: 'PDF',
    [FileFormat.DOCX]: 'Word',
    [FileFormat.XLSX]: 'Excel',
    [FileFormat.MARKDOWN]: 'Markdown',
  }

  const statusIcon = {
    pending: <Clock className="w-4 h-4" />,
    processing: <RefreshCw className="w-4 h-4 animate-spin" />,
    completed: <Check className="w-4 h-4" />,
    failed: <AlertCircle className="w-4 h-4" />,
  }

  const statusText = {
    pending: '等待中',
    processing: '处理中',
    completed: '已完成',
    failed: '失败',
  }

  const statusColor = {
    pending: 'bg-secondary-100 text-secondary-700',
    processing: 'bg-warning-100 text-warning-700',
    completed: 'bg-success-100 text-success-700',
    failed: 'bg-error-100 text-error-700',
  }

  useEffect(() => {
    const pollStatus = async () => {
      try {
        const taskStatus = await fileGeneratorApi.getTaskStatus(taskId)
        setStatus(taskStatus)

        if (taskStatus.status === 'completed' || taskStatus.status === 'failed') {
          setIsLoading(false)
        } else {
          // 继续轮询
          setTimeout(pollStatus, 1000)
        }
      } catch {
        setError('获取任务状态失败')
        setIsLoading(false)
      }
    }

    pollStatus()
  }, [taskId])

  const handleDownload = async () => {
    if (status?.status !== 'completed') return

    setIsDownloading(true)
    try {
      const blob = await fileGeneratorApi.downloadFile(taskId)
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = filename
      a.click()
      URL.revokeObjectURL(url)
    } catch {
      setError('文件下载失败')
    } finally {
      setIsDownloading(false)
    }
  }

  const handlePreview = async () => {
    if (status?.status !== 'completed') return

    try {
      const blob = await fileGeneratorApi.downloadFile(taskId)
      const url = URL.createObjectURL(blob)
      setPreviewUrl(url)
      setShowPreview(true)
    } catch {
      setError('文件预览失败')
    }
  }

  return (
    <Card className="p-6 max-w-md mx-auto">
      <div className="flex items-center justify-between mb-6">
        <h3 className="text-lg font-semibold flex items-center gap-2">
          {formatIcon[format]}
          文件生成状态
        </h3>
        <Button
          variant="ghost"
          size="sm"
          onClick={onClose}
          icon={<X className="w-4 h-4" />}
        >
          关闭
        </Button>
      </div>

      {error && (
        <Alert variant="destructive" className="mb-4">
          {error}
        </Alert>
      )}

      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <p className="text-sm font-medium">{filename}</p>
            <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{formatName[format]} 格式</p>
          </div>
          <Badge className={status ? statusColor[status.status] : 'bg-neutral-100 dark:bg-neutral-800 text-neutral-700'}>
            {status ? (
              <div className="flex items-center gap-1">
                {statusIcon[status.status]}
                <span>{statusText[status.status]}</span>
              </div>
            ) : (
              '加载中...'
            )}
          </Badge>
        </div>

        {status && status.status !== 'completed' && status.status !== 'failed' && (
          <div>
            <Progress value={status.progress} className="w-full" />
            <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-2">
              处理进度: {status.progress}%
            </p>
          </div>
        )}

        {status?.error_message && (
          <Alert variant="destructive" className="mt-4">
            <p className="text-sm">生成失败: {status.error_message}</p>
          </Alert>
        )}

        {status?.status === 'completed' && (
          <div className="space-y-3">
            <div className="flex items-center justify-between text-sm">
              <span>文件大小:</span>
              <span>{(status.file_size || 0) / 1024}.toFixed(2) KB</span>
            </div>
            <div className="flex gap-2">
              <Button
                onClick={handlePreview}
                variant="secondary"
                icon={<Eye className="w-4 h-4" />}
              >
                预览
              </Button>
              <Button
                onClick={handleDownload}
                loading={isDownloading}
                icon={<Download className="w-4 h-4" />}
              >
                下载
              </Button>
            </div>
          </div>
        )}

        {status?.status === 'failed' && (
          <Button
            variant="secondary"
            onClick={() => window.location.reload()}
            icon={<RefreshCw className="w-4 h-4" />}
          >
            重试
          </Button>
        )}
      </div>

      {/* 预览模态框 */}
      {showPreview && previewUrl && (
        <Modal open={showPreview} onClose={() => setShowPreview(false)} title="文件预览">
          <div className="h-96 overflow-auto">
            {format === FileFormat.PDF ? (
              <iframe
                src={previewUrl}
                width="100%"
                height="100%"
                title="PDF 预览"
              />
            ) : (
              <div className="p-4 bg-neutral-50 dark:bg-neutral-800 rounded-lg">
                <p className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                  此文件格式不支持在线预览，请下载后查看
                </p>
                <Button
                  className="mt-4"
                  onClick={handleDownload}
                  loading={isDownloading}
                  icon={<Download className="w-4 h-4" />}
                >
                  下载文件
                </Button>
              </div>
            )}
          </div>
        </Modal>
      )}
    </Card>
  )
}

export function FileGenerationButton({
  content,
  filename,
  format,
  template = 'default',
  children,
}: {
  content: any
  filename: string
  format: FileFormat
  template?: string
  children: React.ReactNode
}) {
  const [isGenerating, setIsGenerating] = useState(false)
  const [taskId, setTaskId] = useState<string | null>(null)
  const [showDelivery, setShowDelivery] = useState(false)

  const handleGenerate = async () => {
    setIsGenerating(true)
    try {
      const id = await fileGeneratorApi.generateFileAsync({
        content,
        format,
        filename,
        template,
      })
      setTaskId(id)
      setShowDelivery(true)
    } catch (error) {
      logger.error('文件生成失败:', error)
      alert('文件生成失败，请重试')
    } finally {
      setIsGenerating(false)
    }
  }

  return (
    <>
      <Button
        onClick={handleGenerate}
        loading={isGenerating}
      >
        {children}
      </Button>

      {showDelivery && taskId && (
        <Modal
          open={showDelivery}
          onClose={() => setShowDelivery(false)}
          title="文件生成"
          maxWidth="sm:max-w-md"
        >
          <FileDelivery
            taskId={taskId}
            filename={filename}
            format={format}
            onClose={() => setShowDelivery(false)}
          />
        </Modal>
      )}
    </>
  )
}

import { useState, useEffect, useMemo, useRef, useCallback } from 'react'
import { ChevronRight, ChevronDown, Search, X, FolderOpen, Folder } from 'lucide-react'
import { cn } from '@/lib/utils'
import { categoryApi } from '@/api/category'
import { Input, Badge } from '@/components/ui'
import type { Category } from '@/types'

interface CategoryTreeProps {
  value: number[]
  onChange: (ids: number[]) => void
  placeholder?: string
  maxHeight?: string
}

interface TreeNode extends Category {
  expanded?: boolean
  children?: TreeNode[]
  formulaCount?: number
}

function buildTree(categories: Category[]): TreeNode[] {
  const map = new Map<number, TreeNode>()
  const roots: TreeNode[] = []

  categories.forEach((cat) => {
    map.set(cat.id, { ...cat, expanded: false, children: [] })
  })

  map.forEach((node) => {
    if (node.parentId && map.has(node.parentId)) {
      map.get(node.parentId)!.children!.push(node)
    } else {
      roots.push(node)
    }
  })

  return roots
}

function flattenTree(
  nodes: TreeNode[],
  expandedIds: Set<number>,
  searchTerm: string,
  selectedIds: number[],
): TreeNode[] {
  const result: TreeNode[] = []

  nodes.forEach((node) => {
    const matchesSearch = searchTerm
      ? node.name.toLowerCase().includes(searchTerm.toLowerCase())
      : true

    const childMatches = node.children?.some(
      (child) =>
        flattenTree([child], expandedIds, searchTerm, selectedIds).length > 0,
    ) ?? false

    if (matchesSearch || childMatches) {
      result.push(node)
    }

    if (expandedIds.has(node.id) && node.children) {
      result.push(...flattenTree(node.children, expandedIds, searchTerm, selectedIds))
    }
  })

  return result
}

export function CategoryTree({
  value,
  onChange,
  placeholder = '选择分类',
  maxHeight = '320px',
}: CategoryTreeProps) {
  const [open, setOpen] = useState(false)
  const [search, setSearch] = useState('')
  const [categories, setCategories] = useState<Category[]>([])
  const [expandedIds, setExpandedIds] = useState<Set<number>>(new Set())
  const [loading, setLoading] = useState(false)

  // 虚拟滚动相关状态
  const [scrollTop, setScrollTop] = useState(0)
  const containerRef = useRef<HTMLDivElement>(null)
  const ITEM_HEIGHT = 36 // 每个节点的高度


  useEffect(() => {
    if (open && categories.length === 0) {
      setLoading(true)
      categoryApi.getTree().then((data) => {
        setCategories(data)
        setLoading(false)
      }).catch(() => {
        setLoading(false)
      })
    }
  }, [open, categories.length])

  const selectedCategories = useMemo(() => {
    const selected: Category[] = []
    const ids = new Set(value)

    const traverse = (cats: Category[]) => {
      cats.forEach((cat) => {
        if (ids.has(cat.id)) selected.push(cat)
        if (cat.children) traverse(cat.children)
      })
    }
    traverse(categories)

    return selected
  }, [value, categories])

  const treeData = useMemo(() => buildTree(categories), [categories])

  const flatData = useMemo(
    () => flattenTree(treeData, expandedIds, search, value),
    [treeData, expandedIds, search, value],
  )

  // 虚拟滚动相关计算
  const visibleItemCount = useMemo(() => {
    const containerHeight = parseInt(maxHeight) || 320
    return Math.ceil(containerHeight / ITEM_HEIGHT) + 2 // 额外渲染2个项目以避免空白
  }, [maxHeight])

  const startIndex = useMemo(() => {
    return Math.max(0, Math.floor(scrollTop / ITEM_HEIGHT) - 1) // 额外渲染1个项目以避免空白
  }, [scrollTop])

  const endIndex = useMemo(() => {
    return Math.min(flatData.length, startIndex + visibleItemCount)
  }, [flatData.length, startIndex, visibleItemCount])

  const visibleItems = useMemo(() => {
    return flatData.slice(startIndex, endIndex)
  }, [flatData, startIndex, endIndex])

  const handleScroll = useCallback((e: React.UIEvent<HTMLDivElement>) => {
    setScrollTop(e.currentTarget.scrollTop)
  }, [])

  const toggleExpand = (id: number) => {
    setExpandedIds((prev) => {
      const next = new Set(prev)
      if (next.has(id)) {
        next.delete(id)
      } else {
        next.add(id)
      }
      return next
    })
  }

  const toggleSelect = (id: number) => {
    if (value.includes(id)) {
      onChange(value.filter((v) => v !== id))
    } else {
      onChange([...value, id])
    }
  }

  const removeSelected = (id: number) => {
    onChange(value.filter((v) => v !== id))
  }

  const getIndent = (node: TreeNode): number => {
    let depth = 0
    let current = node
    while (current.parentId) {
      depth++
      current = categories.find((c) => c.id === current.parentId) || current
    }
    return depth
  }

  return (
    <div className="relative">
      <button
        type="button"
        onClick={() => setOpen(!open)}
        className={cn(
          'w-full min-h-[44px] px-3 py-1.5 rounded-lg border border-neutral-200 dark:border-neutral-700',
          'bg-white dark:bg-neutral-900 text-sm text-left',
          'hover:border-primary-400 dark:hover:border-primary-600 transition-colors',
          'flex flex-wrap gap-1.5 items-center',
        )}
      >
        {/* A-35：占位文案原为 neutral-400，白底 2.56:1 不达标 */}
        {selectedCategories.length === 0 ? (
          <span className="text-neutral-500 dark:text-neutral-400">{placeholder}</span>
        ) : (
          selectedCategories.map((cat) => (
            <Badge key={cat.id} variant="primary" size="sm" className="gap-1">
              {cat.name}
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation()
                  removeSelected(cat.id)
                }}
                className="hover:text-error-500"
              >
                <X size={10} />
              </button>
            </Badge>
          ))
        )}
      </button>

      {open && (
        <div className="absolute z-30 mt-1 w-full bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-700 rounded-xl shadow-xl overflow-hidden">
          <div className="p-2 border-b border-neutral-100 dark:border-neutral-800">
            <Input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="搜索分类..."
              size="sm"
              prefix={<Search size={14} />}
              suffix={
                search && (
                  <button
                    type="button"
                    onClick={() => setSearch('')}
                    className="hover:text-error-500"
                  >
                    <X size={14} />
                  </button>
                )
              }
              className="w-full"
            />
          </div>

          <div
            ref={containerRef}
            className="overflow-y-auto"
            style={{ maxHeight }}
            onScroll={handleScroll}
          >
            {loading ? (
              <div className="p-4 text-center text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                <div className="w-4 h-4 border-2 border-primary-300 border-t-primary-600 rounded-full animate-spin mx-auto" />
              </div>
            ) : flatData.length === 0 ? (
              <div className="p-4 text-center text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                {search ? '未找到匹配分类' : '暂无分类数据'}
              </div>
            ) : (
              <div style={{ height: `${flatData.length * ITEM_HEIGHT}px`, position: 'relative' }}>
                <div style={{
                  position: 'absolute',
                  top: `${startIndex * ITEM_HEIGHT}px`,
                  width: '100%',
                }}>
                  {visibleItems.map((node) => {
                    const indent = getIndent(node)
                    const hasChildren = (node.children?.length ?? 0) > 0
                    const isSelected = value.includes(node.id)
                    const isExpanded = expandedIds.has(node.id)

                    return (
                      <div
                        key={node.id}
                        className={cn(
                          'flex items-center gap-1.5 px-3 py-1.5 text-sm cursor-pointer',
                          'hover:bg-neutral-50 dark:hover:bg-neutral-800',
                          isSelected && 'bg-primary-50 dark:bg-primary-300/20',
                        )}
                        style={{ paddingLeft: `${12 + indent * 16}px`, height: `${ITEM_HEIGHT}px` }}
                         role="button" tabIndex={0} onClick={() => hasChildren ? toggleExpand(node.id) : toggleSelect(node.id)}
                      >
                        {hasChildren ? (
                          <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                            {isExpanded ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
                          </span>
                        ) : (
                          <span className="w-[14px]" />
                        )}
                        <span className="text-neutral-600 dark:text-neutral-400">
                          {isExpanded ? <FolderOpen size={14} /> : <Folder size={14} />}
                        </span>
                        <span
                          className={cn(
                            'flex-1 truncate',
                            isSelected
                              ? 'text-primary-700 dark:text-primary-700 font-medium'
                              : 'text-neutral-700 dark:text-neutral-300',
                          )}
                        >
                          {node.name}
                        </span>
                        {node.formulaCount !== undefined && node.formulaCount > 0 && (
                          <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{node.formulaCount}</span>
                        )}
                        {isSelected && (
                          <span className="w-2 h-2 rounded-full bg-primary-500" />
                        )}
                      </div>
                    )
                  })}
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {open && (
        <div
          className="fixed inset-0 z-20"
           role="button" tabIndex={0} onClick={() => setOpen(false)}
        />
      )}
    </div>
  )
}

/**
 * 效果预测曲线图 - PK/PD 时效曲线可视化
 */
import { useMemo } from 'react';

interface EffectCurveChartProps {
  ctCurve?: Array<{ time_hour: number; concentration: number }>;
  etCurve?: Array<{ time_hour: number; effect_level: number }>;
  peakTime?: number;
  peakConcentration?: number;
  maxEffect?: number;
  auc?: number;
}

export function EffectCurveChart({
  ctCurve = [],
  etCurve = [],
  peakTime = 0,
  peakConcentration = 0,
  maxEffect = 0,
  auc = 0,
}: EffectCurveChartProps) {
  const width = 400;
  const height = 200;
  const padding = 40;

  const maxX = Math.max(...ctCurve.map(p => p.time_hour), ...etCurve.map(p => p.time_hour), 1);
  const maxYCT = Math.max(...ctCurve.map(p => p.concentration), 1);
  const maxYET = Math.max(...etCurve.map(p => p.effect_level), 1);

  const pointsToPath = (points: Array<{ x: number; y: number }>) => {
    if (points.length < 2) return '';
    return points.map((p, i) => `${i === 0 ? 'M' : 'L'} ${p.x} ${p.y}`).join(' ');
  };

  const ctPoints = ctCurve.map(p => ({
    x: padding + (p.time_hour / maxX) * (width - 2 * padding),
    y: height - padding - (p.concentration / maxYCT) * (height - 2 * padding),
  }));

  const etPoints = etCurve.map(p => ({
    x: padding + (p.time_hour / maxX) * (width - 2 * padding),
    y: height - padding - (p.effect_level / maxYET) * (height - 2 * padding),
  }));

  return (
    <div className="space-y-3">
      <svg width="100%" viewBox={`0 0 ${width} ${height}`} className="max-w-full h-auto">
        {/* Grid */}
        {[0, 0.25, 0.5, 0.75, 1].map(frac => (
          <g key={frac}>
            <line
              x1={padding}
              y1={height - padding - frac * (height - 2 * padding)}
              x2={width - padding}
              y2={height - padding - frac * (height - 2 * padding)}
              stroke="currentColor"
              strokeWidth="0.5"
              className="text-neutral-200 dark:text-neutral-700"
            />
          </g>
        ))}
        {/* CT Curve */}
        <path d={pointsToPath(ctPoints)} fill="none" stroke="#8b5cf6" strokeWidth="2" />
        {/* ET Curve */}
        <path d={pointsToPath(etPoints)} fill="none" stroke="#10b981" strokeWidth="2" />
        {/* Peak marker */}
        {peakTime > 0 && (
          <circle
            cx={padding + (peakTime / maxX) * (width - 2 * padding)}
            cy={height - padding - (peakConcentration / maxYCT) * (height - 2 * padding)}
            r="4"
            fill="#ef4444"
          />
        )}
        {/* Axes */}
        <line x1={padding} y1={height - padding} x2={width - padding} y2={height - padding} stroke="currentColor" strokeWidth="1" className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
        <line x1={padding} y1={padding} x2={padding} y2={height - padding} stroke="currentColor" strokeWidth="1" className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
        {/* Labels */}
        <text x={width / 2} y={height - 5} textAnchor="middle" className="text-xs fill-neutral-500">时间 (h)</text>
        <text x={10} y={height / 2} textAnchor="middle" transform={`rotate(-90, 10, ${height / 2})`} className="text-xs fill-neutral-500">浓度/效应</text>
      </svg>
      <div className="flex gap-4 text-xs">
        <div className="flex items-center gap-1">
          <div className="w-3 h-0.5 bg-accent-500" />
          <span className="text-neutral-600 dark:text-neutral-400">血浆浓度 (CT)</span>
        </div>
        <div className="flex items-center gap-1">
          <div className="w-3 h-0.5 bg-success-500" />
          <span className="text-neutral-600 dark:text-neutral-400">效应水平 (ET)</span>
        </div>
        <div className="flex items-center gap-1 ml-auto">
          <div className="w-2 h-2 rounded-full bg-error-500" />
          <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">Tmax: {peakTime.toFixed(1)}h</span>
        </div>
      </div>
      <div className="grid grid-cols-3 gap-2 text-xs">
        <div className="p-2 rounded bg-accent-50 dark:bg-accent-300/20 text-center">
          <div className="text-accent-600 dark:text-accent-700">Cmax</div>
          <div className="font-bold text-accent-700 dark:text-accent-700">{peakConcentration.toFixed(1)}</div>
        </div>
        <div className="p-2 rounded bg-success-50 dark:bg-success-300/20 text-center">
          <div className="text-success-700 dark:text-success-600">Emax</div>
          <div className="font-bold text-success-700 dark:text-success-700">{maxEffect.toFixed(3)}</div>
        </div>
        <div className="p-2 rounded bg-secondary-50 dark:bg-secondary-300/20 text-center">
          <div className="text-secondary-700 dark:text-secondary-700">AUC</div>
          <div className="font-bold text-secondary-700 dark:text-secondary-700">{auc.toFixed(1)}</div>
        </div>
      </div>
    </div>
  );
}

/**
 * 配方效果预测可视化组件
 *
 * 功能:
 * - 时效曲线 (C-T) 图表
 * - 效应曲线 (E-T) 图表
 * - 多方案对比视图
 * - 最佳服用时间窗口标注
 * - 导出功能 (PNG/PDF)
 */

import React, { useState, useMemo } from 'react';
import {
  LineChart as LineIcon,
  Clock,
  TrendingUp,
  Maximize2,
  Download,
  GitCompare,
  Calendar,
  Target,
  CheckCircle2,
} from 'lucide-react';
import { Card, Button, Badge, Tabs, TabsTrigger } from '@/components/ui';

// ==================== 类型定义 ====================

interface TimePointData {
  time: number;
  concentration: number;
  effect: number;
}

interface EffectPredictionData {
  formula_id: string;
  ct_curve: TimePointData[];
  et_curve: TimePointData[];
  peak_time: number;
  peak_concentration: number;
  max_effect: number;
  duration: number;
  optimal_window: [number, number];
  auc: number;
}

interface ComparisonViewProps {
  formulas: {
    id: string;
    name: string;
    data: EffectPredictionData;
  }[];
  selectedFormulas?: string[];
  onFormulaToggle?: (id: string) => void;
}

// ==================== 组件1: 单方案效果预测图 ====================

interface EffectPredictionChartProps {
  data: EffectPredictionData;
  showConfidenceBand?: boolean;
  height?: number;
}

export function EffectPredictionChart({ data, showConfidenceBand = true, height = 300 }: EffectPredictionChartProps) {
  const [activeTab, setActiveTab] = useState<'ct' | 'et'>('ct');

  // 计算图表坐标范围
  const chartWidth = 600;
  const padding = { top: 30, right: 30, bottom: 50, left: 60 };
  const plotWidth = chartWidth - padding.left - padding.right;
  const plotHeight = height - padding.top - padding.bottom;

  // 坐标转换函数
  const maxTime = Math.max(...data.ct_curve.map((p) => p.time));
  const maxConc = Math.max(...data.ct_curve.map((p) => p.concentration)) * 1.2;
  const maxEffect = 1.1;

  const toX = (time: number) => (time / maxTime) * plotWidth + padding.left;
  const toYConc = (conc: number) => plotHeight - (conc / maxConc) * plotHeight + padding.top;
  const toYEffect = (effect: number) => plotHeight - (effect / maxEffect) * plotHeight + padding.top;

  // 生成 SVG 路径
  const generatePath = (points: TimePointData[], yMapper: (val: number) => number) => {
    if (points.length < 2) return '';

    return points
      .map((p, i) => {
        const x = toX(p.time);
        const y = yMapper(p === points[0] ? 0 : p.concentration || p.effect);
        return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
      })
      .join(' ');
  };

  // C-T 曲线路径
  const ctPath = generatePath(data.ct_curve, toYConc);
  // E-T 曲线路径
  const etPath = generatePath(data.et_curve, toYEffect);

  // 关键点标记
  const peakX = toX(data.peak_time);
  const peakYConc = toYConc(data.peak_concentration);
  const peakYEffect = toYEffect(data.max_effect);

  // 最佳时间窗口标记
  const windowStartX = toX(data.optimal_window[0]);
  const windowEndX = toX(data.optimal_window[1]);

  return (
    <Card className="p-6">
      {/* 标题栏 */}
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-semibold text-neutral-900 dark:text-white flex items-center gap-2">
          <TrendingUp className="w-5 h-5 text-success-500" />
          效果预测模拟
          <Badge variant="info">{data.formula_id}</Badge>
        </h3>

        <div className="flex gap-2">
          <Button variant="outline" size="sm">
            <Download className="w-4 h-4 mr-2" />
            PNG
          </Button>
          <Button variant="outline" size="sm">
            <Download className="w-4 h-4 mr-2" />
            PDF
          </Button>
        </div>
      </div>

      {/* 核心指标卡片 */}
      <div className="grid grid-cols-2 md:grid-cols-5 gap-3 mb-6">
        {[
          { label: '达峰时间', value: `${data.peak_time.toFixed(1)}h`, icon: <Clock />, color: 'blue' },
          {
            label: '峰浓度',
            value: `${data.peak_concentration.toFixed(2)}`,
            unit: 'μg/mL',
            icon: <LineIcon />,
            color: 'purple',
          },
          { label: '最大效应', value: `${(data.max_effect * 100).toFixed(1)}%`, icon: <Target />, color: 'green' },
          { label: '持续时间', value: `${data.duration.toFixed(1)}h`, icon: <Calendar />, color: 'orange' },
          { label: 'AUC', value: `${data.auc.toFixed(1)}`, unit: 'μg·h/mL', icon: <TrendingUp />, color: 'indigo' },
        ].map(({ label, value, unit, icon, color }) => (
          <div key={label} className={`p-3 bg-${color}-50 dark:bg-${color}-950 rounded-lg`}>
            <div className={`text-${color}-600 dark:text-${color}-400 mb-1`}>{icon}</div>
            <p className="text-xs text-neutral-600 dark:text-neutral-400">{label}</p>
            <p className="font-mono font-bold text-neutral-900 dark:text-white">
              {value}
              {unit && <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] ml-1">{unit}</span>}
            </p>
          </div>
        ))}
      </div>

      {/* 图表切换标签 */}
      <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as 'ct' | 'et')}>
        <TabsTrigger value="ct">时效曲线 (C-T)</TabsTrigger>
        <TabsTrigger value="et">效应曲线 (E-T)</TabsTrigger>
      </Tabs>

      {/* 图表区域 */}
      <div className="mt-4 relative bg-gradient-to-b from-neutral-50 to-white dark:from-neutral-900 dark:to-neutral-800 rounded-lg p-4 overflow-hidden">
        <svg width={chartWidth} height={height} className="mx-auto">
          {/* 网格线 */}
          {[0, 0.25, 0.5, 0.75, 1].map((tick) => (
            <g key={tick}>
              <line
                x1={padding.left + plotWidth * tick}
                y1={padding.top}
                x2={padding.left + plotWidth * tick}
                y2={height - padding.bottom}
                stroke="#E5E7EB"
                strokeDasharray="4,4"
                className="dark:stroke-neutral-700"
              />
              <line
                x1={padding.left}
                y1={height - padding.bottom - plotHeight * tick}
                x2={chartWidth - padding.right}
                y2={height - padding.bottom - plotHeight * tick}
                stroke="#E5E7EB"
                strokeDasharray="4,4"
                className="dark:stroke-neutral-700"
              />
            </g>
          ))}

          {/* 最佳时间窗口背景 */}
          <rect
            x={windowStartX}
            y={padding.top}
            width={windowEndX - windowStartX}
            height={plotHeight}
            fill="var(--color-primary-400)"
            opacity="0.08"
            rx="4"
          />

          {activeTab === 'ct' ? (
            <>
              {/* C-T 曲线 */}
              <path
                d={ctPath}
                fill="none"
                stroke="var(--color-secondary-500)"
                strokeWidth="3"
                strokeLinecap="round"
                strokeLinejoin="round"
              />

              {/* 峰值点标记 */}
              <circle cx={peakX} cy={peakYConc} r="6" fill="var(--color-secondary-500)" stroke="#fff" strokeWidth="2" />

              {/* 峰值标注 */}
              <g>
                <rect x={peakX - 40} y={peakYConc - 35} width="80" height="24" rx="4" fill="var(--color-secondary-500)" />
                <text x={peakX} y={peakYConc - 19} textAnchor="middle" fontSize="11" fill="#fff" fontWeight="bold">
                  Tmax: {data.peak_time.toFixed(1)}h
                </text>
                <line x1={peakX} y1={peakYConc - 11} x2={peakX} y2={peakYConc - 6} stroke="var(--color-secondary-500)" strokeWidth="2" />
              </g>

              {/* Y轴标签 */}
              <text
                x="15"
                y={height / 2 + 5}
                textAnchor="middle"
                fontSize="12"
                fill="#6B7280"
                transform={`rotate(-90, 15, ${height / 2})`}
              >
                浓度 (μg/mL)
              </text>

              {/* X轴刻度 */}
              {[0, 6, 12, 18, 24].map((hour) => (
                <g key={hour}>
                  <line
                    x1={toX(hour)}
                    y1={height - padding.bottom}
                    x2={toX(hour)}
                    y2={height - padding.bottom + 5}
                    stroke="#6B7280"
                    strokeWidth="1"
                  />
                  <text x={toX(hour)} y={height - padding.bottom + 18} textAnchor="middle" fontSize="11" fill="#6B7280">
                    {hour}h
                  </text>
                </g>
              ))}

              {/* 置信区间带（可选） */}
              {showConfidenceBand && (
                <path
                  d={`${generatePath(
                    data.ct_curve.map((p) => ({
                      ...p,
                      concentration: p.concentration * 1.3,
                    })),
                    toYConc,
                  )} L ${generatePath(
                    [...data.ct_curve.reverse()].map((p) => ({
                      ...p,
                      concentration: p.concentration * 0.7,
                    })),
                    toYConc,
                  )} Z`}
                  fill="var(--color-secondary-500)"
                  opacity="0.1"
                />
              )}
            </>
          ) : (
            <>
              {/* E-T 曲线 */}
              <path
                d={etPath}
                fill="none"
                stroke="var(--color-primary-400)"
                strokeWidth="3"
                strokeLinecap="round"
                strokeLinejoin="round"
              />

              {/* 最大效应点标记 */}
              <circle cx={toX(data.peak_time)} cy={peakYEffect} r="6" fill="var(--color-primary-400)" stroke="#fff" strokeWidth="2" />

              {/* 半效期参考线 */}
              <line
                x1={padding.left}
                y2={toYEffect(data.max_effect / 2)}
                x2={chartWidth - padding.right}
                y1={toYEffect(data.max_effect / 2)}
                stroke="#D97706"
                strokeWidth="1"
                strokeDasharray="8,4"
                opacity="0.6"
              />
              <text
                x={chartWidth - padding.right - 60}
                y={toYEffect(data.max_effect / 2) - 5}
                fontSize="10"
                fill="#D97706"
              >
                50% Emax
              </text>

              {/* Y轴标签 */}
              <text
                x="15"
                y={height / 2 + 5}
                textAnchor="middle"
                fontSize="12"
                fill="#6B7280"
                transform={`rotate(-90, 15, ${height / 2})`}
              >
                效应水平 (归一化)
              </text>

              {/* X轴刻度 */}
              {[0, 6, 12, 18, 24].map((hour) => (
                <g key={hour}>
                  <line
                    x1={toX(hour)}
                    y1={height - padding.bottom}
                    x2={toX(hour)}
                    y2={height - padding.bottom + 5}
                    stroke="#6B7280"
                    strokeWidth="1"
                  />
                  <text x={toX(hour)} y={height - padding.bottom + 18} textAnchor="middle" fontSize="11" fill="#6B7280">
                    {hour}h
                  </text>
                </g>
              ))}
            </>
          )}

          {/* 最佳窗口标注 */}
          <g>
            <line
              x1={windowStartX}
              y1={padding.top}
              x2={windowStartX}
              y2={height - padding.bottom}
              stroke="var(--color-primary-400)"
              strokeWidth="2"
              strokeDasharray="6,3"
            />
            <line
              x1={windowEndX}
              y1={padding.top}
              x2={windowEndX}
              y2={height - padding.bottom}
              stroke="var(--color-primary-400)"
              strokeWidth="2"
              strokeDasharray="6,3"
            />

            {/* 窗口标签 */}
            <rect
              x={(windowStartX + windowEndX) / 2 - 45}
              y={padding.top - 20}
              width="90"
              height="18"
              rx="9"
              fill="var(--color-primary-400)"
            />
            <text
              x={(windowStartX + windowEndX) / 2}
              y={padding.top - 8}
              textAnchor="middle"
              fontSize="10"
              fill="#fff"
              fontWeight="bold"
            >
              ⏰ 最佳服用窗口
            </text>
          </g>
        </svg>
      </div>

      {/* 底部说明 */}
      <div className="mt-4 flex items-center justify-between text-sm text-neutral-600 dark:text-neutral-400">
        <div className="flex items-center gap-4">
          <span>📊 基于 PopPK/PD 一室模型 + Sigmoid Emax</span>
          <span>•</span>
          <span>体重: 70kg</span>
        </div>

        <div className="flex items-center gap-2">
          <Badge variant="success">
            最佳窗口: {data.optimal_window[0].toFixed(1)}-{data.optimal_window[1].toFixed(1)}h
          </Badge>
        </div>
      </div>
    </Card>
  );
}

// ==================== 组件2: 多方案对比视图 ====================

export function MultiFormulaComparison({ formulas, selectedFormulas = [], onFormulaToggle }: ComparisonViewProps) {
  const [viewMode, setViewMode] = useState<'overlay' | 'sidebyside'>('overlay');

  const toggleFormula = (id: string) => {
    onFormulaToggle?.(id);
  };

  return (
    <Card className="p-6">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-semibold text-neutral-900 dark:text-white flex items-center gap-2">
          <GitCompare className="w-5 h-5 text-accent-500" />
          多方案对比分析
        </h3>

        <div className="flex items-center gap-2">
          <Button
            variant={viewMode === 'overlay' ? 'primary' : 'outline'}
            size="sm"
            onClick={() => setViewMode('overlay')}
          >
            叠加显示
          </Button>
          <Button
            variant={viewMode === 'sidebyside' ? 'primary' : 'outline'}
            size="sm"
            onClick={() => setViewMode('sidebyside')}
          >
            并列显示
          </Button>
        </div>
      </div>

      {/* 方案选择器 */}
      <div className="flex flex-wrap gap-2 mb-6">
        {formulas.map((f) => (
          <button
            key={f.id}
            onClick={() => toggleFormula(f.id)}
            className={`px-4 py-2 rounded-lg border-2 transition-all ${
              selectedFormulas.includes(f.id)
                ? 'border-primary-500 bg-primary-50 dark:bg-primary-950 shadow-md'
                : 'border-neutral-200 dark:border-neutral-700 hover:border-neutral-300'
            }`}
          >
            <span className="font-medium text-sm">{f.name}</span>
            {selectedFormulas.includes(f.id) && <CheckCircle2 className="inline w-4 h-4 ml-2 text-primary-500" />}
          </button>
        ))}
      </div>

      {/* 对比指标表格 */}
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead className="bg-neutral-50 dark:bg-neutral-800">
            <tr>
              <th className="px-4 py-3 text-left font-semibold text-neutral-700 dark:text-neutral-300">指标</th>
              {formulas
                .filter((f) => selectedFormulas.includes(f.id))
                .map((f) => (
                  <th key={f.id} className="px-4 py-3 text-right font-semibold text-neutral-700 dark:text-neutral-300">
                    {f.name}
                  </th>
                ))}
            </tr>
          </thead>
          <tbody className="divide-y divide-neutral-200 dark:divide-neutral-700">
            {[
              { label: 'Tmax (小时)', getValue: (d: EffectPredictionData) => d.peak_time.toFixed(2), unit: 'h' },
              { label: 'Cmax (μg/mL)', getValue: (d: EffectPredictionData) => d.peak_concentration.toFixed(3) },
              { label: 'Emax (%)', getValue: (d: EffectPredictionData) => (d.max_effect * 100).toFixed(1), unit: '%' },
              { label: '持续时间 (h)', getValue: (d: EffectPredictionData) => d.duration.toFixed(2), unit: 'h' },
              { label: 'AUC', getValue: (d: EffectPredictionData) => d.auc.toFixed(2) },
              {
                label: '最佳窗口',
                getValue: (d: EffectPredictionData) =>
                  `${d.optimal_window[0].toFixed(1)}-${d.optimal_window[1].toFixed(1)}`,
              },
            ].map(({ label, getValue, unit }) => (
              <tr key={label} className="hover:bg-neutral-50 dark:hover:bg-neutral-800">
                <td className="px-4 py-3 font-medium text-neutral-900 dark:text-white">{label}</td>
                {formulas
                  .filter((f) => selectedFormulas.includes(f.id))
                  .map((f) => (
                    <td key={f.id} className="px-4 py-3 text-right font-mono">
                      {getValue(f.data)}
                      {unit && <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] ml-1">{unit}</span>}
                    </td>
                  ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* 提示信息 */}
      {selectedFormulas.length === 0 && (
        <div className="text-center py-8 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
          <GitCompare className="w-12 h-12 mx-auto mb-3 opacity-30" />
          <p>请选择至少一个配方进行对比</p>
        </div>
      )}

      {selectedFormulas.length > 0 && selectedFormulas.length <= 4 && (
        <div className="mt-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          {formulas
            .filter((f) => selectedFormulas.includes(f.id))
            .map((f) => (
              <div key={f.id}>
                <EffectPredictionChart data={f.data} height={220} showConfidenceBand={false} />
              </div>
            ))}
        </div>
      )}
    </Card>
  );
}

