import { useState, useEffect, useRef, useMemo, useCallback } from 'react'
import { Search, X, Plus, Tag as TagIcon } from 'lucide-react'
import { cn } from '@/lib/utils'
import { tagApi } from '@/api/tag'
import { Input, Badge, Button } from '@/components/ui'
import type { Tag } from '@/types'

interface TagMultiSelectProps {
  value: number[]
  onChange: (ids: number[]) => void
  placeholder?: string
  maxHeight?: string
}

export function TagMultiSelect({
  value,
  onChange,
  placeholder = '选择标签',
  maxHeight = '320px',
}: TagMultiSelectProps) {
  const [open, setOpen] = useState(false)
  const [search, setSearch] = useState('')
  const [tags, setTags] = useState<Tag[]>([])
  const [loading, setLoading] = useState(false)
  const [creating, setCreating] = useState(false)
  const [creatingName, setCreatingName] = useState('')
  const dropdownRef = useRef<HTMLDivElement>(null)

  // 虚拟滚动相关状态
  const [scrollTop, setScrollTop] = useState(0)
  const containerRef = useRef<HTMLDivElement>(null)
  const ITEM_HEIGHT = 40 // 每个标签的高度

  useEffect(() => {
    if (open && tags.length === 0) {
      loadTags()
    }
  }, [open, tags.length])

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
        setOpen(false)
      }
    }
    if (open) {
      document.addEventListener('mousedown', handleClickOutside)
    }
    return () => {
      document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [open])

  const loadTags = async () => {
    setLoading(true)
    try {
      const data = await tagApi.list({ search: search || undefined })
      setTags(data)
    } catch {
      setTags([])
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    const timer = setTimeout(() => {
      if (open) {
        loadTags()
      }
    }, 300)
    return () => clearTimeout(timer)
  }, [search, open])

  const selectedTags = tags.filter((tag) => value.includes(tag.id))

  // 虚拟滚动相关计算
  const visibleItemCount = useMemo(() => {
    const containerHeight = parseInt(maxHeight) || 320
    return Math.ceil(containerHeight / ITEM_HEIGHT) + 2 // 额外渲染2个项目以避免空白
  }, [maxHeight])

  const startIndex = useMemo(() => {
    return Math.max(0, Math.floor(scrollTop / ITEM_HEIGHT) - 1) // 额外渲染1个项目以避免空白
  }, [scrollTop])

  const endIndex = useMemo(() => {
    return Math.min(tags.length, startIndex + visibleItemCount)
  }, [tags.length, startIndex, visibleItemCount])

  const visibleTags = useMemo(() => {
    return tags.slice(startIndex, endIndex)
  }, [tags, startIndex, endIndex])

  const handleScroll = useCallback((e: React.UIEvent<HTMLDivElement>) => {
    setScrollTop(e.currentTarget.scrollTop)
  }, [])

  const toggleTag = (id: number) => {
    if (value.includes(id)) {
      onChange(value.filter((v) => v !== id))
    } else {
      onChange([...value, id])
    }
  }

  const removeTag = (id: number) => {
    onChange(value.filter((v) => v !== id))
  }

  const handleCreateTag = async () => {
    const name = creatingName.trim()
    if (!name) return

    setCreating(true)
    try {
      const newTag = await tagApi.create({ name })
      setTags((prev) => [newTag, ...prev])
      onChange([...value, newTag.id])
      setCreatingName('')
      setCreating(false)
    } catch {
      setCreating(false)
    }
  }

  const getTagColor = (tag: Tag) => {
    if (tag.color) return tag.color
    const colors = ['primary', 'success', 'warning', 'info', 'neutral']
    const index = tag.name.charCodeAt(0) % colors.length
    return colors[index]
  }

  return (
    <div className="relative" ref={dropdownRef}>
      <button
        type="button"
        onClick={() => setOpen(!open)}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault()
            setOpen(!open)
          } else if (e.key === 'Escape' && open) {
            setOpen(false)
          }
        }}
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-labelledby="tag-select-label"
        aria-describedby="tag-select-desc"
        className={cn(
          'w-full min-h-[44px] px-3 py-1.5 rounded-lg border border-neutral-200 dark:border-neutral-700',
          'bg-white dark:bg-neutral-900 text-sm text-left',
          'hover:border-primary-400 dark:hover:border-primary-600 transition-colors',
          'flex flex-wrap gap-1.5 items-center',
          'focus:outline-none focus:ring-2 focus:ring-primary-500 focus:ring-offset-2',
        )}
      >
        <span id="tag-select-label" className="sr-only">选择标签</span>
        <span id="tag-select-desc" className="sr-only">
          {open ? '已打开标签选择下拉菜单' : '点击打开标签选择下拉菜单'}
        </span>
        {/* A-35：占位文案原为 neutral-400(#94a3b8)，白底仅 2.56:1。
            占位符同样承载信息，WCAG 对比度要求对它一视同仁。 */}
        {selectedTags.length === 0 ? (
          <span className="text-neutral-500 dark:text-neutral-400">{placeholder}</span>
        ) : (
          selectedTags.map((tag) => (
            <Badge
              key={tag.id}
              variant={getTagColor(tag) as 'primary' | 'success' | 'warning' | 'info' | 'neutral'}
              size="sm"
              className="gap-1"
            >
              {tag.icon && <span className="text-xs">{tag.icon}</span>}
              {tag.name}
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation()
                  removeTag(tag.id)
                }}
                className="hover:text-error-500 focus:outline-none focus:ring-2 focus:ring-error-500 focus:ring-offset-1 rounded"
                aria-label={`移除标签 ${tag.name}`}
              >
                <X size={10} />
              </button>
            </Badge>
          ))
        )}
      </button>

      {open && (
        <div
          className="absolute z-30 mt-1 w-full bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-700 rounded-xl shadow-xl overflow-hidden"
          role="listbox"
          aria-multiselectable="true"
          aria-label="标签选择列表"
          aria-activedescendant={selectedTags.length > 0 ? `tag-item-${selectedTags[0].id}` : undefined}
        >
          <div className="p-2 border-b border-neutral-100 dark:border-neutral-800">
            <Input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="搜索标签..."
              size="sm"
              prefix={<Search size={14} />}
              suffix={
                search && (
                  <button
                    type="button"
                    onClick={() => setSearch('')}
                    className="hover:text-error-500"
                    aria-label="清除搜索"
                  >
                    <X size={14} />
                  </button>
                )
              }
              className="w-full"
            />
          </div>

          <div
            ref={containerRef}
            className="overflow-y-auto"
            style={{ maxHeight }}
            onScroll={handleScroll}
          >
            {loading ? (
              <div className="p-4 text-center text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                <div className="w-4 h-4 border-2 border-primary-300 border-t-primary-600 rounded-full animate-spin mx-auto" />
              </div>
            ) : tags.length === 0 ? (
              <div className="p-4 text-center text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                {search ? '未找到匹配标签' : '暂无标签数据'}
              </div>
            ) : (
              <div style={{ height: `${tags.length * ITEM_HEIGHT}px`, position: 'relative' }}>
                <div style={{
                  position: 'absolute',
                  top: `${startIndex * ITEM_HEIGHT}px`,
                  width: '100%',
                }}>
                  {visibleTags.map((tag) => {
                    const isSelected = value.includes(tag.id)
                    const tagVariant = getTagColor(tag) as 'primary' | 'success' | 'warning' | 'info' | 'neutral'

                    return (
                      <div
                        key={tag.id}
                        id={`tag-item-${tag.id}`}
                        role="option"
                        aria-selected={isSelected}
                        aria-disabled={(tag.usageCount ?? 0) === 0}
                        onClick={() => toggleTag(tag.id)}
                        onKeyDown={(e) => {
                          if (e.key === 'Enter' || e.key === ' ') {
                            e.preventDefault()
                            toggleTag(tag.id)
                          } else if (e.key === 'Escape') {
                            setOpen(false)
                          }
                        }}
                        tabIndex={isSelected ? 0 : -1}
                        className={cn(
                          'flex items-center gap-2 px-3 py-2 text-sm cursor-pointer',
                          'hover:bg-neutral-50 dark:hover:bg-neutral-800',
                          isSelected && 'bg-primary-50 dark:bg-primary-300/20',
                        )}
                        style={{ height: `${ITEM_HEIGHT}px` }}
                      >
                        <span
                          className={cn(
                            'w-2 h-2 rounded-full',
                            tagVariant === 'primary' && 'bg-primary-500',
                            tagVariant === 'success' && 'bg-primary-500',
                            tagVariant === 'warning' && 'bg-warning-500',
                            tagVariant === 'info' && 'bg-info-500',
                            tagVariant === 'neutral' && 'bg-neutral-400',
                          )}
                        />
                        <TagIcon size={12} className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
                        <span
                          className={cn(
                            'flex-1 truncate',
                            isSelected
                              ? 'text-primary-700 dark:text-primary-700 font-medium'
                              : 'text-neutral-700 dark:text-neutral-300',
                          )}
                        >
                          {tag.name}
                        </span>
                        {isSelected && (
                          <span className="text-xs text-primary-500" aria-label="已选中">
                            ✓
                          </span>
                        )}
                        {(tag.usageCount ?? 0) > 0 && (
                          <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                            {(tag.usageCount ?? 0)}次
                          </span>
                        )}
                      </div>
                    )
                  })}
                </div>
              </div>
            )}

            {search && !tags.some((t) => t.name.toLowerCase() === search.toLowerCase()) && (
              <div className="p-2 border-t border-neutral-100 dark:border-neutral-800">
                <div className="flex items-center gap-2">
                  <Input
                    value={creatingName || search}
                    onChange={(e) => setCreatingName(e.target.value)}
                    placeholder="创建新标签"
                    size="sm"
                    className="flex-1"
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') {
                        e.preventDefault()
                        handleCreateTag()
                      }
                    }}
                  />
                  <Button
                    type="button"
                    size="sm"
                    variant="primary"
                    icon={<Plus size={14} />}
                    onClick={handleCreateTag}
                    loading={creating}
                  >
                    创建
                  </Button>
                </div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  )
}

/**
 * 模板编辑器 - 创建/编辑配方模板
 */
import { useState } from 'react';
import { X, Plus, Trash2 } from 'lucide-react';
import { Button, Input, Textarea } from '@/components/ui';
import { formulaApi } from '@/api/formula';
import { useToast } from '@/components/ui';

interface TemplateEditorProps {
  open: boolean;
  onClose: () => void;
  template?: any;
  onSuccess: () => void;
}

export function TemplateEditor({ open, onClose, template, onSuccess }: TemplateEditorProps) {
  const { addToast } = useToast();
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    code: '',
    name: '',
    description: '',
    category: '',
    effects: [] as string[],
    effectInput: '',
    is_featured: false,
  });

  if (!open) return null;

  const handleSubmit = async () => {
    if (!formData.code || !formData.name) {
      addToast({ type: 'error', message: '请填写模板代码和名称' });
      return;
    }
    setLoading(true);
    try {
      if (template) {
        await formulaApi.updateFormulaTemplate(template.code, formData);
        addToast({ type: 'success', message: '模板已更新' });
      } else {
        await formulaApi.createFormulaTemplate(formData);
        addToast({ type: 'success', message: '模板已创建' });
      }
      onSuccess();
      onClose();
    } catch (err) {
      addToast({ type: 'error', message: '操作失败' });
    } finally {
      setLoading(false);
    }
  };

  const addEffect = () => {
    if (formData.effectInput.trim() && !formData.effects.includes(formData.effectInput.trim())) {
      setFormData(prev => ({ ...prev, effects: [...prev.effects, prev.effectInput.trim()] }));
      setFormData(prev => ({ ...prev, effectInput: '' }));
    }
  };

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
      <div className="bg-white dark:bg-neutral-900 rounded-2xl w-full max-w-lg mx-4 max-h-[90vh] overflow-y-auto">
        <div className="p-6">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-lg font-semibold text-neutral-900 dark:text-white">
              {template ? '编辑模板' : '创建模板'}
            </h2>
            <button onClick={onClose} className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-neutral-600">
              <X size={20} />
            </button>
          </div>

          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-1.5">
                模板代码 <span className="text-error-500">*</span>
              </label>
              <Input
                value={formData.code}
                onChange={e => setFormData(prev => ({ ...prev, code: e.target.value }))}
                placeholder="如：immune-boost"
                disabled={!!template}
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-1.5">
                模板名称 <span className="text-error-500">*</span>
              </label>
              <Input
                value={formData.name}
                onChange={e => setFormData(prev => ({ ...prev, name: e.target.value }))}
                placeholder="如：增强免疫配方"
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-1.5">
                分类
              </label>
              <Input
                value={formData.category}
                onChange={e => setFormData(prev => ({ ...prev, category: e.target.value }))}
                placeholder="如：免疫力、睡眠、慢性病"
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-1.5">
                描述
              </label>
              <Textarea
                value={formData.description}
                onChange={e => setFormData(prev => ({ ...prev, description: e.target.value }))}
                placeholder="模板描述..."
                rows={3}
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-1.5">
                功效标签
              </label>
              <div className="flex gap-2">
                <Input
                  value={formData.effectInput}
                  onChange={e => setFormData(prev => ({ ...prev, effectInput: e.target.value }))}
                  onKeyDown={e => e.key === 'Enter' && (e.preventDefault(), addEffect())}
                  placeholder="输入功效后回车"
                />
                <Button variant="secondary" size="sm" icon={<Plus size={14} />} onClick={addEffect}>
                  添加
                </Button>
              </div>
              {formData.effects.length > 0 && (
                <div className="flex flex-wrap gap-1.5 mt-2">
                  {formData.effects.map((eff, idx) => (
                    <span key={idx} className="flex items-center gap-1 px-2 py-1 rounded-full bg-primary-100 dark:bg-primary-300/25 text-primary-700 dark:text-primary-700 text-xs">
                      {eff}
                      <button onClick={() => setFormData(prev => ({ ...prev, effects: prev.effects.filter((_, i) => i !== idx) }))}>
                        <X size={12} />
                      </button>
                    </span>
                  ))}
                </div>
              )}
            </div>

            <div className="flex items-center gap-2">
              <input
                type="checkbox"
                id="featured"
                checked={formData.is_featured}
                onChange={e => setFormData(prev => ({ ...prev, is_featured: e.target.checked }))}
                className="rounded"
              />
              <label htmlFor="featured" className="text-sm text-neutral-700 dark:text-neutral-300">
                设为推荐模板
              </label>
            </div>
          </div>
        </div>

        <div className="flex justify-end gap-2 p-6 border-t border-neutral-200 dark:border-neutral-700">
          <Button variant="secondary" onClick={onClose}>取消</Button>
          <Button variant="primary" onClick={handleSubmit} loading={loading}>
            {template ? '保存修改' : '创建模板'}
          </Button>
        </div>
      </div>
    </div>
  );
}

/**
 * 对话列表组件
 * 使用虚拟列表实现高性能渲染（支持1000+条数据）
 * 参考 VS Code 文件树设计
 */

import React, { useMemo, useCallback } from 'react'
import { useVirtualizer } from '@tanstack/react-virtual'
import {
  MessageSquare, FlaskConical, FileText, Search,
  Pin, Archive, MoreVertical, Clock,
} from 'lucide-react'
import { cn } from '@/lib/utils'
import type { Conversation } from './types'
import { format } from 'date-fns'
import { zhCN } from 'date-fns/locale'

interface ConversationListProps {
  conversations: Conversation[]
  selectedId: string | null
  onSelect: (conversation: Conversation) => void
  onDelete: (id: string) => void
  onArchive: (id: string) => void
  onPin: (id: string) => void
}

const iconMap: Record<string, React.ComponentType<{ size?: number; strokeWidth?: number }>> = {
  chat: MessageSquare,
  formula: FlaskConical,
  report: FileText,
  search: Search,
}

function ConversationItem({
  conversation,
  isSelected,
  onSelect,
  style,
}: {
  conversation: Conversation
  isSelected: boolean
  onSelect: () => void
  onDelete: () => void
  onArchive: () => void
  onPin: () => void
  style?: React.CSSProperties
}) {
  const Icon = iconMap[conversation.type] || MessageSquare

  const formatDate = (date: Date) => {
    const now = new Date()
    const diff = now.getTime() - date.getTime()

    // 小于1分钟
    if (diff < 60000) return '刚刚'
    // 小于1小时
    if (diff < 3600000) return `${Math.floor(diff / 60000)}分钟前`
    // 小于24小时
    if (diff < 86400000) return `${Math.floor(diff / 3600000)}小时前`
    // 今年
    if (date.getFullYear() === now.getFullYear()) {
      return format(date, 'M月d日', { locale: zhCN })
    }
    // 其他
    return format(date, 'yyyy年M月d日', { locale: zhCN })
  }

  return (
    <div
      style={style}
      className={cn(
        'relative flex items-start gap-3 p-2 rounded-lg cursor-pointer',
        'transition-all duration-150 select-none',
        'hover:bg-neutral-100 dark:hover:bg-neutral-800',
        isSelected && 'bg-primary/5 dark:bg-primary/10',
      )}
       role="button" tabIndex={0} onClick={onSelect}
      aria-selected={isSelected}
      aria-label={conversation.title}
    >
      {/* 状态指示 */}
      {isSelected && (
        <div
          className="absolute left-0 top-1/2 -translate-y-1/2 w-0.5 h-6 rounded-r"
          style={{ background: 'var(--color-primary)' }}
        />
      )}

      {/* 图标 */}
      <div
        className={cn(
          'flex-shrink-0 flex items-center justify-center rounded-md',
          isSelected ? 'bg-primary text-white' : 'bg-neutral-100 dark:bg-neutral-700',
        )}
        style={{ width: '32px', height: '32px' }}
      >
        <Icon size={16} strokeWidth={isSelected ? 2 : 1.5} />
      </div>

      {/* 内容区域 */}
      <div className="flex-1 min-w-0">
        <div className="flex items-center justify-between gap-2">
          <h3
            className={cn(
              'font-medium truncate',
              isSelected ? 'text-primary' : 'text-primary dark:text-white',
            )}
            style={{ fontSize: 'var(--text-body-sm)' }}
          >
            {conversation.title}
          </h3>
          {conversation.unreadCount > 0 && (
            <span
              className="flex-shrink-0 flex items-center justify-center min-w-[20px] h-[20px] rounded-full text-xs font-semibold px-1.5"
              style={{
                background: 'var(--color-primary)',
                color: 'white',
              }}
            >
              {conversation.unreadCount > 99 ? '99+' : conversation.unreadCount}
            </span>
          )}
        </div>

        <p
          className="truncate text-xs mt-0.5"
          style={{ color: 'var(--text-muted)' }}
        >
          {conversation.content}
        </p>

        <div className="flex items-center justify-between gap-2 mt-1.5">
          <div className="flex items-center gap-1.5">
            {/* 置顶标签 */}
            {conversation.status === 'pinned' && (
              <span className="flex items-center gap-0.5 text-xs" style={{ color: 'var(--color-warning)' }}>
                <Pin size={10} />
                置顶
              </span>
            )}
            {/* 归档标签 */}
            {conversation.status === 'archived' && (
              <span className="flex items-center gap-0.5 text-xs" style={{ color: 'var(--text-muted)' }}>
                <Archive size={10} />
                已归档
              </span>
            )}
            {/* 分类标签 */}
            <span
              className="text-xs px-1.5 py-0.5 rounded-full"
              style={{
                background: `${conversation.category.color}20`,
                color: conversation.category.color,
              }}
            >
              {conversation.category.name}
            </span>
          </div>

          {/* 更新时间 */}
          <span className="flex items-center gap-1 text-xs" style={{ color: 'var(--text-muted)' }}>
            <Clock size={10} />
            {formatDate(conversation.updatedAt)}
          </span>
        </div>
      </div>

      {/* 操作菜单 */}
      <div className="relative flex-shrink-0">
        <button
          onClick={(e) => {
            e.stopPropagation()
          }}
          className={cn(
            'p-1.5 rounded-md opacity-0 group-hover:opacity-100',
            'hover:bg-neutral-200 dark:hover:bg-neutral-700 transition-all',
          )}
          style={{ opacity: isSelected ? 1 : 0 }}
          aria-label="更多操作"
        >
          <MoreVertical size={14} />
        </button>
      </div>
    </div>
  )
}

export function ConversationList({
  conversations,
  selectedId,
  onSelect,
  onDelete,
  onArchive,
  onPin,
}: ConversationListProps) {
  const parentRef = React.useRef<HTMLDivElement>(null)

  const virtualizer = useVirtualizer({
    count: conversations.length,
    getScrollElement: () => parentRef.current,
    estimateSize: useCallback(() => 88, []),
    overscan: 5,
  })

  const pinnedConversations = useMemo(
    () => conversations.filter((c) => c.status === 'pinned'),
    [conversations],
  )

  const activeConversations = useMemo(
    () => conversations.filter((c) => c.status === 'active'),
    [conversations],
  )

  const archivedConversations = useMemo(
    () => conversations.filter((c) => c.status === 'archived'),
    [conversations],
  )

  const renderSection = (
    title: string,
    items: Conversation[],
    showHeader: boolean,
  ) => {
    if (items.length === 0) return null

    const startIndex = conversations.indexOf(items[0])
    const endIndex = startIndex + items.length

    return (
      <div key={title}>
        {showHeader && (
          <div className="px-3 py-2">
            <span
              className="text-xs font-semibold uppercase tracking-wider"
              style={{ color: 'var(--text-muted)' }}
            >
              {title} ({items.length})
            </span>
          </div>
        )}
        {virtualizer.getVirtualItems().map((virtualItem) => {
          if (virtualItem.index >= startIndex && virtualItem.index < endIndex) {
            const conversation = conversations[virtualItem.index]
            return (
              <ConversationItem
                key={conversation.id}
                conversation={conversation}
                isSelected={selectedId === conversation.id}
                onSelect={() => onSelect(conversation)}
                onDelete={() => onDelete(conversation.id)}
                onArchive={() => onArchive(conversation.id)}
                onPin={() => onPin(conversation.id)}
                style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  width: '100%',
                  transform: `translateY(${virtualItem.start}px)`,
                }}
              />
            )
          }
          return null
        })}
      </div>
    )
  }

  if (conversations.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-12 text-center">
        <div
          className="flex items-center justify-center w-16 h-16 rounded-full mb-4"
          style={{ background: 'var(--bg-surface-container-low)' }}
        >
          <MessageSquare size={24} style={{ color: 'var(--text-muted)' }} />
        </div>
        <p style={{ color: 'var(--text-secondary)', fontSize: 'var(--text-body-sm)' }}>
          暂无对话记录
        </p>
        <p style={{ color: 'var(--text-muted)', fontSize: 'var(--text-caption)' }}>
          开始新对话后会在这里显示
        </p>
      </div>
    )
  }

  return (
    <div
      ref={parentRef}
      className="relative overflow-y-auto"
      style={{
        height: '100%',
        minHeight: '200px',
      }}
    >
      {/* 虚拟列表容器 */}
      <div
        className="relative"
        style={{ height: `${virtualizer.getTotalSize()}px` }}
      >
        {renderSection('置顶', pinnedConversations, pinnedConversations.length > 0)}
        {renderSection('对话', activeConversations, pinnedConversations.length > 0 || activeConversations.length > 0)}
        {renderSection('归档', archivedConversations, archivedConversations.length > 0)}
      </div>
    </div>
  )
}

