/**
 * 历史记录侧边栏主组件
 * 参考 VS Code 侧边栏设计规范
 * 特性:
 * - 响应式适配（移动端可折叠）
 * - 虚拟列表高性能渲染
 * - 分类和标签筛选
 * - 搜索功能
 * - 平滑动画过渡
 */

import React, { useState, useMemo, useCallback, useEffect } from 'react'
import {
  History, ChevronLeft, ChevronRight, Filter,
  SlidersHorizontal, X, RefreshCw, Plus,
} from 'lucide-react'
import { cn } from '@/lib/utils'
import { useBreakpoint } from '@/hooks/useMobile'
import { SearchInput } from './SearchInput'
import { CategoryFilter } from './CategoryFilter'
import { TagFilter } from './TagFilter'
import { ConversationList } from './ConversationList'
import type { Conversation, FilterState, SidebarConfig, SidebarActions } from './types'

interface HistorySidebarProps {
  conversations: Conversation[]
  config?: Partial<SidebarConfig>
  actions?: Partial<SidebarActions>
  selectedConversationId?: string | null
}

const defaultConfig: SidebarConfig = {
  collapsible: true,
  defaultCollapsed: false,
  width: 280,
  collapsedWidth: 48,
  showTagFilter: true,
  showCategoryFilter: true,
  showSearch: true,
}

export function HistorySidebar({
  conversations,
  config: customConfig,
  actions,
  selectedConversationId,
}: HistorySidebarProps) {
  const config = { ...defaultConfig, ...customConfig }
  const { isMobile, isTablet, isDesktop } = useBreakpoint()

  // 折叠状态
  const [isCollapsed, setIsCollapsed] = useState(() => {
    if (isMobile) return config.defaultCollapsed
    return false
  })

  // 移动端抽屉状态
  const [isMobileOpen, setIsMobileOpen] = useState(false)

  // 筛选状态
  const [filterState, setFilterState] = useState<FilterState>({
    searchQuery: '',
    selectedCategory: null,
    selectedTags: [],
    statusFilter: 'all',
    sortBy: 'date',
    sortOrder: 'desc',
  })

  // 标签展开状态
  const [tagsExpanded, setTagsExpanded] = useState(false)

  // 处理折叠/展开
  const handleToggleCollapse = useCallback(() => {
    if (!config.collapsible) return
    setIsCollapsed((prev) => !prev)
  }, [config.collapsible])

  // 处理移动端抽屉
  const handleMobileToggle = useCallback(() => {
    setIsMobileOpen((prev) => !prev)
  }, [])

  // 搜索变化
  const handleSearchChange = useCallback((value: string) => {
    setFilterState((prev) => ({ ...prev, searchQuery: value }))
  }, [])

  // 分类选择
  const handleCategorySelect = useCallback((categoryId: string | null) => {
    setFilterState((prev) => ({ ...prev, selectedCategory: categoryId }))
  }, [])

  // 标签切换
  const handleTagToggle = useCallback((tagId: string) => {
    setFilterState((prev) => {
      const selectedTags = prev.selectedTags.includes(tagId)
        ? prev.selectedTags.filter((id) => id !== tagId)
        : [...prev.selectedTags, tagId]
      return { ...prev, selectedTags }
    })
  }, [])

  // 清除标签筛选
  const handleClearTags = useCallback(() => {
    setFilterState((prev) => ({ ...prev, selectedTags: [] }))
  }, [])

  // 清除所有筛选
  const handleClearFilters = useCallback(() => {
    setFilterState({
      searchQuery: '',
      selectedCategory: null,
      selectedTags: [],
      statusFilter: 'all',
      sortBy: 'date',
      sortOrder: 'desc',
    })
    actions?.onClearFilters?.()
  }, [actions])

  // 选择对话
  const handleSelectConversation = useCallback((conversation: Conversation) => {
    if (isMobile) {
      setIsMobileOpen(false)
    }
    actions?.onSelectConversation?.(conversation)
  }, [actions, isMobile])

  // 删除对话
  const handleDeleteConversation = useCallback((id: string) => {
    actions?.onDeleteConversation?.(id)
  }, [actions])

  // 归档对话
  const handleArchiveConversation = useCallback((id: string) => {
    actions?.onArchiveConversation?.(id)
  }, [actions])

  // 置顶对话
  const handlePinConversation = useCallback((id: string) => {
    actions?.onPinConversation?.(id)
  }, [actions])

  // 筛选和排序对话
  const filteredAndSortedConversations = useMemo(() => {
    let result = [...conversations]

    // 搜索过滤
    if (filterState.searchQuery) {
      const query = filterState.searchQuery.toLowerCase()
      result = result.filter(
        (c) =>
          c.title.toLowerCase().includes(query) ||
          c.content.toLowerCase().includes(query),
      )
    }

    // 分类过滤
    if (filterState.selectedCategory) {
      result = result.filter((c) => c.category.id === filterState.selectedCategory)
    }

    // 标签过滤（多选，必须包含所有选中的标签）
    if (filterState.selectedTags.length > 0) {
      result = result.filter((c) =>
        filterState.selectedTags.every((tagId) => c.tags.includes(tagId)),
      )
    }

    // 状态过滤
    if (filterState.statusFilter !== 'all') {
      result = result.filter((c) => c.status === filterState.statusFilter)
    }

    // 排序
    result.sort((a, b) => {
      let comparison = 0
      switch (filterState.sortBy) {
        case 'date':
          comparison = b.updatedAt.getTime() - a.updatedAt.getTime()
          break
        case 'title':
          comparison = a.title.localeCompare(b.title, 'zh-CN')
          break
        case 'unread':
          comparison = b.unreadCount - a.unreadCount
          break
      }
      return filterState.sortOrder === 'asc' ? comparison : -comparison
    })

    return result
  }, [conversations, filterState])

  // 是否有活跃筛选
  const hasActiveFilters = useMemo(() => {
    return (
      filterState.searchQuery !== '' ||
      filterState.selectedCategory !== null ||
      filterState.selectedTags.length > 0 ||
      filterState.statusFilter !== 'all'
    )
  }, [filterState])

  // 响应式：移动端自动切换
  useEffect(() => {
    if (isMobile) {
      setIsCollapsed(true)
    } else {
      setIsCollapsed(false)
    }
  }, [isMobile])

  const sidebarWidth = isCollapsed ? config.collapsedWidth : config.width

  return (
    <>
      {/* 移动端遮罩 */}
      {isMobile && isMobileOpen && (
        <div
          className="fixed inset-0 z-40 bg-black/50 backdrop-blur-sm"
           role="button" tabIndex={0} onClick={handleMobileToggle}
          aria-hidden={!isMobileOpen}
        />
      )}

      {/* 侧边栏主体 */}
      <aside
        className={cn(
          'flex flex-col transition-all duration-300 ease-out',
          'bg-surface-container border-r border-border',
          isMobile && isMobileOpen ? 'fixed inset-y-0 left-0 z-50 shadow-2xl' : '',
          isDesktop && !isCollapsed ? 'h-full' : '',
        )}
        style={{
          width: isMobile && isMobileOpen ? 'calc(100% - 64px)' : sidebarWidth,
          maxWidth: isMobile && isMobileOpen ? '320px' : undefined,
          background: 'var(--bg-surface-container)',
          borderRight: '1px solid var(--border-color)',
          boxShadow: isMobile && isMobileOpen ? 'var(--shadow-xl)' : undefined,
          flexShrink: 0,
        }}
        aria-label="历史记录"
      >
        {/* 头部区域 */}
        <div
          className="flex items-center justify-between px-3 py-3 border-b"
          style={{
            borderBottom: '1px solid var(--border-color)',
          }}
        >
          {/* 移动端关闭按钮 */}
          {isMobile && isMobileOpen && (
            <button
              onClick={handleMobileToggle}
              className="p-2 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-700 transition-colors"
              style={{ color: 'var(--text-muted)' }}
              aria-label="关闭侧边栏"
            >
              <X size={18} />
            </button>
          )}

          {/* 标题 */}
          <div className="flex items-center gap-2">
            <History size={18} style={{ color: 'var(--color-primary)' }} />
            {!isCollapsed && (
              <h2
                className="font-semibold"
                style={{
                  fontSize: 'var(--text-body)',
                  color: 'var(--text-primary)',
                }}
              >
                历史记录
                <span
                  className="ml-2 text-xs font-normal"
                  style={{ color: 'var(--text-muted)' }}
                >
                  ({conversations.length})
                </span>
              </h2>
            )}
          </div>

          {/* 操作按钮 */}
          <div className="flex items-center gap-1">
            {/* 清除筛选 */}
            {!isCollapsed && hasActiveFilters && (
              <button
                onClick={handleClearFilters}
                className="p-2 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-700 transition-colors"
                style={{ color: 'var(--text-muted)' }}
                aria-label="清除所有筛选"
                title="清除筛选"
              >
                <Filter size={14} />
              </button>
            )}

            {/* 折叠按钮 */}
            {config.collapsible && (
              <button
                onClick={isMobile ? handleMobileToggle : handleToggleCollapse}
                className="p-2 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-700 transition-colors"
                style={{ color: 'var(--text-muted)' }}
                aria-label={isCollapsed ? '展开侧边栏' : '折叠侧边栏'}
                title={isCollapsed ? '展开' : '折叠'}
              >
                {isCollapsed ? <ChevronRight size={16} /> : <ChevronLeft size={16} />}
              </button>
            )}
          </div>
        </div>

        {/* 折叠状态 - 仅显示图标 */}
        {isCollapsed && (
          <div className="flex flex-col items-center py-4 gap-4">
            <button
              onClick={handleToggleCollapse}
              className="p-3 rounded-xl hover:bg-primary/10 transition-colors"
              style={{ color: 'var(--color-primary)' }}
              aria-label="历史记录"
              title="历史记录"
            >
              <History size={20} />
            </button>
            <button
              className="p-3 rounded-xl hover:bg-neutral-100 dark:hover:bg-neutral-700 transition-colors"
              style={{ color: 'var(--text-muted)' }}
              aria-label="新建对话"
              title="新建对话"
            >
              <Plus size={20} />
            </button>
            <button
              className="p-3 rounded-xl hover:bg-neutral-100 dark:hover:bg-neutral-700 transition-colors"
              style={{ color: 'var(--text-muted)' }}
              aria-label="刷新"
              title="刷新"
            >
              <RefreshCw size={20} />
            </button>
          </div>
        )}

        {/* 展开状态 - 完整内容 */}
        {!isCollapsed && (
          <div className="flex flex-col h-[calc(100%-56px)]">
            {/* 筛选区域 */}
            <div className="p-3 space-y-3 border-b overflow-hidden">
              {/* 搜索 */}
              {config.showSearch && (
                <SearchInput
                  value={filterState.searchQuery}
                  onChange={handleSearchChange}
                  onClear={handleClearFilters}
                />
              )}

              {/* 分类筛选 */}
              {config.showCategoryFilter && (
                <CategoryFilter
                  categories={[
                    { id: 'all', name: '全部', icon: 'LayoutGrid', count: conversations.length, color: '#6B7280' },
                    { id: 'chat', name: 'AI 对话', icon: 'MessageSquare', count: conversations.filter((c) => c.type === 'chat').length, color: 'var(--color-primary-500)' },
                    { id: 'formula', name: '配方设计', icon: 'FlaskConical', count: conversations.filter((c) => c.type === 'formula').length, color: 'var(--color-secondary-500)' },
                    { id: 'report', name: '学术报告', icon: 'FileText', count: conversations.filter((c) => c.type === 'report').length, color: 'var(--color-accent-500)' },
                    { id: 'search', name: '检索记录', icon: 'Search', count: conversations.filter((c) => c.type === 'search').length, color: '#D97706' },
                  ]}
                  selectedCategory={filterState.selectedCategory}
                  onSelect={handleCategorySelect}
                />
              )}

              {/* 标签筛选 */}
              {config.showTagFilter && (
                <div className="space-y-2">
                  <button
                    onClick={() => setTagsExpanded((prev) => !prev)}
                    className="flex items-center justify-between w-full text-sm"
                    style={{ color: 'var(--text-secondary)' }}
                  >
                    <span className="flex items-center gap-2">
                      <SlidersHorizontal size={14} />
                      标签筛选
                      {filterState.selectedTags.length > 0 && (
                        <span
                          className="px-1.5 py-0.5 rounded text-xs font-medium"
                          style={{
                            background: 'var(--color-primary-container)',
                            color: 'var(--color-primary)',
                          }}
                        >
                          {filterState.selectedTags.length}
                        </span>
                      )}
                    </span>
                    <ChevronLeft
                      size={14}
                      className={`transition-transform duration-200 ${tagsExpanded ? 'rotate-90' : ''}`}
                    />
                  </button>
                  {tagsExpanded && (
                    <div className="pl-6">
                      <TagFilter
                        tags={[
                          { id: 't1', name: '营养配方', color: 'var(--color-primary-500)', count: conversations.filter((c) => c.tags.includes('t1')).length },
                          { id: 't2', name: '护肤配方', color: 'var(--color-secondary-500)', count: conversations.filter((c) => c.tags.includes('t2')).length },
                          { id: 't3', name: 'AI生成', color: 'var(--color-accent-500)', count: conversations.filter((c) => c.tags.includes('t3')).length },
                          { id: 't4', name: '待审核', color: '#D97706', count: conversations.filter((c) => c.tags.includes('t4')).length },
                          { id: 't5', name: '已完成', color: 'var(--color-primary-400)', count: conversations.filter((c) => c.tags.includes('t5')).length },
                          { id: 't6', name: '研究中', color: '#D946EF', count: conversations.filter((c) => c.tags.includes('t6')).length },
                          { id: 't7', name: '紧急', color: '#FF3B30', count: conversations.filter((c) => c.tags.includes('t7')).length },
                          { id: 't8', name: '客户需求', color: 'var(--color-info-600)', count: conversations.filter((c) => c.tags.includes('t8')).length },
                        ]}
                        selectedTags={filterState.selectedTags}
                        onToggle={handleTagToggle}
                        onClearAll={handleClearTags}
                      />
                    </div>
                  )}
                </div>
              )}
            </div>

            {/* 列表区域 */}
            <div className="flex-1 overflow-hidden">
              <ConversationList
                conversations={filteredAndSortedConversations}
                selectedId={selectedConversationId ?? null}
                onSelect={handleSelectConversation}
                onDelete={handleDeleteConversation}
                onArchive={handleArchiveConversation}
                onPin={handlePinConversation}
              />
            </div>

            {/* 底部操作栏 */}
            <div
              className="p-3 border-t flex items-center justify-between"
              style={{ borderTop: '1px solid var(--border-color)' }}
            >
              <button
                className="flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm font-medium transition-all"
                style={{
                  background: 'var(--color-primary)',
                  color: 'white',
                  boxShadow: '0 2px 8px rgba(var(--color-primary-rgb), 0.2)',
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.boxShadow = '0 4px 12px rgba(var(--color-primary-rgb), 0.3)'
                  e.currentTarget.style.transform = 'translateY(-1px)'
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.boxShadow = '0 2px 8px rgba(var(--color-primary-rgb), 0.2)'
                  e.currentTarget.style.transform = 'translateY(0)'
                }}
                aria-label="新建对话"
              >
                <Plus size={14} />
                新建对话
              </button>
              <button
                className="p-2 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-700 transition-colors"
                style={{ color: 'var(--text-muted)' }}
                aria-label="刷新列表"
              >
                <RefreshCw size={16} />
              </button>
            </div>
          </div>
        )}
      </aside>

      {/* 移动端触发按钮 */}
      {isMobile && !isMobileOpen && (
        <button
          onClick={handleMobileToggle}
          className="fixed bottom-6 right-6 z-30 p-3 rounded-full shadow-lg transition-all"
          style={{
            background: 'var(--color-primary)',
            color: 'white',
            boxShadow: '0 4px 16px rgba(var(--color-primary-rgb), 0.4)',
          }}
          aria-label="打开历史记录"
        >
          <History size={20} />
        </button>
      )}
    </>
  )
}

/**
 * ImportPanel — 数据导入面板
 *
 * 多步骤向导：上传 → 预览 → 字段映射 → 执行 → 结果
 */
'use client'

import { useCallback, useRef, useState } from 'react'
import { useImportEngine, type ImportStep } from '@/hooks/useImportEngine'
import type { ImportProgress } from '@/hooks/useImportEngine'
import type { FieldMappingConfig } from '@/api/import'

// ── Step indicators ──────────────────────────────────────────────

const STEPS = [
  { key: 'upload', label: '上传文件', icon: '📁' },
  { key: 'preview', label: '数据预览', icon: '👁️' },
  { key: 'mapping', label: '字段映射', icon: '🔗' },
  { key: 'running', label: '导入中', icon: '⚙️' },
  { key: 'done', label: '完成', icon: '✅' },
] as const

function StepIndicator({ currentStep }: { currentStep: ImportStep }) {
  const currentIndex = STEPS.findIndex(s => s.key === currentStep)

  return (
    <div className="flex items-center gap-1 mb-6">
      {STEPS.map((s, i) => {
        const isActive = s.key === currentStep
        const isDone = i < currentIndex
        return (
          <div key={s.key} className="flex items-center gap-1">
            <div
              className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold transition-colors ${
                isActive
                  ? 'bg-warning-500 text-white shadow-md shadow-warning-200 dark:shadow-warning-900/30'
                  : isDone
                    ? 'bg-success-500 text-white'
                    : 'bg-neutral-100 dark:bg-neutral-700 text-neutral-400'
              }`}
            >
              {isDone ? '✓' : s.icon}
            </div>
            <span className={`text-xs hidden sm:block ${isActive ? 'text-warning-600 dark:text-warning-700 font-semibold' : 'text-neutral-400'}`}>
              {s.label}
            </span>
            {i < STEPS.length - 1 && (
              <div className={`w-4 h-0.5 mx-1 ${isDone ? 'bg-success-500' : 'bg-neutral-200 dark:bg-neutral-600'}`} />
            )}
          </div>
        )
      })}
    </div>
  )
}

// ── Upload Step ──────────────────────────────────────────────────

function UploadStep({
  file,
  onFileSelect,
  onUpload,
}: {
  file: File | null
  onFileSelect: (f: File | null) => void
  onUpload: () => void
}) {
  const inputRef = useRef<HTMLInputElement>(null)
  const [dragOver, setDragOver] = useState(false)
  const [delimiter, setDelimiter] = useState('auto')
  const [fileType, setFileType] = useState('csv')

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    setDragOver(false)
    const f = e.dataTransfer.files[0]
    if (f) onFileSelect(f)
  }, [onFileSelect])

  const handleFileChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const f = e.target.files?.[0]
    if (f) onFileSelect(f)
  }, [onFileSelect])

  const handleUpload = useCallback(() => {
    if (file) onUpload()
  }, [file, onUpload])

  return (
    <div className="space-y-4">
      {/* Drop zone */}
      <div
        onDragOver={(e) => { e.preventDefault(); setDragOver(true) }}
        onDragLeave={() => setDragOver(false)}
        onDrop={handleDrop}
        onClick={() => inputRef.current?.click()}
        className={`relative border-2 border-dashed rounded-xl p-8 text-center cursor-pointer transition-all ${
          dragOver
            ? 'border-warning-400 bg-warning-50 dark:bg-warning-300/15 scale-[1.02]'
            : 'border-neutral-200 dark:border-neutral-600 hover:border-warning-300 dark:hover:border-warning-700'
        }`}
      >
        <input ref={inputRef} type="file" accept=".csv,.tsv,.json,.jsonl" className="hidden" onChange={handleFileChange} aria-hidden="true" tabIndex={-1} />
        <div className="text-3xl mb-2">{dragOver ? '📂' : '📥'}</div>
        <p className="text-sm text-neutral-600 dark:text-neutral-300 font-medium">
          {dragOver ? '松开文件开始上传' : '拖拽文件到此处，或点击选择'}
        </p>
        <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">支持 CSV、TSV、JSON、JSONL</p>
      </div>

      {/* File info */}
      {file && (
        <div className="bg-neutral-50 dark:bg-neutral-800 rounded-lg px-3 py-2 flex items-center gap-2">
          <span className="text-sm">📄</span>
          <div className="flex-1 min-w-0">
            <p className="text-xs font-medium truncate">{file.name}</p>
            <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{(file.size / 1024).toFixed(1)} KB</p>
          </div>
          <button
            onClick={(e) => { e.stopPropagation(); onFileSelect(null) }}
            className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-error-500 text-xs"
          >
            ✕
          </button>
        </div>
      )}

      {/* Config */}
      {file && (
        <div className="flex gap-3">
          <select
            value={fileType}
            onChange={e => setFileType(e.target.value)}
            className="flex-1 text-xs rounded-lg border border-neutral-200 dark:border-neutral-600 bg-white dark:bg-neutral-800 px-2 py-1.5"
          >
            <option value="csv">CSV / TSV</option>
            <option value="json">JSON / JSONL</option>
          </select>
          {fileType === 'csv' && (
            <select
              value={delimiter}
              onChange={e => setDelimiter(e.target.value)}
              className="flex-1 text-xs rounded-lg border border-neutral-200 dark:border-neutral-600 bg-white dark:bg-neutral-800 px-2 py-1.5"
            >
              <option value="auto">自动检测分隔符</option>
              <option value=",">逗号 (,)</option>
              <option value="\t">制表符 (Tab)</option>
              <option value=";">分号 (;)</option>
            </select>
          )}
        </div>
      )}

      {/* Upload button */}
      <button
        onClick={handleUpload}
        disabled={!file}
        className="w-full py-2.5 rounded-xl bg-gradient-to-r from-[var(--color-warning-surface)] to-[var(--color-warning-surface-deep)] text-white font-semibold text-sm disabled:opacity-40 disabled:cursor-not-allowed hover:from-[var(--color-warning-surface-deep)] hover:to-[var(--color-warning-surface-deep)] transition-all shadow-md shadow-warning-200 dark:shadow-warning-900/20"
      >
        上传并继续
      </button>
    </div>
  )
}

// ── Preview Step ─────────────────────────────────────────────────

function PreviewStep({ data, totalRows }: { data: Record<string, unknown>[]; totalRows: number }) {
  if (!data.length) return <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] text-center py-4">暂无预览数据</p>

  const columns = Object.keys(data[0]).slice(0, 8)

  return (
    <div className="space-y-2">
      <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">共 {totalRows.toLocaleString()} 行，显示前 {Math.min(data.length, 10)} 行</p>
      <div className="overflow-auto max-h-[280px] custom-scrollbar rounded-lg border border-neutral-200 dark:border-neutral-700">
        <table className="w-full text-xs">
          <thead className="bg-neutral-50 dark:bg-neutral-700/50 sticky top-0 z-10">
            <tr>{columns.map(c => (
              <th key={c} className="px-2 py-1.5 text-left font-semibold text-neutral-500 border-b border-neutral-200 dark:border-neutral-600 whitespace-nowrap">{c}</th>
            ))}</tr>
          </thead>
          <tbody>
            {data.slice(0, 10).map((row, i) => (
              <tr key={i} className="hover:bg-neutral-50 dark:hover:bg-neutral-700/20">
                {columns.map(c => (
                  <td key={c} className="px-2 py-1 text-neutral-600 dark:text-neutral-400 border-b border-neutral-100 dark:border-neutral-700/30 truncate max-w-[140px]">
                    {String(row[c] ?? '').slice(0, 40)}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  )
}

// ── Mapping Step ─────────────────────────────────────────────────

function MappingStep({
  columns,
  targetTable,
  idField,
  mappings,
  onTargetChange,
  onIdFieldChange,
  onMappingsChange,
}: {
  columns: string[]
  targetTable: string
  idField: string
  mappings: FieldMappingConfig[]
  onTargetChange: (t: string) => void
  onIdFieldChange: (f: string) => void
  onMappingsChange: (m: FieldMappingConfig[]) => void
}) {
  // Available target columns for the target table
  const TARGET_COLUMNS = [
    'external_id', 'sku', 'brand', 'product_name', 'product_line',
    'category', 'sub_category', 'formulation_type',
    'effects', 'target_population',
    'full_ingredients', 'key_ingredients',
    'price', 'currency', 'package_size',
    'volume_ml', 'weight_g',
    'sales_channels', 'image_urls',
    'allergens_tags', 'additives_tags', 'traces_tags',
    'source', 'data_quality',
  ]

  const addMapping = () => {
    onMappingsChange([...mappings, { source: '', target: '' }])
  }

  const updateMapping = (idx: number, field: keyof FieldMappingConfig, value: string | boolean | undefined) => {
    const next = [...mappings]
    next[idx] = { ...next[idx], [field]: value }
    onMappingsChange(next)
  }

  const removeMapping = (idx: number) => {
    onMappingsChange(mappings.filter((_, i) => i !== idx))
  }

  return (
    <div className="space-y-4">
      {/* Target config */}
      <div className="grid grid-cols-2 gap-3">
        <div>
          <label className="block text-xs font-semibold text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">目标表</label>
          <select
            value={targetTable}
            onChange={e => onTargetChange(e.target.value)}
            className="w-full text-xs rounded-lg border border-neutral-200 dark:border-neutral-600 bg-white dark:bg-neutral-800 px-2 py-1.5"
          >
            <option value="retail_products">retail_products (零售产品)</option>
            <option value="food_materials">food_materials (食品原料)</option>
          </select>
        </div>
        <div>
          <label className="block text-xs font-semibold text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">唯一标识字段</label>
          <select
            value={idField}
            onChange={e => onIdFieldChange(e.target.value)}
            className="w-full text-xs rounded-lg border border-neutral-200 dark:border-neutral-600 bg-white dark:bg-neutral-800 px-2 py-1.5"
          >
            {columns.map(c => <option key={c} value={c}>{c}</option>)}
          </select>
        </div>
      </div>

      {/* Mapping rules */}
      <div className="space-y-2">
        <div className="flex items-center justify-between">
          <label className="text-xs font-semibold text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">字段映射规则</label>
          <button onClick={addMapping} className="text-xs text-warning-500 hover:text-warning-600 font-medium">+ 添加映射</button>
        </div>

        {mappings.map((m, i) => (
          <div key={i} className="flex items-center gap-2">
            <select
              value={m.source}
              onChange={e => updateMapping(i, 'source', e.target.value)}
              className="flex-1 text-xs rounded border border-neutral-200 dark:border-neutral-600 bg-white dark:bg-neutral-800 px-1.5 py-1"
            >
              <option value="">— 源列 —</option>
              {columns.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
            <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">→</span>
            <select
              value={m.target}
              onChange={e => updateMapping(i, 'target', e.target.value)}
              className="flex-1 text-xs rounded border border-neutral-200 dark:border-neutral-600 bg-white dark:bg-neutral-800 px-1.5 py-1"
            >
              <option value="">— 目标字段 —</option>
              {TARGET_COLUMNS.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
            <button onClick={() => removeMapping(i)} className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-error-400 text-xs">✕</button>
          </div>
        ))}

        {!mappings.length && (
          <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] text-center py-2">添加映射规则以将源列映射到目标字段</p>
        )}
      </div>
    </div>
  )
}

// ── Progress Step ────────────────────────────────────────────────

function ProgressStep({ progress, errorMessage }: { progress: ImportProgress | null; errorMessage: string | null }) {
  if (!progress) return null

  return (
    <div className="space-y-4">
      {/* Progress bar */}
      <div className="space-y-1">
        <div className="flex justify-between text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
          <span>处理进度</span>
          <span>{progress.progressPct.toFixed(1)}%</span>
        </div>
        <div className="h-2 bg-neutral-100 dark:bg-neutral-700 rounded-full overflow-hidden">
          <div
            className="h-full rounded-full bg-gradient-to-r from-warning-400 to-warning-400 transition-all duration-500"
            style={{ width: `${progress.progressPct}%` }}
          />
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-3 gap-2">
        <StatCard label="总行数" value={progress.totalRows.toLocaleString()} color="neutral" />
        <StatCard label="成功" value={(progress.insertedRows + progress.updatedRows).toLocaleString()} color="green" />
        <StatCard label="错误" value={progress.errorRows.toLocaleString()} color={progress.errorRows > 0 ? 'red' : 'green'} />
      </div>

      {/* Error message */}
      {errorMessage && (
        <div className="bg-error-50 dark:bg-error-300/20 rounded-lg px-3 py-2 text-xs text-error-600 dark:text-error-700">
          {errorMessage}
        </div>
      )}
    </div>
  )
}

function StatCard({ label, value, color }: { label: string; value: string; color: string }) {
  const colors: Record<string, string> = {
    neutral: 'bg-neutral-50 dark:bg-neutral-800 text-neutral-600 dark:text-neutral-300',
    green: 'bg-success-50 dark:bg-success-300/20 text-success-600 dark:text-success-700',
    red: 'bg-error-50 dark:bg-error-300/20 text-error-600 dark:text-error-700',
  }
  return (
    <div className={`rounded-lg px-3 py-2 text-center ${colors[color] || colors.neutral}`}>
      <div className="text-lg font-bold">{value}</div>
      <div className="text-xs opacity-70">{label}</div>
    </div>
  )
}

// ── Main Component ───────────────────────────────────────────────

export function ImportPanel({ onClose }: { onClose: () => void }) {
  const {
    step, task, uploadResponse, previewData, progress, file, errorMessage,
    setFile, uploadFile, fetchPreview, runImport, refreshTask, clear, goToStep,
  } = useImportEngine()

  // Local state for mapping UI
  const [targetTable, setTargetTable] = useState('retail_products')
  const [idField, setIdField] = useState('external_id')
  const [mappings, setMappings] = useState<FieldMappingConfig[]>([])
  const [delimiter] = useState('auto')
  const [fileType] = useState('csv')

  // Polling for running imports
  const pollingRef = useRef<any>(null)

  // Start polling when running
  if (step === 'running' && uploadResponse?.task_id) {
    // eslint-disable-next-line react-hooks/refs
    if (!pollingRef.current) {
      pollingRef.current = setInterval(async () => {
        await refreshTask()
      }, 2000)
    }
  }

  // Cleanup polling
  // eslint-disable-next-line react-hooks/refs
  if (step !== 'running' && pollingRef.current) {
    // eslint-disable-next-line react-hooks/refs
    clearInterval(pollingRef.current)
    // eslint-disable-next-line react-hooks/refs
    pollingRef.current = null
  }

  const handleUpload = useCallback(() => {
    uploadFile(fileType, delimiter)
  }, [fileType, delimiter, uploadFile])

  const handleRun = useCallback(() => {
    if (mappings.length === 0) return
    runImport(targetTable, idField, mappings)
  }, [targetTable, idField, mappings, runImport])

  // Derive columns from preview data
  const columns = previewData?.length ? Object.keys(previewData[0]) : []

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm p-4"  role="button" tabIndex={0} onClick={(e) => { if (e.target === e.currentTarget) onClose() }}>
      <div className="bg-white dark:bg-neutral-800 rounded-2xl shadow-2xl w-full max-w-[560px] max-h-[90vh] overflow-hidden flex flex-col animate-fade-in">
        {/* Header */}
        <div className="flex items-center justify-between px-5 py-3 bg-gradient-to-r from-warning-50 to-warning-50 dark:from-warning-950/50 dark:to-warning-950/50 border-b border-warning-100/50 dark:border-warning-900/30 shrink-0">
          <div className="flex items-center gap-2">
            <span className="text-lg">📥</span>
            <span className="text-sm font-bold text-warning-700 dark:text-warning-700">数据导入向导</span>
          </div>
          <button onClick={onClose} className="w-6 h-6 rounded flex items-center justify-center hover:bg-warning-100 dark:hover:bg-warning-800/30 text-neutral-400 transition-colors">✕</button>
        </div>

        {/* Body */}
        <div className="flex-1 overflow-y-auto p-5 custom-scrollbar">
          <StepIndicator currentStep={step} />

          {step === 'upload' && (
            <UploadStep
              file={file}
              onFileSelect={setFile}
              onUpload={handleUpload}
            />
          )}

          {step === 'preview' && uploadResponse && (
            <div className="space-y-4">
              <PreviewStep data={previewData || []} totalRows={task?.total_rows || 0} />
              <div className="flex gap-2">
                <button
                  onClick={() => fetchPreview(10)}
                  className="flex-1 py-2 rounded-lg bg-neutral-100 dark:bg-neutral-700 text-xs font-medium hover:bg-neutral-200 dark:hover:bg-neutral-600 transition-colors"
                >
                  🔄 刷新预览
                </button>
                <button
                  onClick={() => goToStep('mapping')}
                  disabled={!previewData?.length}
                  className="flex-1 py-2 rounded-lg bg-gradient-to-r from-[var(--color-warning-surface)] to-[var(--color-warning-surface-deep)] text-white text-xs font-semibold disabled:opacity-40 hover:from-[var(--color-warning-surface-deep)] hover:to-[var(--color-warning-surface-deep)] transition-all"
                >
                  下一步 → 字段映射
                </button>
              </div>
            </div>
          )}

          {step === 'mapping' && (
            <div className="space-y-4">
              <MappingStep
                columns={columns}
                targetTable={targetTable}
                idField={idField}
                mappings={mappings}
                onTargetChange={setTargetTable}
                onIdFieldChange={setIdField}
                onMappingsChange={setMappings}
              />
              <div className="flex gap-2">
                <button
                  onClick={() => goToStep('preview')}
                  className="flex-1 py-2 rounded-lg bg-neutral-100 dark:bg-neutral-700 text-xs font-medium hover:bg-neutral-200 dark:hover:bg-neutral-600 transition-colors"
                >
                  ← 上一步
                </button>
                <button
                  onClick={handleRun}
                  disabled={mappings.length === 0}
                  className="flex-1 py-2 rounded-lg bg-gradient-to-r from-[var(--color-warning-surface)] to-[var(--color-warning-surface-deep)] text-white text-xs font-semibold disabled:opacity-40 hover:from-[var(--color-warning-surface-deep)] hover:to-[var(--color-warning-surface-deep)] transition-all"
                >
                  🚀 开始导入
                </button>
              </div>
            </div>
          )}

          {(step === 'running' || step === 'done' || step === 'error') && (
            <ProgressStep progress={progress} errorMessage={errorMessage} />
          )}
        </div>

        {/* Footer */}
        {step !== 'idle' && step !== 'running' && (
          <div className="px-5 py-3 border-t border-neutral-100 dark:border-neutral-700 flex gap-2 shrink-0">
            {(step === 'preview' || step === 'mapping') && (
              <button
                onClick={() => goToStep(step === 'preview' ? 'upload' : 'preview')}
                className="flex-1 py-2 rounded-lg bg-neutral-100 dark:bg-neutral-700 text-xs font-medium hover:bg-neutral-200 dark:hover:bg-neutral-600 transition-colors"
              >
                ← 返回
              </button>
            )}
            {(step === 'done' || step === 'error') && (
              <button
                onClick={clear}
                className="flex-1 py-2 rounded-lg bg-gradient-to-r from-[var(--color-warning-surface)] to-[var(--color-warning-surface-deep)] text-white text-xs font-semibold hover:from-[var(--color-warning-surface-deep)] hover:to-[var(--color-warning-surface-deep)] transition-all"
              >
                关闭
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  )
}

import { useState, useCallback, useMemo, useRef, useEffect } from 'react';
import {
  ChevronLeft, ChevronRight, SkipBack, SkipForward,
  ChevronDown, ChevronUp, Search, Filter,
  Lightbulb, Cog, Eye, FileText, Clock, CheckCircle, XCircle,
  Hash, BarChart3,
} from 'lucide-react';
import { clsx } from 'clsx';
import type {
  InferenceChain,
  InferenceStep,
  InferenceChainStats,
  FilterOptions,
} from '@/types/inference';
import {
  InferenceStepType,
  InferenceStepStatus,
} from '@/types/inference';
import InferenceStepCard from './InferenceStepCard';

interface InferenceChainVisualizerProps {
  chain: InferenceChain;
  autoScrollToActive?: boolean;
}

export default function InferenceChainVisualizer({ chain, autoScrollToActive = true }: InferenceChainVisualizerProps) {
  const [expandedSteps, setExpandedSteps] = useState<Set<string>>(new Set());
  const [currentStepIndex, setCurrentStepIndex] = useState<number>(0);
  const [searchQuery, setSearchQuery] = useState('');
  const [showFilter, setShowFilter] = useState(false);
  const [filterOptions, setFilterOptions] = useState<FilterOptions>({
    stepTypes: Object.values(InferenceStepType),
    statuses: Object.values(InferenceStepStatus),
    searchQuery: '',
  });

  const stepsContainerRef = useRef<HTMLDivElement>(null);

  // 计算统计信息
  const stats: InferenceChainStats = useMemo(() => {
    const steps = chain.steps;
    const executionTimes = steps.filter(s => s.executionTime !== undefined).map(s => s.executionTime!);

    return {
      totalSteps: steps.length,
      thoughtCount: steps.filter(s => s.type === InferenceStepType.THOUGHT).length,
      actionCount: steps.filter(s => s.type === InferenceStepType.ACTION).length,
      observationCount: steps.filter(s => s.type === InferenceStepType.OBSERVATION).length,
      successCount: steps.filter(s => s.status === InferenceStepStatus.SUCCESS).length,
      failedCount: steps.filter(s => s.status === InferenceStepStatus.FAILED).length,
      totalExecutionTime: steps.reduce((sum, s) => sum + (s.executionTime || 0), 0),
      avgStepTime: executionTimes.length > 0
        ? Math.round(executionTimes.reduce((a, b) => a + b, 0) / executionTimes.length)
        : 0,
      maxStepTime: executionTimes.length > 0 ? Math.max(...executionTimes) : 0,
      minStepTime: executionTimes.length > 0 ? Math.min(...executionTimes) : 0,
    };
  }, [chain.steps]);

  // 过滤步骤
  const filteredSteps = useMemo(() => {
    return chain.steps.filter(step => {
      // 类型过滤
      if (!filterOptions.stepTypes.includes(step.type)) return false;
      // 状态过滤
      if (!filterOptions.statuses.includes(step.status)) return false;
      // 搜索过滤
      const searchLower = filterOptions.searchQuery.toLowerCase();
      if (searchLower) {
        const matchesTitle = step.title.toLowerCase().includes(searchLower);
        const matchesContent = step.content.toLowerCase().includes(searchLower);
        return matchesTitle || matchesContent;
      }
      return true;
    });
  }, [chain.steps, filterOptions]);

  // 切换步骤展开状态
  const handleToggleExpand = useCallback((stepId: string) => {
    setExpandedSteps(prev => {
      const newSet = new Set(prev);
      if (newSet.has(stepId)) {
        newSet.delete(stepId);
      } else {
        newSet.add(stepId);
      }
      return newSet;
    });
  }, []);

  // 展开所有步骤
  const handleExpandAll = useCallback(() => {
    const allStepIds = new Set(chain.steps.map(s => s.id));
    setExpandedSteps(allStepIds);
  }, [chain.steps]);

  // 折叠所有步骤
  const handleCollapseAll = useCallback(() => {
    setExpandedSteps(new Set());
  }, []);

  // 导航到特定步骤
  const handleNavigateTo = useCallback((stepIndex: number) => {
    if (stepIndex >= 0 && stepIndex < filteredSteps.length) {
      setCurrentStepIndex(stepIndex);
    }
  }, [filteredSteps.length]);

  // 上一步
  const handlePrevStep = useCallback(() => {
    if (currentStepIndex > 0) {
      handleNavigateTo(currentStepIndex - 1);
    }
  }, [currentStepIndex, handleNavigateTo]);

  // 下一步
  const handleNextStep = useCallback(() => {
    if (currentStepIndex < filteredSteps.length - 1) {
      handleNavigateTo(currentStepIndex + 1);
    }
  }, [currentStepIndex, filteredSteps.length, handleNavigateTo]);

  // 跳转到第一步
  const handleFirstStep = useCallback(() => {
    handleNavigateTo(0);
  }, [handleNavigateTo]);

  // 跳转到最后一步
  const handleLastStep = useCallback(() => {
    handleNavigateTo(filteredSteps.length - 1);
  }, [filteredSteps.length, handleNavigateTo]);

  // 步骤点击处理
  const handleStepClick = useCallback((stepId: string) => {
    const index = filteredSteps.findIndex(s => s.id === stepId);
    if (index !== -1) {
      setCurrentStepIndex(index);
    }
  }, [filteredSteps]);

  // 自动滚动到当前激活步骤
  useEffect(() => {
    if (autoScrollToActive && stepsContainerRef.current) {
      const activeStep = stepsContainerRef.current.querySelector('[data-active="true"]');
      if (activeStep) {
        activeStep.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
    }
  }, [currentStepIndex, autoScrollToActive]);

  // 搜索同步
  useEffect(() => {
    setFilterOptions(prev => ({ ...prev, searchQuery }));
  }, [searchQuery]);

  // 获取当前步骤
  const currentStep: InferenceStep | undefined = filteredSteps[currentStepIndex];

  return (
    <div className="flex flex-col h-full bg-white dark:bg-neutral-900 rounded-xl border border-neutral-200 overflow-hidden">
      {/* 头部 */}
      <div className="px-6 py-4 border-b border-neutral-200 dark:border-neutral-700 bg-gradient-to-r from-neutral-50 to-white">
        <div className="flex items-center justify-between">
          <div>
            <h2 className="text-lg font-semibold text-neutral-900">{chain.title}</h2>
            {chain.description && (
              <p className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">{chain.description}</p>
            )}
          </div>
          <div className="flex items-center gap-2">
            <span className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
              步骤: {filteredSteps.length}/{chain.steps.length}
            </span>
          </div>
        </div>
      </div>

      {/* 统计信息栏 */}
      <div className="px-6 py-3 bg-neutral-50 dark:bg-neutral-800 border-b border-neutral-200">
        <div className="flex flex-wrap items-center gap-4">
          <StatItem icon={Hash} label="总步骤" value={stats.totalSteps} />
          <StatItem icon={Lightbulb} label="思考" value={stats.thoughtCount} color="text-warning-600" />
          <StatItem icon={Cog} label="行动" value={stats.actionCount} color="text-secondary-600" />
          <StatItem icon={Eye} label="观察" value={stats.observationCount} color="text-success-600" />
          <StatItem icon={CheckCircle} label="成功" value={stats.successCount} color="text-success-500" />
          <StatItem icon={XCircle} label="失败" value={stats.failedCount} color="text-error-500" />
          <StatItem icon={Clock} label="总耗时" value={`${stats.totalExecutionTime}ms`} />
        </div>
      </div>

      {/* 工具栏 */}
      <div className="px-6 py-3 border-b border-neutral-100 flex items-center justify-between">
        {/* 导航控制 */}
        <div className="flex items-center gap-2">
          <button
            onClick={handleFirstStep}
            disabled={currentStepIndex === 0}
            className="nav-btn"
            title="跳转到第一步"
          >
            <SkipBack className="w-4 h-4" />
          </button>
          <button
            onClick={handlePrevStep}
            disabled={currentStepIndex === 0}
            className="nav-btn"
            title="上一步"
          >
            <ChevronLeft className="w-4 h-4" />
          </button>
          <span className="px-3 py-1 bg-neutral-100 dark:bg-neutral-800 rounded-full text-sm font-medium text-neutral-700 min-w-[80px] text-center">
            {currentStepIndex + 1} / {filteredSteps.length}
          </span>
          <button
            onClick={handleNextStep}
            disabled={currentStepIndex === filteredSteps.length - 1}
            className="nav-btn"
            title="下一步"
          >
            <ChevronRight className="w-4 h-4" />
          </button>
          <button
            onClick={handleLastStep}
            disabled={currentStepIndex === filteredSteps.length - 1}
            className="nav-btn"
            title="跳转到最后一步"
          >
            <SkipForward className="w-4 h-4" />
          </button>
        </div>

        {/* 操作按钮 */}
        <div className="flex items-center gap-2">
          {/* 搜索框 */}
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
            <input
              type="text"
              placeholder="搜索步骤..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-9 pr-4 py-1.5 text-sm border border-neutral-200 dark:border-neutral-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-secondary-500 focus:border-transparent w-64"
            />
          </div>

          {/* 过滤器 */}
          <button
            onClick={() => setShowFilter(!showFilter)}
            className={clsx(
              'flex items-center gap-1.5 px-3 py-1.5 text-sm rounded-lg border transition-colors',
              showFilter
                ? 'bg-secondary-50 border-secondary-300 text-secondary-700'
                : 'border-neutral-200 text-neutral-600 hover:bg-neutral-50 dark:bg-neutral-800',
            )}
          >
            <Filter className="w-4 h-4" />
            过滤
          </button>

          {/* 展开/折叠按钮 */}
          <button
            onClick={handleExpandAll}
            className="flex items-center gap-1.5 px-3 py-1.5 text-sm border border-neutral-200 rounded-lg text-neutral-600 hover:bg-neutral-50 dark:bg-neutral-800 transition-colors"
          >
            <ChevronDown className="w-4 h-4" />
            展开全部
          </button>
          <button
            onClick={handleCollapseAll}
            className="flex items-center gap-1.5 px-3 py-1.5 text-sm border border-neutral-200 rounded-lg text-neutral-600 hover:bg-neutral-50 dark:bg-neutral-800 transition-colors"
          >
            <ChevronUp className="w-4 h-4" />
            折叠全部
          </button>
        </div>
      </div>

      {/* 过滤器面板 */}
      {showFilter && (
        <div className="px-6 py-3 bg-neutral-50 dark:bg-neutral-800 border-b border-neutral-200">
          <div className="flex flex-wrap gap-6">
            {/* 类型过滤 */}
            <div>
              <label className="text-xs font-medium text-neutral-600 mb-1.5 block">步骤类型</label>
              <div className="flex flex-wrap gap-1.5">
                {Object.values(InferenceStepType).map(type => (
                  <button
                    key={type}
                    onClick={() => setFilterOptions(prev => ({
                      ...prev,
                      stepTypes: prev.stepTypes.includes(type)
                        ? prev.stepTypes.filter(t => t !== type)
                        : [...prev.stepTypes, type],
                    }))}
                    className={clsx(
                      'px-2.5 py-1 text-xs rounded-full border transition-colors',
                      filterOptions.stepTypes.includes(type)
                        ? 'bg-secondary-100 border-secondary-300 text-secondary-700'
                        : 'bg-white dark:bg-neutral-900 border-neutral-200 text-neutral-500 hover:bg-neutral-50 dark:bg-neutral-800',
                    )}
                  >
                    {typeLabels[type]}
                  </button>
                ))}
              </div>
            </div>

            {/* 状态过滤 */}
            <div>
              <label className="text-xs font-medium text-neutral-600 mb-1.5 block">步骤状态</label>
              <div className="flex flex-wrap gap-1.5">
                {Object.values(InferenceStepStatus).map(status => (
                  <button
                    key={status}
                    onClick={() => setFilterOptions(prev => ({
                      ...prev,
                      statuses: prev.statuses.includes(status)
                        ? prev.statuses.filter(s => s !== status)
                        : [...prev.statuses, status],
                    }))}
                    className={clsx(
                      'px-2.5 py-1 text-xs rounded-full border transition-colors',
                      filterOptions.statuses.includes(status)
                        ? 'bg-success-100 border-success-300 text-success-700'
                        : 'bg-white dark:bg-neutral-900 border-neutral-200 text-neutral-500 hover:bg-neutral-50 dark:bg-neutral-800',
                    )}
                  >
                    {statusLabels[status]}
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 步骤列表 */}
      <div
        ref={stepsContainerRef}
        className="flex-1 overflow-y-auto p-4 space-y-3 bg-neutral-50 dark:bg-neutral-800/50"
      >
        {filteredSteps.length > 0 ? (
          filteredSteps.map((step, index) => (
            <InferenceStepCard
              key={step.id}
              step={step}
              isExpanded={expandedSteps.has(step.id)}
              onToggleExpand={handleToggleExpand}
              isActive={index === currentStepIndex}
              onClick={handleStepClick}
              data-active={index === currentStepIndex}
            />
          ))
        ) : (
          <div className="flex flex-col items-center justify-center py-12 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
            <BarChart3 className="w-12 h-12 mb-3 opacity-50" />
            <p>没有找到匹配的步骤</p>
            <p className="text-sm mt-1">请尝试调整过滤条件或搜索关键词</p>
          </div>
        )}
      </div>

      {/* 当前步骤信息栏 */}
      {currentStep && (
        <div className="px-6 py-3 border-t border-neutral-200 bg-white dark:bg-neutral-900">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <span className="text-sm font-medium text-neutral-700">当前步骤:</span>
              <span className="text-sm text-neutral-900">{currentStep.title}</span>
            </div>
            <div className="flex items-center gap-4 text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
              <span>类型: {typeLabels[currentStep.type]}</span>
              <span>状态: {statusLabels[currentStep.status]}</span>
              {currentStep.confidence !== undefined && (
                <span>置信度: {(currentStep.confidence * 100).toFixed(0)}%</span>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// 类型标签
const typeLabels: Record<InferenceStepType, string> = {
  [InferenceStepType.THOUGHT]: '思考',
  [InferenceStepType.ACTION]: '行动',
  [InferenceStepType.OBSERVATION]: '观察',
  [InferenceStepType.SUMMARY]: '总结',
};

// 状态标签
const statusLabels: Record<InferenceStepStatus, string> = {
  [InferenceStepStatus.PENDING]: '等待',
  [InferenceStepStatus.RUNNING]: '执行中',
  [InferenceStepStatus.SUCCESS]: '成功',
  [InferenceStepStatus.FAILED]: '失败',
  [InferenceStepStatus.SKIPPED]: '跳过',
};

// 统计项组件
interface StatItemProps {
  icon: typeof Hash;
  label: string;
  value: number | string;
  color?: string;
}

function StatItem({ icon: Icon, label, value, color = 'text-neutral-600' }: StatItemProps) {
  return (
    <div className="flex items-center gap-1.5">
      <Icon className={clsx('w-4 h-4', color)} />
      <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{label}</span>
      <span className={clsx('text-sm font-semibold', color)}>{value}</span>
    </div>
  );
}

import { useState, useCallback, useMemo, useRef, useEffect } from 'react';
import { useVirtualizer } from '@tanstack/react-virtual';
import {
  ChevronLeft,
  ChevronRight,
  SkipBack,
  SkipForward,
  ChevronDown,
  ChevronUp,
  Search,
  Filter,
  Lightbulb,
  Cog,
  Eye,
  FileText,
  Clock,
  CheckCircle,
  XCircle,
  Hash,
  BarChart3,
} from 'lucide-react';
import { clsx } from 'clsx';
import type { InferenceChain, InferenceStep, InferenceChainStats, FilterOptions } from '@/types/inference';
import { InferenceStepType, InferenceStepStatus } from '@/types/inference';
import InferenceStepCard from './InferenceStepCard';

interface InferenceChainVisualizerProps {
  chain: InferenceChain;
  autoScrollToActive?: boolean;
}

export default function InferenceChainVisualizer({ chain, autoScrollToActive = true }: InferenceChainVisualizerProps) {
  const [expandedSteps, setExpandedSteps] = useState<Set<string>>(new Set());
  const [currentStepIndex, setCurrentStepIndex] = useState<number>(0);
  const [searchQuery, setSearchQuery] = useState('');
  const [showFilter, setShowFilter] = useState(false);
  const [filterOptions, setFilterOptions] = useState<FilterOptions>({
    stepTypes: Object.values(InferenceStepType),
    statuses: Object.values(InferenceStepStatus),
    searchQuery: '',
  });

  const parentRef = useRef<HTMLDivElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  // 过滤步骤（使用useMemo缓存）
  const filteredSteps = useMemo(() => {
    return chain.steps.filter((step) => {
      if (!filterOptions.stepTypes.includes(step.type)) return false;
      if (!filterOptions.statuses.includes(step.status)) return false;
      const searchLower = filterOptions.searchQuery.toLowerCase();
      if (searchLower) {
        const matchesTitle = step.title.toLowerCase().includes(searchLower);
        const matchesContent = step.content.toLowerCase().includes(searchLower);
        return matchesTitle || matchesContent;
      }
      return true;
    });
  }, [chain.steps, filterOptions]);

  // 计算统计信息
  const stats: InferenceChainStats = useMemo(() => {
    const steps = chain.steps;
    const executionTimes = steps.filter((s) => s.executionTime !== undefined).map((s) => s.executionTime!);

    return {
      totalSteps: steps.length,
      thoughtCount: steps.filter((s) => s.type === InferenceStepType.THOUGHT).length,
      actionCount: steps.filter((s) => s.type === InferenceStepType.ACTION).length,
      observationCount: steps.filter((s) => s.type === InferenceStepType.OBSERVATION).length,
      successCount: steps.filter((s) => s.status === InferenceStepStatus.SUCCESS).length,
      failedCount: steps.filter((s) => s.status === InferenceStepStatus.FAILED).length,
      totalExecutionTime: steps.reduce((sum, s) => sum + (s.executionTime || 0), 0),
      avgStepTime:
        executionTimes.length > 0 ? Math.round(executionTimes.reduce((a, b) => a + b, 0) / executionTimes.length) : 0,
      maxStepTime: executionTimes.length > 0 ? Math.max(...executionTimes) : 0,
      minStepTime: executionTimes.length > 0 ? Math.min(...executionTimes) : 0,
    };
  }, [chain.steps]);

  // 计算步骤高度（展开状态影响高度）
  const getStepHeight = useCallback(
    (step: InferenceStep) => {
      const baseHeight = 72; // 折叠状态高度
      if (!expandedSteps.has(step.id)) return baseHeight;

      // 展开状态估算高度
      let expandedHeight = baseHeight + 60; // 基础内容高度

      // 工具调用信息
      if (step.type === InferenceStepType.ACTION && step.toolCall) {
        expandedHeight += 40 + step.toolCall.parameters.length * 24;
      }

      // 工具执行结果
      if (step.toolResult) {
        expandedHeight += 50;
        if (step.toolResult.data) {
          expandedHeight += 80; // 数据展示区域
        }
      }

      return expandedHeight;
    },
    [expandedSteps],
  );

  // 虚拟列表配置
  const virtualizer = useVirtualizer({
    count: filteredSteps.length,
    getScrollElement: () => scrollRef.current,
    estimateSize: useCallback(
      (index) => {
        return getStepHeight(filteredSteps[index]);
      },
      [filteredSteps, getStepHeight],
    ),
    overscan: 5, // 预渲染前后5个元素
  });

  // 切换步骤展开状态（触发虚拟列表重新计算）
  const handleToggleExpand = useCallback(
    (stepId: string) => {
      setExpandedSteps((prev) => {
        const newSet = new Set(prev);
        if (newSet.has(stepId)) {
          newSet.delete(stepId);
        } else {
          newSet.add(stepId);
        }
        return newSet;
      });
      // 强制虚拟列表重新计算尺寸
      setTimeout(() => {
        (virtualizer as any)?.recomputeSize?.();
      }, 50);
    },
    [virtualizer],
  );

  // 展开所有步骤
  const handleExpandAll = useCallback(() => {
    const allStepIds = new Set(chain.steps.map((s) => s.id));
    setExpandedSteps(allStepIds);
    setTimeout(() => {
      (virtualizer as any)?.recomputeSize?.();
    }, 50);
  }, [chain.steps, virtualizer]);

  // 折叠所有步骤
  const handleCollapseAll = useCallback(() => {
    setExpandedSteps(new Set());
    setTimeout(() => {
      (virtualizer as any)?.recomputeSize?.();
    }, 50);
  }, [virtualizer]);

  // 导航到特定步骤
  const handleNavigateTo = useCallback(
    (stepIndex: number) => {
      if (stepIndex >= 0 && stepIndex < filteredSteps.length) {
        setCurrentStepIndex(stepIndex);
        // 滚动到目标步骤
        virtualizer.scrollToIndex(stepIndex, { behavior: 'smooth', align: 'center' });
      }
    },
    [filteredSteps.length, virtualizer],
  );

  // 上一步
  const handlePrevStep = useCallback(() => {
    if (currentStepIndex > 0) {
      handleNavigateTo(currentStepIndex - 1);
    }
  }, [currentStepIndex, handleNavigateTo]);

  // 下一步
  const handleNextStep = useCallback(() => {
    if (currentStepIndex < filteredSteps.length - 1) {
      handleNavigateTo(currentStepIndex + 1);
    }
  }, [currentStepIndex, filteredSteps.length, handleNavigateTo]);

  // 跳转到第一步
  const handleFirstStep = useCallback(() => {
    handleNavigateTo(0);
  }, [handleNavigateTo]);

  // 跳转到最后一步
  const handleLastStep = useCallback(() => {
    handleNavigateTo(filteredSteps.length - 1);
  }, [filteredSteps.length, handleNavigateTo]);

  // 步骤点击处理
  const handleStepClick = useCallback(
    (stepId: string) => {
      const index = filteredSteps.findIndex((s) => s.id === stepId);
      if (index !== -1) {
        setCurrentStepIndex(index);
      }
    },
    [filteredSteps],
  );

  // 搜索同步
  useEffect(() => {
    setFilterOptions((prev) => ({ ...prev, searchQuery }));
    setCurrentStepIndex(0); // 搜索时重置到第一步
  }, [searchQuery]);

  // 获取当前步骤
  const currentStep: InferenceStep | undefined = filteredSteps[currentStepIndex];

  return (
    <div className="flex flex-col h-full bg-white dark:bg-neutral-900 rounded-xl border border-neutral-200 overflow-hidden">
      {/* 头部 */}
      <div className="px-6 py-4 border-b border-neutral-200 dark:border-neutral-700 bg-gradient-to-r from-neutral-50 to-white">
        <div className="flex items-center justify-between">
          <div>
            <h2 className="text-lg font-semibold text-neutral-900">{chain.title}</h2>
            {chain.description && <p className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">{chain.description}</p>}
          </div>
          <div className="flex items-center gap-2">
            <span className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
              步骤: {filteredSteps.length}/{chain.steps.length}
            </span>
          </div>
        </div>
      </div>

      {/* 统计信息栏 */}
      <div className="px-6 py-3 bg-neutral-50 dark:bg-neutral-800 border-b border-neutral-200">
        <div className="flex flex-wrap items-center gap-4">
          <StatItem icon={Hash} label="总步骤" value={stats.totalSteps} />
          <StatItem icon={Lightbulb} label="思考" value={stats.thoughtCount} color="text-warning-600" />
          <StatItem icon={Cog} label="行动" value={stats.actionCount} color="text-secondary-600" />
          <StatItem icon={Eye} label="观察" value={stats.observationCount} color="text-success-600" />
          <StatItem icon={CheckCircle} label="成功" value={stats.successCount} color="text-success-500" />
          <StatItem icon={XCircle} label="失败" value={stats.failedCount} color="text-error-500" />
          <StatItem icon={Clock} label="总耗时" value={`${stats.totalExecutionTime}ms`} />
        </div>
      </div>

      {/* 工具栏 */}
      <div className="px-6 py-3 border-b border-neutral-100 flex items-center justify-between">
        {/* 导航控制 */}
        <div className="flex items-center gap-2">
          <button onClick={handleFirstStep} disabled={currentStepIndex === 0} className="nav-btn" title="跳转到第一步">
            <SkipBack className="w-4 h-4" />
          </button>
          <button onClick={handlePrevStep} disabled={currentStepIndex === 0} className="nav-btn" title="上一步">
            <ChevronLeft className="w-4 h-4" />
          </button>
          <span className="px-3 py-1 bg-neutral-100 dark:bg-neutral-800 rounded-full text-sm font-medium text-neutral-700 min-w-[80px] text-center">
            {currentStepIndex + 1} / {filteredSteps.length}
          </span>
          <button
            onClick={handleNextStep}
            disabled={currentStepIndex === filteredSteps.length - 1}
            className="nav-btn"
            title="下一步"
          >
            <ChevronRight className="w-4 h-4" />
          </button>
          <button
            onClick={handleLastStep}
            disabled={currentStepIndex === filteredSteps.length - 1}
            className="nav-btn"
            title="跳转到最后一步"
          >
            <SkipForward className="w-4 h-4" />
          </button>
        </div>

        {/* 操作按钮 */}
        <div className="flex items-center gap-2">
          {/* 搜索框 */}
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
            <input
              type="text"
              placeholder="搜索步骤..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-9 pr-4 py-1.5 text-sm border border-neutral-200 dark:border-neutral-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-secondary-500 focus:border-transparent w-64"
            />
          </div>

          {/* 过滤器 */}
          <button
            onClick={() => setShowFilter(!showFilter)}
            className={clsx(
              'flex items-center gap-1.5 px-3 py-1.5 text-sm rounded-lg border transition-colors',
              showFilter
                ? 'bg-secondary-50 border-secondary-300 text-secondary-700'
                : 'border-neutral-200 text-neutral-600 hover:bg-neutral-50 dark:bg-neutral-800',
            )}
          >
            <Filter className="w-4 h-4" />
            过滤
          </button>

          {/* 展开/折叠按钮 */}
          <button
            onClick={handleExpandAll}
            className="flex items-center gap-1.5 px-3 py-1.5 text-sm border border-neutral-200 rounded-lg text-neutral-600 hover:bg-neutral-50 dark:bg-neutral-800 transition-colors"
          >
            <ChevronDown className="w-4 h-4" />
            展开全部
          </button>
          <button
            onClick={handleCollapseAll}
            className="flex items-center gap-1.5 px-3 py-1.5 text-sm border border-neutral-200 rounded-lg text-neutral-600 hover:bg-neutral-50 dark:bg-neutral-800 transition-colors"
          >
            <ChevronUp className="w-4 h-4" />
            折叠全部
          </button>
        </div>
      </div>

      {/* 过滤器面板 */}
      {showFilter && (
        <div className="px-6 py-3 bg-neutral-50 dark:bg-neutral-800 border-b border-neutral-200">
          <div className="flex flex-wrap gap-6">
            <div>
              <label className="text-xs font-medium text-neutral-600 mb-1.5 block">步骤类型</label>
              <div className="flex flex-wrap gap-1.5">
                {Object.values(InferenceStepType).map((type) => (
                  <button
                    key={type}
                    onClick={() =>
                      setFilterOptions((prev) => ({
                        ...prev,
                        stepTypes: prev.stepTypes.includes(type)
                          ? prev.stepTypes.filter((t) => t !== type)
                          : [...prev.stepTypes, type],
                      }))
                    }
                    className={clsx(
                      'px-2.5 py-1 text-xs rounded-full border transition-colors',
                      filterOptions.stepTypes.includes(type)
                        ? 'bg-secondary-100 border-secondary-300 text-secondary-700'
                        : 'bg-white dark:bg-neutral-900 border-neutral-200 text-neutral-500 hover:bg-neutral-50 dark:bg-neutral-800',
                    )}
                  >
                    {typeLabels[type]}
                  </button>
                ))}
              </div>
            </div>

            <div>
              <label className="text-xs font-medium text-neutral-600 mb-1.5 block">步骤状态</label>
              <div className="flex flex-wrap gap-1.5">
                {Object.values(InferenceStepStatus).map((status) => (
                  <button
                    key={status}
                    onClick={() =>
                      setFilterOptions((prev) => ({
                        ...prev,
                        statuses: prev.statuses.includes(status)
                          ? prev.statuses.filter((s) => s !== status)
                          : [...prev.statuses, status],
                      }))
                    }
                    className={clsx(
                      'px-2.5 py-1 text-xs rounded-full border transition-colors',
                      filterOptions.statuses.includes(status)
                        ? 'bg-success-100 border-success-300 text-success-700'
                        : 'bg-white dark:bg-neutral-900 border-neutral-200 text-neutral-500 hover:bg-neutral-50 dark:bg-neutral-800',
                    )}
                  >
                    {statusLabels[status]}
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 步骤列表（虚拟列表） */}
      <div ref={parentRef} className="flex-1 overflow-hidden bg-neutral-50 dark:bg-neutral-800/50">
        <div
          ref={scrollRef}
          className="h-full overflow-y-auto"
          style={{
            height: '100%',
          }}
        >
          <div
            className="relative"
            style={{
              height: `${virtualizer.getTotalSize()}px`,
              width: '100%',
            }}
          >
            {filteredSteps.length > 0 ? (
              virtualizer.getVirtualItems().map((virtualItem) => (
                <div
                  key={virtualItem.key}
                  style={{
                    position: 'absolute',
                    top: 0,
                    left: 0,
                    width: '100%',
                    transform: `translateY(${virtualItem.start}px)`,
                  }}
                >
                  <div className="px-4 py-3">
                    <InferenceStepCard
                      step={filteredSteps[virtualItem.index]}
                      isExpanded={expandedSteps.has(filteredSteps[virtualItem.index].id)}
                      onToggleExpand={handleToggleExpand}
                      isActive={virtualItem.index === currentStepIndex}
                      onClick={handleStepClick}
                    />
                  </div>
                </div>
              ))
            ) : (
              <div className="flex flex-col items-center justify-center py-12 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                <BarChart3 className="w-12 h-12 mb-3 opacity-50" />
                <p>没有找到匹配的步骤</p>
                <p className="text-sm mt-1">请尝试调整过滤条件或搜索关键词</p>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* 当前步骤信息栏 */}
      {currentStep && (
        <div className="px-6 py-3 border-t border-neutral-200 bg-white dark:bg-neutral-900">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <span className="text-sm font-medium text-neutral-700">当前步骤:</span>
              <span className="text-sm text-neutral-900">{currentStep.title}</span>
            </div>
            <div className="flex items-center gap-4 text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
              <span>类型: {typeLabels[currentStep.type]}</span>
              <span>状态: {statusLabels[currentStep.status]}</span>
              {currentStep.confidence !== undefined && (
                <span>置信度: {(currentStep.confidence * 100).toFixed(0)}%</span>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

const typeLabels: Record<InferenceStepType, string> = {
  [InferenceStepType.THOUGHT]: '思考',
  [InferenceStepType.ACTION]: '行动',
  [InferenceStepType.OBSERVATION]: '观察',
  [InferenceStepType.SUMMARY]: '总结',
};

const statusLabels: Record<InferenceStepStatus, string> = {
  [InferenceStepStatus.PENDING]: '等待',
  [InferenceStepStatus.RUNNING]: '执行中',
  [InferenceStepStatus.SUCCESS]: '成功',
  [InferenceStepStatus.FAILED]: '失败',
  [InferenceStepStatus.SKIPPED]: '跳过',
};

interface StatItemProps {
  icon: typeof Hash;
  label: string;
  value: number | string;
  color?: string;
}

function StatItem({ icon: Icon, label, value, color = 'text-neutral-600' }: StatItemProps) {
  return (
    <div className="flex items-center gap-1.5">
      <Icon className={clsx('w-4 h-4', color)} />
      <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{label}</span>
      <span className={clsx('text-sm font-semibold', color)}>{value}</span>
    </div>
  );
}

