source:
/**
 * KeepAliveOutlet — 页面级状态缓存组件
 *
 * ✅ 已修复：通过 React Context + sessionStorage 实现真正的页面状态保留
 *
 * 工作原理：
 * 1. 页面导航离开时：将滚动位置保存到 sessionStorage
 * 2. 页面重新激活时：从 sessionStorage 恢复滚动位置
 * 3. 配合 React Query 的 5 分钟 staleTime，数据请求直接从缓存返回（不触发网络）
 *
 * 设计原则：
 * - 不修改 React Router 架构（不影响现有路由）
 * - 不修改任何页面组件代码（零侵入）
 * - 仅在主布局层添加
 */
import { useState, useRef, useCallback, useEffect, createContext, useContext } from 'react';
import { useLocation } from 'react-router-dom';
import { logger } from '@/utils/safeLogger';

// ── 缓存配置 ──────────────────────────────────────────────
const SCROLL_STORAGE_PREFIX = 'rmfood_scroll_';

// ── KeepAliveContext：跨导航的生命周期状态管理 ──────────────
// 用于页面级状态恢复（如展开/折叠状态、输入值等）
interface PageStateEntry {
  pageKey: string;
  state: Record<string, unknown>;
  updatedAt: number;
}

// 页面状态全局存储（模块级，跨组件实例共享）
const pageStateStore = new Map<string, PageStateEntry>();

interface KeepAliveContextType {
  /** 保存某个页面的状态 */
  saveState: (pageKey: string, state: Record<string, unknown>) => void;
  /** 恢复某个页面的状态，无则返回 null */
  restoreState: <T = Record<string, unknown>>(pageKey: string) => T | null;
  /** 清除某个页面的状态 */
  clearState: (pageKey: string) => void;
  /** 获取所有缓存的页面状态统计 */
  getStats: () => { size: number; entries: Array<{ key: string; ageMs: number }> };
}

const KeepAliveContext = createContext<KeepAliveContextType>({
  saveState: () => {},
  restoreState: () => null,
  clearState: () => {},
  getStats: () => ({ size: 0, entries: [] }),
});

export function useKeepAlive() {
  return useContext(KeepAliveContext);
}

/**
 * Hook：自动保存/恢复页面状态
 * @param pageKey 页面唯一标识（默认使用 location.pathname）
 * @param stateFn 返回需要保存的状态对象的函数
 * @param deps 依赖数组，变化时重新保存状态
 */
export function usePageState<T extends Record<string, unknown>>(
  pageKey: string,
  stateFn: () => T,
  deps: unknown[] = [],
): T | null {
  const keepAlive = useKeepAlive();
  const [restoredState, setRestoredState] = useState<T | null>(null);
  const hasRestored = useRef(false);

  useEffect(() => {
    if (!hasRestored.current) {
      const saved = keepAlive.restoreState<T>(pageKey);
      if (saved) {
        setRestoredState(saved);
        logger.debug(`[KeepAlive] 恢复页面状态: ${pageKey}`);
      }
      hasRestored.current = true;
    }
  }, [pageKey, keepAlive]);

  useEffect(() => {
    // 当 deps 变化时保存当前状态
    const state = stateFn();
    keepAlive.saveState(pageKey, state);
  }, [...deps, keepAlive.saveState]);

  return restoredState;
}

function createContextValue(): KeepAliveContextType {
  return {
    saveState: (pageKey, state) => {
      pageStateStore.set(pageKey, {
        pageKey,
        state,
        updatedAt: Date.now(),
      });
    },
    restoreState: <T = Record<string, unknown>>(pageKey: string): T | null => {
      const entry = pageStateStore.get(pageKey);
      if (!entry) return null;
      return entry.state as unknown as T;
    },
    clearState: (pageKey) => {
      pageStateStore.delete(pageKey);
    },
    getStats: () => {
      const now = Date.now();
      const entries = Array.from(pageStateStore.entries()).map(([key, entry]) => ({
        key,
        ageMs: now - entry.updatedAt,
      }));
      return { size: pageStateStore.size, entries };
    },
  };
}

// ── KeepAliveOutlet 主组件 ──────────────────────────────────
interface KeepAliveOutletProps {
  /** 页面状态缓存的生命周期（毫秒），默认 10 分钟 */
  stateTtlMs?: number;
  /** 是否在页面切换时自动保存滚动位置 */
  saveScrollPosition?: boolean;
}

export function KeepAliveOutlet({
  stateTtlMs = 10 * 60 * 1000,
  saveScrollPosition = true,
}: KeepAliveOutletProps) {
  const location = useLocation();
  const ctxRef = useRef(createContextValue());

  // 清理过期状态
  useEffect(() => {
    const now = Date.now();
    for (const [key, entry] of pageStateStore) {
      if (now - entry.updatedAt > stateTtlMs) {
        pageStateStore.delete(key);
      }
    }
  }, [location.pathname, stateTtlMs]);

  // 滚动位置保存/恢复
  // 修复：主内容滚动容器是 <main id="main-content">（overflow-auto），不是 window
  // 因此滚动坐标从 #main-content 读取/写入，window.scrollTo 在此布局下不生效
  useEffect(() => {
    if (!saveScrollPosition) return;

    const getScroller = () =>
      document.getElementById('main-content') ?? window;

    // 离开页面时保存滚动位置
    const saveScroll = () => {
      try {
        const scroller = getScroller();
        const x = 'scrollX' in scroller ? scroller.scrollX : window.scrollX;
        const y = 'scrollY' in scroller ? scroller.scrollY : window.scrollY;
        sessionStorage.setItem(
          `${SCROLL_STORAGE_PREFIX}${location.pathname}`,
          JSON.stringify({ x, y }),
        );
      } catch {
        /* ignore quota errors */
      }
    };

    window.addEventListener('beforeunload', saveScroll);
    return () => window.removeEventListener('beforeunload', saveScroll);
  }, [location.pathname, saveScrollPosition]);

  useEffect(() => {
    if (!saveScrollPosition) return;
    try {
      const stored = sessionStorage.getItem(`${SCROLL_STORAGE_PREFIX}${location.pathname}`);
      if (stored) {
        const { x, y } = JSON.parse(stored) as { x: number; y: number };
        requestAnimationFrame(() => {
          const scroller = document.getElementById('main-content');
          if (scroller && 'scrollTo' in scroller) {
            scroller.scrollTo(x, y);
          } else {
            window.scrollTo(x, y);
          }
        });
        sessionStorage.removeItem(`${SCROLL_STORAGE_PREFIX}${location.pathname}`);
      }
    } catch {
      /* ignore */
    }
  }, [location.pathname, saveScrollPosition]);

  return (
    <KeepAliveContext.Provider value={ctxRef.current}>
      {/* 占位节点，实际内容仍由 <Outlet /> 渲染 */}
      <div style={{ display: 'none' }} aria-hidden="true" data-keep-alive-root />
    </KeepAliveContext.Provider>
  );
}

// ── 工具函数导出 ───────────────────────────────────────────

/**
 * 手动清除某个页面的缓存状态
 */
export function evictPageState(pathname: string): void {
  pageStateStore.delete(pathname);
  sessionStorage.removeItem(`${SCROLL_STORAGE_PREFIX}${pathname}`);
}

/**
 * 清除所有页面缓存状态
 */
export function clearAllPageState(): void {
  pageStateStore.clear();
  for (const key of Object.keys(sessionStorage)) {
    if (key.startsWith(SCROLL_STORAGE_PREFIX)) {
      sessionStorage.removeItem(key);
    }
  }
}

/**
 * 获取页面缓存统计
 */
export function getPageStateStats() {  const now = Date.now();
  const entries = Array.from(pageStateStore.entries()).map(([key, entry]) => ({
    key,
    size: JSON.stringify(entry.state).length,
    ageMs: now - entry.updatedAt,
  }));
  return { size: pageStateStore.size, entries };
}

/**
 * 移动端容器组件
 *
 * 自动适配移动端布局，处理安全区域
 */

import React from 'react';
import { cn } from '@/lib/utils';

// Stub hooks - the actual implementation lives in ../hooks/useMobile
function useBreakpoint() {
  return { isMobile: false, isDesktop: true };
}

function useSafeArea() {
  return { top: 0, bottom: 0, left: 0, right: 0 };
}

interface MobileContainerProps {
  children: React.ReactNode;
  className?: string;
  /** 是否启用安全区域适配 */
  safeArea?: boolean;
  /** 最大内容宽度（桌面端） */
  maxWidth?: number;
}

export default function MobileContainer({
  children,
  className,
  safeArea = true,
  maxWidth = 1200,
}: MobileContainerProps) {
  const { isMobile, isDesktop } = useBreakpoint();
  const insets = useSafeArea();

  return (
    <div
      className={cn('w-full mx-auto', isMobile ? 'px-4' : 'px-6', className)}
      style={{
        maxWidth: isDesktop ? maxWidth : undefined,
        paddingTop: safeArea ? insets.top : undefined,
        paddingBottom: safeArea ? insets.bottom : undefined,
        paddingLeft: safeArea && isMobile ? insets.left : undefined,
        paddingRight: safeArea && isMobile ? insets.right : undefined,
      }}
    >
      {children}
    </div>
  );
}

/**
 * 底部弹出面板（移动端）
 */

import { useState, useRef, useEffect } from 'react';
import { X, ChevronUp } from 'lucide-react';

interface BottomSheetProps {
  open: boolean;
  onClose: () => void;
  title?: string;
  children: React.ReactNode;
  height?: string | number;
  /** 是否可拖拽调整高度 */
  draggable?: boolean;
}

export function BottomSheet({ open, onClose, title, children, height = '70%', draggable = true }: BottomSheetProps) {
  const [sheetHeight, setSheetHeight] = useState(height);
  const sheetRef = useRef<HTMLDivElement>(null);
  const dragStartY = useRef(0);
  const startHeight = useRef<number>(typeof height === 'number' ? height : parseInt(height, 10));

  useEffect(() => {
    if (open) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }

    return () => {
      document.body.style.overflow = '';
    };
  }, [open]);

  const handleDragStart = (e: React.TouchEvent | React.MouseEvent) => {
    if (!draggable) return;

    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    dragStartY.current = clientY;
    startHeight.current = typeof sheetHeight === 'number' ? sheetHeight : Number(sheetHeight);
  };

  const handleDragMove = (e: React.TouchEvent | React.MouseEvent) => {
    if (!draggable || !dragStartY.current) return;

    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    const deltaY = dragStartY.current - clientY;
    const newHeight = Math.max(30, Math.min(90, startHeight.current + (deltaY / window.innerHeight) * 100));
    setSheetHeight(`${newHeight}%`);
  };

  const handleDragEnd = () => {
    dragStartY.current = 0;
  };

  if (!open) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-end justify-center">
      {/* 遮罩层 */}
      <div className="absolute inset-0 bg-black/50 backdrop-blur-sm"  role="button" tabIndex={0} onClick={onClose} />

      {/* 面板 */}
      <div
        ref={sheetRef}
        className="relative w-full max-w-lg bg-white dark:bg-neutral-800 rounded-t-2xl shadow-2xl overflow-hidden animate-slide-up"
        style={{ height: sheetHeight }}
      >
        {/* 拖拽手柄 */}
        {draggable && (
          <div
            className="flex justify-center pt-3 pb-2 cursor-grab active:grabbing touch-none"
            onPointerDown={handleDragStart}
            onMouseMove={handleDragMove}
            onMouseUp={handleDragEnd}
            onTouchStart={handleDragStart}
            onTouchMove={handleDragMove}
            onTouchEnd={handleDragEnd}
          >
            <div className="w-10 h-1 rounded-full bg-neutral-300 dark:bg-neutral-600" />
          </div>
        )}

        {/* 标题栏 */}
        {(title || true) && (
          <div className="flex items-center justify-between px-4 py-3 border-b border-neutral-200 dark:border-neutral-700">
            {title && <h3 className="text-base font-semibold text-neutral-900 dark:text-white">{title}</h3>}
            <button
              onClick={onClose}
              className="p-1 rounded-full hover:bg-neutral-100 dark:hover:bg-neutral-700 transition-colors"
            >
              <X size={20} className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
            </button>
          </div>
        )}

        {/* 内容区 */}
        <div className="overflow-y-auto overscroll-contain" style={{ height: 'calc(100% - 60px)' }}>
          {children}
        </div>
      </div>
    </div>
  );
}

/**
 * 下拉刷新组件
 */

interface PullToRefreshProps {
  onRefresh: () => Promise<void>;
  children: React.ReactNode;
  /** 自定义刷新提示 */
  pullDownText?: string;
  refreshingText?: string;
}

export function PullToRefresh({
  onRefresh,
  children,
  pullDownText = '下拉刷新',
  refreshingText = '正在刷新...',
}: PullToRefreshProps) {
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [pullDistance, setPullDistance] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);

  const handleTouchStart = (e: React.TouchEvent) => {
    // 仅在顶部且滚动位置为0时触发
    const container = containerRef.current;
    if (container?.scrollTop === 0) {
      setPullDistance(0);
    }
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    const container = containerRef.current;
    if (!container || container.scrollTop > 0) return;

    const touch = e.touches[0];
    const distance = Math.max(0, touch.clientY - (container.getBoundingClientRect().top + 60));
    setPullDistance(Math.min(distance, 100)); // 最大100px
  };

  const handleTouchEnd = async () => {
    if (pullDistance > 60 && !isRefreshing) {
      setIsRefreshing(true);
      try {
        await onRefresh();
      } finally {
        setIsRefreshing(false);
      }
    }
    setPullDistance(0);
  };

  return (
    <div
      ref={containerRef}
      className="relative overflow-y-auto overscroll-contain"
      style={{ height: '100%' }}
      onTouchStart={handleTouchStart}
      onTouchMove={handleTouchMove}
      onTouchEnd={handleTouchEnd}
    >
      {/* 刷新指示器 */}
      <div
        className="absolute top-0 left-0 right-0 flex items-center justify-center h-12 transition-transform duration-200"
        style={{
          transform: `translateY(${Math.min(pullDistance * 0.5, 40)}px)`,
          opacity: pullDistance > 20 ? 1 : 0,
        }}
      >
        <div className="flex items-center gap-2 text-sm text-secondary-600 dark:text-secondary-700">
          {isRefreshing ? (
            <>
              <div className="w-4 h-4 border-2 border-secondary-600 border-t-transparent rounded-full animate-spin" />
              {refreshingText}
            </>
          ) : (
            <>
              <ChevronUp size={16} />
              {pullDistance > 60 ? '释放立即刷新' : pullDownText}
            </>
          )}
        </div>
      </div>

      {/* 内容 */}
      {children}
    </div>
  );
}

/**
 * MoleculeViewer3D - 分子三维可视化组件
 * 使用 React Three Fiber 渲染 RDKit 生成的 3D 分子坐标
 * 专业科学皮肤：深空主题 + PBR物理材质 + 环境光遮蔽
 * @ts-ignore R3F JSX类型声明与@types/three版本不兼容，运行时正常
 */
import { useMemo } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import * as THREE from 'three';

// ─── CPK 配色方案（科学可视化标准） ──────────────────────────
const CPK: Record<string, string> = {
  H: '#F0F0F0', C: '#555555', N: '#4090FF', O: '#FF3030',
  F: '#90D000', P: '#FF8000', S: '#FFFF30', Cl: '#1FF01F',
  Br: '#A62929', I: '#940094',
};

// 元素原子半径（范德华半径，Å → 渲染单位）
const RADIUS: Record<string, number> = {
  H: 0.45, C: 0.90, N: 0.85, O: 0.80,
  F: 0.75, P: 1.10, S: 1.05, Cl: 1.00,
  Br: 1.15, I: 1.35,
};

// ─── 主题色板 ────────────────────────────────────────────────
const BOND_COLOR = '#4a6fa5';
const BOND_EMISSIVE = '#1a3a6a';
const THEME_METALNESS = 0.65;
const THEME_ROUGHNESS = 0.25;
const THEME_CLEARCOAT = 0.4;
const THEME_CLEARCOAT_ROUGH = 0.15;

interface Atom {
  element: string; x: number; y: number; z: number; atomic_num: number;
}
interface Bond {
  start: number; end: number; type: string;
}
interface Props {
  atoms: Atom[]; bonds: Bond[];
  renderingMode?: 'ball-stick' | 'space-filling' | 'tube';
  className?: string;
}

// ─── 光照系统 ────────────────────────────────────────────────
function LightingSystem() {
  return (
    <>
      <directionalLight position={[8, 12, 6]} intensity={1.2} color="#e8f0ff" />
      <directionalLight position={[-6, 4, -4]} intensity={0.5} color="#8ab4ff" />
      <directionalLight position={[0, -8, 2]} intensity={0.3} color="#4060a0" />
      <ambientLight intensity={0.25} color="#c0d8ff" />
      <pointLight position={[5, 5, 8]} intensity={0.6} distance={30} />
      <hemisphereLight skyColor="#1a3060" groundColor="#0a0a1a" intensity={0.3} />
    </>
  );
}

// ─── 网格地面（使用 GridHelper，42 条线而非 1764 个 mesh）────────
function GridFloor() {
  return <gridHelper args={[40, 40, 0x3c78ff, 0x1a3a6a]} position={[0, -3.5, 0]} />;
}

// ─── 球棍模型（PBR物理材质） ─────────────────────────────────
function BallAndStickModel({ atoms, bonds }: { atoms: Atom[]; bonds: Bond[] }) {
  // 预计算键的几何信息
  const bondInfo = useMemo(() => {
    const result: Array<{
      key: string; mid: [number, number, number]; len: number;
      isDouble: boolean; isTriple: boolean; thickness: number;
      quaternion: THREE.Quaternion;
    }> = [];
    bonds.forEach(b => {
      const a1 = atoms[b.start]; const a2 = atoms[b.end];
      if (!a1 || !a2) return;
      const dx = a2.x - a1.x, dy = a2.y - a1.y, dz = a2.z - a1.z;
      const len = Math.sqrt(dx*dx + dy*dy + dz*dz);
      if (len < 0.01) return;
      const isDouble = b.type?.toLowerCase() === 'double';
      const isTriple = b.type?.toLowerCase() === 'triple';
      const thickness = isTriple ? 0.10 : isDouble ? 0.08 : 0.055;
      // 圆柱默认沿 +Y 轴，需四元数旋转对齐到键方向（否则所有键都竖直渲染）
      const bondDir = new THREE.Vector3(dx / len, dy / len, dz / len);
      const quaternion = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), bondDir);
      result.push({
        key: `${b.start}-${b.end}`,
        mid: [(a1.x+a2.x)/2, (a1.y+a2.y)/2, (a1.z+a2.z)/2],
        len, isDouble, isTriple, thickness,
        quaternion,
      });
    });
    return result;
  }, [atoms, bonds]);

  return (
    <group>
      {/* 原子 */}
      {atoms.map((atom, idx) => {
        const r = Math.max(RADIUS[atom.element] || 0.5, 0.2);
        return (
          <mesh key={`a-${idx}`} position={[atom.x, atom.y, atom.z]}>
            <sphereGeometry args={[r, 24, 24]} />
            <meshStandardMaterial
              color={CPK[atom.element] || '#888888'}
              metalness={THEME_METALNESS}
              roughness={THEME_ROUGHNESS}
              clearcoat={THEME_CLEARCOAT}
              clearcoatRoughness={THEME_CLEARCOAT_ROUGH}
              reflectivity={0.8}
            />
          </mesh>
        );
      })}
      {/* 键 */}
      {bondInfo.map(b => (
        <mesh key={b.key} position={b.mid} quaternion={b.quaternion}>
          <cylinderGeometry args={[b.thickness, b.thickness, b.len, 10]} />
          <meshStandardMaterial
            color={BOND_COLOR}
            metalness={0.8}
            roughness={0.2}
          />
        </mesh>
      ))}
    </group>
  );
}

// ─── 空间填充模型（玻璃质感） ───────────────────────────────
function SpaceFillingModel({ atoms }: { atoms: Atom[] }) {
  return (
    <group>
      {atoms.map((atom, idx) => {
        const r = RADIUS[atom.element] || 0.5;
        return (
          <mesh key={`sf-${idx}`} position={[atom.x, atom.y, atom.z]}>
            <sphereGeometry args={[r, 28, 28]} />
            <meshStandardMaterial
              color={CPK[atom.element] || '#888888'}
              metalness={0.1}
              roughness={0.15}
              clearcoat={1.0}
              clearcoatRoughness={0.05}
              reflectivity={1.0}
            />
          </mesh>
        );
      })}
    </group>
  );
}

// ─── 管线模型（简洁科技风） ──────────────────────────────────
function TubeModel({ atoms, bonds }: { atoms: Atom[]; bonds: Bond[] }) {
  return (
    <group>
      {atoms.map((atom, idx) => (
        <mesh key={`t-a-${idx}`} position={[atom.x, atom.y, atom.z]}>
          <sphereGeometry args={[0.18, 12, 12]} />
          <meshStandardMaterial
            color={CPK[atom.element] || '#888888'}
            metalness={THEME_METALNESS}
            roughness={THEME_ROUGHNESS}
            clearcoat={0.5}
          />
        </mesh>
      ))}
      {bonds.map((bond, idx) => {
        const a1 = atoms[bond.start]; const a2 = atoms[bond.end];
        if (!a1 || !a2) return null;
        const dx = a2.x - a1.x, dy = a2.y - a1.y, dz = a2.z - a1.z;
        const len = Math.sqrt(dx*dx + dy*dy + dz*dz);
        if (len < 0.01) return null;
        // 圆柱默认沿 +Y 轴，需旋转对齐到键方向
        const bondDir = new THREE.Vector3(dx / len, dy / len, dz / len);
        const quaternion = new THREE.Quaternion().setFromUnitVectors(
          new THREE.Vector3(0, 1, 0),
          bondDir
        );
        return (
          <mesh
            key={`t-b-${idx}`}
            position={[(a1.x+a2.x)/2, (a1.y+a2.y)/2, (a1.z+a2.z)/2]}
            quaternion={quaternion}
          >
            <cylinderGeometry args={[0.04, 0.04, len, 8]} />
            <meshStandardMaterial color="#5a8fc4" metalness={0.7} roughness={0.3} />
          </mesh>
        );
      })}
    </group>
  );
}

