interface NotificationPrefs {
  enabled: boolean
  email_enabled: boolean
  push_enabled: boolean
  quiet_hours_start: string
  quiet_hours_end: string
}

const PREFS_STORAGE_KEY = 'rmfood_notification_prefs'
const DEFAULT_PREFS: NotificationPrefs = {
  enabled: true,
  email_enabled: true,
  push_enabled: true,
  quiet_hours_start: '22:00',
  quiet_hours_end: '08:00',
}

export function NotificationCenter() {
  const navigate = useNavigate()
  const { addToast } = useToast()
  const user = useAuthStore((s) => s.user)

  const [isOpen, setIsOpen] = useState(false)
  const [notifications, setNotifications] = useState<Notification[]>([])
  const [unreadCount, setUnreadCount] = useState(0)
  const [loading, setLoading] = useState(false)
  const [activeTab, setActiveTab] = useState<'all' | 'unread'>('all')
  const [page, setPage] = useState(1)
  const [totalPages, setTotalPages] = useState(1)
  const [showSettings, setShowSettings] = useState(false)
  const [categoryFilter, setCategoryFilter] = useState<string | null>(null)
  const [showCategoryMenu, setShowCategoryMenu] = useState(false)
  const [confirmClear, setConfirmClear] = useState(false)
  const [sendingTest, setSendingTest] = useState(false)
  // 偏好初始值：先从 localStorage 恢复（惰性初始化，避免 effect 中同步 setState）
  const [prefs, setPrefs] = useState<NotificationPrefs>(() => {
    try {
      const saved = localStorage.getItem(PREFS_STORAGE_KEY)
      if (saved) return { ...DEFAULT_PREFS, ...JSON.parse(saved) }
    } catch { /* 忽略损坏数据 */ }
    return DEFAULT_PREFS
  })

  const panelRef = useRef<HTMLDivElement>(null)
  const triggerRef = useRef<HTMLButtonElement>(null)

  const fetchNotifications = useCallback(async () => {
    setLoading(true)
    try {
      const params: Record<string, any> = {
        page,
        page_size: 10,
      }

      // admin 路由支持 status 过滤（unread/read）
      if (activeTab === 'unread') {
        params.status = 'unread'
      }

      const response = await api.get<any>('/notifications', { params })

      if (response.data) {
        const data = normalizeNotificationList(response.data)
        setNotifications(data.items)
        setUnreadCount(data.unread_count)
        setTotalPages(data.total_pages)
      }
    } catch (error: any) {
      if (error?.response?.status === 401) {
        logger.info('🔐 [NotificationCenter] 未登录，跳过通知加载')
        return
      }
      if (error.message === 'canceled' || error.code === 'ERR_CANCELED') {
        logger.info('⏳ [NotificationCenter] 请求被取消（页面导航）')
        return
      }
      if (error?.response?.status === 500) {
        logger.warn('⚠️ [NotificationCenter] 通知服务暂时不可用，使用空数据')
        setNotifications([])
        setUnreadCount(0)
        setTotalPages(1)
        return
      }
      logger.error('❌ [NotificationCenter] 获取通知失败:', error?.message || error)
    } finally {
      setLoading(false)
    }
  }, [page, activeTab])

  // Keyboard trap: Escape closes, Tab moves within panel
  useEffect(() => {
    if (!isOpen) return
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setIsOpen(false)
        triggerRef.current?.focus()
      }
    }
    document.addEventListener('keydown', handleKeyDown)
    return () => document.removeEventListener('keydown', handleKeyDown)
  }, [isOpen])

  // 初始加载 + 切换页签/翻页时刷新 + 点击面板外部关闭
  useEffect(() => {
    // 数据加载需同步置 loading 状态（react-hooks/set-state-in-effect 对数据请求场景误报）
    // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchNotifications()

    const handleClickOutside = (e: MouseEvent) => {
      if (panelRef.current && !panelRef.current.contains(e.target as Node)) {
        setIsOpen(false)
      }
    }

    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [page, activeTab, fetchNotifications])

  useEffect(() => {
    if (isOpen) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      fetchNotifications()
    }
  }, [isOpen, fetchNotifications])

  // 未读角标轮询（60s 一次，关闭面板时静默刷新）
  useEffect(() => {
    const timer = setInterval(() => {
      if (!isOpen) {
        api.get<any>('/notifications/unread-count')
          .then((res) => {
            const count = res.data?.unread_count
            if (typeof count === 'number') setUnreadCount(count)
          })
          .catch(() => { /* 静默 */ })
      }
    }, 60000)
    return () => clearInterval(timer)
  }, [isOpen])

  // 实时推送：WebSocket 收到 notification 事件时立即刷新未读角标/列表
  useEffect(() => {
    const refresh = () => {
      if (isOpen) {
        fetchNotifications()
      } else {
        api.get<any>('/notifications/unread-count')
          .then((res) => {
            const count = res.data?.unread_count
            if (typeof count === 'number') setUnreadCount(count)
          })
          .catch(() => { /* 静默 */ })
      }
    }

    const unsubChannel = subscribeToChannel('notification', refresh)
    const offMessage = onWebSocketMessage((msg) => {
      if (msg.type === 'notification') refresh()
    })
    return () => {
      unsubChannel()
      offMessage()
    }
  }, [isOpen, fetchNotifications])

  // 从服务端同步通知偏好（尽力而为；本地已由 useState 惰性初始化恢复）
  useEffect(() => {
    api.get<any>('/notifications/preferences')
      .then((res) => {
        const p = res.data?.preferences
        if (p) {
          setPrefs((prev) => ({
            ...prev,
            email_enabled: p.email_enabled ?? prev.email_enabled,
            push_enabled: p.push_enabled ?? prev.push_enabled,
            quiet_hours_start: p.quiet_hours?.start ?? prev.quiet_hours_start,
            quiet_hours_end: p.quiet_hours?.end ?? prev.quiet_hours_end,
          }))
        }
      })
      .catch(() => { /* 后端未实现持久化时静默，使用本地设置 */ })
  }, [])

  const savePrefs = (next: NotificationPrefs) => {
    setPrefs(next)
    try {
      localStorage.setItem(PREFS_STORAGE_KEY, JSON.stringify(next))
    } catch { /* 存储不可用时忽略 */ }
    // 尽力与服务端同步（v1 当前不落库，仅返回）
    api.put('/notifications/preferences', {
      email_enabled: next.email_enabled,
      push_enabled: next.push_enabled,
      quiet_hours_start: next.quiet_hours_start,
      quiet_hours_end: next.quiet_hours_end,
    }).catch(() => { /* 静默 */ })
  }

  // 标记单条已读 —— 对齐后端 v1 路由：PUT /notifications/{id}/read
  const markAsRead = async (id: number) => {
    try {
      await api.put(`/notifications/${id}/read`)

      setNotifications((prev) =>
        activeTab === 'unread'
          ? prev.filter((n) => n.id !== id)
          : prev.map((n) => (n.id === id ? { ...n, is_read: true, isRead: true } : n)),
      )
      setUnreadCount((prev) => Math.max(0, prev - 1))
    } catch (error) {
      logger.error('❌ 标记已读失败:', error)
      addToast({ type: 'error', message: '标记已读失败，请重试' })
    }
  }

  const markAllAsRead = async () => {
    try {
      await api.put('/notifications/read-all')

      setNotifications((prev) => prev.map((n) => ({ ...n, is_read: true, isRead: true })))
      setUnreadCount(0)
      addToast({ type: 'success', message: '已全部标记为已读' })
    } catch (error) {
      logger.error('❌ 全部标记已读失败:', error)
      addToast({ type: 'error', message: '全部标记已读失败，请重试' })
    }
  }

  const deleteNotification = async (id: number, wasUnread: boolean) => {
    try {
      await api.delete(`/notifications/${id}`)

      setNotifications((prev) => prev.filter((n) => n.id !== id))
      if (wasUnread) {
        setUnreadCount((prev) => Math.max(0, prev - 1))
      }
      addToast({ type: 'success', message: '通知已删除' })
    } catch (error) {
      logger.error('❌ 删除通知失败:', error)
      addToast({ type: 'error', message: '删除通知失败，请重试' })
    }
  }

  // 点击通知主体：未读则标记已读，有链接则跳转
  const handleNotificationClick = (n: Notification) => {
    if (!n.is_read) {
      markAsRead(n.id)
    }
    if (n.link) {
      setIsOpen(false)
      navigate(n.link)
    }
  }

  // 清空全部通知（设置面板内，需二次点击确认）
  const clearAllNotifications = async () => {
    try {
      await api.delete('/notifications/clear-all')
      setNotifications([])
      setUnreadCount(0)
      setTotalPages(1)
      setConfirmClear(false)
      addToast({ type: 'success', message: '已清空全部通知' })
    } catch (error) {
      logger.error('❌ 清空通知失败:', error)
      addToast({ type: 'error', message: '清空通知失败，请重试' })
    }
  }

  // 发送测试通知（仅管理员，用于验证实时推送链路）
  const sendTestNotification = async () => {
    setSendingTest(true)
    try {
      await api.post('/notifications/v2/send', { template_id: 'test' })
      addToast({ type: 'success', message: '测试通知已发送' })
    } catch (error) {
      logger.error('❌ 发送测试通知失败:', error)
      addToast({ type: 'error', message: '发送测试通知失败' })
    } finally {
      setSendingTest(false)
    }
  }

  // 分类筛选：从当前已加载通知的 metadata.category 提取可筛选分类
  const categories = [...new Set(
    notifications
      .map((n) => n.metadata?.category)
      .filter((c): c is string => Boolean(c)),
  )]

  const visibleNotifications = categoryFilter
    ? notifications.filter((n) => n.metadata?.category === categoryFilter)
    : notifications

  const formatTimeAgo = (dateString: string) => {
    const date = new Date(dateString)
    if (Number.isNaN(date.getTime())) return ''
    const now = new Date()
    const diffMs = now.getTime() - date.getTime()
    const diffMins = Math.floor(diffMs / 60000)
    const diffHours = Math.floor(diffMs / 3600000)
    const diffDays = Math.floor(diffMs / 86400000)

    if (diffMins < 1) return '刚刚'
    if (diffMins < 60) return `${diffMins}分钟前`
    if (diffHours < 24) return `${diffHours}小时前`
    if (diffDays < 7) return `${diffDays}天前`
    return date.toLocaleDateString('zh-CN')
  }

  return (
    <div className="relative" ref={panelRef}>
      {/* Trigger Button */}
      <button
        ref={triggerRef}
        onClick={() => setIsOpen(!isOpen)}
        className="relative p-2 min-w-[44px] min-h-[44px] inline-flex items-center justify-center rounded-lg hover:bg-[var(--color-primary-50)] dark:hover:bg-[var(--color-primary)]/15 transition-colors focus:outline-none"
        aria-label="通知中心"
        title="通知"
        aria-expanded={isOpen}
        aria-haspopup="true"
      >
        <Bell className="w-5 h-5 text-neutral-600 dark:text-neutral-300" />
        {unreadCount > 0 && (
          <span className="absolute -top-0.5 -right-0.5 bg-error-500 text-white text-xs rounded-full w-5 h-5 flex items-center justify-center font-medium">
            {unreadCount > 99 ? '99+' : unreadCount}
          </span>
        )}
      </button>

      {/* Notification Panel
            桌面端：跟随铃铛按钮右下弹出（sm:absolute）
            移动端：fixed 贴住视口右缘/顶栏下方，避免 420px 宽面板溢出屏幕 */}
      {isOpen && (
        <div className="fixed right-4 top-[calc(var(--header-height,56px)+var(--safe-area-inset-top,0px)+8px)] w-[calc(100vw-32px)] max-w-[420px] sm:absolute sm:right-0 sm:top-full sm:mt-2 sm:w-[420px] sm:max-w-none bg-white dark:bg-neutral-900 rounded-xl shadow-2xl border border-neutral-200 dark:border-neutral-700 z-[100] overflow-hidden"
             style={{ paddingBottom: 'var(--safe-area-inset-bottom, 0px)' }}>
          {/* Header */}
          <div className="flex items-center justify-between px-4 py-3 border-b border-neutral-200 dark:border-neutral-700">
            <h3 className="font-semibold text-neutral-900 dark:text-white">通知中心</h3>
            <div className="flex items-center gap-2">
              {unreadCount > 0 && (
                <button
                  onClick={markAllAsRead}
                  className="flex items-center gap-1 px-2 py-1 text-sm text-secondary-600 hover:bg-secondary-50 dark:hover:bg-secondary-900/20 rounded transition-colors"
                >
                  <CheckCheck className="w-4 h-4" />
                  全部已读
                </button>
              )}
              <button
                onClick={() => setShowSettings(!showSettings)}
                className={`p-1.5 rounded-lg transition-colors focus:outline-none ${
                  showSettings ? 'bg-neutral-100 dark:bg-neutral-800' : 'hover:bg-neutral-100 dark:bg-neutral-800 dark:hover:bg-neutral-800'
                }`}
                aria-label="通知设置"
                title="通知设置"
              >
                <Settings className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
              </button>
              <button
                onClick={() => setIsOpen(false)}
                className="p-1.5 rounded-lg hover:bg-neutral-100 dark:bg-neutral-800 dark:hover:bg-neutral-800 focus:outline-none"
                aria-label="关闭通知面板"
              >
                <X className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
              </button>
            </div>
          </div>

          {/* Settings Panel（已接线：本地持久化 + 服务端同步） */}
          {showSettings && (
            <div className="p-4 bg-neutral-50 dark:bg-neutral-800/50 border-b border-neutral-200 dark:border-neutral-700">
              <div className="flex items-center justify-between mb-3">
                <h4 className="text-sm font-medium text-neutral-700 dark:text-neutral-300">通知设置</h4>
                <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">自动保存</span>
              </div>
              <div className="space-y-2">
                <label className="flex items-center gap-2 text-sm cursor-pointer">
                  <input
                    aria-label="启用通知"
                    type="checkbox"
                    checked={prefs.enabled}
                    onChange={(e) => savePrefs({ ...prefs, enabled: e.target.checked })}
                    className="rounded"
                  />
                  <span>启用通知</span>
                </label>
                <label className="flex items-center gap-2 text-sm cursor-pointer">
                  <input
                    aria-label="邮件通知"
                    type="checkbox"
                    checked={prefs.enabled && prefs.email_enabled}
                    disabled={!prefs.enabled}
                    onChange={(e) => savePrefs({ ...prefs, email_enabled: e.target.checked })}
                    className="rounded"
                  />
                  <span>邮件通知</span>
                </label>
                <label className="flex items-center gap-2 text-sm cursor-pointer">
                  <input
                    aria-label="实时推送"
                    type="checkbox"
                    checked={prefs.enabled && prefs.push_enabled}
                    disabled={!prefs.enabled}
                    onChange={(e) => savePrefs({ ...prefs, push_enabled: e.target.checked })}
                    className="rounded"
                  />
                  <span>实时推送</span>
                </label>
                <div className="flex items-center gap-2 pt-2">
                  <Clock className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
                  <input
                    type="time"
                    value={prefs.quiet_hours_start}
                    onChange={(e) => savePrefs({ ...prefs, quiet_hours_start: e.target.value })}
                    className="text-sm border rounded px-2 py-1 w-28"
                    aria-label="免打扰开始时间"
                  />
                  <span className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">至</span>
                  <input
                    type="time"
                    value={prefs.quiet_hours_end}
                    onChange={(e) => savePrefs({ ...prefs, quiet_hours_end: e.target.value })}
                    className="text-sm border rounded px-2 py-1 w-28"
                    aria-label="免打扰结束时间"
                  />
                  <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">免打扰时段</span>
                </div>

                {/* 管理操作 */}
                <div className="flex items-center gap-2 pt-3 mt-3 border-t border-neutral-200 dark:border-neutral-700">
                  {user?.role === 'admin' && (
                    <button
                      onClick={sendTestNotification}
                      disabled={sendingTest}
                      className="flex items-center gap-1 px-2 py-1 text-xs text-secondary-600 hover:bg-secondary-50 dark:hover:bg-secondary-900/20 rounded transition-colors focus:outline-none disabled:opacity-50"
                    >
                      <Send className="w-3 h-3" />
                      {sendingTest ? '发送中...' : '发送测试通知'}
                    </button>
                  )}
                  <button
                    onClick={() => {
                      if (!confirmClear) {
                        setConfirmClear(true)
                        setTimeout(() => setConfirmClear(false), 3000)
                        return
                      }
                      clearAllNotifications()
                    }}
                    className={`flex items-center gap-1 px-2 py-1 text-xs rounded transition-colors focus:outline-none ${
                      confirmClear
                        ? 'bg-error-50 text-error-600 dark:bg-error-900/30 dark:text-error-400 font-medium'
                        : 'text-error-600 hover:bg-error-50 dark:text-error-400 dark:hover:bg-error-900/30'
                    }`}
                  >
                    <Trash2 className="w-3 h-3" />
                    {confirmClear ? '再次点击确认清空' : '清空全部通知'}
                  </button>
                </div>
              </div>
            </div>
          )}

          {/* Tabs + 分类筛选 */}
          <div className="flex items-center gap-2 px-4 py-2 border-b border-neutral-100 dark:border-neutral-800">
            <div className="flex bg-neutral-100 dark:bg-neutral-800 rounded-lg p-0.5">
              <button
                onClick={() => { setActiveTab('all'); setPage(1) }}
                className={`px-3 py-1 text-sm rounded-md transition-colors focus:outline-none ${
                  activeTab === 'all'
                    ? 'bg-white dark:bg-neutral-700 shadow-sm font-medium'
                    : 'text-neutral-600 dark:text-neutral-400'
                }`}
              >
                全部
              </button>
              <button
                onClick={() => { setActiveTab('unread'); setPage(1) }}
                className={`px-3 py-1 text-sm rounded-md transition-colors relative focus:outline-none ${
                  activeTab === 'unread'
                    ? 'bg-white dark:bg-neutral-700 shadow-sm font-medium'
                    : 'text-neutral-600 dark:text-neutral-400'
                }`}
              >
                未读
                {unreadCount > 0 && (
                  <span className="ml-1 bg-error-500 text-white text-xs rounded-full px-1.5 min-w-[18px] text-center">
                    {unreadCount}
                  </span>
                )}
              </button>
            </div>

            {/* 分类筛选（有分类数据时显示） */}
            {categories.length > 0 && (
              <div className="relative ml-auto">
                <button
                  onClick={() => setShowCategoryMenu(!showCategoryMenu)}
                  className={`flex items-center gap-1 px-2 py-1 text-sm rounded-md transition-colors focus:outline-none ${
                    categoryFilter
                      ? 'bg-neutral-200 dark:bg-neutral-700 text-neutral-800 dark:text-neutral-200'
                      : 'text-neutral-500 hover:text-neutral-700 hover:bg-neutral-100 dark:hover:bg-neutral-800'
                  }`}
                  aria-haspopup="menu"
                  aria-expanded={showCategoryMenu}
                >
                  <Filter className="w-3 h-3" />
                  {categoryFilter ?? '筛选'}
                </button>
                {showCategoryMenu && (
                  <div
                    className="absolute right-0 mt-1 w-40 bg-white dark:bg-neutral-800 rounded-lg shadow-xl border border-neutral-200 dark:border-neutral-700 z-50 py-1"
                    role="menu"
                  >
                    <button
                      role="menuitem"
                      onClick={() => { setCategoryFilter(null); setShowCategoryMenu(false) }}
                      className="block w-full text-left px-3 py-1.5 text-xs hover:bg-neutral-100 dark:hover:bg-neutral-700 focus:outline-none"
                    >
                      全部类型
                    </button>
                    {categories.map((c) => (
                      <button
                        key={c}
                        role="menuitem"
                        onClick={() => { setCategoryFilter(c); setShowCategoryMenu(false) }}
                        className="block w-full text-left px-3 py-1.5 text-xs hover:bg-neutral-100 dark:hover:bg-neutral-700 focus:outline-none"
                      >
                        {c}
                      </button>
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>

          {/* Notification List */}
          <div className="max-h-[480px] overflow-y-auto">
            {loading ? (
              <div className="flex flex-col items-center justify-center py-12 space-y-3">
                <div className="w-8 h-8 border-2 border-secondary-500 border-t-transparent rounded-full animate-spin" />
                <span className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">加载中...</span>
              </div>
            ) : visibleNotifications.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-12 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                <Bell className="w-12 h-12 mb-3 opacity-50" />
                <p className="text-sm">
                  {categoryFilter
                    ? '该分类下暂无通知'
                    : `暂无${activeTab === 'unread' ? '未读' : ''}通知`}
                </p>
              </div>
            ) : (
              <div className="divide-y divide-neutral-100 dark:divide-neutral-800">
                {visibleNotifications.map((notification) => (
                  <div
                    key={notification.id}
                    role="button"
                    tabIndex={0}
                    onClick={() => handleNotificationClick(notification)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') handleNotificationClick(notification)
                    }}
                    className={`group relative px-4 py-3 hover:bg-neutral-50 dark:bg-neutral-800 dark:hover:bg-neutral-800/50 transition-colors border-l-2 cursor-pointer focus:outline-none ${
                      notification.is_read
                        ? PRIORITY_COLORS[normalizePriority(notification)] + ' bg-neutral-50/50 dark:bg-neutral-800/30'
                        : PRIORITY_COLORS[normalizePriority(notification)] + ' bg-secondary-50/30 dark:bg-secondary-300/15'
                    }`}
                  >
                    <div className="flex gap-3">
                      {/* Icon */}
                      <div className="mt-0.5 flex-shrink-0">
                        {CATEGORY_ICONS[notification.metadata?.category ?? 'general'] || <Bell className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />}
                      </div>

                      {/* Content */}
                      <div className="flex-1 min-w-0">
                        <div className="flex items-start justify-between gap-2">
                          <h4 className={`text-sm font-medium line-clamp-1 ${
                            notification.is_read
                              ? 'text-neutral-600 dark:text-neutral-400'
                              : 'text-neutral-900 dark:text-white'
                          }`}>
                            {notification.subject || '无标题'}
                          </h4>
                          <div className="flex items-center gap-1.5 shrink-0">
                            {notification.type && (
                              <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-neutral-100 dark:bg-neutral-800 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                                {TYPE_LABELS[notification.type] || notification.type}
                              </span>
                            )}
                            {!notification.is_read && (
                              <span className="flex-shrink-0 w-2 h-2 bg-secondary-500 rounded-full mt-1.5" />
                            )}
                          </div>
                        </div>

                        <p className="text-xs text-neutral-500 dark:text-neutral-400 mt-1 line-clamp-2">
                          {stripHtml(notification.body) || '无内容'}
                        </p>

                        <div className="flex items-center gap-3 mt-2">
                          <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] flex items-center gap-1">
                            <Clock className="w-3 h-3" />
                            {formatTimeAgo(notification.created_at)}
                          </span>

                          <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                            {CHANNEL_ICONS[notification.channel || 'in_app']}
                            <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{getChannelLabel(notification.channel || 'in_app')}</span>
                          </div>
                        </div>

                        {/* Actions on hover */}
                        <div className="flex items-center gap-1 mt-2 opacity-0 group-hover:opacity-100 transition-opacity">
                          {!notification.is_read && (
                            <button
                              onClick={(e) => {
                                e.stopPropagation()
                                markAsRead(notification.id)
                              }}
                              className="flex items-center gap-1 px-2 py-1 text-xs text-secondary-600 hover:bg-secondary-50 rounded transition-colors focus:outline-none"
                            >
                              <Check className="w-3 h-3" />
                              标记已读
                            </button>
                          )}

                          {notification.link && (
                            <a
                              href={notification.link}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="flex items-center gap-1 px-2 py-1 text-xs text-success-600 hover:bg-success-50 rounded transition-colors"
                              onClick={(e) => e.stopPropagation()}
                            >
                              <ExternalLink className="w-3 h-3" />
                              查看详情
                            </a>
                          )}

                          <button
                            onClick={(e) => {
                              e.stopPropagation()
                              deleteNotification(notification.id, !notification.is_read)
                            }}
                            className="flex items-center gap-1 px-2 py-1 text-xs text-error-600 hover:bg-error-50 rounded transition-colors ml-auto focus:outline-none"
                          >
                            <Trash2 className="w-3 h-3" />
                            删除
                          </button>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Footer with Pagination */}
          {totalPages > 1 && (
            <div className="flex items-center justify-between px-4 py-3 border-t border-neutral-200 dark:border-neutral-700 bg-neutral-50 dark:bg-neutral-800/50">
              <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                第 {page} / {totalPages} 页
              </span>
              <div className="flex gap-2">
                <button
                  onClick={() => setPage((p) => Math.max(1, p - 1))}
                  disabled={page <= 1}
                  className="px-3 py-1 text-sm bg-white dark:bg-neutral-700 border rounded disabled:opacity-50 hover:bg-neutral-100 dark:bg-neutral-800 dark:hover:bg-neutral-600 focus:outline-none"
                >
                  上一页
                </button>
                <button
                  onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                  disabled={page >= totalPages}
                  className="px-3 py-1 text-sm bg-white dark:bg-neutral-700 border rounded disabled:opacity-50 hover:bg-neutral-100 dark:bg-neutral-800 dark:hover:bg-neutral-600 focus:outline-none"
                >
                  下一页
                </button>
              </div>
            </div>
          )}

          {/* Quick Link to Full Page */}
          <div className="px-4 py-2 bg-neutral-50 dark:bg-neutral-800/30 border-t border-neutral-200 dark:border-neutral-700">
            <a
              href="/notifications"
              className="block text-center text-sm text-secondary-600 hover:text-secondary-700 py-1"
              onClick={() => setIsOpen(false)}
            >
              查看所有通知 →
            </a>
          </div>
        </div>
      )}
    </div>
  )
}

function normalizePriority(notification: Notification): string {
  return notification.metadata?.priority || 'normal'
}

function stripHtml(html: string | undefined | null): string {
  if (!html) return ''
  return html.replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim()
}

function getChannelLabel(channel: string): string {
  const labels: Record<string, string> = {
    in_app: '站内信',
    email: '邮件',
    websocket: '实时推送',
    sms: '短信',
    wechat: '微信',
  }
  return labels[channel] || channel
}

/**
 * 营养成分表组件 — GB 28050-2011 标准格式
 *
 * E2E测试建议：使用Playwright测试组件渲染、交互和主题切换 — GB 28050-2011 标准格式
 *
 * 显示：能量、蛋白质、脂肪、饱和脂肪、碳水化合物、糖、膳食纤维、钠
 * 双列：每100g + 每份，含 NRV%
 */
import { useState } from 'react'
import { cn } from '@/lib/utils'

interface NutritionLabelData {
  per_100g: Record<string, number>
  per_serving: Record<string, number>
  nrv_percentages: Record<string, number>
  label_items: Array<{
    nutrient: string
    unit: string
    is_mandatory: boolean
    per_100g: number
    per_serving: number | null
    nrv_percent: number | null
    claim?: string
  }>
  serving_info: { serving_size_g: number; servings_per_container: number }
  energy_check: { match: boolean; calculated_kj: number; listed_kj: number }
  claims: string[]
  warnings: string[]
}

interface NutritionLabelProps {
  data: NutritionLabelData
  showServing?: boolean
  compact?: boolean
  className?: string
}

const NUTRIENT_NAMES_CN: Record<string, string> = {
  energy: '能量',
  protein: '蛋白质',
  fat: '脂肪',
  saturated_fat: '饱和脂肪',
  carbohydrate: '碳水化合物',
  sugar: '糖',
  dietary_fiber: '膳食纤维',
  sodium: '钠',
  calcium: '钙',
  iron: '铁',
}

export function NutritionLabel({
  data,
  showServing = true,
  compact = false,
  className,
}: NutritionLabelProps) {
  const [expanded, setExpanded] = useState(false)
  const servingSize = data.serving_info?.serving_size_g ?? 100

  // 可选营养素（默认收起）
  const optionalItems = data.label_items.filter((item) => !item.is_mandatory)
  const mandatoryItems = data.label_items.filter((item) => item.is_mandatory)

  return (
    <div className={cn('nutrition-label', className)}>
      {/* 标题栏 */}
      <div className="nutrition-label-header">
        <h3 className="nutrition-label-title">营养成分表</h3>
        <div className="nutrition-label-meta">
          <span>每份 {servingSize}g</span>
          {showServing && (
            <span className="nutrition-label-divider">|</span>
          )}
          <span>{data.serving_info?.servings_per_container ?? 1}份/容器</span>
        </div>
      </div>

      {/* 表格 */}
      <table className="nutrition-label-table">
        <thead>
          <tr>
            <th className="col-nutrient">营养成分</th>
            <th className="col-per100g">
              每100<span className="unit-label">g</span>
            </th>
            <th className="col-nrv">NRV%</th>
            {showServing && (
              <th className="col-perServing">
                每份<span className="unit-label">({servingSize}g)</span>
              </th>
            )}
          </tr>
        </thead>
        <tbody>
          {mandatoryItems.map((item) => (
            <NutritionRow key={item.nutrient} item={item} showServing={showServing} compact={compact} />
          ))}

          {/* 可选营养素（可展开） */}
          {optionalItems.length > 0 && (
            <>
              <tr>
                <td colSpan={showServing ? 4 : 3}>
                  <button
                    className="nutrition-label-toggle"
                    onClick={() => setExpanded((v) => !v)}
                  >
                    {expanded ? '▲ 收起可选项目' : '▼ 展开可选项目'}
                  </button>
                </td>
              </tr>
              {expanded &&
                optionalItems.map((item) => (
                  <NutritionRow
                    key={item.nutrient}
                    item={item}
                    showServing={showServing}
                    compact={compact}
                  />
                ))}
            </>
          )}
        </tbody>
        <tfoot>
          <tr>
            <td colSpan={showServing ? 4 : 3} className="footnote">
              * NRV = 营养素参考值（GB 28050-2011）
            </td>
          </tr>
        </tfoot>
      </table>

      {/* 营养声称 */}
      {data.claims.length > 0 && (
        <div className="nutrition-label-claims">
          <div className="nutrition-label-claims-label">营养声称</div>
          <div className="nutrition-label-claims-list">
            {data.claims.map((claim) => (
              <span key={claim} className="claim-badge">
                {claim}
              </span>
            ))}
          </div>
        </div>
      )}

      {/* 警告 */}
      {data.warnings.length > 0 && (
        <div className="nutrition-label-warnings">
          {data.warnings.map((w, i) => (
            <p key={i} className="warning-text">
              ⚠ {w}
            </p>
          ))}
        </div>
      )}
    </div>
  )
}

// ── 单行组件 ───────────────────────────────────────────────

interface NutritionRowProps {
  item: {
    nutrient: string
    unit: string
    is_mandatory: boolean
    per_100g: number
    per_serving: number | null
    nrv_percent: number | null
    claim?: string
  }
  showServing: boolean
  compact: boolean
}

function NutritionRow({ item, showServing, compact }: NutritionRowProps) {
  const cnName = NUTRIENT_NAMES_CN[item.nutrient] || item.nutrient
  const nrvColor =
    item.nrv_percent != null
      ? item.nrv_percent >= 30
        ? 'text-danger-600 dark:text-danger-600'
        : item.nrv_percent >= 15
        ? 'text-warning-600 dark:text-warning-700'
        : 'text-success-600 dark:text-success-600'
      : ''

  return (
    <tr className={cn('nutrition-row', !item.is_mandatory && 'optional-row')}>
      <td className="nutrient-name">
        <span>{cnName}</span>
        {item.claim && <span className="claim-tag">{item.claim}</span>}
      </td>
      <td className="nutrient-value">
        {formatValue(item.per_100g, item.unit)}
      </td>
      <td className={cn('nrv-cell', nrvColor)}>
        {item.nrv_percent != null ? `${item.nrv_percent}%` : '—'}
      </td>
      {showServing && (
        <td className="nutrient-value">
          {item.per_serving != null
            ? formatValue(item.per_serving, item.unit)
            : '—'}
        </td>
      )}
    </tr>
  )
}

function formatValue(value: number, unit: string): string {
  if (value === 0) return `0 ${unit}`
  const num = Math.round(value * 100) / 100
  return `${num} ${unit}`
}

/**
 * 可解释性报告展示组件
 *
 * 展示配方来源分析、贡献度、相互作用和优化依据
 */
'use client';

import React from 'react';
import { type ExplainabilityResult } from '@/api/explainability';

interface Props {
  result: ExplainabilityResult | null;
  loading?: boolean;
  error?: string;
}

const SCORE_COLOR = (score: number) => {
  if (score >= 80) return { color: 'text-success-600 dark:text-success-700', bg: 'bg-success-50 dark:bg-success-300/20', border: 'border-success-200 dark:border-success-800' };
  if (score >= 60) return { color: 'text-warning-600 dark:text-warning-700', bg: 'bg-warning-50 dark:bg-warning-300/20', border: 'border-warning-200 dark:border-warning-800' };
  return { color: 'text-error-600 dark:text-error-700', bg: 'bg-error-50 dark:bg-error-300/20', border: 'border-error-200 dark:border-error-800' };
};

const ROLE_BADGE: Record<string, string> = {
  core: '君',
  primary: '臣',
  supporting: '佐',
  moderator: '使',
};

const ROLE_COLOR: Record<string, string> = {
  core: 'bg-accent-100 dark:bg-accent-300/25 text-accent-700 dark:text-accent-700',
  primary: 'bg-secondary-100 dark:bg-secondary-300/25 text-secondary-700 dark:text-secondary-700',
  supporting: 'bg-success-100 dark:bg-success-300/25 text-success-700 dark:text-success-700',
  moderator: 'bg-neutral-100 dark:bg-neutral-700 text-neutral-600 dark:text-neutral-300',
};

export function ExplainabilityReport({ result, loading, error }: Props) {
  if (loading) {
    return (
      <div className="flex items-center gap-2 text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
        <span className="inline-block w-2 h-2 rounded-full bg-accent-500 animate-pulse" />
        生成解释报告中...
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-3 rounded-xl bg-error-50 dark:bg-error-300/20 border border-error-200 dark:border-error-800 text-sm text-error-600 dark:text-error-700">
        {error}
      </div>
    );
  }

  if (!result) return null;

  const scoreCfg = SCORE_COLOR(result.scores.overall);

  return (
    <div className="space-y-4">
      {/* 综合评分卡片 */}
      <div className={`rounded-2xl border p-5 ${scoreCfg.bg} ${scoreCfg.border}`}>
        <div className="flex items-center gap-4">
          <div className="text-center">
            <div className={`text-4xl font-bold ${scoreCfg.color}`}>
              {result.scores.overall}
            </div>
            <div className="text-xs text-neutral-500 dark:text-neutral-400 mt-1">综合评分</div>
          </div>
          <div className="flex-1 grid grid-cols-3 gap-3">
            {[
              { label: '功效匹配', value: result.scores.efficacy, color: 'text-accent-600' },
              { label: '安全评分', value: result.scores.safety, color: 'text-success-600' },
              { label: '成本评分', value: result.scores.cost, color: 'text-secondary-600' },
            ].map(({ label, value, color }) => (
              <div key={label} className="text-center">
                <div className={`text-xl font-semibold ${color}`}>{value}</div>
                <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{label}</div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* 摘要 */}
      <div className="rounded-xl border border-neutral-200 dark:border-neutral-700 p-4 bg-white dark:bg-neutral-800">
        <div className="flex items-center gap-2 mb-2">
          <span className="text-lg">📋</span>
          <h3 className="font-semibold text-neutral-900 dark:text-neutral-100">报告摘要</h3>
        </div>
        <p className="text-sm text-neutral-600 dark:text-neutral-300 leading-relaxed">
          {result.summary}
        </p>
      </div>

      {/* 君臣佐使 */}
      {result.core_ingredients.length > 0 && (
        <div className="rounded-xl border border-neutral-200 dark:border-neutral-700 p-4 bg-white dark:bg-neutral-800">
          <div className="flex items-center gap-2 mb-3">
            <span className="text-lg">🏛️</span>
            <h3 className="font-semibold text-neutral-900 dark:text-neutral-100">君臣佐使</h3>
          </div>
          <div className="space-y-2">
            {result.core_ingredients.map((ing) => (
              <div key={ing.name} className="flex items-start gap-3 p-3 rounded-lg bg-accent-50 dark:bg-accent-300/20">
                <span className={`px-2 py-0.5 rounded-full text-xs font-bold ${ROLE_COLOR['core']}`}>君</span>
                <div className="flex-1">
                  <div className="font-medium text-neutral-900 dark:text-neutral-100">{ing.name}</div>
                  {ing.mechanism && (
                    <div className="text-xs text-neutral-500 dark:text-neutral-400 mt-1">{ing.mechanism}</div>
                  )}
                  {ing.evidence && (
                    <div className="text-xs text-neutral-400 dark:text-neutral-500 italic mt-0.5">
                      依据: {ing.evidence}
                    </div>
                  )}
                </div>
              </div>
            ))}
            {result.primary_ingredients.map((ing) => (
              <div key={ing.name} className="flex items-start gap-3 p-3 rounded-lg bg-secondary-50 dark:bg-secondary-300/20">
                <span className={`px-2 py-0.5 rounded-full text-xs font-bold ${ROLE_COLOR['primary']}`}>臣</span>
                <div className="flex-1">
                  <div className="font-medium text-neutral-900 dark:text-neutral-100">{ing.name}</div>
                  {ing.mechanism && (
                    <div className="text-xs text-neutral-500 dark:text-neutral-400">{ing.mechanism}</div>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 协同效应 */}
      {result.synergies.length > 0 && (
        <div className="rounded-xl border border-neutral-200 dark:border-neutral-700 p-4 bg-white dark:bg-neutral-800">
          <div className="flex items-center gap-2 mb-3">
            <span className="text-lg">🤝</span>
            <h3 className="font-semibold text-neutral-900 dark:text-neutral-100">协同效应</h3>
          </div>
          <div className="space-y-2">
            {result.synergies.map((s, i) => (
              <div key={i} className="flex items-center gap-3 p-2 rounded-lg bg-success-50 dark:bg-success-300/20">
                <div className="flex items-center gap-1">
                  <span className="text-sm font-medium text-neutral-700 dark:text-neutral-300">{s.a}</span>
                  <span className="text-success-600 dark:text-success-700">+</span>
                  <span className="text-sm font-medium text-neutral-700 dark:text-neutral-300">{s.b}</span>
                </div>
                <div className="flex-1 text-xs text-neutral-500 dark:text-neutral-400">{s.desc}</div>
                <div className="text-xs font-mono text-success-600 dark:text-success-700">
                  强度 {Math.round(s.strength * 100)}%
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 拮抗/禁忌 */}
      {result.antagonisms.length > 0 && (
        <div className="rounded-xl border border-error-200 dark:border-error-800 p-4 bg-error-50 dark:bg-error-300/20">
          <div className="flex items-center gap-2 mb-2">
            <span className="text-lg">⚠️</span>
            <h3 className="font-semibold text-error-700 dark:text-error-700">禁忌搭配</h3>
          </div>
          {result.antagonisms.map((a, i) => (
            <div key={i} className="text-sm text-error-600 dark:text-error-700">
              {a.a} + {a.b} (强度 {Math.round(a.strength * 100)}%)
            </div>
          ))}
        </div>
      )}

      {/* 合规说明 */}
      {result.compliance_notes.length > 0 && (
        <div className="rounded-xl border border-neutral-200 dark:border-neutral-700 p-4 bg-white dark:bg-neutral-800">
          <div className="flex items-center gap-2 mb-2">
            <span className="text-lg">✅</span>
            <h3 className="font-semibold text-neutral-900 dark:text-neutral-100">合规说明</h3>
          </div>
          <div className="space-y-1 text-sm">
            {result.compliance_notes.map((note, i) => (
              <div key={i} className={`px-2 py-1 rounded ${
                note.startsWith('✓') ? 'text-success-600 dark:text-success-700' :
                note.startsWith('⚠') ? 'text-warning-600 dark:text-warning-700' :
                note.startsWith('✗') ? 'text-error-600 dark:text-error-700' :
                'text-neutral-500 dark:text-neutral-400'
              }`}>
                {note}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 建议 */}
      {result.recommendations.length > 0 && (
        <div className="rounded-xl border border-accent-200 dark:border-accent-800 p-4 bg-accent-50 dark:bg-accent-300/20">
          <div className="flex items-center gap-2 mb-2">
            <span className="text-lg">💡</span>
            <h3 className="font-semibold text-accent-700 dark:text-accent-700">改进建议</h3>
          </div>
          <ul className="space-y-1 text-sm text-neutral-700 dark:text-neutral-300">
            {result.recommendations.map((rec, i) => (
              <li key={i} className="flex items-start gap-2">
                <span className="text-accent-500 mt-0.5">•</span>
                {rec}
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}

/**
 * 报告导出组件
 *
 * 提供报告格式选择和一键下载功能
 */
'use client';

import React from 'react';
import { useReportExport, type ExportOptions } from '@/api/reportExport';
import { type ExplainabilityResult } from '@/api/explainability';
import { logger } from '@/utils/safeLogger';
import { BarChart3, CheckCircle2, Clock } from 'lucide-react';

interface Props {
  report?: ExplainabilityResult;
  formulaName: string;
  ingredients: Array<{ name: string; dosage_mg: number }>;
  targetEffects: string[];
}

type Format = 'docx' | 'pdf' | 'markdown';

const FORMAT_CONFIG: Record<Format, { label: string; icon: string; desc: string }> = {
  docx: { label: 'Word 文档', icon: '', desc: '可编辑的 Word 格式' },
  pdf: { label: 'PDF 文档', icon: '', desc: '标准 PDF 格式' },
  markdown: { label: 'Markdown', icon: '', desc: '源代码格式' },
};

export function ReportExportPanel({ report, formulaName, ingredients, targetEffects }: Props) {
  const { exportReport, exporting, error } = useReportExport();
  const [selectedFormat, setSelectedFormat] = React.useState<Format>('docx');
  const [exportedUrl, setExportedUrl] = React.useState<string | null>(null);

  const handleExport = async () => {
    try {
      const result = await exportReport({
        formula_name: formulaName,
        ingredients,
        target_effects: targetEffects,
        format: selectedFormat,
      }, selectedFormat);

      if (selectedFormat === 'markdown') {
        // Markdown 直接返回内容，保存到剪贴板
        const result = await exportReport({
          formula_name: formulaName,
          ingredients,
          target_effects: targetEffects,
          format: selectedFormat,
        }, selectedFormat) as { data?: { markdown?: string } };
        if (result.data?.markdown) {
          await navigator.clipboard.writeText(result.data.markdown);
          alert('Markdown 内容已复制到剪贴板');
        }
      } else {
        const result = await exportReport({
          formula_name: formulaName,
          ingredients,
          target_effects: targetEffects,
          format: selectedFormat,
        }, selectedFormat) as { url: string; filename: string };
        if (result.url) setExportedUrl(result.url);
      }
    } catch (err) {
      logger.error('报告导出失败:', err);
    }
  };

  return (
    <div className="rounded-2xl border border-neutral-200 dark:border-neutral-700 p-5 bg-white dark:bg-neutral-800">
      <div className="flex items-center gap-2 mb-4">
        <BarChart3 size={28} className="text-accent-600" />
        <h3 className="font-semibold text-neutral-900 dark:text-neutral-100">导出报告</h3>
      </div>

      {/* 格式选择 */}
      <div className="grid grid-cols-3 gap-3 mb-4">
        {(Object.keys(FORMAT_CONFIG) as Format[]).map((fmt) => (
          <button
            key={fmt}
            onClick={() => setSelectedFormat(fmt)}
            className={`p-3 rounded-xl border-2 transition-all text-center ${
              selectedFormat === fmt
                ? 'border-accent-500 bg-accent-50 dark:bg-accent-300/20'
                : 'border-neutral-200 dark:border-neutral-700 hover:border-accent-300'
            }`}
          >
            <div className="text-2xl mb-1">{FORMAT_CONFIG[fmt].icon}</div>
            <div className="text-sm font-medium text-neutral-900 dark:text-neutral-100">
              {FORMAT_CONFIG[fmt].label}
            </div>
            <div className="text-xs text-neutral-500 dark:text-neutral-400 mt-0.5">
              {FORMAT_CONFIG[fmt].desc}
            </div>
          </button>
        ))}
      </div>

      {/* 导出按钮 */}
      <button
        onClick={handleExport}
        disabled={exporting}
        className="w-full py-3 rounded-xl bg-accent-600 hover:bg-accent-700 disabled:bg-neutral-300 dark:disabled:bg-neutral-600 text-white font-medium transition-colors disabled:cursor-not-allowed"
      >
        {exporting ? (<><Clock size={14} className='animate-spin' /> 生成中...</>) : `导出 ${FORMAT_CONFIG[selectedFormat].label}`}
      </button>

      {/* 错误提示 */}
      {error && (
        <div className="mt-3 p-3 rounded-xl bg-error-50 dark:bg-error-300/20 border border-error-200 dark:border-error-800 text-sm text-error-600 dark:text-error-700">
          {error}
        </div>
      )}

      {/* 导出结果 */}
      {exportedUrl && (
        <a
          href={exportedUrl}
          download
          className="mt-3 flex items-center justify-center gap-2 py-3 rounded-xl border-2 border-success-300 dark:border-success-700 text-success-700 dark:text-success-700 font-medium hover:bg-success-50 dark:hover:bg-success-900/20 transition-colors"
        >
          <CheckCircle2 size={14} className="text-success-500" /> 下载报告
        </a>
      )}
    </div>
  );
}

