/**
 * 全局搜索组件 (Global Search Bar)
 *
 * 功能:
 * - Command+K 快捷键唤起
 * - 实时搜索建议
 * - 最近搜索历史
 * - 跨类型结果展示
 * - 键盘导航
 * - 高亮匹配文本
 */

import React, { useState, useEffect, useRef, useCallback } from 'react';
import {
  Search,
  X,
  Clock,
  ArrowRight,
  FileText,
  FlaskConical,
  GitBranch,
  Users,
  TrendingUp,
  Filter,
  SlidersHorizontal,
  Zap,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { useNavigate } from 'react-router-dom';
import api from '@/api/client';
import { Badge, Modal } from '@/components/ui';
import { logger } from '@/utils/safeLogger';

interface SearchResultItem {
  id: number;
  type: string;
  title: string;
  description?: string;
  url: string;
  score?: number;
}

interface SearchHistoryItem {
  keyword: string;
  timestamp: Date;
  count?: number;
}

export function GlobalSearch() {
  const [isOpen, setIsOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<Record<string, SearchResultItem[]>>({});
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [history, setHistory] = useState<SearchHistoryItem[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [activeType, setActiveType] = useState<string | null>(null);

  const inputRef = useRef<HTMLInputElement>(null);
  const navigate = useNavigate();

  // 快捷键: Cmd/Ctrl + K
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        setIsOpen(true);
        setTimeout(() => inputRef.current?.focus(), 100);
      }
      if (e.key === 'Escape') {
        setIsOpen(false);
        setQuery('');
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  // 搜索逻辑
  useEffect(() => {
    if (!query || query.length < 2) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setResults({});
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setSuggestions([]);
      return;
    }

    const timer = setTimeout(async () => {
      setIsSearching(true);
      try {
        // 并行请求：建议 + 搜索结果
        const [suggestionsRes, searchRes] = await Promise.all([
          api
            .get(`/api/v1/search/suggestions?prefix=${encodeURIComponent(query)}&type=formula`)
            .catch(() => ({ data: { suggestions: [] } })),
          api
            .get(`/api/v1/search/global?q=${encodeURIComponent(query)}&types=formula,experiment&page_size=5`)
            .catch(() => ({ data: {} })),
        ]);

        setSuggestions(suggestionsRes.data?.suggestions || []);

        if (searchRes.data?.types) {
          setResults(searchRes.data.types);
        }
      } catch (error) {
        logger.error('Search error:', error);
      } finally {
        setIsSearching(false);
      }
    }, 300);

    return () => clearTimeout(timer);
  }, [query]);

  // 加载搜索历史
  useEffect(() => {
    const saved = localStorage.getItem('rmfood_search_history');
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        // eslint-disable-next-line react-hooks/set-state-in-effect
        setHistory(parsed.slice(0, 10));
      } catch { /* 历史数据损坏时忽略 */ }
    }
  }, []);

  // 保存搜索历史
  const saveToHistory = useCallback(
    (keyword: string) => {
      const newHistory = [
        { keyword, timestamp: new Date() },
        ...history.filter((h) => h.keyword !== keyword).slice(0, 19),
      ];
      setHistory(newHistory);
      localStorage.setItem('rmfood_search_history', JSON.stringify(newHistory));
    },
    [history],
  );

  const handleSelect = (item: SearchResultItem) => {
    saveToHistory(query);
    navigate(item.url);
    setIsOpen(false);
    setQuery('');
  };

  const handleHistoryClick = (keyword: string) => {
    setQuery(keyword);
    inputRef.current?.focus();
  };

  const totalResults = Object.values(results).reduce((sum, items) => sum + items.length, 0);

  return (
    <>
      {/* 触发按钮 */}
      <button
        onClick={() => setIsOpen(true)}
        className={cn(
          'flex items-center gap-2 px-4 py-2 rounded-lg',
          'bg-neutral-100 dark:bg-neutral-800 hover:bg-neutral-200 dark:hover:bg-neutral-700',
          'text-neutral-500 dark:text-neutral-400 text-sm transition-colors',
          'border border-neutral-200 dark:border-neutral-700',
        )}
      >
        <Search size={16} />
        <span className="hidden sm:inline">搜索...</span>
        <kbd className="hidden md:inline-flex items-center px-1.5 py-0.5 rounded bg-white dark:bg-neutral-900 border border-neutral-300 dark:border-neutral-600 text-xs font-mono text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
          ⌘K
        </kbd>
      </button>

      {/* 搜索弹窗 */}
      {isOpen && (
        <Modal open={isOpen} onClose={() => setIsOpen(false)} className="p-0 max-w-2xl">
          <div className="flex flex-col h-[600px]">
            {/* 搜索输入框 */}
            <div className="flex items-center gap-3 p-4 border-b border-neutral-200 dark:border-neutral-700">
              <Search size={20} className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] flex-shrink-0" />
              <input
                ref={inputRef}
                autoFocus
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder="搜索配方、实验、原料..."
                className="flex-1 bg-transparent outline-none text-lg text-neutral-900 dark:text-white placeholder:text-neutral-400"
              />
              {(query || isSearching) && (
                <div className="w-5 h-5 border-2 border-secondary-500 border-t-transparent rounded-full animate-spin" />
              )}
              <button
                onClick={() => {
                  setIsOpen(false);
                  setQuery('');
                }}
                className="p-1 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded"
              >
                <X size={18} className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
              </button>
            </div>

            {/* 内容区域 */}
            <div className="flex-1 overflow-y-auto">
              {/* 无查询时显示历史和建议 */}
              {!query && (
                <div className="p-4 space-y-6">
                  {/* 最近搜索 */}
                  {history.length > 0 && (
                    <div>
                      <h3 className="text-xs font-semibold text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] uppercase tracking-wider mb-2 flex items-center gap-1">
                        <Clock size={12} /> 最近搜索
                      </h3>
                      <div className="space-y-1">
                        {history.slice(0, 8).map((item, i) => (
                          <button
                            key={i}
                            onClick={() => handleHistoryClick(item.keyword)}
                            className="flex items-center gap-2 w-full px-3 py-2 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-800 text-left transition-colors"
                          >
                            <Clock size={14} className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
                            <span className="text-sm text-neutral-700 dark:text-neutral-300">{item.keyword}</span>
                            <span className="ml-auto text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{formatTimeAgo(item.timestamp)}</span>
                          </button>
                        ))}
                      </div>
                    </div>
                  )}

                  {/* 热门搜索 */}
                  <div>
                    <h3 className="text-xs font-semibold text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] uppercase tracking-wider mb-2 flex items-center gap-1">
                      <TrendingUp size={12} /> 热门搜索
                    </h3>
                    <div className="flex flex-wrap gap-2">
                      {['降血糖配方', '抗氧化', '免疫调节', 'AI生成', 'TCMSP', '活性肽'].map((kw) => (
                        <button
                          key={kw}
                          onClick={() => handleHistoryClick(kw)}
                          className="px-3 py-1.5 rounded-full bg-neutral-100 dark:bg-neutral-800 text-sm text-neutral-600 dark:text-neutral-400 hover:bg-secondary-50 dark:hover:bg-secondary-900/20 hover:text-secondary-600 transition-colors"
                        >
                          {kw}
                        </button>
                      ))}
                    </div>
                  </div>

                  {/* 快捷键提示 */}
                  <div className="pt-4 border-t border-neutral-100 dark:border-neutral-800">
                    <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] text-center">
                      按 <kbd className="px-1 py-0.5 rounded bg-neutral-200 dark:bg-neutral-700 text-xs">↑↓</kbd> 导航 ·
                      <kbd className="px-1 py-0.5 rounded bg-neutral-200 dark:bg-neutral-700 text-xs">↵</kbd> 选择 ·
                      <kbd className="px-1 py-0.5 rounded bg-neutral-200 dark:bg-neutral-700 text-xs">Esc</kbd> 关闭
                    </p>
                  </div>
                </div>
              )}

              {/* 搜索结果 */}
              {query && (
                <div>
                  {/* 类型标签切换 */}
                  {totalResults > 0 && (
                    <div className="flex items-center gap-2 px-4 py-2 bg-neutral-50 dark:bg-neutral-800/50 border-b border-neutral-200 dark:border-neutral-700 overflow-x-auto">
                      <button
                        onClick={() => setActiveType(null)}
                        className={cn(
                          'px-3 py-1 rounded-full text-xs font-medium whitespace-nowrap transition-colors',
                          !activeType
                            ? 'bg-secondary-100 text-secondary-700 dark:bg-secondary-300/25 dark:text-secondary-700'
                            : 'text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-neutral-700',
                        )}
                      >
                        全部 ({totalResults})
                      </button>

                      {Object.entries(results).map(([type, items]) => (
                        <button
                          key={type}
                          onClick={() => setActiveType(activeType === type ? null : type)}
                          className={cn(
                            'px-3 py-1 rounded-full text-xs font-medium whitespace-nowrap transition-colors',
                            activeType === type
                              ? 'bg-secondary-100 text-secondary-700 dark:bg-secondary-300/25 dark:text-secondary-700'
                              : 'text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-neutral-700',
                          )}
                        >
                          {getTypeLabel(type)} ({items.length})
                        </button>
                      ))}
                    </div>
                  )}

                  {/* 结果列表 */}
                  <div className="divide-y divide-neutral-100 dark:divide-neutral-800">
                    {Object.entries(results)
                      .filter(([type]) => !activeType || activeType === type)
                      .map(([type, items]) => (
                        <div key={type}>
                          {items.map((item) => (
                            <button
                              key={`${type}-${item.id}`}
                              onClick={() => handleSelect(item)}
                              className="flex items-start gap-3 w-full px-4 py-3 hover:bg-neutral-50 dark:hover:bg-neutral-800/50 text-left transition-colors group"
                            >
                              <div
                                className={cn(
                                  'mt-0.5 w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0',
                                  getTypeColor(type),
                                )}
                              >
                                {getTypeIcon(type, 16)}
                              </div>

                              <div className="flex-1 min-w-0">
                                <div className="flex items-center gap-2">
                                  <h4 className="text-sm font-medium text-neutral-900 dark:text-white truncate group-hover:text-secondary-600 transition-colors">
                                    {highlightText(item.title, query)}
                                  </h4>
                                  <Badge size="sm" variant="neutral">
                                    {getTypeLabel(type)}
                                  </Badge>
                                </div>

                                {item.description && (
                                  <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-0.5 line-clamp-2">
                                    {highlightText(item.description.substring(0, 120), query)}
                                  </p>
                                )}
                              </div>

                              <ArrowRight
                                size={16}
                                className="mt-1 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] opacity-0 group-hover:opacity-100 transition-opacity flex-shrink-0"
                              />
                            </button>
                          ))}
                        </div>
                      ))}

                    {/* 无结果 */}
                    {totalResults === 0 && !isSearching && (
                      <div className="flex flex-col items-center justify-center py-12 text-center">
                        <Search size={48} className="text-neutral-300 dark:text-neutral-400 mb-4" />
                        <h3 className="text-sm font-medium text-neutral-900 dark:text-white mb-1">
                          未找到 "{query}" 的相关结果
                        </h3>
                        <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-4">尝试使用不同的关键词或检查拼写</p>

                        {suggestions.length > 0 && (
                          <div className="space-y-1">
                            <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-2">建议搜索:</p>
                            {suggestions.map((s, i) => (
                              <button
                                key={i}
                                onClick={() => setQuery(s)}
                                className="px-3 py-1.5 rounded-full bg-secondary-50 dark:bg-secondary-300/20 text-sm text-secondary-600 dark:text-secondary-700 hover:bg-secondary-100 dark:hover:bg-secondary-900/30 transition-colors"
                              >
                                {s}
                              </button>
                            ))}
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              )}
            </div>

            {/* 底部操作栏 */}
            {query && (
              <div className="flex items-center justify-between px-4 py-3 bg-neutral-50 dark:bg-neutral-800/50 border-t border-neutral-200 dark:border-neutral-700">
                <div className="flex items-center gap-3">
                  <button className="flex items-center gap-1.5 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-neutral-700 transition-colors">
                    <SlidersHorizontal size={14} /> 高级筛选
                  </button>
                  <button className="flex items-center gap-1.5 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-neutral-700 transition-colors">
                    <Filter size={14} /> 保存筛选
                  </button>
                </div>

                <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                  {isSearching ? '搜索中...' : `找到 ${totalResults} 条结果`}
                </div>
              </div>
            )}
          </div>
        </Modal>
      )}
    </>
  );
}

// ── 辅助函数 ──

function getTypeLabel(type: string): string {
  const labels: Record<string, string> = {
    formula: '配方',
    experiment: '实验',
    ingredient: '原料',
    workflow: '工作流',
    user: '用户',
  };
  return labels[type] || type;
}

function getTypeIcon(type: string, size = 16) {
  const icons: Record<string, any> = {
    formula: <FileText size={size} />,
    experiment: <FlaskConical size={size} />,
    workflow: <GitBranch size={size} />,
    ingredient: <Zap size={size} />,
    user: <Users size={size} />,
  };
  return icons[type] || <FileText size={size} />;
}

function getTypeColor(type: string): string {
  const colors: Record<string, string> = {
    formula: 'bg-secondary-100 text-secondary-600 dark:bg-secondary-300/25 dark:text-secondary-700',
    experiment: 'bg-accent-100 text-accent-600 dark:bg-accent-300/25 dark:text-accent-700',
    workflow: 'bg-success-100 text-success-600 dark:bg-success-300/25 dark:text-success-600',
    ingredient: 'bg-warning-100 text-warning-600 dark:bg-warning-300/25 dark:text-warning-700',
    user: 'bg-neutral-100 text-neutral-600 dark:bg-neutral-700 dark:text-neutral-400',
  };
  return colors[type] || 'bg-neutral-100 dark:bg-neutral-800 text-neutral-600';
}

function highlightText(text: string, query: string): React.ReactNode {
  if (!query) return text;

  const parts = text.split(new RegExp(`(${escapeRegExp(query)})`, 'gi'));

  return (
    <>
      {parts.map((part, i) =>
        part.toLowerCase() === query.toLowerCase() ? (
          <mark key={i} className="bg-warning-200 dark:bg-warning-800/40 text-inherit rounded px-0.5">
            {part}
          </mark>
        ) : (
          part
        ),
      )}
    </>
  );
}

function escapeRegExp(string: string): string {
  return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function formatTimeAgo(date: Date): string {
  const seconds = Math.floor((new Date().getTime() - date.getTime()) / 1000);

  if (seconds < 60) return '刚刚';
  if (seconds < 3600) return `${Math.floor(seconds / 60)}分钟前`;
  if (seconds < 86400) return `${Math.floor(seconds / 3600)}小时前`;
  return `${Math.floor(seconds / 86400)}天前`;
}

export default GlobalSearch;

