/**
 * 搜索栏组件
 * 支持：按时间检索、按主题筛选、按标签筛选、全文搜索
 */

import React, { useState, useCallback, useMemo, useEffect, useRef } from 'react';
import { Search, X, Filter, Clock, Tag, FolderOpen, ChevronDown, History, TrendingUp, ArrowRight } from 'lucide-react';
import type { SearchFilters, SearchResultType, SearchSuggestion, SearchHistoryItem } from '@/types/search.types';
import { searchService } from '@/services/searchService';
import { clsx } from 'clsx';

// 搜索类型配置
const TYPE_CONFIG: Record<SearchResultType, { label: string; color: string }> = {
  formula: { label: '配方', color: 'bg-secondary-100 text-secondary-700' },
  experiment: { label: '实验', color: 'bg-accent-100 text-accent-700' },
  herb: { label: '中药', color: 'bg-success-100 text-success-700' },
  peptide: { label: '肽', color: 'bg-warning-100 text-warning-700' },
  knowledge: { label: '知识', color: 'bg-danger-100 text-danger-700' },
};

interface SearchBarProps {
  onSearch: (filters: SearchFilters) => void;
  onSelectResult?: (item: any) => void;
  className?: string;
  showFilters?: boolean;
}

export const SearchBar: React.FC<SearchBarProps> = ({ onSearch, onSelectResult, className, showFilters = true }) => {
  const [query, setQuery] = useState('');
  const [isFocused, setIsFocused] = useState(false);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [showFilterPanel, setShowFilterPanel] = useState(false);
  const [suggestions, setSuggestions] = useState<SearchSuggestion[]>([]);
  const [searchHistory, setSearchHistory] = useState<SearchHistoryItem[]>([]);
  const [popularSearches, setPopularSearches] = useState<SearchHistoryItem[]>([]);
  const inputRef = useRef<HTMLInputElement>(null);

  // 筛选状态
  const [filters, setFilters] = useState<SearchFilters>({
    types: [],
    tags: [],
    category: '',
    dateRange: undefined,
    sortBy: 'relevance',
    sortOrder: 'desc',
  });

  // 日期范围选项
  const dateRangeOptions = [
    { label: '全部时间', value: 'all' },
    { label: '今天', value: 'today' },
    { label: '本周', value: 'week' },
    { label: '本月', value: 'month' },
    { label: '本季度', value: 'quarter' },
    { label: '本年', value: 'year' },
  ];

  const [selectedDateRange, setSelectedDateRange] = useState('all');

  // 加载历史记录和热门搜索
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setSearchHistory(searchService.getSearchHistory());
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setPopularSearches(searchService.getPopularSearches(5));
  }, []);

  // 防抖搜索建议
  useEffect(() => {
    if (query.length >= 2) {
      const timer = setTimeout(() => {
        const results = searchService.getSuggestions(query, 8);
        setSuggestions(results);
      }, 300);
      return () => clearTimeout(timer);
    } else {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setSuggestions([]);
      return;
    }
  }, [query]);

  // 执行搜索
  const handleSearch = useCallback(() => {
    if (!query.trim() && (filters.types ?? []).length === 0 && (filters.tags ?? []).length === 0 && !filters.dateRange) {
      return;
    }

    const searchFilters: SearchFilters = {
      keyword: query.trim() || undefined,
      types: (filters.types ?? []).length > 0 ? filters.types : undefined,
      tags: (filters.tags ?? []).length > 0 ? filters.tags : undefined,
      category: filters.category || undefined,
      dateRange: filters.dateRange,
      sortBy: filters.sortBy,
      sortOrder: filters.sortOrder,
    };

    onSearch(searchFilters);
    searchService.saveSearchHistory(query, searchFilters);
    setShowSuggestions(false);
  }, [query, filters, onSearch]);

  // 点击建议项
  const handleSelectSuggestion = useCallback((suggestion: SearchSuggestion) => {
    setQuery(suggestion.text);
    setShowSuggestions(false);

    const searchFilters: SearchFilters = {
      keyword: suggestion.text,
      types: [suggestion.type],
    };

    onSearch(searchFilters);
    searchService.saveSearchHistory(suggestion.text, searchFilters);

    if (onSelectResult) {
      onSelectResult(suggestion);
    }
  }, [onSearch, onSelectResult]);

  // 点击历史记录
  const handleSelectHistory = useCallback((history: SearchHistoryItem) => {
    setQuery(history.query);
    setShowSuggestions(false);

    const searchFilters: SearchFilters = {
      keyword: history.query,
      ...history.filters,
    };

    onSearch(searchFilters);
  }, [onSearch]);

  // 清除输入
  const handleClear = useCallback(() => {
    setQuery('');
    setSuggestions([]);
    inputRef.current?.focus();
  }, []);

  // 切换类型筛选
  const toggleTypeFilter = useCallback((type: SearchResultType) => {
    setFilters((prev) => {
      const types = (prev.types ?? []).includes(type)
        ? (prev.types ?? []).filter((t) => t !== type)
        : [...(prev.types ?? []), type];
      return { ...prev, types };
    });
  }, []);

  // 移除标签
  const removeTag = useCallback((tag: string) => {
    setFilters((prev) => ({ ...prev, tags: (prev.tags ?? []).filter((t) => t !== tag) }));
  }, []);

  // 设置日期范围
  const handleDateRangeChange = useCallback((value: string) => {
    setSelectedDateRange(value);

    if (value === 'all') {
      setFilters((prev) => ({ ...prev, dateRange: undefined }));
      return;
    }

    const now = new Date();
    let startDate: Date;

    switch (value) {
      case 'today':
        startDate = new Date(now.setHours(0, 0, 0, 0));
        break;
      case 'week':
        startDate = new Date(now);
        startDate.setDate(startDate.getDate() - 7);
        break;
      case 'month':
        startDate = new Date(now);
        startDate.setMonth(startDate.getMonth() - 1);
        break;
      case 'quarter':
        startDate = new Date(now);
        startDate.setMonth(startDate.getMonth() - 3);
        break;
      case 'year':
        startDate = new Date(now);
        startDate.setFullYear(startDate.getFullYear() - 1);
        break;
      default:
        startDate = now;
    }

    setFilters((prev) => ({
      ...prev,
      dateRange: {
        start: startDate.toISOString().split('T')[0],
        end: new Date().toISOString().split('T')[0],
      },
    }));
  }, []);

  // 清除所有筛选
  const clearFilters = useCallback(() => {
    setFilters({
      types: [],
      tags: [],
      category: '',
      dateRange: undefined,
      sortBy: 'relevance',
      sortOrder: 'desc',
    });
    setSelectedDateRange('all');
  }, []);

  // 是否有激活的筛选条件
  const hasActiveFilters = useMemo(() => {
    return (filters.types ?? []).length > 0 || (filters.tags ?? []).length > 0 || filters.dateRange || filters.category;
  }, [filters]);

  return (
    <div className={clsx('relative w-full', className)}>
      {/* 搜索输入框 */}
      <div
        className={clsx(
          'relative flex items-center gap-3 bg-white dark:bg-neutral-900 border rounded-lg shadow-sm transition-all duration-200',
          'focus-within:border-secondary-500 focus-within:ring-2 focus-within:ring-secondary-200',
          isFocused && 'shadow-md',
        )}
      >
        <div className="pl-4">
          <Search className="w-5 h-5 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
        </div>

        <input
          ref={inputRef}
          type="text"
          value={query}
          onChange={(e) => {
            setQuery(e.target.value);
            setShowSuggestions(true);
          }}
          onFocus={() => {
            setIsFocused(true);
            setShowSuggestions(true);
          }}
          onBlur={() => setTimeout(() => setIsFocused(false), 200)}
          onKeyDown={(e) => {
            if (e.key === 'Enter') {
              handleSearch();
            }
          }}
          placeholder="搜索配方、实验、中药、肽..."
          className="flex-1 py-3 bg-transparent border-none outline-none text-neutral-700 placeholder-neutral-400"
        />

        {query && (
          <button
            onClick={handleClear}
            className="p-1 mr-2 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-neutral-600 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        )}

        {showFilters && (
          <button
            onClick={() => setShowFilterPanel(!showFilterPanel)}
            className={clsx(
              'px-4 py-2 mr-1 rounded-lg transition-colors',
              hasActiveFilters
                ? 'bg-secondary-container text-secondary-main'
                : 'bg-neutral-100 dark:bg-neutral-800 text-neutral-600 hover:bg-neutral-200',
            )}
          >
            <Filter className="w-4 h-4" />
          </button>
        )}

        <button
          onClick={handleSearch}
          className="px-6 py-2 mr-1 bg-secondary-container text-secondary-main rounded-lg hover:bg-secondary-container transition-colors"
        >
          搜索
        </button>
      </div>

      {/* 下拉面板 */}
      {isFocused && (showSuggestions || searchHistory.length > 0) && (
        <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-neutral-900 border border-neutral-200 rounded-xl shadow-lg z-50 overflow-hidden">
          {/* 搜索建议 */}
          {suggestions.length > 0 && (
            <div className="p-2">
              <div className="px-3 py-2 text-xs font-medium text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">搜索建议</div>
              {suggestions.map((suggestion) => (
                <button
                  key={`${suggestion.type}-${suggestion.id}`}
                  onClick={() => handleSelectSuggestion(suggestion)}
                  className="w-full flex items-center gap-3 px-3 py-2 hover:bg-neutral-50 dark:bg-neutral-800 transition-colors text-left"
                >
                  <span className={clsx('px-2 py-0.5 text-xs rounded-full', TYPE_CONFIG[suggestion.type].color)}>
                    {TYPE_CONFIG[suggestion.type].label}
                  </span>
                  <span className="flex-1 text-neutral-700">{suggestion.text}</span>
                  {suggestion.hint && (
                    <span className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{suggestion.hint}</span>
                  )}
                  <ArrowRight className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
                </button>
              ))}
            </div>
          )}

          {/* 搜索历史 */}
          {(!query || suggestions.length === 0) && searchHistory.length > 0 && (
            <div className="p-2 border-t border-neutral-100">
              <div className="flex items-center justify-between px-3 py-2">
                <div className="flex items-center gap-2 text-xs font-medium text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                  <History className="w-3 h-3" />
                  搜索历史
                </div>
                <button
                  onClick={() => {
                    searchService.clearSearchHistory();
                    setSearchHistory([]);
                  }}
                  className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-error-500"
                >
                  清除
                </button>
              </div>
              {searchHistory.slice(0, 5).map((item) => (
                <button
                  key={item.id}
                  onClick={() => handleSelectHistory(item)}
                  className="w-full flex items-center gap-3 px-3 py-2 hover:bg-neutral-50 dark:bg-neutral-800 transition-colors text-left"
                >
                  <Search className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
                  <span className="flex-1 text-neutral-700">{item.query}</span>
                </button>
              ))}
            </div>
          )}

          {/* 热门搜索 */}
          {(!query || suggestions.length === 0) && popularSearches.length > 0 && (
            <div className="p-2 border-t border-neutral-100">
              <div className="flex items-center gap-2 px-3 py-2 text-xs font-medium text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                <TrendingUp className="w-3 h-3" />
                热门搜索
              </div>
              {popularSearches.map((item) => (
                <button
                  key={item.id}
                  onClick={() => handleSelectHistory(item)}
                  className="w-full flex items-center gap-3 px-3 py-2 hover:bg-neutral-50 dark:bg-neutral-800 transition-colors text-left"
                >
                  <TrendingUp className="w-4 h-4 text-warning-400" />
                  <span className="flex-1 text-neutral-700">{item.query}</span>
                </button>
              ))}
            </div>
          )}
        </div>
      )}

      {/* 筛选面板 */}
      {showFilterPanel && (
        <div className="mt-3 p-4 bg-neutral-50 dark:bg-neutral-800 rounded-xl border border-neutral-200">
          <div className="flex items-center justify-between mb-4">
            <h3 className="font-medium text-neutral-700">筛选条件</h3>
            {hasActiveFilters && (
              <button
                onClick={clearFilters}
                className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-error-500 transition-colors"
              >
                清除全部筛选
              </button>
            )}
          </div>

          {/* 类型筛选 */}
          <div className="mb-4">
            <div className="flex items-center gap-2 mb-2 text-sm font-medium text-neutral-600">
              <FolderOpen className="w-4 h-4" />
              内容类型
            </div>
            <div className="flex flex-wrap gap-2">
              {(Object.keys(TYPE_CONFIG) as SearchResultType[]).map((type) => (
                <button
                  key={type}
                  onClick={() => toggleTypeFilter(type)}
                  className={clsx(
                    'px-3 py-1.5 text-sm rounded-full border transition-colors',
                    (filters.types ?? []).includes(type)
                      ? 'border-secondary-500 bg-secondary-container text-secondary-main'
                      : 'border-neutral-200 dark:border-neutral-700 text-neutral-600 hover:border-neutral-300 dark:border-neutral-700',
                  )}
                >
                  {TYPE_CONFIG[type].label}
                </button>
              ))}
            </div>
          </div>

          {/* 日期范围 */}
          <div className="mb-4">
            <div className="flex items-center gap-2 mb-2 text-sm font-medium text-neutral-600">
              <Clock className="w-4 h-4" />
              时间范围
            </div>
            <div className="flex flex-wrap gap-2">
              {dateRangeOptions.map((option) => (
                <button
                  key={option.value}
                  onClick={() => handleDateRangeChange(option.value)}
                  className={clsx(
                    'px-3 py-1.5 text-sm rounded-full border transition-colors',
                    selectedDateRange === option.value
                      ? 'border-secondary-500 bg-secondary-container text-secondary-main'
                      : 'border-neutral-200 dark:border-neutral-700 text-neutral-600 hover:border-neutral-300 dark:border-neutral-700',
                  )}
                >
                  {option.label}
                </button>
              ))}
            </div>
          </div>

          {/* 标签筛选 */}
          <div className="mb-4">
            <div className="flex items-center gap-2 mb-2 text-sm font-medium text-neutral-600">
              <Tag className="w-4 h-4" />
              标签
            </div>
            {(filters.tags ?? []).length > 0 ? (
              <div className="flex flex-wrap gap-2">
                {(filters.tags ?? []).map((tag) => (
                  <span
                    key={tag}
                    className="flex items-center gap-1 px-3 py-1 bg-warning-100 text-warning-700 rounded-full text-sm"
                  >
                    {tag}
                    <button onClick={() => removeTag(tag)} className="hover:text-warning-900">
                      <X className="w-3 h-3" />
                    </button>
                  </span>
                ))}
              </div>
            ) : (
              <div className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">暂无标签筛选</div>
            )}
          </div>

          {/* 排序选项 */}
          <div>
            <div className="flex items-center gap-2 mb-2 text-sm font-medium text-neutral-600">
              排序方式
            </div>
            <div className="flex items-center gap-2">
              <select
                value={filters.sortBy}
                onChange={(e) =>
                  setFilters((prev) => ({ ...prev, sortBy: e.target.value as SearchFilters['sortBy'] }))
                }
                className="px-3 py-2 text-sm border border-neutral-200 dark:border-neutral-700 rounded-lg focus:outline-none focus:border-secondary-500"
              >
                <option value="relevance">相关性</option>
                <option value="createdAt">创建时间</option>
                <option value="updatedAt">更新时间</option>
              </select>
              <button
                onClick={() =>
                  setFilters((prev) => ({
                    ...prev,
                    sortOrder: prev.sortOrder === 'desc' ? 'asc' : 'desc',
                  }))
                }
                className={clsx(
                  'px-3 py-2 text-sm border border-neutral-200 rounded-lg hover:bg-neutral-100 dark:bg-neutral-800 transition-colors',
                )}
              >
                <ChevronDown className={clsx('w-4 h-4', filters.sortOrder === 'asc' && 'rotate-180')} />
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default SearchBar;

/**
 * 搜索结果组件
 * 展示搜索结果列表，支持快速选择和复用
 */

import React, { useState, useCallback } from 'react';
import { FileText, FlaskConical, Leaf, Dna, Lightbulb, Clock, Tag, ArrowRight, Check, Copy, ExternalLink } from 'lucide-react';
import type { SearchResultItem, SearchResultType } from '@/types/search.types';
import { clsx } from 'clsx';

// 类型图标配置
const TYPE_ICON_CONFIG: Record<SearchResultType, { icon: React.ReactNode; color: string }> = {
  formula: { icon: <FileText className="w-5 h-5" />, color: 'bg-secondary-100 text-secondary-600' },
  experiment: { icon: <FlaskConical className="w-5 h-5" />, color: 'bg-accent-100 text-accent-600' },
  herb: { icon: <Leaf className="w-5 h-5" />, color: 'bg-success-100 text-success-600' },
  peptide: { icon: <Dna className="w-5 h-5" />, color: 'bg-warning-100 text-warning-600' },
  knowledge: { icon: <Lightbulb className="w-5 h-5" />, color: 'bg-danger-100 text-danger-600' },
};

// 类型标签配置
const TYPE_LABEL_CONFIG: Record<SearchResultType, { label: string; color: string }> = {
  formula: { label: '配方', color: 'bg-secondary-500' },
  experiment: { label: '实验', color: 'bg-accent-500' },
  herb: { label: '中药', color: 'bg-success-500' },
  peptide: { label: '肽', color: 'bg-warning-500' },
  knowledge: { label: '知识', color: 'bg-danger-500' },
};

interface SearchResultsProps {
  results: SearchResultItem[];
  loading?: boolean;
  error?: string;
  query?: string;
  total?: number;
  onSelect: (item: SearchResultItem) => void;
  onQuickReuse?: (item: SearchResultItem) => void;
  onCopy?: (item: SearchResultItem) => void;
}

export const SearchResults: React.FC<SearchResultsProps> = ({
  results,
  loading,
  error,
  query,
  total,
  onSelect,
  onQuickReuse,
  onCopy,
}) => {
  const [selectedItems, setSelectedItems] = useState<Set<string | number>>(new Set());
  const [copiedId, setCopiedId] = useState<string | number | null>(null);

  // 切换选择状态
  const toggleSelect = useCallback(
    (item: SearchResultItem, e: React.MouseEvent) => {
      e.stopPropagation();
      setSelectedItems((prev) => {
        const newSet = new Set(prev);
        if (newSet.has(item.id)) {
          newSet.delete(item.id);
        } else {
          newSet.add(item.id);
        }
        return newSet;
      });
    },
    [],
  );

  // 选择全部
  const selectAll = useCallback(() => {
    if (selectedItems.size === results.length) {
      setSelectedItems(new Set());
    } else {
      setSelectedItems(new Set(results.map((r) => r.id)));
    }
  }, [selectedItems.size, results]);

  // 处理复制
  const handleCopy = useCallback(
    (item: SearchResultItem, e: React.MouseEvent) => {
      e.stopPropagation();
      navigator.clipboard.writeText(item.title);
      setCopiedId(item.id);
      setTimeout(() => setCopiedId(null), 2000);
      if (onCopy) {
        onCopy(item);
      }
    },
    [onCopy],
  );

  // 处理快速复用
  const handleQuickReuse = useCallback(
    (item: SearchResultItem, e: React.MouseEvent) => {
      e.stopPropagation();
      if (onQuickReuse) {
        onQuickReuse(item);
      }
    },
    [onQuickReuse],
  );

  // 格式化日期
  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleDateString('zh-CN', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
    });
  };

  // 渲染空状态
  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <div className="animate-spin rounded-full h-10 w-10 border-4 border-secondary-500 border-t-transparent" />
      </div>
    );
  }

  // 渲染错误状态
  if (error) {
    return (
      <div className="flex flex-col items-center justify-center py-16 text-error-500">
        <div className="text-4xl mb-4">加载失败</div>
        <p>{error}</p>
      </div>
    );
  }

  // 渲染无结果状态
  if (results.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-16 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
        <div className="text-4xl mb-4">暂无结果</div>
        <p>未找到与"{query}"相关的内容</p>
        <p className="text-sm mt-2">请尝试其他关键词或调整筛选条件</p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* 结果统计和选择控制 */}
      <div className="flex items-center justify-between">
        <div className="text-sm text-neutral-600">
          找到 <span className="font-semibold text-neutral-800">{total || results.length}</span> 个结果
          {query && <span className="ml-2">关于 "{query}"</span>}
        </div>
        {results.length > 1 && (
          <button
            onClick={selectAll}
            className="text-sm text-secondary-500 hover:text-secondary-600 transition-colors"
          >
            {selectedItems.size === results.length ? '取消全选' : '全选'}
          </button>
        )}
      </div>

      {/* 结果列表 */}
      <div className="space-y-3">
        {results.map((item) => (
          <div
            key={item.id}
             role="button" tabIndex={0} onClick={() => onSelect(item)}
            className={clsx(
              'group relative flex items-start gap-4 p-4 bg-white dark:bg-neutral-900 border rounded-xl cursor-pointer transition-all duration-200',
              'hover:shadow-md hover:border-secondary-200',
              selectedItems.has(item.id) && 'ring-2 ring-secondary-500 border-secondary-500',
            )}
          >
            {/* 选择复选框 */}
            {results.length > 1 && (
              <button
                onClick={(e) => toggleSelect(item, e)}
                className={clsx(
                  'mt-1 flex-shrink-0 w-5 h-5 rounded border-2 flex items-center justify-center transition-colors',
                  selectedItems.has(item.id)
                    ? 'bg-secondary-container border-secondary-500 text-secondary-main'
                    : 'border-neutral-300 dark:border-neutral-700 hover:border-secondary-400',
                )}
              >
                {selectedItems.has(item.id) && <Check className="w-3 h-3" />}
              </button>
            )}

            {/* 类型图标 */}
            <div className={clsx('flex-shrink-0 p-2 rounded-lg', TYPE_ICON_CONFIG[item.type].color)}>
              {TYPE_ICON_CONFIG[item.type].icon}
            </div>

            {/* 内容区域 */}
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2 mb-1">
                <h3 className="font-semibold text-neutral-800 group-hover:text-secondary-600 transition-colors truncate">
                  {item.title}
                </h3>
                <span className={clsx('flex-shrink-0 px-2 py-0.5 text-xs text-white rounded-full', TYPE_LABEL_CONFIG[item.type].color)}>
                  {TYPE_LABEL_CONFIG[item.type].label}
                </span>
              </div>

              {item.subtitle && (
                <p className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-2 truncate">{item.subtitle}</p>
              )}

              {item.description && (
                <p className="text-sm text-neutral-600 line-clamp-2 mb-2">{item.description}</p>
              )}

              {/* 标签和日期 */}
              <div className="flex flex-wrap items-center gap-2">
                {item.tags.length > 0 && (
                  <>
                    <div className="flex items-center gap-1 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                      <Tag className="w-3 h-3" />
                    </div>
                    {item.tags.slice(0, 3).map((tag) => (
                      <span
                        key={tag}
                        className="px-2 py-0.5 text-xs bg-neutral-100 dark:bg-neutral-800 text-neutral-600 rounded-full"
                      >
                        {tag}
                      </span>
                    ))}
                    {item.tags.length > 3 && (
                      <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">+{item.tags.length - 3}</span>
                    )}
                  </>
                )}

                <div className="flex items-center gap-1 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] ml-auto">
                  <Clock className="w-3 h-3" />
                  {formatDate(item.createdAt)}
                </div>
              </div>
            </div>

            {/* 操作按钮 */}
            <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
              {onQuickReuse && (
                <button
                  onClick={(e) => handleQuickReuse(item, e)}
                  className="p-2 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-success-600 hover:bg-success-50 rounded-lg transition-colors"
                  title="快速复用"
                >
                  <Copy className="w-4 h-4" />
                </button>
              )}
              {onCopy && (
                <button
                  onClick={(e) => handleCopy(item, e)}
                  className={clsx(
                    'p-2 rounded-lg transition-colors',
                    copiedId === item.id
                      ? 'text-success-600 bg-success-50'
                      : 'text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-secondary-600 hover:bg-secondary-50',
                  )}
                  title={copiedId === item.id ? '已复制' : '复制标题'}
                >
                  {copiedId === item.id ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                </button>
              )}
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  onSelect(item);
                }}
                className="p-2 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-secondary-600 hover:bg-secondary-50 rounded-lg transition-colors"
                title="查看详情"
              >
                <ExternalLink className="w-4 h-4" />
              </button>
            </div>

            {/* 相关性指示器 */}
            {item.relevance !== undefined && (
              <div className="absolute top-4 right-4">
                <div className="flex items-center gap-1">
                  <div className="w-16 h-1.5 bg-neutral-200 rounded-full overflow-hidden">
                    <div
                      className="h-full bg-secondary-500 rounded-full transition-all"
                      style={{ width: `${(item.relevance || 0) * 100}%` }}
                    />
                  </div>
                  <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{Math.round((item.relevance || 0) * 100)}%</span>
                </div>
              </div>
            )}
          </div>
        ))}
      </div>

      {/* 批量操作提示 */}
      {selectedItems.size > 0 && (
        <div className="fixed bottom-4 left-1/2 -translate-x-1/2 flex items-center gap-4 px-6 py-3 bg-white dark:bg-neutral-900 border border-neutral-200 rounded-lg shadow-lg z-50">
          <span className="text-sm text-neutral-600">
            已选择 <span className="font-semibold">{selectedItems.size}</span> 项
          </span>
          {onQuickReuse && (
            <button
              onClick={() => {
                const selected = results.filter((r) => selectedItems.has(r.id));
                selected.forEach((item) => onQuickReuse(item));
              }}
              className="px-4 py-2 bg-success-500 text-white rounded-lg hover:bg-success-600 transition-colors"
            >
              批量复用
            </button>
          )}
          <button
            onClick={() => setSelectedItems(new Set())}
            className="px-4 py-2 text-neutral-600 hover:bg-neutral-100 dark:bg-neutral-800 rounded-lg transition-colors"
          >
            取消选择
          </button>
        </div>
      )}
    </div>
  );
};

export default SearchResults;

import React, { useState, useCallback, useMemo } from 'react';
import {
  AlertTriangle,
  CheckCircle,
  XCircle,
  GitMerge,
  User,
  Server,
  ChevronDown,
  ChevronUp,
  Eye,
  EyeOff,
  RefreshCw,
  AlertCircle,
} from 'lucide-react';

export interface ConflictField {
  name: string;
  localValue: any;
  serverValue: any;
  baseValue?: any;
}

export interface ConflictData {
  id: string;
  entityType: string;
  entityId: string;
  conflictType: 'content_conflict' | 'delete_modify_conflict' | 'structural_conflict';
  status: 'detected' | 'auto_resolved' | 'pending_user' | 'resolved';
  localData: Record<string, any>;
  serverData: Record<string, any>;
  baseData?: Record<string, any>;
  localTimestamp?: string;
  serverTimestamp?: string;
  conflictingFields: string[];
  recommendedStrategy: 'last_write_wins' | 'union_merge' | 'manual';
  resolvedData?: Record<string, any>;
  detectedAt: string;
}

export interface ConflictResolverProps {
  conflicts: ConflictData[];
  onResolve: (conflictId: string, choice: 'local' | 'server' | 'custom', customData?: Record<string, any>) => void;
  onAutoResolve?: (conflictId: string) => void;
  onBatchResolve?: (
    resolutions: { conflictId: string; choice: 'local' | 'server' | 'custom'; customData?: Record<string, any> }[],
  ) => void;
  isLoading?: boolean;
  className?: string;
}

const conflictTypeConfig = {
  content_conflict: {
    label: '内容冲突',
    color: 'text-warning-600',
    bgColor: 'bg-warning-50',
    borderColor: 'border-warning-200',
    icon: AlertTriangle,
  },
  delete_modify_conflict: {
    label: '删除-修改冲突',
    color: 'text-error-600',
    bgColor: 'bg-error-50',
    borderColor: 'border-error-200',
    icon: XCircle,
  },
  structural_conflict: {
    label: '结构冲突',
    color: 'text-accent-600',
    bgColor: 'bg-accent-50',
    borderColor: 'border-accent-200',
    icon: AlertCircle,
  },
};

const strategyLabels = {
  last_write_wins: '最后写入优先',
  union_merge: '联合合并',
  manual: '手动解决',
};

export const ConflictResolver: React.FC<ConflictResolverProps> = ({
  conflicts,
  onResolve,
  onAutoResolve,
  onBatchResolve,
  isLoading = false,
  className = '',
}) => {
  const [expandedConflicts, setExpandedConflicts] = useState<Set<string>>(new Set());
  const [selectedResolution, setSelectedResolution] = useState<Record<string, 'local' | 'server' | 'custom'>>({});
  const [customEdits] = useState<Record<string, Record<string, any>>>({});
  const [showSensitiveData, setShowSensitiveData] = useState<Set<string>>(new Set());

  const pendingConflicts = useMemo(
    () => conflicts.filter((c) => c.status === 'pending_user' || c.status === 'detected'),
    [conflicts],
  );

  const resolvedConflicts = useMemo(
    () => conflicts.filter((c) => c.status === 'resolved' || c.status === 'auto_resolved'),
    [conflicts],
  );

  const toggleExpand = useCallback((conflictId: string) => {
    setExpandedConflicts((prev) => {
      const next = new Set(prev);
      if (next.has(conflictId)) {
        next.delete(conflictId);
      } else {
        next.add(conflictId);
      }
      return next;
    });
  }, []);

  const toggleSensitiveData = useCallback((conflictId: string) => {
    setShowSensitiveData((prev) => {
      const next = new Set(prev);
      if (next.has(conflictId)) {
        next.delete(conflictId);
      } else {
        next.add(conflictId);
      }
      return next;
    });
  }, []);

  const handleResolve = useCallback(
    (conflictId: string) => {
      const choice = selectedResolution[conflictId];
      if (!choice) return;

      if (choice === 'custom') {
        onResolve(conflictId, choice, customEdits[conflictId]);
      } else {
        onResolve(conflictId, choice);
      }
    },
    [onResolve, selectedResolution, customEdits],
  );

  const handleAutoResolveAll = useCallback(() => {
    const autoResolvable = pendingConflicts.filter((c) => c.recommendedStrategy !== 'manual');
    autoResolvable.forEach((c) => onAutoResolve?.(c.id));
  }, [pendingConflicts, onAutoResolve]);

  const handleBatchResolveLocal = useCallback(() => {
    const resolutions = pendingConflicts.map((c) => ({
      conflictId: c.id,
      choice: 'local' as const,
    }));
    onBatchResolve?.(resolutions);
  }, [pendingConflicts, onBatchResolve]);

  const handleBatchResolveServer = useCallback(() => {
    const resolutions = pendingConflicts.map((c) => ({
      conflictId: c.id,
      choice: 'server' as const,
    }));
    onBatchResolve?.(resolutions);
  }, [pendingConflicts, onBatchResolve]);

  const formatTimestamp = (ts?: string) => {
    if (!ts) return '未知时间';
    try {
      return new Date(ts).toLocaleString('zh-CN', {
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
      });
    } catch {
      return ts;
    }
  };

  const maskSensitiveData = (data: Record<string, any>, isVisible: boolean) => {
    if (isVisible) return data;

    const masked: Record<string, any> = {};
    const sensitiveFields = ['password', 'token', 'secret', 'api_key'];

    Object.entries(data).forEach(([key, value]) => {
      if (sensitiveFields.some((f) => key.toLowerCase().includes(f))) {
        masked[key] = '******';
      } else if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
        masked[key] = maskSensitiveData(value, false);
      } else {
        masked[key] = value;
      }
    });

    return masked;
  };

  const renderFieldValue = (value: any, label: string): React.ReactNode => {
    void label;
    if (value === null || value === undefined) {
      return <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] italic">空值</span>;
    }

    if (typeof value === 'boolean') {
      return <span className={value ? 'text-success-600' : 'text-error-600'}>{value ? '是' : '否'}</span>;
    }

    if (Array.isArray(value)) {
      return (
        <div className="space-y-1">
          {value.map((item, idx) => (
            <div key={idx} className="text-sm bg-neutral-50 dark:bg-neutral-800 px-2 py-1 rounded">
              {typeof item === 'object' ? JSON.stringify(item, null, 2) : String(item)}
            </div>
          ))}
        </div>
      );
    }

    if (typeof value === 'object') {
      return (
        <pre className="text-xs bg-neutral-50 dark:bg-neutral-800 p-2 rounded overflow-auto max-h-40">{JSON.stringify(value, null, 2)}</pre>
      );
    }

    return <span>{String(value)}</span>;
  };

  const renderConflictCard = (conflict: ConflictData) => {
    const isExpanded = expandedConflicts.has(conflict.id);
    const config = conflictTypeConfig[conflict.conflictType];
    const IconComponent = config.icon;
    const canAutoResolve = conflict.recommendedStrategy !== 'manual';
    const showData = showSensitiveData.has(conflict.id);

    return (
      <div key={conflict.id} className={`border rounded-lg transition-all ${config.bgColor} ${config.borderColor}`}>
        <div
          className="p-4 cursor-pointer hover:bg-opacity-80 transition-colors"
           role="button" tabIndex={0} onClick={() => toggleExpand(conflict.id)}
        >
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <IconComponent className={`w-5 h-5 ${config.color}`} />
              <div>
                <div className="font-medium text-neutral-900">
                  {conflict.entityType} #{conflict.entityId}
                </div>
                <div className={`text-sm ${config.color}`}>{config.label}</div>
              </div>
            </div>

            <div className="flex items-center gap-3">
              <span className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{conflict.conflictingFields.length} 个字段冲突</span>
              <span
                className={`px-2 py-1 text-xs rounded-full ${
                  conflict.status === 'resolved'
                    ? 'bg-success-100 text-success-700'
                    : conflict.status === 'auto_resolved'
                      ? 'bg-secondary-100 text-secondary-700'
                      : 'bg-warning-100 text-warning-700'
                }`}
              >
                {conflict.status === 'resolved'
                  ? '已解决'
                  : conflict.status === 'auto_resolved'
                    ? '自动解决'
                    : '待处理'}
              </span>
              {isExpanded ? (
                <ChevronUp className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
              ) : (
                <ChevronDown className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
              )}
            </div>
          </div>
        </div>

        {isExpanded && (
          <div className="px-4 pb-4 space-y-4">
            <div className="grid grid-cols-2 gap-4 text-sm">
              <div className="flex items-center gap-2">
                <User className="w-4 h-4 text-secondary-500" />
                <span className="text-neutral-600">本地:</span>
                <span>{formatTimestamp(conflict.localTimestamp)}</span>
              </div>
              <div className="flex items-center gap-2">
                <Server className="w-4 h-4 text-success-500" />
                <span className="text-neutral-600">服务器:</span>
                <span>{formatTimestamp(conflict.serverTimestamp)}</span>
              </div>
            </div>

            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <h4 className="font-medium text-neutral-700">冲突字段详情</h4>
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    toggleSensitiveData(conflict.id);
                  }}
                  className="text-xs text-secondary-600 hover:text-secondary-800 flex items-center gap-1"
                >
                  {showData ? <EyeOff className="w-3 h-3" /> : <Eye className="w-3 h-3" />}
                  {showData ? '隐藏敏感数据' : '显示敏感数据'}
                </button>
              </div>

              <div className="space-y-3 max-h-60 overflow-y-auto">
                {conflict.conflictingFields.map((field) => (
                  <div key={field} className="border rounded p-3 bg-white dark:bg-neutral-900">
                    <div className="font-medium text-sm mb-2 text-neutral-800">{field}</div>
                    <div className="grid grid-cols-2 gap-3">
                      <div className="space-y-1">
                        <div className="text-xs font-medium text-secondary-600 flex items-center gap-1">
                          <User className="w-3 h-3" /> 本地版本
                        </div>
                        <div className="text-sm">
                          {renderFieldValue(
                            maskSensitiveData({ [field]: conflict.localData[field] }, showData)[field],
                            field,
                          )}
                        </div>
                      </div>
                      <div className="space-y-1">
                        <div className="text-xs font-medium text-success-600 flex items-center gap-1">
                          <Server className="w-3 h-3" /> 服务器版本
                        </div>
                        <div className="text-sm">
                          {renderFieldValue(
                            maskSensitiveData({ [field]: conflict.serverData[field] }, showData)[field],
                            field,
                          )}
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {(conflict.status === 'pending_user' || conflict.status === 'detected') && (
              <div className="space-y-3 pt-2 border-t">
                <div className="text-sm font-medium text-neutral-700">选择解决方案</div>
                <div className="flex flex-wrap gap-2">
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      setSelectedResolution((prev) => ({ ...prev, [conflict.id]: 'local' }));
                    }}
                    className={`px-3 py-2 text-sm rounded-lg border transition-all ${
                      selectedResolution[conflict.id] === 'local'
                        ? 'border-secondary-500 bg-secondary-50 text-secondary-700'
                        : 'border-neutral-300 dark:border-neutral-700 hover:border-secondary-300'
                    }`}
                  >
                    <User className="w-4 h-4 inline mr-1" />
                    使用本地版本
                  </button>

                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      setSelectedResolution((prev) => ({ ...prev, [conflict.id]: 'server' }));
                    }}
                    className={`px-3 py-2 text-sm rounded-lg border transition-all ${
                      selectedResolution[conflict.id] === 'server'
                        ? 'border-success-500 bg-success-50 text-success-700'
                        : 'border-neutral-300 dark:border-neutral-700 hover:border-success-300'
                    }`}
                  >
                    <Server className="w-4 h-4 inline mr-1" />
                    使用服务器版本
                  </button>

                  {canAutoResolve && onAutoResolve && (
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        onAutoResolve(conflict.id);
                      }}
                      className="px-3 py-2 text-sm rounded-lg border border-accent-300 hover:bg-accent-50 text-accent-700 transition-all"
                    >
                      <RefreshCw className="w-4 h-4 inline mr-1" />
                      自动解决 ({strategyLabels[conflict.recommendedStrategy]})
                    </button>
                  )}
                </div>

                {selectedResolution[conflict.id] && (
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      handleResolve(conflict.id);
                    }}
                    disabled={isLoading}
                    className="px-4 py-2 bg-secondary-container text-secondary-main rounded-lg hover:bg-secondary-container disabled:opacity-50 transition-all"
                  >
                    确认解决
                  </button>
                )}
              </div>
            )}

            {conflict.status === 'resolved' && conflict.resolvedData && (
              <div className="pt-2 border-t">
                <div className="text-sm font-medium text-success-700 mb-2 flex items-center gap-1">
                  <CheckCircle className="w-4 h-4" /> 解决结果
                </div>
                <pre className="text-xs bg-success-50 p-3 rounded overflow-auto max-h-40">
                  {JSON.stringify(conflict.resolvedData, null, 2)}
                </pre>
              </div>
            )}
          </div>
        )}
      </div>
    );
  };

  if (conflicts.length === 0) {
    return (
      <div className={`text-center py-12 ${className}`}>
        <CheckCircle className="w-16 h-16 mx-auto text-success-500 mb-4" />
        <h3 className="text-lg font-medium text-neutral-900 mb-2">没有检测到冲突</h3>
        <p className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">所有数据同步正常，无需手动干预</p>
      </div>
    );
  }

  return (
    <div className={`space-y-6 ${className}`}>
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-bold text-neutral-900 flex items-center gap-2">
            <GitMerge className="w-6 h-6" />
            冲突解决中心
          </h2>
          <p className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">
            共 {conflicts.length} 个冲突（{pendingConflicts.length} 个待处理，{resolvedConflicts.length} 个已解决）
          </p>
        </div>

        {pendingConflicts.length > 0 && (
          <div className="flex gap-2">
            {pendingConflicts.some((c) => c.recommendedStrategy !== 'manual') && (
              <button
                onClick={handleAutoResolveAll}
                disabled={isLoading}
                className="px-3 py-2 text-sm bg-accent-100 text-accent-700 rounded-lg hover:bg-accent-200 disabled:opacity-50 transition-all"
              >
                <RefreshCw className="w-4 h-4 inline mr-1" />
                自动解决全部
              </button>
            )}
            <button
              onClick={handleBatchResolveLocal}
              disabled={isLoading}
              className="px-3 py-2 text-sm bg-secondary-100 text-secondary-700 rounded-lg hover:bg-secondary-200 disabled:opacity-50 transition-all"
            >
              全部使用本地
            </button>
            <button
              onClick={handleBatchResolveServer}
              disabled={isLoading}
              className="px-3 py-2 text-sm bg-success-100 text-success-700 rounded-lg hover:bg-success-200 disabled:opacity-50 transition-all"
            >
              全部使用服务器
            </button>
          </div>
        )}
      </div>

      {pendingConflicts.length > 0 && (
        <div className="space-y-3">
          <h3 className="font-semibold text-neutral-800 flex items-center gap-2">
            <AlertTriangle className="w-5 h-5 text-warning-500" />
            待解决的冲突 ({pendingConflicts.length})
          </h3>
          {pendingConflicts.map(renderConflictCard)}
        </div>
      )}

      {resolvedConflicts.length > 0 && (
        <div className="space-y-3">
          <h3 className="font-semibold text-neutral-800 flex items-center gap-2">
            <CheckCircle className="w-5 h-5 text-success-500" />
            已解决的冲突 ({resolvedConflicts.length})
          </h3>
          {resolvedConflicts.map(renderConflictCard)}
        </div>
      )}

      {isLoading && (
        <div className="flex items-center justify-center py-8">
          <RefreshCw className="w-6 h-6 animate-spin text-secondary-500 mr-2" />
          <span className="text-neutral-600">正在处理...</span>
        </div>
      )}
    </div>
  );
};

export default ConflictResolver;

