import { useState, useEffect, useRef, useCallback } from 'react'
import { useNavigate } from 'react-router-dom'
import { Search, FlaskConical, TestTubes, Leaf, Dna, ArrowRight, Command, Plus, Sparkles } from 'lucide-react'
import { useQuery } from '@tanstack/react-query'
import { searchApi, type SearchResult, type SearchSuggestion } from '@/api/search'
import { cn } from '@/lib/utils'

const TYPE_CONFIG: Record<string, { icon: typeof FlaskConical; label: string; color: string }> = {
  formula: { icon: FlaskConical, label: '配方', color: 'text-primary-700 dark:text-primary-700' },
  experiment: { icon: TestTubes, label: '实验', color: 'text-secondary-600 dark:text-secondary-700' },
  herb: { icon: Leaf, label: '药材', color: 'text-primary-700 dark:text-primary-700' },
  peptide: { icon: Dna, label: '肽', color: 'text-accent-600 dark:text-accent-700' },
}

const STATUS_LABELS: Record<string, string> = {
  draft: '草稿', pending_review: '待审核', approved: '已通过', rejected: '已驳回', archived: '已归档',
  planned: '计划中', in_progress: '进行中', completed: '已完成', failed: '已失败', cancelled: '已取消',
  food_homology: '药食同源', tcm: '中药材',
}

/** 可选择项的通用接口 */
interface SelectableItem {
  id: string | number
  type: string
}

function ResultItem({
  item,
  onSelect,
  isSelected,
  itemRef,
}: {
  item: SearchResult
  onSelect: () => void
  isSelected: boolean
  itemRef: (el: HTMLButtonElement | null) => void
}) {
  const config = TYPE_CONFIG[item.type] || TYPE_CONFIG.formula
  const Icon = config.icon

  return (
    <button
      ref={itemRef}
      onClick={onSelect}
      className={cn(
        'w-full flex items-center gap-3 px-4 py-3 text-left rounded-xl transition-all duration-150',
        'group',
        isSelected
          ? 'bg-primary-50 dark:bg-primary-300/20'
          : 'hover:bg-neutral-100 dark:hover:bg-neutral-800/70',
      )}
    >
      <div className={cn('shrink-0 w-9 h-9 rounded-lg flex items-center justify-center bg-neutral-100 dark:bg-neutral-800', config.color)}>
        <Icon size={16} />
      </div>
      <div className="flex-1 min-w-0">
        <p className={cn(
          'text-sm font-medium truncate',
          isSelected
            ? 'text-primary-700 dark:text-primary-700'
            : 'text-neutral-900 dark:text-white group-hover:text-primary-700 dark:group-hover:text-primary-300',
        )}>
          {item.title}
        </p>
        <p className="text-xs text-neutral-500 dark:text-neutral-400 truncate">{item.subtitle}</p>
      </div>
      <div className="flex items-center gap-2 shrink-0">
        {item.status && (
          <span className="text-xs font-medium px-1.5 py-0.5 rounded-full bg-neutral-100 dark:bg-neutral-800 text-neutral-500 dark:text-neutral-400">
            {STATUS_LABELS[item.status] || item.status}
          </span>
        )}
        {isSelected ? (
          <span className="text-xs font-medium px-1.5 py-0.5 rounded bg-primary-100 dark:bg-primary-300/30 text-primary-700 dark:text-primary-700">
            跳转
          </span>
        ) : (
          <ArrowRight size={14} className="text-neutral-600 dark:text-neutral-400 opacity-0 group-hover:opacity-100 transition-opacity" />
        )}
      </div>
    </button>
  )
}

/** 聚焦选中的项（自动滚动到可视区域） */
function scrollToItem(el: HTMLButtonElement | null) {
  if (!el) return
  el.scrollIntoView({ block: 'nearest', behavior: 'smooth' })
}

export default function CommandPalette() {
  const [open, setOpen] = useState(false)
  const [query, setQuery] = useState('')
  const [selectedIndex, setSelectedIndex] = useState(-1)
  const inputRef = useRef<HTMLInputElement>(null)
  const itemRefs = useRef<Map<number, HTMLButtonElement>>(new Map())
  const navigate = useNavigate()

  // ── 快捷键 Ctrl+K / Cmd+K ──
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault()
        setOpen((v) => !v)
      }
    }
    // 自定义事件：顶栏搜索按钮直接触发（避免伪造 KeyboardEvent 修饰键在 macOS 失效）
    const customHandler = () => setOpen(true)
    document.addEventListener('keydown', handler)
    document.addEventListener('rmfood:open-command-palette', customHandler)
    return () => {
      document.removeEventListener('keydown', handler)
      document.removeEventListener('rmfood:open-command-palette', customHandler)
    }
  }, [])

  // ESC 关闭
  useEffect(() => {
    if (!open) return
    const handler = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.preventDefault()
        setOpen(false)
      }
    }
    document.addEventListener('keydown', handler)
    return () => document.removeEventListener('keydown', handler)
  }, [open])

  // 聚焦输入框 + 重置状态 + Focus Trap
  useEffect(() => {
    if (open) {
      setTimeout(() => inputRef.current?.focus(), 50)
      setSelectedIndex(-1)
      itemRefs.current.clear()

      // Focus Trap: 阻止 Tab 焦点逃出命令面板
      const handleTabTrap = (e: KeyboardEvent) => {
        if (e.key !== 'Tab') return
        const focusable = document.querySelectorAll<HTMLElement>(
          '#command-palette-search, [data-command-item]',
        )
        if (focusable.length === 0) return
        const first = focusable[0]
        const last = focusable[focusable.length - 1]
        if (e.shiftKey && document.activeElement === first) {
          e.preventDefault()
          last?.focus()
        } else if (!e.shiftKey && document.activeElement === last) {
          e.preventDefault()
          first?.focus()
        }
      }
      document.addEventListener('keydown', handleTabTrap)
      return () => document.removeEventListener('keydown', handleTabTrap)
    } else {
      setQuery('')
    }
    return
  }, [open])

  // ── 搜索请求（防抖 300ms） ──
  const [debouncedQuery, setDebouncedQuery] = useState('')
  useEffect(() => {
    const timer = setTimeout(() => setDebouncedQuery(query), 300)
    return () => clearTimeout(timer)
  }, [query])

  const { data: suggestData } = useQuery({
    queryKey: ['search-suggest', debouncedQuery],
    queryFn: () => searchApi.suggest(debouncedQuery),
    enabled: open && debouncedQuery.length > 0,
  })

  const { data: searchData, isLoading: searching } = useQuery({
    queryKey: ['search-global', debouncedQuery],
    queryFn: () => searchApi.global(debouncedQuery),
    enabled: open && debouncedQuery.length > 0,
    staleTime: 0,
  })

  // ── 合并结果 ──
  const allResults: SearchResult[] = []
  if (searchData?.results) {
    if (searchData.results.formulas) allResults.push(...searchData.results.formulas)
    if (searchData.results.experiments) allResults.push(...searchData.results.experiments)
    if (searchData.results.herbs) allResults.push(...searchData.results.herbs)
    if (searchData.results.peptides) allResults.push(...searchData.results.peptides)
  }

  const suggestions = suggestData?.suggestions ?? []

  // ── 选择结果 → 跳转 ──
  const handleSelect = useCallback((item: SearchResult | SearchSuggestion) => {
    const type = item.type
    if (type === 'formula') navigate(`/formulas/${item.id}`)
    else if (type === 'experiment') navigate(`/experiments/${item.id}`)
    else if (type === 'herb') navigate('/databases?tab=herbs')
    else if (type === 'peptide') navigate('/databases?tab=peptides')
    setOpen(false)
  }, [navigate])

  // 搜索时重置选中索引
  useEffect(() => {
    setSelectedIndex(-1)
  }, [searchData, suggestData])

  // ── 键盘导航（上下箭头 + Enter） ──
  const totalItems = allResults.length > 0 ? allResults.length : suggestions.length

  const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
    if (totalItems === 0) return

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault()
        setSelectedIndex((prev) => {
          const next = prev < totalItems - 1 ? prev + 1 : 0
          scrollToItem(itemRefs.current.get(next) ?? null)
          return next
        })
        break

      case 'ArrowUp':
        e.preventDefault()
        setSelectedIndex((prev) => {
          const next = prev > 0 ? prev - 1 : totalItems - 1
          scrollToItem(itemRefs.current.get(next) ?? null)
          return next
        })
        break

      case 'Enter':
        e.preventDefault()
        if (selectedIndex >= 0 && selectedIndex < allResults.length) {
          handleSelect(allResults[selectedIndex])
        } else if (selectedIndex >= 0 && selectedIndex < suggestions.length) {
          handleSelect(suggestions[selectedIndex])
        }
        break
    }
  }, [totalItems, allResults, suggestions, selectedIndex, handleSelect])

  // 设置 item ref
  const setItemRef = useCallback((index: number) => (el: HTMLButtonElement | null) => {
    if (el) itemRefs.current.set(index, el)
    else itemRefs.current.delete(index)
  }, [])

  return (
    <>
      {/* 遮罩 */}
      {open && (
        <div
          className="fixed inset-0 z-[60] bg-black/40 backdrop-blur-sm animate-fade-in"
           role="button" tabIndex={0} onClick={() => setOpen(false)}
        />
      )}

      {/* 命令面板 */}
      <div
        className={cn(
          'fixed left-1/2 top-[15%] z-[70] w-full max-w-xl -translate-x-1/2',
          'bg-white dark:bg-neutral-900 rounded-2xl shadow-2xl border border-neutral-200 dark:border-neutral-700',
          'overflow-hidden flex flex-col',
          'transition-all duration-200 origin-top',
          open ? 'opacity-100 scale-100' : 'opacity-0 scale-95 pointer-events-none',
        )}
        style={{ maxHeight: '70vh' }}
      >
        {/* 搜索输入 */}
        <div className="flex items-center gap-3 px-4 py-3 border-b border-neutral-200 dark:border-neutral-800">
          <Search size={18} className="text-neutral-600 dark:text-neutral-400 shrink-0" />
          <input
            ref={inputRef}
            id="command-palette-search"
            name="search"
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="搜索配方、实验、药材、活性肽..."
            className="flex-1 bg-transparent text-sm text-neutral-900 dark:text-white placeholder:text-neutral-600 focus:outline-none"
            autoComplete="off"
          />
          {query && (
            <button
              onClick={() => setQuery('')}
              className="text-xs text-neutral-600 hover:text-neutral-600 dark:hover:text-neutral-600 transition-colors"
            >
              清除
            </button>
          )}
          <kbd className="shrink-0 px-1.5 py-0.5 rounded text-xs font-medium text-neutral-600 dark:text-neutral-300 bg-neutral-100 dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700">
            ESC
          </kbd>
        </div>

        {/* 结果列表 */}
        <div className="overflow-y-auto flex-1 py-2">
          {query.length === 0 ? (
            /* 空状态 - 显示快捷入口 */
            <div className="px-4 py-6 text-center">
              <div className="w-12 h-12 mx-auto mb-3 rounded-xl bg-neutral-100 dark:bg-neutral-800 flex items-center justify-center">
                <Command size={20} className="text-neutral-600 dark:text-neutral-400" />
              </div>
              <p className="text-sm text-neutral-500 dark:text-neutral-400">输入关键词开始搜索</p>
              <p className="text-xs text-neutral-600 dark:text-neutral-400 mt-1">支持搜索配方、实验、中药材、活性肽</p>

              {/* 快捷入口 */}
              <div className="mt-5 grid grid-cols-2 gap-2 max-w-xs mx-auto">
                {/* D-68：四个快捷入口 chip 在暗色下用 *-900/20 浅色蒙版 + 600 档文字，
                    实测 accent #a78bfa 3.72:1、secondary #60a5fa 4.02:1 —— 均未达 AA。
                    暗色色阶是反转的（号大越亮），统一提到 700 档后为 5.49 / 5.67。 */}
                <button
                  onClick={() => { navigate('/formulas/new'); setOpen(false) }}
                  className="flex min-h-[44px] items-center gap-2 px-3 py-2.5 rounded-xl bg-primary-50 dark:bg-primary-300/20 text-primary-700 dark:text-primary-700 hover:bg-primary-100 dark:hover:bg-primary-900/30 transition-colors text-sm font-medium"
                >
                  <Plus size={14} /> 新建配方
                </button>
                <button
                  onClick={() => { navigate('/experiments/new'); setOpen(false) }}
                  className="flex min-h-[44px] items-center gap-2 px-3 py-2.5 rounded-xl bg-accent-50 dark:bg-accent-300/20 text-accent-700 dark:text-accent-700 hover:bg-accent-100 dark:hover:bg-accent-900/30 transition-colors text-sm font-medium"
                >
                  <Plus size={14} /> 新建实验
                </button>
                <button
                  onClick={() => { navigate('/ai'); setOpen(false) }}
                  className="flex min-h-[44px] items-center gap-2 px-3 py-2.5 rounded-xl bg-warning-50 dark:bg-warning-300/20 text-warning-700 dark:text-warning-700 hover:bg-warning-100 dark:hover:bg-warning-900/30 transition-colors text-sm font-medium"
                >
                  <Sparkles size={14} /> AI 助手
                </button>
                <button
                  onClick={() => { navigate('/databases'); setOpen(false) }}
                  className="flex min-h-[44px] items-center gap-2 px-3 py-2.5 rounded-xl bg-secondary-50 dark:bg-secondary-300/20 text-secondary-700 dark:text-secondary-700 hover:bg-secondary-100 dark:hover:bg-secondary-900/30 transition-colors text-sm font-medium"
                >
                  <Dna size={14} /> 数据库
                </button>
              </div>

              <div className="mt-4 flex items-center justify-center gap-4 text-xs text-neutral-600 dark:text-neutral-400">
                <span className="flex items-center gap-1"><Leaf size={12} /> 药材</span>
                <span className="flex items-center gap-1"><FlaskConical size={12} /> 配方</span>
                <span className="flex items-center gap-1"><TestTubes size={12} /> 实验</span>
                <span className="flex items-center gap-1"><Dna size={12} /> 肽</span>
              </div>
            </div>
          ) : searching ? (
            <div className="px-4 py-6 text-center">
              <div className="inline-block w-5 h-5 border-2 border-primary-500 border-t-transparent rounded-full animate-spin" />
              <p className="text-xs text-neutral-600 dark:text-neutral-400 mt-2">搜索中...</p>
            </div>
          ) : allResults.length > 0 ? (
            <div className="space-y-0.5 px-2">
              {allResults.map((item, idx) => (
                <ResultItem
                  key={`${item.type}-${item.id}`}
                  item={item}
                  onSelect={() => handleSelect(item)}
                  isSelected={idx === selectedIndex}
                  itemRef={setItemRef(idx)}
                />
              ))}
            </div>
          ) : suggestions.length > 0 ? (
            <div className="space-y-0.5 px-2">
              {suggestions.map((s, idx) => {
                const config = TYPE_CONFIG[s.type] || TYPE_CONFIG.formula
                const Icon = config.icon
                const isSel = idx === selectedIndex
                return (
                  <button
                    key={`${s.type}-${s.id}`}
                    ref={setItemRef(idx)}
                    onClick={() => handleSelect(s)}
                    className={cn(
                      'w-full flex items-center gap-3 px-4 py-2.5 text-left rounded-xl transition-colors',
                      isSel
                        ? 'bg-primary-50 dark:bg-primary-300/20'
                        : 'hover:bg-neutral-100 dark:hover:bg-neutral-800/70',
                    )}
                  >
                    <Icon size={14} className={cn('shrink-0', config.color)} />
                    <span className={cn(
                      'text-sm',
                      isSel ? 'text-primary-700 dark:text-primary-700' : 'text-neutral-700 dark:text-neutral-400',
                    )}>
                      {s.text}
                    </span>
                    <span className="text-xs text-neutral-600 ml-auto">{s.hint}</span>
                  </button>
                )
              })}
            </div>
          ) : (
            <div className="px-4 py-8 text-center">
              <p className="text-sm text-neutral-500 dark:text-neutral-400">未找到相关结果</p>
              <p className="text-xs text-neutral-600 dark:text-neutral-400 mt-1">尝试不同的关键词</p>
            </div>
          )}
        </div>

        {/* 底部提示 */}
        {(searchData || query.length > 0) && (
          <div className="px-4 py-2 border-t border-neutral-100 dark:border-neutral-800 flex items-center justify-between">
            <span className="text-xs text-neutral-600">
              {searchData ? `共 ${searchData.total} 个结果` : '输入关键词搜索'}
            </span>
            <div className="flex items-center gap-3 text-xs text-neutral-600">
              <span className="flex items-center gap-1">
                <kbd className="px-1 py-0.5 rounded bg-neutral-100 dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 text-[9px]">↑↓</kbd>
                导航
              </span>
              <span className="flex items-center gap-1">
                <kbd className="px-1 py-0.5 rounded bg-neutral-100 dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 text-[9px]">↵</kbd>
                选择
              </span>
              <span className="flex items-center gap-1">
                <kbd className="px-1 py-0.5 rounded bg-neutral-100 dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 text-[9px]">esc</kbd>
                关闭
              </span>
            </div>
          </div>
        )}
      </div>
    </>
  )
}

/**
 * RMFOOD 设计系统 — 通用组件
 * StatusBadge / EmptyState / Skeleton / Pagination
 */
import type { ReactNode } from 'react'
import { useTranslation } from 'react-i18next'
import { cn } from '@/lib/utils'
import { ChevronLeft, ChevronRight, Inbox, FlaskConical, AlertTriangle, Lock } from 'lucide-react'

/* ═══════════════════════════════════════════
   StatusBadge 状态标签
   ═══════════════════════════════════════════ */

interface StatusBadgeProps {
  status: string
  className?: string
  size?: 'sm' | 'md'
}

const statusConfig: Record<string, { label: string; cls: string; dot?: string }> = {
  // 配方状态
  draft:          { label: '草稿',   cls: 'bg-neutral-100 text-neutral-600 dark:bg-neutral-800 dark:text-neutral-400 border border-neutral-200 dark:border-neutral-700', dot: 'bg-neutral-400' },
  pending_review: { label: '待审核', cls: 'bg-warning-50 text-warning-700 dark:bg-warning-300/25 dark:text-warning-700 border border-warning-200 dark:border-warning-800', dot: 'bg-warning-500' },
  approved:       { label: '已通过', cls: 'bg-primary-50 text-primary-700 dark:bg-primary-300/25 dark:text-primary-700 border border-primary-200 dark:border-primary-800', dot: 'bg-primary-500' },
  rejected:       { label: '已驳回', cls: 'bg-error-50 text-error-700 dark:bg-error-300/25 dark:text-error-600 border border-error-200 dark:border-error-800', dot: 'bg-danger-500' },
  archived:       { label: '已归档', cls: 'bg-neutral-100 text-neutral-500 dark:bg-neutral-800/60 dark:text-neutral-400 border border-neutral-200 dark:border-neutral-700', dot: 'bg-neutral-300' },
  // 实验状态
  planned:     { label: '计划中', cls: 'bg-info-50 text-info-700 dark:bg-info-300/25 dark:text-info-700 border border-info-200 dark:border-info-800', dot: 'bg-info-500' },
  in_progress: { label: '进行中', cls: 'bg-accent-50 text-accent-700 dark:bg-accent-300/25 dark:text-accent-700 border border-accent-200 dark:border-accent-800', dot: 'bg-accent-500' },
  completed:   { label: '已完成', cls: 'bg-primary-50 text-primary-700 dark:bg-primary-300/25 dark:text-primary-700 border border-primary-200 dark:border-primary-800', dot: 'bg-primary-500' },
  failed:      { label: '已失败', cls: 'bg-error-50 text-error-700 dark:bg-error-300/25 dark:text-error-600 border border-error-200 dark:border-error-800', dot: 'bg-danger-500' },
  cancelled:   { label: '已取消', cls: 'bg-neutral-100 text-neutral-500 dark:bg-neutral-800/60 dark:text-neutral-400 border border-neutral-200 dark:border-neutral-700', dot: 'bg-neutral-300' },
}

export function StatusBadge({ status, className, size = 'md' }: StatusBadgeProps) {
  const { t } = useTranslation()
  const key = status.toLowerCase()
  const config = statusConfig[key] ?? statusConfig[status] ?? { label: status, cls: 'bg-neutral-100 text-neutral-600 dark:bg-neutral-800 dark:text-neutral-400', dot: 'bg-neutral-400' }
  const label = t(`common.statusLabels.${key}`, { defaultValue: config.label })
  return (
    <span
      className={cn(
        'inline-flex items-center gap-1.5 rounded-full font-medium',
        size === 'sm' ? 'px-2 py-px text-xs' : 'px-2.5 py-0.5 text-xs',
        config.cls,
        className,
      )}
    >
      {config.dot && (
        <span className={cn('w-1.5 h-1.5 rounded-full shrink-0', config.dot)} />
      )}
      {label}
    </span>
  )
}

/* ═══════════════════════════════════════════
   EmptyState 空状态（增强版：支持空/错误/无权限状态）
   ═══════════════════════════════════════════ */

type EmptyStateVariant = 'empty' | 'error' | 'forbidden'

interface EmptyStateProps {
  icon?: ReactNode
  title: string
  description?: string
  action?: ReactNode
  variant?: EmptyStateVariant
  titleClassName?: string
  descriptionClassName?: string
}

const VARIANT_CONFIG: Record<EmptyStateVariant, { iconBg: string; iconColor: string; containerClass: string }> = {
  empty: {
    iconBg: 'bg-neutral-100 dark:bg-neutral-800',
    iconColor: 'text-neutral-400 dark:text-neutral-400',
    containerClass: '',
  },
  error: {
    iconBg: 'bg-error-100 dark:bg-error-300/20',
    iconColor: 'text-error-500 dark:text-error-600',
    containerClass: '',
  },
  forbidden: {
    iconBg: 'bg-warning-100 dark:bg-warning-300/20',
    iconColor: 'text-warning-600 dark:text-warning-700',
    containerClass: '',
  },
}

export function EmptyState({
  icon,
  title,
  description,
  action,
  variant = 'empty',
  titleClassName = '',
  descriptionClassName = '',
}: EmptyStateProps) {
  const config = VARIANT_CONFIG[variant]

  const defaultIcon = variant === 'error'
    ? <AlertTriangle size={48} strokeWidth={1.5} />
    : variant === 'forbidden'
      ? <Lock size={48} strokeWidth={1.5} />
      : <FlaskConical size={48} strokeWidth={1.5} />

  return (
    <div className={`flex flex-col items-center justify-center py-12 md:py-16 px-4 text-center ${config.containerClass}`}>
      <div className={`mb-4 w-16 h-16 md:w-20 md:h-20 rounded-2xl flex items-center justify-center ${config.iconBg} ${config.iconColor}`}>
        {icon ?? defaultIcon}
      </div>
      <h3 className={`text-lg md:text-xl font-semibold text-neutral-900 dark:text-neutral-100 ${titleClassName}`}>{title}</h3>
      {description && (
        <p className={`mt-2 max-w-md text-sm md:text-base text-neutral-500 dark:text-neutral-400 leading-relaxed ${descriptionClassName}`}>{description}</p>
      )}
      {action && (
        <div className="mt-6 md:mt-8">
          {action}
        </div>
      )}
    </div>
  )
}

/* ═══════════════════════════════════════════
   Skeleton 骨架屏
   ═══════════════════════════════════════════ */

interface SkeletonProps {
  className?: string
  lines?: number
}

export function Skeleton({ className, lines }: SkeletonProps) {
  if (lines && lines > 1) {
    return (
      <div className="space-y-3">
        {Array.from({ length: lines }).map((_, i) => (
          <div
            key={i}
            className={cn(
              'skeleton',
              i === lines - 1 && 'w-3/4',
              className,
            )}
          />
        ))}
      </div>
    )
  }
  return <div className={cn('skeleton', className)} />
}

/* ═══════════════════════════════════════════
   Pagination 分页
   ═══════════════════════════════════════════ */

interface PaginationProps {
  // 兼容模式: currentPage + totalPages
  currentPage?: number
  totalPages?: number
  // 标准模式: page + pageSize + total
  page?: number
  pageSize?: number
  total?: number
  onPageChange: (page: number) => void
  className?: string
}

export function Pagination({
  // 兼容模式
  currentPage,
  totalPages: tp,
  // 标准模式
  page,
  pageSize,
  total,
  onPageChange,
  className,
}: PaginationProps) {
  // 优先使用兼容模式
  const _page = currentPage ?? page ?? 1
  const totalPages = tp ?? (pageSize && total ? Math.ceil(total / pageSize) : 1)

  if (totalPages <= 1) return null

  // 生成页码：首页 ... 当前页附近 ... 末页
  const getPageNumbers = (): (number | '...')[] => {
    if (totalPages <= 7) return Array.from({ length: totalPages }, (_, i) => i + 1)
    const pages: (number | '...')[] = [1]
    if (_page > 3) pages.push('...')
    for (let i = Math.max(2, _page - 1); i <= Math.min(totalPages - 1, _page + 1); i++) {
      pages.push(i)
    }
    if (_page < totalPages - 2) pages.push('...')
    pages.push(totalPages)
    return pages
  }

  const pages = getPageNumbers()

  return (
    <nav className={cn('flex items-center justify-between gap-4', className)} aria-label="分页">
      {/* 信息 */}
      <span className="text-sm text-neutral-500 dark:text-neutral-400">
        共 <span className="font-medium text-neutral-700 dark:text-neutral-300">{total ?? (tp ? _page * 10 : 0)}</span> 条
      </span>

      {/* 页码 */}
      <div className="flex items-center gap-1">
        {/* 上一页 */}
        <button
          onClick={() => onPageChange(_page - 1)}
          disabled={_page <= 1}
          className={cn(
            'inline-flex items-center justify-center w-8 h-8 rounded-lg text-sm transition-all duration-150',
            'border border-neutral-200 dark:border-neutral-700',
            'hover:bg-neutral-100 dark:hover:bg-neutral-800 hover:border-neutral-300 dark:hover:border-neutral-600',
            'disabled:opacity-40 disabled:cursor-not-allowed disabled:hover:bg-transparent',
          )}
          aria-label="上一页"
        >
          <ChevronLeft size={16} />
        </button>

        {/* 页码按钮 */}
        {pages.map((p, i) =>
          p === '...' ? (
            <span key={`dots-${i}`} className="w-8 h-8 flex items-center justify-center text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] text-sm">
              ...
            </span>
          ) : (
            <button
              key={p}
              onClick={() => onPageChange(p)}
              className={cn(
                'w-8 h-8 rounded-lg text-sm font-medium transition-all duration-150',
                p === _page
                  ? 'bg-primary-container text-primary-main shadow-sm shadow-primary-600/20'
                  : 'text-neutral-600 dark:text-neutral-400 hover:bg-neutral-100 dark:hover:bg-neutral-800',
              )}
              aria-current={p === _page ? 'page' : undefined}
            >
              {p}
            </button>
          ),
        )}

        {/* 下一页 */}
        <button
          onClick={() => onPageChange(_page + 1)}
          disabled={_page >= totalPages}
          className={cn(
            'inline-flex items-center justify-center w-8 h-8 rounded-lg text-sm transition-all duration-150',
            'border border-neutral-200 dark:border-neutral-700',
            'hover:bg-neutral-100 dark:hover:bg-neutral-800 hover:border-neutral-300 dark:hover:border-neutral-600',
            'disabled:opacity-40 disabled:cursor-not-allowed disabled:hover:bg-transparent',
          )}
          aria-label="下一页"
        >
          <ChevronRight size={16} />
        </button>
      </div>
    </nav>
  )
}

