import * as React from'react';
import { cn } from'@/lib/utils';

interface FocusRingProps extends React.HTMLAttributes<HTMLDivElement> {
 /** 焦点环颜色 (默认使用品牌色) */
 color?: string;
 /** 焦点环宽度 (默认 2px) */
