 * AI模块统一配置管理系统
 *
 * 设计原则:
 * 1. 零硬编码 - 所有可配置参数集中管理
 * 2. 环境感知 - 支持开发/测试/生产环境切换
 * 3. 类型安全 - 完整TypeScript类型约束
 * 4. 可扩展 - 易于添加新配置项
 *
 * @version 4.0.0
 * @author RMFOOD Architecture Team
 */

// ============================================================================
// 环境类型定义
// ============================================================================

export type Environment = 'development' | 'staging' | 'production';

export interface AIConfig {
  // API配置
  api: {
    baseUrl: string;
    timeout: number;
    retryCount: number;
    retryDelay: number;
  };

  // 流式响应配置
  streaming: {
    enabled: boolean;
    chunkTimeout: number;
    maxRetries: number;
  };

  // 会话管理配置
  session: {
    maxSessions: number;
    maxMessagesPerSession: number;
    autoSaveInterval: number;
    storageKey: string;
  };

  // UI配置
  ui: {
    animationDuration: number;
    debounceDelay: number;
    maxInputLength: number;
    virtualScrollThreshold: number;
  };

  // 性能阈值
  performance: {
    fcpTarget: number;
    lcpTarget: number;
    ttiTarget: number;
    bundleSizeLimit: number;
  };

  // 功能开关
  features: {
    ragEnabled: boolean;
    intentDetection: boolean;
    multiSession: boolean;
    exportEnabled: boolean;
    offlineSupport: boolean;
  };
}

// ============================================================================
// 环境检测
// ============================================================================

function getEnvironment(): Environment {
  const env = import.meta.env?.VITE_APP_ENV || process.env?.NODE_ENV || 'development';

  if (env.includes('prod')) return 'production';
  if (env.includes('stag')) return 'staging';
  return 'development';
}

