        addChatMessage,

        // 版本管理相关
        formulaVersions,
        setFormulaVersions,
        selectedVersion,
        setSelectedVersion,

        // 模型相关
        selectedModel,
        setSelectedModel,
        useLlm,
        setUseLlm,

        // UI状态
        viewMode,
        setViewMode,
        selectedCompareIndex,
        setSelectedCompareIndex,

        // 面板状态
        showSharePanel,
        setShowSharePanel,
        showOptimizationAdvisor,
        setShowOptimizationAdvisor,
        paramPanelExpanded,
        setParamPanelExpanded,

        // 错误状态
        errorMessage,
        setErrorMessage,
        saveSuccess,
        setSaveSuccess,
      }}
    >
