/**
 * 移动端底部弹出面板组件
 * 支持拖拽调整高度、动画过渡、安全区域适配
 */

import React, { useState, useRef, useEffect } from 'react'
import { X, ChevronUp } from 'lucide-react'
import { cn } from '@/lib/utils'
import { useSafeArea } from '../useMobile'

interface MobileBottomSheetProps {
  open: boolean
  onClose: () => void
  title?: string
  children: React.ReactNode
  height?: string | number
  /** 是否可拖拽调整高度 */
  draggable?: boolean
  /** 是否显示关闭按钮 */
  showClose?: boolean
  /** 是否适配安全区域 */
  safeArea?: boolean
}

export default function MobileBottomSheet({
  open,
  onClose,
  title,
  children,
  height = '70%',
  draggable = true,
  showClose = true,
  safeArea = true,
}: MobileBottomSheetProps) {
  const [sheetHeight, setSheetHeight] = useState(height)
  const sheetRef = useRef<HTMLDivElement>(null)
  const dragStartY = useRef(0)
  const startHeight = useRef(height)
  const insets = useSafeArea()

  useEffect(() => {
    if (open) {
      document.body.style.overflow = 'hidden'
    } else {
      document.body.style.overflow = ''
    }

    return () => {
      document.body.style.overflow = ''
    }
  }, [open])

  const handleDragStart = (e: React.TouchEvent | React.MouseEvent) => {
    if (!draggable) return

    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY
    dragStartY.current = clientY
    startHeight.current = typeof sheetHeight === 'number' ? sheetHeight : parseInt(sheetHeight)
  }

  const handleDragMove = (e: React.TouchEvent | React.MouseEvent) => {
    if (!draggable || !dragStartY.current) return

    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY
    const deltaY = dragStartY.current - clientY
    const baseHeight = typeof startHeight.current === 'number' ? startHeight.current : parseFloat(startHeight.current) || 70
    const newHeight = Math.max(30, Math.min(90, baseHeight + (deltaY / window.innerHeight) * 100))
    setSheetHeight(`${newHeight}%`)
  }

  const handleDragEnd = () => {
    dragStartY.current = 0
  }

  if (!open) return null

  return (
    <div className="fixed inset-0 z-50 flex items-end justify-center">
      {/* 遮罩层 */}
      <div
        className="absolute inset-0 bg-black/50 backdrop-blur-sm transition-opacity duration-300"
         role="button" tabIndex={0} onClick={onClose}
      />

      {/* 面板 */}
      <div
        ref={sheetRef}
        className={cn(
          'relative w-full max-w-lg bg-white dark:bg-neutral-800 rounded-t-2xl shadow-2xl overflow-hidden',
          'animate-slide-up',
        )}
        style={{
          height: sheetHeight,
          paddingBottom: safeArea ? insets.bottom : undefined,
        }}
      >
        {/* 拖拽手柄 */}
        {draggable && (
          <div
            className="flex justify-center pt-3 pb-2 cursor-grab active:grabbing touch-none"
            onMouseDown={handleDragStart}
            onMouseMove={handleDragMove}
            onMouseUp={handleDragEnd}
            onTouchStart={handleDragStart}
            onTouchMove={handleDragMove}
            onTouchEnd={handleDragEnd}
          >
            <div className="w-10 h-1 rounded-full bg-neutral-300 dark:bg-neutral-600" />
          </div>
        )}

        {/* 标题栏 */}
        {(title || showClose) && (
          <div className="flex items-center justify-between px-4 py-3 border-b border-neutral-200 dark:border-neutral-700">
            {title && (
              <h3 className="text-base font-semibold text-neutral-900 dark:text-white">
                {title}
              </h3>
            )}
            {showClose && !title && (
              <div className="flex-1" />
            )}
            {showClose && (
              <button
                onClick={onClose}
                className="p-1.5 rounded-full hover:bg-neutral-100 dark:hover:bg-neutral-700 transition-all duration-200 touch-target"
                aria-label="关闭面板"
              >
                <X size={20} className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
              </button>
            )}
          </div>
        )}

        {/* 内容区 */}
        <div
          className="overflow-y-auto overscroll-contain"
          style={{ height: 'calc(100% - 60px)' }}
        >
          {children}
        </div>
      </div>
    </div>
  )
}

export { MobileBottomSheet }

/**
 * 分析页面实时数据更新 Hook — 增强版
 *
 * 优先级：
 * 1. WebSocket 实时推送（如果启用且连接成功）
 * 2. HTTP 轮询拉取真实后端数据（作为降级方案）
 *
 * 原来完全依赖模拟数据，现在对接真实后端。
 */

import { useEffect, useState, useCallback, useRef } from 'react'
import { wsService, type MessageHandler, type WebSocketMessage } from '@/services/websocket'
import { logger } from '@/utils/safeLogger'
import { envConfig } from '@/config/env'

export interface AnalyticsRealtimeData {
  type: 'kpi_update' | 'chart_update' | 'system_health' | 'activity'
  payload: Record<string, unknown>
  timestamp: number
}

export interface AnalyticsStats {
  total_formulas: number
  total_experiments: number
  active_users: number
  data_points: number
  success_rate: number
  avg_processing_time: number
}

export interface UseAnalyticsRealtimeOptions {
  enabled?: boolean
  refreshInterval?: number
  onDataUpdate?: (data: AnalyticsRealtimeData) => void
}

const BASE = envConfig.api.baseUrl

export function useAnalyticsRealtime(options: UseAnalyticsRealtimeOptions = {}) {
  const {
    enabled = true,
    refreshInterval = 30000,
    onDataUpdate,
  } = options

  const [isConnected, setIsConnected] = useState(false)
  const [isRealTime, setIsRealTime] = useState(false)
  const [lastUpdate, setLastUpdate] = useState<number>(Date.now())

  // 从真实 API 拉取的统计数据
  const [stats, setStats] = useState<AnalyticsStats>({
    total_formulas: 0,
    total_experiments: 0,
    active_users: 0,
    data_points: 0,
    success_rate: 0,
    avg_processing_time: 0,
  })

  const messageHandlerRef = useRef<MessageHandler | null>(null)
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null)
  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null)

  // ─── 从 API 拉取最新 KPI ──────────────────────────────────
  const fetchKPIs = useCallback(async () => {
    try {
      const res = await fetch(`${BASE}/analytics/kpi`, {
        credentials: 'include',
      })
      if (!res.ok) throw new Error(`HTTP ${res.status}`)
      const data = await res.json()
      const metrics = data.metrics ?? []

      const map = new Map(metrics.map((m: { id: string; value: number }) => [m.id, m.value]))

      setStats(prev => ({
        ...prev,
        total_formulas: Number(map.get('total_formulas') ?? prev.total_formulas),
        total_experiments: Number(map.get('total_experiments') ?? prev.total_experiments),
        active_users: Number(map.get('active_users') ?? prev.active_users),
        data_points: Number(map.get('ai_generations') ?? prev.data_points),
        success_rate: Number(map.get('published_formulas') ?? prev.success_rate),
        avg_processing_time: Number(map.get('storage_usage') ?? prev.avg_processing_time),
      }))
      setLastUpdate(Date.now())
    } catch (e) {
      logger.error('[useAnalyticsRealtime] fetchKPIs failed:', e)
    }
  }, [])

  // ─── WebSocket 消息处理 ───────────────────────────────────
  useEffect(() => {
    if (!enabled) return

    messageHandlerRef.current = (message: WebSocketMessage) => {
      try {
        const data: AnalyticsRealtimeData = {
          type: message.type as AnalyticsRealtimeData['type'],
          payload: message.data as Record<string, unknown>,
          timestamp: Date.now(),
        }

        if (message.type === 'data_update') {
          const entityType = message.data?.entity_type as string
          if (entityType === 'formula' || entityType === 'experiment') {
            const updates = message.data?.data as Record<string, number>
            if (updates) {
              setStats(prev => ({ ...prev, ...updates }))
              setLastUpdate(Date.now())
            }
          }
        }

        if (message.type === 'kpi_update') {
          const kpiData = message.data as Record<string, number>
          if (kpiData) {
            setStats(prev => ({ ...prev, ...kpiData }))
            setLastUpdate(Date.now())
          }
        }

        if (message.type === 'system_health') {
          logger.info('System health update', message.data)
        }

        onDataUpdate?.(data)
      } catch (error) {
        logger.error('Error processing analytics message', { error })
      }
    }

    const unsubscribe = wsService.onMessage(messageHandlerRef.current)

    wsService.connect().then((connected) => {
      setIsConnected(connected)
      setIsRealTime(connected)
      logger.info(`Analytics WebSocket ${connected ? 'connected' : 'not connected'}`)
    })

    return () => {
      unsubscribe()
    }
  }, [enabled, onDataUpdate])

  // ─── 降级方案：HTTP 轮询 ──────────────────────────────────
  useEffect(() => {
    if (!enabled) return

    // 如果 WebSocket 未连接，使用 HTTP 轮询
    if (!isRealTime) {
      // 立即拉取一次
      fetchKPIs()

      pollRef.current = setInterval(fetchKPIs, refreshInterval)
    }

    return () => {
      if (pollRef.current) {
        clearInterval(pollRef.current)
        pollRef.current = null
      }
    }
  }, [enabled, isRealTime, refreshInterval, fetchKPIs])

  // ─── 控制函数 ─────────────────────────────────────────────
  const connect = useCallback(async () => {
    const connected = await wsService.connect()
    setIsConnected(connected)
    setIsRealTime(connected)
    return connected
  }, [])

  const disconnect = useCallback(() => {
    wsService.disconnect()
    setIsConnected(false)
    setIsRealTime(false)
  }, [])

  const forceRefresh = useCallback(() => {
    if (isRealTime) {
      wsService.send({ type: 'refresh_analytics', timestamp: Date.now() })
    } else {
      fetchKPIs()
    }
  }, [isRealTime, fetchKPIs])

  const updateStats = useCallback((newStats: Partial<AnalyticsStats>) => {
    setStats(prev => ({ ...prev, ...newStats }))
    setLastUpdate(Date.now())
  }, [])

  return {
    stats,
    isConnected,
    isRealTime,
    lastUpdate,
    connect,
    disconnect,
    forceRefresh,
    updateStats,
  }
}

export interface UseRealtimeChartDataOptions {
  enabled?: boolean
  chartType: string
}

export function useRealtimeChartData(options: UseRealtimeChartDataOptions) {
  const { enabled = true, chartType } = options
  const [data, setData] = useState<Array<Record<string, string | number>>>([])
  const [isUpdating, setIsUpdating] = useState(false)

  useEffect(() => {
    if (!enabled) return

    const handler: MessageHandler = (message: WebSocketMessage) => {
      if (message.type === 'chart_update' && message.data?.chart_type === chartType) {
        setIsUpdating(true)

        setTimeout(() => {
          const newData = message.data?.data as Array<Record<string, string | number>>
          if (newData && Array.isArray(newData)) {
            setData(newData)
          }
          setIsUpdating(false)
        }, 100)
      }
    }

    const unsubscribe = wsService.subscribe(chartType, handler)

    return () => {
      unsubscribe()
    }
  }, [enabled, chartType])

  return {
    data,
    isUpdating,
  }
}

/**
 * WebSocket Hook for Real-time Analytics Updates
 *
 * Features:
 * - Auto-reconnection with exponential backoff
 * - Message queue for offline handling
 * - Connection status monitoring
 * - Custom event handlers
 * - Performance optimized
 */
import { useState, useEffect, useRef, useCallback } from 'react'
import { logger } from '@/utils/safeLogger';


interface UseWebSocketOptions {
  url: string
  reconnect?: boolean
  reconnectInterval?: number
  maxReconnectAttempts?: number
  onMessage?: (data: any) => void
  onConnectionChange?: (connected: boolean) => void
  onError?: (error: Event) => void
}

interface WebSocketState {
  connected: boolean
  connecting: boolean
  error: string | null
  lastMessage: any | null
  messageCount: number
}

export function useAnalyticsWebSocket(options: UseWebSocketOptions) {
  const {
    url,
    reconnect = true,
    reconnectInterval = 3000,
    maxReconnectAttempts = 10,
    onMessage,
    onConnectionChange,
    onError,
  } = options

  const [state, setState] = useState<WebSocketState>({
    connected: false,
    connecting: false,
    error: null,
    lastMessage: null,
    messageCount: 0,
  })

  const wsRef = useRef<WebSocket | null>(null)
  const reconnectAttemptsRef = useRef(0)
  const reconnectTimeoutRef = useRef<NodeJS.Timeout | null>(null)
  const mountedRef = useRef(true)

  const connect = useCallback(() => {
    if (!mountedRef.current) return

    setState(prev => ({ ...prev, connecting: true, error: null }))

    try {
      const ws = new WebSocket(url)
      wsRef.current = ws

      ws.onopen = () => {
        logger.info('[AnalyticsWS] 连接成功')
        reconnectAttemptsRef.current = 0

        if (mountedRef.current) {
          setState(prev => ({
            ...prev,
            connected: true,
            connecting: false,
            error: null,
          }))

          onConnectionChange?.(true)
        }

        // Subscribe to analytics channel
        ws.send(JSON.stringify({
          type: 'subscribe',
          channels: ['analytics_dashboard', 'kpi_updates', 'chart_refresh'],
        }))
      }

      ws.onmessage = (event) => {
        try {
          const data = JSON.parse(event.data)

          if (mountedRef.current) {
            setState(prev => ({
              ...prev,
              lastMessage: data,
              messageCount: prev.messageCount + 1,
            }))
          }

          onMessage?.(data)
        } catch (err) {
          logger.error('[AnalyticsWS] 消息解析失败:', err)
        }
      }

      ws.onerror = (event) => {
        logger.error('[AnalyticsWS] 连接错误:', event)
        onError?.(event)
      }

      ws.onclose = (event) => {
        logger.info(`[AnalyticsWS] 连接关闭: code=${event.code}`)

        if (mountedRef.current) {
          setState(prev => ({
            ...prev,
            connected: false,
            connecting: false,
          }))

          onConnectionChange?.(false)
        }

        // Attempt reconnection
        if (reconnect && reconnectAttemptsRef.current < maxReconnectAttempts && mountedRef.current) {
          const delay = Math.min(
            reconnectInterval * Math.pow(2, reconnectAttemptsRef.current),
            30000, // Max 30 seconds
          )

          logger.info(`[AnalyticsWS] ${delay/1000}秒后尝试重连 (${reconnectAttemptsRef.current + 1}/${maxReconnectAttempts})`)

          reconnectTimeoutRef.current = setTimeout(() => {
            reconnectAttemptsRef.current++
            connect()
          }, delay)
        }
      }

    } catch (error) {
      logger.error('[AnalyticsWS] 创建连接失败:', error)

      if (mountedRef.current) {
        setState(prev => ({
          ...prev,
          connecting: false,
          error: '无法建立连接',
        }))
      }
    }
  }, [url, reconnect, reconnectInterval, maxReconnectAttempts, onMessage, onConnectionChange, onError])

  const disconnect = useCallback(() => {
    reconnectAttemptsRef.current = maxReconnectAttempts // Stop reconnection attempts

    if (reconnectTimeoutRef.current) {
      clearTimeout(reconnectTimeoutRef.current)
      reconnectTimeoutRef.current = null
    }

    if (wsRef.current) {
      wsRef.current.close(1000, '用户主动断开')
      wsRef.current = null
    }

    if (mountedRef.current) {
      setState({
        connected: false,
        connecting: false,
        error: null,
        lastMessage: null,
        messageCount: 0,
      })

      onConnectionChange?.(false)
    }
  }, [maxReconnectAttempts, onConnectionChange])

  const sendMessage = useCallback((message: any) => {
    if (wsRef.current?.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify(message))
      return true
    }

    logger.warn('[AnalyticsWS] 无法发送消息: 连接未就绪')
    return false
  }, [])

  useEffect(() => {
    mountedRef.current = true
    connect()

    return () => {
      mountedRef.current = false
      disconnect()
    }
  }, [connect, disconnect])

  return {
    ...state,
    connect,
    disconnect,
    sendMessage,
    websocket: wsRef.current,
  }
}

export default useAnalyticsWebSocket

import { useReducer, useCallback, useRef } from 'react';
import api from '@/api/client';
import { logger } from '@/utils/safeLogger';

export type ExportFormat = 'csv' | 'excel' | 'json' | 'pdf';

export interface Permission {
  id: number;
  name: string;
  description?: string;
  resource: string;
  actions: string[];
}

export interface OperationResult {
  id: number;
  success: boolean;
  error?: string;
  data?: Record<string, unknown>;
  timestamp: number;
}

interface BulkOperationState {
  isProcessing: boolean;
  progress: number;
  totalItems: number;
  processedItems: number;
  results: OperationResult[];
  currentOperation: string | null;
  error: Error | null;
  rollbackData: Map<number, unknown>;
}

type BulkOperationAction =
  | { type: 'START_OPERATION'; payload: { operation: string; totalItems: number } }
  | { type: 'PROGRESS_UPDATE'; payload: { processed: number; result?: OperationResult } }
  | { type: 'COMPLETE_OPERATION' }
  | { type: 'SET_ERROR'; payload: Error }
  | { type: 'CLEAR_RESULTS' }
  | { type: 'STORE_ROLLBACK_DATA'; payload: { id: number; data: unknown } }
  | { type: 'CLEAR_ROLLBACK_DATA' };

const initialState: BulkOperationState = {
  isProcessing: false,
  progress: 0,
  totalItems: 0,
  processedItems: 0,
  results: [],
  currentOperation: null,
  error: null,
  rollbackData: new Map(),
};

function bulkOperationReducer(state: BulkOperationState, action: BulkOperationAction): BulkOperationState {
  switch (action.type) {
    case 'START_OPERATION':
      return {
        ...state,
        isProcessing: true,
        currentOperation: action.payload.operation,
        totalItems: action.payload.totalItems,
        processedItems: 0,
        progress: 0,
        results: [],
        error: null,
      };

    case 'PROGRESS_UPDATE': {
      const newProcessed = state.processedItems + 1;
      const newProgress = Math.round((newProcessed / state.totalItems) * 100);
      const newResults = action.payload.result ? [...state.results, action.payload.result] : state.results;

      return {
        ...state,
        processedItems: newProcessed,
        progress: newProgress,
        results: newResults,
      };
    }

    case 'COMPLETE_OPERATION':
      return {
        ...state,
        isProcessing: false,
        progress: 100,
      };

    case 'SET_ERROR':
      return {
        ...state,
        error: action.payload,
        isProcessing: false,
      };

    case 'CLEAR_RESULTS':
      return {
        ...state,
        results: [],
        error: null,
        rollbackData: new Map(),
      };

    case 'STORE_ROLLBACK_DATA': {
      const newRollbackData = new Map(state.rollbackData);
      newRollbackData.set(action.payload.id, action.payload.data);
      return {
        ...state,
        rollbackData: newRollbackData,
      };
    }

    case 'CLEAR_ROLLBACK_DATA':
      return {
        ...state,
        rollbackData: new Map(),
      };

    default:
      return state;
  }
}

interface UseBulkOperationsOptions {
  batchSize?: number;
  enableRollback?: boolean;
  onProgress?: (progress: number) => void;
  onComplete?: (results: OperationResult[]) => void;
  onError?: (error: Error) => void;
}

export function useBulkOperations(options: UseBulkOperationsOptions = {}) {
  const { batchSize = 10, enableRollback = true, onProgress, onComplete } = options;

  const [state, dispatch] = useReducer(bulkOperationReducer, initialState);
  const mountedRef = useRef(true);

  const processBatch = useCallback(
    async <T>(
      items: T[],
      processor: (item: T) => Promise<OperationResult>,
      operationName: string,
    ): Promise<OperationResult[]> => {
      if (!mountedRef.current || items.length === 0) return [];

      dispatch({
        type: 'START_OPERATION',
        payload: { operation: operationName, totalItems: items.length },
      });

      const results: OperationResult[] = [];
      let hasError = false;

      for (let i = 0; i < items.length; i += batchSize) {
        if (!mountedRef.current) break;

        const batch = items.slice(i, i + batchSize);
        const batchPromises = batch.map(async (item) => {
          try {
            const result = await processor(item);
            onProgress?.(state.progress);
            return result;
          } catch (error: any) {
            return {
              id: typeof item === 'object' && item !== null && 'id' in item ? ((item as Record<string, unknown>).id as string) : i,
              success: false,
              error: error.message || 'Unknown error',
              timestamp: Date.now(),
            };
          }
        });

        const batchResults = await Promise.all(batchPromises);
        results.push(...batchResults as OperationResult[]);

        for (const result of batchResults) {
          dispatch({ type: 'PROGRESS_UPDATE', payload: { processed: 1, result: result as OperationResult } });
        }

        if (batchResults.some((r) => !r.success)) {
          hasError = true;
        }
      }

      if (hasError && enableRollback) {
        logger.warn('Some operations failed. Rollback data available for recovery.');
      }

      dispatch({ type: 'COMPLETE_OPERATION' });
      onComplete?.(results);

      return results;
    },
    [batchSize, enableRollback, onProgress, onComplete, state.progress],
  );

  const bulkChangePermissions = useCallback(
    async (ids: number[], permissions: Partial<Permission>): Promise<void> => {
      await processBatch(
        ids,
        async (id): Promise<OperationResult> => {
          if (enableRollback) {
            try {
              const currentPerm = await api.get(`/organizations/permissions/${id}`);
              dispatch({
                type: 'STORE_ROLLBACK_DATA',
                payload: { id, data: currentPerm.data },
              });
            } catch { /* 获取回滚数据失败则跳过 */ }
          }

          await api.patch(`/organizations/permissions/${id}`, permissions);

          return {
            id,
            success: true,
            data: permissions,
            timestamp: Date.now(),
          };
        },
        'bulk_change_permissions',
      );
    },
    [processBatch, enableRollback],
  );

  const bulkExport = useCallback(
    async (ids: number[], format: ExportFormat): Promise<void> => {
      await processBatch(
        ids,
        async (id): Promise<OperationResult> => {
          const response = await api.get(`/organizations/${id}/export`, {
            params: { format },
            responseType: format === 'csv' || format === 'excel' ? 'blob' : 'json',
          });

          if (format === 'csv' || format === 'excel') {
            const blob = new Blob([response.data], {
              type: format === 'csv' ? 'text/csv' : 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            });
            const url = window.URL.createObjectURL(blob);
            const link = document.createElement('a');
            link.href = url;
            link.download = `organizations_export_${Date.now()}.${format === 'excel' ? 'xlsx' : 'csv'}`;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            window.URL.revokeObjectURL(url);
          }

          return {
            id,
            success: true,
            data: { format, exportedAt: Date.now() },
            timestamp: Date.now(),
          };
        },
        'bulk_export',
      );
    },
    [processBatch],
  );

  const bulkArchive = useCallback(
    async (ids: number[]): Promise<void> => {
      await processBatch(
        ids,
        async (id): Promise<OperationResult> => {
          if (enableRollback) {
            try {
              const currentOrg = await api.get(`/organizations/${id}`);
              dispatch({
                type: 'STORE_ROLLBACK_DATA',
                payload: { id, data: currentOrg.data },
              });
            } catch { /* 获取回滚数据失败则跳过 */ }
          }

          await api.put(`/organizations/${id}/archive`);

          return {
            id,
            success: true,
            data: { archived: true },
            timestamp: Date.now(),
          };
        },
        'bulk_archive',
      );
    },
    [processBatch, enableRollback],
  );

  const bulkDelete = useCallback(
    async (ids: number[]): Promise<void> => {
      await processBatch(
        ids,
        async (id): Promise<OperationResult> => {
          if (enableRollback) {
            try {
              const currentOrg = await api.get(`/organizations/${id}`);
              dispatch({
                type: 'STORE_ROLLBACK_DATA',
                payload: { id, data: currentOrg.data },
              });
            } catch { /* 获取回滚数据失败则跳过 */ }
          }

          await api.delete(`/organizations/${id}`);

          return {
            id,
            success: true,
            data: { deleted: true },
            timestamp: Date.now(),
          };
        },
        'bulk_delete',
      );
    },
    [processBatch, enableRollback],
  );

  const rollbackFailedOperations = useCallback(async (): Promise<boolean> => {
    if (!enableRollback || state.rollbackData.size === 0) return false;

    const failedResults = state.results.filter((r) => !r.success);
    let allRolledBack = true;

    for (const result of failedResults) {
      const rollbackInfo = state.rollbackData.get(result.id);
      if (rollbackInfo) {
        try {
          await api.put(`/organizations/${result.id}/restore`, rollbackInfo);
        } catch {
          allRolledBack = false;
        }
      }
    }

    dispatch({ type: 'CLEAR_ROLLBACK_DATA' });
    return allRolledBack;
  }, [enableRollback, state.rollbackData, state.results]);

  const clearResults = useCallback(() => {
    dispatch({ type: 'CLEAR_RESULTS' });
  }, []);

  const successCount = state.results.filter((r) => r.success).length;
  const failureCount = state.results.filter((r) => !r.success).length;
  const isComplete = !state.isProcessing && state.results.length > 0;

  return {
    isProcessing: state.isProcessing,
    progress: state.progress,
    results: state.results,
    error: state.error,
    currentOperation: state.currentOperation,

    bulkChangePermissions,
    bulkExport,
    bulkArchive,
    bulkDelete,

    rollbackFailedOperations,
    clearResults,

    successCount,
    failureCount,
    isComplete,
    totalItems: state.totalItems,
    processedItems: state.processedItems,
  };
}

export type UseBulkOperationsReturn = ReturnType<typeof useBulkOperations>;

/**
 * 单元格编辑管理 Hook
 *
 * 提供完整的行内数据编辑功能：
 * - 编辑模式管理 (单单元格/批量/添加行)
 * - 撤销/重做栈 (最多50步)
 * - 行选择与批量操作
 * - 变更追踪与持久化
 * - 数据校验集成
 */

import { useReducer, useCallback, useRef } from 'react';
import type {
  EditingState,
  EditingAction,
  CellEditState,
  CellChangeRecord,
  UndoRedoItem,
  FieldEditorConfig,
  UseCellEditorReturn,
} from '@/types/editing.types';
import { EditMode } from '@/types/editing.types';
import axios from 'axios';


import { logger } from '@/utils/safeLogger';
/** 最大撤销/重做步数 */
const MAX_UNDO_STACK_SIZE = 50;

/**
 * 创建空的编辑状态
 */
function createInitialState(data: Record<string, any>[]): EditingState {
  return {
    mode: EditMode.NONE,
    editingCell: null,
    selectedRows: new Set(),
    changes: [],
    undoStack: [],
    redoStack: [],
    currentData: JSON.parse(JSON.stringify(data)),
    originalData: JSON.parse(JSON.stringify(data)),
  };
}

/**
 * 生成变更ID
 */
function generateChangeId(): string {
  return `change-${Date.now().toString(36)}-${Math.random().toString(36).substring(2, 8)}`;
}

/**
 * 生成快照ID
 */
function generateSnapshotId(): string {
  return `snapshot-${Date.now().toString(36)}`;
}

/**
 * 创建快照 (用于撤销)
 */
function createSnapshot(
  data: Record<string, any>[],
  description: string,
  changes?: CellChangeRecord[],
): UndoRedoItem {
  return {
    snapshotId: generateSnapshotId(),
    timestamp: Date.now(),
    description,
    data: JSON.parse(JSON.stringify(data)),
    changes,
  };
}

/**
 * 编辑状态 Reducer
 */
function editingReducer(state: EditingState, action: EditingAction): EditingState {
  switch (action.type) {
    // ====== 进入编辑模式 ======
    case 'ENTER_EDIT_MODE':
      // 如果已有编辑中的单元格，先保存它（隐式确认）
      if (state.editingCell && state.editingCell.isModified) {
        const change = createChangeFromCell(
          state.editingCell,
          state.currentData,
          'edit',
        );

        const updatedData = [...state.currentData];
        if (state.editingCell.rowIndex < updatedData.length) {
          updatedData[state.editingCell.rowIndex] = {
            ...updatedData[state.editingCell.rowIndex],
            [state.editingCell.columnKey]: state.editingCell.currentValue,
          };
        }

        const snapshot = createSnapshot(updatedData, `编辑单元格 [${state.editingCell.columnKey}]`, [change]);

        return {
          ...state,
          mode: EditMode.CELL,
          editingCell: action.cell,
          changes: [...state.changes, change],
          currentData: updatedData,
          undoStack: [...state.undoStack, snapshot],
          redoStack: [],  // 新操作清空重做栈
        };
      }

      return {
        ...state,
        mode: EditMode.CELL,
        editingCell: action.cell,
        redoStack: [],
      };

    // ====== 退出编辑模式 ======
    case 'EXIT_EDIT_MODE':
      if (action.save && state.editingCell?.isModified) {
        // 保存当前编辑的值
        const change = createChangeFromCell(
          state.editingCell,
          state.currentData,
          'edit',
        );

        const updatedData = [...state.currentData];
        if (state.editingCell.rowIndex < updatedData.length) {
          updatedData[state.editingCell.rowIndex] = {
            ...updatedData[state.editingCell.rowIndex],
            [state.editingCell.columnKey]: state.editingCell.currentValue,
          };
        }

        const snapshot = createSnapshot(updatedData, '退出并保存', [change]);

        return {
          ...state,
          mode: EditMode.NONE,
          editingCell: null,
          changes: [...state.changes, change],
          currentData: updatedData,
          undoStack: [...state.undoStack, snapshot],
          redoStack: [],
        };
      }

      // 不保存，直接退出
      return {
        ...state,
        mode: EditMode.NONE,
        editingCell: null,
        redoStack: [],
      };

    // ====== 更新单元格值 ======
    case 'UPDATE_CELL_VALUE': {
      if (!state.editingCell) return state;

      const isModified = state.editingCell.originalValue !== action.value;

      return {
        ...state,
        editingCell: {
          ...state.editingCell,
          currentValue: action.value,
          isModified,
        },
      };
    }

    // ====== 行选择操作 ======
    case 'SELECT_ROWS': {
      const newSelection = new Set(state.selectedRows);
      const rowArray = Array.isArray(action.rows)
        ? action.rows
        : [...(action.rows)];

      for (const row of rowArray) {
        if (action.toggle) {
          if (newSelection.has(row)) {
            newSelection.delete(row);
          } else {
            newSelection.add(row);
          }
        } else {
          newSelection.add(row);
        }
      }

      return { ...state, selectedRows: newSelection };
    }

    case 'DESELECT_ALL':
      return { ...state, selectedRows: new Set() };

    // ====== 批量编辑模式 ======
    case 'ENTER_BATCH_MODE':
      return {
        ...state,
        mode: EditMode.BATCH,
        editingCell: null,
        redoStack: [],
      };

    case 'EXIT_BATCH_MODE':
      return {
        ...state,
        mode: EditMode.NONE,
        redoStack: [],
      };

    // ====== 应用批量修改 ======
    case 'APPLY_BATCH_CHANGE': {
      const { columnKey, value } = action;
      const affectedRows = Array.from(state.selectedRows).sort((a, b) => a - b);

      const changes: CellChangeRecord[] = [];
      const updatedData = [...state.currentData];

      for (const rowIndex of affectedRows) {
        if (rowIndex < updatedData.length) {
          const oldValue = updatedData[rowIndex]?.[columnKey];

          changes.push({
            id: generateChangeId(),
            rowId: rowIndex,
            columnKey,
            columnLabel: columnKey,
            oldValue,
            newValue: value,
            timestamp: Date.now(),
            actionType: 'batch_edit',
            isSaved: false,
          });

          updatedData[rowIndex] = {
            ...updatedData[rowIndex],
            [columnKey]: value,
          };
        }
      }

      const snapshot = createSnapshot(
        updatedData,
        `批量修改 ${columnKey} (${affectedRows.length}行)`,
        changes,
      );

      return {
        ...state,
        mode: EditMode.NONE,
        changes: [...state.changes, ...changes],
        currentData: updatedData,
        selectedRows: new Set(),  // 批量操作后清除选择
        undoStack: [...state.undoStack, snapshot],
        redoStack: [],
      };
    }

    // ====== 保存所有变更 ======
    case 'SAVE_CHANGES': {
      // 标记所有变更为已保存
      const savedChanges = state.changes.map(c => ({ ...c, isSaved: true }));

      return {
        ...state,
        changes: savedChanges,
        undoStack: [],  // 保存后清空撤销栈（可选）
        redoStack: [],
      };
    }

    // ====== 放弃所有变更 ======
    case 'DISCARD_CHANGES':
      if (state.undoStack.length > 0) {
        // 恢复到最近的快照（通常是原始状态或上次保存点）
        const lastSnapshot = state.undoStack[state.undoStack.length - 1]
        return {
          ...state,
          mode: EditMode.NONE,
          editingCell: null,
          changes: [],
          currentData: JSON.parse(JSON.stringify(lastSnapshot.data)),
          selectedRows: new Set(),
          redoStack: [],
        };
      }

      // 无历史记录，恢复到原始数据
      return {
        ...createInitialState(state.originalData),
        mode: EditMode.NONE,
      };

    // ====== 撤销 ======
    case 'UNDO': {
      if (state.undoStack.length === 0) return state;

      // 弹出当前状态的快照到重做栈
      const undoCurrentSnapshot = createSnapshot(
        state.currentData,
        '撤销前状态',
        state.changes.slice(-10),  // 只保留最近10条变更记录
      );

      // 弹出上一个快照
      const newUndoStack = [...state.undoStack];
      const previousSnapshot = newUndoStack.pop()!

      return {
        ...state,
        currentData: previousSnapshot.data,
        changes: previousSnapshot.changes || [],
        undoStack: newUndoStack,
        redoStack: [...state.redoStack, undoCurrentSnapshot].slice(-MAX_UNDO_STACK_SIZE),
        mode: EditMode.NONE,
        editingCell: null,
        selectedRows: new Set(),
      };
    }

    // ====== 重做 ======
    case 'REDO': {
      if (state.redoStack.length === 0) return state;

      // 弹出重做栈顶部的快照
      const newRedoStack = [...state.redoStack];
      const redoSnapshot = newRedoStack.pop()!

      // 将当前状态压入撤销栈
      const redoCurrentSnapshot = createSnapshot(
        state.currentData,
        '重做前状态',
        state.changes.slice(-10),
      )

      return {
        ...state,
        currentData: redoSnapshot.data,
        changes: redoSnapshot.changes || [],
        undoStack: [...state.undoStack, redoCurrentSnapshot].slice(-MAX_UNDO_STACK_SIZE),
        redoStack: newRedoStack,
        mode: EditMode.NONE,
        editingCell: null,
        selectedRows: new Set(),
      };
    }

    // ====== 重置为原始数据 ======
    case 'RESET_DATA':
      return createInitialState(state.originalData);

    // ====== 设置新数据 ======
    case 'SET_DATA':
      return {
        ...state,
        currentData: action.data,
        originalData: action.data,
        changes: [],
        undoStack: [],
        redoStack: [],
        mode: EditMode.NONE,
        editingCell: null,
        selectedRows: new Set(),
      };

    default:
      return state;
  }
}

/**
 * 从 CellEditState 创建 ChangeRecord
 */
function createChangeFromCell(
  cell: CellEditState,
  _data: Record<string, any>[],
  actionType: CellChangeRecord['actionType'],
): CellChangeRecord {

  return {
    id: generateChangeId(),
    rowId: cell.rowIndex,
    columnKey: cell.columnKey,
    columnLabel: cell.columnKey,
    oldValue: cell.originalValue,
    newValue: cell.currentValue,
    timestamp: Date.now(),
    actionType,
    isSaved: false,
  };
}

/**
 * 列视图管理 Hook 主函数
 */
export function useCellEditor(
  initialData: Record<string, any>[],
  fieldConfigs: FieldEditorConfig[],
): UseCellEditorReturn {
  const [state, dispatch] = useReducer(editingReducer, initialData, createInitialState);

  const batchColumnKeyRef = useRef<string>('');

  // === 单元格编辑 ===

  /**
   * 开始编辑指定单元格
   */
  const startEditing = useCallback((rowIndex: number, columnKey: string, value: any) => {
    dispatch({
      type: 'ENTER_EDIT_MODE',
      cell: {
        rowIndex,
        columnKey,
        originalValue: value,
        currentValue: value,
        isModified: false,
        enteredAt: Date.now(),
      },
    });
  }, [fieldConfigs]);

  /**
   * 更新编辑中的值
   */
  const updateValue = useCallback((value: any) => {
    dispatch({ type: 'UPDATE_CELL_VALUE', value });
  }, []);

  /**
   * 确认编辑 (保存并退出)
   */
  const confirmEdit = useCallback(() => {
    dispatch({ type: 'EXIT_EDIT_MODE', save: true });
  }, []);

  /**
   * 取消编辑 (不保存并退出)
   */
  const cancelEdit = useCallback(() => {
    dispatch({ type: 'EXIT_EDIT_MODE', save: false });
  }, []);

  // === 选择操作 ===

  /**
   * 选中某行
   */
  const selectRow = useCallback((rowIndex: number) => {
    dispatch({ type: 'SELECT_ROWS', rows: [rowIndex], toggle: false });
  }, []);

  /**
   * 切换行的选中状态
   */
  const toggleRowSelection = useCallback((rowIndex: number) => {
    dispatch({ type: 'SELECT_ROWS', rows: [rowIndex], toggle: true });
  }, []);

  /**
   * 全选
   */
  const selectAll = useCallback(() => {
    const allIndices = state.currentData.map((_, idx) => idx);
    dispatch({ type: 'SELECT_ROWS', rows: allIndices, toggle: false });
  }, [state.currentData]);

  /**
   * 清除所有选择
   */
  const clearSelection = useCallback(() => {
    dispatch({ type: 'DESELECT_ALL' });
  }, []);

  /**
   * 检查某行是否被选中
   */
  const isRowSelected = useCallback((rowIndex: number): boolean => {
    return state.selectedRows.has(rowIndex);
  }, [state.selectedRows]);

  /**
   * 获取选中行数量
   */
  const getSelectedCount = useCallback((): number => {
    return state.selectedRows.size;
  }, [state.selectedRows]);

  // === 批量操作 ===

  /**
   * 进入批量编辑模式
   */
  const enterBatchMode = useCallback((columnKey: string) => {
    if (state.selectedRows.size === 0) {
      logger.warn('[useCellEditor] 请先选择要修改的行');
      return;
    }
    batchColumnKeyRef.current = columnKey;
    dispatch({ type: 'ENTER_BATCH_MODE' });
  }, [state.selectedRows.size]);

  /**
   * 退出批量编辑模式
   */
  const exitBatchMode = useCallback(() => {
    dispatch({ type: 'EXIT_BATCH_MODE' });
  }, []);

  /**
   * 应用批量修改
   */
  const applyBatchChange = useCallback((value: any) => {
    dispatch({ type: 'APPLY_BATCH_CHANGE', columnKey: batchColumnKeyRef.current, value });
  }, []);

  // === 撤销/重做 ===

  /**
   * 撤销上一步操作
   */
  const undo = useCallback((): boolean => {
    if (!canUndo()) return false;
    dispatch({ type: 'UNDO' });
    return true;
  }, []);

  /**
   * 重做下一步操作
   */
  const redo = useCallback((): boolean => {
    if (!canRedo()) return false;
    dispatch({ type: 'REDO' });
    return true;
  }, []);

  /**
   * 是否可以撤销
   */
  const canUndo = useCallback((): boolean => {
    return state.undoStack.length > 0;
  }, [state.undoStack.length]);

  /**
   * 是否可以重做
   */
  const canRedo = useCallback((): boolean => {
    return state.redoStack.length > 0;
  }, [state.redoStack.length]);

  // === 变更追踪 ===

  /**
   * 获取所有变更记录
   */
  const getChanges = useCallback((): CellChangeRecord[] => {
    return [...state.changes];
  }, [state.changes]);

  /**
   * 获取变更数量
   */
  const getChangesCount = useCallback((): number => {
    return state.changes.length;
  }, [state.changes]);

  /**
   * 是否有未保存的变更
   */
  const hasUnsavedChanges = useCallback((): boolean => {
    return state.changes.some(c => !c.isSaved);
  }, [state.changes]);

  /**
   * 保存所有变更 (模拟调用外部API)
   */
  const saveAllChanges = useCallback(async (): Promise<boolean> => {
    try {
      if (state.changes.length === 0) {
        dispatch({ type: 'SAVE_CHANGES' });
        return true;
      }

      await axios.post('/api/v1/ai/formulas/batch-update', { changes: state.changes });

      dispatch({ type: 'SAVE_CHANGES' });
      return true;
    } catch (error: any) {
      logger.error('[useCellEditor] 保存失败:', error);
      return false;
    }
  }, [state.changes]);

  /**
   * 放弃所有未保存的变更
   */
  const discardAllChanges = useCallback(() => {
    dispatch({ type: 'DISCARD_CHANGES' });
  }, []);

  // === 数据管理 ===

  /**
   * 更新整个数据集
   */
  const setData = useCallback((data: Record<string, any>[]) => {
    dispatch({ type: 'SET_DATA', data });
  }, []);

  /**
   * 重置为原始数据
   */
  const resetToOriginal = useCallback(() => {
    dispatch({ type: 'RESET_DATA' });
  }, []);

  /**
   * 获取当前数据副本
   */
  const getCurrentData = useCallback((): Record<string, any>[] => {
    return state.currentData.map(row => ({ ...row }));
  }, [state.currentData]);

  return {
    // 状态
    state,

    // 单元格编辑
    startEditing,
    updateValue,
    confirmEdit,
    cancelEdit,

    // 选择操作
    selectRow,
    toggleRowSelection,
    selectAll,
    clearSelection,
    isRowSelected,
    getSelectedCount,

    // 批量操作
    enterBatchMode,
    exitBatchMode,
    applyBatchChange,

    // 撤销/重做
    undo,
    redo,
    canUndo,
    canRedo,

    // 变更追踪
    getChanges,
    getChangesCount,
    hasUnsavedChanges,
    saveAllChanges,
    discardAllChanges,

    // 数据管理
    setData,
    resetToOriginal,
    getCurrentData,
  };
}

export default useCellEditor;

import { logger } from '@/utils/safeLogger';
import { useState, useCallback, useRef, useEffect } from 'react';
import type {
  Collaborator,
  Annotation,
  CommentThread,
  VersionInfo,
  ShareSettings,
  AccessStatistics,
  CollaborationSession,
  RealtimeEvent,
} from '../types/collaboration.types';
import { CollaborationPermission, ShareAccessType } from '../types/collaboration.types';

export interface UseCollaborationReturn {
  session: CollaborationSession | null;
  isConnected: boolean;

  collaborators: Collaborator[];
  annotations: Annotation[];
  commentThreads: CommentThread[];
  versions: VersionInfo[];

  joinSession: (reportId: string) => Promise<void>;
  leaveSession: () => void;

  addCollaborator: (email: string, permission: CollaborationPermission) => Promise<boolean>;
  removeCollaborator: (userId: string) => Promise<void>;
  updatePermission: (userId: string, permission: CollaborationPermission) => Promise<void>;

  addAnnotation: (annotation: Omit<Annotation, 'id' | 'createdAt' | 'updatedAt'>) => Promise<Annotation>;
  updateAnnotation: (id: string, updates: Partial<Annotation>) => Promise<void>;
  deleteAnnotation: (id: string) => Promise<void>;
  resolveAnnotation: (id: string) => Promise<void>;

  addCommentThread: (
    thread: Omit<CommentThread, 'id' | 'createdAt' | 'updatedAt' | 'annotations'>,
  ) => Promise<CommentThread>;
  replyToComment: (threadId: string, content: string) => Promise<void>;

  saveVersion: (message?: string) => Promise<VersionInfo>;
  getVersion: (versionId: string) => Promise<VersionInfo>;
  compareVersions: (version1Id: string, version2Id: string) => Promise<VersionDiff>;
  restoreVersion: (versionId: string) => Promise<void>;

  shareSettings: ShareSettings;
  updateShareSettings: (settings: Partial<ShareSettings>) => Promise<void>;
  generateShareLink: () => Promise<string>;

  accessStats: AccessStatistics | null;
  fetchAccessStats: () => Promise<void>;

  realtimeEvents: RealtimeEvent[];
}

export interface VersionDiff {
  version1: VersionInfo;
  version2: VersionInfo;
  changes: {
    type: 'add' | 'modify' | 'delete';
    sectionId: string;
    content: string;
    highlight?: 'green' | 'red' | 'yellow';
  }[];
}

export function useCollaboration(): UseCollaborationReturn {
  const [session, setSession] = useState<CollaborationSession | null>(null);
  const [isConnected, setIsConnected] = useState(false);
  const [collaborators, setCollaborators] = useState<Collaborator[]>([]);
  const [annotations, setAnnotations] = useState<Annotation[]>([]);
  const [commentThreads, setCommentThreads] = useState<CommentThread[]>([]);
  const [versions, setVersions] = useState<VersionInfo[]>([]);
  const [shareSettings, setShareSettings] = useState<ShareSettings>({
    isPublic: false,
    accessType: ShareAccessType.LINK,
    allowDownload: true,
    allowCopy: true,
    allowComment: true,
  });
  const [accessStats, setAccessStats] = useState<AccessStatistics | null>(null);
  const [realtimeEvents, setRealtimeEvents] = useState<RealtimeEvent[]>([]);

  const wsRef = useRef<WebSocket | null>(null);
  const eventBufferRef = useRef<RealtimeEvent[]>([]);

  useEffect(() => {
    return () => {
      if (wsRef.current) {
        wsRef.current.close();
      }
    };
  }, []);

  const joinSession = useCallback(async (reportId: string): Promise<void> => {
    try {
      setIsConnected(true);

      const mockSession: CollaborationSession = {
        reportId,
        sessionId: `session-${Date.now()}`,
        collaborators: [
          {
            id: 'user-current',
            name: '当前用户',
            email: 'current@rmfood.com',
            permission: CollaborationPermission.ADMIN,
            joinedAt: new Date().toISOString(),
            lastActiveAt: new Date().toISOString(),
            isOnline: true,
          },
        ],
        activeAnnotations: [],
        currentVersion: {
          id: 'version-1',
          versionNumber: 1,
          createdBy: {
            id: 'user-current',
            name: '当前用户',
            email: '',
            permission: CollaborationPermission.ADMIN,
            joinedAt: '',
            lastActiveAt: '',
            isOnline: true,
          },
          createdAt: new Date().toISOString(),
          message: '初始版本',
          changes: [],
          fileSize: 0,
          checksum: '',
        },
        cursorPositions: new Map(),
        selectionRanges: new Map(),
        lastSyncAt: new Date().toISOString(),
      };

      setSession(mockSession);
      setCollaborators(mockSession.collaborators);
      setVersions([mockSession.currentVersion]);
    } catch (error) {
      logger.error('Failed to join collaboration session:', error);
      throw error;
    }
  }, []);

  const leaveSession = useCallback(() => {
    if (wsRef.current) {
      wsRef.current.close();
      wsRef.current = null;
    }
    setSession(null);
    setIsConnected(false);
    setCollaborators([]);
    setAnnotations([]);
  }, []);

  const addCollaborator = useCallback(async (email: string, permission: CollaborationPermission): Promise<boolean> => {
    const newCollaborator: Collaborator = {
      id: `user-${Date.now()}`,
      name: email.split('@')[0],
      email,
      permission,
      joinedAt: new Date().toISOString(),
      lastActiveAt: new Date().toISOString(),
      isOnline: false,
    };

    setCollaborators((prev) => [...prev, newCollaborator]);
    return true;
  }, []);

  const removeCollaborator = useCallback(async (userId: string): Promise<void> => {
    setCollaborators((prev) => prev.filter((c) => c.id !== userId));
  }, []);

  const updatePermission = useCallback(async (userId: string, permission: CollaborationPermission): Promise<void> => {
    setCollaborators((prev) => prev.map((c) => (c.id === userId ? { ...c, permission } : c)));
  }, []);

  const addAnnotation = useCallback(
    async (annotationData: Omit<Annotation, 'id' | 'createdAt' | 'updatedAt'>): Promise<Annotation> => {
      const newAnnotation: Annotation = {
        ...annotationData,
        id: `annotation-${Date.now()}`,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };

      setAnnotations((prev) => [...prev, newAnnotation]);
      return newAnnotation;
    },
    [],
  );

  const updateAnnotation = useCallback(async (id: string, updates: Partial<Annotation>): Promise<void> => {
    setAnnotations((prev) =>
      prev.map((a) => (a.id === id ? { ...a, ...updates, updatedAt: new Date().toISOString() } : a)),
    );
  }, []);

  const deleteAnnotation = useCallback(async (id: string): Promise<void> => {
    setAnnotations((prev) => prev.filter((a) => a.id !== id));
  }, []);

  const resolveAnnotation = useCallback(
    async (id: string): Promise<void> => {
      updateAnnotation(id, {
        resolved: true,
        resolvedAt: new Date().toISOString(),
      });
    },
    [updateAnnotation],
  );

  const addCommentThread = useCallback(
    async (
      threadData: Omit<CommentThread, 'id' | 'createdAt' | 'updatedAt' | 'annotations'>,
    ): Promise<CommentThread> => {
      const newThread: CommentThread = {
        ...threadData,
        id: `thread-${Date.now()}`,
        annotations: [],
        status: 'open',
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };

      setCommentThreads((prev) => [...prev, newThread]);
      return newThread;
    },
    [],
  );

  const replyToComment = useCallback(async (threadId: string, content: string): Promise<void> => {
    logger.log(`Replying to thread ${threadId}:`, content);
  }, []);

  const saveVersion = useCallback(
    async (message?: string): Promise<VersionInfo> => {
      const newVersion: VersionInfo = {
        id: `version-${Date.now()}`,
        versionNumber: versions.length + 1,
        createdBy: collaborators[0] || {
          id: '',
          name: '',
          email: '',
          permission: CollaborationPermission.VIEW,
          joinedAt: '',
          lastActiveAt: '',
          isOnline: false,
        },
        createdAt: new Date().toISOString(),
        message: message || `版本 ${versions.length + 1}`,
        changes: [],
        fileSize: Math.floor(Math.random() * 1000000),
        checksum: `hash-${Date.now()}`,
      };

      setVersions((prev) => [...prev, newVersion]);
      return newVersion;
    },
    [collaborators, versions.length],
  );

  const getVersion = useCallback(
    async (versionId: string): Promise<VersionInfo> => {
      return versions.find((v) => v.id === versionId) || versions[0];
    },
    [versions],
  );

  const compareVersions = useCallback(
    async (version1Id: string, version2Id: string): Promise<VersionDiff> => {
      const v1 = versions.find((v) => v.id === version1Id);
      const v2 = versions.find((v) => v.id === version2Id);

      return {
        version1: v1!,
        version2: v2!,
        changes: [
          { type: 'modify', sectionId: 'intro', content: '修改了引言部分内容', highlight: 'yellow' },
          { type: 'add', sectionId: 'new-section', content: '新增了章节', highlight: 'green' },
          { type: 'delete', sectionId: 'old-section', content: '删除了章节', highlight: 'red' },
        ],
      };
    },
    [versions],
  );

  const restoreVersion = useCallback(async (versionId: string): Promise<void> => {
    logger.log('Restoring version:', versionId);
  }, []);

  const updateShareSettingsInternal = useCallback((settings: Partial<ShareSettings>) => {
    setShareSettings((prev) => ({ ...prev, ...settings }));
  }, []);

  const updateShareSettings = useCallback(
    async (settings: Partial<ShareSettings>): Promise<void> => {
      updateShareSettingsInternal(settings);
    },
    [updateShareSettingsInternal],
  );

  const generateShareLink = useCallback(async (): Promise<string> => {
    const link = `${window.location.origin}/share/report/${session?.reportId}?token=${Date.now()}`;
    updateShareSettingsInternal({ link });
    return link;
  }, [session?.reportId, updateShareSettingsInternal]);

  const fetchAccessStats = useCallback(async (): Promise<void> => {
    const mockStats: AccessStatistics = {
      totalViews: Math.floor(Math.random() * 1000),
      uniqueVisitors: Math.floor(Math.random() * 500),
      totalDownloads: Math.floor(Math.random() * 200),
      averageTimeOnPage: Math.floor(Math.random() * 300) + 60,
      viewsByDate: Array.from({ length: 7 }, (_, i) => ({
        date: new Date(Date.now() - (6 - i) * 86400000).toISOString().split('T')[0],
        count: Math.floor(Math.random() * 50),
      })),
      topReferrers: [
        { source: '直接访问', count: Math.floor(Math.random() * 200) },
        { source: '搜索引擎', count: Math.floor(Math.random() * 100) },
        { source: '社交媒体', count: Math.floor(Math.random() * 80) },
      ],
      geographicDistribution: [
        { country: '中国', count: Math.floor(Math.random() * 400) },
        { country: '美国', count: Math.floor(Math.random() * 100) },
        { country: '日本', count: Math.floor(Math.random() * 50) },
      ],
    };
    setAccessStats(mockStats);
  }, []);

  return {
    session,
    isConnected,
    collaborators,
    annotations,
    commentThreads,
    versions,

    joinSession,
    leaveSession,

    addCollaborator,
    removeCollaborator,
    updatePermission,

    addAnnotation,
    updateAnnotation,
    deleteAnnotation,
    resolveAnnotation,

    addCommentThread,
    replyToComment,

    saveVersion,
    getVersion,
    compareVersions,
    restoreVersion,

    shareSettings,
    updateShareSettings,
    generateShareLink,

    accessStats,
    fetchAccessStats,

    realtimeEvents: eventBufferRef.current,
  };
}

/**
 * 自定义列视图管理 Hook
 *
 * 提供列视图的 CRUD 操作、localStorage 持久化、导入/导出功能
 */

import { useState, useCallback, useEffect } from 'react';

import { logger } from '@/utils/safeLogger';
import { useToast } from '@/components/ui';
const { error: toastError, warning: toastWarning, success: toastSuccess } = useToast();

import type {
  ColumnView,
  ColumnConfig,
  SerializedColumnView,
} from '@/types/columnView.types';

const STORAGE_KEY = 'rmfood_column_views';
const DEFAULT_VIEW_ID = 'default';
const MAX_VIEWS_DEFAULT = 20;
const DATA_FORMAT_VERSION = 1;

/**
 * 创建默认视图 (包含所有列，按初始顺序)
 */
function createDefaultView(columns: Omit<ColumnConfig, 'visible' | 'order'>[]): ColumnView {
  return {
    id: DEFAULT_VIEW_ID,
    name: '默认视图',
    description: '显示所有可用列的默认视图',
    columns: columns.map((col, index) => ({
      ...col,
      visible: true,
      order: index,
    })),
    isDefault: true,
    isSystem: true,
    createdAt: Date.now(),
  };
}

/**
 * 从 localStorage 加载已保存的视图列表
 */
function loadViewsFromStorage(): ColumnView[] {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (!stored) return [];

    const parsed = JSON.parse(stored) as ColumnView[];

    // 验证数据格式
    if (!Array.isArray(parsed)) {
      logger.warn('[useColumnView] localStorage 数据格式无效，使用空数组');
      return [];
    }

    return parsed.filter(view =>
      view && view.id && view.name && Array.isArray(view.columns),
    );
  } catch (error) {
    logger.error('[useColumnView] 加载视图失败:', error);
    return [];
  }
}

/**
 * 保存视图列表到 localStorage
 */
function saveViewsToStorage(views: ColumnView[]): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(views));
  } catch (error) {
    logger.error('[useColumnView] 保存视图失败:', error);
    // 可能是存储空间不足
    if (error instanceof DOMException && error.name === 'QuotaExceededError') {
      toastError('存储空间不足，请删除部分视图后重试');
    }
  }
}

/**
 * 列视图管理 Hook
 *
 * @param initialColumns 初始列定义数组 (不含 visible/order)
 * @returns 视图管理的状态和操作方法
 */
export function useColumnView(
  initialColumns: Omit<ColumnConfig, 'visible' | 'order'>[],
) {
  // 当前激活的视图
  const [currentView, setCurrentView] = useState<ColumnView>(() =>
    createDefaultView(initialColumns),
  );

  // 已保存的视图列表
  const [savedViews, setSavedViews] = useState<ColumnView[]>(() =>
    loadViewsFromStorage(),
  );

  // 初始化时加载默认视图或最近使用的视图
  useEffect(() => {
    const loaded = loadViewsFromStorage();

    if (loaded.length > 0) {
      setSavedViews(loaded);

      // 查找标记为默认的视图
      const defaultView = loaded.find(v => v.isDefault);

      // 如果有默认视图且有效，使用它；否则保持系统默认视图
      if (defaultView?.columns && defaultView.columns.length > 0) {
        setCurrentView(defaultView);
      }
    }
  }, []);

  /**
   * 更新当前视图的列配置
   */
  const updateColumns = useCallback((updater: (cols: ColumnConfig[]) => ColumnConfig[]) => {
    setCurrentView(prev => ({
      ...prev,
      columns: updater(prev.columns),
      updatedAt: Date.now(),
    }));
  }, []);

  /**
   * 切换单个列的可见性
   */
  const toggleColumnVisibility = useCallback((key: string, visible?: boolean) => {
    updateColumns(cols => cols.map(col =>
      col.key === key
        ? { ...col, visible: visible !== undefined ? visible : !col.visible }
        : col,
    ));
  }, [updateColumns]);

  /**
   * 调整列顺序 (拖拽排序后调用)
   */
  const reorderColumns = useCallback((fromIndex: number, toIndex: number) => {
    updateColumns(cols => {
      const newCols = [...cols];
      const [moved] = newCols.splice(fromIndex, 1);
			newCols.splice(toIndex, 0, moved);

      // 更新 order 属性
      return newCols.map((col, idx) => ({ ...col, order: idx }));
    });
  }, [updateColumns]);

  /**
   * 调整单个列的宽度
   */
  const resizeColumn = useCallback((key: string, width: number | null) => {
    updateColumns(cols => cols.map(col =>
      col.key === key ? { ...col, width } : col,
    ));
  }, [updateColumns]);

  /**
   * 重置为默认视图 (显示所有列)
   */
  const resetToDefault = useCallback(() => {
    const defaultView = createDefaultView(initialColumns);
    setCurrentView(defaultView);
  }, [initialColumns]);

  /**
   * 保存当前视图为新方案
   *
   * @param name 视图名称
   * @param description 可选描述
   * @param maxViews 最大允许数量 (默认20)
   * @returns 是否保存成功
   */
  const saveCurrentView = useCallback((
    name: string,
    description?: string,
    maxViews: number = MAX_VIEWS_DEFAULT,
  ): boolean => {
    if (!name?.trim()) {
      logger.warn('[useColumnView] 视图名称不能为空');
      return false;
    }

    const trimmedName = name.trim();

    // 检查是否超出最大数量限制
    const existingNonSystem = savedViews.filter(v => !v.isSystem);
    if (existingNonSystem.length >= maxViews && !savedViews.find(v => v.name === trimmedName)) {
      logger.warn(`[useColumnView] 已达到最大视图数限制 (${maxViews})`);
      toastWarning(`最多只能保存 ${maxViews} 个自定义视图`);
      return false;
    }

    const newView: ColumnView = {
      id: `view-${Date.now().toString(36)}-${Math.random().toString(36).substring(2, 8)}`,
      name: trimmedName,
      description,
      columns: currentView.columns,
      isDefault: false,
      createdAt: Date.now(),
    };

    // 如果同名视图已存在，更新它；否则添加新视图
    let updatedViews: ColumnView[];
    const existingIndex = savedViews.findIndex(v => v.name === trimmedName && !v.isSystem);

    if (existingIndex >= 0) {
      updatedViews = [...savedViews];
      updatedViews[existingIndex] = {
        ...newView,
        id: savedViews[existingIndex].id,  // 保持原有ID
					createdAt: savedViews[existingIndex].createdAt,  // 保持创建时间
        updatedAt: Date.now(),
      };
    } else {
      updatedViews = [...savedViews, newView];
    }

    setSavedViews(updatedViews);
    saveViewsToStorage(updatedViews);

    return true;
  }, [currentView, savedViews]);

  /**
   * 删除指定ID的视图
   */
  const deleteView = useCallback((id: string): boolean => {
    // 不允许删除系统内置视图
    const target = savedViews.find(v => v.id === id);
    if (target?.isSystem) {
      logger.warn('[useColumnView] 不能删除系统内置视图');
      return false;
    }

    const updatedViews = savedViews.filter(v => v.id !== id);
    setSavedViews(updatedViews);
    saveViewsToStorage(updatedViews);

    // 如果删除的是当前正在使用的视图，切换回默认视图
    if (currentView.id === id) {
      resetToDefault();
    }

    return true;
  }, [savedViews, currentView.id, resetToDefault]);

  /**
   * 设为默认视图
   */
  const setAsDefault = useCallback((id: string): boolean => {
    const target = savedViews.find(v => v.id === id);
    if (!target || target.isSystem) {
      return false;
    }

    // 取消其他视图的默认标记
    const updatedViews = savedViews.map(v => ({
      ...v,
      isDefault: v.id === id,
    }));

    setSavedViews(updatedViews);
    saveViewsToStorage(updatedViews);

    // 同时切换到该视图
    setCurrentView(target);

    return true;
  }, [savedViews]);

  /**
   * 加载指定的视图
   */
  const loadView = useCallback((view: ColumnView): void => {
    setCurrentView(view);
  }, []);

  /**
   * 导出视图为 JSON 字符串 (用于分享/备份)
   */
  const exportView = useCallback((view?: ColumnView): string => {
    const target = view || currentView;

    const serialized: SerializedColumnView = {
      version: DATA_FORMAT_VERSION,
      exportTime: Date.now(),
      view: {
        name: target.name,
        description: target.description,
        columns: target.columns,
        isDefault: target.isDefault,
        createdAt: target.createdAt,
        updatedAt: target.updatedAt,
      },
    };

    return JSON.stringify(serialized, null, 2);
  }, [currentView]);

  /**
   * 从 JSON 字符串导入视图
   *
   * @param jsonString JSON 格式的视图数据
   * @returns 导入成功返回新视图对象，失败返回 null
   */
  const importView = useCallback((jsonString: string): ColumnView | null => {
    try {
      const parsed = JSON.parse(jsonString) as SerializedColumnView;

      // 验证基本结构
      if (parsed?.version === undefined || !parsed.view) {
        throw new Error('无效的视图数据格式');
      }

      const { view } = parsed;

      // 验证必要字段
      if (!view.name || !Array.isArray(view.columns) || view.columns.length === 0) {
        throw new Error('视图数据缺少必要字段');
      }

      // 验证每列的结构
      for (const col of view.columns) {
        if (!col.key || typeof col.visible !== 'boolean' || typeof col.order !== 'number') {
          throw new Error(`列配置 "${col.key}" 格式无效`);
        }
      }

      // 创建新视图 (生成新的 ID)
      const importedView: ColumnView = {
        ...view,
        id: `imported-${Date.now().toString(36)}`,
        name: `${view.name} (导入)`,
        isDefault: false,
        isSystem: false,
        createdAt: Date.now(),
        updatedAt: Date.now(),
      };

      // 自动保存到本地
      const updatedViews = [...savedViews, importedView];
      setSavedViews(updatedViews);
      saveViewsToStorage(updatedViews);

      return importedView;

    } catch (error) {
      logger.error('[useColumnView] 导入视图失败:', error);
      toastError(`导入失败: ${error instanceof Error ? error.message : '数据格式错误'}`);
      return null;
    }
  }, [savedViews]);

  /**
   * 获取可见列列表 (按 order 排序)
   */
  const getVisibleColumns = useCallback((): ColumnConfig[] => {
    return currentView.columns
      .filter(col => col.visible)
      .sort((a, b) => a.order - b.order);
  }, [currentView]);

  /**
   * 获取所有列列表 (按 order 排序)
   */
  const getAllColumns = useCallback((): ColumnConfig[] => {
    return [...currentView.columns].sort((a, b) => a.order - b.order);
  }, [currentView]);

  return {
    // 状态
    currentView,
    savedViews,

    // 视图操作
    setCurrentView,
    saveCurrentView,
    deleteView,
    setAsDefault,
    loadView,
    resetToDefault,

    // 列操作
    updateColumns,
    toggleColumnVisibility,
    reorderColumns,
    resizeColumn,

    // 辅助方法
    getVisibleColumns,
    getAllColumns,
    exportView,
    importView,
  };
}

export default useColumnView;

/**
 * 统一的 debounce/throttle hooks
 *
 * 此模块是项目中唯一的 useDebounce 和 useThrottle 实现。
 * 所有其他文件应从此处导入，而非各自定义。
 */
import { useState, useEffect, useRef, useCallback } from 'react'

/**
 * Debounce a value — returns the debounced value after delay ms.
 */
export function useDebounce<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value)

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedValue(value)
    }, delay)

    return () => {
      clearTimeout(handler)
    }
  }, [value, delay])

  return debouncedValue
}

/**
 * Throttle a value — returns the throttled value.
 */
export function useThrottle<T>(value: T, interval: number): T {
  const [throttledValue, setThrottledValue] = useState<T>(value)
  const lastExecuted = useRef<number>(Date.now())

  useEffect(() => {
    const now = Date.now()
    const timeSinceLastExecution = now - lastExecuted.current

    if (timeSinceLastExecution >= interval) {
      lastExecuted.current = now
      setThrottledValue(value)
    } else {
      const timer = setTimeout(() => {
        lastExecuted.current = Date.now()
        setThrottledValue(value)
      }, interval - timeSinceLastExecution)

      return () => clearTimeout(timer)
    }
    return undefined
  }, [value, interval])

  return throttledValue
}

/**
 * Debounce a callback function.
 */
export function useDebouncedCallback<T extends (...args: any[]) => void>(
  callback: T,
  delay = 300,
): T {
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const callbackRef = useRef(callback)

  useEffect(() => {
    callbackRef.current = callback
  }, [callback])

  const debouncedCallback = useCallback(
    (...args: any[]) => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current)
      }
      timeoutRef.current = setTimeout(() => {
        callbackRef.current(...args)
      }, delay)
    },
    [delay],
  ) as T

  useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current)
      }
    }
  }, [])

  return debouncedCallback
}

import { useState, useCallback, useRef, useEffect } from 'react'
import { logger } from '@/utils/safeLogger';


export interface UndoableAction<T = any> {
  id: string
  type: string
  previousState: T
  newState: T
  timestamp: number
  description: string
}

export interface UndoableState<T = any> {
  past: UndoableAction<T>[]
  present: T
  future: UndoableAction<T>[]
}

export interface UseUndoOptions<T> {
  maxHistory?: number
  onUndo?: (action: UndoableAction<T>) => void
  onRedo?: (action: UndoableAction<T>) => void
  onChange?: (state: T, action: UndoableAction<T>) => void
}

export function useUndoableState<T>(initialState: T, options: UseUndoOptions<T> = {}) {
  const { maxHistory = 50, onUndo, onRedo, onChange } = options

  const [history, setHistory] = useState<UndoableState<T>>({
    past: [],
    present: initialState,
    future: [],
  })

  const lastActionRef = useRef<UndoableAction<T> | null>(null)

  const canUndo = history.past.length > 0
  const canRedo = history.future.length > 0

  const executeAction = useCallback(
    (type: string, description: string, reducer: (state: T) => T) => {
      setHistory((prev) => {
        const newPresent = reducer(prev.present)
        const action: UndoableAction<T> = {
          id: `${Date.now()}-${Math.random().toString(36).substring(2, 11)}`,
          type,
          previousState: prev.present,
          newState: newPresent,
          timestamp: Date.now(),
          description,
        }

        lastActionRef.current = action

        const newPast = [...prev.past, action].slice(-maxHistory)

        onChange?.(newPresent, action)

        return {
          past: newPast,
          present: newPresent,
          future: [],
        }
      })
    },
    [maxHistory, onChange],
  )

  const undo = useCallback(() => {
    if (!canUndo) return

    setHistory((prev) => {
      const newFuture = [lastActionRef.current!, ...prev.future]
      const lastAction = prev.past[prev.past.length - 1]

      onUndo?.(lastAction)
      lastActionRef.current = lastAction

      return {
        past: prev.past.slice(0, -1),
        present: lastAction.previousState,
        future: newFuture,
      }
    })
  }, [canUndo, onUndo])

  const redo = useCallback(() => {
    if (!canRedo) return

    setHistory((prev) => {
      const lastFutureAction = prev.future[0]
      const newPast = [...prev.past, lastFutureAction]

      onRedo?.(lastFutureAction)
      lastActionRef.current = lastFutureAction

      return {
        past: newPast,
        present: lastFutureAction.newState,
        future: prev.future.slice(1),
      }
    })
  }, [canRedo, onRedo])

  const clear = useCallback(() => {
    setHistory({
      past: [],
      present: history.present,
      future: [],
    })
  }, [history.present])

  return {
    state: history.present,
    past: history.past,
    future: history.future,
    canUndo,
    canRedo,
    executeAction,
    undo,
    redo,
    clear,
  }
}

export interface ErrorRecoveryState {
  error: Error | null
  errorInfo: string | null
  timestamp: number | null
  context: Record<string, any>
}

export interface UseErrorRecoveryOptions {
  maxErrors?: number
  onError?: (error: Error, context: Record<string, any>) => void
  onRecover?: (context: Record<string, any>) => void
}

export function useErrorRecovery(options: UseErrorRecoveryOptions = {}) {
  const { maxErrors = 10, onError, onRecover } = options

  const [errorHistory, setErrorHistory] = useState<ErrorRecoveryState[]>([])
  const [currentError, setCurrentError] = useState<Error | null>(null)
  const [isRecovering, setIsRecovering] = useState(false)

  const captureError = useCallback(
    (error: Error, context: Record<string, any> = {}) => {
      const errorState: ErrorRecoveryState = {
        error,
        errorInfo: error.message,
        timestamp: Date.now(),
        context,
      }

      setErrorHistory((prev) => [errorState, ...prev].slice(0, maxErrors))
      setCurrentError(error)
      onError?.(error, context)
    },
    [maxErrors, onError],
  )

  const clearError = useCallback(() => {
    setCurrentError(null)
  }, [])

  const recover = useCallback(
    (context: Record<string, any> = {}) => {
      setIsRecovering(true)
      try {
        onRecover?.(context)
        clearError()
      } finally {
        setIsRecovering(false)
      }
    },
    [clearError, onRecover],
  )

  const retryLastOperation = useCallback(() => {
    if (errorHistory.length > 0) {
      const lastError = errorHistory[0]
      recover(lastError.context)
    }
  }, [errorHistory, recover])

  const clearErrorHistory = useCallback(() => {
    setErrorHistory([])
  }, [])

  return {
    currentError,
    errorHistory,
    isRecovering,
    hasError: currentError !== null,
    hasErrorHistory: errorHistory.length > 0,
    captureError,
    clearError,
    recover,
    retryLastOperation,
    clearErrorHistory,
  }
}

export interface ActionHistoryItem<T = any> {
  id: string
  type: string
  payload: T
  timestamp: number
  status: 'pending' | 'success' | 'error' | 'reverted'
  error?: string
  revertedBy?: string
}

export function useActionHistory<T = any>(maxItems = 100) {
  const [history, setHistory] = useState<ActionHistoryItem<T>[]>([])
  const [pendingActions, setPendingActions] = useState<Map<string, ActionHistoryItem<T>>>(new Map())

  const addAction = useCallback(
    (type: string, payload: T) => {
      const action: ActionHistoryItem<T> = {
        id: `${Date.now()}-${Math.random().toString(36).substring(2, 11)}`,
        type,
        payload,
        timestamp: Date.now(),
        status: 'pending',
      }

      setPendingActions((prev) => {
        const newMap = new Map(prev)
        newMap.set(action.id, action)
        return newMap
      })

      return action.id
    },
    [],
  )

  const completeAction = useCallback(
    (actionId: string, status: 'success' | 'error', error?: string) => {
      setPendingActions((prev) => {
        const action = prev.get(actionId)
        if (!action) return prev

        const updatedAction: ActionHistoryItem<T> = {
          ...action,
          status,
          error,
        }

        setHistory((h) => [updatedAction, ...h].slice(0, maxItems))

        const newMap = new Map(prev)
        newMap.delete(actionId)
        return newMap
      })
    },
    [maxItems],
  )

  const revertAction = useCallback(
    (actionId: string) => {
      setHistory((prev) =>
        prev.map((action) =>
          action.id === actionId
            ? { ...action, status: 'reverted' as const, revertedBy: actionId }
            : action,
        ),
      )
    },
    [],
  )

  const clearHistory = useCallback(() => {
    setHistory([])
    setPendingActions(new Map())
  }, [])

  return {
    history,
    pendingActions: Array.from(pendingActions.values()),
    hasPendingActions: pendingActions.size > 0,
    addAction,
    completeAction,
    revertAction,
    clearHistory,
  }
}

export interface SessionRecoveryData {
  version: number
  timestamp: number
  data: Record<string, any>
}

export function useSessionRecovery(storageKey = 'rmfood_recovery') {
  const [recoveryData, setRecoveryData] = useState<SessionRecoveryData | null>(null)
  const [canRecover, setCanRecover] = useState(false)

  useEffect(() => {
    try {
      const stored = localStorage.getItem(storageKey)
      if (stored) {
        const parsed = JSON.parse(stored) as SessionRecoveryData
        if (Date.now() - parsed.timestamp < 1000 * 60 * 30) {
          setRecoveryData(parsed)
          setCanRecover(true)
        } else {
          localStorage.removeItem(storageKey)
        }
      }
    } catch (error) {
      logger.warn('Failed to load recovery data:', error)
    }
  }, [storageKey])

  const saveForRecovery = useCallback(
    (data: Record<string, any>) => {
      try {
        const recoveryData: SessionRecoveryData = {
          version: 1,
          timestamp: Date.now(),
          data,
        }
        localStorage.setItem(storageKey, JSON.stringify(recoveryData))
      } catch (error) {
        logger.warn('Failed to save recovery data:', error)
      }
    },
    [storageKey],
  )

  const clearRecovery = useCallback(() => {
    try {
      localStorage.removeItem(storageKey)
      setRecoveryData(null)
      setCanRecover(false)
    } catch (error) {
      logger.warn('Failed to clear recovery data:', error)
    }
  }, [storageKey])

  return {
    recoveryData,
    canRecover,
    saveForRecovery,
    clearRecovery,
  }
}

import { logger } from '@/utils/safeLogger'
import { useState, useCallback, useRef } from 'react';
import { ExportFormat } from '../types/export.types';
import type {
  ExportOptions,
  ExportColumn,
  ExportProgress,
  ExportResult,
  ExportCallback,
} from '../types/export.types';

export interface UseExportReturn {
  doExport: (options: ExportOptions) => Promise<ExportResult>;
  export: (options: ExportOptions, data: unknown[], onProgress?: ExportCallback) => Promise<ExportResult>;
  progress: ExportProgress;
  isExporting: boolean;
  cancelExport: () => void;
  getSupportedFormats: () => ExportFormat[];
  getDefaultFileName: (format: ExportFormat) => string;
}

export function useExport(): UseExportReturn {
  const [progress, setProgress] = useState<ExportProgress>({
    isExporting: false,
    currentStep: '',
    progress: 0,
    totalSteps: 0,
  });

  const abortRef = useRef(false);

  const updateProgress = useCallback((step: string, current: number, total: number) => {
    setProgress({
      isExporting: true,
      currentStep: step,
      progress: current,
      totalSteps: total,
    });
  }, []);

  const exportData = useCallback(async (
    options: ExportOptions,
    data: unknown[],
    onProgress?: ExportCallback,
  ): Promise<ExportResult> => {
    abortRef.current = false;

    try {
      updateProgress('准备导出数据...', 0, 4);

      const visibleColumns = options.columns.filter(col => col.visible)
        .sort((a, b) => a.order - b.order);

      const processedData = data;

      if (onProgress) {
        onProgress({
          isExporting: true,
          currentStep: '处理数据...',
          progress: 1,
          totalSteps: 4,
        });
      }

      await new Promise(resolve => setTimeout(resolve, 100));

      if (abortRef.current) {
        throw new Error('导出已取消');
      }

      let result: ExportResult;

      switch (options.format) {
        case ExportFormat.CSV:
          result = await exportToCSV(processedData, visibleColumns, options);
          break;
        case ExportFormat.EXCEL:
          result = await exportToExcel(processedData, visibleColumns, options);
          break;
        case ExportFormat.JSON:
          result = await exportToJSON(processedData, visibleColumns, options);
          break;
        case ExportFormat.PDF:
          result = await exportToPDF(processedData, visibleColumns, options);
          break;
        default:
          throw new Error(`不支持的导出格式: ${options.format}`);
      }

      if (onProgress) {
        onProgress({
          isExporting: false,
          currentStep: '完成',
          progress: 4,
          totalSteps: 4,
        });
      }

      setProgress({
        isExporting: false,
        currentStep: '完成',
        progress: 4,
        totalSteps: 4,
      });

      return {
        ...result,
        timestamp: Date.now(),
      };

    } catch (error) {
      setProgress({
        isExporting: false,
        currentStep: '失败',
        progress: 0,
        totalSteps: 0,
      });

      return {
        success: false,
        fileName: '',
        format: options.format,
        recordCount: 0,
        error: error instanceof Error ? error.message : '导出失败',
        timestamp: Date.now(),
      };
    }
  }, [updateProgress]);

  const cancelExport = useCallback(() => {
    abortRef.current = true;
  }, []);

  const getSupportedFormats = useCallback((): ExportFormat[] => {
    return Object.values(ExportFormat);
  }, []);

  const getDefaultFileName = useCallback((format: ExportFormat): string => {
    const timestamp = new Date().toISOString().slice(0, 19).replace(/[T:]/g, '-');
    const formatMap: Record<ExportFormat, string> = {
      [ExportFormat.CSV]: 'csv',
      [ExportFormat.EXCEL]: 'xlsx',
      [ExportFormat.JSON]: 'json',
      [ExportFormat.PDF]: 'pdf',
    };
    return `data_export_${timestamp}.${formatMap[format]}`;
  }, []);

  const doExport = useCallback(async (options: ExportOptions): Promise<ExportResult> => {
    logger.log('Export called with options:', options);
    return exportData(options, [], undefined);
  }, [exportData]);

  return {
    doExport,
    export: exportData,
    progress,
    isExporting: progress.isExporting,
    cancelExport,
    getSupportedFormats,
    getDefaultFileName,
  };
}

async function exportToCSV(
  data: any[],
  columns: ExportColumn[],
  options: ExportOptions,
): Promise<ExportResult> {
  const delimiter = options.csvConfig?.delimiter || ',';
  const encoding = options.csvConfig?.encoding || 'utf-8';
  const quoteFields = options.csvConfig?.quoteFields !== false;

  let csvContent = '';

  if (options.includeHeader !== false) {
    if (options.includeIndex) {
      csvContent += `序号${delimiter}`;
    }
    csvContent += columns.map(col => {
      const label = quoteFields ? `"${col.label}"` : col.label;
      return label.replace(new RegExp(delimiter, 'g'), '\\$&');
    }).join(delimiter);
    csvContent += '\n';
  }

  data.forEach((row, index) => {
    if (options.includeIndex) {
      csvContent += `${index + 1}${delimiter}`;
    }
    csvContent += columns.map(col => {
      let value = row[col.key];
      if (col.format && value != null) {
        value = col.format(value);
      }
      if (value == null) value = '';
      value = String(value);

      if (quoteFields || value.includes(delimiter) || value.includes('"') || value.includes('\n')) {
        value = `"${value.replace(/"/g, '""')}"`;
      }
      return value;
    }).join(delimiter);
    csvContent += '\n';
  });

  const blob = new Blob([csvContent], { type: `text/csv;charset=${encoding}` });
  downloadBlob(blob, options.fileName || getDefaultFileNameStatic(ExportFormat.CSV));

  return {
    success: true,
    fileName: options.fileName || getDefaultFileNameStatic(ExportFormat.CSV),
    format: ExportFormat.CSV,
    recordCount: data.length,
    fileSize: blob.size,
    timestamp: Date.now(),
  };
}

async function exportToExcel(
  data: any[],
  columns: ExportColumn[],
  options: ExportOptions,
): Promise<ExportResult> {
  try {
    const ExcelJS = await import('exceljs');

    const worksheetData: any[][] = [];

    if (options.includeHeader !== false) {
      const headerRow: any[] = [];
      if (options.includeIndex) headerRow.push('序号');
      columns.forEach(col => headerRow.push(col.label));
      worksheetData.push(headerRow);
    }

    data.forEach((row, index) => {
      const dataRow: any[] = [];
      if (options.includeIndex) dataRow.push(index + 1);
      columns.forEach(col => {
        let value = row[col.key];
        if (col.format && value != null) {
          value = col.format(value);
        }
        dataRow.push(value ?? '');
      });
      worksheetData.push(dataRow);
    });

    const wb = new ExcelJS.default.Workbook();
    const ws = wb.addWorksheet('Sheet1');

    worksheetData.forEach(row => ws.addRow(row));

    if (options.excelStyle?.freezePane) {
      ws.views = [{ state: 'frozen', ySplit: 1 }];
    }

    ws.columns = columns.map(col => ({
      header: col.label,
      key: col.key,
      width: col.width || 15,
    }));

    const excelBuffer = await wb.xlsx.writeBuffer();
    const blob = new Blob([excelBuffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    downloadBlob(blob, options.fileName || getDefaultFileNameStatic(ExportFormat.EXCEL));

    return {
      success: true,
      fileName: options.fileName || getDefaultFileNameStatic(ExportFormat.EXCEL),
      format: ExportFormat.EXCEL,
      recordCount: data.length,
      fileSize: blob.size,
      timestamp: Date.now(),
    };
  } catch {
    throw new Error('Excel导出失败，请检查exceljs库是否已安装');
  }
}

async function exportToJSON(
  data: any[],
  columns: ExportColumn[],
  options: ExportOptions,
): Promise<ExportResult> {
  const jsonData = data.map((row, index) => {
    const obj: Record<string, any> = {};
    if (options.includeIndex) {
      obj['序号'] = index + 1;
    }
    columns.forEach(col => {
      let value = row[col.key];
      if (col.format && value != null) {
        value = col.format(value);
      }
      obj[col.label] = value;
    });
    return obj;
  });

  const jsonContent = JSON.stringify(jsonData, null, 2);
  const blob = new Blob([jsonContent], { type: 'application/json;charset=utf-8' });
  downloadBlob(blob, options.fileName || getDefaultFileNameStatic(ExportFormat.JSON));

  return {
    success: true,
    fileName: options.fileName || getDefaultFileNameStatic(ExportFormat.JSON),
    format: ExportFormat.JSON,
    recordCount: data.length,
    fileSize: blob.size,
    timestamp: Date.now(),
  };
}

async function exportToPDF(
  data: any[],
  columns: ExportColumn[],
  options: ExportOptions,
): Promise<ExportResult> {
  try {
    const jsPDF = await import('jspdf');
    await import('jspdf-autotable');

    const doc = new jsPDF.default({
      orientation: options.pdfConfig?.orientation || 'portrait',
      unit: 'mm',
      format: options.pdfConfig?.pageSize || 'A4',
    });

    if (options.pdfConfig?.title) {
      doc.setFontSize(16);
      doc.text(options.pdfConfig.title, 14, 20);
    }

    if (options.pdfConfig?.subtitle) {
      doc.setFontSize(12);
      doc.text(options.pdfConfig.subtitle, 14, 28);
    }

    const tableData = data.map((row, index) => {
      const rowData: any[] = [];
      if (options.includeIndex) rowData.push(index + 1);
      columns.forEach(col => {
        let value = row[col.key];
        if (col.format && value != null) {
          value = col.format(value);
        }
        rowData.push(String(value ?? ''));
      });
      return rowData;
    });

    const tableHeaders: string[] = [];
    if (options.includeIndex) tableHeaders.push('序号');
    columns.forEach(col => tableHeaders.push(col.label));

    (doc as { autoTable?: (opts: unknown) => void }).autoTable?.({
      head: [tableHeaders],
      body: tableData,
      startY: options.pdfConfig?.title ? 35 : 20,
      styles: {
        fontSize: options.pdfConfig ? 9 : 8,
        cellPadding: 2,
      },
      headStyles: {
        fillColor: [41, 128, 185],
        textColor: 255,
        fontStyle: 'bold',
      },
      alternateRowStyles: {
        fillColor: [245, 245, 245],
      },
      margin: options.pdfConfig?.margins || { top: 20, right: 15, bottom: 20, left: 15 },
    });

    if (options.pdfConfig?.showPageNumbers !== false) {
      const pageCount = doc.getNumberOfPages();
      for (let i = 1; i <= pageCount; i++) {
        doc.setPage(i);
        doc.setFontSize(8);
        doc.setTextColor(150);
        doc.text(
          `第 ${i} 页 / 共 ${pageCount} 页`,
          doc.internal.pageSize.getWidth() / 2,
          doc.internal.pageSize.getHeight() - 10,
          { align: 'center' },
        );
      }
    }

    const pdfBlob = doc.output('blob');
    downloadBlob(pdfBlob, options.fileName || getDefaultFileNameStatic(ExportFormat.PDF));

    return {
    success: true,
    fileName: options.fileName || getDefaultFileNameStatic(ExportFormat.PDF),
    format: ExportFormat.PDF,
    recordCount: data.length,
    fileSize: pdfBlob.size,
    timestamp: Date.now(),
  };
  } catch {
    throw new Error('PDF导出需要安装jspdf和jspdf-autotable库');
  }
}

function downloadBlob(blob: Blob, fileName: string): void {
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = fileName;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
}

function getDefaultFileNameStatic(format: ExportFormat): string {
  const timestamp = new Date().toISOString().slice(0, 19).replace(/[T:]/g, '-');
  const formatMap: Record<ExportFormat, string> = {
    [ExportFormat.CSV]: 'csv',
    [ExportFormat.EXCEL]: 'xlsx',
    [ExportFormat.JSON]: 'json',
    [ExportFormat.PDF]: 'pdf',
  };
  return `data_export_${timestamp}.${formatMap[format]}`;
}

export default useExport;

import { useCallback } from 'react'
import type { AICandidate } from '@/api/ai'
import { logger } from '@/utils/safeLogger'
import { csvEscape, sanitizeCSVValue, addBOM } from '@/utils/encodingUtils'

export type ExportFormat = 'json' | 'csv'

export interface ExportOptions {
  includeDetails?: boolean
  includeScores?: boolean
  filename?: string
}

const DEFAULT_OPTIONS: ExportOptions = {
  includeDetails: true,
  includeScores: true,
}

export function useExportFormulas() {
  const exportToJSON = useCallback((
    formulas: AICandidate[],
    options: ExportOptions = {},
  ) => {
    const opts = { ...DEFAULT_OPTIONS, ...options }
    const filename = opts.filename || `formulas_${Date.now()}.json`

    let data: Array<Record<string, unknown>> = formulas.map(f => ({
      id: f.id,
      name: f.name,
      formula_name: f.formula_name,
      score: f.score,
      effects: f.effects,
    }))

    if (opts.includeDetails) {
      data = formulas.map(f => ({
        ...data.find(d => d.id === f.id),
        ingredients: f.ingredients,
        herb_combination: f.herb_combination,
        generated_by: f.generated_by,
        generated_at: f.generated_at,
      }))
    }

    if (opts.includeScores) {
      data = formulas.map(f => ({
        ...data.find(d => d.id === f.id),
        synergy_score: f.synergy_score,
        taste_score: f.taste_score,
        stability_score: f.stability_score,
        overall_score: f.overall_score,
        patent_synergy_scores: f.patent_synergy_scores,
        safety_passed: f.safety_passed,
      }))
    }

    downloadFile(JSON.stringify(data, null, 2), filename, 'application/json')
    logger.info('配方已导出为JSON', { count: formulas.length, filename })
  }, [])

  const exportToCSV = useCallback((
    formulas: AICandidate[],
    options: ExportOptions = {},
  ) => {
    const opts = { ...DEFAULT_OPTIONS, ...options }
    const filename = opts.filename || `formulas_${Date.now()}.csv`

    const headers = [
      '配方ID',
      '配方名称',
      '综合评分',
      '功效',
      '生成方式',
      '生成时间',
    ]

    if (opts.includeScores) {
      headers.push('协同评分', '口感评分', '稳定性评分', '总体评分')
    }

    if (opts.includeDetails) {
      headers.push('药材成分', '药材组合')
    }

    const rows: string[][] = formulas.map(f => {
      const row: string[] = [
        csvEscape(f.id),
        csvEscape(f.name || f.formula_name || ''),
        csvEscape(String(f.score || '')),
        csvEscape((f.effects || []).join(';')),
        csvEscape(f.generated_by || ''),
        csvEscape(f.generated_at || ''),
      ]

      if (opts.includeScores) {
        row.push(
          csvEscape(String(f.synergy_score || '')),
          csvEscape(String(f.taste_score || '')),
          csvEscape(String(f.stability_score || '')),
          csvEscape(String(f.overall_score || '')),
        )
      }

      if (opts.includeDetails) {
        const ingredients = (f.ingredients || []).map(i => `${i.name}: ${i.dosage || i.amount_mg}`).join(';')
        const herbs = (f.herb_combination || []).map(h => `${h.name || ''}(${h.role || ''})`).join(';')
        row.push(csvEscape(ingredients), csvEscape(herbs))
      }

      return row
    })

    const csvContent = [
      headers.map(h => csvEscape(h)).join(','),
      ...rows.map(r => r.join(',')),
    ].join('\n')

    const utf8Content = addBOM(csvContent)

    downloadFile(utf8Content, filename, 'text/csv;charset=utf-8')
    logger.info('配方已导出为CSV', { count: formulas.length, filename })
  }, [])

  const exportFormulas = useCallback((
    formulas: AICandidate[],
    format: ExportFormat,
    options: ExportOptions = {},
  ) => {
    if (formulas.length === 0) {
      logger.warn('没有选中任何配方')
      return
    }

    switch (format) {
      case 'json':
        exportToJSON(formulas, options)
        break
      case 'csv':
        exportToCSV(formulas, options)
        break
      default:
        logger.error(`不支持的导出格式: ${format}`)
    }
  }, [exportToJSON, exportToCSV])

  return {
    exportFormulas,
    exportToJSON,
    exportToCSV,
  }
}

function downloadFile(content: string, filename: string, mimeType: string) {
  const blob = new Blob([content], { type: mimeType })
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  link.download = filename
  document.body.appendChild(link)
  link.click()
  document.body.removeChild(link)
  URL.revokeObjectURL(url)
}

export default useExportFormulas

/**
 * 配方分析Hook
 * 用于实时分析配方内容并获取AI评分
 */
import { useState, useCallback, useRef } from 'react'
import { aiApi } from '@/api/ai'
import { parseFormulaTable, type FormulaTableData } from '@/utils/formulaParser'
import type { AICandidate, SafetyCheckResult, SynergyResult } from '@/types'
import type { StabilityPredictionResponse } from '@/types/ai.api'
import { logger } from '@/utils/safeLogger';


export interface FormulaAnalysisResult {
  candidate: AICandidate | null
  isLoading: boolean
  progress: number
  error: string | null
}

export interface AnalysisProgress {
  stage: 'idle' | 'parsing' | 'safety' | 'synergy' | 'taste' | 'stability' | 'complete' | 'error'
  message: string
  percent: number
}

export function useFormulaAnalysis() {
  const [result, setResult] = useState<FormulaAnalysisResult>({
    candidate: null,
    isLoading: false,
    progress: 0,
    error: null,
  })

  const [progress, setProgress] = useState<AnalysisProgress>({
    stage: 'idle',
    message: '',
    percent: 0,
  })

  const abortControllerRef = useRef<AbortController | null>(null)

  const updateProgress = useCallback((stage: AnalysisProgress['stage'], message: string, percent: number) => {
    setProgress({ stage, message, percent })
    setResult(prev => ({ ...prev, progress: percent }))
  }, [])

  const analyzeFormula = useCallback(async (content: string): Promise<AICandidate | null> => {
    // 验证输入
    if (!content || content.trim().length === 0) {
      setResult({
        candidate: null,
        isLoading: false,
        progress: 0,
        error: '配方内容不能为空',
      })
      return null
    }

    // 取消之前的请求
    if (abortControllerRef.current) {
      abortControllerRef.current.abort()
    }
    abortControllerRef.current = new AbortController()

    setResult({ candidate: null, isLoading: true, progress: 0, error: null })

    try {
      // 1. 解析配方内容
      updateProgress('parsing', '正在解析配方内容...', 10)
      const parsedFormula = parseFormulaTable(content)

      if (!parsedFormula || parsedFormula.ingredients.length === 0) {
        throw new Error('未能解析到配方成分，请确保包含有效的成分和用量信息')
      }

      await new Promise(resolve => setTimeout(resolve, 300))

      // 2. 安全检查
      updateProgress('safety', '正在进行安全性检查...', 25)
      const ingredientNames = parsedFormula.ingredients.map(i => i.name)
      let safetyResult: SafetyCheckResult
      try {
        safetyResult = await aiApi.safetyCheck(ingredientNames)
      } catch (error) {
        logger.warn('安全检查API调用失败，使用默认评分:', error)
        safetyResult = {
          passed: true,
          checks: {},
          warnings: [],
          errors: [],
          summary: '安全检查完成',
        }
      }

      await new Promise(resolve => setTimeout(resolve, 300))

      // 3. 协同作用分析
      updateProgress('synergy', '正在分析成分协同作用...', 45)
      let synergyResult: SynergyResult
      try {
        synergyResult = await aiApi.synergyAnalysis(ingredientNames)
      } catch (error) {
        logger.warn('协同分析API调用失败，使用默认评分:', error)
        synergyResult = {
          score: 0.75,
          synergy_pairs: [],
          antagonism_warnings: [],
          shared_pathways: [],
          heat_map: {},
          summary: '协同分析完成',
        }
      }

      await new Promise(resolve => setTimeout(resolve, 300))

      // 4. 口感预测
      updateProgress('taste', '正在评估口感风味...', 65)
      let tasteResult: { sweetness: number; bitterness: number; astringency: number; overall_score: number; flavor_notes: string[] }
      try {
        tasteResult = await aiApi.tastePredict(
          parsedFormula.ingredients.map(i => ({ name: i.name })),
        )
      } catch (error) {
        logger.warn('口感预测API调用失败，使用默认评分:', error)
        tasteResult = {
          sweetness: 0.6,
          bitterness: 0.3,
          astringency: 0.2,
          overall_score: 0.7,
          flavor_notes: ['口感适中'],
        }
      }

      await new Promise(resolve => setTimeout(resolve, 300))

      // 5. 稳定性预测
      updateProgress('stability', '正在评估稳定性...', 85)
      let stabilityResult: StabilityPredictionResponse
      try {
        stabilityResult = await aiApi.stabilityPredict(
          parsedFormula.ingredients.map(i => ({ name: i.name })),
        )
      } catch (error) {
        logger.warn('稳定性预测API调用失败，使用默认评分:', error)
        stabilityResult = {
          stability_score: 0.75,
          estimated_shelf_life_months: 18,
          risk_factors: [],
          monthly_curve: [],
          // 后端返回 string[]，不是单个 string
          storage_advice: ['常温保存'],
        }
      }

      // 6. 计算综合评分
      updateProgress('complete', '分析完成！', 100)

      const overallScore = calculateOverallScore({
        synergy: synergyResult.score ?? synergyResult.synergyScore ?? 0.75,
        taste: tasteResult.overall_score,
        stability: stabilityResult.stability_score,
        safety: safetyResult.passed ? 0.85 : 0.6,
      })

      // 构建AICandidate结果
      const candidate: AICandidate = {
        formula_name: parsedFormula.name || '手动输入配方',
        herb_combination: parsedFormula.ingredients.map(i => ({
          name: i.name,
          role: i.efficacyTags?.[0] || '主成分',
          dosage: `${i.amount}${i.unit}`,
        })),
        peptide_candidates: [],
        synergy_score: synergyResult.score ?? synergyResult.synergyScore ?? 0.75,
        safety_passed: safetyResult.passed,
        safety_details: {
          warnings: (safetyResult.warnings || []).map(w => w.message || String(w)),
          contraindications: parsedFormula.ingredients
            .flatMap(i => i.precautions?.map(p => p.content) || [])
            .filter(Boolean),
          summary: safetyResult.summary || '安全检查完成',
        },
        taste_score: tasteResult.overall_score,
        stability_score: stabilityResult.stability_score,
        overall_score: overallScore,
        description: `基于${parsedFormula.ingredients.length}种成分配制的配方`,
        target_population: '一般人群',
        contraindications: parsedFormula.ingredients
          .flatMap(i => i.precautions?.filter(p => p.type === 'contraindication').map(p => p.content) || [])
          .join('、') || '无特殊禁忌',
        generated_at: new Date().toISOString(),
      }

      setResult({
        candidate,
        isLoading: false,
        progress: 100,
        error: null,
      })

      return candidate
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : '配方分析失败'
      updateProgress('error', errorMessage, 0)
      setResult({
        candidate: null,
        isLoading: false,
        progress: 0,
        error: errorMessage,
      })
      return null
    }
  }, [updateProgress])

  const cancelAnalysis = useCallback(() => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort()
    }
    setResult({
      candidate: null,
      isLoading: false,
      progress: 0,
      error: null,
    })
    setProgress({
      stage: 'idle',
      message: '',
      percent: 0,
    })
  }, [])

  const resetResult = useCallback(() => {
    setResult({
      candidate: null,
      isLoading: false,
      progress: 0,
      error: null,
    })
    setProgress({
      stage: 'idle',
      message: '',
      percent: 0,
    })
  }, [])

  return {
    result,
    progress,
    analyzeFormula,
    cancelAnalysis,
    resetResult,
  }
}

/**
 * 计算综合评分
 */
function calculateOverallScore(scores: {
  synergy: number
  taste: number
  stability: number
  safety: number
}): number {
  const weights = {
    synergy: 0.35,
    taste: 0.25,
    stability: 0.25,
    safety: 0.15,
  }

  return Math.round(
    (scores.synergy * weights.synergy +
     scores.taste * weights.taste +
     scores.stability * weights.stability +
     scores.safety * weights.safety) * 100,
  ) / 100
}

/**
 * useGlobalShortcuts — 统一全局快捷键注册与冲突检测
 *
 * 所有快捷键在此集中注册，自动检测冲突并记录。
 * 优先级：global > local（input 聚焦时 local 接管）
 *
 * @example
 * useGlobalShortcuts([
 *   { key: 'k', ctrl: true, action: toggleSearch, scope: 'global' },
 *   { key: 'Escape', action: closeAll, scope: 'global' },
 * ])
 */
import { useEffect, useCallback, useRef } from 'react'

export interface GlobalShortcut {
  /** 按键（小写） */
  key: string
  ctrl?: boolean
  shift?: boolean
  alt?: boolean
  meta?: boolean
  /** 作用域：global = 始终监听；local = 仅在 no focus 时触发 */
  scope?: 'global' | 'local'
  /** 描述，用于调试/帮助面板 */
  description?: string
  /** 按键处理函数 */
  action: (e: KeyboardEvent) => void
  /** 是否启用 */
  enabled?: boolean
  /** 命中优先级，数字越大越优先（默认 0） */
  priority?: number
}

/** 当前是否有 focus 在 input/textarea/contenteditable 内 */
function isFocusInInput(): boolean {
  const el = document.activeElement
  if (!el) return false
  const tag = el.tagName
  return (
    tag === 'INPUT' ||
    tag === 'TEXTAREA' ||
    (el as HTMLElement).contentEditable === 'true' ||
    (el as HTMLElement).getAttribute('role') === 'textbox'
  )
}

let _registeredShortcuts: GlobalShortcut[] = []
let _conflictLog: Array<{ keys: string; descriptions: string[] }> = []

function keyDesc(s: GlobalShortcut): string {
  const parts: string[] = []
  if (s.ctrl || s.meta) parts.push('Ctrl')
  if (s.shift) parts.push('Shift')
  if (s.alt) parts.push('Alt')
  parts.push(s.key.toUpperCase())
  return parts.join('+')
}

export function useGlobalShortcuts(shortcuts: GlobalShortcut[], enabled = true) {
  const shortcutsRef = useRef(shortcuts)
  shortcutsRef.current = shortcuts

  // 冲突检测
  useEffect(() => {
    if (!enabled) return
    const conflicts = new Map<string, string[]>()
    for (const s of shortcuts) {
      if (s.enabled === false) continue
      const desc = keyDesc(s)
      const existing = conflicts.get(desc)
      if (existing) {
        existing.push(s.description ?? '(unnamed)')
      } else {
        conflicts.set(desc, [s.description ?? '(unnamed)'])
      }
    }
    _conflictLog = Array.from(conflicts.entries())
      .filter(([, descs]) => descs.length > 1)
      .map(([keys, descs]) => ({ keys, descriptions: descs }))
    if (_conflictLog.length > 0) {
    }
  }, [shortcuts, enabled])

  useEffect(() => {
    if (!enabled) return
    _registeredShortcuts = shortcuts

    const handler = (e: KeyboardEvent) => {
      const inInput = isFocusInInput()

      // 排序：priority 高的优先
      const sorted = [...shortcuts]
        .filter((s) => s.enabled !== false)
        .sort((a, b) => (b.priority ?? 0) - (a.priority ?? 0))

      for (const shortcut of sorted) {
        if (shortcut.enabled === false) continue
        // local scope 时，不在 input 中才触发
        if (shortcut.scope === 'local' && inInput) continue

        const matches =
          shortcut.key.toLowerCase() === e.key.toLowerCase() &&
          (!!shortcut.ctrl === e.ctrlKey || shortcut.ctrl === undefined) &&
          (!!shortcut.shift === e.shiftKey || shortcut.shift === undefined) &&
          (!!shortcut.alt === e.altKey || shortcut.alt === undefined) &&
          (!!shortcut.meta === e.metaKey || shortcut.meta === undefined)

        if (matches) {
          e.preventDefault()
          shortcut.action(e)
          break
        }
      }
    }

    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [shortcuts, enabled])

  return { conflicts: _conflictLog }
}

/** 导出冲突日志，供快捷键帮助面板使用 */
export function getShortcutConflicts(): Array<{ keys: string; descriptions: string[] }> {
  return _conflictLog
}

/**
 * useImportEngine — 数据导入引擎 Hook
 *
 * 管理完整的导入流程：上传 → 预览 → 映射配置 → 执行 → 进度追踪 → 错误查看
 */
import { useCallback, useState } from 'react'
import { importApi, type FieldMappingConfig, type ImportTaskDetail, type ImportErrorItem, type UploadResponse } from '@/api/import'


import { logger } from '@/utils/safeLogger';
export type ImportStep = 'idle' | 'upload' | 'preview' | 'mapping' | 'running' | 'done' | 'error'

export interface ImportProgress {
  totalRows: number
  processedRows: number
  insertedRows: number
  updatedRows: number
  errorRows: number
  progressPct: number
  successRate: number
}

export interface UseImportEngineReturn {
  // State
  step: ImportStep
  task: ImportTaskDetail | null
  uploadResponse: UploadResponse | null
  previewData: Record<string, unknown>[] | null
  errors: ImportErrorItem[]
  progress: ImportProgress | null
  file: File | null
  errorMessage: string | null
  isRunning: boolean

  // Actions
  setFile: (file: File | null) => void
  uploadFile: (fileType: string, delimiter: string) => Promise<void>
  fetchPreview: (limit?: number) => Promise<void>
  runImport: (targetTable: string, idField: string, mappings: FieldMappingConfig[]) => Promise<void>
  refreshTask: () => Promise<void>
  cancelTask: () => Promise<void>
  clear: () => void
  goToStep: (step: ImportStep) => void
}

export function useImportEngine(): UseImportEngineReturn {
  const [step, setStep] = useState<ImportStep>('idle')
  const [task, setTask] = useState<ImportTaskDetail | null>(null)
  const [uploadResponse, setUploadResponse] = useState<UploadResponse | null>(null)
  const [previewData, setPreviewData] = useState<Record<string, unknown>[] | null>(null)
  const [errors, setErrors] = useState<ImportErrorItem[]>([])
  const [progress, setProgress] = useState<ImportProgress | null>(null)
  const [file, setFileState] = useState<File | null>(null)
  const [errorMessage, setErrorMessage] = useState<string | null>(null)

  const taskId = uploadResponse?.task_id || ''

  const setFile = useCallback((f: File | null) => {
    setFileState(f)
    if (!f) {
      setStep('idle')
      setUploadResponse(null)
      setTask(null)
      setPreviewData(null)
      setErrors([])
      setProgress(null)
      setErrorMessage(null)
    }
  }, [])

  const uploadFile = useCallback(async (fileType: string, delimiter: string) => {
    if (!file) return
    try {
      setErrorMessage(null)
      const resp = await importApi.uploadFile(file, fileType, delimiter)
      setUploadResponse(resp)
      setStep('upload')
    } catch (e: any) {
      setErrorMessage(e.response?.data?.detail || e.message || '文件上传失败')
      setStep('error')
    }
  }, [file])

  const fetchPreview = useCallback(async (limit = 10) => {
    if (!taskId) return
    try {
      const data = await importApi.preview(taskId, limit, 'auto', 'csv')
      setPreviewData(data.preview)
      setStep('preview')
    } catch (e: any) {
      setErrorMessage(e.response?.data?.detail || e.message || '预览失败')
      setStep('error')
    }
  }, [taskId])

  const runImport = useCallback(async (targetTable: string, idField: string, mappings: FieldMappingConfig[]) => {
    if (!taskId) return
    try {
      setStep('running')
      const report = await importApi.runImport(taskId, targetTable, idField, mappings)
      setTask({
        task_id: report.task_id,
        adapter_type: 'csv',
        target_table: targetTable,
        status: report.status,
        total_rows: (report.stats as Record<string, unknown> | undefined)?.total_rows as number || 0,
        processed_rows: (report.stats as Record<string, unknown> | undefined)?.valid_rows as number || 0,
        inserted_rows: (report.stats as Record<string, unknown> | undefined)?.inserted as number || 0,
        updated_rows: (report.stats as Record<string, unknown> | undefined)?.updated as number || 0,
        error_rows: (report.stats as Record<string, unknown> | undefined)?.error_count as number || 0,
        progress_pct: 100,
        success_rate: (report.stats as Record<string, unknown> | undefined)?.success_rate as number || 0,
        error_summary: report.message,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      })
      setProgress({
        totalRows: (report.stats as Record<string, unknown> | undefined)?.total_rows as number || 0,
        processedRows: (report.stats as Record<string, unknown> | undefined)?.valid_rows as number || 0,
        insertedRows: (report.stats as Record<string, unknown> | undefined)?.inserted as number || 0,
        updatedRows: (report.stats as Record<string, unknown> | undefined)?.updated as number || 0,
        errorRows: (report.stats as Record<string, unknown> | undefined)?.error_count as number || 0,
        progressPct: 100,
        successRate: (report.stats as Record<string, unknown> | undefined)?.success_rate as number || 0,
      })
      setStep(report.status === 'completed' ? 'done' : 'error')
      setErrorMessage(report.status === 'failed' ? report.message : null)
    } catch (e: any) {
      setErrorMessage(e.response?.data?.detail || e.message || '导入失败')
      setStep('error')
    }
  }, [taskId])

  const refreshTask = useCallback(async () => {
    if (!uploadResponse?.task_id) return
    try {
      const detail = await importApi.getTaskDetail(uploadResponse.task_id)
      setTask(detail)
      setProgress({
        totalRows: detail.total_rows,
        processedRows: detail.processed_rows,
        insertedRows: detail.inserted_rows,
        updatedRows: detail.updated_rows,
        errorRows: detail.error_rows,
        progressPct: detail.progress_pct,
        successRate: detail.success_rate,
      })
      if (detail.status === 'running') {
        setStep('running')
      } else if (detail.status === 'completed') {
        setStep('done')
      } else if (detail.status === 'failed') {
        setStep('error')
        setErrorMessage(detail.error_summary || '导入失败')
      }
    } catch (e: any) {
      logger.warn('[useImportEngine] refresh failed:', e.message)
    }
  }, [uploadResponse?.task_id])

  const cancelTask = useCallback(async () => {
    if (!uploadResponse?.task_id) return
    try {
      await importApi.cancelTask(uploadResponse.task_id)
      setStep('idle')
      setUploadResponse(null)
    } catch (e: any) {
      setErrorMessage(e.response?.data?.detail || e.message || '取消失败')
    }
  }, [uploadResponse?.task_id])

  const clear = useCallback(() => {
    setStep('idle')
    setTask(null)
    setUploadResponse(null)
    setPreviewData(null)
    setErrors([])
    setProgress(null)
    setFileState(null)
    setErrorMessage(null)
  }, [])

  const goToStep = useCallback((s: ImportStep) => {
    setStep(s)
  }, [])

  return {
    step,
    task,
    uploadResponse,
    previewData,
    errors,
    progress,
    file,
    errorMessage,
    isRunning: step === 'running',
    setFile,
    uploadFile,
    fetchPreview,
    runImport,
    refreshTask,
    cancelTask,
    clear,
    goToStep,
  }
}

import { useEffect, useCallback } from 'react'

interface KeyboardShortcutOptions {
  key: string
  ctrlKey?: boolean
  shiftKey?: boolean
  metaKey?: boolean
  callback: () => void
  preventDefault?: boolean
}

export function useKeyboardShortcut(options: KeyboardShortcutOptions) {
  const { key, ctrlKey = false, shiftKey = false, metaKey = false, callback, preventDefault = true } = options

  const handleKeyDown = useCallback(
    (event: KeyboardEvent) => {
      const isCtrl = ctrlKey ? (event.ctrlKey || event.metaKey) : !event.ctrlKey && !event.metaKey
      const isShift = shiftKey ? event.shiftKey : !event.shiftKey

      if (event.key.toLowerCase() === key.toLowerCase() && isCtrl && isShift) {
        if (preventDefault) event.preventDefault()
        callback()
      }
    },
    [key, ctrlKey, shiftKey, callback, preventDefault],
  )

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [handleKeyDown])
}

