/**
 * 生成响应式 CSS 类名
 */
export function responsiveClass(
  base: string,
  variants: Partial<Record<Breakpoint, string>>,
): string {
  const classes = [base]

  for (const [bp, className] of Object.entries(variants)) {
    if (className) {
      classes.push(`${bp}:${className}`)
    }
  }

  return classes.join(' ')
}

