import { useState, useCallback, useEffect, useRef } from 'react'

export interface TourStep {
  id: string
  target: string
  title: string
  content: string
  placement?: 'top' | 'bottom' | 'left' | 'right' | 'center'
  actionText?: string
  skipText?: string
}

export interface TourOptions {
  steps: TourStep[]
  onComplete?: () => void
  onSkip?: () => void
  onStepChange?: (step: TourStep, index: number) => void
}

export function useTour(options: TourOptions) {
  const { steps, onComplete, onSkip, onStepChange } = options
  const [currentStep, setCurrentStep] = useState(0)
  const [isActive, setIsActive] = useState(false)
  const [isVisible, setIsVisible] = useState(false)
  const tooltipRef = useRef<HTMLDivElement>(null)

  const step = steps[currentStep]
  const isFirstStep = currentStep === 0
  const isLastStep = currentStep === steps.length - 1

  const start = useCallback(() => {
    setCurrentStep(0)
    setIsActive(true)
    setIsVisible(true)
  }, [])

  const stop = useCallback(() => {
    setIsActive(false)
    setIsVisible(false)
    setCurrentStep(0)
  }, [])

  const next = useCallback(() => {
    if (isLastStep) {
      onComplete?.()
      stop()
    } else {
      const nextStep = currentStep + 1
      setCurrentStep(nextStep)
      onStepChange?.(steps[nextStep], nextStep)
    }
  }, [currentStep, isLastStep, onComplete, onStepChange, stop, steps])

  const previous = useCallback(() => {
    if (!isFirstStep) {
      const prevStep = currentStep - 1
      setCurrentStep(prevStep)
      onStepChange?.(steps[prevStep], prevStep)
    }
  }, [currentStep, isFirstStep, onStepChange, steps])

  const skip = useCallback(() => {
    onSkip?.()
    stop()
  }, [onSkip, stop])

  const goToStep = useCallback(
    (index: number) => {
      if (index >= 0 && index < steps.length) {
        setCurrentStep(index)
        onStepChange?.(steps[index], index)
      }
    },
    [onStepChange, steps],
  )

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!isActive) return

      switch (e.key) {
        case 'Escape':
          skip()
          break
        case 'ArrowRight':
        case 'Enter':
          next()
          break
        case 'ArrowLeft':
          previous()
          break
      }
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [isActive, next, previous, skip])

  return {
    step,
    currentStep,
    totalSteps: steps.length,
    isActive,
    isVisible,
    isFirstStep,
    isLastStep,
    tooltipRef,
    start,
    stop,
    next,
    previous,
    skip,
    goToStep,
  }
}

export interface TooltipProps {
  content: string
  children: React.ReactNode
  position?: 'top' | 'bottom' | 'left' | 'right'
  delay?: number
}

export function useTooltip({ delay = 200 }: { delay?: number } = {}) {
  const [isVisible, setIsVisible] = useState(false)
  const [position, setPosition] = useState({ x: 0, y: 0 })
  const triggerRef = useRef<HTMLElement | null>(null)
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  const show = useCallback((e: React.MouseEvent | React.FocusEvent) => {
    timeoutRef.current = setTimeout(() => {
      setIsVisible(true)
    }, delay)
  }, [delay])

  const hide = useCallback(() => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current)
    }
    setIsVisible(false)
  }, [])

  const updatePosition = useCallback((rect: DOMRect) => {
    setPosition({
      x: rect.left + rect.width / 2,
      y: rect.top,
    })
  }, [])

  return {
    isVisible,
    position,
    triggerRef,
    show,
    hide,
    updatePosition,
  }
}

export interface FeatureHighlightProps {
  id: string
  title: string
  description: string
  learnMoreUrl?: string
}

export function useFeatureAnnouncements() {
  const [announcements, setAnnouncements] = useState<FeatureHighlightProps[]>([])
  const [currentIndex, setCurrentIndex] = useState(0)

  const addAnnouncement = useCallback((announcement: FeatureHighlightProps) => {
    setAnnouncements((prev) => [...prev, announcement])
  }, [])

  const removeAnnouncement = useCallback((id: string) => {
    setAnnouncements((prev) => prev.filter((a) => a.id !== id))
  }, [])

  const dismissAll = useCallback(() => {
    setAnnouncements([])
    setCurrentIndex(0)
  }, [])

  const next = useCallback(() => {
    if (currentIndex < announcements.length - 1) {
      setCurrentIndex((prev) => prev + 1)
    }
  }, [currentIndex, announcements.length])

  const previous = useCallback(() => {
    if (currentIndex > 0) {
      setCurrentIndex((prev) => prev - 1)
    }
  }, [currentIndex])

  return {
    announcements,
    currentAnnouncement: announcements[currentIndex],
    currentIndex,
    total: announcements.length,
    addAnnouncement,
    removeAnnouncement,
    dismissAll,
    next,
    previous,
    hasNext: currentIndex < announcements.length - 1,
    hasPrevious: currentIndex > 0,
  }
}

export interface KeyboardShortcut {
  key: string
  modifiers?: ('ctrl' | 'alt' | 'shift' | 'meta')[]
  description: string
  action: () => void
}

export function useGlobalShortcuts(shortcuts: KeyboardShortcut[]) {
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      for (const shortcut of shortcuts) {
        const modifiersMatch =
          !shortcut.modifiers ||
          shortcut.modifiers.every((mod) => {
            switch (mod) {
              case 'ctrl':
                return e.ctrlKey
              case 'alt':
                return e.altKey
              case 'shift':
                return e.shiftKey
              case 'meta':
                return e.metaKey
              default:
                return false
            }
          })

        const keyMatch = e.key.toLowerCase() === shortcut.key.toLowerCase()

        if (modifiersMatch && keyMatch) {
          e.preventDefault()
          shortcut.action()
          break
        }
      }
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [shortcuts])
}

export interface OnboardingProgress {
  completedSteps: string[]
  totalSteps: number
  percentage: number
}

export function useOnboardingProgress() {
  const [progress, setProgress] = useState<OnboardingProgress>({
    completedSteps: [],
    totalSteps: 5,
    percentage: 0,
  })

  const completeStep = useCallback((stepId: string) => {
    setProgress((prev) => {
      if (prev.completedSteps.includes(stepId)) return prev

      const newCompletedSteps = [...prev.completedSteps, stepId]
      const percentage = Math.round(
        (newCompletedSteps.length / prev.totalSteps) * 100,
      )

      return { ...prev, completedSteps: newCompletedSteps, percentage }
    })
  }, [])

  const resetProgress = useCallback(() => {
    setProgress({
      completedSteps: [],
      totalSteps: 5,
      percentage: 0,
    })
  }, [])

  const isStepCompleted = useCallback(
    (stepId: string) => progress.completedSteps.includes(stepId),
    [progress.completedSteps],
  )

  return {
    progress,
    completeStep,
    resetProgress,
    isStepCompleted,
  }
}

import { useCallback, useState, useRef, useLayoutEffect } from 'react'
import { useToast } from '@/components/ui'
import { getErrorInfo, getUserMessage, getSolution, isRetryable, ERROR_CODES } from '@/constants/errorCodes'
import type { ErrorCodeInfo } from '@/constants/errorCodes'

export type FeedbackType = 'success' | 'error' | 'warning' | 'info'

export interface FeedbackConfig {
  type: FeedbackType
  title: string
  message?: string
  duration?: number
  code?: string
  solution?: string
  retryable?: boolean
  onRetry?: () => void
}

export interface OperationState {
  isLoading: boolean
  isSuccess: boolean
  isError: boolean
  errorCode?: string
  errorInfo?: ErrorCodeInfo
}

export function useOperationFeedback() {
  const toast = useToast()
  const [operationState, setOperationState] = useState<OperationState>({
    isLoading: false,
    isSuccess: false,
    isError: false,
  })
  const timeoutRef = useRef<number | null>(null)

  // 清理定时器
  useLayoutEffect(() => {
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current)
      }
    }
  }, [])

  const clearState = useCallback(() => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current)
    }
    setOperationState({
      isLoading: false,
      isSuccess: false,
      isError: false,
      errorCode: undefined,
      errorInfo: undefined,
    })
  }, [])

  const showFeedback = useCallback((config: FeedbackConfig | FeedbackType, title?: string, message?: string, duration?: number) => {
    let finalConfig: FeedbackConfig

    if (typeof config === 'string') {
      finalConfig = {
        type: config,
        title: title || '',
        message,
        duration,
      }
    } else {
      finalConfig = config
    }

    const { type, title: configTitle, message: configMessage, duration: configDuration, code, solution, retryable } = finalConfig
    const displayDuration = configDuration ?? (type === 'error' ? 5000 : 3000)
    const fullMessage = configMessage ? `${configTitle}\n${configMessage}` : configTitle

    // 使用Promise.resolve确保微任务立即执行，确保反馈延迟≤300ms
    Promise.resolve().then(() => {
      toast.addToast({
        type,
        message: fullMessage,
        title: undefined,
        duration: displayDuration,
      })
    })

    // 更新操作状态
    if (type === 'error') {
      const errorInfo = code ? getErrorInfo(code) : undefined
      setOperationState({
        isLoading: false,
        isSuccess: false,
        isError: true,
        errorCode: code,
        errorInfo,
      })
    } else if (type === 'success') {
      setOperationState({
        isLoading: false,
        isSuccess: true,
        isError: false,
      })
      // 3秒后清除成功状态
      timeoutRef.current = window.setTimeout(clearState, 3000)
    }

    return {
      dismiss: () => {
        // Toast组件内部已有dismiss逻辑
      },
      retryable: retryable ?? (code ? isRetryable(code) : false),
    }
  }, [toast, clearState])

  const showSuccess = useCallback((title: string, message?: string, duration?: number) => {
    return showFeedback({
      type: 'success',
      title,
      message,
      duration: duration ?? 3000,
    })
  }, [showFeedback])

  const showError = useCallback((title: string, message?: string, duration?: number) => {
    return showFeedback({
      type: 'error',
      title,
      message,
      duration: duration ?? 5000,
    })
  }, [showFeedback])

  const showErrorWithCode = useCallback((errorCode: string, customMessage?: string) => {
    const errorInfo = getErrorInfo(errorCode)
    const userMessage = customMessage || getUserMessage(errorCode)
    const solution = getSolution(errorCode)

    return showFeedback({
      type: 'error',
      title: userMessage,
      message: solution || undefined,
      duration: 5000,
      code: errorCode,
      solution,
      retryable: errorInfo?.retryable ?? true,
    })
  }, [showFeedback])

  const showWarning = useCallback((title: string, message?: string, duration?: number) => {
    return showFeedback({
      type: 'warning',
      title,
      message,
      duration: duration ?? 4000,
    })
  }, [showFeedback])

  const showInfo = useCallback((title: string, message?: string, duration?: number) => {
    return showFeedback({
      type: 'info',
      title,
      message,
      duration: duration ?? 3000,
    })
  }, [showFeedback])

  const startOperation = useCallback(() => {
    clearState()
    setOperationState((prev) => ({ ...prev, isLoading: true }))
  }, [clearState])

  const completeOperation = useCallback((success: boolean, errorCode?: string) => {
    if (success) {
      setOperationState({
        isLoading: false,
        isSuccess: true,
        isError: false,
      })
      timeoutRef.current = window.setTimeout(clearState, 3000)
    } else {
      const errorInfo = errorCode ? getErrorInfo(errorCode) : undefined
      setOperationState({
        isLoading: false,
        isSuccess: false,
        isError: true,
        errorCode,
        errorInfo,
      })
    }
  }, [clearState])

  return {
    showFeedback,
    showSuccess,
    showError,
    showErrorWithCode,
    showWarning,
    showInfo,
    startOperation,
    completeOperation,
    operationState,
    clearState,
    ERROR_CODES,
  }
}

// 批量操作反馈hook
export function useBatchOperationFeedback() {
  const [batchState, setBatchState] = useState<{
    total: number
    completed: number
    success: number
    failed: number
    isRunning: boolean
  }>({
    total: 0,
    completed: 0,
    success: 0,
    failed: 0,
    isRunning: false,
  })

  const startBatch = useCallback((total: number) => {
    setBatchState({
      total,
      completed: 0,
      success: 0,
      failed: 0,
      isRunning: true,
    })
  }, [])

  const updateBatch = useCallback((success: boolean) => {
    setBatchState((prev) => ({
      ...prev,
      completed: prev.completed + 1,
      success: success ? prev.success + 1 : prev.success,
      failed: success ? prev.failed : prev.failed + 1,
      isRunning: prev.completed + 1 < prev.total,
    }))
  }, [])

  const completeBatch = useCallback(() => {
    setBatchState((prev) => ({
      ...prev,
      isRunning: false,
    }))
  }, [])

  const resetBatch = useCallback(() => {
    setBatchState({
      total: 0,
      completed: 0,
      success: 0,
      failed: 0,
      isRunning: false,
    })
  }, [])

  const progress = batchState.total > 0 ? (batchState.completed / batchState.total) * 100 : 0

  return {
    batchState,
    startBatch,
    updateBatch,
    completeBatch,
    resetBatch,
    progress,
  }
}

import React, { memo, useMemo, useCallback, useRef, useEffect, useState } from 'react';

export type PropertyComparator<T> = (prevProps: T, nextProps: T) => boolean;

export function createPropComparator<T>(keys: (keyof T)[]): PropertyComparator<T> {
  return (prevProps: T, nextProps: T) => {
    return keys.every((key) => {
      const prevValue = prevProps[key];
      const nextValue = nextProps[key];
      if (prevValue === nextValue) return true;
      if (typeof prevValue === 'object' && typeof nextValue === 'object') {
        return JSON.stringify(prevValue) === JSON.stringify(nextValue);
      }
      return false;
    });
  };
}

export function deepCompare<T>(prevProps: T, nextProps: T): boolean {
  const prevKeys = Object.keys(prevProps as object);
  const nextKeys = Object.keys(nextProps as object);
  if (prevKeys.length !== nextKeys.length) return false;
  for (const key of prevKeys) {
    const prevValue = (prevProps as Record<string, unknown>)[key];
    const nextValue = (nextProps as Record<string, unknown>)[key];
    if (prevValue === nextValue) continue;
    if (typeof prevValue === 'object' && typeof nextValue === 'object') {
      if (!deepCompare(prevValue, nextValue)) return false;
    } else {
      return false;
    }
  }
  return true;
}

export function optimizedMemo<T extends React.ComponentType<any>>(
  Component: T,
  comparator?: PropertyComparator<React.ComponentProps<T>>,
): T {
  return memo(Component, comparator as (a: T, b: T) => boolean) as unknown as T;
}

// NOTE: useDebouncedCallback has been moved to hooks/useDebounce.ts
// Import from there instead of this file.

export function useThrottledCallback<T extends (...args: any[]) => any>(callback: T, delay = 300): T {
  const lastCallRef = useRef(0);
  return useCallback(
    ((...args: any[]) => {
      const now = Date.now();
      if (now - lastCallRef.current >= delay) {
        lastCallRef.current = now;
        callback(...args);
      }
    }) as unknown as unknown as T,
    [callback, delay],
  );
}

export function useComputed<T>(compute: () => T, deps: React.DependencyList): T {
  return useMemo(compute, deps);
}

export const OptimizedCondition = memo<{
  condition: boolean;
  children: React.ReactNode;
  fallback?: React.ReactNode;
}>(({ condition, children, fallback }) => {
  if (condition) {
    return React.createElement(React.Fragment, null, children);
  }
  return fallback ? React.createElement(React.Fragment, null, fallback) : null;
});

export const OptimizedList = memo<{
  items: unknown[];
  renderItem: (item: unknown, index: number) => React.ReactNode;
  keyExtractor: (item: unknown, index: number) => string | number;
  className?: string;
}>(({ items, renderItem, keyExtractor, className }) => {
  const children = items.map((item, index) => {
    return React.createElement(React.Fragment, { key: keyExtractor(item, index) }, renderItem(item, index));
  });
  return React.createElement('div', { className }, children);
});

/**
 * 组织管理快捷键 Hook
 * 支持：
 *   - n: 新建组织
 *   - /: 搜索聚焦
 *   - g o: 概览
 *   - g m: 我的组织
 *   - g a: 全部
 *   - g t: 数据分析
 *   - Escape: 关闭弹窗
 */
import { useEffect, useRef } from 'react';

export type OrgKey = 'new' | 'search' | 'overview' | 'myOrgs' | 'all' | 'analytics' | 'escape';

interface UseKeyboardShortcutsProps {
  onAction: (action: OrgKey) => void;
  enabled?: boolean;
}

export function useKeyboardShortcuts({ onAction, enabled = true }: UseKeyboardShortcutsProps) {
  const lastKeyRef = useRef('');
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    if (!enabled) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      // Ignore if typing in input
      const tag = (e.target as HTMLElement)?.tagName;
      if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;

      // Single key shortcuts
      if (e.key === 'n' && !e.ctrlKey && !e.metaKey) {
        e.preventDefault();
        onAction('new');
        return;
      }
      if (e.key === '/' && !e.ctrlKey && !e.metaKey) {
        e.preventDefault();
        onAction('search');
        return;
      }
      if (e.key === 'Escape') {
        onAction('escape');
        return;
      }

      // Two-key sequence shortcuts (g + letter)
      if (e.key === 'g' && !e.ctrlKey && !e.metaKey) {
        lastKeyRef.current = 'g';
        clearTimeout(timeoutRef.current ?? 0);
        timeoutRef.current = setTimeout(() => {
          lastKeyRef.current = '';
        }, 800);
        return;
      }

      if (lastKeyRef.current === 'g') {
        clearTimeout(timeoutRef.current ?? 0);
        lastKeyRef.current = '';
        switch (e.key.toLowerCase()) {
          case 'o':
            e.preventDefault();
            onAction('overview');
            return;
          case 'm':
            e.preventDefault();
            onAction('myOrgs');
            return;
          case 'a':
            e.preventDefault();
            onAction('all');
            return;
          case 't':
            e.preventDefault();
            onAction('analytics');
            return;
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      clearTimeout(timeoutRef.current ?? 0);
    };
  }, [onAction, enabled]);
}

