import { useReducer, useCallback, useEffect, useRef, useMemo } from 'react'
import api from '@/api/client'
import type { Organization } from './useOrganizations'

export interface Member {
  id: number
  userId: number
  email: string
  displayName: string
  avatarUrl?: string
  role: Role
  status: 'active' | 'pending' | 'invited' | 'suspended'
  joinedAt: string
  lastActiveAt?: string
  customRoles?: string[]
}

export type Role = 'owner' | 'admin' | 'member' | 'viewer'

/** Map backend member record to frontend Member interface */
function mapMemberResponse(raw: Record<string, any>): Member {
  return {
    id: raw.id,
    userId: raw.user_id ?? raw.userId,
    email: raw.email ?? '',
    displayName: raw.username ?? raw.display_name ?? raw.full_name ?? raw.email?.split('@')[0] ?? '',
    avatarUrl: raw.avatar_url ?? raw.avatarUrl,
    role: (raw.role || 'member') as Role,
    status: (raw.status || (raw.is_active === false ? 'suspended' : 'active')) as Member['status'],
    joinedAt: raw.joined_at ?? raw.joinedAt ?? new Date().toISOString(),
    lastActiveAt: raw.last_active_at ?? raw.lastActiveAt,
    customRoles: raw.custom_roles ?? raw.customRoles ?? [],
  }
}

/** Map backend team record to frontend Team interface（后端无 slug/memberIds 时兜底，避免 undefined.includes 崩溃） */
function mapTeamResponse(raw: Record<string, any>): Team {
  return {
    id: raw.id,
    name: raw.name ?? '',
    description: raw.description ?? '',
    slug: raw.slug ?? '',
    memberIds: Array.isArray(raw.memberIds)
      ? raw.memberIds
      : (Array.isArray(raw.member_ids) ? raw.member_ids : []),
    leadId: raw.lead_id ?? raw.leadId,
    createdAt: raw.created_at ?? raw.createdAt ?? new Date().toISOString(),
    updatedAt: raw.updated_at ?? raw.updatedAt ?? raw.created_at ?? new Date().toISOString(),
  }
}

export interface Team {
  id: number
  name: string
  description?: string
  slug: string
  memberIds: number[]
  leadId?: number
  createdAt: string
  updatedAt: string
}

interface OrganizationDetailState {
  organization: Organization | null
  members: Member[]
  teams: Team[]
  loading: boolean
  error: Error | null
  activeTab: string
  organizationId: number | null
}

type OrganizationDetailAction =
  | { type: 'SET_LOADING'; payload: boolean }
  | { type: 'SET_ERROR'; payload: Error | null }
  | { type: 'SET_ORGANIZATION'; payload: Organization }
  | { type: 'SET_MEMBERS'; payload: Member[] }
  | { type: 'ADD_MEMBER'; payload: Member }
  | { type: 'UPDATE_MEMBER'; payload: { id: number; data: Partial<Member> } }
  | { type: 'REMOVE_MEMBER'; payload: number }
  | { type: 'SET_TEAMS'; payload: Team[] }
  | { type: 'ADD_TEAM'; payload: Team }
  | { type: 'UPDATE_TEAM'; payload: { id: number; data: Partial<Team> } }
  | { type: 'REMOVE_TEAM'; payload: number }
  | { type: 'SET_ACTIVE_TAB'; payload: string }
  | { type: 'SET_ORGANIZATION_ID'; payload: number | null }
  | { type: 'RESET_STATE' }

const initialState: OrganizationDetailState = {
  organization: null,
  members: [],
  teams: [],
  loading: false,
  error: null,
  activeTab: 'overview',
  organizationId: null,
}

function organizationDetailReducer(
  state: OrganizationDetailState,
  action: OrganizationDetailAction,
): OrganizationDetailState {
  switch (action.type) {
    case 'SET_LOADING':
      return { ...state, loading: action.payload }

    case 'SET_ERROR':
      return { ...state, error: action.payload, loading: false }

    case 'SET_ORGANIZATION':
      return { ...state, organization: action.payload, loading: false }

    case 'SET_MEMBERS':
      return { ...state, members: action.payload }

    case 'ADD_MEMBER':
      return { ...state, members: [...state.members, action.payload] }

    case 'UPDATE_MEMBER':
      return {
        ...state,
        members: state.members.map((member) =>
          member.id === action.payload.id ? { ...member, ...action.payload.data } : member,
        ),
      }

    case 'REMOVE_MEMBER':
      return {
        ...state,
        members: state.members.filter((member) => member.id !== action.payload),
      }

    case 'SET_TEAMS':
      return { ...state, teams: action.payload }

    case 'ADD_TEAM':
      return { ...state, teams: [...state.teams, action.payload] }

    case 'UPDATE_TEAM':
      return {
        ...state,
        teams: state.teams.map((team) =>
          team.id === action.payload.id ? { ...team, ...action.payload.data } : team,
        ),
      }

    case 'REMOVE_TEAM':
      return {
        ...state,
        teams: state.teams.filter((team) => team.id !== action.payload),
      }

    case 'SET_ACTIVE_TAB':
      return { ...state, activeTab: action.payload }

    case 'SET_ORGANIZATION_ID':
      return { ...state, organizationId: action.payload }

    case 'RESET_STATE':
      return { ...initialState }

    default:
      return state
  }
}

interface UseOrganizationDetailOptions {
  autoFetchMembers?: boolean
  autoFetchTeams?: boolean
}

export function useOrganizationDetail(options: UseOrganizationDetailOptions = {}) {
  const { autoFetchMembers = true, autoFetchTeams = true } = options

  const [state, dispatch] = useReducer(organizationDetailReducer, initialState)
  const abortControllerRef = useRef<AbortController | null>(null)
  const mountedRef = useRef(true)

  useEffect(() => {
    mountedRef.current = true
    return () => {
      mountedRef.current = false
      if (abortControllerRef.current) {
        abortControllerRef.current.abort()
      }
    }
  }, [])

  const fetchDetail = useCallback(
    async (id: number) => {
      if (!mountedRef.current) return
      if (typeof window === 'undefined') return

      if (abortControllerRef.current) {
        abortControllerRef.current.abort()
      }

      abortControllerRef.current = new AbortController()

      dispatch({ type: 'SET_ORGANIZATION_ID', payload: id })
      dispatch({ type: 'SET_LOADING', payload: true })
      dispatch({ type: 'SET_ERROR', payload: null })

      try {
        const [orgResponse, membersResponse, teamsResponse] = await Promise.all([
          api.get(`/organizations/${id}`, {
            signal: abortControllerRef.current.signal,
          }),
          autoFetchMembers
            ? api.get(`/organizations/${id}/members`, {
                signal: abortControllerRef.current.signal,
              })
            : Promise.resolve({ data: [] }),
          autoFetchTeams
            ? api.get(`/organizations/${id}/teams`, {
                signal: abortControllerRef.current.signal,
              })
            : Promise.resolve({ data: [] }),
        ])

        if (!mountedRef.current) return

        // Backend returns { organization: {...} }, { members: [...] }, { teams: [...] }
        const rawOrg = orgResponse.data?.organization ?? orgResponse.data
        dispatch({ type: 'SET_ORGANIZATION', payload: rawOrg })

        if (autoFetchMembers) {
          const rawMembers = membersResponse.data?.members || membersResponse.data || []
          dispatch({
            type: 'SET_MEMBERS',
            payload: rawMembers.map((m: Record<string, any>) => mapMemberResponse(m)),
          })
        }

        if (autoFetchTeams) {
          const rawTeams = teamsResponse.data?.teams || teamsResponse.data || []
          dispatch({
            type: 'SET_TEAMS',
            payload: rawTeams.map((t: Record<string, any>) => mapTeamResponse(t)),
          })
        }
      } catch (error: any) {
        if (!mountedRef.current) return
        if (error.name === 'CanceledError') return

        dispatch({ type: 'SET_ERROR', payload: error as Error })
      }
    },
    [autoFetchMembers, autoFetchTeams],
  )

  const setActiveTab = useCallback((tab: string) => {
    dispatch({ type: 'SET_ACTIVE_TAB', payload: tab })
  }, [])

  const inviteMember = useCallback(
    async (email: string, role: Role = 'member'): Promise<void> => {
      if (!state.organizationId) throw new Error('No organization selected')

      dispatch({ type: 'SET_ERROR', payload: null })

      try {
        // Backend: POST /organizations/{id}/members with { email, role, team_ids? }
        const response = await api.post(`/organizations/${state.organizationId}/members`, {
          email,
          role,
        })

        const newMember = response.data as Member
        dispatch({ type: 'ADD_MEMBER', payload: newMember })
      } catch (error: any) {
        dispatch({ type: 'SET_ERROR', payload: error as Error })
        throw error
      }
    },
    [state.organizationId],
  )

  const removeMember = useCallback(
    async (memberUserId: number): Promise<void> => {
      if (!state.organizationId) throw new Error('No organization selected')

      dispatch({ type: 'SET_ERROR', payload: null })

      try {
        // Backend DELETE /{org_id}/members/{user_id} expects user_id
        await api.delete(`/organizations/${state.organizationId}/members/${memberUserId}`)
        // Remove from local state by matching userId
        dispatch({
          type: 'REMOVE_MEMBER',
          payload: state.members.find((m) => m.userId === memberUserId)?.id ?? memberUserId,
        })
      } catch (error: any) {
        dispatch({ type: 'SET_ERROR', payload: error as Error })
        throw error
      }
    },
    [state.organizationId, state.members],
  )

  const updateMemberRole = useCallback(
    async (memberId: number, role: Role): Promise<void> => {
      if (!state.organizationId) throw new Error('No organization selected')

      dispatch({ type: 'SET_ERROR', payload: null })

      try {
        // Backend: PUT /organizations/{id}/members/{user_id}/role
        await api.put(`/organizations/${state.organizationId}/members/${memberId}/role`, { role })
        dispatch({
          type: 'UPDATE_MEMBER',
          payload: { id: memberId, data: { role } },
        })
      } catch (error: any) {
        dispatch({ type: 'SET_ERROR', payload: error as Error })
        throw error
      }
    },
    [state.organizationId],
  )

  const createTeam = useCallback(
    async (data: Partial<Team>): Promise<Team> => {
      if (!state.organizationId) throw new Error('No organization selected')

      dispatch({ type: 'SET_ERROR', payload: null })

      try {
        const response = await api.post(`/organizations/${state.organizationId}/teams`, data)
        const newTeam = response.data as Team
        dispatch({ type: 'ADD_TEAM', payload: newTeam })
        return newTeam
      } catch (error: any) {
        dispatch({ type: 'SET_ERROR', payload: error as Error })
        throw error
      }
    },
    [state.organizationId],
  )

  const updateTeam = useCallback(
    async (teamId: number, data: Partial<Team>): Promise<Team> => {
      if (!state.organizationId) throw new Error('No organization selected')

      dispatch({ type: 'SET_ERROR', payload: null })

      try {
        // Backend: PUT /organizations/{id}/teams/{team_id}
        await api.put(`/organizations/${state.organizationId}/teams/${teamId}`, data)
        dispatch({
          type: 'UPDATE_TEAM',
          payload: { id: teamId, data },
        })

        const updatedTeam = state.teams.find((t) => t.id === teamId)
        return updatedTeam ? { ...updatedTeam, ...data } : ({} as Team)
      } catch (error: any) {
        dispatch({ type: 'SET_ERROR', payload: error as Error })
        throw error
      }
    },
    [state.organizationId, state.teams],
  )

  const deleteTeam = useCallback(
    async (teamId: number): Promise<void> => {
      if (!state.organizationId) throw new Error('No organization selected')

      dispatch({ type: 'SET_ERROR', payload: null })

      try {
        await api.delete(`/organizations/${state.organizationId}/teams/${teamId}`)
        dispatch({ type: 'REMOVE_TEAM', payload: teamId })
      } catch (error: any) {
        dispatch({ type: 'SET_ERROR', payload: error as Error })
        throw error
      }
    },
    [state.organizationId],
  )

  const fetchMembers = useCallback(async (): Promise<void> => {
    if (!state.organizationId || !mountedRef.current) return

    try {
      const response = await api.get(`/organizations/${state.organizationId}/members`)
      if (mountedRef.current) {
        // Backend returns { members: [...] }
        dispatch({
          type: 'SET_MEMBERS',
          payload: response.data?.members || response.data || [],
        })
      }
    } catch (error: any) {
      if (mountedRef.current) {
        dispatch({ type: 'SET_ERROR', payload: error as Error })
      }
    }
  }, [state.organizationId])

  const fetchTeams = useCallback(async (): Promise<void> => {
    if (!state.organizationId || !mountedRef.current) return

    try {
      const response = await api.get(`/organizations/${state.organizationId}/teams`)
      if (mountedRef.current) {
        // Backend returns { teams: [...] }
        const rawTeams = response.data?.teams || response.data || []
        dispatch({
          type: 'SET_TEAMS',
          payload: rawTeams.map((t: Record<string, any>) => mapTeamResponse(t)),
        })
      }
    } catch (error: any) {
      if (mountedRef.current) {
        dispatch({ type: 'SET_ERROR', payload: error as Error })
      }
    }
  }, [state.organizationId])

  const refetch = useCallback(() => {
    if (state.organizationId) {
      fetchDetail(state.organizationId)
    }
  }, [fetchDetail, state.organizationId])

  const memberCount = useMemo(() => state.members.length, [state.members.length])
  const teamCount = useMemo(() => state.teams.length, [state.teams.length])
  const activeMemberCount = useMemo(
    () => state.members.filter((m) => m.status === 'active').length,
    [state.members],
  )
  const pendingInvites = useMemo(
    () => state.members.filter((m) => m.status === 'pending' || m.status === 'invited').length,
    [state.members],
  )

  return {
    organization: state.organization,
    members: state.members,
    teams: state.teams,
    loading: state.loading,
    error: state.error,
    activeTab: state.activeTab,

    fetchDetail,
    setActiveTab,

    inviteMember,
    removeMember,
    updateMemberRole,

    createTeam,
    updateTeam,
    deleteTeam,

    fetchMembers,
    fetchTeams,
    refetch,

    memberCount,
    teamCount,
    activeMemberCount,
    pendingInvites,
  }
}

export type UseOrganizationDetailReturn = ReturnType<typeof useOrganizationDetail>

import { useReducer, useCallback, useEffect, useRef, useMemo } from 'react'
import api from '@/api/client'

export interface Organization {
  id: number
  name: string
  slug: string
  description?: string
  plan: 'free' | 'pro' | 'enterprise'
  memberCount: number
  teamCount: number
  storageUsed: number
  storageLimit: number
  apiUsage: number
  apiLimit: number
  isFavorite: boolean
  isPinned: boolean
  isActive: boolean
  myRole: 'owner' | 'admin' | 'member' | 'viewer'
  createdAt: string
  updatedAt: string
}

export interface OrganizationFilters {
  plan?: ('free' | 'pro' | 'enterprise')[]
  role?: ('owner' | 'admin' | 'member' | 'viewer')[]
  status?: ('active' | 'inactive')[]
}

export interface CreateOrganizationRequest {
  name: string
  slug?: string
  description?: string
  plan?: 'free' | 'pro' | 'enterprise'
}

export interface UpdateOrganizationRequest {
  name?: string
  description?: string
  slug?: string
  plan?: 'free' | 'pro' | 'enterprise'
  isActive?: boolean
}

interface OrganizationsState {
  organizations: Organization[]
  loading: boolean
  error: Error | null
  total: number
  page: number
  pageSize: number
  search: string
  filters: OrganizationFilters
  sortBy: string
  sortOrder: 'asc' | 'desc'
  selectedIds: Set<number>
  lastFetchedAt: number | null
  trashedOrganizations: Organization[]
  trashLoading: boolean
}

type OrganizationsAction =
  | { type: 'SET_LOADING'; payload: boolean }
  | { type: 'SET_ERROR'; payload: Error | null }
  | { type: 'SET_ORGANIZATIONS'; payload: { items: Organization[]; total: number } }
  | { type: 'ADD_ORGANIZATION'; payload: Organization }
  | { type: 'UPDATE_ORGANIZATION'; payload: { id: number; data: Partial<Organization> } }
  | { type: 'REMOVE_ORGANIZATION'; payload: number }
  | { type: 'SET_PAGE'; payload: number }
  | { type: 'SET_PAGE_SIZE'; payload: number }
  | { type: 'SET_SEARCH'; payload: string }
  | { type: 'SET_FILTERS'; payload: Partial<OrganizationFilters> }
  | { type: 'SET_SORT'; payload: { field: string; order: 'asc' | 'desc' } }
  | { type: 'TOGGLE_SELECT'; payload: number }
  | { type: 'SELECT_ALL'; payload: number[] }
  | { type: 'CLEAR_SELECTION' }
  | { type: 'RESET_STATE' }
  | { type: 'SET_TRASHED'; payload: Organization[] }
  | { type: 'REMOVE_TRASHED'; payload: number }

/** Map backend org list response to frontend Organization type */
function mapOrgResponse(raw: Record<string, any>): Organization {
  const plan = raw.plan || 'free'
  const limits: Record<string, number> = raw.limits || {}
  return {
    id: raw.id,
    name: raw.name || '',
    slug: raw.slug || '',
    description: raw.description || '',
    plan,
    memberCount: raw.member_count ?? raw.memberCount ?? 0,
    teamCount: raw.team_count ?? raw.teamCount ?? 0,
    storageUsed: Number(raw.storage_used_mb ?? raw.storageUsed) * 1024 * 1024 || 0,
    storageLimit: (limits.storage_mb ?? 1024) * 1024 * 1024,
    apiUsage: 0,
    apiLimit: limits.api_calls_per_day ?? 10000,
    isFavorite: raw.is_favorite === true || raw.isFavorite === true,
    isPinned: raw.is_pinned === true || raw.isPinned === true,
    isActive: raw.is_active !== false,
    myRole: raw.member_role ?? raw.my_role ?? 'member',
    createdAt: raw.created_at || new Date().toISOString(),
    updatedAt: raw.updated_at || raw.created_at || new Date().toISOString(),
  }
}

const initialState: OrganizationsState = {
  organizations: [],
  loading: false,
  error: null,
  total: 0,
  page: 1,
  pageSize: 10,
  search: '',
  filters: {},
  sortBy: 'createdAt',
  sortOrder: 'desc',
  selectedIds: new Set(),
  lastFetchedAt: null,
  trashedOrganizations: [],
  trashLoading: false,
}

function organizationsReducer(state: OrganizationsState, action: OrganizationsAction): OrganizationsState {
  switch (action.type) {
    case 'SET_LOADING':
      return { ...state, loading: action.payload }

    case 'SET_ERROR':
      return { ...state, error: action.payload, loading: false }

    case 'SET_ORGANIZATIONS':
      return {
        ...state,
        organizations: action.payload.items,
        total: action.payload.total,
        loading: false,
        error: null,
        lastFetchedAt: Date.now(),
      }

    case 'ADD_ORGANIZATION':
      return {
        ...state,
        organizations: [action.payload, ...state.organizations],
        total: state.total + 1,
      }

    case 'UPDATE_ORGANIZATION':
      return {
        ...state,
        organizations: state.organizations.map((org) =>
          org.id === action.payload.id ? { ...org, ...action.payload.data } : org,
        ),
      }

    case 'REMOVE_ORGANIZATION':
      return {
        ...state,
        organizations: state.organizations.filter((org) => org.id !== action.payload),
        total: state.total - 1,
        selectedIds: new Set([...state.selectedIds].filter((id) => id !== action.payload)),
      }

    case 'SET_PAGE':
      return { ...state, page: action.payload }

    case 'SET_PAGE_SIZE':
      return { ...state, pageSize: action.payload, page: 1 }

    case 'SET_SEARCH':
      return { ...state, search: action.payload, page: 1 }

    case 'SET_FILTERS':
      return { ...state, filters: { ...state.filters, ...action.payload }, page: 1 }

    case 'SET_SORT':
      return { ...state, sortBy: action.payload.field, sortOrder: action.payload.order }

    case 'TOGGLE_SELECT': {
      const newSelected = new Set(state.selectedIds)
      if (newSelected.has(action.payload)) {
        newSelected.delete(action.payload)
      } else {
        newSelected.add(action.payload)
      }
      return { ...state, selectedIds: newSelected }
    }

    case 'SELECT_ALL':
      return { ...state, selectedIds: new Set(action.payload) }

    case 'CLEAR_SELECTION':
      return { ...state, selectedIds: new Set() }

    case 'RESET_STATE':
      return { ...initialState }

    case 'SET_TRASHED':
      return { ...state, trashedOrganizations: action.payload }

    case 'REMOVE_TRASHED':
      return { ...state, trashedOrganizations: state.trashedOrganizations.filter((o) => o.id !== action.payload) }

    default:
      return state
  }
}

interface UseOrganizationsOptions {
  autoFetch?: boolean
  debounceMs?: number
  cacheTTL?: number
  maxRetries?: number
}

export function useOrganizations(options: UseOrganizationsOptions = {}) {
  const {
    autoFetch = true,
    debounceMs = 300,
    cacheTTL = 1000 * 60 * 5,
    maxRetries = 3,
  } = options

  const [state, dispatch] = useReducer(organizationsReducer, initialState)
  const abortControllerRef = useRef<AbortController | null>(null)
  const debounceTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const retryCountRef = useRef(0)
  const mountedRef = useRef(true)

  useEffect(() => {
    mountedRef.current = true
    return () => {
      mountedRef.current = false
      if (abortControllerRef.current) {
        abortControllerRef.current.abort()
      }
      if (debounceTimerRef.current) {
        clearTimeout(debounceTimerRef.current)
      }
    }
  }, [])

  const buildQueryParams = useCallback(() => {
    const params: Record<string, any> = {
      page: state.page,
      pageSize: state.pageSize,
      sortBy: state.sortBy,
      sortOrder: state.sortOrder,
    }

    if (state.search.trim()) {
      params.search = state.search.trim()
    }

    if (state.filters.plan?.length) {
      params.plan = state.filters.plan.join(',')
    }

    if (state.filters.role?.length) {
      params.role = state.filters.role.join(',')
    }

    if (state.filters.status?.length) {
      params.status = state.filters.status.join(',')
    }

    return params
  }, [state.page, state.pageSize, state.search, state.filters, state.sortBy, state.sortOrder])

  const fetchOrganizations = useCallback(async () => {
    if (!mountedRef.current) return

    if (abortControllerRef.current) {
      abortControllerRef.current.abort()
    }

    abortControllerRef.current = new AbortController()

    dispatch({ type: 'SET_LOADING', payload: true })
    dispatch({ type: 'SET_ERROR', payload: null })

    try {
      const params = buildQueryParams()
      const response = await api.get('/organizations', {
        params,
        signal: abortControllerRef.current.signal,
      })

      if (!mountedRef.current) return

      const data = response.data
      const rawOrgs = data.organizations || data.items || data.data || []
      const mapped = rawOrgs.map((o: Record<string, any>) => mapOrgResponse(o))
      dispatch({
        type: 'SET_ORGANIZATIONS',
        payload: {
          items: mapped,
          total: data.total ?? mapped.length,
        },
      })

      retryCountRef.current = 0
    } catch (error: any) {
      if (!mountedRef.current) return

      if (error.name === 'CanceledError') return

      if (retryCountRef.current < maxRetries && error.response?.status >= 500) {
        retryCountRef.current++
        setTimeout(() => {
          if (mountedRef.current) {
            fetchOrganizations()
          }
        }, Math.pow(2, retryCountRef.current) * 1000)
        return
      }

      dispatch({ type: 'SET_ERROR', payload: error as Error })
    }
  }, [buildQueryParams, maxRetries])

  useEffect(() => {
    if (autoFetch && typeof window !== 'undefined') {
      fetchOrganizations()
    }
  }, [autoFetch, fetchOrganizations])

  const setSearch = useCallback((search: string) => {
    if (debounceTimerRef.current) {
      clearTimeout(debounceTimerRef.current)
    }

    dispatch({ type: 'SET_SEARCH', payload: search })

    debounceTimerRef.current = setTimeout(() => {
      fetchOrganizations()
    }, debounceMs)
  }, [fetchOrganizations, debounceMs])

  const setFilters = useCallback((filters: Partial<OrganizationFilters>) => {
    dispatch({ type: 'SET_FILTERS', payload: filters })
  }, [])

  useEffect(() => {
    if (state.filters !== initialState.filters) {
      fetchOrganizations()
    }
  }, [state.filters, fetchOrganizations])

  const setSort = useCallback((field: string, order: 'asc' | 'desc') => {
    dispatch({ type: 'SET_SORT', payload: { field, order } })
  }, [])

  useEffect(() => {
    if (state.sortBy !== initialState.sortBy || state.sortOrder !== initialState.sortOrder) {
      fetchOrganizations()
    }
  }, [state.sortBy, state.sortOrder, fetchOrganizations])

  const setPage = useCallback((page: number) => {
    dispatch({ type: 'SET_PAGE', payload: page })
  }, [])

  useEffect(() => {
    if (state.page > 1) {
      fetchOrganizations()
    }
  }, [state.page, fetchOrganizations])

  const setPageSize = useCallback((size: number) => {
    dispatch({ type: 'SET_PAGE_SIZE', payload: size })
  }, [])

  const toggleSelect = useCallback((id: number) => {
    dispatch({ type: 'TOGGLE_SELECT', payload: id })
  }, [])

  const selectAll = useCallback(() => {
    const allIds = state.organizations.map((org) => org.id)
    dispatch({ type: 'SELECT_ALL', payload: allIds })
  }, [state.organizations])

  const clearSelection = useCallback(() => {
    dispatch({ type: 'CLEAR_SELECTION' })
  }, [])

  const createOrganization = useCallback(
    async (data: CreateOrganizationRequest): Promise<Organization> => {
      dispatch({ type: 'SET_ERROR', payload: null })

      try {
        const response = await api.post('/organizations', data)
        // Backend returns { success: true, organization: {...} }
        const rawOrg = response.data?.organization ?? response.data
        const newOrg = mapOrgResponse(rawOrg as Record<string, any>)
        dispatch({ type: 'ADD_ORGANIZATION', payload: newOrg })
        return newOrg
      } catch (error: any) {
        dispatch({ type: 'SET_ERROR', payload: error as Error })
        throw error
      }
    },
    [],
  )

  const updateOrganization = useCallback(async (id: number, data: UpdateOrganizationRequest): Promise<void> => {
    dispatch({ type: 'SET_ERROR', payload: null })

    try {
      await api.put(`/organizations/${id}`, data)
      dispatch({
        type: 'UPDATE_ORGANIZATION',
        payload: { id, data },
      })
    } catch (error: any) {
      dispatch({ type: 'SET_ERROR', payload: error as Error })
      throw error
    }
  }, [])

  const deleteOrganization = useCallback(async (id: number): Promise<void> => {
    dispatch({ type: 'SET_ERROR', payload: null })

    try {
      await api.delete(`/organizations/${id}`)
      dispatch({ type: 'REMOVE_ORGANIZATION', payload: id })
    } catch (error: any) {
      dispatch({ type: 'SET_ERROR', payload: error as Error })
      throw error
    }
  }, [])

  const toggleFavorite = useCallback(async (id: number): Promise<void> => {
    const org = state.organizations.find((o) => o.id === id)
    if (!org) return
    const next = !org.isFavorite
    // 乐观更新
    dispatch({ type: 'UPDATE_ORGANIZATION', payload: { id, data: { isFavorite: next } } })
    try {
      await api.put(`/organizations/${id}/favorite`, { favorite: next })
    } catch (err: any) {
      // 失败回滚
      dispatch({ type: 'UPDATE_ORGANIZATION', payload: { id, data: { isFavorite: !next } } })
      throw err
    }
  }, [state.organizations])

  const fetchTrashedOrganizations = useCallback(async () => {
    if (!mountedRef.current) return
    dispatch({ type: 'SET_LOADING', payload: true })
    try {
      // 后端提供已归档组织专用接口（/organizations/trashed），避免与活跃列表混用
      const response = await api.get('/organizations/trashed')
      if (!mountedRef.current) return
      const rawOrgs = response.data?.organizations || response.data?.items || response.data?.data || []
      const trashed = rawOrgs.map((o: Record<string, any>) => mapOrgResponse(o))
      dispatch({ type: 'SET_TRASHED', payload: trashed })
      dispatch({ type: 'SET_LOADING', payload: false })
    } catch (error: any) {
      if (!mountedRef.current) return
      dispatch({ type: 'SET_ERROR', payload: error as Error })
    }
  }, [])

  const restoreOrganization = useCallback(async (id: number): Promise<void> => {
    // Backend uses PUT /organizations/{id}/restore
    await api.put(`/organizations/${id}/restore`)
    dispatch({ type: 'REMOVE_ORGANIZATION', payload: id })
    dispatch({ type: 'REMOVE_TRASHED', payload: id })
  }, [])

  const cloneOrganization = useCallback(async (id: number, newName?: string): Promise<number> => {
    const response = await api.post(`/organizations/${id}/clone`, { name: newName })
    // Backend returns { success, new_organization_id }
    const newOrgId = response.data?.new_organization_id ?? response.data?.id
    dispatch({
      type: 'ADD_ORGANIZATION',
      payload: {
        id: newOrgId,
        name: newName || '克隆组织',
        slug: `clone-${Date.now()}`,
        description: '',
        plan: 'free' as const,
        memberCount: 1,
        teamCount: 0,
        storageUsed: 0,
        storageLimit: 500 * 1024 * 1024,
        apiUsage: 0,
        apiLimit: 10000,
        isFavorite: false,
        isPinned: false,
        isActive: true,
        myRole: 'owner' as const,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      },
    })
    return newOrgId
  }, [])

  const permanentDeleteOrganization = useCallback(async (id: number): Promise<void> => {
    // Use the standard delete (soft delete) then remove from trash
    await api.delete(`/organizations/${id}`)
    dispatch({ type: 'REMOVE_ORGANIZATION', payload: id })
    dispatch({ type: 'REMOVE_TRASHED', payload: id })
  }, [])

  const togglePin = useCallback(async (id: number): Promise<void> => {
    const org = state.organizations.find((o) => o.id === id)
    if (!org) return
    const next = !org.isPinned
    dispatch({ type: 'UPDATE_ORGANIZATION', payload: { id, data: { isPinned: next } } })
    try {
      await api.put(`/organizations/${id}/pin`, { pinned: next })
    } catch (err: any) {
      dispatch({ type: 'UPDATE_ORGANIZATION', payload: { id, data: { isPinned: !next } } })
      throw err
    }
  }, [state.organizations])

  const refetch = useCallback(() => {
    retryCountRef.current = 0
    fetchOrganizations()
  }, [fetchOrganizations])

  const isStale = useMemo(() => {
    if (!state.lastFetchedAt) return true
    return Date.now() - state.lastFetchedAt > cacheTTL
  }, [state.lastFetchedAt, cacheTTL])

  const allSelected = useMemo(
    () => state.organizations.length > 0 && state.selectedIds.size === state.organizations.length,
    [state.organizations.length, state.selectedIds.size],
  )

  const someSelected = useMemo(
    () => state.selectedIds.size > 0 && state.selectedIds.size < state.organizations.length,
    [state.selectedIds.size, state.organizations.length],
  )

  return {
    organizations: state.organizations,
    loading: state.loading,
    error: state.error,
    total: state.total,
    page: state.page,
    pageSize: state.pageSize,
    search: state.search,
    filters: state.filters,
    sortBy: state.sortBy,
    sortOrder: state.sortOrder,
    selectedIds: state.selectedIds,

    fetchOrganizations,
    setSearch,
    setFilters,
    setSort,
    setPage,
    setPageSize,
    toggleSelect,
    selectAll,
    clearSelection,

    createOrganization,
    updateOrganization,
    deleteOrganization,

    toggleFavorite,
    togglePin,

    refetch,
    isStale,
    allSelected,
    someSelected,
    trashedOrganizations: state.trashedOrganizations ?? [],
    trashLoading: state.loading,
    fetchTrashedOrganizations,
    restoreOrganization,
    permanentDeleteOrganization,
    cloneOrganization,
  }
}

export interface PermissionMatrixData {
  organization_id: number
  permissions: Record<string, boolean>
  my_role: string
}

export async function getPermissionMatrix(organizationId: number): Promise<PermissionMatrixData> {
  const response = await api.get("/organizations/" + organizationId + "/permissions")
  return response.data
}

export type UseOrganizationsReturn = ReturnType<typeof useOrganizations>

