          <button
            onClick={() => this.setState({ hasError: false, error: null })}
            className="px-4 py-2 bg-error-600 text-white rounded-lg hover:bg-error-700 transition-colors"
          >
            重试
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

/**
 * 性能监控工具
 *
 * @description 提供 React 应用的性能监控和分析功能
 * @version 1.0.0
 */

import { logger } from '@/utils/safeLogger';
import { useEffect, useRef, useState } from 'react';

export interface PerformanceMetrics {
  renderCount: number;
  lastRenderTime: number;
  averageRenderTime: number;
  components: Record<string, ComponentMetrics>;
}

export interface ComponentMetrics {
  renderCount: number;
  lastRenderTime: number;
  averageRenderTime: number;
  prevProps?: string;
  nextProps?: string;
}

export interface UseRenderMonitorOptions {
  enabled?: boolean;
  logToConsole?: boolean;
  maxHistory?: number;
}

const globalMetrics: PerformanceMetrics = {
  renderCount: 0,
  lastRenderTime: 0,
  averageRenderTime: 0,
  components: {},
};

export function useRenderMonitor(componentName: string, options: UseRenderMonitorOptions = {}) {
  const { enabled = process.env.NODE_ENV === 'development', logToConsole = false } = options;
  const renderCountRef = useRef(0);
  const startTimeRef = useRef(0);
  const renderTimesRef = useRef<number[]>([]);

  useEffect(() => {
    if (!enabled) return;

    const endTime = performance.now();
    const renderTime = endTime - startTimeRef.current;

    renderCountRef.current++;
    renderTimesRef.current.push(renderTime);

    if (renderTimesRef.current.length > 100) {
      renderTimesRef.current.shift();
    }

    const averageRenderTime = renderTimesRef.current.reduce((a, b) => a + b, 0) / renderTimesRef.current.length;

    globalMetrics.renderCount++;
    globalMetrics.lastRenderTime = renderTime;
    globalMetrics.averageRenderTime = averageRenderTime;

    globalMetrics.components[componentName] = {
      renderCount: renderCountRef.current,
      lastRenderTime: renderTime,
      averageRenderTime,
    };

    if (logToConsole) {
      logger.log(`[${componentName}] Render #${renderCountRef.current} in ${renderTime.toFixed(2)}ms`);
    }

    startTimeRef.current = performance.now();
  });

  useEffect(() => {
    if (enabled) {
      startTimeRef.current = performance.now();
    }
  });

  return {
    renderCount: renderCountRef.current,
    metrics: globalMetrics.components[componentName],
  };
}

export function useRenderTimeTracker() {
  const [metrics, setMetrics] = useState<PerformanceMetrics>(globalMetrics);

  useEffect(() => {
    const interval = setInterval(() => {
      setMetrics({ ...globalMetrics });
    }, 5000);

    return () => clearInterval(interval);
  }, []);

  return metrics;
}

export function getPerformanceMetrics(): PerformanceMetrics {
  return { ...globalMetrics };
}

export function resetPerformanceMetrics() {
  globalMetrics.renderCount = 0;
  globalMetrics.lastRenderTime = 0;
  globalMetrics.averageRenderTime = 0;
  globalMetrics.components = {};
}

export function logPerformanceReport() {
  console.group('📊 Performance Report');
  logger.log('Total Renders:', globalMetrics.renderCount);
  logger.log('Last Render Time:', `${globalMetrics.lastRenderTime.toFixed(2)}ms`);
  logger.log('Average Render Time:', `${globalMetrics.averageRenderTime.toFixed(2)}ms`);

  console.group('Components');
  Object.entries(globalMetrics.components).forEach(([name, metrics]) => {
    logger.log(`  ${name}:`, {
      renders: metrics.renderCount,
      last: `${metrics.lastRenderTime.toFixed(2)}ms`,
      avg: `${metrics.averageRenderTime.toFixed(2)}ms`,
    });
  });
  console.groupEnd();

  console.groupEnd();
}

export interface MemoryUsage {
  usedJSHeapSize: number;
  totalJSHeapSize: number;
  jsHeapSizeLimit: number;
}

export function getMemoryUsage(): MemoryUsage | null {
  const perfWithMemory = performance as Performance & { memory?: { usedJSHeapSize: number; totalJSHeapSize: number; jsHeapSizeLimit: number } };
  if (typeof window !== 'undefined' && perfWithMemory.memory) {
    const memory = perfWithMemory.memory;
    return {
      usedJSHeapSize: memory.usedJSHeapSize,
      totalJSHeapSize: memory.totalJSHeapSize,
      jsHeapSizeLimit: memory.jsHeapSizeLimit,
    };
  }
  return null;
}

export function formatBytes(bytes: number): string {
  if (bytes === 0) return '0 Bytes';
  const k = 1024;
  const sizes = ['Bytes', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
}

export function useMemoryMonitor(enabled = false) {
  const [memory, setMemory] = useState<MemoryUsage | null>(null);

  useEffect(() => {
    if (!enabled) return;

    const updateMemory = () => {
      const mem = getMemoryUsage();
      if (mem) {
        setMemory(mem);
      }
    };

    updateMemory();
    const interval = setInterval(updateMemory, 5000);

    return () => clearInterval(interval);
  }, [enabled]);

  return memory;
}

export function logMemoryReport() {
  const memory = getMemoryUsage();
  if (memory) {
    console.group('💾 Memory Usage');
    logger.log('Used:', formatBytes(memory.usedJSHeapSize));
    logger.log('Total:', formatBytes(memory.totalJSHeapSize));
    logger.log('Limit:', formatBytes(memory.jsHeapSizeLimit));
    logger.log('Usage %:', `${((memory.usedJSHeapSize / memory.jsHeapSizeLimit) * 100).toFixed(1)}%`);
    console.groupEnd();
  }
}

export interface FPSMonitorOptions {
  targetFPS?: number;
  warnThreshold?: number;
}

export function useFPSMonitor(options: FPSMonitorOptions = {}) {
  const { targetFPS = 60, warnThreshold = 30 } = options;
  const [fps, setFps] = useState(60);
  const frameCount = useRef(0);
  const lastTime = useRef(performance.now());
  const rafId = useRef<number>(0);

  useEffect(() => {
    const measureFPS = () => {
      const now = performance.now();
      frameCount.current++;

      if (now - lastTime.current >= 1000) {
        const currentFPS = Math.round((frameCount.current * 1000) / (now - lastTime.current));
        setFps(currentFPS);

        if (currentFPS < warnThreshold) {
          logger.warn(`FPS dropped to ${currentFPS}, below threshold ${warnThreshold}`);
        }

        frameCount.current = 0;
        lastTime.current = now;
      }

      rafId.current = requestAnimationFrame(measureFPS);
    };

    rafId.current = requestAnimationFrame(measureFPS);

    return () => {
      if (rafId.current) {
        cancelAnimationFrame(rafId.current);
      }
    };
  }, [targetFPS, warnThreshold]);

  return {
    fps,
    isHealthy: fps >= targetFPS,
    isWarning: fps < warnThreshold,
  };
}

export class PerformanceMonitor {
  private static instance: PerformanceMonitor;
  private marks = new Map<string, number>();
  private measures: { name: string; duration: number; timestamp: number }[] = [];

  static getInstance(): PerformanceMonitor {
    if (!PerformanceMonitor.instance) {
      PerformanceMonitor.instance = new PerformanceMonitor();
    }
    return PerformanceMonitor.instance;
  }

  mark(name: string) {
    this.marks.set(name, performance.now());
  }

  measure(name: string, startMark: string, endMark?: string) {
    const startTime = this.marks.get(startMark);
    if (!startTime) {
      logger.warn(`Start mark "${startMark}" not found`);
      return;
    }

    const endTime = endMark ? this.marks.get(endMark) : performance.now();
    if (!endTime) {
      logger.warn(`End mark "${endMark}" not found`);
      return;
    }

    const duration = endTime - startTime;
    this.measures.push({
      name,
      duration,
      timestamp: Date.now(),
    });

    if (process.env.NODE_ENV === 'development') {
      logger.log(`⏱️ [${name}] ${duration.toFixed(2)}ms`);
    }
  }

  getMeasures() {
    return [...this.measures];
  }

  clear() {
    this.marks.clear();
    this.measures = [];
  }

  report() {
    console.group('📈 Performance Measures');
    this.measures.forEach((measure) => {
      logger.log(`  ${measure.name}: ${measure.duration.toFixed(2)}ms`);
    });
    console.groupEnd();
  }
}

export const performanceMonitor = PerformanceMonitor.getInstance();

/**
 * 🟡 P1-1: 前端权限路由守卫
 *
 * 提供统一的权限控制体系
 *
 * 核心组件:
 * 1. PermissionGuard - 路由级权限守卫
 * 2. PermissionCheck - 组件级权限检查
 * 3. usePermission - 权限查询 Hook
 * 4. 权限元数据配置
 *
 * 使用方式:
 * // 1. 路由守卫 (App.tsx)
 * <Route
 *   path="/formulas"
 *   element={
 *     <PermissionGuard required="formula:read" redirect="/login">
 *       <FormulaListPage />
 *     </PermissionGuard>
 *   }
 * />
 *
 * // 2. 组件检查 (Page 内)
 * {can('formula:write') && <EditButton />}
 *
 * // 3. 权限 Hook
 * const { can, isAdmin, hasAny } = usePermission()
 */

import { useMemo, useContext, createContext } from 'react';
import { Navigate, useLocation } from 'react-router-dom';

// 权限元数据配置
// （替换为您项目中的 store 路径
// 假设项目有全局用户信息在全局 useAuth 中
// 以下是核心功能

/**
 * 角色与权限的映射关系
 */
const ROLE_PERMISSION_MAP = {
  // 超级管理员: 所有权限
  admin: [
    'formula:read',
    'formula:write',
    'formula:delete',
    'formula:approve',
    'formula:export',
    'formula:version',
    'experiment:read',
    'experiment:write',
    'ingredient:read',
    'ingredient:write',
    'peptide:read',
    'peptide:write',
    'ai:access',
    'ai:advanced',
    'user:read',
    'user:write',
    'settings:read',
    'settings:write',
  ],
  // 研究员: 配方/实验/AI 基本权限
  'researcher': [
    'formula:read',
    'formula:write',
    'experiment:read',
    'experiment:write',
    'ingredient:read',
    'ai:access',
  ],
  // 配方师: 编辑配方权限
  'formulator': [
    'formula:read',
    'formula:write',
    'formula:version',
    'formula:export',
    'ingredient:read',
    'peptide:read',
    'ai:access',
  ],
  // 审核者: 只读 + 审核权限
  'reviewer': [
    'formula:read',
    'formula:approve',
    'formula:export',
    'experiment:read',
    'ingredient:read',
    'ingredient:write',
    'ai:access',
    'ai:advanced',
    'peptide:read',
  ],
  // 访客: 只读
  'viewer': ['formula:read', 'ingredient:read'],
};

/**
 * 获取用户的角色
 * （这里是示例代码中的用户对象的角色字段，根据项目情况替换为
 */
function getCurrentUser() {
  // 注意: 这里是模拟实现
  try {
    // 模拟返回 { role: 'admin', permissions: [] }
    const userStr = sessionStorage.getItem('user');
    if (!userStr) {
      return { role: 'viewer', permissions: [] };
    }
    const user = JSON.parse(userStr);
    return user || { role: 'viewer', permissions: [] };
  } catch {
    return { role: 'viewer', permissions: [] };
  }
}

/**
 * 获取权限列表
 */
function getRolePermissions(role: string): string[] {
  return ROLE_PERMISSION_MAP[role as keyof typeof ROLE_PERMISSION_MAP] || [];
}

/**
 * 检查用户是否具有所需权限
 */
export function hasPermission(required: string, user: any = getCurrentUser()): boolean {
  const { role, permissions } = user || getCurrentUser();

  // 获取用户的角色权限
  const rolePermissions = getRolePermissions(role || 'viewer');
  const userPerms = [...rolePermissions, ...(permissions || [])];

  // 没有权限检查
  if (Array.isArray(required)) {
    // 全部权限: 需要全部满足
    return required.every((p) => userPerms.includes(p));
  }
  // 单权限检查
  return userPerms.includes(required);
}

/**
 * 🔒 P1-1: Permission Hook
 */
export function usePermission(user: any = getCurrentUser()) {
  const permissionsKey = user?.permissions?.join(',');
  return useMemo(() => {
    const can = (required: string) => hasPermission(required, user);
    const isAdmin = user?.role === 'admin';
    const isFormulator = user?.role === 'formulator';
    const hasAny = (required: string[]) => required.some((p) => can(p));

    return {
      // 核心检查方法
      can, // 检查是否有指定权限
      canAny: hasAny, // 检查是否有任意权限列表中至少一个
      isAdmin, isFormulator, // 是否管理员
      // 当前角色
      role: user?.role || 'viewer',
    };
  }, [user?.role, permissionsKey]);
}

/**
 * 🔒 P1-1: 权限守卫组件（路由级保护）
 */
export function PermissionGuard({
  required, // 需要的权限
  fallback = null, // Fallback 组件（默认不通过时）
  requireAll = true, // 是否需要所有权限
  children, // 受保护的子组件
}: {
  required: string;
  fallback?: React.ReactNode;
  redirect?: string;
  requireAll?: boolean;
  children: React.ReactNode;
}) {
  const { can, canAny: hasAny } = usePermission();

  // 检查权限是否满足
  const hasAccess =
    Array.isArray(required) && !requireAll
      ? hasAny(required) // 任意权限通过
      : can(required as string);

  // 权限不通过
  if (!hasAccess) {
    return <>{fallback}</>;
  }

  // 权限通过
  return <>{children}</>;
}

/**
 * 🔒 P1-1: 登录守卫（替代 PermissionGuard，重定向模式
 */
export function ProtectedRoute({
  required,
  redirect = '/login',
  children,
}: {
  required?: string;
  redirect?: string;
  children: React.ReactNode;
}) {
  const location = useLocation();
  const { can, canAny: hasAny } = usePermission();

  // 无权限跳转
  if (Array.isArray(required) && !required.every((p) => can(p))) {
    return <Navigate to={redirect} replace state={{ from: location }} />;
  }

  // 无权限跳转
  if (!Array.isArray(required) && required && !hasAny([required])) {
    return <Navigate to={redirect} replace state={{ from: location }} />;
  }

  return <>{children}</>;
}

/**
 * 🔒 P1-1: 仅管理员可访问的守卫
 */
export function AdminOnly({ children }: { children: React.ReactNode }) {
  const { isAdmin } = usePermission();
  return isAdmin ? <>{children}</> : null;
}

/**
 * 🔒 P1-1: 权限按钮（带权限检查的按钮组件
 */
export function PermissionButton({
  required,
  children,
  className = '',
  ...props
}: {
  required: string;
  children: React.ReactNode;
  className?: string;
} & React.ButtonHTMLAttributes<HTMLButtonElement>) {
  const { can } = usePermission();

  // 检查是否有权限
  const hasAccess = Array.isArray(required)
    ? required.some((p) => can(p))
    : can(required);

  // 无权限则不渲染
  if (!hasAccess) return null;

  return (
    <button className={className} {...props}>
      {children}
    </button>
  );
}

/**
 * 🔒 P1-1: 权限菜单项（带权限检查的菜单项
 */
export function PermissionMenuItem({
  required,
  children,
  onClick,
}: {
  required: string;
  children: React.ReactNode;
  onClick?: () => void;
}) {
  const { can } = usePermission();
  const hasAccess = Array.isArray(required)
    ? required.some((p) => can(p))
    : can(required);

  if (!hasAccess) return null;

  return <li onClick={onClick}>{children}</li>;
}

/**
 * 🔒 P1-1: 权限显示组件（权限不足时显示禁用状态显示
 */
export function WithPermission({
  required,
  children,
}: {
  required: string;
  children: React.ReactNode;
}) {
  const { can } = usePermission();
  if (!can(required)) return null;
  return <>{children}</>;
}

/**
 * 🔒 P1-1: 权限信息显示组件（显示权限信息的页面
 */
export function PermissionInfo() {
  const { role } = usePermission();
  return <div>当前角色: {role}</div>;
}

/**
 * 🔒 P1-1: 权限上下文（供子组件调用）
 */
export function PermissionContextProvider({
  children,
}: {
  children: React.ReactNode;
}) {
  const { can, isAdmin, role } = usePermission();

  // 简化: 提供上下文供子组件调用
  const ctx = {
    can,
    isAdmin,
    role,
  };

  return (
    <PermissionContext.Provider value={ctx}>{children}</PermissionContext.Provider>
  );
}

/**
 * 🔒 P1-1: 权限上下文 Hook（通过 createContext 实现，供深层嵌套组件使用
 */
const PermissionContext = createContext<{
  can: (required: string) => boolean;
  isAdmin: boolean;
  role: string;
} | null>(null);

/**
 * 🔒 P1-1: 权限上下文 Hook（供子组件调用）
 */
export function usePermissionContext() {
  const context = useContext(PermissionContext);
  const fallback = usePermission();
  if (!context) {
    // 未在组件中调用
    return fallback;
  }
  return context;
}

/**
 * 🔒 P1-1: 角色守卫（仅特定角色才能访问
 */
export function RoleBasedGuard({
  allowedRoles,
  children,
}: {
  allowedRoles: string[];
  children: React.ReactNode;
}) {
  const { role } = usePermission();
  if (!allowedRoles.includes(role)) return null;

  return <>{children}</>;
}

/**
 * 🔒 P1-1: 条件守卫（自定义条件检查）
 */
export function ConditionalGuard({
  condition,
  children,
  fallback,
}: {
  condition: () => boolean;
  children: React.ReactNode;
  fallback?: React.ReactNode;
}) {
  const result = condition();
  if (!result) return <>{fallback || null}</>;
  return <>{children}</>;
}

/**
 * 🔒 P1-1: 权限验证状态（供调试使用）
 */
export function PermissionDebugInfo() {
  const { role, can, isAdmin } = usePermission();
  return (
    <div className="permission-debug">
      <div>角色: {role}</div>
      <div>是否管理员: {isAdmin ? '是' : '否'}</div>
      <div>权限列表: {can('formula:write') ? '✓' : '✗'}</div>
    </div>
  );
}

/**
 * 🔒 P1-1: 权限检查工具（页面级权限检查快速方法
 */
export function checkPagePermission(required: string): boolean {
  return hasPermission(required);
}

