/**
 * useRAGContext - RAG 知识库上下文 Hook
 *
 * 管理 RAG 开关状态、检索结果缓存，
 * 提供消息发送时的 RAG 增强注入功能。
 * v2.0: 添加种子注入状态检查
 */

import { useState, useCallback, useRef, useEffect } from 'react'
import { queryRAG, seedKnowledgeBase, getSeedStatus, type RAGChunkResult } from '@/api/rag'
import { logger } from '@/utils/safeLogger'

export interface RAGContextState {
  /** RAG 增强是否启用 */
  isEnabled: boolean
  /** 切换 RAG 状态 */
  toggleRAG: () => void
  /** 设置 RAG 状态 */
  setRAGEnabled: (enabled: boolean) => void
  /** 当前检索到的文档块 */
  chunks: RAGChunkResult[]
  /** 最后一次检索的源文件列表 */
  lastSources: string[]
  /** 对用户输入进行 RAG 增强，返回增强后的文本 */
  augment: (question: string) => Promise<string>
  /** 清除检索结果 */
  clearChunks: () => void
  /** 是否有知识库数据（用于显示） */
  hasActiveChunks: boolean
  /** 最后一次检索是否成功 */
  lastQuerySuccess: boolean
  /** 知识库是否已注入种子数据 */
  isSeeded: boolean
  /** 种子注入是否进行中 */
  isSeeding: boolean
  /** 知识库当前文档块总数（未 seed 时为 0） */
  totalChunks: number
  /** 触发种子注入 */
  triggerSeed: () => Promise<void>
}

export function useRAGContext(): RAGContextState {
  const [isEnabled, setIsEnabled] = useState(false)
  const [chunks, setChunks] = useState<RAGChunkResult[]>([])
  const [hasActiveChunks, setHasActiveChunks] = useState(false)
  const [lastSources, setLastSources] = useState<string[]>([])
  const [lastQuerySuccess, setLastQuerySuccess] = useState(false)
  const [isSeeded, setIsSeeded] = useState(false)
  const [isSeeding, setIsSeeding] = useState(false)
  const [totalChunks, setTotalChunks] = useState(0)

  // 启动时检查种子注入状态
  useEffect(() => {
    const checkSeedStatus = async () => {
      try {
        const status = await getSeedStatus()
        setIsSeeded(status.is_seeded)
        setTotalChunks(status.total_chunks ?? 0)
        if (!status.is_seeded) {
          logger.info('[useRAGContext] 知识库尚未注入种子数据，建议手动触发')
        }
      } catch (error) {
        logger.warn('[useRAGContext] 检查种子状态失败:', error)
      }
    }
    checkSeedStatus()
  }, [])

  const triggerSeed = useCallback(async () => {
    setIsSeeding(true)
    try {
      const result = await seedKnowledgeBase()
      setIsSeeded(result.seeded)
      // 注入后刷新真实块数
      try {
        const status = await getSeedStatus()
        setIsSeeded(status.is_seeded)
        setTotalChunks(status.total_chunks ?? 0)
      } catch {
        /* 状态刷新失败不影响注入结果 */
      }
      logger.info('[useRAGContext] 种子注入完成:', result)
    } catch (error) {
      logger.error('[useRAGContext] 种子注入失败:', error)
    } finally {
      setIsSeeding(false)
    }
  }, [])

  const augment = useCallback(async (question: string): Promise<string> => {
    if (!isEnabled || !question.trim()) return question

    try {
      const result = await queryRAG(question, 5)

      if (result.chunks && result.chunks.length > 0) {
        setChunks(result.chunks)
        setHasActiveChunks(true)
        setLastQuerySuccess(true)

        // 提取唯一源文件列表
        const sources = [...new Set(result.chunks.map(c => c.source))]
        setLastSources(sources)

        logger.info('[useRAGContext] RAG 检索成功:', {
          chunks: result.chunks.length,
          sources: sources.length,
          totalInKB: result.total_chunks,
        })

        return result.augmented_prompt
      }

      // 无结果时返回原始问题
      setLastQuerySuccess(false)
      setLastSources([])
      return question
    } catch (error) {
      logger.warn('[useRAGContext] RAG 检索失败，使用原始问题:', error)
      setLastQuerySuccess(false)
      return question
    }
  }, [isEnabled])

  const toggleRAG = useCallback(() => {
    setIsEnabled(prev => !prev)
    if (isEnabled) {
      setChunks([])
      setHasActiveChunks(false)
    }
  }, [isEnabled])

  const setRAGEnabled = useCallback((enabled: boolean) => {
    setIsEnabled(enabled)
    if (!enabled) {
      setChunks([])
      setHasActiveChunks(false)
    }
  }, [])

  const clearChunks = useCallback(() => {
    setChunks([])
    setHasActiveChunks(false)
    setLastSources([])
    setLastQuerySuccess(false)
  }, [])

  return {
    isEnabled,
    toggleRAG,
    setRAGEnabled,
    chunks,
    lastSources,
    augment,
    clearChunks,
    hasActiveChunks,
    lastQuerySuccess,
    isSeeded,
    isSeeding,
    totalChunks,
    triggerSeed,
  }
}

/**
 * 实时数据同步 Hook
 *
 * 监听 CDC WebSocket 消息，自动刷新相关数据。
 * 当数据库发生变更时，前端 UI 自动更新，无需手动刷新。
 *
 * 使用方式:
 *   // 在 App 或 Layout 组件中调用
 *   useRealtimeSync()
 *
 * 架构:
 *   WebSocket → CDC 消息 → React Query 缓存失效 → UI 自动更新
 */
import { useEffect, useCallback, useRef } from 'react'
import { useQueryClient } from '@tanstack/react-query'
import { wsService } from '@/services/websocket'
import { logger } from '@/utils/safeLogger'

/** CDC 变更事件数据 */
export interface CDCChangeEvent {
  entity_type: string
  entity_id: number
  action: 'INSERT' | 'UPDATE' | 'DELETE'
  changed_fields?: string[]
  user_id?: number
  timestamp?: string
}

/** WebSocket CDC 消息 */
interface CDCMessage {
  type: 'data_change'
  data: CDCChangeEvent
  channel?: string
}

/** 实体类型到 React Query key 的映射 */
const ENTITY_QUERY_KEY_MAP: Record<string, string[]> = {
  formulas: ['formulas', 'formula', 'dashboard'],
  experiments: ['experiments', 'experiment', 'dashboard'],
  users: ['users', 'user', 'auth', 'admin-users'],
  teams: ['teams', 'team'],
  team_members: ['teams', 'team'],
  notifications: ['notifications'],
  workflows: ['workflows', 'workflow'],
  ingredients: ['ingredients'],
  peptides: ['peptides', 'peptide'],
  comments: ['comments'],
  formula_versions: ['formulas', 'formula'],
  chat_sessions: ['chat-sessions', 'chat-session'],
  chat_messages: ['chat-messages', 'chat-session'],
  peptide_designs: ['peptide-designs', 'peptide-design'],
  peptide_analyses: ['peptide-analyses', 'peptide-analysis'],
  audit_logs: ['audit-logs', 'admin-audit-logs'],
  sync_logs: ['sync-logs'],
  ai_suggestions: ['ai-suggestions'],
  prompt_templates: ['prompt-templates'],
  prompt_versions: ['prompt-versions'],
}

/**
 * 实时数据同步 Hook
 *
 * 监听 WebSocket CDC 消息，自动失效相关 React Query 缓存。
 * 使用防抖机制避免频繁刷新。
 */
export function useRealtimeSync() {
  const queryClient = useQueryClient()
  const pendingInvalidations = useRef<Set<string>>(new Set())
  const flushTimer = useRef<ReturnType<typeof setTimeout> | null>(null)

  /** 批量刷新缓存（防抖 200ms） */
  const flushInvalidations = useCallback(() => {
    if (pendingInvalidations.current.size === 0) return

    const keys = Array.from(pendingInvalidations.current)
    pendingInvalidations.current.clear()

    logger.info(`🔄 CDC 触发缓存刷新: ${keys.join(', ')}`)

    for (const key of keys) {
      queryClient.invalidateQueries({ queryKey: [key] })
    }
  }, [queryClient])

  /** 计划刷新（防抖） */
  const scheduleFlush = useCallback(() => {
    if (flushTimer.current) {
      clearTimeout(flushTimer.current)
    }
    flushTimer.current = setTimeout(flushInvalidations, 200)
  }, [flushInvalidations])

  /** 处理 CDC 消息 */
  const handleCDCMessage = useCallback(
    (message: CDCMessage) => {
      if (message.type !== 'data_change') return

      const { entity_type, entity_id, action, changed_fields } = message.data
      logger.debug(
        `📡 CDC 事件: ${action} ${entity_type}:${entity_id} fields=${changed_fields?.join(',')}`,
      )

      // 获取需要刷新的查询 key
      const queryKeys = ENTITY_QUERY_KEY_MAP[entity_type]
      if (!queryKeys) {
        logger.debug(`⚠️ 未知实体类型: ${entity_type}`)
        return
      }

      // 添加到待刷新集合
      for (const key of queryKeys) {
        pendingInvalidations.current.add(key)
      }

      // 如果是特定实体的更新，也刷新该实体的详情
      if (action === 'UPDATE' || action === 'DELETE') {
        pendingInvalidations.current.add(`${entity_type.slice(0, -1)}`) // formulas → formula
      }

      // 计划刷新
      scheduleFlush()
    },
    [scheduleFlush],
  )

  useEffect(() => {
    // 订阅 WebSocket CDC 消息
    const unsubscribe = wsService.onMessage((rawMessage: unknown) => {
      try {
        const message = rawMessage as CDCMessage
        if (message.type === 'data_change') {
          handleCDCMessage(message)
        }
      } catch (error) {
        // 忽略非 CDC 消息
      }
    })

    logger.info('📡 实时数据同步已启动')

    return () => {
      unsubscribe()
      if (flushTimer.current) {
        clearTimeout(flushTimer.current)
      }
      logger.info('📡 实时数据同步已停止')
    }
  }, [handleCDCMessage])
}

/**
 * 实时实体 Hook
 *
 * 监听特定实体类型的变更，当该实体发生变更时触发回调。
 *
 * 使用方式:
 *   useRealtimeEntity('formulas', (change) => {
 *     logger.log('配方变更:', change)
 *   })
 */
export function useRealtimeEntity(
  entityType: string,
  onChange?: (change: CDCChangeEvent) => void,
) {
  const queryClient = useQueryClient()

  useEffect(() => {
    const unsubscribe = wsService.onMessage((rawMessage: unknown) => {
      try {
        const message = rawMessage as CDCMessage
        if (message.type === 'data_change' && message.data.entity_type === entityType) {
          // 刷新相关查询
          queryClient.invalidateQueries({ queryKey: [entityType] })

          // 触发回调
          onChange?.(message.data)
        }
      } catch {
        // 忽略非 CDC 消息
      }
    })

    return unsubscribe
  }, [entityType, onChange, queryClient])
}

/**
 * 实时计数 Hook
 *
 * 监听实体变更并维护一个计数器（用于未读数等场景）。
 *
 * 使用方式:
 *   const changeCount = useRealtimeCount('notifications')
 */
export function useRealtimeCount(entityType: string): number {
  const countRef = useRef(0)

  useEffect(() => {
    const unsubscribe = wsService.onMessage((rawMessage: unknown) => {
      try {
        const message = rawMessage as CDCMessage
        if (message.type === 'data_change' && message.data.entity_type === entityType) {
          if (message.data.action === 'INSERT') {
            countRef.current += 1
          }
        }
      } catch {
        // 忽略
      }
    })

    return unsubscribe
  }, [entityType])

  return countRef.current
}

import { useState, useCallback, useRef } from 'react';
import {
  GenerationStage,
  OutputFormat,
  DetailLevel,
} from '../types/report.types';
import type {
  ReportGenerationOptions,
  GeneratedReport,
  GenerationProgress,
  ReportData,
} from '../types/report.types';

export interface UseReportGeneratorReturn {
  generate: (options: ReportGenerationOptions) => Promise<GeneratedReport>;
  cancelGeneration: () => void;
  currentReport: GeneratedReport | null;
  isGenerating: boolean;
  progress: GenerationProgress | null;
  getTemplatePreview: (templateId: string) => string;
}

export function useReportGenerator(): UseReportGeneratorReturn {
  const [currentReport, setCurrentReport] = useState<GeneratedReport | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [progress, setProgress] = useState<GenerationProgress | null>(null);
  const abortRef = useRef(false);

  const updateProgress = useCallback((
    stage: GenerationStage,
    current: number,
    total: number,
    message: string,
  ) => {
    const progressData: GenerationProgress = {
      stage,
      progress: current,
      total,
      message,
    };
    setProgress(progressData);
  }, []);

  const generate = useCallback(async (
    options: ReportGenerationOptions,
  ): Promise<GeneratedReport> => {
    abortRef.current = false;
    setIsGenerating(true);

    const reportId = `report-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`;

    try {
      updateProgress(GenerationStage.INITIALIZING, 0, 8, '正在初始化报告生成...');
      await simulateDelay(200);

      if (abortRef.current) throw new Error('生成已取消');

      updateProgress(GenerationStage.LOADING_TEMPLATE, 1, 8, '加载报告模板...');
      await simulateDelay(300);

      if (abortRef.current) throw new Error('生成已取消');

      updateProgress(GenerationStage.PROCESSING_DATA, 2, 8, '处理输入数据...');
      const processedData = processReportData(options.data);
      await simulateDelay(400);

      if (abortRef.current) throw new Error('生成已取消');

      updateProgress(GenerationStage.GENERATING_SECTIONS, 3, 8, '生成报告章节...');
      const sectionsContent = generateSections(options.templateId, processedData, options.detailLevel);
      await simulateDelay(500);

      if (abortRef.current) throw new Error('生成已取消');

      updateProgress(GenerationStage.RENDERING_CHARTS, 4, 8, '渲染图表和可视化内容...');
      await simulateDelay(400);

      if (abortRef.current) throw new Error('生成已取消');

      updateProgress(GenerationStage.FORMATTING_TABLES, 5, 8, '格式化表格数据...');
      await simulateDelay(300);

      if (abortRef.current) throw new Error('生成已取消');

      updateProgress(GenerationStage.COMPILING_DOCUMENT, 6, 8, '编译文档结构...');
      const documentContent = compileDocument(sectionsContent, options);
      await simulateDelay(400);

      if (abortRef.current) throw new Error('生成已取消');

      updateProgress(GenerationStage.EXPORTING, 7, 8, `导出为${options.outputFormat}格式...`);
      const outputBlob = await exportDocument(documentContent, options.outputFormat, options.fileName);
      await simulateDelay(300);

      if (abortRef.current) throw new Error('生成已取消');

      updateProgress(GenerationStage.COMPLETED, 8, 8, '报告生成完成！');

      const generatedReport: GeneratedReport = {
        id: reportId,
        templateId: options.templateId,
        options,
        status: 'completed',
        progress: {
          stage: GenerationStage.COMPLETED,
          progress: 8,
          total: 8,
          message: '完成',
        },
        outputFile: outputBlob,
        generatedAt: new Date().toISOString(),
        pageCount: estimatePageCount(documentContent),
        fileSize: outputBlob.size,
      };

      setCurrentReport(generatedReport);
      setIsGenerating(false);

      return generatedReport;

    } catch (error) {
      setIsGenerating(false);

      return {
        id: reportId,
        templateId: options.templateId,
        options,
        status: 'failed',
        progress: {
          stage: GenerationStage.ERROR,
          progress: progress?.progress || 0,
          total: progress?.total || 0,
          message: error instanceof Error ? error.message : '未知错误',
        },
        error: error instanceof Error ? error.message : '报告生成失败',
        generatedAt: new Date().toISOString(),
      };
    }
  }, [updateProgress]);

  const cancelGeneration = useCallback(() => {
    abortRef.current = true;
  }, []);

  const getTemplatePreview = useCallback((templateId: string): string => {
    const templatePreviews: Record<string, string> = {
      'academic-research-v1': `
        <div style="font-family: serif; padding: 20px;">
          <h1 style="text-align: center; font-size: 24px; margin-bottom: 20px;">学术论文预览</h1>
