function simulateDelay(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function processReportData(data: ReportData): ReportData {
  return {
    ...data,
    authors: data.authors.map(author => ({
      name: author.name || '未指定',
      email: author.email,
      affiliation: author.affiliation || 'RMFOOD配方平台',
    })),
    date: (data.date || new Date().toISOString().split('T')[0]) ?? '',
    keywords: data.keywords || [],
    tables: data.tables || [],
    charts: data.charts || [],
    images: data.images || [],
  };
}

function generateSections(
  templateId: string,
  data: ReportData,
  detailLevel: DetailLevel,
): Record<string, any> {
  return {
    title: data.title,
    metadata: {
      authors: data.authors,
      date: data.date,
      language: 'zh-CN',
    },
    sections: generateSectionContent(templateId, data, detailLevel),
  };
}

function generateSectionContent(
  _templateId: string,
  data: ReportData,
  _detailLevel: DetailLevel,
): {id: string, title: string, content: string}[] {
  const baseSections = [
    { id: 'title', title: '标题', content: data.title },
    { id: 'abstract', title: '摘要', content: data.abstract || '' },
    { id: 'content', title: '正文', content: JSON.stringify(data.content, null, 2) },
  ];

  if (data.tables && data.tables.length > 0) {
    baseSections.push({
      id: 'tables',
      title: '表格数据',
      content: `共 ${data.tables.length} 个表格`,
    });
  }

  if (data.charts && data.charts.length > 0) {
    baseSections.push({
      id: 'charts',
      title: '图表',
      content: `共 ${data.charts.length} 个图表`,
    });
  }

  return baseSections;
}

function compileDocument(
  sectionsContent: Record<string, any>,
  options: ReportGenerationOptions,
): string {
  const formatLabels: Record<OutputFormat, string> = {
    [OutputFormat.PDF]: 'PDF',
    [OutputFormat.DOCX]: 'Word',
    [OutputFormat.HTML]: 'HTML',
    [OutputFormat.MARKDOWN]: 'Markdown',
  };

  return JSON.stringify({
    format: formatLabels[options.outputFormat],
    templateId: options.templateId,
    language: options.language,
    detailLevel: options.detailLevel,
    generatedAt: new Date().toISOString(),
    content: sectionsContent,
  }, null, 2);
}

async function exportDocument(
  content: string,
  format: OutputFormat,
  fileName?: string,
): Promise<Blob> {
  let mimeType: string;
  let extension: string;

  switch (format) {
    case OutputFormat.PDF:
      mimeType = 'application/pdf';
      extension = '.pdf';
      break;
    case OutputFormat.DOCX:
      mimeType = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
      extension = '.docx';
      break;
    case OutputFormat.HTML:
      mimeType = 'text/html';
      extension = '.html';
      break;
    case OutputFormat.MARKDOWN:
      mimeType = 'text/markdown';
      extension = '.md';
      break;
    default:
      mimeType = 'application/octet-stream';
      extension = '.txt';
  }

  const finalFileName = fileName || `report_${new Date().toISOString().slice(0, 10)}${extension}`;

  if (format === OutputFormat.HTML) {
    const htmlContent = generateHTMLDocument(content);
    return new Blob([htmlContent], { type: mimeType });
  } else if (format === OutputFormat.MARKDOWN) {
    const mdContent = generateMarkdownDocument(content);
    return new Blob([mdContent], { type: mimeType });
  } else {
    const textContent = `${finalFileName}\n${'='.repeat(finalFileName.length)}\n\n${content}`;
    return new Blob([textContent], { type: 'application/octet-stream' });
  }
}

function generateHTMLDocument(content: string): string {
  return `<!DOCTYPE html>
<html lang="zh-CN">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>生成的报告</title>
  <style>
    body { font-family: "SimSun", "Times New Roman", serif; line-height: 1.6; max-width: 800px; margin: 40px auto; padding: 20px; }
    h1 { color: #003E87; text-align: center; border-bottom: 3px solid #003E87; padding-bottom: 10px; }
    h2 { color: var(--color-secondary-500); margin-top: 24px; border-left: 4px solid var(--color-secondary-500); padding-left: 12px; }
    table { width: 100%; border-collapse: collapse; margin: 16px 0; }
    th, td { border: 1px solid #d1d5db; padding: 8px; text-align: left; }
    th { background-color: #f3f4f6; font-weight: bold; }
    .metadata { background-color: #f9fafb; padding: 16px; border-radius: 8px; margin: 20px 0; }
  </style>
</head>
<body>
  <pre style="white-space: pre-wrap; word-wrap: break-word;">${escapeHtml(content)}</pre>
</body>
</html>`;
}

function generateMarkdownDocument(content: string): string {
  return `# 生成的报告\n\n---\n\n${content}\n\n---\n\n*由 RMFOOD配方平台自动生成*`;
}

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function estimatePageCount(content: string): number {
  const wordsPerPage = 500;
  const wordCount = content.split(/\s+/).length;
  return Math.max(1, Math.ceil(wordCount / wordsPerPage));
}

import { useState, useCallback, useMemo } from 'react';
import { SectionType, DetailLevel } from '../types/report.types';
import type { ReportSection } from '../types/report.types';

export interface UseReportStructureReturn {
  sections: ReportSection[];
  addSection: (section: ReportSection, parentId?: string) => void;
  removeSection: (sectionId: string) => void;
  updateSection: (sectionId: string, updates: Partial<ReportSection>) => void;
  moveSection: (sectionId: string, direction: 'up' | 'down') => void;
  moveSectionToIndex: (sectionId: string, newIndex: number) => void;
  reorderSections: (startIndex: number, endIndex: number) => void;
  toggleSectionVisibility: (sectionId: string) => void;
  setSectionDetailLevel: (sectionId: string, level: DetailLevel) => void;
  duplicateSection: (sectionId: string) => void;
  resetToTemplate: (templateSections: ReportSection[]) => void;
  getVisibleSections: () => ReportSection[];
  getFlatSections: () => ReportSection[];
  getSectionById: (sectionId: string) => ReportSection | undefined;
  exportStructure: () => ReportSection[];
  importStructure: (sections: ReportSection[]) => void;
}

export function useReportStructure(
  initialSections: ReportSection[] = [],
): UseReportStructureReturn {
  const [sections, setSections] = useState<ReportSection[]>(initialSections);

  const addSection = useCallback((newSection: ReportSection, parentId?: string) => {
    if (parentId) {
      setSections(prev =>
        prev.map(section => {
          if (section.id === parentId) {
            const children = section.children || [];
            return {
              ...section,
              children: [...children, { ...newSection, order: children.length }],
            };
          }
          return section;
        }),
      );
    } else {
      setSections(prev => [
        ...prev,
        { ...newSection, order: prev.length },
      ]);
    }
  }, []);

  const removeSection = useCallback((sectionId: string) => {
    setSections(prev => prev.filter(s => s.id !== sectionId));
  }, []);

  const updateSection = useCallback((sectionId: string, updates: Partial<ReportSection>) => {
    const updateRecursive = (secs: ReportSection[]): ReportSection[] => {
      return secs.map(section => {
        if (section.id === sectionId) {
          return { ...section, ...updates };
        }
        if (section.children) {
          return {
            ...section,
            children: updateRecursive(section.children),
          };
        }
        return section;
      });
    };

    setSections(updateRecursive);
  }, []);

  const moveSection = useCallback((sectionId: string, direction: 'up' | 'down') => {
    setSections(prev => {
      const index = prev.findIndex(s => s.id === sectionId);
      if (index === -1) return prev;

      const newIndex = direction === 'up' ? index - 1 : index + 1;
      if (newIndex < 0 || newIndex >= prev.length) return prev;

      const newSections = [...prev];
      [newSections[index], newSections[newIndex]] = [newSections[newIndex], newSections[index]];

      return newSections.map((s, i) => ({ ...s, order: i }));
    });
  }, []);

  const moveSectionToIndex = useCallback((sectionId: string, newIndex: number) => {
    setSections(prev => {
      const currentIndex = prev.findIndex(s => s.id === sectionId);
      if (currentIndex === -1 || currentIndex === newIndex) return prev;

      const newSections = [...prev];
      const [removed] = newSections.splice(currentIndex, 1);
      newSections.splice(newIndex, 0, removed);

      return newSections.map((s, i) => ({ ...s, order: i }));
    });
  }, []);

  const reorderSections = useCallback((startIndex: number, endIndex: number) => {
    setSections(prev => {
      const result = Array.from(prev);
      const [removed] = result.splice(startIndex, 1);
      result.splice(endIndex, 0, removed);

      return result.map((s, i) => ({ ...s, order: i }));
    });
  }, []);

  const toggleSectionVisibility = useCallback((sectionId: string) => {
    updateSection(sectionId, { visible: !getSectionByIdHelper(sections, sectionId)?.visible });
  }, [updateSection, sections]);

  const setSectionDetailLevel = useCallback((sectionId: string, level: DetailLevel) => {
    updateSection(sectionId, { detailLevel: level });
  }, [updateSection]);

  const duplicateSection = useCallback((sectionId: string) => {
    const sectionToDuplicate = getSectionByIdHelper(sections, sectionId);
    if (!sectionToDuplicate) return;

    const duplicated: ReportSection = {
      ...sectionToDuplicate,
      id: `${sectionId}-copy-${Date.now()}`,
      title: `${sectionToDuplicate.title} (副本)`,
      order: sections.length,
    };

    setSections(prev => [...prev, duplicated]);
  }, [sections]);

  const resetToTemplate = useCallback((templateSections: ReportSection[]) => {
    setSections(templateSections);
  }, []);

  const getVisibleSections = useCallback((): ReportSection[] => {
    return sections.filter(s => s.visible).sort((a, b) => a.order - b.order);
  }, [sections]);

  const getFlatSections = useCallback((): ReportSection[] => {
    const flatten = (secs: ReportSection[], depth = 0): ReportSection[] => {
      return secs.reduce<ReportSection[]>((acc, section) => {
        acc.push({ ...section, level: depth });
        if (section.children && section.children.length > 0) {
          acc.push(...flatten(section.children, depth + 1));
        }
        return acc;
      }, []);
    };

    return flatten(sections).sort((a, b) => a.order - b.order);
  }, [sections]);

  const getSectionById = useCallback((sectionId: string): ReportSection | undefined => {
    return getSectionByIdHelper(sections, sectionId);
  }, [sections]);

  const exportStructure = useCallback((): ReportSection[] => {
    return JSON.parse(JSON.stringify(sections));
  }, [sections]);

  const importStructure = useCallback((importedSections: ReportSection[]) => {
    setSections(importedSections);
  }, []);

  return {
    sections,
    addSection,
    removeSection,
    updateSection,
    moveSection,
    moveSectionToIndex,
    reorderSections,
    toggleSectionVisibility,
    setSectionDetailLevel,
    duplicateSection,
    resetToTemplate,
    getVisibleSections,
    getFlatSections,
    getSectionById,
    exportStructure,
    importStructure,
  };
}

function getSectionByIdHelper(
  sections: ReportSection[],
  sectionId: string,
): ReportSection | undefined {
  for (const section of sections) {
    if (section.id === sectionId) return section;
    if (section.children) {
      const found = getSectionByIdHelper(section.children, sectionId);
      if (found) return found;
    }
  }
  return undefined;
}

