// 语言包映射
const MESSAGES_MAP: Record<Locale, TranslationMessages> = {
  'zh-CN': ZH_CN_MESSAGES,
  'en-US': EN_US_MESSAGES,
  'de-DE': DE_DE_MESSAGES,
  'ko-KR': KO_KR_MESSAGES,
};

// ═════════════════════════════════════════════
// 🟡 P4-5: 翻译函数
// ═════════════════════════════════════════════

/**
 * 获取嵌套对象属性（安全访问）
 */
function getNestedValue(obj: Record<string, unknown>, path: string): unknown {
  const parts = path.split('.');
  let current: unknown = obj;
  for (const key of parts) {
    if (current == null || typeof current !== 'object') return undefined;
    current = (current as Record<string, unknown>)[key];
  }
  return current;
}

/**
 * 替换插值变量
 * 支持 {{name}} 和 {{name, format}} 两种格式
 */
function interpolate(
  template: string,
  params?: Record<string, any>,
  locale?: Locale,
): string {
  if (!params || !template) return template;

  return template.replace(/\{\{(\w+)(?:,\s*(\w+))?\}\}/g, (match, key, format) => {
    const value = params[key];

    if (value === undefined || value === null) {
      return match; // 保留原样
    }

    // 处理格式
    if (format) {
      const localeCode = locale || 'zh-CN';
      try {
        if (format.startsWith('number')) {
          return new Intl.NumberFormat(localeCode.replace('-', '_')).format(value);
        }
        if (format.startsWith('date')) {
          const date = value instanceof Date ? value : new Date(value);
          return new Intl.DateTimeFormat(localeCode.replace('-', '_')).format(date);
        }
      } catch {
        return String(value);
      }
    }

    return String(value);
  });
}

// ═════════════════════════════════════════════
// 🟡 P4-5: 上下文
// ═════════════════════════════════════════════

const TranslationContext = createContext<TranslationContextValue | null>(null);

interface TranslationProviderProps {
  children: ReactNode;
  initialLocale?: Locale;
  onLocaleChange?: (locale: Locale) => void;
  fallbackLocale?: Locale;
}

export function TranslationProvider({
  children,
  initialLocale = 'zh-CN',
  onLocaleChange,
  fallbackLocale = 'zh-CN',
}: TranslationProviderProps) {
  const [locale, setLocaleState] = useState<Locale>(() => {
    // 从 localStorage 读取
    if (typeof window !== 'undefined') {
      const stored = localStorage.getItem('rmfood_locale') as Locale;
      if (stored && LOCALES[stored]) {
        return stored;
      }
    }
    return initialLocale;
  });

  const [isLoading, setIsLoading] = useState(false);

  // 加载语言包（支持懒加载）
  const loadLocale = useCallback(async (targetLocale: Locale) => {
    // 如果已加载，直接使用
    if (MESSAGES_MAP[targetLocale]) {
      return;
    }

    setIsLoading(true);
    try {
      // 懒加载示例：实际应从 API 获取
      // const messages = await fetch(`/locales/${targetLocale}.json`).then(r => r.json());
      // MESSAGES_MAP[targetLocale] = messages;

      // 简化：使用中文作为占位
      MESSAGES_MAP[targetLocale] = ZH_CN_MESSAGES;
    } catch (error) {
      logger.error(`Failed to load locale: ${targetLocale}`, error);
    } finally {
      setIsLoading(false);
    }
  }, []);

  // 切换语言
  const setLocale = useCallback(
    (newLocale: Locale) => {
      if (!LOCALES[newLocale]) {
        if (import.meta.env.DEV) logger.warn(`Unknown locale: ${newLocale}`);
        return;
      }

      setLocaleState(newLocale);

      // 持久化
      if (typeof window !== 'undefined') {
        localStorage.setItem('rmfood_locale', newLocale);
        document.documentElement.lang = newLocale;

        // 设置 RTL
        document.documentElement.dir = LOCALES[newLocale].rtl ? 'rtl' : 'ltr';
      }

      // 回调
      onLocaleChange?.(newLocale);

      // 加载语言包
      loadLocale(newLocale);
    },
    [onLocaleChange, loadLocale],
  );

  // 翻译函数
  const t = useCallback(
    (key: string, params?: Record<string, any>): string => {
      const messages = MESSAGES_MAP[locale] || MESSAGES_MAP[fallbackLocale];
      const fallbackMessages = MESSAGES_MAP[fallbackLocale];

      // 查找翻译
      let translation = getNestedValue(messages, key);

      // 尝试回退到默认语言
      if (translation === undefined) {
        translation = getNestedValue(fallbackMessages, key);
      }

      // 如果仍找不到，返回 key
      if (translation === undefined) {
        if (import.meta.env.DEV) {
          logger.warn(`Missing translation: ${key}`);
        }
        return key;
      }

      // 插值
      return interpolate(typeof translation === 'string' ? translation : key, params, locale);
    },
    [locale, fallbackLocale],
  );

  // 格式化函数
  const formatNumber = useCallback(
    (value: number, options?: Intl.NumberFormatOptions) => {
      void options;
      return new Intl.NumberFormat(locale.replace('-', '_')).format(value);
    },
    [locale],
  );

  const formatDate = useCallback(
    (date: Date | string, options?: Intl.DateTimeFormatOptions) => {
      const d = date instanceof Date ? date : new Date(date);
      return new Intl.DateTimeFormat(locale.replace('-', '_'), options).format(d);
    },
    [locale],
  );

  const formatCurrency = useCallback(
    (value: number, currency: string = 'CNY') => {
      return new Intl.NumberFormat(locale.replace('-', '_'), {
        style: 'currency',
        currency,
      }).format(value);
    },
    [locale],
  );

  // 初始化
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    loadLocale(locale);
  }, [locale, loadLocale]);

  const value: TranslationContextValue = {
    locale,
    setLocale,
    t,
    formatNumber,
    formatDate,
    formatCurrency,
    isLoading,
    availableLocales: Object.keys(LOCALES) as Locale[],
  };

  return <TranslationContext.Provider value={value}>{children}</TranslationContext.Provider>;
}

// ═════════════════════════════════════════════
// 🟡 P4-5: Hook
// ═════════════════════════════════════════════

export function useTranslation(): TranslationContextValue {
  const context = useContext(TranslationContext);
  if (!context) {
    // 提供默认实现
    return {
      locale: 'zh-CN',
      setLocale: () => {},
      t: (key) => key,
      formatNumber: (v) => String(v),
      formatDate: (v) => String(v),
      formatCurrency: (v) => String(v),
      isLoading: false,
      availableLocales: ['zh-CN', 'en-US'],
    };
  }
  return context;
}

// ═════════════════════════════════════════════
// 🟡 P4-5: 非 Hook 翻译函数（用于非组件文件）
// ═════════════════════════════════════════════

let _currentLocale: Locale = 'zh-CN';

export function setGlobalLocale(locale: Locale) {
  _currentLocale = locale;
  if (typeof window !== 'undefined') {
    localStorage.setItem('rmfood_locale', locale);
  }
}

export function tf(key: string, params?: Record<string, any>): string {
  const messages = MESSAGES_MAP[_currentLocale] || ZH_CN_MESSAGES;
  const translation = getNestedValue(messages, key);

  if (translation === undefined) {
    return key;
  }

  return interpolate(typeof translation === 'string' ? translation : key, params, _currentLocale);
}

// ═════════════════════════════════════════════
// 🟡 P4-5: 组件导出
// ═════════════════════════════════════════════

interface LocaleSwitcherProps {
  className?: string;
}

export function LocaleSwitcher({ className }: LocaleSwitcherProps) {
  const { locale, setLocale, availableLocales } = useTranslation();

  return (
    <select
      className={className}
      value={locale}
      onChange={(e) => setLocale(e.target.value as Locale)}
      style={{
        padding: '4px 8px',
        borderRadius: '4px',
        border: '1px solid #ddd',
        background: 'white',
        cursor: 'pointer',
      }}
    >
      {availableLocales.map((loc) => (
        <option key={loc} value={loc}>
          {LOCALES[loc]?.nativeName || loc}
        </option>
      ))}
    </select>
  );
}

// ═════════════════════════════════════════════
// 🟡 P4-5: 导出
// ═════════════════════════════════════════════

// LOCALES is exported at line 83 above — no duplicate export needed.

/**
 * RMFOOD 配方平台 - Motion 工具函数
 *
 * 所有动画均使用 compositor-friendly 属性 (transform, opacity)
 * 时长和缓动曲线来自设计系统 token (tokens.css)
 * 符合 prefers-reduced-motion 无障碍要求
 */

/**
 * 淡入动画
 * @param duration - 动画持续时间 (毫秒)
 * @returns CSS transition 字符串
 */
export function fadeIn(duration: number = 300): string {
 return `opacity ${duration}ms var(--ease-out-expo)`;
}

/**
 * 淡出动画
 * @param duration - 动画持续时间 (毫秒)
 * @returns CSS transition 字符串
 */
export function fadeOut(duration: number = 300): string {
 return `opacity ${duration}ms var(--ease-standard)`;
}

/**
 * 上滑进入动画
 * @param distance - 初始偏移距离 (像素)
 * @param duration - 动画持续时间 (毫秒)
 * @returns CSS transform transition 字符串
 */
export function slideUp(distance: number = 20, duration: number = 300): string {
 return `transform ${duration}ms var(--ease-out-expo)`;
}

/**
 * 下滑进入动画
 * @param distance - 初始偏移距离 (像素)
 * @param duration - 动画持续时间 (毫秒)
 * @returns CSS transform transition 字符串
 */
export function slideDown(distance: number = 20, duration: number = 300): string {
 return `transform ${duration}ms var(--ease-out-expo)`;
}

/**
 * 缩放脉冲动画
 * @param scale - 缩放比例
 * @param duration - 动画持续时间 (毫秒)
 * @returns CSS transform transition 字符串
 */
export function scalePulse(scale: number = 1.05, duration: number = 200): string {
 return `transform ${duration}ms var(--ease-standard)`;
}

/**
 * 获取当前动画配置
 * @param motionToken - 设计系统 motion token 名称
 * @returns CSS transition 配置对象
 */
export function getMotionConfig(motionToken: string): {
 duration: number;
 easing: string;
 transition: string;
} {
 const tokenMap: Record<string, { duration: number; easing: string }> = {
 fast: { duration: 150, easing:'var(--ease-standard)' },
 normal: { duration: 300, easing:'var(--ease-out-expo)' },
 slow: { duration: 500, easing:'var(--ease-standard)' },
 };

 const config = tokenMap[motionToken] || tokenMap['normal'];
 return {
 ...config,
 transition: `all ${config.duration}ms ${config.easing}`,
 };
}

/**
 * 检查是否应该禁用动画 (用户偏好减少动画)
 */
export function shouldReduceMotion(): boolean {
 if (typeof window !=='undefined') {
 const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
 return mediaQuery.matches;
 }
 return false;
}

/**
 * 重型依赖动态导入
 *
 * 按需加载重型库，减少初始 bundle 大小。
 * 使用方式:
 * const { BarChart, LineChart } = await loadRecharts()
 * const pdf = await loadJsPDF()
 */

/** Recharts 图表库 (按需加载) */
export const loadRecharts = () => import('recharts')

/** D3 可视化库 (按需加载) */
export const loadD3 = () => import('d3')

/** docx 文档生成 (按需加载) */
export const loadDocx = () => import('docx')

/** jsPDF PDF 生成 (按需加载) */
export const loadJsPDF = () => import('jspdf')

/** ExcelJS Excel 处理 (按需加载) */
export const loadExcelJS = () => import('exceljs')

/** html2canvas 截图 (按需加载) */
export const loadHtml2Canvas = () => import('html2canvas')

/**
 * 预加载指定依赖（在空闲时加载）
 */
export type HeavyDep ='recharts' |'d3' |'docx' |'jspdf' |'exceljs' |'html2canvas'

const loaders: Record<HeavyDep, () => Promise<any>> = {
 recharts: loadRecharts,
 d3: loadD3,
 docx: loadDocx,
 jspdf: loadJsPDF,
 exceljs: loadExcelJS,
 html2canvas: loadHtml2Canvas,
}

const loaded = new Set<string>()

export function preloadOnIdle(dep: HeavyDep): void {
 if (loaded.has(dep)) return
 if ('requestIdleCallback' in window) {
 requestIdleCallback(() => {
 loaders[dep]().then(() => loaded.add(dep))
 })
 } else {
 setTimeout(() => {
 loaders[dep]().then(() => loaded.add(dep))
 }, 1000)
 }
}

export function isDepLoaded(dep: HeavyDep): boolean {
 return loaded.has(dep)
}

