                      <span className="text-xs px-1.5 py-0.5 rounded-[var(--radius-pill)] font-medium" style={r.type === '配方' ? { backgroundColor: 'var(--color-primary-container)', color: 'var(--color-primary-text)' } : { backgroundColor: 'var(--color-secondary-container)', color: 'var(--color-secondary)' }}>{r.type}</span>
                      <span className="text-sm text-[var(--text-primary)] truncate">{r.title}</span>
                      <ArrowRight size={12} className="text-[var(--text-muted)] ml-auto shrink-0" aria-hidden="true" />
                    </Link>
                  ))
                ) : (
                  <div className="px-[var(--space-apple-md)] py-[var(--space-apple-sm)] text-sm text-[var(--text-muted)] text-center">{t('ai.page.noResults')}</div>
                )}
              </div>
            )}
          </div>

          {/* ── 统计卡片 — Dashboard 风格，DESIGN.md 规范 ── */}
          <section aria-label={t('ai.page.moduleStats')} className="grid grid-cols-2 md:grid-cols-4 gap-4">
            {/* 主卡（large） */}
            <StatCard
              label="智能对话"
              value={chatCount}
              icon={MessageSquare}
              variant="primary"
              size="large"
              subtitle={`累计 ${chatCount > 0 ? chatCount.toLocaleString() : '0'} 次对话`}
              className="cursor-pointer"
              onClick={() => handleStatCardClick('chat', '智能对话')}
            />
            <StatCard
              label="配方生成"
              value={generateCount}
              icon={Sparkles}
              variant="secondary"
              size="large"
              subtitle={`累计生成 ${generateCount > 0 ? generateCount.toLocaleString() : '0'} 个配方`}
              className="cursor-pointer"
              onClick={() => handleStatCardClick('generate', '配方生成')}
            />
            <StatCard
              label="安全检查"
              value={safetyChecks}
              icon={Shield}
              variant="warning"
              size="large"
              subtitle={`累计检查 ${safetyChecks > 0 ? safetyChecks.toLocaleString() : '0'} 次`}
              className="cursor-pointer"
              onClick={() => handleStatCardClick('safety', '安全检查')}
            />
            <StatCard
              label="协同分析"
              value={synergyCount}
              icon={GitMerge}
              variant="success"
              size="large"
              subtitle={`累计分析 ${synergyCount > 0 ? synergyCount.toLocaleString() : '0'} 次`}
              className="cursor-pointer"
              onClick={() => handleStatCardClick('synergy', '协同分析')}
            />
            {/* 辅卡（default） */}
            <StatCard
              label="肽序列分析"
              value={peptideAnalyzeCount}
              icon={Dna}
              variant="info"
              subtitle="{t('ai.page.peptideSeqSubtitle')}"
              className="cursor-pointer"
              onClick={() => handleStatCardClick('peptide-analyze', '肽序列分析')}
            />
            <StatCard
              label="肽设计优化"
              value={peptideDesignCount}
              icon={Dna}
              variant="success"
              subtitle="{t('ai.page.peptideDesignSubtitle')}"
              className="cursor-pointer"
              onClick={() => handleStatCardClick('peptide-design', '肽设计优化')}
            />
            <StatCard
              label="模型状态"
              value={llmAvailable ? '在线' : '离线'}
              icon={Bot}
              variant={llmAvailable ? 'success' : 'warning'}
              subtitle={llmAvailable ? 'LLM 服务正常' : '请检查模型配置'}
              className="cursor-pointer"
              onClick={() => handleStatCardClick('config', '模型状态')}
            />
            <StatCard
              label="知识库"
              value={knowledgeDocCount}
              icon={Database}
              variant="secondary"
              subtitle={`${knowledgeDocCount} 篇文档`}
              className="cursor-pointer"
              onClick={() => handleStatCardClick('knowledge', '知识库')}
            />
          </section>

          {/* 统计接口失败时必须显式提示，否则 9 张卡片会静默显示全 0 */}
          {statsIsError && (
            <div
              role="status"
              className="flex items-center gap-2 rounded-[var(--radius-Apple-sm)] border-[var(--color-warning-border)] bg-[var(--color-warning-container)] px-[var(--space-apple-sm)] py-2 text-xs text-[var(--color-warning-text)]"
