                        )}
                      </div>
                      <div ref={(el) => { tabGroupRefs.current.set(group.key, el); }} className="p-2 flex gap-1.5 overflow-x-auto scrollbar-hide">
                        {group.tabs.map((t) => {
                          const TabIcon = t.icon;
                          const isSelected = tab === t.value;
                          return (
                            <button
                              key={t.value}
                              onClick={() => handleTabChange(t.value as AITab)}
                              role="tab"
                              aria-selected={isSelected}
                              aria-controls={`panel-${t.value}`}
                              className={`flex min-h-[44px] items-center gap-1.5 px-[var(--space-apple-sm)] py-2 rounded-[var(--radius-Apple-sm)] text-xs font-medium whitespace-nowrap transition-all duration-150 ${
                                isSelected
                                  ? `${c.bgActive} ${c.textActive}`
                                  : 'text-[var(--text-muted)] hover:bg-[var(--bg-secondary)]'
                              }`}
                            >
                              <TabIcon className="w-3.5 h-3.5" aria-hidden="true" />
                              <span>{t.label}</span>
                              {t.badge != null && t.badge > 0 && (
                                <span className={`h-4 px-1 rounded-[var(--radius-Apple-sm)] text-xs font-semibold ${isSelected ? `bg-[var(--bg-tertiary)]/70 ${c.textActive}` : 'bg-[var(--bg-tertiary)] text-[var(--text-muted)]'}`}>{t.badge}</span>
                              )}
                            </button>
                          );
                        })}
                      </div>
                    </div>
                  );
                })}
              </div>
            {/* Tab Panels — 条件渲染，避免 Radix Tabs 状态冲突 */}
            <div className="mt-[var(--space-apple-md)]">
              {tab === 'chat' && (
                <Suspense fallback={<TabLoadingSkeleton />}>

                  <div role="tabpanel" id="panel-chat" aria-label={t('ai.page.panelChat')}>
                    <ErrorBoundary moduleName="智能对话">
                      <ChatStateProvider>
                        <ChatTab />
                      </ChatStateProvider>
                    </ErrorBoundary>
                  </div>
                </Suspense>
              )}
              {tab === 'generate' && (
                <Suspense fallback={<TabLoadingSkeleton />}>

                  <div role="tabpanel" id="panel-generate" aria-label={t('ai.page.panelGenerate')}>
                    <ErrorBoundary moduleName="配方生成">
                    <GenerateTab llmAvailable={llmAvailable} modelStatus={modelStatus || {}} />
                  </ErrorBoundary>

                  </div>
                </Suspense>
              )}
              {tab === 'genetic' && (
                <Suspense fallback={<TabLoadingSkeleton />}>

                  <div role="tabpanel" id="panel-genetic" aria-label={t('ai.page.panelGenetic')}>
                    <div className="mb-[var(--space-apple-md)]">
                    <Tabs
                      value={geneticMode}
                      onValueChange={(v) => {
                        setGeneticMode(v as 'single' | 'multi' | 'formula');
                        if (v === 'formula') {
                          announceToScreenReader('切换到配方优化模式');
                        } else {
                          announceToScreenReader(v === 'multi' ? '切换到多目标优化模式' : '切换到单目标遗传算法模式');
                        }
                      }}
                    >
                      <TabsList className="mb-[var(--space-apple-md)]" role="tablist" aria-label={t('ai.page.geneticModeSwitch')}>
                        <TabsTrigger value="single" role="tab" aria-selected={geneticMode === 'single'}>
                          <Dna className="w-3.5 h-3.5 mr-1.5 text-[var(--color-accent-text)]" aria-hidden="true" />
                          单目标 (GA)
                        </TabsTrigger>
                        <TabsTrigger value="multi" role="tab" aria-selected={geneticMode === 'multi'}>
                          <GitBranch className="w-3.5 h-3.5 mr-1.5 text-[var(--color-accent-text)]" aria-hidden="true" />
                          多目标 (NSGA-II)
                        </TabsTrigger>
                        <TabsTrigger value="formula" role="tab" aria-selected={geneticMode === 'formula'}>
                          <FileText className="w-3.5 h-3.5 mr-1.5 text-[var(--color-primary-text)]" aria-hidden="true" />
                          配方优化
                        </TabsTrigger>
                      </TabsList>
                      <TabsContent value="single">
                        <GeneticAlgorithmPanel />
                      </TabsContent>
                      <TabsContent value="multi">
                        <MultiObjectivePanel />
                      </TabsContent>
                      <TabsContent value="formula">
                        <Suspense fallback={<TabLoadingSkeleton />}>
                          <FormulaInputWithOptimization />
                        </Suspense>
                      </TabsContent>
                      </Tabs>
                    </div>
                  </div>
                </Suspense>
              )}
              {tab === 'safety' && (
                <Suspense fallback={<TabLoadingSkeleton />}>

                  <div role="tabpanel" id="panel-safety" aria-label={t('ai.page.panelSafety')}>
                    <ErrorBoundary moduleName="安全检查">
                    <SafetyTab />
                  </ErrorBoundary>

                  </div>
                </Suspense>
              )}
              {tab === 'synergy' && (
                <Suspense fallback={<TabLoadingSkeleton />}>

                  <div role="tabpanel" id="panel-synergy" aria-label={t('ai.page.panelSynergy')}>
                    <ErrorBoundary moduleName="协同分析">
                    <SynergyTab />
                  </ErrorBoundary>

                  </div>
                </Suspense>
              )}
              {tab === 'taste' && (
                <Suspense fallback={<TabLoadingSkeleton />}>

                  <div role="tabpanel" id="panel-taste" aria-label={t('ai.page.panelTaste')}>
                    <ErrorBoundary moduleName="口感预测">
                    <TastePredictTab />
                  </ErrorBoundary>

                  </div>
                </Suspense>
              )}
              {tab === 'stability' && (
                <Suspense fallback={<TabLoadingSkeleton />}>

                  <div role="tabpanel" id="panel-stability" aria-label={t('ai.page.panelStability')}>
                    <ErrorBoundary moduleName="稳定性评估">
                    <StabilityPredictTab />
                  </ErrorBoundary>

                  </div>
                </Suspense>
              )}
              {tab === 'peptide-analyze' && (
                <Suspense fallback={<TabLoadingSkeleton />}>

                  <div role="tabpanel" id="panel-peptide-analyze" aria-label={t('ai.page.panelPeptideAnalyze')}>
                    <ErrorBoundary moduleName="肽序列分析">
                    <AdvancedPeptideAnalyzer />
                  </ErrorBoundary>

                  </div>
                </Suspense>
              )}
              {tab === 'peptide-design' && (
                <Suspense fallback={<TabLoadingSkeleton />}>

                  <div role="tabpanel" id="panel-peptide-design" aria-label={t('ai.page.panelPeptideDesign')}>
                    <ErrorBoundary moduleName="肽设计优化">
                    <AdvancedPeptideDesign />
                  </ErrorBoundary>

                  </div>
                </Suspense>
              )}
              {tab === 'knowledge' && (
                <Suspense fallback={<TabLoadingSkeleton />}>

                  <div role="tabpanel" id="panel-knowledge" aria-label={t('ai.page.panelKnowledge')}>
                    <ErrorBoundary moduleName="知识库">
                    <KnowledgeBasePanel isEmbedded />
                  </ErrorBoundary>

                  </div>
                </Suspense>
              )}
              {tab === 'config' && (
                <Suspense fallback={<TabLoadingSkeleton />}>

                  <div role="tabpanel" id="panel-config" aria-label={t('ai.page.panelConfig')}>
                    <ErrorBoundary moduleName="配置管理">
                    <ConfigManagementPanel />
                  </ErrorBoundary>

                  </div>
                </Suspense>
              )}
            </div>
          </nav>
        </main>

        {/* 全局搜索模态框 */}
        <SearchModal isOpen={searchOpen} onClose={closeSearch} />
      </div>
    </ErrorBoundary>
  );
}

/**
 * 数据分析中心页面 — 参考 Dashboard 设计风格
 * 统一使用 bg-[var(--color-primary)] 横幅、StatCard、Card+CardHeader+CardContent 模式
 */
import { useState, useEffect, useCallback, useRef, useMemo } from 'react'
import { useTranslation } from 'react-i18next'
import {
  Tabs,
  TabsList, TabsTrigger, TabsContent, useToast,
  Card, Button,
} from '@/components/ui'
import {
  BarChart3, TrendingUp,
  Activity, Users, FileText, FlaskConical, Zap,
  Download, LayoutDashboard,
  Settings2, Wifi, WifiOff,
  RefreshCw, Clock, Loader2,
} from 'lucide-react'
import type { LucideIcon } from 'lucide-react'
import { useAnalyticsWebSocket } from '@/hooks/useAnalyticsWebSocket'

// 导入功能模块
import OverviewTab from './tabs/OverviewTab'
import TrendsTab from './tabs/TrendsTab'
import ReportsTab from './tabs/ReportsTab'
import CustomTab from './tabs/CustomTab'
import BusinessInsightsTab from './tabs/BusinessInsightsTab'

// 导入企业级错误边界
import { AnalyticsErrorBoundary } from '@/components/analytics/AnalyticsErrorBoundary'
import { AnalyticsSkeleton } from '@/components/analytics/skeleton/AnalyticsSkeleton'
import { useAnalyticsData } from '@/hooks/useAnalyticsData'

type AnalyticsTab = 'overview' | 'trends' | 'reports' | 'business' | 'custom'

interface FilterConfig {
  timeRange: '7d' | '30d' | '90d' | '1y'
  categories: string[]
  status: string[]
  users: string[]
}

const TABS: { key: AnalyticsTab; labelKey: string; icon: LucideIcon }[] = [
  { key: 'overview',        labelKey: 'pages.analytics.tabOverview', icon: LayoutDashboard },
  { key: 'trends',          labelKey: 'pages.analytics.tabTrends', icon: TrendingUp },
  { key: 'reports',         labelKey: 'pages.analytics.tabReports', icon: FileText },
  { key: 'business',        labelKey: 'pages.analytics.tabBusiness', icon: FlaskConical },
  { key: 'custom',          labelKey: 'pages.analytics.tabCustom', icon: Settings2 },
]

export default function AnalyticsPage() {
  const { t, i18n } = useTranslation()
  const [tab, setTab] = useState<AnalyticsTab>('overview')
  const [showFilters, setShowFilters] = useState(false)
  const [filters, setFilters] = useState<FilterConfig>({
    timeRange: '30d',
    categories: [],
    status: [],
    users: [],
  })
  const [isLoading, setIsLoading] = useState(true)
  const filterRef = useRef<HTMLDivElement>(null)
  const toast = useToast()

  const {
    stats,
    dashboard,
    loading: dataLoading,
    error: dataError,
    lastFetched,
    refresh,
    filters: apiFilters,
  } = useAnalyticsData({
    pollInterval: 30_000,
    timeRange: filters.timeRange,
    categories: filters.categories,
    status: filters.status,
    users: filters.users,
  })

  // ─── WebSocket 实时连接 ──────────────────────────────────────
  const wsUrl = useMemo(() => {
    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:'
    // 优先使用 VITE_WS_ANALYTICS_URL（直连后端，避免依赖 dev 代理的 WS 转发）；
    // 生产部署未配置该变量时，回退到同源路径（需网关/反向代理支持 WS 升级）。
    return (
      import.meta.env?.VITE_WS_ANALYTICS_URL ||
      `${protocol}//${window.location.host}/api/v1/analytics/ws/dashboard`
    )
  }, [])

  const {
    connected: wsConnected,
    connecting: wsConnecting,
  } = useAnalyticsWebSocket({
    url: wsUrl,
    reconnect: true,
    reconnectInterval: 5000,
    maxReconnectAttempts: 5,
    onMessage: useCallback((data: any) => {
      if (data?.type === 'kpi_update' || data?.type === 'chart_refresh') {
        refresh()
      }
    }, [refresh]),
  })

  // 导出当前仪表盘数据为 CSV/JSON
  const handleExport = useCallback(async (format: 'json' | 'excel') => {
    if (!dashboard) return
    try {
      if (format === 'json') {
        const blob = new Blob([JSON.stringify(dashboard, null, 2)], { type: 'application/json' })
        const url = URL.createObjectURL(blob)
        const a = document.createElement('a')
        a.href = url
        a.download = `analytics_dashboard_${filters.timeRange}_${new Date().toISOString().slice(0, 10)}.json`
        a.click()
        URL.revokeObjectURL(url)
      } else {
        const kpiRows = dashboard.kpi?.map((k: any) => ({
          指标ID: k.id,
          指标名称: k.name,
          数值: k.value,
          单位: k.unit,
          环比变化: k.change_percent ?? '—',
          目标值: k.target ?? '—',
        })) || []
        const headers = Object.keys(kpiRows[0] ?? {}).join(',')
        const rows = kpiRows.map(r => Object.values(r).map(v => String(v ?? '')).join(','))
        const csv = [headers, ...rows].join('\n')
        const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8' })
        const url = URL.createObjectURL(blob)
        const a = document.createElement('a')
        a.href = url
        a.download = `analytics_kpi_${filters.timeRange}.csv`
        a.click()
        URL.revokeObjectURL(url)
      }
    } catch {
      toast.error(t('pages.analytics.exportFailed'))
    }
  }, [dashboard, filters.timeRange, toast, t])

  // 初始加载完成后清除骨架屏（防止缓存命中时仍显示假 loading）
  useEffect(() => {
    const timer = setTimeout(() => setIsLoading(false), 300)
    return () => clearTimeout(timer)
  }, [])

  // 全局筛选防抖
  // 点击外部关闭筛选面板
  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (filterRef.current && !filterRef.current.contains(e.target as Node)) {
        setShowFilters(false)
      }
    }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [])

  // 初始加载状态处理
  useEffect(() => {
    const timer = setTimeout(() => {
      setIsLoading(false)
    }, 800)
    return () => clearTimeout(timer)
  }, [])

  const formatTime = (timestamp: Date) => {
    return timestamp.toLocaleTimeString(i18n.language, { hour: '2-digit', minute: '2-digit', second: '2-digit' })
  }

  if (isLoading) {
    return <AnalyticsSkeleton />
  }

  return (
    <div className="space-y-[var(--space-apple-md)] max-w-[1600px] mx-auto px-2 sm:px-6 lg:px-8 py-4 sm:py-[var(--space-apple-lg)]">

      {/* Primary Banner — 与 Dashboard 一致的 bg-[var(--color-primary)] 横幅（移动端紧凑化） */}
      <div className="surface-primary rounded-[var(--radius-Apple-md)] p-4 sm:p-5 shadow-sm">
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
          <div className="flex-1 min-w-0">
            <h1 className="text-lg sm:text-xl font-bold leading-snug truncate">{t('pages.analytics.title')}</h1>
            <p className="mt-0.5 text-white/85 text-xs sm:text-sm truncate">
              {t('pages.analytics.subtitle')}
            </p>
          </div>
          <div className="flex flex-wrap items-center gap-1.5 w-full sm:w-auto">
            {/* 最后更新时间 */}
            <div className="flex items-center gap-1.5 text-xs text-[var(--color-primary-text)] dark:text-white/75 px-2.5 py-1.5 bg-[var(--color-primary-container)] dark:bg-[var(--bg-secondary)]/10 rounded-[var(--radius-Apple-sm)] shrink-0">
              <Clock className="w-3.5 h-3.5" />
              <span>{t('pages.analytics.updatedAt', { time: lastFetched ? formatTime(lastFetched) : '--:--:--' })}</span>
            </div>
            {/* 数据状态 */}
            <div className={`flex items-center gap-1.5 px-2.5 py-1.5 rounded-[var(--radius-Apple-sm)] text-xs shrink-0 ${
              dataLoading
                ? 'bg-[var(--bg-secondary)]/95 dark:bg-[var(--color-warning-container)]0/20 text-[var(--color-warning-text)] dark:text-white'
                : 'bg-[var(--bg-secondary)]/95 dark:bg-[var(--color-success-container)]0/20 text-[var(--color-success-text)] dark:text-white'
            }`}>
              {dataLoading ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Wifi className="w-3.5 h-3.5" />}
              {dataLoading ? t('pages.analytics.loading') : t('pages.analytics.connected')}
            </div>
            {/* WebSocket 状态 */}
            <div className={`flex items-center gap-1.5 px-2.5 py-1.5 rounded-[var(--radius-Apple-sm)] text-xs shrink-0 ${
              wsConnected
                ? 'bg-[var(--bg-secondary)]/95 dark:bg-[var(--color-success-container)]0/20 text-[var(--color-success-text)] dark:text-white'
                : wsConnecting
                  ? 'bg-[var(--bg-secondary)]/95 dark:bg-[var(--color-warning-container)]0/20 text-[var(--color-warning-text)] dark:text-white'
                  : 'bg-[var(--bg-secondary)]/95 dark:bg-[var(--bg-tertiary)]0/20 text-[var(--text-primary)] dark:text-white'
            }`}>
              {wsConnected
                ? <Wifi className="w-3.5 h-3.5 text-[var(--color-success-text)] dark:text-[var(--color-success-text)]" />
                : wsConnecting
                  ? <Loader2 className="w-3.5 h-3.5 animate-spin text-[var(--color-warning-text)] dark:text-[var(--color-warning-text)]" />
                  : <WifiOff className="w-3.5 h-3.5" />
              }
              <span>{wsConnected ? t('pages.analytics.realtime') : wsConnecting ? t('pages.analytics.connecting') : t('pages.analytics.polling')}</span>
            </div>
            {/* 刷新按钮 */}
            <Button
              variant="secondary"
              size="sm"
              icon={<RefreshCw size={14} />}
              onClick={refresh}
              disabled={dataLoading}
            >
              <span className="hidden sm:inline">{t('pages.analytics.refresh')}</span>
            </Button>
            {/* 导出按钮 */}
            <Button
              variant="ghost"
              size="sm"
              icon={<Download size={14} />}
              onClick={() => handleExport('excel')}
            >
              <span className="hidden sm:inline">{t('pages.analytics.exportCsv')}</span>
            </Button>
            <Button
              variant="ghost"
              size="sm"
              icon={<Download size={14} />}
              onClick={() => handleExport('json')}
            >
              <span className="hidden sm:inline">{t('pages.analytics.exportJson')}</span>
            </Button>
          </div>
        </div>
      </div>

      {/* 筛选工具栏 */}
      <div ref={filterRef} className="relative">
        <div className="flex items-center gap-[var(--space-apple-sm)]">
          {/* 时间范围 */}
          <select
            value={filters.timeRange}
            onChange={(e) => setFilters({ ...filters, timeRange: e.target.value as FilterConfig['timeRange'] })}
