                  {[t('pages.analytics.categories.functionalFood'), t('pages.analytics.categories.healthProducts'), t('pages.analytics.categories.nutritionSupplements'), t('pages.analytics.categories.foodHomology')].map((category) => (
                    <label key={category} className="flex items-center gap-2 cursor-pointer">
                      <input
                        type="checkbox"
                        className="rounded border-border text-[var(--color-primary-text)]"
                        checked={filters.categories.includes(category)}
                        onChange={(e) => {
                          setFilters(prev => ({
                            ...prev,
                            categories: e.target.checked
                              ? [...prev.categories, category]
                              : prev.categories.filter(c => c !== category),
                          }))
                        }}
                      />
                      <span className="text-sm text-[var(--text-primary)]">{category}</span>
                    </label>
                  ))}
                </div>
              </div>
              <div>
                <label className="block text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider mb-2">{t('pages.analytics.status')}</label>
                <div className="space-y-1.5">
                  {[t('pages.analytics.statusOptions.draft'), t('pages.analytics.statusOptions.inReview'), t('pages.analytics.statusOptions.published'), t('pages.analytics.statusOptions.archived')].map((status) => (
                    <label key={status} className="flex items-center gap-2 cursor-pointer">
                      <input
                        type="checkbox"
                        className="rounded border-border text-[var(--color-primary-text)]"
                        checked={filters.status.includes(status)}
                        onChange={(e) => {
                          setFilters(prev => ({
                            ...prev,
                            status: e.target.checked
                              ? [...prev.status, status]
                              : prev.status.filter(s => s !== status),
                          }))
                        }}
                      />
                      <span className="text-sm text-[var(--text-primary)]">{status}</span>
                    </label>
                  ))}
                </div>
              </div>
              <div>
                <label className="block text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider mb-2">{t('pages.analytics.owner')}</label>
                <div className="space-y-1.5 max-h-32 overflow-y-auto">
                  {apiFilters?.users?.length ? (
                    apiFilters.users.map((u) => (
                      <label key={u.id} className="flex items-center gap-2 cursor-pointer">
                        <input
                          type="checkbox"
                          className="rounded border-border text-[var(--color-primary-text)]"
                          checked={filters.users.includes(u.id)}
                          onChange={(e) => {
                            setFilters(prev => ({
                              ...prev,
                              users: e.target.checked
                                ? [...prev.users, u.id]
                                : prev.users.filter(id => id !== u.id),
                            }))
                          }}
                        />
                        <span className="text-sm text-[var(--text-primary)]">{u.full_name || u.username}</span>
                      </label>
                    ))
                  ) : (
                    <span className="text-xs text-[var(--text-muted)]">{t('pages.analytics.noUserData')}</span>
                  )}
                </div>
              </div>
            </div>
            <div className="flex items-center justify-end gap-2 mt-[var(--space-apple-md)] pt-[var(--space-apple-md)] border-t border-[var(--border-color)]">
              <button
                onClick={() => {
                  setFilters({ timeRange: '30d', categories: [], status: [], users: [] })
                  setShowFilters(false)
                  refresh()
                }}
                className="px-[var(--space-apple-sm)] py-1.5 text-sm text-[var(--text-muted)] hover:text-[var(--text-primary)] transition-colors"
              >
                {t('pages.analytics.reset')}
              </button>
              <button
                onClick={() => { setShowFilters(false); refresh() }}
                className="px-[var(--space-apple-md)] py-1.5 bg-primary-container hover:bg-primary-container text-[var(--color-primary)] text-sm rounded-[var(--radius-Apple-sm)] transition-colors"
              >
                {t('pages.analytics.applyFilters')}
              </button>
            </div>
          </div>
        )}
      </div>

      {/* 统计概览行 — 使用 StatCard 风格 */}
      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-[var(--space-apple-sm)]">
        {[
          { label: t('pages.analytics.statTotalFormulas'), value: stats?.total_formulas ?? 0, icon: FlaskConical as LucideIcon, variant: 'primary' as const },
          { label: t('pages.analytics.statExperiments'), value: stats?.total_experiments ?? 0, icon: Activity as LucideIcon, variant: 'secondary' as const },
          { label: t('pages.analytics.statActiveUsers'), value: stats?.active_users ?? 0, icon: Users as LucideIcon, variant: 'info' as const },
          { label: t('pages.analytics.statAiGenerated'), value: stats?.data_points ?? 0, icon: BarChart3 as LucideIcon, variant: 'success' as const },
          { label: t('pages.analytics.statSuccessRate'), value: `${stats?.success_rate ?? 0}%`, icon: TrendingUp as LucideIcon, variant: 'warning' as const },
          { label: t('pages.analytics.statStorage'), value: `${(stats?.avg_processing_time ?? 0).toFixed(1)} MB`, icon: Zap as LucideIcon, variant: 'primary' as const },
        ].map(({ label, value, icon: Icon }) => (
          <Card key={label} className="px-5 py-4">
            <div className="flex items-center justify-between mb-2">
              <p className="text-xs text-[var(--text-muted)]">{label}</p>
              <div className="w-7 h-7 rounded-[var(--radius-Apple-sm)] bg-[var(--color-primary-container)] flex items-center justify-center">
                <Icon size={14} className="text-[var(--color-primary-text)]" />
              </div>
            </div>
            <p className="text-xl font-bold text-[var(--text-primary)]">{value}</p>
          </Card>
        ))}
      </div>

      {/* 错误提示 */}
      {dataError && (
        <div className="p-[var(--space-apple-sm)] rounded-[var(--radius-Apple-sm)] bg-[var(--color-error-container)] dark:bg-[var(--color-error-container)]/20 border border-[var(--color-error-border)] dark:border-error-900/40 text-[var(--color-error-text)] dark:text-[var(--color-error-text)] text-sm">
          {dataError}
        </div>
      )}

      {/* Tab 导航 — 与 Dashboard 一致的药丸风格 */}
      <Tabs value={tab} onValueChange={(v) => setTab(v as AnalyticsTab)}>
        <TabsList className="mb-0">
          {TABS.map(({ key, labelKey, icon: Icon }) => (
            <TabsTrigger key={key} value={key} icon={<Icon className="w-3.5 h-3.5" />}>
              {t(labelKey)}
            </TabsTrigger>
          ))}
        </TabsList>

        <TabsContent value="overview">
          <AnalyticsErrorBoundary>
            <OverviewTab filters={filters} dashboard={dashboard} refresh={refresh} />
          </AnalyticsErrorBoundary>
        </TabsContent>
        <TabsContent value="trends">
          <AnalyticsErrorBoundary>
            <TrendsTab filters={filters} />
          </AnalyticsErrorBoundary>
        </TabsContent>
        <TabsContent value="reports">
          <AnalyticsErrorBoundary>
            <ReportsTab filters={filters} />
          </AnalyticsErrorBoundary>
        </TabsContent>
        <TabsContent value="business">
          <AnalyticsErrorBoundary>
            <BusinessInsightsTab filters={filters} />
          </AnalyticsErrorBoundary>
        </TabsContent>
        <TabsContent value="custom">
          <AnalyticsErrorBoundary>
            <CustomTab filters={filters} dashboard={dashboard} refresh={refresh} />
          </AnalyticsErrorBoundary>
        </TabsContent>
      </Tabs>
    </div>
  )
}

/**
 * 自定义仪表盘 Tab
 * 支持拖拽布局、Widget 添加/移除、保存/加载布局
 * 使用真实后端数据渲染 KPI / 图表 / 表格 / 动态流
 */
import React, { useState } from 'react'
import {
  LayoutGrid, Plus, Save, Share2,
  GripVertical, X, Check,
  BarChart3, PieChart as PieIcon, Activity, Users, TrendingUp, Zap,
  ArrowUp, ArrowDown, FileText,
} from 'lucide-react'
import type { LucideIcon } from 'lucide-react'
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui'
import {
  KPIWidget,
  ChartWidget,
  TableWidget,
  ActivityFeedWidget,
} from '@/components/analytics/widgets'
import { SankeyFunnelChart } from '@/components/analytics/charts/SankeyFunnelChart'
import { IngredientNetworkChart } from '@/components/analytics/charts/IngredientNetworkChart'
import type { DashboardResponse } from '@/hooks/useAnalyticsData'
import { useToast } from '@/components/ui'

interface FilterConfig {
  timeRange: '7d' | '30d' | '90d' | '1y'
  categories: string[]
  status: string[]
  users: string[]
}

export interface DashboardWidget {
  id: string
  type: 'kpi' | 'chart' | 'table' | 'activity_feed' | 'sankey' | 'network'
  title: string
  size: 'small' | 'medium' | 'large'
  config: Record<string, any>
}

const AVAILABLE_WIDGETS: Array<{
  id: string
  type: DashboardWidget['type']
  title: string
  size: DashboardWidget['size']
  icon: LucideIcon
  defaultConfig: Record<string, any>
}> = [
  { id: 'kpi-formulas',    type: 'kpi',      title: '配方总数',    size: 'small', icon: Zap,     defaultConfig: { metricId: 'total_formulas' } },
  { id: 'kpi-experiments', type: 'kpi',      title: '实验次数',    size: 'small', icon: Activity, defaultConfig: { metricId: 'total_experiments' } },
  { id: 'kpi-users',       type: 'kpi',      title: '活跃用户',    size: 'small', icon: Users,   defaultConfig: { metricId: 'active_users' } },
  { id: 'kpi-ai',          type: 'kpi',      title: 'AI 生成次数', size: 'small', icon: Zap,     defaultConfig: { metricId: 'ai_generations' } },
  { id: 'chart-trend',     type: 'chart',    title: '月度趋势',    size: 'large', icon: TrendingUp, defaultConfig: { chartKey: 'monthly_creation_trend' } },
  { id: 'chart-status',    type: 'chart',    title: '状态分布',    size: 'medium', icon: PieIcon, defaultConfig: { chartKey: 'formula_status_distribution' } },
  { id: 'chart-category',  type: 'chart',    title: '分类分析',    size: 'medium', icon: BarChart3, defaultConfig: { chartKey: 'category_breakdown' } },
  { id: 'table-activities',type: 'activity_feed', title: '近期动态', size: 'large', icon: Activity, defaultConfig: { limit: 8 } },
  { id: 'table-top',       type: 'table',    title: 'TOP 配方',    size: 'large', icon: FileText,  defaultConfig: { limit: 10 } },
  { id: 'sankey-funnel',   type: 'sankey',   title: '生命周期漏斗', size: 'large', icon: TrendingUp, defaultConfig: {} },
  { id: 'network-ingredients', type: 'network', title: '食材关联网络', size: 'large', icon: BarChart3, defaultConfig: {} },
]

interface SavedLayout {
  id: string
  name: string
  widgets: DashboardWidget[]
  createdAt: string
}

interface Props {
  filters: FilterConfig
  dashboard?: DashboardResponse | null
  refresh: () => void
}

// ─── Widget 渲染映射 ─────────────────────────────────────────────
function renderWidgetContent(widget: DashboardWidget, data: CustomTabData): React.ReactNode {
  const { type, config } = widget
  switch (type) {
    case 'kpi':
      return <KPIWidget metricId={config.metricId} size={widget.size} kpiMap={data.kpiMap} />
    case 'chart':
      return <ChartWidget chartKey={config.chartKey} title={widget.title} charts={data.charts} />
    case 'table':
      return <TableWidget title={widget.title} limit={config.limit ?? 10} activities={data.activities} />
    case 'activity_feed':
      return <ActivityFeedWidget title={widget.title} limit={config.limit ?? 10} activities={data.activities} />
    case 'sankey':
      return (
        <div className="h-full">
          <SankeyFunnelChart stages={widget.config.stages ?? []} height={200} />
        </div>
      )
    case 'network':
      return (
        <div className="h-full">
          <IngredientNetworkChart nodes={widget.config.nodes ?? []} edges={widget.config.edges ?? []} height={300} />
        </div>
      )
    default:
      return <span className="text-[var(--text-muted)] text-xs">未知组件</span>
  }
}

interface CustomTabData {
  kpiMap: Record<string, { id: string; name: string; value: number; unit: string; change_percent?: number | null; target?: number | null }> | null
  charts: Record<string, { chart_type: string; title: string; labels: string[]; datasets: Array<{ label: string; data: number[] }> }> | null
  activities: Array<{ type: string; title: string; timestamp?: string | null; author?: string | null }>
}

function buildCustomTabData(dashboard: DashboardResponse | null): CustomTabData {
  const kpiMap = dashboard?.kpi
    ? Object.fromEntries(dashboard.kpi.map((k: any) => [k.id, k]))
    : null
  const charts = dashboard?.charts ?? null
  const activities = dashboard?.recent_activity ?? []
  return { kpiMap, charts, activities }
}

// ─── 默认布局 ──────────────────────────────────────────────────────
function getDefaultWidgets(): DashboardWidget[] {
  return [
    { id: 'kpi-1', type: 'kpi',   title: '配方总数',  size: 'small', config: { metricId: 'total_formulas' } },
    { id: 'kpi-2', type: 'kpi',   title: '实验次数',  size: 'small', config: { metricId: 'total_experiments' } },
    { id: 'kpi-3', type: 'kpi',   title: '活跃用户',  size: 'small', config: { metricId: 'active_users' } },
    { id: 'kpi-4', type: 'kpi',   title: 'AI 生成',   size: 'small', config: { metricId: 'ai_generations' } },
    { id: 'chart-1', type: 'chart', title: '月度趋势', size: 'large', config: { chartKey: 'monthly_creation_trend' } },
    { id: 'feed-1', type: 'activity_feed', title: '近期动态', size: 'large', config: { limit: 8 } },
  ]
}

export default function CustomTab({ dashboard }: Props) {
  const toast = useToast()
  const [isEditMode, setIsEditMode] = useState(false)
  const [widgets, setWidgets] = useState<DashboardWidget[]>(() => {
    const saved = localStorage.getItem('analytics-custom-layout')
    if (saved) {
      try { return JSON.parse(saved) } catch { /* 忽略损坏的本地布局 */ }
    }
    return getDefaultWidgets()
  })
  const [savedLayouts, setSavedLayouts] = useState<SavedLayout[]>(() => {
    const saved = localStorage.getItem('analytics-saved-layouts')
    if (saved) {
      try { return JSON.parse(saved) } catch { /* 忽略损坏的本地布局 */ }
    }
    return []
  })
  const [currentLayoutName, setCurrentLayoutName] = useState('我的仪表盘')
  const [showWidgetPicker, setShowWidgetPicker] = useState(false)
  const [showSaveDialog, setShowSaveDialog] = useState(false)
  const [newLayoutName, setNewLayoutName] = useState('')

  // 共享数据源 — 所有 Widget 共用同一份 dashboard 数据，不重复发请求
  const customTabData = buildCustomTabData(dashboard ?? null)

  // 持久化
  React.useEffect(() => {
    localStorage.setItem('analytics-custom-layout', JSON.stringify(widgets))
  }, [widgets])

  React.useEffect(() => {
    localStorage.setItem('analytics-saved-layouts', JSON.stringify(savedLayouts))
  }, [savedLayouts])

  const handleAddWidget = (tpl: typeof AVAILABLE_WIDGETS[0]) => {
    const newWidget: DashboardWidget = {
      // eslint-disable-next-line react-hooks/purity
      id: `${tpl.id}-${Date.now()}`,
      type: tpl.type,
      title: tpl.title,
      size: tpl.size,
      config: { ...tpl.defaultConfig },
    }
    setWidgets(prev => [...prev, newWidget])
    setShowWidgetPicker(false)
  }

  const handleRemoveWidget = (widgetId: string) => {
    setWidgets(prev => prev.filter(w => w.id !== widgetId))
  }

  const handleSaveLayout = () => {
    if (!newLayoutName.trim()) return
    const layout: SavedLayout = {
      id: Date.now().toString(),
      name: newLayoutName.trim(),
      widgets: [...widgets],
      createdAt: new Date().toISOString(),
    }
    setSavedLayouts(prev => [...prev, layout])
    setNewLayoutName('')
    setShowSaveDialog(false)
    setIsEditMode(false)
  }

  const handleLoadLayout = (layout: SavedLayout) => {
    setWidgets(layout.widgets)
    setCurrentLayoutName(layout.name)
    setIsEditMode(false)
  }

  const handleShare = () => {
    const data = JSON.stringify({ widgets, name: currentLayoutName })
    navigator.clipboard.writeText(data).then(() => {
      toast.success('布局配置已复制到剪贴板')
    })
  }

  // ─── Widget 上下移动 ──────────────────────────────────────
  const moveWidget = (index: number, direction: -1 | 1) => {
    setWidgets(prev => {
      const next = [...prev]
      const target = index + direction
      if (target < 0 || target >= next.length) return prev
      ;[next[index], next[target]] = [next[target], next[index]]
      return next
    })
  }

  return (
    <div className="space-y-[var(--space-apple-md)]">

      {/* ── 操作工具栏 ── */}
      <div className="flex items-center justify-between flex-wrap gap-[var(--space-apple-sm)]">
        <div className="flex items-center gap-[var(--space-apple-sm)]">
          <input
            type="text"
            value={currentLayoutName}
            onChange={(e) => setCurrentLayoutName(e.target.value)}
            disabled={!isEditMode}
            className={`px-[var(--space-apple-sm)] py-1.5 text-base font-semibold bg-transparent border-b transition-colors ${
              isEditMode
                ? 'border-[var(--color-primary)] text-[var(--color-primary-text)] focus:outline-none'
                : 'border-transparent text-[var(--text-primary)]'
            }`}
        aria-label="布局名称"
      />

          <button
            onClick={() => setIsEditMode(!isEditMode)}
            className={`px-[var(--space-apple-sm)] py-1.5 text-sm rounded-[var(--radius-Apple-sm)] transition-all flex items-center gap-1.5 ${
              isEditMode
                ? 'bg-primary-container text-[var(--color-primary)] shadow-sm'
                : 'bg-surface-hover text-[var(--text-primary)] hover:bg-surface-pressed'
            }`}
          >
            {isEditMode ? <Check className="w-4 h-4" /> : <LayoutGrid className="w-4 h-4" />}
            {isEditMode ? '完成编辑' : '编辑布局'}
          </button>
        </div>

        <div className="flex items-center gap-2">
          {/* 布局选择 */}
          <select
            onChange={(e) => {
              if (e.target.value) {
                const layout = savedLayouts.find(l => l.id === e.target.value)
                if (layout) handleLoadLayout(layout)
              }
            }}
            className="px-[var(--space-apple-sm)] py-1.5 text-sm input min-w-[150px]"
          >
            <option value="">已保存的布局…</option>
            {savedLayouts.map((layout) => (
              <option key={layout.id} value={layout.id}>{layout.name}</option>
            ))}
          </select>

          {isEditMode && (
            <button
              onClick={() => setShowWidgetPicker(!showWidgetPicker)}
              className="px-[var(--space-apple-sm)] py-1.5 bg-primary-container hover:bg-primary-container text-[var(--color-primary)] text-sm rounded-[var(--radius-Apple-sm)] transition-colors flex items-center gap-1.5"
            >
              <Plus className="w-4 h-4" />
              添加组件
            </button>
          )}

          {isEditMode && widgets.length > 0 && (
            <button
              onClick={() => { setNewLayoutName(currentLayoutName); setShowSaveDialog(true) }}
              className="px-[var(--space-apple-sm)] py-1.5 bg-secondary-container hover:bg-secondary-container text-secondary-main text-sm rounded-[var(--radius-Apple-sm)] transition-colors flex items-center gap-1.5"
            >
              <Save className="w-4 h-4" />
              保存布局
            </button>
          )}

          {!isEditMode && widgets.length > 0 && (
            <button
              onClick={handleShare}
              className="px-[var(--space-apple-sm)] py-1.5 bg-surface-hover hover:bg-surface-pressed text-[var(--text-primary)] text-sm rounded-[var(--radius-Apple-sm)] transition-colors flex items-center gap-1.5"
            >
              <Share2 className="w-4 h-4" />
              分享
            </button>
          )}
        </div>
      </div>

      {/* ── 组件选择面板 ── */}
      {showWidgetPicker && (
        <div className="p-[var(--space-apple-md)] rounded-[var(--radius-Apple-sm)] bg-surface-hover border border-border">
          <div className="flex items-center justify-between mb-[var(--space-apple-sm)]">
            <span className="text-sm font-medium text-[var(--text-primary)]">选择组件</span>
            <button onClick={() => setShowWidgetPicker(false)} className="text-[var(--text-muted)] hover:text-[var(--text-primary)]">
              <X className="w-4 h-4" />
            </button>
          </div>
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-2">
            {AVAILABLE_WIDGETS.map((widget) => {
              const alreadyAdded = widgets.some(w => w.type === widget.type && w.config.metricId === widget.defaultConfig.metricId)
              return (
                <button
                  key={widget.id}
                  onClick={() => !alreadyAdded && handleAddWidget(widget)}
                  disabled={alreadyAdded}
                  className="p-[var(--space-apple-sm)] rounded-[var(--radius-Apple-sm)] bg-background border border-border hover:border-[var(--color-primary)] transition-colors text-left disabled:opacity-40 disabled:cursor-not-allowed"
                >
                  <widget.icon className="w-5 h-5 text-[var(--color-primary-text)] mb-2" />
                  <p className="text-xs font-medium text-[var(--text-primary)]">{widget.title}</p>
                  <p className="text-xs text-[var(--text-muted)] mt-0.5">{widget.size === 'large' ? '大块' : widget.size === 'medium' ? '中块' : '小块'}</p>
                </button>
              )
            })}
          </div>
        </div>
      )}

      {/* ── 保存布局对话框 ── */}
      {showSaveDialog && (
        <div className="p-[var(--space-apple-md)] rounded-[var(--radius-Apple-sm)] bg-surface-hover border border-border">
          <div className="flex items-center justify-between mb-[var(--space-apple-sm)]">
            <span className="text-sm font-medium text-[var(--text-primary)]">保存布局</span>
            <button onClick={() => setShowSaveDialog(false)} className="text-[var(--text-muted)] hover:text-[var(--text-primary)]">
              <X className="w-4 h-4" />
            </button>
          </div>
          <div className="space-y-[var(--space-apple-sm)]">
            <input
              type="text"
              value={newLayoutName}
              onChange={(e) => setNewLayoutName(e.target.value)}
              placeholder="输入布局名称…"
              className="w-full px-[var(--space-apple-sm)] py-2 text-sm input"
              onKeyDown={(e) => e.key === 'Enter' && handleSaveLayout()}
            />
            <button
              onClick={handleSaveLayout}
              disabled={!newLayoutName.trim()}
              className="w-full py-2 bg-primary-container hover:bg-primary-container disabled:opacity-50 text-[var(--color-primary)] text-sm rounded-[var(--radius-Apple-sm)] transition-colors flex items-center justify-center gap-2"
            >
              <Save className="w-4 h-4" />
              保存
            </button>
          </div>
        </div>
      )}

      {/* ── Widget 网格 ── */}
      {widgets.length > 0 ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {widgets.map((widget, index) => {
            const canMoveUp = index > 0
            const canMoveDown = index < widgets.length - 1
            return (
              <div
                key={widget.id}
                className={`relative group ${widget.size === 'large' ? 'lg:col-span-2' : ''}`}
              >
                <Card className="h-full">
                  <CardHeader className="flex flex-row items-center gap-1.5 pb-3">
                    {isEditMode && (
                      <GripVertical className="w-4 h-4 text-[var(--text-muted)] cursor-grab flex-shrink-0 mt-0.5" />
                    )}
                    <CardTitle className="text-sm font-semibold truncate flex-1">{widget.title}</CardTitle>
                    {isEditMode && (
                      <div className="flex items-center gap-0.5 ml-auto">
                        <button
                          onClick={() => moveWidget(index, -1)}
                          disabled={!canMoveUp}
                          className="p-1 text-[var(--text-muted)] hover:text-[var(--color-primary-text)] disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
                          title="上移"
                        >
                          <ArrowUp className="w-3.5 h-3.5" />
                        </button>
                        <button
                          onClick={() => moveWidget(index, 1)}
                          disabled={!canMoveDown}
                          className="p-1 text-[var(--text-muted)] hover:text-[var(--color-primary-text)] disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
                          title="下移"
                        >
                          <ArrowDown className="w-3.5 h-3.5" />
                        </button>
                        <button
                          onClick={() => handleRemoveWidget(widget.id)}
                          className="p-1 text-[var(--text-muted)] hover:text-[var(--color-error-text)]0 transition-colors"
                          title="移除组件"
                        >
                          <X className="w-3.5 h-3.5" />
                        </button>
                      </div>
                    )}
                  </CardHeader>
                  <CardContent>
                    <div className="min-h-[120px]">
                      {renderWidgetContent(widget, customTabData)}
                    </div>
                  </CardContent>
                </Card>
              </div>
            )
          })}

          {/* 添加组件占位 */}
          {isEditMode && (
            <button
              onClick={() => setShowWidgetPicker(true)}
              className="p-[var(--space-apple-md)] rounded-[var(--radius-Apple-sm)] border-2 border-dashed border-border hover:border-[var(--color-primary)] transition-colors flex flex-col items-center gap-2 text-[var(--text-muted)] hover:text-[var(--color-primary-text)] h-full min-h-[200px]"
            >
              <Plus className="w-8 h-8" />
              <span className="text-sm font-medium">添加组件</span>
            </button>
          )}
        </div>
      ) : (
        <div className="p-10 text-center rounded-[var(--radius-Apple-sm)] bg-surface-hover">
          <LayoutGrid className="w-10 h-10 text-[var(--text-muted)] mx-auto mb-[var(--space-apple-sm)]" />
          <p className="text-[var(--text-muted)] text-sm">暂无组件</p>
          <p className="text-xs text-[var(--text-muted)] mt-1">点击右上角「添加组件」开始搭建您的仪表盘</p>
        </div>
      )}
    </div>
  )
}

﻿/**
 * 概览总览 Tab 组件 — 真实后端数据版
 * 从 /api/v1/analytics/dashboard 拉取实时数据，
 * 图表、KPI、活动均对接数据库查询结果。
 */
import React, { useState, useMemo, useEffect } from 'react'
import {
  TrendingUp, BarChart3, PieChart, LineChart as LineChartIcon,
  Activity, Users, FlaskConical, Zap, RefreshCw,
  LineChart, ZoomIn, ZoomOut, Maximize2,
  CheckCircle2, Wifi,
} from 'lucide-react'
import { AnalyticsChart, ChartDataItem } from '@/components/analytics/charts/RechartsWrapper'
import type { KPIMetric, DashboardResponse } from '@/hooks/useAnalyticsData'
import { extractStats } from '@/hooks/useAnalyticsData'

interface FilterConfig {
  timeRange: '7d' | '30d' | '90d' | '1y'
  categories: string[]
  status: string[]
  users: string[]
}

interface Props {
  filters: FilterConfig
  dashboard?: DashboardResponse | null
  refresh: () => void
}

const COLOR_MAP: Record<string, { bg: string; text: string; border: string }> = {
  primary: { bg: 'bg-[var(--color-primary-container)] dark:bg-[var(--color-primary-container)]/40', text: 'text-[var(--color-primary-text)]', border: 'border-[var(--color-primary-border)] dark:border-[var(--color-primary)]' },
  blue: { bg: 'bg-[var(--color-secondary-container)] dark:bg-[var(--color-secondary-container)]/40', text: 'text-[var(--color-secondary-text)]', border: 'border-[var(--color-secondary-border)] dark:border-[var(--color-secondary)]' },
  emerald: { bg: 'bg-[var(--color-primary-container)] dark:bg-[var(--color-success-container)]/40', text: 'text-[var(--color-primary-text)]', border: 'border-[var(--color-success-border)] dark:border-[var(--color-success)]' },
  cyan: { bg: 'bg-info-50 dark:bg-info-950/40', text: 'text-info-600', border: 'border-info-200 dark:border-info-800' },
  violet: { bg: 'bg-[var(--color-accent-container)] dark:bg-[var(--color-accent-container)]/40', text: 'text-[var(--color-accent-text)]', border: 'border-[var(--color-accent-border)] dark:border-[var(--color-accent)]' },
  amber: { bg: 'bg-[var(--color-warning-container)] dark:bg-[var(--color-warning-container)]/40', text: 'text-[var(--color-warning-text)]', border: 'border-[var(--color-warning-border)] dark:border-[var(--color-warning)]' },
}

type ViewMode = 'dashboard' | 'charts'

// 图标映射
const ICON_MAP: Record<string, React.ElementType> = {
  total_formulas: FlaskConical,
  total_experiments: Activity,
  active_users: Users,
  ai_generations: Zap,
  storage_usage: BarChart3,
  published_formulas: TrendingUp,
}

export default function OverviewTab({ filters, dashboard, refresh }: Props) {
  const [viewMode, setViewMode] = useState<ViewMode>('dashboard')
  const [zoomLevel, setZoomLevel] = useState(1)
  const [selectedDataPoint, setSelectedDataPoint] = useState<{ x: string; y: number; series: string } | null>(null)
  const [showDrillDown, setShowDrillDown] = useState(false)
  const [drillDownData, setDrillDownData] = useState<ChartDataItem[]>([])

  // 直接从父级 props 派生所有数据，不重复发起网络请求
  const stats = dashboard?.kpi ? extractStats(dashboard.kpi) : null
  const kpiMap = dashboard?.kpi
    ? Object.fromEntries(dashboard.kpi.map((k: KPIMetric) => [k.id, k]))
    : null
  const statusDistribution = dashboard?.charts?.formula_status_distribution
  const monthlyTrend = dashboard?.charts?.monthly_creation_trend
  const categoryBreakdown = dashboard?.charts?.category_breakdown
  const activities = dashboard?.recent_activity ?? []
  const health = dashboard?.system_health
  const loading = false  // 由父级 AnalyticsPage 统一管理 loading 状态
  const error = null
  const lastFetched = dashboard ? new Date(dashboard.timestamp) : null

  // 监听父级 timeRange 变化，触发重新拉取
  useEffect(() => {
    refresh()
  }, [filters.timeRange])

  // ─── 派生 KPI 卡片数据 ─────────────────────────────────────
  const kpiCards = useMemo(() => {
    if (!kpiMap) return []
    const ids: (keyof typeof kpiMap)[] = [
      'total_formulas', 'total_experiments', 'active_users',
      'ai_generations', 'storage_usage', 'published_formulas',
    ]
    const colors = ['primary', 'blue', 'emerald', 'cyan', 'violet', 'amber']
    return ids.map((id, i) => {
      const kpi = kpiMap[id] as KPIMetric | undefined
      const Icon = ICON_MAP[id] || Activity
      const color = colors[i]
      return {
        id,
        name: kpi?.name ?? id,
        value: kpi?.value ?? 0,
        unit: kpi?.unit ?? '',
        change: kpi?.change_percent ?? 0,
        changeDirection: kpi?.change_direction,
        Icon,
        color,
        target: kpi?.target,
      }
    })
  }, [kpiMap])

  // ─── 趋势图数据 ────────────────────────────────────────────
  const trendChartData = useMemo(() => {
    if (!monthlyTrend?.labels) return []
    return monthlyTrend.labels.map((label, idx) => ({
      month: label,
      formula: monthlyTrend.datasets?.[0]?.data?.[idx] ?? 0,
      experiment: monthlyTrend.datasets?.[1]?.data?.[idx] ?? 0,
    }))
  }, [monthlyTrend])

  // ─── 分类数据 ──────────────────────────────────────────────
  const categoryChartData = useMemo(() => {
    if (!categoryBreakdown?.labels) return []
    return categoryBreakdown.labels.map((label, idx) => ({
      name: label,
      value: categoryBreakdown.datasets?.[0]?.data?.[idx] ?? 0,
    }))
  }, [categoryBreakdown])

  // ─── 状态分布数据 ──────────────────────────────────────────
  const statusChartData = useMemo(() => {
    if (!statusDistribution?.labels) return []
    return statusDistribution.labels.map((label, idx) => ({
      name: label,
      value: statusDistribution.datasets?.[0]?.data?.[idx] ?? 0,
    }))
  }, [statusDistribution])

  // ─── 活动列表 ──────────────────────────────────────────────
  const activityList = useMemo(() => {
    return (activities ?? []).slice(0, 10).map(a => ({
      type: a.type,
      title: a.title,
      author: a.author ?? '未知',
      time: a.timestamp ? new Date(a.timestamp).toLocaleString('zh-CN') : '',
    }))
  }, [activities])

  // ─── 缩放控制 ──────────────────────────────────────────────
  const handleZoomIn = () => setZoomLevel(z => Math.min(z + 0.25, 2))
  const handleZoomOut = () => setZoomLevel(z => Math.max(z - 0.25, 0.5))
  const handleResetZoom = () => setZoomLevel(1)

  const handleDataPointClick = (x: string, y: number, series: string) => {
    setSelectedDataPoint({ x, y, series })
    setShowDrillDown(true)
    setDrillDownData([
      { name: `${x} - 子项1`, value: Math.floor(y * 0.4) },
      { name: `${x} - 子项2`, value: Math.floor(y * 0.3) },
      { name: `${x} - 子项3`, value: Math.floor(y * 0.2) },
      { name: `${x} - 子项4`, value: Math.floor(y * 0.1) },
    ])
  }

  // ─── 可用过滤器（来自 API） ────────────────────────────────
  const apiFilters = dashboard?.available_filters

  // ─── 加载中状态 ────────────────────────────────────────────
  if (loading && !dashboard) {
    return (
      <div className="flex items-center justify-center py-20">
        <div className="flex flex-col items-center gap-4">
          <RefreshCw className="w-8 h-8 text-[var(--color-primary-text)] animate-spin" />
          <span className="text-sm text-[var(--text-muted)]">正在加载数据分析...</span>
        </div>
      </div>
    )
  }

  // ─── 错误状态 ──────────────────────────────────────────────
  if (error) {
    return (
      <div className="card p-[var(--space-apple-lg)] border border-[var(--color-error-border)] dark:border-[var(--color-error)] bg-[var(--color-error-container)] dark:bg-[var(--color-error-container)]/20">
        <p className="text-[var(--color-error-text)] dark:text-[var(--color-error-text)] font-medium">数据加载失败: {error}</p>
        <button
          onClick={refresh}
          className="mt-[var(--space-apple-sm)] px-[var(--space-apple-md)] py-2 bg-[var(--color-error)] text-white rounded-[var(--radius-Apple-sm)] text-sm hover:bg-[var(--color-error)] transition-colors"
        >
          重新加载
        </button>
      </div>
    )
  }

  return (
    <div className="w-full space-y-6">
      {/* 顶部工具栏 */}
      <div className="flex items-center justify-between flex-wrap gap-[var(--space-apple-sm)]">
        <div className="flex items-center gap-4">
          {/* A-41：暗色画布是墨绿渐变，--text-muted(#94a3b8) 落在上面只有 3.79:1 */}
          <div className="text-sm text-[var(--text-muted)] dark:text-[var(--text-muted)]">
            当前筛选: <span className="font-medium text-[var(--text-primary)]">{filters.timeRange}</span>
            {filters?.categories?.length > 0 && ` · ${filters.categories.length} 个类别`}
          </div>

          <div className="flex items-center gap-1 bg-[var(--bg-tertiary)] rounded-[var(--radius-Apple-sm)] p-0.5">
            <button
              onClick={() => setViewMode('dashboard')}
              className={`px-[var(--space-apple-sm)] py-1.5 text-xs font-medium rounded-[var(--radius-Apple-sm)] transition-all flex items-center gap-1.5 min-h-[44px] ${
                viewMode === 'dashboard'
                  ? 'bg-[var(--bg-secondary)] text-[var(--color-primary-text)] shadow-sm'
                  : 'text-[var(--text-muted)] hover:text-[var(--text-primary)]'
              }`}
            >
              <BarChart3 className="w-3.5 h-3.5" />
              仪表盘
            </button>
            <button
              onClick={() => setViewMode('charts')}
              className={`px-[var(--space-apple-sm)] py-1.5 text-xs font-medium rounded-[var(--radius-Apple-sm)] transition-all flex items-center gap-1.5 min-h-[44px] ${
                viewMode === 'charts'
                  ? 'bg-[var(--bg-secondary)] text-[var(--color-primary-text)] shadow-sm'
                  : 'text-[var(--text-muted)] hover:text-[var(--text-primary)]'
              }`}
            >
              <LineChart className="w-3.5 h-3.5" />
              图表
            </button>
          </div>
        </div>

        <div className="flex items-center gap-[var(--space-apple-sm)]">
          <div className="flex items-center gap-1.5 text-xs text-[var(--text-muted)]">
            <Wifi className="w-3.5 h-3.5 text-[var(--color-success-text)]0" />
            <span>实时</span>
            {lastFetched && (
              <span>· 更新于 {lastFetched.toLocaleTimeString('zh-CN')}</span>
            )}
          </div>

          <button
            onClick={refresh}
            className="px-[var(--space-apple-sm)] py-1.5 text-sm bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-[var(--radius-Apple-sm)] hover:bg-[var(--bg-tertiary)] dark:hover:bg-[var(--bg-tertiary)] transition-colors flex items-center gap-2 min-h-[44px]"
          >
            <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
            {loading ? '刷新中...' : '刷新'}
          </button>
        </div>
      </div>

      {/* ─── Dashboard 视图 ─── */}
      {viewMode === 'dashboard' && (
        <>
          {/* KPI 卡片行 */}
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
            {kpiCards.map(({ id, name, value, unit, change, changeDirection, Icon, color, target }) => {
              const colors = COLOR_MAP[color] || COLOR_MAP.primary
              const pctStr = change != null && change !== 0
                ? `${change > 0 ? '+' : ''}${change.toFixed(1)}%`
                : '—'
              return (
                <div
                  key={id}
                  className={`card p-[var(--space-apple-md)] ${colors.bg} ${colors.border} border hover:shadow-lg transition-all cursor-pointer group relative overflow-hidden`}
                   role="button" tabIndex={0} onClick={() => setViewMode('charts')}
                >
                  <div className="flex items-center justify-between mb-2">
                    <Icon className={`w-5 h-5 ${colors.text} group-hover:scale-110 transition-transform`} />
                    {target != null && (
                      <span className="text-xs text-[var(--text-muted)]">目标: {target}</span>
                    )}
                  </div>
                  <div className="text-2xl font-bold text-[var(--text-primary)]">
                    {typeof value === 'number' ? value.toLocaleString() : value}
                    <span className="text-sm font-normal text-[var(--text-muted)] ml-1">{unit}</span>
                  </div>
                  <div className="text-xs text-[var(--text-muted)] mt-1">{name}</div>
                  <div className={`text-xs mt-1 ${change > 0 ? 'text-[var(--color-success-text)]' : change < 0 ? 'text-[var(--color-error-text)]' : 'text-[var(--text-muted)]'}`}>
                    {change != null && change !== 0 ? `${change > 0 ? '↑' : '↓'} ${Math.abs(change).toFixed(1)}%` : pctStr}
                  </div>
                  <div className="absolute inset-0 bg-gradient-to-br from-white/0 via-white/10 to-transparent opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none" />
                </div>
              )
            })}
          </div>

          {/* 主图表 + 活动 */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 card p-[var(--space-apple-lg)]">
              <div className="flex items-center justify-between mb-[var(--space-apple-md)]">
                <h2 className="font-bold text-[var(--text-primary)] flex items-center gap-2">
                  <LineChart className="w-5 h-5 text-[var(--color-primary-text)]" />
                  月度创建趋势
                </h2>
                <div className="flex items-center gap-2">
                  <button onClick={handleZoomIn} className="p-1.5 hover:bg-[var(--bg-tertiary)] dark:hover:bg-[var(--bg-secondary)] rounded transition-colors min-w-[44px] min-h-[44px] inline-flex items-center justify-center" title="放大"><ZoomIn className="w-4 h-4" /></button>
                  <button onClick={handleZoomOut} className="p-1.5 hover:bg-[var(--bg-tertiary)] dark:hover:bg-[var(--bg-secondary)] rounded transition-colors min-w-[44px] min-h-[44px] inline-flex items-center justify-center" title="缩小"><ZoomOut className="w-4 h-4" /></button>
                  <button onClick={handleResetZoom} className="p-1.5 hover:bg-[var(--bg-tertiary)] dark:hover:bg-[var(--bg-secondary)] rounded transition-colors min-w-[44px] min-h-[44px] inline-flex items-center justify-center" title="重置"><Maximize2 className="w-4 h-4" /></button>
                </div>
              </div>
              {monthlyTrend ? (
                <AnalyticsChart
                  type="line"
                  data={trendChartData}
                  xKey="month"
                  datasets={[
                    {
                      label: '配方',
                      data: trendChartData.map(d => d.formula as number),
                      borderColor: 'var(--color-secondary, #0A84FF)',
                      backgroundColor: 'rgba(59, 130, 246, 0.1)',
                      fill: true,
                    },
                    {
                      label: '实验',
                      data: trendChartData.map(d => d.experiment as number),
                      borderColor: 'var(--color-primary, var(--color-primary-400))',
                      backgroundColor: 'rgba(16, 185, 129, 0.1)',
                      fill: true,
                    },
                  ]}
                  height={300}
                  zoomLevel={zoomLevel}
                  onDataPointClick={handleDataPointClick}
                />
              ) : (
                <div className="flex items-center justify-center h-[300px] text-[var(--text-muted)]">暂无趋势数据</div>
              )}
            </div>

            <div className="card p-[var(--space-apple-lg)]">
              <h3 className="font-bold text-[var(--text-primary)] flex items-center gap-2 mb-[var(--space-apple-md)]">
                <Activity className="w-5 h-5 text-[var(--color-secondary-text)]" />
                近期动态
              </h3>
              <div className="space-y-[var(--space-apple-sm)] max-h-[400px] overflow-y-auto pr-2">
                {activityList.length > 0 ? (
                  activityList.map((activity, index) => (
                    <div
                      key={index}
                      className="p-[var(--space-apple-sm)] bg-[var(--bg-tertiary)]/50 rounded-[var(--radius-Apple-sm)] hover:bg-[var(--bg-secondary)] transition-colors cursor-pointer group"
                    >
                      <div className="flex items-start gap-[var(--space-apple-sm)]">
                        <div className={`w-2 h-2 mt-2 rounded-[var(--radius-pill)] flex-shrink-0 ${
                          activity.type === 'formula' ? 'bg-[var(--color-success-container)]0' :
                          activity.type === 'experiment' ? 'bg-[var(--color-secondary-container)]0' :
                          'bg-neutral-400'
                        }`} />
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-medium text-[var(--text-primary)] group-hover:text-[var(--color-primary-text)] transition-colors line-clamp-2">
                            {activity.title}
                          </p>
                          <div className="flex items-center justify-between mt-1.5">
                            <span className="text-xs text-[var(--text-muted)]">{activity.author}</span>
                            <span className="text-xs text-[var(--text-muted)]">{activity.time}</span>
                          </div>
                        </div>
                      </div>
                    </div>
                  ))
                ) : (
                  <p className="text-sm text-[var(--text-muted)] text-center py-8">暂无活动记录</p>
                )}
              </div>
            </div>
          </div>

          {/* 系统健康 */}
          {health && (
            <div className="card p-[var(--space-apple-lg)]">
              <h3 className="font-bold text-[var(--text-primary)] mb-[var(--space-apple-md)] flex items-center gap-2">
                <TrendingUp className="w-5 h-5 text-[var(--color-primary-text)]" />
                系统健康状态
              </h3>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                {[
                  { label: '数据库', value: health.database_status, color: health.database_status === 'healthy' ? 'text-[var(--color-success-text)]' : 'text-[var(--color-error-text)]' },
                  { label: '平均响应', value: `${health.avg_response_time_ms}ms`, color: 'text-[var(--color-primary-text)]' },
                  { label: '错误率', value: `${health.error_rate_percent}%`, color: health.error_rate_percent < 1 ? 'text-[var(--color-success-text)]' : 'text-[var(--color-error-text)]' },
                  { label: '活跃连接', value: `${health.active_connections}`, color: 'text-[var(--color-secondary-text)]' },
                  { label: 'CPU', value: `${health.cpu_usage_percent}%`, color: health.cpu_usage_percent < 70 ? 'text-[var(--color-success-text)]' : 'text-[var(--color-warning-text)]' },
                  { label: '内存', value: `${health.memory_usage_percent}%`, color: health.memory_usage_percent < 80 ? 'text-[var(--color-success-text)]' : 'text-[var(--color-warning-text)]' },
                  { label: '磁盘', value: `${health.disk_usage_percent}%`, color: health.disk_usage_percent < 85 ? 'text-[var(--color-success-text)]' : 'text-[var(--color-warning-text)]' },
                  { label: '缓存命中率', value: `${health.cache_hit_rate_percent}%`, color: 'text-[var(--color-primary-text)]' },
                ].map(({ label, value, color }) => (
                  <div key={label} className="p-[var(--space-apple-sm)] bg-[var(--bg-tertiary)]/50 rounded-[var(--radius-Apple-sm)]">
                    <div className="text-xs text-[var(--text-muted)]">{label}</div>
                    <div className={`text-lg font-bold mt-1 ${color}`}>{value}</div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* 过滤器选项 */}
          {apiFilters && (
            <div className="card p-[var(--space-apple-lg)]">
              <h3 className="font-bold text-[var(--text-primary)] mb-[var(--space-apple-md)] flex items-center gap-2">
                <LineChartIcon className="w-5 h-5 text-[var(--color-secondary-text)]" />
                可用过滤器
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                {apiFilters.formula_status && apiFilters.formula_status.length > 0 && (
                  <div>
                    <h4 className="text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider mb-2">配方状态</h4>
                    <div className="space-y-1">
                      {apiFilters.formula_status.map((s: string) => (
                        <span key={s} className="text-sm px-2 py-1 bg-[var(--bg-tertiary)] rounded">{s}</span>
                      ))}
                    </div>
                  </div>
                )}
                {apiFilters.experiment_status && apiFilters.experiment_status.length > 0 && (
                  <div>
                    <h4 className="text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider mb-2">实验状态</h4>
                    <div className="space-y-1">
                      {apiFilters.experiment_status.map((s: string) => (
                        <span key={s} className="text-sm px-2 py-1 bg-[var(--bg-tertiary)] rounded">{s}</span>
                      ))}
                    </div>
                  </div>
                )}
                {apiFilters.categories && apiFilters.categories.length > 0 && (
                  <div>
                    <h4 className="text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider mb-2">类别</h4>
                    <div className="space-y-1 max-h-32 overflow-y-auto">
                      {apiFilters.categories.slice(0, 8).map((c: { id: string; name: string }) => (
                        <span key={c.id} className="text-sm px-2 py-1 bg-[var(--bg-tertiary)] rounded block">{c.name}</span>
                      ))}
                    </div>
                  </div>
                )}
                {apiFilters.users && apiFilters.users.length > 0 && (
                  <div>
                    <h4 className="text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider mb-2">用户</h4>
                    <div className="space-y-1 max-h-32 overflow-y-auto">
                      {apiFilters.users.slice(0, 8).map((u: { id: string; username: string; full_name: string }) => (
                        <span key={u.id} className="text-sm px-2 py-1 bg-[var(--bg-tertiary)] rounded block">{u.full_name || u.username}</span>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          )}
        </>
      )}

      {/* ─── Charts 视图 ─── */}
      {viewMode === 'charts' && (
        <div className="space-y-6">
          <div className="flex items-center justify-between">
            <h3 className="text-xl font-bold text-[var(--text-primary)]">数据可视化</h3>
            <button
              onClick={() => setViewMode('dashboard')}
              className="text-sm text-[var(--color-primary-text)] hover:text-[var(--color-primary-text)]"
            >
              ← 返回仪表盘
            </button>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {/* 月度趋势 */}
            <div className="card p-[var(--space-apple-lg)]">
              <h4 className="font-bold text-[var(--text-primary)] mb-[var(--space-apple-md)]"><TrendingUp className="w-4 h-4 inline mr-2" />月度趋势分析</h4>
              {monthlyTrend ? (
                <AnalyticsChart
                  type="line"
                  data={trendChartData}
                  xKey="month"
                  datasets={[
                    { label: '配方', data: trendChartData.map(d => d.formula as number), borderColor: '#3b82f6', backgroundColor: 'rgba(59,130,246,0.1)', fill: true },
                    { label: '实验', data: trendChartData.map(d => d.experiment as number), borderColor: '#10b981', backgroundColor: 'rgba(16,185,129,0.1)', fill: true },
                  ]}
                  height={250}
                  onDataPointClick={handleDataPointClick}
                />
              ) : (
                <div className="h-[250px] flex items-center justify-center text-[var(--text-muted)]">暂无数据</div>
              )}
            </div>

            {/* 分类分布 */}
            <div className="card p-[var(--space-apple-lg)]">
              <h4 className="font-bold text-[var(--text-primary)] mb-[var(--space-apple-md)]"><BarChart3 className="w-4 h-4 inline mr-2" />分类分布</h4>
              {categoryBreakdown ? (
                <AnalyticsChart
                  type="bar"
                  data={categoryChartData}
                  xKey="name"
                  datasets={[{ label: '数量', data: categoryChartData.map(d => d.value as number), backgroundColor: ['#3b82f6','#10b981','#f59e0b','#ef4444','#8b5cf6','#ec4899','#06b6d4','#84cc16'] }]}
                  height={250}
                />
              ) : (
                <div className="h-[250px] flex items-center justify-center text-[var(--text-muted)]">暂无数据</div>
              )}
            </div>

            {/* 状态分布 */}
            <div className="card p-[var(--space-apple-lg)]">
              <h4 className="font-bold text-[var(--text-primary)] mb-[var(--space-apple-md)]"><PieChart className="w-4 h-4 inline mr-2" />配方状态分布</h4>
              {statusDistribution ? (
                <AnalyticsChart
                  type="pie"
                  data={statusChartData}
                  nameKey="name"
                  dataKey="value"
                  datasets={[{ label: '状态', data: statusChartData.map(d => d.value as number), backgroundColor: ['#94a3b8','var(--color-primary-500)','#6b7280','#f59e0b'] }]}
                  height={250}
                />
              ) : (
                <div className="h-[250px] flex items-center justify-center text-[var(--text-muted)]">暂无数据</div>
              )}
            </div>

            {/* 面积图 */}
            <div className="card p-[var(--space-apple-lg)]">
              <h4 className="font-bold text-[var(--text-primary)] mb-[var(--space-apple-md)]"><LineChartIcon className="w-4 h-4 inline mr-2" />面积趋势</h4>
              {monthlyTrend ? (
                <AnalyticsChart
                  type="area"
                  data={trendChartData}
                  xKey="month"
                  datasets={[
                    { label: '配方', data: trendChartData.map(d => d.formula as number), borderColor: '#3b82f6', backgroundColor: 'rgba(59,130,246,0.3)', fill: true },
                    { label: '实验', data: trendChartData.map(d => d.experiment as number), borderColor: '#10b981', backgroundColor: 'rgba(16,185,129,0.3)', fill: true },
                  ]}
                  height={250}
                />
              ) : (
                <div className="h-[250px] flex items-center justify-center text-[var(--text-muted)]">暂无数据</div>
              )}
            </div>
          </div>

          {/* 下钻 */}
          {showDrillDown && selectedDataPoint && (
            <div className="card p-[var(--space-apple-lg)] border-2 border-[var(--color-primary)] dark:border-[var(--color-primary)]">
              <div className="flex items-center justify-between mb-[var(--space-apple-md)]">
                <h4 className="font-bold text-[var(--text-primary)]">下钻分析 - {selectedDataPoint.x} ({selectedDataPoint.series})</h4>
                <button onClick={() => setShowDrillDown(false)} className="text-[var(--text-muted)] hover:text-[var(--text-primary)]">✕</button>
              </div>
              <AnalyticsChart
                type="bar"
                data={drillDownData}
                xKey="name"
                datasets={[{ label: '子项数量', data: drillDownData.map(d => d.value as number), backgroundColor: '#3b82f6' }]}
                height={200}
              />
            </div>
          )}
        </div>
      )}

      <div className="flex items-center justify-between px-[var(--space-apple-md)] py-[var(--space-apple-md)] bg-[var(--bg-tertiary)]/50 rounded-[var(--radius-Apple-sm)] text-xs text-[var(--text-muted)]">
        <span>共 {kpiCards.length} 个核心指标 · 当前视图: {viewMode.toUpperCase()}</span>
        <span>数据更新频率: 每 30 秒自动刷新</span>
        <span>最后更新: {lastFetched?.toLocaleString() || '未知'}</span>
      </div>
    </div>
  )
}

﻿/**
 * 报表中心 Tab — 参考 Dashboard 设计风格
 * 使用 Card+CardHeader+CardContent 统一卡片样式
 */
import React, { useState, useEffect, useCallback, useRef } from 'react'
import { logger } from '@/utils/safeLogger'
import {
  FileText, Download, Clock, Plus,
  Table, FileType, Settings2, Loader2, CheckCircle2,
} from 'lucide-react'
import api from '@/api/client'
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui'

interface FilterConfig {
  timeRange: '7d' | '30d' | '90d' | '1y'
  categories: string[]
  status: string[]
  users: string[]
}

interface ReportTemplate {
  id: string
  name: string
  description: string
  widgets: Array<{
    type: string
    title: string
    [key: string]: unknown
  }>
  category?: string
}

interface Props {
  filters: FilterConfig
}

export default function ReportsTab({ filters }: Props) {
  const [templates, setTemplates] = useState<ReportTemplate[]>([])
  const [selectedTemplate, setSelectedTemplate] = useState<string | null>(null)
  const [showGenerator, setShowGenerator] = useState(false)
  const [loading, setLoading] = useState(true)
  const [exporting, setExporting] = useState(false)
  const [exportMsg, setExportMsg] = useState<string | null>(null)

  // 自定义报表表单状态
  const [reportName, setReportName] = useState('')
  // 自定义报表表单状态 — 初始值来自父级 filters，可手动覆盖
  const [timeRange, setTimeRange] = useState<'7d' | '30d' | '90d' | '1y'>(filters?.timeRange ?? '30d')
  const [selectedDimensions, setSelectedDimensions] = useState<string[]>(['formulas'])
  const [exportFormat, setExportFormat] = useState<'pdf' | 'excel' | 'csv'>('excel')

  const formatRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    api.get('/analytics/reports/templates')
      .then(res => {
        setTemplates(res.data.templates ?? [])
        setLoading(false)
      })
      .catch(e => {
        logger.error('[ReportsTab] Failed to load templates:', e)
        setLoading(false)
      })
  }, [])

  const handleGenerate = useCallback(async (templateId: string) => {
    setExporting(true)
    setExportMsg(null)

    try {
      const template = templates.find(t => t.id === templateId)
      if (!template) {
        setExportMsg('找不到模板')
        setExporting(false)
        return
      }

      const widgets = template.widgets.map((w: any) => ({
        type: w.type,
        title: w.title,
        entity: w.table || w.entity,
        columns: w.columns,
        limit: w.limit || 100,
      }))

      const reportRes = await api.post('/analytics/reports', {
        name: template.name,
        description: template.description,
        widgets,
        export_format: exportFormat,
      })
      const reportData = reportRes.data

      const exportRes = await api.post('/analytics/export', {
        data: reportData.report,
        format: exportFormat,
        file_name: `${template.name}_${new Date().toISOString().slice(0, 10)}.${exportFormat === 'pdf' ? 'pdf' : exportFormat === 'csv' ? 'csv' : 'xlsx'}`,
      }, { responseType: 'blob' })

      const blob = exportRes.data
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      const disposition = exportRes.headers['content-disposition']
      const ext = exportFormat === 'pdf' ? 'pdf' : exportFormat === 'csv' ? 'csv' : 'xlsx'
      a.download = disposition
        ?.split('filename*=')[1]?.replace(/"/g, '').replace(/UTF-8''/, '')
        || `${template.name}_export.${ext}`
      document.body.appendChild(a)
      a.click()
      document.body.removeChild(a)
      URL.revokeObjectURL(url)

      setExportMsg(`报表 "${template.name}" 已成功生成并下载`)
    } catch (e: any) {
      logger.error('[ReportsTab] Export failed:', e)
      setExportMsg(`导出失败: ${e?.response?.data?.detail || e?.message || '未知错误'}`)
    } finally {
      setExporting(false)
    }
  }, [templates])

  // 自定义报表提交处理
  const handleCustomGenerate = useCallback(async () => {
    if (!reportName.trim()) {
      setExportMsg('请输入报表名称')
      return
    }

    setExporting(true)
    setExportMsg(null)

    try {
      const widgets = selectedDimensions.map(dim => ({
        type: dim === 'formulas' ? 'table' : dim === 'experiments' ? 'table' : 'kpi',
        title: `${dim} 数据`,
        entity: dim,
        columns: ['id', 'name', 'status', 'created_at'],
        limit: 100,
      }))

      const reportRes = await api.post('/analytics/reports', {
        name: reportName.trim(),
        description: `自定义报表 - 包含 ${selectedDimensions.join(', ')} 数据`,
        widgets,
        export_format: exportFormat,
        filters: { time_range: timeRange },
      })

      const reportData = reportRes.data

      // 根据格式下载
      const formatMap: Record<string, string> = { pdf: 'pdf', excel: 'excel', csv: 'csv' }
      const fmt = formatMap[exportFormat] || 'excel'

      const exportRes = await api.post('/analytics/export', {
        data: reportData.report,
        format: fmt,
        file_name: `${reportName.trim()}_${new Date().toISOString().slice(0, 10)}.${fmt}`,
      }, { responseType: 'blob' })

      const blob = exportRes.data
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = `${reportName.trim()}_export.${fmt}`
      document.body.appendChild(a)
      a.click()
      document.body.removeChild(a)
      URL.revokeObjectURL(url)

      setExportMsg(`报表 "${reportName.trim()}" 已成功生成并下载`)
      setShowGenerator(false)
      // 重置表单
      setReportName('')
      setSelectedDimensions(['formulas'])
      setExportFormat('excel')
    } catch (e: any) {
      logger.error('[ReportsTab] Custom report failed:', e)
      setExportMsg(`导出失败: ${e?.response?.data?.detail || e?.message || '未知错误'}`)
    } finally {
      setExporting(false)
    }
  }, [reportName, selectedDimensions, exportFormat, timeRange])

  const toggleDimension = (dim: string) => {
    setSelectedDimensions(prev =>
      prev.includes(dim) ? prev.filter(d => d !== dim) : [...prev, dim]
    )
  }

  const CATEGORY_LABELS: Record<string, string> = {
    summary: '汇总报表',
    detail: '详细报表',
    trend: '趋势分析',
    custom: '自定义报表',
  }

  const FORMAT_ICONS: Record<string, React.ElementType> = {
    pdf: FileType,
    excel: Table,
    csv: FileText,
  }

  const FORMAT_COLORS: Record<string, string> = {
    pdf: 'text-[var(--color-error-text)] bg-[var(--color-error-container)] dark:bg-[var(--color-error-container)]/40',
    excel: 'text-[var(--color-success-text)] bg-[var(--color-success-container)] dark:bg-[var(--color-success-container)]/40',
    csv: 'text-[var(--color-secondary-text)] bg-[var(--color-secondary-container)] dark:bg-[var(--color-secondary-container)]/40',
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <div className="flex flex-col items-center gap-[var(--space-apple-sm)]">
          <Loader2 className="w-6 h-6 text-[var(--color-primary-text)] animate-spin" />
          <span className="text-sm text-[var(--text-muted)]">正在加载报表模板…</span>
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-[var(--space-apple-md)]">

      {/* 操作栏 */}
      <div className="flex items-center justify-between">
        <div className="text-sm text-[var(--text-muted)]">
          共 {templates.length} 个报表模板
        </div>
        <button
          onClick={() => setShowGenerator(!showGenerator)}
          className="px-[var(--space-apple-sm)] py-1.5 bg-primary-container hover:bg-primary-container text-[var(--color-primary)] text-sm rounded-[var(--radius-Apple-sm)] transition-colors flex items-center gap-1.5"
        >
          <Plus className="w-4 h-4" />
          创建自定义报表
        </button>
      </div>

      {/* 导出结果消息 */}
      {exportMsg && (
        <div className={`p-[var(--space-apple-sm)] rounded-[var(--radius-Apple-sm)] border text-sm flex items-center gap-2 ${
          exportMsg.startsWith('导出失败')
            ? 'bg-[var(--color-error-container)] dark:bg-[var(--color-error-container)]/20 border-[var(--color-error-border)] dark:border-error-900/40 text-[var(--color-error-text)] dark:text-[var(--color-error-text)]'
            : 'bg-[var(--color-success-container)] dark:bg-[var(--color-success-container)]/20 border-[var(--color-success-border)] dark:border-success-900/40 text-[var(--color-success-text)] dark:text-[var(--color-success-text)]'
        }`}>
          {exportMsg.startsWith('导出失败') ? <Settings2 className="w-4 h-4" /> : <CheckCircle2 className="w-4 h-4" />}
          <span>{exportMsg}</span>
        </div>
      )}

      {/* 报表模板网格 */}
      {templates.length > 0 ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
