} from 'lucide-react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { batchApi, sampleApi } from '@/api/batch'
import { StatusBadge, EmptyState, Skeleton } from '@/components/ui/Common'
import { Button, Card, CardContent, CardHeader, CardTitle } from '@/components/ui'
import { useToast } from '@/components/ui/Toast'

export default function BatchDetailPage() {
  const { t, i18n } = useTranslation()
  const { id } = useParams<{ id: string }>()
  const navigate = useNavigate()
  const { addToast } = useToast()
  const queryClient = useQueryClient()
  const batchId = Number(id)
  const [showStatusAction, setShowStatusAction] = useState(false)

  // 使用 null 安全获取；503/404 → null
  const { data: batch, isLoading: batchLoading, error: batchError } = useQuery({
    queryKey: ['batch', batchId],
    queryFn: () => batchApi.get(batchId),
    enabled: !!batchId,
    retry: false,
  })

  const { data: samples, isLoading: samplesLoading } = useQuery({
    queryKey: ['samples', { batch_id: batchId }],
    queryFn: () => sampleApi.list({ batch_id: batchId }),
    enabled: !!batchId && !!batch,
  })

  const { data: backwardTrace, isLoading: traceLoading } = useQuery({
    queryKey: ['batch-trace-backward', batchId],
    queryFn: () => batchApi.backwardTrace(batchId),
    enabled: !!batchId && !!batch,
  })

  const updateStatus = useMutation({
    mutationFn: ({ batchId, status, actualWeight }: { batchId: number; status: string; actualWeight?: number }) =>
      batchApi.updateStatus(batchId, status, actualWeight),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['batch', batchId] })
      queryClient.invalidateQueries({ queryKey: ['samples', { batch_id: batchId }] })
      queryClient.invalidateQueries({ queryKey: ['batch-trace-backward', batchId] })
      addToast({ type: 'success', message: t('pages.batch.statusUpdated') })
      setShowStatusAction(false)
    },
    onError: (e: any) => {
      addToast({ type: 'error', message: t('pages.batch.statusUpdateFailed', { message: e?.response?.data?.detail ?? e?.message }) })
    },
  })

  // ── 加载中 ──
  if (batchLoading || samplesLoading || traceLoading) {
    return (
      <div className="max-w-[1600px] mx-auto space-y-6 py-[var(--space-apple-lg)] px-4 sm:px-5 lg:px-[var(--space-apple-lg)]">
        <div className="flex items-center gap-[var(--space-apple-sm)]">
          <Skeleton className="h-6 w-20" />
          <Skeleton className="h-8 w-48" />
        </div>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          {Array.from({ length: 4 }).map((_, i) => <Skeleton key={i} className="h-24" />)}
        </div>
        <Skeleton className="h-48" />
        <Skeleton className="h-32" />
      </div>
    )
  }

  // ── 错误 / 不存在 ──
  if (!batch) {
    const errorMsg = batchError instanceof Error
      ? batchError.message
      : t('pages.batch.notAvailable')
    return (
      <div className="max-w-[1600px] mx-auto px-4 sm:px-5 lg:px-[var(--space-apple-lg)]">
        <button
          onClick={() => navigate('/batches')}
          className="flex items-center gap-1 text-sm text-[var(--text-muted)] hover:text-[var(--text-primary)] transition-colors mb-[var(--space-apple-md)]"
        >
          <ArrowLeft size={16} /> {t('pages.batch.backToList')}
        </button>
        <EmptyState
          icon={<AlertCircle size={48} className="text-[var(--color-warning-text)]0" strokeWidth={1.5} />}
          title={t('pages.batch.notAvailable')}
          description={errorMsg}
          action={
            <div className="flex gap-2 mt-[var(--space-apple-md)]">
              <button
                onClick={() => navigate('/batches')}
                className="px-[var(--space-apple-md)] py-2 rounded-[var(--radius-Apple-sm)] bg-primary-surface text-white text-sm hover:bg-primary-surface-hover transition-colors"
              >
                {t('pages.batch.backToBatches')}
              </button>
              <button
                onClick={() => navigate('/batches/new')}
                className="px-[var(--space-apple-md)] py-2 rounded-[var(--radius-Apple-sm)] border border-[var(--border-color)] text-sm hover:bg-[var(--bg-tertiary)] dark:hover:bg-[var(--bg-tertiary)] transition-colors"
              >
                {t('pages.batch.newBatch')}
              </button>
            </div>
          }
        />
      </div>
    )
  }

  // ── 正常渲染 ──
  return (
    <div className="min-h-screen">
      <div className="max-w-[1600px] mx-auto space-y-6 py-[var(--space-apple-lg)] px-4 sm:px-5 lg:px-[var(--space-apple-lg)]">
      {/* 页头横幅 — 对齐 Dashboard 品牌横幅规范 */}
      <div className="surface-primary rounded-[var(--radius-Apple-md)] p-[var(--space-apple-lg)] shadow-sm">
        <div className="flex items-start gap-4">
          <button
            onClick={() => navigate('/batches')}
            className="flex items-center gap-1 text-sm text-white/80 hover:text-white transition-colors mt-1"
          >
            <ArrowLeft size={16} /> {t('pages.batch.back')}
          </button>
          <div className="flex-1">
            <div className="flex items-center gap-[var(--space-apple-sm)] flex-wrap">
              <h1 className="text-xl font-semibold leading-snug tracking-tight">
                {batch.batch_code}
              </h1>
              <StatusBadge status={batch.status} />
            </div>
            <p className="text-white/80 text-sm mt-1">
              {t('pages.batch.formulaLabel')}{' '}
              <Link to={`/formulas/${batch.formula_id}`} className="text-white underline font-medium">
                {batch.formula_name || batch.formula_code}
              </Link>
              {batch.preparation_date && (
                <span className="ml-4">{t('pages.batch.created', { date: new Date(batch.created_at).toLocaleString(i18n.language) })}</span>
              )}
            </p>
          </div>
          <div className="flex gap-2">
            <button onClick={() => window.print()} className="px-[var(--space-apple-sm)] py-1.5 rounded-[var(--radius-Apple-sm)] bg-[var(--bg-secondary)]/15 hover:bg-[var(--bg-secondary)]/25 text-sm text-[var(--color-primary-text)] dark:text-white transition-colors flex items-center gap-1">
              <Printer size={14} /> {t('pages.batch.print')}
            </button>
            <button className="px-[var(--space-apple-sm)] py-1.5 rounded-[var(--radius-Apple-sm)] bg-[var(--bg-secondary)]/15 hover:bg-[var(--bg-secondary)]/25 text-sm text-[var(--color-primary-text)] dark:text-white transition-colors flex items-center gap-1">
              <Download size={14} /> {t('pages.batch.export')}
            </button>
          </div>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <StatCard label={t('pages.batch.targetYield')} value={`${batch.target_weight_kg?.toFixed(3)} kg`} />
        <StatCard
          label={t('pages.batch.actualYield')}
          value={batch.actual_weight_kg ? `${batch.actual_weight_kg.toFixed(3)} kg` : '—'}
          sub={batch.actual_weight_kg ? t('pages.batch.achievementRate', { rate: ((batch.actual_weight_kg / batch.target_weight_kg) * 100).toFixed(1) }) : undefined}
        />
        <StatCard label={t('pages.batch.yieldRate')} value={batch.yield_rate ? `${batch.yield_rate.toFixed(1)}%` : '—'} />
        <StatCard label={t('pages.batch.sampleCount')} value={String(batch.sample_count ?? 0)} />
      </div>

      {/* Action Buttons */}
      <div className="flex gap-2 flex-wrap">
        {batch.status === 'planned' && (
          <Button
            size="sm"
            onClick={() => { setShowStatusAction(true); updateStatus.mutate({ batchId, status: 'in_progress' }) }}
          >
            <Play size={14} /> {t('pages.batch.startProduction')}
          </Button>
        )}
        {batch.status === 'in_progress' && (
          <Button
            size="sm"
            variant="outline"
            onClick={() => updateStatus.mutate({ batchId, status: 'completed' })}
          >
            <CheckCircle size={14} /> {t('pages.batch.complete')}
          </Button>
        )}
        {batch.status === 'completed' && (
          <Button
            size="sm"
            variant="outline"
            onClick={() => {
              if (confirm(t('pages.batch.confirmClose'))) {
                updateStatus.mutate({ batchId, status: 'closed' })
              }
            }}
          >
            <Lock size={14} /> {t('pages.batch.close')}
          </Button>
        )}
        <Link to="/batches/new">
          <Button size="sm" variant="outline">
            <Plus size={14} /> {t('pages.batch.newBatchShort')}
          </Button>
        </Link>
        <Link to={`/trace/backward?batch=${batchId}`}>
          <Button size="sm" variant="outline">
            <ArrowRight size={14} /> {t('pages.batch.backwardTrace')}
          </Button>
        </Link>
      </div>

      {/* Samples Section */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-base">
            <TestTube size={16} className="text-primary" />
            {t('pages.batch.sampleList', { count: samples?.total ?? 0 })}
          </CardTitle>
        </CardHeader>
        <CardContent>
          {samples?.items && samples.items.length > 0 ? (
            <div className="space-y-2">
              {samples.items.map(sample => (
                <div
                  key={sample.id}
                  className="flex items-center justify-between p-[var(--space-apple-sm)] rounded-[var(--radius-Apple-sm)] border border-[var(--border-color)] hover:bg-[var(--bg-tertiary)] dark:hover:bg-[var(--bg-tertiary)]/50 transition-colors cursor-pointer"
                >
                  <div className="flex items-center gap-[var(--space-apple-sm)]">
                    <span className="font-mono text-xs text-primary">{sample.sample_code}</span>
                    <span className="text-sm text-[var(--text-secondary)]">{sample.sample_type}</span>
                    {sample.storage_condition && (
                      <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{sample.storage_condition}</span>
                    )}
                  </div>
                  <div className="flex items-center gap-[var(--space-apple-sm)] text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                    <span>{t('pages.batch.testCount', { count: sample.test_count ?? 0 })}</span>
                    <ChevronRight size={14} />
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <EmptyState
              icon={<TestTube size={40} strokeWidth={1.5} />}
              title={t('pages.batch.noSamples')}
              description={t('pages.batch.noSamplesDesc')}
            />
          )}
        </CardContent>
      </Card>

      {/* Traceability Preview */}
      {backwardTrace && backwardTrace.ingredient_lots && backwardTrace.ingredient_lots.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-base">
              <Tag size={16} className="text-primary" />
              {t('pages.batch.ingredientTrace', { count: backwardTrace.ingredient_lots.length })}
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              {backwardTrace.ingredient_lots.map((lot: any) => (
                <div
                  key={lot.id}
                  className="flex items-center justify-between p-[var(--space-apple-sm)] rounded-[var(--radius-Apple-sm)] border border-[var(--border-color)] bg-[var(--bg-secondary)]/50"
                >
                  <div className="flex items-center gap-[var(--space-apple-sm)]">
                    <div className="w-8 h-8 rounded-[var(--radius-Apple-sm)] bg-[var(--color-success-container)] flex items-center justify-center">
                      <Tag size={14} className="text-[var(--color-success-text)]0 dark:text-[var(--color-success-text)]" />
                    </div>
                    <div>
                      <div className="font-mono text-xs text-primary">{lot.internal_lot_code}</div>
                      <div className="text-sm text-[var(--text-secondary)]">{lot.ingredient_name}</div>
                    </div>
                  </div>
                  <div className="text-right text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                    <div>{t('pages.batch.supplier', { name: lot.supplier_lot_number || '—' })}</div>
                    <div className="font-mono text-[var(--text-primary)]">
                      {t('pages.batch.usageQty', { weight: lot.used_qty_kg?.toFixed(3) })}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}
      </div>
    </div>
  )
}

/* ── 辅助组件 ─────────────────────────────────────────────────── */

function StatCard({
  label,
  value,
  sub,
}: {
  label: string
  value: string
  sub?: string
}) {
  return (
    <Card>
      <CardContent className="pt-[var(--space-apple-md)]">
        <div className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{label}</div>
        <div className="text-2xl font-semibold mt-1">{value}</div>
        {sub && <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">{sub}</div>}
      </CardContent>
    </Card>
  )
}

/**
 * 追溯查询页面
 * Phase 2: 双向追溯 + 真实批次数据选择 + 完整错误处理
 */
import { useState, useEffect } from 'react'
import { useParams, useNavigate, Link } from 'react-router-dom'
import { ArrowLeft, Search, Package, TestTube, AlertCircle, CheckCircle2 } from 'lucide-react'
import { useQuery } from '@tanstack/react-query'
import { batchApi } from '@/api/batch'
import { Button, Input, Card, CardContent, CardHeader, CardTitle } from '@/components/ui'
import { StatusBadge, EmptyState, Skeleton } from '@/components/ui/Common'
import { cn } from '@/lib/utils'
import { useToast } from '@/components/ui/Toast'

type TraceMode = 'forward' | 'backward'

export default function TracePage() {
  const navigate = useNavigate()
  const { addToast } = useToast()
  const { mode } = useParams<{ mode: string }>()
  const [lotCode, setLotCode] = useState('')
  const [batchId, setBatchId] = useState('')
  const [result, setResult] = useState<any>(null)
  const [loading, setLoading] = useState(false)
  const [traceMode, setTraceMode] = useState<TraceMode>(mode === 'forward' ? 'forward' : 'backward')
  const [traceError, setTraceError] = useState<string | null>(null)

  // 加载可用批次列表（反向追溯时下拉选择）
  const { data: batchesData, isLoading: batchesLoading } = useQuery({
    queryKey: ['batches', { page: 1, page_size: 50 }],
    queryFn: () => batchApi.list({ page: 1, page_size: 50 }),
    enabled: traceMode === 'backward',
  })

  // 加载原料批号列表（正向追溯时使用，从 ingredient_lots 提取）
  const { data: ingredientsData } = useQuery({
    queryKey: ['ingredients', 'lots'],
    queryFn: async () => {
      const res = await fetch('/api/v1/ingredients')
      if (!res.ok) return []
      const d = await res.json()
      return (d?.data?.items ?? []).map((item: any) => ({
        id: item.id,
        name: item.name,
        lot_code: item.lot_code || item.internal_lot_code || `LOT-${item.id}`,
      }))
    },
    enabled: traceMode === 'forward',
    staleTime: 60_000,
  })

  // 当 URL 参数提供了 batchId 时自动填充
  useEffect(() => {
    if (mode === 'backward' && (batchesData?.items ?? []).length > 0) {
      // 从 URL 读取?batch=X 参数
      const params = new URLSearchParams(window.location.search)
      const urlBatch = params.get('batch')
      if (urlBatch && !batchId) setBatchId(urlBatch)
    }
  }, [mode, batchesData, batchId])

  const handleForwardTrace = async () => {
    if (!lotCode.trim()) {
      addToast({ type: 'warning', message: '请输入原料批号 ID' })
      return
    }
    setLoading(true)
    setTraceError(null)
    setResult(null)
    try {
      const lotId = parseInt(lotCode)
      if (isNaN(lotId)) throw new Error('请输入有效的数字批号')
      const data = await batchApi.forwardTrace(lotId)
      setResult(data)
      addToast({ type: 'success', message: `正向追溯完成：找到 ${data?.batch_count ?? 0} 个关联批次` })
    } catch (e: any) {
      const msg = e?.response?.data?.detail ?? e?.message ?? '追溯请求失败'
      setTraceError(msg)
      setResult({ error: msg })
      addToast({ type: 'error', message: `正向追溯失败：${msg}` })
    } finally {
      setLoading(false)
    }
  }

  const handleBackwardTrace = async () => {
    if (!batchId.trim()) {
      addToast({ type: 'warning', message: '请选择或输入批次 ID' })
      return
    }
    setLoading(true)
    setTraceError(null)
    setResult(null)
    try {
      const id = parseInt(batchId)
      if (isNaN(id)) throw new Error('请输入有效的批次 ID')
      const data = await batchApi.backwardTrace(id)
      setResult(data)
      addToast({ type: 'success', message: `反向追溯完成：找到 ${data?.ingredient_lot_count ?? 0} 个原料批号` })
    } catch (e: any) {
      const msg = e?.response?.data?.detail ?? e?.message ?? '追溯请求失败'
      setTraceError(msg)
      setResult({ error: msg })
      addToast({ type: 'error', message: `反向追溯失败：${msg}` })
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="min-h-screen">
      <div className="max-w-[1600px] mx-auto space-y-6 py-[var(--space-apple-lg)] px-4 sm:px-5 lg:px-[var(--space-apple-lg)]">
      {/* 返回按钮 */}
      <button
        onClick={() => navigate(-1)}
        className="flex items-center gap-1 text-sm text-[var(--text-muted)] hover:text-[var(--text-primary)] transition-colors"
      >
        <ArrowLeft size={16} /> 返回
      </button>

      {/* 页头横幅 — 对齐 Dashboard 品牌横幅规范 */}
      <div className="surface-primary rounded-[var(--radius-Apple-md)] p-[var(--space-apple-lg)] shadow-sm">
        <h1 className="text-xl font-semibold leading-snug tracking-tight flex items-center gap-2">
          <Search size={20} className="text-white/80 shrink-0" />
          双向追溯
        </h1>
        <p className="mt-1 text-white/80 text-sm">追踪原料批号与成品批次之间的完整链路</p>
      </div>

      {/* 模式切换标签 */}
      <div className="flex gap-2 p-1 bg-[var(--bg-tertiary)] rounded-[var(--radius-Apple-md)] w-fit">
        <button
          onClick={() => { setTraceMode('backward'); setResult(null); setTraceError(null) }}
          className={cn(
            'px-[var(--space-apple-md)] py-2 rounded-[var(--radius-Apple-sm)] text-sm font-medium transition-all',
            traceMode === 'backward'
              ? 'bg-[var(--bg-secondary)] dark:bg-[var(--bg-secondary)] text-primary shadow-sm'
              : 'text-[var(--text-muted)] hover:text-[var(--text-primary)]',
          )}
        >
          <span className="flex items-center gap-2">
            <Package size={14} />
            反向追溯（批次→原料）
          </span>
        </button>
        <button
          onClick={() => { setTraceMode('forward'); setResult(null); setTraceError(null) }}
          className={cn(
            'px-[var(--space-apple-md)] py-2 rounded-[var(--radius-Apple-sm)] text-sm font-medium transition-all',
            traceMode === 'forward'
              ? 'bg-[var(--bg-secondary)] dark:bg-[var(--bg-secondary)] text-primary shadow-sm'
              : 'text-[var(--text-muted)] hover:text-[var(--text-primary)]',
          )}
        >
          <span className="flex items-center gap-2">
            <TestTube size={14} />
            正向追溯（原料→批次）
          </span>
        </button>
      </div>

      {/* 反向追溯：批次选择 */}
      {traceMode === 'backward' && (
        <Card>
          <CardHeader>
            <CardTitle className="text-base flex items-center gap-2">
              <Package size={16} className="text-primary" /> 反向追溯 — 选择批次
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-[var(--space-apple-md)]">
            {batchesLoading ? (
              <Skeleton className="h-10 w-full" />
            ) : batchesData?.items?.length === 0 ? (
              <div className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] text-center py-4">
                当前无批记录，请先{' '}
                <Link to="/batches/new" className="text-primary hover:underline font-medium">创建批记录</Link>
              </div>
            ) : (
              <>
                <select
                  value={batchId}
                  onChange={e => setBatchId(e.target.value)}
                  className="w-full h-10 px-[var(--space-apple-sm)] rounded-[var(--radius-Apple-sm)] border border-[var(--border-color)] bg-transparent text-sm text-[var(--text-primary)] focus:outline-none focus:ring-2 focus:ring-primary/50"
                >
                  <option value="">— 选择批次 —</option>
                  {batchesData?.items?.map((b: any) => (
                    <option key={b.id} value={b.id}>
                      {b.batch_code} · {b.formula_name || b.formula_code} · {b.status}
                    </option>
                  ))}
                </select>
                <div className="flex items-center justify-between text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                  <span>共 {batchesData?.total ?? 0} 条批记录</span>
                  <Link to="/batches" className="text-primary hover:underline">查看全部</Link>
                </div>
                <Button onClick={handleBackwardTrace} disabled={loading || !batchId} className="w-full sm:w-auto">
                  {loading ? (
                    <span className="flex items-center gap-2"><span className="w-3 h-3 border-2 border-white/30 border-t-white rounded-[var(--radius-pill)] animate-spin" />查询中...</span>
                  ) : (
                    <><Search size={14} /> 开始追溯</>
                  )}
                </Button>
              </>
            )}
          </CardContent>
        </Card>
      )}

      {/* 正向追溯：批号输入 */}
      {traceMode === 'forward' && (
        <Card>
          <CardHeader>
            <CardTitle className="text-base flex items-center gap-2">
              <TestTube size={16} className="text-primary" /> 正向追溯 — 输入原料批号
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-[var(--space-apple-md)]">
            <div className="flex gap-[var(--space-apple-sm)]">
              <Input
                placeholder="输入原料批号 ID..."
                value={lotCode}
                onChange={e => setLotCode(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleForwardTrace()}
                className="flex-1 max-w-xs"
              />
              <Button onClick={handleForwardTrace} disabled={loading || !lotCode.trim()}>
                {loading ? (
                  <span className="flex items-center gap-2"><span className="w-3 h-3 border-2 border-white/30 border-t-white rounded-[var(--radius-pill)] animate-spin" />查询中...</span>
                ) : (
                  <><Search size={14} /> 追溯</>
                )}
              </Button>
            </div>
            <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">输入原料入库批号，查找所有使用该批号的成品批次</p>
          </CardContent>
        </Card>
      )}

      {/* 错误提示 */}
      {traceError && (
        <Card className="border-danger-200 dark:border-danger-900/50">
          <CardContent className="pt-[var(--space-apple-md)] flex items-start gap-[var(--space-apple-sm)] text-danger-600 dark:text-danger-600">
            <AlertCircle size={18} className="shrink-0 mt-0.5" />
            <div>
              <div className="font-medium text-sm">追溯失败</div>
              <div className="text-xs mt-1 opacity-80">{traceError}</div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* 追溯结果 */}
      {result && !result.error && (
        <div className="space-y-[var(--space-apple-md)]">
          {traceMode === 'backward' ? (
            <ResultCard result={result} type="backward" onGoToBatch={(id: number) => navigate(`/batches/${id}`)} />
          ) : (
            <ResultCard result={result} type="forward" />
          )}
        </div>
      )}
      </div>
    </div>
  )
}

/* ── 结果卡片 ─────────────────────────────────────────────────── */

function ResultCard({
  result,
  type,
  onGoToBatch,
}: {
  result: any
  type: 'forward' | 'backward'
  onGoToBatch?: (id: number) => void
}) {
  if (type === 'backward') {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-base">
            <CheckCircle2 size={16} className="text-[var(--color-success-text)]0 dark:text-[var(--color-success-text)]" />
            反向追溯结果
            {result.batch_code && (
              <span className="font-mono text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] font-normal ml-auto">
                {result.batch_code}
              </span>
            )}
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-[var(--space-apple-md)]">
          {/* 批次摘要 */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-[var(--space-apple-sm)]">
            <div className="p-[var(--space-apple-sm)] rounded-[var(--radius-Apple-sm)] bg-[var(--bg-tertiary)]/50">
              <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">配方</div>
              <div className="text-sm font-medium truncate" title={result.formula_name || result.formula_code}>
                {result.formula_name || result.formula_code || '—'}
              </div>
            </div>
            <div className="p-[var(--space-apple-sm)] rounded-[var(--radius-Apple-sm)] bg-[var(--bg-tertiary)]/50">
              <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">目标产量</div>
              <div className="text-sm font-medium">
                {result.target_weight_kg?.toFixed(3)} kg
              </div>
            </div>
            <div className="p-[var(--space-apple-sm)] rounded-[var(--radius-Apple-sm)] bg-[var(--bg-tertiary)]/50">
              <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">原料批号数</div>
              <div className="text-sm font-medium">{result.ingredient_lot_count ?? 0}</div>
            </div>
            <div className="p-[var(--space-apple-sm)] rounded-[var(--radius-Apple-sm)] bg-[var(--bg-tertiary)]/50">
              <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">样品数</div>
              <div className="text-sm font-medium">{result.samples?.length ?? 0}</div>
            </div>
          </div>

          {/* 原料批号列表 */}
          {result.ingredient_lots?.length > 0 ? (
            <div>
              <h2 className="text-sm font-medium text-[var(--text-primary)] mb-2">
                使用的原料批号 ({result.ingredient_lots.length})
              </h2>
              <div className="space-y-2">
                {result.ingredient_lots.map((lot: any) => (
                  <div
                    key={lot.id}
                    className="flex items-center justify-between p-[var(--space-apple-sm)] rounded-[var(--radius-Apple-sm)] border border-[var(--border-color)] bg-[var(--bg-secondary)]/50"
                  >
                    <div className="flex items-center gap-[var(--space-apple-sm)]">
                      <div className="w-8 h-8 rounded-[var(--radius-Apple-sm)] bg-primary/10 flex items-center justify-center">
                        <Package size={14} className="text-primary" />
                      </div>
                      <div>
                        <div className="font-mono text-xs text-primary">{lot.internal_lot_code}</div>
                        <div className="text-sm text-[var(--text-secondary)]">{lot.ingredient_name}</div>
                      </div>
                    </div>
                    <div className="text-right text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                      <div>供应商: {lot.supplier_lot_number || '—'}</div>
                      <div className="font-mono">用量: {lot.used_qty_kg?.toFixed(3)} kg</div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ) : (
            <div className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] text-center py-4">暂无原料批号记录</div>
          )}

          {/* 样品列表 */}
          {result.samples?.length > 0 && (
            <div>
              <h2 className="text-sm font-medium text-[var(--text-primary)] mb-2 flex items-center gap-2">
                <TestTube size={14} /> 关联样品 ({result.samples.length})
              </h2>
              <div className="space-y-2">
                {result.samples.map((s: any) => (
                  <div
                    key={s.id}
                    className="flex items-center justify-between p-[var(--space-apple-sm)] rounded-[var(--radius-Apple-sm)] border border-[var(--border-color)] bg-[var(--bg-secondary)]/50"
                  >
                    <div className="flex items-center gap-[var(--space-apple-sm)]">
                      <div className="w-8 h-8 rounded-[var(--radius-Apple-sm)] bg-[var(--color-accent-container)] flex items-center justify-center">
                        <TestTube size={14} className="text-[var(--color-accent-text)]0" />
                      </div>
                      <div>
                        <div className="font-mono text-xs text-[var(--color-accent-text)] dark:text-[var(--color-accent-text)]">{s.sample_code}</div>
                        <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{s.sample_type}</div>
                      </div>
                    </div>
                    <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">测试项: {s.test_count ?? 0}</div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </CardContent>
      </Card>
    )
  }

  // 正向追溯
  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2 text-base">
          <CheckCircle2 size={16} className="text-[var(--color-success-text)]0 dark:text-[var(--color-success-text)]" />
          正向追溯结果
          {result.ingredient_name && (
            <span className="font-mono text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] font-normal ml-auto">
              {result.ingredient_name} · Lot #{result.ingredient_lot_id ?? result.ingredient_lot_code ?? '—'}
            </span>
          )}
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-[var(--space-apple-md)]">
        {/* 原料摘要 */}
        {(result.ingredient_name || result.received_qty_kg) && (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-[var(--space-apple-sm)]">
            {result.ingredient_name && (
              <div className="p-[var(--space-apple-sm)] rounded-[var(--radius-Apple-sm)] bg-[var(--bg-tertiary)]/50">
                <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">原料</div>
                <div className="text-sm font-medium">{result.ingredient_name}</div>
              </div>
            )}
            {result.received_qty_kg != null && (
              <div className="p-[var(--space-apple-sm)] rounded-[var(--radius-Apple-sm)] bg-[var(--bg-tertiary)]/50">
                <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">入库量</div>
                <div className="text-sm font-medium">{result.received_qty_kg.toFixed(3)} kg</div>
              </div>
            )}
            {result.remaining_qty_kg != null && (
              <div className="p-[var(--space-apple-sm)] rounded-[var(--radius-Apple-sm)] bg-[var(--bg-tertiary)]/50">
                <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">剩余量</div>
                <div className="text-sm font-medium">{result.remaining_qty_kg.toFixed(3)} kg</div>
              </div>
            )}
            <div className="p-[var(--space-apple-sm)] rounded-[var(--radius-Apple-sm)] bg-[var(--bg-tertiary)]/50">
              <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">使用批次</div>
              <div className="text-sm font-medium">{result.batch_count ?? 0}</div>
            </div>
          </div>
        )}

        {/* 关联批次 */}
        {result.batches?.length > 0 ? (
          <div>
            <h2 className="text-sm font-medium text-[var(--text-primary)] mb-2">
              使用的批次 ({result.batches.length})
            </h2>
            <div className="space-y-2">
              {result.batches.map((b: any) => (
                <div
                  key={b.id}
                  className="flex items-center justify-between p-[var(--space-apple-sm)] rounded-[var(--radius-Apple-sm)] border border-[var(--border-color)] bg-[var(--bg-secondary)]/50"
                >
                  <div className="flex items-center gap-[var(--space-apple-sm)]">
                    <div className="w-8 h-8 rounded-[var(--radius-Apple-sm)] bg-[var(--color-warning-container)] flex items-center justify-center">
                      <Package size={14} className="text-[var(--color-warning-text)]0" />
                    </div>
                    <div>
                      <div className="font-mono text-xs text-primary">{b.batch_code}</div>
                      <div className="text-sm text-[var(--text-secondary)]">
                        {b.formula_name || b.formula_code}
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center gap-[var(--space-apple-sm)]">
                    <StatusBadge status={b.status} />
                    {onGoToBatch && (
                      <button
                        onClick={() => onGoToBatch(b.id)}
                        className="text-xs text-primary hover:underline"
                      >
                        查看详情
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        ) : (
          <div className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] text-center py-4">未找到关联批次</div>
        )}

        {/* 关联样品统计 */}
        {result.samples?.length > 0 && (
          <div className="pt-2 border-t border-[var(--border-color)]">
            <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
              共关联 <span className="font-medium text-[var(--text-primary)]">{result.samples.length}</span> 个样品
              {(() => {
                const flat = (result.samples as any[]).flat()
                return flat?.length ? `，${flat.length} 条测试记录` : ''
              })()}
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  )
}

/**
 * /billing — 组织级订阅与账单页
 * - 当前计划 + 用量概览
 * - 升级方案对比（模拟支付）
 * - 订单历史（GET /organizations/{id}/subscription/orders）
 * - 企业版定制联系（mailto）
 * 仅组织 owner/admin 可访问（非管理员显示无权限提示）
 */
import { useState, useEffect, useCallback } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import {
  Building2, HardDrive, Users, FlaskConical, Zap, Sparkles,
  RefreshCw, Check, Shield, ArrowLeft, Mail, Loader2,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import api from '@/api/client';
import { useToast } from '@/components/ui/Toast';

interface OrgItem {
  id: number;
  name: string;
  slug: string;
  plan: string;
  myRole?: string;
}

interface SubscriptionInfo {
  organization_id: number;
  plan: string;
  plan_display_name: string;
  status: string;
  billing_cycle: string;
  started_at?: string | null;
  expires_at?: string | null;
  usage: Record<string, { used: number; limit: number; over: boolean }>;
}

interface OrderItem {
  id: number;
  plan: string;
  billing_cycle: string;
  amount_cents: number;
  currency: string;
  status: string;
  provider_order_id?: string;
  paid_at?: string | null;
  created_at?: string;
}

const PLAN_META: Record<string, { label: string; monthly: string; yearly: string; color: string; desc: string }> = {
  free: { label: '免费版', monthly: '¥0', yearly: '¥0', color: 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)] dark:bg-[var(--bg-tertiary)] dark:text-[var(--text-muted)]', desc: '5 成员 / 2 团队 / 100 配方 / 1GB' },
  pro: { label: '专业版', monthly: '¥199/月', yearly: '¥1999/年', color: 'bg-[var(--color-primary-container)] text-[var(--color-primary-text)] dark:bg-[var(--color-primary-container)]/25 dark:text-[var(--color-primary-text)]', desc: '50 成员 / 10 团队 / 1000 配方 / 10GB' },
  enterprise: { label: '企业版', monthly: '¥1999/月起', yearly: '定制', color: 'bg-[var(--color-warning-container)] text-[var(--color-warning-text)] dark:bg-[var(--color-warning-container)]/25 dark:text-[var(--color-warning-text)]', desc: '无限资源 / SSO / 私有化部署' },
};

const USAGE_LABELS: Record<string, { label: string; icon: typeof Users }> = {
  members: { label: '成员', icon: Users },
  teams: { label: '团队', icon: Building2 },
  formulas: { label: '配方', icon: FlaskConical },
  storage: { label: '存储', icon: HardDrive },
  api_calls: { label: 'API 调用/天', icon: Zap },
  ai_generations: { label: 'AI 生成/天', icon: Sparkles },
};

function formatUsed(used: number, limit: number, key: string): string {
  if (key === 'storage') {
    return `${(used / 1024 / 1024 / 1024).toFixed(1)}GB / ${limit < 0 ? '无限' : `${(limit / 1024 / 1024 / 1024).toFixed(0)}GB`}`;
  }
  return `${used} / ${limit < 0 ? '无限' : limit}`;
}

function formatMoney(cents: number, currency: string): string {
  const sym = currency === 'CNY' ? '¥' : '$';
  return `${sym}${(cents / 100).toFixed(2)}`;
}

export default function BillingPage() {
  const [searchParams, setSearchParams] = useSearchParams();
  const navigate = useNavigate();
  const toast = useToast();

  const urlOrgId = searchParams.get('org') ? Number(searchParams.get('org')) : null;
  const [orgs, setOrgs] = useState<OrgItem[]>([]);
  const [selectedOrgId, setSelectedOrgId] = useState<number | null>(urlOrgId);
  const [subscription, setSubscription] = useState<SubscriptionInfo | null>(null);
  const [orders, setOrders] = useState<OrderItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [billingCycle, setBillingCycle] = useState<'monthly' | 'yearly'>('monthly');
  const [confirmUpgrade, setConfirmUpgrade] = useState<string | null>(null);
  const [upgrading, setUpgrading] = useState(false);

  // 加载组织列表
  useEffect(() => {
    let cancelled = false;
    api.get('/organizations')
      .then((res) => {
        const list = (res.data?.organizations || []).map((o: Record<string, unknown>) => ({
          id: o.id,
          name: o.name,
          slug: o.slug,
          plan: o.plan,
          myRole: o.member_role ?? o.my_role ?? 'member',
        })) as OrgItem[];
        if (cancelled) return;
        setOrgs(list);
        if (!selectedOrgId && list.length > 0) {
          setSelectedOrgId(list[0].id);
        }
      })
      .catch(() => { if (!cancelled) setError('组织列表加载失败'); });
    return () => { cancelled = true; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // 加载订阅与订单
  useEffect(() => {
    if (!selectedOrgId) return;
    let cancelled = false;
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setLoading(true);
    setError(null);
    Promise.all([
      api.get(`/organizations/${selectedOrgId}/subscription`),
      api.get(`/organizations/${selectedOrgId}/subscription/orders`),
    ])
      .then(([subRes, orderRes]) => {
        if (cancelled) return;
        setSubscription(subRes.data?.subscription ?? subRes.data ?? null);
        setOrders(orderRes.data?.orders ?? []);
      })
      .catch((err: any) => {
        if (!cancelled) setError(err?.response?.data?.detail || '订阅数据加载失败');
      })
      .finally(() => { if (!cancelled) setLoading(false); });
    return () => { cancelled = true; };
  }, [selectedOrgId]);

  const selectedOrg = orgs.find((o) => o.id === selectedOrgId) || null;
  const canManage = selectedOrg?.myRole === 'owner' || selectedOrg?.myRole === 'admin';
  const currentPlan = subscription?.plan || selectedOrg?.plan || 'free';
  const planMeta = PLAN_META[currentPlan] || PLAN_META.free;
  const usage = subscription?.usage || {};

  const handleOrgChange = useCallback((orgId: number) => {
    setSelectedOrgId(orgId);
    setSearchParams({ org: String(orgId) }, { replace: true });
    setConfirmUpgrade(null);
  }, [setSearchParams]);

  const handleUpgrade = useCallback(async (plan: string) => {
    if (!selectedOrgId) return;
    setUpgrading(true);
    try {
      await api.post(`/organizations/${selectedOrgId}/subscription/upgrade`, { plan, billing_cycle: billingCycle });
      toast.success(`已升级至 ${PLAN_META[plan]?.label || plan}（模拟支付成功）`);
      setConfirmUpgrade(null);
      // 刷新订阅与订单
      const [subRes, orderRes] = await Promise.all([
        api.get(`/organizations/${selectedOrgId}/subscription`),
        api.get(`/organizations/${selectedOrgId}/subscription/orders`),
      ]);
      setSubscription(subRes.data?.subscription ?? subRes.data ?? null);
      setOrders(orderRes.data?.orders ?? []);
    } catch (err: any) {
      toast.error(err?.response?.data?.detail || '升级失败，请重试');
    } finally {
      setUpgrading(false);
    }
  }, [selectedOrgId, billingCycle, toast]);

  if (!selectedOrgId) {
    return (
      <div className="min-h-[60vh] flex items-center justify-center">
        <p className="text-sm text-[var(--text-muted)]">正在加载组织...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen">
      <div className="max-w-[1600px] mx-auto px-[var(--space-apple-md)] sm:px-6 lg:px-8 py-[var(--space-apple-lg)] space-y-[var(--space-apple-md)]">
        {/* 顶部标题栏 */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
          <div>
            <div className="flex items-center gap-2 text-sm text-[var(--text-muted)]">
              <button onClick={() => navigate('/organizations')} className="flex min-h-[44px] items-center gap-1 -m-2 px-2 hover:text-[var(--text-primary)] transition-colors">
                <ArrowLeft className="w-3.5 h-3.5" /> 返回组织列表
              </button>
            </div>
            <h1 className="mt-1 text-xl font-semibold tracking-tight text-[var(--text-primary)]">组织订阅与账单</h1>
            <p className="text-sm text-[var(--text-muted)] mt-0.5">
              {canManage ? '查看组织当前计划、用量与升级方案' : '仅组织所有者或管理员可管理订阅与查看账单'}
            </p>
          </div>
          {/* 组织选择器 */}
          <select
            value={selectedOrgId}
            onChange={(e) => handleOrgChange(Number(e.target.value))}
            className="px-[var(--space-apple-sm)] py-2 rounded-[var(--radius-Apple-sm)] border border-[var(--border-color)] dark:border-neutral-700 bg-[var(--bg-secondary)] text-sm text-[var(--text-primary)] focus:outline-none focus:ring-2 focus:ring-[var(--color-primary)]"
            aria-label="选择组织"
          >
            {orgs.map((o) => (
              <option key={o.id} value={o.id}>{o.name}（{PLAN_META[o.plan]?.label || o.plan}）</option>
            ))}
          </select>
        </div>

        {error && (
          <div className="p-[var(--space-apple-md)] rounded-[var(--radius-Apple-sm)] bg-[var(--color-error-container)] border border-[var(--color-error-border)] dark:border-[var(--color-error)] text-sm text-[var(--color-error-text)] dark:text-[var(--color-error-text)]">
            {error}
          </div>
        )}

        {!canManage ? (
          <div className="p-10 text-center bg-[var(--bg-secondary)] rounded-[var(--radius-Apple-md)] border border-[var(--border-color)] dark:border-neutral-800">
            <Shield className="w-10 h-10 mx-auto text-[var(--text-muted)] mb-[var(--space-apple-sm)]" />
            <h2 className="text-lg font-semibold text-[var(--text-primary)]">无权限查看账单</h2>
            <p className="text-sm text-[var(--text-muted)] mt-1">仅组织所有者或管理员可管理订阅与查看账单。</p>
          </div>
        ) : (
          <>
            {/* 当前计划 + 用量 */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
              {/* 当前计划卡片 */}
              <div className="bg-[var(--bg-secondary)] rounded-[var(--radius-Apple-md)] border border-[var(--border-color)] dark:border-neutral-800 p-[var(--space-apple-lg)] shadow-sm">
                <div className="flex items-center justify-between">
                  <span className="text-xs font-medium uppercase tracking-wider text-[var(--text-muted)]">当前计划</span>
                  <span className={cn('px-2.5 py-0.5 rounded-[var(--radius-pill)] text-xs font-medium', planMeta.color)}>{planMeta.label}</span>
                </div>
                <p className="mt-[var(--space-apple-sm)] text-2xl font-bold text-[var(--text-primary)]">
                  {billingCycle === 'yearly' ? planMeta.yearly : planMeta.monthly}
                </p>
                <p className="text-sm text-[var(--text-muted)] mt-1">{planMeta.desc}</p>
                <p className="text-xs text-[var(--text-muted)] mt-[var(--space-apple-sm)]">
                  计费周期：{subscription?.billing_cycle === 'yearly' ? '年付' : '月付'} · 状态：{subscription?.status || 'active'}
                </p>
              </div>

              {/* 用量概览 */}
              <div className="lg:col-span-2 bg-[var(--bg-secondary)] rounded-[var(--radius-Apple-md)] border border-[var(--border-color)] dark:border-neutral-800 p-[var(--space-apple-lg)] shadow-sm">
                <div className="flex items-center justify-between mb-[var(--space-apple-md)]">
                  <h2 className="text-sm font-semibold text-[var(--text-primary)]">用量概览</h2>
                  <button
                    onClick={() => { setSelectedOrgId(selectedOrgId); }}
                    className="inline-flex min-h-[44px] items-center gap-1 -m-2 px-2 text-xs text-[var(--text-muted)] hover:text-[var(--color-primary-text)] transition-colors"
                    title="刷新"
                  >
                    <RefreshCw className="w-3 h-3" /> 刷新
                  </button>
                </div>
                {loading ? (
                  <div className="flex items-center justify-center py-8">
                    <Loader2 className="w-6 h-6 text-[var(--color-primary-text)]0 animate-spin" />
                  </div>
                ) : (
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    {Object.entries(USAGE_LABELS).map(([key, meta]) => {
                      const u = usage[key] || { used: 0, limit: -1, over: false };
                      const Icon = meta.icon;
                      const pct = u.limit > 0 ? Math.min(100, Math.round((u.used / u.limit) * 100)) : 0;
                      return (
                        <div key={key}>
                          <div className="flex items-center justify-between text-xs">
                            <span className="flex items-center gap-1.5 text-[var(--text-secondary)]">
                              <Icon className="w-3.5 h-3.5" /> {meta.label}
                            </span>
                            <span className={cn('font-medium', u.over ? 'text-[var(--color-error-text)]' : 'text-[var(--text-muted)]')}>
                              {formatUsed(u.used, u.limit, key)}
                            </span>
                          </div>
                          <div className="mt-1.5 h-1.5 rounded-[var(--radius-pill)] bg-[var(--bg-tertiary)] overflow-hidden">
                            <div
                              className={cn('h-full rounded-[var(--radius-pill)] transition-all', u.over ? 'bg-[var(--color-error-container)]0' : 'bg-[var(--color-primary-container)]0')}
                              style={{ width: `${pct}%` }}
                            />
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            </div>

            {/* 升级方案对比 */}
            <div className="bg-[var(--bg-secondary)] rounded-[var(--radius-Apple-md)] border border-[var(--border-color)] dark:border-neutral-800 p-[var(--space-apple-lg)] shadow-sm">
              <div className="flex items-center justify-between mb-5">
                <h2 className="text-sm font-semibold text-[var(--text-primary)]">升级方案</h2>
                <div className="flex items-center gap-1.5 bg-[var(--bg-tertiary)] rounded-[var(--radius-pill)] p-1">
                  {(['monthly', 'yearly'] as const).map((c) => (
                    <button
                      key={c}
                      onClick={() => setBillingCycle(c)}
                      className={cn(
                        'px-[var(--space-apple-sm)] py-1.5 text-xs font-medium rounded-[var(--radius-pill)] transition-colors min-h-[44px]',
                        billingCycle === c
                          ? 'bg-[var(--bg-secondary)] dark:bg-[var(--bg-secondary)] text-[var(--color-primary-text)] shadow-sm'
                          : 'text-[var(--text-secondary)] hover:text-neutral-800',
                      )}
                    >
                      {c === 'monthly' ? '月付' : '年付（省 17%）'}
                    </button>
                  ))}
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                {(['free', 'pro', 'enterprise'] as const).map((p) => {
                  const meta = PLAN_META[p];
                  const isCurrent = currentPlan === p;
                  return (
                    <div
                      key={p}
                      className={cn(
                        'relative p-5 rounded-[var(--radius-Apple-md)] border-2 transition-all',
                        isCurrent
                          ? 'border-[var(--color-primary)] bg-[var(--color-primary-container)]/40 dark:bg-[var(--color-primary-container)]/10'
                          : 'border-[var(--border-color)] hover:border-[var(--border-color)] dark:hover:border-neutral-600',
                      )}
                    >
                      {p === 'pro' && (
                        <span className="absolute -top-2 right-3 px-1.5 py-0.5 rounded-[var(--radius-pill)] text-xs font-semibold bg-[var(--color-primary)] text-white">推荐</span>
                      )}
                      <p className="font-semibold text-[var(--text-primary)]">{meta.label}</p>
                      <p className="text-lg font-bold text-[var(--text-primary)] mt-1">
                        {billingCycle === 'yearly' ? meta.yearly : meta.monthly}
                      </p>
                      <p className="text-xs text-[var(--text-muted)] mt-1">{meta.desc}</p>
                      {p === 'enterprise' && (
                        <p className="text-xs text-[var(--color-warning-text)] mt-1">含 SSO / 私有化 / 自定义集成</p>
                      )}
                      {isCurrent ? (
                        <span className="inline-flex items-center gap-1 mt-[var(--space-apple-sm)] text-xs font-medium text-[var(--color-primary-text)]">
                          <Check className="w-3.5 h-3.5" /> 当前计划
                        </span>
                      ) : p === 'enterprise' ? (
                        <a
                          href="mailto:sales@rmfood.cn?subject=企业版定制咨询"
                          className="mt-[var(--space-apple-sm)] inline-flex items-center gap-1.5 text-sm font-medium text-[var(--color-warning-text)] hover:text-[var(--color-warning-text)] transition-colors"
                        >
                          <Mail className="w-3.5 h-3.5" /> 联系定制
                        </a>
                      ) : (
                        <button
                          onClick={() => setConfirmUpgrade(p)}
                          className="mt-[var(--space-apple-sm)] inline-flex items-center gap-1 px-[var(--space-apple-sm)] py-1.5 text-sm font-medium bg-[var(--color-primary)] text-white rounded-[var(--radius-Apple-sm)] hover:bg-[var(--color-primary)] transition-colors"
                        >
                          升级至{meta.label}
                        </button>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>

            {/* 订单历史 */}
            <div className="bg-[var(--bg-secondary)] rounded-[var(--radius-Apple-md)] border border-[var(--border-color)] dark:border-neutral-800 overflow-x-auto shadow-sm">
              <div className="px-6 py-4 border-b border-[var(--border-color)] flex items-center justify-between">
                <h2 className="text-sm font-semibold text-[var(--text-primary)]">订单历史</h2>
                <span className="text-xs text-[var(--text-muted)]">当前为演示支付，订单为模拟数据</span>
              </div>
              {orders.length === 0 ? (
                <div className="p-10 text-center text-sm text-[var(--text-muted)]">暂无订单记录</div>
              ) : (
                <table className="w-full text-sm">
                  <thead className="bg-[var(--bg-tertiary)]/50">
                    <tr>
                      <th className="px-6 py-[var(--space-apple-md)] text-left text-xs font-medium text-[var(--text-muted)] uppercase">订单号</th>
                      <th className="px-6 py-[var(--space-apple-md)] text-left text-xs font-medium text-[var(--text-muted)] uppercase">计划</th>
                      <th className="px-6 py-[var(--space-apple-md)] text-left text-xs font-medium text-[var(--text-muted)] uppercase">周期</th>
                      <th className="px-6 py-[var(--space-apple-md)] text-left text-xs font-medium text-[var(--text-muted)] uppercase">金额</th>
                      <th className="px-6 py-[var(--space-apple-md)] text-left text-xs font-medium text-[var(--text-muted)] uppercase">状态</th>
                      <th className="px-6 py-[var(--space-apple-md)] text-left text-xs font-medium text-[var(--text-muted)] uppercase">时间</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-neutral-100 dark:divide-neutral-800">
                    {orders.map((o) => (
                      <tr key={o.id}>
                        <td className="px-6 py-[var(--space-apple-md)] font-mono text-xs text-[var(--text-secondary)]">{o.provider_order_id || `#${o.id}`}</td>
                        <td className="px-6 py-[var(--space-apple-md)] text-[var(--text-primary)]">{PLAN_META[o.plan]?.label || o.plan}</td>
                        <td className="px-6 py-[var(--space-apple-md)] text-[var(--text-secondary)]">{o.billing_cycle === 'yearly' ? '年付' : '月付'}</td>
                        <td className="px-6 py-[var(--space-apple-md)] font-medium text-[var(--text-primary)]">{formatMoney(o.amount_cents, o.currency)}</td>
                        <td className="px-6 py-[var(--space-apple-md)]"><span className="px-2 py-0.5 rounded-[var(--radius-pill)] text-xs font-medium bg-[var(--color-success-container)] text-[var(--color-success-text)]">{o.status}</span></td>
                        <td className="px-6 py-[var(--space-apple-md)] text-[var(--text-muted)]">{o.paid_at ? new Date(o.paid_at).toLocaleString('zh-CN') : '-'}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
          </>
        )}
      </div>

      {/* 升级确认弹窗 */}
      {confirmUpgrade && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-[var(--space-apple-md)]">
          <div className="w-full max-w-md bg-[var(--bg-secondary)] rounded-[var(--radius-Apple-md)] shadow-lg p-[var(--space-apple-lg)]">
            <h3 className="text-lg font-semibold text-[var(--text-primary)]">确认升级</h3>
            <p className="text-sm text-[var(--text-muted)] mt-2">
              将 {selectedOrg?.name} 升级至 <strong>{PLAN_META[confirmUpgrade]?.label}</strong>（{billingCycle === 'yearly' ? '年付' : '月付'}），
              金额 {billingCycle === 'yearly' ? PLAN_META[confirmUpgrade]?.yearly : PLAN_META[confirmUpgrade]?.monthly}。
              当前为模拟支付，不会真实扣款。
            </p>
            <div className="flex justify-end gap-[var(--space-apple-sm)] mt-6">
              <button
                onClick={() => setConfirmUpgrade(null)}
                className="px-[var(--space-apple-md)] py-2 text-sm text-[var(--text-secondary)] hover:bg-[var(--bg-tertiary)] rounded-[var(--radius-Apple-sm)] transition-colors"
              >
                取消
              </button>
              <button
                onClick={() => handleUpgrade(confirmUpgrade)}
                disabled={upgrading}
                className="inline-flex items-center gap-2 px-[var(--space-apple-md)] py-2 text-sm font-medium bg-[var(--color-primary)] text-white rounded-[var(--radius-Apple-sm)] hover:bg-[var(--color-primary)] disabled:opacity-50 transition-colors"
              >
                {upgrading && <Loader2 className="w-4 h-4 animate-spin" />}
                确认升级
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * 合规检查页面 — 完整功能版
 * 十八反十九畏 + GB16740限量 + 自动修复 + 配方历史
 * 主题系统：对齐 Dashboard 设计系统规范（bg-grid + brand banner + Card/Button + design tokens）
 */
import { useState, useEffect } from 'react'
import { useTranslation } from 'react-i18next'
import {
  ShieldCheck, AlertTriangle, CheckCircle2, Trash2, Plus,
  RefreshCw, Search, BookOpen, Scale, Save, History,
  Lightbulb, XCircle,
} from 'lucide-react'
import {
  RadarChart as RechartsRadarChart, Radar, PolarGrid,
  PolarAngleAxis, PolarRadiusAxis, ResponsiveContainer,
  Tooltip as RechartsTooltip,
} from 'recharts'
import { complianceApi, type Ingredient } from '@/api/compliance'
import { ingredientApi } from '@/api/ingredient'
import { useToast } from '@/components/ui/Toast'
import { Card, CardHeader, CardTitle, CardContent, Button, Input, Badge } from '@/components/ui'

const POPULATION_OPTIONS = [
  { value: 'adults', label: '成人' },
  { value: 'children', label: '儿童' },
  { value: 'elderly', label: '老年人' },
]

// ─── 本地存储 ────────────────────────────────────────────────
const FORMULA_KEY = 'rmfood_formula_history'
const loadFormulas = () => { try { return JSON.parse(localStorage.getItem(FORMULA_KEY) ?? '[]') } catch { return [] } }
const saveFormulas = (items: any[]) => localStorage.setItem(FORMULA_KEY, JSON.stringify(items.slice(0, 30)))

export default function ComplianceCheckPage() {
  const { t, i18n } = useTranslation()
  const { addToast } = useToast()
  const [activeTab, setActiveTab] = useState<'check' | 'prohibited' | 'limits' | 'db'>('check')
  const [ingredients, setIngredients] = useState<Ingredient[]>([
    { name: '黄芪', dosage_mg: 5000 },
    { name: '党参', dosage_mg: 3000 },
  ])
  const [population, setPopulation] = useState('adults')
  const [checkResult, setCheckResult] = useState<any>(null)
  const [loading, setLoading] = useState(false)
  const [prohibitedList, setProhibitedList] = useState<any[]>([])
  const [dosageLimits, setDosageLimits] = useState<Record<string, number>>({})
  const [searchTerm, setSearchTerm] = useState('')
  const [dbItems, setDbItems] = useState<any[]>([])
  const [dbTotal, setDbTotal] = useState(0)
  const [homologyList, setHomologyList] = useState<any[]>([])
  const [formulaName, setFormulaName] = useState('')
  const [formulas, setFormulas] = useState<any[]>(loadFormulas)
  const [showFormulas, setShowFormulas] = useState(false)

  useEffect(() => {
    complianceApi.getProhibited().then(r => { if (r.success) setProhibitedList(r.data.combinations ?? []) })
    complianceApi.getLimits().then(r => { if (r.success) setDosageLimits(r.data.limits ?? {}) })
    complianceApi.getFoodHomology().then((r: any) => { if (r.success && r.data?.materials) setHomologyList(r.data.materials) })
  }, [])

  const addIngredient = () => setIngredients([...ingredients, { name: '', dosage_mg: 1000 }])
  const removeIngredient = (i: number) => setIngredients(ingredients.filter((_, idx) => idx !== i))
  const updateIngredient = (i: number, field: string, value: string | number) => {
    const next = [...ingredients]
    next[i] = { ...next[i], [field]: value }
    setIngredients(next)
  }

  const handleCheck = async () => {
    if (!ingredients.some(x => x.name.trim())) {
      addToast({ type: 'warning', message: t('pages.compliance.toastNeedIngredient') })
      return
    }
    setLoading(true)
    try {
      const res = await complianceApi.bulkCheck(ingredients, population as any)
      setCheckResult(res.data)
      addToast({ type: 'success', message: t('pages.compliance.toastScore', { score: res.data?.score ?? '?' }) })
    } catch (e: any) {
      addToast({ type: 'error', message: String(e) })
    } finally { setLoading(false) }
  }

  const handleFix = async () => {
    setLoading(true)
    try {
      const res = await complianceApi.autoFix(ingredients, population as any)
      const data = res.data
      setIngredients(data.fixed_ingredients ?? ingredients)
      setCheckResult({
        score: data.fixed_score,
        status: data.fixed_status,
        violations: data.remaining_violations ?? [],
        warnings: [],
        suggestions: [],
      })
      addToast({
        type: data.fixed_score > data.original_score ? 'success' : 'warning',
        message: t('pages.compliance.toastFixed', { count: data.fixes.length, from: data.original_score, to: data.fixed_score }),
      })
    } catch (e: any) { addToast({ type: 'error', message: String(e) }) }
    finally { setLoading(false) }
  }

  const handleSaveFormula = () => {
    if (!checkResult) { addToast({ type: 'warning', message: t('pages.compliance.toastRunCheckFirst') }); return }
    const name = formulaName.trim() || `配方-${new Date().toLocaleDateString(i18n.language)}`
    const item = {
      id: Date.now(),
      name,
      ingredients: ingredients.map(i => `${i.name}(${i.dosage_mg}mg)`).join(', '),
      score: checkResult.score,
      status: checkResult.status,
      date: new Date().toLocaleDateString(i18n.language),
    }
    const newFormulas = [item, ...formulas].slice(0, 30)
    setFormulas(newFormulas)
    saveFormulas(newFormulas)
    setFormulaName('')
    addToast({ type: 'success', message: t('pages.compliance.toastFormulaSaved', { name }) })
  }

  const handleDbSearch = async () => {
    setLoading(true)
    const search = searchTerm.trim()
    try {
      const homRes: any = await complianceApi.getFoodHomology(search || undefined)
      if (homRes.success && homRes.data?.materials?.length > 0) {
        setDbItems(homRes.data.materials)
        setDbTotal(homRes.data.count ?? homRes.data.materials.length)
        return
      }
      const res: any = await ingredientApi.getIngredients({ page: 1, page_size: 20, search: search })
      if (res.data) { setDbItems(res.data.items ?? []); setDbTotal(res.data.total ?? 0) }
    } catch (e: any) { addToast({ type: 'error', message: String(e) }) }
    finally { setLoading(false) }
  }

  // 供带参数的二次调用（如后续扩展）
  const runDbSearch = async (term?: string) => {
    const search = (term ?? searchTerm).trim()
    const homRes: any = await complianceApi.getFoodHomology(search || undefined)
    if (homRes.success && homRes.data?.materials?.length > 0) {
      setDbItems(homRes.data.materials)
      setDbTotal(homRes.data.count ?? homRes.data.materials.length)
      return
    }
    const res: any = await ingredientApi.getIngredients({ page: 1, page_size: 20, search: search })
    if (res.data) { setDbItems(res.data.items ?? []); setDbTotal(res.data.total ?? 0) }
  }

  useEffect(() => {
    // 切换到 db tab 时若列表为空则自动加载
    if (activeTab === 'db' && dbItems.length === 0) handleDbSearch()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeTab])

  const scoreColor = (s: number) => s >= 80 ? 'text-[var(--color-success-text)]0 dark:text-[var(--color-success-text)]' : s >= 60 ? 'text-[var(--color-warning-text)]0 dark:text-[var(--color-warning-text)]' : 'text-danger-500 dark:text-danger-600'

  // Build radar data for risk dimensions
  const radarData = checkResult ? [
    { dimension: t('pages.compliance.compatibilityTaboo'), value: Math.max(0, 100 - (checkResult.violations ?? []).length * 25) },
    { dimension: t('pages.compliance.dosageCompliance'), value: Math.max(0, 100 - (checkResult.warnings ?? []).filter((w: any) => w.type === 'dosage').length * 20) },
    { dimension: t('pages.compliance.populationFit'), value: population === 'adults' ? 90 : population === 'children' ? 70 : 75 },
    { dimension: t('pages.compliance.foodHomology'), value: homologyList.length > 0 ? 85 : 60 },
    { dimension: t('pages.compliance.overallSafety'), value: checkResult.score ?? 50 },
  ] : []

  const selectClass = 'h-9 px-2 text-sm rounded-[var(--radius-Apple-sm)] border border-input bg-transparent text-[var(--text-primary)] shadow-sm focus:outline-none focus:ring-1 focus:ring-ring'

  return (
    <div className="min-h-screen">
      <div className="max-w-[1600px] mx-auto px-[var(--space-apple-md)] sm:px-6 lg:px-8 py-[var(--space-apple-lg)] space-y-[var(--space-apple-md)]">
        {/* 页头横幅 — 对齐 Dashboard 品牌横幅规范 */}
        <div className="surface-primary rounded-[var(--radius-Apple-md)] p-[var(--space-apple-lg)] shadow-sm">
          <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
            <div className="flex-1">
              <h1 className="text-xl font-semibold leading-snug tracking-tight flex items-center gap-2">
                <ShieldCheck size={20} className="text-white/80 shrink-0" />
                {t('pages.compliance.title')}
              </h1>
              <p className="mt-1 text-white/80 text-sm">{t('pages.compliance.subtitle')}</p>
            </div>
            {formulas.length > 0 && (
              <button onClick={() => setShowFormulas(!showFormulas)}
                className="flex items-center gap-1.5 px-[var(--space-apple-sm)] py-1.5 min-h-[44px] text-xs font-medium bg-[var(--bg-secondary)]/15 hover:bg-[var(--bg-secondary)]/25 rounded-[var(--radius-pill)] transition-colors">
                <History size={12} />{t('pages.compliance.formulaHistory', { count: formulas.length })}
              </button>
            )}
          </div>
        </div>

        {/* 配方历史 */}
        {showFormulas && formulas.length > 0 && (
          <Card>
            <CardContent className="p-[var(--space-apple-md)]">
              <div className="text-xs font-semibold text-[var(--text-muted)] mb-2 uppercase tracking-wide">{t('pages.compliance.savedFormulas')}</div>
              <div className="flex gap-2 flex-wrap">
                {formulas.map(f => (
                  <div key={f.id} className="flex items-center gap-2 px-[var(--space-apple-sm)] py-1.5 bg-[var(--bg-tertiary)]/60 rounded-[var(--radius-Apple-sm)] text-xs">
                    <span className="font-medium text-[var(--text-primary)]">{f.name}</span>
                    <span className={`font-bold ${f.score >= 80 ? 'text-[var(--color-success-text)]0 dark:text-[var(--color-success-text)]' : f.score >= 60 ? 'text-[var(--color-warning-text)]0 dark:text-[var(--color-warning-text)]' : 'text-danger-500 dark:text-danger-600'}`}>
                      {f.score}
                    </span>
                    <span className="text-[var(--text-muted)] truncate max-w-[150px]">{f.ingredients}</span>
                    <span className="text-[var(--text-muted)] dark:text-[var(--text-muted)]">{f.date}</span>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        )}

        {/* 标签页 — 对齐设计系统 Apple Segmented Control 规范 */}
        <div className="mt-[var(--space-apple-md)]">
          <div className="tabs-list w-fit">
            {[
              { key: 'check' as const, label: t('pages.compliance.tabCheck'), icon: Scale },
              { key: 'prohibited' as const, label: t('pages.compliance.tabProhibited'), icon: AlertTriangle },
              { key: 'limits' as const, label: t('pages.compliance.tabLimits'), icon: BookOpen },
              { key: 'db' as const, label: t('pages.compliance.tabDb'), icon: Search },
            ].map(tab => (
              <button key={tab.key} onClick={() => setActiveTab(tab.key)}
                className={'tabs-trigger ' + (activeTab === tab.key ? 'tabs-trigger-active' : '')}>
                <span className="icon"><tab.icon size={14} /></span>
                {tab.label}
              </button>
            ))}
          </div>
        </div>

        <div className="mt-6 space-y-6">
          {activeTab === 'check' && (
            <div className="space-y-[var(--space-apple-md)]">
              {/* 药材输入 */}
              <Card>
                <CardHeader className="px-5 pt-5 pb-3">
                  <div className="flex items-center justify-between">
                    <CardTitle as="h2" className="text-sm font-semibold flex items-center gap-2">
                      <Plus size={14} className="text-[var(--color-primary-text)]0 dark:text-[var(--color-primary-text)]" />
                      {t('pages.compliance.ingredients')}
                    </CardTitle>
                    <div className="flex items-center gap-2">
                      <select value={population} onChange={e => setPopulation(e.target.value)} className={selectClass}>
                        {POPULATION_OPTIONS.map(p => <option key={p.value} value={p.value}>{t(`pages.compliance.population.${p.value}`)}</option>)}
                      </select>
                      <Button variant="secondary" size="sm" onClick={addIngredient} icon={<Plus size={12} />} className="text-xs">{t('pages.compliance.addHerb')}</Button>
                    </div>
                  </div>
                </CardHeader>
                <CardContent className="px-5 pb-5 pt-0 space-y-2">
                  {ingredients.map((ing, i) => (
                    <div key={i} className="flex items-center gap-[var(--space-apple-sm)]">
                      <Input value={ing.name} onChange={e => updateIngredient(i, 'name', e.target.value)}
                        placeholder={t('pages.compliance.herbNamePlaceholder')} className="flex-1 h-9" />
                      <Input type="number" value={ing.dosage_mg} onChange={e => updateIngredient(i, 'dosage_mg', parseFloat(e.target.value) || 0)}
                        className="w-28 h-9 text-center tabular-nums" />
                      <span className="text-xs text-[var(--text-muted)] w-8">mg</span>
                      <Button variant="ghost" size="sm" onClick={() => removeIngredient(i)} disabled={ingredients.length <= 1}
                        icon={<Trash2 size={14} />}
                        className="text-[var(--text-muted)] hover:text-danger-500 dark:hover:text-danger-400" />
                    </div>
                  ))}
                </CardContent>
              </Card>

              {/* 操作按钮 */}
              <div className="flex gap-[var(--space-apple-sm)] flex-wrap">
                <Button onClick={handleCheck} disabled={loading}
                  icon={<RefreshCw size={14} className={loading ? 'animate-spin' : ''} />}>
                  {loading ? t('pages.compliance.checking') : t('pages.compliance.runCheck')}
                </Button>
                <Button variant="secondary" onClick={handleFix} disabled={loading || !checkResult}
                  icon={<ShieldCheck size={14} />}>{t('pages.compliance.autoFix')}</Button>
                <div className="flex items-center gap-2">
                  <Input value={formulaName} onChange={e => setFormulaName(e.target.value)}
                    placeholder={t('pages.compliance.formulaNamePlaceholder')} className="h-9 w-48" />
                  <Button variant="outline" onClick={handleSaveFormula} disabled={!checkResult} icon={<Save size={14} />}>{t('pages.compliance.saveFormula')}</Button>
                </div>
              </div>

              {/* 结果 */}
              {checkResult && (
                <div className="space-y-[var(--space-apple-md)]">
                  {/* 评分总览 */}
                  <div className={`rounded-[var(--radius-Apple-md)] p-5 border ${
                    checkResult.status === 'compliant' ? 'bg-[var(--color-success-container)] dark:bg-[var(--color-success-container)]/20 border-[var(--color-success-border)] dark:border-success-900' :
                    checkResult.status === 'warning' ? 'bg-[var(--color-warning-container)] dark:bg-[var(--color-warning-container)]/20 border-[var(--color-warning-border)] dark:border-warning-900' :
                    'bg-danger-50 dark:bg-danger-950/20 border-danger-200 dark:border-danger-900'
                  }`}>
                    <div className="flex items-center gap-6">
                      {checkResult.status === 'compliant' ? <CheckCircle2 className="text-[var(--color-success-text)]0 dark:text-[var(--color-success-text)]" size={32} /> : <AlertTriangle className="text-[var(--color-warning-text)]0 dark:text-[var(--color-warning-text)]" size={32} />}
                      <div>
                        <div className={`text-3xl font-bold ${scoreColor(checkResult.score ?? 0)}`}>{checkResult.score ?? '?'}</div>
                        <div className="text-sm text-[var(--text-muted)]">{t('pages.compliance.complianceScore', { status: checkResult.status === 'compliant' ? t('pages.compliance.statusCompliant') : checkResult.status === 'warning' ? t('pages.compliance.statusWarning') : t('pages.compliance.statusNonCompliant') })}</div>
                      </div>
                      <div className="ml-auto text-right">
                        {checkResult.violations?.length > 0 && <div className="text-danger-500 dark:text-danger-600 font-semibold">{t('pages.compliance.violationsCount', { count: checkResult.violations.length })}</div>}
                        {checkResult.warnings?.length > 0 && <div className="text-[var(--color-warning-text)]0 dark:text-[var(--color-warning-text)] font-semibold">{t('pages.compliance.warningsCount', { count: checkResult.warnings.length })}</div>}
                      </div>
                    </div>
                  </div>

                  {/* 风险雷达图 */}
                  <Card>
                    <CardHeader className="px-5 pt-5 pb-3">
                      <CardTitle as="h3" className="text-sm font-semibold flex items-center gap-2">
                        <Lightbulb size={14} className="text-[var(--color-warning-text)]0 dark:text-[var(--color-warning-text)]" />
                        {t('pages.compliance.riskRadar')}
                      </CardTitle>
                    </CardHeader>
                    <CardContent className="px-5 pb-5 pt-0 space-y-[var(--space-apple-md)]">
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div className="h-64">
                          <ResponsiveContainer width="100%" height="100%">
                            <RechartsRadarChart data={radarData}>
                              <PolarGrid stroke="var(--border-color)" />
                              <PolarAngleAxis dataKey="dimension" tick={{ fontSize: 12, fill: 'var(--text-muted)' }} />
                              <PolarRadiusAxis angle={30} domain={[0, 100]} tick={{ fontSize: 10, fill: 'var(--text-muted)' }} />
                              <RechartsTooltip
                                formatter={(value: number) => [`${value}${t('pages.compliance.riskScore')}`, t('pages.compliance.riskDimension')]}
                                contentStyle={{ backgroundColor: 'var(--card-bg-solid)', border: '1px solid var(--border-color)', borderRadius: '8px', padding: '12px' }}
                              />
                              <Radar name={t('pages.compliance.riskDimension')} dataKey="value" stroke="var(--color-warning)" fill="var(--color-warning)" fillOpacity={0.2} strokeWidth={2} />
                            </RechartsRadarChart>
                          </ResponsiveContainer>
                        </div>
                        <div className="space-y-2 self-center">
                          <div className="text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wide">{t('pages.compliance.riskDetails')}</div>
                          {radarData.map(d => (
                            <div key={d.dimension} className="flex items-center gap-[var(--space-apple-sm)]">
                              <span className="text-sm text-[var(--text-secondary)] w-20 shrink-0">{d.dimension}</span>
                              <div className="flex-1 h-2 bg-[var(--bg-tertiary)] rounded-[var(--radius-pill)] overflow-hidden">
                                <div className={`h-full rounded-[var(--radius-pill)] ${d.value >= 80 ? 'bg-[var(--color-success-container)]0' : d.value >= 60 ? 'bg-[var(--color-warning-container)]0' : 'bg-danger-500'}`}
                                  style={{ width: `${d.value}%` }} />
                              </div>
                              <span className="text-xs font-mono text-[var(--text-muted)] w-10 text-right">{d.value.toFixed(0)}</span>
                            </div>
                          ))}
                        </div>
                      </div>
                    </CardContent>
                  </Card>

                  {/* 违规项 */}
                  {checkResult.violations?.length > 0 && (
                    <Card className="border-danger-200 dark:border-danger-800/60">
                      <CardHeader className="px-5 pt-5 pb-3">
                        <CardTitle as="h3" className="text-sm font-semibold flex items-center gap-2">
                          <XCircle size={14} className="text-danger-500 dark:text-danger-600" />
                          {t('pages.compliance.violations', { count: checkResult.violations.length })}
                        </CardTitle>
                      </CardHeader>
                      <CardContent className="px-5 pb-5 pt-0 space-y-2">
                        {checkResult.violations.map((v: any, i: number) => (
                          <div key={i} className="flex items-start gap-[var(--space-apple-sm)] px-[var(--space-apple-sm)] py-2 bg-danger-50 dark:bg-danger-950/20 rounded-[var(--radius-Apple-sm)] border border-danger-200 dark:border-danger-900">
                            <XCircle size={14} className="text-danger-500 dark:text-danger-600 mt-0.5 shrink-0" />
                            <div className="flex-1">
                              <div className="text-sm text-[var(--text-primary)] font-medium">{v.description}</div>
                              <div className="text-xs text-[var(--text-muted)] mt-0.5">{v.rule_name} · {t('pages.compliance.severity', { value: (v.severity * 100).toFixed(0) })}</div>
                            </div>
                            <Badge variant="danger" size="sm">{v.type}</Badge>
                          </div>
                        ))}
                      </CardContent>
                    </Card>
                  )}

                  {/* 警告项 */}
                  {checkResult.warnings?.length > 0 && (
                    <Card className="border-[var(--color-warning-border)] dark:border-[var(--color-warning)]/60">
                      <CardHeader className="px-5 pt-5 pb-3">
                        <CardTitle as="h3" className="text-sm font-semibold flex items-center gap-2">
                          <AlertTriangle size={14} className="text-[var(--color-warning-text)]0 dark:text-[var(--color-warning-text)]" />
                          {t('pages.compliance.warnings', { count: checkResult.warnings.length })}
                        </CardTitle>
                      </CardHeader>
                      <CardContent className="px-5 pb-5 pt-0 space-y-2">
                        {checkResult.warnings.map((w: any, i: number) => (
                          <div key={i} className="flex items-start gap-[var(--space-apple-sm)] px-[var(--space-apple-sm)] py-2 bg-[var(--color-warning-container)] dark:bg-[var(--color-warning-container)]/20 rounded-[var(--radius-Apple-sm)] border border-[var(--color-warning-border)] dark:border-warning-900">
                            <AlertTriangle size={14} className="text-[var(--color-warning-text)]0 dark:text-[var(--color-warning-text)] mt-0.5 shrink-0" />
                            <div className="flex-1">
                              <div className="text-sm text-[var(--text-primary)]">{w.description}</div>
                              <div className="text-xs text-[var(--text-muted)] mt-0.5">{w.rule_name}</div>
                            </div>
                            <Badge variant="warning" size="sm">{w.type}</Badge>
                          </div>
                        ))}
                      </CardContent>
                    </Card>
                  )}

                  {/* 优化建议 */}
                  {checkResult.suggestions?.length > 0 && (
                    <Card className="border-[var(--color-secondary-border)] dark:border-[var(--color-secondary)]/60">
                      <CardHeader className="px-5 pt-5 pb-3">
                        <CardTitle as="h3" className="text-sm font-semibold flex items-center gap-2">
                          <Lightbulb size={14} className="text-[var(--color-secondary-text)]0 dark:text-[var(--color-secondary-text)]" />
                          {t('pages.compliance.suggestions')}
                        </CardTitle>
                      </CardHeader>
                      <CardContent className="px-5 pb-5 pt-0 space-y-2">
                        {checkResult.suggestions.map((s: any, i: number) => (
                          <div key={i} className="flex items-start gap-2 px-[var(--space-apple-sm)] py-2 bg-[var(--color-secondary-container)] dark:bg-[var(--color-secondary-container)]/20 rounded-[var(--radius-Apple-sm)] border border-[var(--color-secondary-border)] dark:border-secondary-900">
                            <span className="text-[var(--color-secondary-text)]0 dark:text-[var(--color-secondary-text)] mt-0.5">→</span>
                            <span className="text-sm text-[var(--text-primary)]">{s}</span>
                          </div>
                        ))}
                      </CardContent>
                    </Card>
                  )}
                </div>
              )}
            </div>
          )}

          {activeTab === 'prohibited' && (
            <Card>
              <CardHeader className="px-5 pt-5 pb-3">
                <CardTitle as="h2" className="text-sm font-semibold flex items-center gap-2">
                  <AlertTriangle size={14} className="text-danger-500 dark:text-danger-600" />
                  {t('pages.compliance.prohibitedTitle')}
                </CardTitle>
              </CardHeader>
              <CardContent className="px-5 pb-5 pt-0 space-y-2">
                {prohibitedList.length === 0 ? (
                  <p className="text-sm text-[var(--text-muted)] text-center py-8">{t('pages.compliance.loading')}</p>
                ) : (
                  <div className="space-y-2">
                    {prohibitedList.map((pair: any, i: number) => (
                      <div key={i} className="flex items-center gap-[var(--space-apple-sm)] px-[var(--space-apple-sm)] py-2 bg-danger-50 dark:bg-danger-950/20 rounded-[var(--radius-Apple-sm)] border border-danger-200 dark:border-danger-900">
                        <span className="text-xs font-mono text-danger-400 dark:text-danger-700 w-16 shrink-0">{pair.rule || '十八反'}</span>
                        <span className="text-sm text-[var(--text-primary)]">
                          <strong>{pair.herb1 || pair.pair?.[0]}</strong> ↔ <strong>{pair.herb2 || pair.pair?.[1]}</strong>
                        </span>
                      </div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          )}

          {activeTab === 'limits' && (
            <Card>
              <CardHeader className="px-5 pt-5 pb-3">
                <CardTitle as="h2" className="text-sm font-semibold flex items-center gap-2">
                  <BookOpen size={14} className="text-[var(--color-warning-text)]0 dark:text-[var(--color-warning-text)]" />
                  {t('pages.compliance.limitsTitle')}
                </CardTitle>
              </CardHeader>
              <CardContent className="px-5 pb-5 pt-0 space-y-[var(--space-apple-sm)]">
                <div className="overflow-x-auto">
                  <table className="data-table w-full text-xs">
                    <thead>
                      <tr className="border-b border-[var(--border-color)] text-[var(--text-muted)] uppercase">
                        <th className="pb-2 pr-3 text-left">{t('pages.compliance.thHerb')}</th>
                        <th className="pb-2 px-2 text-center">{t('pages.compliance.thMaxDosage')}</th>
                        <th className="pb-2 px-2 text-center">{t('pages.compliance.thStatus')}</th>
                        <th className="pb-2 pl-2 text-center">{t('pages.compliance.thApprovedDate')}</th>
                      </tr>
                    </thead>
                    <tbody>
                      {Object.entries(dosageLimits).map(([name, limit]) => (
                        <tr key={name} className="border-b border-[var(--border-color)] hover:bg-[var(--bg-tertiary)] dark:hover:bg-[var(--bg-tertiary)]/50">
                          <td className="py-2 pr-3 text-[var(--text-primary)] font-medium">{name}</td>
                          <td className="py-2 px-2 text-center font-mono text-[var(--color-warning-text)] dark:text-[var(--color-warning-text)]">{limit}mg</td>
                          <td className="py-2 px-2 text-center"><span className="text-[var(--color-success-text)]0 dark:text-[var(--color-success-text)]">{t('pages.compliance.allowed')}</span></td>
                          <td className="py-2 pl-2 text-[var(--text-muted)] text-center">2025版</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
                <div className="text-xs text-[var(--text-muted)] text-center">{t('pages.compliance.limitsCount', { count: Object.keys(dosageLimits).length })}</div>
              </CardContent>
            </Card>
          )}

          {activeTab === 'db' && (
            <Card>
              <CardHeader className="px-5 pt-5 pb-3">
                <CardTitle as="h2" className="text-sm font-semibold flex items-center gap-2">
                  <Search size={14} className="text-[var(--color-warning-text)]0 dark:text-[var(--color-warning-text)]" />
                  {t('pages.compliance.dbTitle')}
                </CardTitle>
              </CardHeader>
              <CardContent className="px-5 pb-5 pt-0 space-y-[var(--space-apple-md)]">
                <div className="flex gap-[var(--space-apple-sm)]">
                  <Input value={searchTerm} onChange={e => setSearchTerm(e.target.value)}
                    placeholder={t('pages.compliance.searchPlaceholder')} className="flex-1 h-9" />
                  <Button onClick={handleDbSearch} disabled={loading} icon={<Search size={14} />}>{t('pages.compliance.search')}</Button>
                </div>
                <div className="space-y-2 max-h-96 overflow-y-auto">
                  {dbItems.length === 0 ? (
                    <p className="text-sm text-[var(--text-muted)] text-center py-8">{loading ? t('pages.compliance.loading') : t('pages.compliance.noHerbsFound')}</p>
                  ) : dbItems.map((item: any, i: number) => (
                    <div key={i} className="flex items-center gap-4 px-[var(--space-apple-sm)] py-2.5 bg-[var(--bg-tertiary)]/60 rounded-[var(--radius-Apple-sm)] border border-[var(--border-color)]">
                      <span className="text-sm font-medium text-[var(--text-primary)]">{item.name}</span>
                      <span className="text-xs text-[var(--text-muted)]">{item.latin_name}</span>
                      <span className="text-xs text-[var(--text-muted)] ml-auto">{item.category}</span>
                      <span className="text-xs font-mono text-[var(--color-warning-text)] dark:text-[var(--color-warning-text)]">{t('pages.compliance.maxDosage', { value: item.max_dosage })}</span>
                    </div>
                  ))}
                </div>
                {dbTotal > 0 && <div className="text-xs text-[var(--text-muted)] text-right">{t('pages.compliance.recordsCount', { count: dbTotal })}</div>}
              </CardContent>
            </Card>
          )}
        </div>
      </div>
    </div>
  )
}

