/* eslint-disable @typescript-eslint/no-explicit-any */
/**
 * 肽链结构分析器 - 增强版
 * 功能：完整分析、结构转换、数据库查询、对比分析、历史记录、可视化图表
 */
import { useState, useCallback, useEffect, useRef } from 'react';
import { useSearchParams } from 'react-router-dom';
import { peptideStructureService } from '@/services/professional/peptideStructureService';
import { Button, Input, Card, Badge, Pagination } from '@/components/ui';
import { MoleculeViewer3D } from '@/components/molecule';
import {
  Beaker, ArrowRightLeft, Dna, ShieldCheck, Activity, FlaskConical,
  AlertCircle, CheckCircle, Database, GitCompare as Compare, History, BarChart3,
  Search, TrendingUp, Download, Trash2, Plus, X, Copy,
  Layers, Zap, Target, Bot, ZoomIn, Expand, Leaf,
} from 'lucide-react';

// 使用全局echarts对象（从CDN加载）
declare global {
  interface Window {
    echarts?: any;
  }
}

const ReactECharts = ({ option, style }: { option: any; style?: any }) => {
  const chartRef = useRef<HTMLDivElement>(null);
  const chartInstance = useRef<any>(null);
  const optionRef = useRef<any>(option);
  // eslint-disable-next-line react-hooks/refs
  optionRef.current = option;
  const [echartsReady, setEchartsReady] = useState(true);

  useEffect(() => {
    const echarts = window.echarts;
    if (!echarts) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setEchartsReady(false);
      return;
    }
    if (!chartRef.current) return;

    if (!chartInstance.current) {
      chartInstance.current = echarts.init(chartRef.current, null, { renderer: 'svg' });
    }

    chartInstance.current.setOption(optionRef.current, true);

    return () => {
      if (chartInstance.current) {
        chartInstance.current.dispose();
        chartInstance.current = null;
      }
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  if (!echartsReady) {
    return (
      <div style={style} className="w-full h-full flex items-center justify-center bg-[var(--bg-tertiary)] rounded-[var(--radius-Apple-sm)] border border-[var(--border-color)]">
        <span className="text-xs text-[var(--text-muted,#9A9A9F)]">图表加载失败，请检查网络连接</span>
      </div>
    );
  }

  return <div ref={chartRef} style={{ ...style, width: '100%' }} className="w-full h-full" />;
};

// ─── 类型定义 ───
interface PeptideAnalysisResult {
  sequence: string;
  smiles?: string;
  selfies?: string;
  molecular_weight: number;
  isoelectric_point: number;
  hydrophobicity: number;
  ace_inhibition: ActivityScore;
  antioxidant: ActivityScore;
  antimicrobial: ActivityScore;
  dpp4_inhibition?: ActivityScore;
  ml_model?: MLModelInfo;
  safety: SafetyInfo;
  taste: TasteInfo;
  source: SourceInfo;
  analysis_time: string;
}

interface MLModelInfo {
  name: string;
  ace_score: number | null;
  method: 'ml' | 'fallback_rule' | 'unavailable';
  library_size: number;
  training_samples: number;
  validation_samples: number;
  library_real_count: number;
  library_synth_count: number;
  library_pubmed_count?: number;
  include_pubmed?: boolean;
  train_real_count: number;
  train_synth_count: number;
  validation_accuracy: number | null;
  validation_f1: number | null;
  validation_balanced_accuracy: number | null;
  validation_majority_baseline: number | null;
  validation_precision: number | null;
  validation_recall: number | null;
  metrics_note?: string;
  is_trustworthy?: boolean;
  trust_note?: string;
  balanced_accuracy?: number | null;
  trained_on_real_only?: boolean;
  decision_threshold?: number;
  is_predicted_active?: boolean | null;
  // Step C-2 泛化测试：序列级 5 折防泄漏数字 + 长肽 LOO 警示
  gen_five_fold_f1?: number | null;
  gen_five_fold_balanced?: number | null;
  gen_loo_long_recall?: number | null;
  short_peptide_bias?: string;
  honest_note?: string;
}

interface ActivityScore {
  score: number;
  level: 'high' | 'medium' | 'low' | 'none';
}

interface SafetyInfo {
  food_score: number;
  is_allergen: boolean;
  is_toxic: boolean;
  digestibility: string;
  allergen_source?: string | null;
  allergen_evidence?: string | null;
  toxic_source?: string | null;
  toxic_evidence?: string | null;
  digestibility_reason?: string | null;
  peptic_resistance?: number;
  proteolytic_resistance?: number;
  overall_risk?: string;
  warnings?: string[];
}

interface TasteInfo {
  bitterness: number;
  umami: number;
}

interface SourceInfo {
  food?: string;
  database?: string;
  references: string[];
}

// 3D分子坐标类型
interface Atom3D {
  element: string;
  x: number;
  y: number;
  z: number;
  atomic_num: number;
}

interface Bond3D {
  start: number;
  end: number;
  type: string;
}

interface Molecule3DData {
  success: boolean;
  smiles: string;
  atom_count: number;
  bond_count: number;
  molecular_weight: number;
  atoms: Atom3D[];
  bonds: Bond3D[];
}

interface HistoryRecord {
  id: number;
  sequence: string;
  molecular_weight: number;
  food_safety_score: number;
  ace_inhibition_score: number;
  antioxidant_score: number;
  antimicrobial_score: number;
  is_allergen: boolean;
  is_toxic: boolean;
  digestibility: string;
  created_at: string;
}

interface DatabasePeptide {
  sequence: string;
  source_protein?: string;
  activity_type?: string;
  activity_value?: number;
  activity_unit?: string;
  molecular_weight?: number;
  food_source?: string;
  source_database: string;
  is_synthetic?: boolean;
  provenance?: string;
}

type TabType = 'analyze' | 'convert' | 'database' | 'compare' | 'history' | 'batch' | 'deep' | 'optimize' | 'synergy' | 'advanced';

// ─── 工具函数 ───
function getScoreColor(score: number): string {
  if (score >= 0.8) return 'text-[var(--color-success-text)] dark:text-[var(--color-success-text)]';
  if (score >= 0.5) return 'text-[var(--color-warning-text)] dark:text-[var(--color-warning-text)]';
  return 'text-[var(--color-error-text)] dark:text-[var(--color-error-text)]';
}

function getActivityBadge(level: string): 'success' | 'warning' | 'danger' | 'neutral' {
  switch (level) {
    case 'high': return 'success';
    case 'medium': return 'warning';
    case 'low': return 'danger';
    default: return 'neutral';
  }
}

// ─── 评分进度条组件 ───
function ScoreProgress({ label, score }: { label: string; score: number }) {
  return (
    <div className="space-y-1">
      <div className="flex justify-between text-xs">
        <span className="text-[var(--text-secondary,#6B7280)] dark:text-[var(--text-secondary-dark,#9CA3AF)]">{label}</span>
        <span className={`font-medium ${getScoreColor(score)}`}>{(score * 100).toFixed(1)}%</span>
      </div>
      <div className="w-full bg-[var(--border-color)] dark:bg-[var(--bg-secondary)] rounded-[var(--radius-pill)] h-2">
        <div
          className="h-2 rounded-[var(--radius-pill)] transition-all duration-500"
          style={{
            width: `${score * 100}%`,
            backgroundColor: score >= 0.8 ? 'var(--color-primary-500)' : score >= 0.5 ? '#eab308' : '#ef4444',
          }}
        />
      </div>
    </div>
  );
}

// ─── 雷达图配置 ───
function RadarChart({ data }: { data: PeptideAnalysisResult }) {
  const option = {
    title: {
      text: '活性谱雷达图',
      left: 'center',
      top: 5,
      textStyle: { fontSize: 12, fontWeight: 'normal', color: 'var(--text-secondary,#6B7280)' }
    },
    radar: {
      indicator: [
        { name: 'ACE抑制', max: 1 },
        { name: '抗氧化', max: 1 },
        { name: '抗菌', max: 1 },
        { name: '食品安全', max: 1 },
      ],
      shape: 'polygon',
      splitNumber: 4,
      axisName: { color: 'var(--text-secondary,#6B7280)', fontSize: 12 },
      splitLine: { lineStyle: { color: 'rgba(128,128,128,0.2)' } },
      splitArea: { show: false },
      axisLine: { lineStyle: { color: 'rgba(128,128,128,0.3)' } },
    },
    series: [{
      type: 'radar',
      data: [{
        value: [
          data.ace_inhibition.score,
          data.antioxidant.score,
          data.antimicrobial.score,
          data.safety.food_score / 100,
        ],
        name: '活性谱',
        areaStyle: { color: 'rgba(59,130,246,0.2)' },
        lineStyle: { color: '#3b82f6', width: 2 },
        itemStyle: { color: '#3b82f6' },
      }],
    }],
    tooltip: { trigger: 'item' },
    legend: { show: false },
  };
  return <ReactECharts option={option} style={{ height: 240 }} />;
}

// ─── 柱状图配置 ───
function BarChart({ data }: { data: PeptideAnalysisResult }) {
  const option = {
    title: {
      text: '活性得分柱状图',
      left: 'center',
      top: 5,
      textStyle: { fontSize: 12, fontWeight: 'normal', color: 'var(--text-secondary,#6B7280)' }
    },
    grid: { left: '3%', right: '4%', bottom: '15%', top: '25%', containLabel: true },
    xAxis: {
      type: 'category',
      data: ['ACE抑制', '抗氧化', '抗菌', '食品安全'],
      axisLabel: { color: 'var(--text-secondary,#6B7280)', fontSize: 12 },
      axisLine: { lineStyle: { color: 'rgba(128,128,128,0.3)' } },
    },
    yAxis: {
      type: 'value',
      max: 1,
      axisLabel: {
        formatter: (value: number) => `${(value * 100).toFixed(0)}%`,
        color: 'var(--text-secondary,#6B7280)'
      },
      splitLine: { lineStyle: { color: 'rgba(128,128,128,0.1)', type: 'dashed' } },
      axisLine: { lineStyle: { color: 'rgba(128,128,128,0.3)' } },
    },
    series: [{
      data: [
        {
          value: data.ace_inhibition.score,
          itemStyle: { color: '#3b82f6', borderRadius: [4, 4, 0, 0] }
        },
        {
          value: data.antioxidant.score,
          itemStyle: { color: 'var(--color-primary-500)', borderRadius: [4, 4, 0, 0] }
        },
        {
          value: data.antimicrobial.score,
          itemStyle: { color: '#f59e0b', borderRadius: [4, 4, 0, 0] }
        },
        {
          value: data.safety.food_score / 100,
          itemStyle: { color: '#8b5cf6', borderRadius: [4, 4, 0, 0] }
        },
      ],
      type: 'bar',
      barWidth: '50%',
      label: {
        show: true,
        position: 'top',
        formatter: (params: any) => `${(params.value * 100).toFixed(0)}%`,
        fontSize: 10,
        color: 'var(--text-secondary,#6B7280)'
      },
    }],
    tooltip: {
      trigger: 'axis',
      axisPointer: { type: 'shadow' },
      formatter: (params: any) => {
        const p = params[0];
        return `${p.name}<br/>得分: <b>${(p.value * 100).toFixed(1)}%</b>`;
      },
    },
  };
  return <ReactECharts option={option} style={{ height: 240 }} />;
}

// ─── 活性热力图（多肽 × 多目标矩阵）───
function ActivityHeatmap({ results }: { results: PeptideAnalysisResult[] }) {
  const objectives = ['ACE抑制', '抗氧化', '抗菌', '食品安全'];
  const points: Array<[number, number, number, string]> = [];
  results.forEach((r, row) => {
    const vals = [
      r.ace_inhibition.score,
      r.antioxidant.score,
      r.antimicrobial.score,
      r.safety.food_score / 100,
    ];
    vals.forEach((v, col) => {
      points.push([col, row, v, r.sequence]);
    });
  });
  const option = {
    title: {
      text: '多肽 × 目标 活性热力图',
      left: 'center',
      top: 5,
      textStyle: { fontSize: 12, fontWeight: 'normal', color: 'var(--text-secondary,#6B7280)' },
    },
    tooltip: {
      position: 'top',
      formatter: (p: any) => `${p.data[3]}<br/>${objectives[p.data[0]]}: <b>${(p.data[2] * 100).toFixed(1)}%</b>`,
    },
    grid: { left: '8%', right: '10%', top: '18%', bottom: '15%', containLabel: true },
    xAxis: {
      type: 'category',
      data: objectives,
      splitArea: { show: true },
      axisLabel: { color: 'var(--text-secondary,#6B7280)', fontSize: 11 },
    },
    yAxis: {
      type: 'category',
      data: results.map(r => r.sequence),
      splitArea: { show: true },
      axisLabel: { color: 'var(--text-secondary,#6B7280)', fontSize: 11, fontFamily: 'monospace' },
    },
    visualMap: {
      min: 0,
      max: 1,
      calculable: false,
      orient: 'vertical',
      right: 0,
      top: 'center',
      inRange: { color: ['#f1f5f9', '#bfdbfe', '#3b82f6', '#1d4ed8'] },
      textStyle: { color: 'var(--text-secondary,#6B7280)', fontSize: 10 },
      text: ['高', '低'],
    },
    series: [{
      type: 'heatmap',
      data: points,
      label: {
        show: true,
        formatter: (p: any) => `${(p.data[2] * 100).toFixed(0)}%`,
        fontSize: 10,
        color: '#111827',
      },
      itemStyle: { borderColor: '#fff', borderWidth: 1 },
      emphasis: { itemStyle: { shadowBlur: 8, shadowColor: 'rgba(0,0,0,0.3)' } },
    }],
  };
  return <ReactECharts option={option} style={{ height: Math.max(240, results.length * 36 + 80) }} />;
}

// ─── Pareto 前沿二维散点图 ──
function ParetoScatter({ points }: {
  points: Array<{ sequence: string; objectives: Record<string, number>; rank: number }>;
}) {
  // 取前两个目标作为 X/Y 轴
  const data = points.map(p => {
    const keys = Object.keys(p.objectives);
    return [
      p.objectives[keys[0]] ?? 0,
      p.objectives[keys[1]] ?? 0,
      p.sequence,
      p.rank,
    ];
  });
  const k0 = Object.keys(points[0]?.objectives ?? {});
  const option = {
    title: {
      text: 'Pareto 前沿（前 2 目标）',
      left: 'center',
      top: 5,
      textStyle: { fontSize: 12, fontWeight: 'normal', color: 'var(--text-secondary,#6B7280)' },
    },
    tooltip: {
      formatter: (p: any) => `${p.data[2]}<br/>${k0[0]}: ${(p.data[0] * 100).toFixed(1)}%<br/>${k0[1] ?? '目标2'}: ${(p.data[1] * 100).toFixed(1)}%<br/>rank: ${p.data[3]}`,
    },
    grid: { left: '6%', right: '6%', bottom: '18%', top: '20%', containLabel: true },
    xAxis: {
      name: k0[0] ?? '目标1',
      type: 'value',
      min: 0,
      max: 1,
      nameTextStyle: { color: 'var(--text-secondary,#6B7280)', fontSize: 11 },
      axisLabel: { formatter: (v: number) => `${(v * 100).toFixed(0)}%`, color: 'var(--text-secondary,#6B7280)', fontSize: 10 },
      splitLine: { lineStyle: { color: 'rgba(128,128,128,0.1)', type: 'dashed' } },
    },
    yAxis: {
      name: k0[1] ?? '目标2',
      type: 'value',
      min: 0,
      max: 1,
      nameTextStyle: { color: 'var(--text-secondary,#6B7280)', fontSize: 11 },
      axisLabel: { formatter: (v: number) => `${(v * 100).toFixed(0)}%`, color: 'var(--text-secondary,#6B7280)', fontSize: 10 },
      splitLine: { lineStyle: { color: 'rgba(128,128,128,0.1)', type: 'dashed' } },
    },
    series: [{
      type: 'scatter',
      data,
      symbolSize: (val: any) => (val[3] === 0 ? 18 : 12),
      itemStyle: {
        color: (p: any) => (p.data[3] === 0 ? '#16a34a' : '#3b82f6'),
        opacity: 0.85,
      },
      label: {
        show: true,
        formatter: (p: any) => p.data[2],
        position: 'top',
        fontSize: 9,
        color: 'var(--text-secondary,#6B7280)',
      },
    }],
  };
  return <ReactECharts option={option} style={{ height: 280 }} />;
}

// ─── 对比分析组件 ───
function ComparisonView({ sequences }: { sequences: string[] }) {
  const [results, setResults] = useState<PeptideAnalysisResult[]>([]);
  const [loading, setLoading] = useState(false);

  const handleCompare = useCallback(async () => {
    if (sequences.length < 2) return;
    setLoading(true);
    try {
      const comparisons = await Promise.all(
        sequences.map(seq => peptideStructureService.analyzePeptide(seq))
      );
      setResults(comparisons);
    } catch (e) {
      console.error('对比分析失败:', e);
    } finally {
      setLoading(false);
    }
  }, [sequences]);

  if (sequences.length < 2) {
    return (
      <div className="text-center py-8 text-[var(--text-muted,#9A9A9F)]">
        <Compare className="w-10 h-10 mx-auto mb-2 opacity-30" />
        <p className="text-sm">请至少输入2条序列进行对比分析</p>
      </div>
    );
  }

  return (
    <div className="space-y-[var(--space-apple-md)]">
      <div className="flex gap-2">
        <Button onClick={handleCompare} disabled={loading} className="flex-1">
          {loading ? '分析中...' : '开始对比'}
        </Button>
      </div>

      {results.length > 0 && (
        <div className="space-y-[var(--space-apple-md)]">
          {/* 活性热力图 */}
          <Card className="p-[var(--space-apple-md)]">
            <h3 className="text-sm font-medium mb-2 flex items-center gap-2">
              <BarChart3 className="w-4 h-4 text-primary" />
              活性热力图
            </h3>
            <ActivityHeatmap results={results} />
          </Card>
          {/* 对比表格 */}
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-[var(--border-color)]">
                  <th className="px-[var(--space-apple-sm)] py-2 text-left text-xs font-medium text-[var(--text-muted,#9A9A9F)]">序列</th>
                  <th className="px-[var(--space-apple-sm)] py-2 text-right text-xs font-medium text-[var(--text-muted,#9A9A9F)]">分子量</th>
                  <th className="px-[var(--space-apple-sm)] py-2 text-right text-xs font-medium text-[var(--text-muted,#9A9A9F)]">食品评分</th>
                  <th className="px-[var(--space-apple-sm)] py-2 text-right text-xs font-medium text-[var(--text-muted,#9A9A9F)]">ACE抑制</th>
                  <th className="px-[var(--space-apple-sm)] py-2 text-right text-xs font-medium text-[var(--text-muted,#9A9A9F)]">抗氧化</th>
                  <th className="px-[var(--space-apple-sm)] py-2 text-right text-xs font-medium text-[var(--text-muted,#9A9A9F)]">抗菌</th>
                  <th className="px-[var(--space-apple-sm)] py-2 text-center text-xs font-medium text-[var(--text-muted,#9A9A9F)]">过敏</th>
                  <th className="px-[var(--space-apple-sm)] py-2 text-center text-xs font-medium text-[var(--text-muted,#9A9A9F)]">毒性</th>
                </tr>
              </thead>
              <tbody>
                {results.map((r, i) => (
                  <tr key={i} className="border-b border-[var(--border-color)]">
                    <td className="px-[var(--space-apple-sm)] py-2 font-mono font-medium">{r.sequence}</td>
                    <td className="px-[var(--space-apple-sm)] py-2 text-right">{r.molecular_weight.toFixed(1)}</td>
                    <td className="px-[var(--space-apple-sm)] py-2 text-right">
                      <span className={`font-bold ${getScoreColor(r.safety.food_score / 100)}`}>
                        {r.safety.food_score.toFixed(0)}
                      </span>
                    </td>
                    <td className="px-[var(--space-apple-sm)] py-2 text-right">{(r.ace_inhibition.score * 100).toFixed(1)}%</td>
                    <td className="px-[var(--space-apple-sm)] py-2 text-right">{(r.antioxidant.score * 100).toFixed(1)}%</td>
                    <td className="px-[var(--space-apple-sm)] py-2 text-right">{(r.antimicrobial.score * 100).toFixed(1)}%</td>
                    <td className="px-[var(--space-apple-sm)] py-2 text-center">
                      {r.safety.is_allergen ? (
                        <span className="text-[var(--color-error-text)]0">是</span>
                      ) : (
                        <span className="text-[var(--color-success-text)]0">否</span>
                      )}
                    </td>
                    <td className="px-[var(--space-apple-sm)] py-2 text-center">
                      {r.safety.is_toxic ? (
                        <span className="text-[var(--color-error-text)]0">是</span>
                      ) : (
                        <span className="text-[var(--color-success-text)]0">否</span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* 综合评分对比图 */}
          <div className="pt-[var(--space-apple-md)]">
            <h4 className="text-sm font-medium mb-[var(--space-apple-sm)]">活性对比</h4>
            <ReactECharts
              option={{
                radar: {
                  indicator: [
                    { name: 'ACE抑制', max: 1 },
                    { name: '抗氧化', max: 1 },
                    { name: '抗菌', max: 1 },
                    { name: '食品安全', max: 1 },
                  ],
                  shape: 'polygon',
                  splitNumber: 4,
                },
                series: [{
                  type: 'radar',
                  data: results.map((r, i) => ({
                    value: [
                      r.ace_inhibition.score,
                      r.antioxidant.score,
                      r.antimicrobial.score,
                      r.safety.food_score / 100,
                    ],
                    name: r.sequence,
                    lineStyle: { color: ['#3b82f6', 'var(--color-primary-500)', '#f59e0b', '#ef4444'][i % 4] },
                    areaStyle: { color: (['rgba(59,130,246,0.1)', 'rgba(34,197,94,0.1)', 'rgba(245,158,11,0.1)', 'rgba(239,68,68,0.1)'][i % 4]) },
                  })),
                }],
                legend: { bottom: 0, textStyle: { fontSize: 10 } },
              }}
              style={{ height: 280 }}
            />
          </div>
        </div>
      )}
    </div>
  );
}

// ─── 数据库查询组件 ───
function DatabaseView({ onAnalyzeSequence, initialQuery }: { onAnalyzeSequence?: (seq: string) => void; initialQuery?: string }) {
  const [query, setQuery] = useState(initialQuery || '');
  const [results, setResults] = useState<DatabasePeptide[]>([]);
  const [loading, setLoading] = useState(false);
  const [stats, setStats] = useState<any>(null);
  const [, setShowAll] = useState(false);
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState<number>(0); // 保存搜索结果总数
  // 外部数据源检索状态
  const [useOnline, setUseOnline] = useState(false);
  const [extLoading, setExtLoading] = useState(false);
  const [extResults, setExtResults] = useState<DatabasePeptide[]>([]);
  const [extMeta, setExtMeta] = useState<{ seq: string; dbs: string[] } | null>(null);
  const PAGE_SIZE = 20;

  const doSearch = useCallback(async (q: string, p: number = 1) => {
setLoading(true);
    try {
      const res = await peptideStructureService.searchDatabase({ sequence: q || undefined, page: p, page_size: PAGE_SIZE });

      setResults(res.peptides);
      setTotal(res.total || 0);
      setShowAll(q === '');
    } catch (e) {
      console.error('数据库搜索失败:', e);
    } finally {
      setLoading(false);
    }
  }, []);

  // 外部数据源检索（DFBP 本地 7540 条 + BioPeptideDB 在线可选）
  const doExternalSearch = useCallback(async (seq: string) => {
    if (!seq.trim()) return;
    setExtLoading(true); setExtResults([]); setExtMeta(null);
    try {
      const res = await peptideStructureService.externalSourceLookup(seq.trim().toUpperCase(), useOnline);
      const mapped: DatabasePeptide[] = (res.records || []).map(r => ({
        sequence: r.sequence,
        source_protein: r.source_protein ?? undefined,
        activity_type: r.activity_type ?? undefined,
        activity_value: r.activity_value ?? undefined,
        activity_unit: r.activity_unit ?? undefined,
        molecular_weight: r.molecular_weight ?? undefined,
        food_source: r.food_source ?? undefined,
        source_database: r.source_database,
      }));
      setExtResults(mapped);
      setExtMeta({ seq: seq.trim().toUpperCase(), dbs: res.databases_queried || [] });
    } catch (e: any) {
      console.error('外部检索失败:', e);
      setExtResults([]);
      setExtMeta({ seq: seq.trim().toUpperCase(), dbs: [] });
    } finally {
      setExtLoading(false);
    }
  }, [useOnline]);

  const handleLoadStats = useCallback(async () => {
    try {
      const res = await peptideStructureService.getDatabaseStatistics();
      // service 已返回 statistics 对象，直接使用
      setStats(res);
    } catch (e) {
      console.error('获取统计失败:', e);
    }
  }, []);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    handleLoadStats();
    // 有预填序列（来自分析 Tab 反向跳转）则按序列搜索，否则显示前20条
    doSearch(initialQuery || '', 1);
  }, [initialQuery]);

  const handleSearch = useCallback(() => {

    setPage(1);
    doSearch(query, 1);
  }, [query, doSearch]);

  return (
    <div className="space-y-[var(--space-apple-md)]">
      {/* 搜索框 */}
      <div className="flex gap-2">
        <Input
          value={query}
          onChange={(e) => setQuery(e.target.value.toUpperCase())}
          placeholder="输入序列搜索数据库..."
          className="flex-1 font-mono"
          onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
        />
        <Button onClick={() => {  handleSearch(); }} disabled={loading || !query}>
          <Search className="w-4 h-4 mr-1" />
          搜索
        </Button>

        <Button variant="outline" onClick={() => doSearch('', 1)} disabled={loading}>
          显示全部
        </Button>

        <Button
          variant="ghost"
          className="border border-[var(--color-primary-border)] dark:border-[var(--color-primary)] text-[var(--color-primary-text)] dark:text-[var(--color-primary-text)]"
          onClick={() => doExternalSearch(query)}
          disabled={extLoading || !query}
        >
          {extLoading ? <><span className="animate-spin w-3 h-3 border-2 border-current border-t-transparent rounded-[var(--radius-pill)] inline-block mr-1"/>检索中...</> : <><Database className="w-4 h-4 mr-1" />外部检索</>}
        </Button>
        <label className="flex items-center gap-1.5 text-xs text-[var(--text-muted,#9A9A9F)] cursor-pointer select-none">
          <input type="checkbox" checked={useOnline} onChange={e => setUseOnline(e.target.checked)} className="accent-[var(--color-primary)]" />
          BioPeptideDB 在线
        </label>
      </div>

      {/* 外部检索结果（并入表格，标注来源库） */}
      {extMeta && (
        <div className="space-y-2">
          <div className="flex items-center justify-between p-2.5 bg-[var(--color-primary-container)] dark:bg-[var(--color-primary-container)]/20 border border-[var(--color-primary-border)] dark:border-[var(--color-primary)] rounded-[var(--radius-Apple-sm)] text-xs">
            <span className="text-[var(--color-primary-text)] dark:text-[var(--color-primary-text)] flex items-center gap-1.5">
              <Database className="w-3.5 h-3.5" />
              外部数据源：{extMeta.dbs.length > 0 ? extMeta.dbs.join(' + ') : '未配置在线源（仅查 DFBP 本地库）'}，命中 {extResults.length} 条
            </span>
            <button onClick={() => { setExtResults([]); setExtMeta(null); }} className="text-[var(--text-muted,#9A9A9F)] hover:text-[var(--text-primary)]">清除</button>
          </div>
          {extResults.length > 0 ? (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-[var(--border-color)]">
                    {['序列', '来源库', '来源蛋白', '活性类型', '活性值', '食物来源', '操作'].map((h, i) => (
                      <th key={i} className={i < 6 ? 'px-[var(--space-apple-sm)] py-2 text-left text-xs font-medium text-[var(--text-muted,#9A9A9F)]' : 'px-[var(--space-apple-sm)] py-2 text-center text-xs font-medium text-[var(--text-muted,#9A9A9F)]'}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {extResults.map((p, i) => (
                    <tr key={i} className="border-b border-[var(--border-color)]">
                      <td className="px-[var(--space-apple-sm)] py-2 font-mono font-medium">{p.sequence}</td>
                      <td className="px-[var(--space-apple-sm)] py-2"><Badge variant="outline" size="sm">{p.source_database}</Badge></td>
                      <td className="px-[var(--space-apple-sm)] py-2 text-xs">{p.source_protein || '-'}</td>
                      <td className="px-[var(--space-apple-sm)] py-2 text-xs">{p.activity_type || '-'}</td>
                      <td className="px-[var(--space-apple-sm)] py-2 text-xs">{p.activity_value != null ? `${p.activity_value} ${p.activity_unit || ''}` : '-'}</td>
                      <td className="px-[var(--space-apple-sm)] py-2 text-xs">{p.food_source || '-'}</td>
                      <td className="px-[var(--space-apple-sm)] py-2 text-center">
                        {onAnalyzeSequence && (
                          <Button size="sm" variant="ghost" className="h-7 text-xs text-primary" onClick={() => onAnalyzeSequence(p.sequence)}>
                            <Beaker className="w-3.5 h-3.5 mr-1" />分析
                          </Button>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            !extLoading && (
              <div className="text-center py-4 text-xs text-[var(--text-muted,#9A9A9F)]">
                该序列未在外部数据源中命中（可能为合成序列或库中未收录）
              </div>
            )
          )}
        </div>
      )}

      {/* 统计信息 */}
      {stats && (
        <div className="grid grid-cols-3 gap-[var(--space-apple-sm)]">
          <div className="p-[var(--space-apple-sm)] bg-[var(--bg-tertiary)]/50 rounded-[var(--radius-Apple-sm)] text-center">
            <div className="text-2xl font-bold text-primary">{stats.total_peptides}</div>
            <div className="text-xs text-[var(--text-muted,#9A9A9F)]">总肽数</div>
          </div>
          <div className="p-[var(--space-apple-sm)] bg-[var(--bg-tertiary)]/50 rounded-[var(--radius-Apple-sm)] text-center">
            <div className="text-2xl font-bold text-primary">{Object.keys(stats.activities).length}</div>
            <div className="text-xs text-[var(--text-muted,#9A9A9F)]">活性类型</div>
          </div>
          <div className="p-[var(--space-apple-sm)] bg-[var(--bg-tertiary)]/50 rounded-[var(--radius-Apple-sm)] text-center">
            <div className="text-2xl font-bold text-primary">{Object.keys(stats.food_sources).length}</div>
            <div className="text-xs text-[var(--text-muted,#9A9A9F)]">食物来源</div>
          </div>
        </div>
      )}

      {/* 搜索结果 */}
      {loading && <div className="text-center py-8 text-[var(--text-muted)]">加载中...</div>}
      {!loading && results.length > 0 && (
        <>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-[var(--border-color)]">
                  <th className="px-[var(--space-apple-sm)] py-2 text-left text-xs font-medium text-[var(--text-muted,#9A9A9F)]">序列</th>
                  <th className="px-[var(--space-apple-sm)] py-2 text-left text-xs font-medium text-[var(--text-muted,#9A9A9F)]">来源蛋白</th>
                  <th className="px-[var(--space-apple-sm)] py-2 text-left text-xs font-medium text-[var(--text-muted,#9A9A9F)]">活性类型</th>
                  <th className="px-[var(--space-apple-sm)] py-2 text-right text-xs font-medium text-[var(--text-muted,#9A9A9F)]">活性值</th>
                  <th className="px-[var(--space-apple-sm)] py-2 text-left text-xs font-medium text-[var(--text-muted,#9A9A9F)]">食物来源</th>
                  <th className="px-[var(--space-apple-sm)] py-2 text-left text-xs font-medium text-[var(--text-muted,#9A9A9F)]">数据来源</th>
                  <th className="px-[var(--space-apple-sm)] py-2 text-center text-xs font-medium text-[var(--text-muted,#9A9A9F)]">操作</th>
                </tr>
              </thead>
              <tbody>
                {results.map((p, i) => (
                  <tr key={i} className="border-b border-[var(--border-color)]">
                    <td className="px-[var(--space-apple-sm)] py-2 font-mono font-medium">{p.sequence}</td>
                    <td className="px-[var(--space-apple-sm)] py-2 text-xs">{p.source_protein || '-'}</td>
                    <td className="px-[var(--space-apple-sm)] py-2 text-xs">{p.activity_type || '-'}</td>
                    <td className="px-[var(--space-apple-sm)] py-2 text-right text-xs">
                      {p.activity_value ? `${p.activity_value} ${p.activity_unit}` : '-'}
                    </td>
                    <td className="px-[var(--space-apple-sm)] py-2 text-xs">{p.food_source || '-'}</td>
                    <td className="px-[var(--space-apple-sm)] py-2">
                      {p.is_synthetic ? (
                        <Badge variant="warning" size="sm" title="程序合成（generate_peptides random 生成），非真实 DFBP 文献">合成</Badge>
                      ) : (
                        <Badge variant="success" size="sm" title={p.provenance === 'hand_expanded' ? '基于文献的手写扩展' : '核心真实 DFBP 文献记录'}>
                          {p.provenance === 'hand_expanded' ? '扩展' : '真实'}
                        </Badge>
                      )}
                    </td>
                    <td className="px-[var(--space-apple-sm)] py-2 text-center">
                      {onAnalyzeSequence && (
                        <Button
                          size="sm"
                          variant="ghost"
                          className="h-7 text-xs text-primary hover:bg-[var(--color-primary-container)] dark:hover:bg-[var(--color-primary-container)]/20"
                          onClick={() => onAnalyzeSequence(p.sequence)}
                        >
                          <Beaker className="w-3.5 h-3.5 mr-1" />分析
                        </Button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <Pagination
            currentPage={page}
            totalPages={Math.ceil(total / PAGE_SIZE)}
            onPageChange={(p) => { setPage(p); doSearch(query, p); }}
            total={total || stats?.total_peptides || 0}
          />
        </>
      )}

      {!loading && results.length === 0 && query && (
        <div className="text-center py-8 text-[var(--text-muted,#9A9A9F)]">
          <Database className="w-10 h-10 mx-auto mb-2 opacity-30" />
          <p className="text-sm">未找到匹配记录</p>
        </div>
      )}
    </div>
  );
}

// ─── 历史记录组件 ───
function HistoryView() {
  const [records, setRecords] = useState<HistoryRecord[]>([]);
  const [stats, setStats] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const [page] = useState(1);

  const loadHistory = useCallback(async () => {
    setLoading(true);
    try {
      const [histRes, statsRes] = await Promise.all([
        peptideStructureService.getHistory({ page, page_size: 20 }),
        peptideStructureService.getHistoryStatistics(),
      ]);
      setRecords(histRes.items);
      setStats(statsRes);
    } catch (e) {
      console.error('加载历史失败:', e);
    } finally {
      setLoading(false);
    }
  }, [page]);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    loadHistory();
  }, [loadHistory]);

  const handleDelete = useCallback(async (id: number) => {
    try {
      await peptideStructureService.deleteHistory(id);
      setRecords(prev => prev.filter(r => r.id !== id));
    } catch (e) {
      console.error('删除失败:', e);
    }
  }, []);

  return (
    <div className="space-y-[var(--space-apple-md)]">
      {/* 统计概览 */}
      {stats && (
        <div className="grid grid-cols-4 gap-[var(--space-apple-sm)]">
          <div className="p-[var(--space-apple-sm)] bg-[var(--bg-tertiary)]/50 rounded-[var(--radius-Apple-sm)] text-center">
            <div className="text-xl font-bold text-primary">{stats.total_analyses}</div>
            <div className="text-xs text-[var(--text-muted,#9A9A9F)]">总分析数</div>
          </div>
          <div className="p-[var(--space-apple-sm)] bg-[var(--bg-tertiary)]/50 rounded-[var(--radius-Apple-sm)] text-center">
            <div className="text-xl font-bold text-primary">{stats.avg_food_score.toFixed(1)}</div>
            <div className="text-xs text-[var(--text-muted,#9A9A9F)]">平均评分</div>
          </div>
          <div className="p-[var(--space-apple-sm)] bg-[var(--bg-tertiary)]/50 rounded-[var(--radius-Apple-sm)] text-center">
            <div className={`text-xl font-bold ${stats.allergen_count > 0 ? 'text-[var(--color-error-text)]0' : 'text-[var(--color-success-text)]0'}`}>
              {stats.allergen_count}
            </div>
            <div className="text-xs text-[var(--text-muted,#9A9A9F)]">过敏原</div>
          </div>
          <div className="p-[var(--space-apple-sm)] bg-[var(--bg-tertiary)]/50 rounded-[var(--radius-Apple-sm)] text-center">
            <div className={`text-xl font-bold ${stats.toxic_count > 0 ? 'text-[var(--color-error-text)]0' : 'text-[var(--color-success-text)]0'}`}>
              {stats.toxic_count}
            </div>
            <div className="text-xs text-[var(--text-muted,#9A9A9F)]">毒性</div>
          </div>
        </div>
      )}

      {/* 评分分布图 */}
      {stats?.score_distribution && stats.score_distribution.length > 0 && (
        <div>
          <h4 className="text-sm font-medium mb-2">评分分布</h4>
          <ReactECharts
            option={{
              xAxis: {
                type: 'category',
