        <div>
          <label className="text-xs text-[var(--text-secondary)] block mb-1">药材（逗号分隔，留空使用默认）</label>
          <Input value={herbInput} onChange={e => setHerbInput(e.target.value)} placeholder="黄芪,人参,枸杞子" />
