      {/* 批量分析 */}
      {activeTab === 'batch' && <BatchAnalysisView />}

      {/* Pareto 优化 */}
      {activeTab === 'optimize' && <OptimizeView />}

      {/* 协同分析 */}
      {activeTab === 'synergy' && <SynergyView />}

      {/* 结构转换 */}
      {activeTab === 'convert' && (
        <div className="space-y-[var(--space-apple-md)]">
          <Card className="p-[var(--space-apple-md)] space-y-[var(--space-apple-md)]">
