/**
 * 搜索分析仪表盘
 *
 * 用于 Potion AI VFT x RMFOOD 深度融合方案。
 * 展示搜索热词、趋势、行为统计、转化率等数据。
 */
import React, { useState, useEffect, useCallback } from 'react';
import {
  Card, CardHeader, CardContent,
  Button, Badge,
  DataTable,
  EmptyState,
  Alert,
  StatCard,
  CardTitle,
} from '@/components/ui';
import {
  Search,
  Eye, CheckCircle,
  BarChart3,
} from 'lucide-react';
import {
  LineChart as ReLineChart,
  BarChart as ReBarChart, Bar,
  PieChart as RePieChart, Pie,
  Cell,
  XAxis, YAxis, CartesianGrid,
  ResponsiveContainer, AreaChart, Area,
} from 'recharts';
import { databaseApi } from '@/api/database';
import { logger } from '@/utils/safeLogger';

// ── 颜色常量 ──
const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884D8', '#82CA9D'];

// ── 类型定义 ──
interface HotSearchItem {
  keyword: string;
  search_count: number;
  last_searched: string;
  trend: 'rising' | 'stable';
}

interface SearchBehaviorStats {
  total_searches: number;
  unique_users: number;
  avg_result_count: number;
  zero_result_rate: number;
  source_distribution: Record<string, number>;
}

interface ConversionRate {
  total_searches: number;
  converted: number;
  conversion_rate: number;
}

interface PopularCategory {
  category: string;
  count: number;
}

// ── 搜索分析仪表盘主组件 ──
const SearchAnalyticsDashboard: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'overview' | 'trends' | 'categories'>('overview');

  // 数据状态
  const [hotSearches, setHotSearches] = useState<HotSearchItem[]>([]);
  const [behaviorStats, setBehaviorStats] = useState<SearchBehaviorStats | null>(null);
  const [conversionRate, setConversionRate] = useState<ConversionRate | null>(null);
  const [popularCategories, setPopularCategories] = useState<PopularCategory[]>([]);
  const [trendData, setTrendData] = useState<any[]>([]);
  const [selectedKeyword, setSelectedKeyword] = useState<string>('');

  // 加载概览数据
  const loadOverview = useCallback(async () => {
    setLoading(true);
    try {
      const [hotRes, behaviorRes, conversionRes, categoryRes] = await Promise.all([
        databaseApi.get('/search/analytics/hot-searches', { params: { limit: 20 } }),
        databaseApi.get('/search/analytics/behavior-stats'),
        databaseApi.get('/search/analytics/conversion-rate'),
        databaseApi.get('/search/analytics/popular-categories'),
      ]);

      setHotSearches(hotRes || []);
      setBehaviorStats(behaviorRes);
      setConversionRate(conversionRes);
      setPopularCategories(categoryRes || []);
    } catch (err) {
      logger.error('加载搜索分析数据失败:', err);
    } finally {
      setLoading(false);
    }
  }, []);

  // 加载趋势数据
  const loadTrendData = useCallback(async (keyword: string) => {
    if (!keyword) return;
    try {
      const resp = await databaseApi.get(`/search/analytics/trends/${encodeURIComponent(keyword)}`, {
        params: { days: 30 },
      });
      setTrendData(resp || []);
    } catch (err) {
      logger.error('加载趋势数据失败:', err);
    }
  }, []);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    loadOverview();
  }, [loadOverview]);

  // ── 概览卡片 ──
  const OverviewCards = () => (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
      <StatCard
        label="总搜索次数"
        value={behaviorStats?.total_searches || 0}
        icon={Search}
        variant="primary"
      />
      <StatCard
        label="独立用户数"
        value={behaviorStats?.unique_users || 0}
        icon={Eye}
        variant="success"
      />
      <StatCard
        label="平均结果数"
        value={behaviorStats?.avg_result_count?.toFixed(1) || 0}
        icon={BarChart3}
        variant="warning"
      />
      <StatCard
        label="转化率"
        value={`${conversionRate?.conversion_rate || 0}%`}
        icon={CheckCircle}
        variant="info"
      />
    </div>
  );

  // ── 热门搜索词表格 ──
  const HotSearchTable = () => {
    const handleRowClick = (record: HotSearchItem) => {
      setSelectedKeyword(record.keyword);
      loadTrendData(record.keyword);
      setActiveTab('trends');
    };

    return (
      <Card className="mb-6">
        <CardHeader className="flex flex-row items-center justify-between pb-2">
          <CardTitle>🔥 热门搜索词</CardTitle>
          <div className="flex gap-1">
            {(['overview', 'trends', 'categories'] as const).map((tab) => (
              <Button
                key={tab}
                variant={activeTab === tab ? 'primary' : 'ghost'}
                size="sm"
                onClick={() => setActiveTab(tab)}
                className="text-xs h-7"
              >
                {{ overview: '概览', trends: '趋势', categories: '分类' }[tab]}
              </Button>
            ))}
          </div>
        </CardHeader>
        <CardContent>
          <DataTable
            columns={[
              {
                accessorKey: 'rank',
                header: '排名',
                size: 60,
                cell: ({ row }: { row: { index: number } }) => (
                  <span className="font-bold">{row.index + 1}</span>
                ),
              },
              {
                accessorKey: 'keyword',
                header: '搜索词',
                cell: ({ row }: { row: { original: HotSearchItem } }) => (
                  <a
                    onClick={() => handleRowClick(row.original)}
                    className="text-primary hover:underline cursor-pointer"
                  >
                    {row.original.keyword}
                  </a>
                ),
              },
              {
                accessorKey: 'search_count',
                header: '搜索次数',
                size: 120,
                cell: ({ row }: { row: { original: HotSearchItem } }) => row.original.search_count,
              },
              {
                accessorKey: 'trend',
                header: '趋势',
                size: 100,
                cell: ({ row }: { row: { original: HotSearchItem } }) => (
                  <Badge variant={row.original.trend === 'rising' ? 'destructive' : 'success'}>
                    {row.original.trend === 'rising' ? '🔥 上升' : '➡️ 稳定'}
                  </Badge>
                ),
              },
              {
                accessorKey: 'last_searched',
                header: '最后搜索',
                size: 120,
                cell: ({ row }: { row: { original: HotSearchItem } }) =>
                  row.original.last_searched
                    ? new Date(row.original.last_searched).toLocaleDateString('zh-CN')
                    : '-',
              },
            ]}
            data={hotSearches}
            onRowClick={handleRowClick}
            pageSizeOptions={[10, 20]}
          />
        </CardContent>
      </Card>
    );
  };

  // ── 趋势图表 ──
  const TrendChart = () => {
    if (!selectedKeyword) {
      return <EmptyState title="请选择一个搜索词查看趋势" description="点击热门搜索词可在此查看其搜索趋势变化" />;
    }

    return (
      <Card className="mb-6">
        <CardHeader>
          <CardTitle>{`📈 ${selectedKeyword} 搜索趋势`}</CardTitle>
        </CardHeader>
        <CardContent>
          <ResponsiveContainer width="100%" height={300}>
            <AreaChart data={trendData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="date" />
              <YAxis />
              <ReLineChart />
              <Area
                type="monotone"
                dataKey="count"
                stroke="#8884d8"
                fill="#8884d8"
                fillOpacity={0.3}
                name="搜索次数"
              />
            </AreaChart>
          </ResponsiveContainer>
        </CardContent>
      </Card>
    );
  };

  // ── 分类饼图 ──
  const CategoryPie = () => {
    const pieData = popularCategories.map((c) => ({
      name: c.category,
      value: c.count,
    }));

    if (pieData.length === 0) {
      return <EmptyState title="暂无分类数据" description="暂无热门分类统计信息" />;
    }

    return (
      <Card className="mb-6">
        <CardHeader>
          <CardTitle>📊 热门分类分布</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <ResponsiveContainer width="100%" height={300}>
              <RePieChart>
                <Pie rootTabIndex={-1}
                  data={pieData}
                  cx="50%"
                  cy="50%"
                  labelLine={false}
                  label={({ name, percent }) => `${name}: ${(percent * 100).toFixed(1)}%`}
                  outerRadius={80}
                  fill="#8884d8"
                  dataKey="value"
                >
                  {pieData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
              </RePieChart>
            </ResponsiveContainer>
            <ResponsiveContainer width="100%" height={300}>
              <ReBarChart data={pieData}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="name" angle={-45} textAnchor="end" height={60} />
                <YAxis />
                <Bar dataKey="value" fill="#82ca9d" name="数量" />
              </ReBarChart>
            </ResponsiveContainer>
          </div>
        </CardContent>
      </Card>
    );
  };

  // ── 零结果率告警 ──
  const ZeroResultAlert = () => {
    if (!behaviorStats || behaviorStats.zero_result_rate < 5) return null;
    return (
      <Alert
        variant="warning"
        title="零结果率偏高"
        description={`当前零结果率为 ${behaviorStats.zero_result_rate}%，建议优化搜索算法或扩充词库。`}
      />
    );
  };

  // ── 来源分布 ──
  const SourceDistribution = () => {
    if (!behaviorStats?.source_distribution) return null;

    const sourceData = Object.entries(behaviorStats.source_distribution).map(([name, value]) => ({
      name,
      value,
    }));

    return (
      <Card className="mb-6">
        <CardHeader>
          <CardTitle>🔍 搜索来源分布</CardTitle>
        </CardHeader>
        <CardContent>
          <ResponsiveContainer width="100%" height={200}>
            <ReBarChart data={sourceData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="name" />
              <YAxis />
              <Bar dataKey="value" fill="#8884d8" name="搜索次数" />
            </ReBarChart>
          </ResponsiveContainer>
        </CardContent>
      </Card>
    );
  };

  return (
    <div className="p-[var(--space-apple-lg)]">
      {loading ? (
        <div className="flex flex-col items-center justify-center py-16 gap-[var(--space-apple-sm)]">
          <div className="animate-spin h-8 w-8 border-2 border-primary border-t-transparent rounded-[var(--radius-pill)]" />
          <span className="text-sm text-muted-foreground">加载分析数据...</span>
        </div>
      ) : (
        <>
          {/* eslint-disable-next-line react-hooks/static-components */}
          <ZeroResultAlert />
          {/* eslint-disable-next-line react-hooks/static-components */}
          <OverviewCards />
          {/* eslint-disable-next-line react-hooks/static-components */}
          <HotSearchTable />
          {/* eslint-disable-next-line react-hooks/static-components */}
          <TrendChart />
          {/* eslint-disable-next-line react-hooks/static-components */}
          <CategoryPie />
          {/* eslint-disable-next-line react-hooks/static-components */}
          <SourceDistribution />
        </>
      )}
    </div>
  );
};

export default SearchAnalyticsDashboard;

﻿/**
 * TCMSP 靶点检索面板
 * 展示 3,300+ 靶点数据，支持关键词搜索
 */
import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { databaseApi } from '@/api/database';
import { Input, Button, Badge } from '@/components/ui';
import { Search, Download, ArrowUp, ArrowDown, Minus } from 'lucide-react';

type SortField = 'name' | 'gene_symbol';
type SortDir = 'asc' | 'desc';

export default function TargetsTab() {
  const [keyword, setKeyword] = useState('');
  const [page, setPage] = useState(1);
  const [sortField, setSortField] = useState<SortField>('name');
  const [sortDir, setSortDir] = useState<SortDir>('asc');

  const pageSize = 20;

  const targetsQuery = useQuery({
    queryKey: ['db-targets', keyword, page, sortField, sortDir],
    queryFn: async () => databaseApi.searchTargets({
      keyword: keyword.trim() || undefined,
      page, page_size: pageSize,
    }),
  });

  const statsQuery = useQuery({
    queryKey: ['db-targets-stats'],
    queryFn: () => databaseApi.getTargetStats(),
  });

  const total = targetsQuery.data?.total ?? 0;
  const items = targetsQuery.data?.items ?? [];
  const totalPages = Math.ceil(total / pageSize);

  const doSearch = () => setPage(1);

  const toggleSort = (field: SortField) => {
    if (sortField === field) setSortDir((d) => (d === 'asc' ? 'desc' : 'asc'));
    else { setSortField(field); setSortDir('asc'); }
  };

  const SortIcon = ({ field }: { field: SortField }) => {
    if (sortField !== field) return <Minus className="w-3 h-3 ml-0.5 opacity-20" />;
    return sortDir === 'asc' ? <ArrowUp className="w-3 h-3 ml-0.5 text-[var(--color-primary-text)]0" />
      : <ArrowDown className="w-3 h-3 ml-0.5 text-[var(--color-primary-text)]0" />;
  };

  const exportCSV = () => {
    const headers = ['靶点名称', '基因符号', '物种', '来源'];
    const rows = items.map((t: any) => [t.name, t.gene_symbol || '', t.organism || '', t.source || '']);
    const csv = [headers, ...rows].map((r: any[]) => r.map((c: any) => `"${c}"`).join(',')).join('\n');
    const blob = new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `targets_${new Date().toISOString().slice(0, 10)}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="space-y-4">
      {/* 统计概览 */}
      {statsQuery.data && (
        <div className="flex flex-wrap gap-3">
          {[
            { label: '靶点总数', value: statsQuery.data.total_targets?.toLocaleString() ?? '-', color: 'text-[var(--color-primary-text)]' },
            { label: '有基因符号', value: statsQuery.data.with_gene_symbol?.toLocaleString() ?? '0', color: 'text-[var(--color-accent-text)]' },
          ].map((s, i) => (
            <div key={i} className="card px-4 py-3 flex-1 min-w-[140px]">
              <div className={`text-lg font-bold ${s.color} tabular-nums`}>{s.value}</div>
              <div className="text-xs text-[var(--text-muted)] font-medium">{s.label}</div>
            </div>
          ))}
        </div>
      )}

      {/* 搜索栏 */}
      <div className="flex flex-wrap gap-3 items-center">
        <div className="relative flex-1 min-w-[200px]">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
          <Input value={keyword} onChange={(e) => setKeyword(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && doSearch()} placeholder="搜索靶点名称或基因符号..." className="pl-9" />
        </div>
        <Button variant="primary" size="sm" onClick={doSearch} icon={<Search className="w-3.5 h-3.5" />}>搜索</Button>
        <Button variant="ghost" size="sm" onClick={exportCSV} icon={<Download className="w-3.5 h-3.5" />} disabled={items.length === 0}>导出</Button>
      </div>

      <div className="text-xs text-[var(--text-muted)]">共 {total.toLocaleString()} 个靶点，第 {page}/{totalPages || 1} 页</div>

      {/* 表格 */}
      <div className="card overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-[var(--border-color)] dark:border-neutral-700 bg-[var(--bg-tertiary)]/50">
                <th className="px-4 py-2.5 text-left text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider">
                  <button onClick={() => toggleSort('name')} className="flex items-center gap-1 hover:text-[var(--color-primary-text)] transition-colors">
                    靶点名称 <SortIcon field="name" />
                  </button>
                </th>
                <th className="px-4 py-2.5 text-left text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider">
                  <button onClick={() => toggleSort('gene_symbol')} className="flex items-center gap-1 hover:text-[var(--color-primary-text)] transition-colors">
                    基因符号 <SortIcon field="gene_symbol" />
                  </button>
                </th>
                <th className="px-4 py-2.5 text-left text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider">物种</th>
                <th className="px-4 py-2.5 text-left text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider">来源</th>
              </tr>
            </thead>
            <tbody>
              {targetsQuery.isLoading ? (
                <tr><td colSpan={4} className="px-4 py-8 text-center text-[var(--text-muted)] text-sm">加载中...</td></tr>
              ) : items.length === 0 ? (
                <tr><td colSpan={4} className="px-4 py-8 text-center text-[var(--text-muted)] text-sm">暂无数据，请先执行数据同步</td></tr>
              ) : items.map((t: any) => (
                <tr key={t.id} className="border-b border-[var(--border-color)]/50 hover:bg-[var(--bg-tertiary)] dark:hover:bg-[var(--bg-tertiary)]/30 transition-colors">
                  <td className="px-4 py-2.5 font-medium text-[var(--text-primary)] max-w-[300px] truncate" title={t.name}>{t.name}</td>
                  <td className="px-4 py-2.5 font-mono text-xs text-[var(--color-primary-text)] dark:text-[var(--color-primary-text)]">{t.gene_symbol || <span className="text-[var(--text-muted)]">-</span>}</td>
                  <td className="px-4 py-2.5 text-[var(--text-muted)]">{t.organism || '-'}</td>
                  <td className="px-4 py-2.5"><Badge variant="secondary" size="sm">{t.source || 'tcmsp'}</Badge></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {totalPages > 1 && (
        <div className="flex items-center justify-between">
          <div className="text-xs text-[var(--text-muted)]">第 {((page - 1) * pageSize) + 1} - {Math.min(page * pageSize, total)} 条，共 {total} 条</div>
          <div className="flex items-center gap-1">
            <Button variant="outline" size="sm" disabled={page <= 1} onClick={() => setPage(p => p - 1)}>上一页</Button>
            <span className="px-3 py-1 text-xs font-medium text-[var(--text-muted)]">{page} / {totalPages}</span>
            <Button variant="outline" size="sm" disabled={page >= totalPages} onClick={() => setPage(p => p + 1)}>下一页</Button>
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * 文档智能提取页面 — 完整功能版
 * CoA/PDS/SD 文本提取 + PDF解析 + 提取历史 + 结果对比
 * 主题系统：对齐 Dashboard 设计系统规范（bg-grid + brand banner + Card/Button + design tokens）
 */
import { useState, useRef } from 'react'
import { useNavigate } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import {
  FileText, Upload, AlertTriangle, CheckCircle2,
  FileCheck, Loader2, History, Trash2, Layers, Download,
} from 'lucide-react'
import { documentApi, documentArchiveApi, type DocumentType, type ExtractionResult, type ArchiveRecord } from '@/api/document'
import { useToast } from '@/components/ui/Toast'
import { Card, CardHeader, CardTitle, CardContent, Button } from '@/components/ui'
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter,
} from '@/components/ui'

// ─── 本地存储 ────────────────────────────────────────────────
const HISTORY_KEY = 'rmfood_doc_history'
const loadHistory = () => { try { return JSON.parse(localStorage.getItem(HISTORY_KEY) ?? '[]') } catch { return [] } }
const saveHistory = (items: any[]) => localStorage.setItem(HISTORY_KEY, JSON.stringify(items.slice(0, 20)))

// ─── 预填示例文本 ─────────────────────────────────────────────
const EXAMPLE_TEXTS: Record<DocumentType, string> = {
  coa: `检验报告
产品名称：黄芪多糖提取物
批号：HT2024001
规格：1kg/袋
检验项目：
1. 性状：淡黄色粉末
2. 鉴别： TLC对照，阳性
3. 含量测定：黄芪多糖≥95.0%（HPLC法）
4. 水分：≤5.0%（烘干失重法）
5. 灰分：≤5.0%
6. 重金属：铅≤2.0mg/kg，砷≤1.0mg/kg，汞≤0.5mg/kg
7. 微生物：细菌总数≤1000cfu/g，霉菌≤100cfu/g，酵母菌≤50cfu/g，大肠杆菌阴性，沙门氏菌阴性
结论：本品经检验，符合《中国药典》2020年版四部通则1185之规定，判定为合格。`,
  pds: `产品安全数据表（PDS）
产品名称：胶原蛋白肽粉
供应商：XX生物科技股份有限公司
产品编号：CP-2024-001
1. 成分信息
   - 主要成分：Ⅰ型胶原蛋白肽
   - 分子量：500-1000 Da
   - 蛋白质含量：≥90%
   - 水分：≤8%
2. 安全信息
   - 刺激性：无刺激性
   - 致敏性：低致敏性
   - 建议摄入量：每日5-10g
3. 储存条件
   - 储存温度：室温，避光
   - 有效期：24个月`,
  sd: `安全数据表（SDS）
化学品名称：柠檬酸
CAS号：77-92-9
1. 成分识别
   - 化学品名称：柠檬酸（Citric Acid）
   - 分子式：C6H8O7
   - 分子量：192.12 g/mol
2. 危险性识别
   - GHS分类：皮肤刺激类别2，严重眼损伤类别2
   - 信号词：警告
   - 危险说明：H315-H319
3. 急救措施
   - 皮肤接触：用大量水冲洗
   - 眼睛接触：用清水冲洗至少15分钟`,
}

// 置信度 → 设计令牌映射（阈值 0.85 / 0.6 → success / warning / danger）
const confClass = (conf: number) =>
  conf >= 0.85
    ? { card: 'bg-[var(--color-success-container)] dark:bg-[var(--color-success-container)]/20 border-[var(--color-success-border)] dark:border-[var(--color-success-border)]', text: 'text-[var(--color-success-text)] dark:text-[var(--color-success-text)]', bar: 'bg-[var(--color-success-text)]' }
    : conf >= 0.6
      ? { card: 'bg-[var(--color-warning-container)] dark:bg-[var(--color-warning-container)]/20 border-[var(--color-warning-border)] dark:border-[var(--color-warning-border)]', text: 'text-[var(--color-warning-text)] dark:text-[var(--color-warning-text)]', bar: 'bg-[var(--color-warning-text)]' }
      : { card: 'bg-[var(--color-error-container)] dark:bg-[var(--color-error-container)]/20 border-[var(--color-error-border)] dark:border-[var(--color-error-border)]', text: 'text-[var(--color-error-text)] dark:text-[var(--color-error-text)]', bar: 'bg-[var(--color-error-text)]' }

export default function DocumentExtractPage() {
  const { t, i18n } = useTranslation()
  const { addToast } = useToast()
  const [docType, setDocType] = useState<DocumentType>('coa')
  const [textInput, setTextInput] = useState('')
  const [result, setResult] = useState<null | ExtractionResult>(null)
  const [loading, setLoading] = useState(false)
  const [dragOver, setDragOver] = useState(false)
  const [history, setHistory] = useState<any[]>(loadHistory)
  const [showHistory, setShowHistory] = useState(false)
  const [compareMode, setCompareMode] = useState(false)
  const [compareResults, setCompareResults] = useState<ExtractionResult[]>([])
  const [archives, setArchives] = useState<ArchiveRecord[]>([])
  const [showArchives, setShowArchives] = useState(false)
  const [archivesLoading, setArchivesLoading] = useState(false)
  const [saving, setSaving] = useState(false)
  const [uploadedFileName, setUploadedFileName] = useState<string | null>(null)
  const [lastGeneratedCoaId, setLastGeneratedCoaId] = useState<number | null>(null)
  const [reviewOpen, setReviewOpen] = useState(false)
  const [reviewDraft, setReviewDraft] = useState<Record<string, string>>({})
  const [reviewed, setReviewed] = useState(false)
  const [reviewArchiveId, setReviewArchiveId] = useState<number | null>(null)
  const navigate = useNavigate()
  const fileInputRef = useRef<HTMLInputElement>(null)

  const docTypeLabel = (dt: DocumentType) => dt === 'coa' ? t('pages.document.coaType') : dt === 'pds' ? t('pages.document.pdsType') : t('pages.document.sdType')

  const handleTextExtract = async () => {
    if (!textInput.trim()) { addToast({ type: 'warning', message: t('pages.document.inputDocText') }); return }
    setLoading(true)
    try {
      const res = await documentApi.extractText(textInput, docType)
      // 后端返回 { status, data: ExtractionResult }，axios res.data 即该对象
      const data = (res.data as any)?.data ?? res.data
      setResult(data)
      // Save to history
      const count = Object.keys(data?.extracted_fields ?? {}).length
      const histItem = {
        id: Date.now(),
        type: docType,
        text: textInput.substring(0, 50) + (textInput.length > 50 ? '...' : ''),
        fields: count,
        confidence: data?.overall_confidence ?? 0,
        date: new Date().toLocaleDateString(i18n.language),
      }
      const newHistory = [histItem, ...history].slice(0, 20)
      setHistory(newHistory)
      saveHistory(newHistory)
      addToast({ type: 'success', message: t('pages.document.extractedCount', { count }) })
    } catch (e: any) {
      addToast({ type: 'error', message: String(e) })
    } finally { setLoading(false) }
  }

  const handleFileUpload = async (file: File) => {
    const formData = new FormData()
    formData.append('file', file)
    formData.append('document_type', docType)
    setLoading(true)
    setUploadedFileName(file.name)
    try {
      const res = await fetch('/api/v1/documents/extract', {
        method: 'POST',
        body: formData,
      })
      if (!res.ok) throw new Error(await res.text())
      const json = await res.json()
      if (json.status === 'error') throw new Error(json.error ?? t('pages.document.uploadFailed'))
      const data = json.data
      setResult(data)
      const count = Object.keys(data?.extracted_fields ?? {}).length
      addToast({ type: 'success', message: t('pages.document.uploadedAuto', { name: file.name, count }) })
    } catch (e: any) {
      setUploadedFileName(null)
      addToast({ type: 'error', message: e.message ?? t('pages.document.uploadFailed') })
    } finally { setLoading(false) }
  }

  const overallConf = result ? result.overall_confidence : 0
  const conf = confClass(overallConf)

  const handleCompare = () => {
    if (result) {
      setCompareResults(prev => [...prev, result])
      addToast({ type: 'success', message: t('pages.document.addedToCompare', { count: compareResults.length + 1 }) })
    }
  }

  // ─── 备案：保存提取结果到后端数据库 ─────────────────────────
  const loadArchives = async () => {
    setArchivesLoading(true)
    try {
      const res = await documentArchiveApi.list({ limit: 50 })
      const data = (res.data as any)?.data ?? []
      setArchives(data)
    } catch {
      setArchives([])
    } finally {
      setArchivesLoading(false)
    }
  }

  const handleSaveArchive = async () => {
    if (!result) return
    setSaving(true)
    try {
      await documentArchiveApi.save({
        document_type: result.document_type,
        ingredient_id: (result as any)?.metadata?.ingredient_id ?? null,
        extracted_fields: result.extracted_fields,
        confidence_scores: result.confidence_scores,
        inspection_items: result.inspection_items,
        overall_confidence: result.overall_confidence,
        requires_review: result.requires_review,
        raw_text_preview: result.raw_text_preview,
      })
      addToast({ type: 'success', message: t('pages.document.archiveSaved') })
      await loadArchives()
    } catch (e: any) {
      addToast({ type: 'error', message: String(e?.message ?? e) })
    } finally {
      setSaving(false)
    }
  }

  const handleDeleteArchive = async (id: number) => {
    if (!window.confirm(t('pages.document.confirmDeleteArchive'))) return
    try {
      await documentArchiveApi.remove(id)
      setArchives(prev => prev.filter(a => a.id !== id))
      addToast({ type: 'success', message: t('pages.document.archiveDeleted') })
    } catch (e: any) {
      addToast({ type: 'error', message: String(e?.message ?? e) })
    }
  }

  const handleGeneratePeptideCoa = async (id: number) => {
    try {
      const res = await documentArchiveApi.toPeptideCoa(id)
      const coa = (res.data as any)?.data
      if (coa?.id) {
        setLastGeneratedCoaId(coa.id)
        addToast({ type: 'success', message: t('pages.document.peptideCoaGenerated', { id: coa.id }) })
      } else {
        addToast({ type: 'success', message: t('pages.document.peptideCoaGeneratedShort') })
      }
    } catch (e: any) {
      addToast({ type: 'error', message: String(e?.message ?? e) })
    }
  }

  // ─── 人工复核：修正低置信度字段值（结果 / 已备案记录） ───
  const openReview = () => {
    if (!result) return
    setReviewArchiveId(null)
    const draft: Record<string, string> = {}
    for (const [key, field] of Object.entries(result.extracted_fields)) {
      draft[key] = String(field.value ?? '')
    }
    setReviewDraft(draft)
    setReviewOpen(true)
  }

  const openArchiveReview = async (archiveId: number) => {
    try {
      const res = await documentArchiveApi.detail(archiveId)
      const detail = (res.data as any)?.data
      if (!detail?.extracted_fields) {
        addToast({ type: 'error', message: t('pages.document.cannotReadArchive') })
        return
      }
      setReviewArchiveId(archiveId)
      const draft: Record<string, string> = {}
      for (const [key, field] of Object.entries(detail.extracted_fields) as Array<[string, { value?: unknown }]>) {
        draft[key] = String((field as any)?.value ?? '')
      }
      setReviewDraft(draft)
      setReviewOpen(true)
    } catch (e: any) {
      addToast({ type: 'error', message: String(e?.message ?? e) })
    }
  }

  const confirmReview = async () => {
    if (reviewArchiveId != null) {
      // 备案记录复核：读取详情，更新后写回后端
      try {
        const res = await documentArchiveApi.detail(reviewArchiveId)
        const detail = (res.data as any)?.data
        if (!detail?.extracted_fields) {
          addToast({ type: 'error', message: t('pages.document.cannotReadArchive') })
          return
        }
        const updatedFields = { ...detail.extracted_fields }
        for (const [key, value] of Object.entries(reviewDraft)) {
          if (updatedFields[key]) {
            updatedFields[key] = { ...updatedFields[key], value }
          }
        }
        await documentArchiveApi.update(reviewArchiveId, {
          extracted_fields: updatedFields,
          confidence_scores: detail.confidence_scores ?? {},
          inspection_items: detail.inspection_items ?? [],
          overall_confidence: detail.overall_confidence ?? 0,
          requires_review: false, // 复核完成，清除复核标记
        })
        setReviewOpen(false)
        setReviewArchiveId(null)
        addToast({ type: 'success', message: t('pages.document.reviewDoneArchive') })
        await loadArchives()
      } catch (e: any) {
        addToast({ type: 'error', message: String(e?.message ?? e) })
      }
      return
    }

    // 当前提取结果复核：写回本地 result
    if (!result) return
    const updated: ExtractionResult = { ...result }
    updated.extracted_fields = { ...result.extracted_fields }
    for (const [key, value] of Object.entries(reviewDraft)) {
      if (updated.extracted_fields[key]) {
        updated.extracted_fields[key] = { ...updated.extracted_fields[key], value }
      }
    }
    setResult(updated)
    setReviewed(true)
    setReviewOpen(false)
    addToast({ type: 'success', message: t('pages.document.reviewDone') })
  }

  return (
    <div className="min-h-screen">
      <div className="max-w-[1600px] mx-auto px-[var(--space-apple-md)] sm:px-6 lg:px-8 py-[var(--space-apple-lg)] space-y-[var(--space-apple-md)]">
        {/* 页头横幅 — 对齐 Dashboard 品牌横幅规范 */}
        <div className="surface-primary rounded-[var(--radius-Apple-md)] p-[var(--space-apple-lg)] shadow-sm">
          <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
            <div className="flex-1">
              <h1 className="text-xl font-semibold leading-snug tracking-tight flex items-center gap-2">
                <FileCheck size={20} className="text-white/80 shrink-0" />
                {t('pages.document.title')}
              </h1>
              <p className="mt-1 text-white/80 text-sm">{t('pages.document.subtitle')}</p>
            </div>
            <div className="flex items-center gap-2">
              {history.length > 0 && (
                <button onClick={() => setShowHistory(!showHistory)}
                  className="flex items-center gap-1.5 px-[var(--space-apple-sm)] py-1.5 min-h-[44px] text-xs font-medium bg-[var(--bg-secondary)]/15 hover:bg-[var(--bg-secondary)]/25 rounded-[var(--radius-pill)] transition-colors">
                  <History size={12} />{t('pages.document.history', { count: history.length })}
                </button>
              )}
              {compareResults.length > 0 && (
                <button onClick={() => setCompareMode(!compareMode)}
                  className={`flex items-center gap-1.5 px-[var(--space-apple-sm)] py-1.5 min-h-[44px] text-xs font-medium rounded-[var(--radius-pill)] transition-colors ${
                    compareMode ? 'bg-[var(--bg-secondary)]/30' : 'bg-[var(--bg-secondary)]/15 hover:bg-[var(--bg-secondary)]/25'
                  }`}>
                  <Layers size={12} />{t('pages.document.compare', { count: compareResults.length })}
                </button>
              )}
              <button onClick={() => {
                if (!showArchives && archives.length === 0) loadArchives()
                setShowArchives(!showArchives)
              }}
                className={`flex items-center gap-1.5 px-[var(--space-apple-sm)] py-1.5 min-h-[44px] text-xs font-medium rounded-[var(--radius-pill)] transition-colors ${
                  showArchives ? 'bg-[var(--bg-secondary)]/30' : 'bg-[var(--bg-secondary)]/15 hover:bg-[var(--bg-secondary)]/25'
                }`}>
                <FileText size={12} />{t('pages.document.archive', { count: archives.length })}
              </button>
            </div>
          </div>
        </div>

        {/* History Panel */}
        {showHistory && history.length > 0 && (
          <Card>
            <CardContent className="p-[var(--space-apple-md)]">
              <div className="text-xs font-semibold text-[var(--text-muted)] mb-2 uppercase tracking-wide">{t('pages.document.recentExtractionHistory')}</div>
              <div className="flex gap-2 flex-wrap">
                {history.map(h => (
                  <div key={h.id} className="flex items-center gap-2 px-[var(--space-apple-sm)] py-1.5 bg-[var(--bg-tertiary)]/60 rounded-[var(--radius-Apple-sm)] text-xs border border-[var(--border-color)]">
                    <span className="font-mono text-[var(--color-accent-text)] dark:text-[var(--color-accent-text)]">{h.type.toUpperCase()}</span>
                    <span className="text-[var(--text-muted)]">{t('pages.document.fieldsCount', { count: h.fields })}</span>
                    <span className="text-[var(--text-muted)]">{t('pages.document.confidencePercent', { value: (h.confidence * 100).toFixed(0) })}</span>
                    <span className="text-[var(--text-muted)] dark:text-[var(--text-muted)]">{h.date}</span>
                    <button onClick={() => {
                      const newHist = history.filter(x => x.id !== h.id)
                      setHistory(newHist)
                      saveHistory(newHist)
                    }} className="text-[var(--text-muted)] hover:text-[var(--color-error-text)] ml-1"><Trash2 size={10} /></button>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        )}

        {/* Compare Panel */}
        {compareMode && compareResults.length > 0 && (
          <Card>
            <CardContent className="p-[var(--space-apple-md)]">
              <div className="flex items-center justify-between mb-[var(--space-apple-sm)]">
                <div className="text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wide">{t('pages.document.compareResults', { count: compareResults.length })}</div>
                <button onClick={() => { setCompareResults([]); setCompareMode(false) }} className="text-xs text-[var(--text-muted)] hover:text-[var(--text-secondary)] dark:hover:text-[var(--text-muted)]">{t('pages.document.clearCompare')}</button>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-[var(--space-apple-sm)]">
                {compareResults.map((cr, idx) => {
                  const c = cr.overall_confidence ?? 0
                  const cc = confClass(c)
                  const fieldCount = Object.keys(cr.extracted_fields ?? {}).length
                  return (
                    <div key={idx} className={`p-[var(--space-apple-sm)] rounded-[var(--radius-Apple-sm)] border ${cc.card}`}>
                      <div className="flex items-center justify-between mb-2">
                        <span className="text-xs font-semibold text-[var(--text-secondary)]">{t('pages.document.resultItem', { id: idx + 1 })}</span>
                        <span className={`text-xs font-mono ${cc.text}`}>
                          {t('pages.document.confidence')} {c.toFixed(2)}
                        </span>
                      </div>
                      <div className="text-xs text-[var(--text-muted)]">{t('pages.document.fieldsExtracted', { count: fieldCount })}</div>
                      <div className="mt-2 w-full bg-[var(--border-color)] rounded-[var(--radius-pill)] h-1">
                        <div className={`h-1 rounded-[var(--radius-pill)] ${cc.bar}`}
                          style={{ width: `${c * 100}%` }} />
                      </div>
                    </div>
                  )
                })}
              </div>
            </CardContent>
          </Card>
        )}

        {/* Archive Panel — 数据库备案记录 */}
        {showArchives && (
          <Card>
            <CardContent className="p-[var(--space-apple-md)]">
              <div className="flex items-center justify-between mb-[var(--space-apple-sm)]">
                <div className="text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wide">{t('pages.document.archiveRecords', { count: archives.length })}</div>
                <div className="flex items-center gap-3">
                  {lastGeneratedCoaId && (
                    <button onClick={() => navigate('/database')} className="text-xs text-[var(--color-primary-text)] hover:underline">
                      {t('pages.document.viewGeneratedArchive')}
                    </button>
                  )}
                  <button onClick={() => { setShowArchives(false); setArchives([]) }} className="text-xs text-[var(--text-muted)] hover:text-[var(--text-secondary)] dark:hover:text-[var(--text-muted)]">{t('pages.document.close')}</button>
                </div>
              </div>
              {archivesLoading ? (
                <p className="text-sm text-[var(--text-muted)] py-4 text-center">{t('pages.document.loading')}</p>
              ) : archives.length === 0 ? (
                <p className="text-sm text-[var(--text-muted)] py-4 text-center">{t('pages.document.noArchiveRecords')}</p>
              ) : (
                <div className="space-y-2">
                  {archives.map(a => (
                    <div key={a.id} className="flex items-center gap-3 px-[var(--space-apple-sm)] py-2.5 bg-[var(--bg-tertiary)]/60 rounded-[var(--radius-Apple-sm)] border border-[var(--border-color)]">
                      <span className="font-mono text-xs text-[var(--color-accent-text)] dark:text-[var(--color-accent-text)] w-12 shrink-0">{a.document_type.toUpperCase()}</span>
                      <span className="text-xs text-[var(--text-muted)]">#{a.id}</span>
                      <span className="text-xs text-[var(--text-primary)] font-medium truncate max-w-[180px]">{a.product_name || t('pages.document.unnamedDocument')}</span>
                      <span className="text-xs text-[var(--text-muted)] shrink-0">{t('pages.document.fieldsCount', { count: a.field_count })}</span>
                      {typeof a.inspection_count === 'number' && a.inspection_count > 0 && (
                        <span className="text-xs text-[var(--text-muted)] shrink-0">{t('pages.document.inspectionCount', { count: a.inspection_count })}</span>
                      )}
                      <span className={`text-xs font-mono ${a.overall_confidence >= 0.85 ? 'text-[var(--color-success-text)]' : a.overall_confidence >= 0.6 ? 'text-[var(--color-warning-text)]' : 'text-[var(--color-error-text)]'}`}>
                        {t('pages.document.confidence')} {(a.overall_confidence * 100).toFixed(0)}%
                      </span>
                      {a.requires_review && (
                        <button onClick={() => openArchiveReview(a.id)}
                          className="text-xs text-[var(--color-warning-text)] hover:underline"
                          aria-label={`${t('pages.document.reviewArchiveTitle', { id: a.id })}`}>
                          {t('pages.document.requiresReview')}
                        </button>
                      )}
                      <span className="text-xs text-[var(--text-muted)]">{a.created_at ? new Date(a.created_at).toLocaleDateString(i18n.language) : ''}</span>
                      <button onClick={() => handleGeneratePeptideCoa(a.id)}
                        className="ml-auto inline-flex items-center gap-1 text-xs text-[var(--color-primary-text)] hover:underline"
                        aria-label={`${t('pages.document.generateQcArchive')} #${a.id}`}>
                        <FileCheck size={12} />{t('pages.document.generateQcArchive')}
                      </button>
                      <button onClick={() => handleDeleteArchive(a.id)}
                        className="text-[var(--text-muted)] hover:text-[var(--color-error-text)] transition-colors"
                        aria-label={`${t('pages.document.confirmDeleteArchive')} #${a.id}`}>
                        <Trash2 size={12} />
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        )}

        <div className="max-w-5xl space-y-[var(--space-apple-md)]">
          {/* 文档类型 */}
          <Card>
            <CardHeader className="px-5 pt-5 pb-3">
              <CardTitle as="h2" className="text-sm font-semibold">{t('pages.document.docType')}</CardTitle>
            </CardHeader>
            <CardContent className="px-5 pb-5 pt-0">
              <div className="flex gap-[var(--space-apple-sm)] flex-wrap">
                {(['coa', 'pds', 'sd'] as DocumentType[]).map(t => (
                  <button key={t} onClick={() => { setDocType(t); setTextInput(EXAMPLE_TEXTS[t] ?? '') }}
                    className={`px-[var(--space-apple-md)] py-2 rounded-[var(--radius-Apple-sm)] text-sm font-medium transition-colors ${
                      docType === t
                        ? 'bg-[var(--color-primary-container)] text-[var(--color-primary-text)] shadow-sm'
                        : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)] hover:bg-[var(--border-color)] dark:hover:bg-[var(--bg-secondary)]'
                    }`}>
                    {docTypeLabel(t)}
                  </button>
                ))}
              </div>
            </CardContent>
          </Card>

          {/* 文档内容 */}
          <Card>
            <CardHeader className="px-5 pt-5 pb-3">
              <div className="flex items-center justify-between">
                <CardTitle as="h2" className="text-sm font-semibold flex items-center gap-2">
                  <FileText size={14} className="text-[var(--color-accent-text)] dark:text-[var(--color-accent-text)]" />{t('pages.document.docContent')}
                </CardTitle>
                <button onClick={() => setTextInput(EXAMPLE_TEXTS[docType] ?? '')}
                  className="text-xs text-[var(--color-accent-text)] hover:text-[var(--color-accent-text)] dark:text-[var(--color-accent-text)] dark:hover:text-[var(--color-accent-text)] transition-colors inline-flex items-center min-h-[44px] px-1 -mx-1">
                  {t('pages.document.fillExample')}
                </button>
              </div>
            </CardHeader>
            <CardContent className="px-5 pb-5 pt-0 space-y-[var(--space-apple-sm)]">
              <textarea
                value={textInput}
                onChange={e => setTextInput(e.target.value)}
                placeholder={t('pages.document.textareaPlaceholder')}
                rows={8}
                className="w-full px-[var(--space-apple-md)] py-[var(--space-apple-md)] text-sm rounded-[var(--radius-Apple-sm)] border border-[var(--border-color)] bg-[var(--bg-tertiary)] dark:text-[var(--text-primary)] resize-none focus:outline-none focus-visible:ring-0"
              />
              <div
                className={`border-2 border-dashed rounded-[var(--radius-Apple-sm)] p-5 text-center transition-colors ${
                  dragOver ? 'border-[var(--color-accent)] bg-[var(--color-accent-container)] dark:bg-[var(--color-accent-container)]/20' : 'border-[var(--border-color)]'
                }`}
                onDragOver={e => { e.preventDefault(); setDragOver(true) }}
                onDragLeave={() => setDragOver(false)}
                onDrop={e => { e.preventDefault(); setDragOver(false); if (e.dataTransfer.files[0]) handleFileUpload(e.dataTransfer.files[0]) }}
              >
                <Upload className="mx-auto mb-2 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" size={24} />
                <p className="text-sm text-[var(--text-muted)]">{t('pages.document.dragFileHint')}</p>
                <p className="text-xs text-[var(--text-muted)] mt-1">{t('pages.document.supportedFormats')}</p>
                {uploadedFileName && (
                  <p className="text-xs text-[var(--color-success-text)] mt-1">{t('pages.document.uploaded', { name: uploadedFileName })}</p>
                )}
                <input ref={fileInputRef} id="file-input" type="file" accept=".pdf,.docx,.txt" className="hidden"
                  onChange={e => e.target.files?.[0] && handleFileUpload(e.target.files[0])} aria-hidden="true" tabIndex={-1} />
                <label htmlFor="file-input" onClick={() => fileInputRef.current?.click()}
                  className="inline-block mt-2 px-[var(--space-apple-md)] py-1.5 text-sm bg-[var(--bg-tertiary)] rounded-[var(--radius-Apple-sm)] hover:bg-[var(--border-color)] dark:hover:bg-[var(--bg-secondary)] cursor-pointer transition-colors">
                  {t('pages.document.selectFile')}
                </label>
              </div>
            </CardContent>
          </Card>

          {/* 操作按钮 */}
          <div className="flex gap-[var(--space-apple-sm)]">
            <Button variant="primary" onClick={handleTextExtract} disabled={loading}
              icon={loading ? <Loader2 size={14} className="animate-spin" /> : <FileCheck size={14} />}
              className="flex-1 sm:flex-none px-6">
              {loading ? t('pages.document.extracting') : t('pages.document.startExtract')}
            </Button>
            {result && (
              <Button variant="outline" onClick={handleCompare}
                icon={<Layers size={14} />} className="flex-1 sm:flex-none px-5">
                {t('pages.document.addToCompare')}
              </Button>
            )}
            {result && (
              <Button variant="primary" onClick={handleSaveArchive} disabled={saving}
                icon={saving ? <Loader2 size={14} className="animate-spin" /> : <FileText size={14} />}
                className="flex-1 sm:flex-none px-5">
                {saving ? t('pages.document.saving') : t('pages.document.saveArchive')}
              </Button>
            )}
          </div>

          {/* 提取结果 */}
          {result && (
            <div className="space-y-[var(--space-apple-md)]">
              {/* 置信度总览 */}
              <div className={`rounded-[var(--radius-Apple-md)] p-[var(--space-apple-md)] border ${conf.card}`}>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-[var(--space-apple-sm)]">
                    {overallConf >= 0.85
                      ? <CheckCircle2 className="text-[var(--color-success-text)] dark:text-[var(--color-success-text)]" size={20} />
                      : <AlertTriangle className="text-[var(--color-warning-text)] dark:text-[var(--color-warning-text)]" size={20} />}
                    <div>
                      <div className="text-sm font-semibold text-[var(--text-primary)]">
                        {t('pages.document.overallConfidence', { value: overallConf.toFixed(2) })}
                      </div>
                      <div className="text-xs text-[var(--text-muted)]">
                        {t('pages.document.fieldsFound', { found: result.metadata.total_fields_found, expected: result.metadata.total_fields_expected })}
                        {result.requires_review && (
                          <>
                            <span className="text-[var(--color-warning-text)] dark:text-[var(--color-warning-text)] ml-2">{t('pages.document.requiresReview')}</span>
                            <button onClick={openReview} className="ml-2 text-xs text-[var(--color-primary-text)] underline underline-offset-2 hover:opacity-80">
                              {reviewed ? t('pages.document.reviewedEdit') : t('pages.document.goReview')}
                            </button>
                          </>
                        )}
                      </div>
                    </div>
                  </div>
                  <div className="text-right">
                    <div className="text-xs text-[var(--text-muted)]">{result.document_type.toUpperCase()}</div>
                  </div>
                </div>
                {/* 进度条 */}
                <div className="mt-[var(--space-apple-sm)] w-full bg-[var(--border-color)] rounded-[var(--radius-pill)] h-2">
                  <div className={`h-2 rounded-[var(--radius-pill)] transition-all ${conf.bar}`} style={{ width: `${overallConf * 100}%` }} />
                </div>
              </div>

              {/* 检验明细（OCR 表格解析） */}
              {result.inspection_items && result.inspection_items.length > 0 && (
                <Card>
                  <CardHeader className="px-5 pt-5 pb-3">
                    <CardTitle as="h3" className="text-sm font-semibold">{t('pages.document.inspectionDetails', { count: result.inspection_items.length })}</CardTitle>
                  </CardHeader>
                  <CardContent className="px-5 pb-5 pt-0">
                    <div className="overflow-x-auto">
                      <table className="w-full text-xs">
                        <thead>
                          <tr className="text-left text-[var(--text-muted)] border-b border-[var(--border-color)]">
                            <th className="py-2 pr-2 font-medium">{t('pages.document.thItem')}</th>
                            <th className="py-2 pr-2 font-medium">{t('pages.document.thStandard')}</th>
                            <th className="py-2 pr-2 font-medium">{t('pages.document.thResult')}</th>
                            <th className="py-2 font-medium">{t('pages.document.thJudgment')}</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-[var(--border-color)]">
                          {result.inspection_items.map((it, idx) => (
                            <tr key={idx}>
                              <td className="py-2 pr-2 text-[var(--text-primary)] align-top">
                                {it.item || '—'}
                                {it.item_en && <div className="text-xs sm:text-[10px] text-[var(--text-muted)]/70 mt-0.5">{it.item_en}</div>}
                              </td>
                              <td className="py-2 pr-2 text-[var(--text-muted)] align-top">
                                {it.standard || '—'}
                                {it.standard_en && <div className="text-xs sm:text-[10px] text-[var(--text-muted)]/70 mt-0.5">{it.standard_en}</div>}
                              </td>
                              <td className="py-2 pr-2 text-[var(--text-muted)] align-top">
                                {it.result || '—'}
                                {it.result_en && <div className="text-xs sm:text-[10px] text-[var(--text-muted)]/70 mt-0.5">{it.result_en}</div>}
                              </td>
                              <td className="py-2 text-[var(--text-muted)] align-top">
                                {it.judgment || '—'}
                                {it.judgment_en && <div className="text-xs sm:text-[10px] text-[var(--text-muted)]/70 mt-0.5">{it.judgment_en}</div>}
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </CardContent>
                </Card>
              )}

              {/* 字段明细 */}
              <Card>
                <CardHeader className="px-5 pt-5 pb-3">
                  <div className="flex items-center justify-between">
                    <CardTitle as="h3" className="text-sm font-semibold">{t('pages.document.fieldDetails')}</CardTitle>
                    <Button variant="ghost" size="sm" onClick={() => {
                      // Export results
                      const data = JSON.stringify(result, null, 2)
                      const blob = new Blob([data], { type: 'application/json' })
                      const url = URL.createObjectURL(blob)
                      const a = document.createElement('a')
                      a.href = url
                      a.download = `extraction_${docType}_${Date.now()}.json`
                      a.click()
                      URL.revokeObjectURL(url)
                      addToast({ type: 'success', message: t('pages.document.exportedJson') })
                    }} icon={<Download size={12} />}>
                      {t('pages.document.exportJson')}
                    </Button>
                  </div>
                </CardHeader>
                <CardContent className="px-5 pb-5 pt-0 space-y-2">
                  <div className="space-y-2">
                    {Object.entries(result.extracted_fields).map(([key, field]: [string, any]) => (
                      <div key={key} className="flex items-center gap-4 px-[var(--space-apple-sm)] py-2.5 bg-[var(--bg-tertiary)]/60 rounded-[var(--radius-Apple-sm)] border border-[var(--border-color)]">
                        <span className="text-xs font-mono text-[var(--text-muted)] w-24 shrink-0">{key}</span>
                        <span className="text-sm text-[var(--text-primary)] flex-1">{String(field.value || '—')}</span>
                        <span className="text-xs text-[var(--text-muted)]">{field.label ?? key}</span>
                        <span className={`text-xs font-mono w-10 text-right ${
                          field.confidence >= 0.8 ? 'text-[var(--color-success-text)] dark:text-[var(--color-success-text)]' : field.confidence >= 0.6 ? 'text-[var(--color-warning-text)] dark:text-[var(--color-warning-text)]' : 'text-[var(--color-error-text)] dark:text-[var(--color-error-text)]'
                        }`}>
                          {(field.confidence * 100).toFixed(0)}%
                        </span>
                      </div>
                    ))}
                    {Object.keys(result.extracted_fields).length === 0 && (
                      <div className="text-center py-4 space-y-1">
                        <p className="text-sm text-[var(--text-muted)]">{t('pages.document.noFields')}</p>
                        <p className="text-xs text-[var(--text-muted)]">{t('pages.document.noFieldsHint')}</p>
                      </div>
                    )}
                  </div>
                </CardContent>
              </Card>
            </div>
          )}
        </div>
      </div>

      {/* 人工复核弹窗：修正低置信度字段 */}
      <Dialog open={reviewOpen} onOpenChange={setReviewOpen}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>{reviewArchiveId != null ? t('pages.document.reviewArchiveTitle', { id: reviewArchiveId }) : t('pages.document.reviewTitle')}</DialogTitle>
            <DialogDescription>{t('pages.document.reviewDesc', { suffix: reviewArchiveId != null ? t('pages.document.reviewDescArchive') : t('pages.document.reviewDescResult') })}</DialogDescription>
          </DialogHeader>
          <div className="max-h-[60vh] overflow-y-auto space-y-2 px-1">
            {result && Object.entries(result.extracted_fields).map(([key, field]: [string, any]) => {
              const low = field.confidence < 0.7
              return (
                <div key={key} className={`flex items-center gap-3 px-3 py-2 rounded-[var(--radius-Apple-sm)] border ${
                  low
                    ? 'border-[var(--color-warning-border)] bg-[var(--color-warning-container)]/40'
                    : 'border-[var(--border-color)] bg-[var(--bg-tertiary)]/40'
                }`}>
                  <div className="w-28 shrink-0">
                    <div className="text-xs font-medium text-[var(--text-primary)]">{field.label ?? key}</div>
                    <div className="text-xs sm:text-[10px] font-mono text-[var(--text-muted)]">{key}</div>
                  </div>
                  <input
                    value={reviewDraft[key] ?? ''}
                    onChange={(e) => setReviewDraft(prev => ({ ...prev, [key]: e.target.value }))}
                    className="flex-1 h-9 min-w-0 px-2 text-sm rounded-[var(--radius-Apple-sm)] border border-[var(--border-color)] bg-[var(--bg-secondary)] text-[var(--text-primary)] focus:outline-none focus-visible:ring-0"
                    aria-label={t('pages.document.reviewFieldAria', { label: field.label ?? key })}
                  />
                  <span className={`text-xs font-mono w-12 text-right shrink-0 ${
                    low ? 'text-[var(--color-warning-text)]' : 'text-[var(--text-muted)]'
                  }`}>
                    {(field.confidence * 100).toFixed(0)}%
                  </span>
                </div>
              )
            })}
          </div>
          <DialogFooter>
            <Button variant="ghost" size="sm" onClick={() => setReviewOpen(false)}>{t('pages.document.cancel')}</Button>
            <Button variant="primary" size="sm" onClick={confirmReview}>{t('pages.document.confirmReview')}</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

/**
 * DOE 实验设计页面 — 完整功能版 * CCD / BBD / 混料 设计矩阵 + 多响应面拟合 + 反向搜索 + 主动学习 + 散点图 *
 * 真实数据链路? *   实验管理(实验ID） /doe/experiments/{id}/runs  → runs(真实参数） 选择响应值 /doe/fit
 *   配方种子          /doe/seed-from-formula/{id}  → runs(成分占比因子+真实响应） /doe/fit
 */
import { useState, useEffect, useMemo } from 'react'
import { useSearchParams } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import {
  Beaker, Plus, Trash2, Play, Search, Sparkles, TrendingUp,
  ChevronRight, FileText, Target, RefreshCw,
  Save, ClipboardList, Eye, EyeOff, Lightbulb,
  FolderInput, Send, FlaskConical, PieChart,
} from 'lucide-react'
import {
  ScatterChart, Scatter, XAxis, YAxis, ZAxis,
  CartesianGrid, Tooltip as RechartsTooltip, ResponsiveContainer,
  Legend,
} from 'recharts'
import { doeApi, type DOEFactor, type DOERun, type FittedModel } from '@/api/doe'
import { useToast } from '@/components/ui/Toast'
import { Card, CardHeader, CardTitle, CardContent, Button, Input, Badge, StatCard } from '@/components/ui'

const STORAGE_KEY = 'rmfood_doe_history'
const loadHistory = () => {
  try { return JSON.parse(localStorage.getItem(STORAGE_KEY) ?? '[]') } catch { return [] }
}
const saveHistory = (items: any[]) => localStorage.setItem(STORAGE_KEY, JSON.stringify(items))

/** 推导 runs 中实际值值出现的响应参数名（response_values 的键*/
const deriveResponseNames = (runs: DOERun[]): string[] => {
  const names = new Set<string>()
  for (const r of runs) {
    if (r.response_values && typeof r.response_values === 'object') {
      for (const k of Object.keys(r.response_values)) names.add(k)
    }
  }
  return Array.from(names)
}

function FactorRow({ factor, index, onChange, onRemove, canRemove }: {
  factor: DOEFactor; index: number
  onChange: (f: DOEFactor) => void
  onRemove: () => void
  canRemove: boolean
}) {
  return (
    <div className="flex items-center gap-[var(--space-apple-sm)] p-[var(--space-apple-sm)] bg-[var(--bg-tertiary)]/70 dark:bg-[var(--bg-tertiary)]/40 rounded-[var(--radius-Apple-sm)] border border-[var(--border-color)]">
      <span className="text-xs font-mono text-[var(--text-muted)] w-6">{index + 1}</span>
      <Input className="flex-1 h-8 text-sm"
        placeholder="因子名称（例如：温度）" value={factor.name}
        onChange={e => onChange({ ...factor, name: e.target.value })} />
      {(['low', 'high', 'center'] as const).map(k => (
        <div key={k} className="flex flex-col items-center gap-1">
          <span className="text-xs text-[var(--text-muted)] uppercase tracking-wide">{k === 'low' ? '低水平 (-1)' : k === 'high' ? '高水平 (+1)' : '中心点 (0)'}</span>
          <Input type="number" step="0.1"
            className="w-20 h-8 text-sm text-center tabular-nums"
            value={factor[k]}
            onChange={e => onChange({ ...factor, [k]: parseFloat(e.target.value) || 0 })} />
        </div>
      ))}
      <button onClick={onRemove} disabled={!canRemove}
        className="p-1.5 rounded-[var(--radius-Apple-sm)] hover:bg-danger-50 dark:hover:bg-danger-950/40 text-[var(--text-muted)] hover:text-danger-500 disabled:opacity-30 transition-colors">
        <Trash2 size={14} />
      </button>
    </div>
  )
}

function MixtureComponentRow({ comp, index, onChange, onRemove }: {
  comp: { name: string; lower: number; upper: number }; index: number
  onChange: (c: { name: string; lower: number; upper: number }) => void
  onRemove: () => void
}) {
  return (
    <div className="flex items-center gap-[var(--space-apple-sm)] p-[var(--space-apple-sm)] bg-[var(--bg-tertiary)]/70 dark:bg-[var(--bg-tertiary)]/40 rounded-[var(--radius-Apple-sm)] border border-[var(--border-color)]">
      <span className="text-xs font-mono text-[var(--text-muted)] w-6">{index + 1}</span>
      <Input className="flex-1 h-8 text-sm"
        placeholder="组分名称（例如：黄芪）" value={comp.name}
        onChange={e => onChange({ ...comp, name: e.target.value })} />
      {(['lower', 'upper'] as const).map(k => (
        <div key={k} className="flex flex-col items-center gap-1">
          <span className="text-xs text-[var(--text-muted)] uppercase tracking-wide">{k === 'lower' ? '下限' : '上限'}</span>
          <Input type="number" step="0.01"
            className="w-20 h-8 text-sm text-center tabular-nums"
            value={comp[k]}
            onChange={e => onChange({ ...comp, [k]: parseFloat(e.target.value) || 0 })} />
        </div>
      ))}
      <button onClick={onRemove} className="p-1.5 rounded-[var(--radius-Apple-sm)] hover:bg-danger-50 dark:hover:bg-danger-950/40 text-[var(--text-muted)] hover:text-danger-500 transition-colors">
        <Trash2 size={14} />
      </button>
    </div>
  )
}

function ResponseInputTable({ runs, factors, values, onChange, autoFill }: {
  runs: DOERun[]
  factors: DOEFactor[]
  values: Record<number, number>
  onChange: (runId: number, v: number) => void
  autoFill?: (run: DOERun) => number | null
}) {
  const factorNames = factors.map(f => f.name)
  return (
    <div className="overflow-x-auto">
      <table className="w-full text-xs">
        <thead>
          <tr className="border-b border-[var(--border-color)] text-[var(--text-muted)]">
            <th className="pb-2 pr-2 text-left w-10">#</th>
            {factorNames.map(name => <th key={name} className="pb-2 px-2 text-center min-w-[80px]">{name}</th>)}
            <th className="pb-2 px-2 text-center min-w-[100px]">响应值?y)</th>
          </tr>
        </thead>
        <tbody>
          {runs.map(run => {
            const shown = values[run.run_id] ?? (autoFill ? autoFill(run) : undefined)
            return (
              <tr key={run.run_id} className="border-b border-[var(--border-color)] hover:bg-[var(--bg-tertiary)] dark:hover:bg-[var(--bg-tertiary)]/50">
                <td className="py-2 pr-2 text-[var(--text-muted)] font-mono">{run.run_id}</td>
                {factorNames.map(name => (
                  <td key={name} className="py-2 px-2 text-center font-mono text-[var(--text-secondary)] tabular-nums">
                    {((run.factor_levels?.[name] ?? run.coded_levels?.[name] ?? 0) as number).toFixed(2)}
                  </td>
                ))}
                <td className="py-2 px-2">
                  <Input type="number" step="0.01" value={shown ?? ''}
                    onChange={e => onChange(run.run_id, parseFloat(e.target.value) || 0)}
                    placeholder="输入响应值"
                    className="h-7 w-full text-center tabular-nums" />
                </td>
              </tr>
            )
          })}
        </tbody>
      </table>
    </div>
  )
}

function ScatterPlot({ runs, factors, values }: {
  runs: DOERun[]
  factors: DOEFactor[]
  values: Record<number, number>
}) {
  if (factors.length < 2) return null
  const f1 = factors[0].name
  const f2 = factors[1].name
  const scatterData = runs.filter(r => values[r.run_id] != null).map(r => ({
    x: (r.coded_levels?.[f1] ?? r.factor_levels?.[f1] ?? 0),
    y: (r.coded_levels?.[f2] ?? r.factor_levels?.[f2] ?? 0),
    z: values[r.run_id] ?? 0,
    run_id: r.run_id,
    f1_val: (r.factor_levels?.[f1] ?? r.coded_levels?.[f1] ?? 0),
    f2_val: (r.factor_levels?.[f2] ?? r.coded_levels?.[f2] ?? 0),
  }))
  if (scatterData.length < 3) {
    return (
      <div className="h-56 flex items-center justify-center text-[var(--text-muted)] text-sm bg-[var(--bg-tertiary)]/50 rounded-[var(--radius-Apple-md)]">
        请输入至少组响应值以生成分散图      </div>
    )
  }
  return (
    <div className="h-72">
      <ResponsiveContainer width="100%" height="100%">
        <ScatterChart margin={{ top: 10, right: 20, bottom: 10, left: 10 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="var(--border-color, rgba(148,163,184,0.12))" opacity={0.35} />
          <XAxis type="number" dataKey="x" name={f1} tick={{ fontSize: 12, fill: 'var(--text-muted)' }} axisLine={{ stroke: 'var(--border-color)' }} tickLine={{ stroke: 'var(--border-color)' }} label={{ value: f1, position: 'bottom', offset: 0, fontSize: 12, fill: 'var(--text-muted)' }} />
          <YAxis type="number" dataKey="y" name={f2} tick={{ fontSize: 12, fill: 'var(--text-muted)' }} axisLine={{ stroke: 'var(--border-color)' }} tickLine={{ stroke: 'var(--border-color)' }} label={{ value: f2, angle: -90, position: 'left', offset: 0, fontSize: 12, fill: 'var(--text-muted)' }} />
          <ZAxis type="number" dataKey="z" range={[60, 400]} name="响应值" />
          <RechartsTooltip
            content={({ active, payload }) => {
              if (!active || !payload?.[0]) return null
              const d = payload[0].payload as any
              return (
                <div className="bg-card border border-[var(--border-color)] rounded-[var(--radius-Apple-sm)] p-2 text-xs shadow-lg">
                  <div className="font-semibold mb-1">第#{d.run_id} 组</div>
                  <div>{f1}: {d.f1_val.toFixed(2)}</div>
                  <div>{f2}: {d.f2_val.toFixed(2)}</div>
                  <div className="text-[var(--color-primary-text)] font-bold">响应值 {d.z.toFixed(2)}</div>
                </div>
              )
            }}
          />
          <Legend />
          <Scatter name="散点" data={scatterData} fill="var(--color-primary, #10b981)" fillOpacity={0.7} />
        </ScatterChart>
      </ResponsiveContainer>
      <p className="text-xs text-[var(--text-muted)] text-center mt-1">
        气泡大小 = 响应值· X值= {f1} · Y值= {f2}
      </p>
    </div>
  )
}

export default function DoePage() {
  const { t } = useTranslation()
  const { addToast } = useToast()
  const [searchParams, setSearchParams] = useSearchParams()
  const [activeTab, setActiveTab] = useState<'design' | 'fit' | 'search' | 'active'>('design')
  const [factors, setFactors] = useState<DOEFactor[]>([
    { name: '温度', low: 60, high: 100, center: 80 },
    { name: '时间', low: 10, high: 60, center: 35 },
  ])
  // 混料组分
  const [mixtureComponents, setMixtureComponents] = useState<Array<{ name: string; lower: number; upper: number }>>([
    { name: '组分A', lower: 0, upper: 1 },
    { name: '组分B', lower: 0, upper: 1 },
    { name: '组分C', lower: 0, upper: 1 },
  ])
  const [mixtureDesignType, setMixtureDesignType] = useState<'lattice' | 'centroid'>('lattice')
  const [mixtureDegree, setMixtureDegree] = useState(2)
  const [designResult, setDesignResult] = useState<null | { type: string; runs: DOERun[]; notes: string }>(null)
  const [showResponseInput, setShowResponseInput] = useState(false)
  const [responseValues, setResponseValues] = useState<Record<number, number>>({})
  const [fittingRuns, setFittingRuns] = useState<DOERun[]>([])
  const [fitResult, setFitResult] = useState<FittedModel[] | null>(null)
  const [targetValue, setTargetValue] = useState('')
  const [searchResult, setSearchResult] = useState<any>(null)
  const [activeLearningResult, setActiveLearningResult] = useState<any[]>([])
  const [activeStrategy, setActiveStrategy] = useState<string>('')
  const [expIdInput, setExpIdInput] = useState('')
  const [respParamInput, setRespParamInput] = useState('')
  const [importedMeta, setImportedMeta] = useState<null | { expId: number; totalRuns: number; factors: string[]; responseCandidates: string[] }>(null)
  // 配方种子
  const [seedFormulas, setSeedFormulas] = useState<Array<{ id: number; name: string }>>([])
  const [seedFormulaId, setSeedFormulaId] = useState('')
  const [seedRespParam, setSeedRespParam] = useState('感官评分')
  const [seedExpId, setSeedExpId] = useState('')
  const [seedMeta, setSeedMeta] = useState<null | {
    formulaId: number; formulaName: string; totalRuns: number; responseParam: string
    experimentId: number | null; responsePool: number[]
  }>(null)
  // 拟合响应参数选择（默认'y'，可改为真实参数名）
  const [fitResponseParam, setFitResponseParam] = useState('y')
  // P2-1：记录用户是否手动改过响应参数；一旦手动改过，不再被自动切换覆盖
  const [respParamTouched, setRespParamTouched] = useState(false)
  const [loading, setLoading] = useState(false)
  const [history, setHistory] = useState<any[]>(loadHistory)
  const [showHistory, setShowHistory] = useState(false)

  // 从 fittingRuns → response_values 自动推导可用响应参数
  const responseCandidates = useMemo(() => deriveResponseNames(fittingRuns), [fittingRuns])

  // 当 fittingRuns 变化时，自动把默认响应参数切到首个真实参数（P2-1 修复：仅当用户没有手动改过 respParamTouched=false 时才自动切换，尊重用户选择）
  useEffect(() => {
    if (!respParamTouched && responseCandidates.length > 0 && fitResponseParam === 'y') {
      setFitResponseParam(responseCandidates[0])
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [responseCandidates])

  // 加载真实配方列表（供"从配方生成种子"下拉框）
  useEffect(() => {
    let cancelled = false
    doeApi.listSeedFormulas().then((body: any) => {
      if (cancelled) return
      const imp = body?.data ?? body
      const list = Array.isArray(imp?.formulas) ? imp.formulas : []
      setSeedFormulas(list)
      if (import.meta.env.DEV) console.log('[DOE] listSeedFormulas total', imp?.total, 'recipes', list.length)
      if (list.length === 0) {
        addToast({ type: 'warning', message: `配方列表为空（API 返回 total=${imp?.total ?? '?'})，请确认 /doe/formulas 端点正常` })
      }
    }).catch((e: any) => {
      if (cancelled) return
      if (import.meta.env.DEV) console.warn('[DOE] listSeedFormulas failed', e?.response?.status, e?.response?.data ?? e)
      addToast({ type: 'error', message: `加载配方列表失败 ${e?.response?.status ?? e?.message}` })
    })
    return () => { cancelled = true }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  /**
   * → runs 的某个真实响应参数映射成后端 /fit 能识别的 response_values。
   * - 手动 'y' 模式：run.response_values = { y: responseValues[run.run_id] }
   */
  const buildFittingPayload = (respParam: string) => {
    const manual = respParam === 'y'
    const payload = fittingRuns.map(run => {
      const raw = run.response_values ?? {}
      let v: number | null = null
      if (manual) {
        v = responseValues[run.run_id] != null ? responseValues[run.run_id] : null
      } else {
        v = raw[respParam] != null ? raw[respParam] : null
      }
      return {
        ...run,
        response_values: v != null ? { [respParam]: v } : null,
      }
    }).filter(r => r.response_values != null)
    return payload
  }

  // 从真实配方生成种子runs →回填因子 + 拟合队列
  const handleSeedFromFormula = () => {
    const fid = parseInt(seedFormulaId, 10)
    if (!fid) { addToast({ type: 'warning', message: '请选择至少一个配方' }); return }
    setLoading(true)
    ;(async () => {
      try {
        // P0-1：把 seedExpId 传给后端 →按该实验真实数据点取响应值（pool 循环使用）
        const expId = seedExpId ? parseInt(seedExpId, 10) : undefined
        const body: any = await doeApi.seedFromFormula(fid, {
          n_center: 2,
          response_parameter: seedRespParam || undefined,
          experiment_id: expId,
        })
        const imp = body?.data ?? body
        const runs: DOERun[] = imp.runs ?? []
        if (runs.length === 0) {
          addToast({ type: 'warning', message: '该配方无法生成种子（有效成分不足 2 个）' })
          return
        }
        setFittingRuns(runs)
        setFactors((imp.factors ?? []).map((f: any) => ({ name: f.name, low: f.low, high: f.high, center: f.center })))
        // P0-1：seedMeta 携带 experimentId主动学习闭环可写回该实验
        setSeedMeta({
          formulaId: fid,
          formulaName: imp.formula?.name ?? `配方 ${fid}`,
          totalRuns: runs.length,
          responseParam: imp.response_parameter ?? '感官评分',
          experimentId: imp.experiment_id ?? expId ?? null,
          responsePool: imp.response_pool ?? [],
        })
        // 自动把拟合响应参数指向种子真实响应值
        const firstResp = Object.keys(runs[0]?.response_values ?? {})
        if (firstResp.length > 0) setFitResponseParam(firstResp[0])
        const pool = imp.response_pool ?? []
        const poolNote = pool.length > 1 ? `，响应池 ${pool.length} 个不同真实响应` : ''
        addToast({ type: 'success', message: `已用真实配方{imp.formula?.name}」生成${runs.length} 组种子（响应：{imp.response_parameter}${poolNote}）` })
        setActiveTab('fit')
      } catch (e: any) {
        addToast({ type: 'error', message: e?.response?.data?.detail ?? String(e) })
      } finally {
        setLoading(false)
      }
    })()
  }

    // 从实验管理跳转进来时（doe?exp=12）自动填入实验ID 并导入
  useEffect(() => {
    const expParam = searchParams.get('exp')
    if (expParam) {
      setExpIdInput(expParam)
      handleImportFromExperiment(expParam)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // 从实验管理导入数据自动填充因子 + 拟合队列
  const handleImportFromExperiment = (expIdOverride?: string) => {
    const expIdRaw = expIdOverride ?? expIdInput
    const expId = parseInt(expIdRaw, 10)
    if (!expId) { addToast({ type: 'warning', message: '请输入实验ID' }); return }
    setLoading(true)
    ;(async () => {
      try {
        const imp: any = await doeApi.importExperimentRuns(expId, respParamInput ? { response_parameter: respParamInput } : undefined)
        const runs: DOERun[] = imp?.runs ?? []
        if (runs.length === 0) {
          addToast({ type: 'warning', message: '该实验暂无可导入的运行（数据点为空或无时间戳）' })
          return
        }
        const factorNames = (imp.factors ?? []).map((f: any) => f.name)
        setFittingRuns(runs)
        if (imp.factors?.length) {
          setFactors((imp.factors ?? []).map((f: any) => ({ name: f.name, low: f.low, high: f.high, center: f.center })))
        }
        const respCands: string[] = imp.response_candidates ?? []
        setImportedMeta({ expId, totalRuns: runs.length, factors: factorNames, responseCandidates: respCands })
        // 自动把拟合响应参数指向导入的真实响应
        if (respCands.length > 0) setFitResponseParam(respCands[0])
        addToast({ type: 'success', message: `已导入 ${runs.length} 组运行（实验 ${expId}，响应候选 ${respCands.length} 个）` })
        setActiveTab('fit')
        if (expIdOverride && searchParams.get('exp')) {
          setSearchParams({}, { replace: true })
        }
      } catch (e: any) {
        addToast({ type: 'error', message: e?.response?.data?.detail ?? String(e) })
      } finally {
        setLoading(false)
      }
    })()
  }

  // 把主动学习推荐写回实验管理（闭环）  // P0-1：支持两种来源 — 实验导入(importedMeta) 或 配方种子(seedMeta.experimentId)
  const closeLoopExpId = importedMeta?.expId ?? seedMeta?.experimentId ?? null
  const handleExportRecommendations = async () => {
    if (activeLearningResult.length === 0) { addToast({ type: 'warning', message: '暂无可导出的推荐点' }); return }
    const targetExp = closeLoopExpId
    if (!targetExp) {
      addToast({ type: 'warning', message: importedMeta
        ? '实验导入来源缺少 expId'
        : '请先在从实验导入数据，或在配方种子中填写实验ID 再导出推荐点' })
      return
    }
    setLoading(true)
    try {
      const body: any = await doeApi.exportToExperiment({
        experiment_id: targetExp,
        recommendations: activeLearningResult,
        note: `strategy=${activeStrategy || 'auto'}${seedMeta?.formulaName ? ` seed=${seedMeta.formulaName}` : ''}`,
      })
      const imp = body?.data ?? body
      addToast({ type: 'success', message: `已写回 ${imp.created_data_points ?? 0} 个数据点到实验 ${targetExp}` })
    } catch (e: any) {
      addToast({ type: 'error', message: e?.response?.data?.detail ?? String(e) })
    } finally {
      setLoading(false)
    }
  }

  const handleActiveLearning = async () => {
    if (fittingRuns.length === 0) { addToast({ type: 'warning', message: '请先在在拟合队列中添加加实验数据' }); return }
    setLoading(true)
    try {
      const res: any = await doeApi.activeLearning({
        existing_runs: fittingRuns.map(r => ({
          run_id: r.run_id,
          coded_levels: r.coded_levels ?? {},
          factor_levels: r.factor_levels ?? {},
          response_values: r.response_values ?? {},
        })),
        n_recommend: 3,
        fitted_model: fitResult?.[0] ?? undefined,
      })
      const imp = res?.data ?? res
      const recs = imp.recommendations ?? []
      setActiveLearningResult(recs)
      setActiveStrategy(imp.strategy ?? '')
      addToast({ type: 'success', message: `已推荐${recs.length} 组新实验验点（策略{imp.strategy ?? 'default'}）` })
    } catch (e: any) {
      addToast({ type: 'error', message: e?.response?.data?.detail ?? String(e) })
    } finally {
      setLoading(false)
    }
  }

  const addFactor = () => setFactors([...factors, { name: '', low: 0, high: 100, center: 50 }])
  const removeFactor = (i: number) => setFactors(factors.filter((_, idx) => idx !== i))
  const updateFactor = (i: number, f: DOEFactor) => { const n = [...factors]; n[i] = f; setFactors(n) }
  const updateResponseValue = (runId: number, v: number) => setResponseValues(prev => ({ ...prev, [runId]: v }))

  const addMixtureComponent = () => setMixtureComponents([...mixtureComponents, { name: `组分${String.fromCharCode(65 + mixtureComponents.length)}`, lower: 0, upper: 1 }])
  const removeMixtureComponent = (i: number) => setMixtureComponents(mixtureComponents.filter((_, idx) => idx !== i))
  const updateMixtureComponent = (i: number, c: { name: string; lower: number; upper: number }) => {
    const n = [...mixtureComponents]; n[i] = c; setMixtureComponents(n)
  }

  const handleGenerate = async (type: 'ccd' | 'bbd') => {
    if (factors.length < 2) { addToast({ type: 'warning', message: '请至少添加 2 个因子' }); return }
    setLoading(true)
    try {
      const res = await doeApi[type === 'ccd' ? 'generateCCD' : 'generateBBD']({ factors, n_center_points: Math.max(6, factors.length * 2) })
      const data = res.data?.data ?? res.data
      setDesignResult({ type, runs: data.runs ?? [], notes: data.notes ?? '' })
      setFittingRuns(data.runs ?? []); setResponseValues({}); setShowResponseInput(false); setSearchResult(null)
      addToast({ type: 'success', message: `已生成${data.total_runs} 组实验设计` })
    } catch (e: any) { addToast({ type: 'error', message: e?.response?.data?.detail ?? String(e) }) }
    finally { setLoading(false) }
  }

  const handleGenerateMixture = async () => {
    if (mixtureComponents.length < 2) { addToast({ type: 'warning', message: '混料设计至少需要 2 个组分' }); return }
    setLoading(true)
    try {
      const res = await doeApi.generateMixture({
        components: mixtureComponents.map(c => ({ name: c.name, lower: Math.min(c.lower, c.upper), upper: Math.max(c.lower, c.upper) })),
        design_type: mixtureDesignType,
        degree: mixtureDesignType === 'lattice' ? mixtureDegree : 3,
      })
      const data = res.data?.data ?? res.data
      setDesignResult({ type: `mixture_${mixtureDesignType}`, runs: data.runs ?? [], notes: data.notes ?? '' })
      setFittingRuns(data.runs ?? []); setResponseValues({}); setShowResponseInput(false); setSearchResult(null)
      addToast({ type: 'success', message: `已生成${data.total_runs} 组混料设计` })
    } catch (e: any) {
      addToast({ type: 'error', message: e?.response?.data?.detail ?? String(e) })
    } finally {
      setLoading(false)
    }
  }

  const handleFit = async () => {
    // P0-2 修复：保留真实响应名。后端 /fit 接受任意 response_names，模型 responses/equation/coefficients/r_squared 都会用该真实参数名（不再使用 'y'）
    const runsWithResponses = buildFittingPayload(fitResponseParam)
    if (runsWithResponses.length < 2) {
    addToast({ type: 'warning', message: `至少需要 2 组带响应值(${fitResponseParam})的实验才能拟合` })
      return
    }
    setLoading(true)
    try {
      const res = await doeApi.fitResponseSurface({
        runs: runsWithResponses,
      response_names: [fitResponseParam],  // 真实参数名（如 "感官评分"），而非 'y'
        include_interaction: true,
        include_quadratic: true,
      })
      const models = res.data?.models ?? res.data
      setFitResult(models); setSearchResult(null)
      const r2 = models?.[0]?.r_squared?.[fitResponseParam] ?? 0
      addToast({ type: 'success', message: `拟合「${fitResponseParam}」完成，R² = ${Number(r2).toFixed(4)}` })
    } catch (e: any) { addToast({ type: 'error', message: e?.response?.data?.detail ?? String(e) }) }
    finally { setLoading(false) }
  }
  const handleSearch = async () => {
    if (!fitResult?.length || !fitResult[0]) { addToast({ type: 'warning', message: '请先在「响应面拟合」标签页执行模型拟合' }); return }
    setLoading(true)
    try {
      // 把因子实际值单位范围(low/high)传给后端 → 反解回实际值
      const factor_bounds: Record<string, [number, number]> = {}
      for (const f of factors) factor_bounds[f.name] = [f.low, f.high]
      // P0-2：target_values 用真实响应名（与 fit 的 response_names 一致），模型才能匹配
      const targetKey = fitResponseParam
      const res: any = await doeApi.inverseSearch({
        model: fitResult[0],
        target_values: { [targetKey]: parseFloat(targetValue) || 50 },
        factor_bounds,
      })
      const data = res.data ?? res
      setSearchResult(data)
      addToast({ type: 'success', message: data.converged ? '反向搜索已收敛' : '搜索未收敛，结果可能不精确（仅供参考）' })
    } catch (e: any) { addToast({ type: 'error', message: String(e) }) }
    finally { setLoading(false) }
  }

  const handleSaveDesign = () => {
    if (!designResult) return
    const item = { id: Date.now(), type: designResult.type.toUpperCase(), factors: factors.map(f => f.name), runs: designResult.runs.length, date: new Date().toLocaleDateString() }
    const newHistory = [item, ...history].slice(0, 20)
    setHistory(newHistory); saveHistory(newHistory)
    addToast({ type: 'success', message: '设计已保存到历史记录' })
  }

  /** 一键把整张设计矩阵加入拟合队列（去重），并跳到拟合标签页 */
  const handleAddAllToFitting = () => {
    if (!designResult) return
    const existing = new Set(fittingRuns.map(r => r.run_id))
    const newRuns = designResult.runs.filter(r => !existing.has(r.run_id))
    if (newRuns.length === 0) {
      addToast({ type: 'info', message: '该设计的所有组均已在拟合队列中' })
      return
    }
    setFittingRuns(prev => [...prev, ...newRuns])
    setActiveTab('fit')
    addToast({ type: 'success', message: `已将 ${newRuns.length} 组设计加入拟合队列（跳过 ${designResult.runs.length - newRuns.length} 组已存在）` })
  }

  // 当前要展示的响应参数名（用于 fit 结果 R² 标签）
  const displayRespName = fitResponseParam

  return (
    <div className="min-h-screen">
      <div className="max-w-[1600px] mx-auto px-[var(--space-apple-md)] sm:px-6 lg:px-8 py-[var(--space-apple-lg)] space-y-[var(--space-apple-md)]">
      {/* 页头横幅 — 对齐 Dashboard 品牌横幅规范 */}
      <div className="surface-primary rounded-[var(--radius-Apple-md)] p-[var(--space-apple-lg)] shadow-sm">
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
          <div className="flex-1">
            <h1 className="text-xl font-semibold leading-snug tracking-tight flex items-center gap-2">
              <Beaker size={20} className="text-white/80 shrink-0" />
              {t('pages.doe.title')}
            </h1>
            <p className="mt-1 text-white/80 text-sm">{t('pages.doe.subtitle')}</p>
          </div>
          {history.length > 0 && (
            <button onClick={() => setShowHistory(!showHistory)}
              className="flex items-center gap-1.5 px-[var(--space-apple-sm)] py-1.5 min-h-[44px] text-xs font-medium bg-[var(--bg-secondary)]/15 hover:bg-[var(--bg-secondary)]/25 rounded-[var(--radius-pill)] transition-colors">
              <ClipboardList size={12} />{t('pages.doe.history', { count: history.length })}
            </button>
          )}
        </div>
      </div>

      {/* 历史记录 */}
      {showHistory && history.length > 0 && (
        <Card>
          <CardContent className="p-[var(--space-apple-md)]">
              <div className="text-xs font-semibold text-[var(--text-muted)] mb-2 uppercase tracking-wide">{t('pages.doe.recentDesigns')}</div>
            <div className="flex gap-2 flex-wrap">
              {history.map(h => (
                <div key={h.id} className="flex items-center gap-2 px-[var(--space-apple-sm)] py-1.5 bg-[var(--bg-tertiary)]/60 rounded-[var(--radius-Apple-sm)] text-xs">
                  <span className="font-mono text-[var(--color-primary-text)]">{h.type}</span>
                  <span className="text-[var(--text-muted)]">{h.factors.join('×')}</span>
                    <span className="text-[var(--text-muted)]">{t('pages.doe.runsCount', { count: h.runs })}</span>
                  <span className="text-[var(--text-muted)]">{h.date}</span>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}

      {/* 实验管理 → DOE 导入DOE 导入 */}
      <Card className="border-[var(--color-primary-border)] dark:border-[var(--color-primary)]/60">
        <CardHeader className="px-5 pt-5 pb-3">
          <CardTitle as="h3" className="text-sm font-semibold flex items-center gap-2">
            <FolderInput size={14} className="text-[var(--color-primary-text)]0 dark:text-[var(--color-primary-text)]" />
            <span className="text-[var(--color-primary-text)]">{t('pages.doe.importFromExperiment')}</span>
            <span className="text-xs font-normal text-[var(--text-muted)] ml-1">{t('pages.doe.importFromExperimentDesc')}</span>
          </CardTitle>
        </CardHeader>
        <CardContent className="px-5 pb-5 pt-0">
          <div className="flex flex-wrap items-center gap-[var(--space-apple-sm)]">
            <Input value={expIdInput} onChange={e => setExpIdInput(e.target.value)}
              placeholder={t('pages.doe.expIdPlaceholder')} className="w-32 h-9 text-sm" />
            <Input value={respParamInput} onChange={e => setRespParamInput(e.target.value)}
                  placeholder={t('pages.doe.respParamPlaceholder')} className="w-48 h-9 text-sm" />
            <Button onClick={() => handleImportFromExperiment()} disabled={loading}
              icon={<FolderInput size={14} />}>{t('pages.doe.import')}</Button>
            {importedMeta && (
                  <span className="text-xs text-[var(--text-muted)]">{t('pages.doe.importedMeta', { id: importedMeta.expId, runs: importedMeta.totalRuns, candidates: importedMeta.responseCandidates.join(', ') })}</span>
            )}
          </div>
        </CardContent>
      </Card>

        {/* 配方 → DOE 种子生成（真实配方成分占比，非模拟） */}
      <Card>
        <CardHeader className="px-5 pt-5 pb-3">
          <CardTitle as="h3" className="text-sm font-semibold flex items-center gap-2">
            <FlaskConical size={14} className="text-[var(--color-secondary-text)]0 dark:text-[var(--color-secondary-text)]" />
            <span className="text-[var(--color-secondary-text)] dark:text-[var(--color-secondary-text)]">{t('pages.doe.seedFromFormula')}</span>
            <span className="text-xs font-normal text-[var(--text-muted)] ml-1">{t('pages.doe.seedFromFormulaDesc')}</span>
          </CardTitle>
        </CardHeader>
        <CardContent className="px-5 pb-5 pt-0">
          <div className="flex flex-wrap items-center gap-[var(--space-apple-sm)]">
            <Button variant="outline" onClick={() => doeApi.listSeedFormulas().then((body: any) => {
              const imp = body?.data ?? body
              setSeedFormulas(Array.isArray(imp?.formulas) ? imp.formulas : [])
      if (import.meta.env.DEV) console.log('[DOE] 重新加载配方', imp?.formulas?.length ?? 0)
            }).catch((e: any) => {
              if (import.meta.env.DEV) console.warn('[DOE] 重新加载配方失败', e?.response?.status, e?.response?.data ?? e)
              addToast({ type: 'error', message: `重新加载配方失败 ` })
            })}
              className="text-xs"
              icon={<RefreshCw size={12} />}>{t('pages.doe.reloadFormulas')}</Button>
            <select value={seedFormulaId} onChange={e => setSeedFormulaId(e.target.value)}
              className="w-44 h-9 px-[var(--space-apple-sm)] text-sm rounded-[var(--radius-Apple-sm)] border border-input bg-transparent text-[var(--text-primary)] shadow-sm focus:outline-none focus:ring-1 focus:ring-ring">
              <option value="">{t('pages.doe.selectFormula')}</option>
              {seedFormulas.map(f => (
                <option key={f.id} value={f.id}>{f.name}（{f.id}）</option>
              ))}
            </select>
            <Input value={seedRespParam} onChange={e => setSeedRespParam(e.target.value)}
              placeholder={t('pages.doe.respParamDefault')} className="w-48 h-9 text-sm" />
            <Input value={seedExpId} onChange={e => setSeedExpId(e.target.value)}
              placeholder={t('pages.doe.expIdOptional')} className="w-40 h-9 text-sm" />
            <Button variant="secondary" onClick={handleSeedFromFormula} disabled={loading || !seedFormulaId}
              icon={<FlaskConical size={14} />}>{t('pages.doe.generateSeed')}</Button>
            {seedMeta && (
              <span className="text-xs text-[var(--text-muted)]">
                {t('pages.doe.seedMeta', { name: seedMeta.formulaName, runs: seedMeta.totalRuns, resp: seedMeta.responseParam })}
                {seedMeta.responsePool?.length > 1 ? t('pages.doe.responsePool', { count: seedMeta.responsePool.length }) : ''}
              </span>
            )}
          </div>
          {seedFormulas.length === 0 && (
                <div className="mt-2 text-xs text-[var(--text-muted)]">{t('pages.doe.noSeedFormulas')}</div>
          )}
        </CardContent>
      </Card>

      {/* 标签对齐设计系统 Apple Segmented Control 规范 */}
      <div className="mt-[var(--space-apple-md)]">
      <div className="tabs-list w-fit">
        {[
          { key: 'design' as const, label: t('pages.doe.tabDesign'), icon: Play },
          { key: 'fit' as const, label: t('pages.doe.tabFit'), icon: TrendingUp },
          { key: 'search' as const, label: t('pages.doe.tabSearch'), icon: Search },
          { key: 'active' as const, label: t('pages.doe.tabActive'), icon: Lightbulb },
        ].map(tab => (
          <button key={tab.key} onClick={() => setActiveTab(tab.key)}
            className={`tabs-trigger ${activeTab === tab.key ? 'tabs-trigger-active' : ''}`}>
            <span className="icon"><tab.icon size={14} /></span>
            {tab.label}
          </button>
        ))}
      </div>
      </div>

      <div className="mt-6 space-y-6">
        {/* 实验设计标签 */}
        {activeTab === 'design' && (
          <div className="space-y-6">
            {/* 因子设置 */}
            <Card>
              <CardHeader className="px-5 pt-5 pb-3">
                <div className="flex items-center justify-between">
                  <CardTitle as="h2" className="text-sm font-semibold flex items-center gap-2">
                    <Plus size={14} className="text-[var(--color-primary-text)]0 dark:text-[var(--color-primary-text)]" />{t('pages.doe.factorSettings')}
                  </CardTitle>
                  <Button variant="outline" size="sm" onClick={addFactor} icon={<Plus size={12} />} className="text-xs">{t('pages.doe.addFactor')}</Button>
                </div>
              </CardHeader>
              <CardContent className="px-5 pb-5 pt-0 space-y-2">
                <div className="flex items-center gap-[var(--space-apple-sm)] px-[var(--space-apple-sm)] py-1.5 text-xs text-[var(--text-muted)] uppercase tracking-wider">
                  <span className="w-6">#</span><span className="flex-1">{t('pages.doe.factorName')}</span>
                  <span className="w-20 text-center">{t('pages.doe.lowLevel')}</span>
                  <span className="w-20 text-center">{t('pages.doe.highLevel')}</span>
                  <span className="w-20 text-center">{t('pages.doe.centerPoint')}</span>
                  <span className="w-8" />
                </div>
                {factors.map((f, i) => (
                  <FactorRow key={i} factor={f} index={i} onChange={v => updateFactor(i, v)} onRemove={() => removeFactor(i)} canRemove={factors.length > 2} />
                ))}
              </CardContent>
            </Card>

            {/* 混料设计设置 */}
            <Card className="border-[var(--color-secondary-border)] dark:border-[var(--color-secondary)]/60">
              <CardHeader className="px-5 pt-5 pb-3">
                <div className="flex items-center justify-between">
                  <CardTitle as="h2" className="text-sm font-semibold flex items-center gap-2">
                    <PieChart size={14} className="text-[var(--color-secondary-text)]0 dark:text-[var(--color-secondary-text)]" />{t('pages.doe.mixtureDesign')}
                  </CardTitle>
                  <Button variant="outline" size="sm" onClick={addMixtureComponent} icon={<Plus size={12} />} className="text-xs">{t('pages.doe.addComponent')}</Button>
                </div>
              </CardHeader>
              <CardContent className="px-5 pb-5 pt-0 space-y-[var(--space-apple-md)]">
                <div className="space-y-2">
                  <div className="flex items-center gap-[var(--space-apple-sm)] px-[var(--space-apple-sm)] py-1.5 text-xs text-[var(--text-muted)] uppercase tracking-wider">
                    <span className="w-6">#</span><span className="flex-1">{t('pages.doe.componentName')}</span>
                    <span className="w-20 text-center">{t('pages.doe.lowerLimit')}</span>
                    <span className="w-20 text-center">{t('pages.doe.upperLimit')}</span>
                    <span className="w-8" />
                  </div>
                  {mixtureComponents.map((c, i) => (
                    <MixtureComponentRow key={i} comp={c} index={i} onChange={v => updateMixtureComponent(i, v)} onRemove={() => removeMixtureComponent(i)} />
                  ))}
                </div>
                <div className="flex flex-wrap items-center gap-4">
                  <div className="flex items-center gap-2 text-xs">
                    <span className="text-[var(--text-muted)]">{t('pages.doe.designType')}</span>
                    <select value={mixtureDesignType} onChange={e => setMixtureDesignType(e.target.value as any)}
                      className="h-8 px-2 text-xs rounded-[var(--radius-Apple-sm)] border border-input bg-transparent text-[var(--text-primary)] shadow-sm focus:outline-none focus:ring-1 focus:ring-ring">
                      <option value="lattice">{t('pages.doe.lattice')}</option>
                      <option value="centroid">{t('pages.doe.centroid')}</option>
                    </select>
                  </div>
                  {mixtureDesignType === 'lattice' && (
                    <div className="flex items-center gap-2 text-xs">
                      <span className="text-[var(--text-muted)]">{t('pages.doe.degree')}</span>
                      <select value={mixtureDegree} onChange={e => setMixtureDegree(parseInt(e.target.value, 10))}
                        className="h-8 px-2 text-xs rounded-[var(--radius-Apple-sm)] border border-input bg-transparent text-[var(--text-primary)] shadow-sm focus:outline-none focus:ring-1 focus:ring-ring">
                        <option value={2}>{t('pages.doe.degree2')}</option>
                        <option value={3}>{t('pages.doe.degree3')}</option>
                      </select>
                    </div>
                  )}
                </div>
              </CardContent>
            </Card>

            {/* 生成按钮 */}
            <div className="flex flex-wrap gap-[var(--space-apple-sm)]">
              <Button onClick={() => handleGenerate('ccd')} disabled={loading}
                icon={<Play size={14} />}>{t('pages.doe.generateCCD')}</Button>
              <Button variant="secondary" onClick={() => handleGenerate('bbd')} disabled={loading}
                icon={<Play size={14} />}>{t('pages.doe.generateBBD')}</Button>
              <Button variant="outline" onClick={handleGenerateMixture} disabled={loading}
                icon={<PieChart size={14} />}>{t('pages.doe.generateMixture')}</Button>
              {designResult && <Button variant="ghost" onClick={handleSaveDesign}
                icon={<Save size={14} />}>{t('pages.doe.saveDesign')}</Button>}
            </div>

            {/* 设计结果 */}
            {designResult && (
              <Card>
                <CardHeader className="px-5 pt-5 pb-3">
                  <div className="flex items-center justify-between">
                    <CardTitle as="h3" className="text-sm font-semibold flex items-center gap-2">
                      <Sparkles size={14} className="text-[var(--color-primary-text)]0 dark:text-[var(--color-primary-text)]" />
                      {designResult.type.toUpperCase()} 设计矩阵
                    </CardTitle>
                    <div className="flex items-center gap-2">
                    <Badge variant="neutral" size="sm">{designResult.runs.length} 组</Badge>
                      <Button size="sm" onClick={handleAddAllToFitting}
                        icon={<TrendingUp size={12} />} className="text-xs">
                        全部加入拟合
                      </Button>
                      <Button variant="outline" size="sm" onClick={() => setShowResponseInput(!showResponseInput)}
                        icon={showResponseInput ? <EyeOff size={12} /> : <Eye size={12} />} className="text-xs">
                        {showResponseInput ? '收起响应输入' : '输入响应值'}
                      </Button>
                    </div>
                  </div>
                </CardHeader>
                <CardContent className="px-5 pb-5 pt-0 space-y-[var(--space-apple-md)]">
                  {designResult.notes && <p className="text-xs text-[var(--text-muted)] px-1">{designResult.notes}</p>}

                  {/* 响应值输出*/}
                  {showResponseInput && (
                    <div className="p-[var(--space-apple-sm)] bg-[var(--color-primary-container)] dark:bg-[var(--color-primary-container)]/20 rounded-[var(--radius-Apple-sm)] border border-[var(--color-primary-border)] dark:border-primary-900">
                    <div className="text-xs font-semibold text-[var(--color-primary-text)] mb-2">请输入实验响应值（y）</div>
                      <ResponseInputTable runs={designResult.runs} factors={factors} values={responseValues} onChange={updateResponseValue} />
                      <div className="text-xs text-[var(--text-muted)] mt-2">{Object.keys(responseValues).length} / {designResult.runs.length} 组响应已填写</div>
                    </div>
                  )}

                {/* 因子空间可视化 */}
                  {designResult.runs.length >= 2 && factors.length >= 2 && (
                    <div>
                      <div className="text-xs font-semibold text-[var(--text-muted)] mb-2">因子空间可视化化（前两个因子）</div>
                      <ScatterPlot runs={designResult.runs} factors={factors} values={responseValues} />
                    </div>
                  )}

                  {/* 设计矩阵表格 */}
                  <div className="overflow-x-auto">
                    <table className="data-table w-full text-xs">
                      <thead>
                        <tr>
                          <th className="pr-3 text-left w-10">#</th>
                          {designResult.runs[0]?.coded_levels &&
                            Object.keys(designResult.runs[0].coded_levels).map(k => <th key={k} className="px-2 text-center">{k}</th>)}
                          <th className="pl-2 text-center">加入拟合队列</th>
                        </tr>
                      </thead>
                      <tbody>
                        {designResult.runs.map(run => (
                          <tr key={run.run_id}>
                            <td className="pr-3 text-[var(--text-muted)] font-mono">{run.run_id}</td>
                            {Object.entries(run.coded_levels).map(([k, v]) => (
                              <td key={k} className="px-2 text-center font-mono text-[var(--color-primary-text)] tabular-nums">{(v as number).toFixed(4)}</td>
                            ))}
                            <td className="pl-2">
                              {fittingRuns.some(r => r.run_id === run.run_id) ? (
                                <span className="text-xs text-[var(--color-primary-text)]0 dark:text-[var(--color-primary-text)]">已在队列</span>
                              ) : (
                                <button
                                  onClick={() => {
                                    setFittingRuns(prev => [...prev, run])
                                    addToast({ type: 'success', message: `已将 #${run.run_id} 加入拟合队列` })
                                  }}
                                  className="text-[var(--color-primary-text)]0 dark:text-[var(--color-primary-text)] hover:text-[var(--color-primary-text)] dark:hover:text-[var(--color-primary-text)] transition-colors">
                                  <ChevronRight size={14} />
                                </button>
                              )}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </CardContent>
              </Card>
            )}
          </div>
        )}

        {/* 响应面拟合标签*/}
        {activeTab === 'fit' && (
          <div className="space-y-6">
            <Card>
              <CardHeader className="px-5 pt-5 pb-3">
                <div className="flex items-center justify-between">
                  <CardTitle as="h2" className="text-sm font-semibold flex items-center gap-2">
                    <TrendingUp size={14} className="text-[var(--color-primary-text)]0 dark:text-[var(--color-primary-text)]" />
                    {t('pages.doe.fitQueue', { count: fittingRuns.length })}
                  </CardTitle>
                  {/* 响应参数选选择*/}
                  <div className="flex items-center gap-2">
                    <label className="text-xs text-[var(--text-muted)]">{t('pages.doe.fitResponse')}</label>
                    <select value={fitResponseParam}
                      onChange={e => { setFitResponseParam(e.target.value); setRespParamTouched(true) }}
                      className="h-8 px-2 text-xs rounded-[var(--radius-Apple-sm)] border border-input bg-transparent text-[var(--text-primary)] shadow-sm focus:outline-none focus:ring-1 focus:ring-ring">
                      <option value="y">{t('pages.doe.manualY')}</option>
                      {responseCandidates.map(n => <option key={n} value={n}>{t('pages.doe.realData', { name: n })}</option>)}
                    </select>
                  </div>
                </div>
              </CardHeader>
              <CardContent className="px-5 pb-5 pt-0 space-y-[var(--space-apple-md)]">
                {fittingRuns.length === 0 ? (
                  <div className="text-center py-12 text-[var(--text-muted)]">
                    <FileText size={32} className="mx-auto mb-[var(--space-apple-sm)] opacity-30" />
                    <p className="text-sm">请通过上方「实验管理导入」或「配方种子」获取真实数据，或在「实验设计」标签页添加</p>
                  </div>
                ) : (
                  <div className="space-y-2 max-h-80 overflow-y-auto">
                    {fittingRuns.map(run => (
                      <div key={run.run_id} className="flex items-center gap-[var(--space-apple-sm)] px-[var(--space-apple-sm)] py-2 bg-[var(--bg-tertiary)]/70 dark:bg-[var(--bg-tertiary)]/40 rounded-[var(--radius-Apple-sm)] flex-wrap">
                        <span className="text-xs font-mono text-[var(--text-muted)] w-6">#{run.run_id}</span>
                        {Object.entries(run.factor_levels ?? run.coded_levels ?? {}).slice(0, 6).map(([k, v]) => (
                          <span key={k} className="text-xs font-mono text-[var(--text-secondary)] tabular-nums">{k}={(v as number).toFixed(2)}</span>
                        ))}
                        {run.response_values && Object.keys(run.response_values).length > 0 && (
                          <span className="text-xs font-mono text-[var(--color-primary-text)]">
                            {Object.entries(run.response_values).map(([k, v]) => `${k}=${(v as number).toFixed(2)}`).join(' ')}
                          </span>
                        )}
                        <button onClick={() => setFittingRuns(fittingRuns.filter(r => r.run_id !== run.run_id))}
                          className="ml-auto text-[var(--text-muted)] hover:text-danger-500 transition-colors">
                          <Trash2 size={12} />
                        </button>
                      </div>
                    ))}
                  </div>
                )}

                {/* 手动输入响应（选择 y（手动输入） 或没有真实响应时） */}
                {(fitResponseParam === 'y' || responseCandidates.length === 0) && fittingRuns.length > 0 && (
                  <div className="p-[var(--space-apple-sm)] bg-[var(--color-primary-container)] dark:bg-[var(--color-primary-container)]/20 rounded-[var(--radius-Apple-sm)] border border-[var(--color-primary-border)] dark:border-primary-900">
                    <div className="text-xs font-semibold text-[var(--color-primary-text)] mb-2">手动输入响应值（y组</div>
                    <ResponseInputTable runs={fittingRuns} factors={factors} values={responseValues} onChange={updateResponseValue} />
                    <div className="text-xs text-[var(--text-muted)] mt-2">{Object.keys(responseValues).length} / {fittingRuns.length} 组已填写</div>
                  </div>
                )}

                <div className="flex items-center gap-[var(--space-apple-sm)]">
                  <Button onClick={handleFit} disabled={loading || fittingRuns.length < 2}
                    icon={loading ? <RefreshCw size={14} className="animate-spin" /> : <RefreshCw size={14} />}>
                    {loading ? '拟合中..' : `拟合「${fitResponseParam}」响应面`}
                  </Button>
                  <Button variant="ghost" size="sm" onClick={() => { setFittingRuns([]); setResponseValues({}); setFitResult(null); setSearchResult(null) }}
                    className="text-xs">
                    清空队列
                  </Button>
                </div>
              </CardContent>
            </Card>

            {/* 拟合结果 */}
            {fitResult && (
              <Card className="border-[var(--color-primary-border)] dark:border-[var(--color-primary)]/60">
                <CardHeader className="px-5 pt-5 pb-3">
                  <CardTitle as="h3" className="text-sm font-semibold flex items-center gap-2">
                    <Sparkles size={14} className="text-[var(--color-primary-text)]0 dark:text-[var(--color-primary-text)]" />
                    <span className="text-[var(--color-primary-text)]">拟合结果（响应：{displayRespName}）</span>
                  </CardTitle>
                </CardHeader>
                <CardContent className="px-5 pb-5 pt-0 space-y-[var(--space-apple-md)]">
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                    <StatCard label={`R² (${displayRespName})`} value={Number((fitResult[0]?.r_squared?.y ?? fitResult[0]?.r_squared?.[displayRespName] ?? 0).toFixed(4))} icon={TrendingUp} variant="primary" />
                    <StatCard label={`Adj R² (${displayRespName})`} value={Number((fitResult[0]?.adjusted_r_squared?.y ?? fitResult[0]?.adjusted_r_squared?.[displayRespName] ?? 0).toFixed(4))} icon={TrendingUp} variant="secondary" />
                    <StatCard label={`RMSE (${displayRespName})`} value={Number((fitResult[0]?.rmse?.y ?? fitResult[0]?.rmse?.[displayRespName] ?? 0).toFixed(6))} icon={Search} variant="info" />
                    <StatCard label="显著项数" value={(fitResult[0]?.significant_terms?.length ?? 0)} icon={Sparkles} variant="warning" />
                  </div>

                  {/* 回归方程 */}
                  <div className="bg-[var(--bg-tertiary)]/60 rounded-[var(--radius-Apple-sm)] p-[var(--space-apple-sm)]">
                    <div className="text-xs text-[var(--text-muted)] mb-1">回归方程</div>
                    <div className="font-mono text-sm text-[var(--text-primary)] break-all">{fitResult[0]?.equation}</div>
                  </div>

                  {/* 模型系数表（完整）*/}
                  <div>
                    <div className="text-xs font-semibold text-[var(--text-muted)] mb-2">模型系数</div>
                    <div className="overflow-x-auto">
                      <table className="data-table w-full text-xs">
                        <thead>
                          <tr>
                          <th className="pr-3 text-left">#</th>
                            <th className="px-2 text-right">系数</th>
                            <th className="px-2 text-center">显著</th>
                          </tr>
                        </thead>
                        <tbody>
                          {Object.entries(fitResult[0]?.coefficients?.y ?? fitResult[0]?.coefficients?.[displayRespName] ?? {}).map(([term, coef]) => {
                            const sig = fitResult[0]?.significant_terms?.includes(term) ?? false
                            return (
                              <tr key={term}>
                                <td className="pr-3 font-mono text-[var(--text-secondary)]">{term}</td>
                                <td className="px-2 text-right font-mono text-[var(--text-primary)] tabular-nums">{(coef as number).toFixed(6)}</td>
                                <td className="px-2 text-center">
                                  {sig
                                    ? <span className="inline-block w-2 h-2 rounded-[var(--radius-pill)] bg-[var(--color-primary-container)]0" title="显著" />
                                    : <span className="inline-block w-2 h-2 rounded-[var(--radius-pill)] bg-neutral-300 dark:bg-[var(--border-color)]" title="不显著" />
                                  }
                                </td>
                              </tr>
                            )
                          })}
                        </tbody>
                      </table>
                    </div>
                  </div>

                  {/* 显著项列表*/}
                  {(fitResult[0]?.significant_terms?.length ?? 0) > 0 && (
                    <div>
                      <div className="text-xs text-[var(--text-muted)] mb-1">显著项列表（|b| &gt; 2·RMSE）</div>
                      <div className="flex flex-wrap gap-1">
                        {(fitResult[0]?.significant_terms ?? []).map((t: string, i: number) => (
                          <Badge key={i} variant="success" size="sm" className="font-mono">{t}</Badge>
                        ))}
                      </div>
                    </div>
                  )}
                </CardContent>
              </Card>
            )}
          </div>
        )}

        {/* 反向搜索标签 */}
        {activeTab === 'search' && (
          <div className="space-y-6">
            <Card>
              <CardHeader className="px-5 pt-5 pb-3">
                <CardTitle as="h2" className="text-sm font-semibold flex items-center gap-2">
                  <Target size={14} className="text-[var(--color-primary-text)]0 dark:text-[var(--color-primary-text)]" />
                  反向参数搜索
                </CardTitle>
              </CardHeader>
              <CardContent className="px-5 pb-5 pt-0 space-y-[var(--space-apple-md)]">
                {fitResult ? (
                  <>
                    <div className="max-w-xs">
                    <label className="text-xs text-[var(--text-muted)] mb-1 block">目标响应值（{displayRespName}）</label>
                      <Input type="number" value={targetValue} onChange={e => setTargetValue(e.target.value)}
                        className="mt-1 h-9 text-sm tabular-nums" />
                      <Input placeholder="例如 85" className="mt-1 h-9 text-sm tabular-nums" />
                    </div>
                    <Button onClick={handleSearch} disabled={loading}
                      icon={<Search size={14} />}>执行反向搜索</Button>
                  </>
                ) : (
                  <div className="text-center py-8 text-[var(--text-muted)]">
                  <p className="text-sm">请先在「响应面拟合」标签页完成模型拟合</p>
                  </div>
                )}
              </CardContent>
            </Card>

            {/* 搜索结果 */}
            {searchResult && (
              <Card className={searchResult.converged
                ? 'border-[var(--color-primary-border)] dark:border-[var(--color-primary)]/60'
                : 'border-[var(--color-warning-border)] dark:border-[var(--color-warning)]/60'}>
                <CardHeader className="px-5 pt-5 pb-3">
                  <CardTitle as="h3" className={`text-sm font-semibold flex items-center gap-2 ${searchResult.converged ? 'text-[var(--color-primary-text)]' : 'text-[var(--color-warning-text)] dark:text-[var(--color-warning-text)]'}`}>
                    <Sparkles size={14} />
                    搜索结果{!searchResult.converged && '（未收敛，仅供参考）'}
                  </CardTitle>
                </CardHeader>
                <CardContent className="px-5 pb-5 pt-0 space-y-[var(--space-apple-md)]">
                {/* P2-2 修复：未收敛时强警示，禁用下游操作 */}
                {!searchResult.converged && (
                  <div className="p-[var(--space-apple-sm)] bg-[var(--color-warning-container)] dark:bg-[var(--color-warning-container)]/30 rounded-[var(--radius-Apple-sm)] border border-[var(--color-warning-border)] dark:border-[var(--color-warning)] text-xs text-[var(--color-warning-text)]">
                    <div>⚠️ 本次搜索未收敛：梯度可能停在局部极小，或目标值超出响应面可达范围。以下数值仅供参考，请勿直接用于生产决策。建议：调整目标值或扩大 factor_bounds，或增加拟合样本后重试。</div>
                  </div>
                )}
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                  <div className={`rounded-[var(--radius-Apple-sm)] p-[var(--space-apple-sm)] ${searchResult.converged ? 'bg-[var(--color-primary-container)] dark:bg-[var(--color-primary-container)]/30' : 'bg-[var(--color-warning-container)] dark:bg-[var(--color-warning-container)]/30'}`}>
                    <div className="text-xs text-[var(--text-muted)] mb-1">收敛状态</div>
                    <div className={`text-lg font-bold ${searchResult.converged ? 'text-[var(--color-primary-text)]0 dark:text-[var(--color-primary-text)]' : 'text-[var(--color-warning-text)] dark:text-[var(--color-warning-text)]'}`}>
                    {searchResult.converged ? '✓ 已收敛' : '✗ 未收敛'}
                    </div>
                  </div>
                  <div className="bg-[var(--color-secondary-container)] dark:bg-[var(--color-secondary-container)]/30 rounded-[var(--radius-Apple-sm)] p-[var(--space-apple-sm)]">
                    <div className="text-xs text-[var(--text-muted)] mb-1">可行性评分</div>
                    <div className="text-lg font-bold text-[var(--color-secondary-text)] dark:text-[var(--color-secondary-text)] tabular-nums">{(searchResult.feasibility_score ?? 0).toFixed(3)}</div>
                  </div>
                  {Object.entries(searchResult.predicted_factors ?? {}).map(([k, v]) => {
                    const ci = searchResult.confidence_interval?.[k]
                    const coded = searchResult.predicted_coded?.[k]
                    return (
                    <div key={k} className="bg-[var(--bg-tertiary)]/60 rounded-[var(--radius-Apple-sm)] p-[var(--space-apple-sm)]">
                        <div className="text-xs text-[var(--text-muted)] mb-1">{k}（实际值）</div>
                        <div className={`text-lg font-bold tabular-nums ${searchResult.converged ? 'text-[var(--text-primary)]' : 'text-[var(--text-muted)]'}`}>
                          {Number(v).toFixed(2)}
                        {!searchResult.converged && <span className="text-xs text-[var(--color-warning-text)] dark:text-[var(--color-warning-text)] ml-1">≈</span>}
                        </div>
                        {coded != null && <div className="text-xs text-[var(--text-muted)] mt-0.5">编码 {Number(coded).toFixed(2)}</div>}
                        {ci && <div className="text-xs text-[var(--text-muted)] mt-0.5">范围 [{Number(ci[0]).toFixed(2)}, {Number(ci[1]).toFixed(2)}]</div>}
                      </div>
                    )
                  })}
                </div>
                {searchResult.iteration_count > 0 && (
                  <div className="text-xs text-[var(--text-muted)]">迭代 {searchResult.iteration_count} 组</div>
                )}
                {searchResult.converged && (
                  <div className="text-xs text-[var(--color-primary-text)]">
                    建议：将以上因子组合纳入下一个DOE实验验证                  </div>
                )}
              </CardContent>
            </Card>
          )}
          </div>
        )}

        {/* 主动学习标签 */}
        {activeTab === 'active' && (
          <div className="space-y-6">
            <Card>
              <CardHeader className="px-5 pt-5 pb-3">
                <CardTitle as="h2" className="text-sm font-semibold flex items-center gap-2">
                  <Lightbulb size={14} className="text-[var(--color-warning-text)]0 dark:text-[var(--color-warning-text)]" />
                  主动学习推荐
                </CardTitle>
              </CardHeader>
              <CardContent className="px-5 pb-5 pt-0 space-y-[var(--space-apple-md)]">
                <p className="text-xs text-[var(--text-muted)]">
                  基于已有实验数据，使用不确定性采样策略推荐下一批最优实验点，最大化信息增益。
                </p>
                <div className="flex items-center gap-[var(--space-apple-sm)]">
                  <div className="flex items-center justify-between">
                    <Button variant="warning" onClick={handleActiveLearning}
                      disabled={loading || fittingRuns.length === 0}
                      icon={<Lightbulb size={14} className={loading ? 'animate-pulse' : ''} />}>
                      {loading ? '计算中...' : '推荐 3 组新实验点'}
                    </Button>
                  </div>
                </div>
                {fittingRuns.length === 0 && (
                  <div className="text-xs text-[var(--text-muted)]">请先在「实验设计」标签页将实验组加入拟合队列</div>
                )}
              </CardContent>
            </Card>

            {activeLearningResult.length > 0 && (
              <Card className="border-[var(--color-warning-border)] dark:border-[var(--color-warning)]/60">
                <CardHeader className="px-5 pt-5 pb-3">
                  <CardTitle as="h3" className="text-sm font-semibold flex items-center gap-2">
                    <Sparkles size={14} className="text-[var(--color-warning-text)]0 dark:text-[var(--color-warning-text)]" />
                    <span className="text-[var(--color-warning-text)]">推荐实验点</span>
                  </CardTitle>
                </CardHeader>
                <CardContent className="px-5 pb-5 pt-0 space-y-[var(--space-apple-md)]">
                  <div className="overflow-x-auto">
                    <table className="data-table w-full text-xs">
                      <thead>
                        <tr>
                          <th className="pr-2 text-left w-10">#</th>
                          {Object.keys(activeLearningResult[0]?.coded_levels ?? {}).map(k => (
                            <th key={k} className="px-2 text-center">{k}</th>
                          ))}
                          {Object.keys(activeLearningResult[0]?.factor_levels ?? {}).map(k => (
                            <th key={`fl-${k}`} className="px-2 text-center text-[var(--color-warning-text)]">{k}（实际值）</th>
                          ))}
                        </tr>
                      </thead>
                      <tbody>
                        {activeLearningResult.map((rec: any, i: number) => (
                          <tr key={i}>
                            <td className="pr-2 text-[var(--text-muted)] font-mono">{rec.run_id}</td>
                            {Object.entries(rec.coded_levels ?? {}).map(([k, v]) => (
                              <td key={k} className="px-2 text-center font-mono text-[var(--color-primary-text)] tabular-nums">{(v as number).toFixed(4)}</td>
                            ))}
                            {Object.entries(rec.factor_levels ?? {}).map(([k, v]) => (
                              <td key={`fl-${k}`} className="px-2 text-center font-mono text-[var(--color-warning-text)] tabular-nums">{(v as number).toFixed(2)}</td>
                            ))}
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                  {activeStrategy && (
                    <div className="text-xs text-[var(--text-muted)] flex items-center gap-2">
                      <Badge variant="warning" size="sm" className="font-mono">{activeStrategy}</Badge>
                      采样策略
                    </div>
                  )}
                  <div className="text-xs text-[var(--text-muted)]">
                    提示：将以上推荐点加入实验队列，执行实验后回填响应值，可进一步改善响应面模型精度。
                  </div>
                  {closeLoopExpId && (
                    <div className="pt-3 border-t border-[var(--border-color)]">
                      <Button variant="warning" size="sm" onClick={handleExportRecommendations} disabled={loading}
                        icon={<Send size={13} />} className="text-xs">
                        把推荐点写回实验 {closeLoopExpId}（闭环）
                      </Button>
                      <div className="mt-1.5 text-xs text-[var(--text-muted)]">
                        来源：{importedMeta ? `实验导入 #${importedMeta.expId}` : seedMeta ? `配方种子「${seedMeta.formulaName}」→ 实验 ${seedMeta.experimentId}` : '-'}
                      </div>
                    </div>
                  )}
                </CardContent>
              </Card>
            )}
          </div>
        )}
      </div>
      </div>
      </div>
  )
}

﻿/**
 * 实验日历视图
 */
import { useState, useMemo } from 'react'
import { Link, useSearchParams } from 'react-router-dom'
import {
  Calendar as CalendarIcon, ArrowLeft, Filter, FlaskConical,
  ChevronLeft, ChevronRight,
} from 'lucide-react'
import { useExperiments } from '@/hooks/useQueries'
import { StatusBadge } from '@/components/ui/Common'
import { Button, Card, CardContent } from '@/components/ui'
import { cn } from '@/lib/utils'
import { format, startOfMonth, endOfMonth, eachDayOfInterval, isSameMonth, isSameDay, addMonths, subMonths } from 'date-fns'
import { zhCN } from 'date-fns/locale'

type ViewMode = 'month' | 'list'

/** 安全日期格式化：避免 Invalid Date 抛 RangeError */
function safeDate(raw: string | null | undefined, pattern = 'yyyy-MM-dd'): string {
  if (!raw) return '-'
  const dt = new Date(raw)
  if (Number.isNaN(dt.getTime())) return '-'
  return format(dt, pattern, { locale: zhCN })
}

/** 安全获取 Date 对象：无效返回 null */
function safeDateObj(raw: string | null | undefined): Date | null {
  if (!raw) return null
  const dt = new Date(raw)
  if (Number.isNaN(dt.getTime())) return null
  return dt
}

export default function ExperimentCalendarPage() {
  const [viewMode, setViewMode] = useState<ViewMode>('month')
  const [displayDate, setDisplayDate] = useState(new Date())

  const { data, isLoading } = useExperiments({ page_size: 100 })
  const experiments = data?.items ?? []

  const daysInMonth = useMemo(() => {
    const start = startOfMonth(displayDate)
    const end = endOfMonth(displayDate)
    return eachDayOfInterval({ start, end })
  }, [displayDate])

  const experimentsByDate = useMemo(() => {
    const map: Record<string, typeof experiments> = {}
    for (const exp of experiments) {
      const dt = safeDateObj(exp.start_date)
      if (!dt) continue
      const dateKey = format(dt, 'YYYY-MM-DD')
      if (!map[dateKey]) map[dateKey] = []
      map[dateKey].push(exp)
    }
    return map
  }, [experiments])

  const weekDays = ['日', '一', '二', '三', '四', '五', '六']

  const prevMonth = () => setDisplayDate(subMonths(displayDate, 1))
  const nextMonth = () => setDisplayDate(addMonths(displayDate, 1))
  const today = () => setDisplayDate(new Date())
  const headerTitle = format(displayDate, 'yyyy年MM月', { locale: zhCN })

  const sortedExperiments = useMemo(() => {
    return [...experiments]
      .filter((e) => e.start_date)
      .sort((a, b) => {
        const ta = safeDateObj(a.start_date)?.getTime() ?? 0
        const tb = safeDateObj(b.start_date)?.getTime() ?? 0
        return ta - tb
      })
  }, [experiments])

  return (
    <div className="max-w-[1600px] mx-auto space-y-6 px-[var(--space-apple-md)] lg:px-6 py-[var(--space-apple-lg)]">
      {/* 欢迎横幅 */}
      <div className="surface-primary rounded-[var(--radius-Apple-md)] p-[var(--space-apple-lg)] shadow-sm">
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-[var(--space-apple-md)]">
          <div className="flex items-center gap-[var(--space-apple-sm)]">
            <Link
              to="/experiments"
              className="p-2 rounded-[var(--radius-Apple-sm)] hover:bg-white/10 transition-colors text-white/80"
              title="返回实验列表"
            >
              <ArrowLeft size={18} />
            </Link>
            <div>
              <h1 className="text-xl font-semibold leading-snug tracking-tight">实验日历</h1>
              <p className="mt-1 text-sm text-white/80">按日历查看实验计划与安排</p>
            </div>
          </div>
          <div className="flex flex-wrap items-center gap-2 shrink-0">
            {/* 视图切换 */}
            <div className="flex bg-black/15 dark:bg-[var(--bg-secondary)]/15 rounded-[var(--radius-Apple-sm)] p-0.5">
              <button
                onClick={() => setViewMode('month')}
                className={cn(
                  'px-[var(--space-apple-sm)] py-1.5 rounded-[var(--radius-Apple-sm)] text-xs font-medium transition-colors',
                  viewMode === 'month'
                    ? 'bg-[var(--bg-secondary)] dark:bg-[var(--bg-tertiary)] text-[var(--color-primary-text)] dark:text-neutral-50 shadow-sm'
                    : 'text-white/90 hover:text-white',
                )}
              >
                月视图
              </button>
              <button
                onClick={() => setViewMode('list')}
                className={cn(
                  'px-[var(--space-apple-sm)] py-1.5 rounded-[var(--radius-Apple-sm)] text-xs font-medium transition-colors',
                  viewMode === 'list'
                    ? 'bg-[var(--bg-secondary)] dark:bg-[var(--bg-tertiary)] text-[var(--color-primary-text)] dark:text-neutral-50 shadow-sm'
                    : 'text-white/90 hover:text-white',
                )}
              >
                列表
              </button>
            </div>
          </div>
        </div>
      </div>

      {viewMode === 'month' ? (
        <>
          {/* 月份导航 */}
          <Card>
            <CardContent className="py-4">
              <div className="flex items-center justify-between mb-[var(--space-apple-md)]">
                <Button variant="ghost" size="sm" icon={<ChevronLeft size={14} />} onClick={prevMonth}>上月</Button>
                <span className="text-lg font-semibold text-[var(--text-primary)]">{headerTitle}</span>
                <div className="flex gap-2">
                  <Button variant="ghost" size="sm" onClick={today}>今天</Button>
                  <Button variant="ghost" size="sm" icon={<ChevronRight size={14} />} onClick={nextMonth}>下月</Button>
                </div>
              </div>

              {/* 日历网格 */}
              <div className="grid grid-cols-7 gap-px">
                {weekDays.map((d) => (
                  <div key={d} className="text-center text-xs font-medium text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] py-2">
                    {d}
                  </div>
                ))}
                {daysInMonth.map((day) => {
                  const dateKey = format(day, 'yyyy-MM-dd')
                  const dayExps = experimentsByDate[dateKey] || []
                  const isToday = isSameDay(day, new Date())
                  const isCurrentMonth = isSameMonth(day, displayDate)

                  return (
                    <div
                      key={dateKey}
                      className={cn(
                        'min-h-[100px] p-2 border border-[var(--border-color)] transition-colors',
                        !isCurrentMonth && 'opacity-40',
                        isToday && 'bg-[var(--color-accent-container)] dark:bg-[var(--color-accent-container)]/15',
                      )}
                    >
                      <div className={cn(
                        'text-xs font-medium mb-1',
                        isToday ? 'text-[var(--color-accent-text)] dark:text-[var(--color-accent-text)]' : 'text-[var(--text-muted)]',
                      )}>
                        {format(day, 'd')}
                      </div>
                      {dayExps.map((exp: any) => (
                        <Link
                          key={exp.id}
                          to={`/experiments/${exp.id}`}
                          className={cn(
                            'block px-1.5 py-0.5 rounded text-xs truncate mb-0.5 transition-colors',
                            exp.status === 'in_progress' ? 'bg-[var(--color-primary-container)] text-[var(--color-primary-text)] dark:bg-[var(--color-primary-container)]/25 dark:text-[var(--color-primary-text)]'
                              : exp.status === 'completed' ? 'bg-[var(--color-success-container)] text-[var(--color-success-text)] dark:bg-[var(--color-success-container)]/25 dark:text-[var(--color-success-text)]'
                              : exp.status === 'failed' ? 'bg-[var(--color-warning-container)] text-[var(--color-warning-text)] dark:bg-[var(--color-warning-container)]/25 dark:text-[var(--color-warning-text)]'
                              : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)] dark:bg-[var(--bg-tertiary)] dark:text-[var(--text-muted)]',
                          )}
                          title={exp.title}
                        >
                          {exp.title}
                        </Link>
                      ))}
                      {dayExps.length > 2 && (
                        <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] pl-1.5">+{dayExps.length - 2} 更多</div>
                      )}
                    </div>
                  )
                })}
              </div>
            </CardContent>
          </Card>
        </>
      ) : (
        /* 列表视图 */
        <div className="space-y-[var(--space-apple-sm)]">
          {isLoading ? (
            Array.from({ length: 4 }).map((_, i) => (
              <Card key={i}><CardContent className="p-[var(--space-apple-md)]"><div className="h-4 bg-[var(--bg-tertiary)] rounded w-1/3 mb-2" /></CardContent></Card>
            ))
          ) : sortedExperiments.length === 0 ? (
            <Card>
              <CardContent className="py-12 text-center">
                <CalendarIcon size={32} className="mx-auto text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-2" />
                <p className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">暂无实验数据</p>
                <Link to="/experiments/new">
                  <Button variant="ghost" size="sm" className="mt-2">新建实验</Button>
                </Link>
              </CardContent>
            </Card>
          ) : (
            sortedExperiments.map((exp: any) => (
              <Link key={exp.id} to={`/experiments/${exp.id}`} className="block">
                <Card className="hover:shadow-md transition-shadow">
                  <CardContent className="p-[var(--space-apple-md)] flex items-center gap-4">
                    <div className="w-12 h-12 rounded-[var(--radius-Apple-sm)] bg-[var(--color-accent-container)] flex flex-col items-center justify-center shrink-0">
                      <span className="text-xs font-bold text-[var(--color-accent-text)] dark:text-[var(--color-accent-text)]">{safeDate(exp.start_date, 'MM')}</span>
                      <span className="text-xs text-[var(--color-accent-text)]0 dark:text-[var(--color-accent-text)] -mt-0.5">{safeDate(exp.start_date, 'dd')}</span>
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-0.5">
                        <span className="text-sm font-semibold text-[var(--text-primary)] truncate">{exp.title}</span>
                        <StatusBadge status={exp.status} />
                      </div>
                      <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{exp.code} · {safeDate(exp.start_date, 'yyyy-MM-dd')}</p>
                    </div>
                    <ChevronRight size={16} className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] shrink-0" />
                  </CardContent>
                </Card>
              </Link>
            ))
          )}
        </div>
      )}
    </div>
  )
}

