        <p className="text-xs text-[var(--text-muted)] mt-1">点击「录入数据」开始记录实验数据</p>
      </div>
    )
  }

  return (
    <div className="overflow-x-auto">
      <table className="w-full text-sm">
        <thead>
          <tr className="border-b border-[var(--border-color)]">
