            <th className="text-left py-2.5 px-[var(--space-apple-sm)] text-xs font-semibold text-[var(--text-muted)]">数值</th>
            <th className="text-left py-2.5 px-[var(--space-apple-sm)] text-xs font-semibold text-[var(--text-muted)]">单位</th>
            <th className="text-left py-2.5 px-[var(--space-apple-sm)] text-xs font-semibold text-[var(--text-muted)]">备注</th>
            <th className="text-left py-2.5 px-[var(--space-apple-sm)] text-xs font-semibold text-[var(--text-muted)]">时间</th>
            <th className="w-16"></th>
          </tr>
        </thead>
        <tbody>
          {data.map((d) => {
            const isEditing = editingId === d.id
            return (
              <tr key={d.id} className="border-b border-[var(--border-color)] hover:bg-[var(--bg-tertiary)] dark:hover:bg-[var(--bg-tertiary)]/50 transition-colors">
                {isEditing ? (
                  <>
                    <td className="py-2 px-[var(--space-apple-sm)]">
                      <input value={editForm.parameter} onChange={(e) => setEditForm({ ...editForm, parameter: e.target.value })} className="w-full h-7 px-2 text-xs rounded border border-[var(--border-color)] bg-[var(--bg-secondary)]" placeholder="参数名" />
                    </td>
