                    </td>
                    <td className="py-2 px-[var(--space-apple-sm)]">
                      <input value={editForm.unit} onChange={(e) => setEditForm({ ...editForm, unit: e.target.value })} className="w-16 h-7 px-2 text-xs rounded border border-[var(--border-color)] bg-[var(--bg-secondary)]" placeholder="单位" />
                    </td>
