            {/* 添加参数 */}
            <div className="flex gap-2">
              <Input
                value={paramKey}
                onChange={(e) => setParamKey(e.target.value)}
                placeholder="参数名"
                size="sm"
                className="flex-1"
              />
              <Input
                value={paramValue}
                onChange={(e) => setParamValue(e.target.value)}
