  { value: 'stability', label: '稳定性实验', desc: '检测配方在不同条件下的稳定性', icon: Thermometer, color: 'bg-secondary-surface' },
  { value: 'efficacy', label: '功效验证实验', desc: '验证配方的目标功效', icon: Target, color: 'bg-primary-surface' },
  { value: 'safety', label: '安全毒理学', desc: '急性/亚慢性毒性试验', icon: Shield, color: 'bg-warning-surface' },
