  { value: 'positive', label: '阳性对照', desc: '使用标准品/已知有效成分的对照组' },
  { value: 'vehicle', label: '溶剂对照', desc: '仅含溶剂/赋形剂的对照组' },
  { value: 'dose', label: '剂量对照', desc: '不同剂量梯度组' },
