    if (form.objectives?.length) items.push({ label: '目标', value: form.objectives.join('；') })
    if (form.methodology?.trim()) items.push({ label: '方法', value: form.methodology.slice(0, 80) + (form.methodology.length > 80 ? '…' : '') })
    if (form.start_date) items.push({ label: '开始', value: form.start_date })
    if (form.end_date) items.push({ label: '结束', value: form.end_date })
    if (form.materials?.length) items.push({ label: '材料', value: `${form.materials.length} 项` })
    if (form.equipment?.length) items.push({ label: '设备', value: `${form.equipment.length} 项` })
    if (controlGroup !== 'none') items.push({ label: '对照组', value: CONTROL_GROUPS.find(c => c.value === controlGroup)?.label || '' })
    if (efficacyTargets.length > 0) items.push({ label: '功效目标', value: efficacyTargets.map(t => EFFICACY_TARGETS.find(e => e.value === t)?.label).filter(Boolean).join('、') })
    return items
  }, [form, selectedType, controlGroup, efficacyTargets])

  return (
    <div className="min-h-screen">
      <div className="max-w-[1600px] mx-auto px-[var(--space-apple-md)] sm:px-6 lg:px-8 space-y-[var(--space-apple-md)] py-[var(--space-apple-lg)]">

        {/* ── 欢迎横幅（surface-primary 实底，对齐 DashboardPage） ── */}
