                    <Input value={equipmentInput.quantity} onChange={(e) => setEquipmentInput({ ...equipmentInput, quantity: e.target.value })} placeholder="数量" size="sm" />
                    <Input value={equipmentInput.unit} onChange={(e) => setEquipmentInput({ ...equipmentInput, unit: e.target.value })} placeholder="单位" size="sm" />
