                </div>
              )}

              {form.formula_id && selectedFormulaDetail && (
                <div className="flex items-center justify-between px-[var(--space-apple-sm)] py-2.5 bg-[var(--color-primary-container)] rounded-[var(--radius-Apple-sm)]">
