/** 药材搜索下拉框 */
function HerbSearchDropdown({
  keyword,
  onSelect,
  existingIds,
  activeIndex,
  onActiveIndexChange,
}: {
  keyword: string;
  onSelect: (herb: TCMHerb) => void;
  existingIds: number[];
  inputRef: React.RefObject<HTMLInputElement | null>;
  activeIndex: number;
  onActiveIndexChange: (index: number) => void;
}) {
  const [herbs, setHerbs] = useState<TCMHerb[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!keyword.trim()) {
      // eslint-disable-next-line react-hooks/set-state-in-effect -- 关键词清空时同步重置下拉数据
      setHerbs([]);
      onActiveIndexChange(-1);
      return;
    }
    const timer = setTimeout(async () => {
      setLoading(true);
      onActiveIndexChange(-1);
      try {
        const res = await databaseApi.searchHerbs({ keyword, page_size: 8 });
        setHerbs(res.items || []);
      } catch {
        setHerbs([]);
      } finally {
        setLoading(false);
      }
    }, 300);
    return () => clearTimeout(timer);
  }, [keyword]);

  const isDuplicate = (id: number) => existingIds.includes(id);

  if (loading) {
    return (
      <div className="absolute z-20 mt-1 w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-[var(--radius-Apple-md)] shadow-xl overflow-hidden">
        <div className="p-[var(--space-apple-sm)] text-center text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
          <div className="w-4 h-4 border-2 border-[var(--color-primary-border)] border-t-primary-600 rounded-[var(--radius-pill)] animate-spin mx-auto" />
        </div>
      </div>
    );
  }

  if (herbs.length === 0) {
    return (
      <div className="absolute z-20 mt-1 w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-[var(--radius-Apple-md)] shadow-xl overflow-hidden">
        <div className="p-[var(--space-apple-sm)] text-center text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">未找到匹配药材</div>
      </div>
    );
  }

  return (
    <div className="absolute z-20 mt-1 w-full bg-[var(--bg-secondary)] border border-[var(--border-color)] rounded-[var(--radius-Apple-md)] shadow-xl overflow-hidden max-h-56 overflow-y-auto">
      {herbs.map((herb, idx) => (
        <button
          key={herb.id}
          type="button"
          disabled={isDuplicate(herb.id)}
          onClick={() => onSelect(herb)}
          onMouseEnter={() => onActiveIndexChange(idx)}
          className={cn(
            'w-full text-left px-[var(--space-apple-sm)] py-2 text-sm hover:bg-[var(--bg-tertiary)] dark:hover:bg-[var(--bg-tertiary)] transition-colors border-b border-[var(--border-color)] last:border-0',
            idx === activeIndex && 'bg-[var(--bg-tertiary)]',
            isDuplicate(herb.id) && 'opacity-50 cursor-not-allowed',
          )}
        >
          <div className="flex items-center justify-between">
            <div>
              <span className="font-medium text-[var(--text-primary)]">{herb.name_cn || herb.name}</span>
              {herb.category && <span className="ml-2 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{herb.category}</span>}
            </div>
            <div className="flex items-center gap-1.5">
              {herb.is_food_homology && (
                <Badge variant="success" size="sm">
                  药食同源
                </Badge>
              )}
              {isDuplicate(herb.id) && (
                <Badge variant="neutral" size="sm">
                  已添加
                </Badge>
              )}
            </div>
          </div>
          {(herb.effects || herb.efficacy) && <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-0.5 truncate">{herb.effects || herb.efficacy}</p>}
        </button>
      ))}
    </div>
  );
}

﻿/**
 * 配方模板库页面 - 真实数据版
 * 模板数据来自后端 GET /api/v1/formulas/templates（真实数据库）
 * 支持搜索、分类筛选、收藏、一键使用模板（跳转新建配方页并预填）
 */
import { useState, useMemo } from 'react'
import { useQuery } from '@tanstack/react-query'
import { useNavigate, Link } from 'react-router-dom'
import { Plus, Search, FlaskConical, Sparkles, Star, ArrowRight, Copy, Clock, Zap, RefreshCw } from 'lucide-react'
import { Button, Input, Badge, Card, CardContent } from '@/components/ui'
import { EmptyState, Skeleton } from '@/components/ui/Common'
import { cn } from '@/lib/utils'
import { formulaApi, getFormulaTemplates, type FormulaTemplateItem } from '@/api/formula'

type Category = 'all' | '热门' | '免疫力' | '睡眠' | '肠胃' | '美容' | '慢性病' | '其他'

const CATEGORIES: { value: Category; label: string }[] = [
  { value: 'all', label: '全部' },
  { value: '热门', label: '热门推荐' },
  { value: '免疫力', label: '增强免疫' },
  { value: '睡眠', label: '改善睡眠' },
  { value: '肠胃', label: '调理肠胃' },
  { value: '美容', label: '美容养颜' },
  { value: '慢性病', label: '慢性病辅助' },
  { value: '其他', label: '其他功效' },
]

// 类别 → 视觉颜色（纯展示用，非数据字段）
const CATEGORY_COLORS: Record<string, string> = {
  免疫力: 'var(--color-primary, var(--color-primary-400))',
  睡眠: 'var(--color-tertiary, var(--color-accent-500))',
  慢性病: 'var(--color-secondary, #0A84FF)',
  美容: 'var(--color-danger-500, #D946EF)',
  肠胃: 'var(--color-warning, #FF9F0A)',
  其他: 'var(--color-teal-500, #14B8A6)',
}

const OTHER_CATEGORY_KEYS = ['免疫力', '睡眠', '肠胃', '美容', '慢性病']

// 后端模板 → 卡片展示字段映射
function mapTemplate(t: FormulaTemplateItem) {
  return {
    id: String(t.id),
    code: t.code,
    name: t.name,
    description: t.description || '',
    effects: t.effects || [],
    ingredients: (t.ingredients || []).map((ing) => ({
      name: ing.name,
      role: ing.role || '',
      dosage: ing.dosage || '',
      category: ing.category || '',
    })),
    usage: t.usage || '',
    usage_count: t.usage_count || 0,
    tags: [t.category || '其他'],
    is_featured: t.is_featured,
    color: CATEGORY_COLORS[t.category || '其他'] || 'var(--color-primary, var(--color-primary-400))',
  }
}

export default function FormulaTemplatesPage() {
  const navigate = useNavigate()
  const [search, setSearch] = useState('')
  const [category, setCategory] = useState<Category>('all')
  const [favorites, setFavorites] = useState<Set<string>>(new Set())
  const [showFavOnly, setShowFavOnly] = useState(false)

  const { data, isLoading, isError, refetch } = useQuery({
    queryKey: ['formula-templates'],
    queryFn: () => getFormulaTemplates(),
  })

  const templates = useMemo(() => (data?.items || []).map(mapTemplate), [data])

  const toggleFavorite = (id: string) => {
    setFavorites(prev => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }

  const filteredTemplates = useMemo(() => {
    let result = [...templates]
    if (showFavOnly) result = result.filter(t => favorites.has(t.id))
    if (category !== 'all') {
      if (category === '热门') {
        result = result.filter(t => t.is_featured)
      } else if (category === '其他') {
        result = result.filter(t => !OTHER_CATEGORY_KEYS.includes(t.tags[0] || ''))
      } else {
        result = result.filter(t => t.tags.includes(category))
      }
    }
    if (search.trim()) {
      const keyword = search.toLowerCase()
      result = result.filter(t =>
        t.name.toLowerCase().includes(keyword) ||
        t.description.toLowerCase().includes(keyword) ||
        t.effects.some(e => e.toLowerCase().includes(keyword)),
      )
    }
    return result.sort((a, b) => b.usage_count - a.usage_count)
  }, [templates, search, category, favorites, showFavOnly])

  const totalUsage = useMemo(() => templates.reduce((sum, t) => sum + t.usage_count, 0), [templates])

  const handleUseTemplate = (template: ReturnType<typeof mapTemplate>) => {
    // 将模板数据存储到 sessionStorage，跳转到新建配方页
