                  </div>
                )}

                {/* 服用方法 */}
                {template.usage && (
                  <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-[var(--space-apple-md)] flex items-center gap-1">
                    <Clock size={10} />
