export function CommentItem({
  comment,
  currentUserId,
  onDelete,
  onReply,
  expanded,
  onToggle,
}: {
  comment: Comment;
  currentUserId?: number;
  onDelete: (id: number) => void;
  onReply: (id: number) => void;
  expanded: boolean;
  onToggle: () => void;
}) {
  const qc = useQueryClient();
  const [likeLoading, setLikeLoading] = useState(false);

  const { data: likesData } = useQuery({
    queryKey: ['comment-likes', comment.id],
    queryFn: () => commentApi.getLikes(comment.id),
  });

  const likeCount = likesData?.like_count ?? comment.like_count ?? 0;
  const isLiked = likesData?.is_liked ?? comment.is_liked ?? false;

  const likeMut = useMutation({
    mutationFn: () => (isLiked ? commentApi.unlike(comment.id) : commentApi.like(comment.id)),
    onMutate: async () => {
      setLikeLoading(true);
    },
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['comment-likes', comment.id] });
    },
    onSettled: () => {
      setLikeLoading(false);
    },
  });

  const { data: replies } = useQuery({
    queryKey: ['comment-replies', comment.id],
    queryFn: () => commentApi.getReplies(comment.id),
    enabled: expanded,
  });

  const canDelete = currentUserId === comment.user_id;

  return (
    <div className="group">
      <div className="flex gap-[var(--space-apple-sm)]">
        <div className="w-7 h-7 rounded-[var(--radius-pill)] bg-[var(--bg-tertiary)] flex items-center justify-center text-[var(--text-muted)] text-xs font-medium shrink-0 mt-0.5">
          {comment.author_name?.[0] ?? 'U'}
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-0.5">
            <span className="text-sm font-medium text-[var(--text-primary)]">
              {comment.author_name ?? '未知用户'}
            </span>
            {comment.author_role && (
              <span className="text-xs px-1.5 py-0.5 rounded-[var(--radius-pill)] bg-[var(--bg-tertiary)] text-[var(--text-muted)]">
                {ROLE_LABELS[comment.author_role] ?? comment.author_role}
              </span>
            )}
            <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
              {new Date(comment.created_at).toLocaleDateString('zh-CN', {
                month: 'short',
                day: 'numeric',
                hour: '2-digit',
                minute: '2-digit',
              })}
            </span>
          </div>
          <p className="text-sm text-[var(--text-secondary)] leading-relaxed whitespace-pre-wrap">
            {comment.content}
          </p>
          <div className="flex items-center gap-[var(--space-apple-sm)] mt-1.5 opacity-0 group-hover:opacity-100 transition-opacity">
            <button
              onClick={() => likeMut.mutate()}
              disabled={likeLoading}
              className={cn(
                'flex items-center gap-1 text-xs transition-all duration-200',
                isLiked ? 'text-[var(--color-error-text)]0 hover:text-[var(--color-error-text)]' : 'text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-[var(--color-error-text)]0',
              )}
            >
              <Heart
                size={12}
                className={cn('transition-transform duration-200', isLiked ? 'fill-error-500 scale-110' : 'fill-none')}
              />
              {likeCount > 0 && <span>{likeCount}</span>}
            </button>
            <button
              onClick={() => onReply(comment.id)}
              className="flex items-center gap-1 text-xs text-[var(--text-muted)] hover:text-[var(--color-primary-text)] dark:hover:text-[var(--color-primary-text)] transition-colors"
            >
              <Reply size={12} /> 回复
            </button>
            {canDelete && (
              <button
                onClick={() => onDelete(comment.id)}
                className="flex items-center gap-1 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-[var(--color-error-text)]0 transition-colors"
              >
                <Trash2 size={12} /> 删除
              </button>
            )}
          </div>

          {/* 回复展开 */}
          {comment.replies_count > 0 && (
            <button
              onClick={onToggle}
              className="flex items-center gap-1 mt-2 text-xs text-[var(--text-muted)] hover:text-[var(--color-primary-text)] dark:hover:text-[var(--color-primary-text)] transition-colors"
            >
              {expanded ? <ChevronUp size={12} /> : <ChevronDown size={12} />}
              {comment.replies_count} 条回复
            </button>
          )}
          {expanded && replies && replies.length > 0 && (
            <div className="mt-2 pl-2 border-l-2 border-[var(--border-color)] space-y-[var(--space-apple-sm)]">
              {replies.map((reply) => {
                const canDeleteReply = currentUserId === reply.user_id;
                return (
                  <div key={reply.id} className="flex gap-2 group/reply">
                    <div className="w-6 h-6 rounded-[var(--radius-pill)] bg-[var(--bg-tertiary)] flex items-center justify-center text-[var(--text-muted)] text-xs font-medium shrink-0 mt-0.5">
                      {reply.author_name?.[0] ?? 'U'}
                    </div>
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-0.5">
                        <span className="text-xs font-medium text-[var(--text-primary)]">{reply.author_name}</span>
                        <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                          {new Date(reply.created_at).toLocaleDateString('zh-CN', {
                            month: 'short',
                            day: 'numeric',
                            hour: '2-digit',
                            minute: '2-digit',
                          })}
                        </span>
                      </div>
                      <p className="text-sm text-[var(--text-secondary)]">{reply.content}</p>
                      {canDeleteReply && (
                        <button
                          onClick={() => onDelete(reply.id)}
                          className="flex items-center gap-1 mt-1 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] hover:text-[var(--color-error-text)]0 opacity-0 group-hover/reply:opacity-100 transition-all"
                        >
                          <Trash2 size={11} /> 删除
                        </button>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

﻿/**
 * 配方成分可视化组件
 * 饼图展示君臣佐使角色分布 + 柱状图展示用量分布
 */
import { useMemo } from 'react'
import { PieChart, Pie, Cell, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip } from 'recharts'
import { CHART_TYPOGRAPHY } from '../../../utils/typography'
import { getChartThemeColors, getRoleColor } from '../../../utils/chartTheme'
import { useIsDarkMode } from '@/theme'

interface Ingredient {
  name: string
  category?: string
  is_food_homology?: boolean
  dosage?: string
  role?: string
}

interface CompositionChartProps {
  ingredients: Ingredient[]
  compact?: boolean
}

function parseDosage(dosage: string): number {
  if (!dosage) return 0
  const match = /^([\d.]+)/.exec(dosage)
  if (match) return parseFloat(match[1])
  return 0
}

function getDosageUnit(dosage: string): string {
  if (!dosage) return ''
  return dosage.replace(/^[\d.]+/, '').trim() || 'g'
}

export function CompositionChart({ ingredients, compact = false }: CompositionChartProps) {
  // D-43 修复：原为 useMemo(..., []) 空依赖 —— 切主题后图表颜色不会更新
  const isDark = useIsDarkMode()
  const colors = useMemo(() => getChartThemeColors(), [isDark])
  const tooltipBg = colors.tooltipBg || 'var(--card-bg-solid, #FFFFFF)'
  const tooltipBorder = colors.tooltipBorder || 'var(--border-subtle, rgba(0,0,0,0.06))'
  const tooltipText = colors.tooltipText || 'var(--text-secondary, #6E6E73)'
  const axisColor = colors.axisColor || 'var(--text-muted, #9A9A9F)'
  const barFill = colors.barFill || 'var(--color-secondary, #0A84FF)'

  const tooltipStyle = {
    backgroundColor: tooltipBg,
    border: `1px solid ${tooltipBorder}`,
    borderRadius: '8px',
    color: tooltipText,
    fontSize: '12px',
  }

  const roleData = useMemo(() => {
    const roleMap: Record<string, number> = {}
    ingredients.forEach(ing => {
      const role = ing.role || '未分类'
      roleMap[role] = (roleMap[role] || 0) + 1
    })
    return Object.entries(roleMap).map(([name, value]) => ({
      name,
      value,
      fill: getRoleColor(name),
    }))
  }, [ingredients])

  const dosageData = useMemo(() => {
    return ingredients
      .map(ing => ({
        name: ing.name.length > 6 ? ing.name.slice(0, 6) + '...' : ing.name,
        dosage: parseDosage(ing.dosage || '0'),
        unit: getDosageUnit(ing.dosage || '0'),
      }))
      .filter(item => item.dosage > 0)
      .sort((a, b) => b.dosage - a.dosage)
      .slice(0, compact ? 5 : 10)
  }, [ingredients, compact])

  const categoryData = useMemo(() => {
    const catMap: Record<string, number> = {}
    ingredients.forEach(ing => {
      const cat = ing.category || '未分类'
      catMap[cat] = (catMap[cat] || 0) + 1
    })
    return Object.entries(catMap)
      .map(([name, value], i) => ({
        name: name.length > 8 ? name.slice(0, 8) + '...' : name,
        value,
        fill: colors.pie[i % colors.pie.length],
      }))
      .sort((a, b) => b.value - a.value)
  }, [ingredients, colors])

  const totalIngredients = ingredients.length

  if (totalIngredients === 0) {
    return (
      <div className="py-8 text-center text-[var(--text-muted)]">
        <p className="text-sm">暂无成分数据</p>
        <p className="text-xs mt-1">请先添加成分后查看分布图</p>
      </div>
    )
  }

  if (compact) {
    return (
      <div className="flex items-center gap-[var(--space-apple-sm)]">
        <div className="w-20 h-20 shrink-0">
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie rootTabIndex={-1}
                data={roleData}
                cx="50%"
                cy="50%"
                innerRadius={16}
                outerRadius={32}
                paddingAngle={2}
                dataKey="value"
              >
                {roleData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={entry.fill} />
                ))}
              </Pie>
            </PieChart>
          </ResponsiveContainer>
        </div>
        <div className="flex-1 min-w-0">
          <div className="grid grid-cols-2 gap-x-3 gap-y-1">
            {roleData.map((entry) => (
              <div key={entry.name} className="flex items-center gap-1.5">
                <div className="w-2.5 h-2.5 rounded-[var(--radius-pill)] shrink-0" style={{ backgroundColor: entry.fill }} />
                <span className="text-xs text-[var(--text-secondary)] truncate">
                  {entry.name} ({entry.value})
                </span>
              </div>
            ))}
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-[var(--space-apple-md)]">
      {roleData.length > 0 && (
        <div>
          <h5 className="text-xs font-medium text-[var(--text-muted)] mb-2">君臣佐使分布</h5>
          <div className="flex items-center gap-4">
            <div className="w-28 h-28 shrink-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie rootTabIndex={-1}
                    data={roleData}
                    cx="50%"
                    cy="50%"
                    innerRadius={24}
                    outerRadius={44}
                    paddingAngle={3}
                    dataKey="value"
                    label={({ name, percent }) => `${name}${Math.round(percent * 100)}%`}
                    labelLine={false}
                  >
                    {roleData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={entry.fill} />
                    ))}
                  </Pie>
                  <Tooltip
                      contentStyle={tooltipStyle}
                      formatter={(value: number) => [`${value} 种 (${((value / totalIngredients) * 100).toFixed(0)}%)`, '数量']}
                    />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <div className="flex-1">
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                {roleData.map((entry) => (
                  <div key={entry.name} className="flex items-center gap-2 px-2 py-1.5 rounded-[var(--radius-Apple-sm)] bg-[var(--bg-tertiary)]/50">
                    <div className="w-3 h-3 rounded-[var(--radius-pill)] shrink-0" style={{ backgroundColor: entry.fill }} />
                    <div className="min-w-0">
                      <span className="text-xs font-medium text-[var(--text-primary)]">{entry.name}</span>
                      <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{entry.value} 种</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      {dosageData.length > 0 && (
        <div>
          <h5 className="text-xs font-medium text-[var(--text-muted)] mb-2">用量分布 (Top {dosageData.length})</h5>
          <div className="h-32">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={dosageData} layout="vertical" margin={{ left: 50, right: 16 }}>
                <XAxis type="number" tick={{ fontSize: 10, fill: axisColor }} />
                <YAxis type="category" dataKey="name" tick={{ fontSize: 10, fill: axisColor }} width={50} />
                <Tooltip
                  contentStyle={tooltipStyle}
                  formatter={(value: number, _: any, props: any) => [`${value} ${props.payload.unit || 'g'}`, '用量']}
                />
                <Bar dataKey="dosage" fill={barFill} radius={[0, 3, 3, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      )}

      {categoryData.length > 0 && (
        <div>
          <h5 className="text-xs font-medium text-[var(--text-muted)] mb-2">药材分类分布</h5>
          <div className="flex flex-wrap gap-1.5">
            {categoryData.map((entry) => (
              <div key={entry.name} className="flex items-center gap-1.5 px-2 py-1 rounded-[var(--radius-pill)] text-xs" style={{ backgroundColor: `${entry.fill}15`, color: entry.fill }}>
                <div className="w-2 h-2 rounded-[var(--radius-pill)]" style={{ backgroundColor: entry.fill }} />
                <span>{entry.name}</span>
                <span className="opacity-70">{entry.value}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  )
}

﻿/**
 * 配方卡片组件 — 用于卡片视图展示单个配方
 * Apple HIG 风格：清晰层级、充足呼吸空间、语义化颜色
 */
import { Link } from 'react-router-dom';
import { CheckCircle2, Eye, Star, ArrowRightLeft } from 'lucide-react';
import { cn } from '@/lib/utils';
import { Highlight } from '@/components/common';
import { StatusBadge, Badge, Card, CardContent } from '@/components/ui';
import type { Formula, FormulaStatus } from '@/types/formula';

function formatDate(dateStr: string): string {
  if (!dateStr) return '-';
  return new Date(dateStr).toLocaleDateString('zh-CN');
}

function getStatusLabel(status: FormulaStatus): string {
  const map: Record<string, string> = {
    draft: '草稿',
    pending_review: '待审核',
    in_review: '审核中',
    approved: '已通过',
    rejected: '已驳回',
    archived: '已归档',
    deprecated: '已弃用',
  };
  return map[status as string] || (status as string);
}

const STATUS_ACCENT: Record<string, string> = {
  approved:     'border-[var(--color-success)]',
  pending_review: 'border-[var(--color-warning)]',
  in_review:    'border-[var(--color-secondary)]',
  rejected:     'border-[var(--color-error)]',
  draft:        'border-[var(--border-color)] dark:border-neutral-700',
  archived:     'border-[var(--border-color)]',
  deprecated:   'border-[var(--border-color)]',
};

const STATUS_BG: Record<string, string> = {
  approved:     'bg-[var(--color-success-container)] dark:bg-[var(--color-success-container)]/20',
  pending_review: 'bg-[var(--color-warning-container)] dark:bg-[var(--color-warning-container)]/20',
  in_review:    'bg-[var(--color-secondary-container)] dark:bg-[var(--color-secondary-container)]/20',
  rejected:     'bg-[var(--color-error-container)] dark:bg-[var(--color-error-container)]/20',
  draft:        'bg-[var(--bg-tertiary)]/40',
  archived:     'bg-[var(--bg-tertiary)]/40',
  deprecated:   'bg-[var(--bg-tertiary)]/40',
};

const STATUS_BAR: Record<string, string> = {
  approved:     'bg-[var(--color-success-container)]0',
  pending_review: 'bg-[var(--color-warning-container)]0',
  in_review:    'bg-[var(--color-secondary-container)]0',
  rejected:     'bg-[var(--color-error-container)]0',
  draft:        'bg-neutral-300',
  archived:     'bg-[var(--border-color)]',
  deprecated:   'bg-[var(--border-color)]',
};

export function FormulaCard({
  formula,
  search,
  isFavorite,
  isSelected,
  onToggleFavorite,
  onToggleSelect,
  onPreview,
}: {
  formula: Formula;
  search: string;
  isFavorite: boolean;
  isSelected: boolean;
  onToggleFavorite: () => void;
  onToggleSelect: () => void;
  onPreview: () => void;
}) {
  const accentBorder = STATUS_ACCENT[formula.status] || STATUS_ACCENT.draft;
  const statusBg     = STATUS_BG[formula.status] || STATUS_BG.draft;
  const statusBar    = STATUS_BAR[formula.status] || STATUS_BAR.draft;
  const isFavOrSelected = isFavorite || isSelected;

  return (
    <Card className={cn(
      'group relative overflow-visible transition-all duration-200',
      'border border-[var(--border-color)] bg-[var(--bg-secondary)] shadow-sm',
      isSelected && 'ring-2 ring-[var(--color-primary-container)] dark:ring-[var(--color-primary)]',
      isFavOrSelected && statusBg,
    )}>
      {/* 顶部状态色条 */}
      <div className={cn('h-[3px] w-full rounded-t-xl', statusBar)} />

      <CardContent className="p-5">
        {/* 收藏按钮 */}
        <button
          onClick={(e) => { e.preventDefault(); e.stopPropagation(); onToggleFavorite(); }}
          className={cn(
            /* A-23：原 26×26（14px 图标 + p-1.5），未达 WCAG 2.5.5 的 44×44。
               撑到 44×44 作命中区，用 -m-[9px] 抵消，视觉位置与原来完全一致。 */
            'absolute top-[var(--space-apple-sm)] right-3 p-1.5 min-w-[44px] min-h-[44px] -m-[9px] inline-flex items-center justify-center rounded-[var(--radius-Apple-sm)] transition-all',
            isFavorite
              ? 'bg-[var(--color-warning-container)] text-[var(--color-warning-text)]0'
              : 'text-[var(--text-muted)] hover:bg-[var(--bg-secondary)] hover:text-[var(--color-warning-text)]',
          )}
          aria-label={isFavorite ? '取消收藏' : '收藏'}
          aria-pressed={isFavorite}
        >
          <Star size={14} className={isFavorite ? 'fill-warning-400 text-[var(--color-warning-text)]' : ''} />
        </button>

        {/* 多选框 */}
        <button
          onClick={(e) => { e.preventDefault(); e.stopPropagation(); onToggleSelect(); }}
          className="w-11 h-11 -m-3 rounded shrink-0 transition-all inline-flex items-center justify-center mt-0.5"
          aria-label={isSelected ? '取消选择' : '选择'}
          aria-pressed={isSelected}
        >
          {/* A-23：20×20 的视觉方框下沉到内层 span，外层 button 只作 44×44 命中区 */}
          <span
            className={cn(
              'w-5 h-5 rounded border-2 shrink-0 transition-all flex items-center justify-center',
              isSelected
                ? 'bg-primary-container border-[var(--color-primary)] text-[var(--color-primary)]'
                : 'border-[var(--border-color)]',
            )}
          >
            {isSelected && <CheckCircle2 size={14} strokeWidth={3} />}
          </span>
        </button>

        {/* 标题区 */}
        <div className="flex items-start justify-between mb-2 pl-7 pr-8">
          <div className="min-w-0 flex-1">
            <h3 className="text-sm font-semibold text-[var(--text-primary)] group-hover:text-[var(--color-primary-text)] dark:group-hover:text-[var(--color-primary-text)] transition-colors line-clamp-1 leading-snug">
              <Highlight text={formula.name} keyword={search} />
            </h3>
            <p className="text-xs text-[var(--text-muted)] mt-0.5 leading-relaxed">
              <Highlight text={formula.code || ''} keyword={search} /> · v{formula.version}
            </p>
          </div>
          <StatusBadge status={formula.status} />
        </div>

        {/* 描述 */}
        {formula.description && (
          <p className="text-xs text-[var(--text-muted)] line-clamp-2 mb-[var(--space-apple-sm)] leading-relaxed pl-7">
            {formula.description}
          </p>
        )}

        {/* 功效标签 */}
        {formula.targetEffects && formula.targetEffects.length > 0 && (
          <div className="flex flex-wrap gap-1.5 mb-[var(--space-apple-sm)] pl-7">
            {formula.targetEffects.slice(0, 3).map((effect: any) => (
              <Badge key={typeof effect === 'string' ? effect : effect.effectName} variant="primary" size="sm">
                {typeof effect === 'string' ? effect : effect.effectName}
              </Badge>
            ))}
            {formula.targetEffects.length > 3 && (
              <Badge variant="neutral" size="sm">
                +{formula.targetEffects.length - 3}
              </Badge>
            )}
          </div>
        )}

        {/* 底部信息 */}
        <div className="flex items-center justify-between pt-3 mt-1 border-t border-[var(--border-color)]">
          <span className="text-xs text-[var(--text-muted)]">{formatDate(formula.updatedAt)}</span>
          <div className="flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
            <button
              onClick={(e) => { e.preventDefault(); onPreview(); }}
              className="p-1.5 rounded-[var(--radius-Apple-sm)] hover:bg-[var(--bg-secondary)] text-[var(--text-muted)] hover:text-[var(--color-primary-text)] dark:hover:text-[var(--color-primary-text)] transition-colors"
              aria-label="快速预览"
            >
              <Eye size={14} />
            </button>
            <Link
              to={`/formulas/${formula.id}`}
              className="p-1.5 rounded-[var(--radius-Apple-sm)] hover:bg-[var(--bg-secondary)] text-[var(--text-muted)] hover:text-[var(--color-primary-text)] dark:hover:text-[var(--color-primary-text)] transition-colors"
              aria-label="查看详情"
            >
              <ArrowRightLeft size={14} />
            </Link>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

/**
 * 配方对比组件
 * 左右对比两个配方的成分、功效、参数等差异
 */
import { useMemo, useState } from 'react'
import { Link } from 'react-router-dom'
import { Sparkles, FlaskConical } from 'lucide-react'
import { useQuery } from '@tanstack/react-query'
import { formulaApi } from '@/api/formula'
import { StatusBadge, Skeleton } from '@/components/ui/Common'
import { Badge, Card, CardHeader, CardTitle, CardContent } from '@/components/ui'
import { CompositionChart } from './CompositionChart'
import { cn } from '@/lib/utils'


/** 配方对比评估数据 */
interface FormulaCompareData {
  risk_factors?: string[]
  passed_checks?: number
  total_checks?: number
  error_count?: number
}

interface FormulaCompareProps {
  leftId: number | null
  rightId: number | null
}

interface ParsedIngredient {
  name: string
  category: string
  dosage: string
  role: string
  is_food_homology: boolean
}

interface ParsedFormula {
  id: number
  name: string
  code: string
  status: string
  description: string | null
  target_effects: string[]
  dosage: string | null
  processing_method: string | null
  storage_conditions: string | null
  shelf_life: number | null
  safety_check: Record<string, unknown> | null
  synergy_analysis: Record<string, unknown> | null
  ingredients: ParsedIngredient[]
}

function parseFormula(formula: any): ParsedFormula | null {
  if (!formula) return null
  const comp = formula.composition || {}
  const list = Array.isArray(comp.ingredients) ? comp.ingredients :
               Array.isArray(comp.components) ? comp.components : []
  return {
    id: formula.id,
    name: formula.name,
    code: formula.code,
    status: formula.status,
    description: formula.description,
    target_effects: formula.target_effects || [],
    dosage: formula.dosage,
    processing_method: formula.processing_method,
    storage_conditions: formula.storage_conditions,
    shelf_life: formula.shelf_life,
    safety_check: formula.safety_check,
    synergy_analysis: formula.synergy_analysis,
    ingredients: list.map((item: any, idx: number) => ({
      name: item.name || item.name_cn || `成分${idx + 1}`,
      category: item.category || item.classification || '-',
      dosage: item.dosage || item.amount || '-',
      role: item.role || '',
      is_food_homology: item.is_food_homology === true || item.is_medical_food === true,
    })),
  }
}

function parseSafety(formula: ParsedFormula | null): { passed: boolean | null; summary: string } {
  if (!formula?.safety_check || typeof formula.safety_check !== 'object') return { passed: null, summary: '' }
  const sc = formula.safety_check
  return {
    passed: (sc.passed ?? sc.is_passed ?? null) as boolean | null,
    summary: (sc.summary ?? '') as string,
  }
}

function parseSynergy(formula: ParsedFormula | null): number | null {
  if (!formula?.synergy_analysis || typeof formula.synergy_analysis !== 'object') return null
  const sa = formula.synergy_analysis
  return (sa.score ?? sa.overall_score ?? null) as number | null
}

export function FormulaCompare({ leftId, rightId }: FormulaCompareProps) {
  const [showAnalysis, setShowAnalysis] = useState(false)

  const { data: leftRaw, isLoading: leftLoading } = useQuery({
    queryKey: ['formula', leftId],
    queryFn: () => formulaApi.get(leftId!),
    enabled: !!leftId,
  })
  const { data: rightRaw, isLoading: rightLoading } = useQuery({
    queryKey: ['formula', rightId],
    queryFn: () => formulaApi.get(rightId!),
    enabled: !!rightId,
  })

  const left = parseFormula(leftRaw)
  const right = parseFormula(rightRaw)

  // 加载分析缓存
  const { data: leftSynergyData } = useQuery({
    queryKey: ['formula-analysis', leftId, 'synergy'],
    queryFn: () => formulaApi.analyzeFormulaSynergy(leftId!),
    enabled: !!leftId && showAnalysis,
    staleTime: 5 * 60 * 1000,
  })
  const { data: rightSynergyData } = useQuery({
    queryKey: ['formula-analysis', rightId, 'synergy'],
    queryFn: () => formulaApi.analyzeFormulaSynergy(rightId!),
    enabled: !!rightId && showAnalysis,
    staleTime: 5 * 60 * 1000,
  })
  const { data: leftStabilityData } = useQuery({
    queryKey: ['formula-analysis', leftId, 'stability'],
    queryFn: () => formulaApi.predictFormulaStability(leftId!),
    enabled: !!leftId && showAnalysis,
    staleTime: 5 * 60 * 1000,
  })
  const { data: rightStabilityData } = useQuery({
    queryKey: ['formula-analysis', rightId, 'stability'],
    queryFn: () => formulaApi.predictFormulaStability(rightId!),
    enabled: !!rightId && showAnalysis,
    staleTime: 5 * 60 * 1000,
  })
  const { data: leftTasteData } = useQuery({
    queryKey: ['formula-analysis', leftId, 'taste'],
    queryFn: () => formulaApi.predictFormulaTaste(leftId!),
    enabled: !!leftId && showAnalysis,
    staleTime: 5 * 60 * 1000,
  })
  const { data: rightTasteData } = useQuery({
    queryKey: ['formula-analysis', rightId, 'taste'],
    queryFn: () => formulaApi.predictFormulaTaste(rightId!),
    enabled: !!rightId && showAnalysis,
    staleTime: 5 * 60 * 1000,
  })
  const { data: leftCompatData } = useQuery({
    queryKey: ['formula-analysis', leftId, 'compat'],
    queryFn: () => formulaApi.checkFormulaCompatibility(leftId!),
    enabled: !!leftId && showAnalysis,
    staleTime: 5 * 60 * 1000,
  })
  const { data: rightCompatData } = useQuery({
    queryKey: ['formula-analysis', rightId, 'compat'],
    queryFn: () => formulaApi.checkFormulaCompatibility(rightId!),
    enabled: !!rightId && showAnalysis,
    staleTime: 5 * 60 * 1000,
  })
  const { data: leftSafetyData } = useQuery({
    queryKey: ['formula-analysis', leftId, 'safety'],
    queryFn: () => formulaApi.checkFormulaSafety(leftId!, { daily_dosage_g: 10, target_group: 'adult' }),
    enabled: !!leftId && showAnalysis,
    staleTime: 5 * 60 * 1000,
  })
  const { data: rightSafetyData } = useQuery({
    queryKey: ['formula-analysis', rightId, 'safety'],
    queryFn: () => formulaApi.checkFormulaSafety(rightId!, { daily_dosage_g: 10, target_group: 'adult' }),
    enabled: !!rightId && showAnalysis,
    staleTime: 5 * 60 * 1000,
  })

  // 成分对比分析
  const ingredientsComparison = useMemo(() => {
    if (!left && !right) return { onlyLeft: [], onlyRight: [], shared: [] }
    const leftNames = new Set(left?.ingredients.map(i => i.name) || [])
    const rightNames = new Set(right?.ingredients.map(i => i.name) || [])
    const shared = left?.ingredients.filter(i => rightNames.has(i.name)).map(i => i.name) || []
    const onlyLeft = left?.ingredients.filter(i => !rightNames.has(i.name)).map(i => i.name) || []
    const onlyRight = right?.ingredients.filter(i => !leftNames.has(i.name)).map(i => i.name) || []
    return { onlyLeft, onlyRight, shared }
  }, [left, right])

  // 功效对比
  const effectsComparison = useMemo(() => {
    if (!left && !right) return { onlyLeft: [], onlyRight: [], shared: [] }
    const leftSet = new Set(left?.target_effects || [])
    const rightSet = new Set(right?.target_effects || [])
    const shared = [...leftSet].filter(e => rightSet.has(e))
    const onlyLeft = [...leftSet].filter(e => !rightSet.has(e))
    const onlyRight = [...rightSet].filter(e => !leftSet.has(e))
    return { onlyLeft, onlyRight, shared }
  }, [left, right])

  if (!leftId && !rightId) {
    return (
      <div className="text-center py-12">
        <Sparkles size={48} className="mx-auto text-[var(--text-muted)] dark:text-[var(--text-muted)] mb-[var(--space-apple-sm)]" />
        <p className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">请从配方列表中选择两个配方进行对比</p>
        <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">点击配方卡片上的对比按钮，或在配方详情页点击「对比」</p>
      </div>
    )
  }

  const leftSafety = parseSafety(left)
  const rightSafety = parseSafety(right)
  const leftSynergy = parseSynergy(left)
  const rightSynergy = parseSynergy(right)

  return (
    <div className="space-y-[var(--space-apple-md)]">
      {/* 对比概览 */}
      <div className="grid grid-cols-2 gap-[var(--space-apple-sm)]">
        {/* 左侧 */}
        <Card className={cn('overflow-hidden', leftId ? '' : 'opacity-50')}>
          <CardContent className="p-[var(--space-apple-sm)]">
            {leftLoading ? (
              <Skeleton className="h-5 w-28 mb-1.5" />
            ) : left ? (
              <>
                <div className="flex items-center gap-2 mb-1">
                  <Link to={`/formulas/${left.id}`} className="font-semibold text-[var(--text-primary)] hover:text-[var(--color-primary-text)]">
                    {left.name}
                  </Link>
                  <StatusBadge status={left.status} />
                </div>
                <p className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{left.code}</p>
              </>
            ) : (
              <p className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">选择配方 A</p>
            )}
          </CardContent>
        </Card>

        <Card className={cn('overflow-hidden', rightId ? '' : 'opacity-50')}>
          <CardContent className="p-[var(--space-apple-sm)]">
            {rightLoading ? (
              <Skeleton className="h-5 w-28 mb-1.5" />
            ) : right ? (
              <>
                <div className="flex items-center gap-2 mb-1">
                  <Link to={`/formulas/${right.id}`} className="font-semibold text-[var(--text-primary)] hover:text-[var(--color-primary-text)]">
                    {right.name}
                  </Link>
                  <StatusBadge status={right.status} />
                </div>
                <p className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{right.code}</p>
              </>
            ) : (
              <p className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">选择配方 B</p>
            )}
          </CardContent>
        </Card>
      </div>

      {/* 深度分析切换 */}
      {leftId && rightId && (
        <div className="flex items-center justify-between">
          <button
            type="button"
            onClick={() => setShowAnalysis((v) => !v)}
            className={`flex items-center gap-2 px-[var(--space-apple-md)] py-2 rounded-[var(--radius-Apple-sm)] text-sm font-medium transition-colors ${
              showAnalysis
                ? 'bg-[var(--color-accent-container)] dark:bg-[var(--color-accent-container)]/25 text-[var(--color-accent-text)] dark:text-[var(--color-accent-text)] border border-[var(--color-accent-border)] dark:border-[var(--color-accent)]'
                : 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)] border border-[var(--border-color)] hover:border-[var(--color-accent-border)] dark:hover:border-[var(--color-accent)]'
            }`}
          >
            <FlaskConical size={14} />
            {showAnalysis ? '隐藏深度分析' : '运行深度分析对比'}
          </button>
        </div>
      )}

      {/* 深度分析对比 */}
      {showAnalysis && leftId && rightId && (
        <div className="space-y-[var(--space-apple-md)]">
          {/* 协同效应对比 */}
          <div className="grid grid-cols-2 gap-[var(--space-apple-sm)]">
            {[
              { data: leftSynergyData, label: left?.name ?? 'A', loading: false },
              { data: rightSynergyData, label: right?.name ?? 'B', loading: false },
            ].map(({ data, label }) => (
              <div key={label} className="rounded-[var(--radius-Apple-md)] border border-[var(--border-color)] p-[var(--space-apple-md)] bg-[var(--bg-secondary)]">
                <p className="text-xs font-medium text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-2">{label} · 协同效应</p>
                {data ? (
                  <div>
                    <p className="text-2xl font-bold text-[var(--color-accent-text)] dark:text-[var(--color-accent-text)]">
                      {data.overall_si?.toFixed(2) ?? '—'}
                    </p>
                    <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">{data.pairs?.length ?? 0} 个成分对</p>
                  </div>
                ) : (
                  <Skeleton className="h-6 w-16" />
                )}
              </div>
            ))}
          </div>

          {/* 稳定性对比 */}
          <div className="grid grid-cols-2 gap-[var(--space-apple-sm)]">
            {[
              { data: leftStabilityData, label: left?.name ?? 'A' },
              { data: rightStabilityData, label: right?.name ?? 'B' },
            ].map(({ data, label }) => (
              <div key={label} className="rounded-[var(--radius-Apple-md)] border border-[var(--border-color)] p-[var(--space-apple-md)] bg-[var(--bg-secondary)]">
                <p className="text-xs font-medium text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-2">{label} · 稳定性</p>
                {data ? (
                  <div className="space-y-1">
                    <p className="text-lg font-bold text-[var(--color-success-text)] dark:text-[var(--color-success-text)]">
                      {data.stability_score?.toFixed(0) ?? '—'}/100
                    </p>
                    <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                      预测货架期: {data.predicted_shelf_life_months?.toFixed(0) ?? '—'} 月
                    </p>
                    {((data as FormulaCompareData)?.risk_factors?.length ?? 0) > 0 && (
                      <p className="text-xs text-[var(--color-warning-text)] dark:text-[var(--color-warning-text)]">
                        ⚠ {(data as FormulaCompareData)?.risk_factors?.length} 个风险因素
                      </p>
                    )}
                  </div>
                ) : (
                  <Skeleton className="h-6 w-20" />
                )}
              </div>
            ))}
          </div>

          {/* 风味对比 */}
          <div className="grid grid-cols-2 gap-[var(--space-apple-sm)]">
            {[
              { data: leftTasteData, label: left?.name ?? 'A' },
              { data: rightTasteData, label: right?.name ?? 'B' },
            ].map(({ data, label }) => (
              <div key={label} className="rounded-[var(--radius-Apple-md)] border border-[var(--border-color)] p-[var(--space-apple-md)] bg-[var(--bg-secondary)]">
                <p className="text-xs font-medium text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-2">{label} · 风味</p>
                {data ? (
                  <div className="space-y-1">
                    <div className="flex gap-1">
                      {(['bitter', 'sweet', 'umami', 'astringent', 'sour'] as const).map((k) => {
                        const val = data.taste_profile?.[k] ?? 0
                        const colors: Record<string, string> = {
                          bitter: 'bg-danger-400', sweet: 'bg-danger-400', umami: 'bg-[var(--color-warning)]',
                          astringent: 'bg-[var(--color-accent)]', sour: 'bg-[var(--color-success)]',
                        }
                        const labels: Record<string, string> = { bitter: '苦', sweet: '甜', umami: '鲜', astringent: '涩', sour: '酸' }
                        return (
                          <div key={k} className="flex-1 text-center">
                            <div className={`h-2 rounded ${colors[k]} opacity-60`} style={{ height: `${Math.max(4, val * 24)}px` }} />
                            <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-0.5">{labels[k]}</p>
                          </div>
                        )
                      })}
                    </div>
                    <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                      平衡度: {data.balance_score?.toFixed(2) ?? '—'} · 接受度: {data.acceptability?.toFixed(2) ?? '—'}
                    </p>
                  </div>
                ) : (
                  <Skeleton className="h-6 w-20" />
                )}
              </div>
            ))}
          </div>

          {/* 兼容性对比 */}
          <div className="grid grid-cols-2 gap-[var(--space-apple-sm)]">
            {[
              { data: leftCompatData, label: left?.name ?? 'A' },
              { data: rightCompatData, label: right?.name ?? 'B' },
            ].map(({ data, label }) => (
              <div key={label} className="rounded-[var(--radius-Apple-md)] border border-[var(--border-color)] p-[var(--space-apple-md)] bg-[var(--bg-secondary)]">
                <p className="text-xs font-medium text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-2">{label} · 兼容性</p>
                {data ? (
                  <div>
                    <p className="text-2xl font-bold text-[var(--color-secondary-text)] dark:text-[var(--color-secondary-text)]">
                      {data.overall_score?.toFixed(0) ?? '—'}/100
                    </p>
                    <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">
                      {(data as FormulaCompareData)?.passed_checks ?? 0}/{(data as FormulaCompareData)?.total_checks ?? 0} 项通过
                      {((data as FormulaCompareData)?.error_count ?? 0) > 0 && <span className="text-danger-500 ml-1">({(data as FormulaCompareData)?.error_count} 错误)</span>}
                    </p>
                  </div>
                ) : (
                  <Skeleton className="h-6 w-20" />
                )}
              </div>
            ))}
          </div>

          {/* 安全检查对比 */}
          <div className="grid grid-cols-2 gap-[var(--space-apple-sm)]">
            {[
              { data: leftSafetyData, label: left?.name ?? 'A' },
              { data: rightSafetyData, label: right?.name ?? 'B' },
            ].map(({ data, label }) => (
              <div key={label} className={`rounded-[var(--radius-Apple-md)] border p-[var(--space-apple-md)] bg-[var(--bg-secondary)] ${
                data?.is_safe ? 'border-[var(--color-success-border)] dark:border-[var(--color-success)]' : 'border-danger-200 dark:border-danger-800'
              }`}>
                <p className="text-xs font-medium text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-2">{label} · 安全性</p>
                {data ? (
                  <div className="flex items-center gap-2">
                    {data.is_safe ? (
                      <>
                        <span className="text-[var(--color-success-text)]0">✓</span>
                        <span className="text-sm font-medium text-[var(--color-success-text)] dark:text-[var(--color-success-text)]">安全</span>
                      </>
                    ) : (
                      <>
                        <span className="text-danger-500">⚠</span>
                        <span className="text-sm font-medium text-danger-700 dark:text-danger-700">有风险</span>
                      </>
                    )}
                    <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] ml-auto">风险评分: {data.overall_risk_score?.toFixed(0) ?? '—'}</span>
                  </div>
                ) : (
                  <Skeleton className="h-5 w-16" />
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 指标对比 */}
      <div className="grid grid-cols-3 gap-2">
        <div className="bg-[var(--bg-tertiary)]/50 rounded-[var(--radius-Apple-sm)] p-[var(--space-apple-sm)] text-center">
          <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1.5">安全检查</p>
          <div className="flex justify-center gap-[var(--space-apple-sm)]">
            <span className={leftSafety.passed === true ? 'text-[var(--color-success-text)]0' : leftSafety.passed === false ? 'text-[var(--color-error-text)]0' : 'text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]'}>
              {leftSafety.passed === null ? '-' : leftSafety.passed ? '通过' : '未通过'}
            </span>
            <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">vs</span>
            <span className={rightSafety.passed === true ? 'text-[var(--color-success-text)]0' : rightSafety.passed === false ? 'text-[var(--color-error-text)]0' : 'text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]'}>
              {rightSafety.passed === null ? '-' : rightSafety.passed ? '通过' : '未通过'}
            </span>
          </div>
        </div>
        <div className="bg-[var(--bg-tertiary)]/50 rounded-[var(--radius-Apple-sm)] p-[var(--space-apple-sm)] text-center">
          <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1.5">协同评分</p>
          <div className="flex justify-center gap-[var(--space-apple-sm)]">
            <span className="text-lg font-semibold text-[var(--color-primary-text)]">{leftSynergy ?? '-'}</span>
            <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">vs</span>
            <span className="text-lg font-semibold text-[var(--color-primary-text)]">{rightSynergy ?? '-'}</span>
          </div>
        </div>
        <div className="bg-[var(--bg-tertiary)]/50 rounded-[var(--radius-Apple-sm)] p-[var(--space-apple-sm)] text-center">
          <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1.5">成分数量</p>
          <div className="flex justify-center gap-[var(--space-apple-sm)]">
            <span className="text-lg font-semibold text-[var(--text-primary)]">{left?.ingredients.length ?? 0}</span>
            <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">vs</span>
            <span className="text-lg font-semibold text-[var(--text-primary)]">{right?.ingredients.length ?? 0}</span>
          </div>
        </div>
      </div>

      {/* 成分对比 */}
      <Card>
        <CardHeader className="py-2.5 px-[var(--space-apple-sm)]">
          <CardTitle as="h3" className="text-sm">成分对比</CardTitle>
        </CardHeader>
        <CardContent className="space-y-[var(--space-apple-sm)] p-[var(--space-apple-sm)]">
          {ingredientsComparison.shared.length > 0 && (
            <div>
              <div className="flex items-center gap-2 mb-1.5">
                <span className="text-sm font-medium text-[var(--text-primary)]">共同成分</span>
                <Badge variant="primary" size="sm">{ingredientsComparison.shared.length}</Badge>
              </div>
              <div className="flex flex-wrap gap-1.5">
                {ingredientsComparison.shared.map(name => (
                  <Badge key={name} variant="primary" size="sm">{name}</Badge>
                ))}
              </div>
            </div>
          )}

          {(ingredientsComparison.onlyLeft.length > 0 || ingredientsComparison.onlyRight.length > 0) && (
            <div className="grid grid-cols-2 gap-[var(--space-apple-sm)]">
              <div>
                <div className="flex items-center gap-2 mb-1.5">
                  <span className="text-sm font-medium text-[var(--text-primary)]">配方 A 独有</span>
                  <Badge variant="info" size="sm">{ingredientsComparison.onlyLeft.length}</Badge>
                </div>
                <div className="flex flex-wrap gap-1.5">
                  {ingredientsComparison.onlyLeft.map(name => (
                    <Badge key={name} variant="info" size="sm">{name}</Badge>
                  ))}
                </div>
              </div>
              <div>
                <div className="flex items-center gap-2 mb-1.5">
                  <span className="text-sm font-medium text-[var(--text-primary)]">配方 B 独有</span>
                  <Badge variant="warning" size="sm">{ingredientsComparison.onlyRight.length}</Badge>
                </div>
                <div className="flex flex-wrap gap-1.5">
                  {ingredientsComparison.onlyRight.map(name => (
                    <Badge key={name} variant="warning" size="sm">{name}</Badge>
                  ))}
                </div>
              </div>
            </div>
          )}

          {/* 成分可视化 */}
          <div className="grid grid-cols-2 gap-[var(--space-apple-sm)] pt-3 border-t border-[var(--border-color)]">
            <div>
              <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-2">配方 A 成分分布</p>
              {left && left.ingredients.length > 0 ? (
                <CompositionChart ingredients={left.ingredients} compact />
              ) : (
                <p className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">暂无数据</p>
              )}
            </div>
            <div>
              <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-2">配方 B 成分分布</p>
              {right && right.ingredients.length > 0 ? (
                <CompositionChart ingredients={right.ingredients} compact />
              ) : (
