﻿/**
 * 配方快速预览组件
 * 在列表页弹窗显示配方核心信息，无需跳转到详情页
 */
import { useMemo, useRef, useEffect } from 'react';
import { useFocusTrap } from '@/hooks/useFocusTrap';
import { X, ArrowRight, Zap } from 'lucide-react';
import { useQuery } from '@tanstack/react-query';
import { formulaApi } from '@/api/formula';
import { StatusBadge, Skeleton } from '@/components/ui/Common';
import { Button, Badge } from '@/components/ui';
import { CompositionChart } from './CompositionChart';
import { cn } from '@/lib/utils';

interface FormulaQuickViewProps {
  formulaId: number | null;
  onClose: () => void;
  onNavigate: (id: number) => void;
}

export function FormulaQuickView({ formulaId, onClose, onNavigate }: FormulaQuickViewProps) {
  const panelRef = useRef<HTMLDivElement>(null);
  useFocusTrap(panelRef, !!formulaId, onClose);

  const { data: formula, isLoading } = useQuery({
    queryKey: ['formula', formulaId],
    queryFn: () => formulaApi.get(formulaId!),
    enabled: !!formulaId,
  });

  const ingredientList = useMemo(() => {
    if (!formula?.composition || typeof formula.composition !== 'object') return [];
    const comp = formula.composition as Record<string, unknown>;
    const list = comp.ingredients ?? comp.components;
    if (!Array.isArray(list)) return [];
    return list.map((item: Record<string, unknown>, idx: number) => ({
      name: (item.name ?? item.name ?? `成分${idx + 1}`) as string,
      category: (item.category ?? item.classification ?? '-') as string,
      is_food_homology: item.is_food_homology === true || item.is_medical_food === true,
      dosage: (item.dosage ?? item.amount ?? '-') as string,
      role: (item.role ?? '') as string,
    }));
  }, [formula?.composition]);

  const safetyPassed = useMemo(() => {
    if (!formula?.safety_check || typeof formula.safety_check !== 'object') return null;
    const sc = formula.safety_check as Record<string, unknown>;
    return sc.passed ?? sc.is_passed ?? null;
  }, [formula?.safety_check]);

  const synergyScore = useMemo(() => {
    if (!formula?.synergy_analysis || typeof formula.synergy_analysis !== 'object') return null;
    const sa = formula.synergy_analysis as Record<string, unknown>;
    return (sa.score ?? sa.overall_score ?? null) as number | null;
  }, [formula?.synergy_analysis]);

  if (!formulaId) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-[var(--space-apple-md)]">
      <div className="absolute inset-0 bg-black/50 backdrop-blur-sm"  role="button" tabIndex={0} onClick={onClose} />
      <div
        ref={panelRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby="quick-view-title"
        className="relative w-full max-w-2xl max-h-[85vh] bg-[var(--bg-secondary)] rounded-[var(--radius-Apple-md)] shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-200"
      >
        <div className="flex items-center justify-between px-[var(--space-apple-md)] py-[var(--space-apple-md)] border-b border-[var(--border-color)]">
          <div className="flex items-center gap-2">
            {isLoading ? (
              <Skeleton className="w-8 h-8 rounded-[var(--radius-Apple-sm)]" />
            ) : (
              <div className="w-8 h-8 rounded-[var(--radius-Apple-sm)] bg-[var(--color-primary-container)] flex items-center justify-center">
                <Zap size={16} className="text-[var(--color-primary-text)]0" />
              </div>
            )}
            <div>
              {isLoading ? (
                <>
                  <Skeleton className="w-28 h-4 mb-1" />
                  <Skeleton className="w-16 h-3.5" />
                </>
              ) : (
                <>
                  <h2 id="quick-view-title" className="text-base font-semibold text-[var(--text-primary)]">{formula?.name}</h2>
                  <div className="flex items-center gap-2 mt-0.5">
                    <span className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{formula?.code}</span>
                    <StatusBadge status={formula!.status} />
                  </div>
                </>
              )}
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 rounded-[var(--radius-Apple-sm)] hover:bg-[var(--bg-secondary)] text-[var(--text-muted)] hover:text-[var(--text-secondary)] transition-colors"
          >
            <X size={18} />
          </button>
        </div>

        <div className="overflow-y-auto max-h-[calc(85vh-120px)] p-[var(--space-apple-md)]">
          {isLoading ? (
            <div className="space-y-[var(--space-apple-sm)]">
              <Skeleton className="w-full h-20" />
              <Skeleton className="w-full h-40" />
              <Skeleton className="w-full h-28" />
            </div>
          ) : formula ? (
            <div className="space-y-[var(--space-apple-md)]">
              {formula.description && (
                <p className="text-sm text-[var(--text-secondary)] leading-relaxed">{formula.description}</p>
              )}

              {formula.targetEffects && formula.targetEffects.length > 0 && (
                <div>
                  <h4 className="text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider mb-2">
                    目标功效
                  </h4>
                  <div className="flex flex-wrap gap-1.5">
                    {formula.targetEffects.map((effect) => {
                      const label = typeof effect === 'string' ? effect : effect.effectName;
                      return (
                        <Badge key={label} variant="primary" size="sm">
                          {label}
                        </Badge>
                      );
                    })}
                  </div>
                </div>
              )}

              <div className="grid grid-cols-3 gap-2">
                <div className="bg-[var(--bg-tertiary)]/50 rounded-[var(--radius-Apple-sm)] p-2.5 text-center">
                  <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">安全检查</p>
                  <p
                    className={cn(
                      'text-base font-semibold',
                      safetyPassed === true
                        ? 'text-[var(--color-success-text)]'
                        : safetyPassed === false
                          ? 'text-[var(--color-error-text)]'
                          : 'text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]',
                    )}
                  >
                    {safetyPassed === null ? '未检测' : safetyPassed ? '通过' : '未通过'}
                  </p>
                </div>
                <div className="bg-[var(--bg-tertiary)]/50 rounded-[var(--radius-Apple-sm)] p-2.5 text-center">
                  <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">协同评分</p>
                  <p className="text-base font-semibold text-[var(--color-primary-text)]">
                    {synergyScore !== null ? synergyScore : '-'}
                  </p>
                </div>
                <div className="bg-[var(--bg-tertiary)]/50 rounded-[var(--radius-Apple-sm)] p-2.5 text-center">
                  <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">成分数量</p>
                  <p className="text-base font-semibold text-[var(--text-primary)]">{ingredientList.length}</p>
                </div>
              </div>

              {ingredientList.length > 0 && (
                <div>
                  <h4 className="text-xs font-semibold text-[var(--text-muted)] uppercase tracking-wider mb-2">
                    成分组成
                  </h4>
                  <CompositionChart ingredients={ingredientList} compact />
                  <div className="mt-2 max-h-28 overflow-y-auto">
                    <table className="w-full text-sm">
                      <tbody className="divide-y divide-neutral-100 dark:divide-neutral-800">
                        {ingredientList.map((ing, i) => (
                          <tr key={i}>
                            <td className="py-1.5">
                              <span className="font-medium text-[var(--text-primary)]">{ing.name}</span>
                              {ing.role && (
                                <Badge variant="info" size="sm" className="ml-1">
                                  {ing.role}
                                </Badge>
                              )}
                            </td>
                            <td className="py-1.5 text-right text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{ing.dosage}</td>
                            <td className="py-1.5 text-right">
                              {ing.is_food_homology && (
                                <Badge variant="success" size="sm">
                                  药食同源
                                </Badge>
                              )}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              )}

              <div className="grid grid-cols-2 gap-2">
                {[
                  { label: '服用剂量', value: formula.dosage },
                  { label: '加工工艺', value: formula.processing_method },
                  { label: '储藏条件', value: formula.storage_conditions },
                  { label: '保质期', value: formula.shelf_life ? `${formula.shelf_life} 天` : null },
                ]
                  .filter((p) => p.value)
                  .map(({ label, value }) => (
                    <div key={label} className="bg-[var(--bg-tertiary)]/50 rounded-[var(--radius-Apple-sm)] p-2">
                      <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">{label}</p>
                      <p className="text-sm font-medium text-[var(--text-primary)] mt-0.5">{value}</p>
                    </div>
                  ))}
              </div>
            </div>
          ) : (
            <div className="text-center py-[var(--space-apple-lg)] text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">配方不存在</div>
          )}
        </div>

        <div className="flex items-center justify-between px-[var(--space-apple-md)] py-[var(--space-apple-md)] border-t border-[var(--border-color)] bg-[var(--bg-tertiary)]/50 dark:bg-[var(--bg-tertiary)]/50">
          <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
            {isLoading
              ? ''
              : `版本 v${formula?.version} · 创建于 ${formula ? new Date(formula.createdAt).toLocaleDateString('zh-CN') : ''}`}
          </span>
          <div className="flex items-center gap-2">
            <Button variant="secondary" size="sm" onClick={() => onNavigate(formulaId)}>
              复制
            </Button>
            <Button
              size="sm"
              icon={<ArrowRight size={14} />}
              onClick={() => {
                onClose();
                onNavigate(formulaId);
              }}
            >
              查看详情
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { useFocusTrap } from '@/hooks/useFocusTrap';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import {
  FileText,
  Download,
  X,
  ChevronLeft,
  ChevronRight,
  ChevronsLeft,
  ChevronsRight,
  ArrowUpDown,
  Filter,
  CheckCircle2,
  XCircle,
  AlertTriangle,
  Clock,
  User,
  Activity,
  Eye,
  Search,
} from 'lucide-react';
import { formulaApi } from '@/api/formula';
import type { OperationAction, OperationLogQueryParams } from '@/types/formula';
import { Button, Modal, Select, Input, Badge, Tooltip } from '@/components/ui';
import { cn } from '@/lib/utils';
import { logger } from '@/utils/safeLogger';

interface OperationLogPanelProps {
  open: boolean;
  onClose: () => void;
  targetId?: string;
  targetType?: string;
}

type TimeRange = 'today' | '7days' | '30days' | 'custom';
type SortField = 'created_at' | 'action' | 'operator_name';
type SortOrder = 'asc' | 'desc';

const ACTION_LABELS: Record<OperationAction, string> = {
  create: '创建',
  update: '编辑',
  delete: '删除',
  import: '导入',
  export: '导出',
  approve: '审核通过',
  reject: '审核驳回',
  archive: '归档',
  restore: '恢复',
  rollback: '版本回滚',
  permission_change: '权限变更',
  batch_operation: '批量操作',
  undo_delete: '撤销删除',
};

const ACTION_OPTIONS = Object.entries(ACTION_LABELS).map(([value, label]) => ({
  value,
  label,
}));

const TIME_RANGE_OPTIONS = [
  { value: 'today', label: '今天' },
  { value: '7days', label: '最近7天' },
  { value: '30days', label: '最近30天' },
  { value: 'custom', label: '自定义' },
];

const RESULT_OPTIONS = [
  { value: '', label: '全部' },
  { value: 'success', label: '成功' },
  { value: 'failure', label: '失败' },
  { value: 'partial', label: '部分成功' },
];

const PAGE_SIZE = 20;

export default function OperationLogPanel({ open, onClose, targetId, targetType }: OperationLogPanelProps) {
  const panelRef = useRef<HTMLDivElement>(null);
  useFocusTrap(panelRef, open, onClose);
  const queryClient = useQueryClient();

  const [page, setPage] = useState(1);
  const [timeRange, setTimeRange] = useState<TimeRange>('7days');
  const [customStartDate, setCustomStartDate] = useState('');
  const [customEndDate, setCustomEndDate] = useState('');
  const [selectedOperator, setSelectedOperator] = useState('');
  const [selectedActions, setSelectedActions] = useState<OperationAction[]>([]);
  const [selectedResult, setSelectedResult] = useState<string>('');
  const [sortField, setSortField] = useState<SortField>('created_at');
  const [sortOrder, setSortOrder] = useState<SortOrder>('desc');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedLogId, setSelectedLogId] = useState<string | null>(null);
  const [isExporting, setIsExporting] = useState(false);

  const getDateRange = useCallback(() => {
    const now = new Date();
    const today = now.toISOString().split('T')[0];

    switch (timeRange) {
      case 'today':
        return { start_date: today, end_date: today };
      case '7days': {
        const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
        return { start_date: sevenDaysAgo.toISOString().split('T')[0], end_date: today };
      }
      case '30days': {
        const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
        return { start_date: thirtyDaysAgo.toISOString().split('T')[0], end_date: today };
      }
      case 'custom':
        return { start_date: customStartDate, end_date: customEndDate };
      default:
        return {};
    }
  }, [timeRange, customStartDate, customEndDate]);

  const queryParams: OperationLogQueryParams = useMemo(
    () => ({
      page,
      page_size: PAGE_SIZE,
      ...getDateRange(),
      ...(selectedOperator && { operator_id: selectedOperator }),
      ...(selectedActions.length > 0 && { action: selectedActions[0] }),
      ...(selectedResult && { result: selectedResult as 'success' | 'failure' | 'partial' }),
      sort_field: sortField,
      sort_order: sortOrder,
      ...(targetId && { target_id: targetId }),
      ...(targetType && { target_type: targetType }),
    }),
    [page, getDateRange, selectedOperator, selectedActions, selectedResult, sortField, sortOrder, targetId, targetType],
  );

  const {
    data: logsData,
    isLoading,
    error,
  } = useQuery({
    queryKey: ['operation-logs', queryParams],
    queryFn: () => formulaApi.getOperationLogs(queryParams),
    enabled: open,
  });

  const logs = logsData?.data || [];
  const total = logsData?.total || 0;
  const totalPages = Math.ceil(total / PAGE_SIZE);

  const uniqueOperators = useMemo(() => {
    const operatorMap = new Map<string, string>();
    logs.forEach((log) => {
      if (!operatorMap.has(log.operatorId)) {
        operatorMap.set(log.operatorId, log.operatorName);
      }
    });
    return Array.from(operatorMap.entries()).map(([id, name]) => ({
      id,
      name,
    }));
  }, [logs]);

  useEffect(() => {
    if (!open) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setPage(1);
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setSearchQuery('');
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setSelectedLogId(null);
    }
  }, [open]);

  useEffect(() => {
    if (open) {
      const interval = setInterval(() => {
        queryClient.invalidateQueries({ queryKey: ['operation-logs'] });
      }, 30000);
      return () => clearInterval(interval);
    }
    return undefined;
  }, [open, queryClient]);

  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortOrder('desc');
    }
  };

  const handleExport = async () => {
    setIsExporting(true);
    try {
      const blob = await formulaApi.exportLogs(queryParams, 'excel');
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `操作日志_${new Date().toISOString().slice(0, 10)}.xlsx`;
      a.click();
      URL.revokeObjectURL(url);
    } catch (error) {
      logger.error('[OperationLogPanel] Export failed:', error);
    } finally {
      setIsExporting(false);
    }
  };

  const filteredLogs = useMemo(() => {
    if (!searchQuery.trim()) return logs;

    const query = searchQuery.toLowerCase();
    return logs.filter(
      (log) =>
        log.target_name.toLowerCase().includes(query) ||
        log.operatorName.toLowerCase().includes(query) ||
        ACTION_LABELS[log.action]?.toLowerCase().includes(query),
    );
  }, [logs, searchQuery]);

  const selectedLog = useMemo(() => logs.find((log) => log.id === selectedLogId), [logs, selectedLogId]);

  const renderResultBadge = (result: string) => {
    switch (result) {
      case 'success':
        return (
          <Badge variant="success" size="sm">
            <CheckCircle2 className="w-3 h-3 mr-1" />
            成功
          </Badge>
        );
      case 'failure':
        return (
          <Badge variant="danger" size="sm">
            <XCircle className="w-3 h-3 mr-1" />
            失败
          </Badge>
        );
      case 'partial':
        return (
          <Badge variant="warning" size="sm">
            <AlertTriangle className="w-3 h-3 mr-1" />
            部分成功
          </Badge>
        );
      default:
        return (
          <Badge variant="neutral" size="sm">
            {result}
          </Badge>
        );
    }
  };

  if (!open) return null;

  return (
    <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-[var(--space-apple-md)]">
      <div
        ref={panelRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby="operation-log-title"
        className="bg-[var(--bg-secondary)] rounded-[var(--radius-Apple-md)] shadow-2xl w-full max-w-7xl max-h-[90vh] flex flex-col"
      >
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-[var(--border-color)]">
          <div className="flex items-center gap-[var(--space-apple-sm)]">
            <FileText className="w-5 h-5 text-[var(--color-primary-text)]" />
            <h2 id="operation-log-title" className="text-lg font-semibold text-[var(--text-primary)]">操作日志</h2>
            <Badge variant="neutral" size="sm">
              共 {total} 条
            </Badge>
          </div>

          <div className="flex items-center gap-2">
            <Button
              variant="outline"
              size="sm"
              icon={<Download className="w-4 h-4" />}
              onClick={handleExport}
              loading={isExporting}
            >
              导出
            </Button>
            <button
              onClick={onClose}
              className="p-2 hover:bg-[var(--bg-secondary)] rounded-[var(--radius-Apple-sm)] transition-colors"
            >
              <X className="w-5 h-5 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
            </button>
          </div>
        </div>

        {/* Filters */}
        <div className="px-6 py-4 border-b border-[var(--border-color)] space-y-[var(--space-apple-sm)]">
          <div className="flex items-center gap-2 text-sm text-[var(--text-secondary)]">
            <Filter className="w-4 h-4" />
            <span className="font-medium">筛选条件</span>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-[var(--space-apple-sm)]">
            <Select
              value={timeRange}
              onChange={(v) => setTimeRange(v as TimeRange)}
              placeholder="时间范围"
            >
              {TIME_RANGE_OPTIONS.map((o) => (
                <option key={o.value} value={o.value}>
                  {o.label}
                </option>
              ))}
            </Select>

            {timeRange === 'custom' && (
              <>
                <Input
                  type="date"
                  value={customStartDate}
                  onChange={(e: React.ChangeEvent<HTMLInputElement>) => setCustomStartDate(e.target.value)}
                />
                <Input
                  type="date"
                  value={customEndDate}
                  onChange={(e: React.ChangeEvent<HTMLInputElement>) => setCustomEndDate(e.target.value)}
                  placeholder="结束日期"
                />
              </>
            )}

            <Select value={selectedOperator} onChange={(v) => setSelectedOperator(v)} placeholder="操作人">
              <option value="">全部操作人</option>
              {uniqueOperators.map((o) => (
                <option key={o.id} value={o.id}>
                  {o.name}
                </option>
              ))}
            </Select>

            <Select
              value={selectedActions[0] || ''}
              onChange={(v) => setSelectedActions(v ? [v as OperationAction] : [])}
              placeholder="操作类型"
            >
              <option value="">全部操作类型</option>
              {ACTION_OPTIONS.map((o) => (
                <option key={o.value} value={o.value}>
                  {o.label}
                </option>
              ))}
            </Select>

            <Select value={selectedResult} onChange={(v) => setSelectedResult(v)} placeholder="操作结果">
              {RESULT_OPTIONS.map((o) => (
                <option key={o.value} value={o.value}>
                  {o.label}
                </option>
              ))}
            </Select>
          </div>

          <div className="flex items-center gap-2">
            <div className="relative flex-1 max-w-md">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
              <input
                type="text"
                value={searchQuery}
                onChange={(e: React.ChangeEvent<HTMLInputElement>) => setSearchQuery(e.target.value)}
                placeholder="搜索目标名称、操作人..."
                className="w-full pl-10 pr-4 py-2 border border-[var(--border-color)] rounded-[var(--radius-Apple-sm)] text-sm focus:ring-2 focus:ring-[var(--color-primary)] focus:border-transparent bg-[var(--bg-secondary)]"
              />
            </div>
          </div>
        </div>

        {/* Table */}
        <div className="flex-1 overflow-auto px-6 py-4">
          {isLoading ? (
            <div className="flex items-center justify-center h-64">
              <div className="animate-spin rounded-[var(--radius-pill)] h-8 w-8 border-b-2 border-[var(--color-primary)]"></div>
            </div>
          ) : error ? (
            <div className="flex items-center justify-center h-64 text-[var(--color-error-text)]">加载失败，请重试</div>
          ) : filteredLogs.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-64 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
              <FileText className="w-12 h-12 mb-[var(--space-apple-sm)] opacity-50" />
              <p className="text-sm">暂无日志记录</p>
            </div>
          ) : (
            <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-[var(--bg-tertiary)] sticky top-0">
                <tr>
                  <th
                    className="px-[var(--space-apple-md)] py-[var(--space-apple-md)] text-left font-medium text-[var(--text-primary)] cursor-pointer hover:bg-[var(--bg-tertiary)] dark:hover:bg-[var(--bg-secondary)]"
                    onClick={() => handleSort('created_at')}
                  >
                    <div className="flex items-center gap-1">
                      <Clock className="w-4 h-4" />
                      时间
                      <ArrowUpDown className="w-3 h-3" />
                    </div>
                  </th>
                  <th
                    className="px-[var(--space-apple-md)] py-[var(--space-apple-md)] text-left font-medium text-[var(--text-primary)] cursor-pointer hover:bg-[var(--bg-tertiary)] dark:hover:bg-[var(--bg-secondary)]"
                    onClick={() => handleSort('operator_name')}
                  >
                    <div className="flex items-center gap-1">
                      <User className="w-4 h-4" />
                      操作人
                      <ArrowUpDown className="w-3 h-3" />
                    </div>
                  </th>
                  <th
                    className="px-[var(--space-apple-md)] py-[var(--space-apple-md)] text-left font-medium text-[var(--text-primary)] cursor-pointer hover:bg-[var(--bg-tertiary)] dark:hover:bg-[var(--bg-secondary)]"
                    onClick={() => handleSort('action')}
                  >
                    <div className="flex items-center gap-1">
                      <Activity className="w-4 h-4" />
                      操作类型
                      <ArrowUpDown className="w-3 h-3" />
                    </div>
                  </th>
                  <th className="px-[var(--space-apple-md)] py-[var(--space-apple-md)] text-left font-medium text-[var(--text-primary)]">操作对象</th>
                  <th className="px-[var(--space-apple-md)] py-[var(--space-apple-md)] text-left font-medium text-[var(--text-primary)]">结果</th>
                  <th className="px-[var(--space-apple-md)] py-[var(--space-apple-md)] text-left font-medium text-[var(--text-primary)]">操作</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-neutral-200 dark:divide-neutral-700">
                {filteredLogs.map((log) => (
                  <tr
                    key={log.id}
                    className={cn(
                      'hover:bg-[var(--bg-tertiary)] dark:hover:bg-[var(--bg-tertiary)] cursor-pointer transition-colors',
                      selectedLogId === log.id && 'bg-[var(--color-primary-container)]',
                    )}
                    onClick={() => setSelectedLogId(log.id)}
                  >
                    <td className="px-[var(--space-apple-md)] py-[var(--space-apple-md)] text-[var(--text-primary)] whitespace-nowrap">
                      {new Date(log.created_at).toLocaleString('zh-CN', {
                        month: '2-digit',
                        day: '2-digit',
                        hour: '2-digit',
                        minute: '2-digit',
                        second: '2-digit',
                      })}
                    </td>
                    <td className="px-[var(--space-apple-md)] py-[var(--space-apple-md)] text-[var(--text-primary)]">{log.operatorName}</td>
                    <td className="px-[var(--space-apple-md)] py-[var(--space-apple-md)]">
                      <Badge variant="neutral" size="sm">
                        {ACTION_LABELS[log.action] || log.action}
                      </Badge>
                    </td>
                    <td className="px-[var(--space-apple-md)] py-[var(--space-apple-md)] text-[var(--text-primary)] max-w-xs truncate">
                      {log.target_name}
                    </td>
                    <td className="px-[var(--space-apple-md)] py-[var(--space-apple-md)]">{renderResultBadge(log.result)}</td>
                    <td className="px-[var(--space-apple-md)] py-[var(--space-apple-md)]">
                      <Tooltip content="查看详情">
                        <button className="p-1 hover:bg-[var(--bg-tertiary)] dark:hover:bg-[var(--bg-secondary)] rounded">
                          <Eye className="w-4 h-4 text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
                        </button>
                      </Tooltip>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
            </div>
          )}
        </div>

        {/* Pagination */}
        {totalPages > 1 && (
          <div className="px-6 py-4 border-t border-[var(--border-color)] flex items-center justify-between">
            <div className="text-sm text-[var(--text-secondary)]">
              共 {total} 条 · 第 {page}/{totalPages} 页
            </div>
            <div className="flex items-center gap-2">
              <Button
                variant="ghost"
                size="sm"
                icon={<ChevronsLeft className="w-4 h-4" />}
                onClick={() => setPage(1)}
                disabled={page === 1}
              />
              <Button
                variant="ghost"
                size="sm"
                icon={<ChevronLeft className="w-4 h-4" />}
                onClick={() => setPage(page - 1)}
                disabled={page === 1}
              />
              <span className="text-sm text-[var(--text-secondary)] px-2">{page}</span>
              <Button
                variant="ghost"
                size="sm"
                icon={<ChevronRight className="w-4 h-4" />}
                onClick={() => setPage(page + 1)}
                disabled={page >= totalPages}
              />
              <Button
                variant="ghost"
                size="sm"
                icon={<ChevronsRight className="w-4 h-4" />}
                onClick={() => setPage(totalPages)}
                disabled={page >= totalPages}
              />
            </div>
          </div>
        )}

        {/* Detail Modal */}
        <Modal open={!!selectedLog} onClose={() => setSelectedLogId(null)} title="日志详情" size="lg">
          {selectedLog &&
            (() => {
              const log = selectedLog;
              return (
                <div className="space-y-6">
                  {/* Basic Info */}
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-xs font-medium text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">操作时间</label>
                      <div className="text-sm text-[var(--text-primary)]">
                        {new Date(log.created_at).toLocaleString('zh-CN')}
                      </div>
                    </div>
                    <div>
                      <label className="block text-xs font-medium text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">操作人</label>
                      <div className="text-sm text-[var(--text-primary)]">
                        {log.operatorName} ({log.operatorRole})
                      </div>
                    </div>
                    <div>
                      <label className="block text-xs font-medium text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">操作类型</label>
                      <div className="text-sm">{renderResultBadge(log.result)}</div>
                    </div>
                    <div>
                      <label className="block text-xs font-medium text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">IP 地址</label>
                      <div className="text-sm text-[var(--text-primary)]">{log.ip_address || '-'}</div>
                    </div>
                  </div>

                  {/* Target Info */}
                  <div>
                    <label className="block text-xs font-medium text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">操作对象</label>
                    <div className="bg-[var(--bg-tertiary)] rounded-[var(--radius-Apple-sm)] p-[var(--space-apple-sm)]">
                      <p className="text-sm font-medium text-[var(--text-primary)]">{log.target_name}</p>
                      <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">
                        类型: {log.target_type} · ID: {log.target_id}
                      </p>
                    </div>
                  </div>

                  {/* Changes Diff */}
                  {log.details?.changes && Object.keys(log.details.changes).length > 0 && (
                    <div>
                      <label className="block text-xs font-medium text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-2">变更详情</label>
                      <div className="space-y-2">
                        {Object.entries(log.details.changes).map(([key, change]) => (
                          <div key={key} className="bg-[var(--bg-tertiary)] rounded-[var(--radius-Apple-sm)] p-[var(--space-apple-sm)]">
                            <div className="text-xs font-medium text-[var(--text-secondary)] mb-2">{key}</div>
                            <div className="grid grid-cols-2 gap-2 text-sm">
                              <div>
                                <span className="text-[var(--color-error-text)] line-through mr-2">{JSON.stringify(change.from)}</span>
                              </div>
                              <div>
                                <span className="text-[var(--color-success-text)]">→ {JSON.stringify(change.to)}</span>
                              </div>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}

                  {/* Error Message */}
                  {log.details?.error_message && (
                    <div>
                      <label className="block text-xs font-medium text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">错误信息</label>
                      <div className="bg-[var(--color-error-container)] border border-[var(--color-error-border)] dark:border-[var(--color-error)] rounded-[var(--radius-Apple-sm)] p-[var(--space-apple-sm)]">
                        <p className="text-sm text-[var(--color-error-text)] dark:text-[var(--color-error-text)]">{log.details.error_message}</p>
                      </div>
                    </div>
                  )}

                  {/* Duration & Metadata */}
                  {(log.details?.duration_ms || log.details?.metadata) && (
                    <div className="grid grid-cols-2 gap-4">
                      {log.details?.duration_ms && (
                        <div>
                          <label className="block text-xs font-medium text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">执行耗时</label>
                          <div className="text-sm text-[var(--text-primary)]">
                            {(log.details.duration_ms / 1000).toFixed(2)} 秒
                          </div>
                        </div>
                      )}
                      {log.details?.metadata && (
                        <div>
                          <label className="block text-xs font-medium text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mb-1">元数据</label>
                          <pre className="text-xs bg-[var(--bg-tertiary)] rounded p-2 overflow-auto max-h-32">
                            {JSON.stringify(log.details.metadata, null, 2)}
                          </pre>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              );
            })()}
        </Modal>
      </div>
    </div>
  );
}

/**
 * 配料六维分析页面 — 完整功能版
 * 雷达图可视化 + 添加剂替代建议 + 药食同源检索
 * 主题系统：对齐设计令牌规范（violet→accent, emerald→success, amber/yellow→warning, red→danger, blue→secondary）
 */
import { useState } from 'react'
import { useTranslation } from 'react-i18next'
import {
  Beaker, FlaskConical, AlertTriangle,
  Activity, ShieldAlert, BookOpen, Lightbulb, XCircle,
} from 'lucide-react'
import {
  RadarChart as RechartsRadarChart, Radar, PolarGrid, PolarAngleAxis,
  PolarRadiusAxis, ResponsiveContainer, Tooltip as RechartsTooltip,
} from 'recharts'
import { ingredientApi, type AnalysisResult, type AdditiveInfo } from '@/api/ingredient'
import { complianceApi } from '@/api/compliance'
import { useToast } from '@/components/ui/Toast'
import { Card, CardHeader, CardTitle, CardContent, Button, Input } from '@/components/ui'

// ─── 本地存储 ────────────────────────────────────────────────
const STORAGE_KEY = 'rmfood_ingredient_history'
const loadHistory = () => { try { return JSON.parse(localStorage.getItem(STORAGE_KEY) ?? '[]') } catch { return [] } }
const saveHistory = (items: any[]) => localStorage.setItem(STORAGE_KEY, JSON.stringify(items.slice(0, 20)))

// ─── 图表配色（设计令牌）────────────────────────────────────
const CHART_COLORS = {
  accent: 'var(--color-accent)',
  success: 'var(--color-success)',
  warning: 'var(--color-warning)',
  danger: 'var(--color-error)',
  secondary: 'var(--color-secondary)',
}

// ─── 风险分级 ────────────────────────────────────────────────
const riskColor = (risk: string) =>
  risk === 'high' ? 'text-danger-500 dark:text-danger-600' : risk === 'medium' ? 'text-[var(--color-warning-text)]0 dark:text-[var(--color-warning-text)]' : 'text-[var(--color-success-text)]0 dark:text-[var(--color-success-text)]'
const riskBg = (risk: string) =>
  risk === 'high' ? 'bg-danger-50 dark:bg-danger-950/20 border-danger-200 dark:border-danger-900' :
  risk === 'medium' ? 'bg-[var(--color-warning-container)] dark:bg-[var(--color-warning-container)]/20 border-[var(--color-warning-border)] dark:border-warning-900' :
  'bg-[var(--color-success-container)] dark:bg-[var(--color-success-container)]/20 border-[var(--color-success-border)] dark:border-success-900'

export default function IngredientAnalysisPage() {
  const { t, i18n } = useTranslation()
  const { addToast } = useToast()
  const [activeTab, setActiveTab] = useState<'analyze' | 'additives' | 'homology'>('analyze')
  const [ingredientText, setIngredientText] = useState('')
  const [result, setResult] = useState<AnalysisResult | null>(null)
  const [additives, setAdditives] = useState<AdditiveInfo[]>([])
  const [loading, setLoading] = useState(false)
  const [searchTerm, setSearchTerm] = useState('')
  const [filteredAdditives, setFilteredAdditives] = useState<AdditiveInfo[]>([])
  const [homologyList, setHomologyList] = useState<any[]>([])
  const [history, setHistory] = useState<any[]>(loadHistory)
  const [showHistory, setShowHistory] = useState(false)

  const handleAnalyze = async () => {
    if (!ingredientText.trim()) { addToast({ type: 'warning', message: t('pages.ingredient.toastInputRequired') }); return }
    setLoading(true)
    try {
      const res: any = await ingredientApi.analyze({ ingredient_text: ingredientText })
      // 后端返回 { success, data: AnalysisResult, message }，axios res.data 即该对象
      const data = res.data?.data ?? res.data
      setResult(data)
      // Save to history
      const histItem = {
        id: Date.now(),
        text: ingredientText.substring(0, 50) + (ingredientText.length > 50 ? '...' : ''),
        score: data?.overallScore ?? 0,
        grade: data?.riskLevel ?? '?',
        date: new Date().toLocaleDateString(i18n.language),
      }
      const newHistory = [histItem, ...history].slice(0, 20)
      setHistory(newHistory)
      saveHistory(newHistory)
      addToast({ type: 'success', message: t('pages.ingredient.toastScore', { score: data?.overallScore ?? 0 }) })
    } catch (e: any) {
      addToast({ type: 'error', message: String(e) })
    } finally { setLoading(false) }
  }

  const handleLoadAdditives = async () => {
    try {
      const res: any = await ingredientApi.getAdditives()
      // 后端返回 { success, data: AdditiveInfo[], total }，axios res.data 即该对象
      const items = res.data?.data ?? res.data ?? []
      setAdditives(items); setFilteredAdditives(items)
    } catch (e: any) { addToast({ type: 'error', message: String(e) }) }
  }

  const handleLoadHomology = async () => {
    try {
      const res: any = await complianceApi.getFoodHomology()
      // 后端返回 { success, data: { source, count, materials: [...] } }，直连 JSON 非 axios
      if (res.success && res.data?.materials) setHomologyList(res.data.materials)
    } catch (e: any) { addToast({ type: 'error', message: String(e) }) }
  }

  const handleSearchAdditive = (term: string) => {
    setSearchTerm(term)
    if (!term) { setFilteredAdditives(additives); return }
    const filtered = additives.filter(a =>
      (a.name || '').toLowerCase().includes(term.toLowerCase()) ||
      ((a.eCode || '') as string).toLowerCase().includes(term.toLowerCase())
    )
    setFilteredAdditives(filtered)
  }

  // Build radar chart data from analysis result
  const radarData = result ? [
    { dimension: t('pages.ingredient.radarDimensions.nutrition'), value: result.nutriScore, fullMark: 100 },
    { dimension: t('pages.ingredient.radarDimensions.nova'), value: Math.max(0, 100 - ((result.novaResult?.group as number ?? 1)) * 25), fullMark: 100 },
    { dimension: t('pages.ingredient.radarDimensions.safety'), value: result.overallScore >= 70 ? 80 : result.overallScore >= 40 ? 50 : 20, fullMark: 100 },
    { dimension: t('pages.ingredient.radarDimensions.allergenRisk'), value: Math.max(0, 100 - (result.allergens?.length ?? 0) * 20), fullMark: 100 },
    { dimension: t('pages.ingredient.radarDimensions.herbalCompliance'), value: ((result.herbalIngredients?.length ?? 0) > 0) ? 70 : 90, fullMark: 100 },
    { dimension: t('pages.ingredient.radarDimensions.additiveRisk'), value: Math.max(0, 100 - result.additives.length * 15), fullMark: 100 },
  ] : []

  // Get substitution suggestions for high-risk additives
  const getSubstitutions = (additive: AdditiveInfo) => {
    const subs: Record<string, string[]> = {
      '苯甲酸钠': ['山梨酸钾', '乳酸链球菌素', '天然防腐剂（nistatin）'],
      '丙二醇': ['甘油', '聚乙二醇', '植物甘油'],
      '阿斯巴甜': ['赤藓糖醇', '甜菊糖苷', '罗汉果甜苷'],
      '亮蓝': ['螺旋藻提取物', '姜黄素', '甜菜红'],
      '柠檬黄': ['姜黄素', '枸杞提取物', '红曲红'],
    }
    return subs[additive.name] ?? [t('pages.ingredient.consultProfessional')]
  }

  return (
    <div className="min-h-screen">
      {/* 品牌横幅 — 对齐设计系统 */}
      <div className="max-w-[1600px] mx-auto px-[var(--space-apple-md)] sm:px-6 lg:px-8 py-[var(--space-apple-lg)]">
        <div className="surface-primary rounded-[var(--radius-Apple-md)] p-[var(--space-apple-lg)] shadow-sm">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="w-10 h-10 rounded-[var(--radius-Apple-sm)] bg-[var(--bg-secondary)]/15 flex items-center justify-center">
                <Beaker className="w-5 h-5 text-white" />
              </div>
              <div>
                <h1 className="text-xl font-semibold">{t('pages.ingredient.title')}</h1>
                <p className="text-white/80 text-sm">{t('pages.ingredient.subtitle')}</p>
              </div>
            </div>
            {history.length > 0 && (
              <button onClick={() => setShowHistory(!showHistory)}
                className="flex items-center gap-1.5 px-[var(--space-apple-sm)] py-1.5 min-h-[44px] text-xs font-medium bg-[var(--bg-secondary)]/15 hover:bg-[var(--bg-secondary)]/25 text-[var(--color-primary-text)] dark:text-white rounded-[var(--radius-pill)] transition-colors">
                <BookOpen size={12} />{t('pages.ingredient.history', { count: history.length })}
              </button>
            )}
          </div>
        </div>
      </div>

      <div className="max-w-[1600px] mx-auto px-[var(--space-apple-md)] sm:px-6 lg:px-8 py-[var(--space-apple-lg)] space-y-[var(--space-apple-md)]">
        {/* 历史面板 */}
        {showHistory && history.length > 0 && (
          <Card>
            <CardContent className="p-[var(--space-apple-md)]">
              <div className="text-xs font-semibold text-[var(--text-muted)] mb-2 uppercase tracking-wide">{t('pages.ingredient.recentAnalysis')}</div>
              <div className="flex gap-2 flex-wrap">
                {history.map(h => (
                  <div key={h.id} className="flex items-center gap-2 px-[var(--space-apple-sm)] py-1.5 bg-[var(--bg-tertiary)]/60 rounded-[var(--radius-Apple-sm)] text-xs">
                    <span className="font-mono text-[var(--color-accent-text)] dark:text-[var(--color-accent-text)]">{h.score}/100</span>
                    <span className={`font-medium ${h.grade === 'low' ? 'text-[var(--color-success-text)]0 dark:text-[var(--color-success-text)]' : h.grade === 'medium' ? 'text-[var(--color-warning-text)]0 dark:text-[var(--color-warning-text)]' : 'text-danger-500 dark:text-danger-600'}`}>
                      {h.grade === 'low' ? t('pages.ingredient.riskLow') : h.grade === 'medium' ? t('pages.ingredient.riskMedium') : t('pages.ingredient.riskHigh')}
                    </span>
                    <span className="text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] truncate max-w-[120px]">{h.text}</span>
                    <span className="text-[var(--text-muted)] dark:text-[var(--text-muted)]">{h.date}</span>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        )}

        {/* Tabs — 对齐 Apple Segmented Control 规范 */}
        <div className="tabs-list w-fit">
          {[
            { key: 'analyze' as const, label: t('pages.ingredient.tabAnalyze'), icon: Activity },
            { key: 'additives' as const, label: t('pages.ingredient.tabAdditives'), icon: ShieldAlert },
            { key: 'homology' as const, label: t('pages.ingredient.tabHomology'), icon: BookOpen },
          ].map(tab => (
            <button key={tab.key} onClick={() => { setActiveTab(tab.key); if (tab.key === 'additives' && additives.length === 0) handleLoadAdditives(); if (tab.key === 'homology' && homologyList.length === 0) handleLoadHomology() }}
              className={`tabs-trigger ${activeTab === tab.key ? 'tabs-trigger-active' : ''}`}>
              <span className="icon"><tab.icon size={14} /></span>
              {tab.label}
            </button>
          ))}
        </div>

        {/* ═══ 六维分析 Tab ═══ */}
        {activeTab === 'analyze' && (
          <div className="space-y-[var(--space-apple-md)]">
            <Card>
              <CardHeader className="px-5 pt-5 pb-3">
                <CardTitle as="h3" className="text-sm font-semibold flex items-center gap-2">
                  <FlaskConical size={14} className="text-[var(--color-accent-text)]0 dark:text-[var(--color-accent-text)]" />{t('pages.ingredient.ingredientList')}
                </CardTitle>
              </CardHeader>
              <CardContent className="px-5 pb-5 pt-0">
                <textarea
                  value={ingredientText}
                  onChange={e => setIngredientText(e.target.value)}
                  placeholder={t('pages.ingredient.textareaPlaceholder')}
                  rows={5}
                  className="w-full px-[var(--space-apple-md)] py-[var(--space-apple-md)] text-sm rounded-[var(--radius-Apple-sm)] border border-[var(--border-color)] bg-[var(--bg-tertiary)] dark:text-[var(--text-primary)] resize-none focus:outline-none focus:ring-2 focus:ring-[var(--color-accent)]"
                />
                <div className="mt-[var(--space-apple-sm)]">
                  <Button onClick={handleAnalyze} disabled={loading}>
                    {loading ? <Activity size={14} className="animate-spin" /> : <Activity size={14} />}
                    {loading ? t('pages.ingredient.analyzing') : t('pages.ingredient.runAnalyze')}
                  </Button>
                </div>
              </CardContent>
            </Card>

            {result && (
              <>
                {/* 六维雷达图 */}
                <Card>
                  <CardHeader className="px-5 pt-5 pb-3">
                    <CardTitle as="h3" className="text-sm font-semibold flex items-center gap-2">
                      <Activity size={14} className="text-[var(--color-accent-text)]0 dark:text-[var(--color-accent-text)]" />{t('pages.ingredient.radarTitle')}
                    </CardTitle>
                  </CardHeader>
                  <CardContent className="px-5 pb-5 pt-0">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      <div className="h-72">
                        <ResponsiveContainer width="100%" height="100%">
                          <RechartsRadarChart data={radarData}>
                            <PolarGrid stroke="var(--border-color)" />
                            <PolarAngleAxis dataKey="dimension" tick={{ fontSize: 12, fill: 'var(--text-muted)' }} />
                            <PolarRadiusAxis angle={30} domain={[0, 100]} tick={{ fontSize: 10, fill: 'var(--text-muted)' }} />
                            <RechartsTooltip
                              formatter={(value: number) => [`${value}${t('pages.ingredient.scoreUnit')}`, t('pages.ingredient.overallScoreName')]}
                              contentStyle={{ backgroundColor: 'var(--card-bg-solid)', border: '1px solid var(--border-color)', borderRadius: '8px', padding: '12px' }}
                            />
                            <Radar name={t('pages.ingredient.overallScoreName')} dataKey="value" stroke={CHART_COLORS.accent} fill={CHART_COLORS.accent} fillOpacity={0.2} strokeWidth={2} />
                          </RechartsRadarChart>
                        </ResponsiveContainer>
                      </div>
                      <div className="space-y-[var(--space-apple-sm)]">
                        <div className="grid grid-cols-2 gap-[var(--space-apple-sm)]">
                          <div className="rounded-[var(--radius-Apple-md)] p-[var(--space-apple-sm)] bg-[var(--color-success-container)] dark:bg-[var(--color-success-container)]/20 border border-[var(--color-success-border)] dark:border-success-900">
                            <div className="text-xs text-[var(--text-muted)] mb-1">{t('pages.ingredient.nutriScore')}</div>
                            <div className="text-xl font-bold text-[var(--color-success-text)]0 dark:text-[var(--color-success-text)]">{result.nutriScore}/100</div>
                            <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">{t('pages.ingredient.grade', { grade: String(result.nutriGrade?.grade ?? '?') })}</div>
                          </div>
                          <div className="rounded-[var(--radius-Apple-md)] p-[var(--space-apple-sm)] bg-[var(--color-secondary-container)] dark:bg-[var(--color-secondary-container)]/20 border border-[var(--color-secondary-border)] dark:border-secondary-900">
                            <div className="text-xs text-[var(--text-muted)] mb-1">{t('pages.ingredient.novaGroup')}</div>
                            <div className="text-xl font-bold text-[var(--color-secondary-text)]0 dark:text-[var(--color-secondary-text)]">{String(result.novaResult?.group ?? "?")}</div>
                            <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">{String(result.novaResult?.label ?? "")}</div>
                          </div>
                          <div className="rounded-[var(--radius-Apple-md)] p-[var(--space-apple-sm)] bg-[var(--bg-tertiary)] border border-[var(--border-color)]">
                            <div className="text-xs text-[var(--text-muted)] mb-1">{t('pages.ingredient.overallScore')}</div>
                            <div className={`text-xl font-bold ${result.overallScore >= 70 ? 'text-[var(--color-success-text)]0 dark:text-[var(--color-success-text)]' : result.overallScore >= 40 ? 'text-[var(--color-warning-text)]0 dark:text-[var(--color-warning-text)]' : 'text-danger-500 dark:text-danger-600'}`}>
                              {result.overallScore}
                            </div>
                            <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">
                              {result.riskLevel === 'high' ? t('pages.ingredient.riskHigh') : result.riskLevel === 'medium' ? t('pages.ingredient.riskMedium') : t('pages.ingredient.riskLow')}
                            </div>
                          </div>
                          <div className="rounded-[var(--radius-Apple-md)] p-[var(--space-apple-sm)] bg-[var(--color-warning-container)] dark:bg-[var(--color-warning-container)]/20 border border-[var(--color-warning-border)] dark:border-warning-900">
                            <div className="text-xs text-[var(--text-muted)] mb-1">{t('pages.ingredient.allergens')}</div>
                            <div className="text-xl font-bold text-[var(--color-warning-text)]0 dark:text-[var(--color-warning-text)]">{result.allergens?.length ?? 0}</div>
                            <div className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">{t('pages.ingredient.allergensCount')}</div>
                          </div>
                        </div>

                        {/* 过敏原列表 */}
                        {result.allergens.length > 0 && (
                          <div>
                            <div className="text-xs font-semibold text-[var(--text-muted)] mb-2">{t('pages.ingredient.identifiedAllergens')}</div>
                            <div className="flex flex-wrap gap-1">
                              {result.allergens.map((a, i) => (
                                <span key={i} className="px-2 py-0.5 bg-[var(--color-warning-container)] dark:bg-[var(--color-warning-container)]/25 text-[var(--color-warning-text)] text-xs rounded-[var(--radius-Apple-sm)] font-medium">
                                  {a.name} ({a.level})
                                </span>
                              ))}
                            </div>
                          </div>
                        )}

                        {/* 中草药识别 */}
                        {result.herbalIngredients.length > 0 && (
                          <div>
                            <div className="text-xs font-semibold text-[var(--text-muted)] mb-2">{t('pages.ingredient.herbalIngredients')}</div>
                            <div className="flex flex-wrap gap-1">
                              {result.herbalIngredients.map((h, i) => (
                                <span key={i} className="px-2 py-0.5 bg-[var(--color-accent-container)] dark:bg-[var(--color-accent-container)]/25 text-[var(--color-accent-text)] dark:text-[var(--color-accent-text)] text-xs rounded-[var(--radius-Apple-sm)] font-medium">
                                  {h.name}
                                </span>
                              ))}
                            </div>
                          </div>
                        )}
                      </div>
                    </div>
                  </CardContent>
                </Card>

                {/* 添加剂分析 */}
                {result.additives.length > 0 && (
                  <Card>
                    <CardHeader className="px-5 pt-5 pb-3">
                      <CardTitle as="h3" className="text-sm font-semibold flex items-center gap-2">
                        <ShieldAlert size={14} className="text-[var(--color-warning-text)]0 dark:text-[var(--color-warning-text)]" />{t('pages.ingredient.additivesSuggestions')}
                      </CardTitle>
                    </CardHeader>
                    <CardContent className="px-5 pb-5 pt-0">
                      <div className="space-y-2">
                        {result.additives.map((a, i) => (
                          <div key={i} className={`rounded-[var(--radius-Apple-sm)] border p-[var(--space-apple-sm)] ${riskBg(a.risk)}`}>
                            <div className="flex items-center gap-4">
                              <span className="text-xs font-mono text-[var(--text-muted)] w-16">{a.eCode}</span>
                              <span className="text-sm font-medium text-[var(--text-primary)]">{a.name}</span>
                              <span className="text-xs text-[var(--text-muted)]">{a.function}</span>
                              <span className={`text-xs font-bold ${riskColor(a.risk)}`}>{a.risk === 'high' ? t('pages.ingredient.riskHigh') : a.risk === 'medium' ? t('pages.ingredient.riskMedium') : t('pages.ingredient.riskLow')}</span>
                              {a.carcinogen && <span className="text-xs bg-danger-100 dark:bg-danger-300/25 text-danger-600 dark:text-danger-600 px-1.5 py-0.5 rounded">{t('pages.ingredient.carcinogen')}</span>}
                              {a.allergen && <span className="text-xs bg-[var(--color-warning-container)] dark:bg-[var(--color-warning-container)]/25 text-[var(--color-warning-text)] dark:text-[var(--color-warning-text)] px-1.5 py-0.5 rounded">{t('pages.ingredient.allergen')}</span>}
                              {a.maxUsage && <span className="ml-auto text-xs text-[var(--text-muted)]">{t('pages.ingredient.maxUsage', { value: a.maxUsage })}</span>}
                            </div>
                            {a.risk === 'high' && (
                              <div className="mt-2 pt-2 border-t border-inherit">
                                <div className="text-xs font-semibold text-[var(--text-muted)] mb-1 flex items-center gap-1">
                                  <Lightbulb size={12} className="text-[var(--color-warning-text)]0 dark:text-[var(--color-warning-text)]" />{t('pages.ingredient.substitution')}
                                </div>
                                <div className="flex flex-wrap gap-1">
                                  {getSubstitutions(a).map((sub, j) => (
                                    <span key={j} className="px-2 py-0.5 bg-[var(--color-success-container)] dark:bg-[var(--color-success-container)]/25 text-[var(--color-success-text)] dark:text-[var(--color-success-text)] text-xs rounded-[var(--radius-Apple-sm)]">
                                      → {sub}
                                    </span>
                                  ))}
                                </div>
                              </div>
                            )}
                          </div>
                        ))}
                      </div>
                    </CardContent>
                  </Card>
                )}

                {/* 风险消息 */}
                {result.riskMessages.length > 0 && (
                  <div className="rounded-[var(--radius-Apple-md)] bg-danger-50 dark:bg-danger-950/20 border border-danger-200 dark:border-danger-900 p-5">
                    <h2 className="text-sm font-semibold text-danger-600 dark:text-danger-600 mb-[var(--space-apple-sm)] flex items-center gap-2">
                      <AlertTriangle size={14} />{t('pages.ingredient.riskMessages')}
                    </h2>
                    <div className="space-y-1">
                      {result.riskMessages.map((m, i) => (
                        <div key={i} className="flex items-start gap-2 px-[var(--space-apple-sm)] py-1.5 text-sm text-[var(--text-primary)]">
                          <XCircle size={12} className="text-danger-400 mt-0.5 shrink-0" />{m}
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* 优化建议 */}
                {result.suggestions.length > 0 && (
                  <div className="rounded-[var(--radius-Apple-md)] bg-[var(--color-secondary-container)] dark:bg-[var(--color-secondary-container)]/20 border border-[var(--color-secondary-border)] dark:border-secondary-900 p-5">
                    <h2 className="text-sm font-semibold text-[var(--color-secondary-text)] dark:text-[var(--color-secondary-text)] mb-[var(--space-apple-sm)] flex items-center gap-2">
                      <Lightbulb size={14} />{t('pages.ingredient.suggestions')}
                    </h2>
                    <div className="space-y-1">
                      {result.suggestions.map((s, i) => (
                        <div key={i} className="flex items-start gap-2 px-[var(--space-apple-sm)] py-1.5 text-sm text-[var(--text-primary)]">
                          <span className="text-[var(--color-secondary-text)]">→</span>{typeof s === 'string' ? s : (s as any).text || (s as any).message || (s as any).type || JSON.stringify(s)}
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </>
            )}
          </div>
        )}

        {/* ═══ 添加剂库 Tab ═══ */}
        {activeTab === 'additives' && (
          <Card>
            <CardHeader className="px-5 pt-5 pb-3">
              <CardTitle as="h3" className="text-sm font-semibold flex items-center gap-2">
                <ShieldAlert size={14} className="text-[var(--color-warning-text)]0 dark:text-[var(--color-warning-text)]" />{t('pages.ingredient.additivesDb')}
              </CardTitle>
            </CardHeader>
            <CardContent className="px-5 pb-5 pt-0">
              <div className="mb-[var(--space-apple-md)]">
                <Input value={searchTerm} onChange={e => handleSearchAdditive(e.target.value)}
                  placeholder={t('pages.ingredient.searchAdditive')} className="h-9 text-sm" />
              </div>
              <div className="space-y-2 max-h-96 overflow-y-auto">
                {filteredAdditives.length === 0 ? (
                  <p className="text-sm text-[var(--text-muted)] text-center py-8">
                    {additives.length === 0 ? t('pages.ingredient.loading') : t('pages.ingredient.noMatch')}
                  </p>
                ) : filteredAdditives.map((a, i) => (
                  <div key={i} className={`flex items-center gap-4 px-[var(--space-apple-sm)] py-2.5 rounded-[var(--radius-Apple-sm)] border ${riskBg(a.risk)}`}>
                    <span className="text-xs font-mono text-[var(--text-muted)] w-16">{a.eCode}</span>
                    <span className="text-sm font-medium text-[var(--text-primary)]">{a.name}</span>
                    <span className="text-xs text-[var(--text-muted)]">{a.function}</span>
                    <span className={`text-xs font-bold ${riskColor(a.risk)}`}>{a.risk === 'high' ? t('pages.ingredient.riskHighShort') : a.risk === 'medium' ? t('pages.ingredient.riskMediumShort') : t('pages.ingredient.riskLowShort')}</span>
                    {a.carcinogen && <span className="text-xs bg-danger-100 dark:bg-danger-300/25 text-danger-600 dark:text-danger-600 px-1.5 py-0.5 rounded">{t('pages.ingredient.carcinogen')}</span>}
                    {a.allergen && <span className="text-xs bg-[var(--color-warning-container)] dark:bg-[var(--color-warning-container)]/25 text-[var(--color-warning-text)] dark:text-[var(--color-warning-text)] px-1.5 py-0.5 rounded">{t('pages.ingredient.allergen')}</span>}
                    {a.maxUsage && <span className="ml-auto text-xs text-[var(--text-muted)]">{a.maxUsage}</span>}
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        )}

        {/* ═══ 药食同源 Tab ═══ */}
        {activeTab === 'homology' && (
          <Card>
            <CardHeader className="px-5 pt-5 pb-3">
              <CardTitle as="h3" className="text-sm font-semibold flex items-center gap-2">
                <BookOpen size={14} className="text-[var(--color-accent-text)]0 dark:text-[var(--color-accent-text)]" />{t('pages.ingredient.homologyCatalog')}
              </CardTitle>
            </CardHeader>
            <CardContent className="px-5 pb-5 pt-0">
              {homologyList.length === 0 ? (
                <p className="text-sm text-[var(--text-muted)] text-center py-8">{t('pages.ingredient.loading')}</p>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-2 max-h-96 overflow-y-auto">
                  {homologyList.map((item: any, i: number) => (
                    <div key={i} className="flex items-center gap-[var(--space-apple-sm)] px-[var(--space-apple-sm)] py-2.5 bg-[var(--bg-tertiary)]/60 rounded-[var(--radius-Apple-sm)]">
                      <span className="text-sm font-medium text-[var(--text-primary)]">{item.name}</span>
                      <span className="text-xs text-[var(--text-muted)]">{item.category}</span>
                      <span className="text-xs font-mono text-[var(--color-accent-text)] dark:text-[var(--color-accent-text)] ml-auto">{t('pages.ingredient.maxDosage', { value: item.max_dosage })}</span>
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  )
}

