              {onClone && (
                <button
                  onClick={() => onClone(Number(org.id))}
                  title="克隆组织"
                  className="px-[var(--space-apple-sm)] py-2 bg-[var(--bg-tertiary)] hover:bg-[var(--color-secondary-container)] dark:hover:bg-[var(--color-secondary-container)]/20 text-[var(--text-primary)] hover:text-[var(--color-secondary-text)] dark:hover:text-[var(--color-secondary-text)] rounded-[var(--radius-Apple-sm)] transition-colors text-sm"
                >
                  <Copy className="w-4 h-4" />
                </button>
              )}
            </div>
          </div>
        </div>
      </div>
    );
  },
);

