﻿/**
 * 组织权限矩阵（与后端 /permissions 真实模型对齐）
 * 后端模型：组织级权限开关（member_management / team_management / formula_access /
 * experiment_access / data_export / api_access），非角色级 RBAC 矩阵。
 */
import { useState, useEffect, useCallback, useRef, memo } from 'react';
import { Shield, Save, Loader2, CheckCircle, AlertCircle, KeyRound, Users2, FlaskConical, FlaskRound, Download, Server } from 'lucide-react';
import api from '@/api/client';
import { cn } from '@/lib/utils';
import { useToast } from '@/components/ui/Toast';

interface PermissionMatrixProps {
  organizationId: number;
}

interface OrgPermissions {
  member_management: boolean;
  team_management: boolean;
  formula_access: boolean;
  experiment_access: boolean;
  data_export: boolean;
  api_access: boolean;
}

const PERMISSION_DEFS: Array<{ key: keyof OrgPermissions; label: string; description: string; icon: typeof KeyRound }> = [
  { key: 'member_management', label: '成员管理', description: '允许成员邀请/移除成员、修改成员角色', icon: Users2 },
  { key: 'team_management', label: '团队管理', description: '允许成员创建/编辑/删除团队', icon: Shield },
  { key: 'formula_access', label: '配方访问', description: '允许成员查看与使用配方库', icon: FlaskConical },
  { key: 'experiment_access', label: '实验访问', description: '允许成员查看与录入实验数据', icon: FlaskRound },
  { key: 'data_export', label: '数据导出', description: '允许成员导出组织数据', icon: Download },
  { key: 'api_access', label: 'API 访问', description: '允许成员通过 API 访问组织数据', icon: Server },
];

const DEFAULT_PERMISSIONS: OrgPermissions = {
  member_management: true,
  team_management: true,
  formula_access: true,
  experiment_access: true,
  data_export: true,
  api_access: true,
};

function normalizePermissions(raw: Record<string, unknown>): OrgPermissions {
  const p = { ...DEFAULT_PERMISSIONS };
  for (const def of PERMISSION_DEFS) {
    if (typeof raw[def.key] === 'boolean') p[def.key] = raw[def.key] as boolean;
  }
  return p;
}

export function PermissionMatrix({ organizationId }: PermissionMatrixProps) {
  const toast = useToast();
  const toastRef = useRef(toast);
  toastRef.current = toast;
  const [permissions, setPermissions] = useState<OrgPermissions>(DEFAULT_PERMISSIONS);
  const [myRole, setMyRole] = useState('');
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const { data } = await api.get(`/organizations/${organizationId}/permissions`);
      setPermissions(normalizePermissions(data.permissions || {}));
      setMyRole(data.my_role || '');
    } catch {
      toastRef.current.error('加载权限矩阵失败');
    } finally {
      setLoading(false);
    }
  }, [organizationId]);

  useEffect(() => {
    load();
  }, [load]);

  const canEdit = myRole?.toLowerCase() === 'owner';

  const toggle = useCallback((key: keyof OrgPermissions) => {
    if (!canEdit) return;
    setPermissions(prev => ({ ...prev, [key]: !prev[key] }));
  }, [canEdit]);

  const handleSave = useCallback(async () => {
    if (!canEdit) return;
    setSaving(true);
    try {
      await api.put(`/organizations/${organizationId}/permissions`, permissions);
      toast.success('权限配置已更新');
    } catch (err: any) {
      toast.error(err?.response?.data?.detail || '保存失败，请重试');
    } finally {
      setSaving(false);
    }
  }, [organizationId, permissions, toast, canEdit]);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="w-8 h-8 animate-spin text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]" />
      </div>
    );
  }

  return (
    <div className="space-y-[var(--space-apple-md)]">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-semibold text-[var(--text-primary)] flex items-center gap-2">
            <Shield className="w-5 h-5 text-[var(--color-secondary-text)]0" />
            权限矩阵
          </h3>
          <p className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-0.5">
            组织级权限开关（我的角色：{myRole ? ({ owner: '所有者', admin: '管理员', member: '成员', viewer: '访客' } as Record<string, string>)[myRole] || myRole : '未知'}）
          </p>
        </div>
        <button
          onClick={handleSave}
          disabled={saving || !canEdit}
          className="flex items-center gap-2 px-[var(--space-apple-md)] py-2 text-sm bg-secondary-container text-secondary-main rounded-[var(--radius-Apple-sm)] hover:bg-secondary-container disabled:opacity-50 transition-colors"
        >
          {saving && <Loader2 className="w-4 h-4 animate-spin" />}
          <Save className="w-4 h-4" />
          保存配置
        </button>
      </div>

      {!canEdit && (
        <div className="flex items-start gap-2.5 p-[var(--space-apple-sm)] rounded-[var(--radius-Apple-md)] border border-[var(--color-warning-border)] dark:border-[var(--color-warning)] bg-[var(--color-warning-container)] dark:bg-[var(--color-warning-container)]/15 text-sm text-[var(--color-warning-text)] dark:text-[var(--color-warning-text)]">
          <AlertCircle className="w-4 h-4 mt-0.5 shrink-0" />
          <div>
            <p className="font-semibold">仅所有者可修改权限配置</p>
            <p className="text-xs mt-0.5">当前角色为「{myRole}」，可查看权限设置但无法切换或保存。</p>
          </div>
        </div>
      )}

      <div className="surface-card rounded-[var(--radius-Apple-md)] border border-[var(--border-color)] overflow-hidden">
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-[var(--space-apple-sm)] p-5">
          {PERMISSION_DEFS.map(def => {
            const Icon = def.icon;
            const checked = permissions[def.key];
            return (
              <button
                key={def.key}
                onClick={() => toggle(def.key)}
                disabled={!canEdit}
                className={cn(
                  'flex items-start gap-[var(--space-apple-sm)] p-[var(--space-apple-md)] rounded-[var(--radius-Apple-md)] border text-left transition-all cursor-pointer',
                  checked
                    ? 'border-[var(--color-secondary-border)] dark:border-[var(--color-secondary)] bg-[var(--color-secondary-container)] dark:bg-[var(--color-secondary-container)]/15'
                    : 'border-[var(--border-color)] bg-[var(--bg-secondary)]/50 hover:border-[var(--border-color)] dark:hover:border-neutral-600',
                  !canEdit && 'cursor-not-allowed opacity-70',
                )}
              >
                <div className={cn(
                  'shrink-0 w-9 h-9 rounded-[var(--radius-Apple-sm)] flex items-center justify-center',
                  checked ? 'bg-[var(--color-secondary-container)]0 text-white' : 'bg-[var(--bg-tertiary)] text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]',
                )}>
                  <Icon className="w-4.5 h-4.5" />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center justify-between">
                    <span className="font-medium text-[var(--text-primary)]">{def.label}</span>
                    <span className={cn(
                      'inline-flex items-center gap-1 text-xs font-medium',
                      checked ? 'text-[var(--color-secondary-text)] dark:text-[var(--color-secondary-text)]' : 'text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]',
                    )}>
                      <CheckCircle className="w-3.5 h-3.5" />
                      {checked ? '已开启' : '已关闭'}
                    </span>
                  </div>
                  <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">
                    {def.description}
                  </p>
                </div>
              </button>
            );
          })}
        </div>
      </div>

      <div className="flex items-center gap-4 text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
        <div className="flex items-center gap-1.5">
          <CheckCircle className="w-3.5 h-3.5 text-[var(--color-secondary-text)]0" />
          <span>{canEdit ? '点击卡片切换组织级权限开关' : '权限开关当前只读'}</span>
        </div>
        <div className="flex items-center gap-1.5 ml-auto">
          <AlertCircle className="w-3.5 h-3.5" />
          <span>开关关闭后，对应操作对非所有者成员生效（仅所有者及拥有对应自定义角色权限的成员不受限）</span>
        </div>
      </div>
    </div>
  );
}

export default PermissionMatrix;

import { useState, useCallback } from 'react';
import { useToast } from '@/components/ui/Toast';
import { Modal } from '@/components/ui/Modal';
import { Loader2, CheckCircle, AlertCircle } from 'lucide-react';
import { cn } from '@/lib/utils';
import api from '@/api/client';
import type { Organization } from '@/hooks/useOrganizations';

interface PlanUpgradeDialogProps {
  open: boolean;
  organization: Organization;
  onClose: () => void;
  onPlanUpdated: (plan: string) => void;
}

const PLAN_CONFIG = [
  {
    value: 'free' as const,
    label: '免费版',
    price: '免费',
    desc: '适合个人学习使用',
    maxMembers: 5,
    maxStorage: '500 MB',
    maxTeams: 1,
    maxFormulas: 50,
    features: ['基础配方管理', '团队协作', '数据导出'],
    highlight: false,
  },
  {
    value: 'pro' as const,
    label: '专业版',
    price: '¥99/月',
    desc: '适合小型团队使用',
    maxMembers: 50,
    maxStorage: '5 GB',
    maxTeams: 10,
    maxFormulas: 500,
    features: ['全部免费版功能', '高级AI分析', '优先支持', 'API接入'],
    highlight: true,
  },
  {
    value: 'enterprise' as const,
    label: '企业版',
    price: '定制报价',
    desc: '适合大型企业使用',
    maxMembers: -1,
    maxStorage: '无限',
    maxTeams: -1,
    maxFormulas: -1,
    features: ['全部专业版功能', 'SSO单点登录', '专属客户经理', '私有化部署', '自定义集成'],
    highlight: false,
  },
] as const;

export function PlanUpgradeDialog({ open, organization, onClose, onPlanUpdated }: PlanUpgradeDialogProps) {
  const toast = useToast();
  const [selectedPlan, setSelectedPlan] = useState<'free' | 'pro' | 'enterprise'>(organization?.plan || 'free');
  const [confirming, setConfirming] = useState(false);
  const [confirmText, setConfirmText] = useState('');
  const [, setError] = useState<string | null>(null);

  const canDowngrade = useCallback(() => {
    const target = PLAN_CONFIG.find(p => p.value === selectedPlan);
    if (!target) return true;
    if (target.maxMembers > 0 && organization.memberCount > target.maxMembers) return false;
    if (target.maxTeams > 0 && organization.teamCount > target.maxTeams) return false;
    return true;
  }, [selectedPlan, organization]);

  const handleSelectPlan = useCallback((plan: 'free' | 'pro' | 'enterprise') => {
    setSelectedPlan(plan);
    setError(null);
  }, []);

  const handleConfirm = useCallback(async () => {
    if (!confirmText) return;
    if (!canDowngrade()) {
      setError('当前成员数或团队数超过目标计划限制，请添加更多成员或升级后操作');
      return;
    }
    setConfirming(true);
    try {
      await api.put(`/organizations/${organization.id}/plan`, { plan: selectedPlan });
      toast.success(`计划已更新为${PLAN_CONFIG.find(p => p.value === selectedPlan)?.label}`);
      onPlanUpdated(selectedPlan);
      onClose();
    } catch (err: any) {
      setError(err.message || '操作失败');
    } finally {
      setConfirming(false);
    }
  }, [selectedPlan, confirmText, organization.id, canDowngrade, toast, onPlanUpdated, onClose]);

  const handleClose = useCallback(() => {
    setSelectedPlan(organization?.plan || 'free');
    setConfirmText('');
    setError(null);
    onClose();
  }, [organization, onClose]);

  return (
    <Modal open={open} onClose={handleClose} title="升级/变更订阅计划" size="lg">
      <div className="space-y-6">
        {/* Current Plan */}
        <div className="flex items-center gap-[var(--space-apple-sm)] p-[var(--space-apple-md)] bg-[var(--bg-tertiary)] dark:bg-[var(--bg-secondary)]/30 rounded-[var(--radius-Apple-md)] border border-[var(--border-color)] dark:border-neutral-800">
          <span className="text-sm text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">当前计划:</span>
          <span className="px-[var(--space-apple-sm)] py-1 rounded-[var(--radius-pill)] text-sm font-medium bg-[var(--color-secondary-container)] text-[var(--color-secondary-text)] dark:bg-[var(--color-secondary-container)]/25 dark:text-[var(--color-secondary-text)]">
            {PLAN_CONFIG.find(p => p.value === organization?.plan)?.label || organization?.plan}
          </span>
          <span className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">· {organization?.memberCount} 成员 · {organization?.teamCount} 团队</span>
        </div>

        {/* Plan Selection */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          {PLAN_CONFIG.map((plan) => (
            <button
              key={plan.value}
              onClick={() => handleSelectPlan(plan.value)}
              className={cn(
                'relative rounded-[var(--radius-Apple-md)] border-2 p-5 text-left transition-all',
                selectedPlan === plan.value
                  ? 'border-[var(--color-secondary)] bg-[var(--color-secondary-container)] dark:bg-[var(--color-secondary-container)]/20 shadow-md'
                  : 'border-[var(--border-color)] hover:border-[var(--border-color)] dark:border-neutral-700',
                plan.highlight && 'ring-2 ring-[var(--color-accent)]/30',
              )}
            >
              {plan.highlight && (
                <span className="absolute -top-2.5 left-4 px-2 py-0.5 text-xs font-medium bg-accent-container text-accent-main rounded-[var(--radius-pill)]">
                  推荐
                </span>
              )}
              {plan.value === organization?.plan && (
                <span className="absolute top-2 right-2 text-xs text-[var(--color-secondary-text)]">当前</span>
              )}
              <h3 className="font-semibold text-[var(--text-primary)]">{plan.label}</h3>
              <p className={cn('text-2xl font-bold mt-2', plan.value === 'enterprise' ? 'text-neutral-900' : 'text-[var(--color-secondary-text)]')}>
                {plan.price}
              </p>
              <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] mt-1">{plan.desc}</p>
              <div className="mt-[var(--space-apple-md)] space-y-1.5">
                <p className="text-xs text-[var(--text-secondary)]">
                  成员: {plan.maxMembers > 0 ? `最多 ${plan.maxMembers} 人` : '不限'}
                </p>
                <p className="text-xs text-[var(--text-secondary)]">存储: {plan.maxStorage}</p>
                <p className="text-xs text-[var(--text-secondary)]">团队: {plan.maxTeams > 0 ? `最多 ${plan.maxTeams} 个` : '不限'}</p>
              </div>
              <ul className="mt-[var(--space-apple-md)] space-y-1">
                {plan.features.map((f, i) => (
                  <li key={i} className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)] flex items-center gap-1.5">
                    <CheckCircle className="w-3 h-3 text-[var(--color-success-text)]0 shrink-0" />{f}
                  </li>
                ))}
              </ul>
            </button>
          ))}
        </div>

        {/* DANGER: Downgrade warning */}
        {!canDowngrade() && (
          <div className="flex items-center gap-2 text-sm text-[var(--color-error-text)] dark:text-[var(--color-error-text)] bg-[var(--color-error-container)] rounded-[var(--radius-Apple-sm)] px-[var(--space-apple-md)] py-[var(--space-apple-md)]">
            <AlertCircle className="w-4 h-4 shrink-0" />
            当前成员数 ({organization?.memberCount}) 或团队数 ({organization?.teamCount}) 超过目标计划限制
          </div>
        )}

        {/* Confirm Text Input */}
        <div>
          <label className="block text-sm font-medium text-[var(--text-primary)] mb-1.5">
            确认操作
          </label>
          <input
            type="text"
            value={confirmText}
            onChange={(e) => setConfirmText(e.target.value)}
            placeholder={`输入 "确认升级至 ${PLAN_CONFIG.find(p => p.value === selectedPlan)?.label}" 确认`}
            className="w-full px-[var(--space-apple-sm)] py-2 rounded-[var(--radius-Apple-sm)] border border-[var(--border-color)] dark:border-neutral-700 surface-card text-sm focus:outline-none focus:ring-2 focus:ring-[var(--color-secondary)]"
          />
        </div>

        {/* Actions */}
        <div className="flex justify-end gap-[var(--space-apple-sm)] pt-2">
          <button onClick={handleClose} className="px-[var(--space-apple-md)] py-2 text-sm text-[var(--text-secondary)] hover:bg-[var(--bg-tertiary)] rounded-[var(--radius-Apple-sm)] transition-colors">
            取消
          </button>
          <button
            onClick={handleConfirm}
            disabled={confirming || !confirmText.trim() || confirmText !== `确认升级至 ${PLAN_CONFIG.find(p => p.value === selectedPlan)?.label}` || !canDowngrade()}
            className="px-[var(--space-apple-md)] py-2 text-sm bg-secondary-container text-secondary-main rounded-[var(--radius-Apple-sm)] hover:bg-secondary-container disabled:opacity-50 transition-colors flex items-center gap-2"
          >
            {confirming && <Loader2 className="w-4 h-4 animate-spin" />}
            确认变更
          </button>
        </div>
      </div>
    </Modal>
  );
}

export default PlanUpgradeDialog;

/**
 * 组织订阅与用量面板（真实功能）
 * - 展示当前计划、订阅状态、用量进度条
 * - 升级（模拟支付）/ 取消订阅
 * - 超限时显示升级引导
 */
import React, { useState } from 'react'
import { Link } from 'react-router-dom'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { Card, CardContent, Button, Badge, Progress, useToast } from '@/components/ui'
import { Crown, Zap, Building2, RefreshCw } from 'lucide-react'
import api from '@/api/client'

export interface SubscriptionInfo {
  organization_id: number
  plan: string
  plan_display_name: string
  status: string
  billing_cycle: string
  started_at?: string | null
  expires_at?: string | null
  usage: Record<string, { used: number; limit: number; over: boolean }>
}

const PLAN_META: Record<string, { label: string; monthly: string; yearly: string; color: string }> = {
  free: { label: '免费版', monthly: '¥0', yearly: '¥0', color: 'bg-[var(--bg-tertiary)] text-[var(--text-secondary)]' },
  pro: { label: '专业版', monthly: '¥199/月', yearly: '¥1999/年', color: 'bg-[var(--color-primary-container)] text-[var(--color-primary-text)]' },
  enterprise: { label: '企业版', monthly: '¥1999/月起', yearly: '定制', color: 'bg-[var(--color-warning-container)] text-[var(--color-warning-text)]' },
}

const USAGE_LABELS: Record<string, string> = {
  members: '成员',
  teams: '团队',
  formulas: '配方',
  storage: '存储',
  api_calls: 'API 调用/天',
  ai_generations: 'AI 生成/天',
}

function formatLimit(used: number, limit: number, key: string): string {
  if (key === 'storage') {
    return `${(used / 1024 / 1024).toFixed(1)}MB / ${(limit / 1024 / 1024).toFixed(0)}GB`
  }
  if (limit < 0) return `${used} / 无限`
  return `${used} / ${limit}`
}

export const SubscriptionPanel: React.FC<{ organizationId: number }> = ({ organizationId }) => {
  const toast = useToast()
  const qc = useQueryClient()
  const [confirmUpgrade, setConfirmUpgrade] = useState<string | null>(null)
  const [billingCycle, setBillingCycle] = useState<'monthly' | 'yearly'>('yearly')

  const { data, isLoading } = useQuery<SubscriptionInfo>({
    queryKey: ['org-subscription', organizationId],
    queryFn: async () => {
      const { data } = await api.get(`/organizations/${organizationId}/subscription`)
      return data
    },
  })

  const upgradeMutation = useMutation({
    mutationFn: async (plan: string) => {
      const { data } = await api.post(`/organizations/${organizationId}/subscription/upgrade`, { plan, billing_cycle: billingCycle })
      return data
    },
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['org-subscription', organizationId] })
      qc.invalidateQueries({ queryKey: ['organizations'] })
      setConfirmUpgrade(null)
      toast.success('升级成功（模拟支付完成）')
    },
    onError: (e: any) => {
      toast.error(e?.response?.data?.detail || '升级失败，请重试')
    },
  })

  const cancelMutation = useMutation({
    mutationFn: async () => {
      const { data } = await api.post(`/organizations/${organizationId}/subscription/cancel`)
      return data
    },
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['org-subscription', organizationId] })
      toast.success('订阅已取消')
    },
    onError: (e: any) => {
      toast.error(e?.response?.data?.detail || '取消失败，请重试')
    },
  })

  if (isLoading || !data) {
    return (
      <Card>
        <CardContent className="p-[var(--space-apple-lg)] space-y-[var(--space-apple-sm)]">
          <div className="h-5 w-1/3 bg-[var(--border-color)] animate-pulse rounded" />
          <div className="h-4 w-2/3 bg-[var(--border-color)] animate-pulse rounded" />
        </CardContent>
      </Card>
    )
  }

  const planMeta = PLAN_META[data.plan] || PLAN_META.free
  const overItems = Object.values(data.usage || {}).filter((u) => u.over)

  return (
    <Card>
      <CardContent className="p-[var(--space-apple-lg)] space-y-5">
        {/* 头部：当前计划 */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-[var(--space-apple-sm)]">
            <div className="w-10 h-10 rounded-[var(--radius-Apple-md)] bg-gradient-to-br from-primary-100 to-accent-50 dark:from-primary-900/40 dark:to-accent-900/20 flex items-center justify-center">
              <Crown className="w-5 h-5 text-[var(--color-primary-text)]" />
            </div>
            <div>
              <h3 className="text-base font-semibold text-[var(--text-primary)]">订阅与用量</h3>
              <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                组织 #{organizationId} · {data.status === 'canceled' ? '已取消续费' : '订阅中'} · {data.billing_cycle === 'yearly' ? '年付' : '月付'}
              </p>
            </div>
          </div>
          <Badge variant={data.plan === 'enterprise' ? 'warning' : data.plan === 'pro' ? 'success' : 'secondary'}>
            {planMeta.label} {data.plan !== 'free' && `· ${data.billing_cycle === 'yearly' ? '年付' : '月付'}`}
          </Badge>
          <Link
            to={`/billing?org=${organizationId}`}
            className="inline-flex items-center gap-1 px-2.5 py-1.5 rounded-[var(--radius-Apple-sm)] text-xs font-medium text-[var(--color-secondary-text)] dark:text-[var(--color-secondary-text)] hover:bg-[var(--color-secondary-container)] dark:hover:bg-[var(--color-secondary-container)]/10 transition-colors shrink-0"
          >
            账单页
          </Link>
        </div>

        {/* 超限提醒 */}
        {overItems.length > 0 && (
          <div className="rounded-[var(--radius-Apple-md)] border border-[var(--color-warning-border)] dark:border-[var(--color-warning)] bg-[var(--color-warning-container)] p-[var(--space-apple-md)] flex items-start gap-[var(--space-apple-sm)]">
            <Zap className="w-5 h-5 text-[var(--color-warning-text)] dark:text-[var(--color-warning-text)] mt-0.5 shrink-0" />
            <div className="text-sm text-[var(--color-warning-text)] dark:text-[var(--color-warning-text)]">
              <p className="font-semibold">当前计划已超限（{overItems.length} 项）</p>
              <p className="text-xs mt-0.5">升级到更高计划可解除限制并继续使用完整功能。</p>
            </div>
          </div>
        )}

        {/* 用量进度条 */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          {Object.entries(data.usage || {}).map(([key, item]) => {
            const label = USAGE_LABELS[key] || key
            const pct = item.limit > 0 ? Math.min(100, Math.round((item.used / item.limit) * 100)) : 0
            return (
              <div key={key} className="space-y-1.5">
                <div className="flex items-center justify-between text-sm">
                  <span className="text-[var(--text-secondary)]">{label}</span>
                  <span className={`font-medium tabular-nums ${item.over ? 'text-[var(--color-error-text)]' : 'text-[var(--text-primary)]'}`}>
                    {formatLimit(item.used, item.limit, key)}
                    {item.over && <span className="ml-1 text-xs">超限</span>}
                  </span>
                </div>
                <Progress
                  value={pct}
                  max={100}
                  variant={item.over ? 'danger' : 'success'}
                  size="sm"
                />
              </div>
            )
          })}
        </div>

        {/* 升级/取消 */}
        <div className="pt-3 border-t border-[var(--border-color)] dark:border-neutral-700 space-y-[var(--space-apple-sm)]">
          <div className="flex items-center gap-2">
            <span className="text-xs font-medium text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">计费周期：</span>
            <Button size="sm" variant={billingCycle === 'yearly' ? 'default' : 'ghost'} onClick={() => setBillingCycle('yearly')}>年付（省 17%）</Button>
            <Button size="sm" variant={billingCycle === 'monthly' ? 'default' : 'ghost'} onClick={() => setBillingCycle('monthly')}>月付</Button>
          </div>

          <div className="flex flex-wrap items-center gap-2">
            {data.plan !== 'pro' && (
              <Button
                size="sm"
                variant="glass"
                onClick={() => setConfirmUpgrade('pro')}
                disabled={upgradeMutation.isPending}
              >
                <Crown className="w-4 h-4 mr-1" />
                升级专业版 {billingCycle === 'yearly' ? '¥1999/年' : '¥199/月'}
              </Button>
            )}
            {data.plan !== 'enterprise' && (
              <Button
                size="sm"
                variant="glass"
                onClick={() => setConfirmUpgrade('enterprise')}
                disabled={upgradeMutation.isPending}
              >
                <Building2 className="w-4 h-4 mr-1" />
                升级企业版（联系定制）
              </Button>
            )}
            {data.plan !== 'free' && (
              <Button size="sm" variant="ghost" onClick={() => cancelMutation.mutate()} disabled={cancelMutation.isPending}>
                取消订阅
              </Button>
            )}
            <Button size="sm" variant="ghost" onClick={() => qc.invalidateQueries({ queryKey: ['org-subscription', organizationId] })}>
              <RefreshCw className="w-3.5 h-3.5 mr-1" /> 刷新
            </Button>
          </div>

          {confirmUpgrade && (
            <div className="rounded-[var(--radius-Apple-md)] border border-[var(--color-primary-border)] dark:border-[var(--color-primary)]/50 bg-[var(--color-primary-container)] dark:bg-[var(--color-primary-container)]/10 p-[var(--space-apple-md)] space-y-[var(--space-apple-sm)]">
              <p className="text-sm font-medium text-neutral-800 dark:text-[var(--text-primary)]">
                确认升级到「{PLAN_META[confirmUpgrade]?.label}」（{billingCycle === 'yearly' ? '年付' : '月付'}）？
              </p>
              <p className="text-xs text-[color:var(--text-muted)] dark:text-[color:var(--text-secondary)]">
                当前为模拟支付：将生成一笔已支付订单并立即生效，不产生真实扣款。
              </p>
              <div className="flex gap-2">
                <Button size="sm" onClick={() => upgradeMutation.mutate(confirmUpgrade)} disabled={upgradeMutation.isPending}>
                  {upgradeMutation.isPending ? '处理中...' : '确认升级（模拟支付）'}
                </Button>
                <Button size="sm" variant="ghost" onClick={() => setConfirmUpgrade(null)}>取消</Button>
              </div>
            </div>
          )}
        </div>
      </CardContent>
    </Card>
  )
}

