      <div className="space-y-4">
        <div className="p-4 border rounded-lg">
          <h2 className="font-medium mb-3">测试 1: 基础 range input</h2>
          <input
            type="range"
            min={0}
            max={100}
            value={values.s1}
            onChange={(e) => handleChange('s1', e)}
            className="w-full h-2 bg-neutral-200 rounded-lg"
            aria-label="测试 1: 基础 range input"
          />
          <p className="text-sm mt-1">值: {values.s1}</p>
