 return `${index + 1}. ${authors}. ${citation.title}[C]//${citation.journal || '会议名称'}. ${citation.publisher || ''}: ${citation.year}: ${citation.pages || ''}.`;

 case 'thesis':
 return `${index + 1}. ${authors}. ${citation.title}[D]. ${citation.publisher || '学校名称'}: ${citation.year}.`;

