 default:
 return `${authors}. ${citation.title}. ${citation.year}.`;
 }
 });
 }

 // IEEE 格式
 private generateIEEEReferences(): string[] {
 const sortedCitations = [...this.citations].sort((a, b) => {
 const aFirstAuthor = a.authors[0] || '';
 const bFirstAuthor = b.authors[0] || '';
 return aFirstAuthor.localeCompare(bFirstAuthor, 'en-US');
 });

 return sortedCitations.map((citation, index) => {
 const formatAuthor = (authors: string[]) => {
 if (authors.length === 0) return 'Anonymous';
 return authors.map(a => {
 const parts = a.split(' ');
 if (parts.length > 1) {
 return `${parts[0][0]}. ${parts.slice(1).join(' ')}`;
 }
 return a;
 }).join(', ');
 };

 const authors = formatAuthor(citation.authors);

 switch (citation.type) {
 case 'journal-article':
 return `[${index + 1}] ${authors}, "${citation.title}", *${citation.journal || ''}*, vol. ${citation.volume || ''}, no. 0, pp. ${citation.pages || ''}, ${citation.year}. ${citation.doi ? `doi: ${citation.doi}` : ''}`;

 case 'book':
 return `[${index + 1}] ${authors}, *${citation.title}*. ${citation.publisher || ''}, ${citation.year}.${citation.isbn ? ` ISBN: ${citation.isbn}` : ''}`;

 case 'book-chapter':
 return `[${index + 1}] ${authors}, "${citation.title}", in ${citation.journal || 'Editor'}, Ed., *Book Title*. ${citation.publisher || ''}, ${citation.year}, pp. ${citation.pages || ''}.`;

 case 'conference-proceeding':
 return `[${index + 1}] ${authors}, "${citation.title}", in *${citation.journal || ''}*, ${citation.year}, pp. ${citation.pages || ''}.`;

 case 'thesis':
 return `[${index + 1}] ${authors}, *${citation.title}* [${citation.type === 'thesis' ? 'Ph.D. dissertation' : 'M.S. thesis'}]. ${citation.publisher || 'University'}, ${citation.year}.`;

 case 'report':
 return `[${index + 1}] ${authors}, *${citation.title}* [Tech. Rep.]. ${citation.publisher || 'Organization'}, ${citation.year}.`;

 case 'web-page':
 return `[${index + 1}] ${authors}, "${citation.title}." [Online]. Available: ${citation.url || ''}. [Accessed: ${citation.accessedDate || Date.now().toString()}].`;

 default:
 return `[${index + 1}] ${authors}, ${citation.title}, ${citation.year}.`;
 }
 });
 }

 // 导入BibTeX
 importBibTeX(content: string): Citation[] {
 const entries = content.split('@');
 const imported: Citation[] = [];

 for (const entry of entries) {
 if (!entry.trim()) continue;

 const typeMatch = /^(\w+)\s*\{/.exec(entry);
 if (!typeMatch) continue;

 const bibType = typeMatch[1].toLowerCase() as CitationType;
			const contentMatch = /\{([^}]+)\}/.exec(entry);
			if (!contentMatch) continue;

			const fields = contentMatch[1].split(/,\s*/);
 const citation: Partial<Citation> = {
 type: bibType,
 authors: [],
 title: '',
 year: new Date().getFullYear(),
 };

 for (const field of fields) {
 const [key, value] = field.split(/\s*=\s*/);
 if (!key || !value) continue;

 const cleanValue = value.replace(/["'{}]/g, '').trim();

 switch (key.toLowerCase()) {
 case 'author':
 citation.authors = cleanValue.split(/\s+and\s+/).map(a => a.trim());
 break;
 case 'title':
 citation.title = cleanValue;
 break;
 case 'journal':
 case 'booktitle':
 citation.journal = cleanValue;
 break;
 case 'year':
 citation.year = parseInt(cleanValue) || new Date().getFullYear();
 break;
 case 'volume':
 citation.volume = cleanValue;
 break;
 case 'pages':
 citation.pages = cleanValue;
 break;
 case 'doi':
 citation.doi = cleanValue;
 break;
 case 'isbn':
 citation.isbn = cleanValue;
 break;
 case 'publisher':
 citation.publisher = cleanValue;
 break;
 case 'url':
 citation.url = cleanValue;
 break;
 }
 }

 if (citation.title && citation.authors && citation.authors.length > 0) {
 imported.push(this.addCitation(citation as Omit<Citation, 'id'>));
 }
 }

 return imported;
 }

 // 导出BibTeX
 exportBibTeX(): string {
 return this.citations.map(citation => {
 const type = citation.type.toUpperCase().replace('-', '{-}');
 const fields: string[] = [];

 fields.push(`author = "${citation.authors.join(' and ')}"`);
 fields.push(`title = "${citation.title}"`);
 if (citation.journal) fields.push(`journal = "${citation.journal}"`);
 if (citation.year) fields.push(`year = "${citation.year}"`);
 if (citation.volume) fields.push(`volume = "${citation.volume}"`);
 if (citation.pages) fields.push(`pages = "${citation.pages}"`);
 if (citation.doi) fields.push(`doi = "${citation.doi}"`);
 if (citation.isbn) fields.push(`isbn = "${citation.isbn}"`);
 if (citation.publisher) fields.push(`publisher = "${citation.publisher}"`);
 if (citation.url) fields.push(`url = "${citation.url}"`);

 return `@${type}{${citation.id},\n ${fields.join(',\n ')}\n}`;
 }).join('\n\n');
 }
}

import type { Ingredient, DosageCalculationResult } from '@/types/ai.types'
import { UNIT_CONVERSION_MAP } from '@/config/dosage.constants'


import { logger } from '@/utils/safeLogger';
interface NormalizedDosage {
  value: number
  unit: string
  originalValue?: number
  originalUnit?: string
}

interface PercentageResult {
  ingredient: Ingredient
  percentage: number | null
  normalizedAmount: number | null
  absoluteAmount: { value: number; unit: string }
}

interface DosageCalculationMeta {
  totalNormalizedAmount: number
  totalOriginalAmount: number
  unitConsistent: boolean
  primaryUnit: string
  calculationTimestamp: Date
  warnings: string[]
}

interface BatchCalculationResult {
  ingredients: (Ingredient & { calculatedPercentage: number | null })[]
  meta: DosageCalculationMeta
}

const BASE_UNIT_MASS = 'mg'
const BASE_UNIT_VOLUME = 'ml'
const MASS_UNITS = new Set(['mg', 'g', 'kg', 'μg', 'ug', '钱', '两', '斤'])
const VOLUME_UNITS = new Set(['ml', 'l', 'ul', 'μl'])

function isMassUnit(unit: string): boolean {
  return MASS_UNITS.has(unit.toLowerCase())
}

function isVolumeUnit(unit: string): boolean {
  return VOLUME_UNITS.has(unit.toLowerCase())
}

export function normalizeUnit(value: string): NormalizedDosage | null {
  if (!value || typeof value !== 'string') return null

  const trimmed = value.trim()
  const match = /^([\d.]+)\s*([a-zA-Zμ\u03BC\u4E91\u4E24\u65A4]+)$/.exec(trimmed)

  if (!match) {
    logger.warn(`[DosageCalculator] 无法解析用量值: "${value}"`)
    return null
  }

  const numValue = parseFloat(match[1])
  let rawUnit = match[2].toLowerCase()

  if (rawUnit === 'μg' || rawUnit === '\u03bcg') rawUnit = 'ug'
  if (rawUnit === 'μl' || rawUnit === '\u03bcl') rawUnit = 'ul'

  if (isNaN(numValue) || numValue < 0) {
    logger.warn(`[DosageCalculator] 无效的数值: "${value}"`)
    return null
  }

  let targetUnit: string
  let convertedValue: number | null

  if (isMassUnit(rawUnit)) {
    targetUnit = BASE_UNIT_MASS
    convertedValue = convertToBase(numValue, rawUnit, 'mass')
    if (convertedValue === null) return null
  } else if (isVolumeUnit(rawUnit)) {
    targetUnit = BASE_UNIT_VOLUME
    convertedValue = convertToBase(numValue, rawUnit, 'volume')
    if (convertedValue === null) return null
  } else {
    logger.warn(`[DosageCalculator] 未知的单位类型: "${rawUnit}" (原始值: "${value}")`)
    return {
      value: numValue,
      unit: rawUnit,
      originalValue: numValue,
      originalUnit: rawUnit,
    }
  }

  return {
    value: parseFloat(convertedValue.toFixed(6)),
    unit: targetUnit,
    originalValue: numValue,
    originalUnit: rawUnit,
  }
}

function convertToBase(value: number, fromUnit: string, type: 'mass' | 'volume'): number | null {
  if (type === 'mass') {
    switch (fromUnit.toLowerCase()) {
      case 'mg': return value
      case 'g': return value * 1000
      case 'kg': return value * 1000000
      case 'ug': return value * 0.001
      case '钱': return value * 5000
      case '两': return value * 50000
      case '斤': return value * 500000
      default:
        logger.warn(`[DosageCalculator] 不支持的质量单位转换: ${fromUnit}`)
        return null
    }
  } else {
    switch (fromUnit.toLowerCase()) {
      case 'ml': return value
      case 'l': return value * 1000
      case 'ul': return value * 0.001
      default:
        logger.warn(`[DosageCalculator] 不支持的体积单位转换: ${fromUnit}`)
        return null
    }
  }
}

export function calculateTotalAmount(ingredients: Ingredient[]): number {
  if (!Array.isArray(ingredients) || ingredients.length === 0) return 0

  const amounts: number[] = []
  let primaryType: 'mass' | 'volume' | null = null

  for (const ing of ingredients) {
    if (!ing || typeof ing.amount !== 'number' || !ing.unit) continue

    const normalized = normalizeUnit(`${ing.amount}${ing.unit}`)
    if (!normalized) continue

    const currentType = isMassUnit(normalized.unit) ? 'mass' : 'volume'

    if (primaryType === null) {
      primaryType = currentType
    } else if (primaryType !== currentType) {
      logger.warn(`[DosageCalculator] 检测到混合单位类型: ${ing.name} (${normalized.unit}) 与主单位类型不一致`)
    }

    amounts.push(normalized.value)
  }

  const total = amounts.reduce((sum, val) => sum + val, 0)
  return parseFloat(total.toFixed(6))
}

export function calculatePercentage(
  ingredient: Ingredient,
  totalAmount: number,
): number | null {
  if (!ingredient || totalAmount <= 0) return null

  if (typeof ingredient.amount !== 'number' || !ingredient.unit) {
    logger.warn(`[DosageCalculator] 成分缺少必要的用量数据:`, ingredient)
    return null
  }

  const normalized = normalizeUnit(`${ingredient.amount}${ingredient.unit}`)
  if (!normalized || normalized.value <= 0) return null

  const percentage = (normalized.value / totalAmount) * 100
  return parseFloat(percentage.toFixed(1))
}

export function calculateAllPercentages(
  ingredients: Ingredient[],
): BatchCalculationResult | null {
  if (!Array.isArray(ingredients) || ingredients.length === 0) {
    logger.warn('[DosageCalculator] 输入的成分数组为空')
    return null
  }

  const warnings: string[] = []
  const enhancedIngredients: (Ingredient & { calculatedPercentage: number | null })[] = []
  let totalNormalized = 0
  let totalOriginal = 0
  let unitConsistent = true
  let detectedPrimaryUnit: string | null = null

  for (let i = 0; i < ingredients.length; i++) {
    const ing = ingredients[i]

    if (!ing || typeof ing.amount !== 'number' || !ing.unit) {
      warnings.push(`成分 #${i + 1} (${ing?.name ?? '未知'}): 缺少用量或单位数据`)
      enhancedIngredients.push({
        ...ing,
        calculatedPercentage: null,
      })
      continue
    }

    const normalized = normalizeUnit(`${ing.amount}${ing.unit}`)

    if (!normalized) {
      warnings.push(`成分 #${i + 1} (${ing.name}): 单位解析失败 (${ing.amount}${ing.unit})`)
      enhancedIngredients.push({
        ...ing,
        calculatedPercentage: null,
      })
      continue
    }

    totalOriginal += ing.amount

    if (detectedPrimaryUnit === null) {
      detectedPrimaryUnit = normalized.unit
    } else if (detectedPrimaryUnit !== normalized.unit && isMassUnit(normalized.unit) && isMassUnit(detectedPrimaryUnit)) {
      // 同类型不同基准单位，继续（已统一到基准）
    } else if (detectedPrimaryUnit !== normalized.unit) {
      unitConsistent = false
      warnings.push(`检测到质量/体积单位混合: ${ing.name} 使用 ${normalized.unit}`)
    }

    totalNormalized += normalized.value

    enhancedIngredients.push({
      ...ing,
      calculatedPercentage: null, // 先设为null，后面统一计算
    })
  }

  if (totalNormalized <= 0) {
    warnings.push('所有成分的总标准化用量为0，无法计算占比')
    return {
      ingredients: enhancedIngredients,
      meta: {
        totalNormalizedAmount: 0,
        totalOriginalAmount: totalOriginal,
        unitConsistent,
        primaryUnit: detectedPrimaryUnit || 'unknown',
        calculationTimestamp: new Date(),
        warnings,
      },
    }
  }

  for (let i = 0; i < enhancedIngredients.length; i++) {
    const ing = ingredients[i]
    if (!ing || typeof ing.amount !== 'number' || !ing.unit) continue

    const normalized = normalizeUnit(`${ing.amount}${ing.unit}`)
    if (!normalized) continue

    const percentage = parseFloat(((normalized.value / totalNormalized) * 100).toFixed(1))
    enhancedIngredients[i].calculatedPercentage = percentage
  }

  const sumPercentages = enhancedIngredients
    .filter(ing => ing.calculatedPercentage !== null)
    .reduce((sum, ing) => sum + (ing.calculatedPercentage ?? 0), 0)

  if (Math.abs(sumPercentages - 100) > 1) {
    warnings.push(`百分比总和异常: ${sumPercentages.toFixed(1)}% (期望≈100%)`)
  }

  return {
    ingredients: enhancedIngredients,
    meta: {
      totalNormalizedAmount: parseFloat(totalNormalized.toFixed(6)),
      totalOriginalAmount: parseFloat(totalOriginal.toFixed(6)),
      unitConsistent,
      primaryUnit: detectedPrimaryUnit || 'unknown',
      calculationTimestamp: new Date(),
      warnings,
    },
  }
}

export function getIngredientAbsoluteAmount(ingredient: Ingredient): { value: number; unit: string } | null {
  if (!ingredient || typeof ingredient.amount !== 'number' || !ingredient.unit) return null

  const normalized = normalizeUnit(`${ingredient.amount}${ingredient.unit}`)
  if (!normalized) return null

  return {
    value: normalized.originalValue ?? ingredient.amount,
    unit: normalized.originalUnit ?? ingredient.unit,
  }
}

import Fuse from 'fuse.js'
import type {
  EfficacyTag,
  TagCategory,
  EfficacyTagMeta,
  TagCategoryNode,
} from '@/types/efficacyTag.types'
import {
  EFFICACY_TAG_METADATA,
  EFFICACY_TAG_CATEGORY_TREE,
  getEfficacyTagMeta,
} from '@/config/efficacyTags.constants'

export interface MatchedTagResult {
  tag: EfficacyTag
  matchType: 'exact' | 'alias' | 'fuzzy'
  confidence: number
  meta: EfficacyTagMeta
}

const INGREDIENT_ALIAS_MAP: Record<string, string> = {
  '酸枣仁': 'Ziziphus jujuba',
  '人参': 'Panax ginseng',
  '黄芪': 'Astragalus membranaceus',
  '灵芝': 'Ganoderma lucidum',
  '枸杞': 'Lycium barbarum',
  '当归': 'Angelica sinensis',
  '熟地黄': 'Rehmannia glutinosa',
  '白芍': 'Paeonia lactiflora',
  '川芎': 'Ligusticum chuanxiong',
  '丹参': 'Salvia miltiorrhiza',
  '三七': 'Panax notoginseng',
  '山楂': 'Crataegus pinnatifida',
  '茯苓': 'Poria cocos',
  '白术': 'Atractylodes macrocephala',
  '陈皮': 'Citrus reticulata',
  '甘草': 'Glycyrrhiza uralensis',
  '柴胡': 'Bupleurum chinense',
  '杜仲': 'Eucommia ulmoides',
  '淫羊藿': 'Epimedium brevicornum',
  '何首乌': 'Polygonum multiflorum',
  '菊花': 'Chrysanthemum morifolium',
}

class EfficacyTagService {
  private presetTags: EfficacyTag[] = []
  private categories: TagCategoryNode[] = []
  private fuseInstance: Fuse<EfficacyTagMeta> | null = null

  constructor() {
    this.initialize()
  }

  private initialize(): void {
    this.presetTags = EFFICACY_TAG_METADATA.map((meta) => meta.name)
    this.categories = EFFICACY_TAG_CATEGORY_TREE
    this.fuseInstance = new Fuse(EFFICACY_TAG_METADATA, {
      keys: [
        { name: 'name', weight: 2.0 },
        { name: 'keywords', weight: 1.5 },
        { name: 'relatedIngredients', weight: 1.0 },
        { name: 'description', weight: 0.5 },
      ],
      threshold: 0.3,
      includeScore: true,
      minMatchCharLength: 1,
    })
  }

  loadPresetTags(): EfficacyTag[] {
    return [...this.presetTags]
  }

  getTagCategories(): TagCategoryNode[] {
    return [...this.categories]
  }

  getTagMeta(tagName: EfficacyTag): EfficacyTagMeta | undefined {
    return getEfficacyTagMeta(tagName)
  }

  matchTagsByIngredientName(
    ingredientName: string,
    allTags?: EfficacyTag[],
  ): MatchedTagResult[] {
    const tagsToSearch = allTags || this.presetTags
    const results: MatchedTagResult[] = []
    const matchedTagNames = new Set<string>()

    const exactMatches = this.findExactMatches(ingredientName, tagsToSearch)
    exactMatches.forEach((result) => {
      if (!matchedTagNames.has(result.tag)) {
        matchedTagNames.add(result.tag)
        results.push(result)
      }
    })

    const aliasMatches = this.findAliasMatches(ingredientName, tagsToSearch)
    aliasMatches.forEach((result) => {
      if (!matchedTagNames.has(result.tag)) {
        matchedTagNames.add(result.tag)
        results.push(result)
      }
    })

    const fuzzyMatches = this.findFuzzyMatches(ingredientName, tagsToSearch)
    fuzzyMatches.forEach((result) => {
      if (!matchedTagNames.has(result.tag)) {
        matchedTagNames.add(result.tag)
        results.push(result)
      }
    })

    results.sort((a, b) => b.confidence - a.confidence)

    return results.slice(0, 5)
  }

  private findExactMatches(
    ingredientName: string,
    tagsToSearch: EfficacyTag[],
  ): MatchedTagResult[] {
    const results: MatchedTagResult[] = []

    for (const tagName of tagsToSearch) {
      const meta = getEfficacyTagMeta(tagName)
      if (!meta) continue

      const isExactMatch = meta.relatedIngredients.some(
        (related) =>
          related.toLowerCase() === ingredientName.toLowerCase() ||
          related.includes(ingredientName) ||
          ingredientName.includes(related),
      )

      if (isExactMatch) {
        results.push({
          tag: tagName,
          matchType: 'exact',
          confidence: 1.0,
          meta,
        })
      }
    }

    return results
  }

  private findAliasMatches(
    ingredientName: string,
    tagsToSearch: EfficacyTag[],
  ): MatchedTagResult[] {
    const results: MatchedTagResult[] = []

    const latinAlias = INGREDIENT_ALIAS_MAP[ingredientName]
    if (!latinAlias) return results

    for (const tagName of tagsToSearch) {
      const meta = getEfficacyTagMeta(tagName)
      if (!meta) continue

      const isAliasMatch = meta.relatedIngredients.some(
        (related) =>
          related.toLowerCase() === latinAlias.toLowerCase() ||
          related.toLowerCase().includes(latinAlias.toLowerCase()) ||
          latinAlias.toLowerCase().includes(related.toLowerCase()),
      )

      if (isAliasMatch) {
        results.push({
          tag: tagName,
          matchType: 'alias',
          confidence: 0.85,
          meta,
        })
      }
    }

    return results
  }

  private findFuzzyMatches(
    ingredientName: string,
    _tagsToSearch: EfficacyTag[],
  ): MatchedTagResult[] {
    if (!this.fuseInstance) return []

    const searchResults = this.fuseInstance.search(ingredientName)

    return searchResults
      .filter((result) => result.score !== undefined && result.score < 0.3)
      .map((result) => ({
        tag: result.item.name,
        matchType: 'fuzzy' as const,
        confidence: Math.max(0, Math.min(1, 1 - (result.score ?? 0))),
        meta: result.item,
      }))
  }

  batchMatchTags(
    ingredients: { name: string }[],
  ): Map<string, EfficacyTag[]> {
    const tagMap = new Map<string, EfficacyTag[]>()

    for (const ingredient of ingredients) {
      const matches = this.matchTagsByIngredientName(ingredient.name)
      const uniqueTags = [...new Set(matches.map((m) => m.tag))]
      tagMap.set(ingredient.name, uniqueTags)
    }

    return tagMap
  }

  getCategoryColor(category: TagCategory): string {
    const categoryNode = this.categories.find((cat) => cat.category === category)
    return categoryNode?.color || '#8c8c8c'
  }

  getCategoryIcon(category: TagCategory): string | undefined {
    const categoryNode = this.categories.find((cat) => cat.category === category)
    return categoryNode?.icon
  }

  getAllTagsByCategory(category: TagCategory): EfficacyTag[] {
    const categoryNode = this.categories.find((cat) => cat.category === category)
    return categoryNode?.tags || []
  }
}

export const efficacyTagService = new EfficacyTagService()

export default efficacyTagService

import { logger } from '@/utils/safeLogger';

/**
 * 增强版错误处理与日志记录系统
 * 提供分级错误捕获、详细错误日志、用户友好错误提示
 */

// 错误级别
export enum ErrorLevel {
  DEBUG = 'debug',
  INFO = 'info',
  WARNING = 'warning',
  ERROR = 'error',
  CRITICAL = 'critical',
}

// 错误类型
export enum ErrorCategory {
  NETWORK = 'network',
  VALIDATION = 'validation',
  PERMISSION = 'permission',
  RUNTIME = 'runtime',
  RESOURCE = 'resource',
  EXTERNAL = 'external',
  UNKNOWN = 'unknown',
}

// 错误信息接口
export interface AppError {
  id: string;
  level: ErrorLevel;
  category: ErrorCategory;
  timestamp: number;
  message: string;
  detail?: string;
  stack?: string;
  context?: Record<string, any>;
  recoverable: boolean;
  userFriendlyMessage: string;
}

// 错误记录接口
export interface ErrorRecord {
  timestamp: number;
  type: string;
  message: string;
  detail?: string;
  stack?: string;
  level: string;
  url: string;
  userAgent: string;
  context?: Record<string, any>;
}

class ErrorHandler {
  private static instance: ErrorHandler;
  private errorBuffer: ErrorRecord[] = [];
  private readonly MAX_BUFFER_SIZE = 100;
  private onErrorCallbacks: ((error: AppError) => void)[] = [];
  private enableConsoleLogging = true;
  private enableRemoteReporting = false;
  private logLevel: ErrorLevel = ErrorLevel.WARNING;

  private constructor() {
    this.initGlobalErrorHandlers();
  }

  public static getInstance(): ErrorHandler {
    if (!ErrorHandler.instance) {
      ErrorHandler.instance = new ErrorHandler();
    }
    return ErrorHandler.instance;
  }

  // 启用/禁用控制台日志
  public setConsoleLogging(enabled: boolean): void {
    this.enableConsoleLogging = enabled;
  }

  // 设置日志级别
  public setLogLevel(level: ErrorLevel): void {
    this.logLevel = level;
  }

  // 添加错误回调
  public addErrorCallback(callback: (error: AppError) => void): () => void {
    this.onErrorCallbacks.push(callback);
    return () => {
      this.onErrorCallbacks = this.onErrorCallbacks.filter(cb => cb !== callback);
    };
  }

  // 初始化全局错误处理器
  private initGlobalErrorHandlers(): void {
    if (typeof window !== 'undefined') {
      // 全局未捕获异常
      window.addEventListener('error', (event) => {
        this.handleGlobalError(event);
      });

      // Promise未捕获异常
      window.addEventListener('unhandledrejection', (event) => {
        this.handlePromiseRejection(event);
      });
    }
  }

  // 处理全局错误
  private handleGlobalError(event: ErrorEvent): void {
    // ── 静默过滤请求被中止的错误（页面导航/组件卸载等正常场景）──
    // 注意：XHR 中止时 event.message 通常为空字符串，错误信息在 event.error 中
    const errorMsg = String(event.message || '') + ' ' + String(event.error?.message || event.error?.code || '')
    if (errorMsg.match(/ERR_ABORTED|canceled|Request aborted|aborted/i)) {
      return;
    }

    const error: AppError = {
      id: `err_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`,
      level: ErrorLevel.ERROR,
      category: ErrorCategory.RUNTIME,
      timestamp: Date.now(),
      message: event.message || '未知错误',
      detail: String(event.error),
      stack: event.error?.stack,
      recoverable: false,
      userFriendlyMessage: '系统遇到意外错误，请刷新页面重试。',
    };
    this.processError(error);
  }

  // 处理Promise未捕获异常
  private handlePromiseRejection(event: PromiseRejectionEvent): void {
    // ── 静默过滤请求被中止的 rejection ──
    const reason = String(event.reason?.message || event.reason?.code || event.reason || '')
    if (reason.match(/ERR_ABORTED|canceled|Request aborted|aborted/i)) {
      return;
    }

    const error: AppError = {
      id: `err_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`,
      level: ErrorLevel.ERROR,
      category: ErrorCategory.RUNTIME,
      timestamp: Date.now(),
      message: String(event.reason),
      stack: event.reason?.stack,
      recoverable: true,
      userFriendlyMessage: '操作执行失败，请重试。',
    };
    this.processError(error);
  }

  // 处理错误（主方法）
  public handleError(
    error: Error | string,
    options: {
      level?: ErrorLevel;
      category?: ErrorCategory;
      context?: Record<string, any>;
      userFriendlyMessage?: string;
      recoverable?: boolean;
    } = {},
  ): AppError {
    const appError = this.createAppError(error, options);
    this.processError(appError);
    return appError;
  }

  // 创建标准化错误对象
  private createAppError(
    error: Error | string,
    options: {
      level?: ErrorLevel;
      category?: ErrorCategory;
      context?: Record<string, any>;
      userFriendlyMessage?: string;
      recoverable?: boolean;
    } = {},
  ): AppError {
    const {
      level = ErrorLevel.ERROR,
      category = ErrorCategory.UNKNOWN,
      context = {},
      userFriendlyMessage = '发生未知错误',
      recoverable = true,
    } = options;

    let message: string;
    let stack: string | undefined;
    let detail: string | undefined;

    if (typeof error === 'string') {
      message = error;
    } else {
      message = error.message || '未知错误';
      stack = error.stack;
      detail = String(error);
    }

    return {
      id: `err_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`,
      level,
      category,
      timestamp: Date.now(),
      message,
      detail,
      stack,
      context,
      recoverable,
      userFriendlyMessage,
    };
  }

  // 处理错误
  private processError(error: AppError): void {
    // 添加到缓冲区
    this.addToBuffer(error);

    // 回调通知
    this.onErrorCallbacks.forEach(callback => {
      try {
        callback(error);
      } catch (err) {
        logger.error('错误回调执行失败:', err);
      }
    });

    // 控制台日志
    if (this.enableConsoleLogging && this.shouldLog(error.level)) {
      this.logToConsole(error);
    }

    // 远程上报（可选）
    if (this.enableRemoteReporting) {
      this.reportError(error);
    }
  }

  // 检查是否应该记录
  private shouldLog(level: ErrorLevel): boolean {
    const levelOrder = [
      ErrorLevel.DEBUG,
      ErrorLevel.INFO,
      ErrorLevel.WARNING,
      ErrorLevel.ERROR,
      ErrorLevel.CRITICAL,
    ];
    const currentIndex = levelOrder.indexOf(this.logLevel);
    const errorIndex = levelOrder.indexOf(level);
    return errorIndex >= currentIndex;
  }

  // 添加到缓冲区
  private addToBuffer(error: AppError): void {
    const record: ErrorRecord = {
      timestamp: error.timestamp,
      type: error.category,
      message: error.message,
      detail: error.detail,
      stack: error.stack,
      level: error.level,
      url: typeof window !== 'undefined' ? window.location.href : 'n/a',
      userAgent: typeof navigator !== 'undefined' ? navigator.userAgent : 'n/a',
      context: error.context,
    };

    this.errorBuffer.push(record);

    // 限制缓冲区大小
    if (this.errorBuffer.length > this.MAX_BUFFER_SIZE) {
      this.errorBuffer.shift();
    }
  }

  // 控制台日志输出
  private logToConsole(error: AppError): void {
    const { level, message, detail, stack, context } = error;

    const logMethod = {
      [ErrorLevel.DEBUG]: console.debug,
      [ErrorLevel.INFO]: console.info,
      [ErrorLevel.WARNING]: console.warn,
      [ErrorLevel.ERROR]: console.error,
      [ErrorLevel.CRITICAL]: console.error,
    };

    const logger = logMethod[level] || console.error;

    const prefix = `[${error.timestamp}] [${error.level.toUpperCase()}]`;

    logger(`${prefix} ${message}`);
    if (detail && detail !== message) {
      logger(`  详情: ${detail}`);
    }
    if (context && Object.keys(context).length > 0) {
      logger('  上下文:', context);
    }
    if (stack) {
      logger('  堆栈:', stack);
    }
  }

  // 上报错误（可扩展）
  private reportError(error: AppError): void {
    logger.debug('错误上报（功能开发中）:', error);
  }

  // 获取错误历史
  public getErrorHistory(): ErrorRecord[] {
    return [...this.errorBuffer];
  }

  // 清除错误历史
  public clearHistory(): void {
    this.errorBuffer = [];
  }

  // 便利方法 - 快速创建警告
  public warning(
    message: string,
    context?: Record<string, any>,
  ): AppError {
    return this.handleError(message, {
      level: ErrorLevel.WARNING,
      category: ErrorCategory.VALIDATION,
      context,
      userFriendlyMessage: message,
    });
  }

  // 便利方法 - 快速创建错误
  public error(
    message: string,
    options?: {
      category?: ErrorCategory;
      context?: Record<string, any>;
      userFriendlyMessage?: string;
      recoverable?: boolean;
    },
  ): AppError {
    return this.handleError(message, {
      level: ErrorLevel.ERROR,
      ...options,
    });
  }

  // 便利方法 - 网络错误
  public networkError(
    error: Error | string,
    context?: Record<string, any>,
  ): AppError {
    return this.handleError(error, {
      level: ErrorLevel.ERROR,
      category: ErrorCategory.NETWORK,
      context,
      userFriendlyMessage: '网络连接失败，请检查网络设置后重试。',
      recoverable: true,
    });
  }

  // 便利方法 - 验证错误
  public validationError(
    message: string,
    field?: string,
  ): AppError {
    return this.handleError(message, {
      level: ErrorLevel.WARNING,
      category: ErrorCategory.VALIDATION,
      context: { field },
      userFriendlyMessage: message,
    });
  }
}

