/**
 * PDF 导出服务
 * 使用 jspdf + jspdf-autotable 实现专业级 PDF 导出功能
 */

import { logger } from '@/utils/safeLogger'
import jsPDF from 'jspdf'
import autoTable from 'jspdf-autotable'
import type { ColumnDef } from '@tanstack/react-table'
import type { EnhancedIngredient, ProfessionalReport } from '@/types/ai.types'

/** PDF 导出选项 */
export interface PdfExportOptions {
  filename?: string
  title?: string
  subtitle?: string
  author?: string
  date?: string
  watermark?: boolean
  watermarkText?: string
  orientation?: 'portrait' | 'landscape'
  fontSize?: number
  showPageNumbers?: boolean
}

/** 表格样式配置 */
interface TableStyle {
  headerBackgroundColor?: [number, number, number]
  headerTextColor?: [number, number, number]
  alternateRowColors?: [[number, number, number], [number, number, number]]
  borderColor?: [number, number, number]
  cellPadding?: number
}

const DEFAULT_OPTIONS: Required<PdfExportOptions> = {
  filename: 'RMFOOD_配方明细',
  title: 'RMFOOD 配方平台',
  subtitle: '专业配方分析报告',
  author: 'AI 智能分析系统',
  date: new Date().toLocaleDateString('zh-CN'),
  watermark: true,
  watermarkText: 'RMFOOD 配方平台',
  orientation: 'portrait',
  fontSize: 10,
  showPageNumbers: true,
}

const DEFAULT_TABLE_STYLE: TableStyle = {
  headerBackgroundColor: [41, 128, 185],
  headerTextColor: [255, 255, 255],
  alternateRowColors: [[245, 245, 245], [255, 255, 255]],
  borderColor: [200, 200, 200],
  cellPadding: 5,
}

/**
 * 导出数据为 PDF 格式（表格数据）
 */
export async function exportToPDF(
  data: any[] | EnhancedIngredient[],
  options: Partial<PdfExportOptions> = {},
  columns?: ColumnDef<any>[],
): Promise<void> {
  if (!data || data.length === 0) {
    logger.warn('[PdfExportService] No data to export')
    return
  }

  try {
    const config = { ...DEFAULT_OPTIONS, ...options }

    const doc = new jsPDF({
      orientation: config.orientation,
      unit: 'mm',
      format: 'a4',
    })

    doc.setProperties({
      title: config.title,
      subject: config.subtitle,
      author: config.author,
      creator: 'RMFOOD 配方平台',
    })

    if (config.watermark) {
      addWatermark(doc, config.watermarkText)
    }

    addTitleSection(doc, config)

    const headers = prepareTableHeaders(data[0], columns)
    const rows = prepareTableRows(data, headers)

    addStyledTable(doc, headers, rows, {
      startY: getTableStartY(doc),
      styles: DEFAULT_TABLE_STYLE,
      showPageNumbers: config.showPageNumbers,
    })

    addFooterInfo(doc, config)

    const filename = `${config.filename}_${formatDate()}.pdf`
    doc.save(filename)

    logger.log(`[PdfExportService] ✅ PDF export success: ${filename}`)

  } catch (error) {
    logger.error('[PdfExportService] ❌ PDF export failed:', error)
    throw new Error(`PDF export failed: ${error instanceof Error ? error.message : 'Unknown error'}`)
  }
}

/**
 * 导出专业报告为 PDF 格式
 */
export async function exportReportToPDF(
  reportData: ProfessionalReport,
  options: Partial<PdfExportOptions> = {},
): Promise<void> {
  try {
    const config = {
      ...DEFAULT_OPTIONS,
      ...options,
      filename: 'RMFOOD_专业分析报告',
      title: 'RMFOOD 专业配方分析报告',
      subtitle: `生成时间: ${new Date().toLocaleString('zh-CN')}`,
    }

    const doc = new jsPDF({
      orientation: 'portrait',
      unit: 'mm',
      format: 'a4',
    })

    doc.setProperties({
      title: config.title,
      subject: config.subtitle,
      author: config.author,
      creator: 'RMFOOD 配方平台',
    })

    if (config.watermark) {
      addWatermark(doc, config.watermarkText)
    }

    let currentY = 20

    currentY = addReportHeader(doc, reportData, currentY)

    currentY = addSectionWithTitle(doc, '一、执行摘要', currentY)
    addTextBlock(doc, reportData.title || '专业分析报告', currentY)

    addFooterInfo(doc, config)

    const filename = `${config.filename}_${formatDate()}.pdf`
    doc.save(filename)

    logger.log(`[PdfExportService] ✅ Report PDF export success: ${filename}`)

  } catch (error) {
    logger.error('[PdfExportService] ❌ Report PDF export failed:', error)
    throw error
  }
}

function addWatermark(doc: jsPDF, text: string): void {
  const pageCount = doc.getNumberOfPages()

  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i)
    doc.setFontSize(60)
    doc.setTextColor(230, 230, 230)

    const pageWidth = doc.internal.pageSize.getWidth()
    const pageHeight = doc.internal.pageSize.getHeight()

    doc.text(text, pageWidth / 2, pageHeight / 2, {
      align: 'center',
      angle: 45,
    })
  }
}

function addTitleSection(doc: jsPDF, config: Required<PdfExportOptions>): void {
  const pageWidth = doc.internal.pageSize.getWidth()

  doc.setFontSize(24)
  doc.setTextColor(41, 128, 185)
  doc.text(config.title, pageWidth / 2, 25, { align: 'center' })

  doc.setFontSize(14)
  doc.setTextColor(100, 100, 100)
  doc.text(config.subtitle, pageWidth / 2, 33, { align: 'center' })

  doc.setFontSize(10)
  doc.setTextColor(150, 150, 150)
  doc.text(`作者: ${config.author}`, pageWidth / 2, 42, { align: 'center' })
  doc.text(`日期: ${config.date}`, pageWidth / 2, 47, { align: 'center' })

  doc.setDrawColor(41, 128, 185)
  doc.setLineWidth(0.5)
  doc.line(20, 52, pageWidth - 20, 52)
}

function getTableStartY(doc: jsPDF): number {
  void doc;
  return 58
}

function addStyledTable(
  doc: jsPDF,
  headers: string[],
  rows: any[][],
  options: {
    startY: number
    styles: TableStyle
    showPageNumbers?: boolean
  },
): void {
  autoTable(doc, {
    head: [headers],
    body: rows,
    startY: options.startY,
    margin: { top: 20, right: 15, bottom: 20, left: 15 },
    styles: {
      fontSize: options.styles.cellPadding || 5,
      cellPadding: options.styles.cellPadding || 5,
      lineColor: options.styles.borderColor || [200, 200, 200],
      lineWidth: 0.1,
    },
    headStyles: {
      fillColor: options.styles.headerBackgroundColor || [41, 128, 185],
      textColor: options.styles.headerTextColor || [255, 255, 255],
      fontStyle: 'bold',
      halign: 'center',
    },
    alternateRowStyles: {
      fillColor: options.styles.alternateRowColors?.[0] || [245, 245, 245],
    },
    didDrawPage: (data) => {
      if (options.showPageNumbers) {
        const pageCount = doc.getNumberOfPages()
        const currentPage = data.pageNumber

        doc.setFontSize(9)
        doc.setTextColor(150, 150, 150)
        doc.text(
          `第 ${currentPage} / ${pageCount} 页`,
          doc.internal.pageSize.getWidth() / 2,
          doc.internal.pageSize.getHeight() - 10,
          { align: 'center' },
        )
      }
    },
  })
}

function addFooterInfo(doc: jsPDF, config: Required<PdfExportOptions>): void {
  void config;
  const pageCount = doc.getNumberOfPages()

  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i)

    const pageHeight = doc.internal.pageSize.getHeight()
    const pageWidth = doc.internal.pageSize.getWidth()

    doc.setDrawColor(200, 200, 200)
    doc.setLineWidth(0.3)
    doc.line(15, pageHeight - 15, pageWidth - 15, pageHeight - 15)

    doc.setFontSize(8)
    doc.setTextColor(150, 150, 150)
    doc.text(
      '© 2025 RMFOOD 配方平台 | AI 智能分析系统 | 保密文件',
      pageWidth / 2,
      pageHeight - 10,
      { align: 'center' },
    )
  }
}

function prepareTableHeaders(firstRow: any, columns?: ColumnDef<any>[]): string[] {
  if (columns && columns.length > 0) {
    return columns.map((col) => {
      const h = (col as ColumnDef<any, any> & { header?: string | ((info: unknown) => unknown) }).header
      return typeof h === 'function' ? String(h({})) : (typeof h === 'string' ? h : (col as ColumnDef<any, any> & { accessorKey?: string }).accessorKey || '')
    }).filter(Boolean)
  }

  return Object.keys(firstRow || {})
}

function prepareTableRows(data: any[], headers: string[]): any[][] {
  return data.map(row =>
    headers.map(header => {
      const value = row[header]

      if (value === null || value === undefined) return ''
      if (typeof value === 'object') return JSON.stringify(value)
      if (typeof value === 'boolean') return value ? '是' : '否'

      return String(value)
    }),
  )
}

function formatDate(): string {
  const now = new Date()
  return `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}${String(now.getDate()).padStart(2, '0')}_${String(now.getHours()).padStart(2, '0')}${String(now.getMinutes()).padStart(2, '0')}`
}

function addReportHeader(doc: jsPDF, report: ProfessionalReport, y: number): number {
  const pageWidth = doc.internal.pageSize.getWidth()

  doc.setFontSize(22)
  doc.setTextColor(41, 128, 185)
  doc.text(report.title || '专业分析报告', pageWidth / 2, y, { align: 'center' })

  y += 12
  doc.setFontSize(11)
  doc.setTextColor(100, 100, 100)
  doc.text(`版本: ${report.version}`, 20, y)
  doc.text(`生成时间: ${report.generatedAt.toLocaleDateString('zh-CN')}`, pageWidth - 70, y)

  y += 8
  doc.setDrawColor(41, 128, 185)
  doc.setLineWidth(0.5)
  doc.line(20, y, pageWidth - 20, y)

  return y + 10
}

function addSectionWithTitle(doc: jsPDF, title: string, y: number): number {
  checkAndAddPage(doc, y, 30)

  doc.setFontSize(16)
  doc.setTextColor(41, 128, 185)
  doc.text(title, 20, y)

  doc.setDrawColor(41, 128, 185)
  doc.setLineWidth(0.3)
  doc.line(20, y + 2, 200, y + 2)

  return y + 12
}

function addTextBlock(doc: jsPDF, text: string, y: number): number {
  const maxWidth = doc.internal.pageSize.getWidth() - 40
  const lines = doc.splitTextToSize(text, maxWidth)

  doc.setFontSize(11)
  doc.setTextColor(60, 60, 60)

  lines.forEach((line: string) => {
    checkAndAddPage(doc, y, 15)
    doc.text(line, 20, y)
    y += 6
  })

  return y + 5
}

function checkAndAddPage(doc: jsPDF, currentY: number, requiredSpace: number): number {
  const pageHeight = doc.internal.pageSize.getHeight()
  const marginBottom = 25

  if (currentY + requiredSpace > pageHeight - marginBottom) {
    doc.addPage()
    return 20
  }

  return currentY
}

import React, { useState, useEffect } from 'react';
import { PeptideService, Peptide, PeptideAnalysis, BioactivityPrediction } from './peptideService';

interface PeptideAnalyzerProps {
  initialSequence?: string;
}

export const PeptideAnalyzer: React.FC<PeptideAnalyzerProps> = ({ initialSequence = 'LVGQDPVHPF' }) => {
  const [sequence, setSequence] = useState(initialSequence);
  const [analysis, setAnalysis] = useState<PeptideAnalysis | null>(null);
  const [bioactivity, setBioactivity] = useState<BioactivityPrediction[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const peptideService = PeptideService.getInstance();

  const analyzePeptide = () => {
    setLoading(true);
    setError(null);

    try {
      const result = peptideService.analyzePeptide(sequence);
      setAnalysis(result);

      const predictions = peptideService.predictBioactivity(sequence);
      setBioactivity(predictions);
    } catch (err) {
      setError(err instanceof Error ? err.message : '分析失败');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    analyzePeptide();
  }, []);

  return (
    <div className="peptide-analyzer">
      <input
        type="text"
        value={sequence}
        onChange={(e) => setSequence(e.target.value.toUpperCase())}
        placeholder="请输入肽序列"
      />
      <button onClick={analyzePeptide} disabled={loading}>
        {loading ? '分析中…' : '分析'}
      </button>

      {error && <div className="error">{error}</div>}

      {analysis && (
        <div className="analysis-results">
          <h3>分析结果</h3>
          <div>序列长度：{analysis.length}</div>
          <div>分子量：{analysis.molecularWeight.toFixed(2)} Da</div>
          <div>等电点：{analysis.isoelectricPoint.toFixed(2)}</div>
          <div>疏水性：{analysis.hydrophobicity.toFixed(2)}</div>
          <div>GRAVY（脂残基指数）：{analysis.gravy.toFixed(2)}</div>
          <div>不稳定性指数：{analysis.instabilityIndex.toFixed(2)}</div>
          <div>脂肪族指数：{analysis.aliphaticIndex.toFixed(2)}</div>
          <div>pH 7 净电荷：{analysis.chargeAtPH7.toFixed(3)}</div>

          <h4>二级结构预测</h4>
          <div>α-螺旋：{analysis.secondaryStructure.helix.toFixed(2)}%</div>
          <div>β-折叠：{analysis.secondaryStructure.sheet.toFixed(2)}%</div>
          <div>卷曲/无规：{analysis.secondaryStructure.coil.toFixed(2)}%</div>

          <h4>氨基酸组成</h4>
          <div>{JSON.stringify(analysis.aminoAcidComposition, null, 2)}</div>
        </div>
      )}

      {bioactivity.length > 0 && (
        <div className="bioactivity-predictions">
          <h3>生物活性预测</h3>
          {bioactivity.map((pred, index) => (
            <div key={index} className="prediction">
              <h4>{pred.type}</h4>
              <div>置信度：{(pred.confidence * 100).toFixed(1)}%</div>
              <div>{pred.mechanism}</div>
              {pred.predictedIC50 && (
                <div>预测 IC50：{pred.predictedIC50.toFixed(2)} μM</div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default PeptideAnalyzer;

import type { ProfessionalServiceConfig, ApiResponse, ErrorResponse } from '../../types/professional';

export class ProfessionalBaseService {
  protected baseURL: string;
  protected timeout: number;
  protected retries: number;
  protected cacheEnabled: boolean;
  protected cacheDuration: number;
  protected cache: Map<string, { data: any; timestamp: number }>;
  protected abortControllers: Map<string, AbortController>;

  constructor(config: ProfessionalServiceConfig = {}) {
    this.baseURL = config.baseURL || '/api';
    this.timeout = config.timeout || 30000;
    this.retries = config.retries || 3;
    this.cacheEnabled = config.cacheEnabled !== false;
    this.cacheDuration = config.cacheDuration || 5 * 60 * 1000;
    this.cache = new Map();
    this.abortControllers = new Map();
  }

  protected getCacheKey(endpoint: string, params?: any): string {
    return `${endpoint}:${params ? JSON.stringify(params) : ''}`;
  }

  protected getFromCache(key: string): any | null {
    if (!this.cacheEnabled) return null;

    const cached = this.cache.get(key);
    if (!cached) return null;

    const now = Date.now();
    if (now - cached.timestamp > this.cacheDuration) {
      this.cache.delete(key);
      return null;
    }

    return cached.data;
  }

  protected setCache(key: string, data: any): void {
    if (!this.cacheEnabled) return;

    this.cache.set(key, {
      data,
      timestamp: Date.now(),
    });
  }

  protected clearCache(): void {
    this.cache.clear();
  }

  protected clearCacheByPattern(pattern: string): void {
    const keysToDelete: string[] = [];
    this.cache.forEach((_, key) => {
      if (key.includes(pattern)) {
        keysToDelete.push(key);
      }
    });
    keysToDelete.forEach(key => this.cache.delete(key));
  }

  protected async fetchWithTimeout(
    url: string,
    options: RequestInit = {},
    timeout: number = this.timeout,
  ): Promise<Response> {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeout);

    try {
      const response = await fetch(url, {
        ...options,
        signal: controller.signal,
      });
      return response;
    } finally {
      clearTimeout(timeoutId);
    }
  }

  protected async request<T>(
    endpoint: string,
    options: RequestInit = {},
    useCache = true,
    cacheKey?: string,
  ): Promise<T> {
    const key = cacheKey || this.getCacheKey(endpoint, options.body);

    if (useCache && (options.method === 'GET' || !options.method)) {
      const cached = this.getFromCache(key);
      if (cached) {
        return cached as T;
      }
    }

    const url = `${this.baseURL}${endpoint}`;
    const requestOptions: RequestInit = {
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    };

    let lastError: Error | null = null;

    for (let attempt = 0; attempt < this.retries; attempt++) {
      try {
        const response = await this.fetchWithTimeout(url, requestOptions);

        if (!response.ok) {
          const errorData: ErrorResponse = await response.json().catch(() => ({
            error: 'Unknown error',
            message: response.statusText,
            status: response.status,
          }));

          throw new Error(errorData.message || `HTTP ${response.status}`);
        }

        const data: ApiResponse<T> = await response.json();

        if (useCache && (options.method === 'GET' || !options.method)) {
          this.setCache(key, data);
        }

        // 兼容两种响应格式：
        // 1. 有 data 包装的 ApiResponse<T> → 返回 data
        // 2. 直接返回数据的响应（无 data 包装）→ 返回原始数据
        const d = data as unknown as Record<string, unknown>; return d.data !== undefined ? d.data as unknown as T : data as T;
      } catch (error) {
        lastError = error as Error;

        if (error instanceof Error && error.name === 'AbortError') {
          throw new Error('Request timeout');
        }

        if (attempt < this.retries - 1) {
          await this.delay(Math.pow(2, attempt) * 1000);
        }
      }
    }

    throw lastError || new Error('Request failed');
  }

  protected async get<T>(endpoint: string, params?: any, useCache = true): Promise<T> {
    const queryString = params ? '?' + new URLSearchParams(params).toString() : '';
    return this.request<T>(`${endpoint}${queryString}`, {
      method: 'GET',
    }, useCache);
  }

  protected async post<T>(endpoint: string, data: any, useCache = false): Promise<T> {
    return this.request<T>(endpoint, {
      method: 'POST',
      body: JSON.stringify(data),
    }, useCache);
  }

  protected async put<T>(endpoint: string, data: any, useCache = false): Promise<T> {
    return this.request<T>(endpoint, {
      method: 'PUT',
      body: JSON.stringify(data),
    }, useCache);
  }

  protected async delete<T>(endpoint: string, useCache = false): Promise<T> {
    return this.request<T>(endpoint, {
      method: 'DELETE',
    }, useCache);
  }

  protected async patch<T>(endpoint: string, data: any, useCache = false): Promise<T> {
    return this.request<T>(endpoint, {
      method: 'PATCH',
      body: JSON.stringify(data),
    }, useCache);
  }

  protected async upload<T>(
    endpoint: string,
    file: File | Blob,
    additionalData?: Record<string, string>,
    onProgress?: (progress: number) => void,
  ): Promise<T> {
    const formData = new FormData();
    formData.append('file', file);

    if (additionalData) {
      Object.entries(additionalData).forEach(([key, value]) => {
        formData.append(key, value);
      });
    }

    return new Promise((resolve, reject) => {
      const xhr = new XMLHttpRequest();

      if (onProgress) {
        xhr.upload.onprogress = (event) => {
          if (event.lengthComputable) {
            const progress = (event.loaded / event.total) * 100;
            onProgress(progress);
          }
        };
      }

      xhr.onload = () => {
        if (xhr.status >= 200 && xhr.status < 300) {
          try {
            const response = JSON.parse(xhr.responseText);
            resolve(response.data);
          } catch {
            resolve(xhr.responseText as unknown as T);
          }
        } else {
          reject(new Error(`Upload failed: ${xhr.statusText}`));
        }
      };

      xhr.onerror = () => {
        reject(new Error('Network error'));
      };

      xhr.open('POST', `${this.baseURL}${endpoint}`);
      xhr.send(formData);
    });
  }

  protected cancelRequest(key: string): void {
    const controller = this.abortControllers.get(key);
    if (controller) {
      controller.abort();
      this.abortControllers.delete(key);
    }
  }

  protected cancelAllRequests(): void {
    this.abortControllers.forEach((controller) => {
      controller.abort();
    });
    this.abortControllers.clear();
  }

  protected delay(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  protected validateResponse<T>(data: any): T {
    if (!data || typeof data !== 'object') {
      throw new Error('Invalid response data');
    }
    return data as T;
  }

  protected formatError(error: any): Error {
    if (error instanceof Error) {
      return error;
    }

    if (typeof error === 'string') {
      return new Error(error);
    }

    if (error?.message) {
      return new Error(error.message);
    }

    return new Error('Unknown error occurred');
  }

  protected async retryWithBackoff<T>(
    fn: () => Promise<T>,
    maxRetries = 3,
    baseDelay = 1000,
  ): Promise<T> {
    let lastError: Error | null = null;

    for (let attempt = 0; attempt < maxRetries; attempt++) {
      try {
        return await fn();
      } catch (error) {
        lastError = this.formatError(error);

        if (attempt < maxRetries - 1) {
          const delay = baseDelay * Math.pow(2, attempt);
          await this.delay(delay);
        }
      }
    }

    throw lastError;
  }

  protected getCacheStats(): { size: number; keys: string[] } {
    return {
      size: this.cache.size,
      keys: Array.from(this.cache.keys()),
    };
  }

  protected optimizeCache(maxSize = 100): void {
    if (this.cache.size > maxSize) {
      const entries = Array.from(this.cache.entries());
      entries.sort((a, b) => a[1].timestamp - b[1].timestamp);

      const toDelete = entries.slice(0, entries.length - maxSize);
      toDelete.forEach(([key]) => this.cache.delete(key));
    }
  }
}

export default ProfessionalBaseService;

export interface ChemistryDescriptor {
  atomCount: number;
  bondCount: number;
  ringCount: number;
  aromaticRings: number;
  molecularWeight: number;
  logP: number;
  hbd: number;
  hba: number;
  tpsa: number;
  rotatableBonds: number;
  complexity: number;
  charge: number;
  isotopeCount: number;
}

export interface AtomInfo {
  symbol: string;
  atomicNumber: number;
  valence: number;
  electronegativity: number;
  mass: number;
  position: { x: number; y: number };
}

export interface BondInfo {
  atom1: number;
  atom2: number;
  order: number;
  type: 'single' | 'double' | 'triple' | 'aromatic';
}

export class ChemistryUtils {
  private static ATOM_WEIGHTS: Record<string, number> = {
    H: 1.008,
    C: 12.011,
    N: 14.007,
    O: 15.999,
    P: 30.974,
    S: 32.065,
    F: 18.998,
    Cl: 35.453,
    Br: 79.904,
    I: 126.904,
    B: 10.81,
    Si: 28.086,
  };

  private static VALENCE: Record<string, number> = {
    H: 1,
    C: 4,
    N: 3,
    O: 2,
    P: 5,
    S: 6,
    F: 1,
    Cl: 1,
    Br: 1,
    I: 1,
    B: 3,
    Si: 4,
  };

  private static ELECTRONEGATIVITY: Record<string, number> = {
    H: 2.20,
    C: 2.55,
    N: 3.04,
    O: 3.44,
    P: 2.19,
    S: 2.58,
    F: 3.98,
    Cl: 3.16,
    Br: 2.96,
    I: 2.66,
    B: 2.04,
    Si: 1.90,
  };

  public static parseSMILES(smiles: string): {
    atoms: AtomInfo[];
    bonds: BondInfo[];
  } {
    const atoms: AtomInfo[] = [];
    const bonds: BondInfo[] = [];
    const organicSubset = ['B', 'C', 'N', 'O', 'P', 'S', 'F', 'Cl', 'Br', 'I'];

    const position = { x: 0, y: 0 };
    let atomIndex = 0;
    let bondOrder = 1;
    let previousAtomIndex = -1;

    for (let i = 0; i < smiles.length; i++) {
      const char = smiles[i];

      if (char === ' ') continue;

      if (char === '(' || char === ')') {
        continue;
      }

      if (char === '-') {
        bondOrder = 1;
        continue;
      }
      if (char === '=') {
        bondOrder = 2;
        continue;
      }
      if (char === '#') {
        bondOrder = 3;
        continue;
      }

      if (char === '[') {
        const closeBracket = smiles.indexOf(']', i);
        if (closeBracket !== -1) {
          const atomSymbol = smiles.substring(i + 1, closeBracket);
          if (atomSymbol in this.ATOM_WEIGHTS) {
            const atom: AtomInfo = {
              symbol: atomSymbol,
              atomicNumber: this.getAtomicNumber(atomSymbol),
              valence: this.VALENCE[atomSymbol] || 4,
              electronegativity: this.ELECTRONEGATIVITY[atomSymbol] || 2.5,
              mass: this.ATOM_WEIGHTS[atomSymbol] || 12.0,
              position: { ...position },
            };
            atoms.push(atom);

            if (previousAtomIndex !== -1) {
              bonds.push({
                atom1: previousAtomIndex,
                atom2: atomIndex,
                order: bondOrder,
                type: this.getBondType(bondOrder),
              });
            }

            previousAtomIndex = atomIndex;
            atomIndex++;
            bondOrder = 1;
          }
          i = closeBracket;
          position.x += 30;
        }
        continue;
      }

      if (organicSubset.includes(char)) {
        let symbol = char;
        if (char === 'C' && smiles[i + 1] === 'l') {
          symbol = 'Cl';
          i++;
        } else if (char === 'B' && smiles[i + 1] === 'r') {
          symbol = 'Br';
          i++;
        } else if (char === 'C' && smiles[i + 1] === 'a') {
          symbol = 'Ca';
          i++;
        } else if (char === 'M' && smiles[i + 1] === 'g') {
          symbol = 'Mg';
          i++;
        }

        if (symbol in this.ATOM_WEIGHTS) {
          const atom: AtomInfo = {
            symbol,
            atomicNumber: this.getAtomicNumber(symbol),
            valence: this.VALENCE[symbol] || 4,
            electronegativity: this.ELECTRONEGATIVITY[symbol] || 2.5,
            mass: this.ATOM_WEIGHTS[symbol] || 12.0,
            position: { ...position },
          };
          atoms.push(atom);

          if (previousAtomIndex !== -1) {
            bonds.push({
              atom1: previousAtomIndex,
              atom2: atomIndex,
              order: bondOrder,
              type: this.getBondType(bondOrder),
            });
          }

          previousAtomIndex = atomIndex;
          atomIndex++;
          bondOrder = 1;
          position.x += 30;

          if (position.x > 300) {
            position.x = 0;
            position.y += 40;
          }
        }
      }
    }

    return { atoms, bonds };
  }

  private static getAtomicNumber(symbol: string): number {
    const atomicNumbers: Record<string, number> = {
      H: 1, He: 2, B: 5, C: 6, N: 7, O: 8, F: 9,
      Ne: 10, Na: 11, Mg: 12, Si: 14, P: 15, S: 16,
      Cl: 17, Ar: 18, Ca: 20, Br: 35, I: 53,
    };
    return atomicNumbers[symbol] || 6;
  }

  private static getBondType(order: number): 'single' | 'double' | 'triple' | 'aromatic' {
    switch (order) {
      case 1:
        return 'single';
      case 2:
        return 'double';
      case 3:
        return 'triple';
      default:
        return 'single';
    }
  }

  public static calculateDescriptors(smiles: string): ChemistryDescriptor {
    const { atoms, bonds } = this.parseSMILES(smiles);

    let molecularWeight = 0;
    let totalElectronegativity = 0;
    const charge = 0;

    atoms.forEach((atom) => {
      molecularWeight += atom.mass;
      totalElectronegativity += atom.electronegativity;
    });

    const uniqueSymbols = new Set(atoms.map((a) => a.symbol));
    const atomCounts: Record<string, number> = {};
    uniqueSymbols.forEach((symbol) => {
      atomCounts[symbol] = atoms.filter((a) => a.symbol === symbol).length;
    });

    let hbd = 0;
    let hba = 0;
    if ('O' in atomCounts) {
      hba += atomCounts.O;
      hbd += Math.min(atomCounts.O, Math.floor(atomCounts.H / 2));
    }
    if ('N' in atomCounts) {
      hba += atomCounts.N;
      hbd += atomCounts.N;
    }

    let rotatableBonds = 0;
    bonds.forEach((bond) => {
      if (bond.type === 'single') {
        rotatableBonds++;
      }
    });

    const complexity = this.calculateComplexity(atoms.length, bonds.length);
    const tpsa = this.calculateTPSA(atoms);

    const logP = this.estimateLogP(atomCounts, bonds.length);

    return {
      atomCount: atoms.length,
      bondCount: bonds.length,
      ringCount: 0,
      aromaticRings: 0,
      molecularWeight,
      logP,
      hbd,
      hba,
      tpsa,
      rotatableBonds,
      complexity,
      charge,
      isotopeCount: 0,
    };
  }

  private static calculateComplexity(atomCount: number, bondCount: number): number {
    return Math.sqrt(atomCount * bondCount) * (atomCount + bondCount) * 0.1;
  }

  private static calculateTPSA(atoms: AtomInfo[]): number {
    const polarAtoms = atoms.filter((a) =>
      ['N', 'O', 'P', 'S'].includes(a.symbol),
    );

    return polarAtoms.length * 12.5 + 10;
  }

  private static estimateLogP(atomCounts: Record<string, number>, bondCount: number): number {
    let logP = 0;

    if ('C' in atomCounts) {
      logP += atomCounts.C * 0.25;
    }
    if ('H' in atomCounts) {
      logP -= atomCounts.H * 0.05;
    }
    if ('O' in atomCounts) {
      logP -= atomCounts.O * 0.5;
    }
    if ('N' in atomCounts) {
      logP -= atomCounts.N * 0.4;
    }
    if ('F' in atomCounts) {
      logP += atomCounts.F * 0.4;
    }
    if ('Cl' in atomCounts) {
      logP += atomCounts.Cl * 0.8;
    }
    if ('Br' in atomCounts) {
      logP += atomCounts.Br * 1.0;
    }
    if ('I' in atomCounts) {
      logP += atomCounts.I * 1.3;
    }

    logP += bondCount * 0.1;

    return logP;
  }

  public static generateSVG(
    smiles: string,
    width = 400,
    height = 300,
  ): string {
    const { atoms, bonds } = this.parseSMILES(smiles);

    if (atoms.length === 0) {
      return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}">
        <rect width="${width}" height="${height}" fill="#f0f0f0"/>
        <text x="${width / 2}" y="${height / 2}" text-anchor="middle" fill="#666">Invalid SMILES</text>
      </svg>`;
    }

    let svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">`;

    svg += `<rect width="${width}" height="${height}" fill="#ffffff"/>`;

    const minX = Math.min(...atoms.map((a) => a.position.x));
    const maxX = Math.max(...atoms.map((a) => a.position.x));
    const minY = Math.min(...atoms.map((a) => a.position.y));
    const maxY = Math.max(...atoms.map((a) => a.position.y));

    const padding = 40;
    const scaleX = (width - 2 * padding) / (maxX - minX || 1);
    const scaleY = (height - 2 * padding) / (maxY - minY || 1);
    const scale = Math.min(scaleX, scaleY);

    const offsetX = (width - (maxX - minX) * scale) / 2 - minX * scale;
    const offsetY = (height - (maxY - minY) * scale) / 2 - minY * scale;

    const transformPoint = (p: { x: number; y: number }) => ({
      x: p.x * scale + offsetX,
      y: p.y * scale + offsetY,
    });

    bonds.forEach((bond) => {
      const atom1 = atoms[bond.atom1];
      const atom2 = atoms[bond.atom2];
      if (atom1 && atom2) {
        const p1 = transformPoint(atom1.position);
        const p2 = transformPoint(atom2.position);

        svg += `<line x1="${p1.x}" y1="${p1.y}" x2="${p2.x}" y2="${p2.y}" `;
        svg += `stroke="#333" stroke-width="2"/>`;
      }
    });

    const atomRadius = Math.max(8, Math.min(15, 200 / atoms.length));

    atoms.forEach((atom) => {
      const p = transformPoint(atom.position);
      const color = this.getAtomColor(atom.symbol);

      svg += `<circle cx="${p.x}" cy="${p.y}" r="${atomRadius}" fill="${color}" stroke="#333" stroke-width="1.5"/>`;

      svg += `<text x="${p.x}" y="${p.y + atomRadius + 15}" text-anchor="middle" font-size="11" fill="#333" font-weight="bold">${atom.symbol}</text>`;
    });

    svg += '</svg>';
    return svg;
  }

  private static getAtomColor(symbol: string): string {
    const colors: Record<string, string> = {
      C: '#909090',
      H: '#ffffff',
      N: '#3050F8',
      O: '#FF0D0D',
      P: '#FF8000',
      S: '#FFFF30',
      F: '#90E050',
      Cl: '#1FF01F',
      Br: '#A62929',
      I: '#940094',
      B: '#FFB5B5',
      Si: '#F0C8A0',
    };
    return colors[symbol] || '#FF99CC';
  }

  public static isDrugLike(descriptors: ChemistryDescriptor): boolean {
    const MW_UPPER = 500;
    const LOGP_UPPER = 5;
    const HBD_UPPER = 5;
    const HBA_UPPER = 10;
    const TPSA_UPPER = 140;

    return (
      descriptors.molecularWeight <= MW_UPPER &&
      descriptors.logP <= LOGP_UPPER &&
      descriptors.hbd <= HBD_UPPER &&
      descriptors.hba <= HBA_UPPER &&
      descriptors.tpsa <= TPSA_UPPER &&
      descriptors.rotatableBonds <= 10
    );
  }

  public static calculateSimilarity(
    smiles1: string,
    smiles2: string,
  ): number {
    const desc1 = this.calculateDescriptors(smiles1);
    const desc2 = this.calculateDescriptors(smiles2);

    const mwDiff = Math.abs(desc1.molecularWeight - desc2.molecularWeight) /
                   Math.max(desc1.molecularWeight, desc2.molecularWeight, 1);
    const logPDiff = Math.abs(desc1.logP - desc2.logP) / 5;
    const hbdDiff = Math.abs(desc1.hbd - desc2.hbd) / 5;
    const hbaDiff = Math.abs(desc1.hba - desc2.hba) / 10;

    const similarity = 1 - (mwDiff + logPDiff + hbdDiff + hbaDiff) / 4;
    return Math.max(0, Math.min(1, similarity));
  }
}

export default ChemistryUtils;

import { ProfessionalBaseService } from './ProfessionalBaseService';
import type { ProfessionalServiceConfig } from '../../types/professional';
import {
  CompatibilityRule,
  CompatibilityGroup,
  XIANGSHENG,
  COMPATIBILITY_GROUPS,
  getCompatibilityRulesByHerb,
  checkCompatibility,
} from '../../data/compatibilityKnowledge';
import { checkCompatibilityBatch, getHerbConflicts } from '../../data/compatibilityKnowledge';

export interface CompatibilityCheckResult {
  compatible: boolean;
  conflicts: CompatibilityRule[];
  warnings: CompatibilityRule[];
  suggestions: CompatibilitySuggestion[];
  summary: string;
}

export interface CompatibilitySuggestion {
  id: string;
  type: 'avoid' | 'caution' | 'recommend';
  herb1: string;
  herb2: string;
  description: string;
  alternative?: string;
}

export interface CompatibilityReport {
  herbs: string[];
  result: CompatibilityCheckResult;
  timestamp: number;
}

export interface HerbCompatibilityInfo {
  herbName: string;
  opposites: string[];
  fears: string[];
  enhances: string[];
  compatibleHerbs: string[];
  incompatibleHerbs: string[];
}

class CompatibilityService extends ProfessionalBaseService {
  private mockMode = true;

  constructor(config: ProfessionalServiceConfig = {}) {
    super({
      ...config,
      baseURL: config.baseURL || 'https://api.compatibility.rmfood.com',
      cacheDuration: 60 * 60 * 1000,
    });
  }

  public enableMockMode(enable: boolean): void {
    this.mockMode = enable;
  }

  public async checkHerbCompatibility(herbs: string[]): Promise<CompatibilityCheckResult> {
    const cacheKey = this.getCacheKey('/compatibility/check', herbs.sort());
    const cached = this.getFromCache(cacheKey);
    if (cached) return cached;

    if (this.mockMode) {
      return this.mockCheckCompatibility(herbs);
    }

    const result = await this.post<CompatibilityCheckResult>('/api/compatibility/check', { herbs });
    this.setCache(cacheKey, result);
    return result;
  }

  private mockCheckCompatibility(herbs: string[]): CompatibilityCheckResult {
    const conflicts = checkCompatibilityBatch(herbs);

    const highSeverityConflicts = conflicts.filter((c) => c.severity === 'high');
    const mediumSeverityConflicts = conflicts.filter((c) => c.severity === 'medium');

    const suggestions: CompatibilitySuggestion[] = [];

    for (const conflict of highSeverityConflicts) {
      suggestions.push({
        id: `avoid_${conflict.id}`,
        type: 'avoid',
        herb1: conflict.herb1,
        herb2: conflict.herb2,
        description: conflict.description,
        alternative: this.getAlternativeHerb(conflict),
      });
    }

    for (const conflict of mediumSeverityConflicts) {
      suggestions.push({
        id: `caution_${conflict.id}`,
        type: 'caution',
        herb1: conflict.herb1,
        herb2: conflict.herb2,
        description: conflict.description,
      });
    }

    for (let i = 0; i < herbs.length; i++) {
      for (let j = i + 1; j < herbs.length; j++) {
        const enhanceRule = this.findEnhanceRule(herbs[i], herbs[j]);
        if (enhanceRule) {
          suggestions.push({
            id: `recommend_${enhanceRule.id}`,
            type: 'recommend',
            herb1: enhanceRule.herb1,
            herb2: enhanceRule.herb2,
            description: enhanceRule.reason,
          });
        }
      }
    }

    const summary = this.generateSummary(herbs, conflicts, suggestions);

    return {
      compatible: conflicts.length === 0,
      conflicts: highSeverityConflicts,
      warnings: mediumSeverityConflicts,
      suggestions,
      summary,
    };
  }

  private findEnhanceRule(herb1: string, herb2: string): CompatibilityRule | null {
    for (const rule of XIANGSHENG.rules) {
      if ((rule.herb1 === herb1 && rule.herb2 === herb2) || (rule.herb1 === herb2 && rule.herb2 === herb1)) {
        return rule;
      }
    }
    return null;
  }

  private getAlternativeHerb(conflict: CompatibilityRule): string | undefined {
    const alternatives: Record<string, string> = {
      甘遂: '大戟',
      大戟: '甘遂',
      芫花: '大戟',
      海藻: '昆布',
      半夏: '陈皮',
      瓜蒌: '贝母',
      贝母: '瓜蒌',
      白蔹: '白及',
      白及: '白蔹',
      人参: '党参',
      沙参: '麦冬',
      丹参: '川芎',
      玄参: '生地',
      苦参: '黄连',
      细辛: '白芷',
      芍药: '当归',
    };
    return alternatives[conflict.herb1] || alternatives[conflict.herb2];
  }

  private generateSummary(
    herbs: string[],
    conflicts: CompatibilityRule[],
    suggestions: CompatibilitySuggestion[],
  ): string {
    if (conflicts.length === 0) {
      if (suggestions.some((s) => s.type === 'recommend')) {
        return `${herbs.join('、')}配伍合理，具有协同增效作用。`;
      }
      return `${herbs.join('、')}配伍安全，未发现明显禁忌。`;
    }

    const highConflicts = conflicts.filter((c) => c.severity === 'high');
    const mediumConflicts = conflicts.filter((c) => c.severity === 'medium');

    let summary = '';
    if (highConflicts.length > 0) {
      summary += `${herbs.join('、')}存在配伍禁忌：`;
      summary += highConflicts.map((c) => c.description).join('；');
    }
    if (mediumConflicts.length > 0) {
      if (summary) summary += '；';
      summary += `需注意：${mediumConflicts.map((c) => c.description).join('；')}`;
    }

    return summary;
  }

  public async getHerbCompatibilityInfo(herbName: string): Promise<HerbCompatibilityInfo> {
    const cacheKey = `/compatibility/herb/${herbName}`;
    const cached = this.getFromCache(cacheKey);
    if (cached) return cached;

    if (this.mockMode) {
      const { opposites, fears, enhances } = getHerbConflicts(herbName);
      const result: HerbCompatibilityInfo = {
        herbName,
        opposites,
        fears,
        enhances,
        compatibleHerbs: enhances,
        incompatibleHerbs: [...opposites, ...fears],
      };
      this.setCache(cacheKey, result);
      return result;
    }

    const result = await this.get<HerbCompatibilityInfo>(`/api/compatibility/herb/${encodeURIComponent(herbName)}`);
    this.setCache(cacheKey, result);
    return result;
  }

  public async getAllCompatibilityGroups(): Promise<CompatibilityGroup[]> {
    const cacheKey = '/compatibility/groups';
    const cached = this.getFromCache(cacheKey);
    if (cached) return cached;

    if (this.mockMode) {
      this.setCache(cacheKey, COMPATIBILITY_GROUPS);
      return COMPATIBILITY_GROUPS;
    }

    const result = await this.get<CompatibilityGroup[]>('/api/compatibility/groups');
    this.setCache(cacheKey, result);
    return result;
  }

  public async getCompatibilityRulesByHerb(herbName: string): Promise<CompatibilityRule[]> {
    const cacheKey = `/compatibility/rules/${herbName}`;
    const cached = this.getFromCache(cacheKey);
    if (cached) return cached;

    if (this.mockMode) {
      const rules = getCompatibilityRulesByHerb(herbName);
      this.setCache(cacheKey, rules);
      return rules;
    }

    const result = await this.get<CompatibilityRule[]>(`/api/compatibility/rules/${encodeURIComponent(herbName)}`);
    this.setCache(cacheKey, result);
    return result;
  }

  public async checkTwoHerbs(herb1: string, herb2: string): Promise<CompatibilityRule | null> {
    const cacheKey = `/compatibility/check/${herb1}/${herb2}`;
    const cached = this.getFromCache(cacheKey);
    if (cached !== undefined) return cached;

    if (this.mockMode) {
      const rule = checkCompatibility(herb1, herb2);
      this.setCache(cacheKey, rule);
      return rule;
    }

    const result = await this.get<CompatibilityRule | null>(
      `/api/compatibility/check/${encodeURIComponent(herb1)}/${encodeURIComponent(herb2)}`,
    );
    this.setCache(cacheKey, result);
    return result;
  }

  public async getCompatibilityReport(herbs: string[]): Promise<CompatibilityReport> {
    const result = await this.checkHerbCompatibility(herbs);
    return {
      herbs,
      result,
      timestamp: Date.now(),
    };
  }

  public async getRecommendedCombinations(herbName: string): Promise<CompatibilitySuggestion[]> {
    const cacheKey = `/compatibility/recommendations/${herbName}`;
    const cached = this.getFromCache(cacheKey);
    if (cached) return cached;

    if (this.mockMode) {
      const { enhances } = getHerbConflicts(herbName);
      const suggestions: CompatibilitySuggestion[] = [];

      for (const enhanceHerb of enhances) {
        const rule = this.findEnhanceRule(herbName, enhanceHerb);
        if (rule) {
          suggestions.push({
            id: `recommend_${rule.id}`,
            type: 'recommend',
            herb1: herbName,
            herb2: enhanceHerb,
            description: rule.reason,
          });
        }
      }

      this.setCache(cacheKey, suggestions);
      return suggestions;
    }

    const result = await this.get<CompatibilitySuggestion[]>(
      `/api/compatibility/recommendations/${encodeURIComponent(herbName)}`,
    );
    this.setCache(cacheKey, result);
    return result;
  }

  public async validateFormula(formula: string[]): Promise<{
    isValid: boolean;
    issues: {
      type: 'error' | 'warning' | 'info';
      message: string;
      herbs: string[];
    }[];
  }> {
    if (this.mockMode) {
      const conflicts = checkCompatibilityBatch(formula);
      const issues: {
        type: 'error' | 'warning' | 'info';
        message: string;
        herbs: string[];
      }[] = [];

      for (const conflict of conflicts) {
        issues.push({
          type: conflict.severity === 'high' ? 'error' : 'warning',
          message: conflict.description,
          herbs: [conflict.herb1, conflict.herb2],
        });
      }

      return {
        isValid: conflicts.length === 0,
        issues,
      };
    }

    return this.post<{ isValid: boolean; issues: any[] }>('/api/compatibility/validate', { formula });
  }

  public clearCompatibilityCache(): void {
    this.clearCache();
  }

  public getServiceInfo(): {
    mockMode: boolean;
    cachedItems: number;
    totalRules: number;
  } {
    let totalRules = 0;
    for (const group of COMPATIBILITY_GROUPS) {
      totalRules += group.rules.length;
    }

    return {
      mockMode: this.mockMode,
      cachedItems: this.getCacheStats().size,
      totalRules,
    };
  }
}

