    const warnings = ingredients.filter((i) => !approvedHerbs.includes(i));

    return {
      valid: warnings.length === 0,
      results,
      warnings: warnings.map((i) => `成分 ${i} 未在已知法规目录中找到`),
      errors: [],
      summary: {
