  /**
   * 导出学术报告为PDF（使用HTML渲染解决中文乱码）
   */
  async exportToPDF(
    candidate: AICandidate,
    effects: string[],
    options: ReportExportOptions = {},
    onProgress?: (progress: ExportProgress) => void,
  ): Promise<Blob> {
    const { filename = '配方学术报告.pdf' } = options

    try {
      onProgress?.({
        stage: 'preparing',
        message: '正在准备报告数据...',
        percent: 10,
      })

      // 1. 创建HTML模板
      const htmlContent = this.createPrintableHTML({ candidate, effects })

      onProgress?.({
        stage: 'rendering',
        message: '正在渲染报告内容...',
        percent: 30,
      })

      // 2. 创建隐藏的iframe来渲染HTML
      const iframe = document.createElement('iframe')
      iframe.style.cssText = 'position:absolute;width:800px;height:1200px;left:-9999px;top:-9999px;'
      document.body.appendChild(iframe)

      const iframeDoc = iframe.contentDocument || iframe.contentWindow?.document
      if (!iframeDoc) {
        throw new Error('无法创建iframe文档')
      }

      iframeDoc.open()
      iframeDoc.write(htmlContent)
      iframeDoc.close()

      // 等待字体加载
      await new Promise(resolve => setTimeout(resolve, 500))

      // 3. 获取报告容器并渲染为canvas
      const reportElement = iframeDoc.getElementById('report-content')
      if (!reportElement) {
        throw new Error('无法获取报告内容元素')
      }

      onProgress?.({
        stage: 'generating',
        message: '正在生成PDF文件...',
        percent: 60,
      })

      const canvas = await html2canvas(reportElement, {
        scale: 2,
        useCORS: true,
        allowTaint: true,
        backgroundColor: '#ffffff',
        width: 800,
        height: reportElement.scrollHeight + 40,
      })

      // 清理iframe
      document.body.removeChild(iframe)

      onProgress?.({
        stage: 'generating',
        message: '正在处理PDF...',
        percent: 80,
      })

      // 4. 创建PDF并添加图片
      const pdf = new jsPDF({
        orientation: 'portrait',
        unit: 'mm',
        format: 'a4',
      })

      const pageWidth = pdf.internal.pageSize.getWidth()
      const pageHeight = pdf.internal.pageSize.getHeight()
      const imgWidth = pageWidth
      const imgHeight = (canvas.height * imgWidth) / canvas.width

      // 如果内容超过一页，需要分页
      let heightLeft = imgHeight
      let position = 0

      const imgData = canvas.toDataURL('image/jpeg', 0.95)

      // 添加第一页
      pdf.addImage(imgData, 'JPEG', 0, position, imgWidth, imgHeight)
      heightLeft -= pageHeight

      // 如果内容超过一页，添加更多页面
      while (heightLeft > 0) {
        position = heightLeft - imgHeight
        pdf.addPage()
        pdf.addImage(imgData, 'JPEG', 0, position, imgWidth, imgHeight)
        heightLeft -= pageHeight
      }

      // 添加页脚
      const totalPages = pdf.getNumberOfPages()
      for (let i = 1; i <= totalPages; i++) {
        pdf.setPage(i)
        pdf.setFontSize(8)
        pdf.setTextColor(156, 163, 175)
        pdf.text(
          '本报告由 AI 配方生成系统自动生成，仅供参考。具体使用请遵医嘱或咨询专业人士。',
          pageWidth / 2,
          pageHeight - 8,
          { align: 'center' },
        )
        pdf.text(
          `第 ${i} 页 / 共 ${totalPages} 页`,
          pageWidth - 15,
          pageHeight - 8,
          { align: 'right' },
        )
      }

      onProgress?.({
        stage: 'complete',
        message: '导出完成！',
        percent: 100,
      })

      return new Blob([pdf.output('arraybuffer')], { type: 'application/pdf' })
    } catch (error) {
      onProgress?.({
        stage: 'error',
        message: error instanceof Error ? error.message : '导出失败',
        percent: 0,
      })
      throw error
    }
  }

  /**
   * 下载PDF文件
   */
  downloadPDF(blob: Blob, filename: string): void {
    const url = URL.createObjectURL(blob)
    const link = document.createElement('a')
    link.href = url
    link.download = filename
    document.body.appendChild(link)
    link.click()
    document.body.removeChild(link)
    URL.revokeObjectURL(url)
  }
}

