/**
 * 搜索服务 - 使用Fuse.js实现全文搜索
 *
 * 支持：
 * 1. 按时间检索
 * 2. 按主题筛选
 * 3. 按标签筛选
 * 4. 全文搜索（模糊匹配）
 * 5. 快速选择和复用
 */

import Fuse, { type IFuseOptions as FuseOptions } from 'fuse.js';
import type { SearchResultItem, SearchFilters, SearchHistoryItem, SearchSuggestion, SearchConfig } from '@/types/search.types';
import type { Formula, Experiment, TCMHerb, BioactivePeptide, KnowledgeNode } from '@/types';

// 默认搜索配置
const DEFAULT_CONFIG: SearchConfig = {
  enabledTypes: ['formula', 'experiment', 'herb', 'peptide', 'knowledge'],
  defaultSortBy: 'relevance',
  defaultSortOrder: 'desc',
  maxResults: 50,
  minSearchLength: 2,
  debounceDelay: 300,
  fuzzyMatch: true,
};

// Fuse.js 配置
const FUSE_OPTIONS: FuseOptions<SearchResultItem> = {
  includeScore: true,
  includeMatches: true,
  threshold: 0.3,
  distance: 100,
  minMatchCharLength: 2,
  keys: ['title', 'subtitle', 'description', 'tags', 'category'],
};

// 存储搜索历史的键
const SEARCH_HISTORY_KEY = 'rmfood_search_history';
const MAX_HISTORY_SIZE = 20;

// 搜索索引缓存
let fuseIndex: Fuse<SearchResultItem> | null = null;
let indexedData: SearchResultItem[] = [];

export class SearchService {
  private config: SearchConfig;

  constructor(config: Partial<SearchConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * 初始化搜索索引
   */
  initializeIndex(data: SearchResultItem[]): void {
    indexedData = data;
    fuseIndex = new Fuse(data, FUSE_OPTIONS);
  }

  /**
   * 从多种数据源构建搜索索引
   */
  buildIndexFromSources({
    formulas = [],
    experiments = [],
    herbs = [],
    peptides = [],
    knowledgeNodes = [],
  }: {
    formulas?: Formula[];
    experiments?: Experiment[];
    herbs?: TCMHerb[];
    peptides?: BioactivePeptide[];
    knowledgeNodes?: KnowledgeNode[];
  }): void {
    const items: SearchResultItem[] = [];

    // 配方
    formulas.forEach((f) => {
      items.push({
        id: f.id,
        type: 'formula',
        title: f.name,
        subtitle: f.description,
        description: f.description,
        tags: f.tags ?? [],
        category: f.category?.toString() || '',
        createdAt: f.createdAt,
        updatedAt: f.updatedAt,
      });
    });

    // 实验
    experiments.forEach((e) => {
      items.push({
        id: e.id,
        type: 'experiment',
        title: e.title,
        subtitle: e.description,
        description: e.description,
        tags: [],
        category: e.type.toString(),
        createdAt: e.createdAt,
        updatedAt: e.updatedAt,
      });
    });

    // 中药
    herbs.forEach((h) => {
      items.push({
        id: h.id,
        type: 'herb',
        title: h.name,
        subtitle: h.latinName || h.pinyinName,
        description: h.efficacy,
        tags: [h.nature || '', h.meridian || ''].filter(Boolean),
        category: h.category || '',
        createdAt: h.createdAt,
        updatedAt: h.updatedAt,
      });
    });

    // 肽
    peptides.forEach((p) => {
      items.push({
        id: p.id,
        type: 'peptide',
        title: p.sequence,
        subtitle: p.name || p.source,
        description: p.mechanismOfAction,
        tags: p.activityTypes || [],
        category: '',
        createdAt: p.createdAt,
        updatedAt: p.updatedAt,
      });
    });

    // 知识节点
    knowledgeNodes.forEach((k) => {
      items.push({
        id: k.id,
        type: 'knowledge',
        title: k.title,
        subtitle: k.type,
        description: k.content,
        tags: k.tags || [],
        category: k.type,
        createdAt: k.createdAt,
        updatedAt: k.updatedAt,
      });
    });

    this.initializeIndex(items);
  }

  /**
   * 执行搜索
   */
  search(filters: SearchFilters): SearchResultItem[] {
    if (!fuseIndex) {
      return [];
    }

    let results: SearchResultItem[] = [];
    const { keyword, types, tags, category, dateRange, sortBy, sortOrder } = filters;

    // 如果有关键词，执行全文搜索
    if (keyword && keyword.length >= this.config.minSearchLength) {
      const fuseResults = fuseIndex.search(keyword);
      results = fuseResults.map((r) => ({
        ...r.item,
        relevance: r.score ? 1 - r.score : 1,
      }));
    } else if (!keyword) {
      // 没有关键词，返回所有数据
      results = [...indexedData];
    }

    // 按类型筛选
    if (types && types.length > 0) {
      results = results.filter((item) => types.includes(item.type));
    }

    // 按分类筛选
    if (category) {
      results = results.filter((item) => item.category === category);
    }

    // 按标签筛选
    if (tags && tags.length > 0) {
      results = results.filter((item) =>
        tags.some((tag) => item.tags.some((t) => t.toLowerCase().includes(tag.toLowerCase()))),
      );
    }

    // 按时间范围筛选
    if (dateRange) {
      const startDate = new Date(dateRange.start);
      const endDate = new Date(dateRange.end);
      results = results.filter((item) => {
        const createdAt = new Date(item.createdAt);
        return createdAt >= startDate && createdAt <= endDate;
      });
    }

    // 排序
    results = this.sortResults(results, sortBy || this.config.defaultSortBy, sortOrder || this.config.defaultSortOrder);

    // 限制数量
    return results.slice(0, this.config.maxResults);
  }

  /**
   * 排序结果
   */
  private sortResults(
    results: SearchResultItem[],
    sortBy: 'relevance' | 'createdAt' | 'updatedAt',
    sortOrder: 'asc' | 'desc',
  ): SearchResultItem[] {
    return [...results].sort((a, b) => {
      let comparison = 0;

      switch (sortBy) {
        case 'relevance':
          comparison = (b.relevance || 0) - (a.relevance || 0);
          break;
        case 'createdAt':
          comparison = new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
          break;
        case 'updatedAt':
          const aUpdated = a.updatedAt ? new Date(a.updatedAt).getTime() : 0;
          const bUpdated = b.updatedAt ? new Date(b.updatedAt).getTime() : 0;
          comparison = bUpdated - aUpdated;
          break;
      }

      return sortOrder === 'desc' ? comparison : -comparison;
    });
  }

  /**
   * 获取搜索建议
   */
  getSuggestions(query: string, limit = 8): SearchSuggestion[] {
    if (!fuseIndex || !query || query.length < 2) {
      return [];
    }

    const results = fuseIndex.search(query, { limit });
    const seen = new Set<string>();

    return results
      .filter((r) => {
        const key = `${r.item.type}-${r.item.title}`;
        if (seen.has(key)) return false;
        seen.add(key);
        return true;
      })
      .map((r) => ({
        id: r.item.id,
        text: r.item.title,
        hint: r.item.subtitle,
        type: r.item.type,
        category: r.item.category,
      }))
      .slice(0, limit);
  }

  /**
   * 保存搜索历史
   */
  saveSearchHistory(query: string, filters?: Partial<SearchFilters>, resultCount?: number): void {
    const history = this.getSearchHistory();
    const newItem: SearchHistoryItem = {
      id: Date.now().toString(),
      query,
      timestamp: new Date().toISOString(),
      filters,
      resultCount,
    };

    // 移除重复的查询
    const filtered = history.filter((h) => h.query !== query);
    filtered.unshift(newItem);

    // 限制历史记录数量
    const trimmed = filtered.slice(0, MAX_HISTORY_SIZE);

    localStorage.setItem(SEARCH_HISTORY_KEY, JSON.stringify(trimmed));
  }

  /**
   * 获取搜索历史
   */
  getSearchHistory(): SearchHistoryItem[] {
    try {
      const data = localStorage.getItem(SEARCH_HISTORY_KEY);
      return data ? JSON.parse(data) : [];
    } catch {
      return [];
    }
  }

  /**
   * 清除搜索历史
   */
  clearSearchHistory(): void {
    localStorage.removeItem(SEARCH_HISTORY_KEY);
  }

  /**
   * 删除单条搜索历史
   */
  removeSearchHistory(id: string): void {
    const history = this.getSearchHistory();
    const filtered = history.filter((h) => h.id !== id);
    localStorage.setItem(SEARCH_HISTORY_KEY, JSON.stringify(filtered));
  }

  /**
   * 获取热门搜索词
   */
  getPopularSearches(limit = 10): SearchHistoryItem[] {
    const history = this.getSearchHistory();

    // 统计搜索词频率
    const frequency: Record<string, { count: number; lastUsed: string; filters?: Partial<SearchFilters> }> = {};

    history.forEach((item) => {
      if (!frequency[item.query]) {
        frequency[item.query] = { count: 0, lastUsed: item.timestamp, filters: item.filters };
      }
      frequency[item.query].count++;
      if (item.timestamp > frequency[item.query].lastUsed) {
        frequency[item.query].lastUsed = item.timestamp;
      }
    });

    // 按频率和时间排序
    return Object.entries(frequency)
      .map(([query, data]) => ({
        id: data.lastUsed,
        query,
        timestamp: data.lastUsed,
        filters: data.filters,
        count: data.count,
      }))
      .sort((a, b) => {
        if (b.count !== a.count) return b.count - a.count;
        return new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime();
      })
      .map(({ count, ...rest }) => rest) // 移除临时 count
      .slice(0, limit);
  }

  /**
   * 检查索引是否已初始化
   */
  isIndexReady(): boolean {
    return fuseIndex !== null;
  }

  /**
   * 获取索引数据统计
   */
  getIndexStats(): { total: number; byType: Record<string, number> } {
    const byType: Record<string, number> = {};

    indexedData.forEach((item) => {
      byType[item.type] = (byType[item.type] || 0) + 1;
    });

    return {
      total: indexedData.length,
      byType,
    };
  }
}

// 创建单例实例
export const searchService = new SearchService();

export default SearchService;

/**
 * WebSocket 客户端服务
 * - 管理WebSocket连接
 * - 实现自动重连
 * - 处理实时数据同步
 * - 提供消息订阅机制
 * - 支持消息批量处理和防抖优化
 */

import { useAuthStore } from '@/stores/auth'
import { logger } from '@/utils/safeLogger'


export interface WebSocketMessage {
  type: string
  data: Record<string, unknown>
  timestamp: string
  channel?: string
  [key: string]: unknown
}

interface WebSocketOptions {
  url: string
  autoReconnect?: boolean
  reconnectInterval?: number
  maxReconnectAttempts?: number
  batchProcessing?: boolean
  batchInterval?: number
}

export type MessageHandler = (message: WebSocketMessage) => void
export type BatchMessageHandler = (messages: WebSocketMessage[]) => void

interface ChannelSubscription {
  channel: string
  handler: MessageHandler
}

export class WebSocketService {
  private ws: WebSocket | null = null
  private url: string
  private autoReconnect: boolean
  private maxReconnectAttempts: number
  private reconnectAttempts = 0
  private isConnecting = false
  private isConnected = false
  private messageHandlers: MessageHandler[] = []
  private batchMessageHandlers: BatchMessageHandler[] = []
  private channelSubscriptions: ChannelSubscription[] = []
  private heartbeatInterval: ReturnType<typeof setInterval> | null = null
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null
  private batchTimer: ReturnType<typeof setTimeout> | null = null
  private messageBuffer: WebSocketMessage[] = []
  private connectionId: string
  private lastHeartbeat = 0
  private _lastErrorLogTime = 0  // 错误日志去重时间戳
  private _consecutiveFailures = 0  // 连续失败计数
  private _backendUnreachable = false  // 后端不可达标记
  private static readonly MAX_CONSECUTIVE_FAILURES = 5  // 一个完整重连周期即判定后端不可达
  private stats: { messagesSent: number; bytesSent: number; messagesReceived: number } = {
    messagesSent: 0,
    bytesSent: 0,
    messagesReceived: 0,
  }
  private batchProcessing: boolean
  private batchInterval: number
  private eventHandlers = new Map<string, Set<(data?: Record<string, unknown>) => void>>()

  constructor(options: WebSocketOptions) {
    this.url = options.url
    this.autoReconnect = options.autoReconnect ?? true
    this.maxReconnectAttempts = options.maxReconnectAttempts ?? 5
    this.batchProcessing = options.batchProcessing ?? true
    this.batchInterval = options.batchInterval ?? 100
    this.connectionId = `conn_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`
  }

  get getLastHeartbeat(): number {
    return this.lastHeartbeat
  }

  connect(): Promise<boolean> {
    return new Promise((resolve) => {
      if (this.isConnecting || this.isConnected) {
        resolve(this.isConnected)
        return
      }

      // 后端已标记为不可达 → 直接返回，不再尝试连接
      if (this._backendUnreachable) {
        resolve(false)
        return
      }

      // 预检：sessionStorage 中记录的后端不可达状态（跨 HMR 生效）
      const STORAGE_KEY = 'ws_backend_unreachable_until'
      const storedUntil = sessionStorage.getItem(STORAGE_KEY)
      if (storedUntil && Number(storedUntil) > Date.now()) {
        this._backendUnreachable = true
        resolve(false)
        return
      }

      this.isConnecting = true

      try {
        // 🔒 P0 安全修复: Token 存储在 HttpOnly Cookie 中，前端无法直接读取
        // WebSocket 连接时浏览器会自动携带同源 Cookie，后端可通过 Cookie 认证
        // 不再通过 URL query param 传递 token（更安全）
        const authState = useAuthStore.getState()
        const isAuthenticated = authState?.isAuthenticated

        if (!isAuthenticated) {
          logger.warn('WebSocket: 用户未认证，跳过连接')
          this.isConnecting = false
          resolve(false)
          return
        }

        const url = `${this.url}?connection_id=${this.connectionId}&client_info=${encodeURIComponent(JSON.stringify({
          userAgent: navigator.userAgent,
          screenSize: `${window.screen.width}x${window.screen.height}`,
          timestamp: new Date().toISOString(),
        }))}`

        this.ws = new WebSocket(url)

        this.ws.onopen = () => {
          logger.info('WebSocket: Connected')
          this.isConnected = true
          this.isConnecting = false
          this.reconnectAttempts = 0
          this._consecutiveFailures = 0  // 重置连续失败计数
          this._backendUnreachable = false  // 重置不可达标记
          sessionStorage.removeItem('ws_backend_unreachable_until')  // 清除持久化标记
          this.startHeartbeat()
          // 发送连接成功事件
          this.emit('connected', {})
          resolve(true)
        }

        this.ws.onmessage = (event) => {
          try {
            const message = JSON.parse(event.data) as WebSocketMessage
            this.handleMessage(message)
          } catch (error) {
            logger.error('WebSocket: Error parsing message', { error })
            // 发送解析错误事件
            this.emit('error', { type: 'parse_error', error })
          }
        }

        this.ws.onclose = (event) => {
          logger.info(`WebSocket: Disconnected (code: ${event.code}, reason: ${event.reason})`)
          this.isConnected = false
          this.isConnecting = false
          this.stopHeartbeat()
          // 发送断开连接事件
          this.emit('disconnected', { code: event.code, reason: event.reason })
          if (this.autoReconnect) {
            // 只在非正常关闭时重连
            if (event.code !== 1000) { // 1000 = Normal Closure
              this.scheduleReconnect()
            }
          }
        }

        this.ws.onerror = (error) => {
          this._consecutiveFailures++

          // 连续失败达到阈值 → 标记后端不可达，停止所有重连
          if (this._consecutiveFailures >= WebSocketService.MAX_CONSECUTIVE_FAILURES && !this._backendUnreachable) {
            this._backendUnreachable = true
            // 持久化到 sessionStorage，跨 HMR 生效（5 分钟有效期）
            const STORAGE_KEY = 'ws_backend_unreachable_until'
            sessionStorage.setItem(STORAGE_KEY, String(Date.now() + 5 * 60 * 1000))
            logger.warn(`WebSocket: 后端不可达（连续 ${this._consecutiveFailures} 次失败），已自动禁用重连。如需恢复请刷新页面或配置 VITE_WEBSOCKET_ENABLED=true`)
            this.emit('backend_unreachable', { consecutiveFailures: this._consecutiveFailures })
          }

          // 去重：同一重连周期内只记录一次错误，避免控制台刷屏
          const now = Date.now()
          if (!this._lastErrorLogTime || now - this._lastErrorLogTime > 10000) {
            this._lastErrorLogTime = now
            const errorInfo = {
              type: error.type,
              message: 'WebSocket error',
              attempt: this.reconnectAttempts,
              maxAttempts: this.maxReconnectAttempts,
              consecutiveFailures: this._consecutiveFailures,
            }
            logger.error('WebSocket: Error', errorInfo)
          }
          // 发送错误事件
          this.emit('error', { type: 'connection_error', error: { type: error.type, message: 'WebSocket error' } })
          this.isConnecting = false
          resolve(false)
        }

      } catch (error) {
        this._consecutiveFailures++

        if (this._consecutiveFailures >= WebSocketService.MAX_CONSECUTIVE_FAILURES && !this._backendUnreachable) {
          this._backendUnreachable = true
          const STORAGE_KEY = 'ws_backend_unreachable_until'
          sessionStorage.setItem(STORAGE_KEY, String(Date.now() + 5 * 60 * 1000))
          logger.warn(`WebSocket: 后端不可达（连续 ${this._consecutiveFailures} 次失败），已自动禁用重连`)
        }

        // 提取错误信息，避免直接传递Error对象
        const errorInfo = {
          message: error instanceof Error ? error.message : String(error),
          stack: error instanceof Error ? error.stack : undefined,
        }
        logger.error('WebSocket: Connection error', errorInfo)
        // 发送连接错误事件
        this.emit('error', { type: 'connection_error', error: errorInfo })
        this.isConnecting = false
        resolve(false)
      }
    })
  }

  disconnect() {
    this.autoReconnect = false
    this.stopHeartbeat()

    // 清理批量处理定时器
    if (this.batchTimer) {
      clearTimeout(this.batchTimer)
      this.batchTimer = null
    }

    // 清理重连定时器
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer)
    }

    // 清理消息缓冲区
    this.messageBuffer = []

    // 关闭WebSocket连接
    if (this.ws) {
      this.ws.close()
      this.ws = null
    }

    this.isConnected = false
    this.isConnecting = false
  }

  private scheduleReconnect() {
    // 后端不可达 → 不再调度重连
    if (this._backendUnreachable) {
      return
    }

    if (this.reconnectAttempts >= this.maxReconnectAttempts) {
      logger.error('WebSocket: Max reconnect attempts reached')
      this.emit('reconnect_failed', {
        attempts: this.reconnectAttempts,
        maxAttempts: this.maxReconnectAttempts,
      })
      return
    }

    // 指数退避策略：1s, 2s, 4s, 8s, 16s, 30s
    const baseDelay = 1000
    const maxDelay = 30000
    const delay = Math.min(maxDelay, baseDelay * Math.pow(2, this.reconnectAttempts)) + Math.random() * 1000

    logger.info(`WebSocket: Scheduling reconnect in ${Math.round(delay)}ms (attempt ${this.reconnectAttempts + 1}/${this.maxReconnectAttempts})`)

    // 发送重连尝试事件
    this.emit('reconnect_attempt', {
      attempt: this.reconnectAttempts + 1,
      maxAttempts: this.maxReconnectAttempts,
      delay: Math.round(delay),
    })

    this.reconnectTimer = setTimeout(() => {
      this.reconnectAttempts++
      this.connect().then((connected) => {
        if (connected) {
          logger.info('WebSocket: Reconnect successful')
          this.emit('reconnect_success', {})
        } else {
          logger.warn('WebSocket: Reconnect failed, scheduling next attempt')
        }
      })
    }, delay)
  }

  private startHeartbeat() {
    this.heartbeatInterval = setInterval(() => {
      if (this.isConnected && this.ws) {
        try {
          this.ws.send(JSON.stringify({
            type: 'ping',
            timestamp: Date.now(),
          }))
        } catch (error) {
          logger.error('WebSocket: Error sending heartbeat', { error })
        }
      }
    }, 30000)
  }

  private stopHeartbeat() {
    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval)
      this.heartbeatInterval = null
    }
  }

  private handleMessage(message: WebSocketMessage) {
    this.stats.messagesReceived++

    // 处理心跳响应（不参与批量处理）
    if (message.type === 'pong') {
      this.lastHeartbeat = Date.now()
      this.emit('heartbeat', { timestamp: message.timestamp })
      return
    }

    // 处理连接建立（不参与批量处理）
    if (message.type === 'connection_established') {
      logger.info('WebSocket: Connection established', message)
      this.emit('connection_established', message.data)
      return
    }

    // 处理错误消息（不参与批量处理）
    if (message.type === 'error') {
      logger.error('WebSocket: Server error', message.data)
      this.emit('error', { type: 'server_error', error: message.data })
      return
    }

    // 如果启用批量处理，将消息加入缓冲区
    if (this.batchProcessing) {
      this.messageBuffer.push(message)
      this.scheduleBatchProcessing()
    } else {
      // 立即处理消息
      this.processMessageImmediately(message)
    }
  }

  private scheduleBatchProcessing() {
    if (this.batchTimer) return

    this.batchTimer = setTimeout(() => {
      this.flushMessageBuffer()
    }, this.batchInterval)
  }

  private flushMessageBuffer() {
    if (this.messageBuffer.length === 0) {
      this.batchTimer = null
      return
    }

    const messages = [...this.messageBuffer]
    this.messageBuffer = []
    this.batchTimer = null

    // 调用批量消息处理器
    this.batchMessageHandlers.forEach(handler => {
      try {
        handler(messages)
      } catch (error) {
        logger.error('WebSocket: Error in batch message handler', { error })
      }
    })

    // 单独处理每条消息
    messages.forEach(message => {
      this.processMessageImmediately(message)
    })
  }

  private processMessageImmediately(message: WebSocketMessage) {
    // 处理用户状态更新
    if (message.type === 'user_status') {
      logger.info('WebSocket: User status update', message)
      this.emit('user_status', message.data)
    }

    // 处理数据更新
    if (message.type === 'data_update') {
      logger.info('WebSocket: Data update', message)
      this.emit('data_update', message.data)
    }

    // 处理特定频道的消息
    if (message.channel) {
      this.emit(message.channel, message.data)
    }

    // 调用所有消息处理器
    this.messageHandlers.forEach(handler => {
      try {
        handler(message)
      } catch (error) {
        logger.error('WebSocket: Error in message handler', { error })
      }
    })

    // 调用频道订阅处理器
    this.channelSubscriptions.forEach(subscription => {
      if (this.messageMatchesChannel(message, subscription.channel)) {
        try {
          subscription.handler(message)
        } catch (error) {
          logger.error('WebSocket: Error in channel handler', { error })
        }
      }
    })
  }

  private messageMatchesChannel(message: WebSocketMessage, channel: string): boolean {
    // 实现频道匹配逻辑
    if (channel === '*') return true
    if (channel === message.type) return true
    if (message.type === 'data_update' && message.data?.entity_type === channel) return true
    return false
  }

  send(message: Record<string, unknown>): boolean {
    if (!this.isConnected || !this.ws) {
      logger.warn('WebSocket: Not connected, cannot send message')
      this.emit('send_failed', { message, error: 'Not connected' })
      return false
    }

    try {
      const messageStr = JSON.stringify(message)
      this.ws.send(messageStr)
      // 记录发送的消息
      this.stats.messagesSent++
      this.stats.bytesSent += messageStr.length
      return true
    } catch (error) {
      logger.error('WebSocket: Error sending message', { error })
      this.emit('send_failed', { message, error })
      // 尝试重新连接
      if (!this.isConnecting) {
        this.scheduleReconnect()
      }
      return false
    }
  }

  onMessage(handler: MessageHandler): () => void {
    this.messageHandlers.push(handler)
    return () => {
      this.messageHandlers = this.messageHandlers.filter(h => h !== handler)
    }
  }

  onBatchMessage(handler: BatchMessageHandler): () => void {
    this.batchMessageHandlers.push(handler)
    return () => {
      this.batchMessageHandlers = this.batchMessageHandlers.filter(h => h !== handler)
    }
  }

  subscribe(channel: string, handler: MessageHandler): () => void {
    const subscription: ChannelSubscription = { channel, handler }
    this.channelSubscriptions.push(subscription)
    return () => {
      this.channelSubscriptions = this.channelSubscriptions.filter(
        sub => sub.channel !== channel || sub.handler !== handler,
      )
    }
  }

  unsubscribe(channel: string) {
    this.channelSubscriptions = this.channelSubscriptions.filter(
      sub => sub.channel !== channel,
    )
  }

  getIsConnected(): boolean {
    return this.isConnected
  }

  getConnectionId(): string {
    return this.connectionId
  }

  on(event: string, handler: (data?: Record<string, unknown>) => void): () => void {
    // 事件订阅（EventEmitter 语义）：emit(event, data) 时调用所有对应 handler
    if (!this.eventHandlers.has(event)) {
      this.eventHandlers.set(event, new Set())
    }
    const handlers = this.eventHandlers.get(event)!
    handlers.add(handler)
    return () => {
      handlers.delete(handler)
      if (handlers.size === 0) {
        this.eventHandlers.delete(event)
      }
    }
  }

  private emit(event: string, data?: Record<string, unknown>) {
    // 事件分发：遍历该事件的全部 handler（拷贝 Set 避免回调中增删导致迭代器失效）
    const handlers = this.eventHandlers.get(event)
    if (!handlers || handlers.size === 0) {
      logger.info(`WebSocket event: ${event}`, data)
      return
    }
    handlers.forEach(handler => {
      try {
        handler(data)
      } catch (error) {
        logger.error(`WebSocket event handler error for "${event}":`, error)
      }
    })
  }
}

/**
 * 检查是否应该启用 WebSocket
 * 默认禁用 — 需要显式配置 VITE_WEBSOCKET_ENABLED=true 才启用
 */
const shouldEnableWebSocket = (): boolean => {
  const wsEnabled = import.meta.env.VITE_WEBSOCKET_ENABLED || import.meta.env.VITE_ENABLE_WEBSOCKET
  // 只有显式设置为 true/1 才启用，其他所有情况（未配置/false/其他值）均禁用
  return wsEnabled === 'true' || wsEnabled === '1'
}

/**
 * 创建一个降级的 WebSocket 服务（不实际连接）
 */
class NoOpWebSocketService {
  connect(): Promise<boolean> {
    logger.info('WebSocket: WebSocket is disabled, using no-op service')
    return Promise.resolve(false)
  }

  disconnect() {}

  send(): boolean {
    logger.warn('WebSocket: WebSocket is disabled, cannot send message')
    return false
  }

  onMessage(): () => void {
    return () => {}
  }

  onBatchMessage(): () => void {
    return () => {}
  }

  subscribe(): () => void {
    return () => {}
  }

  unsubscribe() {}

  getIsConnected(): boolean {
    return false
  }

  getConnectionId(): string {
    return 'no-op'
  }

  on(): () => void {
    // 降级模式：订阅无实际事件源，返回空取消函数
    return () => {}
  }
}

export const isWebSocketEnabled = shouldEnableWebSocket()

// 创建全局WebSocket服务实例 — 从 VITE_BACKEND_URL 动态推导 WS 地址
const _backendUrl = (import.meta.env.VITE_BACKEND_URL || 'http://localhost:8000').replace(/^https?/, 'ws')
const wsUrl = import.meta.env.VITE_WS_URL || `${_backendUrl}/api/v1/ws`

export const wsService = shouldEnableWebSocket()
  ? new WebSocketService({
      url: wsUrl,
      autoReconnect: true,
      reconnectInterval: 1000,
      maxReconnectAttempts: 5,
      batchProcessing: true,
      batchInterval: 100,
    })
  : new NoOpWebSocketService() as unknown as WebSocketService

// 导出便捷方法
export const connectWebSocket = async () => {
  return await wsService.connect()
}

export const disconnectWebSocket = () => {
  wsService.disconnect()
}

export const sendWebSocketMessage = (message: any) => {
  return wsService.send(message)
}

export const onWebSocketMessage = (handler: MessageHandler) => {
  return wsService.onMessage(handler)
}

export const subscribeToChannel = (channel: string, handler: MessageHandler) => {
  return wsService.subscribe(channel, handler)
}

export const unsubscribeFromChannel = (channel: string) => {
  wsService.unsubscribe(channel)
}

