 */
import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';

// 通过 vi.hoisted 在 vi.mock 工厂中共享 mock 函数
const mocks = vi.hoisted(() => ({
  clientGet: vi.fn(),
