    getMe: vi.fn(),
    refresh: vi.fn(),
  },
}));

// 登录流程中的 getMe 走的是集中式 axios client（@/api/client），而非 authApi.getMe，
// 因此必须 mock client 才能让登录用例在无网络环境下通过。
vi.mock('@/api/client', () => ({
  default: {
    get: mocks.clientGet,
    post: mocks.clientPost,
    put: mocks.clientPut,
    delete: mocks.clientDelete,
  },
}));

vi.mock('@/services/websocket', () => ({
