    });
    const light = css.slice(css.indexOf(':root {')).split('\n}')[0];
    // base.css:72 accent=700 / :73 rgb=139,92,246（500）/ :74 hover=600 / :75 container=100
    expect(light).toContain('--color-accent: #6d28d9;');
