interface UIState {
  theme: 'dark' | 'light';
  primaryColor: string;
  locale: 'zh-CN' | 'en-US';
  collapsed: boolean; // 侧边栏是否折叠
  tableDensity: 'comfortable' | 'compact'; // 表格密度
  // 列表筛选条件记忆
  filters: { [pageKey: string]: any };
  // 列可见性配置
  columnVisibility: { [tableName: string]: { [col: string]: boolean } };

  // 操作方法
  setTheme: (theme: 'dark' | 'light') => void;
  toggleTheme: () => void;
  setPrimaryColor: (color: string) => void;
  setLocale: (locale: 'zh-CN' | 'en-US') => void;
  toggleSidebar: () => void;
  setTableDensity: (density: 'comfortable' | 'compact') => void;
  setFilter: (key: string, value: any) => void;
  removeFilter: (key: string) => void;
  clearAllFilters: () => void;
  setColumnVisibility: (table: string, column: string, visible: boolean) => void;
  resetUI: () => void;
}

export const useUIStore = create<UIState>()(
  persist(
    (set, get) => ({
      theme: 'dark',
      primaryColor: '#1677ff',
      locale: 'zh-CN',
      collapsed: false,
      tableDensity: 'comfortable',
      filters: {},
      columnVisibility: {},

      setTheme: (theme) => set({ theme }),
      toggleTheme: () => set({ theme: get().theme === 'dark' ? 'light' : 'dark' }),
      setPrimaryColor: (color) => set({ primaryColor: color }),
      setLocale: (locale) => set({ locale }),
      toggleSidebar: () => set({ collapsed: !get().collapsed }),
      setTableDensity: (density) => set({ tableDensity: density }),

      // 筛选条件
      setFilter: (key, value) => {
        const filters = { ...get().filters, [key]: value };
        set({ filters });
      },
      removeFilter: (key) => {
        const { [key]: _removed, ...rest } = get().filters;
        void _removed;
        set({ filters: rest });
      },
      clearAllFilters: () => set({ filters: {} }),

      // 列可见性
      setColumnVisibility: (table, column, visible) => {
        set((state) => ({
          columnVisibility: {
            ...state.columnVisibility,
            [table]: {
              ...state.columnVisibility[table],
              [column]: visible,
            },
          },
        }));
      },

      resetUI: () =>
        set({
          theme: 'dark',
          primaryColor: '#1677ff',
          locale: 'zh-CN',
          collapsed: false,
          tableDensity: 'comfortable',
          filters: {},
          columnVisibility: {},
        }),
    }),
    {
      name: 'rmfood:ui',
      storage: createJSONStorage(() => localStorage),
    },
  ),
);

