// ==================== 注意事项 ====================

/**
 * 注意事项严重程度
 */
export type PrecautionSeverity = 'low' | 'medium' | 'high' | 'critical';

/**
 * 注意事项类型分类（扩展版）
 */
export type PrecautionCategory =
  | 'contraindication' // 禁忌症
  | 'warning' // 警告/慎用
  | 'dosage' // 用量注意
  | 'interaction' // 药物相互作用
  | 'pregnancy' // 孕期相关
  | 'allergy' // 过敏风险
  | 'special_pop'; // 特殊人群

/**
 * 触发条件接口
 * 定义注意事项的触发条件，用于智能提示系统
 */
export interface TriggerCondition {
  /** 条件类型 */
  type: 'age_range' | 'condition' | 'dosage_exceed' | 'combination' | 'duration';
  /** 条件描述 */
  description: string;
  /** 条件值（根据type不同而不同） */
  value: string | number | { min?: number; max?: number };
  /** 是否为硬性限制 */
  isHardLimit: boolean;
}

/**
 * 成分使用注意事项（扩展版）
 * 记录成分在使用过程中需要特别关注的安全信息
 *
 * @example
 * ```ts
 * const precaution: Precaution = {
 *   category: 'contraindication',
 *   content: '孕妇禁用',
 *   severity: 'high',
 *   triggerConditions: [{
 *     type: 'condition',
 *     description: '妊娠期',
 *     value: 'pregnant',
 *     isHardLimit: true
 *   }]
 * }
 * ```
 */
export interface Precaution {
  /** 注意事项分类 */
  category: PrecautionCategory;
  /** 注意事项具体内容 */
  content: string;
  /** 严重程度 */
  severity: PrecautionSeverity;
  /** 触发条件列表（可选） */
  triggerConditions?: TriggerCondition[];
  /** 参考来源（可选） */
  reference?: string;
  /** 建议措施（可选） */
  recommendation?: string;
}

// ==================== 来源分类 ====================

/**
 * 成分来源分类枚举
 * 标识成分的来源类别，用于配方归类与分析
 */
export enum IngredientSource {
  /** 药食同源 - 中药材及药食同源物质 */
  TCM = 'TCM',
  /** 食源性多肽 - 通过酶解等技术制备的功能性多肽 */
  PEPTIDE = 'PEPTIDE',
  /** 辅料 - 赋形剂、稳定剂等辅助材料 */
  EXCIPIENT = 'EXCIPIENT',
}

// ==================== 剂量计算 ====================

/**
 * 剂量计算结果接口
 * 用于存储和传递剂量换算的计算结果
 */
export interface DosageCalculationResult {
  /** 原始值 */
  originalValue: number;
  /** 原始单位 */
  originalUnit: string;
  /** 转换后值 */
  convertedValue: number;
  /** 转换后单位 */
  convertedUnit: string;
  /** 换算系数 */
  conversionFactor: number;
  /** 计算时间戳 */
  calculatedAt: Date;
}

// ==================== 核心成分 ====================

/**
 * 配方成分接口（扩展版）
 * 描述配方中单一成分的完整属性信息
 *
 * @example
 * ```ts
 * const ingredient: Ingredient = {
 *   name: '人参',
 *   latinName: 'Panax ginseng',
 *   amount: 500,
 *   unit: 'g',
 *   percentage: 25,
 *   efficacyTags: ['补气养血', '增强免疫', '抗疲劳'],
 *   precautions: [{ category: 'warning', content: '高血压患者慎用', severity: 'medium' }],
 *   source: IngredientSource.TCM,
 *   qualityScore: 85,
 *   sourceDatabase: 'TCMSP'
 * }
 * ```
 */
export interface Ingredient {
  /** 中文名称 */
  name: string;
  /** 拉丁学名（可选） */
  latinName?: string;
  /** 用量数值 */
  amount: number;
  /** 单位（g/ml 等） */
  unit: string;
  /** 在配方中的占比百分比（0-100，可选） */
  percentage?: number;
  /** 功效标签数组（可选） */
  efficacyTags?: EfficacyTag[];
  /** 注意事项数组（可选） */
  precautions?: Precaution[];
  /** 来源分类 */
  source: IngredientSource;
  /** 质量评分 (0-100，可选) */
  qualityScore?: number;
  /** 数据来源数据库（可选） */
  sourceDatabase?: string;
  /** 成分角色（可选，如主药/辅药/佐使） */
  role?: string;
}

/**
 * 增强型成分接口
 * 在基础成分信息之上，提供更丰富的分析数据
 */
export interface EnhancedIngredient extends Ingredient {
  /** 成分唯一ID */
  id: string;
  /** 化学成分列表 */
  activeCompounds?: string[];
  /** 药理作用机制 */
  mechanismOfAction?: string;
  /** 生物利用度 (%) */
  bioavailability?: number;
  /** 半衰期信息 */
  halfLife?: string;
  /** 相互作用成分列表 */
  interactions?: string[];
  /** 临床研究数量 */
  clinicalStudiesCount?: number;
  /** 推荐日用量范围 */
  recommendedDosage?: { min: number; max: number; unit: string };
  /** 毒性等级 */
  toxicityLevel?: 'safe' | 'low' | 'moderate' | 'high';
}

