  /** 单位（可选） */
  unit?: string;
  /** 功效说明（可选） */
  efficacy?: string;
  /** 备注信息（可选） */
  notes?: string;
}

/**
 * AI识别后的完整配方数据
 * 用于存储从AI对话中识别出的配方信息，包含元数据和原始解析结果
 *
 * @example
 * ```ts
 * const recognizedFormula: AIRecognizedFormula = {
 *   id: 'FMT-1a2b3c-xyz123',
 *   name: '气血双补配方',
 *   ingredientCount: 5,
 *   confidence: 0.92,
 *   sourceMessageId: 'msg_001',
 *   parsedAt: new Date(),
 *   rawData: formulaTableData,
 *   ingredients: [
 *     { name: '人参', dosage: '500', unit: 'g' },
 *     { name: '黄芪', dosage: '300', unit: 'g' }
 *   ]
 * }
 * ```
 */
export interface AIRecognizedFormula {
  /** 唯一标识符 (基于名称哈希 + 时间戳生成) */
  id: string;
  /** 配方名称 */
  name: string;
  /** 成分数量统计 */
  ingredientCount: number;
  /** 置信度评分 (0-1，越高表示识别越准确) */
  confidence: number;
  /** 来源消息ID (标识该配方来自哪条AI回复) */
  sourceMessageId: string;
  /** 解析识别的时间戳 */
  parsedAt: Date;
  /** 原始解析数据 (完整的表格数据结构) */
  rawData: FormulaTableData;
  /** 结构化的成分列表 */
  ingredients: RecognizedFormulaIngredient[];

  // ===== 新增字段 (v8.0 增强版) =====

  /** 自动生成的语义化名称（由formulaNamingEngine生成） */
  autoName?: string;

  /** 配方质量综合评分 (0-100) */
  qualityScore?: number;

  /** 质量等级 (A/B/C/D/F) */
  qualityGrade?: 'A' | 'B' | 'C' | 'D' | 'F';

  /** 功效标签数组（自动提取或手动添加） */
  tags?: string[];

  /** 功效描述文本 */
  efficacy?: string;

  /** 适用人群标签 */
  targetAudience?: string[];

  /** 推荐剂量范围 */
  recommendedDosage?: string;

  /** 禁忌症/注意事项 */
  contraindications?: string;

  /** 用户自定义备注 */
  userNotes?: string;

  /** 是否已收藏 */
  isFavorite?: boolean;

  /** 创建时间戳 */
  createdAt?: number;

  /** 最后更新时间戳 */
  updatedAt?: number;

  /** 版本号（用于版本追踪） */
  version?: number;

  /** 原始文本内容（用于命名引擎提取关键词） */
  content?: string;

  /** 扩展元数据（功效、来源等） */
  metadata?: Record<string, unknown>;
}

/**
 * 配方索引类型
 * 使用Map结构存储和管理多个识别后的配方，以配方ID为键
 * 支持快速查找、更新和删除操作
 *
 * @example
 * ```ts
 * const formulaIndex: FormulaIndex = new Map()
 * formulaIndex.set(recognizedFormula.id, recognizedFormula)
 * const formula = formulaIndex.get('FMT-1a2b3c-xyz123')
 * ```
 */
export type FormulaIndex = Map<string, AIRecognizedFormula>;

// ==================== v8.0 新增：质量评分与筛选类型 ====================

/**
 * 配方质量评分详情
 * 提供多维度的配方质量评估结果
 *
 * @example
 * ```ts
 * const score: FormulaQualityScore = {
 *   overallScore: 85,
 *   confidenceScore: 92,
 *   completenessScore: 78,
 *   diversityScore: 85,
 *   qualityGrade: 'B',
 *   recommendations: ['建议补充成分信息', '可增加功效描述']
 * }
 * ```
 */
export interface FormulaQualityScore {
  /** 综合评分 (0-100) */
  overallScore: number;
  /** 置信度得分 (0-100) */
  confidenceScore: number;
  /** 完整性得分 (0-100) */
  completenessScore: number;
  /** 成分多样性得分 (0-100) */
  diversityScore: number;
  /** 质量等级 */
  qualityGrade: 'A' | 'B' | 'C' | 'D' | 'F';
  /** 改进建议列表 */
  recommendations: string[];
}

/**
 * 配方筛选条件
 * 用于高级搜索和过滤功能
 *
 * @example
 * ```ts
 * const filters: FormulaFilters = {
 *   keyword: '抗氧化',
 *   minConfidence: 0.8,
 *   grade: ['A', 'B'],
 *   tags: ['免疫调节'],
 *   minIngredients: 3
 * }
 * ```
 */
export interface FormulaFilters {
  /** 搜索关键词 */
  keyword?: string;

  /** 质量等级筛选（多选） */
  qualityGrades?: ('A' | 'B' | 'C' | 'D' | 'F')[];

  /** 置信度范围（百分比） */
  confidenceRange?: {
    min: number;
    max: number;
  };

  /** 时间范围 */
  dateRange?: {
    start: number;
    end: number;
  };

  /** 成分数量范围 */
  ingredientCountRange?: {
    min: number;
    max: number;
  };

  /** 标签筛选（多选） */
  tags?: string[];

  /** @deprecated 使用 confidenceRange 替代 */
  minConfidence?: number;
  /** @deprecated 使用 confidenceRange 替代 */
  maxConfidence?: number;
  /** @deprecated 使用 qualityGrades 替代 */
  grade?: ('A' | 'B' | 'C' | 'D' | 'F')[];
  /** @deprecated 使用 dateRange 替代 */
  dateFrom?: number;
  /** @deprecated 使用 dateRange 替代 */
  dateTo?: number;
  /** @deprecated 使用 ingredientCountRange 替代 */
  minIngredients?: number;
  /** @deprecated 使用 ingredientCountRange 替代 */
  maxIngredients?: number;
}

/**
 * 排序字段枚举
 * 定义可用的排序维度
 */
export type FormulaSortField = 'createdAt' | 'updatedAt' | 'name' | 'confidence' | 'qualityScore' | 'ingredientCount';

/**
 * 排序方向
 */
export type SortOrder = 'asc' | 'desc';

