  | 'general_inquiry' // 一般性询问
  | 'feedback_positive' // 正面反馈
  | 'feedback_negative' // 负面反馈
  | 'clarification' // 澄清/追问
  | 'topic_change' // 话题切换
  | 'farewell'; // 告别

