  | 'pregnancy_safety' // 孕期安全
  | 'efficacy_enhancement' // 功效增强
  | 'taste_optimization' // 口感优化
  | 'stability_improvement' // 稳定性改善
  | 'cost_reduction' // 成本降低
  | 'regulatory_compliance' // 法规合规
  | 'general'; // 通用

/**
 * 置信度级别
 * 用于标注意图识别的置信程度
 */
export type ConfidenceLevel = 'high' | 'medium' | 'low' | 'unknown';

/**
 * 意图检测结果
 * NLP 引擎输出的标准化结果结构
 */
export interface IntentDetectionResult {
  /** 主要意图 */
  primaryIntent: IntentType;
  /** 置信度分数 (0-1) */
  confidence: number;
  /** 子意图列表 */
  subIntents?: SubIntent[];
  /** 识别方法 ('rule-based' | 'semantic' | 'fallback') */
  method: string;
  /** 处理耗时 (ms) */
  processingTime?: number;
  /** 提取的实体列表 */
  entities?: {
    type: string;
    text: string;
    confidence: number;
    position?: [number, number];
  }[];
  /** 情感分析结果 */
  sentiment?: {
    sentiment: 'positive' | 'negative' | 'neutral';
    score: number;
  };
  /** 原始输入文本 */
  originalText?: string;
}

/**
 * 实体类型
 * 从用户输入中提取的结构化信息
 */
export interface Entity {
  /** 实体类型分类 */
  type: 'formula' | 'ingredient' | 'dosage' | 'regulation' | 'general';
  /** 实体值 */
  value: string;
  /** 置信度 (0-1) */
  confidence: number;
  /** 最后被提及的时间戳 */
  lastMentioned: number;
  /** 被提及次数 */
  mentionCount: number;
}

/**
 * 话题结构
 * 多轮对话管理器使用的话题定义
 */
export interface Topic {
  /** 话题唯一 ID */
  id: string;
  /** 话题标题 */
  title: string;
  /** 话题类型分类 */
  type: 'formula-design' | 'safety-review' | 'cost-analysis' | 'general-qna' | 'regulatory-query' | 'quality-control';
  /** 话题上下文 */
  context: TopicContext;
  /** 父话题 ID（用于嵌套话题） */
  parentTopicId?: string;
  /** 子话题 ID 列表 */
  childTopics: string[];
  /** 创建时间 */
  createdAt: number;
  /** 最后活跃时间 */
  lastActiveAt: number;
  /** 消息数量 */
  messageCount: number;
}

/**
 * 话题上下文
 */
export interface TopicContext {
  /** 主题关键词 */
  keywords: string[];
  /** 相关实体 */
  entities: string[];
  /** 话题摘要 */
  summary: string;
}

/**
 * 引用解析结果
 * 用于指代消解（"它"、"这个"等代词）
 */
export interface Reference {
  /** 原始代词文本 */
  originalText: string;
  /** 解析后的实际指向 */
  resolvedText: string;
  /** 解析的实体 ID */
  entityId?: string;
  /** 置信度 */
  confidence: number;
  /** 解析时间戳 */
  resolvedAt: number;
}

/**
 * 多轮对话处理结果
 */
export interface ProcessResult {
  /** 指代消解后的用户输入 */
  resolvedInput: string;
  /** 话题更新信息 */
  topicUpdate?: {
    topic: Topic;
    isTopicChange: boolean;
    previousTopic?: Topic;
  };
  /** 已解析的引用列表 */
  referencesResolved?: Reference[];
  /** 处理耗时 (ms) */
  processingTime: number;
}

