export function getChartTypeById(id: string): ChartTypeDefinition | undefined {
  return CHART_TYPE_DEFINITIONS.find(ct => ct.id === id);
}

export function getChartsByCategory(category: ChartCategory): ChartTypeDefinition[] {
  return CHART_TYPE_DEFINITIONS.filter(ct => ct.category === category);
}

export enum CollaborationPermission {
  VIEW = 'view',
  COMMENT = 'comment',
  EDIT = 'edit',
  ADMIN = 'admin'
}

export enum ShareAccessType {
  LINK = 'link',
  EMAIL = 'email',
  EMBED = 'embed'
}

export interface Collaborator {
  id: string;
  name: string;
  email: string;
  avatar?: string;
  permission: CollaborationPermission;
  joinedAt: string;
  lastActiveAt: string;
  isOnline: boolean;
  role?: string;
}

export interface Annotation {
  id: string;
  type: 'text' | 'drawing' | 'highlight';
