  content: string;
  position: {
    page?: number;
    sectionId?: string;
    x: number;
    y: number;
  };
  createdAt: string;
  updatedAt: string;
  resolved: boolean;
  resolvedBy?: Collaborator;
  resolvedAt?: string;
  mentions?: string[];
  replies?: AnnotationReply[];
}

