/**
 * RMFOOD 核心业务类型定义
 *
 * 提供精确的TypeScript接口，替代项目中的 `any` 类型。
 * 覆盖：用户、配方、肽分析、AI响应等核心实体。
 *
 * 使用示例：
 * ```typescript
 * import type { User, Formula, PeptideAnalysisResult } from '@/types';
 *
 * const user: User = await api.getCurrentUser();
 * const formulas: Formula[] = await api.listFormulas();
 * ```
 */

// ════════════════════════════════════════════
// 1. 用户与权限
// ════════════════════════════════════════════

export interface User {
  id: number;
  username: string;
  email: string;
  fullName?: string;
  avatarUrl?: string;

  // 角色与权限
  role: UserRole;
  isActive: boolean;
  department?: string;
  phone?: string;

  // 个人资料扩展字段（设置页「账户」模块）
  position?: string;
  bio?: string;
  website?: string;
  github?: string;
  linkedin?: string;

  // 安全信息
  lastLoginAt?: string; // ISO 8601
  loginAttempts: number;
  lockedUntil?: string | null;

  // 偏好设置
  preferences?: UserPreferences;

  // 时间戳
  createdAt: string;
  updatedAt: string;
}

export enum UserRole {
  ADMIN = 'admin',
  GUEST = 'guest',
  RESEARCHER = 'researcher',
  FORMULATOR = 'formulator',
  REVIEWER = 'reviewer',
}

export interface UserPreferences {
  language: 'zh' | 'en';
  theme: 'light' | 'dark' | 'system';
  notifications: NotificationPreferences;
  dashboardLayout?: DashboardLayoutConfig;
}

export interface NotificationPreferences {
  emailEnabled: boolean;
  pushEnabled: boolean;
  categories: {
    system: boolean;
    collaboration: boolean;
    aiComplete: boolean;
    deadline: boolean;
  };
}

export interface DashboardLayoutConfig {
  widgets: WidgetConfig[];
  columns: number;
}

export interface WidgetConfig {
  id: string;
  type: 'chart' | 'list' | 'stat' | 'table';
  title: string;
  size: 'small' | 'medium' | 'large';
  position: { x: number; y: number };
}

