    expect(() => sanitizeFileName('..\\..\\windows\\system32')).toThrow(FileSecurityError)
  })

  it('应该移除危险字符', () => {
    expect(sanitizeFileName('file<name>.txt')).toBe('file_name_.txt')
    expect(sanitizeFileName('file"name>.txt')).toBe('file_name_.txt')
    expect(sanitizeFileName('file|name?.txt')).toBe('file_name_.txt')
