    expect(result).toBe('application/pdf')
  })

  it('应该检测 MIME 类型不匹配', async () => {
    const jpegBytes = [0xFF, 0xD8, 0xFF, 0xE0, ...new Array(12).fill(0)]
    const file = createMockFile(jpegBytes, 'text/plain', 'fake.txt')

