    it('12.1 解析复杂配方应该在100ms内完成', () => {
      const complexFormula = `
## 配方详情

本配方包含以下成分：

| 中文名称 | 英文名称 | 含量 | 单位 | 功效说明 |
|----------|----------|------|------|----------|
| 人参提取物 | Ginseng Extract | 100 | mg | 补气养血 |
| 黄芪多糖 | Astragalus Polysaccharide | 200 | mg | 增强免疫 |
| 当归精油 | Angelica Essential Oil | 50 | mg | 活血化瘀 |
| 白术粉 | Atractylodes Powder | 150 | mg | 健脾燥湿 |
| 茯苓多糖 | Poria Polysaccharide | 180 | mg | 利水渗湿 |
| 甘草提取物 | Licorice Extract | 80 | mg | 调和诸药 |

**注意事项**：请在医师指导下使用。
`.repeat(10)

      const startTime = performance.now()
      const result = parseFormulaTable(complexFormula)
      const endTime = performance.now()

      const duration = endTime - startTime

      // 解析时间应该小于100ms
      expect(duration).toBeLessThan(100)

      if (result) {
        expect(result.ingredients.length).toBeGreaterThan(0)
      }
    })

    it('12.2 批量提取多个配方的性能测试', () => {
      const texts = Array.from({ length: 50 }, (_, i) => 
        `配方${i + 1}：\n| 成分 | 用量 |\n|------|------|\n| 成分A${i} | ${10 + i}g |\n| 成分B${i} | ${20 + i}g |`
      )

      const startTime = performance.now()

      for (let i = 0; i < texts.length; i++) {
        extractAllFormulas(texts[i], `perf_msg_${i}`)
      }

      const endTime = performance.now()
      const totalTime = endTime - startTime

      // 50个配方的总提取时间应该小于500ms（平均每个<10ms）
      expect(totalTime).toBeLessThan(500)
    })
  })

  // ============================================================
  // 13. 其他边界情况
  // ============================================================
  describe('其他边界情况', () => {
    it('13.1 只有1个成分的表格不应该被视为有效配方', () => {
      const singleIngredient = `| 成分 | 用量 |\n|------|------|\n| 人参 | 10g |`

      const result = parseFormulaTable(singleIngredient)

      // MIN_INGREDIENTS_FOR_FORMULA = 2，所以单个成分应该返回null
      // 或者如果被自然语言解析器捕获，也可能返回结果
      if (result && result.formatType === 'table') {
        expect(result.ingredients.length).toBeGreaterThanOrEqual(2)
      }
    })

    it('13.2 数值为0的成分应该被过滤', () => {
      const tableWithZero = `| 成分 | 用量 |\n|------|------|\n| 人参 | 0g |\n| 黄芪 | 15g |\n| 当归 | 8g |`

      const result = parseFormulaTable(tableWithZero)

      if (result) {
        expect(result.ingredients.every(ing => ing.amount > 0)).toBeTruthy()
      }
    })

    it('13.3 超大数值应该被限制或过滤', () => {
      const tableWithHugeValue = `| 成分 | 用量 |\n|------|------|\n| 人参 | 999999g |\n| 黄芪 | 15g |`

      // 不应该崩溃
      expect(() => parseFormulaTable(tableWithHugeValue)).not.toThrow()
    })

    it('13.4 Unicode和特殊Unicode字符的处理', () => {
      const unicodeText = `| 成分名稱 | 劑量 |
|----------|------|
| 人蔘 | 10g |
| 黃耆 | 15g |
| 當歸 | 8g |`

      // 不应该崩溃
      expect(() => parseFormulaTable(unicodeText)).not.toThrow()
      const result = parseFormulaTable(unicodeText)
      if (result) {
        expect(result.ingredients.length).toBeGreaterThan(0)
      }
    })

    it('13.5 HTML实体编码的内容应该能正确处理', () => {
      const htmlEntityText = `成分：&amp;人参&amp; 10g，&lt;黄芪&gt; 15g`

      // 不应该崩溃
      expect(() => parseFormulaTable(htmlEntityText)).not.toThrow()
    })
  })
})

/**
 * formulaValidator 单元测试
 *
 * 测试覆盖范围：
 * - validateFormulaName: 配方名称验证（7个测试用例）
 * - validateIngredient: 成分验证（5个测试用例）
 * - validateIngredientList: 成分列表验证（7个测试用例）
 * - validateFormulaSteps: 步骤验证（4个测试用例）
 * - validateFormulaEffects: 功效验证（5个测试用例）
 * - validateFullFormula: 完整配方验证（5个测试用例）
 * - getErrorMessage 和 hasFieldError 辅助函数
 *
 * 目标代码覆盖率 ≥ 90%
 */
import { describe, it, expect } from 'vitest'
import {
  validateFormulaName,
  validateIngredient,
  validateIngredientList,
  validateFormulaSteps,
  validateFormulaEffects,
  validateFullFormula,
  getErrorMessage,
  hasFieldError,
} from '@/utils/formulaValidator'

describe('formulaValidator - 配方验证工具函数库', () => {
  // ============================================================
  // 1. validateFormulaName 测试
  // ============================================================
  describe('validateFormulaName - 配方名称验证', () => {
    it('应该通过有效的配方名称', () => {
      const result = validateFormulaName('气血双补配方')
      expect(result).toHaveLength(0)
    })

    it('空字符串应返回 REQUIRED 错误', () => {
      const result = validateFormulaName('')
      expect(result).toHaveLength(1)
      expect(result[0].code).toBe('REQUIRED')
      expect(result[0].field).toBe('name')
    })

    it('只有空格应返回 REQUIRED 错误', () => {
      const result = validateFormulaName('   ')
      expect(result).toHaveLength(1)
      expect(result[0].code).toBe('REQUIRED')
    })

    it('超过100字符应返回 MAX_LENGTH 错误', () => {
      const longName = 'a'.repeat(101)
      const result = validateFormulaName(longName)
      const maxLengthError = result.find(e => e.code === 'MAX_LENGTH')
      expect(maxLengthError).toBeDefined()
      expect(maxLengthError?.field).toBe('name')
    })

    it('恰好100字符应通过', () => {
      const name = 'a'.repeat(100)
      const result = validateFormulaName(name)
      const maxLengthError = result.find(e => e.code === 'MAX_LENGTH')
      expect(maxLengthError).toBeUndefined()
    })

    it('少于2字符应返回 MIN_LENGTH 错误', () => {
      const result = validateFormulaName('a')
      const minLengthError = result.find(e => e.code === 'MIN_LENGTH')
      expect(minLengthError).toBeDefined()
      expect(minLengthError?.field).toBe('name')
    })

    it('包含特殊非法字符应返回 INVALID_CHARACTERS', () => {
      const result = validateFormulaName('配方<test>')
      const invalidCharError = result.find(e => e.code === 'INVALID_CHARACTERS')
      expect(invalidCharError).toBeDefined()
    })

    it('null/undefined 应返回 REQUIRED 错误', () => {
      const result1 = validateFormulaName(null as any)
      const result2 = validateFormulaName(undefined as any)
      expect(result1[0].code).toBe('REQUIRED')
      expect(result2[0].code).toBe('REQUIRED')
    })

    it('包含多种非法字符应返回所有相关错误', () => {
      const name = '<script>alert("xss")</script>'
      const result = validateFormulaName(name)
      expect(result.some(e => e.code === 'INVALID_CHARACTERS')).toBeTruthy()
    })
  })

  // ============================================================
  // 2. validateIngredient 测试
  // ============================================================
  describe('validateIngredient - 成分验证', () => {
    it('有效成分应通过验证', () => {
      const ingredient = { name: '人参', amount: 10, percentage: 50 }
      const result = validateIngredient(ingredient)
      expect(result).toHaveLength(0)
    })

    it('缺少名称应返回 REQUIRED 错误', () => {
      const ingredient = { amount: 10, percentage: 50 }
      const result = validateIngredient(ingredient)
      expect(result.some(e => e.field === 'name' && e.code === 'REQUIRED')).toBeTruthy()
    })

    it('用量为负数应返回 OUT_OF_RANGE', () => {
      const ingredient = { name: '人参', amount: -5, percentage: 50 }
      const result = validateIngredient(ingredient)
      expect(result.some(e => e.field === 'amount' && e.code === 'OUT_OF_RANGE')).toBeTruthy()
    })

    it('比例超过100应返回 OUT_OF_RANGE', () => {
      const ingredient = { name: '人参', amount: 10, percentage: 150 }
      const result = validateIngredient(ingredient)
      expect(result.some(e => e.field === 'percentage' && e.code === 'OUT_OF_RANGE')).toBeTruthy()
    })

    it('比例小于0应返回 OUT_OF_RANGE', () => {
      const ingredient = { name: '人参', amount: 10, percentage: -10 }
      const result = validateIngredient(ingredient)
      expect(result.some(e => e.field === 'percentage' && e.code === 'OUT_OF_RANGE')).toBeTruthy()
    })

    it('用量超出合理范围（>1000000）应返回 OUT_OF_RANGE', () => {
      const ingredient = { name: '人参', amount: 1000001, percentage: 50 }
      const result = validateIngredient(ingredient)
      expect(result.some(e => e.field === 'amount' && e.code === 'OUT_OF_RANGE')).toBeTruthy()
    })

    it('缺少用量应返回 REQUIRED 错误', () => {
      const ingredient = { name: '人参', percentage: 50 }
      const result = validateIngredient(ingredient)
      expect(result.some(e => e.field === 'amount' && e.code === 'REQUIRED')).toBeTruthy()
    })

    it('缺少比例应返回 REQUIRED 错误', () => {
      const ingredient = { name: '人参', amount: 10 }
      const result = validateIngredient(ingredient)
      expect(result.some(e => e.field === 'percentage' && e.code === 'REQUIRED')).toBeTruthy()
    })
  })

  // ============================================================
  // 3. validateIngredientList 测试
  // ============================================================
  describe('validateIngredientList - 成分列表验证', () => {
    it('空数组应返回错误（至少一条成分）', () => {
      const result = validateIngredientList([])
      expect(result.some(e => e.code === 'REQUIRED' && e.field === 'ingredients')).toBeTruthy()
    })

    it('null/undefined 应返回 REQUIRED 错误', () => {
      const result1 = validateIngredientList(null as any)
      const result2 = validateIngredientList(undefined as any)
      expect(result1.some(e => e.code === 'REQUIRED')).toBeTruthy()
      expect(result2.some(e => e.code === 'REQUIRED')).toBeTruthy()
    })

    it('单条成分且比例100%应通过', () => {
      const ingredients = [{ name: '水', percentage: 100 }]
      const result = validateIngredientList(ingredients)
      expect(result.filter(e => e.code === 'SUM_NOT_100')).toHaveLength(0)
    })

    it('多条成分比例总和为100%应通过', () => {
      const ingredients = [
        { name: '人参', percentage: 30 },
        { name: '黄芪', percentage: 40 },
        { name: '当归', percentage: 30 },
      ]
      const result = validateIngredientList(ingredients)
      expect(result.filter(e => e.code === 'SUM_NOT_100')).toHaveLength(0)
    })

    it('比例总和<100%应返回 SUM_NOT_100', () => {
      const ingredients = [
        { name: '人参', percentage: 30 },
        { name: '黄芪', percentage: 40 },
      ]
      const result = validateIngredientList(ingredients)
      expect(result.some(e => e.code === 'SUM_NOT_100')).toBeTruthy()
    })

    it('比例总和>100%应返回 SUM_NOT_100', () => {
      const ingredients = [
        { name: '人参', percentage: 60 },
        { name: '黄芪', percentage: 60 },
      ]
      const result = validateIngredientList(ingredients)
      expect(result.some(e => e.code === 'SUM_NOT_100')).toBeTruthy()
    })

    it('比例总和99.99%（浮点误差范围）应通过', () => {
      const ingredients = [
        { name: '人参', percentage: 33.34 },
        { name: '黄芪', percentage: 33.33 },
        { name: '当归', percentage: 33.33 },
      ]
      const result = validateIngredientList(ingredients)
      expect(result.filter(e => e.code === 'SUM_NOT_100')).toHaveLength(0)
    })

    it('含重复名称成分应返回 DUPLICATE_NAME', () => {
      const ingredients = [
        { name: '人参', percentage: 30 },
        { name: '人参', percentage: 40 },
        { name: '当归', percentage: 30 },
      ]
      const result = validateIngredientList(ingredients)
      expect(result.some(e => e.code === 'DUPLICATE_NAME')).toBeTruthy()
    })

    it('应对每个成分单独验证并返回带索引的错误', () => {
      const ingredients = [
        { name: '', percentage: 50 },
        { name: '黄芪', percentage: 50 },
      ]
      const result = validateIngredientList(ingredients)
      expect(result.some(e => e.field.startsWith('ingredients[0]'))).toBeTruthy()
    })
  })

  // ============================================================
  // 4. validateFormulaSteps 测试
  // ============================================================
  describe('validateFormulaSteps - 步骤验证', () => {
    it('空步骤列表应通过（步骤可选）', () => {
      const result = validateFormulaSteps([])
      expect(result).toHaveLength(0)
    })

    it('null/undefined 步骤应通过', () => {
      const result1 = validateFormulaSteps(null as any)
      const result2 = validateFormulaSteps(undefined as any)
      expect(result1).toHaveLength(0)
      expect(result2).toHaveLength(0)
    })

    it('步骤编号重复应报错', () => {
      const steps = [
        { step_number: 1, description: '第一步' },
        { step_number: 1, description: '重复编号' },
        { step_number: 2, description: '第三步' },
      ]
      const result = validateFormulaSteps(steps)
      expect(result.some(e => e.code === 'DUPLICATE_NAME' && e.field === 'process_steps')).toBeTruthy()
    })

    it('步骤描述为空应报错', () => {
      const steps = [
        { step_number: 1, description: '' },
        { step_number: 2, description: '第二步' },
      ]
      const result = validateFormulaSteps(steps)
      expect(result.some(e => e.code === 'REQUIRED' && e.field.includes('description'))).toBeTruthy()
    })

    it('步骤描述只有空格应报错', () => {
      const steps = [
        { step_number: 1, description: '   ' },
      ]
      const result = validateFormulaSteps(steps)
      expect(result.some(e => e.code === 'REQUIRED')).toBeTruthy()
    })

    it('步骤描述少于5字符应返回 MIN_LENGTH 错误', () => {
      const steps = [
        { step_number: 1, description: '太短' },
      ]
      const result = validateFormulaSteps(steps)
      expect(result.some(e => e.code === 'MIN_LENGTH')).toBeTruthy()
    })

    it('有效步骤列表应通过', () => {
      const steps = [
        { step_number: 1, description: '将药材洗净浸泡三十分钟' },
        { step_number: 2, description: '大火煮沸后转小火煮二十分钟' },
        { step_number: 3, description: '过滤取汁备用' },
      ]
      const result = validateFormulaSteps(steps)
      expect(result).toHaveLength(0)
    })
  })

  // ============================================================
  // 5. validateFormulaEffects 测试
  // ============================================================
  describe('validateFormulaEffects - 功效验证', () => {
    it('空数组应通过（功效可选）', () => {
      const result = validateFormulaEffects([])
      expect(result).toHaveLength(0)
    })

    it('null/undefined 应通过', () => {
      const result1 = validateFormulaEffects(null as any)
      const result2 = validateFormulaEffects(undefined as any)
      expect(result1).toHaveLength(0)
      expect(result2).toHaveLength(0)
    })

    it('含空字符串元素应返回 REQUIRED 错误', () => {
      const effects = ['补气', '', '养血']
      const result = validateFormulaEffects(effects)
      expect(result.some(e => e.code === 'REQUIRED' && e.field === 'effects[1]')).toBeTruthy()
    })

    it('有效功效数组应通过', () => {
      const effects = ['补气', '养血', '安神']
      const result = validateFormulaEffects(effects)
      expect(result.filter(e => e.code !== 'DUPLICATE_NAME' && e.code !== 'MAX_LENGTH')).toHaveLength(0)
    })

    it('重复功效标签应警告 DUPLICATE_NAME', () => {
      const effects = ['补气', '养血', '补气']
      const result = validateFormulaEffects(effects)
      expect(result.some(e => e.code === 'DUPLICATE_NAME' && e.field === 'effects')).toBeTruthy()
    })

    it('超过20个功效标签应返回 MAX_LENGTH 错误', () => {
      const effects = Array.from({ length: 21 }, (_, i) => `功效${i + 1}`)
      const result = validateFormulaEffects(effects)
      expect(result.some(e => e.code === 'MAX_LENGTH' && e.field === 'effects')).toBeTruthy()
    })

    it('恰好20个功效标签应通过', () => {
      const effects = Array.from({ length: 20 }, (_, i) => `功效${i + 1}`)
      const result = validateFormulaEffects(effects)
      expect(result.some(e => e.code === 'MAX_LENGTH')).toBeFalsy()
    })
  })

  // ============================================================
  // 6. validateFullFormula 测试
  // ============================================================
  describe('validateFullFormula - 完整配方验证', () => {
    it('完整有效数据应返回 valid=true, errors=[]', () => {
      const data = {
        name: '气血双补配方',
        ingredients: [
          { name: '人参', amount: 10, percentage: 30 },
          { name: '黄芪', amount: 15, percentage: 40 },
          { name: '当归', amount: 8, percentage: 30 },
        ],
        process_steps: [
          { step_number: 1, description: '将药材洗净浸泡三十分钟' },
        ],
        effects: ['补气', '养血'],
      }

      const result = validateFullFormula(data)
      expect(result.valid).toBe(true)
      expect(result.errors).toHaveLength(0)
    })

    it('缺失名称应返回对应字段错误', () => {
      const data = {
        ingredients: [
          { name: '人参', amount: 10, percentage: 100 },
        ],
      }

      const result = validateFullFormula(data)
      expect(result.valid).toBe(false)
      expect(result.errors.some(e => e.field === 'name')).toBeTruthy()
    })

    it('多个字段同时有错误应全部返回', () => {
      const data = {
        name: '',
        ingredients: [
          { name: '', amount: -5, percentage: 150 },
        ],
        estimated_cost: -10,
      }

      const result = validateFullFormula(data)
      expect(result.valid).toBe(false)
      expect(result.errors.length).toBeGreaterThanOrEqual(3)
      expect(result.errors.some(e => e.field === 'name')).toBeTruthy()
      expect(result.errors.some(e => e.field.includes('ingredients'))).toBeTruthy()
      expect(result.errors.some(e => e.field === 'estimated_cost')).toBeTruthy()
    })

    it('warnings 和 errors 应分开返回', () => {
      const data = {
        name: '有效配方名',
        tags: Array.from({ length: 11 }, (_, i) => `标签${i}`),
        description: 'a'.repeat(2001),
        ingredients: [
          { name: '成分A', amount: 10, percentage: 100 },
        ],
      }

      const result = validateFullFormula(data)
      expect(result.valid).toBe(true)
      expect(result.warnings.length).toBeGreaterThan(0)
      expect(result.errors.length).toBe(0)
      expect(result.warnings.some(e => e.field === 'tags')).toBeTruthy()
      expect(result.warnings.some(e => e.field === 'description')).toBeTruthy()
    })

    it('部分数据（仅名称）应返回 valid=true 但可能有 warnings', () => {
      const data = {
        name: '仅名称的配方',
      }

      const result = validateFullFormula(data)
      expect(result.valid).toBe(true)
      expect(result.errors).toHaveLength(0)
    })

    it('预估成本为负数应返回错误', () => {
      const data = {
        name: '测试配方',
        estimated_cost: -100,
      }

      const result = validateFullFormula(data)
      expect(result.errors.some(e => e.field === 'estimated_cost' && e.code === 'OUT_OF_RANGE')).toBeTruthy()
    })
  })

  // ============================================================
  // 7. 辅助函数测试
  // ============================================================
  describe('getErrorMessage - 获取错误消息', () => {
    it('应返回指定字段的第一个错误消息', () => {
      const errors = [
        { field: 'name', message: '名称不能为空', code: 'REQUIRED' as const },
        { field: 'amount', message: '用量不能为负数', code: 'OUT_OF_RANGE' as const },
      ]

      expect(getErrorMessage(errors, 'name')).toBe('名称不能为空')
      expect(getErrorMessage(errors, 'amount')).toBe('用量不能为负数')
    })

    it('字段不存在时应返回 null', () => {
      const errors = [{ field: 'name', message: '错误', code: 'REQUIRED' as const }]
      expect(getErrorMessage(errors, 'nonexistent')).toBeNull()
    })

    it('空错误数组应返回 null', () => {
      expect(getErrorMessage([])).toBeNull()
      expect(getErrorMessage([], 'name')).toBeNull()
    })

    it('不指定字段时返回第一个错误消息', () => {
      const errors = [
        { field: 'name', message: '第一个错误', code: 'REQUIRED' as const },
        { field: 'amount', message: '第二个错误', code: 'OUT_OF_RANGE' as const },
      ]

      expect(getErrorMessage(errors)).toBe('第一个错误')
    })
  })

  describe('hasFieldError - 检查字段是否有错误', () => {
    it('精确匹配字段名应返回 true', () => {
      const errors = [{ field: 'name', message: '错误', code: 'REQUIRED' as const }]
      expect(hasFieldError(errors, 'name')).toBe(true)
    })

    it('前缀匹配（嵌套字段）应返回 true', () => {
      const errors = [
        { field: 'ingredients.name', message: '错误', code: 'REQUIRED' as const },
      ]
      expect(hasFieldError(errors, 'ingredients')).toBe(true)
    })

    it('无匹配字段应返回 false', () => {
      const errors = [{ field: 'name', message: '错误', code: 'REQUIRED' as const }]
      expect(hasFieldError(errors, 'amount')).toBe(false)
    })

    it('空错误数组应返回 false', () => {
      expect(hasFieldError([], 'name')).toBe(false)
    })
  })
})

/**
 * permissions 单元测试
 *
 * 测试覆盖范围：
 * - hasPermission: 权限检查函数（5个测试用例）
 * - hasAnyPermission: 任一权限检查（3个测试用例）
 * - PermissionGate 组件（4个测试用例）
 * - ROLE_PERMISSIONS 映射表验证（3个测试用例）
 * - requirePermission 函数（2个测试用例）
 * - PermissionDeniedError 类（2个测试用例）
 *
 * 目标代码覆盖率 ≥ 95%
 */
import { describe, it, expect, vi, beforeAll } from 'vitest'
import React from 'react'
import { render } from '@testing-library/react'

// 定义 UserRole 常量（与源码中的枚举值一致）
const VIEWER = 'VIEWER'
const RESEARCHER = 'RESEARCHER'
const ANALYST = 'ANALYST'
const ADMIN = 'ADMIN'
const MANAGER = 'MANAGER'

// Mock useAuthStore
vi.mock('@/stores/auth', () => ({
  useAuthStore: vi.fn(() => ({
    getState: () => ({
      user: null,
    }),
  })),
}))

describe('permissions - 权限工具函数库', () => {
  let hasPermission: (role: string | null, perm: string) => boolean
  let hasAnyPermission: (role: string | null, perms: string[]) => boolean
  let requirePermission: (role: string | null, permission: string, fallback?: ReactNode) => { allowed: boolean; fallback?: ReactNode }
  let PermissionGate: any
  let ROLE_PERMISSIONS: any
  let PermissionDeniedError: any
  let FormulaPermission: any

  beforeAll(async () => {
    const module = await import('@/utils/permissions')
    hasPermission = module.hasPermission
    hasAnyPermission = module.hasAnyPermission
    requirePermission = module.requirePermission
    PermissionGate = module.PermissionGate
    ROLE_PERMISSIONS = module.ROLE_PERMISSIONS
    PermissionDeniedError = module.PermissionDeniedError
    FormulaPermission = module.FormulaPermission
  })

  // ============================================================
  // 1. hasPermission 测试
  // ============================================================
  describe('hasPermission - 单权限检查', () => {
    it('管理员应有所有权限', () => {
      expect(hasPermission(ADMIN, FormulaPermission.VIEW)).toBe(true)
      expect(hasPermission(ADMIN, FormulaPermission.CREATE)).toBe(true)
      expect(hasPermission(ADMIN, FormulaPermission.EDIT)).toBe(true)
      expect(hasPermission(ADMIN, FormulaPermission.DELETE)).toBe(true)
      expect(hasPermission(ADMIN, FormulaPermission.EXPORT)).toBe(true)
      expect(hasPermission(ADMIN, FormulaPermission.IMPORT)).toBe(true)
      expect(hasPermission(ADMIN, FormulaPermission.AUDIT)).toBe(true)
      expect(hasPermission(ADMIN, FormulaPermission.MANAGE)).toBe(true)
    })

    it('访客只能查看', () => {
      expect(hasPermission(VIEWER, FormulaPermission.VIEW)).toBe(true)
      expect(hasPermission(VIEWER, FormulaPermission.CREATE)).toBe(false)
      expect(hasPermission(VIEWER, FormulaPermission.EDIT)).toBe(false)
      expect(hasPermission(VIEWER, FormulaPermission.DELETE)).toBe(false)
      expect(hasPermission(VIEWER, FormulaPermission.EXPORT)).toBe(false)
    })

    it('研究员可以创建编辑但不能删除', () => {
      expect(hasPermission(RESEARCHER, FormulaPermission.VIEW)).toBe(true)
      expect(hasPermission(RESEARCHER, FormulaPermission.CREATE)).toBe(true)
      expect(hasPermission(RESEARCHER, FormulaPermission.EDIT)).toBe(true)
      expect(hasPermission(RESEARCHER, FormulaPermission.DELETE)).toBe(false)
      expect(hasPermission(RESEARCHER, FormulaPermission.EXPORT)).toBe(true)
      expect(hasPermission(RESEARCHER, FormulaPermission.MANAGE)).toBe(false)
    })

    it('null 角色应无任何权限', () => {
      expect(hasPermission(null, FormulaPermission.VIEW)).toBe(false)
      expect(hasPermission(null, FormulaPermission.CREATE)).toBe(false)
      expect(hasPermission(null, FormulaPermission.DELETE)).toBe(false)
    })

    it('未知角色应无任何权限', () => {
      expect(hasPermission('UNKNOWN_ROLE', FormulaPermission.VIEW)).toBe(false)
      expect(hasPermission('GUEST', FormulaPermission.CREATE)).toBe(false)
    })
  })

  // ============================================================
  // 2. hasAnyPermission 测试
  // ============================================================
  describe('hasAnyPermission - 任一权限检查', () => {
    it('拥有任一权限即返回 true', () => {
      expect(hasAnyPermission(VIEWER, [FormulaPermission.VIEW])).toBe(true)
      expect(
        hasAnyPermission(VIEWER, [FormulaPermission.CREATE, FormulaPermission.VIEW])
      ).toBe(true)
    })

    it('完全不匹配返回 false', () => {
      expect(
        hasAnyPermission(VIEWER, [FormulaPermission.CREATE, FormulaPermission.DELETE])
      ).toBe(false)
    })

    it('空权限列表应返回 false', () => {
      expect(hasAnyPermission(ADMIN, [])).toBe(false)
      expect(hasAnyPermission(MANAGER, [])).toBe(false)
    })

    it('null 角色应返回 false', () => {
      expect(hasAnyPermission(null, [FormulaPermission.VIEW])).toBe(false)
    })

    it('管理员应对任意权限组合返回 true', () => {
      const allPermissions = Object.values(FormulaPermission)
      expect(hasAnyPermission(ADMIN, allPermissions)).toBe(true)
    })
  })

  // ============================================================
  // 3. requirePermission 测试
  // ============================================================
  describe('requirePermission - 权限要求函数', () => {
    it('有权限时应返回 allowed=true 且无 fallback', () => {
      const result = requirePermission(ADMIN, FormulaPermission.DELETE)
      expect(result.allowed).toBe(true)
      expect(result.fallback).toBeUndefined()
    })

    it('无权限时应返回 allowed=false 并包含 fallback', () => {
      const fallback = React.createElement('div', null, '无权限提示')
      const result = requirePermission(VIEWER, FormulaPermission.DELETE, fallback)
      expect(result.allowed).toBe(false)
      expect(result.fallback).toBe(fallback)
    })

    it('无权限且未提供 fallback 时 fallback 应为 undefined', () => {
      const result = requirePermission(VIEWER, FormulaPermission.DELETE)
      expect(result.allowed).toBe(false)
      expect(result.fallback).toBeUndefined()
    })
  })

  // ============================================================
  // 4. PermissionGate 组件测试
  // ============================================================
  describe('PermissionGate - 权限门控组件', () => {
    it('有权限时应渲染 children', () => {
      const { container } = render(
        React.createElement(PermissionGate, {
          permission: FormulaPermission.VIEW,
          userRole: ADMIN,
          children: React.createElement('div', null, '受保护内容'),
        })
      )

      expect(container.textContent).toContain('受保护内容')
    })

    it('无权限时应渲染 fallback', () => {
      const { container } = render(
        React.createElement(PermissionGate, {
          permission: FormulaPermission.DELETE,
          userRole: VIEWER,
          fallback: React.createElement('div', null, '无权限提示'),
          children: React.createElement('div', null, '受保护内容'),
        })
      )

      expect(container.textContent).toContain('无权限提示')
      expect(container.textContent).not.toContain('受保护内容')
    })

    it('无权限且无 fallback 应不渲染任何内容', () => {
      const { container } = render(
        React.createElement(PermissionGate, {
          permission: FormulaPermission.DELETE,
          userRole: VIEWER,
          children: React.createElement('div', null, '受保护内容'),
        })
      )

      expect(container.textContent).toBe('')
    })

    it('传入权限数组（满足任一即可）', () => {
      const { container } = render(
        React.createElement(PermissionGate, {
          permission: [FormulaPermission.CREATE, FormulaPermission.VIEW],
          userRole: VIEWER,
          children: React.createElement('div', null, '可见内容'),
        })
      )

      expect(container.textContent).toContain('可见内容')
    })

    it('传入权限数组（全部不匹配）', () => {
      const { container } = render(
        React.createElement(PermissionGate, {
          permission: [FormulaPermission.DELETE, FormulaPermission.MANAGER],
          userRole: VIEWER,
          fallback: React.createElement('div', null, '无权限'),
          children: React.createElement('div', null, '不可见内容'),
        })
      )

      expect(container.textContent).toContain('无权限')
      expect(container.textContent).not.toContain('不可见内容')
    })
  })

  // ============================================================
  // 5. ROLE_PERMISSIONS 映射表测试
  // ============================================================
  describe('ROLE_PERMISSIONS - 角色权限映射表', () => {
    it('VIEWER 应仅有 VIEW 权限', () => {
      const viewerPermissions = ROLE_PERMISSIONS[VIEWER]
      expect(viewerPermissions).toHaveLength(1)
      expect(viewerPermissions).toContain(FormulaPermission.VIEW)
    })

    it('MANAGER 应包含所有权限', () => {
      const managerPermissions = ROLE_PERMISSIONS[MANAGER]
      const allPermissions = Object.values(FormulaPermission)

      expect(managerPermissions.length).toBe(allPermissions.length)
      allPermissions.forEach((permission) => {
        expect(managerPermissions).toContain(permission)
      })
    })

    it('角色层级正确（VIEWER < RESEARCHER < ANALYST < ADMIN < MANAGER）', () => {
      const viewerPerms = new Set(ROLE_PERMISSIONS[VIEWER])
      const researcherPerms = new Set(ROLE_PERMISSIONS[RESEARCHER])
      const analystPerms = new Set(ROLE_PERMISSIONS[ANALYST])
      const adminPerms = new Set(ROLE_PERMISSIONS[ADMIN])

      for (const perm of viewerPerms) {
        expect(researcherPerms.has(perm)).toBe(true)
      }
      for (const perm of researcherPerms) {
        expect(analystPerms.has(perm)).toBe(true)
      }
      for (const perm of analystPerms) {
        expect(adminPerms.has(perm)).toBe(true)
      }

      expect(analystPerms.size).toBeGreaterThan(researcherPerms.size)
      expect(adminPerms.size).toBeGreaterThan(analystPerms.size)
    })

    it('ANALYST 应比 RESEARCHER 多 AUDIT 权限', () => {
      const researcherPerms = ROLE_PERMISSIONS[RESEARCHER]
      const analystPerms = ROLE_PERMISSIONS[ANALYST]

      expect(researcherPerms).not.toContain(FormulaPermission.AUDIT)
      expect(analystPerms).toContain(FormulaPermission.AUDIT)
    })

    it('ADMIN 应有 DELETE 和 IMPORT 权限但 ANALYST 没有', () => {
      const adminPerms = ROLE_PERMISSIONS[ADMIN]
      const analystPerms = ROLE_PERMISSIONS[ANALYST]

      expect(adminPerms).toContain(FormulaPermission.DELETE)
      expect(adminPerms).toContain(FormulaPermission.IMPORT)
      expect(analystPerms).not.toContain(FormulaPermission.DELETE)
      expect(analystPerms).not.toContain(FormulaPermission.IMPORT)
    })
  })

  // ============================================================
  // 6. PermissionDeniedError 测试
  // ============================================================
  describe('PermissionDeniedError - 权限拒绝错误类', () => {
    it('应创建正确的错误实例', () => {
      const error = new PermissionDeniedError(FormulaPermission.DELETE)
      expect(error).toBeInstanceOf(Error)
      expect(error).toBeInstanceOf(PermissionDeniedError)
      expect(error.name).toBe('PermissionDeniedError')
      expect(error.permission).toBe(FormulaPermission.DELETE)
      expect(error.message).toContain('formula:delete')
    })

    it('支持自定义消息', () => {
      const customMessage = '您没有删除配方的权限'
      const error = new PermissionDeniedError(FormulaPermission.DELETE, customMessage)
      expect(error.message).toBe(customMessage)
    })
  })
})

