import { logger } from '@/utils/safeLogger';

/**
 * Data Export Utilities for Analytics Dashboard
 *
 * Supports:
 * - CSV export (comma-separated values)
 * - Excel export (using exceljs library)
 * - PDF export (using jsPDF + autoTable)
 *
 * Features:
 * - Theme-aware styling
 * - Custom headers and formatting
 * - Date range filtering
 * - Batch export support
 */

export interface ExportOptions {
  filename?: string
  title?: string
  subtitle?: string
  includeHeaders?: boolean
  dateFormat?: string
  numberFormat?: 'locale' | 'raw'
  sheetName?: string
}

export interface ExportColumn {
  key: string
  header: string
  width?: number
  formatter?: (value: any) => string | number
}

export class AnalyticsExporter {

  static async exportToCSV(
    data: Record<string, any>[],
    columns: ExportColumn[],
    options: ExportOptions = {},
  ): Promise<void> {
    const {
      filename = `rmfood-export-${new Date().toISOString().split('T')[0]}`,
      includeHeaders = true,
      title = 'RMFOOD 数据分析报告',
      subtitle = `导出时间: ${new Date().toLocaleString('zh-CN')}`,
    } = options

    const BOM = '\uFEFF'

    let csvContent = BOM

    if (title || subtitle) {
      csvContent += `"${title}"\n`
      csvContent += `"${subtitle}"\n\n`
    }

    if (includeHeaders) {
      csvContent += columns.map(col => `"${col.header}"`).join(',') + '\n'
    }

    data.forEach(row => {
      const rowData = columns.map(col => {
        let value = row[col.key]

        if (col.formatter) {
          value = col.formatter(value)
        }

        if (value === null || value === undefined) {
          return '""'
        }

        if (typeof value === 'string') {
          value = value.replace(/"/g, '""')
          return `"${value}"`
        }

        return String(value)
      })

      csvContent += rowData.join(',') + '\n'
    })

    this.downloadFile(csvContent, `${filename}.csv`, 'text/csv;charset=utf-8;')
  }

  static async exportToExcel(
    data: Record<string, any>[],
    columns: ExportColumn[],
    options: ExportOptions = {},
  ): Promise<void> {
    try {
      const ExcelJS = await import('exceljs')

      const {
        filename = `rmfood-export-${new Date().toISOString().split('T')[0]}`,
        sheetName = '数据分析',
        title = 'RMFOOD 数据分析报告',
        subtitle = `导出时间: ${new Date().toLocaleString('zh-CN')}`,
      } = options

      const workbook = new ExcelJS.default.Workbook()
      workbook.creator = 'RMFOOD'
      workbook.created = new Date()
      const worksheet = workbook.addWorksheet(sheetName)

      if (title || subtitle) {
        worksheet.addRow([title])
        worksheet.addRow([subtitle])
        worksheet.addRow([])
      }

      worksheet.addRow(columns.map(col => col.header))

      data.forEach(row => {
        const rowData = columns.map(col => {
          let value = row[col.key]

          if (col.formatter) {
            value = col.formatter(value)
          }

          return value ?? ''
        })

        worksheet.addRow(rowData)
      })

      worksheet.columns = columns.map((col) => {
        const headerLength = col.header.length;
        const dataLengths = data.map(r => String(r[col.key] || '').length);
        const maxDataLength = dataLengths.length > 0 ? Math.max(...dataLengths) : 0;
        return {
          header: col.header,
          key: col.key,
          width: col.width || Math.max(headerLength, maxDataLength) + 2,
        };
      })

      const excelBuffer = await workbook.xlsx.writeBuffer()

      this.downloadBlob(
        new Blob([excelBuffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' }),
        `${filename}.xlsx`,
      )

    } catch (error) {
      logger.error('Excel 导出失败:', error)
      throw new Error('Excel导出失败，请检查exceljs库是否已安装')
    }
  }

  static async exportToPDF(
    data: Record<string, any>[],
    columns: ExportColumn[],
    options: ExportOptions & { themeColors?: Record<string, string> } = {},
  ): Promise<void> {
    try {
      const { default: jsPDF } = await import('jspdf')
      const { default: autoTable } = await import('jspdf-autotable')

      const {
        filename = `rmfood-export-${new Date().toISOString().split('T')[0]}`,
        title = 'RMFOOD 数据分析报告',
        subtitle = `导出时间: ${new Date().toLocaleString('zh-CN')}`,
        themeColors = {
          primary: '#16A34A',
          textPrimary: '#1F2937',
          textSecondary: '#6B7280',
          background: '#FFFFFF',
        },
      } = options

      const doc = new jsPDF({
        orientation: 'landscape',
        unit: 'mm',
        format: 'a4',
      })

      const pageWidth = doc.internal.pageSize.getWidth()
      const margin = 15

      doc.setFontSize(22)
      doc.setTextColor(themeColors.primary)
      doc.text(title || '', margin, 25)

      doc.setFontSize(11)
      doc.setTextColor(themeColors.textSecondary)
      doc.text(subtitle || '', margin, 33)

      doc.setDrawColor(themeColors.primary)
      doc.setLineWidth(0.5)
      doc.line(margin, 38, pageWidth - margin, 38)

      const tableData = data.map(row =>
        columns.map(col => {
          let value = row[col.key]
          if (col.formatter) {
            value = col.formatter(value)
          }
          return value ?? ''
        }),
      )

      const tableHeaders = columns.map(col => col.header)

      autoTable(doc, {
        head: [tableHeaders],
        body: tableData,
        startY: 45,
        theme: 'grid',
        headStyles: {
          fillColor: [22, 163, 74],
          textColor: [255, 255, 255],
          fontStyle: 'bold',
        },
        styles: {
          fontSize: 9,
          cellPadding: 4,
        },
        alternateRowStyles: {
          fillColor: [245, 245, 245],
        },
        margin: { left: margin, right: margin },
      })

      doc.setFontSize(8)
      doc.setTextColor(themeColors.textSecondary)
      doc.text(
        `Generated by RMFOOD Analytics Platform | ${new Date().toLocaleString('zh-CN')}`,
        margin,
        doc.internal.pageSize.getHeight() - 10,
      )

      doc.save(`${filename}.pdf`)

    } catch (error) {
      logger.error('PDF 导出失败:', error)
      throw new Error('PDF导出失败，请确保jspdf库已安装')
    }
  }

  static downloadFile(content: string, filename: string, mimeType: string): void {
    const blob = new Blob([content], { type: mimeType })
    this.downloadBlob(blob, filename)
  }

  private static downloadBlob(blob: Blob, filename: string): void {
    const url = URL.createObjectURL(blob)
    const link = document.createElement('a')
    link.href = url
    link.download = filename
    document.body.appendChild(link)
    link.click()

    setTimeout(() => {
      window.URL.revokeObjectURL(url)
      document.body.removeChild(link)
    }, 100)
  }

  static formatChartDataForExport(chartData: {
    labels: string[]
    datasets: { label?: string; data: number[] }[]
  }): Record<string, any>[] {
    const labels = chartData.labels || []

    return labels.map((label, index) => {
      const row: Record<string, any> = { period: label }

      ;(chartData.datasets || []).forEach(dataset => {
        row[dataset.label || 'series'] = dataset.data[index]
      })

      return row
    })
  }

  static getExportColumnsFromChart(chartData: {
    labels: string[]
    datasets: { label?: string }[]
  }): ExportColumn[] {
    const columns: ExportColumn[] = [
      { key: 'period', header: '时间/类别', width: 20 },
    ]

    ;(chartData.datasets || []).forEach(dataset => {
      columns.push({
        key: dataset.label || 'series',
        header: dataset.label || '数值',
        formatter: (val: number | null) => val !== null ? val.toLocaleString() : '-',
      })
    })

    return columns
  }
}

export default AnalyticsExporter

import { logger } from '@/utils/safeLogger';
export interface AsyncOperationOptions {
  debounceMs?: number
  leadingEdge?: boolean
  trailingEdge?: boolean
  maxWaitMs?: number
}

export interface RetryOptions {
  maxRetries?: number
  baseDelayMs?: number
  maxDelayMs?: number
  shouldRetry?: (error: Error) => boolean
}

export interface PerformanceMetrics {
  startTime: number
  endTime?: number
  durationMs?: number
  operationId: string
  status: 'pending' | 'completed' | 'cancelled' | 'failed' | 'timeout'
  retryCount?: number
}

export class CancelError extends Error {
  constructor(message = 'Operation was cancelled') {
    super(message)
    this.name = 'CancelError'
  }
}

export class TimeoutError extends Error {
  constructor(message = 'Operation timed out') {
    super(message)
    this.name = 'TimeoutError'
  }
}

interface DebouncedOperation<TArgs extends any[], T> {
  execute: (...args: TArgs) => Promise<T>
  cancel: () => void
  isPending: () => boolean
  getMetrics: () => PerformanceMetrics | null
}

interface AbortableOperation<T> {
  execute: () => Promise<T>
  abort: () => void
  isAborted: () => boolean
  getMetrics: () => PerformanceMetrics | null
}

interface OperationWithTimeout<T> extends Promise<T> {
  cancel: () => void
}

export class AsyncOperationManager<T = any> {
  private activeOperations = new Map<string, { cancel: () => void }>()
  private performanceHistory: PerformanceMetrics[] = []
  private operationCounter = 0

  createDebounced<TArgs extends any[]>(
    fn: (...args: TArgs) => Promise<T>,
    options: AsyncOperationOptions = {},
  ): DebouncedOperation<TArgs, T> {
    const {
      debounceMs = 500,
      leadingEdge = false,
      trailingEdge = true,
      maxWaitMs = 0,
    } = options

    let timerId: ReturnType<typeof setTimeout> | null = null
    let maxWaitTimerId: ReturnType<typeof setTimeout> | null = null
    let isPendingFlag = false
    let currentPromise: Promise<T> | null = null
    let latestArgs: TArgs | null = null
    let operationId: string
    let metrics: PerformanceMetrics | null = null
    let resolveRejectPair: {
      resolve: (value: T) => void
      reject: (error: Error) => void
    } | null = null
    let isCancelled = false

    operationId = `debounced_${++this.operationCounter}_${Date.now()}`

    const executeImmediate = async (): Promise<void> => {
      if (!latestArgs || isCancelled) return

      isPendingFlag = true
      metrics = {
        startTime: Date.now(),
        operationId,
        status: 'pending',
      }

      try {
        const result = await fn(...latestArgs)

        if (!isCancelled) {
          metrics.endTime = Date.now()
          metrics.durationMs = metrics.endTime - metrics.startTime
          metrics.status = 'completed'
          this.recordPerformance(metrics)

          resolveRejectPair?.resolve(result)
        }
      } catch (error) {
        if (!isCancelled && !(error instanceof CancelError)) {
          metrics.endTime = Date.now()
          metrics.durationMs = metrics.endTime - metrics.startTime
          metrics.status = 'failed'
          this.recordPerformance(metrics)

          resolveRejectPair?.reject(error as Error)
        }
      } finally {
        isPendingFlag = false
        currentPromise = null
        timerId = null
      }
    }

    const clearTimers = () => {
      if (timerId) {
        clearTimeout(timerId)
        timerId = null
      }
      if (maxWaitTimerId) {
        clearTimeout(maxWaitTimerId)
        maxWaitTimerId = null
      }
    }

    const execute = (...args: TArgs): Promise<T> => {
      isCancelled = false
      latestArgs = args

      clearTimers()

      currentPromise = new Promise<T>((resolve, reject) => {
        resolveRejectPair = { resolve, reject }

        if (leadingEdge && !isPendingFlag) {
          executeImmediate()
        }

        if (trailingEdge || !leadingEdge) {
          timerId = setTimeout(() => {
            if (!isPendingFlag) {
              executeImmediate()
            }
          }, debounceMs)
        }

        if (maxWaitMs > 0) {
          maxWaitTimerId = setTimeout(() => {
            if (!isPendingFlag) {
              clearTimers()
              executeImmediate()
            }
          }, maxWaitMs)
        }
      })

      return currentPromise
    }

    const cancel = (): void => {
      isCancelled = true
      clearTimers()

      if (metrics) {
        metrics.status = 'cancelled'
        this.recordPerformance(metrics)
      }

      if (resolveRejectPair && isPendingFlag) {
        resolveRejectPair.reject(new CancelError())
      }

      isPendingFlag = false
      currentPromise = null
    }

    const isPending = (): boolean => isPendingFlag

    const getMetrics = (): PerformanceMetrics | null => metrics

    this.activeOperations.set(operationId, { cancel })

    return {
      execute,
      cancel,
      isPending,
      getMetrics,
    }
  }

  createWithTimeout<U>(
    promise: Promise<U>,
    timeoutMs: number,
    errorMessage?: string,
  ): OperationWithTimeout<U> {
    let timeoutId: ReturnType<typeof setTimeout> | null = null
    let isCancelled = false
    const operationId = `timeout_${++this.operationCounter}_${Date.now()}`

    const metrics: PerformanceMetrics = {
      startTime: Date.now(),
      operationId,
      status: 'pending',
    }

    const wrappedPromise = new Promise<U>((resolve, reject) => {
      timeoutId = setTimeout(() => {
        if (!isCancelled) {
          metrics.endTime = Date.now()
          metrics.durationMs = metrics.endTime - metrics.startTime
          metrics.status = 'timeout'
          this.recordPerformance(metrics)

          reject(new TimeoutError(errorMessage))
        }
      }, timeoutMs)

      promise.then(
        (value) => {
          if (!isCancelled && timeoutId) {
            clearTimeout(timeoutId)
            metrics.endTime = Date.now()
            metrics.durationMs = metrics.endTime - metrics.startTime
            metrics.status = 'completed'
            this.recordPerformance(metrics)

            resolve(value)
          }
        },
        (error) => {
          if (!isCancelled && timeoutId) {
            clearTimeout(timeoutId)
            metrics.endTime = Date.now()
            metrics.durationMs = metrics.endTime - metrics.startTime
            metrics.status = 'failed'
            this.recordPerformance(metrics)

            reject(error)
          }
        },
      )
    })

    const cancel = () => {
      isCancelled = true
      if (timeoutId) {
        clearTimeout(timeoutId)
        timeoutId = null
      }
      metrics.status = 'cancelled'
      this.recordPerformance(metrics)
    }

    Object.defineProperty(wrappedPromise, 'cancel', {
      value: cancel,
      writable: false,
      configurable: true,
    })

    this.activeOperations.set(operationId, { cancel })

    return wrappedPromise as OperationWithTimeout<U>
  }

  createAbortable<U>(
    fn: (signal: AbortSignal) => Promise<U>,
  ): AbortableOperation<U> {
    const abortController = new AbortController()
    const operationId = `abortable_${++this.operationCounter}_${Date.now()}`
    let metrics: PerformanceMetrics | null = null

    const execute = async (): Promise<U> => {
      metrics = {
        startTime: Date.now(),
        operationId,
        status: 'pending',
      }

      try {
        const result = await fn(abortController.signal)

        metrics.endTime = Date.now()
        metrics.durationMs = metrics.endTime - metrics.startTime
        metrics.status = 'completed'
        this.recordPerformance(metrics)

        return result
      } catch (error) {
        if (error instanceof DOMException && error.name === 'AbortError') {
          metrics.status = 'cancelled'
          throw new CancelError('Operation aborted')
        }

        metrics.endTime = Date.now()
        metrics.durationMs = metrics.endTime - metrics.startTime
        metrics.status = 'failed'
        this.recordPerformance(metrics)

        throw error
      }
    }

    const abort = () => {
      abortController.abort()
      if (metrics) {
        metrics.status = 'cancelled'
        this.recordPerformance(metrics)
      }
    }

    const isAborted = () => abortController.signal.aborted

    const getMetrics = () => metrics

    this.activeOperations.set(operationId, { cancel: abort })

    return {
      execute,
      abort,
      isAborted,
      getMetrics,
    }
  }

  async withRetry<U>(
    fn: () => Promise<U>,
    options: RetryOptions = {},
  ): Promise<U> {
    const {
      maxRetries = 3,
      baseDelayMs = 1000,
      maxDelayMs = 10000,
      shouldRetry = () => true,
    } = options

    let lastError: Error | null = null
    const operationId = `retry_${++this.operationCounter}_${Date.now()}`

    const metrics: PerformanceMetrics = {
      startTime: Date.now(),
      operationId,
      status: 'pending',
      retryCount: 0,
    }

    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      try {
        const result = await fn()

        metrics.endTime = Date.now()
        metrics.durationMs = metrics.endTime - metrics.startTime
        metrics.status = 'completed'
        metrics.retryCount = attempt
        this.recordPerformance(metrics)

        return result
      } catch (error) {
        lastError = error as Error

        if (attempt < maxRetries && shouldRetry(lastError)) {
          const delay = Math.min(baseDelayMs * Math.pow(2, attempt), maxDelayMs)
          metrics.retryCount = attempt + 1

          await new Promise(resolve => setTimeout(resolve, delay))
        } else {
          metrics.endTime = Date.now()
          metrics.durationMs = metrics.endTime - metrics.startTime
          metrics.status = 'failed'
          this.recordPerformance(metrics)

          throw lastError
        }
      }
    }

    throw lastError
  }

  createRaceConditionSafe<TArgs extends any[], T>(
    fn: (...args: TArgs) => Promise<T>,
    options: AsyncOperationOptions & { keyGenerator?: (...args: TArgs) => string } = {},
  ) {
    let currentRequestId: string | null = null
    let _currentOperation: DebouncedOperation<TArgs, T> | null = null

    // @ts-expect-error -- TypeScript limitation: generic method inference in nested scope causes T/T scope conflict.
    // Runtime safety guaranteed by the `as unknown as DebouncedOperation<TArgs, T>` assertion below.
    const debounced = this.createDebounced(async (...args: TArgs): Promise<T> => {
      const requestId = options.keyGenerator ?
        options.keyGenerator(...args) :
        `request_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`

      currentRequestId = requestId

      const result = await fn(...args)

      if (currentRequestId !== requestId) {
        throw new CancelError('Superseded by newer request')
      }

      return result
    }, options) as unknown as DebouncedOperation<TArgs, T>

    _currentOperation = debounced

    const execute = async (...args: TArgs): Promise<T> => {
      return debounced.execute(...args)
    }

    const cancel = () => {
      currentRequestId = null
      debounced.cancel()
    }

    return {
      execute,
      cancel,
      isPending: () => debounced.isPending(),
      getMetrics: () => debounced.getMetrics(),
    }
  }

  cancelAll(): void {
    this.activeOperations.forEach(({ cancel }) => {
      try {
        cancel()
      } catch (error) {
        logger.warn('Failed to cancel operation:', error)
      }
    })
    this.activeOperations.clear()
  }

  cancelOperation(operationId: string): boolean {
    const operation = this.activeOperations.get(operationId)
    if (operation) {
      operation.cancel()
      this.activeOperations.delete(operationId)
      return true
    }
    return false
  }

  private recordPerformance(metrics: PerformanceMetrics): void {
    this.performanceHistory.push(metrics)

    if (this.performanceHistory.length > 100) {
      this.performanceHistory = this.performanceHistory.slice(-50)
    }
  }

  getPerformanceMetrics(): PerformanceMetrics[] {
    return [...this.performanceHistory]
  }

  getAverageDuration(operationType?: string): number {
    const relevantMetrics = operationType ?
      this.performanceHistory.filter(m => m.operationId.startsWith(operationType)) :
      this.performanceHistory

    const completedMetrics = relevantMetrics.filter(m =>
      m.status === 'completed' && m.durationMs !== undefined,
    )

    if (completedMetrics.length === 0) return 0

    const totalDuration = completedMetrics.reduce((sum, m) => sum + (m.durationMs || 0), 0)
    return totalDuration / completedMetrics.length
  }

  getSuccessRate(operationType?: string): number {
    const relevantMetrics = operationType ?
      this.performanceHistory.filter(m => m.operationId.startsWith(operationType)) :
      this.performanceHistory

    if (relevantMetrics.length === 0) return 0

    const successfulOps = relevantMetrics.filter(m => m.status === 'completed').length
    return (successfulOps / relevantMetrics.length) * 100
  }

  clearPerformanceHistory(): void {
    this.performanceHistory = []
  }

  getActiveOperationsCount(): number {
    return this.activeOperations.size
  }

  destroy(): void {
    this.cancelAll()
    this.clearPerformanceHistory()
    this.operationCounter = 0
  }
}

export const asyncOperationManager = new AsyncOperationManager()

export function createDebouncedOperation<TArgs extends any[], T>(
  fn: (...args: TArgs) => Promise<T>,
  options?: AsyncOperationOptions,
) {
  return asyncOperationManager.createDebounced(fn, options)
}

export function createAbortableOperation<T>(
  fn: (signal: AbortSignal) => Promise<T>,
) {
  return asyncOperationManager.createAbortable(fn)
}

export function withTimeout<T>(
  promise: Promise<T>,
  timeoutMs: number,
  errorMessage?: string,
) {
  return asyncOperationManager.createWithTimeout(promise, timeoutMs, errorMessage)
}

export async function withRetry<T>(
  fn: () => Promise<T>,
  options?: RetryOptions,
) {
  return asyncOperationManager.withRetry(fn, options)
}

import { logger } from '@/utils/safeLogger';

/**
 * 统一配置管理模块
 * 用于管理API密钥和模型配置的集中存储和管理
 */

// 配置类型定义
export interface ApiKey {
  id: string;
  name: string;
  key: string;
  status: 'active' | 'expired' | 'expiring';
  created_at: string;
  expires_at: string;
  permissions: string[];
}

// 加密工具函数
const encrypt = (text: string): string => {
  try {
    return btoa(unescape(encodeURIComponent(text)));
  } catch (error) {
    logger.error('Encryption failed:', error);
    return text;
  }
};

const decrypt = (text: string): string => {
  try {
    if (!text || typeof text !== 'string') {
      return '';
    }
    try {
      return decodeURIComponent(escape(atob(text)));
    } catch {
      return text;
    }
  } catch (error) {
    logger.error('Decryption failed:', error);
    return '';
  }
};

export interface SyncToBackendResult {
  success: boolean
  /** 后端运行时 LLM 服务是否已激活（密钥真正生效的标志） */
  llmActive?: boolean
  /** 后端运行时是否检测到密钥 */
  llmKeyConfigured?: boolean
  /** 403 权限不足（非管理员调用全局端点） */
  forbidden?: boolean
  /** 401 未认证 / token 过期 */
  unauthorized?: boolean
}

// 检测存储值是否已是 base64 编码（用于区分加密数据与旧版明文数据）
const isLikelyBase64 = (value: string): boolean => {
  if (!value || value.length < 4) return false;
  return /^[A-Za-z0-9+/]+={0,2}$/.test(value);
};

export interface ModelConfig {
  apiKey: string;
  baseUrl: string;
  timeout: number;
  maxRetries: number;
  concurrencyLimit: number;
  model?: string;
  provider?: string;
  temperature?: number;
  maxTokens?: number;
  [key: string]: any;
}

export type ModelType = 'formula_gpt' | 'synergy_net' | 'safety_checker' | 'taste_predictor' | 'stability_model' | 'llm' | 'peptide_scorer';

export interface ConfigVersion {
  version: string;
  timestamp: string;
  changes: string;
  config: any;
}

// 配置存储键名
const STORAGE_KEYS = {
  API_KEYS: 'rmfood_api_keys',
  MODEL_CONFIGS: 'rmfood_model_configs',
  CONFIG_VERSIONS: 'rmfood_config_versions',
};

// ─────────────────────────────────────────────────────────────
// P1 密钥本地存储升级：WebCrypto AES-GCM（RMF:2: 前缀）
//   - 写入值形如 RMF:2:<salt_b64>:<iv_b64>:<cipher_b64>
//   - 读取时识别 RMF:2: 前缀走 WebCrypto 解密；解不开返回空串 + legacyUnencrypted=true
//   - WebCrypto 不可用（非安全上下文）时降级到 base64 路径，保持数据可读
// D-6：DPAPI 密钥由账号 ID / token 派生（HKDF-SHA256 → AES-256-GCM），
//   同账号跨会话/换标签页得到相同密钥，实现跨会话免重输。
// ─────────────────────────────────────────────────────────────
const FORMAT_V2_PREFIX = 'RMF:2:';
const DPAPI_KEY_STORAGE = 'rmfood_dpapi_key';
const RMF_HKDF_INFO = 'rmfood-llm-key';
const RMF_HKDF_SALT = 'rmfood-rmf-v3';

/** 模块级 AES 派生输入：由面板层注入（保持 configManager 无 auth store 依赖） */
let _aesDerivationInput: { userId?: number | string; token?: string } = {};
/** 注入 AES 密钥派生输入（面板层在挂载/保存前调用，传入当前用户 id 与 token） */
export function setAesKeyDerivationInput(userId?: number | string, token?: string) {
  _aesDerivationInput = { userId, token };
}

/** 派生输入自动兜底：模块级为空时从 localStorage 读持久化账号 ID，消除注入时序依赖 */
function getEffectiveDerivationInput(): { userId?: number | string; token?: string } {
  if (_aesDerivationInput.userId !== undefined || _aesDerivationInput.token) return _aesDerivationInput;
  try {
    const storedId = localStorage.getItem('rmfood_current_user_id');
    if (storedId) return { ..._aesDerivationInput, userId: storedId };
  } catch { /* localStorage 不可用时忽略 */ }
  return _aesDerivationInput;
}

async function deriveAesKey(cryptoObj: Crypto, input: { userId?: number | string; token?: string }): Promise<CryptoKey | null> {
  try {
    if (!cryptoObj?.subtle) return null;
    // 优先：账号 ID 派生（稳定，不随 token 换发变化）
    if (input.userId !== undefined && input.userId !== null && input.userId !== '') {
      const baseKey = await cryptoObj.subtle.importKey('raw', new TextEncoder().encode(`rmfood-user-${input.userId}`), { name: 'HKDF' }, false, ['deriveKey']);
      return await cryptoObj.subtle.deriveKey(
        { name: 'HKDF', hash: 'SHA-256', salt: new TextEncoder().encode(RMF_HKDF_SALT), info: new TextEncoder().encode(RMF_HKDF_INFO) },
        baseKey,
        { name: 'AES-GCM', length: 256 },
        false,
        ['encrypt', 'decrypt'],
      );
    }
    // 次选：token 派生（兼容旧值；项目已迁 HttpOnly Cookie，localStorage token 仅遗留场景）
    let token = input.token || '';
    try {
      token = token || localStorage.getItem('rmfood_access_token') || localStorage.getItem('access_token') || '';
    } catch { /* localStorage 不可用时忽略 */ }
    if (token) {
      const baseKey = await cryptoObj.subtle.importKey('raw', new TextEncoder().encode(token), { name: 'HKDF' }, false, ['deriveKey']);
      return await cryptoObj.subtle.deriveKey(
        { name: 'HKDF', hash: 'SHA-256', salt: new TextEncoder().encode(RMF_HKDF_SALT), info: new TextEncoder().encode(RMF_HKDF_INFO) },
        baseKey,
        { name: 'AES-GCM', length: 256 },
        false,
        ['encrypt', 'decrypt'],
      );
    }
    return null;
  } catch {
    return null;
  }
}

async function getOrCreateDpapiKey(): Promise<CryptoKey | null> {
  try {
    const cryptoObj = (globalThis.crypto || (self as any).crypto);
    if (!cryptoObj?.subtle) return null;
    const derived = await deriveAesKey(cryptoObj, getEffectiveDerivationInput());
    if (derived) return derived;
    // 未注入派生输入且无账号 ID/token：sessionStorage 随机 256-bit 密钥兜底
    let raw: string | null = null;
    try { raw = sessionStorage.getItem(DPAPI_KEY_STORAGE); } catch { /* sessionStorage 不可用时忽略 */ }
    if (!raw) {
      const bytes = cryptoObj.getRandomValues(new Uint8Array(32));
      raw = btoa(String.fromCharCode(...bytes));
      try { sessionStorage.setItem(DPAPI_KEY_STORAGE, raw); } catch { /* sessionStorage 不可用时忽略 */ }
    }
    const keyBytes = Uint8Array.from(atob(raw), c => c.charCodeAt(0));
    return cryptoObj.subtle.importKey('raw', keyBytes.buffer as ArrayBuffer, { name: 'AES-GCM' }, false, ['encrypt', 'decrypt']);
  } catch {
    return null;
  }
}

/** 异步加密（优先 AES-GCM RMF:2:，WebCrypto 不可用时降级 base64） */
export async function encryptKeyAsync(raw: string): Promise<string> {
  if (!raw) return '';
  const key = await getOrCreateDpapiKey();
  if (!key) return encrypt(raw);
  try {
    const cryptoObj = (globalThis.crypto || (self as any).crypto);
    const salt = cryptoObj.getRandomValues(new Uint8Array(16));
    const iv = cryptoObj.getRandomValues(new Uint8Array(12));
    const data = new TextEncoder().encode(raw);
    const cipher = await cryptoObj.subtle.encrypt({ name: 'AES-GCM', iv }, key, data);
    const enc = (b: ArrayBuffer) => btoa(String.fromCharCode(...new Uint8Array(b)));
    return `${FORMAT_V2_PREFIX}${enc(salt.buffer)}:${enc(iv.buffer)}:${enc(cipher)}`;
  } catch {
    return encrypt(raw);
  }
}

/** 异步解密 RMF:2: 值；非 RMF:2: 或解密失败返回 legacyUnencrypted 标记 */
export async function decryptKeyAsync(stored: string): Promise<{ raw: string; legacyUnencrypted: boolean }> {
  if (!stored) return { raw: '', legacyUnencrypted: false };
  if (stored.startsWith(FORMAT_V2_PREFIX)) {
    try {
      const key = await getOrCreateDpapiKey();
      if (!key) return { raw: '', legacyUnencrypted: true };
      const cryptoObj = (globalThis.crypto || (self as any).crypto);
      const [, ivB64, cipherB64] = stored.slice(FORMAT_V2_PREFIX.length).split(':');
      const dec = (s: string) => Uint8Array.from(atob(s), c => c.charCodeAt(0));
      const iv = dec(ivB64);
      const cipherU8 = dec(cipherB64);
      const plain = await cryptoObj.subtle.decrypt(
        { name: 'AES-GCM', iv },
        key,
        cipherU8.buffer as ArrayBuffer,
      );
      return { raw: new TextDecoder().decode(plain), legacyUnencrypted: false };
    } catch {
      // 解不开（跨会话密钥变化）：标记需重输，不泄露残留明文
      return { raw: '', legacyUnencrypted: true };
    }
  }
  return { raw: decrypt(stored), legacyUnencrypted: false };
}

// ─────────────────────────────────────────────────────────────
// P1 配置广播事件（跨组件/跨标签页同步，带 token 签名防护）
// 仅接受通过 dispatchConfigSync 派发的合法事件，拒绝外来裸事件
// ─────────────────────────────────────────────────────────────
const CONFIG_SYNC_EVENT = 'rmfood-config-sync';
const CONFIG_SYNC_TOKEN_KEY = 'rmfood_config_sync_token';

function generateConfigSyncToken(): string {
  try {
    const cryptoObj = (globalThis.crypto || (self as any).crypto);
    const b = cryptoObj.getRandomValues ? cryptoObj.getRandomValues(new Uint8Array(16)) : null;
    if (b) return Array.from(b).map(x => x.toString(16).padStart(2, '0')).join('');
  } catch { /* crypto 不可用时忽略 */ }
  return `t_${Date.now()}_${Math.random().toString(36).slice(2)}`;
}

/** 派发配置同步事件（每次生成一次性 token 存入 sessionStorage 供监听方校验） */
export function dispatchConfigSync(): void {
  try {
    const token = generateConfigSyncToken();
    sessionStorage.setItem(CONFIG_SYNC_TOKEN_KEY, token);
    window.dispatchEvent(new CustomEvent(CONFIG_SYNC_EVENT, { detail: { token } }));
  } catch { /* 派发失败时忽略 */ }
}

/** 校验广播事件是否为合法派发（token 匹配），拒绝外来脚本派发的裸事件 */
export function validateConfigSync(event: Event): boolean {
  try {
    if (!event || event.type !== CONFIG_SYNC_EVENT) return false;
    const detail = (event as CustomEvent).detail as { token?: string } | undefined;
    if (!detail || typeof detail.token !== 'string') return false;
    return detail.token === sessionStorage.getItem(CONFIG_SYNC_TOKEN_KEY);
  } catch {
    return false;
  }
}

// 配置管理类

interface ModelConfigRaw {
  api_key?: string
  base_url?: string
  timeout_ms?: number
  max_retries?: number
  concurrency_limit?: number
  model?: string
  provider?: string
}

export class ConfigManager {
  // 获取所有API密钥
  static getApiKeys(): ApiKey[] {
    try {
      const stored = localStorage.getItem(STORAGE_KEYS.API_KEYS);
      if (!stored) return [];
      const encryptedKeys = JSON.parse(stored);
      return encryptedKeys.map((key: any) => ({
        ...key,
        key: decrypt(key.key),
      }));
    } catch (error) {
      logger.error('Failed to get API keys:', error);
      return [];
    }
  }

  // 保存API密钥
  static setApiKeys(keys: ApiKey[]): void {
    try {
      const encryptedKeys = keys.map(key => ({
        ...key,
        key: encrypt(key.key),
      }));
      localStorage.setItem(STORAGE_KEYS.API_KEYS, JSON.stringify(encryptedKeys));
      this.createConfigVersion('Updated API keys');
    } catch (error) {
      logger.error('Failed to save API keys:', error);
    }
  }

  // 添加API密钥
  static addApiKey(key: Omit<ApiKey, 'id' | 'created_at'>): ApiKey {
    const newKey: ApiKey = {
      ...key,
      id: `key_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`,
      created_at: new Date().toISOString(),
    };
    const keys = this.getApiKeys();
    keys.push(newKey);
    this.setApiKeys(keys);
    return newKey;
  }

  // 删除API密钥
  static deleteApiKey(id: string): void {
    const keys = this.getApiKeys().filter(key => key.id !== id);
    this.setApiKeys(keys);
  }

  // 获取模型配置
  // 返回 ModelConfig & { legacyUnencrypted?: boolean }；
  // legacyUnencrypted=true 表示该 key 是历史遗留的明文（未经 base64 加密入库），
  // UI 层应据此强制要求用户重新输入，避免把"疑似明文"当作有效密钥写回。
  static getModelConfig(modelType: ModelType): ModelConfig & { legacyUnencrypted?: boolean } {
    try {
      const stored = localStorage.getItem(STORAGE_KEYS.MODEL_CONFIGS);
      if (!stored) return this.getDefaultModelConfig();
      const configs = JSON.parse(stored);
      const config = configs[modelType] || this.getDefaultModelConfig();
      const rawKey = (config as { apiKey?: string }).apiKey || '';
      const legacyUnencrypted = !!rawKey && !isLikelyBase64(rawKey);
      return {
        ...config,
        apiKey: legacyUnencrypted ? rawKey : decrypt(rawKey),
        legacyUnencrypted,
      };
    } catch (error) {
      logger.error(`Failed to get model config for ${modelType}:`, error);
      return this.getDefaultModelConfig();
    }
  }

  // 获取所有模型配置
  static getModelConfigs(): Record<ModelType, ModelConfig> {
    try {
      const stored = localStorage.getItem(STORAGE_KEYS.MODEL_CONFIGS);
      const defaultConfig = this.getDefaultModelConfig();
      const decryptedConfigs: Record<ModelType, ModelConfig> = {
        formula_gpt: defaultConfig,
        synergy_net: defaultConfig,
        safety_checker: defaultConfig,
        taste_predictor: defaultConfig,
        stability_model: defaultConfig,
        llm: defaultConfig,
        peptide_scorer: defaultConfig,
      };
      if (stored) {
        try {
          const configs = JSON.parse(stored);
          Object.entries(configs).forEach(([key, config]) => {
            if (Object.keys(decryptedConfigs).includes(key)) {
              try {
                const encryptedApiKey = (config as Record<string, unknown>).apiKey as string || '';
                const decrypted = decrypt(encryptedApiKey);
                decryptedConfigs[key as ModelType] = {
                  ...(config as object),
                  apiKey: decrypted,
                  baseUrl: ((config as Record<string, unknown>).baseUrl as string) || '',
                  timeout: (config as Record<string, unknown>).timeout as number || 30000,
                  maxRetries: (config as Record<string, unknown>).maxRetries as number || 3,
                  concurrencyLimit: (config as Record<string, unknown>).concurrencyLimit as number || 5,
                };
              } catch (error) {
                logger.error(`Failed to decrypt config for ${key}:`, error);
              }
            }
          });
        } catch (error) {
          logger.error('Failed to parse stored configs:', error);
        }
      }
      return decryptedConfigs;
    } catch (error) {
      logger.error('Failed to get model configs:', error);
      const defaultConfig = this.getDefaultModelConfig();
      return {
        formula_gpt: defaultConfig,
        synergy_net: defaultConfig,
        safety_checker: defaultConfig,
        taste_predictor: defaultConfig,
        stability_model: defaultConfig,
        llm: defaultConfig,
        peptide_scorer: defaultConfig,
      };
    }
  }

  // 保存模型配置
  static setModelConfig(modelType: ModelType, config: ModelConfig): void {
    try {
      const configs = this.getModelConfigs();
      configs[modelType] = {
        ...config,
        apiKey: encrypt(config.apiKey),
      };
      const serialized = JSON.stringify(configs);
      localStorage.setItem(STORAGE_KEYS.MODEL_CONFIGS, serialized);
      this.createConfigVersion(`Updated ${modelType} config`);
    } catch (error) {
      logger.error(`Failed to save model config for ${modelType}:`, error);
    }
  }

  // 重置模型配置
  static resetModelConfig(modelType: ModelType): void {
    try {
      const configs = this.getModelConfigs();
      const defaultConfig = this.getDefaultModelConfig();
      configs[modelType] = {
        ...defaultConfig,
        apiKey: encrypt(defaultConfig.apiKey),
      };
      localStorage.setItem(STORAGE_KEYS.MODEL_CONFIGS, JSON.stringify(configs));
      this.createConfigVersion(`Reset ${modelType} config`);
    } catch (error) {
      logger.error(`Failed to reset model config for ${modelType}:`, error);
    }
  }

  // 获取默认模型配置
  static getDefaultModelConfig(): ModelConfig {
    return {
      apiKey: '',
      baseUrl: 'https://api.deepseek.com/v1',
      timeout: 30000,
      maxRetries: 3,
      concurrencyLimit: 3,
    };
  }

  // 创建配置版本
  static createConfigVersion(changes: string): void {
    try {
      const versions = this.getConfigVersions();
      const newVersion: ConfigVersion = {
        version: `v${versions.length + 1}`,
        timestamp: new Date().toISOString(),
        changes,
        config: {
          apiKeys: this.getApiKeys(),
          modelConfigs: this.getModelConfigs(),
        },
      };
      versions.push(newVersion);
      const trimmedVersions = versions.slice(-10);
      localStorage.setItem(STORAGE_KEYS.CONFIG_VERSIONS, JSON.stringify(trimmedVersions));
    } catch (error) {
      logger.error('Failed to create config version:', error);
    }
  }

  // 获取配置版本历史
  static getConfigVersions(): ConfigVersion[] {
    try {
      const stored = localStorage.getItem(STORAGE_KEYS.CONFIG_VERSIONS);
      return stored ? JSON.parse(stored) : [];
    } catch (error) {
      logger.error('Failed to get config versions:', error);
      return [];
    }
  }

  // 恢复配置版本
  static restoreConfigVersion(version: string): void {
    try {
      const versions = this.getConfigVersions();
      const targetVersion = versions.find(v => v.version === version);
      if (targetVersion) {
        if (targetVersion.config.apiKeys) {
          const encryptedKeys = targetVersion.config.apiKeys.map((key: any) => ({
            ...key,
            key: encrypt(key.key),
          }));
          localStorage.setItem(STORAGE_KEYS.API_KEYS, JSON.stringify(encryptedKeys));
        }
        if (targetVersion.config.modelConfigs) {
          const encryptedConfigs: Record<ModelType, any> = {} as Record<ModelType, any>;
          Object.entries(targetVersion.config.modelConfigs).forEach(([key, modelConfig]) => {
            encryptedConfigs[key as ModelType] = {
              ...(modelConfig as object),
              apiKey: encrypt((modelConfig as Record<string, unknown>).apiKey as string),
            };
          });
          localStorage.setItem(STORAGE_KEYS.MODEL_CONFIGS, JSON.stringify(encryptedConfigs));
        }
        this.createConfigVersion(`Restored to version ${version}`);
      }
    } catch (error) {
      logger.error(`Failed to restore config version ${version}:`, error);
    }
  }

  // 导出配置
  static exportConfig(): string {
    try {
      const config = {
        version: '1.0',
        timestamp: new Date().toISOString(),
        apiKeys: this.getApiKeys(),
        modelConfigs: this.getModelConfigs(),
        versions: this.getConfigVersions(),
      };
      return JSON.stringify(config, null, 2);
    } catch (error) {
      logger.error('Failed to export config:', error);
      return '{}';
    }
  }

  // 导入配置
  // 幂等加密：导入 JSON 可能来自本系统 exportConfig()（值已 base64 编码），
  // 直接再次 encrypt() 会产生双重编码，读取时 decrypt() 一次只能解回"半解码串"。
  // 处理：先用 isLikelyBase64 检测，已编码则跳过加密，避免导出→导入循环损坏密钥。
  static importConfig(configStr: string): boolean {
    try {
      const config = JSON.parse(configStr);
      const safeEncrypt = (raw: unknown): string => {
        const s = typeof raw === 'string' ? raw : '';
        return s && isLikelyBase64(s) ? s : encrypt(s);
      };
      if (config.apiKeys) {
        const encryptedKeys = config.apiKeys.map((key: any) => ({
          ...key,
          key: safeEncrypt(key.key),
        }));
        localStorage.setItem(STORAGE_KEYS.API_KEYS, JSON.stringify(encryptedKeys));
      }
      if (config.modelConfigs) {
        const encryptedConfigs: Record<ModelType, any> = {} as Record<ModelType, any>;
        Object.entries(config.modelConfigs).forEach(([key, modelConfig]) => {
          encryptedConfigs[key as ModelType] = {
            ...(modelConfig as object),
            apiKey: safeEncrypt((modelConfig as Record<string, unknown>).apiKey),
          };
        });
        localStorage.setItem(STORAGE_KEYS.MODEL_CONFIGS, JSON.stringify(encryptedConfigs));
      }
      if (config.versions) {
        localStorage.setItem(STORAGE_KEYS.CONFIG_VERSIONS, JSON.stringify(config.versions));
      }
      this.createConfigVersion('Imported config');
      return true;
    } catch (error) {
      logger.error('Failed to import config:', error);
      return false;
    }
  }

  // 验证API密钥
  static validateApiKey(apiKey: string): boolean {
    return typeof apiKey === 'string' && apiKey.trim().length >= 40;
  }

  // 检查API密钥是否过期
  static isApiKeyExpired(key: ApiKey): boolean {
    return new Date(key.expires_at) < new Date();
  }

  // 检查API密钥是否即将过期（7天内）
  static isApiKeyExpiring(key: ApiKey): boolean {
    const expiresAt = new Date(key.expires_at);
    const now = new Date();
    const daysUntilExpiry = (expiresAt.getTime() - now.getTime()) / (1000 * 60 * 60 * 24);
    return daysUntilExpiry > 0 && daysUntilExpiry <= 7;
  }

  // 将配置同步到后端数据库。
  // 返回 { success, llmActive?, llmKeyConfigured? }；旧调用方如需布尔值可取 .success。
  // llmActive/llmKeyConfigured 来自后端回显的运行时 LLM 状态（密钥是否真正生效）。
  static async syncToBackend(modelType: ModelType, config: ModelConfig): Promise<SyncToBackendResult> {
    try {
      const response = await fetch('/api/v1/ai/models/config/' + modelType, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          model_type: modelType,
          provider: config.provider || 'deepseek',
          api_key: config.apiKey,
          base_url: config.baseUrl,
          model: config.model || '',
          max_tokens: config.maxTokens || 4096,
          temperature: config.temperature || 0.7,
        }),
      });
      if (response.status === 403) {
        return { success: false, forbidden: true };
      }
      if (response.status === 401) {
        return { success: false, unauthorized: true };
      }
      if (!response.ok) throw new Error('HTTP ' + response.status);
      const result = await response.json();
      const runtime = result.llm_runtime;
      return {
        success: result.success === true,
        llmActive: runtime ? runtime.active === true : undefined,
        llmKeyConfigured: runtime ? runtime.api_key_configured === true : undefined,
      };
    } catch (error) {
      logger.error('[ConfigManager] 后端同步失败:', error);
      return { success: false };
    }
  }

  // 从后端数据库加载配置
  // 注意：后端 GET /models/config/{model_type} 返回的 api_key 字段是脱敏串（如 "sk-ab..." 或 "***"），
  // 不是明文密钥。若被写回 localStorage 会导致密钥损坏（P2-3 安全保护）。
  // 返回结果中的 apiKey 永远为空字符串，调用方必须用本地已加密存储的密钥回填，
  // 或用用户重新输入的明文密钥通过 syncToBackend 写回后端。
  static async loadFromBackend(modelType: ModelType): Promise<ModelConfig | null> {
    try {
      const response = await fetch('/api/v1/ai/models/config/' + modelType, {
        method: 'GET',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
      });
      if (!response.ok) throw new Error('HTTP ' + response.status);
      const result = await response.json();
      if (result.success && result.config) {
        const config = result.config;
        return {
          // 脱敏串绝不写回本地存储，固定返回空串
          apiKey: '',
          baseUrl: config.base_url || '',
          timeout: config.timeout_ms || 30000,
          maxRetries: config.max_retries || 3,
          concurrencyLimit: config.concurrency_limit || 3,
          model: config.model || '',
          provider: config.provider || '',
        };
      }
      return null;
    } catch (error) {
      logger.error('[ConfigManager] 后端加载失败:', error);
      return null;
    }
  }

  // 批量从后端加载所有配置
  // 批量从后端加载所有配置
  // 同 loadFromBackend：api_key 是后端脱敏串，绝不写回本地
  static async loadAllFromBackend(): Promise<Record<ModelType, ModelConfig>> {
    try {
      const response = await fetch('/api/v1/ai/models/configs', {
        method: 'GET',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
      });
      if (!response.ok) throw new Error('HTTP ' + response.status);
      const result = await response.json();
      if (result.success && result.configs) {
        const configs: Record<ModelType, ModelConfig> = {
          formula_gpt: this.getDefaultModelConfig(),
          synergy_net: this.getDefaultModelConfig(),
          safety_checker: this.getDefaultModelConfig(),
          taste_predictor: this.getDefaultModelConfig(),
          stability_model: this.getDefaultModelConfig(),
          llm: this.getDefaultModelConfig(),
          peptide_scorer: this.getDefaultModelConfig(),
        };
        Object.entries(result.configs).forEach(([type, config]) => {
          const mt = type as ModelType;
          if (config && typeof config === 'object') {
            configs[mt] = {
              // 脱敏串绝不写回本地存储，固定返回空串
              apiKey: '',
              baseUrl: (config as ModelConfigRaw).base_url || '',
              timeout: (config as ModelConfigRaw).timeout_ms || 30000,
              maxRetries: (config as ModelConfigRaw).max_retries || 3,
              concurrencyLimit: (config as ModelConfigRaw).concurrency_limit || 3,
              model: (config as ModelConfigRaw).model || '',
              provider: (config as ModelConfigRaw).provider || '',
            };
          }
        });
        return configs;
      }
      return this.getDefaultConfigs();
    } catch (error) {
      logger.error('[ConfigManager] 批量后端加载失败:', error);
      return this.getDefaultConfigs();
    }
  }

  // 获取默认配置
  private static getDefaultConfigs(): Record<ModelType, ModelConfig> {
    const defaultConfig = this.getDefaultModelConfig();
    return {
      formula_gpt: defaultConfig,
      synergy_net: defaultConfig,
      safety_checker: defaultConfig,
      taste_predictor: defaultConfig,
      stability_model: defaultConfig,
      llm: defaultConfig,
      peptide_scorer: defaultConfig,
    };
  }

  // ─────────────────────────────────────────────────────────────
  // 用户级 LLM 密钥通道（普通用户保存入口，P0 功能 #1）
  // 后端端点：/api/v1/ai/models/user-key（POST/GET/DELETE）与
  // /api/v1/ai/models/user-key/test（验活）。与全局管理员配置完全隔离。
  // ─────────────────────────────────────────────────────────────

  /** 保存当前用户的个人 LLM 密钥（走 user-key 通道，无需管理员权限） */
  static async saveUserLlmKey(params: {
    provider: string;
    apiKey: string;
    baseUrl?: string;
    model?: string;
  }): Promise<{ success: boolean; message?: string; keyMasked?: string }> {
    try {
      const response = await fetch('/api/v1/ai/models/user-key', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          provider: params.provider,
          api_key: params.apiKey,
          base_url: params.baseUrl || '',
          model: params.model || '',
        }),
      });
      if (!response.ok) {
        return { success: false, message: `保存失败（HTTP ${response.status}）` };
      }
      const result = await response.json();
      return {
        success: result.success === true,
        message: result.message,
        keyMasked: result.key_masked,
      };
    } catch (error) {
      logger.error('[ConfigManager] 用户级密钥保存失败:', error);
      return { success: false, message: '保存失败：后端服务不可达' };
    }
  }

  /** 查询当前用户的个人 LLM 密钥状态（只返回脱敏信息，不含明文） */
  static async getUserLlmKeyStatus(): Promise<{
    success: boolean;
    configured: boolean;
    provider?: string;
    model?: string;
    base_url?: string;
    api_key_masked?: string;
    note?: string;
  }> {
    try {
      const response = await fetch('/api/v1/ai/models/user-key', {
        method: 'GET',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
      });
      if (!response.ok) {
        return { success: false, configured: false };
      }
      const result = await response.json();
      return result as {
        success: boolean;
        configured: boolean;
        provider?: string;
        model?: string;
        base_url?: string;
        api_key_masked?: string;
        note?: string;
      };
    } catch (error) {
      logger.error('[ConfigManager] 查询用户级密钥状态失败:', error);
      return { success: false, configured: false };
    }
  }

  /** 删除当前用户的个人密钥，回退到服务器全局密钥 */
  static async deleteUserLlmKey(): Promise<{ success: boolean; message?: string }> {
    try {
      const response = await fetch('/api/v1/ai/models/user-key', {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
      });
      if (!response.ok) {
        return { success: false, message: `HTTP ${response.status}` };
      }
      const result = await response.json();
      return { success: result.success === true, message: result.message };
    } catch (error) {
      logger.error('[ConfigManager] 删除用户级密钥失败:', error);
      return { success: false, message: '删除失败：后端服务不可达' };
    }
  }

  /** 验活当前填写的用户级 LLM 密钥（不写库，后端直连 LLM 做最小调用） */
  static async testUserLlmKey(params: {
    provider: string;
    apiKey: string;
    baseUrl?: string;
    model?: string;
  }): Promise<{ success: boolean; detail: string }> {
    try {
      const response = await fetch('/api/v1/ai/models/user-key/test', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({
          provider: params.provider,
          api_key: params.apiKey,
          base_url: params.baseUrl || '',
          model: params.model || '',
        }),
      });
      if (!response.ok) {
        return { success: false, detail: `验活请求失败（HTTP ${response.status}）` };
      }
      const result = await response.json();
      return { success: result.success === true, detail: result.detail || (result.success ? '密钥可用' : '验证失败') };
    } catch (error) {
      logger.error('[ConfigManager] 用户级密钥验活失败:', error);
      return { success: false, detail: '验活请求失败：后端服务不可达' };
    }
  }

  // ─────────────────────────────────────────────────────────────
  // 异步读取：识别 RMF:2: AES 加密值并解密，供需要完整明文的场景使用
  // ─────────────────────────────────────────────────────────────
  static async getModelConfigsAsync(): Promise<Record<ModelType, ModelConfig & { legacyUnencrypted?: boolean }>> {
    const out: Record<ModelType, ModelConfig & { legacyUnencrypted?: boolean }> = {
      formula_gpt: { ...this.getDefaultModelConfig(), legacyUnencrypted: false },
      synergy_net: { ...this.getDefaultModelConfig(), legacyUnencrypted: false },
      safety_checker: { ...this.getDefaultModelConfig(), legacyUnencrypted: false },
      taste_predictor: { ...this.getDefaultModelConfig(), legacyUnencrypted: false },
      stability_model: { ...this.getDefaultModelConfig(), legacyUnencrypted: false },
      llm: { ...this.getDefaultModelConfig(), legacyUnencrypted: false },
      peptide_scorer: { ...this.getDefaultModelConfig(), legacyUnencrypted: false },
    };
    try {
      const stored = localStorage.getItem(STORAGE_KEYS.MODEL_CONFIGS);
      if (!stored) return out;
      const raw = JSON.parse(stored);
      await Promise.all(Object.entries(raw).map(async ([key, cfg]) => {
        if (!Object.prototype.hasOwnProperty.call(out, key)) return;
        const mt = key as ModelType;
        const c = cfg as Record<string, unknown>;
        const encKey = (c.apiKey as string) || '';
        const { raw: decrypted, legacyUnencrypted } = await decryptKeyAsync(encKey);
        out[mt] = {
          ...(this.getModelConfig(mt) as ModelConfig),
          ...(c as object),
          apiKey: decrypted,
          legacyUnencrypted,
        } as ModelConfig & { legacyUnencrypted?: boolean };
      }));
    } catch (error) {
      logger.error('[ConfigManager] getModelConfigsAsync failed:', error);
    }
    return out;
  }
}

import { logger } from '@/utils/safeLogger';

/**
 * 冲突解决工具类
 * - 基于时间戳和版本号的冲突检测与处理
 * - 支持乐观锁机制
 * - 提供冲突解决策略
 */

interface ConflictResolverOptions {
  timestampField?: string
  versionField?: string
  defaultStrategy?: ConflictResolutionStrategy
}

export type ConflictResolutionStrategy = 'server_wins' | 'client_wins' | 'merge' | 'prompt'

export interface ConflictContext {
  clientData: any
  serverData: any
  timestamp: number
  entityType: string
  entityId: string
}

export interface ConflictResolution {
  resolvedData: any
  strategy: ConflictResolutionStrategy
  resolvedAt: number
}

export type OperationType = 'insert' | 'delete' | 'update' | 'format'

export interface CollaborationOperation {
  id: string
  userId: string
  type: OperationType
  target: {
    type: 'text' | 'figure' | 'table' | 'formula' | 'code'
    id: string
  }
  before?: unknown
  after?: unknown
  timestamp: Date | number
  version: number
}

export interface CollaborationConflict {
  id: string
  type: 'text' | 'format' | 'delete'
  originalOperation: CollaborationOperation
  incomingOperation: CollaborationOperation
  status: 'pending' | 'detected' | 'resolved'
  resolution?: 'keep-local' | 'keep-remote' | 'merge' | 'manual'
  resolvedAt?: Date | number
  resolvedBy?: string
}

export interface ConflictMarker {
  operationId: string
  type: 'text' | 'format' | 'delete'
  startOffset: number
  endOffset: number
  isLocal: boolean
  timestamp: Date | number
}

export class ConflictResolver {
  private timestampField: string
  private versionField: string
  private defaultStrategy: ConflictResolutionStrategy
  private pendingConflicts = new Map<string, CollaborationConflict>()
  private conflictListeners = new Set<(conflict: CollaborationConflict) => void>()

  constructor(options: ConflictResolverOptions = {}) {
    this.timestampField = options.timestampField || 'updated_at'
    this.versionField = options.versionField || 'version'
    this.defaultStrategy = options.defaultStrategy || 'server_wins'
  }

  detectOperationConflict(
    localOp: CollaborationOperation,
    remoteOp: CollaborationOperation,
  ): boolean {
    if (localOp.target.id !== remoteOp.target.id) {
      return false
    }

    if (localOp.type === 'delete' && remoteOp.type === 'delete') {
      return true
    }

    if (localOp.type === 'update' && remoteOp.type === 'update') {
      return true
    }

    if (localOp.type === 'format' && remoteOp.type === 'format') {
      return true
    }

    const localTime = new Date(localOp.timestamp).getTime()
    const remoteTime = new Date(remoteOp.timestamp).getTime()
    const timeDiff = Math.abs(localTime - remoteTime)

    return timeDiff < 5000 && localOp.userId !== remoteOp.userId
  }

  detectConflict(clientData: any, serverData: any): boolean {
    if (!clientData || !serverData) {
      return false
    }

    // 基于版本号检测
    if (clientData[this.versionField] && serverData[this.versionField]) {
      return clientData[this.versionField] < serverData[this.versionField]
    }

    // 基于时间戳检测
    if (clientData[this.timestampField] && serverData[this.timestampField]) {
      const clientTime = new Date(clientData[this.timestampField]).getTime()
      const serverTime = new Date(serverData[this.timestampField]).getTime()
      return clientTime < serverTime
    }

    return false
  }

  /**
   * 解决冲突
   * @param context 冲突上下文
   * @param strategy 解决策略
   * @returns 解决结果
   */
  resolveConflict(
    context: ConflictContext,
    strategy?: ConflictResolutionStrategy,
  ): ConflictResolution {
    const resolutionStrategy = strategy || this.defaultStrategy
    let resolvedData: any

    switch (resolutionStrategy) {
      case 'server_wins':
        resolvedData = this.serverWins(context)
        break

      case 'client_wins':
        resolvedData = this.clientWins(context)
        break

      case 'merge':
        resolvedData = this.merge(context)
        break

      case 'prompt':
        // 提示用户解决冲突，这里返回服务器数据作为默认
        resolvedData = this.serverWins(context)
        break

      default:
        resolvedData = this.serverWins(context)
    }

    return {
      resolvedData,
      strategy: resolutionStrategy,
      resolvedAt: Date.now(),
    }
  }

  /**
   * 服务器优先策略
   */
  private serverWins(context: ConflictContext): any {
    return {
      ...context.serverData,
      // 保留客户端可能的新字段
      ...this.getNewClientFields(context.clientData, context.serverData),
    }
  }

  /**
   * 客户端优先策略
   */
  private clientWins(context: ConflictContext): any {
    return {
      ...context.clientData,
      // 更新版本号和时间戳
      [this.versionField]: (context.serverData[this.versionField] || 0) + 1,
      [this.timestampField]: new Date().toISOString(),
    }
  }

  /**
   * 合并策略
   */
  private merge(context: ConflictContext): any {
    const clientData = context.clientData
    const serverData = context.serverData

    // 合并对象
    const merged = { ...serverData }

    // 遍历客户端数据，合并不同的字段
    Object.keys(clientData).forEach(key => {
      if (key === this.timestampField || key === this.versionField) {
        return
      }

      const clientValue = clientData[key]
      const serverValue = serverData[key]

      if (clientValue !== serverValue) {
        // 对于嵌套对象，递归合并
        if (typeof clientValue === 'object' && typeof serverValue === 'object') {
          merged[key] = this.mergeObjects(clientValue, serverValue)
        } else {
          // 对于简单值，使用客户端值
          merged[key] = clientValue
        }
      }
    })

    // 更新版本号和时间戳
    merged[this.versionField] = (serverData[this.versionField] || 0) + 1
    merged[this.timestampField] = new Date().toISOString()

    return merged
  }

  /**
   * 合并对象
   */
  private mergeObjects(clientObj: any, serverObj: any): any {
    const merged = { ...serverObj }

    Object.keys(clientObj).forEach(key => {
      const clientValue = clientObj[key]
      const serverValue = serverObj[key]

      if (typeof clientValue === 'object' && typeof serverValue === 'object') {
        merged[key] = this.mergeObjects(clientValue, serverValue)
      } else if (clientValue !== serverValue) {
        merged[key] = clientValue
      }
    })

    return merged
  }

  /**
   * 获取客户端新增的字段
   */
  private getNewClientFields(clientData: any, serverData: any): any {
    const newFields: any = {}

    Object.keys(clientData).forEach(key => {
      if (!(key in serverData)) {
        newFields[key] = clientData[key]
      }
    })

    return newFields
  }

  /**
   * 生成冲突报告
   */
  generateConflictReport(context: ConflictContext): string {
    const { clientData, serverData, entityType, entityId } = context

    const clientTime = clientData[this.timestampField]
      ? new Date(clientData[this.timestampField]).toLocaleString()
      : '未知'

    const serverTime = serverData[this.timestampField]
      ? new Date(serverData[this.timestampField]).toLocaleString()
      : '未知'

    return `
冲突检测报告:
- 实体类型: ${entityType}
- 实体ID: ${entityId}
- 客户端修改时间: ${clientTime}
- 服务器修改时间: ${serverTime}
- 冲突原因: 数据在本地修改后，服务器上也发生了变更
    `.trim()
  }

  createConflict(
    originalOp: CollaborationOperation,
    incomingOp: CollaborationOperation,
  ): CollaborationConflict {
    const conflictType: 'text' | 'format' | 'delete' =
      originalOp.type === 'delete' || incomingOp.type === 'delete'
        ? 'delete'
        : originalOp.type === 'format' || incomingOp.type === 'format'
          ? 'format'
          : 'text'

    const conflict: CollaborationConflict = {
      id: `conflict-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`,
      type: conflictType,
      originalOperation: originalOp,
      incomingOperation: incomingOp,
      status: 'pending',
    }

    this.pendingConflicts.set(conflict.id, conflict)
    this.notifyConflictListeners(conflict)

    return conflict
  }

  resolveCollaborationConflict(
    conflictId: string,
    resolution: 'keep-local' | 'keep-remote' | 'merge' | 'manual',
    resolvedBy: string,
    _manualResult?: CollaborationOperation,
  ): CollaborationConflict | null {
    const conflict = this.pendingConflicts.get(conflictId)
    if (!conflict) {
      return null
    }

    conflict.status = 'resolved'
    conflict.resolution = resolution
    conflict.resolvedAt = Date.now()
    conflict.resolvedBy = resolvedBy

    this.pendingConflicts.delete(conflictId)
    this.notifyConflictListeners(conflict)

    return conflict
  }

  getPendingConflicts(): CollaborationConflict[] {
    return Array.from(this.pendingConflicts.values()).filter(
      c => c.status === 'pending',
    )
  }

  getConflictById(conflictId: string): CollaborationConflict | undefined {
    return this.pendingConflicts.get(conflictId)
  }

  getConflictsForOperation(operationId: string): CollaborationConflict[] {
    return Array.from(this.pendingConflicts.values()).filter(
      c =>
        c.originalOperation.id === operationId ||
        c.incomingOperation.id === operationId,
    )
  }

  markConflict(
    operationId: string,
    type: 'text' | 'format' | 'delete',
    startOffset: number,
    endOffset: number,
    isLocal: boolean,
  ): ConflictMarker {
    return {
      operationId,
      type,
      startOffset,
      endOffset,
      isLocal,
      timestamp: Date.now(),
    }
  }

  applyAutoResolution(
    conflict: CollaborationConflict,
    strategy: 'server_wins' | 'client_wins' | 'merge',
  ): CollaborationOperation {
    switch (strategy) {
      case 'server_wins':
        return conflict.incomingOperation
      case 'client_wins':
        return conflict.originalOperation
      case 'merge':
        return this.mergeOperations(
          conflict.originalOperation,
          conflict.incomingOperation,
        )
      default:
        return conflict.incomingOperation
    }
  }

  private mergeOperations(
    localOp: CollaborationOperation,
    remoteOp: CollaborationOperation,
  ): CollaborationOperation {
    if (localOp.type === 'insert' && remoteOp.type === 'insert') {
      const localTime = new Date(localOp.timestamp).getTime()
      const remoteTime = new Date(remoteOp.timestamp).getTime()

      if (localTime < remoteTime) {
        return {
          ...remoteOp,
          id: `merged-${Date.now()}`,
          timestamp: Date.now(),
        }
      }
      return {
        ...localOp,
        id: `merged-${Date.now()}`,
        timestamp: Date.now(),
      }
    }

    return remoteOp
  }

  onConflictDetected(callback: (conflict: CollaborationConflict) => void): () => void {
    this.conflictListeners.add(callback)
    return () => {
      this.conflictListeners.delete(callback)
    }
  }

  private notifyConflictListeners(conflict: CollaborationConflict): void {
    this.conflictListeners.forEach(listener => {
      try {
        listener(conflict)
      } catch (error) {
        logger.error('Error in conflict listener:', error)
      }
    })
  }

  clearResolvedConflicts(): void {
    const resolved = Array.from(this.pendingConflicts.values()).filter(
      c => c.status === 'resolved',
    )
    resolved.forEach(c => this.pendingConflicts.delete(c.id))
  }
}

