export default logger

import type { OperationAction, OperationLogDetail } from '@/types/formula'
import { useAuthStore } from '@/stores/auth'
import { logger } from '@/utils/safeLogger'
import { formulaApi } from '@/api/formula'

interface PendingOperationLog {
  id: string
  action: OperationAction | string
  target_type: string
  target_id: string
  target_name: string
  details?: OperationLogDetail | Record<string, unknown>
  result: 'success' | 'failure' | 'partial'
  error_message?: string
  operatorId: string
  operatorName: string
  operatorRole: string
  ip_address?: string
  user_agent?: string
  created_at: string
  metadata?: Record<string, unknown>
  isCustom?: boolean
}

const DB_NAME = 'rmfood_operation_logs'
const DB_STORE = 'logs'
const DB_VERSION = 1
const MAX_CACHE_SIZE = 1000
const FLUSH_INTERVAL_MS = 30000
const BATCH_SIZE = 50

class OperationLogger {
  private db: IDBDatabase | null = null
  private pendingQueue: PendingOperationLog[] = []
  private flushTimer: ReturnType<typeof setInterval> | null = null
  private isFlushing = false
  private initialized = false

  constructor() {
    this.initDB()
    this.startFlushTimer()
    this.setupOnlineListener()
  }

  private async initDB(): Promise<void> {
    if (this.initialized) return

    // 环境不支持 IndexedDB（隐私模式 / 受限 WebView / 部分测试环境等）时，
    // 降级为仅内存队列：标记 initialized 并直接返回，saveToIndexedDB 的
    // `!this.db` 分支会跳过持久化，避免模块加载期产生未处理的 Promise rejection。
    if (typeof indexedDB === 'undefined') {
      this.initialized = true
      logger.warn('[OperationLogger] IndexedDB is unavailable, persistence disabled (in-memory queue only)')
      return
    }

    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION)

      request.onerror = () => {
        logger.error('[OperationLogger] Failed to open IndexedDB:', request.error)
        reject(request.error)
      }

      request.onsuccess = () => {
        this.db = request.result
        this.initialized = true
        logger.info('[OperationLogger] IndexedDB initialized successfully')
        this.loadPendingLogs().then(resolve).catch(reject)
      }

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result
        if (!db.objectStoreNames.contains(DB_STORE)) {
          const store = db.createObjectStore(DB_STORE, { keyPath: 'id' })
          store.createIndex('created_at', 'created_at', { unique: false })
          store.createIndex('action', 'action', { unique: false })
          store.createIndex('operator_id', 'operatorId', { unique: false })
          store.createIndex('result', 'result', { unique: false })
        }
      }
    })
  }

  private async loadPendingLogs(): Promise<void> {
    if (!this.db) return

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([DB_STORE], 'readonly')
      const store = transaction.objectStore(DB_STORE)
      const request = store.getAll()

      request.onsuccess = () => {
        this.pendingQueue = request.result || []
        if (this.pendingQueue.length > MAX_CACHE_SIZE) {
          this.pendingQueue = this.pendingQueue.slice(-MAX_CACHE_SIZE)
        }
        resolve()
      }

      request.onerror = () => {
        logger.error('[OperationLogger] Failed to load pending logs:', request.error)
        reject(request.error)
      }
    })
  }

  private startFlushTimer(): void {
    if (this.flushTimer) return

    this.flushTimer = setInterval(() => {
      if (navigator.onLine) {
        this.flush()
      }
    }, FLUSH_INTERVAL_MS)
  }

  private setupOnlineListener(): void {
    window.addEventListener('online', () => {
      logger.info('[OperationLogger] Network online, flushing logs...')
      setTimeout(() => this.flush(), 1000)
    })
  }

  private getUserInfo(): { id: string; name: string; role: string } {
    try {
      const user = useAuthStore.getState().user
      if (user) {
        return {
          id: String(user.id),
          name: user.fullName || user.username || 'Unknown',
          role: String(user.role || 'unknown'),
        }
      }
    } catch (error) {
      logger.warn('[OperationLogger] Failed to get user info:', error)
    }
    return { id: 'anonymous', name: 'Anonymous', role: 'unknown' }
  }

  private generateId(): string {
    return `log_${Date.now()}_${Math.random().toString(36).substring(2, 11)}`
  }

  private async saveToIndexedDB(log: PendingOperationLog): Promise<void> {
    if (!this.db) {
      await this.initDB()
    }

    if (!this.db) {
      logger.warn('[OperationLogger] IndexedDB not available, skipping persistence')
      return
    }

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([DB_STORE], 'readwrite')
      const store = transaction.objectStore(DB_STORE)

      if (this.pendingQueue.length >= MAX_CACHE_SIZE) {
        const oldestLog = this.pendingQueue[0]
        store.delete(oldestLog.id)
      }

      const request = store.put(log)

      request.onsuccess = () => resolve()
      request.onerror = () => {
        logger.error('[OperationLogger] Failed to save log to IndexedDB:', request.error)
        reject(request.error)
      }
    })
  }

  private async removeFromIndexedDB(ids: string[]): Promise<void> {
    if (!this.db || ids.length === 0) return

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction([DB_STORE], 'readwrite')
      const store = transaction.objectStore(DB_STORE)

      ids.forEach((id) => store.delete(id))

      transaction.oncomplete = () => resolve()
      transaction.onerror = () => {
        logger.error('[OperationLogger] Failed to remove logs from IndexedDB:', transaction.error)
        reject(transaction.error)
      }
    })
  }

  log(params: {
    action: OperationAction
    target_type: 'formula' | 'ingredient' | 'template' | 'system'
    target_id: string
    target_name: string
    details?: OperationLogDetail
    result: 'success' | 'failure' | 'partial'
    error_message?: string
  }): void {
    const userInfo = this.getUserInfo()
    const logEntry: PendingOperationLog = {
      id: this.generateId(),
      ...params,
      operatorId: userInfo.id,
      operatorName: userInfo.name,
      operatorRole: userInfo.role,
      ip_address: undefined,
      user_agent: navigator.userAgent,
      created_at: new Date().toISOString(),
    }

    this.addToQueue(logEntry)
  }

  logCustom(params: {
    action: string
    target_type: string
    target_id: string
    target_name: string
    metadata?: Record<string, unknown>
  }): void {
    const userInfo = this.getUserInfo()
    const logEntry: PendingOperationLog = {
      id: this.generateId(),
      action: params.action,
      target_type: params.target_type,
      target_id: params.target_id,
      target_name: params.target_name,
      result: 'success',
      operatorId: userInfo.id,
      operatorName: userInfo.name,
      operatorRole: userInfo.role,
      ip_address: undefined,
      user_agent: navigator.userAgent,
      created_at: new Date().toISOString(),
      metadata: params.metadata,
      isCustom: true,
    }

    this.addToQueue(logEntry)
  }

  private addToQueue(log: PendingOperationLog): void {
    this.pendingQueue.push(log)

    if (this.pendingQueue.length > MAX_CACHE_SIZE) {
      const removed = this.pendingQueue.splice(0, this.pendingQueue.length - MAX_CACHE_SIZE)
      this.removeFromIndexedDB(removed.map((l) => l.id)).catch((err) =>
        logger.warn('[OperationLogger] Failed to remove overflow logs:', err),
      )
    }

    this.saveToIndexedDB(log).catch((err) =>
      logger.warn('[OperationLogger] Failed to persist log to IndexedDB:', err),
    )

    logger.debug(`[OperationLogger] Log queued: ${log.action} on ${log.target_type}/${log.target_name}`)
  }

  getPendingLogs(): PendingOperationLog[] {
    return [...this.pendingQueue]
  }

  async flush(): Promise<{ uploaded: number; failed: number }> {
    if (this.isFlushing || this.pendingQueue.length === 0) {
      return { uploaded: 0, failed: 0 }
    }

    this.isFlushing = true
    let uploaded = 0
    let failed = 0

    try {
      while (this.pendingQueue.length > 0) {
        const batch = this.pendingQueue.splice(0, BATCH_SIZE)
        const batchIds = batch.map((l) => l.id)

        try {
          const payload = batch.map((log) => ({
            action: log.action,
            target_type: log.target_type,
            target_id: log.target_id,
            target_name: log.target_name,
            details: log.details || {},
            result: log.result,
            error_message: log.error_message,
            operator_id: log.operatorId,
            operator_name: log.operatorName,
            operator_role: log.operatorRole,
            ip_address: log.ip_address,
            user_agent: log.user_agent,
            created_at: log.created_at,
            ...(log.metadata && { metadata: log.metadata }),
          }))

          await formulaApi.createBatchOperationLogs(payload as unknown as Array<{ action: string; target_type: string; target_id: string; target_name: string; details?: Record<string, unknown>; result: string; error_message?: string; operator_id: string; operator_name: string; operator_role: string; ip_address?: string; user_agent?: string; created_at: string; metadata?: Record<string, unknown> }>)
          uploaded += batch.length
          this.removeFromIndexedDB(batchIds).catch((err) =>
            logger.warn('[OperationLogger] Failed to remove uploaded logs from IndexedDB:', err),
          )
        } catch (error) {
          failed += batch.length
          this.pendingQueue.unshift(...batch)
          logger.error('[OperationLogger] Batch upload failed:', error)
          break
        }
      }

      if (uploaded > 0) {
        logger.info(`[OperationLogger] Flushed ${uploaded} logs (${failed} failed)`)
      }
    } catch (error) {
      logger.error('[OperationLogger] Flush error:', error)
    } finally {
      this.isFlushing = false
    }

    return { uploaded, failed }
  }

  clearUploaded(): void {
    this.pendingQueue = []

    if (this.db) {
      const transaction = this.db.transaction([DB_STORE], 'readwrite')
      const store = transaction.objectStore(DB_STORE)
      store.clear()

      transaction.oncomplete = () => {
        logger.info('[OperationLogger] All logs cleared')
      }

      transaction.onerror = () => {
        logger.error('[OperationLogger] Failed to clear logs:', transaction.error)
      }
    }
  }

  destroy(): void {
    if (this.flushTimer) {
      clearInterval(this.flushTimer)
      this.flushTimer = null
    }

    if (navigator.onLine && this.pendingQueue.length > 0) {
      this.flush().catch((err) =>
        logger.warn('[OperationLogger] Final flush failed on destroy:', err),
      )
    }

    if (this.db) {
      this.db.close()
      this.db = null
    }

    this.initialized = false
  }
}

export const operationLogger = new OperationLogger()

export function useOperationLogger() {
  return {
    log: operationLogger.log.bind(operationLogger),
    logCustom: operationLogger.logCustom.bind(operationLogger),
  }
}

export function withOperationLogging<T extends (...args: any[]) => any>(
  action: OperationAction,
  targetType: string,
  fn: T,
): T {
  return ((...args: Parameters<T>) => {
    const targetId = String(args[0]?.id || args[0] || 'unknown')
    const targetName = String(args[0]?.name || args[0]?.title || targetId)

    let result: ReturnType<T>
    let logResult: 'success' | 'failure' | 'partial' = 'success'
    let errorMessage: string | undefined

    try {
      result = fn(...args)

// @ts-expect-error - See type definition
      if (result instanceof Promise) {
        return result
          .then((res: unknown) => {
            operationLogger.log({
              action,
              target_type: targetType as 'formula' | 'ingredient' | 'template' | 'system',
              target_id: targetId,
              target_name: targetName,
              result: 'success',
            })
            return res
          })
          .catch((error: Error) => {
            logResult = 'failure'
            errorMessage = error.message
            operationLogger.log({
              action,
              target_type: targetType as 'formula' | 'ingredient' | 'template' | 'system',
              target_id: targetId,
              target_name: targetName,
              result: 'failure',
              error_message: errorMessage,
            })
            throw error
          }) as ReturnType<T>
      }

      operationLogger.log({
        action,
        target_type: targetType as 'formula' | 'ingredient' | 'template' | 'system',
        target_id: targetId,
        target_name: targetName,
        result: 'success',
      })

      return result
    } catch (error: any) {
      logResult = 'failure'
      errorMessage = error?.message

      operationLogger.log({
        action,
        target_type: targetType as 'formula' | 'ingredient' | 'template' | 'system',
        target_id: targetId,
        target_name: targetName,
        result: 'failure',
        error_message: errorMessage,
      })

      throw error
    }
  }) as T
}

export default operationLogger

/**
 * 🔒 P3-4: 前端性能监控 - Web Vitals 采集
 *
 * 采集核心 Web 指标 (Core Web Vitals):
 * 1. LCP (Largest Contentful Paint) - 最大内容绘制 (<2.5s 良好)
 * 2. FID (First Input Delay) - 首次输入延迟 (<100ms 良好)
 * 3. CLS (Cumulative Layout Shift) - 累积布局偏移 (<0.1 良好)
 * 4. TTFB (Time to First Byte) - 首字节时间 (<800ms 良好)
 * 5. INP (Interaction to Next Paint) - 交互到下一绘制 (<200ms 良好)
 * 6. FCP (First Contentful Paint) - 首次内容绘制 (<1.8s 良好)
 *
 * 使用方式:
 *   // 在 main.tsx 中调用
 *   import { initPerformanceMonitoring } from '@/utils/performance'
 *   initPerformanceMonitoring({
 *     enabled: true,
 *     endpoint: '/api/v1/metrics/client-perf',
 *     sampleRate: 0.5, // 50% 采样率
 *   })
 */

import { logger } from '@/utils/safeLogger';
// Web Vitals 指标类型
export type VitalMetric = {
  name: string; // 指标名称
  value: number; // 指标值（毫秒或小数）
  id: string; // 指标唯一 ID
  delta: number; // 与上次的差值
  rating: 'good' | 'needs-improvement' | 'poor'; // 评级
  navigationType?: string; // 导航类型
  attribution?: Record<string, any>; // 归属信息
};

// 性能配置
export interface PerformanceConfig {
  enabled: boolean;
  endpoint?: string; // 上报端点
  sampleRate?: number; // 采样率 (0.0 ~ 1.0)
  batchSize?: number; // 批量上报大小
  batchInterval?: number; // 批量上报间隔 (ms)
  debug?: boolean; // 是否开启调试日志
  reportOnUnload?: boolean; // 页面卸载时是否上报
  userIdentifier?: string; // 用户标识（匿名 ID）
}

// 默认配置
const DEFAULT_CONFIG: PerformanceConfig = {
  enabled: true,
  sampleRate: 0.5,
  batchSize: 10,
  batchInterval: 5000,
  debug: false,
  reportOnUnload: true,
};

let config: PerformanceConfig = DEFAULT_CONFIG;
let metrics: VitalMetric[] = [];
const customMetrics: Record<string, number> = {};
const pageLoadStart: number = Date.now();
let isInitialized = false;
let reportTimer: number | null = null;
let pendingReports: any[] = [];

// 简单的匿名 ID（用于关联同一用户的多次会话）
function getOrCreateSessionId(): string {
  try {
    const key = 'rmfood_perf_session_id';
    let id = localStorage.getItem(key);
    if (!id) {
      id = 'sess_' + Math.random().toString(36).substring(2, 15) + Date.now().toString(36);
      localStorage.setItem(key, id);
    }
    return id;
  } catch {
    return 'sess_' + Math.random().toString(36).substring(2, 10);
  }
}

/**
 * 🔒 P3-4: 根据阈值进行评级
 */
function rateMetric(name: string, value: number): VitalMetric['rating'] {
  const thresholds: Record<string, [number, number]> = {
    // [good_max, needs-improvement_max]
    LCP: [2500, 4000],
    FID: [100, 300],
    CLS: [0.1, 0.25],
    TTFB: [800, 1800],
    INP: [200, 500],
    FCP: [1800, 3000],
    'TTFB-request': [500, 1500],
  };

  const [good, need] = thresholds[name] || [1000, 2000];
  if (value <= good) return 'good';
  if (value <= need) return 'needs-improvement';
  return 'poor';
}

/**
 * 🔒 P3-4: 采集 LCP (Largest Contentful Paint)
 */
function observeLCP(callback: (metric: VitalMetric) => void) {
  try {
    if (typeof PerformanceObserver === 'undefined') return;

    const observer = new PerformanceObserver((entryList) => {
      const entries = entryList.getEntries();
      const lastEntry = entries[entries.length - 1];

      if (lastEntry) {
        const value = Math.max(lastEntry.startTime, 0);
        callback({
          name: 'LCP',
          value: value,
          id: 'v3-' + value,
          delta: value,
          rating: rateMetric('LCP', value),
          attribution: {
            element: (lastEntry as PerformanceEntry & { element?: Element })?.element?.tagName || 'unknown',
            url: (lastEntry as PerformanceNavigationTiming)?.name || 'n/a',
            renderTime: 0,
            loadTime: 0,
          },
        });
      }
    });

    observer.observe({ type: 'largest-contentful-paint', buffered: true });
  } catch {
    if (config.debug) logger.warn('[Perf] LCP observer not supported');
  }
}

/**
 * 🔒 P3-4: 采集 CLS (Cumulative Layout Shift)
 */
function observeCLS(callback: (metric: VitalMetric) => void) {
  try {
    if (typeof PerformanceObserver === 'undefined') return;

    let clsValue = 0;
    let clsEntries: PerformanceEntry[] = [];
    let sessionValue = 0;
    let sessionEntries: PerformanceEntry[] = [];

    const observer = new PerformanceObserver((entryList) => {
      for (const entry of entryList.getEntries()) {
        // 只记录非用户输入的布局偏移
        if (!((entry as PerformanceEntry & { hadRecentInput?: boolean })?.hadRecentInput)) {
          const shiftValue = ((entry as PerformanceEntry & { value?: number })?.value ?? 0);
          sessionValue += shiftValue;
          sessionEntries.push(entry);

          // 每隔一段时间计算一次 session
          const currentSession = Math.max(sessionValue);
          if (currentSession > clsValue) {
            clsValue = currentSession;
            clsEntries = [...sessionEntries];

            callback({
              name: 'CLS',
              value: clsValue,
              id: 'v3-' + clsValue.toFixed(4),
              delta: shiftValue,
              rating: rateMetric('CLS', clsValue),
              attribution: {
                shiftCount: clsEntries.length,
                lastShiftTime: entry.startTime,
              },
            });
          }

          // 1 秒后重置 session
          setTimeout(() => {
            if (Date.now() - (entry.startTime || 0) > 1000) {
              sessionValue = 0;
              sessionEntries = [];
            }
          }, 1000);
        }
      }
    });

    observer.observe({ type: 'layout-shift', buffered: true });
  } catch {
    if (config.debug) logger.warn('[Perf] CLS observer not supported');
  }
}

/**
 * 🔒 P3-4: 采集 FID (First Input Delay) / INP (Interaction to Next Paint)
 */
function observeFID(callback: (metric: VitalMetric) => void) {
  try {
    if (typeof PerformanceObserver === 'undefined') return;

    const observer = new PerformanceObserver((entryList) => {
      for (const entry of entryList.getEntries()) {
        const delay = (((entry as PerformanceEntry & { processingStart?: number })?.processingStart ?? entry.startTime) - entry.startTime || 0);
        callback({
          name: 'FID',
          value: delay,
          id: 'v3-' + delay,
          delta: delay,
          rating: rateMetric('FID', delay),
          attribution: {
            eventType: entry.name,
            eventTime: entry.startTime,
          },
        });
      }
    });

    observer.observe({ type: 'first-input', buffered: true });
  } catch {
    if (config.debug) logger.warn('[Perf] FID observer not supported');
  }
}

/**
 * 🔒 P3-4: 采集 FCP (First Contentful Paint)
 */
function observeFCP(callback: (metric: VitalMetric) => void) {
  try {
    if (typeof PerformanceObserver === 'undefined') return;

    const observer = new PerformanceObserver((entryList) => {
      for (const entry of entryList.getEntries()) {
        const value = entry.startTime;
        callback({
          name: 'FCP',
          value: value,
          id: 'v3-' + value,
          delta: value,
          rating: rateMetric('FCP', value),
        });
      }
    });

    observer.observe({ type: 'paint', buffered: true });
  } catch {
    if (config.debug) logger.warn('[Perf] FCP observer not supported');
  }
}

/**
 * 🔒 P3-4: 采集 TTFB (Time to First Byte) — 从 Navigation Timing 获取
 */
function collectTTFB(callback: (metric: VitalMetric) => void) {
  try {
    // 使用 Navigation Timing API
    const navEntry = performance.getEntriesByType('navigation')[0] as PerformanceNavigationTiming;
    if (navEntry) {
      const ttfb = navEntry.responseStart - navEntry.requestStart;
      callback({
        name: 'TTFB',
        value: ttfb,
        id: 'v3-ttfb-' + ttfb,
        delta: ttfb,
        rating: rateMetric('TTFB', ttfb),
        attribution: {
          navigationType: navEntry.type,
          domInteractive: navEntry.domInteractive,
          domContentLoaded: navEntry.domContentLoadedEventEnd,
          loadEvent: navEntry.loadEventEnd,
        },
      });
    }
  } catch {
    if (config.debug) logger.warn('[Perf] TTFB collection failed');
  }
}

/**
 * 🔒 P3-4: 采集页面加载完整指标
 */
function collectPageLoad(callback: (metric: VitalMetric) => void) {
  if (document.readyState === 'complete') {
    const loadTime = performance.now();
    callback({
      name: 'PAGE_LOAD',
      value: loadTime,
      id: 'v3-page-' + loadTime,
      delta: loadTime,
      rating: rateMetric('PAGE_LOAD', loadTime),
    });
  } else {
    window.addEventListener('load', () => {
      setTimeout(() => {
        const loadTime = performance.now();
        callback({
          name: 'PAGE_LOAD',
          value: loadTime,
          id: 'v3-page-' + loadTime,
          delta: loadTime,
          rating: rateMetric('PAGE_LOAD', loadTime),
        });
      }, 0);
    });
  }
}

/**
 * 🔒 P3-4: 自定义指标（用于业务特定的性能测量）
 */
export function startPerfTimer(name: string): () => number {
  const start = performance.now();
  return () => {
    const elapsed = performance.now() - start;
    customMetrics[name] = elapsed;

    if (config.debug) {
      logger.info(`[Perf] ${name}: ${elapsed.toFixed(2)}ms`);
    }

    // 自动上报自定义指标
    const metric: VitalMetric = {
      name: name.toUpperCase(),
      value: elapsed,
      id: 'custom-' + name + '-' + Date.now(),
      delta: elapsed,
      rating: rateMetric(name, elapsed),
    };
    metrics.push(metric);
    scheduleReport();

    return elapsed;
  };
}

/**
 * 🔒 P3-4: 标记关键时间点
 */
export function markPerfTiming(name: string): void {
  try {
    performance.mark(name);
    customMetrics[name] = performance.now();

    if (config.debug) {
      logger.info(`[Perf] Marked: ${name} at ${performance.now().toFixed(2)}ms`);
    }
  } catch {
    // performance.mark 可能在某些环境失败
  }
}

/**
 * 🔒 P3-4: 处理并存储指标
 */
function handleMetric(metric: VitalMetric) {
  if (!config.enabled) return;

  // 采样率检查
  if (config.sampleRate && Math.random() > config.sampleRate) return;

  metrics.push(metric);

  if (config.debug) {
    logger.info(`[Perf] ${metric.name}: ${metric.value.toFixed(2)}ms (${metric.rating})`);
  }

  // 关键指标达到阈值时立即上报
  if (
    (metric.name === 'LCP' && metric.rating === 'poor') ||
    (metric.name === 'CLS' && metric.rating === 'poor') ||
    (metric.name === 'INP' && metric.rating === 'poor')
  ) {
    scheduleReport(true);
  } else {
    scheduleReport();
  }
}

/**
 * 🔒 P3-4: 构建上报数据
 */
function buildReportPayload(): any {
  const deviceInfo = {
    userAgent: navigator.userAgent,
    language: navigator.language,
    platform: navigator.platform,
    screenWidth: window.screen.width,
    screenHeight: window.screen.height,
    colorDepth: window.screen.colorDepth,
    devicePixelRatio: window.devicePixelRatio,
    connection: (navigator.connection
      ? {
          effectiveType: (navigator.connection.effectiveType || null),
          downlink: (navigator.connection.downlink || null),
          rtt: (navigator.connection.rtt || null),
        }
      : null),
    memory: (navigator.deviceMemory || null),
    hardwareConcurrency: navigator.hardwareConcurrency || null,
  };

  return {
    sessionId: getOrCreateSessionId(),
    userIdentifier: config.userIdentifier || null,
    timestamp: new Date().toISOString(),
    pageUrl: window.location.href,
    pagePath: window.location.pathname,
    pageLoadTime: Date.now() - pageLoadStart,
    metrics: metrics,
    customMetrics: customMetrics,
    device: deviceInfo,
    performance: {
      navigationTiming: getNavigationTimingSummary(),
      memory: getMemoryUsage(),
    },
    env: {
      isDebug: config.debug,
      sampleRate: config.sampleRate,
    },
  };
}

/**
 * 🔒 P3-4: 获取导航时间摘要
 */
function getNavigationTimingSummary(): any {
  try {
    const nav = performance.getEntriesByType('navigation')[0] as PerformanceNavigationTiming;
    if (!nav) return null;

    return {
      redirectCount: nav.redirectCount,
      type: nav.type,
      dnsLookup: nav.domainLookupEnd - nav.domainLookupStart,
      tcpConnect: nav.connectEnd - nav.connectStart,
      sslNegotiation: nav.secureConnectionStart ? nav.connectEnd - nav.secureConnectionStart : 0,
      ttfb: nav.responseStart - nav.requestStart,
      contentDownload: nav.responseEnd - nav.responseStart,
      domInteractive: nav.domInteractive,
      domContentLoaded: nav.domContentLoadedEventEnd,
      domComplete: nav.domComplete,
      loadEvent: nav.loadEventEnd,
    };
  } catch {
    return null;
  }
}

/**
 * 🔒 P3-4: 获取内存使用
 */
function getMemoryUsage(): any {
  try {
    const perf = performance as Performance & { memory?: PerformanceMemory };
    if (perf.memory) {
      return {
        usedMB: Math.round(perf.memory.usedJSHeapSize / 1024 / 1024),
        totalMB: Math.round(perf.memory.totalJSHeapSize / 1024 / 1024),
        limitMB: Math.round(perf.memory.jsHeapSizeLimit / 1024 / 1024),
        percent: ((perf.memory.usedJSHeapSize / perf.memory.jsHeapSizeLimit) * 100).toFixed(2),
      };
    }
    return null;
  } catch {
    return null;
  }
}

/**
 * 🔒 P3-4: 上报到服务器（使用 sendBeacon 或 fetch）
 */
function sendReport(payload: any) {
  if (!config.endpoint) {
    if (config.debug) logger.info('[Perf] Report (no endpoint):', payload);
    return;
  }

  try {
    const body = JSON.stringify(payload);

    // 使用 sendBeacon（页面卸载时更可靠）
    if (navigator.sendBeacon) {
      const result = navigator.sendBeacon(config.endpoint, new Blob([body], { type: 'application/json' }));
      if (result) return;
      // sendBeacon 返回 false 表示请求被拒绝，静默忽略
    }

    // 回退到 fetch（keepalive）— 仅在页面活跃时使用
    if (!document.hidden) {
      fetch(config.endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: body,
        keepalive: true,
      }).catch(() => {
        // 静默忽略上报失败，避免页面卸载时产生 ERR_ABORTED
      });
    }
  } catch {
    // 静默忽略上报序列化失败
  }
}

/**
 * 🔒 P3-4: 调度批量上报
 */
function scheduleReport(immediate: boolean = false) {
  if (!config.endpoint) return;

  pendingReports.push(...metrics);
  metrics = [];

  const shouldReportNow =
    immediate || pendingReports.length >= (config.batchSize || 10) || pendingReports.some((m) => m.rating === 'poor');

  if (shouldReportNow) {
    const payload = buildReportPayload();
    pendingReports = [];
    sendReport(payload);
    return;
  }

  // 延迟批量上报
  if (reportTimer) clearTimeout(reportTimer);
  reportTimer = window.setTimeout(() => {
    const payload = buildReportPayload();
    pendingReports = [];
    sendReport(payload);
  }, config.batchInterval || 5000);
}

/**
 * 🔒 P3-4: 获取当前性能摘要
 */
export interface PerformanceSummary {
  metrics: VitalMetric[];
  custom: Record<string, number>;
  memory?: any;
  navigation?: any;
}

export function getPerformanceSummary(): PerformanceSummary {
  return {
    metrics: metrics,
    custom: customMetrics,
    memory: getMemoryUsage(),
    navigation: getNavigationTimingSummary(),
  };
}

/**
 * 🔒 P3-4: 主初始化函数
 */
export function initPerformanceMonitoring(userConfig: Partial<PerformanceConfig> = {}) {
  if (isInitialized) return;
  isInitialized = true;

  config = { ...DEFAULT_CONFIG, ...userConfig };

  if (!config.enabled) {
    if (config.debug) logger.info('[Perf] Monitoring disabled');
    return;
  }

  if (config.debug) {
    logger.info('[Perf] Initializing performance monitoring', config);
  }

  // 初始化观察者
  observeLCP(handleMetric);
  observeCLS(handleMetric);
  observeFID(handleMetric);
  observeFCP(handleMetric);

  // 收集 TTFB
  collectTTFB(handleMetric);

  // 页面加载完成后收集总时间
  collectPageLoad(handleMetric);

  // 🔒 P3-4: 页面卸载前强制上报
  if (config.reportOnUnload) {
    const unloadHandler = () => {
      if (pendingReports.length > 0 || metrics.length > 0) {
        const payload = buildReportPayload();
        sendReport(payload);
      }
    };

    window.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'hidden') {
        unloadHandler();
      }
    });

    window.addEventListener('pagehide', unloadHandler);
    window.addEventListener('beforeunload', unloadHandler);
  }

  // 🔒 P3-4: 定期上报（即使没有变化也采样）
  if (config.batchInterval) {
    setInterval(
      () => {
        if (pendingReports.length > 0) {
          const payload = buildReportPayload();
          pendingReports = [];
          sendReport(payload);
        }
      },
      Math.max(config.batchInterval, 30000),
    ); // 至少 30 秒
  }
}

/**
 * 🔒 P3-4: 便捷的 React Hook 包装
 */
export function usePerformance(enabled: boolean = true) {
  void enabled;
  return {
    startTimer: startPerfTimer,
    mark: markPerfTiming,
    getSummary: getPerformanceSummary,
    init: initPerformanceMonitoring,
  };
}

// 暴露为全局对象（便于调试）
if (typeof window !== 'undefined') {
  window.__RMFOOD_PERF__ = {
    init: initPerformanceMonitoring,
